INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonumuz esarete gitmeden gaflet uykusundan uyansana artık', 'sonumuz-esarete-gitmeden-gaflet-uykusundan-uyansana-artik-halil-colak-9x3b9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gördüğün bu millet İstiklal savaşında yokluk içinde 

Düşmana karşı Çarıksız ayaklar ile kazma kürekle

Türk Kadınların sırtında bebe elin de satırlar ile

Uyansana artık Savaşı kazanan da sendeğilmiydin 

İhtiyar nenelerin geceleri sürdüğü kağnılar ile

Kara Fatmaların omzunda taşıdığı mermiler ile

Saçları kınalanmış genç yağız delikanlılar ile

Uyansana artık Savaşı kazanan sendeğilmiydin 

Sakarya senin hala kahramanlık türkünü söylüyor

Kıyısında yatan  kahraman şehitlerin onu dinliyor

 Haçlı Düşman bu haline kahkaha ile sana gülüyor

 Düşmanı üstüne güldürme yeter be uyansana artık

İstiklal savaşının tüm şehitlerinin kemikleri sızlıyor

Bütün dünya ey kahraman milletim seni gözlüyor

Sen gaflet içinde olduğun için dinine hücum ediyor

Hz.Muhammed’in övdüğü millet uyansana artık 

Sına çölünde önünde peygamber iminde  rehberlik eden

Dünyayı bir hükümdara çok iki hükümdarda azda gören

Afrika kıtasına türkün şanını şöhretini tarihlere de yazan

Yavuz Sultan Selimin kahraman torunları uyansana artık

Tarihte ilk defa karalardan kalaslar üzerinde gemi üzdüren

Bin yıllık Bizans imparatoruluğunuda tarihten silip süpüren 

Çağ açıp,çağ kapayıp herkesin ibadetinde de serbestlik veren

Fatih Sultan Mehmet’in kahraman da torunları uyansana artık

Doğu cephelerinde Moskof ve Ermeni ‘ yi de yurt anda kovan

Cepheler de ateş hattında beş vakit namazda kıbleye de duran

Halkın nazarında kahraman hem de Allah’ın sevgili kulu olan

Kazım Karabekir paşanın torunları yeter uyudun uyansana artık

Düşmana göz açtırmayıp korkusuzca kahramanca ona saldıran

Korkunç ı cesareti imanı sayesinde düşmanının gözünü yıldıran

Cepheden kaçan alçak şerefsiz ve kansızları acımadan da vuran

Cesaretin timsali korkusuz Halit Paşa’nın nesli uyansana artık

Kerkük. Musul,Telafer’ım analar zulümden kanda  ağlıyor

Afganistan’da Kara bağ’da esaretten inim inimde  inliyor

Filistin, Çecenistan da Müslüman da acımasızca katlediliyor

Küfür tek millettir İslam olan ülkeler yok olmadan uyan artık

Ey ne zaman  uyanacaksın,uyuyan gafletteki Müslüman millet

Ulu peygamber Hz.Muhammed’e saldırıyor haclı da zihniyet

Kendinize gelin Müslüman ülkeler elinizden alınacak hürriyet

Sonumuz esarete gitmeden gaflet uykusundan uyansana artık

Halil Çolak 14.2.2006 Ankara', 'Gördüğün bu millet İstiklal savaşında yokluk içinde  Düşmana karşı Çarıksız ayaklar ile kazma kürekle Türk Kadınların sırtında bebe elin de ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sonumuz-esarete-gitmeden-gaflet-uykusundan-uyansana-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulan ABD Nasıl Sana Başkaldırdıysam Şimdide Başkaldıryorum', 'ulan-abd-nasil-sana-baskaldirdiysam-simdide-baskaldiryorum-eyup-selahattin-dalkiran-ghte7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kızılderililerin topraklarını alan

insanlarını öldüren,sömüren.

Afrikadan getirdiğin köleleri

pazarlarında satan,Kızlarına Tecavüz eden.

Toprakları işgal edip 

Ellerinden alan.

Tomhawakların ile ülkeleri döven

Çoçukları öldüren,işkence eden.

Kimyasal ve napalm bombaların ile

vietnamın ormanlarını alt üst edip yenilen.

Kiliselere yön veren Papazların,Misyonerlerin 

vatikan ile parasını karşılayan.

Yandaşların ile ekonomilere,siyasetlere

yön veren,açlığa iten.

Binlerce annenin yüreklerini yakan

Kendi ülkendekilerde Dahil.

Ortadoğuyu kan gölüne çeviren

Vahşice  katliamlar yapan.

Yüzyıllardır  sosyalistleri,Komünistleri

Müslümanları sorgusuz sualsiz eziyet veren.

Gizli örgütlerinle dünyayı 

Allak bullak eden.

Gazetecileri,Aydınları Senin çıkarın

Doğrultusunda yazmadıkları için öldürtten.

Kendi ajanların ile Külelerini vurdurtan

Sonra kıvıran.

Yüzlerce yere Deprem bombaları atan

Attıklarınla jeolojik dengeyi bozan.

Ortalığa her türlü hastalığı yayan

AİDS,HN5 gibi daha neler neler.

Yaratığın Soğuk Savaş politkaları

Ülkeleri Silah Yığınağı haline getiren.

Ayrıca Hin oğlu hinlik  Yapıp 

Yeşil kuşak teorisini ortaya koyan.

Ulusların bağımsızlığı diye

Haritaların sınırlarını yeniden çizdiren.

Sen Değilmisin ulan ABD

Eskiden Nasıl başkaldırıyorsam

Eskisinden daha çok başkaldırıyorum

ULAN ABD.', 'Kızılderililerin topraklarını alan insanlarını öldüren,sömüren. Afrikadan getirdiğin köleleri pazarlarında satan,Kızlarına Tecavüz eden. Top...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ulan-abd-nasil-sana-baskaldirdiysam-simdide-baskaldiryorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafam Güzel', 'kafam-guzel-hasan-uzel-o9urv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kafam güzel dolaşıyorum

İstanbul sokaklarında

Arıyorum arıyorum amma

Sen yoksun hala

Çıksan gelsen karanlıklardan

Ayrılıklardan kaçarcasına

Son durağın ben olsam

Bir daha ayrılmamacasına

Gönlüm de fırtınalar

İnan dinmek bilmiyor

Bu yaptıkların beni

Deli ediyor

Kafam güzel dolaşıyorum

Sevda sokaklarında

Arıyorum arıyorum amma

Sen yoksun hala

Gözümde ki o yaşlar 

Gönül vermiş yanağıma

Sözümde ki bu sitem

Ayrılıktan yana

Ben yalnızdım gittin gideli

Yanındayken bile hasrettim sana', 'Kafam güzel dolaşıyorum İstanbul sokaklarında Arıyorum arıyorum amma Sen yoksun hala Çıksan gelsen karanlıklardan Ayrılıklardan kaçarcasına ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kafam-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilara''ya', 'dilara-ya-onder-nalbant-p6k9m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'üşüyorum şimdi

aşktandır

yüreğimi çekiştirme artık kelimelerinle

aşkın filizini yeşertmek için

yerde yatan ölüyü

düreterek diriltmek gibi

ben öldüm diyorum

kalbime saplanan ilk kelimende hemen

cesedimi kaldırmadım daha önünden

görmek istersin belki

işlediğin ilk cinayeti

aşk böyle mi fısıldar sana

böyle mi seversin sen

sen hiç öldün mü severken

kaybetmek mi dedin

aşkta kaybetmek yoktur güzelim

senden yansıyan kadardır sevgim

ve üşüyen dudaklarım diyor ki şimdi bana

sen bu kızı hiç sevmemişsin

sen durup durup gözlerimi okşuyorsun ya

yüreğim tir tir dışarıda el secde

ibadetinde, ilk hecesinde adının

sen o yüreği içeri almadıktan sonra

ha senin kollarındayım, yüreksiz

ha yüreğimden habersiz

kirli bir sokak kadınının...

                           15/02/2006', 'üşüyorum şimdi aşktandır yüreğimi çekiştirme artık kelimelerinle aşkın filizini yeşertmek için yerde yatan ölüyü düreterek diriltmek gibi be...', ARRAY['Türk Edebiyatı','Şiir','Önder Nalbant']::text[], 8.5, '{"poet":"Önder Nalbant","poet_slug":"onder-nalbant","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dilara-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bu Sevdalar', 'ah-bu-sevdalar-hasan-uzel-ai1u9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah bu sevdalar sevdalar

Yalan dünyanın yalan sevdaları

Ya çok seversin sevilmezsin

Ya sevmezsin sevilirsin

Açarsın yüreğini ta sonuna kadar

Bölük bölük kıta kıta aşklar

Serersin yar yoluna serebildiğin kadar

Bir gün gelir ne yürek var ne aşk var

Kim verecek hesabını dünya sen mi? 

Uykusuz geçen yar dolu gecelerin

Ve onsuzluğa ışık tutan güneşin

Sen dönmene devam et dönme dünya', 'Ah bu sevdalar sevdalar Yalan dünyanın yalan sevdaları Ya çok seversin sevilmezsin Ya sevmezsin sevilirsin Açarsın yüreğini ta sonuna kadar ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ah-bu-sevdalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-i-brahim-sarihan-5g33l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soruyorum ne oldu bize böyle birden bire

Umursamadan herşey silinip gitti bir günde

Basitmiş bulamıyorum söylenecek kelime

Yaşananların sonunda acıyorum halimize

Benim sitemim hayrete düşüren sözlerine

Özür bekledim senden oysa dilemedin bile

Artık seni anmamalı mıyım ne olur söyle

Yapamam ki bunu seni sevmişim bir kere

Kulaklarımda sesin şimdi hala çınlıyor

Her an benimlesin sanki seni anımsatıyor

Bana bağlan bırakma sımsıkı sar diyor

Aşık olduğum bu tatlı ses içimi ısıtıyor

Gidersen unutma bulamazsın bir daha beni

Anarsam namerdim senin iki heceli ismini

Görmek istemem asla muhteşem güzelliğini

Bak! Gitme desem son defa dinler misin beni? 

(Hakkâri, 12 Kasım 2003)', 'Soruyorum ne oldu bize böyle birden bire Umursamadan herşey silinip gitti bir günde Basitmiş bulamıyorum söylenecek kelime Yaşananların sonu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gitme-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırpınış', 'cirpinis-mehmet-bulut-hretg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çırpınışlar kat kat yağan karın,

karın ağrıtan en diplerine süzülürken

son çırpınış da gurbet oldu

yitik hasretli dönmeyişlerden...

Belli gittiği yerden memnun 

her giden gibi arkasına bakmadan

ve bi haber benim harap halimden..

Şimdi doğrulandı doğruluğu muallak sözler

''''deymedi yare sözümüz

yollarda kaldı gözümüz

böyleymiş kara yazımız''''

Karlı havaların soğuk bakışlı yol gözlemelerinde

olup biten her düş gibiydi

olup biten...

Kar topları atılmadan erimiş 

gibi dondurucu havalarda.

Ama neyleyim bu kış günlerinde 

ellerim bi başına ısınmıyor 

ceplerimde....', 'Çırpınışlar kat kat yağan karın, karın ağrıtan en diplerine süzülürken son çırpınış da gurbet oldu yitik hasretli dönmeyişlerden... Belli gi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cirpinis-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koy kıçına tekmeyi!', 'koy-kicina-tekmeyi-omer-dalman-8h6rz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şu bizim kocaman, tipsiz

kirli-paslı şehirlerimizin

seçkin semtlerinde yaşayan

daha ziyade öğrenim görmüş

kırıcı sözlerden sakınmaya çalışan

damarlarındaki kanlarıysa epeyce kirlenmiş

aslında çaresizce -materyalistleşmiş- insanlar

pek bir başvururlar bu şeye:

istemedikleri bir şeyle karşılaşırlar

kızarlar içten içe

laflarını bir güzel sokarlar

azarlarlar hatta gözlerinizin içine baka baka

hakaret ederler! ..

bakakalırsınız gözleriniz faltaşı gibi

ve en son bir iki cümleyle de

kendinizi savunursunuz veya

bir şeyler söylersiniz işte! 

eliniz armut toplamıyor ya? ! 

sonra

yumuşadığınızı veya -gücünüzü- görürler bir anda ve

hemen ''şaka şaka! '' derler suni bir kibarlıkla! 

ve karşınızdaki o -yalancı ejderha-

uysal bir -köpeğe- dönüverir! 

ne kadar da siniveren bir köpektir bu türler! ? 

o noktadan sonra

vursan vuramazsın

satsan satamazsın

bir de suçlu olursun çünkü, yaparsan! 

neyse...

koy kıçına tekmeyi hepsinin, gitsin! 

(Şubat 2006)', 'şu bizim kocaman, tipsiz kirli-paslı şehirlerimizin seçkin semtlerinde yaşayan daha ziyade öğrenim görmüş kırıcı sözlerden sakınmaya çalışan...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/koy-kicina-tekmeyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Sensiz Diğeri Sen', 'biri-sensiz-digeri-sen-murat-polat-2-32evv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok kısa da olsa

Karşılaşmaları yeniden

Eminim yenemeyecek

Kimse galip değil diğerinden

Yaa...bu bir oyun anlasana

Biri sensiz, diğeri sen

Karşında...acımasız dediğin

Yine sen, sadece sen

Baksana sonuca

Yine aynı eksen...

                       

                         14 Şubat 2006', 'Çok kısa da olsa Karşılaşmaları yeniden Eminim yenemeyecek Kimse galip değil diğerinden Yaa...bu bir oyun anlasana Biri sensiz, diğeri sen K...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biri-sensiz-digeri-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklar', 'asiklar-husam-hasret-93ccr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar boyunca Kerem Aslı ardına düştü

Böyle ilk görüşünde sevda derdine düştü

Yurduna hasret kala eller yurduna düştü

Yandı Kerem''im yandı Aslıyla bir ateşte

Menun''dan ne söyleyim, odur Leyla delisi

Ona çare bulmadı hakimlerin ellisi

Leyla''nın güzel gözü oldu tek tesellisi

Muradına ermeden aklı kalmadı başta

Şirin uğrunda Ferhat sert kayaları deldi

Şirin Şirin diyerek balta kayaya çaldı

Kavuşmadan ruhların beraber felek aldı

Hatıraları kaldı hem dağda hem de taşta

Garip''te gurbet elde uzun zaman çekti gam

Yalnızlık hasretinden gözlerinden coştu nem

Sonda şad oldu, ona kavuştu da Şahsenem

Sürdüler keyf safayı bir ömürde bir yaşta

Kanber de Arzu''sundan yıllaraca uzak düştü

Sevgisinin uğruna cıkmaz yollara koştu

Bir ölüm kucağında Arzu''suna kavuştu

Ne yazık ecel koydu gözlerini hep yaşta

Ben de onlar gibiyim, sevdama kanıyorum

Sevda ölmez bir nesne hep öyle sanıyorum

Bilmiyorum da neden eriyip yanıyorum

Tek söylediğim sözse, gönül sevdadır işte', 'Yıllar boyunca Kerem Aslı ardına düştü Böyle ilk görüşünde sevda derdine düştü Yurduna hasret kala eller yurduna düştü Yandı Kerem''im yandı ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asiklar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Sevgi', 'oylesine-sevgi-yasar-tezel-kiz2b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Goncanın üstüne takılır sevi

Koklayıp hissetmeli özlemi

Yağmur sağanağı berrak

Gök yüzü gibi masmavi 

Yüzü güneşten daha ak

Kumrular misali koklaşsa

İşvesine kurban olduğum

Duyuverse sesimi sevgili

Gülüşü meşhur tebessümü

Dişleri zümrüt görünür

Yanağında kırmızı güldür

Yağmur sağnağı zülüfleri

Bülbül nağmesidir dilleri

Canım o ciğerimin köşesi

Saadet pınarı huzur çeşmesi', 'Goncanın üstüne takılır sevi Koklayıp hissetmeli özlemi Yağmur sağanağı berrak Gök yüzü gibi masmavi  Yüzü güneşten daha ak Kumrular misali ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oylesine-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Sevdim', 'cok-sevdim-hasan-uzel-i39d8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni çok sevdim sevemeyeceğin kadar

Hayatın da varsa biri bu beni çok yaralar

Ben seni çok sevdim istemediğin kadar

Sen benim vazgeçilmezimsin hep aralar

Kıskanıyorum seni ben sana uzanan ellerden

Kıskanıyorum seni ben sana bakan gözlerden

Kimse sana benim gibi bakamaz kimse yanamaz

Yokluğundan çalcam seni ayrılık bile alamaz

Tek isteğim sende beni sevsen keşke benim gibi

Yokluğum da aradın mı yakmadım mı hiç yüreğini? 

Yoksa ben senin için hep yedekte elde mi varım? 

Söyle canım söyle hayatın da bir ben mi varım? 

Varsa şüphen sana olan aşkım dan

Söker yüreğimi atarım acımadan

Yaş ta dökmem hem de gülmem

Ben sensiz bilmeyi bilemem', 'Ben seni çok sevdim sevemeyeceğin kadar Hayatın da varsa biri bu beni çok yaralar Ben seni çok sevdim istemediğin kadar Sen benim vazgeçilme...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-sevdim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Der''di Aşk''a Deva!', 'der-di-ask-a-deva-hakan-kocaoglu-k7jie', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk imiş! Her derde, bin devâ

Aşk derdine, hem bu can fedâ

Yaratılan sev de, sür sefâ

Sever Âşıkları, bil Hüdâ

Aşk eridir, gönül feneri

Düşmez dâr’a, gerçek seveni

Âşık yüzüdür, Kul edebi

Asra güneştir! Âşk Ereni

Aşk imiş! Bu dünyanın sırrı

Dert olmuş, vuslatın hep nâr’ı

Ezel vermiş, ol Aşk’ın hâr’ı

Yanmakmış, Âşık’ın hem kâr’ı

Derdi Aşk olanın! Devâsı

Aşk’mış! Her gönülden; Sedâsı

Dert’miş! Her güzelden; Cefâsı

Aşk’mış! Derdi Aşk’ın; Devâsı', 'Aşk imiş! Her derde, bin devâ Aşk derdine, hem bu can fedâ Yaratılan sev de, sür sefâ Sever Âşıkları, bil Hüdâ Aşk eridir, gönül feneri Düşm...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kocaoğlu']::text[], 8.5, '{"poet":"Hakan Kocaoğlu","poet_slug":"hakan-kocaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/der-di-ask-a-deva-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Döküntüleri', 'yol-dokuntuleri-mehmet-bulut-507t2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana onu getiren 

ve beni ona götürmeyen yollardan

topluyorum döktüğüm sözcükleri.

Size öyle doluyum ki...

Yollar, yolculuklar, sözler, sözcükler anlamsız her imge.

Şimdi seni düşünmek en büyük günah

dakikalara, saniyelere bürünmüş yüzün.

Zaman geçer senle ve sensiz geçmez hiçbir an...

Kabullenemiyorum sensiz geçen zamanı

hayır diyorum...

İstisnasız hayır...

Elimde olmadan yinede geçiyor mevsimler

ve erteleniyor düşlerle, heveslerle o büyük var oluş mucizesi.

Senin o lanetli pazarların benim cumalarım oldu şimdi

cumalardan nefret eder oldum

ve bu gün cuma...

Yani yine yollarda ben 

yani sevda yine yenildi kızgınlıklara, küskünlüklere...

Her dönüş bir ağlamak olsada

umutlar ayakta tutar sevda olmasada.

Bu gün olmazsa yarın mutlaka...', 'Bana onu getiren  ve beni ona götürmeyen yollardan topluyorum döktüğüm sözcükleri. Size öyle doluyum ki... Yollar, yolculuklar, sözler, sözc...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yol-dokuntuleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Senin', 'kalbim-senin-i-brahim-sarihan-3gzmu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acı hüzünleri topladı yüreğim

Bir tek olsun, yoktu sevenim

Alay ettiler, çok oldu gülenim

Yaralıydım, ağlamaklıydı gözlerim

Seninle sona eren, sahte sevgilere

Terk edip giden, sıkıcı hüzünlere

Yüzümdeki itici, somurtkan ifadelere

Elveda geride kalan, berbat günlere

Yeni bir sayfa açtım, hayata sevgili

Düşlüyorum, önümüzdeki o güzel günleri

Sana dair kurduğum, tüm hayalleri

Özlemle bekliyorum şimdi sevgili

Bir dileğim vardı Allah''tan, o sendin

Aradığım ilgiyi, sevgiyi verdin

Ya, başımı döndüren harika gözlerin

Al kalbimi biricik, o yalnız senin

(Ankara, 20 Kasım 2004)', 'Acı hüzünleri topladı yüreğim Bir tek olsun, yoktu sevenim Alay ettiler, çok oldu gülenim Yaralıydım, ağlamaklıydı gözlerim Seninle sona ere...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalbim-senin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda tökezde', 'sevda-tokezde-asude-gediz-l6esr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düştü sıcacık seslenişden sevgi

sarı bir yaprak sürükleniyor,  yalpalıyor

sözler donmuş, titriyor

sevda çaresiz  kalıyor

kanıyor  sıcacık yürek 

kendini yerden yere vuruyor

çırpınıyor, yalvarıyor

yürek çaresiz 

sevgi soluyor

Sevda.... tökezliyor', 'Düştü sıcacık seslenişden sevgi sarı bir yaprak sürükleniyor,  yalpalıyor sözler donmuş, titriyor sevda çaresiz  kalıyor kanıyor  sıcacık yü...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevda-tokezde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lütfen', 'lutfen-murat-polat-2-x21dz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En çok ben,

Kendimi ürkütmüşüm.

Daha önceleri...

Lütfen...ben kirlenmeyi,

Lütfen...bilmem

Tanımazları, yokları...

                

                   14Şubat 2006', 'En çok ben, Kendimi ürkütmüşüm. Daha önceleri... Lütfen...ben kirlenmeyi, Lütfen...bilmem Tanımazları, yokları...                           ...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/lutfen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-baris-polat-50ftf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah bir sevda beklentisiyle

Aralarım göz kapaklarımı

Yakarcasına bir sevdayı beklerim..

Çaresizlikler içerisinde

Fakat,Ne çare beklemekten başka,

bir şey gelmez ellerimden

Gelmez ellerimden umarsızca

Sevgileri beklemekten başka

Ama biliyorum bir gün gelecek

Tutuşacak yüreğim,yeniden,

Atmaya başlayacak kalbim biliyorum.', 'Her sabah bir sevda beklentisiyle Aralarım göz kapaklarımı Yakarcasına bir sevdayı beklerim.. Çaresizlikler içerisinde Fakat,Ne çare bekleme...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biliyorum-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-hasan-uzel-cknt6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah ım ben günahkar bir kulunum

Hani o yapma dediklerini yapanlardan

Hani o yap dediklerini yapmayanlardan

Ben onu çok seviyorum o benim aşkım

Allah ım yarattığın bir kuluna yandım

Aşkı da sen yarattın ayrılıklarıda

Ben günahkar bir kulunum tattım da

Ben onu çok seviyorum o benim aşkım

Sen istemezsen hiç birşey olmaz

Sen dilersen olmaz denen olmaz

Yarattığın aşk geldi beni buldu

Yarattığın ayrılık bu yüreği vurdu

Güç ver Allah ım kuvvet ver bu kuluna

Koru sevdiğimi verme kurda kuşa

Yalan dolan tahtta fani dünya da

Ben onu çok seviyorum o benim aşkım

O da yansın benim gibi o da sevdalansın

Neler çektiğimi bilmiyor o Allah ım

Öyle bir aşk yarat ki yeryüzün de olmayan

Olmasak ta yanyana hasreti duyurmayan

Allah ım ben onu çok seviyorum o benim AŞK IM', 'Allah ım ben günahkar bir kulunum Hani o yapma dediklerini yapanlardan Hani o yap dediklerini yapmayanlardan Ben onu çok seviyorum o benim a...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dua-152-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Kalemim Susmadı *', 'kalemim-susmadi-i-brahim-dikmen-2-ioq0x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün 14 Şubat

biliyor musun? 

sevenlerin tek yürek olduğu

kırmızı güllerle ifade edilen

sevgililerin günü

biliyormusun? 

Sana,

gonca gül gönderdim

ebruli

ölümsüz Aşkımın 

timsali

aslı bende kaldı

yüreğimde açtı gerçeği

Dışarısı ayaz yine

yüreğim kara kışta

dudaklarım

kıraç toprak gibi

sensizliğe susamış

sahra gibi

Sorma! 

düşlerimi sorma

her gecem hazan şimdi

sorma! 

sakın sorma beni

acımı deşme yine

sakın birdaha

lütfen! 

beni sakın arama.

Beni susturdun

lakin! 

kalemimi

yüreğimi susturamadın

ey sevgili

sen olduğun yerde kal

ben bana yeterim

sensiz gecelerde

vuslatım olur

ebruli düşlerim.

14/02/2006', 'Bugün 14 Şubat biliyor musun?  sevenlerin tek yürek olduğu kırmızı güllerle ifade edilen sevgililerin günü biliyormusun?  Sana, gonca gül gö...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kalemim-susmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamsın Sen...', 'sevdamsin-sen-mehmet-ali-demircan-enw9z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen, sıkı sıkıya kavradığım,

Tellerinde yanık yanık ağıtlar yaktığım,

Telli sazım, 

Sevdamsın sen.

Sevgiliye aşk ile sunduğum,

Sımsıkı tutmaktan dikenlerin acısını,

Taa yüreğimde hissettiğim, 

Gül sevdamsın sen.

Uğruna yıllarca sevda çektiğim,

Koynunda boncuk boncuk terlediğim,

sevginden, tüm eziyetlere katlanan,

Sen, göz ağrım, kaşık düşmanım, karım,

Sevdamsın sen.

Susayınca kana kana içtiğim, pınarım,

Acıkınca lokma lokma yediğim, lavaşım,

Üşüdükçe sımsıkı sarıldığım, paltom,

Yudum yudum içime çektiğim, ciğaram,

Sevdamsın sen.

Tarlada orak orak biçtiğim, ekinim,

Terleyince gölgesinde serinlediğim, akasyam,

Uğruna göğüs göğüse çarpıştığım,

Al kırmızı bayrağım, vatanım, canım,

Sevdamsın sen. sevdamsın, 

Sevdamsınız siz.

MAD: 01.03.1995', 'Sen, sıkı sıkıya kavradığım, Tellerinde yanık yanık ağıtlar yaktığım, Telli sazım,  Sevdamsın sen. Sevgiliye aşk ile sunduğum, Sımsıkı tutma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevdamsin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Eseri', 'sevginin-eseri-fatma-guven-mwk1x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Varlık cismimin içindeki,

Yokluğumun yolculuğunda,

Ne korku,öfke,kin,

Ne kıskançlık,sahiplenme,

Medet umma,yalvarma yok.

Yokluk içinde var olan,

Bir nefes,bir can kaldı,

Sevgi ışığı  ruhum.

Dağlarla yürür,

Irmaklarla akar,

Çiceklerle açar,

Kuşlarla kanat süzerim sonsuzlukta.

Sevginin ışık çocuğuyum.

Ol! ..Denildiği anda,

Sevginin sonsuz nurunda,

Varlığımla olanım.

                 14.02.2006', 'Varlık cismimin içindeki, Yokluğumun yolculuğunda, Ne korku,öfke,kin, Ne kıskançlık,sahiplenme, Medet umma,yalvarma yok. Yokluk içinde var o...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevginin-eseri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahilde Yalnız', 'sahilde-yalniz-yasar-tezel-guzxt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İskelede sensiz,sessizdi zaman

Terkedilmiş tekneler gibiyim

Sanırım,günler geçtikçe

Bendim aşınan

Kumlar gibi denizden sahile

Sahilden denize

Geçmekteydi,çalarak zaman

İskelede yine ne ben,sensiz

Gece kadar ıssızım şu beynimde

Nefes alıyor,vuran dalgalara bakıyorum

Viran olmuş sedirler gibi

Keşke hayal olsun,diyorum

olmuyor,olmuyor korkuyorum

Ne olur

İskelede yine sensiz,somurtkan

Serabımsın sen yinede unutsan

Gemilerin sireni,hırçınlaşan deniz

Belki bu derin uykudan,uyaran

Düşmüşüm dalgalar arasına

Kahrolsun boğuluyorum

Yok bana Rabbim,senden başka dost

Al yanına', 'İskelede sensiz,sessizdi zaman Terkedilmiş tekneler gibiyim Sanırım,günler geçtikçe Bendim aşınan Kumlar gibi denizden sahile Sahilden deniz...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sahilde-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Yalan', 'hep-yalan-turkan-yakin-pqvli', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herkez anlatır cocukluğunu,

Anılarını anımsar bazı zaman.

O zaman kesitleri düşündürür beni,

Özlemini hissettiğim an

Hiç oyuncak bebeğim olmadı,

Ben yapmıştım tahtadan.

Evcilik oynardım hani......

Çiçeklerden taç yapardım başıma.

Yiyecek taşıyan karıncalardı arabam.

İzlerdim doyasıya.

Yarış yaparlardı sanki,

Doyamazdım hayallerime.

Çamurdan ev yapardım.

İçine anne baba.

Etrafına da çocuklar.

Bir köpeğimiz vardı,

Adı da YAMAN'' dı,  irice

Üzerine binerdim,

Dolaştırırdı beni sevgiyle.

Özgürce koşardım,

Bozkırda, dağda.

Acıktığımı anlayınca da

Dönerdim ana kucağına.

Ne kadar da sahidendi o günler

Ne kadar da sahiden.

Şimdi ise Yalan oldu nafile

Hep Yalan.', 'Herkez anlatır cocukluğunu, Anılarını anımsar bazı zaman. O zaman kesitleri düşündürür beni, Özlemini hissettiğim an Hiç oyuncak bebeğim olm...', ARRAY['Türk Edebiyatı','Şiir','Türkan Yakın']::text[], 8.5, '{"poet":"Türkan Yakın","poet_slug":"turkan-yakin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hep-yalan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Günü', 'sevgi-gunu-muharrem-cetinkaya-ci51i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'senin seyrine doyamadığın

akvaryumda 

kınalı bir balıktır

benim bu deli gönlüm

.

bazen

bir fil gibi içiverir 

acı gerçekler

akvaryumumdaki suyu

ve bir kaşık suda boğulur

karınca gibi umutlarım

ve güzel düşlerim

ve yaşam

ve aşk

.

bazen de 

mum gibi düşlerimi söndüren

bir rüzgârdır sensizlik

hasretin yangınını alevlendiren..

.

ve sevgililer günü bilmem ben

hep severim

tıpkı akvaryumdaki balığın

suyu gibidir sevdam

ben insanım

_hissederim...', 'senin seyrine doyamadığın akvaryumda  kınalı bir balıktır benim bu deli gönlüm . bazen bir fil gibi içiverir  acı gerçekler akvaryumumdaki s...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgi-gunu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostuma', 'dostuma-yasar-tezel-xedrc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutuyorum

O sıcacık ellerini

Dostum biliyorum

Apayrı bende

Senin yerin

Muhabbeti özlüyorum

Anlaşılmaz kuyudur 

Baldan tatlı suyu serin

Gömülür gider derin

Tatlımı tatlı,onun suyu

Yiğitlerdeki yüreğin

Acı tatlı günlerim de

Dostum sen gelirdin

Hoşgeldin', 'Tutuyorum O sıcacık ellerini Dostum biliyorum Apayrı bende Senin yerin Muhabbeti özlüyorum Anlaşılmaz kuyudur  Baldan tatlı suyu serin Gömül...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dostuma-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-yasar-tezel-f9o9u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seviyorum

                Sebebsiz

                               Bekliyorum

                                                 İskele fenersiz 

                                                                        Anlayın

                                                                                   Rıhtım kedileri....', 'Seviyorum                 Sebebsiz                                Bekliyorum                                                  İskele fenersi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seslenis-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükettik Sevgileri', 'tukettik-sevgileri-kiymet-sonmez-9fvsr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdaları türkülere yazdık yıllarca

Dilimize yerleşti ezgileri

Kimi kavuştu sevdiğine,

Kimi büyük acılar çekti,

Kimi sevda sevinci ile halaylar çekti,

Kiminin sevdası oldu kefeni.

Bazan detan oldu sevdalar,

Küçüklüğümüzde satarlardı,

En acıklı sevda destanlarını,

Sonra şarkılara girdi şiirler,

En güzel sevda dizeleriyle,

Bazan müziğinden etkilendik,

Bazan da sözlerinden,

Gerçek sevdaları anlatan dizelerde,şarkılarda eskimediler yıllarca,

Hala aynı sıcaklığında söyleniyor,

Daha dün yazılmış gibi,

O şarkılarda sevgiliye değer var,

İncitmemeye özen var,

Güzelliklerine övgüler var,

Şarkılara, türkülere baktığımızda,

Bize ‘’bir zamanlar maziye bak ne kadar şendik’’ bile dedirtemiyor,

Çünkü mazi olması için bir geçmişi olması lazım,

Şimdi mazi bile olamıyor şarkılar, 

O kadar çabuk unutuluyor,

O şarkılarda nerde bulasın sevdayı,

Hiç içine girmemiş ki.

Sevgiyi tüketmişizde haberimiz yok,

Tüketim toplumu denmiş,

Doğru,

En önce sevgiyi tüketmişiz,

Daha başka neyi tüketelimki.......', 'Sevdaları türkülere yazdık yıllarca Dilimize yerleşti ezgileri Kimi kavuştu sevdiğine, Kimi büyük acılar çekti, Kimi sevda sevinci ile halay...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/tukettik-sevgileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sevmen Mübahtı Sana', 'beni-sevmen-mubahti-sana-mehmet-akif-ardic-ljjfk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“...Ama her çiçek bir gün solup gider... Her aşk birgün yaşanır biter... Nedir biliyor musun geriye kalan? Acı, umut, sevinç ve gözyaşı... Ve umarsız bir toprakta Güneş’i bekleyiş: Kardelen...............”

Seni seviyorum demeye korkmasam...

Birgün seni sevdiğimi söyleyebilsem sana.

Ama nasılll sevdiğimi...

Sen baştanbaşa Şems’ken ben pervâne olmasam;

Kim anar Kays’ı, böyle meczûb, böylesine deli!

Ne vuslâtın bir adı, ne bu sitem sana;

Ben de koşardım herkesler gibi güllerle sana,

Kavuştuğumda bu ateşin söneceğinden korkmasam...

Bir adı yok hâlâ bu sevginin...

Dostluk mu, can mı?

Kardeşlik mi, aşk mı, hiç olmak mı?

Ölüm mü... Yalan mı...

Hiçbir şeyken her şey olmak mı!?

Bir eşi, benzeri yok bu sevginin...

“Mecnûn’un sadece adı var!” diyor ya Fuzûlî...

Öyle bir âşık-ı sâdık oldum yıllarca sana!

Bedeli bugün, nefessiz, cânsız kalmaksa da,

Yazıldım Elest Meclisi’nde mecnûnca sana!

Yaradananını sevdim, yarattığı bir tek SEN’den ötürü,

Bir “Ene’l Aşk”, bir Sırr-ı Mansûr’ca sana!

Kanadım bin Esrâr Dede;

Râm oldu her kanadım esirce sana.

Solmasın gülüm hiç solmasın diye;

Ağladım bir kaç bin yıl küsûrca sana!

Sevdâmı anlarlar da sana düşman olurlar diye;

Bakamadım doya doya gözlerine, bir kez olsun cesûrca sana!

Ben de koşardım ellerimde güllerle sana,

Dikenin incitmesinden korkmasam...

Bugün Arâf Vâdileri’nden çıkıp gideceğim...

Bugün sana Kâf Dağları’ndan masallar söyleyeceğim...

Bugün... Sevdânın elinde iplik gibi büküleceğim...

Bir nefes daha almasam, almasam...

Göstersem aşkımı yetimce sana! 

Uzansam bu yaralı gönülden ipince sana! 

Bana bir kez “Sevgilim!” söyle; cân çekişeceğimden korkmasan...

Bir nokta kuşu gibi, döner dururum gönlümce sana!

Bana bir kez “Sevgilim!” söyle; ya da “Yetimim, cân”...

Öperim Ben-i Âdem’in her köpeğini, kokun bulaşmıştır diye ömrümce sana!

Sana kasîdeler biriktirdim her çöl yağmurlarında.

Söylesinler Kays ne halde, görünce sana!

Bülbül gibi âh-u zârımda — dinle bir kez ne olur — hasretten çileler örünce sana!

Anla bir kez ne olur, Kays ne halde;

Bu incecik gönül, Ben-i Âdem’de huzûr bulur ancak ikilikten birliğe erince sana!

“Lâ mevcûde illâ habîbî”...

Yok sevgiliden başka hiçbir şey, yüzümü ayaklarına sürünce sana!

Bir adın da “Şems” diye Cehennem’e inanmışım...

İstemem Adn-u Firdevs, bir gececik rûyetin derince sana!

Bir adın da Şems, ben gece kalmışım; karanlık gözlerimle özümce sana!

Bana bir kez “Kays!” söyle... 

Çıldırırım o dudaklardan duyunca adımı!

Oysa kölelerine bir önemsiz hitâbın bile mübâh sana!

Beni sevmen mübâh sana!

Ama bir kez, ama bir kez, “Aşkını duyuyorum Kays!” de.

Fısıldasan bile duyarım inan;

Geçirsen de içinden,

Ya da hiç, ya da hiç söylemesen... 

“Işığımda yanman sebebsiz değil, yandığını biliyorum Kays”, de...

Bugün, yağmurlarla iplik iplik döküleceğim...

Ne olur aç pencereni,

Nokta kuşu değil; ben gireceğim!

Doğduğum bir sevgililer gününde,

Sana bir kez sevgilim diyeceğim!

Şarkımız çalıyor, aç pencereni:

“Elbette önce çekip gidip sonra döneceğim...”

Kays gidiyor, ne olur aç pencereni,

Kayan bir yıldızla, sana dilekler dileyeceğim...

Kardelenler soluyor, ne olur aç pencereni;

Kan kırmızı bir aşkken beyazlara dönüşeceğim...

Dikçe ağlıyor, ne olur aç pencereni;

SEN’i gözyaşlarımla süsleyeceğim...', '“...Ama her çiçek bir gün solup gider... Her aşk birgün yaşanır biter... Nedir biliyor musun geriye kalan? Acı, umut, sevinç ve gözyaşı... V...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ardıç']::text[], 8.5, '{"poet":"Mehmet Akif Ardıç","poet_slug":"mehmet-akif-ardic","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/sems-in-delisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-yasar-tezel-bfoyw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüyalarıma girmez 

oldun

Yol gözlerim,gelmez 

oldun

Gönül kapısına vurmaz

oldun

Kalbine giden bir yol

buldum

Anahtarını getir artık', 'Rüyalarıma girmez  oldun Yol gözlerim,gelmez  oldun Gönül kapısına vurmaz oldun Kalbine giden bir yol buldum Anahtarını getir artık...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nerdesin-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-volkan-yoruc-q9ua1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öylesine

Ne bakışa nede sineye

Bir yalnızlık ki adı neyse

Garipçesine sarmış beni öylesine

Öylesine

Ne beri belli nede öte

Bir tuhaf yol ki nerdeyse

Yürür giderim öylesine

Öylesine

Ne anlaşılır ne anlatılır kelimelerle

Bir zor cümledir ki dilimde

Konuşamaz kalırım öylesine

Öylesine

Oturur dururum kervan geçmez köşelerde

Elimde dünden kalma hayallerle

Sığınır sokulurum anılara öylesine

Öylesine

Kararır gözlerim her seferde

Nasılda batar aşklar kirpiklerime

Yalnızlığımla baki kalırım öylesine', 'Öylesine Ne bakışa nede sineye Bir yalnızlık ki adı neyse Garipçesine sarmış beni öylesine Öylesine Ne beri belli nede öte Bir tuhaf yol ki ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oylesine-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmamalı', 'unutmamali-zeki-ergin-5k11c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'unutma

ne dünü

ne de yarını

erteleme 

yaşa bu günü

yaşam kısa 

geri gelmiyor zaman

yaşanamıyor yarınlar

anlara saklanır yaşam

sev sarııl güzelliklere

günü yaşa 

bir genç kızın 

savrulan eteklerindedir

yağmurdan ıslanan saçlarında

sarıl sevda şarkılarına

sev günü 

ince belli bir çay bardağına 

sarılır gibi 

sarıl

sevdalarına

sarıl

ve hayata

_erenköy 14şub''06', 'unutma ne dünü ne de yarını erteleme  yaşa bu günü yaşam kısa  geri gelmiyor zaman yaşanamıyor yarınlar anlara saklanır yaşam sev sarııl güz...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unutmamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır Taşı', 'sabir-tasi-ahmet-ozdemir-ib821', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Katmanlardan geçtim kaynadım coştum,

Coşum coşum akıp çağlamaktayım.

Maddemi, maddeden süzdüm de koştum; 

Sevgiyi sevgiye bağlamaktayım.

İster doğsun, ister batsın, yok farkı,

Özlemle dönüyor günlerin çarkı,

“Sorma ne haldeyim” diyor bir şarkı; 

Sen sor bir yol nice ağlamaktayım. 

Sevgi defterimi büküp düren var,

Varlık nedenimi görmez gören var,

Gönlüyle gönlüme surlar ören var; 

Örsün, sabır taşı sağlamaktayım.

(14 Şubat 2006)', 'Katmanlardan geçtim kaynadım coştum, Coşum coşum akıp çağlamaktayım. Maddemi, maddeden süzdüm de koştum;  Sevgiyi sevgiye bağlamaktayım. İst...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sabir-tasi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marmara', 'marmara-mehmet-bulut-qzmto', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha serpilmiş gördüm seni marmara

daha acımasız, daha duygusuz, insafsız...

Senin kadar dayanıklı değilim marmara

bin parçaya böldüler, her parçayı kül edip

savurdular, savruk kuytulara...

Ah marmara neden bıraktınki beni

neden gönderdin yazgısız topraklara,

en acı acıları yaşamaya? ..

Marmara ben geldim! 

Bekle dedim marmara yeniden

çocukluğumun ana kucağı..

işte yeniden dönüyorum sana.

Kırılmış, parçalanmış, dağılmış 

ve en çokta azalmış halde...

Yeniden biriktirir misin beni marmara? 

Gitmemişim gibi davranabilir misin

gitmemek üzere sana dönen bana...', 'Daha serpilmiş gördüm seni marmara daha acımasız, daha duygusuz, insafsız... Senin kadar dayanıklı değilim marmara bin parçaya böldüler, her...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/marmara-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sözüm', 'son-sozum-i-brahim-sarihan-vk64j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda yüklü bir gemiyim, denizlerde

Aşkı tattıramadan, güzel bir kalbe

Dalgaları katıp arkama sessizce

Süzülürüm usuldan, demir alıp meçhule

Sormaz, bilmez halimi eş-dost benim

Sönmez, yanıp kavrulur aşkla içim

Bir tek olsun, olsaydı ki sevenim

Canımı bile, O''nun için inan verirdim

Hep hüzünlüydü yüzüm, görmedi tebessüm

Aşkta kaybeden oldu, şu gönül gözüm

Geçseydi, gül bahçesinde tek bir günüm

Acımasız zamana, ahtım olmazdı son sözüm

Karşılıksız aşklar, yakaladı yüreğimi

Minik kalbimdi seven, sevdiysem kimi

Tüm tattığım sevgiler, yalandı belki

Aradığım sevda, elbet bulacak beni

(Hakkâri, 06 Kasım 2003)', 'Sevda yüklü bir gemiyim, denizlerde Aşkı tattıramadan, güzel bir kalbe Dalgaları katıp arkama sessizce Süzülürüm usuldan, demir alıp meçhule...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-sozum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dile Alma', 'dile-alma-mehtap-tezcoskun-9mpg7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bile bile lades demek bu biliyorum ama; 

ne senden alabiliyorum kendimi, 

ne acıdan. 

Hangi yolda mutluluk vaat ettiler de; 

gitmedim acıları bırakıp.

Nerden bilebilirdim ki; 

mutlu bir günün arkasından,

kara bulutlardan perdeler çekeceğimi. 

Oysa demiştim sana anlatma, 

dile alma içindekini diye. 

Sende haykırdın o gece. 

Kah mutluğun sarhoşluğuyla,

kah, çakır keyfi kafayla haykırdın

seni seviyorum diye. 

Dile alma demiştim oysaki içindekileri.. 

dile almaaa…

Ben istemez miydim,

göz göze geldiğimiz o masa başlarında,

pencere arkalarında ki kalp atışlarımı,

sana dinletmeyi. 

Ben istemez miydim,

sen diye elini tuttuklarım,

gerçekte sen olmasını çok istediğimi,

sana söylemeyi. 

Ben istemez miydim,

o soğuk yataktaki sıcak tenini. 

Dile alma demiştim oysa içindekileri.. 

dile alma..

İlk defa korktum sevdiğime 

“seni seviyorum” demekten, 

ilk defa korktum sevdiğimin eline değmekten. 

Resmin öbür yüzü çok karanlıktı. 

Yaptığım tüm hesaplar,

bir yanardağ çıkardı ortaya. 

Topladım senle beni, yandım. 

Çıkardım seni benden yandım. 

Çarptım çoğaldıkça yandım. 

Ama en çok böldüğümde yandım senle beni. 

En çok o bölünmeler yaktı beni. 

Dile alma demiştim oysaki içindekileri.. 

Dile alma..

Şimdi gülmelerde alınganlık, 

gitmelerde suskunluk,

yanlışlarda gözyaşı var. 

Anlamlar yüklemek her lafa,

her söze bana göre değil, 

sana hiç yakışmaz. 

Sen yorgun savaşçı, 

bense kendim savaş. 

Barışım ol desem sana, 

barışım ol. 

Duyura bilsem sessizliğin seslerini,

belki daha çabuk açarsın barışlarını savaşlarıma. 

Beklemek diyorsun,

karar anlarına beklemek. 

Biliyor musun ki, 

saniyeler nasıl işler bu yüreğin tik takların da. 

Bilir misin ki, zaman durur savaşlarda, 

kimse kaldırmaz beyaz bayrağı. 

Karar diyorsun zamanla. 

Ya ben yitireyim zamanları, 

ya sen tüket beni kararlarında. 

Ama yeter ki acele et. 

Ne zamanım dursun, 

kalbimin tik taklarında, 

ne zamanım aksın,

hayatın zehir zemberek akşamlarında sensiz. 

Oysa sırf bu yüzden demiştim sana anlatma,

dile alma içindekini diye. 

Sırf bu yüzden dile alma…', 'Bile bile lades demek bu biliyorum ama;  ne senden alabiliyorum kendimi,  ne acıdan.  Hangi yolda mutluluk vaat ettiler de;  gitmedim acılar...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Tezcoşkun']::text[], 8.5, '{"poet":"Mehtap Tezcoşkun","poet_slug":"mehtap-tezcoskun","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/dile-alma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kriminal Sabıkalar', 'kriminal-sabikalar-ahmet-zekai-yildiz-pwcwv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Krimimal sabıkalarımız,

       parmak uçlarımızdaki

               arsız  dokunuşlarda gizliydi.

Gece yolculuklarımız boyunca,

       kara gözlerinde yanıp sönen 

               şehvet uçkunlarınca yıldız kayardı.

Başımız mutluluktan göğe değince; 

      tutabildiğimiz bir tanesine biner giderdik,

              bin yıl öncesinden

              bin yıl sonrasındaki masum uykular ülkesine.

Çok eskilerden 

      genç mi genç, güzel mi güzel

              bir sevgilinin çıkageldiği

                      bulanık, kirli bir rüya kalırdı geriye.

...! Sen mişsin meğer. 

Şeytani mazoşist umularla gelen.

Canımı acıtan kan, ter çırpınışlar 

      ve epilepsi krizi sonu gibi,

            bayılırken bıraktığım son nefesle 

Bayılırdım sana.', 'Krimimal sabıkalarımız,        parmak uçlarımızdaki                arsız  dokunuşlarda gizliydi. Gece yolculuklarımız boyunca,        kara g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kriminal-sabikalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seveceğim', 'sevecegim-mehmet-ayhan-gunaydin-k17mp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEVECEĞİM

Yirmimde sevdim seni,

Kırkımda sevmekteyim.

Allah nefes verdikçe de,

Ben devam edeceğim.

Allah ömür verirde,

Gelirsem seksenime.

Ellerini alıp ellerime,

Bakıp da gözlerine,

Dalıp taaa içlerine,

Şarkılar okuyacak,

Şiirler söyleyeceğim.

Hatta verirken son nefesi,

Sevgilim diyeceğim.

Biliyorum, yetmeyecek

Öteye de götüreceğim.

Sende öğrendim sevmeyi,

Sayende ben, beni buldum.

Sevmeyi öğrenerek,

Aşka doğru yol tuttum.

Vaadi var Tanrının, 

Alacakmış cennetine.

Kimse seven,

Ve, her kimse sevmeyi bilen.

Bu sevgiyle girebilirsem

Eğer girebilirsem cennetine.

Seni yanımda isteyeceğim,

Sana olan aşkımı,

Sonsuza dek sürdüreceğim.

M. Ayhan Günaydın.

    15 Aralık 2005

          Ankara', 'SEVECEĞİM Yirmimde sevdim seni, Kırkımda sevmekteyim. Allah nefes verdikçe de, Ben devam edeceğim. Allah ömür verirde, Gelirsem seksenime. E...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevecegim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaybı Efendili Kız', 'gaybi-efendili-kiz-yasar-tezel-kidif', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahçede,bir balkonda

Mavi buluz üstüne,

Başına hızma takmış

Beşibirlik var boynunda

Eteğini ateş almış

Yaklaştıran tebessüm,onda

Tatlı bakış,cilve naz,onda

Gözüm kalmasın onda

Bilmem

Yine,görecekmiyim', 'Bir bahçede,bir balkonda Mavi buluz üstüne, Başına hızma takmış Beşibirlik var boynunda Eteğini ateş almış Yaklaştıran tebessüm,onda Tatlı b...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gaybi-efendili-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Altında', 'kar-altinda-ozgur-kokturk-narj6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar altındayken şehir

Gülüşün kalır aklımda içimi ısıtan

Yakar sevdan derinden derine

Külümden geriye adın kalır

Islanan gündür gecenin gözyaşlarıyla

Gözlerin gelir bulutların ardında

Canım iklim iklim süzülür yürekten

Bin umut olur ecelin gözbebeklerinde

Cama vuran aksindir hayat

Akışı nev''i şahsına münhasır...

Cayarım intihar yeminlerinden

Ellerinden tutarken sensiz boşluğun

Bir heyulanın bakışlarına takılırım

Kalırım helezonik hezeyanlar içinde

İçimde suskun çağlayanlar

Ağlayanlar

Anlar...

Suçlara akar masum tebessümler

Masum suçların tebessümünde...

Gün üşüyen soluklara tutsak

Dayanarak sınırsız yasaklara

Hür doğacak can ellerinde

Sevdam seninle özgür olacak...', 'Kar altındayken şehir Gülüşün kalır aklımda içimi ısıtan Yakar sevdan derinden derine Külümden geriye adın kalır Islanan gündür gecenin gözy...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kar-altinda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Kalp', 'su-kalp-i-brahim-sarihan-l5u3y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakışların, delip geçiyor inan kalbimi

Büyülüyorsun Çiçeğim, adeta beni

Gözlerimi kaçıramam, bu mümkün değil

Can suyum oldun, sensiz bir sebil

Yüreğimi ısıtan, o yumuşacık sesin

Ninni inceliğindeki, şirin sözlerin

Küçük buseler, kiraz dudaklarında

Yaşama sevinci aşılıyor, en sonunda

Çiçeğim, bizi herkes yakıştırıyor demiştin

Arkadaş çevren, beğenmiş beni sevinmelisin

Tabii, ne de olsa yakışıklı adamız

Önemlisi Çiçeğim, biz bize sevdalıyız

Şu kalp, başkası için çarpar mı hiç

Sevgin, buğulu gözlerimde bir sevinç

İçimde ateşlenen aşkınla seninim

O minicik yüreğin de, söyle ona yalnız benim

Bırakıp gitme uzaklara, acıtır beni özlemin

Bir an bile yok değilsin, kalbimdesin

Var oluş sensin, gerisini bilemiyorum

Şunu duymuş muydun; seni seviyorum

(Ankara, 14 Şubat 2005)', 'Bakışların, delip geçiyor inan kalbimi Büyülüyorsun Çiçeğim, adeta beni Gözlerimi kaçıramam, bu mümkün değil Can suyum oldun, sensiz bir seb...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/su-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Latife', 'latife-yasar-tezel-13rik', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çizik var

Kaşıntı, bir yerde

Çıban yada kara siğil

Adımız çıktı

Bay siğilli ele

Korktular anlamadılar

Bulaşır diye

Ne çizikti,ne siğil

Hep yakıştırdılar

Takıştırdılar

Kara takke

Boş bunlar boş

Hepsi latife', 'Çizik var Kaşıntı, bir yerde Çıban yada kara siğil Adımız çıktı Bay siğilli ele Korktular anlamadılar Bulaşır diye Ne çizikti,ne siğil Hep y...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/latife-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey sevgili', 'ey-sevgili-hayri-arikan-serdaroglu-48n2f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey sevgili  gönül sana gider herdem fıtraten,

Ey sevgili o sensin gönül mülkünü titreten,

Ey sevgili şeref tahtını bana verensin,

Ey sevgili hu hasretinle yere serensin,

Ey sevgili şems yakmaz canın hak gölgesindedir,

Ey sevgili us ermez sırrı gör bilgesindedir

Ey sevgili bu gönül otağına nar koyan sensin,

Ey sevgili bin yakıp teni canı har koyan sensin,

Ey sevgili bu çile ki benden sana yol açan,

Ey sevgili bu gönül ki herdem acıyı seçen,

Ey sevgili sen bendesin bende ben oldun her dem,

Ey sevgili dil söylesin tek ruh tek baş tek beden,

Ey sevgili bu çilede gönül mülkü tarumar,

Ey sevgili hak çalabım serdaroğlu em umar

,

 Hayri Arıkan (Serdaroğlu)', 'Ey sevgili  gönül sana gider herdem fıtraten, Ey sevgili o sensin gönül mülkünü titreten, Ey sevgili şeref tahtını bana verensin, Ey sevgili...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-sevgili-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigarayi Birakalim', 'sigarayi-birakalim-kemal-oguz-05uvk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutlu olmak istiyorsak,

Huzur vermek biliyorsak.

Insanlari seviyorsak,

Sigarayi birakalim.

Son pismanlik fayda etmez,

Giden saglik geri gelmez.

Yesen hergün tahin, pekmez,

Sigarayi birakalim.

Davetiye hastaliga,

Önemlidir kanser, astma.

Sakin ola yakalanma,

Sigarayi birakalim.

Tiryakiler kulak verin,

Sigarayi terkeyleyin.

Olmaz bosver hic demeyin,

Sigarayi birakalim.

Cocuklari seviyorsak,

Nikotinden koruyorsak.

Zararini biliyorsak,

Sigarayi birakalim.

Evimizde odamizda,

Mutfagimiz banyomuzda.

Rahat nefes borumuzda,

Sigarayi birakalim.

Hayatimiz kararmadan,

Gözlerimiz sararmadan.

Doktor bizi uyarmadan,

Sigarayi birakalim.

Fabrikalar bizi yoldu,

Odamiza duman doldu.

Cocuklarda kurban oldu,

Sigarayi birakalim.

Puro, tütün ne nargile,

Hepsinde var kötü hile.

Bosver deme bile bile,

Sigarayi birakalim.

Beynimizde ur olmadan,

Gözlerimiz kör olmadan.

Akcigerde son bulmadan,

Sigarayi birakalim.

Kemal derki nasihatim,

Bu degildir benim bahtim.

Nikotinden olmaz tahtim,

Sigarayi birakalim.

(Filderstadt, 14 Subat 2006)', 'Mutlu olmak istiyorsak, Huzur vermek biliyorsak. Insanlari seviyorsak, Sigarayi birakalim. Son pismanlik fayda etmez, Giden saglik geri gelm...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sigarayi-birakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler(115) ’ Gül Dalına Yaslandım...''', 'maniler-115-gul-dalina-yaslandim-abdullah-atay-s5kwy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül yarsız çöllerde

Mecnun gibi dillerde

Hani sen gelecektin

Gözüm kaldı yollarda...

Senle bahar yaz güzel

Cilve güzel naz güzel

Seni çok sevdiğimi

Sen gönlüne yaz güzel...

Kınalar yakın güzel

Zilleri takın güzel

Öyle uzakta kalma

Ol bana yakın güzel...

Bağda gülün altısı

Yarim dünya tatlısı

Sevip sevip ayrılan

Dünyanın en dertlisi...

Her gülü koklayamam

Goncasın yoklayamam

Tanrının bildiğini

Kullardan saklayamam...

Gül dalına yaslandım

Nazlı yare seslendim

Yar yanıma gelince

Bal dudakla beslendim...

Unutma sen kefeni

Sarar bir gün bedeni

Dost gönlüne han yapmak

Yaşamın tek nedeni...

Anla insan halini

Hayra harca malını

Gün gelecek seninde

Dost tutacak salını...', 'Gönül yarsız çöllerde Mecnun gibi dillerde Hani sen gelecektin Gözüm kaldı yollarda... Senle bahar yaz güzel Cilve güzel naz güzel Seni çok ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maniler-115-gul-dalina-yaslandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopuşlar III', 'kopuslar-iii-erol-dal-so1wk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Usulca seslendi,

“Umo arte can”

Duydum,

Aldatılan şehrin çığlıklarını.

Perdeye dokundu ıslak eller

Güneş girdi, 

Gizlice.

Dokundu, kürek kemiğimden bir sızı belime.

Şehir yanıyordu, 

Bensiz tepede sinsice.

........

Vurduğu gibi nemin duvarlarına sevdim güneşi,

Sevdim, mis kokan kadının  ellerini. 

Kuru ekmek parçalarını dokundurmak için dilime,

Sevdim annelerin heyecanlarını 

Sevdim delice..

Usulca seslendi

“Umo arte can”

...

Uyudum, uykumda.

ED/06', 'Usulca seslendi, “Umo arte can” Duydum, Aldatılan şehrin çığlıklarını. Perdeye dokundu ıslak eller Güneş girdi,  Gizlice. Dokundu, kürek kem...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kopuslar-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedigöller', 'yedigoller-hulki-can-my6uz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yedigöller on dört pınardan 

On dört  pınar  yüzdoksanaltı çokrağandan 

Yüzdoksanaltı çokrağan da  İvrizin pembe ayaklarıyla bastığı 

İkibinyediyüzkırkdört  gözyaşı göbelinden doğdu. 

Her pınar bir  ana vuracı, her göl bir oğulcuk koruganıydı. 

Göllerin, arıların ve balların   tanrıçası  İvriz 

Delirten baldan yiyen acundaş Tungayı ölümden kurtaramadı. 

Tungay dolunay vakti çakal gibi uludu,

Dördün süresi bitene dek kırlarda vahşi hayvanlarla dövüştü

Sığır gibi ot yedi.

Yürek buruntuları içinde öldü...

Ve gözyaşlarından İvrizin Yedigöller doğdu.

I. Nazlıgöl

Canlı.

Gizemli. Nazlı.

Nilüfer. Yaprağı.

Fil kulağı. Rüzgarlı. 

Göl ormanı gece...

Pırlanta eğimli bir taşın

Kesilmiş yüzü gibi

Sessizlik.

II.. Büyükgöl

Ses veren tılsımlı dağdan

Akar göle elginlik

Karaçam göl ve gölgelik

Yedipınardan geleğen

Sarıçamlara gideğen

Akak Bolu dağına

Vincent Van Gogha.

  

III. Küçükgöl

Bakar ona göl.

Ona da o.

Nergis olur Narsis.

Düş olur.

Balık olur.

Sis olur.

Çığ olur.

Siyah olur

Siyahı koyu - koyu yeşil

Yeşil olur

Yeşili siyah - siyah yeşil

Yeşili Breughel - Siyahı Renoir...

Siyahlar ve yeşiller

Ve küçük çiçeği göl 

Kalbinden ikizler 

Kayar gider su üzerinde toz. 

IV. Sazlıgöl

Dağ. Çam dağı! 

Göl. Dağ gölü! 

Çam gölleri! 

Göl çamları! 

Başkaldıran Alp Parsifal 

Tanrılara kaçan Tanhauser

Diz çöker kutsal haça

Büyüler excalibur 

Dağ  tapınağını

Göl toprağını 

Sihirler sazını 

V. Deringöl

Kanadından  meleğin dökülür –sis...

Bağılar perisini derin - sis......

Lohengrin –sis........

Yankı yansır sisler içinden

Sen! ........ sen! 		Sen! sen! 

Nar  yutan balıklı kilim

Balığı yutan Nar-sis 

Düşünde balık kızın göl

O! .............. o! 		O! o! 

Ben! ............. sen! 	Sen! ben! 

O! ................ o! 	O! o! 

O! .....................o! 	O! o! 

O! .....................o! 	O! o! 

VI. Ortagöl

Yüksek kayaçtan

Doğudan akar

Bindirerek bulutsu doruğa.

Çıpıltısı alaçam

Sazlarda göl.

Kalın

Yoğun

Barok bir kitap gibi

Dağın ortasında

Yağmurla sevişir

                                                                                                            

VII. Aşağıgöl

Gece uyumaz

Bulutsu durmaz

Görünmez dördün

Yamaca yansır saçı sırça

Dolunaysu o kadar siyah

Gölsu o kadar parlak ki...', 'Yedigöller on dört pınardan  On dört  pınar  yüzdoksanaltı çokrağandan  Yüzdoksanaltı çokrağan da  İvrizin pembe ayaklarıyla bastığı  İkibin...', ARRAY['Türk Edebiyatı','Şiir','Hulki Can']::text[], 8.5, '{"poet":"Hulki Can","poet_slug":"hulki-can","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/yedigoller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trans', 'trans-kamer-taskin-27g37', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşin doğuşundan,

Tomurcuğun patlayışından,

Suyun akışından,

Açın doyuşundan,

Alıyorum bir nefes,

Tüm bunlar enfes,

Bilmem hissedebiliyor mu herkes,

Transtayım, lütfen sesini kes.', 'Güneşin doğuşundan, Tomurcuğun patlayışından, Suyun akışından, Açın doyuşundan, Alıyorum bir nefes, Tüm bunlar enfes, Bilmem hissedebiliyor ...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/trans-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şubat Soğundayım', 'subat-sogundayim-hasan-cam-zwvah', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sevgi istiyorum ta derinden, kalpten seven

Birazcık  eskilerden, yürekten, ölümüne seven

Aldığım nefes, içtiğim su, damarımda kan olmalı

Senede bir gün olmamalıydı, can veren yaren

Bu gün, güller gönlümdü, yine kalbimdesin sen

Akşamdan uykusuz sabahı, seni bekledim hep

Güneşim doğmadı bu gün, şubat soğundayım

Belki sağ, belki sol yanında, bilki kalbindeyim ben

Penceremi kapadım, başka görmeyecek gözüm

Yılar yılı gerçektin mazimde, gülmeyecek yüzüm

Değişmeyecek yine, sana akan sevda sellerim

Aptal gönlüm söz dinlemiyor, boşamı hayellerim

Bu gün, güller gönlümdü, yine kalbimdesin sen

Akşamdan uykusuz sabahı, seni bekledim hep

Güneşim doğmadı bu gün, şubat soğundayım

Belki sağ, belki sol yanında, bilki kalbindeyim ben

Bu gün daim, hergün olsun, sevgi günü sevenlerin

Dertlere razıyım, sevgi selim benim servetim olsun

Al sevgilim gönül gülümü, solmadan vazonda dursun

Bu gidiş ne ben, nede sen, ahrette  mutlu olursun

Bu gün, güller gönlümdü, yine kalbimdesin sen

Akşamdan uykusuz sabahı, seni bekledim hep

Güneşim doğmadı bu gün, şubat soğundayım

Belki sağ, belki sol yanında, bilki kalbindeyim ben

14 02 2006

Ümraniye    İstanbul

[email protected]', 'Bir sevgi istiyorum ta derinden, kalpten seven Birazcık  eskilerden, yürekten, ölümüne seven Aldığım nefes, içtiğim su, damarımda kan olmalı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/subat-sogundayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canözüm-3', 'canozum-3-faruk-gokbulut-im39s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adını duyunca canım tutuşur

İçime bir kızıl kor düşer

Sevdana yanınca közüm tutuşur

Aklıma bir güzel yar düşer

Adını anınca özüm yatışır

Kalbime bir beyaz kar düşer

Bastığın bu yerler şavkınla ışır

Bahtıma süt beyaz nur düşer

Makbulse dilekler eller açılır

Yazgıma bir vefalı kul düşer

02 EKİM 2004

Saat:  05:00

Afyon', 'Adını duyunca canım tutuşur İçime bir kızıl kor düşer Sevdana yanınca közüm tutuşur Aklıma bir güzel yar düşer Adını anınca özüm yatışır Kal...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canozum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir dilim ekmekti sevdan', 'bir-dilim-ekmekti-sevdan-selahattin-yetgin-0dw70', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sisler çekilince gönlümün derinliklerinden

yangın dudaklarının yüzyıllarına düşerdim

ritmim bozulurdu kıvrılarak uzanan yollarda

olup olmadık yerde seni arar gölgeni arardım

sırtımızdaki yorgun aşklarla yağlı kandillerle

yüreğimi yüreğine zorunlu beklentilere açardım

konuşurduk oradan buradan sessizliğe ağlardık

cehennem yalnızlığıydı oysa ki ayrılık bilmiyorduk

ucundan koparılmış ekmekçe birbirimize soğuyorduk

bakışlarımızdaki yoksulluk geçiciydi belki anlıyorduk

uzak dağlardı düşünü gördüğümüz gitmek istiyorduk

köpüklü dalgaları aşacaktık sevgimize güveniyorduk

tamamı sevgiden yapılmış yelkenliyi yüzdüremiyorduk

sonra sürgüleri paslı bir kapının ardında kalakaldık

gökyüzünü silkeledik ıslak dirençlerimizi de saldık

payımıza düşen hüsran şarkılarıyla günlerce ağladık

tükenişi oynuyordu tüm sinemalar bilet bulamadık

güneşe döndük o üşümüş bedenlerimizi ısınamadık

iki yaralı kalpti avuçlarımızdaki kan pompalayamadık

devrilmişti kadehlerimiz ve devrikti hep zaferlerimiz

aşkı damıttığımız oluklardan denizler yaratamamıştık

keşkelerin dikildiği ücra atölyelerde zaman tüketmiştik

biz sustukça örselenen yüreklerimizi asla dinlememiştik

geçmiş zaman kapsülünde yarından çok dünü yaşadık

bindiğimiz masal atını kendi ellerimizle dağlara saldık', 'sisler çekilince gönlümün derinliklerinden yangın dudaklarının yüzyıllarına düşerdim ritmim bozulurdu kıvrılarak uzanan yollarda olup olmadı...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-dilim-ekmekti-sevdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
