INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü 2', 'sevgililer-gunu-2-mustafa-aslan-2-mpas3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün subat ayinin ondördü 2006,

Yine yeni bir sevgililer günü,

Belkide ilk defa bukadar mutluyum,

Neden mi? 

Bir sevgilim var.

Bu sevgili dünyaya bedel.

Iliskimin baslamasindan bu yana,

Tam 14 ay geçti,

Hergün beraberiz,

Ve sevgililer günü geldi,

Yine beraberiz,

Yanimda olmasi çok güzel.

Dünden düsündüm ne alabilirim diye,

Sevgimi gösterecek,

Aklima birsey gelmiyordu,

Çildiracaktim.

Gül versem çok standart oldu,

Kolye, küpe veya yüzük,

Geç bunlari.

Parfüm desen,

Onun dogal kokusu hosuma gidiyor.

Saçmada olsa bir bardak aldim,

Bardagin içinde bir aslan,

Ayni soyadim gibi,

Aslanin elinde bir kalp,

Ayni bendeki gibi.

Hosuna gittimi bilmem,

Ama gitti saniyorum.

Gülmesinden belliydi.

Derlerya asik olup çile çekecegime,

Nezle olur burnumu çekerim.

Bence çok saçma,

Çilesi sevda,

Savdasizda hayat olmaz.

Sevgililer gününüz kutlu olsun,

En içten dileklerimle.

Tarih Ve Saati: 14-02-2006	18:27', 'Bugün subat ayinin ondördü 2006, Yine yeni bir sevgililer günü, Belkide ilk defa bukadar mutluyum, Neden mi?  Bir sevgilim var. Bu sevgili d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevgililer-gunu-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Tanrım', 'gunes-tanrim-nilgun-acar-ezl8m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sorun da bu ya birtanem

sen koskoca deryada

bir fenerin üzerindesin

ve aydınlatıyorsun dört bir yanı

yol gösteriyorsun denizcilere

gözlerinden yıldızlar saçıyorsun

onun için yakamoz yakamoz sular

balıklar pul pul saçları köpük köpük dalgaların

deniz tanrısı Poseidon''sun sanki

ya da benim güneş tanrım Apollon

yüreğimi ve beni bana geri veren

evet usatsam elimi tutarım seni

tam karşımda mutluluk yanıbaşımda

ne kadar büyük ve hırçın olursa olsun

aşarım o sütbeyaz denizi kayalıkları

boğulsam parçalansam da önemi yok

ruhum uçar gelir yanına karışır ruhuna

istesem ah evet istesem tutamazlar beni

ama kahretsin bin kere kahretsin

yazılı ve yazısız kanunlar var

insan kılığındakilerin yarattığı

görünmeyen zincirlerle prangalandığımız

oysa yasak değilsin günah değilsin uzak değilsin

üstelik benim için bay sevgisin Bitter çikolatam

seni yalnızca gözlerimle okşayabilirim

yüreğim çırpınır gözlerini görünce ışık ışık

gülüşlerimle gizlerim özlem çığlıklarımı

aynı çatı altında yaklaşamam sana

seni yakarlar taşa tutarlar yokederler

asla kıyamam incimeni istemem

belki senin de mutluluğun özlemin bende

içim bunu hissediyor yaşıyor tüm sıcaklığıyla

hemen şu anda koşmak istiyorum kollarına

sokuluvermek kocaman güçlü göğsüne

ve orada öylece kalıvermek sonsuz

yaşamak yaşamak doyasıya tenini

içmek gözlerini tanımak ellerinin çizgilerini

bu dünyada cenneti yaratmak aşkın ateşiyle

hiç ama hiçbir şeyi düşünmemek yalnızca yaşamak

isterdim hem de nasıl birtanem hayatımın anlamı

kendim için değil korkum dedim ya sana kıyamam

olsun karşımdaki fenerin üzerinde kal yeter ki kal

sütbeyazı denizi ve kayalıkları aşacağım söz

bekle ve bana yardım et yüreğinin gücüyle

kopalım şu yanılsamalar dünyasından

sana dokunamasın hiçbir kötülük karanlık

güneş tanrım ışınlarınla yanmaya razıyım', 'Sorun da bu ya birtanem sen koskoca deryada bir fenerin üzerindesin ve aydınlatıyorsun dört bir yanı yol gösteriyorsun denizcilere gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gunes-tanrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-yasar-tezel-sjsh5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dokunmayın, bana

dokunmayın istemem

Dokunmayın göz yaşıma

silmeyin öyle kalsın istmem

Dokunmayın anılarıma,

dokunmayın istemem

Geceler kararsada

Gurbet bağlasada

dokunmayın sevdiğime

Dokunmayın istemem

Nazar değecekse gözüme

dokunmayın göze akan göze

Göz bebeğime,dokunmayın istemem

Tutsam elini,kucaklasam belini

Dokunmayın istemem

Cana can katan,cana

Gönülden ağlayana dokunmayın

dokunmayın istemem

Değmeyin hayat dolu dünyama

Dokunmayın bana,dokunmayın istemem

Gönül bahçemde açan çiçeğe

Görse gözler gülecek

Belki bir gün gelecek

Dokunmayın yıldızlarıma,

dokunmayın mehtabıma,dokunmayın istemem

Sadece bir teneffüs,içimde kalan

Batmakta olan kızıl güneş

Kıpır kıpır içim

Lakin vakit çok geç

Dokunmayın dizelerime,dokunmayın bana

Dokunmayın istemem.dokunmayın istemem', 'Dokunmayın, bana dokunmayın istemem Dokunmayın göz yaşıma silmeyin öyle kalsın istmem Dokunmayın anılarıma, dokunmayın istemem Geceler karar...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/istemem-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrün Baharları', 'omrun-baharlari-galip-uyar-v9mp9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beklerim demiştim

Baharda gelmen şart değil

Gez, harca baharlarını

Yeşersin filizler

Açsın teker teker çiçekler

Beklerim

Çık gel bir kış akşamı

Kurumuş olsun dallar

Varsın çürüsün ağaçlar

Beklerim

Çık gel bir kış akşamı

Bekler miyim diye düşünme

Çal kapımı çekinme

Bak göreceksin

Söz veriyorum sana

Kışlar dönecek bahara

Yeşerecek ümitler

Açacak yeniden çiçekler

Kuruyan dallara inat...

Dedim ya

Beklerim

Baharda gelmen şart değil', 'Beklerim demiştim Baharda gelmen şart değil Gez, harca baharlarını Yeşersin filizler Açsın teker teker çiçekler Beklerim Çık gel bir kış akş...', ARRAY['Türk Edebiyatı','Şiir','Galip Uyar']::text[], 8.5, '{"poet":"Galip Uyar","poet_slug":"galip-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/omrun-baharlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Merhaba*Sevgililer günü arifesi', 'merhaba-sevgililer-gunu-arifesi-tulay-i-cen-au1vf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba..

can  merhaba...

Aşkım yüreğimdeki  tek yarim  sevgilim.

Canım sensiz gecen yıllar içimdeki  sevginden hiç birşey  eksiltmeden  devam  ediyor.Sen  benim  ışığım benim yol gösterenimsin seni unutmam mümkün değil.Sen  bir tanem  sen inan seni halen  yıllar  öncesinden  daha  cok seviyorum sana sarılmasamda  sana  dokunamasamda  seni  seviyorum sana  kavuşana  kadar  seveceğim.

Aşkım  sana hasretim teninin  kokusunu  halen buram buram kokluyorum kokunu  hiç unutmadım.

Can  uzun zamandır  sana  merhaba  diyemedim  ama sen  hep yüreğimdesin.

Aşkım yarın 14 şubat  Sevgililer  günü ben yine sensiz senin  sevginden yoksunum,ne olur  bana  bir kerecikte olsa  görünüp seni  seviyorum  desen.

Ben hergün sana  sevdiğimi  söylüyorum ama  ne yazık  cevap alamıyorum inanıyorumki bu dünya  yalan  ama  ölüm gercek.Ölüm  seni  benden  götürdü bedenini aldı  benden inanıyorumki sen  benimle  berabersin bana  sevdiğini  söylemesende ben  her gün  seni  sevdiğimi  söyleyeceğim.

Aşkım  yarın  senin yanına  kabristana gelmeye   sana  yakın olmak için elimden  geleni yapacağım.

Canım ben sana  kavuşana  kadar  seni  sevmiye devam  ediceğim sana  kavuştuktan sonra  bile.

Canım  benden seni  unutmamı  asla isteme  bunu  yapamam  sen  benim  kaderimdin  öylede  kalacaksın.

Yüreğim  yaralı olsada  bu beden ve yürek  seni asla  ama asla unutmayacak.

Seni  cok seviyorum hasretinle  eriyip  bitsem bile  seni  seviceğim.

Sevgim mezara kadar.Ölümden sonra  bile devam edicek.

13/02/2002', 'Merhaba.. can  merhaba... Aşkım yüreğimdeki  tek yarim  sevgilim. Canım sensiz gecen yıllar içimdeki  sevginden hiç birşey  eksiltmeden  dev...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/merhaba-sevgililer-gunu-arifesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-emre-i-nan-k5pu0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şimdi gençliğe güvenın yoktur

bu yaşta çileden çıkaran çoktur

erkeğin bakışı sihirli oktur

dikkat et kalbini delerler gülüm', 'şimdi gençliğe güvenın yoktur bu yaşta çileden çıkaran çoktur erkeğin bakışı sihirli oktur dikkat et kalbini delerler gülüm...', ARRAY['Türk Edebiyatı','Şiir','Emre İnan']::text[], 8.5, '{"poet":"Emre İnan","poet_slug":"emre-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gulum-184-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-levent-i-skenderoglu-s31l9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anne

Taze karpuz kokuyor

Dudakların

Tenin güneş yüzü görmemiş

Yüzün bir bebek kadar mahzun

Gözlerin uyku mağruru

Buzdan alevler yapışmış ellerine

Kaşların tane tane dağılmış

Sımsıkı bir mıh çakılmış 

Kirpiklerine

Yine de anne

Çok güzel uyuyorsun

Teneşirin üstünde', 'Anne Taze karpuz kokuyor Dudakların Tenin güneş yüzü görmemiş Yüzün bir bebek kadar mahzun Gözlerin uyku mağruru Buzdan alevler yapışmış ell...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anne-201-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanca', 'i-nsanca-abdullah-oral-y4reg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İNSANCA

Bir sevda sarardı bütün dünyayı

İnsanın elinde gülüm solmasa

Bölüşüm olurdu insanın payı 

Düşünen insana ölüm olmasa.

Hakka razı olsa insanlık soyu

Geçmezdi insana hayvanlık huyu

Akarmıydı kanlar tarihler boyu

İnsan doğasında zulüm olmasa

Bedrettinler dara çekilir miydi

Mansur parça parça kesilir miydi

İsyan çığlıkları yükselir miydi

Şu hınzır paşalar zalim olmasa

Ahmet Yeseviden Bektaşi veli

Doğudan batıya eser dost yeli

İnsan doğasında bir umut seli

Coşar mı sanırsın bilim olmasa

Zirvede oturan beyler paşalar

Basılır göksüme kızgın maşalar

İnsan kanı içer öyle yaşarlar

Varoşlardan coşan selim olmasa

Nasıl aşka düşmez insanın teni

Dostumdan saymışım pir sultan seni

Türküler yakmazdı bu kadar beni

Her gün mızrap vuran telim olmasa

İnsan hak dedikçe taşlanır mıydı

Şairler ozanlar suçlanır mıydı

İnsanca bir sevda yaşanır mıydı

Şu türkü söyleyen dilim olmasa

Şu yüce dağlarda kar olur muydu

Hoşgörüsüz insan yar olur muydu

Örselenmiş ateş nar olur muydu

Hünkar Hacıbektaş velin olmasa

Aşılmazsa insan hakkıyla yollar

Nasıl sarsın dostu dost diye kollar

Sevdaya durur mu baharda dağlar

Kızıl saçlı yarim gelin olmazsa

Uzak etme beni dostluk telinden

Özgürlük türküsü söyle dilinden

Vurguni kurtulmaz zulmün selinden

 Birde kalem tutan elim olmasa…

                                                16 Ağustos 1999 

35.Geleneksel IX Hacıbektaş şenliğinde 2.ödülü', 'İNSANCA Bir sevda sarardı bütün dünyayı İnsanın elinde gülüm solmasa Bölüşüm olurdu insanın payı  Düşünen insana ölüm olmasa. Hakka razı ols...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/insanca-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağdaş olmak', 'cagdas-olmak-abdullah-oral-11qg7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÇAĞDAŞ OLMAK

İnsanın bağında açan

Gül olmaktır çağdaş olmak

Gönülden gönül’e coşan

Sel olmaktır çağdaş olmak

Halk ile birlik yaşayan

Yürekte aşkı taşıyan

İnsanın sevip okşayan

Dil olmaktır çağdaş olmak

Beyinde zinciri kıran

Cehaleti yere vuran

Dört mevsim çiçeğe duran

Dal olmaktır çağdaş olmak

Varır yaşamın tadına 

Sevgi gösterir kadına

Sınıfsız toplum adına 

Yol olmaktır çağdaş olmak

Gönül gözü ile gören

Hak yoluna gönül veren

Dostlukla Dünyayı saran

Kol olmaktır çağdaş olmak

Bir çığlıktır aşka düşen

Zorbanın zulmünü kesen

Bağımsızlık için esen 

Yel olmaktır çağdaş olmak

Halkın derdini dinleyen

Özgürce türkü söyleyen

Mızrap vurdukça inleyen

Tel olmaktır çağdaş olmak

Düşünen insan selinde

Dertli sazımın telinde

Vurguni ozan dilinde 

Bak olmaktır çağdaş olmak

                                      16  Ağustos 2000

36 Geleneksel. X. Ulusal Hacıbektaş şenliklerinde 1.Ödülü.', 'ÇAĞDAŞ OLMAK İnsanın bağında açan Gül olmaktır çağdaş olmak Gönülden gönül’e coşan Sel olmaktır çağdaş olmak Halk ile birlik yaşayan Yürekte...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/cagdas-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tatlı acıbadem...', 'bir-tatli-acibadem-ahmet-kose-xv8ms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğime akıyorken

damlaların

biri mavi

biri kırmızı

biri sen

biri ısırılmış yüreğin.

Dönüyorken hayatıma

siluetin

uçları değerken saçlarıma

beyaz eteğin

sırtının göğsümdeki izi

dayanırken ben yüreğimin duvarına.

Hayatıma giriyorken 

sen

gözümü aşk bürümüş

tınıların kulağımı

sızıların burnumu

bir tatlı acıbademimsin

dilimde eriyen

damağımdan yitmeyen.

Ben seni seviyorken.

14/şubat/aşk/05/bitez', 'Yüreğime akıyorken damlaların biri mavi biri kırmızı biri sen biri ısırılmış yüreğin. Dönüyorken hayatıma siluetin uçları değerken saçlarıma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-tatli-acibadem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Sevdi', 'herkes-sevdi-munur-atakul-0tshx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yunusta Mevlayı aşkta aradı

Yol etti çölleri bir bir taradı

Yunusta kanayan nasıl yaraydı

Bu yüzden lakabı derviş sayılır

Mevlana sevgide buldu huzuru

Her şeyi sev dedi dingin,munzuru

Af eden büyüktür kemi,mahsuru

Bu yüzden mevlaya gitmiş sayılır

Bilal sesi ile ezan sevdirdi

Rengi siyah idi akça sevildi

Sevda haykırırken taşlara geldi

Bu yüzden lakabı habeş sayılır

Ömer hak diyerek ömrü tüketti

Şahsında ALLAH ın adı hükmetti

Nefside bir kefen duayla gitti

Bu yüzden makama yetmiş sayılır

Şeytan kini sevdi kibirle durdu

Bu yüzden dergahtan çıktı kovuldu

Şeytanın yüreği kimlerin yurdu

Bu yüzden belaya batmış sayılır

Ecel gelir çatar bilinmez zaman

Çekilir dizinden döşünden derman

Hak eliyle yetmeden o ulu farman

Bu yüzden her tövbe anmış sayılır', 'Yunusta Mevlayı aşkta aradı Yol etti çölleri bir bir taradı Yunusta kanayan nasıl yaraydı Bu yüzden lakabı derviş sayılır Mevlana sevgide bu...', ARRAY['Türk Edebiyatı','Şiir','Münür Atakul']::text[], 8.5, '{"poet":"Münür Atakul","poet_slug":"munur-atakul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/herkes-sevdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mektup', 'son-mektup-i-brahim-dogan-rggcw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'benden ayrılmaya karar vermişsin

bütün resimleri gönder demişsin

seni sevdiğimi düşünmemişsin

bu bana yazdığın son mektubunmuş', 'benden ayrılmaya karar vermişsin bütün resimleri gönder demişsin seni sevdiğimi düşünmemişsin bu bana yazdığın son mektubunmuş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Doğan']::text[], 8.5, '{"poet":"İbrahim Doğan","poet_slug":"i-brahim-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-mektup-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürmek', 'oldurmek-harun-kaya-3-8h1bh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülen gözlerime bakıpta gülüm sanmaki mutluyum,

Diğer benler  gibi rol yapan usta bir oyuncuyum,

Yabancı değilim artık, kaç kez geçtim bu yoldan,

Yada kaç kez düştüm aynı pusuya bile bile bir bilsen.

Tatmadığım acı küstü bana,

Yemediğim sillle büktü boynunu,

Çekmediğim çilenin gözleri sislendi.

Küçük tepecikler yaptım sırtımdan çıkan kurşunlarla,

Yarı can yaşadım desem yeridir, bir gözüm hep eceli gözler,

Bir türlü alışamadığım sigaram vardı senden önce dudağımda,

birde içimi  delip geçen boktan bir öksürük tam şuramda.

Şimdi sevgine şarkılar var ve yokluğuna sitem dudağımda,

Birde öksürüğüme iyi gelen telefon çağrıların kulağımda.

Telefon dedimde.....

Üç gündür haber yok gene senden,

İçimi garip kurtlar kemriyor gene.

Aklımda kocaman soru işaretleri yarına dair,

Ve içimde seni kaybetme endişesinde korkak bir şair.

Şimdi en büyük korkum,,,,

Bir gün seni başkasının kollarında yürürken görmek,

Bir gün seni başkasının yanında  gülerken görmek,

Yada ben olduğumu bile bile telefonu meşgule düşürdüğünü bilmek.

İşte o gün güzeller güzeli..

İşte ogün gözümün nuru. bana ya ölmek düşecek 

Yada gözümü bile kırpmadan  ÖLDÜRMEK.........

 (c)      Bu şiirin her türlü telif hakkı kendi ve /veya temsilcine aittir', 'Gülen gözlerime bakıpta gülüm sanmaki mutluyum, Diğer benler  gibi rol yapan usta bir oyuncuyum, Yabancı değilim artık, kaç kez geçtim bu yo...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oldurmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezanı Dinlerken', 'ezani-dinlerken-ekrem-sama-ufu5g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlıklar yırtılır, yüce davet zamanı,

Çevirin gönülleri, duyun kutsal ezanı.

İlahi diyarlardan gelir bu ibareler,

Şahitlik ediyor şu yükselen minareler.

Sanmayın bu sedalar müezzinden geliyor,

Rabbimin engin rahmet denizinden geliyor.

Tekbirler dalga dalga, çiçekleniyor sema,

Yine ezan vaktidir, rahmet iner yurduma...

Gönül dünyalarına yağar her bir kelime,

Bu ilahi parola, davet yedi iklime.

Ezanı duyan mümin hemen koşar felaha,

Koş kardeş, kaçan fırsat  ele geçmez bir daha,

Haydin namaza gelin, orda kalsın kıl ü kal,

Kulaklar paslı ya Rabb, gönder yeni bir Bilal! ..

(İstanbul:17.04.2005)', 'Karanlıklar yırtılır, yüce davet zamanı, Çevirin gönülleri, duyun kutsal ezanı. İlahi diyarlardan gelir bu ibareler, Şahitlik ediyor şu yüks...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ezani-dinlerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınalı Kuzum', 'kinali-kuzum-mehmet-sukru-bas-3vv08', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KINALI KUZUM

  Yıl 1915, aylardan Ocak. Yer Çanakkale. Denizde sayısız İngiliz ve Fransız filosu, karşıda İtilaf Devletlerinin, bir ulusu tarihten silmek, can damarı olan boğazlarını ele geçirmek adına bir araya gelmiş yarım milyondan fazla askeri gücü. Akif''in dediği gibi hayâsız bir akın, hayâsız bir ordu.

           Yozgat Sorgun kazasının Karayakup Köyünden cepheye gelen Murat adındaki genç nefer, bölükteki tıbbiye öğrencisi Şükrü Beye anasına hitaben bir mektup yazdırıyor.''Anacığım kardeşlerimi askere gönderirken başına kına yakma. Zabit Efendi bana sordu, cevap veremedim. Kardeşlerim de cevap veremeyip mahcup olmasınlar.'' Der ve bir de şiir ekler mektubuna…..

                           Çanakkale geçilir mi sandı küffar,

                           Bölük bölük buraya geldiler ana.

                           Son nefer de vurulup düşse toprağa,

                           Yine de geçilmez ki, bu belde ana.

                           Yalnız kınanın manasını bilemem,

                           Senden armağan, istesem de silemem.

                           İnandım ki ben, sağ olarak dönemem,

                           Şehitlik rütbesine hazırım ana.

                           Yaktığın bu kına durdukça başta,

                           Mustafa Kemal''ler de oldukça başta.

                           Düşman bin bölük olsa karşıki safta, 

                           Üzülme geçilmez bu belde ana.

                           Kardeşimin başına yakma kınayı,

                           Belki bilemezler kınadaki manayı.

                           Karşımda küffar düşünemem sılayı, 

                           Hakkın helal edesin, hakkını ana.

           Bu mektup Murat''ın anasına gider. Ana bir okuryazar bulup oğluna şu cevabı yazar.''Ey oğul, gözüm nuru Murat''ım! Zabit Efendiye selam söyle. Biz kurbanlık koçları kınalar öyle kurban ederiz. Sen dört kardeşin arasında kurbansın. Sen İsmail''sin (A.S.) , sen orada şehit olacaksın inşallah. Kurbanlık koçlar nasıl kınalanırsa ben de onun için senin saçlarını kınalayıp gönderdim.'' der ve o da mektubuna bir şiir ekler.            

                                                                 

                           Ey oğul, ey Murat''ım, kınalı kuzum,

                           Şehit olmandır gönlümdeki son arzum.

                           Çanakkale ''son kale'' siper et seni,

                           İffetime yâd eli değemesin kuzum.

                           Varsın beklesin yavuklun da yolunu,

                           Bu yollarda şan, şeref beklenir kuzum.

                           Her cefaya her zaman hazır, nazırım,

                           İffetime yâd eli değmesin kuzum.

                           Kardeşinin başına yaktım kınayı, 

                           İsmail gibi Hakk''ın emrinde kuzum,

                           Bu emirde Felah var, şan var, şeref var,

                           Onlar da şehitliğe, hazırdır kuzum.

                           Biz kurbanlık koçlara, kına yakardık,

                           İsmail''in aşkına, Hakk''a adardık.

                           Bu yüzdendir başına kınayı yaktık,

                           Bu vatana, bu yurda, kurban ol kuzum.

          Bu mektup Murat''a gittiğinde, Murat''ın kınalı başı çoktan Allah''ına kurban gitmişti. O mübarek ananın duası kabul olunmuş, kınalı kuzusu Murat şehit olmuştu. 

          Bu mektupta dikkat çeken nedir gördünüz mü? Bir ananın oğlunu şehit olmak amacıyla askere göndermesi, onun şehitlik mertebesine erişmesini temenni etmesi ne mübarek bir temenni yarabbi, ne mübarek bir istek. Böyle anaların elleri öpülmez mi?    

          Bu Çanakkale Savaşı ki; 253.000 vatan evladının, kınalı kuzuların canları pahasına kazanılmıştı.

           Çanakkale''yi geçilmez kılan bu mübarek analara ve bu mübarek şehitlerin cümlesine Allah''tan sonsuz rahmetler diliyorum. 

           Bu yazımı ve bu şiirlerimi bu vatanın nasıl ve ne şartlarla kurtarıldığının hala bilincine varamayan gaflet ve ihanet içinde olan bedbahtlara ithaf ediyorum.

Anne ve oğlunun şiirlerini yazan: MEHMET ŞÜKRÜ BAŞ

                                                   ***** 

             25 Şubat 2006 Tarihli ELAZIĞ Nurhak Gazetesinde yayınlanmıştır.

-------------------------------------------------', 'KINALI KUZUM   Yıl 1915, aylardan Ocak. Yer Çanakkale. Denizde sayısız İngiliz ve Fransız filosu, karşıda İtilaf Devletlerinin, bir ulusu ta...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kinali-kuzum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Gözü Görmüş', 'askin-gozu-gormus-mehmet-dogan-8-odav9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nice nice sevgiler sevgililer 

Aşkın gözü görmüş 

Dudagı yokmuş 

Birileri öpmüş sömürmüş 

Hiç kalmamış

Kalbi dar kıskanç

Sömürgenin gözü kör müydü ki

Bugünü hiç düşünememiş

Haydi gözünüz aydın

Öpmesek koklamasak da

Gönülden gözden ırak

Aşk sevgi hep varmış...', 'Nice nice sevgiler sevgililer  Aşkın gözü görmüş  Dudagı yokmuş  Birileri öpmüş sömürmüş  Hiç kalmamış Kalbi dar kıskanç Sömürgenin gözü kör...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 8']::text[], 8.5, '{"poet":"Mehmet Doğan 8","poet_slug":"mehmet-dogan-8","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askin-gozu-gormus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Suyunun Has Yatağı', 'can-suyunun-has-yatagi-salih-erdem-fkg7z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tek damara süzülürken yağımız

Ölümüz bir neden ayrı sağımız

Belleğine sağlam nat mı sayarsın

Kin dolgulu düşünceden dağımız

Göğümüz bir yerimiz bir yerinme

Aç gönlünü kur otağın erinme

Varlığına teminat mı koyarsın

Mala mülke sırtın verip gerinme

Tutam tutam ömrü biçen bir orak

İbret olsun ağaçlarda her yaprak

Gözlerine kör inat mı yayarsın

Can suyunun has yatağı bu toprak

Her ne kadar çıksan göğün katına

Sonun yerdir girer kabir hattına

Vuslatında gül onat mı giyersin

Çeyizin düz dünya ahret zâtına

Erdemoğlu sarıl kardeş kol kola

Çaput kader benliğini sar çula

Mahşerinde minnet kat mı ayarsın

Yaradanım suret vermiş her kula

03.02.2006 10:14 AYDIN', 'Tek damara süzülürken yağımız Ölümüz bir neden ayrı sağımız Belleğine sağlam nat mı sayarsın Kin dolgulu düşünceden dağımız Göğümüz bir yeri...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/can-suyunun-has-yatagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığından Ak''tı Onlar', 'ay-isigindan-ak-ti-onlar-durmus-kaya-vjbvz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülden bir mahşerdi bakışları,

Isıtırdı  kara kışları! ...

Onlar ki, bu topraklara

Elli milyon şehit vermişlerdi! ...

Bu milletin karanlık gecelerine

Dolunay olup ışımışlar	

En azgın sulara 

Canlarını germişlerdi! ...

Onlar ki, bu toprağın

Yanık yürekleriydiler

Nazik sahillerin sularını

Tanımazdı ayakları! …

Cam kırığı döşeli 

Yolları yürüyüp gelmişlerdi

Geçtikleri  yerlere

Gönüllerini bürüyüp gelmişlerdi! …

Onlar ki, Anadolu bozkırından

Kaşkar’a uzanan ovaların

Nazlı çiçekleriydiler! …

Gün oldu yanardağları

Söndürdüler göğüslerinde

Gün geldi kuşanıp bayrakları

Kanlı gömlek  giydiler! …

Onlar ki, bu vatan için 

Peygamber ocağına

Hira bakışlı

Tanrı Dağı duruşlu

Yiğitler doğurmuşlardı! 

Senin aklının eremediği yerlerde

Sarı çiçekti, 

Akçabardak’tı onlar,

Ne kadar toza çamura bölense de

Ay ışığından ak''tı onlar! ...

Onlar ki, Fatih’lerin

Selim’lerin anasıydılar! …

Bir büyük sevda uğruna

Bala canlar salıp gaza meydanlarına

Şanlarını yeryüzüne yaydılar! ...

Gidip de dönmeyen akıncılarını

Kaderden saydılar! ...

Onlar ki, güzele gül bakışlı,

Soluğu cennet kokuşlu

Bir sevdalı iklimdi! ...

Ve..

Bir sevdalı kilimdi

Nakış nakış dokudukları,

Yunus’tandı yazdıkları

Elif ‘tendi  okudukları…

Ay ayça’ydılar! …

Dolunaydılar! …

Senin duymadığın sesleri duyardı kulakları

Kulaklarından keskin yürekleri  vardı

Fatma Ana’ydılar,

Güllü Bacı''ydılar,

Nene Hatun’dular! …

Meraga göklerinden

Meriç’e Tuna’ya kadar

Menekşe seli çağlayan

Bütün ırmakları

Gözlerinden taşırdılar! 

Ne bir gün yumdular gözlerini,

Ne bir an şaşırdılar! 

Onlar ki,

Aslı gibi

Şirin gibi

Leyla’dandılar

Bayrakları bayrak yapan

Kandılar! ...

Onlar ki, yaratılıştan

Öksüz, yetim ve

Mahzundular! …

Cehennemi yangınlardan alıp 

Bu toprakları

Sana emanet  sundular! ...

yitikozan...', 'Gülden bir mahşerdi bakışları, Isıtırdı  kara kışları! ... Onlar ki, bu topraklara Elli milyon şehit vermişlerdi! ... Bu milletin karanlık g...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/ay-isigindan-ak-ti-onlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yılın İlk İlanı! ....', 'yeni-yilin-i-lk-i-lani-kadir-albayrak-ldhum', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk günü bu gün

İlk doğan güneş, ilk tebessüm

Bu gün 1 Ocak 2006

Bir defteri kapattım dün

Ve bir sayfa açtım! ...

Dün yok, geçmiş yok,mazi yok! ..

Sevgili yok,aşk yok,acı yok! ..

Hayal yok, hasret yok,vuslat yok! ..

Düne dair hiçbir şey yok! ..

Hepsi “RESET! ..”

……..

Ne alacaklı ne borçlu

Ne yar ne ağyar! ..

Anam babam göç edeli yıllar oldu

Ve intizar,

Miadı doldu! ..

……..

Telefon defterimi sıfırladım bu gün

Traş oldum sabah erkenden

O kadar mutluydum ki; 

Tüm anılarımı,

Akşamdan hazırladığım,

Mezara gömerken! ....

……..

İlan ediyorum; 

Bu gün doğum günüm benim

Hiç birinizi tanımıyorum! ..

Hafızam boş, bellek sıfır

Nefes almaya yeni başladım

Ve kaydediyorum! ...

……..

Dün sevdiğim vardı belki

Canı cehenneme

Sevmiyorum! ....

Ne dememişsem aşka yenilip

Hepsini söylüyorum! ...

Ukde bırakmıyorum içimde

Kusuyorum! ..

Ve içimi de temizliyorum

Tüm dosyalar derdest! ....

Yüreğim ağır gelirdi

O da reset! ....

………

Yabancı yabancı bakacağım artık

Hissetmeden! ..

Bu yıl benim! ..

Yıl gibi ben de yenilendim! 

Kim nerede ise orada kalsın

Uzaksa uzak! ..

Varsın karşılaştıkça gözlerime baksın

Ne var ki ağlayacak? ! ...

………………

Aşkı yeniden öğrenmek var! 

Yaşamak yeniden

Ama bilerek dişlerinin yerini

Engin tecrübelerden! ...

Ne paçam birinin elinde

Ne de göz yaşı ardından birinin

Eskiyi yakıp yeninin ateşinde

Peşine düşmek var daha dirinin! ...

……………

Okusun dost yeren

Bir daha bir daha, ama unutmasın

Ne varsa düne dair

Hepsini çizdim

Kimse kusura bakmasın! ..

“Vefa” boza-nın adıymış

İçtim gitti! ...

Hal, hatır, sohbet, muhabbet

“Has-seki Cerrahpaşa! ....”

Külahıma anlat! .. 

Daha yeni başladım

Daha neler var 

Gün görmemiş, 

El değmemiş! ....

Muhteşem, süper,nadir

Ben mi? ? ? ? ? 

“2006 Kadir! ...”', 'İlk günü bu gün İlk doğan güneş, ilk tebessüm Bu gün 1 Ocak 2006 Bir defteri kapattım dün Ve bir sayfa açtım! ... Dün yok, geçmiş yok,mazi y...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/yeni-yilin-ilk-ilani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim demiş gökyüzünde balık yok diye', 'kim-demis-gokyuzunde-balik-yok-diye-kadir-yasan-xhxa9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kim demiş gökyüzünde balık yok diye

dün akşam ben tuttum işte

hem de sürülerle vardı

durmadan olta attım

sazan kadife alabalık

hepsinden tutum

sabah kalktığımda gördüm ki

sular içinde yüzüyor yatak yorgan döşek

bende yüzüyordum kulaç kulaç

kıyılara yakın

şişme simidimle

kenar yastığındaki iğne batmış tenime

son tutuğum torikten çıkmıyordu misine

ben ise don gömlek kaçtım evden

meğerse sular idaresi 

kesmiş suyu

ben uykudayken açmış suyu

çok balık tuttum sabaha kadar 

inanın yıldızlar şahit

annem kan ter içinde olsada!', 'kim demiş gökyüzünde balık yok diye dün akşam ben tuttum işte hem de sürülerle vardı durmadan olta attım sazan kadife alabalık hepsinden tut...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yasan']::text[], 8.5, '{"poet":"Kadir Yasan","poet_slug":"kadir-yasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kim-demis-gokyuzunde-balik-yok-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neslihan', 'neslihan-tugba-simsek-a1h4f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nadide bebegim, biricik varligim olur musun benim? 

Evlenip benimle basimin taci olur musun benim? 

Seni oyle seviyorum ki, daima senin olmak istiyorum senin

Laleler getiririm her aksam kucagina senin

Inan bebegim, su kalbim, askim gorduya seni

Hanceri de vursam kalbime, genede gorurum seni

Askindan cildiriyorum, gel inat etme sev beni

Ne olursun sonsuza dek kollarina al beni

13.02.2006  21.03

(antoloji de bana yardimci olan neslihan osmanoglu na...)', 'Nadide bebegim, biricik varligim olur musun benim?  Evlenip benimle basimin taci olur musun benim?  Seni oyle seviyorum ki, daima senin olma...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/neslihan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ondört şubat', 'ondort-subat-i-brahim-kilinc-1uvev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün hiç içimden yazmak gelmiyor

Ondört Şubat beni mahzun eyledi

Gönlümü vermiyor gönül vermiyor

Ondört Şubat beni mahzun eyledi

Ellerim bir türlü kalem tutmuyor

Seslensem boşuna, sesim gitmiyor

Terk edip gitmeye gücüm yetmiyor

Ondört Şubat beni mahzun eyledi

Aşk elinde garip, bîçâre bir kul

Yâre ulaşmayan bîçâre bir gül

Yine sensiz geçen bîçâre bir yıl

Ondört Şubat beni mahzun eyledii

Kendi gelmez, hayali hiç terk etmez

Gözünün önünde olsam fark etmez

Yine gönül bu sevdayı terk etmez

Ondört Şubat beni mahzun eyledi', 'Bugün hiç içimden yazmak gelmiyor Ondört Şubat beni mahzun eyledi Gönlümü vermiyor gönül vermiyor Ondört Şubat beni mahzun eyledi Ellerim bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ondort-subat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer(!) günü! ...', 'sevgililer-gunu-kadir-albayrak-k2f14', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün “o gün’müş”

Sevenlerin sevişenlerin günü

Hatırlayanların hatta hatıraların

Ufak, ufacıkta olsa

Kül altında ki kıpırtıların

Sönmemiş ateşin

Batmayan güneşin

Ne varsa sevdadan

Ne varsa sevgiden yana

Bilenlerinmiş bu gün! ..

Bu gün “o gün’müş” sevdiğim

Sevenlerin sevişenlerin

Lakin “benden başka”

“Senden başka” herkesin! ...

…………….

Asırlara sığdıramadım

Ve sığmadı asırlar bir güne

Yıl da bir kez gelirmiş bu gün

Sen “Hatırlamadın bile”

Üstelik; 

Seni hep düşündüğümü

Bile bile! ...

Öyle ya; 

Sevenlerinse bu gün

Hatta sevişenlerinse

Sana ne! .... Bana ne! ...

Bu gün “o gün’müş” sevdiğim

Sevenlerin sevişenlerin

Lakin; 

Benden başka

Senden başka

Herkesin! ......', 'Bu gün “o gün’müş” Sevenlerin sevişenlerin günü Hatırlayanların hatta hatıraların Ufak, ufacıkta olsa Kül altında ki kıpırtıların Sönmemiş a...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevgililer-gunu-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa Dair', 'ayriliga-dair-birsen-ates-r9ot5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen benim aşkım

yaşanmamış yarımdın

acılarımdın içimden dökülen 

özlemlerimdin 

tutunduğum kirpiklerinden

ağır ağır düştüğüm

oysa

ilk gün düşmüştü yüreğime

gidişinin acısı

inadına direndim sessizce

hüzün olup döküldün 

gözlerimden 

yine de ağlayamadım

öyle sevmiştim ki

yüreğimde hala izlerin 

birde senden arta kalan

yokluğunda hüzünlü şiirlerim

  14.02.06', 'sen benim aşkım yaşanmamış yarımdın acılarımdın içimden dökülen  özlemlerimdin  tutunduğum kirpiklerinden ağır ağır düştüğüm oysa ilk gün dü...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayriliga-dair-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilisini Arayan Gül', 'sevgilisini-arayan-gul-kamber-bal-xuv85', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tan vakti ile başlar çırpınışları

Berhüdara koşan kıratların telaşında

Yelelerinde sevenlerin, sevgililerin selamı

Oysa boynu bükük kaldı, bendeki gülün soldu yaprakları

Erişilmesi imkansız dağlar gibiydi gençliğinde

Ürkerek doğardı doruğunda güneş, zemheri karı gibi 

aklar düşmezden önce başıma, başımda eserdi sadece

hey hey yelleri, kesilmeden ayakları elleri

bu beden kuru bir ağaç gibi yıkıldı yerlere omuzlarında ağırlığı

sevgilisini arayan sahipsiz güllerin hasret yüküyle

Sevgilisini arayan güllerin hasret yorgunluğu vurdu 

yıllardan daha vurgundu, ömürden öte yorgundu

Bahama''larda kaybolan göznurumun 

küllenmek bilmeyen özlemi

iki damla yaşla da  olsa çaresiz arattı bu gözleri

Kim bilir çıkıp gelecektir,güllerin kokusunu duyunca kanatlarında kuşların

eteklerinde sakladığı,avucunda büyüttüğü, suretimle çürüttüğü düşlerin

Ah bir hatırı varsa eğer, çıkıp gekelcektir

mutlaka çıkıp gelecektir

gelecektir ağalatmamak için elimdeki sevgilisini bekleyen gülleri

Ah bir gelse, gelse diyorum ya

Yoksa vurup başımı aya yıldızları döksem mi eteklerine

bağışlasam ömrümü gizlenen güllerin yapraklarındaki kelebeklere

solmazdı soldu, avuçlarımda sakladığım, göz yaşımla suladığım

sevgilisini bekleyen güller,alın sizin olsun gülsüz sevgili bekleyenler

sizin olsun acınız Bal olsun-Sevgililer gününüz kutlu olsun-', 'Tan vakti ile başlar çırpınışları Berhüdara koşan kıratların telaşında Yelelerinde sevenlerin, sevgililerin selamı Oysa boynu bükük kaldı, b...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgilisini-arayan-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-asima-azra-35jxm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayağımı frenden ne zaman çeksem

kalbim park halinde hayatlara çarptı

çünkü seni sevmek…

geri viteste sürmek gibiydi aşkı

sinyalimi vermeden dönüşler yapmak

ve dikiz aynasından yüzüne bakmak

seni sevmek...

yiğitlikti buzlanmış yokuşa karşı…', 'Ayağımı frenden ne zaman çeksem kalbim park halinde hayatlara çarptı çünkü seni sevmek… geri viteste sürmek gibiydi aşkı sinyalimi vermeden ...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-sevmek-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-durdane-demirkoparan-ucqob', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece

Sensizliğe içiyorum

Lanet ediyorum 

Senli sensiz  her güne

Yastığıma sarılıyorum 

Gözlerimi dikiyorum

Bakıyorum boşluğa

Her yerde 

Seni görüyorum

Yıkılmışlığım,

Ve acım

Tavana vuruyor

Arka planda bir şarkı

Yalanmış diyor

Acıma acı katıyor

Bu acı 

Ne sensizliğe

Ne olmayan sevgine

Bu acı kalleşliğine

Namertliğine

Kısacık zamanda

Dokunmana başka ellere

Nasıl bu kadar acımasız

Nasıl bu kadar duygusuz oldun

İnanmazdım deselerdi

Konduramazdım

Bilmezdim ki,

Böyle yakacağını

Üzerken mutlu olacağını

Bu gece 

Sensizliğe içiyorum

Yanımda olmayışına değil

İnan

Kalleşliğine

Namertliğine…

Devam et yaşamaya

İnsanım diye….

14.02.2006', 'Bu gece Sensizliğe içiyorum Lanet ediyorum  Senli sensiz  her güne Yastığıma sarılıyorum  Gözlerimi dikiyorum Bakıyorum boşluğa Her yerde  S...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bu-gece-189-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtar Rabbim', 'kurtar-rabbim-suleyman-yavuz-s45la', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buralardan sıkıldım bilmem niye

Gitmek istiyorum ama olmuyor

Bir şeyler var beni bağlayan

Nedir bilinmez ama olmuyor

Geçirdiğim her günüm uzun 

Her günüm hüzün

Gecem uzun günüm uzun

Sende yoksun ya 

Olmuyor gönül gözüm

Gitmek istiyor bedenim deki her parça

Yüreğim bırakmıyor beni belli

Çünkü sen vardın burada bir tek sen

Onunla

Gitmek gitmek 

Gidipte yüreğini bırakmak

Ne zor Allahım her gün 

Ağlayıp onu aramak

Yanıp ta kül olmak ne zor

Ayrıldığımıza inanmak ne zor

Onu vermiyorsun bari ya’ rab

Al gitsin şu aciz canımıda

Kurtulayım, kurtar beni 

Budur kulunun sen den son dileği', 'Buralardan sıkıldım bilmem niye Gitmek istiyorum ama olmuyor Bir şeyler var beni bağlayan Nedir bilinmez ama olmuyor Geçirdiğim her günüm uz...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kurtar-rabbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
