INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asansör', 'asansor-reyhan-tataroglu-c8u94', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zemin de bir kat

                             terasta bir kat

                             aradaki farktır 

                             hakikat', 'zemin de bir kat                              terasta bir kat                              aradaki farktır                               hak...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asansor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakılacak Mektuplar 15', 'yakilacak-mektuplar-15-mehmet-tas-das43', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günleri günlere ekledim yine.Sığındım takvimlerin merhametine...Saat vefasız,gün vefasız..Çarmıha gerer her geçen gün gönlümü..Geceler uzadıkça uzar,günler geçmek bilmez...Uzar geleceğin saatler.Postacının yollarını gözleyen müebbet mahkum çaresizliğinde yetim duygular dolar benliğime...Sensizliği solumak kalır geriye.

	Bilirim çaresizsin,bilirim sen de ben kadar öksüzsün saatlerin hoyratlığında.Nasıl sensizliği solumak zehir solumak kadar ağır geliyorsa bana,sen de her nefeste boğulacak gibi oluyorsun.Bunu bilmek için illa da falcı olmam gerekmez ki..Çünkü ben sen olmuşum,sen de ben...

            Bir telefon zilinin ardında aramak umudu...Bir postacının ağır ağır yürüyüşünde...Bir rüzgarın serinliğinde,ya da yağışında yağmurların...Senden haber getirir umuduyla kuşları beklemek açılan pencerelerin önünde. Bazen kararan bulutlara takılıp  ufukların ötelerinde bir yerlere koşmak..Bir gül olup açmak için sevgilinin koynunda...

	Umutsuzluğun koynunda uyuyorum...Hayallerimin en can alıcı yerlerinde sen oluyorsun...Rüyalarımın en tatlı yerlerinde yine sen.Her doğan güne senle merhaba diyor,senle uğurluyorum batan güneşi...Yıldızlarda gözlerini arıyorum...Sabahların geç olduğu gecelerde beni düşünüyor musun? Uykunun gelmediği yerde sen dolduruyorsun bütün benliğimi,sıcaklığını taşıyorum içimde...Sen...Sen bensiz gecelerde üşüyor musun.? 

Bütün şarkılarda seni dinliyor insanlar...Herkesin dudağında türküsün...Bir ben anlıyorum ne kadar hasret yüklü olduğunu nağmelerin.’’Geceyi sana yazdım’’biliyor musun? 

Beni anlıyor musun?', 'Günleri günlere ekledim yine.Sığındım takvimlerin merhametine...Saat vefasız,gün vefasız..Çarmıha gerer her geçen gün gönlümü..Geceler uzadı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yakilacak-mektuplar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitiş', 'bitis-nihal-cinar-r9g1d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne ilgi,ne sevgi,ne şevkat

Zerresini görmediğim aşk

Beklemiyorum artık

Tüm umutları tükettim

Kalmadı ihtiyaç

Bünyenizdeki siğil olmaktan sıkıldım

Koparıp atsanız kurtulursunuz

Sevimsiz varlığımdan

Bana da hediyeniz olur

Asalak yaşımımdan kaybolmam.', 'Ne ilgi,ne sevgi,ne şevkat Zerresini görmediğim aşk Beklemiyorum artık Tüm umutları tükettim Kalmadı ihtiyaç Bünyenizdeki siğil olmaktan sık...', ARRAY['Türk Edebiyatı','Şiir','Nihal Çınar']::text[], 8.5, '{"poet":"Nihal Çınar","poet_slug":"nihal-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bitis-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamı Böyle korkuturlar İşte', 'adami-boyle-korkuturlar-i-ste-eyup-selahattin-dalkiran-9bf4v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çıktı dediki 

Bağır bağır bağırarak

Hakkımı istiyorum hakkımı

Hadi ulan oradan dendi

ananı alda git.

Adam gitti

Tekmeler yedi

yumruklar yedi

Vücudu yarabere

Boy boy resimler

Gazetelere manşet.

Sonra utanmadan çıkmış

Ananı alda git  diyen kişi haklı

Ben bilmeyerek yanlış yaklaştım

Tabii ya çiftçiye bir parmak bal

hani reklamlarda

Bal parmak der gibi

Adamı böyle korkuturlar işte.', 'Çıktı dediki  Bağır bağır bağırarak Hakkımı istiyorum hakkımı Hadi ulan oradan dendi ananı alda git. Adam gitti Tekmeler yedi yumruklar yedi...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/adami-boyle-korkuturlar-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun Örsü', 'yoklugun-orsu-muhammed-mehmet-gul-7lcrw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçmeden esridim her köşede sızdım

Ruhumu çatlamış aynalardan süzdüm

Sırtımda hep onulmaz dert ile gezdim

***Derman derman diyerek süründüm bazen

Dumanı tütmeyen küllenmiş közdüm

Yokluk denen örste varlığımı ezdim

Beni bağlayan tüm düğümleri çözdüm

***Çırılçıplak ruhuma büründüm bazen

Anlamsız rüyalara tabirler düzdüm

Bakmadan kendi kendini gören gözdüm

Varlık denen derimi üzerimden yüzdüm

***Gölge gibi düş gibi göründüm bazen', 'İçmeden esridim her köşede sızdım Ruhumu çatlamış aynalardan süzdüm Sırtımda hep onulmaz dert ile gezdim ***Derman derman diyerek süründüm b...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoklugun-orsu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmuyor', 'sensiz-olmuyor-birsen-ates-ev19a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yokluğun da

asılı kaldı özlemlerim

dudaklarımdan dökülüyor

ağlıyor kalemim

zorladım sınırlarımı 

denedim kaç kez

anladım sensiz olmuyor

kupkuru topraklar gibiyim

sevgi yağmurlarına hasret

yağ üzerime ıslanayım

damla damla

içimde biriken özlemimle

s 

    ü

          r 

              ü 

                    k 

                          l 

                               e 

                                     n 

                                          d

                                                i

                                                    m sana doğru

denedim

sensiz olmuyor

    14.02.06', 'yokluğun da asılı kaldı özlemlerim dudaklarımdan dökülüyor ağlıyor kalemim zorladım sınırlarımı  denedim kaç kez anladım sensiz olmuyor kupk...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensiz-olmuyor-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş', 'akrostis-aysenur-yazici-zeob5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Esas Kız.

Yıl: 2000

Başrol Oyuncuları: Esas Kız & Esas Oğlan

İlişkinin süresi: 2 yıl

Erkeğin son repliği: Seni hala çok seviyorum. Sadece biraz kafam 

karışık. 

Aile, işteki sorunlar vs. vs. Sana hak ettiğin ilgiyi yeterince 

gösteremediğimin farkındayım. Lütfen bana biraz zaman ver.

Esas kız esas oğlana istediği zamanı verir.

Yıl 2005, esas oğlan hala verilen zamanı değerlendirmektedir.

Yıl: 2005

Başrol Oyuncuları: Farklı bir esas kız ve farklı bir esas oğlan

İlişkinin süresi: 2 hafta

Erkeğin son repliği: Senden çok hoşlanıyorum ama sana hak ettiğin 

ilgiyi yeterince gösteremediğimin farkındayım. Aile, işteki sorunlar vs. vs. 

Bana biraz zaman verebilir misin? 

Esas kız esas oğlana istediği zamanı vermez tabi. Takar sepeti koluna, 

gider yoluna.:(

Bilir çünkü aslında esas oğlan zaman istememektedir, gitmek 

istemektedir.

Bu repliklerdeki ilk esas kızla ikinci esas kız arasında hiçbir kan 

bağı, ortak payda ya da kültürel benzerlik yok. Hayattaki tek ortak 

noktaları, yıllardır kapalı gişe oynadıkları bu senaryodaki ''esas kız'' karakteri.

İlişkinin detayları, zamanı, duyguların yoğunluğu ne olursa olsun 

hepimizin hayatta en az bir kez sahne aldığı bir oyundur bu. Esas oğlan bir türlü repliğini ''seni artık sevemiyorum'' ile değiştiremez. Bir zamanlar 

sevdiği ve hala kendisini seven esas kız için üzülür çünkü.

Esas kıza gelince; o da bir türlü karar veremez hangisini tercih 

ettiğine. ''seni artık sevemiyorum'' repliğini duymak mıdır zor olan, yoksa, ''biraz zaman'' isteyen esas oğlana, bir ömüre yayacağını bile bile bu zamanı vermek mi? 

Ne senarist, ne üçüncü şahıslar ne esas oğlan ne de ben biliyorum bu 

sorunun cevabını. Tek bildiğim, esas oğlanın çantasını alıp arkasına bakmadan gittiği, esas kızın ise dürüst olmadığı için yıllar boyu esas oğlanı 

suçladığıdır.

sevgililer gününde kendi kendilerine neden yalnız olduğunu soranlara  ağlamamaları için anlatılmıştır.....', 'Esas Kız. Yıl: 2000 Başrol Oyuncuları: Esas Kız & Esas Oğlan İlişkinin süresi: 2 yıl Erkeğin son repliği: Seni hala çok seviyorum. Sadece bi...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/akrostis-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nikâhları Kıyılan İnsanlar', 'nik-hlari-kiyilan-i-nsanlar-timur-i-likan-j5s1o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her yıl kıyılıyor binlerce insana

şâhitler huzurundaki nikâh

kıyma merâsimlerinde farkında

olunmayarak an be an

Yapılan evliliklerin birçoğunun

sağlam atılmadığından temelleri

ilk şiddetli geçimsizlik depreminde

yerle bir oluveriyor çürük inşâ edilen

evlilikler birbiri peşi sıra

(14 Şubat 2006/ İstanbul)', 'Her yıl kıyılıyor binlerce insana şâhitler huzurundaki nikâh kıyma merâsimlerinde farkında olunmayarak an be an Yapılan evliliklerin birçoğu...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nikahlari-kiyilan-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü', 'sevgililer-gunu-mevlut-bicik-bqfop', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ecnebî! sevgililer günü îlân etmiş ondört şubatı

Bunların lugatında sevgi sözcüğü varmıdır acaba? 

Milleti Íslâmı ifsât için elinden geleni yapıyor şu batı

Bunun farkına varanlar çoğalırmı? ne zaman acaba? 

Hayatım; ilk ve son defa olduğun için benim

Nâmûs ve hayâtının dâima bekcisiyim senin

Hariç’de ve dâhil’de oluyorum senden emin

Bir gün değil sâdece! Her gün seviyorum seni.

Sen benim canım yavrularıma oldun ana

Onları büyüttün,terbiye ettin bırakmadın bana

Íltifâtın,ikrâmın,sevginin engüzeli lâyıktır sana

Bir gün değil sâdece! Her gün seviyorum seni.

Sıkıntılı günümde bilirsin! evim geliyordu dar

Sen ise tebessümünle,sevginle bana oluyordun yar

Sende ki kâlb o kadar güzel ki sanki bembeyaz kar

Bir gün değil sâdece! Her gün seviyorum seni.

Her zaman ve her yerde benim ayıplarımı örttün

Bir yanlış yapacağımı anladığında hemen beni dürttün

Yokluk zamanımızda bile mutfağı, tarhana ile yürüttün

Bir gün değil sâdece! Her gün seviyorum seni.

Senin özellik ve güzelliklerini bu kalem sayamaz

Senden başkasına bu gönül kaymadı zâtende kayamaz

Seninle geçen hayâta doymadı, dahada doyamaz

Bir gün değil sâdece! Her gün seviyorum seni.

Mevlüt Bicik

14.02.2006   saat 21.54

Esslingen', 'Ecnebî! sevgililer günü îlân etmiş ondört şubatı Bunların lugatında sevgi sözcüğü varmıdır acaba?  Milleti Íslâmı ifsât için elinden geleni ...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevgililer-gunu-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Nerede', 'ask-nerede-atilla-guler-brmpx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğime vuran kambur oldu sensizlik 

kahpeliğini ruhuma vurmuş aşk

kırılgan bir ışık yüreğimin sokaklarında

göz gözü görmüyor

odamı dolduran melodide inleyen şarkıcı

haykırıyor yakarışını ağlamaklı

*“aman aman yandım aman

kurşun gibi izler

son bakıştaki o gözler

kaldı aklımızda”

boynu bükük bir gül masadaki vazoda

yüreğimden damlayan kanın rengi yapraklarında

kadehimde oynaşan kırmızı şarabın sarhoşluğu

dansı damağımda bir başıma

her yangın yerinde kalan küllerde

yeniden doğan lanet olası bir soğuk bu…lanet olası bir boşluk

ıslak gözlerin buğusuyla göremediği yüzler

…hayat ıssız/yorgun/yürek yangınlarda

masallarda anlatılan bir büyü

şarkılarda bir iki dize

aşk

…nerede? 

*Son Bakış-Sezen Aksu', 'yüreğime vuran kambur oldu sensizlik  kahpeliğini ruhuma vurmuş aşk kırılgan bir ışık yüreğimin sokaklarında göz gözü görmüyor odamı doldura...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-nerede-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-mehmet-pamuk-rk6d8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yıldızlar yanar önce,

avuçlarımda

kalemler tutuşur

sönmüş volkanlardan daha güçlüdür

bir yangının ortasında

kordur geceler..

bir talan başlar

ve haramiler keser

yüreğin yollarını

düne ait ne kadar haraç varsa

alır kendini benden

zordur geceler..

bir mahkumun özlemi gibi

demirin ayazına yapışır

uykusuz gözkapaklarım

vücudum yorgun

koşar durursun hayallerde

öyleyse

yor beni geceler...

bir iblis uyanır,günahların kenarından

elini tutar dost gibi

bir anlık gaflet

ağzının içinde ekşi tatlar bırakır

o tatlı kemiksiz nefret

her hesabı kendine vereceksin elbet

öyleyse,

sor beni geceler...

güllerden söküp alırsın

kan kırmızı dönülmezlikleri

tek tek

papatya beyazları saçarsın karanlığa

umut diye,kopartır atarsın

sarı bir ölüm yapışır

yüzündeki çizgiye

ve mavilerce denizi özlersin

oysa,

mordur geceler..

dur artık deli gönlüm dur

yazılmaz şiirlerin içinde

kulağımda,

duyulmaz şarkıların hüznüyle

şeritsiz yollar gibisin hayat

şimdi bir yıldız şavkır

göğün göğsünde

kurşun gibi deşer yalnızlığı

öyleyse,

vur beni geceler...', 'yıldızlar yanar önce, avuçlarımda kalemler tutuşur sönmüş volkanlardan daha güçlüdür bir yangının ortasında kordur geceler.. bir talan başla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Pamuk']::text[], 8.5, '{"poet":"Mehmet Pamuk","poet_slug":"mehmet-pamuk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/geceler-142-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
