INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliden Sevgiliye…', 'sevgiliden-sevgiliye-zulfikar-yapar-kaleli-xpng0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aradığın bensem sendeyim elbet

Ben seni atmadım, gel sen de atma

Hayalin başında tutarım nöbet

Hayalime sarıl yorganla yatma

Günlerin güzeli seninle olsun

Ne işin var senin on dört şubatla 

Bağrında gül açsın, karanfil dolsun

Gözün gül mü olur, üstünden atla 

Çocuk büyümez mi, insan düşmez mi? 

Sevginin göğsünde uyurken düşte

Tabibin kötüsü çıban deşmez mi?

Her taraf uyanık baksana işte

Bir türlü bitmiyor bendeki sancı

Kızılca kıyamet koptu kopuyor

Bugün benim değil, bana yabancı

Baharlar tuvalsiz resim yapıyor.

Çatlayan başımı göğsüne yasla

Gül kokun duygumu okşayadursun

Öpmenle okşaman kandırmaz asla

Yüreğim yeter ki sinende vursun.

Arzu ikliminde terlere batma

Hayal aynasına bakılıyım ben.

Beni el alemle tartma, bir tutma

Otuz yıl evvele takılıyım ben.', 'Aradığın bensem sendeyim elbet Ben seni atmadım, gel sen de atma Hayalin başında tutarım nöbet Hayalime sarıl yorganla yatma Günlerin güzeli...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgiliden-sevgiliye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınırsız...', 'sinirsiz-reyhan-tataroglu-wvcwq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili...

                                ne dün

                                ne bugün

                                ne yarın

                                nede ertesi gün

                                seni sevmek 

                                her gün...

                                bir başka düğün', 'Sevgili...                                 ne dün                                 ne bugün                                 ne yarın         ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sinirsiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşler besliyorum', 'atesler-besliyorum-elazigli-mustafa-kaya-ruwci', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'buz  taşıyan dağlar gibi

duygularım.

acı ve öfkelerle yaşıyorum

bu şehirde.

düğümler içindeyim.

düşüncemin korkuları

sığmaz sahillere.

paramparça,

yalnızlığımı aksettiren ayna.

acıların ortasındayım

bir anka kuşu yuvası

kavuşamadığım 

aşk  sancıları.

uykularım kaçıyor

denizler aşıyorum

şehirlere sığamıyorum.

beynimde,

ateşler besliyorum.

martılara takılıp gidiyor

aklım,

dudakları ağlayan

sevgilime …

Mustafa kaya

14.02.2006 / ÜSKÜDAR', 'buz  taşıyan dağlar gibi duygularım. acı ve öfkelerle yaşıyorum bu şehirde. düğümler içindeyim. düşüncemin korkuları sığmaz sahillere. param...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/atesler-besliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlar mısın?', 'aglar-misin-cahit-pehlivan-zh0ke', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çiğdem olsan çiçeğe dursan,

Açıp güzel renginle, baharı duyursan,

Hayran olup sana, seni dalından koparsam,

İçin yaralanıp, arkamdan ağlar mısın? 

Tarumar eder misin? Gönlümü de o zaman,

Pek öfkeli görünürsün sen çiğdemim,

Elime, goncanı koparıp alırsam,

Hemen oracıkta kahrından solarmışsın sen,

Lütufkâr davranıp, affetmezmişsin,

İçim parçalandı, senden bunları duyunca,

Vallahi çiğdemim, yüreğim dayanmadı eridi,

Ağlamışsın sen çiğdemim. Sana kim ne etti? 

Ne olur söyle çiğdemim, bizi kim ayırmak istedi? 

Ankara', 'Çiğdem olsan çiçeğe dursan, Açıp güzel renginle, baharı duyursan, Hayran olup sana, seni dalından koparsam, İçin yaralanıp, arkamdan ağlar m...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aglar-misin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akça Şehir Akçaabat', 'akca-sehir-akcaabat-nihat-malkoc-dcysi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Secde eder serviler anar da yaratanı

Arınır kasvetinden düşündükçe vatanı

Dile gelir mermerler kurumuş şadırvanda

Gözler ki buğulanır, kırk dökük bir handa

Vatan namus, yurt özlem, bu topraklar akçadır

Pulathane bir tarih, her sayfası pakçadır

Bahçendeki rayiha diriltecek ruhumu

Çekilir her geçen gün aşk denizinin kumu

Sargana cenk meydanı, pusulası cennetin

Bedel oldu toprağa;  kanın, kemiğin, etin

Ayın şavkı sulara değdirir busesini

Gökkubbeden duyarım ceddin kılıç sesini 

Selam dursun şanına onca ecnebi güruh

Sözler nurlu, muştulu; nasıl kanatlanmaz ruh? 

Suretler nurdan halka, yürekleri akçadır

Acıyı, saadeti paylaşması hakçadır

Erguvan kokusunda çılgın yaz akşamların

Nice güzellik saklar ruha dolan baharın

Saçının her telinde efkârım kol geziyor

Hasret kurşundan ağır, düşlerimi eziyor

Göğünde uçan kuşun kursağında yem olsam

Kanayan güller gibi bahçelerinde solsam

Masmavi sularında çırpınır yakamozlar

Buz tutmuş bir ayazda mehtabı okşar rüzgâr

Sevdalıyım, hasretim;  şehir sana vurgunum

Yatağını kaybetmiş sular gibi durgunum

Gözlerim çakırkeyif, efkârıma çeyrek var

Al benden bu sevdayı yetiş ey gül yüzlü yâr

Hayalini kurduğum ebruli düşler sensin

Gamzeli yanaklarda tatlı gülüşler sensin

Ceddimden arta kalan tertemiz bir sayfasın 

Ufka hasret taşıyan gemilerde tayfasın

Sırnaşık, debdebeli; deniz gözlü kadınım

Bahtına gül suyuyla nakşedilmiş adınım

Yaralı ceylan gibi nabzın atar derinden

Rüyama girsen bir gün kalbim oynar yerinden

Adın ebedileşir, asuman eyler niyaz

Karanlığın koynunda gölgen gezer bembeyaz

Duyulur ötelerden eski zaman türküsü

Büyüler gözlerimi endamındaki süsü

Ezan ruhlara ilaç, gül kokuyor avlular

Mübarek akşamlarda göğe yükselir Hû’lar

Kaybolan düşlerimi gölgende arıyorum

Hayatımın filmini geriye sarıyorum

İzbe sokaklarında hicran içime işler

Beni ayakta tutar yarına dair düşler

Ey şehrengiz güzeli, menekşe kokar tenin 

Güzellerin içinde emsalin yoktur senin 

Çatma kara kaşını, gülümse Akçaabat

Maziye gömdük dünü, nerde o günler heyhat! 

İçimde büyüttüğüm gizemli hülya şehir

Hayra tabir ettiğim gördüğüm rüya şehir

Denizde balıklara seccade olur sular

Yer aguşunu açar gökten süzülürken kar

Çeşmelerden dökülür mazinin gözyaşları

Asırlık çınarların göğe değer başları

Bulunmaz mücevhersin, masamdaki biblosun

Yaratanın elinden çıkmış eşsiz tablosun

Sevdan bir tutam hasret, içime akan nehir

Bir anne şefkatiyle kucakla beni şehir!', 'Secde eder serviler anar da yaratanı Arınır kasvetinden düşündükçe vatanı Dile gelir mermerler kurumuş şadırvanda Gözler ki buğulanır, kırk ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/akca-sehir-akcaabat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum abilerim kızacaklar Bana', 'biliyorum-abilerim-kizacaklar-bana-eyup-selahattin-dalkiran-1u1ev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece

Bir hiç kimse gibi

tek başıma kutlayacağım

sevgililer gününü.

Seni düşüneceğim

Denizin,Mahirin,İbrahimin,Ulaşın

Che gueveranın resmine

Bakarak bir şişe şarabımla

Susarak.

Susmak isteyeceğim

Ama içimdeki kurt

kendini parcalayacaktır sana karşı

Sanki sen varmışsın gibi karşımda.

Kim demiş? 

Balıklar bulut içinde yüzer diye

Bence ahmaklık etmiş  bu sözle

Dehşet

Anıların alnımdan,göğsümdem vuruyor

senin evinin camından gelen ışıklar ile

adalar vapurundan inerken.

ama sen bilemedin

sevmek umut ekmektir

Sevmemezliğe karşı.

Halbuki

Sevdamız bir bütün emekti

Öptükçe birbirimizi

Günler geçti

Kimbilir şimdi nerelerdesin? 

Camından yansıyan ışık

Seni göstermiyor ama

olsun

Seni düşüneceğim

Denizin,Mahirin,Ulaşın,İbrahimin

Che Guevaranın resmine bakarak

bir şişe şarabımla.

Biliyorum abilerim kızacaklar bana

kaypak bir burjuva yaftası yapıtıracaklar

Kızsınlar

Ama bildiğim birşey var

İkimizde devrimlerin

birer neferiydik

Geceleri yanan ateş böcekleri gibi

Yıldızlara bakar gülerdik

olsun böyle olsun aşk derdik

İster deli

ister burjuva

ister parçalı kişilik desinler

Bir varız yarınki günlere

Bir ayağımız  çoktan çukura girmişken.

T', 'Bu gece Bir hiç kimse gibi tek başıma kutlayacağım sevgililer gününü. Seni düşüneceğim Denizin,Mahirin,İbrahimin,Ulaşın Che gueveranın resmi...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/biliyorum-abilerim-kizacaklar-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teklemeden', 'teklemeden-reyhan-tataroglu-d5t6z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana tek diyeceğim; 

                         tek...

                         bir de

                         teksin', 'Sana tek diyeceğim;                           tek...                          bir de                          teksin...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/teklemeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum', 'agliyorum-cahit-pehlivan-2177h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin için sevgilim,

Ben deli divaneyim.

Senin aşkının esiri miyim? 

Bilemiyorum inan sevgilim.

Ben daima seni arıyorum.

Yalnız senin için ağlıyorum.

İçerim sana yanıyor. Biliyorum.

Yalnız senin için yarelerim kanıyor.

Sen benim damarlarımda ki kansın.

Sen olmasan, ben yaşayamam ki.

Yalnız seninim, sen çabamsın, uğraşımsın.

Sensiz geçen zamanlar beni susturamıyor ki.

Seni yine canı gönülden seviyorum.

Hep seni anıp ağlıyorum.

Benim olman içinde Tanrı''ya yalvarıyorum.

İnan ki sevgilim, seni çok seviyorum.

Kalbim durup, ömrüm bitecek yolunda.

Bir kerecik olsun, kolun durmadı kolumda,

Birleşemedik sevgilim seninle hayat yolunda,

Yinede sen istersen, kurban olurum uğruna.

İzmir', 'Senin için sevgilim, Ben deli divaneyim. Senin aşkının esiri miyim?  Bilemiyorum inan sevgilim. Ben daima seni arıyorum. Yalnız senin için a...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/agliyorum-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşerecek Sevgili', 'yeserecek-sevgili-bil-l-ezilmez-63exm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçsuz bucaksız bir bozkır düşünüyorum

Ortasında sen yeşereceksin.

Taze, canlı, bereketli...

Ben de bir sarmaşık olacağım

senin yanıbaşında.

Ben sarıldıkça sana

Sen sevgiler saçacaksın.

Bu bozkırları sen

bir cennet yapacaksın.', 'Uçsuz bucaksız bir bozkır düşünüyorum Ortasında sen yeşereceksin. Taze, canlı, bereketli... Ben de bir sarmaşık olacağım senin yanıbaşında. ...', ARRAY['Türk Edebiyatı','Şiir','Bilâl Ezilmez']::text[], 8.5, '{"poet":"Bilâl Ezilmez","poet_slug":"bil-l-ezilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeserecek-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanmaz', 'utanmaz-reyhan-tataroglu-4wanw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'adına; 

                                     sürüldüğüm her yer

                                     bana cenneti andırır

                                     cehenneme kadar yolun var 

                                     diyenler

                                     kendini utandırır', 'adına;                                       sürüldüğüm her yer                                      bana cenneti andırır                   ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/utanmaz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-bil-l-ezilmez-too2v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Leylak mı gül mü saçındaki belli değil

Bana gönül verdin mi vermedin mi belli değil

Gülüşün bana mı ellere mi hiç belli değil

Sevda mı yoksa saman alevi mi söyle bana? 

Sevdin mi yoksa beğenmedin mi beni? 

Geceleri rüyanda hiç görmedin mi beni? 

Ben deliler gibi sevmişken hep seni

Beni terketmene sebep neydi, söyle bana?', 'Leylak mı gül mü saçındaki belli değil Bana gönül verdin mi vermedin mi belli değil Gülüşün bana mı ellere mi hiç belli değil Sevda mı yoksa...', ARRAY['Türk Edebiyatı','Şiir','Bilâl Ezilmez']::text[], 8.5, '{"poet":"Bilâl Ezilmez","poet_slug":"bil-l-ezilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vefasiz-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
