INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Oldum', 'asik-oldum-cahit-pehlivan-6z99o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni bir sabah gördüm balkonda,

Sana aşık oldum. Sevgilim işte o anda.

Dalgalı duran o siyah saçlarına,

Öpülmekten al al olmuş yanaklarına,

Gergef işlemekten incinmiş ellerine,

Yanık ve içli şarkılar okuyan sesine,

Beni bir bakışla esir alan gözlerine,

Sabahın sensiz esen seher yellerine,

Âşık oldum. Sevgilim, âşığım bende! ...

(Sevgililer günü anısına) 

İzmir', 'Seni bir sabah gördüm balkonda, Sana aşık oldum. Sevgilim işte o anda. Dalgalı duran o siyah saçlarına, Öpülmekten al al olmuş yanaklarına, ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/asik-oldum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir Zakkum', 'zehir-zakkum-nurdan-unsal-sx062', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çakılı kaldım duvarda

gözlerin/izden kaçıyor

koşarken düşürdüm

kendimi yolda

gölgesiz ağaçlarım/

hain çiçeklerim/

niye zehirlisiniz? 

başımda asılı kaldı 

bulutlar kara

her yer kara

dışarda

içerde

hep kara

kapkara

kanlı bir pazar var

darmadağın

eti budu paylaşılmış

kırmızı karıncanın

sızısı yayılmış evrene

taşıyamaz

sırtı ince

artık hep gece

hep gece

zifir zindan gece

ne acıda eridim

ne ölebildim

kaldım öylece

ellerim insan

aşk büyük acıdan

yazıdan geri kalan

artık hep acı

hep acı

zehir zakkum acı.

15.02.2006', 'çakılı kaldım duvarda gözlerin/izden kaçıyor koşarken düşürdüm kendimi yolda gölgesiz ağaçlarım/ hain çiçeklerim/ niye zehirlisiniz?  başımd...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Ünsal']::text[], 8.5, '{"poet":"Nurdan Ünsal","poet_slug":"nurdan-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/zehir-zakkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-bil-l-ezilmez-m2zrj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir; bir nefes almak

Soluklanmak şu dünyada.

Yaşamak duygularla,

mutluluklarla bir arada.

Şiir; aldığın nefesi,

duyduğun bir sesi

işlemek duygularla; 

ve sevmek her şeyi,

sevilmek her şeyce.', 'Şiir; bir nefes almak Soluklanmak şu dünyada. Yaşamak duygularla, mutluluklarla bir arada. Şiir; aldığın nefesi, duyduğun bir sesi işlemek d...', ARRAY['Türk Edebiyatı','Şiir','Bilâl Ezilmez']::text[], 8.5, '{"poet":"Bilâl Ezilmez","poet_slug":"bil-l-ezilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/siir-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah! şamcı', 'ah-samci-reyhan-tataroglu-bodww', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şişeler lıkır lıkır

                                   dibine vur vur kır

                                   bilmem...

                                   bu sarhoş gönlüm 

                                   ne zaman ayıkır', 'şişeler lıkır lıkır                                    dibine vur vur kır                                    bilmem...                      ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ah-samci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert Bohçası', 'dert-bohcasi-nihat-malkoc-42shx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuşlar da göçtü göğümün masmavi sularından

Kanatları kırık, yürekleri buruk; 

Sitemle, bir acı haykırışla

Barut kokan hava, küstürdü kuşlarımı

Yürek coğrafyasını talan etti

Medenî haramiler

Yıldırımlar kapandı arzın kucağına

Bulutlar gece gündüz ağladı ürkekçe 

Yüce dağ başlarına çöktü yalnızlık

Eğilerek toprağı kucakladım erkekçe

Buharlaştı giryeler solgun dudaklarımda

Bir acı öpüş izi var

Sensiz yanaklarımda

Yüreğimden havalanan güvercinler hâlâ dönmedi geri

Yaralanmış serçeler kondu kalbin pervazlarına

Unutulmuş gülüşlerin hayali yeşertir umutları

Parçalanır düşlerim ruhumun kasvetinden

Her biri bir yana dağılır, toplayamam

Kan beynime sıçrar,

İstesem de ağlayamam

Tenin her hücresine bin sitem düşer

Dert bohçası açılır, bağlayamam

Şimdi kelimeler ateşten bir kor

Teni yakar kavurur

Eser acı bir poyraz 

Küllerimi savurur

Taze bir ölü için sunulan hayat öpücüğüdür 

O masum bakışların

Özgürlük kol geziyor

Gölgesinde kılıçların.', 'Kuşlar da göçtü göğümün masmavi sularından Kanatları kırık, yürekleri buruk;  Sitemle, bir acı haykırışla Barut kokan hava, küstürdü kuşları...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dert-bohcasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Empati', 'empati-melih-coskun-wlmr9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.......Hep olmak istediklerinizin yerine koydunuz kendinizi. Güneşli bir günün ılık rüzgarında oltasını büyük bir  keyifle çeken adamın yerine mesela... 

.......Hep güzel yerler vardı düşlerinizde. Sonsuzluğa uzanan yemyeşil bir orman, size dünyanın bütün mavilerinin sahibiymişsiniz gibi hissettiren, dümeninde püronunuzu keyifle içtiğiniz kocaman bir tekne. 

.......Oysa aklınızın ucundan geçmedi bir kere bile beyaz bir poşet içinde çırpınan balığın yerinde olmak

.......Düş ülkenizi kurmak için kendi düşlerini feda eden onca insanın yüzüne bile bakmak gelmedi içinizden ve kuru bir ekmeği çayla ıslatıp yumuşatmadınız sofralarında. 

.......Sahip olduğunuz için mutlu olmanız gereken her şeyden nefret eder oldunuz. Ve sonunda ne sizi seven tek bir kişi kaldı yanınızda, ne de mutlu olacağınız tek bir yer. 

.......Farkına çok geç vardınız o çok ulaşmak istediğiniz hayallerinizin sizinle dalgasını geçtiğinin, ulaştıklarınıza alıştıkça sizi yeni düşlerin beklediğinin ve en kötüsü, yeni hayallerinizin sahip olduklarınızın yüzüne tükürdüğünün...            

.......Gün geldi büyük kahramaların yerine koydunuz kendinizi. Çektikleri hiçbir cefayı aklınıza getirmeden sefasını sürmek istediniz çalıntı asaletlerinizin. Koltuklarınızı kabartarak haykırdınız son sözlerini. Adımlarınızın izini bıraktınız uğuldayan meydanlara. Ama bir kere bile aklınızdan geçmedi ölümü alnınızın tam ortasında hissetmek, yahut kurşunlanan gövdenizde ayak uçlarınızdan yukarılara doğru tırmanan o son sıcaklığı duyabilmek. 

.......Onun için hiçbir zaman bilemediniz ne demek olduğunu karşılıksız sevebilmenin.  

.......Hep olmak istediklerinizin yerine koydunuz kendinizi

.......Ve en kötüsü de kendiniz bile olmayı beceremediniz hiçbir zaman...    

2005', '.......Hep olmak istediklerinizin yerine koydunuz kendinizi. Güneşli bir günün ılık rüzgarında oltasını büyük bir  keyifle çeken adamın yeri...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/empati-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşütük', 'usutuk-reyhan-tataroglu-4f8v5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'anladımki; 

                            kalbimdi kimsesiz

                            üşüyen organım

                            aşkın oldu sarıpta

                            ısıtan yorganım', 'anladımki;                              kalbimdi kimsesiz                             üşüyen organım                             aşkın oldu ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/usutuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bü/yük', 'bu-yuk-reyhan-tataroglu-9rm1w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'baktım saçlarım 

                                 ne kadar ağarmış

                                 taşıyamaz olmuş 

                                 başım...

                                 başım bağarmış', 'baktım saçlarım                                   ne kadar ağarmış                                  taşıyamaz olmuş                         ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bu-yuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Şehir! ..', 'ey-sehir-nihat-malkoc-o0qrl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nice bağrı yanığa el verip kucak açtın

Hayat denen pınarın oluğundan su içtin

Pulathane ne çabuk tarihinden vazgeçtin

Sargana’da akan kan vatan oldu ey şehir! 

Ceddine sırt çevirdin benzin soldu ey şehir

Hilâlin gölgesinde serviler durur ağlar 

Her ayrılık bir ölüm, gönlümüze is bağlar 

İçimdeki yangını üfler, söndürür dağlar

Mecnun’un hicranına tercüman olan şehir

Gözlerimden süzülüp yüreğe dolan şehir

Bir hilâlin uğruna nice güneşler batar

Dönmeyen yolculara gemilerin yas tutar

Ufka çöker bir duman gök mavisini yutar

Canlanır hatıralar gönlümü dağlar şehir

Çekilir kabuğuna hıçkırır, ağlar şehir

Güller açsın yüzünde gülümsesin gözlerin 

Aydınlık yarınları muştuluyor sözlerin

Her dem dik dur ayakta, bükülmesin dizlerin

Düşmana zehir zıkkım, dost bağında gül şehir

Davran bir seher vakti yollara dökül şehir

Dağların eteğine suların şavkı vurur

Tenha sokaklarında nurdan heykeller durur

Maziyi düşününce içimi sarar gurur

Gönül mabedimizde parlar durur ay şehir

Kucaklayıp beni de yürek dostu say şehir

Gelinliğini giyer salınır da bembeyaz 

Üşür sobada alev sabah edince ayaz

Diner bir gün kara kış elbet gelir bahar, yaz

Ürperir sabah vakti yürekçiği ak şehir

Kır bütün zincirleri geleceğe bak şehir

Yalın ayak, baş açık bir serçe kadar hürsün 

Gökteki saltanatın sonsuza kadar sürsün                                                           

Hasretin katmerleşir düşlerimde büyürsün

Yalnızlığımı dindir, ellerimden tut şehir

Bir anne şefkatiyle koynunda uyut şehir', 'Nice bağrı yanığa el verip kucak açtın Hayat denen pınarın oluğundan su içtin Pulathane ne çabuk tarihinden vazgeçtin Sargana’da akan kan va...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ey-sehir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyor Aşk', 'agliyor-ask-birsen-ates-sm3iy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sonsuz bir aşkın koynundayım

yüreğimde yaşıyorum

gidişinle ağlasada 

yolunu kaybetmiş gölgelerim

bunca zamandır

seviyor sevmiyor diye

ağlıyor aşk

kırmızı güllerin gölgesinde

14.02.06', 'sonsuz bir aşkın koynundayım yüreğimde yaşıyorum gidişinle ağlasada  yolunu kaybetmiş gölgelerim bunca zamandır seviyor sevmiyor diye ağlıyo...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/agliyor-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık dediğin..', 'yalnizlik-dedigin-birol-i-scan-ytayi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlık dediğin..(1)

Yalnızlık dediğin iki şeyden ibaret.

 Bir kendim birde şekil değiştiren içki şişeleri..

                                    Yalnızlık dediğin..(2)

Ben  baharda kanı kaynayan bir taydım 

Aşk yarışmaktan bıkmış yarış beygiri.

Ben ne zaman koşmak çoşmak istesem

Yalnızlığım bağırır otur! Yerine…

                            Yalnızlık dediğin..(3)

Sen çok oldun artık yalnızlığım.

Misafir geldin ev sahibi oldun.', 'Yalnızlık dediğin..(1) Yalnızlık dediğin iki şeyden ibaret.  Bir kendim birde şekil değiştiren içki şişeleri..                              ...', ARRAY['Türk Edebiyatı','Şiir','Birol İşcan']::text[], 8.5, '{"poet":"Birol İşcan","poet_slug":"birol-i-scan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizlik-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aysem (Almanca siirim)', 'aysem-almanca-siirim-ayse-alioglu-1b738', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Den Wind in mir fügst du zu  Stilen.

Nur du kannst meine tränen wischen

meinen   Schmerz kannst nur du lindern

Glaube mir du bist  Lebens wert Aysem.

Würdest du sagen, komm hach Ankara.

Dir würde ich die schönsten Rosen geben,

Es wird zeit meine herz in deine Hände zu legen.

Meine Liebe ist schwer kannst du es Tragen Aysem..

Könnten  wir uns im Jugend Park treffen

In zwei samt  keit uns umarmen

Würdest du wollen das  wir mögen

Du bist  ab jetzt meine Schicksal aysem,,,', 'Den Wind in mir fügst du zu  Stilen. Nur du kannst meine tränen wischen meinen   Schmerz kannst nur du lindern Glaube mir du bist  Lebens we...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aysem-almanca-siirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazıra dağ...', 'hazira-dag-reyhan-tataroglu-kc8de', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'satmak kolay

                                almak zor

                                hangisi çok

                                hangisi daha çok

                                kor...', 'satmak kolay                                 almak zor                                 hangisi çok                                 hangisi d...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hazira-dag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışmıyor', 'yakismiyor-ayse-alioglu-gd0sk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yakışmıyor biliyorum, 

Bizlere Yakışmıyor.... 

Duyguları saklamak, 

kendinden kaçmak..... 

Hislere zincir vurmak, 

Arzuları saklamak... 

Duygu yüklü birine, 

Hicte Yakışmıyor... 

Ezelden kalmış, 

Kuytularda gizlenmış... 

Güneş yüzü görmemış 

Yagmur suyu tatmamış.. 

Rüzgardan nasibini almamış. 

Nice sevdalar var... 

Sevdaları saklamak, 

Kuytularda bırakmak.. 

Hislere zincir vurmak 

Hiçte bize Yakışmıyor,.... 

(24.03.04)', 'Yakışmıyor biliyorum,  Bizlere Yakışmıyor....  Duyguları saklamak,  kendinden kaçmak.....  Hislere zincir vurmak,  Arzuları saklamak...  Duy...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yakismiyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya-tı-yo-rum', 'ya-ti-yo-rum-lokman-ali-yavuz-pt26h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ya-tı-yo-rum

Hakkım  var gibi.

Kara Kıta''nın kara gözleri açken,

Ak çocukların sofraları pak''ken.

Ne yüzle yatıp ta batıyorum? 

Görüyorum. 

Görmez mi olsam? 

Söylüyorum. 

Söylemez mi olsam? 



Geldim işte,

Yarın bilmem kaçta gideceğim.

Hiçbir şey değiştiremeden.......

Yazık bana, hem de çook yazık.

Ve ben yatıyorum.

Sahi ben neye yatıyorum?', 'Ya-tı-yo-rum Hakkım  var gibi. Kara Kıta''nın kara gözleri açken, Ak çocukların sofraları pak''ken. Ne yüzle yatıp ta batıyorum?  Görüyorum.  ...', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ya-ti-yo-rum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CENNETTEN Bir Köşe İSTANBUL', 'cennetten-bir-kose-i-stanbul-i-brahim-necati-gunay-71lu3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yerde sararmış bir yaprak görürsen eğer,

İstanbul seyretmeye değer,

Gel ara beni,

Gel İstanbul,

İstanbul canım İstanbul,

İstanbul Mevla dan almış güzelliğini,

Sana borçluyum güzelliğimi,

Ah! Canım İstanbul,

Gel ara beni,

Bul,İstanbul,

Tepelerin var,tane tane,

Geceleri pişer sokaklarında kestane,

Canım İstanbul,

Şarkılarda dolanır dillere,

Bebek ve Aşiyan,

Ne mutludur senin ile iç içe yaşayan,

Canım İstanbul,

Gel ara beni bul,

Etrafında surların var sıra sıra,

Güzeller yakar her köşende bir çıra,

Yerde yeşermiş bir yaprak görürsen eğer,

İstanbul seyretmeye değer,

Bahar gelince bahçelerinde öter bülbüller,

Nerede o canım gibi açan sümbüller,

Gel ara beni,

Bul İstanbul,

Güzel İstanbul,

Can İstanbul,

Canan İstanbul,

Sevgilim.', 'Yerde sararmış bir yaprak görürsen eğer, İstanbul seyretmeye değer, Gel ara beni, Gel İstanbul, İstanbul canım İstanbul, İstanbul Mevla dan ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cennetten-bir-kose-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sevgin Yeter Bana', 'senin-sevgin-yeter-bana-hanifi-isikoglu-e0jpo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklara kacip gitsende

Sen benden nefret etsende

Seni sevmiyorum desende

Ben seviyorum yeter bana

Adimi nefret le ansanda

Bana olmiyacaklari yapsanda

Beni her yerde karalasanda

Seni seviyorum yeter bana', 'Uzaklara kacip gitsende Sen benden nefret etsende Seni sevmiyorum desende Ben seviyorum yeter bana Adimi nefret le ansanda Bana olmiyacaklar...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senin-sevgin-yeter-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neresinde Zamanın? ! ..', 'neresinde-zamanin-kadir-albayrak-sa0nz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine karıştı zaman beyazladı saçların

Yine karıştı rengi kasvet dolu akşamın

Neden böyle vefasız fırtınalı hayatın

Bilmem ki  neresinde yaşıyorsun zamanın

Acılar perde perde kapatmış pencereni

Bir Allah’tır şahidin başka kim duyar seni

Artık hükmü verilmiş bitmeyecek davanın

Bilmem ki neresinde yaşıyorsun zamanın

Gençliğini vermişsin karşılık beklemeden

Terk edip gitmiş seni hesabını vermeden

Görmez misin boş yere heder oldu hayatın

Bilmem ki neresinde yaşıyorsun zamanın

Kaç yıl oldu akşamlar beyazla vedalaştı

Tebessümün ne zaman hıçkırığa karıştı

Anlamadın mı hala içindesin hatanın

Bilmem ki neresinde yaşıyorsun zamanın

Yüzünde ki çizgiler böyle derin değildi

O başın neden şimdi mahzun düştü eğildi

Göz yaşları içinde çalarken şarkıların

Bilmem ki neresinde yaşıyorsun zamanın

Bir garip alemdesin seviyor musun hala

Bırakmışsın kendini esecek rüzgarlara

Kaderine razı ol boşunadır isyanın

Bilmem ki neresinde yaşıyorsun zamanın

Her şey eskisi gibi olacak mı sanırsın

Farkında değil misin tam yolun sonundasın

Kulların omzunda değişiyor mekanın

Bilmem ki neresinde yaşıyorsun zamanın

Sen de göçtün dünyadan hayattan alacaklı

Bir ben vardım ağlayan bir de garip mezarcı

Ruhun huzur buldu mu bitti mi acıların

Bilmem ki “bir önemi” var mı artık zamanın', 'Yine karıştı zaman beyazladı saçların Yine karıştı rengi kasvet dolu akşamın Neden böyle vefasız fırtınalı hayatın Bilmem ki  neresinde yaşı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/neresinde-zamanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsiz Olmaya Hakkımız Var mı?', 'umitsiz-olmaya-hakkimiz-var-mi-ali-riza-malkoc-czoqt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi çamurda bir gül yetiştirir                  

Kimi çamur atar kendin bitirir                    

Güneş doğar karanlığı götürür                         

Ümitsiz olmaya hakkımız var mı?              

Bazen dolu yağar, bazen yağar kar            

Koca dünya olur bazen bize dar                 

Derdi ve  dermanı   bilen biri var               

Ümitsiz olmaya hakkımız var mı?              

Kapılar yüz kere yüze kapansa                   

Gönüller kor gibi içerden yansa                 

Bilmeyenler seni divane sansa                    

Ümitsiz olmaya hiç gerek var mı?              

Nur  görünce kaçar hep yarasalar                

Gücü yetmeyene midir  yasalar                   

Gün gelir ki mahçup olup susarlar              

Ümitsiz olmaya hiç gerek var mı?              

Malkoç Ali  bu can bende durdukça          

Elim kolum tutup  gözüm gördükçe           

Dostlar meclisinde yerim oldukça              

Ümitsiz olmaya hiç gerek var mı?              

Ali Rıza  Malkoç   15/02/2006    Bursa

www.arm.web.tr', 'Kimi çamurda bir gül yetiştirir                   Kimi çamur atar kendin bitirir                     Güneş doğar karanlığı götürür          ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Malkoç']::text[], 8.5, '{"poet":"Ali Rıza Malkoç","poet_slug":"ali-riza-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/umitsiz-olmaya-hakkimiz-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burukluk', 'burukluk-elazigli-mustafa-kaya-2u6gu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bakamıyorum, 

başkalarının yüzüne. 

kaybettim, 

kırları, 

gerçek mavi ırmakları. 

seven bir kalbi, 

aynaların kıskandığı 

parıltıyı, 

gökyüzümün 

güneşini … 

azap içindeyim. 

her yağmur damlası, 

çarpıyor 

bin acılı ruhumu. 

düşündüm

hüzünlü çehreni

düşündükçe özlemlerini

kalbim sarsılıyor 

sensizliğe

gezdikçe istanbul’u … 

Mustafa kaya

15.02.2006 / yedikule', 'bakamıyorum,  başkalarının yüzüne.  kaybettim,  kırları,  gerçek mavi ırmakları.  seven bir kalbi,  aynaların kıskandığı  parıltıyı,  gökyüz...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/burukluk-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-abdulvahap-ates-7fjmz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşamla barışım ol

candan yakarışım ol

göz nurum gönül bağım

yürek arkadaşım ol

derdim ol derttaşım ol

ayağım ol başım ol

ekmeğim tuzum aşım 

hayat arkadaşım ol

sabahım akşamım ol

kışım ol baharım ol

güneşim ayım canım

sırrım ol sırdaşım ol

gel de öbür yarım ol

dengem ol ayarım ol

peteğim kozam tarlam

kadınım kısrağım ol

helalim yoldaşım ol

yastık arkadaşım ol

ölürsem mezar taşım

makberde kumaşım ol', 'yaşamla barışım ol candan yakarışım ol göz nurum gönül bağım yürek arkadaşım ol derdim ol derttaşım ol ayağım ol başım ol ekmeğim tuzum aşım...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kadinim-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-75 (M.S.) 13/02/2006', 'mektuplar-75-m-s-13-02-2006-mahzun-doga-m5wn2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gölgenden alıkonmuş ayak izlerim

adımlarımın hiçbiri adam değil şimdi

sana koşmaya imkansız 

aciz ve sevimsiz

Aramızdaki bütün nesneler ölümcül

birbirimize değmeyen bütün uzuvlarımız sakat

gereksiz dönüyor bütün saatler

Gün boşuna batıyor

Ya da ay anlamsız duruyor orda

Aramızdaki her şey gereksiz işte

Yani anlayacağın

aramızdaki bu ayrılık berbat bir durum

saçma

gereksiz

ve ödlek

ve patavatsız

ve basiretsiz

ve de çok şakacı

Her şey gereksiz

boşuna güldürmeye çalışma beni

çünkü bunu yaparken ağlıyorsun sen

saklayamıyorsun

saklayamazsın

görmeyemem…', 'Gölgenden alıkonmuş ayak izlerim adımlarımın hiçbiri adam değil şimdi sana koşmaya imkansız  aciz ve sevimsiz Aramızdaki bütün nesneler ölüm...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mektuplar-75-m-s-13-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-ayse-alioglu-zt9jm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim Dünyama doğan 

Güneşimsin 

Sen benim Rüyalarımın 

Melegisin... 

Sensin yüregimde fırtınalari 

Yaşatan 

Sensin gözlerimde 

Okyanuslari aşan 

Sensin sana sevdaliyim 

Ben... 

Gerekirse bir tek sacının teline 

Canimi veririm ben..

. 

Sensiz hayati 

düsünemem 

Sen olmayınca nefes bile alamam 

Benim canım kanım 

herşeyimsin 

Sen benim gözümün 

Bebeği.. 

Yanımdayken bile 

Hiç bitmeyen Özlemimsin... 

Kardeşin Nefise“ye 

Herzaman güzel örneksin.. 

Hey Bebegim haberin varmı 

bu güzeliklerden? 

Seni nekadarda çok 

Sevdigimden 

Annenin  canısin cananısın 

Kardesinin örnek aldiği 

Ablası 

Sen benim Bitanem

ilk askim ve ilk  göz ağrimsin

Iyiki varsın yavrum hayatimizda iyiki varsın........ 

Ayse Alioglu 18.02.2006 

Not: Bu Şiirimi Büyük Kızım Özlem Akyildiz a yazdım', 'Sen benim Dünyama doğan  Güneşimsin  Sen benim Rüyalarımın  Melegisin...  Sensin yüregimde fırtınalari  Yaşatan  Sensin gözlerimde  Okyanusl...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ozlem-314-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolurum', 'kaybolurum-birsen-ates-7zplf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kaybolurum masum 

sevginin kanatlarında

saf ve temiz aşklarım

uzanıp alamadığım 

çocukluğumda kaldı 

yarınlarımdan

geldim öğrenmeye

aşka dair bilmediklerimi

kaybolurum

boğucu kalabalıklarda

hala arıyorum 

en saf halini aşkın

dönmeyecektim çocukluğumdan

gelmeseydi aklıma

o masum bakışların

  

    14.02.06', 'kaybolurum masum  sevginin kanatlarında saf ve temiz aşklarım uzanıp alamadığım  çocukluğumda kaldı  yarınlarımdan geldim öğrenmeye aşka dai...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaybolurum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-rifat-gursoy-tvdk4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Feçese sardı yokluğunda işler

bir sevgi sözlerin kaldı bende

birde yırtık resmin

çilingir sofralarım da yok artık

öylesine bir kulum.

…İçmiyorum şerefine kimsenin

dikleyip foça ediyorum  şişeleri

toz toprak içinde bir durum

her birini  çok özledim  dolu olanların

başka başka şişelerinin de 

gözlerinden çokça öperim..', 'Feçese sardı yokluğunda işler bir sevgi sözlerin kaldı bende birde yırtık resmin çilingir sofralarım da yok artık öylesine bir kulum. …İçmiy...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Gürsoy']::text[], 8.5, '{"poet":"Rıfat Gürsoy","poet_slug":"rifat-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mektup-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Im Himmel sind viele Sterne(Gök yüzü dolu yildizlarla)', 'im-himmel-sind-viele-sterne-gok-yuzu-dolu-yildizlarla-ayse-alioglu-z47wd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Im Himmel sind viele Sterne 

aber einer gehört nur mir 

Den einen besonderen Stern 

Den gebe ich um kein preis her 

Der ist meins bleibt auch meins 

Wage es nicht mir zu nehmen 

Denn der ist dass Venus persönlich 

Venus das ist mein Stern den gebe ich nicht her..... 

xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx 

Gökyüzü dolu yildizlarla 

Ama biri benim yalnizca 

O benim özel yildizim 

Veremem hic kimselere 

O benim yildizim benim kalacak 

Sakin ha almaya kalkisma 

Bir baska parlar gözlerime 

Coban yildizim seni veremem 

Kimselere...... 

(24.03.05)', 'Im Himmel sind viele Sterne  aber einer gehört nur mir  Den einen besonderen Stern  Den gebe ich um kein preis her  Der ist meins bleibt auc...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/im-himmel-sind-viele-sterne-gok-yuzu-dolu-yildizlarla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabanci', 'yabanci-ayse-alioglu-bno9y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yabancıya rastladım bugün 

Oturmus Hagen parkta bir bank´a 

Bende oturdum yorgun argin yanina 

Şöyle izledi beni sorarcasına 

Gülümsedi hos bir tebessümle bana 

Yanagında gamzeleri carpıverdi gözüme 

Elinde bir Kitap, uzattı bana 

Al dedi, oku cekinme 

yıllarımı verdim Ben, buna 

Unutulmasın bir kenarda 

Yırtılmasın yapraklar okunmadan 

Sormama gerek kalmadan daha 

Bakıslarımdan anlayiverdi 

Şiir dedi 

Aldim elime, öyle bir baktım 

Siirlerle doluydu gerçekten 

El dememis, Göz degmemis Siirlerdi 

Basladım okumaya 

Yabancı hayatını dökmüstü siirlere 

Kaybettigi Sevdasıydı, 

Siirlerle süsledigi 

Yabancıya Askından kalan tek hatıra 

Kitabına döktügü siirlerdi 

Yalnızca 

(21.03.05)', 'Bir yabancıya rastladım bugün  Oturmus Hagen parkta bir bank´a  Bende oturdum yorgun argin yanina  Şöyle izledi beni sorarcasına  Gülümsedi ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yabanci-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk Yorgunluk', 'yokluk-yorgunluk-selim-sar-cmjo0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya Rab bu hasretlik beni gucsuz koyuyor

Yol yorgun, zaman yorgun, ben yorgun

Her hayalim bir oncesinden soluyor

Umut yorgun, dua`m yorgun, ben yorgun

Mumkunmuki bu yolda ufuk`a ermek

Vakit olsa, sansim olsa, guc olsa

Hatam olmazdi belki seni sevmek

Vakit olsa, sansim olsa, guc olsa.

Selim Sar

2.2.2006   Istanbul', 'Ya Rab bu hasretlik beni gucsuz koyuyor Yol yorgun, zaman yorgun, ben yorgun Her hayalim bir oncesinden soluyor Umut yorgun, dua`m yorgun, b...', ARRAY['Türk Edebiyatı','Şiir','Selim Sar']::text[], 8.5, '{"poet":"Selim Sar","poet_slug":"selim-sar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yokluk-yorgunluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-selim-sar-hzmhx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dun gece dedimki kendi kendime

Gozyasindan dilek tut gel sevgine

Sen dusundukce o aksin, sen dusun

Gorelim hayaline ne kadar yakinsin

Goz yaslarim akiyor, ben sayiyorum

Her suzulen damlada dagiliyorum

Kapattim gozlerimi, kurdum kalbimi

Her atista bir damla salmis kendini

Bu haliyle cok solgun duruyor beden

Meftuna ol magrur bicmis bir kefen

Golgeme yel degse usur haldeyim

Sen benim disimda bense eldeyim

Bu hal urkutur bedenimi, usume alir

Kapanan gozlerim urkerek aralanir

Yakilmis murekkebin iziyle cizilmisim

Meger bu mahpus halle ne az sevilmisim

Ben kendimden kacarim sen benden

Dilegim ayniydi yok fark oncekinden 

Kuheylan atiyla gelmis olsaydin bana

Engel yoktu o hanceri tekrar sokmana.

Selim Sar

1.2.2006  -  Istanbul', 'Dun gece dedimki kendi kendime Gozyasindan dilek tut gel sevgine Sen dusundukce o aksin, sen dusun Gorelim hayaline ne kadar yakinsin Goz ya...', ARRAY['Türk Edebiyatı','Şiir','Selim Sar']::text[], 8.5, '{"poet":"Selim Sar","poet_slug":"selim-sar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dilek-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu garip', 'bu-garip-i-lhami-arslantas-yx9cq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıkmaz bir sokakta çaresiz başı,

Nerde yatacağın bilmez bu garip.

Boşalır boşalır dolar göz yaşı,

Nasıl tutacağın bilmez bu garip.

El attığı dallar bir bir kuruyor,

Onca bilinmezlik onu vuruyor,

Önünde dağ gibi derdi duruyor,

Nasıl atacağın bilmez bu garip.

Tek bir sabır kaldı onu taşıyan,

Yoksulluk yarasın kimdir kaşıyan? 

Aç açıkta kalmış odur üşüyen,

Nasıl yatacağın bilmez bu garip.

Dolaşır ayağı çözümsüzlüğe,

Asabı bulanmış azimsizliğe,

Nasıl dayanacak hazımsızlığa,

Nasıl yutacağın bilmez bu garip.

Hangi kapı bilmem ona yar olur? 

Hangi hesap bilmem ona kar olur? 

Bu, insana bilemez miyim kor olur,

Nasıl tüteceğin bilmez bu garip.

Der İlhami Ankara’nın kışı yok,

Oradaki vicdan aciz, döşü yok,

Eyvah devletimin niye başı yok? 

Nasıl satacağın bilmez bu garip.', 'Çıkmaz bir sokakta çaresiz başı, Nerde yatacağın bilmez bu garip. Boşalır boşalır dolar göz yaşı, Nasıl tutacağın bilmez bu garip. El attığı...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-garip-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlizlik Nedir?', 'yanlizlik-nedir-selim-sar-u3cj0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnizlik ne demek bilirmisin sen? 

Kelimede durdugu kadar sade

Hissedebildigin kadar senden

Bekleyebildigin kadar yakin

Buyutebildigin kadar guclu

Eskitebildigin kadar yeni

Tasiyabildigin kadar agir

Kaldirabildigin kadar sabir

Dunya dolusu insan

Bir tek yalan dolan

Buhranla islanmis

Kaldirim tasi

Basimda agri

Bekle bekle

Iste yanlizlik.

Selim Sar

14.2.2006  Istanbul', 'Yalnizlik ne demek bilirmisin sen?  Kelimede durdugu kadar sade Hissedebildigin kadar senden Bekleyebildigin kadar yakin Buyutebildigin kada...', ARRAY['Türk Edebiyatı','Şiir','Selim Sar']::text[], 8.5, '{"poet":"Selim Sar","poet_slug":"selim-sar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanlizlik-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen varya Sen', 'sen-varya-sen-ayse-alioglu-wxazc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen varya sen cok baskasin sen... 

Sendeki kaderi istemem ben, 

Sendeki acilar bitmeyecekmi? 

Su felek sanada gülmeyecekmi? 

Gül bahcesi acarmi bir gün gönlünde? 

Yildizlar parlarmi seninde gözlerinde? 

Gel gülüm gel kardesim aglama yeter derim... 

Felege bos ver takma üzülme derim…. 

Hayat bu ne yapsan degismez carki… 

Yardan ayirir koparir yoktur caresi, 

Eceldir gelir sormadan kapina… 

Caresiz birakir hastane kapilarinda… 

Gel uzat elini yeni sevdalara, 

Yenilme felegin kurdugu oyuna.. 

Birak gönlünde güller acsin, 

Gözlerin günes gibi gene parlasin… 

Sana dileklerim en icten sevgimdendir, 

Felege celme takman tek dilegimdir… 

Masize saklamalisin gecen günleri, 

Yeni sevgilere acmalisin yarali yüregini…. 

Derman sende careler elinde,, 

Tek arzum mutlu ol bütün ömrünce........ Ayse Alioglu

Not; bu siirimi birzamanlar sanalda olsa cok sevdigim iki kardesime yazdim ne yazikki felek onlari 6 ay evliliklerinden sonra ölümle ayirdi.esine Allahtan rahmet diliyor Tahir kardesime ise hayata sikica salirmasini ve mutlulugu yeniden bulmasini diliyorum....Ayse Alioglu', 'Sen varya sen cok baskasin sen...  Sendeki kaderi istemem ben,  Sendeki acilar bitmeyecekmi?  Su felek sanada gülmeyecekmi?  Gül bahcesi aca...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-varya-sen-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asirlar önce', 'asirlar-once-ayse-alioglu-k1gep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asirlar önce cikildi yollarina 

Sonunda varildi kutsal Kabenin kapisina 

Secdeye duruldu dualar edildi 

Rabbim sana giden yollar güllerle bezendi. 

Uzat elini kardesim ayirim yapilmasin 

Biz onun kullariyiz bizi kimse ayirmasin 

Allah yolunda atilsin bütün adimlar 

Imana gelsin bütün Kullar 

Kibleye döndük elimizi actik 

Rabbim biz sana günahlarimizla geldik 

Sen yüceler yücesi yaradan bizleri 

Rabbim sen yüceliginle af et af et bizleri..........Amin..... 

(AySeGül 26.01.2005)', 'Asirlar önce cikildi yollarina  Sonunda varildi kutsal Kabenin kapisina  Secdeye duruldu dualar edildi  Rabbim sana giden yollar güllerle be...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asirlar-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz yaslarimla', 'goz-yaslarimla-ayse-alioglu-feq0l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz yaslarimizla  yikansin ruhumuzun kiri, günahi 

Melekler anlatsin Rabbim sana pismanligimizi 

Susuz cöllerde kaldik rabbim  asirlar boyu

Seytanin tuzagindan kurtulamadik   Rabbim 

Rabbim sana giden yolda biz seytana nasil kandik. 

. Secdene vardik   Rabbim günahlarimizla 

Sana sigindik biz  bütün varligimizla 

Sen yüce, Sen yaratan,Sen af edici 

Rabbim Sen bagisla,Sen bagisla Bizleri 

Gülleri sererek yollarina, Vardik Kabenin kapisina, 

Günahlarimizla ya Rab geldik Senin Huzuruna 

Kabenin kapisinda secdeye durduk 

Rabbim sana giden yollu bizsükür bulduk

Secdene vardik ya Rabbim günahlarimizla 

Sana sigindik biz bütün varligimizla 

Sen yüce, Sen yaratan,Sen af edici 

Rabbim Sen bagisla,Sen bagisla Bizleri. 

Rabbim sana giden yollar güllerle bezenmis 

Dualarin Meleklerin sayesinde indirilmis 

Rabbim,Sen bagislayici,Sen af edici, 

Rabbim Seytanin serinden, Sen koru Bizleri........... 

Secdene vardik   Rabbim günahlarimizla 

Sana sigindik biz bütün varligimizla 

Sen yüce, Sen yaratan,Sen af edici 

Rabbim Sen bagisla,Sen bagisla Bizler............AMIN 

(Ayse Alioglu 25.01.2005', 'Göz yaslarimizla  yikansin ruhumuzun kiri, günahi  Melekler anlatsin Rabbim sana pismanligimizi  Susuz cöllerde kaldik rabbim  asirlar boyu ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/goz-yaslarimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Sevdamız', 'gizli-sevdamiz-naciye-bildim-awbw0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen benden habersiz,ben senden habersiz

Meğer birbirimizi ne çok sevmişiz.

İçimizdeki gizli duygularımızla,

Ne hatalı yollara girmişiz.

Sen başka gözlerde,mutluluk ararken

Ben başka kollarda,sevdaya yatmışım.

Sen gönülden sevildiğine inanırken,

Ben rüyalardan rüyalara dalmışım.

Yıllar sonra bu gün,herşey çıktı ortaya,

Fakat ne yazık,yabancısın sen bana.

Dönüş yok,can verilmez bu sevdaya,

Razı ol artık,rüyalarla avunmaya.', 'Sen benden habersiz,ben senden habersiz Meğer birbirimizi ne çok sevmişiz. İçimizdeki gizli duygularımızla, Ne hatalı yollara girmişiz. Sen ...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gizli-sevdamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm', 'uzgunum-naciye-bildim-b7cbg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oysa ne çok sevmişim seni,

Ne çok değer vermişim.

Sen gözlerimdeki yıldız oldun hep,

Gülmeme bir neden,

Yaşamama tek sebeb.

Sen hayatımdaki tek adam,

Ömrümce sevebileceğim tek insan.

Ve sen; 

Severken terkedeceğim,

Severken silebileceğim tek sevdam.

Üzgünüm,

Bir o kadarda ağlamaktayım.

Elimde bitmeye az kalmış sigaram,

Dumanı sen

Yanan alevi ben.

İşte öyle yanmaktayım,

Acıtmaktayım canımı.

Bırakta bir kez daha yansın canım,

Yeniden sen ol,gözlerimden yıldızımı çalanım.

30.01.2006....Nazilli', 'Oysa ne çok sevmişim seni, Ne çok değer vermişim. Sen gözlerimdeki yıldız oldun hep, Gülmeme bir neden, Yaşamama tek sebeb. Sen hayatımdaki ...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzgunum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş Bitmişti Yoksa', 'savas-bitmisti-yoksa-muammer-erturan-xiam2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimi en derinindeydi uykunun...

Kimi kahvaltıda...

Geyşaca hınzırlıklar bekliyordu

kimi evlerde

cepheden dönecekleri...

Savaş bitti bitecek...

Kimin aklına gelecek; 

Pasifik ötesinden havalanan

bir tuhaf ''oğlan''

musallat olacak da başına,

ikimilyon santigratlık

bir cehennem yumağına dönüşecek

canım Hiroşima! ..

Olacak iş mi? ...

Savaş bitti bitecek...

Ah o tüyü bitmedik

çekik gözlü çocuklar! ..

Onlar yok mu onlar...

Kimbilir ne yaptılar,

bindokuzyüzkırkbeşin

altı ağustos sabahı

uyanmayı hak etmeyecek...

Kimbilir ne ettiler

kaşla göz arası

zavallı ''oğlan''a...

Savaş bitmişti yoksa! ..

(6 Ağustos ''95)', 'Kimi en derinindeydi uykunun... Kimi kahvaltıda... Geyşaca hınzırlıklar bekliyordu kimi evlerde cepheden dönecekleri... Savaş bitti bitecek....', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/savas-bitmisti-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durak', 'durak-hakan-baytar-22r27', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yorulmak zamana uymaktır,

tarihi avucundan kaçırmaktır 

ritimsiz soluk alışlar

son savaşçısı kaldın sen 

ikimizin,

son soluğumu koydum kınına.

kimi geçirsem içimden, icazet alıyorum aklımdaki senden

kimin saçları uzaksa sana bezemekten

bir türlü gitmiyor yüzün

aynamın içinden,

bu kışlar böyle karsız,

sulu çamur, ziyan geçer

özledim seni demenin tam zamanını kaçırdım,

tabiatın dengesini,

anını kaçırdım sana koşmanın', 'yorulmak zamana uymaktır, tarihi avucundan kaçırmaktır  ritimsiz soluk alışlar son savaşçısı kaldın sen  ikimizin, son soluğumu koydum kının...', ARRAY['Türk Edebiyatı','Şiir','Hakan Baytar']::text[], 8.5, '{"poet":"Hakan Baytar","poet_slug":"hakan-baytar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/durak-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerinizden Öper', 'ellerinizden-oper-muammer-erturan-fo0vy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutlarınız var 

rengârenk

coşkularınız var

o umutları göğertecek

yürekleriniz var

güneşten de sıcak

ve yaşanacak bir dolu bahar...

Pırıl pırıl

ışıl ışıl

barışçıl mı barışçıl

bir dünya

bırakabilseydik keşke...

Ne çare ki

bu kadarı gelebildi elimizden...

Dahası

ellerinizden öper çocuklar! ..

(''98)', 'Umutlarınız var  rengârenk coşkularınız var o umutları göğertecek yürekleriniz var güneşten de sıcak ve yaşanacak bir dolu bahar... Pırıl pı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ellerinizden-oper-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birdenbire', 'birdenbire-cagdas-yildiz-mqfwh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'birazcık yüklensen 

kırılacak eski bir iskemle gibi dururken

yeni nesil sevgiler

nereden çıkageldin sen', 'birazcık yüklensen  kırılacak eski bir iskemle gibi dururken yeni nesil sevgiler nereden çıkageldin sen...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/birdenbire-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Provalardaki Coşku', 'provalardaki-cosku-muammer-erturan-k9wse', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biledik umutları 

iki ucu keskin, 

adımız gibi belledik tiradını 

o son sahnenin... 

Erişemeden menzile

menziline düşmek de vardı 

kahpe bir merminin ya 

kimin umurunda... 

O günden bugüne 

aynı oyuncular sahnede 

ve hâlâ aynı martavalı okumakta

ve hâlâ yutulmakta 

ve hâlâ seyirci koltuğunda 

sevgili proletarya! .. 

Hele ki şu günler 

en beter perdesinde oyun 

ve en rezil

ve en iğrenç

ve en saçma sapan... 

Kirişi kıran mı istersin 

saplanıp kalan mı konformizm batağına, 

satıp benliğini 

üç beş kuruşa yoksa 

sırtından vuran mı 

eski yoldaşlarını... 

Hangi cehennemde kaldı şu 

provalardaki coşku! ? . 

(6 Ocak ''99)', 'Biledik umutları  iki ucu keskin,  adımız gibi belledik tiradını  o son sahnenin...  Erişemeden menzile menziline düşmek de vardı  kahpe bir...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/provalardaki-cosku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-yusuf-ter-fubgw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar kardan beyaz olur mu

Dön gel sevdiğim ayazdır

Şiir yazdım okunur mu

Dön gel  sevdiğim niyazdır

Hayalin hep hayallesem

Şu meyi  bir  bellesem

Tenin tenime değdirsem

Dön gel  sevdiğim o yazdır 

Yusuf’ ömrün arayansın

Hayatım  ver kora yansın

Kayıp olan yarınımsın

Dön gel sevdiğim bu nazdır

Yusuf Ter 14.02.06

Saat 23:26 İsviçre', 'Kar kardan beyaz olur mu Dön gel sevdiğim ayazdır Şiir yazdım okunur mu Dön gel  sevdiğim niyazdır Hayalin hep hayallesem Şu meyi  bir  bell...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kar-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batkın', 'batkin-cagdas-yildiz-6ich4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerime aydınlıklarını batıran güneş

o batışının kızıllığını sür de alnıma

öyle çek git gideceksen 

eğer bir gün

tekrardan geçeceksen yalnızlığımdan

ellerimi bırak 

gözlerimi bırak da

parıltını toplayıp bir aynaya

nefes ol bari

bir çift yıldıza....', 'gözlerime aydınlıklarını batıran güneş o batışının kızıllığını sür de alnıma öyle çek git gideceksen  eğer bir gün tekrardan geçeceksen yaln...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/batkin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-suskun-resital-yg54a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğunu sevemedim, 

Sen yine de gelmeyi dene. 

Bu uzun gidişler bana göre değil, 

Sen sevildiğin yerde olmayı dene... 

Şiirlerle gel şarkılarla gel, 

Sevinçlerle dost olmayı dene. 

Varsın susmalar eski olsun, 

Sen yeni birşeyler söylemeyi dene...', 'Yokluğunu sevemedim,  Sen yine de gelmeyi dene.  Bu uzun gidişler bana göre değil,  Sen sevildiğin yerde olmayı dene...  Şiirlerle gel şarkı...', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-273-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-cagdas-yildiz-3u4y9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu şehri sevmeye başladım

o da benim gibi..

bak; 

hiç dayanamıyor gidişine...

şimdi saçlarına yağanı

yağmur mu sanıyorsun?', 'bu şehri sevmeye başladım o da benim gibi.. bak;  hiç dayanamıyor gidişine... şimdi saçlarına yağanı yağmur mu sanıyorsun?...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozyasi-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalar Tetikte', 'sevdalar-tetikte-muammer-erturan-3qsjf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tepelerin ardı pusu...

Pusuda düşman...

Ama bir ana kuzusu...

Ama bir insan...

Vurmasan vurulursun...

Vursan vuruldun...

Savaş bu,

iki ucu boklu...

Yolu yok! ..

Yürüyeceksin

üstüne üstüne azrailin...

Titrete titrete dağı taşı...

Yeri göğü inlete inlete...

Patlata patlata zuladan

mermi mermi türküler...

Gün o gün işte! ..

Bugünün yarını da var...

Sevdalar tetikte...

(24 Eylül ''78, Sarıkamış)', 'Tepelerin ardı pusu... Pusuda düşman... Ama bir ana kuzusu... Ama bir insan... Vurmasan vurulursun... Vursan vuruldun... Savaş bu, iki ucu b...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdalar-tetikte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şifa', 'sifa-cagdas-yildiz-o76uk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'başımı yastığa koyup 

nefes alamayışlarım olsun istedim kaç kere

bile bile değilde

bi kazaya kurban gitmek

olmadık şeylerle çarpışmak fena gelmezdi.

sersemliğime ve sarhoşluğuma borçluydum herşeyimi

hayatımıza ve insanın tabiatına

sihirli bir değnekle dokunan 

kader dedikleri şey bu olmalıydı

nasıl acımasızca döktüyse bir gecede bütün yıldızları

yine de bir güneşin yalnız yakıcılığında yağan yağmur

tomurcuklarını döküyordu yalnızlığa

ve artık şifa veriyordu ayrılık

kanayan yaralarımıza...', 'başımı yastığa koyup  nefes alamayışlarım olsun istedim kaç kere bile bile değilde bi kazaya kurban gitmek olmadık şeylerle çarpışmak fena g...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sifa-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusura Bakmayın', 'kusura-bakmayin-naciye-bildim-sgq7k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarımı tutmak için

Saçma sapan espriler yaparsam,

Beni ne olur bağışlayın.

Çektiğim dertlere karşı,

Ve böylesi ayrılıklara

Bir top mermidir gülüşüm,

Bir silahtır kahkahalarım.', 'Gözyaşlarımı tutmak için Saçma sapan espriler yaparsam, Beni ne olur bağışlayın. Çektiğim dertlere karşı, Ve böylesi ayrılıklara Bir top mer...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kusura-bakmayin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar-tanesi', 'kar-tanesi-cagdas-yildiz-3vxe8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'senin hiç sulanmış karlarda 

gezdiğin ayaklarının 

ıslandığı oldu mu? 

ellerinin buz tuttuğu 

ama yine de kartopu oynadığın..

saatlerce uğraştığın kardanadamları

bir dakikada yıkışların..

buz tuttuğunda ellerin

nefesinle ısıtışların

ıslanan yalnızlığını

sobaya asışların

hele hele umutlarının tükendiği anlarda

tek başına yürüdüğün sokaklarda

saçlarına düşen kar tanelerinin

gözyaşına dönüştüğü zamanlar oldu mu

sen hiç kartaneleriyle seviştin mi?', 'senin hiç sulanmış karlarda  gezdiğin ayaklarının  ıslandığı oldu mu?  ellerinin buz tuttuğu  ama yine de kartopu oynadığın.. saatlerce uğra...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kar-tanesi-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut Daha', 'bir-umut-daha-muammer-erturan-lv8qe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bütün çocukların adı: 

Umut... 

Bütün umutlar çocukça... 

Bütün umudu çocuklarda dünyanın... 

Çocukların umuduysa

tümüyle arınmış 

savaştan ve sömürüden 

ve bölüşülmeden paylaşılabilen 

bir dünya... 

Bütün çocukların adı: 

Umut... 

Bir umut da sen tut! .. 

Tut ki yeşersin 

ki eklensin umutlara 

bir umut daha! .. 

(22 Mart ''95)', 'Bütün çocukların adı:  Umut...  Bütün umutlar çocukça...  Bütün umudu çocuklarda dünyanın...  Çocukların umuduysa tümüyle arınmış  savaştan ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-umut-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz', 'olumsuz-cagdas-yildiz-wgruw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bak

eskiye özlem duyan biri daha

yelken açıyor 

fırtınalı denizlere

daha ölmemişsin sen

korkma ölmezsin de

yalnızlığınıza dost 

bir yıldız da sizin için var

gökyüzünde...', 'bak eskiye özlem duyan biri daha yelken açıyor  fırtınalı denizlere daha ölmemişsin sen korkma ölmezsin de yalnızlığınıza dost  bir yıldız d...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olumsuz-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*NnO Balıklama', 'nno-baliklama-akin-akca-jhov9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'K.S. gülen Adam’ında ilk, gülerek doğan -o minnacık kıkırdayan- bebek Fortis; daha sonra da Faithless’ın bir klibinde can buldu, neşe ile hep danseden –duşta, yemekte, uykuda, doğum anınca! ... o kadınla aynı cinsli el(v) enmesinden erkeğin: Böyle bir şey midir, ölüm de; yoksa bahsetmeye gerek yok mu dahi? Gülerek doğan -yürüyen gecekondu dikiverip sırtına asan halatlarından bağlayıcı onu kaçışlarda zaptırapt zabıtadan- Gülen Adam; onun bebeği ağladı doğunca. Buna ağladı, film öylece bitti. Olan böyle olabilir mi: Why go? Sonunda müziğinin hala Faithless’in, hala dansedip ki aile artık olmuşlar; evlenmişlerdi, sofraya tabak diziyorlardı raksederek ve finito klip öylece. Gülen Adam’sa üzüldü nedense ilk, çocuğu dünyaya geldiğinde –dünyaya gelince değil- O ağlamadı bebeği ağlayarak doğdu; hayatı belki de o an anladı, bir anlıktı: Üzülse de, “beş parmağın beşi..” meselesi mi? Belki de hiç doğmamalı doğmadan olsa yaşamak –deneyim kazanmadan olgunlaşmak olsa …Ve/ama devam ettiği gibi nikbin sisleştirmeli, ya da yani yapmamalı böyle (sınırsız genleşmeye bırakmamalı evreni tuzla buz)  ama bir şy var öteye götüren, gerektiklerinde; yoksa, öte yandan, sınırsız, hakim mi?)  (Big Crunch ise, daha elzem, kötü yadedilmeye. Yine de, siyah ve beyaz; ölüm bu mu, yoksa –emin olma kabilinden- bir mucize mi yaşam? 

(“Atların nalları altında parçalanıyorsan sevdiğinin atı altında deli ol; seni ölüme gönderen patişahın gönlü bulsun can. Her yeni gün rüyalar başkenti; yıl ama aynı her, sevgi günü.”) 

Böyle olmalı ağır o çekim robot polisler, bir de gri-metalik onları yapmışlar, maskelerini –Lucas G. Anon.** Koşamıyorlar,,,, bir robot için bile körlemesine bir sağduyu, çok garip. Uzun ve inceler ama copları var -her şey idealizmine uygun, eski bir ‘8o’s- Electronic Lab Labyrinth THX.

Kırmızı beyaz çizgili bir kağıttan patik pembe içine sarmalanmış kıpkırmızı karanfiller ve beyaz küçük çiçek, yapay gibi, garnitürler.. ki karanfillerden aralara serpiştirilmiş, sana sevgilim. Yarın sevgililer günüymüş, bilirim, sessizinde bilirim …

*

Duck Donald, ses-orijin, Disney, Çiçero ve! …

Çocuklar kare parkelerden öte yana geçtiler 

kara delik Tekilliğinden; tam da yanına,

Havada uzayda dönen Koca bir makinanın ki ışık

Saçıyor o merkezinden enerjik… Dev bir 

çevrim oluşmuş İkisi yan yana düşünce,

Bu kara delik ve o makine –

Şiddetli manyetik alan, Yerin eriyikleri

Derinlerinden fırlayıp da yeryüzüne Kamufle...

Zaman, ileri doğru çok Hızlı genleşir; o eskiden 

reenkarne olduğunu Söyleyen Eliza kadın gibi der,

elektronların aşırı Hızlandırılması ile Yörüngelerinde …

Böylece, sadece görünmez mi olu(nu) yor? 

Bu olsa, bir ilizyon. Ya kayıp kütleler? 

*Neyin ne olduğuna

Bu şiir bir anlamda şiirime şiir gönderen sevgili Cezalı Tank/ Nilgün Aras’a cevap gönderme. Teşekkür ederim yorumlarınız için

Çift tırnak içi cümle alıntıdan esnetme

Üzerinde düzeltme yapabilirim

**George Lucas (Txh’i Star Wars’tan önce okuldan mezun olmak için çekmiş deniyor, kısa metrajsı, ama uzunca. Serinin hazırlayıcısı olmuş

K.S. Kemal Sunal', 'K.S. gülen Adam’ında ilk, gülerek doğan -o minnacık kıkırdayan- bebek Fortis; daha sonra da Faithless’ın bir klibinde can buldu, neşe ile he...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nno-baliklama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akordiyonda Gasparon - Gaspard''la Robinson', 'akordiyonda-gasparon-gaspard-la-robinson-akin-akca-3bmxd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gaspard’la Robinson bir çingene havasında

Kumsalda, koynunda dalgaların Ve o ateş

Bir kamp güneşi gibi, afacan beşler, yanıyor.

Dansediyor iki kadim dost, ikiz birer kardeş.

Kerelik aşk, arkadaşlık daimi, gecenin

Karasında, alacasında kumsal alevinin; sapa.

‘Hacı Bektaş ile Mevlana senli’ yükseliyor

Konya’dan, görünmezdir tüm töhmetler.

Seven aşklarına gizilsiz alışılmışlıkların,

Körsü bir anlıktır tüm o kararsız badireler.

Amaldanma işte, orda, iki dost dans tutmuşlar; 

Her yeni günü cinsli, taş demir.. bayan için

Gün ışıdığında, her gülümseyen sabahın.

Bu adamlar da yadediyorlar tepişerek neyi; 

Gecenin rüzgarında uçuş tepeler kumullaşmış? .

Kenarda bir gramofon, şarap mahzeni ellerinde.

İyi de niye pür-cümle, devam etmek varken? 

Görünmeyen hasır altı mahzun gökler yağmur -

kıvrılmış köşede bir yerde- şiddetle kusuyor

Fidanlardan ki olan henüz tomurcuklanmış; 

Su birikintileri az öncesinde oluşmuş.

Kirli sarı dinozorlar çıkacak daha sonraları.

Akordiyonlar körük basıyor oto mekanizma

Şehir efsun o(to) büsü. Fenalıktır aşk,

Anlayana, sevgi ama fedakarlıktır, gitmez geri! 

Kırmızı güller tek tektir, ama bilir halleri,

Birlik ikiz halleri kır papatyalarıdır; 

Bu bir barış: tersinmez; tüy kalem notalarda …

…

Eskibir film(den akis)  anısına

Sevgililer gününüz kutlu olsun', 'Gaspard’la Robinson bir çingene havasında Kumsalda, koynunda dalgaların Ve o ateş Bir kamp güneşi gibi, afacan beşler, yanıyor. Dansediyor i...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/akordiyonda-gasparon-gaspard-la-robinson-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altı Mayıslar', 'alti-mayislar-muammer-erturan-pjvc8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yetmişikiden beri lanetli

altı mayıslar

yetmişikiden beri taa! ..

Destanını yazdıklarından beri kavganın

darağaçlarında

Deniz, Yusuf ve Hüseyin...

Faşizmin kirli elleri

geçirdiğinde ipi boğazlarına

daha baharındaydılar yirmilerin,

ne merhamet dilendiler lakin

ne boyun büktüler

ne ödün verdiler en ufak.

korkak ve şaşkın 

bakışları altında celladın

arslanlar gibi veda ettiler hayata...

Yetmişikiden beri lanetli

altı mayıslar

yetmişikiden beri taa! ..

Yirmiüç yıl sonra şimdi

katmerlendi laneti...

Ettiği yetmezmişçesine bir de

sensizliği saldı üstüme...

(6 Mayıs ''95)', 'Yetmişikiden beri lanetli altı mayıslar yetmişikiden beri taa! .. Destanını yazdıklarından beri kavganın darağaçlarında Deniz, Yusuf ve Hüse...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/alti-mayislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuuuh', 'yuuuh-muammer-erturan-yklrq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırgın mırgın değilim

hele ki sana 

olamam da zaten... 

Başka yerlerdeyim ama 

ve başka zamanlarda bugün... 

Mahirleri düşünüyorum 

ve Denizleri 

ve İboları 

ve altmışlı yetmişli yılları... 

Düşündükçe düşündükçe 

okkalı bir 

yuuuh! .. 

çekiyorum kendime... 

Ulan! diyorum

ulan oğlum! 

Öylesine onurlu gitmek varken 

ne vardı kalacak

yaşanacak dünya mı 

zaman mı bu

içine tükürdüğümün! .. 

(10 Nisan ''95)', 'Kırgın mırgın değilim hele ki sana  olamam da zaten...  Başka yerlerdeyim ama  ve başka zamanlarda bugün...  Mahirleri düşünüyorum  ve Deniz...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yuuuh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Emek, Umut Barış! ...', 'sevgi-emek-umut-baris-ozan-si-ar-agdasan-d7eyy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dost cemali kabe´mizdir

Hac’ca gerek yoktur bizde

Sevgi oduyla yanarız

Sac’a gerek yoktur bizde! 

Sudan tatlı alın teri

Ölmeden öldük biz diri

İnsan dünyanın veziri

Taç’a gerek yoktur bizde

Nakarat:

Gün doğar güller al olur

Yaralı kuşa dal olur…

Dost sevdamızın şavkından

Ay hicap eder lal olur! 

Güzel bir dünya kuralı

Olmasın renkler karalı

Dördü de tutsak yaralı

Sevgi Emek Umut Barış! 

Şiar, zulmü zay ederiz

Karanlığı ay ederiz

Biri kırka pay ederiz

Aça gerek yoktur bizde...!  Nakarat:...

Söz: Ozan Şiar Ağdaşan,  Müzik: Anonim

Yorum ve beste: Ozan Şiar Ağdaşan

Vokaller: Aşık Şah Turna, Şirin Şafak Ağdaşan Umut Müzik

www.siarcan.com', 'Dost cemali kabe´mizdir Hac’ca gerek yoktur bizde Sevgi oduyla yanarız Sac’a gerek yoktur bizde!  Sudan tatlı alın teri Ölmeden öldük biz di...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgi-emek-umut-baris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sellale gibi', 'bir-sellale-gibi-ulya-erkman-y2hcn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sellalenin berrakligi gibi

Berrak sevgim sana

Bir sellalenin durmadan akisi gibi

Akiyor sevgim sana

Bir sellalenin coskun akisi gibi 

Coskun sevgim sana

Bir sellalenin omru gibi 

Omrumcedir sevgim sana

Bir sellalenin bitisi gibi vurunca topraga

Sevgim de sana

Bitecek topraga vurunca', 'Bir sellalenin berrakligi gibi Berrak sevgim sana Bir sellalenin durmadan akisi gibi Akiyor sevgim sana Bir sellalenin coskun akisi gibi  Co...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-sellale-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara gozlum gozundeki yas neden', 'kara-gozlum-gozundeki-yas-neden-yasar-gurlek-5p15t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara  gozlum  gozundeki  yas  neden

Kirdimmi  seni  yoksa  bilmeden

Gel  aglama  kara  gunler  gelmeden

Her  derde  bir  care  bulunur  elbet

Gozundeki  yaslari  kurutayim  dilimle

Al canimi  sana  verdim  al  kalbimi  elinle

Gel  aglama  hep  gulelim   seninle

Her  derde   bir  care  bulunur  elbet

Bin  canim  olsa bin kere  ederim  feda

Kimselerde  gormedim boyle ve  eda

Ne  ses  gelir  senden  nede  bir  seda

Bu  derde  bir  care  bulunur  elbet

Yasar  gurlek  14-02-2006

Rotterdam    hollanda', 'Kara  gozlum  gozundeki  yas  neden Kirdimmi  seni  yoksa  bilmeden Gel  aglama  kara  gunler  gelmeden Her  derde  bir  care  bulunur  elbe...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kara-gozlum-gozundeki-yas-neden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-yasar-gurlek-40j1t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GIDERKEN

Sevgini  birakma  boyle  giderken

Al  yaninda  gotur  yakmasin  beni

Hic  hatira  kalmasin  istemem  senden

Mahserdede af  etmem inanki  seni

Bu  omru  tuketip  seni  bekledim

Senden  ayri hic  kimseye  asla  gulmedim

Sacimi  agartip   bitip   tukendim

Cennetlikte   olsan  af  etmem  seni

Yuregimde  askin  yanar  dururken

Caresiz  derdim  kanar  dururken

Ben  olmeden sen  benim  canim  alirken

Ben  asla  af  etmem   inanki  seni

Hic  bir  iz  birakma  al  hepsini  git

Bosuna  yuregim  yanmasin  sana

Ne  bir  ani  ne  hatira  istemem  senden

Hic  bir  zaman  af  etmem  inanki  seni

Yasar  gurlek  14-02-2006

Rotterdam    hollanda', 'GIDERKEN Sevgini  birakma  boyle  giderken Al  yaninda  gotur  yakmasin  beni Hic  hatira  kalmasin  istemem  senden Mahserdede af  etmem in...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/giderken-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Gonlum', 'benim-gonlum-yasar-gurlek-0fzgl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BENIM  GONLUM

Acilarla  gecti    omrum

Ne  sevkatin  ne  ask  gordum

Bir  bulanik  sele  dondum

Hep  agladi  benim  gonlum

Her  bilmezde  ask  aradim

Zalime  bir  yol  aradim

Tutacak  bir dal  aradim

Hep  agladi benim  gozum

Elden  ele  varip  durdum

Olmadi  hic  yerim  yurdum

Bosu  bosuna  hayal  kurdum

Hep  agladi  benim  gonlum

Hayalinle  gecti  omrum

Sanki  senden  askmi  gordum

Ruyalada  senle  guldum

Cok  agladi  sensiz  gonlum

Hic  bitmedi  sana  askim

Sevdan  ile  oldum  saskin

Sevmeseydim seni  askim (keskem) 

Hep  aglattin  benim  gonlum

Yasar  gurlek  14-02-2006

Rotterdam    hollanda', 'BENIM  GONLUM Acilarla  gecti    omrum Ne  sevkatin  ne  ask  gordum Bir  bulanik  sele  dondum Hep  agladi  benim  gonlum Her  bilmezde  as...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/benim-gonlum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimde Kara Kara', 'kalbimde-kara-kara-yasar-gurlek-ldf36', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KALBIMDE  KARA  KARA

Kalbimde  kara  kara

Her  sevgiden bir  yara  var

Bulun  belki  ara  ara

Sade  yarda  bu  care  var

Kalbim  ile  yana  yana

Isyan  ettik  bugun  sana

Nasil   care  gelir  bana

Sade  canda  bu  care  var

Gulemedim  aglarim  ben

Caresizce yanarim  ben

Ah  insafsiz vijdansiz sen

Sade  sende  bu  care  var

Yasar  gurlek  14-02-2006

Rotterdam    hollanda', 'KALBIMDE  KARA  KARA Kalbimde  kara  kara Her  sevgiden bir  yara  var Bulun  belki  ara  ara Sade  yarda  bu  care  var Kalbim  ile  yana  ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kalbimde-kara-kara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimdeki O Yeri', 'kalbimdeki-o-yeri-yasar-gurlek-549la', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KALBIMDEKI  O  YERI

Kimseler  alamaz kalbimdeki  o  yeri

Dunyalara  degismem sendeki o  gozleri

Hic  bilmedin  anlamadin nasilda sevmistim seni

Ezrail  canim  alsin operken o  elleri

Almak  ister  hep  guzeller  kalbimdeki  yerini

Hic  birini  kabullenmem bildim senin degerini

Anlamadin tanimadin  nasilda  sevdim  seni

Ezrail  canim  alsin  operken o  gozleri

Taht kurmussun kalbime  senindir o  yerler

Asik yasar perisandir   her seyi  olus  heder

Sevemedin  gulemedin  nasilda  sevdim  seni

Ezrail  canim  alsin   operken   o  dilleri

Yasar  gurlek  14-02-2006

Rotterdam    hollanda', 'KALBIMDEKI  O  YERI Kimseler  alamaz kalbimdeki  o  yeri Dunyalara  degismem sendeki o  gozleri Hic  bilmedin  anlamadin nasilda sevmistim s...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kalbimdeki-o-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ne Verdin', 'sen-ne-verdin-yasar-gurlek-crni9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEN  NE  VERDIN

Neden  askim  dedin  bana

Asik  olsan boyle  olmaz

Ben  canimi  verdim  sana

Sen ne  verdin soyle  bana

Yillardir  yandim  askina

Sevdandan dondum saskina

Yalanin  benzer piskine

Sen  ne  verdin  soyle  bana

Kurumus  bir gulmu  verdin

Yikilinca  elmi  verdin

Su  selime  bentmi  oldun

Sen  ne  verdin  soyle  bana

Aci  zulum  dertten baska

Lanet  olsun  boyle  aska

Sevmeseydim  seni  keske

Sen  ne  verdin  soyle bana

Yasar  gurlek  14-02-2006

Rotterdam    hollanda

Yillardir  aglattin beni oyle  cokki  saymadim

Seneler gecip gitti  hic sana  doyamadim

Bu  dunyada  deli  gonlu  bir tek sana bagladim

Pinar oldum irmak oldum nehir oldum cagladim

Ben  askimi  canimi  sevdami   verdim

Sen  ne  verdin  soyle    bana', 'SEN  NE  VERDIN Neden  askim  dedin  bana Asik  olsan boyle  olmaz Ben  canimi  verdim  sana Sen ne  verdin soyle  bana Yillardir  yandim  a...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-ne-verdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unuturmu', 'seni-unuturmu-mehmet-sait-akkus-5rwdc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acep o gün gelecekmi

Bu göz seni görecekmi

Seviyorum diyecekmi

Unuturmu seni dilim

Oturup sana bakınca

Seni saatler boyunca

Bu gözler sana doyunca

Unuturmu seni gözler

İsmin dilde tezbih olmuş

Sevdan yüreklerde yanmış

Seni sevmek hep daimmiş

Unuturmu seni sevdam

Gülüşüne hayran oldum

Bakışına seyran oldum

Temaşına bizar oldum

Unuturmu seni bakış', 'Acep o gün gelecekmi Bu göz seni görecekmi Seviyorum diyecekmi Unuturmu seni dilim Oturup sana bakınca Seni saatler boyunca Bu gözler sana d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-unuturmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Ülkesi', 'sevda-ulkesi-mehmet-sait-akkus-kq2tq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sevdalar ülkesi

Ssen ise kül kedisi

Eğer kalacak varsa birisi

Sen olacaksın sevdiğim

Sevda ülkesi geniş olur

Türlü türlü yemiş olur

Her daima seviş olur

Tam aradığın yerdir sevdiğim

Sevda ülkesi yaşanmazki

Aramakla bulunmazki

Bu gönül nasıl yanmazki

Senin ateşine sevdiğim

Sevda ülkesi can ciğer

Neler gireceksin neler

Bir gün yaşanmassa eğer

Yokluğundandır sevdiğim

Sevda ülkesini sana adadım

Haberinisana yolladım

Unutmadım kendim imzaladım

Hibem olsun sana sevdiğim', 'Ben sevdalar ülkesi Ssen ise kül kedisi Eğer kalacak varsa birisi Sen olacaksın sevdiğim Sevda ülkesi geniş olur Türlü türlü yemiş olur Her ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevda-ulkesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevdanın Acısı', 'bir-sevdanin-acisi-murat-demir-sobvo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Diş ağrısı gibiymiş senin derdini çekmek

Ellerimle başımı tuttukça yere çökmek

Bu aşkı yüreğimden kolay olsaydı sökmek

Bir saniye durmazdım, bir saniye inan ki

Tattıkça zehirliyor tadına yandığım bal

Tutmadan kırılıyor tutunacağım her dal

Seni asla, bilseydim yok eder beni bu hal

Bir saniye sormazdım, bir saniye inan ki

Gönül nasıl bir şeyse vazgeçmiyor sevdimi

Dikeni gül sanıyor aşk atına bindimi

Oysa, ben senin için şu zavallı kalbimi

Bir saniye yormazdım, bir saniye inan ki

Başta ki dumanlı yel nasıl eserse essin

Abdallaşınca insan sormuyor kimsin, nesin

Gücüm yetseydi seni,deyip birtanem sensin

Bir saniye sarmazdım, bir saniye inan ki', 'Diş ağrısı gibiymiş senin derdini çekmek Ellerimle başımı tuttukça yere çökmek Bu aşkı yüreğimden kolay olsaydı sökmek Bir saniye durmazdım,...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sevdanin-acisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kış Günüydü', 'bir-kis-gunuydu-munevver-duver-h1fpp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yirmi yedi Kasım’dı ayrıldım senden 

Bir kış günüydü vuruldum, kalbimden 

Bir demet koparıp, verdi bana gülden

Yirmi yedi Kasım’dı, ayrıldım senden

Senin acın saplandı yüreğime

Gittiğin günden beri, zehir kattın yemeğime

Seni yazdım ben kaderime, 

Yirmi yedi Kasım’dı, ayrıldım senden

Devlet seni, kopardı benden

Ama ben hazırdım buna, taa dünden

Ayrılığın zor olduğunu bilirdik önceden

Yirmi yedi Kasım’dı, ayrıldım senden

Bilmiyorum bensiz orada mutlu musun? 

İnan ben sensiz, çok mutsuzum

Senin sevginle sonsuzum

Yirmi yedi Kasım’dı, ayrıldım senden

Mesken mi tuttun gurbet eli

Bense burada oldum bir deli

Hiç dinmedi, akıttım gözüm seli

Yirmi yedi Kasım’dı, ayrıldım senden

Hasret kaldım sana kaç gündür 

İzine gel de, bari; yüzümü güldür

Ayrılık ateşini bir günde söndür

Yirmi yedi Kasım’dı, ayrıldım senden

Pencereye çıktığımda, hayalini görüyorum

Karşıdasındır diye binayı süzüyorum

Her an senin orada olduğunu seziyorum

Yirmi yedi Kasım’dı, ayrıldım senden

Sevdiğin yokluğuna dayanamaz

Çevreden gelen dedikodulara inanmaz

Umarım yakında bir daha ayrılık olmaz

Yirmi yedi Kasım’dı, ayrıldım senden 

27/11/1990 -saat:12.47 

Büro 

Güneyin Kızı', 'Yirmi yedi Kasım’dı ayrıldım senden  Bir kış günüydü vuruldum, kalbimden  Bir demet koparıp, verdi bana gülden Yirmi yedi Kasım’dı, ayrıldım...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-kis-gunuydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haçlı', 'hacli-halil-colak-39jiq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SeniAradım insanlığın satırları arasında çok aradım  haçlı

Ne kadar aradımsa adalet içerisin de bulamadım da seni

Kaybolmuş gitmişsin nereye de gittiğinde belli de değil

Sayfaları da tekrar çevirdim insanlığın içerindedir belki 

Düşmüşsün tarihin bir çukuruna süslemişsin de içerisini

Halil Çolak 15.2.2006 Ankara', 'SeniAradım insanlığın satırları arasında çok aradım  haçlı Ne kadar aradımsa adalet içerisin de bulamadım da seni Kaybolmuş gitmişsin nereye...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hacli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Efsanevi Aşkımızın Sonunda', 'bu-efsanevi-askimizin-sonunda-huseyin-erdogan-f2q6i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her sabah

gün doğarken sabahlarıma

ilk sen düşersin aklıma

bir hüzün dolar dünyama

yokluğun ok gibi saplanır bağrıma

kan gelmez olur damarlarıma

ah! sevdiğim,sevgili şiirim

bir gün çıkıp gelsen de yanıma

hasretimiz bitse bu dünyada

yoksa seninle mahşeri bekleyeceğiz

hem de ömrümüz boyunca

ben razıyım buna da

yeter ki beni sensiz bırakma

hayallerimde rüyamda olsa da

sen de beni yüreğinde sakla

sakın beni üşütme orada

bil ki sevgindir can veren bana

ne de güzel olurdu inan

muhteşem bir kavuşma olsa

bu efsanevi aşkımızın sonunda

öyle değil mi sevgili cana? 

söyle sen ne dersin buna? 

keşke keşke şairim diyorsan eğer

haydi o güzel ellerini uzat bana

mahşerde bile bırakma bir daha

                              15.02.2006

                          Hüseyin Erdoğan', 'her sabah gün doğarken sabahlarıma ilk sen düşersin aklıma bir hüzün dolar dünyama yokluğun ok gibi saplanır bağrıma kan gelmez olur damarla...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bu-efsanevi-askimizin-sonunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkınızı Helal Edin', 'hakkinizi-helal-edin-sahin-yilmaz-ix2pj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '…….Filistin ve Irak’ta zulüm gören kardeşlerime

Kalp mühürlü, kulak sağır duyamam,

Farzet kıyametin ortasındayım,       

Hakkınızı helal edin diyemem,

*İmanın en zayıf noktasındayım.

Kötülüğü kovamadım elimle,

Yerden yere vuramadım dilimle,

Ancak buğuz ettim kendi halimle,

İmanın en zayıf noktasındayım.

Sen üşüdün, ben sıcakta terledim,

Sen işkence gördün, bense horladım,

Yalnız kendi nefsim içim gürledim,

İmanın en zayıf noktasındayım.

Zulme “yeter” diyen adam çıkmadı,

Sözde Müslümanlar dönüp bakmadı,

Sen vuruldun benim kanım akmadı,

İmanın en zayıf noktasındayım.

Kafasız tavuğa benzer halimiz,

Ne yönedir, belli değil yolumuz,

Kardeşine uzanmıyor kolumuz,

İmanın en zayıf noktasındayım.

Birkaç milyon krediye satıldık,

Yağmurdan kaçarken kara tutulduk,

Bomba olduk üstünüze atıldık,

İmanın en zayıf noktasındayım.

Beş vakitle kendimizi avuttuk,

Müminler kardeşti, çabuk unuttuk,

Kâfirlere yaren olduk, dost tuttuk,

İmanın en zayıf noktasındayım.

Liderler Amerikan patentli çıktı,

Her birisi kovboy şapkası taktı,

Ne yapayım, balık başından koktu,

İmanın en zayıf noktasındayım.

Yeryüzünden arşa kadar günahım,

Medet ey sultanım, medet ey şahım,

Kulluk edemedik, affet Allah’ım,

İmanın en zayıf noktasındayım.

*Bir kötülük gördüğünüzde elinizle, olmazsa dilinizle defediniz. O da olmazsa kalbinizle buğzediniz. Bu imanın en zayıf olanıdır. Hadis-i Şerif.', '…….Filistin ve Irak’ta zulüm gören kardeşlerime Kalp mühürlü, kulak sağır duyamam, Farzet kıyametin ortasındayım,        Hakkınızı helal edi...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hakkinizi-helal-edin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil', 'dil-nizamettin-ozel-lwjyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül girdi araya,

Beni sevdirdi dil.

Padişah eyledi dünyaya; 

Vallahi yalan değil.

Kurutup hep kanları,

Avucuma bıraktı canları.

Peşime takıp insanları; 

Vilayet vilayet, il il...', 'Gönül girdi araya, Beni sevdirdi dil. Padişah eyledi dünyaya;  Vallahi yalan değil. Kurutup hep kanları, Avucuma bıraktı canları. Peşime tak...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dil-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Azrail', 'ey-azrail-nizamettin-ozel-obnea', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey Azrail, uzun etme; 

Alacağın bir can işte.

Ne zaman gelirsen gel,

Hemen veririm, yeter ki iste.

Kaçanda yok, korkanda; 

Sen sade kapımı çal.

O dakika açarım anında,

Yalnız ruhumu acıtmadan al...', 'Ey Azrail, uzun etme;  Alacağın bir can işte. Ne zaman gelirsen gel, Hemen veririm, yeter ki iste. Kaçanda yok, korkanda;  Sen sade kapımı ç...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ey-azrail-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mapus Damı', 'mapus-dami-nizamettin-ozel-0xj92', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suçluydu; 

          Bir cana kıymıştı.

Pişmandı, ağlıyordu,

          Dört duvarla bakıştı.

Onbeş sene; 

          Daracık bir kafeste.

Bir sıgara yaktı; 

          İçine çekti bir nefeste.

Gençti üstelik,

         Hayatının baharında.

Çürüyüp gidecekti; 

         Yaşı otuzbeşe vardığında...', 'Suçluydu;            Bir cana kıymıştı. Pişmandı, ağlıyordu,           Dört duvarla bakıştı. Onbeş sene;            Daracık bir kafeste. Bir...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mapus-dami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kün', 'kun-nizamettin-ozel-t9gj6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evreni gören iki gözünü,

Söyle kimdir, sana veren.

Yıldızlarla süsledi gökyüzünü; 

Bir “ol” emriyle hemen.

Evreni işiten iki kulağı,

Koklayan burnu, konuşan dudağı,

Kim yarattı, sendeki eli ayağı; 

Bir “ol” emri ile hemen.

Kemiklerimize et giydiren O; 

Sizlere kendini sevdiren O.

Yedirip içiren, yaşatıp öldüren O; 

Bir “ol” emriyle hemen...', 'Evreni gören iki gözünü, Söyle kimdir, sana veren. Yıldızlarla süsledi gökyüzünü;  Bir “ol” emriyle hemen. Evreni işiten iki kulağı, Koklaya...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesbit', 'tesbit-nizamettin-ozel-3essn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sayısız dağlar aştım, yalın ayak; 

İnsanlar tanıdım, sayısız çoklukta.

Şehirlerini gezdim, sokak sokak; 

Birkaçı dışında hepsi yoklukta.

Doyurmuyor artık, yiyecekler insanları; 

Isıtmıyor giysiler, üşüyen bedenleri.

Zalim rejimleri ve komuta edenleri; 

“Öl” dese, ölecekler bir buyrukta...', 'Sayısız dağlar aştım, yalın ayak;  İnsanlar tanıdım, sayısız çoklukta. Şehirlerini gezdim, sokak sokak;  Birkaçı dışında hepsi yoklukta. Doy...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tesbit-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormayın Dostlar', 'sormayin-dostlar-mustafa-bilgili-28spn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Derdimi bu gün hiç sormayın dostlar,

Üzerimdeki şu yükü taşıyamıyorum,

Allah takdir etmiş yaratmış ama,

Gelin görün şu halimi yaşamıyorum.

Dert çekmeye mi geldim fani dünyaya,

Bazen atlı gittimse,çok zaman yaya,

Yüreğimdeki acılar   olmuş bir kaya,

Kükremiş sel gibiyim taşamıyorum.

Dizlerim bu bedenimi taşımaz oldu,

Büyüttüğüm güllerim,elimde soldu,

Bu günlerde bana bir şeyler oldu,

Etrafıma set örmüşler,aşamıyorum.

Acılar sıralanmış hep katar katar,

Yüreğimde aşk değil,acılar yatar,

Yoruldum  dertlerden,ne olur yeter,

Kaçmak istiyorum ama koşamıyorum.

Şu yalancı dünya da acı olmasa,

Arayıp en sonunda beni bulmasa,

Giden mühür gözlüm geri gelmese,

Kederim çok büyük,coşamıyorum.

                                                 24.12.1996', 'Derdimi bu gün hiç sormayın dostlar, Üzerimdeki şu yükü taşıyamıyorum, Allah takdir etmiş yaratmış ama, Gelin görün şu halimi yaşamıyorum. D...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sormayin-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanç', 'utanc-nizamettin-ozel-xsed0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu dağların yüksek yamacı,

Boyanmış kardan beyaza.

Yürekte taşıdığım bu utancı,

Bitiremedim yaza yaza.

Çiğdem olurmuş bu karda,

Görmedim sağa sola bakarda.

Bu dert beni yakarda; 

Bitmez yine, çektiğim ceza.

Tek çözüm diye kaçmak,

Biraz yol alıp, sonra durmak; 

Burası şehirden çok uzak,

İsmini bildiğim bir kaza...', 'Şu dağların yüksek yamacı, Boyanmış kardan beyaza. Yürekte taşıdığım bu utancı, Bitiremedim yaza yaza. Çiğdem olurmuş bu karda, Görmedim sağ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/utanc-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sodom ve Gomore', 'sodom-ve-gomore-timur-i-likan-6svow', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Erkekleşen kadınlar

Kadınlaşan erkekler

İnsanlar çıkmış çığrından

Dünyâ dönmüş tersine

Başımıza taş yağacak taş

Bu işin sonu yaş mı yaş

Yaklaşıyoruz kıyâmete

Hepbirlikte yavaş yavaş

(15 Şubat 2006/ İstanbul)', 'Erkekleşen kadınlar Kadınlaşan erkekler İnsanlar çıkmış çığrından Dünyâ dönmüş tersine Başımıza taş yağacak taş Bu işin sonu yaş mı yaş Yakl...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sodom-ve-gomore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap', 'sarap-guler-ilgaz-prur5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şarap içmek istiyorum bu gece

Üzüm olarak uyanabilmek için içinde

Kim kimin yüzünü boyuyor

Gece mi gündüzün

Gündüz mü gecenin

Bilmek için

İçimde', 'Şarap içmek istiyorum bu gece Üzüm olarak uyanabilmek için içinde Kim kimin yüzünü boyuyor Gece mi gündüzün Gündüz mü gecenin Bilmek için İç...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sarap-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşümeden Aşık Olunmaz', 'usumeden-asik-olunmaz-hicret-katirci-z7cgt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her üşüdüğümde sen geliyorsun aklıma,

Sarılsam, yapışsam bembeyaz tenine,

Darmadağın olsam ateşinden, açılsam,

Bilmem severmiydin? istermiydin yine? 

Şöyle bir göz atıyorum çevreye,

Senin beyazlığın gibi bembeyaz,

Her şey seni anlatıyor bana,

İçimdeki dünya, çok benziyor sana.

Üşümekle aşk arasında kaldım ben,

Nereye baksam her yerde sen,

Soğuk ve uzun kış gecelerinde bile,

Seninle olmak seni yaşamak ne güzel.', 'Her üşüdüğümde sen geliyorsun aklıma, Sarılsam, yapışsam bembeyaz tenine, Darmadağın olsam ateşinden, açılsam, Bilmem severmiydin? istermiyd...', ARRAY['Türk Edebiyatı','Şiir','Hicret Katırcı']::text[], 8.5, '{"poet":"Hicret Katırcı","poet_slug":"hicret-katirci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/usumeden-asik-olunmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-nizamettin-ozel-nk4gb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Savaş çetin geçti,

Ölenler oldu,

Sakat kalanlar.

Kan gölüne döndü; 

Dümdüz alanlar.

Ana oğlunu yitirdi,

Kadın kocasını.

Minicik çocuklar,

Yüreklerine gömdü; 

Baba acısını.

Benim anlamadığım,

Kimin kimle,

Alıp veremediği.

Mutlu bir hayat; 

Herkesin istediği.

Öyleyse neden? 

Neden bu savaşlar.

Daha çok erken,

Ölmek için,

Yirmisinde yaşlar...', 'Savaş çetin geçti, Ölenler oldu, Sakat kalanlar. Kan gölüne döndü;  Dümdüz alanlar. Ana oğlunu yitirdi, Kadın kocasını. Minicik çocuklar, Yü...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/savas-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadar', 'o-kadar-ayca-yesim-lzi8p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar uzattıysam sana kollarımı

Bana sen o kadar uzak

Boğulurdum biraz daha her damlada

Sense biraz daha uzak sularda

O kadar üşüyorum şimdi tam

Kolların ne kadar sıcaksa', 'Ne kadar uzattıysam sana kollarımı Bana sen o kadar uzak Boğulurdum biraz daha her damlada Sense biraz daha uzak sularda O kadar üşüyorum şi...', ARRAY['Türk Edebiyatı','Şiir','Ayça Yeşim']::text[], 8.5, '{"poet":"Ayça Yeşim","poet_slug":"ayca-yesim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/o-kadar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-nizamettin-ozel-yglad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlar soğuktu, 

Bir o kadar da yüksek.

Bir tipi tuttu,

Başımıza taş gibi iniyordu,

Biraz yürüsek.

Geceleri yol alıp,

Gündüzleri saklanıyorduk.

Şehirdeki çaresizlere bakıp,

Köle oluşlarına üzülerek,

Topluca ağlıyorduk.

Belki de kaçmak,

Bize yakışmıyordu böyle.

Ama kadınlar gibi ağlamak,

İşte o öldürüyordu.

Ya özgür kalacaktık, ya köle; 

İyi mi yaptık, kötü mü, 

Gerisini sen söyle...', 'Dağlar soğuktu,  Bir o kadar da yüksek. Bir tipi tuttu, Başımıza taş gibi iniyordu, Biraz yürüsek. Geceleri yol alıp, Gündüzleri saklanıyord...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kacis-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kütahyanın Pınarıyım', 'kutahyanin-pinariyim-sahin-erturk-kl413', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kütahyanın pınarıyım

Sevgi olup akıyorum

Uzat güzel yüreğini

Sevgim ile doldurayım

Dertlere ŞİFA dır sevgim

(15.02.2006-Yeni)', 'Kütahyanın pınarıyım Sevgi olup akıyorum Uzat güzel yüreğini Sevgim ile doldurayım Dertlere ŞİFA dır sevgim (15.02.2006-Yeni)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kutahyanin-pinariyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkmenleriz', 'turkmenleriz-husam-hasret-yhifg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sümerlerden bu güne dek

Yaşadık ki başı yüksek

Bizler doğru, bizler gerçek

Belli başlı Türkmenleriz

Şanımızı öğe öğe

Dik başımız değer göğe

Bizimdir bu yurt bu bölge

Tarih yaşlı Türkmenleriz

Gönlümüz bir ak güvercin

Barış sağlar için için

Düşmanı da yakmak için

Gür ateşli Türkmenleriz

Bir gün belli, bir gün gizli

Davamızı kıldık hızlı

Bayrağımız ay yıldızlı

Hem güneşli Türkmenleriz', 'Sümerlerden bu güne dek Yaşadık ki başı yüksek Bizler doğru, bizler gerçek Belli başlı Türkmenleriz Şanımızı öğe öğe Dik başımız değer göğe ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turkmenleriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Şimdi Aşk Yazamam', 'sana-simdi-ask-yazamam-sami-ulug-3s1oy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana şimdi aşk yazamam

omuzlarına taht kurmuş melekleri

adın diye yazamam

yazamam

her kayan yıldızın 

sana dilek tutulduğunu

bir gözünde ay

bir gözünde güneş tutulduğunu

yazamam

sana şimdi aşk yazamam

aslı olmasa da leylanın

dağda ferhat çölde destan 

yazamam

yazamam

her doğan çocuğa

senin adının konulduğunu

fuzuli''nin baki''nin nedim''in

seni yazmak için

cennetten kovulduğunu

yazamam

sana şimdi aşk yazamam

kalemlerin saf tuttuğu kağıtlara

ilahi tarifini yazamam

yazamam

gülleri çatlatan dudaklarına

bülbüllerin vurulduğunu

bir gülüşünle

ayaklarına mahşerin kurulduğunu

yazamam', 'sana şimdi aşk yazamam omuzlarına taht kurmuş melekleri adın diye yazamam yazamam her kayan yıldızın  sana dilek tutulduğunu bir gözünde ay ...', ARRAY['Türk Edebiyatı','Şiir','Sami Uluğ']::text[], 8.5, '{"poet":"Sami Uluğ","poet_slug":"sami-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sana-simdi-ask-yazamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taze Aşkım', 'taze-askim-sahin-erturk-kfgxk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akla dolsa,,İPEK SAÇIN

Kırka varsa,OLGUN YAŞIN

Başkasına,DÖNMEZ BAŞIM

Sensin benim,TAZE AŞKIM

(...Eşime...)

(15.02.2006) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Akla dolsa,,İPEK SAÇIN Kırka varsa,OLGUN YAŞIN Başkasına,DÖNMEZ BAŞIM Sensin benim,TAZE AŞKIM (...Eşime...) (15.02.2006)  KARABORSA SEVGİ ad...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/taze-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Yeri', 'koy-yeri-nizamettin-ozel-1cmr6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Köy yeri,

Ne ayakkabı var,

Ne pantolon,

Ne gömlek,

Ne de ceket.

Üstümde kokan,

Parfüm değil,

Tezek! 

Yine de, yine de; 

Alay etme giysimle,

Alay etme sesimle; 

Burun burunayız,

Her gün ölümle.

Görmezlikten gel,

Suyu temiz de,

Havası güzel.

Ekmeğimizi ye,

Ayranımızı iç.

Ama bizi hor görme,

Eksik olmaz burada,

Bit-pire.

Anlaşılan sen buranın,

Adamı değilsin,

Heydi dön şehire...', 'Köy yeri, Ne ayakkabı var, Ne pantolon, Ne gömlek, Ne de ceket. Üstümde kokan, Parfüm değil, Tezek!  Yine de, yine de;  Alay etme giysimle, ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/koy-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda..', 'yoklugunda-reside-coskun-hjhun', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen kaldınmı,benim uzaklarımda,

Gündüzlerim karanlık,gecelerim zifiri,

Attığım adımlar ise tuzak bana...

Kar yağdımı,kapattımı senin yollarını,

Yağmurlar yağar,aynı anda,

Benim çatlamış topraklarıma...

Günler,haftalar anlamını yitirdimi,sensizlik ağında,

Ondan sonra başlar,

Son bulmayan sonbaharlar,hiç gelmeyen ilkbaharlar...

Ben hiç sönmeyen bir ateşte yanarken,

Sen küllerimden doğsan ne yazar...', 'Sen kaldınmı,benim uzaklarımda, Gündüzlerim karanlık,gecelerim zifiri, Attığım adımlar ise tuzak bana... Kar yağdımı,kapattımı senin yolları...', ARRAY['Türk Edebiyatı','Şiir','Reşide Coşkun']::text[], 8.5, '{"poet":"Reşide Coşkun","poet_slug":"reside-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yoklugunda-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmaz Barut Gibi', 'yanmaz-barut-gibi-sahin-erturk-nvf70', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sorma nasıl durumum

Sanma seni unuttum

Hasretinle dağıttım

Yanmaz barut gibiyim

Ciğerlerim yanıyor

Ayaklarım tutmuyor

Kalbim her gün tekliyor

Yanmaz barut gibiyim

Benziyorsam deliye

Zararım yok kimseye

Ben kendimi tükettim

Yanmaz barut gibiyim

Yalnızlığı sırtlandım

İnan seni kıskandım

Gözyaşımla ıslandım

Yanmaz barut gibiyim

(15.02.2006)', 'Sorma nasıl durumum Sanma seni unuttum Hasretinle dağıttım Yanmaz barut gibiyim Ciğerlerim yanıyor Ayaklarım tutmuyor Kalbim her gün tekliyo...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanmaz-barut-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü', 'olu-nizamettin-ozel-9fn0s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vur, sende vur; 

Kanasın ki bu yürek,

Kapanmasın bu yara; 

Ta ki, ölene dek...

İster silah,

İstersen sopa.

Kimse görmesin bu halimi; 

Bütün kapıları kapa...

Unutmayı denedim,

Olmadı bir türlü.

Sen mutlu ol yeter ki; 

Ben yaşayan ölü...', 'Vur, sende vur;  Kanasın ki bu yürek, Kapanmasın bu yara;  Ta ki, ölene dek... İster silah, İstersen sopa. Kimse görmesin bu halimi;  Bütün ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olabilsen', 'olabilsen-nizamettin-ozel-bx67a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasılda düştüm ağına,

Ferhat gibi ağlamak...

Kolay mı elin dağına,

Kazma kürek sallamak.

Olabilsen sen, o Şirin,

Olabilsem, ben o Ferhat.

Sonu gelmezdi şiirin,

Sen rahat, ben rahat...', 'Nasılda düştüm ağına, Ferhat gibi ağlamak... Kolay mı elin dağına, Kazma kürek sallamak. Olabilsen sen, o Şirin, Olabilsem, ben o Ferhat. So...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olabilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeçen Destanı', 'cecen-destani-nizamettin-ozel-o4ly7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cephelere düştü gönlüm,

Top seslerine, insan çığlıklarına.

Yakın diyorum, bana ölüm; 

Bugün değilse bile, yarına...

Çocukların minicik elleri var,

Cephane taşır, silah tutar.

Meydan okur, zafere kadar,

Dağın onca soğuğuna, karına...

Ağlaşır hep sakallı dedeler,

Toprakta başsız gövdeler.

Kimi sıcak yuvasında, evdeler; 

Kimi yol alır, şehitler diyarına...', 'Cephelere düştü gönlüm, Top seslerine, insan çığlıklarına. Yakın diyorum, bana ölüm;  Bugün değilse bile, yarına... Çocukların minicik eller...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cecen-destani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastane', 'hastane-nizamettin-ozel-vhwd2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlayanı, sızlayanı; 

Öleni yüteni, hep burda.

Şu can pazarını,

Seyret biraz durda...

Kiminin baş ağrısı,

Kiminin derin yarası.

Olunca trafik kazası,

İnsanlar birer hurda! 

Doktor, hemşire tamirde,

Makası, neşteri elinde.

Beklerim eli belinde,

Gündüz gece olurda...', 'Ağlayanı, sızlayanı;  Öleni yüteni, hep burda. Şu can pazarını, Seyret biraz durda... Kiminin baş ağrısı, Kiminin derin yarası. Olunca trafi...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hastane-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köprü', 'kopru-nizamettin-ozel-frsu6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aramızda koca nehir,

              Dost ağlar,

              Düşman güler.

Dediler kan davası! 

              Bir sizden,

              Bir bizden öldüler.

Kurulamadı bir türlü,

              Kurulamadı işte,

              Gönülden gönüle köprüler...', 'Aramızda koca nehir,               Dost ağlar,               Düşman güler. Dediler kan davası!                Bir sizden,               Bir ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kopru-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedava', 'bedava-gulseren-kuddar-p6wzv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir papatyayım yabanda

Ağaçların dibinde ot,tarlada başak,

Serada meyve sebze

Dikenlerimi söktüm batmasın ellerinize

Sokaklarda taş toprak,

Ev yapın tuğlalarımdan,

Elbise dikin kumaşlarımdan,

Aşıklar güneşimde sarılsın birbirine,gölgemde dinlensin, Çeşmemde su içsin yabancılar

Denizlerde çırpınan dalgayım,

Sevenler kavuşsun limanlarımda,

Martılar sesleriyle şarkı söylesin etrafımda

Ben kocaman ormanda  sade bir gülüm,

Alın koparın gönlümden bitmeyen sevgimi,

Hepinize bedava.

08-06-2003', 'Ben bir papatyayım yabanda Ağaçların dibinde ot,tarlada başak, Serada meyve sebze Dikenlerimi söktüm batmasın ellerinize Sokaklarda taş topr...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Kuddar']::text[], 8.5, '{"poet":"Gülseren Kuddar","poet_slug":"gulseren-kuddar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bedava-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert Etmem', 'dert-etmem-nizamettin-ozel-iwbsv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adım adım ilerliyorum,

                    Sonu gelmez,

                     Bir yolda...

Kır zincirlerimi,

                    Akın et üzerime,

                     Ten olda...

Dert etmem, hiçbir şeyi; 

                     Dert etmem,

                     Sen olda...', 'Adım adım ilerliyorum,                     Sonu gelmez,                      Bir yolda... Kır zincirlerimi,                     Akın et üzer...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dert-etmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gümüş Yüzük', 'gumus-yuzuk-nizamettin-ozel-ewgf3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Amcam Ali ÜSTÜN’ün hatırasına) 

Ani bir gürültü, ve de sesler; 

Sokakta insanlar çığlık çığlığa.

Hepsinde panik, hıp hızlı nefesler; 

Bir çırpıda koştum kalabalığa.

Baktım ki, yerde yatıyor Ali amca,

Cansız gözlerle, bana bakan.

Dayandığı baston kaydı kanımca,

Alnında ve ağzında hep kan.

Hemen acilen bir araba buldum,

Gittik, elimde eriye eriye.

Kolumu başının altına koydum; 

Son sürat girdik içeriye...

Dışarıda beklettiler bir müddet,

Duvarları yumrukladım habire.

Kala kaldık bir ben, bir ceset; 

Dediler önce morg’a, sonra kabire.

Kalkar da ayağa, vedalaşırız diye,

Son kez sarıldım, moraran deriye.

Bir gümüş yüzük, bir oltu tesbih; 

Bir de köstek saat çıktı,

                Bütün ceblerinden geriye...', '(Amcam Ali ÜSTÜN’ün hatırasına)  Ani bir gürültü, ve de sesler;  Sokakta insanlar çığlık çığlığa. Hepsinde panik, hıp hızlı nefesler;  Bir ç...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gumus-yuzuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-nizamettin-ozel-nuvp3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göçmen kuşlar gibi,

Ayrılışın; 

Yürekten gidişin,

Bir veda bile etmeden.

Söyle niçin? 

Söyle neden? 

Acını mı paylaşmadım,

Oturup mu ağlaşmadım.

Bir bahane göster,

Tek bir neden? 

Çeker giderim sonra,

Uzaklaşırım senden.

Bir daha görmezsin,

Yaşadığımı bile bilmezsin.

Gel hele, gel; 

Söyle neden? 

Niçin kaçıyorsun? 

Köşe bucak benden...', 'Göçmen kuşlar gibi, Ayrılışın;  Yürekten gidişin, Bir veda bile etmeden. Söyle niçin?  Söyle neden?  Acını mı paylaşmadım, Oturup mu ağlaşma...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neden-222-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağma Kar', 'yagma-kar-cengiz-kapusuz-v6dyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağma kar! 

Yağma artık.

Yağma ne olur,

Çünkü, kafam bozuk.

Dün sevdama ulaşamadım,

Birde yağıp da,

Yollarımı kapatma.

Dertlendim! 

Sabahlara kadar uyuyamadım.

Ne olur yağma,

Sevdama ulaşamadım.

Yağma! 

Yanımda yok sevdam.

Yağma! 

Üşüyorum ısınamam.

Aslında sana değil sızlanmam,

Yanlış anlama,

Yağsan da

Yağmasan da,

Yanımda yok SEVDAM.', 'Yağma kar!  Yağma artık. Yağma ne olur, Çünkü, kafam bozuk. Dün sevdama ulaşamadım, Birde yağıp da, Yollarımı kapatma. Dertlendim!  Sabahlar...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yagma-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşe Atmayın Gençliği', 'atese-atmayin-gencligi-nizamettin-ozel-euomz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaybettiğimiz şeylere bir bakın; 

Din, kültür, örf, adet, töre...

Batının küflü değerlerini bırakın,

Ateşe atmayın gençliği, göz göre göre...

Yardım edelim birbirimize hep; 

Özümüze dönelim biz, aslımıza...

Sevgi saygı diyelim erkeğe, edep,

Namus haya diyelim, genç kıza...', 'Kaybettiğimiz şeylere bir bakın;  Din, kültür, örf, adet, töre... Batının küflü değerlerini bırakın, Ateşe atmayın gençliği, göz göre göre.....', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/atese-atmayin-gencligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acziyet', 'acziyet-nizamettin-ozel-cekgq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çölde kum tanesiyim,

Sayılmazda sayı.

Yada bir yıldızım; 

Düşün sonsuz uzayı...

Kocaman ummanda,

Bir zerreyim sade.

Senden aldığımı; 

Sana ediyorum iade...

Bir köhne gemi gibi,

Yol alırım hep aynı rotada.

Ey kainatın sahibi; 

Acizliğim işte ortada...', 'Çölde kum tanesiyim, Sayılmazda sayı. Yada bir yıldızım;  Düşün sonsuz uzayı... Kocaman ummanda, Bir zerreyim sade. Senden aldığımı;  Sana e...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acziyet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçki İçmedim Anne', 'i-cki-i-cmedim-anne-hidir-altas-gtzaf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün bir partiye gittim anne,bana öğütlerinaklımdaydı

İçki içme yavrum demiştin,yalnızca soda içtim anne

Dediğini yaptığım için içim gururla doluydu

Diğerlerine benzemedim ve İÇKİLİ ARABA KULLANMADIM

Ben doğru olanı yaptım  anne, tıpkı senin dediğin gibi

Şimdi parti sona eriyor anne tam yola çıkacaktım

Diğer arabacı beni görmedi anne, bana bir eşya gibi çarptı

Kaldırımda uzanmış yatarken yaralı

Polisin ''bu çocuk sarhoş dediğini duydum anne

Bana çarpan sarhoşsa onun hatasını benmi ödeyeceğim anne? 

Burada ölüyorum anne, hayatım bir balon gibi sönecekmi? 

Etraf kan dolu anne, benim kanımla

Hissediyorum birazdan öleceğim

Sana son bir şey söylemek istiyorum anne

Yemin ederim hiç içmedim

İçen ben değil onlardı anne.........

Galiba bana çarpanla aynı partideydik

Tek fark;  o sadece sarhoş bense ölüyorum anne

İnsanlar neden içer anne? ? ? ? ? 

Şimdi keskin bir acı duyuyorum, tıpkı bıçak gibi

Bana çarpan yürüyor, görüyorum; bu haksızlık

Kardeşime söyle ağlamasın, babama söyle cesur olsun

Bu hazin vakayı yazan aykaranlık şiir grubundaki vatan_askina rumuzlu hanımefendiye teşekkür ederim. Bütün antolojideki dostların sayfalarına eklemelerini temenni ediyorum. Akdenizin parlayan yıldızı Aşık Turhani', 'Dün bir partiye gittim anne,bana öğütlerinaklımdaydı İçki içme yavrum demiştin,yalnızca soda içtim anne Dediğini yaptığım için içim gururla ...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/icki-icmedim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-nuray-acar-bbqbw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özel bir gün olması için beklemek niye

O gün gelmeyecek belki de 

Ne bizim için bize 

Ne de bizim yakın çevremize

Dünya böylesi kan gölüne dönüşmüşken

Beklemek niye

Günü sınırlamak  çabası içindeki

Şaşkın zihniyetimize', 'Özel bir gün olması için beklemek niye O gün gelmeyecek belki de  Ne bizim için bize  Ne de bizim yakın çevremize Dünya böylesi kan gölüne d...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/o-gun-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Tane', 'bes-tane-nizamettin-ozel-jfzc4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kızına sordu anne; 

Kızım: “seviyor musun beni”.

Cevap verdi kızı,

“Seviyorum anne,

               Hem de beş tane”...

Oğluna sordu baba; 

Oğlum: “Seviyor musun beni”.

Cevap verdi oğlu,

“Seviyorum baba,

                Alırsan oyuncak araba”...', 'Kızına sordu anne;  Kızım: “seviyor musun beni”. Cevap verdi kızı, “Seviyorum anne,                Hem de beş tane”... Oğluna sordu baba;  O...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bes-tane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''na', 'o-na-nizamettin-ozel-ghvkf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kavuşmak rakam hesabı,

Bir’den on’a...

Bir, iki, üç, dört, beş,

Altı, yedi, sekiz, dokuz...

Geldim On’a

Evde bulamadım...', 'Kavuşmak rakam hesabı, Bir’den on’a... Bir, iki, üç, dört, beş, Altı, yedi, sekiz, dokuz... Geldim On’a Evde bulamadım......', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/o-na-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez ki', 'yetmez-ki-ali-aldemir-mr6o3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün dinlemiş,

Gerçek üstü masallar

Masalcı dedelerden! 

Bizden öncekiler

Patlarca alkış tutmuş avuçlar

Tıpkı biz gibi

Kolonlanmışız sanki 

Yirmi üç Nisan çocukları misali

Ey halkım, 

   Senin aklın ermez! 

       Sen düşünme! 

         Gerek yok senin düşünmene! 

En iyisini büyüklerimiz bilir

Ve bizden iyi düşünür geleceğimizi! 

Sen uyu! Uyu ey halkım 

Üç büyükleri bil, onları düşün

Sonra totoyu, lotoyu yetmez.

Altılı ganyan, bir de altı kırk dokuz

Milyarları düşün, trilyonları

Hadi bir kolonda beş artı bir

Yetmez ki oda

Milli piyangosu var daha sıra da 

   Umut et ey hallkım 

      Umut et

Unutma hemen kazanı

Bunlardan birşey çıkmadı mı

Aldırma ey halkım koyver gitsin 

Üzüldüğün şeye bak

Daha neler yok ki 

Popstar m, megastar mı,

Kim beşyüz milyar ister mi 

Seç, seç dene

Olmadı mı o da

Yeşil sahalar, baktın birşey yok

Ne güne duruyor Yeşilçam

Dert etme  kendine, düşünme,

Düşünme sen ey halkım! 

Rahatça koyabilirsin

Her akşam  başını

İyi rüyalar

Nasıl sa hastalık, dert

Uğramaz semtimize

Boş ver tarımı, teknolojiyi

İki öküzlü karasaban

Neyimize yetmez ki! 

Geç bir kalem bunları

Öğretmeni, doktoru

Sonra hastaneyi, okulu

Bir sürü alaylımız var ya

Ne gerek var eğitime 

Düşünme sen ey halkım düşünme! 

Dert etme bütün bunları kendine

İki üfürük

Bir de muska

Yeter de, artar bize!', 'Dün dinlemiş, Gerçek üstü masallar Masalcı dedelerden!  Bizden öncekiler Patlarca alkış tutmuş avuçlar Tıpkı biz gibi Kolonlanmışız sanki  Y...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/yetmez-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm Ben', 'olurum-ben-nizamettin-ozel-col9b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçarım ben,

          Kanatlı kuş gibi gökyüzünde.

Bir umut görürüm hep; 

          Senin o melek yüzünde...

Ölürüm ben,

          Azrail yolumu dahi kesmeden.

Kaçıp giderim ha; 

          Rüzgar bile esmeden...

Ağlarım ben,

          Karanlıkta gece yarıları yalnız.

Düşümde görürüm seni; 

          Semadan kayarken bir yıldız...

Düşünürüm ben,

          Sadece ama sadece seni.

Hep sen sanırım; 

          Peşimden ayrılmayan gölgeni...', 'Uçarım ben,           Kanatlı kuş gibi gökyüzünde. Bir umut görürüm hep;            Senin o melek yüzünde... Ölürüm ben,           Azrail yo...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olurum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Toplumun Gerçeği', 'bu-toplumun-gercegi-nizamettin-ozel-yebiw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu toplumun gerçeği,

Açlar var, hem açıklar.

Kimi bir lokma ekmeği; 

Uykusunda sayıklar.

Bu toplumun gerçeği,

Sevgisiz büyüyen çocuklar.

Alır silahı, çeker tetiği; 

Polis tutuklar.

Bu toplumun gerçeği,

Pazarda satılan genç kızlar.

Böyle gördükçe bu gençliği; 

Yüreğim sızlar.

Bu toplumun gerçeği,

Sorulsa bundan çok sonra.

Bu şiirin içeriği; 

Yeter de artar onlara...', 'Bu toplumun gerçeği, Açlar var, hem açıklar. Kimi bir lokma ekmeği;  Uykusunda sayıklar. Bu toplumun gerçeği, Sevgisiz büyüyen çocuklar. Alı...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-toplumun-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik', 'gelincik-nizamettin-ozel-l8ot7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelincik; 

Gül eğlen, hayat senin.

En güzel köşelerde yerin,

Biricik...

Gelincik; 

Leylak, zambak, yasemin.

En tatlı süsü bahçemin; 

Biricik...

Gelincik; 

Kısa yazılmış, ömür dediğin.

Bir tek ben olayım sevdiğin; 

Biricik...', 'Gelincik;  Gül eğlen, hayat senin. En güzel köşelerde yerin, Biricik... Gelincik;  Leylak, zambak, yasemin. En tatlı süsü bahçemin;  Biricik...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelincik-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkür', 'tesekkur-nizamettin-ozel-c7xha', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kızım çok ama çok güzelsin,

Bütün azaların yerli yerinde.

Aynaya bakıp gece gündüz,

Bir tebessüm etmez misin? 

Seni cennetinde huriler gibi,

Güzel yaratan Rabbi’ne; 

Hiç olmazsa namaz kılıp,

Bir teşekkür etmez misin?', 'Kızım çok ama çok güzelsin, Bütün azaların yerli yerinde. Aynaya bakıp gece gündüz, Bir tebessüm etmez misin?  Seni cennetinde huriler gibi,...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Özel']::text[], 8.5, '{"poet":"Nizamettin Özel","poet_slug":"nizamettin-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tesekkur-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basit Kelimeler', 'basit-kelimeler-murat-polat-2-19pb5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birgün bir dost demişti ki zaar övercesine

Nasıl buluyorsun basit birkaç kelimeyle

Nasıl oluyorda bu duygular...

Yani...hem basit olacak...hem bu aşk

Diyorum ki...anlaşılmalı insan

Bir an önce anlatılmalı duygular

Evirip çevirmeden, dağlamadan

Ne Osmanlı, ne fars...Direk ve kısa olmalı

Çünki vakit çok dar

Bir an önce anlamalılar

Dert bu dünyada bırakmaksa bir değer

İster yanlız koysunlar, ister deli sansınlar

                                           

                                           15 Şubat 2006', 'Birgün bir dost demişti ki zaar övercesine Nasıl buluyorsun basit birkaç kelimeyle Nasıl oluyorda bu duygular... Yani...hem basit olacak...h...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/basit-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup-1-Dünya Sevgi Gününe', 'mektup-1-dunya-sevgi-gunune-vedat-koparan-lxlv5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi Umutlar Ak Bilincin Zorlamasında 

Dirençler Ha Tükendi Kaldı Mı Sabır Hala

Rehin Bir Yaşam Duvar Dibi İnfazlığında

 

(Ne büyüktük! birileri birilerinin farkına varmaları için can bedel ortaya koyarken, 

büyüklüğümüzün hâlâ farkına varamadık (mı?) 

Ne kadar büyüttük; sevdamızın büyümesi için ne emekler verildi, ortaya can koymak bile yetmedi. 

Her büyümede bölündük; kimileri bir ben derken, birileri hep biz dedi yine de fayda etmedi.

Bölündükçe küçüldük, küçülen biz olurken yaşamın her alanı cenderede daha da zorlaşarak küçüldü.

İnsana, insanın ezilmişliğinin son bulmasına, öncesiz ve sonsuz Sevgi dedik, herkese beklentisiz verdik. 

Aşkla yandık iç denizlerimizde. Başımızda eserdi kavak yelleri, pembe düşler yolcuğunda vurgunduk.

Esmelerimiz bir dağ rüzgârıydı. Aktık boz bulanık nice nehirlerde, acılarımızla büyüdük, acılar içinde.

Dostumuzu dost, düşmanı düşman bildik, kalleşliğe yuva etmedik yüreğimizin ateşinde. 

Adaleti en eşit en geniş ve özgürlüğün düşüdür düşümüz…

Her savrulan buğday başağında bir tane, her uçuşan toz zerreciğiyiz, her yağmur tanesinde, tenimize düşen kar zerreciklerinde. Sevgi dağlarıdır dağlarımız..

Bu gün sevgililer günüymüş a dostlar a anam a can parçam 

Ben sevgilerimi dağ oyuklarının yedi kat dibine gömdüm 

Yüreğimin katmerlerinde her bir krater yanar ha yanar 

İlmek ilmek örülen göz nuru çile dokusu

Yaşam kokusu her ilmekte vatan coşkusu

Suyun havanın hayatlığında ateşin yakıcılığında 

Gökyüzü şöleninde her an bizimle güneşin aşkıyla 

Sevgimiz sınırsız sevmelerimiz apansız 

Tutulmuşuz sevdaya onadır kaçaklığımız

Sevgiler Böyle Hoyrat Sevmeler Öyle Tezatta

Dilinde Sevda Türküsü Geceler Akarken Güne

Güneşle Uyanmak İlk Anda Akla Düşmek Var Ya

Bir Güne Sığmayan Sevgiler Yaşanası Gerçekliğe

Hep Bir Derya Kendi Yatağında Daima Doruklarda

Esenlikle Merhaba Nice Yaşanası Sevgi Günlerine

Vedat Koparan 15.02.2006', 'Mavi Umutlar Ak Bilincin Zorlamasında  Dirençler Ha Tükendi Kaldı Mı Sabır Hala Rehin Bir Yaşam Duvar Dibi İnfazlığında   (Ne büyüktük! biri...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mektup-1-dunya-sevgi-gunune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmam, Beklemeden Giderim', 'kalmam-beklemeden-giderim-gul-yazganarikan-rtj71', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yaman bir zamandayım bilemezsin

Doruklarım kar, doruklarım buz...

Yamaçlarımda nicedir ot bitmez olmuş..

Ne bir dost, ne bir göçmen kuş

Terk-i diyar etmiş gönlümü,

Duyulan bir benim sesim, bir de baykuş...

Gömülmüşüm kendi yokluğuma,

Fakirliğime, sana olan açlığıma,

Gelen de fazla kalmıyor,

Yürekte kıtlık oldukça,

Bir bir karışıyor hepsi göç yollarıma...

Ben de durmam artık, giderim

Alırım yalnızlığımı bir şal gibi omuzlarıma,

kurursa bağrım, çatlarsa dudağım

gözyaşımı da içerim....

ben de giderim...

gidenler yol gösterici olur.

Hele biraz erisin, şu kar şu buz.

Ben de alırım yüreğimi 

giderim...

Bu yamaçlarda ot bitmez olmuş...

Sıcak bir ovaya göç ederim...

Ben de durmam olmadığın yerde

Şu kıtlıkta, şu yoklukta,

Söker bırakırım yüreğimi düşmezse ardıma

Onu da bırakır giderim...

kanmam artık yalancı bahara,...

Kalmam

Beklemeden Giderim...', 'Ne yaman bir zamandayım bilemezsin Doruklarım kar, doruklarım buz... Yamaçlarımda nicedir ot bitmez olmuş.. Ne bir dost, ne bir göçmen kuş T...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kalmam-beklemeden-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Virane Kalbim', 'virane-kalbim-tayfur-yilmaz-yilmaz-q2kbi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerdesin sevdiğim nerdesin? 

Sana ulaşmak bu kadar da zor muydu? 

Bu muydu sevgimiz, bu muydu mutluluğumuz? 

Sana kavuşmak bu kadar da zor muydu? 

O ceylan bakışlarını bir daha

Görebilecek miyim? 

Boynuna sarılıp da tekrar tekrar,

Yine ağlayabilecek miyim? 

Her seni hatırladığımda

Anlamsız anlamsız uzaklara

Yine dalacak mıyım? 

Seninle beraber o rüzgarın soğuğunu,

O mevsimlerin eşsiz soluğunu,

Tekrar hissedebilecek miyim? 

Yakıp yıkıp giderken her şeyi…

Düşünmedin mi? 

Hem kendini hem de beni..

Yalnız bıraktığın geceleri…

Hiç düşünmedin mi? 

Sen değil miydin? 

Ölümün önünün sıcak; 

Arkasının da soğuk olduğunu söyleyen? 

Ömrün birkaç ağır sınavdan geçtiğini söyleyen? 

Doğru bildin! 

Sıcakta yandım…

Soğukta dondum…

Şunu bil; şunu bil ama…

Sayende mecnun oldum! 

Bekle geliyorum sevdiğim..bekle…

Hazar’ı aşarak,

Belki de boğularak…

Bekle geliyorum…

Aral’da mola verip,

Balkaş’da konaklayarak…

Kızılkum’da yanarak.

Biliyorum

Belki de bu kara toprak

Sana varmadan

Beni alacak…', 'Nerdesin sevdiğim nerdesin?  Sana ulaşmak bu kadar da zor muydu?  Bu muydu sevgimiz, bu muydu mutluluğumuz?  Sana kavuşmak bu kadar da zor m...', ARRAY['Türk Edebiyatı','Şiir','Tayfur Yılmaz Yılmaz']::text[], 8.5, '{"poet":"Tayfur Yılmaz Yılmaz","poet_slug":"tayfur-yilmaz-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/virane-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım...', 'yalnizligim-ercan-akbay-k3b0g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah doğarken penceremden,

   Bir umut dolar yüreğime

   Bel bağlarım yeni güne sevinçle

   Ve bir türküdür dudaklarımda

   Gün boyu yakıcı yalnızlığım..

   Akşamüstleri işten çıkarken,

   Yolda yürürken,

   En ağır yüktür taşıdığım.

   Sonra,

   Sonra isyanımdır,

   Gece karanlığını gösterirken penceremden

   Çekilen kanımdır...', 'Sabah doğarken penceremden,    Bir umut dolar yüreğime    Bel bağlarım yeni güne sevinçle    Ve bir türküdür dudaklarımda    Gün boyu yakıcı...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizligim-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Intizar', 'intizar-hanifi-isikoglu-tez14', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sende seversin

Gün gelir

Sende aglarsin

Terk edilince

Sende beklersin

Yarim ben gidince

Agla ve sev 

Benim sevdigim

Gibi

Sende terk edil

benim terk edildigim 

Gibi

Otur düsün sabahlara kadar

benim seni düsündügüm gibi

Caresiz dertlere düs

Ayni senin beni

Düsürdügün gibi

Sev ama sevilme

Terk edil sende

Benim terk edildigim

Gibi', 'Sende seversin Gün gelir Sende aglarsin Terk edilince Sende beklersin Yarim ben gidince Agla ve sev  Benim sevdigim Gibi Sende terk edil ben...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/intizar-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Gel (Gerdanlık)', 'kendine-gel-gerdanlik-abdurrahim-karakoc-6yaec', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öfkeyle, nefretle sefere çıkan

Sıcak yaz gününde kışa tutulur

Ben kralım diye değerler yıkan

Fildişi sarayda taşa tutulur..

15.02.2006/Vakit', 'Öfkeyle, nefretle sefere çıkan Sıcak yaz gününde kışa tutulur Ben kralım diye değerler yıkan Fildişi sarayda taşa tutulur.. 15.02.2006/Vakit...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kendine-gel-gerdanlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne tesadüf', 'ne-tesaduf-tarik-yasin-roi01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne tesadüf seni yine aynı yerde görmek hemde seninle oturup kunuştuğumuz ilk yer ne tesadüf ki hala sana 18. yaş gününde  aldığım elbiselerin var üzerinde anlıyorum artık bunlar tesadüf değil çünkü hala beni unutmamışsın tesadüf bile olsa yine seni görmek güzeldi', 'Ne tesadüf seni yine aynı yerde görmek hemde seninle oturup kunuştuğumuz ilk yer ne tesadüf ki hala sana 18. yaş gününde  aldığım elbiseleri...', ARRAY['Türk Edebiyatı','Şiir','Tarık Yasin']::text[], 8.5, '{"poet":"Tarık Yasin","poet_slug":"tarik-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ne-tesaduf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-mehmet-can-k78a3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırak geçsin zaman..

Üzülme yaşlanıyorum diye..

Öyle düşünme..

Ben 32 deyim daha..

Yol yarılanmadı..

Sen 25 de üzülme..

Gülümse dedimya..

Aşk belki öteki bahara..', 'Bırak geçsin zaman.. Üzülme yaşlanıyorum diye.. Öyle düşünme.. Ben 32 deyim daha.. Yol yarılanmadı.. Sen 25 de üzülme.. Gülümse dedimya.. Aş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/birak-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesnedi suphaniye divan-ı şerhi açıklaması', 'mesnedi-suphaniye-divan-i-serhi-aciklamasi-ali-riza-unal-4fdim', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimki cêmâlî görür ayan,anda cêlâl tutar onu,

Görki onda bir gül açsa,anda hâr olur peyda,

------------------

Kimki ayan olur,bezm-i elest sırrı peymana,

Onda nefs payandır,anda ar olur şeydâ,

Bir hırkapuşi melâmiden katre-idi bu zat,

Talibi belâmız uruç oldu,yakin zat-ı sıfat,

Rüşd ü irşad-ın bizdedir vaslı,ısbatı yokluğumuz,

Her cihetten cem-i cenâbız,celle şânımdır vucut,

Yar cêmâli nigâr-imiş,bu ben senıdığım sende,

 Bu dür kenz-i mahvfi oldu. Aynıdan aynaya.

Mesnedi suphaniye dinan-ı şerhi açıklaması

beyit----------------

Kimki cêmâlî görür ayan,anda cêlâl tutar onu,

Görki onda bir gül açsa,anda nâr olur peyda,

----------------

 1: Açıklama:  kim Hakkın cemâlini görürse onu,

Hemen Allahın celâlî yakalar kimki Hakkın cemâlini görmek isterse  cêlâlîne hazır olsun  kahrına cefasına,

Belâsına  kendini hazırlasın yada bu sevdadan vaz geçsin bunun dışındaki laf ve palavradan ibarettir,

Lakin aşığa cefa,sefadır, kahır ve belâ.vuslatın habercisidir ehline ne hoş değilmi.

2:Görürsünki ondan bir gül açılmış biraz yaklaşıp koklayım okşayım desen,anında bir dikeni batarcanını

yakar, ateş peyda olur sana,beşeri Alışkanlıkların  yakanı bırakmaz ve  oradan sessice Kaçar sıvışırsın çünkü o gül haramdır na ehile

Beyit-----------------

3:Kimki ayan olur,bezm-i elest sırrı peymana,

4:Onda nefs payandır,anda ar olur şeydâ,

Açıklama:3-4: kim ayan olur kim aşikâr görür bilir ve Hakkel yakin yaşar,o ruhlar meclisine arif olur mahrem olur yaratılış 

sırrına onda açılır  Hakka ettiği biat verdiği söz Rabbi ile yaptığı akit ortaya çıkar ve öyle bir açığa çıkışki bu sırda o nefs-i cüzzi hiç olur, nerede küllü nefste Yani Hazreti Allahın varlığında, ve artık o nefs payandır yani  ona akîbet ayandır o kişi dünyadada ahiretede

kurtulşuşa erenin ta kendisidir ona ne endişe ne gâm ne keder ne hüzün ulaşamaz,o nefs öyle bir pür nûr olmuşturki ulaşsada o nefse tesiri ancak zem,zem gibidir onun nefsine,ar iffet mahramiyet,anda şeyda

yani,tutkunluk akıllı ama divanelik,bir pejmurdeliğin arkasında,çok sevgiden hasıl olan bir hal mevcutturki bunu ancak tadan bilir…

Beyit---------------

5	: Bir hırkapuşi melâmiden katre-idi bu zat,

6	: Talibi belâmız uruç oldu,yakin zat-ı sıfat,

 -----------------

Açıklama 5::bir hıkapuşi Melâmi.hırkapuşi fakir derviş Melâmi:

Muhammedi meşreb üzere  yokluk mertebesinin

yani kulluk sırrının kemaline mashar halefi adem

zerrenin kendini ummanda bulması yani gerçekte

katre sandığı nefsinin hakikâtte umman olduğunu

idrak etmesi, müşahade ve zuhuratına ayan olması,

6: celâle yani kahra cefeya razı oluşumuz cemâli artı  zatı-ı sıfata Yani mahrem-i sırrı ilâhiye mashar oldu    neyimiz belaya talebimiz Haktan gelene rızamız,mümin sıfatının kulda açığa çıkışına şahid kıldı kim Hazreti Allah.

Beyit,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,

7: Rüşd ü irşad-ın bizdedir vaslı,ısbatı yokluğumuz,

8: Her cihetten cem-i cenâbız,celle şânımdır vucut,', 'Kimki cêmâlî görür ayan,anda cêlâl tutar onu, Görki onda bir gül açsa,anda hâr olur peyda, ------------------ Kimki ayan olur,bezm-i elest s...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/mesnedi-suphaniye-divan-i-serhi-aciklamasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Sevdiğim Gezelim', 'gel-sevdigim-gezelim-yusuf-onder-bahceci-5nxon', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel sevdiğim senle şöyle gezelim,

Seven kâlpleri biz, bir bir sezelim,

Mayası bozuk olanları, ne edelim,

Gel sevdiğim senle şöyle gezelim.

Dağlara bakınca, umutlarım biter,

Koparılan güller tekrar nasıl biter,

Güller gonca ise bilki beni etkiler,

Gel sevdiğim senle şöyle gezelim.

Nehirlere baksam, su gibi aksam,

Sevdiğimin yüzüne, hep baksam,

O gelecektir diye, yollara çıksam,

Gel sevdiğim senle şöyle gezelim.

Gönülden söyleyelim gönül diyelim,

Gönüllere girelim biz gönül verelim,

Sen yanımda yoksan, nasıl ederim,

Gel sevdiğim senle şöyle gezelim.', 'Gel sevdiğim senle şöyle gezelim, Seven kâlpleri biz, bir bir sezelim, Mayası bozuk olanları, ne edelim, Gel sevdiğim senle şöyle gezelim. D...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-sevdigim-gezelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Sen Gelmedin', 'ama-sen-gelmedin-sacide-yaylaz-q29w0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dua,bir yakarış olacaktı 

                 Sana sevdiğimi söyleyebilmek

               Kaç yağmurlu,fırtınalı gündüzlerde,

                   Kaç zifiri karanlık gecelerde,

                    Seni görebilmeyi düşledim,

                  Her aklıma geldiğinde sevgili,

               Fırtınalar,kasırgalar koptu içimde,

                Sana bunları hiç söyleyemedim,

           Güneş bir türlü doğmadı gündüzlerime,

        Ay doğmadı,yıldızlar kaymadı gecelerimde,

             Kayan yıldızlardan seni dileyemedim,

                     Bir dua, bir yakarış olacaktı,

                   Sana sevdiğimi söyleyebilmek.

              Ama sen hiç gelmedin,gelemedin ki..', 'Bir dua,bir yakarış olacaktı                   Sana sevdiğimi söyleyebilmek                Kaç yağmurlu,fırtınalı gündüzlerde,              ...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ama-sen-gelmedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Kurban Olurum', 'ben-sana-kurban-olurum-gul-yazganarikan-8mqqr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyüyorsun, 

öyle hızlı,

Geçiyor zaman...

Bilmiyorsun...

A benim küçüğüm,

Canımın can damlası,

Hayatımın yoldaşı

Gözümün bebeği oğlum 

Ben sana kurban olurum....

Sen de olmasan yaşar mıyım sanıyorsun...

Evimin minicik direği, sen beni dik tutuyorsun...

Bakma zaman zaman ağladığıma,

İçimden gelmez oğlum isyan yaradana...

Seni verdi ya bana 

Binlerce şükür karışır sen uyurken koynuna...

Korkarım oğlum, korkarım 

Sana bağlı şu fani canım,

Sana ya tüm çabalarım.

Beklemem senden karşılık

Canının sağlığıdır benim varlığım...

Gururum, onurum, zenginliğimsin...

Allah seninle nice günler göstersin...

O anne diyen dillerin var ya

Bir ömre değil

Bin ömre de bedelsin...', 'Büyüyorsun,  öyle hızlı, Geçiyor zaman... Bilmiyorsun... A benim küçüğüm, Canımın can damlası, Hayatımın yoldaşı Gözümün bebeği oğlum  Ben s...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-sana-kurban-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altın Yeleli Atların Sırtında..', 'altin-yeleli-atlarin-sirtinda-i-brahim-zarifoglu-09i6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bilinmez akşam zamanı,

Altın  yeleli atlara bineceğiz.

Gökyüzü atlas seccade 

Kurşuni bir rüzgâr gibi eseceğiz..

Unutulmuş dünyanın 

Hem bîçare çocukların,

O simsiyah kıvırcık saçlarını 

Candan sevip okşayacağız! .

Kapatıp zulmün gözlerini

Şükür secdelerine varacağız.

Bir bilinmez muştu akşamı

Kadim tarihe nefes olacağız..

Altın yeleli atların sırtında

Dünyanın kararan bahtına

Atarak tarihin kadim mührünü

Atiye uçacağız! ..', 'Bir bilinmez akşam zamanı, Altın  yeleli atlara bineceğiz. Gökyüzü atlas seccade  Kurşuni bir rüzgâr gibi eseceğiz.. Unutulmuş dünyanın  Hem...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Zarifoğlu']::text[], 8.5, '{"poet":"İbrahim Zarifoğlu","poet_slug":"i-brahim-zarifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/altin-yeleli-atlarin-sirtinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Esaslı Ayrılık..!', 'esasli-ayrilik-dilek-egri-l2wy9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sonunu birtürlü getiremediğim

bir hikayenin ana fikriydin sen..

satırların altına baktım,

büyük harflerini taşıdım,

aşkımı önsöz yaptım,

seni okumaya  doyamayan ben; 

aşk anlayışına anlayışsızdım...! 

bukadar bilinmezliklerle,

ertelenen hayallerle,

bir efsaneyi tüketme..! 

diyecekken; 

yalanın bir satır başında karşıma çıktı.

ve benim a(ş)     k dediğime sen kara dedin..

aşk karalandı..! 

/..esas kız masalından çıkıyor

esaslı sevenini bulamadı diye.../

14/02/06', 'sonunu birtürlü getiremediğim bir hikayenin ana fikriydin sen.. satırların altına baktım, büyük harflerini taşıdım, aşkımı önsöz yaptım, sen...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/esasli-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecegim gün gelecek', 'gelecegim-gun-gelecek-hanifi-isikoglu-p5quz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tarama saclarini

Cirkin desinler

Sevme kimseyi 

Kalpsiz desinler

Birak konusma

Sana dilsiz desinler

Aglama bir tanem

Sevdigini bilmesinler

Bekle beni

Gelecegim sana

Gülüm sayili gün

Cabuk gecer

Bekle beni 

Seni biraktigim gibi

Asker de yim diye 

Aglama

Teskereyi alir gelirim sana', 'Tarama saclarini Cirkin desinler Sevme kimseyi  Kalpsiz desinler Birak konusma Sana dilsiz desinler Aglama bir tanem Sevdigini bilmesinler B...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelecegim-gun-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Şubat', '14-subat-mehmet-can-9d347', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '14 şubat yine

Sevgililer günü..

Ben eski aşkımın hayalinde..

Onsuz ve onunla..

Sinema filmi gibi..

Unutmayan kalbin acısı ayrı..

Unutulmanın  sancısı ayrı..

İşte sevgililer günü..

14 şubat…', '14 şubat yine Sevgililer günü.. Ben eski aşkımın hayalinde.. Onsuz ve onunla.. Sinema filmi gibi.. Unutmayan kalbin acısı ayrı.. Unutulmanın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/14-subat-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serhat''tan Mektup-3', 'serhat-tan-mektup-3-saim-bastik-nfvhd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onlar baş tacımız baba,it deme! 

Sen de çok geride kalmışsın canım! 

Tayyip abim kızar öyle söyleme! 

Sen de çok geride kalmışsın canım! 

Afları sayarken aklım karıştı

Beygir yolda süvarisiz yarıştı

Kurtlar birbiriyle maça girişti

Sen de çok geride kalmışsın canım! 

Onun hizipleri bitirdi bizi

Sona erdiremez zilletimizi

Bunca yıldır tanımadın Deniz’i

Sen de çok geride kalmışsın canım! 

Millet çok kan kusar yaptıkça hata

Anlatsın derdini muhterem zat’a

Vatan onun için kârlı bir meta

Sen de çok geride kalmışsın canım! 

Adam haklı böyle atsa da nara

Öyle yüklenipte sokmayın dara

Düğünden dernekten geldi bu para! 

Sen de çok geride kalmışsın canım! 

Abime de yakışıyor vallahi

Çokmu gördün iki tane villayı

Bak reis’e sahiplenmiş dünyayı

Sen de çok geride kalmışsın canım! 

Bu tezgâhta kuş gribi bahane

Pastörize yumurtalar şahane

Yem derdinden kurtuldunuz daha ne! 

Sen de çok geride kalmışsın canım! 

Baba; sağol aydınlattın yolumu

Elin verme, kaptırırsın kolunu

Sayılanlar,sağır sultan malumu

Sen de çok geride kalmışsın canım! 

15/02/2006', 'Onlar baş tacımız baba,it deme!  Sen de çok geride kalmışsın canım!  Tayyip abim kızar öyle söyleme!  Sen de çok geride kalmışsın canım!  Af...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/serhat-tan-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dallar Kırıldı', 'dallar-kirildi-yusuf-onder-bahceci-5sbw2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hangi dala el attıysam dallar kırıldı,

Gemimiz yan yattı, sallarımız yıkıldı,

Kâlbime hasretinin tohumları atıldı,

Hangi dala el attıysam dallar kırıldı.

Ne de güzel yol alıyordum, aheste,

Şimdi cân kuşumu koydular kafese,

Yolum uzaktır, kaldım nefes nefese,

Hangi dala el attıysam dallar kırıldı.

Yazdığım şiirlerde ümit ve gözyaşı,

Gel sen ölene kadar, bu yükü taşı,

Ayrılığın ataşı çok harlı yakar ataşı,

Hangi dala el attıysam dallar kırıldı.

Hangi dala el attıysam dallar kırıldı,

Her tarafımızsa düşman gibi sarıldı,

Seven dostlarımın hepsi de darıldı,

Hangi dala el attıysam dallar kırıldı.', 'Hangi dala el attıysam dallar kırıldı, Gemimiz yan yattı, sallarımız yıkıldı, Kâlbime hasretinin tohumları atıldı, Hangi dala el attıysam da...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dallar-kirildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiyorsan Sevme O Zaman', 'sevmiyorsan-sevme-o-zaman-olgun-ekinci-xujko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Madem; 

Sigara içimli, uzun, öğle molalı

Keyifli doyulmaz sohbetin 

Ardından yakışmıyorsa romantizm

Uygun düşmüyorsa sevdaya dair

Sana  başka zamanlamalarda

Ve ansızın ve ilk söz olacak

***Seni Seviyorum''larım..

O zaman sevdamız dışında

Başka mod, kod olmayacak

Seni Seviyorum''uma karşılık

Bende Seni Seviyorum''ların…

3.2.2006 - Adana', 'Madem;  Sigara içimli, uzun, öğle molalı Keyifli doyulmaz sohbetin  Ardından yakışmıyorsa romantizm Uygun düşmüyorsa sevdaya dair Sana  başk...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmiyorsan-sevme-o-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmamak...', 'unutulmamak-i-brahim-ethem-bingul-jqie1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönüllerde yaşamayı bilene

Gönlü kırıklara sevgi verene

Ağlayanın göz yaşını silene

Ölüm uzak durur, ölmeyi bilmez...

Para, pul, çokça mülk değil bir imkân

Tatlı söz, güler yüz sevgidir, akan

Gönül bahçesidir ölümsüz mekân

Orada gezinen ölmeyi bilmez...

Dünyaya sığmayan krallar öldü

Nice çok zenginler yerde çürüdü

Şöhretler yok oldu, devler küçüldü

Gönüllere giren ölmedi, ölmez...

www.iebingul.com', 'Gönüllerde yaşamayı bilene Gönlü kırıklara sevgi verene Ağlayanın göz yaşını silene Ölüm uzak durur, ölmeyi bilmez... Para, pul, çokça mülk ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutulmamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-ethem-turan-7tote', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merak etmedim desem yalan olur 

Hani bir sürü işin vardı

Bitiremedim dediğin 

Bittimi merak ettim

Kar yağıyor  buralara

Belki senin yanına da öyledir

Yolların kapalıdır kim bilir

Gelemiyor da olabilirsin

Telefon hatları çalışmıyordur 

Neden mi merak ettim

Hiç aramıyorsun ya 

Sebep buluyorum  seni haklı çıkarmak için 

Belki de kendimi kandırıyorum ne dersin 

Özledim yine seni 

Pekte çok oldu görmeyeli 

Hasretlik çöktü içime

Gelmeli miyim ki

Bilemiyorum ki gelsem mi 

Arasam mı ne yapsam bilemiyorum 

Duramıyorum yerimde

Of  ne sıkıcı oldu hayat yine 

Ne yapayım özledim 

Özledim seni işte', 'Merak etmedim desem yalan olur  Hani bir sürü işin vardı Bitiremedim dediğin  Bittimi merak ettim Kar yağıyor  buralara Belki senin yanına d...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozledim-162-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İslamın Suyu', 'i-slamin-suyu-mehmet-isikoglu-ar5z4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İslamın suyuna mikrop kattılar 

Her türlü çamuru sırta attılar

Kasıt belli bilerek yıprattılar 

Dünyada oldular kendiler dayı 

Müsbet ilimlerle açıldı ara

İrtica damgası alnında kara

Bir merci yok insan mesele sora

Alamadı kimse doğrudan payı

Düşünsün beyinler kendine göre 

İnanca müdahil olmasın töre 

Akledip insanlar sarılsın bire

O zaman durulur islamın suyu', 'İslamın suyuna mikrop kattılar  Her türlü çamuru sırta attılar Kasıt belli bilerek yıprattılar  Dünyada oldular kendiler dayı  Müsbet ilimle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/islamin-suyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Sevdam Diye Ölmedimmi', 'askim-sevdam-diye-olmedimmi-kamil-soylemez-ewosi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nur olup,göklerden içime aksan

Tüm kötü ruhları,silipte atsan

Ömrümü kış iken ilkbahar yapsan

Ne olur, ay yüzlüm sevsen beni

Bilirsin her suyun görünmez dibi

Ben derin maviyim gördüm seni

Aşkım,sevdam diye ölmedimmi

Ne olur, ay yüzlüm sevsen beni

Cahillik insana sakın,kar etmez

Şu anki susuşun, mutlu etmez

Dünyayı verseler cana yetmez

Ne olur,ay yüzlüm sevsen beni

Ana, yavruya baktığı gibi

Aslının kerem,yaktığı gibi

Nehrin denize aktığı gibi

Ne olur,ay yüzlüm sevsen beni', 'Nur olup,göklerden içime aksan Tüm kötü ruhları,silipte atsan Ömrümü kış iken ilkbahar yapsan Ne olur, ay yüzlüm sevsen beni Bilirsin her su...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askim-sevdam-diye-olmedimmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kap hırsızı', 'kap-hirsizi-hanifi-isikoglu-rkwjb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni seviyorumun degeri neydi                                                    söylermisin kalp hırsızı                                                                   girdin kalbime aldın beni                                                               ver kalbimi kalp hırsızı                                                                   inandım sevdim seni                                                                     nebileyim hayırsız                                                                           sevdim seni zarar gördüm                                                            ver kalbimi kalp hırsızı                                                                   sevemem arttık hiç kimseyi                                                          anladım aşkın degerini                                                                  kimseye kaptırmam kalbimi                                                         ver kalbimi kalp hırsızı', 'seni seviyorumun degeri neydi                                                    söylermisin kalp hırsızı                                   ...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Işıkoğlu']::text[], 8.5, '{"poet":"Hanifi Işıkoğlu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kap-hirsizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-seyfettin-bilal-ozluk-2rd3s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tenimi yakan alev gibi sıcaklığınla bırakmıştım seni aylar öncesi

Şimdi kirli havanla mı karşılayacaktın beni

Nerde o sıcaklığın nerde o eski manzaran

Ben seni böylemi bırakmıştım

Kadınım gibi sendemi soğuksun İstanbul''um.

Hani balık ekmek yediğim o sandal

Yoksa battımı? 

Gidenler hep aranırmış bunu biliyorum

Batan sevdam mı yoksa sadece hayaller mi

Kadınım gibi sendemi kayboldun İstanbul''um.

Mavi suların daha berraktı 

Şimdi ise maviliğin yok artık 

İnsanlar gibi sende eskidin ve kaçıyorsun

Ben alışkın değilim sessizliğe ve yalnızlığa

Kadınım gibi sendemi sessizliğe büründün İstanbul''um.

Şu mahşeri kalabalık yalnızlığımı gidermiyor

Herkes üşümüş titriyor ayazdan kalma havanla

Geldim sana pervasızca açmayacakmısın kollarını

Karanlığına bırakacaksan zaten karanlıktayım

Kadınım gibi sendemi yalnız bırakıyorsun İstanbul''um...

''''Serkan,İnceliklerin ve sıcaklığın için teşekkür ederim.Güzel dostum iyi ki varsın.''''', 'Tenimi yakan alev gibi sıcaklığınla bırakmıştım seni aylar öncesi Şimdi kirli havanla mı karşılayacaktın beni Nerde o sıcaklığın nerde o esk...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/istanbul-390-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-ahmet-dalkiz-9fmrr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuru bir dal olsaydım

Yaprağına hasret

Rüzgardan kırılsaydım

Alıp yaksaydın beni

Bir gül olsaydım

Yağmuruna hasret

Kopartıp dalımdan 

Soldursaydın beni

Bir yudum su olsaydım

Denizine hasret

Dudaklarından aksaydım

İçseydin beni

Bir gün olsaydım

Herkesin bildiği

Senede bir gün

Hatırlasaydın beni

Bir sen olsaydın

Alnıma yazılan

Gönlünün kapısını açıp

Bekleseydin beni', 'Kuru bir dal olsaydım Yaprağına hasret Rüzgardan kırılsaydım Alıp yaksaydın beni Bir gül olsaydım Yağmuruna hasret Kopartıp dalımdan  Soldur...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Dalkiz']::text[], 8.5, '{"poet":"Ahmet Dalkiz","poet_slug":"ahmet-dalkiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasret-332-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-hanifi-isikoglu-iohfc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'beni terk edip giden sendin                                                          arkandan aglayan ben                                                                  bana çektirdigin bu ızdırabı                                                           birbaşkasıda sana çektirsin zalim                                               sabırlıyım ben beklerim                                                                 sende yürün benim gibi', 'beni terk edip giden sendin                                                          arkandan aglayan ben                                   ...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Işıkoğlu']::text[], 8.5, '{"poet":"Hanifi Işıkoğlu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sensin-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Dostum', 'tek-dostum-tahmine-yildirim-7wiu3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karalamak beyaz sayfaları

Güzel görebiliyorum yarınları

Aydınlık oluyor içimde gecenin karanlıkları

Tek dostum defterimin beyaz sayfaları

Beni en iyi anlayan bu kalemim

Onunla yazı yazarken yok hiç bir nedenim

Yazı yazma arzusuyla doluyor bu bedenim

Tek dostum işte bu güzel kalemim

Şairlik galiba böyle birşey

Anlayamayana bunu anlatmak zorşey

Yüreğinden kopup gelen oşey

Tek dostum işte yüreğimdeki oşey

Etrafımda sevenlerim variken

Allahım nedir aradığım bir bilsem

Ne olur sanki bana bir yol göstersen

Tek dostum yanlızlığım olmasa.....', 'Karalamak beyaz sayfaları Güzel görebiliyorum yarınları Aydınlık oluyor içimde gecenin karanlıkları Tek dostum defterimin beyaz sayfaları Be...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-dostum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Şaşıyorum Çok', 'cok-sasiyorum-cok-yusuf-onder-bahceci-jk00i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok şaşıyorum şaşıyorum bu insanoğluna,

Ahseni Takvin üzere Yaratmış ve o kuluna,

Kuluna sayısız nimetler, vermiş de vermiş,

Yaratan kulundan hep yalvarma beklermiş.

İnsanlar kısım kısım, yer ise damar damar,

Allah''a isyan ve nisyan edenler şamar yer,

Allah kullarından birşey istemez, dua ister,

Çok şaşıyorum şaşıyorum bu insanoğluna,

Adama yapma, yapma diyorsun duymuyor,

Kendini kandırıyor numara kulağı duymuyor,

Otobüse biniyor yaşlı birini görse uyukluyor,

Çok şaşıyorum şaşıyorum bu insanoğluna.

Öksüzün ve yetimlerin malını öyle bir yiyor,

Getir kardeşim getir afiyetle yiyeyim diyor,

Cahil, kendini Peygambere hasım ediyor,

Çok şaşıyorum şaşıyorum bu insanoğluna.', 'Çok şaşıyorum şaşıyorum bu insanoğluna, Ahseni Takvin üzere Yaratmış ve o kuluna, Kuluna sayısız nimetler, vermiş de vermiş, Yaratan kulunda...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-sasiyorum-cok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / BİR ÇİFT SÖZÜN OLMALI', 'bir-dortluk-de-sen-yaz-bi-r-ci-ft-sozun-olmali-siir-perisi-grubu-dyt8q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/Aşığım Aşık'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı) 

Yetmedi mi sustuğun bağrı yanık milletim 

Senin de söylenecek bir çift sözün olmalı 

Asırlar var yaraya, zehirli mikrop hekim 

Merhamet kadar gerçek bir çift sözün olmalı..........(Ayak dörtlüğü - İbrahim Usta) 

1. 

Esaretin son bulsun, artık zincirleri kır 

Dünyaya gür sesinle hakkaniyeti haykır 

Mazlumun feryadına medeniyetler sağır 

Bütün dünyaya örnek bir çift sözün olmalı.............İbrahim Usta 

2. 

Oynanıyor üstümde türlü türlü oyunlar 

Avrupalı kurtlara teslim oldu koyunlar 

Sükutlar galip gelmiş neden bükük boyunlar 

Silkinip haykıracak bir çift sözün olmalı.............Şemsettin DERVİŞOĞLU 

3. 

Tuz ektirmeyelim artık biz bu yaraya 

Türklüğün şanı için gelelim bir araya 

Düşmanları dizelim esas duruş sıraya 

Kurulsun düğün dernek bir çift sözün olmalı............Hıfzı ÖZBEKMEZ 

4. 

Çağlamalı coşmalı, gerekirse susmalı 

İyinin güzelliğin, hep peşinden koşmalı 

Güzel sözler söyleyip, doğruluğa saçmalı 

Evlatlarına örnek bir çift sözün olmalı................Sevim E.TEZEL 

5. 

Elden gitti gençliğim,dürüstlüğüm terbiyem 

Medya denen canavar bitirdi ben ne diyem 

Çürüme bizden geldi,kime neler söyleyem 

Sana düşüyor yermek,bir çift sözün olmalı..............İbrahim COŞAR 

6. 

Gençliğim bir acayip uzaklaşıyor özden 

Nasihat dinlemiyor,anlamıyor bir sözden 

Yüce İbrahim için güle dönen o közden 

İbretle bahsedecek bir çift sözün olmalı...............Şemsettin DERVİŞOĞLU 

7. 

Kese boş, cepken delik, yaşayıp zar zor, darca 

Evlat de, yüzünü sürt, elde varını harca 

Ne derse boyunu eğ,, ve de gir bunca borca 

Hüzünlenen gönlünde bir çift sözün olmalı….............Zülfikar Yapar kaleli 

8. 

Biz üç ahbap çavuştuk, ele avuca sığmaz, 

Her birimiz bir yerde, çil yavrusu gibiyiz. 

Dağıldık istemeden dağıldı köklerimiz, 

Vefasız ayrılığa bir çift sözün olmalı.................Suna Doğanay 

9. 

Babam, baban kardeşçe, omuzladı vatanı, 

Sinede bayrak ile, gör toprakta yatanı 

Ecdad af etmeyecek, ülkesini satanı 

Birliği bozanlara, bir çift sözün olmalı...............Turan Orak 

10. 

Hakikatle yaşarken her nefes şu alemde 

Her şeyde ara onu hem sözde hem ilimde 

Gidiyorken dünyadan alnın açık ölüme 

Giderken söyleyecek bir çift sözün olmalı..............Mehmet TEKECİ 

11. 

Ortalık yobaz dolmuş yok mu bunun çaresi 

Ne düz yol kalmış temiz ne de eski hilesi 

İçimizden gelmiyor doya doya gülesi 

Bu dertten geçilecek bir çift sözün olmalı.............Samet Mehmet Bora 

12. 

Yetmedi yetmeyecek, sessiz kalan dillere 

Kafi gelmez mi Bunca asır eziyetlere 

Her lahza fırsat kollar bir lokmada yutmaya 

Aç kurtlara seninde, bir çift sözün olmalı.............Mehmet Ali DEMİRCAN 

13. 

Kıvrım kıvrım şu yollar seni bizden alacak 

Uzayan nankör yıllar hasretle ağlatacak 

Aylar yıllar bitecek vuslat kapı çalacak 

Döndüğünde bizlere bir çift sözün olmalı...............Selcen Boyar 

14. 

Zaman geçip gidiyor acı ve tatlısıyla, 

Yürek dolmakta yine zamanın acısıyla 

Bizden geriye kalan duyguların tadıyla, 

Herkese haykıracak bir çift sözün olmalı................Ebru Rabia 

15. 

Suskunluk merhem olmaz kanayan yaralara 

Şöyle bir göz gezdirip bakmak lazım yaraya 

Ar damarı çatlamış nice hayasızlara 

Tam da uyup yakışan bir çift sözün olmalı...............Tamer DURAN 

16. 

Hayat geldi geçiyormuş zamanın neyine, 

Ömür törpüleniyor zaman kendi keyfinde, 

Kurtlar sofrası doluyor yiğitler nerede, 

Sofrayı kuranlara bir çift sözün olmalı.................Hayatcan Öztürk 

17. 

Ne yarenlik edenler,ne dost bildiklerimiz 

Can acıdı yaşım aktı gel dediklerimiz 

Anlamaz,duymaz seni,sevgiden bihaberler 

Böyle vurdum duymaza bir çift sözün olmalı..............Zeliha BİÇER 

18. 

Garibe yardımcı ol, uzat eli diyorum 

Az konuş, öz konuş da, kardeş dinlen diyorum 

Karakış kapıda of, halk ne yapar diyorum 

Şu zenginlere artık, bir çift sözün olmalı...............Serdar Sayıl 

19. 

Eğriyi ve doğruyu tartar kantarın varsa 

Gönül sofran açıksa ekmeği dostla yerse 

Komşum açmış huzur yok bizim hanede derse 

Böyle sağlam bir özün bir çift sözün olmalı..............Hayri Arıkan(Serdaroğlu) 

20. 

Şeref kalmamış halde, şahsiyet firar etmiş. 

Namus yenik çirkefe, iffetçe zarar etmiş. 

Aydınlık hak yol varken zulmette karar etmiş. 

Edepsize, arsıza bir çift sözün olmalı...................Necmi ÜNSAL', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/Aşığım Aşık'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":105,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-bir-cift-sozun-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-nuray-acar-act6o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir aşk? 

bizi düşlere iten, 

açken tok tutan 

üşürken ısıtan 

ağlatırken güldüren 

aşk tezat duyguların çarpışma meydanı mıdır? 

büyülü bir bakış mı? 

dokunuşun yaydığı ürperti mi? 

aşk 

söylenecek çok sözü olan 

söylemesini bilen 

görmesini bilen 

bilip de hissedenlerin 

tanıştığıdır O 

aşk 

sözde 

dilde 

özde 

bilinmezde.... 

aşk bu 

çözemezsin nasıl sana hükmettiğini bilemezsin 

bir gün 

büyüsünde sende kalırsın 

kaldığında 

hissedeceksin 

sözcüklerin sendeki melodisini...', 'Nedir aşk?  bizi düşlere iten,  açken tok tutan  üşürken ısıtan  ağlatırken güldüren  aşk tezat duyguların çarpışma meydanı mıdır?  büyülü b...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ask-546-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / GECELER', 'bir-dortluk-de-sen-yaz-geceler-siir-perisi-grubu-6ovnw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/GECELER'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

Sam yeli durulur güzde ıslanıp, 

Yine de rüzgârsız KALMAZ geceler. 

Güneş bile solar dağa yaslanıp, 

Vuslatın kolunda SOLMAZ geceler.................(Ayak Dörtlüğü)    Feride ÖZMAT 

1. 

Gün gelir tutkuyla çağlamaz deniz. 

Âlem hesap sorar, sanıp kimsesiz. 

Ebedî yeminden kalmaz tek bir iz. 

Aşkın ezgisini ÇALMAZ geceler...................Feride ÖZMAT 

2. 

Sabaha erişmez hain geceler, 

Yalnızlık yürekte aşkı heceler, 

Koyuca içilir telve kahveler, 

Aşığın demidir, GEÇMEZ geceler..................Mehmet Ali DEMİRCAN 

3. 

kır kapılarını suskunca kalma 

kur köprülerini sessizce durma 

kar tutkularını gizlice olma 

bir başınalıkta KALMAZ geceler..................Ali IŞIK 

4. 

Gece bana ağlar ben de geceye 

Hasret kaldım sevda denen heceye 

Çok düşler görürüm ben bir Ece''ye 

Heyhat ki hayıra YORMAZ geceler.................Şemsettin DERVİŞOĞLU 

5. 

Ben miyim divane, sen misin hasif? 

Sen mi takıntılı, ben miyim pasif? 

Ben miyim meyane, sen mi agrasif? 

Sırrı hakikati BİLMEZ geceler...................Zülfikar Yapar KALELİ 

6. 

Korku ile umut kolkola gezer, 

Yorgun hayalleri güvenle süzer, 

Kırar zincirleri şiirler söyler, 

Uykudan arınmış BİTMEZ geceler...................Suna DOĞANAY 

7. 

Bıçağın sırtında geçiyor günler 

Kar gibi eridi yok oldun dünler 

Gerçeği anlatır karanlık sinler 

Aydınlık atiyi SİLMEZ geceler....................Mehmet TEKECİ 

8. 

Hayat çarkıfelek,döner gündüzde, 

Acı yürek vurur,yanar gündüzde 

Yara kabuk açar,kanar gündüzde 

Gündüze gebedir,DOLMAZ geceler...................İbrahim COŞAR 

9. 

Hayındır karanlık korkutur beni 

Yalnızdır geceler üşütür teni 

Rüyalar yetmiyor özlerim seni 

Sansizim sabahı OLMAZ geceler....................Sema Can 

10. 

Hücrem üç adımlık, durmaz gezerim 

Özler, yar yüzünü, kalbe çizerim 

Mahpusluk yüzünden, canı üzerim 

Ne yapsam, ne etsem, GÜLMEZ geceler..............Turan ORAK 

11. 

Alev alev yakıp durdu bakışı 

Közle harlanırdı, kalbe akışı 

Biçare gözlerim, arar çıkışı 

Ay yıldızı ile, GELMEZ geceler...................Şeyhmus SEVİLMEZ 

12. 

Gecelere gündüz nur gönül gözüm. 

Mısralara iner ders verir sözüm. 

Güneş rehin ise yas tutar özüm. 

Karanlığa çözüm BULMAZ geceler...................Hüseyin Sığırtmaç 

13. 

Yüreğime sevgim sığmaz taşarım, 

Bu sevgiyle kaç senedir yaşarım, 

Şu gönlümü aklım almaz şaşarım 

Yari kollarıma SALMAZ geceler....................Selcen Boyar 

14. 

Gül bile solar gün,akşam olunca 

Sevda söner gider,bekler durunca 

Yaşamak ateşi,düşer bağrına 

Aşkın ateşini YAKAR geceler......................EBRU RABİA BERKUL 

15. 

Dualarım size, can evlatlarım 

Allah adı deyin, al sevaplarım 

Çattırmayın bana, kara kaşlarım 

Besmelesiz olmaz, GEÇMEZ geceler.................Sevim E.TEZEL 

16. 

Gözlerin diye ben,sevdim onları. 

Ayrı ayrı öptüm,tüm yıldızları. 

Gittin; şimdi küskün,gülmez yüzleri. 

Herşey susar lakin, SUSMAZ geceler...............Emin Akduman 

17. 

Bitmez dediğin gün mutlaka biter 

Canın sağsa eğer bu sana yeter 

Sanma paylaşımlar hep mutlu eder 

Hiç bir aşka kimlik SORMAZ geceler...............Metin Yaltı 

18. 

Çullanır üstüme, bilmez halimi 

Sormaz; abdalmıyım,yoksa deli mi? 

Soldurdum baharda, gonca gülümü 

Garip neler çeker, BİLMEZ geceler................Saim Bastık 

19. 

Gözümde karadır, gönlümde taştır, 

Parçaladın beni şimdi böl gece, 

İçimde acılar hece hecedir... 

Seni benden alan KANLI gecedir...................Ayşe BAKİYEVA 

20. 

Dünya varmaz böyle aşkın sırrına 

Bugün varım ama kalmam yarına 

Ölüm denen değer senin uğruna 

Gündüz çekileni BİLMEZ geceler...................Samet Mehmet Bora 

21. 

Karartma ışığı görülsün yolum, 

Tenha köşelerde korkmasın kulum, 

Sessizlik diz doyu sorulmaz halım, 

Karanlığa ışık SALMAZ geceler....................İsmail Doğan 

22. 

Aşkınla düşmüşüm cananım derde 

Hasretin adeta gözümde perde 

Derdimi sayarım gece seherde 

Gönülden ahımı ALMAZ geceler.....................Hıfzı ÖZBEKMEZ 

23. 

Kapkaradır kafir korkutur beni 

Kapkaradır kafir yıpratır beni 

Kapkaradır kafir kızdırır beni 

Geceler o sensiz yalnız geceler..................Serdar Sayıl 

24. 

Bağrımda yatıyor, okyanus deniz 

Üstünün örtüsü, göklerde yıldız 

Dert ile doludur, bende ki bu öz 

Dökülüp çağlasam,ALMAZ geceler...................Tuncay Akdeniz 

25. 

Evrende gündüzü aşarak gelir 

Hayaller canlanır koşarak gelir 

Duygular kabarır coşarak gelir 

İlham yağdırmaktan YILMAZ geceler................Mehmet Işıkoğlu 

26. 

Bir güzel derdine çıkam dağlara 

Senin sevdan ile yanam narlara 

Döndürdün yüreğim viran bağlara 

Yardan ayrı ise GEÇMEZ geceler...................Esat Korkmaz 

27. 

Ömür yaklaşmakta sonsuz limana. 

Ecelle yürürüz, izler yan yana. 

Kalp atıyor hâlâ vurmakta cana. 

Vuslat sabahını SALMAZ geceler...................Necmi ÜNSAL 

28. 

Günümüz gam dolu, gecem fazlalık 

Çöktü üstümüze zalim ayrılık 

Hasret bitmez, vuslat uzak gardaşlık 

Sevdama bir muştu, SALMAZ geceler............Yaşar Akbaş', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/GECELER'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun Şİİ...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":145,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar  YALNIZLıK SENFONİSİ', 'sevgiliye-mektuplar-yalnizlik-senfoni-si-olgun-ekinci-wlh0s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '................Savruk düşlerimden solgun yaşantıma giren efsanedeki prenses değildin sen. Günler, yıllar süren yüzyıllık savurganlıklar da tekil yalnızlıklar yaşadığım, sofradaki aşım, çorbadaki tuzum, bardaktaki suyum oldun gelişinle ve henüz kutsanmayan gizemimsin tapınaklarımda... 

................Eflatun rengi ve kırılgan ve hüzün ve uçurum çiçeği serinliğinde yazarken dizelerimi, hazırlanırken yoksul semt pazarlarında satılan eski giysilerin sokak çocuklarındaki eskiz duruşunun dayanılmaz sancılı tariflenmesine… Dizelerin çarptı yüzüme.. Gök gürültülü sağanakların ardı sıra rengarenk gökkuşağının ebruya dökülen yansımasıydın yüzümde... 

............... Virtüözsüz konserlerden solo yaşamlara açılıyordum... Henüz pencere önündeki sarmaşıkların, ıtırlı saksı çiçeklerinin, ortancaların tükenmediği emekçi bir mahallenin sabahlardaki izdüşümlerinden. Ve her sabah kimliksiz, cinsiyetsiz yollardan gidiyordum, geri dönüşü olan, güneşi hep karşımda yansıyan... 

................Tahrip gücü yüksek patlayıcılar yüklüyordum geceden usuma, sessiz patlayan... Dip dalgalarım olsun ruh sürgünü sevdalarda firari aşıkların manifestosu, çöl ayazı susuşlarda gecenin gökkuşağı doğsun diye, ruhu dağınık bir aşk yaşarken yankı yankı sessiz infilaklara gebeydim... 

................Ateşi sönmeyen gözlerime film arası mola vermişliğimin yıllar sürecek sancılı bekleyişlere uzantısının farkında ol(a)  madım... Su vermedim içimdeki köksüz çiçeklere… Kokusu yayılır benden alırlar hoyrat koklarlar diye... Buğday tanesi koymadım yemliğine yüreğimde şakıyan kanaryaların, nağmelerini duyar sustururlar diye... Altın kafese koymadım hiçbir bülbülü vatansız kalmasın diye... 

................ Panayır kalabalığında giydiğim yalnızlık giysilerim yüreğime düşen Cemrenle son buldu. Yeryüzündeki son cemreydin bilinemeyen, saklanan, keşfedilemeyen... İçimdeki deniz, gönlümdeki toprak, soluduğum havaya 

düştün... Önce yavaş, dingin, sessiz... Şimdi Tsunami esrikliğinde bentleri yıkan, coşarak dalga dalga, sevgi sevgi, ırmak ırmak... Terkisi hazır şimdi beyaz atımın kanaviçesiz, çeyizsiz gelişlerine... Güneşi karşımda doğan, karşımda batan yolları kısaltıyorum ulaşmak için... Susuz çiçeklerim kökleniyor, kokusunu sevdana sunmaya… Başak taneleri biriktiriyorum, kanaryalarım ara nağmelerde son ve sonsuz valsımıza senfonileriyle eşlik etsin diye... Ve vatansız sevdalarda bitirmek için firari aşkları, yaşasın yaşansın diye aykırı aşkların tutsakları… 

S enfoniler fısıldayan, keman yayındaki konçert O 

E zgilerin nağmelerinde sen... söylenmemiş fası L 

V e boğaziçinden sahildeki piyaniste uzanan or G 

T ürkülerin kıvamında halay çeken... usta oyunc U 

A şk yolunda savaşan, en yalın en güzel amazo N 

P otbori anılarla efsanem…sevdamsın… 

8.2.2006 - Adana', '................Savruk düşlerimden solgun yaşantıma giren efsanedeki prenses değildin sen. Günler, yıllar süren yüzyıllık savurganlıklar da ...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-yalnizlik-senfonisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Virane Kalbim', 'virane-kalbim-yilmaz-yilmaz-2-aek4l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerdesin sevdiğim nerdesin? 

Sana ulaşmak bu kadar da zor muydu? 

Bu muydu sevgimiz, bu muydu mutluluğumuz? 

Sana kavuşmak bu kadar da zor muydu? 

O ceylan bakışlarını bir daha

Görebilecek miyim? 

Boynuna sarılıp da tekrar tekrar,

Yine ağlayabilecek miyim? 

Her seni hatırladığımda

Anlamsız anlamsız uzaklara

Yine dalacak mıyım? 

Seninle beraber o rüzgarın soğuğunu,

O mevsimlerin eşsiz soluğunu,

Tekrar hissedebilecek miyim? 

Yakıp yıkıp giderken her şeyi…

Düşünmedin mi? 

Hem kendini hem de beni..

Yalnız bıraktığın geceleri…

Hiç düşünmedin mi? 

Sen değil miydin? 

Ölümün önünün sıcak; 

Arkasının da soğuk olduğunu söyleyen? 

Ömrün birkaç ağır sınavdan geçtiğini söyleyen? 

Doğru bildin! 

Sıcakta yandım…

Soğukta dondum…

Şunu bil; şunu bil ama…

Sayende mecnun oldum! 

Bekle geliyorum sevdiğim..bekle…

Hazar’ı aşarak,

Belki de boğularak…

Bekle geliyorum…

Aral’da mola verip,

Balkaş’da konaklayarak…

Kızılkum’da yanarak.

Biliyorum

Belki de bu kara toprak

Sana varmadan

Beni alacak…', 'Nerdesin sevdiğim nerdesin?  Sana ulaşmak bu kadar da zor muydu?  Bu muydu sevgimiz, bu muydu mutluluğumuz?  Sana kavuşmak bu kadar da zor m...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Yılmaz 2']::text[], 8.5, '{"poet":"Yılmaz Yılmaz 2","poet_slug":"yilmaz-yilmaz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/virane-kalbim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-zeynep-aydinlioglu-flqcg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ankara,

Neden puslu bir hava var sende…? 

Hüzün kokuyor soludugum hava 

Kaldırımlar başkalaştı, yollar başkalaştı 

Ankara, 

Bir sonbahar esiyor sende.. 

Güvercinler kendı halınde.. 

Kanaryalar kimbilir 

nerde… 

Eski anılar damla damla yerde.. 

Ankara, 

bir başka hava var sende.. 

Hani dostluk çemberi 

Havadan havaya selamlaşma 

ürken bakışlar 

Eh öylesıne el sıkışmalar 

En tepede sessizce duran 

Adı, 

anılınca susulan 

Bir garip oldun Ankara. 

(02.01.2004)', 'Ankara, Neden puslu bir hava var sende…?  Hüzün kokuyor soludugum hava  Kaldırımlar başkalaştı, yollar başkalaştı  Ankara,  Bir sonbahar esi...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ankara-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Gibi Olmak Gerek', 'toprak-gibi-olmak-gerek-yusuf-onder-bahceci-rwpue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprak gibi olmak gerekir kara toprak,

Toprak da yetişiyor güller ve zambak,

İnanmazsan şöyle göz gezdir bir bak,

Toprak gibi olmak gerekir kara toprak.

Bizi topraktan Yaratmış, topraktan bak,

İşte bunun için isyan etti Şeytan ahmak,

Toprak gibi olursan olur, gül, madımak, 

Toprak gibi olmak gerekir kara toprak.

Toprak gibi olursan sende güller biter,

Toprak gibi olursan sende olur ümitler,

Toprak gibi olursan hep Baharı bekler,

Toprak gibi olmak gerekir kara toprak.

Biz sonunda hep olacağız kara toprak,

İşte bunun için Yaratmış, Yaratan Hâk,

Kıyametin alameti Kıyamete az ramak,

Toprak gibi olmak gerekir kara toprak.', 'Toprak gibi olmak gerekir kara toprak, Toprak da yetişiyor güller ve zambak, İnanmazsan şöyle göz gezdir bir bak, Toprak gibi olmak gerekir ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/toprak-gibi-olmak-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^^^^ Yakındaki Gurbet ^^^^', 'yakindaki-gurbet-zeynep-aydinlioglu-doy94', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gurbet 

Fasıl oldu 

Söylenir içimde 

Ne 

Giden geri geldi 

Nede 

Yangının bitti bende… 

Gurbet 

Nasır oldu 

Kabuk bagladı yüreğim de 

Ne 

Sızına çare bulundu 

Ne de 

Uzaklara bakmam bitti bende… 

Gurbet 

Yoktan hasıl oldu 

Burcu burcu koktun çiçeklerde… 

Ne 

Güneş gülüşün söndü 

Ne de 

Bekleyişin bitti bende… 

Gurbet 

Dendi adına 

Seni her an görsem de 

Ne 

Bakışın döndü bana 

Ne de 

Yolumuz birleşti köşelerde 

Yakınlar 

Gurbet oldu ikimiz içinde… 

(13.02.2006)', 'Gurbet  Fasıl oldu  Söylenir içimde  Ne  Giden geri geldi  Nede  Yangının bitti bende…  Gurbet  Nasır oldu  Kabuk bagladı yüreğim de  Ne  Sı...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yakindaki-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemre', 'cemre-ali-i-hsan-ozturk-3d0qm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cemre düştü havaya 

Çiçek taktım abaya

Geleceksen gel artık

Bahar geldi obaya.

Yeşil örtündü kırlar

Ortaya çıktı sırlar

Özlem arşa ulaştı

Bitmiyor hiç dırdırlar.

Bana hayat veriyor

Senin aldığın nefes

Hep içime giriyor

Bitmeyecek bir heves.

Gelmen yakın sanırım

Kavuşmaya az kaldı

Ben sana aldanırım 

Sözler bitti saz kaldı.

Elim kolum bağlıyor

Yağan yağmur oldu sel

Aşk kalbimi dağlıyor

Yeter artık hadi gel.', 'Cemre düştü havaya  Çiçek taktım abaya Geleceksen gel artık Bahar geldi obaya. Yeşil örtündü kırlar Ortaya çıktı sırlar Özlem arşa ulaştı Bi...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Öztürk']::text[], 8.5, '{"poet":"Ali İhsan Öztürk","poet_slug":"ali-i-hsan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cemre-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hüzün', 'bir-huzun-tahmine-yildirim-a1k8q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak yine içim acıdı işte

Bu aralar nedense pek sık oluyor

Nedir bu yaa niye içime geliyor

Hüzünler geliyor acımasızca üstüme üstüme.

Niye söz geçiremiyorum içime 

Dağdan düşen kaya parçasına benzedim

Pare pare oluyorum

Paralıyor içimi ve bedenimi hüzünler

İstemek ve onun olması 

Çokmu apayrı şeyler anlamadım

Karanlıktayım bir ışık bile yakamadım

İzin vermiyor hüzünler ışığa bakamadım

Kovmak istiyorum içimden

Gelmesinler bana ben onları istemeden

Sağlığımı yitirip hastalıklar gelmeden

Hüzünler bırakmayacak beni ecel bana gelmeden.....', 'Bak yine içim acıdı işte Bu aralar nedense pek sık oluyor Nedir bu yaa niye içime geliyor Hüzünler geliyor acımasızca üstüme üstüme. Niye sö...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-huzun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Bulduk Dünya', 'hos-bulduk-dunya-muammer-erturan-tshf6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hitler gebereli altı yıl olmuş 

milli şef dönemi kapanalı beş… 

Müstakbel eyaletinin bulanık sularında 

balığa çıkmış yanki

oltasında margarinler, süt tozları... 

En azgın zamanları ''Demirkırat''ın

sökülmesine sökülecek nalları ya 

dokuz yıl sonra... 

Akadursun zaman 

dönedursun devran böylece 

dokuz ay on gün önce biçilmiş hükmüm

ve infaz günüm gelmiş çatmış... 

Sıradan bir cumartesiye benziyor uzaktan 

takvimlere bakarsan Aralık’ın onbeşi... 

Erken saatlerinde sabahın 

karakış teslim almış kasabayı 

sokaklar diz boyu kar... 

Dudu hanımın kiracılarının 

eski gazete kaplı cam önlerinde 

bir mısır tanesine 

bin nağme döktürüyor kuşlar

ve hane halkı 

hummalı bir telaş içinde... 

Ve ayağa kalkıyor Gönen 

şaplağı yer yemez ebeden: 

Ingaaaaa! 

Ingaa! 

Ingaaaaaaa! ... 

Hoş bulduk dünya! ...

''97', 'Hitler gebereli altı yıl olmuş  milli şef dönemi kapanalı beş…  Müstakbel eyaletinin bulanık sularında  balığa çıkmış yanki oltasında margar...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hos-bulduk-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkasına Yapma', 'baskasina-yapma-yusuf-onder-bahceci-ykj2u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Flört, mlört anlamam ben gezersem alırım,

Bacımı alıp gezseler herhalde cânını alırım,

Ne diyor İslam, iyi dinle, dinle, bre ahmak,

Sana yapılmasını istemediğini sen yapma.

Senin ki cân da diğerlerinin ki patlıcan mı,

Nâmuslu olsan ne var yoksa patlıyacan mı,

Kadınlar çamaşırmı be alçak katlıyacan mı,

Sana yapılmasını istemediğini sen yapma.

Bu kadınların kimisi benim, kimisi de senin,

Annen, teyzen, halan, bacım, kardeşim olur.

Dünya ve Ukba''da hedefi, namuslular bulur,

Sana yapılmasını istemediğini sen yapma.

Kadın mal değildir, sen alıp ta satamazsın,

Başlık parası, kan hakkı diye uyutamazsın,

O senin öz evladındır, para ile satamazsın,

Sana yapılmasını istemediğini sen yapma.', 'Flört, mlört anlamam ben gezersem alırım, Bacımı alıp gezseler herhalde cânını alırım, Ne diyor İslam, iyi dinle, dinle, bre ahmak, Sana yap...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baskasina-yapma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıkırdaklarım Üşüyor', 'kikirdaklarim-usuyor-mehmet-akif-tiryaki-87yyn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kıkırdaklarım üşüyor,

Kararsız bir dönem,

Pencereler açık,

Perdeler bayrak bayrak

Teslim olanlar esnaf,

Teslim alan şu bankacılar,

Kıkırdaklarım üşüyor,

Muhatap zavallılar,

Önceden dediler ki

Matematik ne işe yarar

Pencerelerde beyaz bayraklar

İnsanlar tutsak olmuş,

İnsanlar ağlar,

Ortalıkta fırıldakçılar

Muhatap zavallılar

Ödeme gününde

Etekleri zil çalar

Karalar bağlar,

Minimum ödeme miktarını

Konu komşuda arar.', 'Kıkırdaklarım üşüyor, Kararsız bir dönem, Pencereler açık, Perdeler bayrak bayrak Teslim olanlar esnaf, Teslim alan şu bankacılar, Kıkırdakl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kikirdaklarim-usuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüzlüğe 1', 'olumsuzluge-1-ali-i-hsan-ozturk-7f85l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıradan bir arkadaştık seninle

Sonra ise iki aşık

Ne çok severdik birbirimizi

Gençliğin bütün hırçınlığı,

Bütün  dolu dizginliği içerisinde

Aşkımızdı bizi bağlayan

Hayatın anlamlılığına.

Öyle anlayışlı, öyle aydındın ki

Bazı ihtiyaçlarım için 

Başkalarıyla olmama aldırmaz,

Gereksiz krizlere mehil vermezdin

Benim seni çok sevdiğime,

Hemde ölesiye çok sevdiğime,

Senin olduğuma, 

Sonsuz güvenir…

Aşkımın yüceliğine biat ederdin.

Benim sana ettiğim gibi', 'Sıradan bir arkadaştık seninle Sonra ise iki aşık Ne çok severdik birbirimizi Gençliğin bütün hırçınlığı, Bütün  dolu dizginliği içerisinde ...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Öztürk']::text[], 8.5, '{"poet":"Ali İhsan Öztürk","poet_slug":"ali-i-hsan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olumsuzluge-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Gezgin', 'i-cimdeki-gezgin-dolunay-kara-js8is', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün hava bir başka! 

Güneş seni özlemekte,

Bulutlar hasretini tüketmekte,

Seni sevmek bir başka bu mevsimde! 

Bugün sahil kenarında,

Umutlarımla dalgalanan denize baktım.

Huzur buldu içimdeki gezgin! 

Kız kulesi ihtişamlıydı senin kadar,

Mutluydu martılar benim kadar! 

Vapurlara el sallamak geldi içimden! 

Güle güle demek istedim son defa hasretime.

Kulağımda muhteşem bir müzik,

Daha önce hiç aklıma gelmeyen düşünceler...

Bana çarparcasına yürüyen insanlar,

Nasıl da büyük bir telaşın içindeler.

Oysa benim hiç acelem yok! 

Hayat mutlu,hayat karışık,

Hayat olağanüstü bir yaratık! 

Ne duruyorsun,

Sımsıkı sarıl ona! 

Hayat onu sevmeyenlere kötü davranıyor,

Tıpkı bir insan gibi...

Bunu geç de olsa anladım.

Onun anahtarını yüreğimde sakladım.

Olanla ölene çare yok bu dünyada,

Ne yapalım sen de içimdesin tatlı bela! 

Olmuş bir kere,bulunmaz buna deva.', 'Bugün hava bir başka!  Güneş seni özlemekte, Bulutlar hasretini tüketmekte, Seni sevmek bir başka bu mevsimde!  Bugün sahil kenarında, Umutl...', ARRAY['Türk Edebiyatı','Şiir','Dolunay Kara']::text[], 8.5, '{"poet":"Dolunay Kara","poet_slug":"dolunay-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/icimdeki-gezgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkülerde yaşadım...', 'turkulerde-yasadim-yusuf-ziya-leblebici-u5l4x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni; iğde kokularıyla 

çektim içime 

Anadolu bağlarında. 

Köylerim kültürümsü havası 

buğdayların sarısı 

kağnıların gıcırtısıyla 

oturdun yüreğime... 

Seni; tandırların kokusuyla 

katmer tadıyla, 

anamın şefkatiyle soludum. 

Derelerden içtim seni 

yudum yudum... 

Bağdaki koruklarda 

okşadım seni, 

dalındaki her taneni. 

Kavallarda dinledim seni 

Anadolu''nun nefesinde 

türkülerde yaşadım seni...', 'Seni; iğde kokularıyla  çektim içime  Anadolu bağlarında.  Köylerim kültürümsü havası  buğdayların sarısı  kağnıların gıcırtısıyla  oturdun ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/turkulerde-yasadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumu Emziren Kadın', 'ruhumu-emziren-kadin-ali-gencay-ay2k1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruhumu emziren kadın

Tut ellerimi

Bugün yarından yakın

Geç buldum seni

Şimdi; 

Eken mi gitmek maksadın

Daha erken, vakit varken

Geceyi yakalım

Yağmurlar yağarken

Üşüyor/titriyor ellerin

Sanki; 

Var gizlin saklın

Dudaklarından düşecek

Kırılacak vuslatın

Gözlerin kapıda

Erken mi gitmek maksadın

Yıldızlar takayım saçına

Teninde güller açsın

Gözlerin alev saçsın

Geceyi sevdiren sen

At siyahı üzerinden

Halen üstünü çıkarmadın

Erken mi gitmek maksadın

Şarkılar söyle 

Efkarım buz olsun dağılsın

Yanaş ta yakınıma

Hasretin parçalansın

Gitmek mi maksadın

Durma git

Bana benden yakınsın

Değerse tenime başka ten

Kavrulsun/yansın…', 'Ruhumu emziren kadın Tut ellerimi Bugün yarından yakın Geç buldum seni Şimdi;  Eken mi gitmek maksadın Daha erken, vakit varken Geceyi yakal...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ruhumu-emziren-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus konuşma!', 'sus-konusma-yusuf-ziya-leblebici-fbser', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sus konuşma, açma ağzını. 

Ben görmek istiyorum güzellikleri. 

Anlatma ağacı, meyveleri 

ördekli dereleri... 

Toprakta yetişen çiçeği 

Tarladaki üreyen ekini 

Ben görmek istiyorum esmer çiftçiyi.. 

İnsanlar gülüyor deme bana. 

Vapurda şakalaşan 

trende konuşan 

parklarda oynayan çocukları 

süzmek istiyorum 

yıkarak bu duvarları... 

Sus, açma ağzını. 

Anlatma bana duyduklarını. 

Yarından korkmayan 

gözlerinde çiçek açan 

insanları istiyorum. 

Onlarda mutluluk 

onlarda güzellik görmeyi bekliyorum. 

Sus, konuşma. 

Senin tatlı dilini değil, 

Gözlerindeki gerçeği ver bana. 

Gözlerimde yaşat dünyayı 

Ben görmek istiyorum 

yürekten gülen insanları...', 'Sus konuşma, açma ağzını.  Ben görmek istiyorum güzellikleri.  Anlatma ağacı, meyveleri  ördekli dereleri...  Toprakta yetişen çiçeği  Tarla...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sus-konusma-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulur Aşk', 'unutulur-ask-ahmet-unal-cam-ag2fe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her acımda, her hüznümde

  şiirler geçer,

       içerimi dağlarım

Kırık aynalara baktım da

Boşa geçer, boşa yıllarım.

Değsen ne olur, gözyaşıma elinle

Ağlamadıktan sonra benimle

Her akşam, her akşam yıldızlara

    bakar bakar ağlarım.

İçim yanar, kavrulur

Gün gelir unutulur aşk,

Aşk, bir rüzğarla savrulur

Silinir acı hatıralarım.

Bir şarkı süzülür gelir

Sanki halimi bilir

Yıkılırken, omuz verir

Çekip gitse dostlarım.', 'Her acımda, her hüznümde   şiirler geçer,        içerimi dağlarım Kırık aynalara baktım da Boşa geçer, boşa yıllarım. Değsen ne olur, gözyaş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unutulur-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştım', 'alistim-ahmet-unal-cam-8euse', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her yıkılışımda yeniden

   doğrulmaya çalıştım

 Acılarla birlikte

   yaşamaya alıştım.', 'Her yıkılışımda yeniden    doğrulmaya çalıştım  Acılarla birlikte    yaşamaya alıştım....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/alistim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurulur Baş Köşeye Acılar', 'kurulur-bas-koseye-acilar-ahmet-unal-cam-bhb1i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'o mahzun bakışlar

   yıkar beni

''Unuttum'' derken aşkı

yeniden başlar çırpınış

   yüreğimde

   *     *    *

Yeniden kahroluşlar

Yeni karşılıksız sevdalar

Acıların yenisi

Kurulur baş köşeye

  yüreğimde

   *     *    *

Bir cesaretsizlik

    bağlar kolumu

Düşünmek istemesem de

    sonumu

Acılardan dağlar olur

    yüreğimde

Her acı tekrar tekrar

    kapatır yolumu', 'o mahzun bakışlar    yıkar beni ''Unuttum'' derken aşkı yeniden başlar çırpınış    yüreğimde    *     *    * Yeniden kahroluşlar Yeni karşılık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kurulur-bas-koseye-acilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamüstü Kızılayda', 'aksamustu-kizilayda-ahmet-unal-cam-nwalg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalabalık akıyor,o yandan o yana

Aklım sana gidip gidip geliyor.

Anlamıyor insanlar beni,anlamıyor.

Çalıyor bir kaset,ortalıkta gürültü

Senden gayrısını kulaklarım duymuyor,

                  gözlerim görmüyor.

Saatler beş''i vuruyor Kızılayda

Sensiz bir akşam daha yaklaşıyor,

    geliyor pervasızca üstüme.

Ne dizlerimde derman,

Ne içimde umut kalmış,

    kıpırdamıyorum bile.

Karanfil sokağı telaşlı,

Kalabalık akıyor o yandan o yana.

    *           *           *

Gözlerim,seni görmüş bir renkte,

Ben sendeyim,ya da sen bende

   Karanfil sokağı yok,

   İnsanlar yok,

   Kasetçiden gelen ses yok,

Zaman-mekan kaybolmuş,

Sen ve ben varız; 

Bir şeyler fısıldıyorsun kulağıma,

Anlamıyorum,dinlemiyorum,

Dalmışım güzelliğine.

Sesin sadece bir nağme,

   sözcükler önemsiz.

Konuşuyor,gülümsüyorsun,

   ellerini uzatıyorsun,

   ellerimi uzatıyorum...

...ellerim boşlukta kalıyor.

Gülüşler,garip bakışlar üstümde

   dönüyorum gerçeğe; 

   sen yoksun! ..sen yoksun! ..

Utanarak indiriyorum ellerimi.

Gülümseyişin uzaklaşan bir kızda

                        kalıyor.

Saatler durmuyor

  akşamın altısındayım Kızılayda.

Bir daha,bir daha uyanıyorum

 ...sensizliğe.', 'Kalabalık akıyor,o yandan o yana Aklım sana gidip gidip geliyor. Anlamıyor insanlar beni,anlamıyor. Çalıyor bir kaset,ortalıkta gürültü Send...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/aksamustu-kizilayda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor beni...', 'sor-beni-yusuf-ziya-leblebici-88vvb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün bir ses duyarsan buradan uzaklardan 

Rüzgar getirse dinlediğimiz şarkıları 

Acı acı cama vuran yağmur damlasından 

Sor beni, ne yapmışım sen gittiğinden beri 

Bulutlardan yağan yağmurlar gözyaşım mıdır 

Çakan o şimşekler sana haykırışım mıdır 

Neler yapmışım ben, sen olmayınca yanımda 

Sor beni, sensizlik benim yıkılışım mıdır 

Yağmur yağarken şöylesine bak pencerenden 

Benim hayatım mıdır camdan kayıp da giden 

İsmimi yaz parmaklarınla buğulu cama 

Silinip giden ben miyim senin ellerinden 

Sor beni gözlerine, sor beni ne görüyor 

Bu adam tek başına nerede, ne yapıyor 

Kulaklarına inen o bildiğim şarkılar 

Seni, benim için nerelere götürüyor 

Olur da bir gün dönersen gittiğin o güne 

Yolara bak, ayak izin hala duruyor mu 

Senin için yazdığım kederli şiirlere 

Sor beni, hala senin yolunu bekliyor mu', 'Bir gün bir ses duyarsan buradan uzaklardan  Rüzgar getirse dinlediğimiz şarkıları  Acı acı cama vuran yağmur damlasından  Sor beni, ne yapm...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sor-beni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün Kapılar Açılır', 'birgun-kapilar-acilir-yusuf-onder-bahceci-f0267', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim uyursa kâlbim uyumaz,

Kulağım sa başka sözü duymaz,

Sabaha dek ederim, dua, niyaz,

Elbet birgün kapılar, açılır bana.

Dua olmasaydı neye yarardınız,

Siz bu Dünya''da, neye yandınız,

Kâlbiniz çok safdı hep inandınız,

Elbet birgün kapılar, açılır sana.

Dua edin, icabet edeyim, diyor,

Dua edenleri ise O çok seviyor,

İşte benim Kullarım bunlar diyor,

Elbet birgün kapılar, açılır sana.

Gönülden gizlice dualar etmeli,

Duam kabul olmadı dememeli,

Kesinlikle hiç haram yememeli,

Elbet birgün kapılar, açılır sana', 'Gözlerim uyursa kâlbim uyumaz, Kulağım sa başka sözü duymaz, Sabaha dek ederim, dua, niyaz, Elbet birgün kapılar, açılır bana. Dua olmasaydı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birgun-kapilar-acilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapisten Mektup', 'hapisten-mektup-ahmet-unal-cam-wywa9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceleri,yalnızlığa sarılıp ta

  uyurum,

Hasret yiyip,dert içip

  büyürüm.

Yollarıma güller ser ki

  gülüm

Belki bu gün,belki yarın

  gelirim.

Buharı tütsün,hazır olsun

  çayın,

Gözün yolda olsun,açık kalsın

  kapın.

Boş kalmış ya son resminde

  sağ yanın,

Girmek için sağ koluna

  gelirim.

Gülüm,beton yerde

  gül bitmez.

Mektup,selam bana

  kar etmez,

Bu dört duvar beni

  hapsetmez,

Gözlerimi kapar

  gelirim.', 'Geceleri,yalnızlığa sarılıp ta   uyurum, Hasret yiyip,dert içip   büyürüm. Yollarıma güller ser ki   gülüm Belki bu gün,belki yarın   geliri...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hapisten-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut', 'bir-umut-muammer-erturan-3ezdh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her zaman

her durumda

bir umut vardır mutlaka...

Her şey bitti

karardı dünyam

derken tam

bir de bakmışsın ki

tünelin ucunda bir ışık

göz kırpmakta...

Her zaman,

her durumda

bir umut vardır...

Bin çiçek solmuş olsa bile

gönül bahçende

bir tohum vardır

yeşermeye hazır her an...

Her durum,

bir umuda gebedir

en azından

her zaman için...

Ne zaman ve nerede

ve nasıl doğuracağı

ayrı hikâye...

(20 Haziran ''99)', 'Her zaman her durumda bir umut vardır mutlaka... Her şey bitti karardı dünyam derken tam bir de bakmışsın ki tünelin ucunda bir ışık göz kır...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-umut-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Şiirler Bitecek', 'huzunlu-siirler-bitecek-ahmet-unal-cam-b3mn3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '**************************************

  * HÜZÜNLÜ ŞİİRLER BİTECEK  *

  * Bir gün olacak                             *

  *   geleceksin,                                *

  * Önce dizelerim gülecek             *

  *   sonra yüzüm.                             *

  **************************************', '**************************************   * HÜZÜNLÜ ŞİİRLER BİTECEK  *   * Bir gün olacak                             *   *   geleceksin,    ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/huzunlu-siirler-bitecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-koray-ergul-o2nbs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden 

Birdenbire buz keser hava? 

Neden 

Bu akşam 

Bu bıçak 

Alabildiğine kusursuz ve parlak? 

Neden 

Gecenin mavisine vurulur insanlar? 

Ve neden

Her kadın bir an

Sana benzer?', 'Neden  Birdenbire buz keser hava?  Neden  Bu akşam  Bu bıçak  Alabildiğine kusursuz ve parlak?  Neden  Gecenin mavisine vurulur insanlar?  V...', ARRAY['Türk Edebiyatı','Şiir','Koray Ergül']::text[], 8.5, '{"poet":"Koray Ergül","poet_slug":"koray-ergul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/neden-223-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımızın Soruları', 'hayatimizin-sorulari-dolunay-kara-p3yrf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat öylesine gelip geçiyor,

Gerek kavgayla gerek yalanla.

Kim kimi kandırıyor acaba! 

Biz mi hayatı,hayat mı bizi,

Yoksa bunlarla kendi kendimizi mi? 

Duygularımız ne kadar gerçek? 

Ne kadarı içten ne kadarı sahte! 

Ya gözyaşlarımız ne kadar acıklı? 

Halbuki onları acıklı kılan,

İnsanoğlunun taşıdığı mutsuz çehre! 

Gülüşlerimiz ne kadar sevinçli? 

Aşklarımızda karar alırken

Beynimizi mi dinliyoruz,

Yoksa kalbimize mi kulak kabartıyoruz? 

Hayatta hiç heyecan yaşıyor muyuz? 

Doğallığa ne kadar önem veriyoruz? 

Nasıl ilişkiler yaşıyoruz? 

Yaşadıklarımızda ne kadar hakkımız var! 

Ne kadar özgürüz,ne kadar bağlıyız? 

İçimizde hangi sessiz isyanları,

Hangi çatışma seslerini taşıyoruz? 

Görüyor mu gözlerimiz ileriyi? 

Biliyor muyuz ki,

Bu hayat ne kadar yapmacık,

Ne kadar geçici!', 'Hayat öylesine gelip geçiyor, Gerek kavgayla gerek yalanla. Kim kimi kandırıyor acaba!  Biz mi hayatı,hayat mı bizi, Yoksa bunlarla kendi ke...', ARRAY['Türk Edebiyatı','Şiir','Dolunay Kara']::text[], 8.5, '{"poet":"Dolunay Kara","poet_slug":"dolunay-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayatimizin-sorulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Roman Sancısı', 'roman-sancisi-murat-polat-2-cu1lu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elbette yazılacak bu roman

Amaç kimse zarar görmesin mi? 

Yoksa kaybedenler olsada –mutlak-

Kazananlar da olsun mu? 

Hem niye yazılacak bu roman

Kimi anlatacak kime? 

Ayrılanı sevdiğine mi kavuşturacak? 

Hesaplaşma mı yoksa yine? 

Hem niye yazılsın ki bu roman

Hep başkası olmak isterken insan

Bende kendilerini mi görsünler? 

Kim görmek ister, kül olmuş alevi

Ben neyi yazayım...

Ben kime yazayım...

                                

                          15 Şubat 2006', 'Elbette yazılacak bu roman Amaç kimse zarar görmesin mi?  Yoksa kaybedenler olsada –mutlak- Kazananlar da olsun mu?  Hem niye yazılacak bu r...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/roman-sancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-muammer-erturan-focjf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İmansız bulutlar sarmış

güneşi ve şehirleri...

İnsan maskeli robotlar

her köşe başında,

tüketmeye hazır herşeyi,

her an...

Kendi elleriyle

kendi kuyusunu

kazma şampiyonu olmuş

çıkmış insan...

Ozan der:

Nereden nereye gelmişiz...

Ne bozmuş bizi? ..

Bozan der:

''Biz'' neyin nesi? ..

''Ben''den öte köy yok...

(''01)', 'İmansız bulutlar sarmış güneşi ve şehirleri... İnsan maskeli robotlar her köşe başında, tüketmeye hazır herşeyi, her an... Kendi elleriyle k...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biz-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüzlüğe 2', 'olumsuzluge-2-ali-i-hsan-ozturk-nb2de', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıl 1988 

İşte lanetli yıl

Kaderin bütün tuzaklarına düştüğüm,

Bütün darbeleri apansız yediğim yıl.

Bir gece yarısı ansızın patlayıverdi tabancalar

Ölümün soğuk yüzünü yaşadım o an,

Vurulmuştum.

Öldüğüm duyuruldu dört bir yana

Bense her şeyden habersiz komada

Tam 15 gün dünyasız yaşadım

Bitkisel hayatta.

Bir ay sonra taburcu olup çıktığımda

Seni aradım…

Telefonla, evinde, sokaklarda…

Tüm kapılar bir bir kapanıyordu yüzüme

Neden dedim,

Neden herkes cevapsız

Kara haber tez duyulurdu ya hani

Senin kara haberin bana ulaşamıyordu bir türlü.

Annenden öğrendim öldüğünü

Lanetlerin en büyüğünü sayarken bana

“Hani sen ölmüştün” diyordu

“Kızım sen öldüğün için canına kıydı” diyordu

Nefretlerin en kutsalını

Bir ana yüreğiyle kusuyordu yüzüme

O kustukça ben ölüyordum.

İçimde derinliklerimden gelen sızıyla

Taze topraklı mezarını buldum

Öptüm doyasıya toprağını, koklayarak

Mezar taşın yaptırılmamıştı henüz

Daha üzerinde konulan çiçekler kurumamıştı

O mezarda senin yattığına inanamadım

Aradım seni tüm olası yerlerde

Ama yoktun. Bulamadım

Zor geliyor sensiz kalmak', 'Yıl 1988  İşte lanetli yıl Kaderin bütün tuzaklarına düştüğüm, Bütün darbeleri apansız yediğim yıl. Bir gece yarısı ansızın patlayıverdi tab...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Öztürk']::text[], 8.5, '{"poet":"Ali İhsan Öztürk","poet_slug":"ali-i-hsan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/olumsuzluge-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyorlar', 'diyorlar-i-brahim-pataz-p5eqk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suya sabuna dokunma,

Ne yazarsan, yaz diyorlar

Olan bitenden, yakınma,

Bak da görmez, gez diyorlar.

Tarif edilir, şöyle bir yol,

Görsen, duysan da sağır ol,

Acele etme, ağır ol,

Niye varız biz, diyorlar? 

Koyun ol, sürüye katıl,

Köle ol, pazarda satıl,

Bir işe, yürütme akıl,

Ne anla, ne sez diyorlar.

Deme, ayıbı, kayıbı,

Elbet yapılır, icabı,

Bu ülkenin, var sahibi,

Sana düşmez, söz diyorlar.

Yerinden oynasın taşlar,

Ayağa eğilsin, başlar,

Kırka katlansın, maaşlar,

Gene, bize az diyorlar.

Yasalarda yok gördüğüm,

Zavırı bastı sorduğum

Her işte, bin bir kör düğüm,

Yolunu bul, çöz diyorlar.

Sığmasın akla vicdana,

Dürüstlük, ne verdi sana? 

Sen de geç soyandan yana,

Bul da yol, bir kaz diyorlar.

ELEMİ, eyleme güman,

Pişman etmezler, bir zaman,

Bak, Allah, Peygamber, Kur’an,

Hakkı söyle, yaz diyorlar.

14.02.2006 Adana', 'Suya sabuna dokunma, Ne yazarsan, yaz diyorlar Olan bitenden, yakınma, Bak da görmez, gez diyorlar. Tarif edilir, şöyle bir yol, Görsen, duy...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/diyorlar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-040 Dalga,', 'ub-040-dalga-mehmet-coban-e6mlh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzeldir denizlerin üstünde

Seyretmeye doyum olmaz

Çirkindir insanların sözlerinde

Çekilmeye tahammül kalmaz

Güzeldir edebiyatta, sanatta

Seyre doyum olmaz

Çirkindir yaşanılan hayatta

Sonuçlarına katlanılamaz

Güzeldir düşüncelerde gezinirken

Düşünmeye, öğrenmeye doyum olmaz

Çirkindir düşüncelerin yaşamında

İhanetten başka hiç anılmaz

Güzeldir toplumlar ayağa kalktığında

Yürüyüşleriyle ortada zulüm kalmaz

Çirkindir, dogmalarda, yasalarda

İnsan hayatıyla oynanmaz

15.02.2006-İzmir', 'Güzeldir denizlerin üstünde Seyretmeye doyum olmaz Çirkindir insanların sözlerinde Çekilmeye tahammül kalmaz Güzeldir edebiyatta, sanatta Se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ub-040-dalga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun', 'gidiyorsun-mehmet-postalli-psk0r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ali Osman KESKİN Ağabeyimin Aziz Hatırasına

Umulmadık bir zamanda

Birden geçip gidiyorsun

Geldin konakladın handa 

Şimdi çekip gidiyorsun

	Dün bizimle yan yanaydın

	Bugün neden ayrı kaldın? 

	Saraydan davet mi aldın? 

	Hemen koşup gidiyorsun

Doyasıya gün görmeden

Rahat bir ömür sürmeden

Kimseye haber vermeden

Sessiz göçüp gidiyorsun

	Ecel yakana sarıldı

	Çarkın dişlisi kırıldı

	Hep işlerin yarım kaldı

	Döküp, saçıp gidiyorsun

Yoruldu mu kan pompası? 

Yetmez doktorun çabası

Kuşandın beyaz libası

Sal’da uçup gidiyorsun

	Tükendi mi suyun, aşın? 

	Çare yok ağrısa başın

	En sevgili arkadaşın; 

	Ah, bırakıp gidiyorsun

Suskunsun bu ne hal desem

Durmazsın, gitme kal desem

Dönen yok haber sal desem

Yollar aşıp gidiyorsun

	Hatıran kaldı geride

	Kavuşuruz ileride 

	Girdin dönülmez şeride

	Uzaklaşıp gidiyorsun

Gidiyorsun, gidiyorsun

Sessiz veda ediyorsun.', 'Ali Osman KESKİN Ağabeyimin Aziz Hatırasına Umulmadık bir zamanda Birden geçip gidiyorsun Geldin konakladın handa  Şimdi çekip gidiyorsun 	D...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gidiyorsun-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurun Uçurtmaları', 'ucurun-ucurtmalari-halil-i-brahim-akay-smjts', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yükseklerde salınıyor,

Hayallerimin şehrine doğru.

Bir tek o kaldı geriye,

Çocukluğumun yadigarı.

Uçurun uçurtmaları,

Bütün umutlarınızı kuyruğuna takarak.

Uçurtmadaki anılar

Rüzgar estikçe parlar.

Hayallere engel olmaz rüzgarlar.

Konuşuyor uçurtmalar,

Yükseklerde özgürce süzülürken.

“Ben engelleri aşarak yükselirim” diyor,

“Ben ufuklara taşırım umutları”.

Bir tek tellere takılmasın.

Umutların tel örgülerde kaldığı gibi,

Çaresizce.

Daha baharlar devam edecekken,

Ve insanlar, ömürlerinde baharı beklerken.

Bir çocuğun gözyaşları kadar

İçten ve hüzün dolu

Masumların ahını yükseklere

Duam olup taşır mısın? 

Çocukluğunu yaşayamayanlara

Çocuk olmayı anlatır mısın? 

Bir çocuğun küçük ellerinden

Bana bir çocuk kalbi kadar

Mutluluklar getirir misin? 

Ben senin her süzülüşünde

Umutları görüyorum

Ve senin ufuklara yükseldiğin gibi

Ufuklardan baharları bekliyorum.

Sevgi, umut ve mutluluk dolu baharları

(İstanbul, 18 Mayıs 2003)', 'Yükseklerde salınıyor, Hayallerimin şehrine doğru. Bir tek o kaldı geriye, Çocukluğumun yadigarı. Uçurun uçurtmaları, Bütün umutlarınızı kuy...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Akay']::text[], 8.5, '{"poet":"Halil İbrahim Akay","poet_slug":"halil-i-brahim-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ucurun-ucurtmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı Bulut', 'sevdali-bulut-h-hikmet-esen-54dkk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevginin adını,

''Bulut'' koymuşlar; 

Ve salmışlar gökyüzüne.

Kimi zaman yokolmuş,

Güneş''te; 

Kimi zaman yansıyan desenlerde.

Hatta bazen,

Beyazın tonlarında

Ağlarmış yalnızlığına...

Ama, 

Tutsak olmamış asla..!', 'Sevginin adını, ''Bulut'' koymuşlar;  Ve salmışlar gökyüzüne. Kimi zaman yokolmuş, Güneş''te;  Kimi zaman yansıyan desenlerde. Hatta bazen, Bey...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdali-bulut-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-095 Sorumluluk! ..', 'ub-095-sorumluluk-mehmet-coban-ybmld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilgi öğrenilir

Kolaydır

Ama 

Sorumluluk? 

Öğrenileceklerden

Duygusal etkilenmemek

Bilinçle seçip ayırmak

Akıl, muhakeme ile

Doğru kararlara ulaşmak

Öğrenilenleri

Özümlemek

Duygulanmak

Düşünce taşı yapmak

Hayata, yaşama katmak

Sabırla takip etmek

Eyleme dönüştürmek

Sonuca eriştirmek 

Bilgiyle ermek gibi

Bilgiyle büyümek gibi

Sorumluluk olmazsa

Öğrenilen hayatta yoksa

Öğrenilen bilgi

Sanki yük gibi! ..

Bilgiyi taşıyan

Sanki eşek gibi! ..

15.02.2006-İzmir', 'Bilgi öğrenilir Kolaydır Ama  Sorumluluk?  Öğrenileceklerden Duygusal etkilenmemek Bilinçle seçip ayırmak Akıl, muhakeme ile Doğru kararlara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ub-095-sorumluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar  SIĞINDıĞIM LİMAN''IM', 'sevgiliye-mektuplar-sigindigim-li-man-im-olgun-ekinci-9z1wr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '............... Serüvensiz seferlerden yorgun düşüp, dalgaların dansında alaboralar yaşayan, huzur, sevgi, sıcak, korunaklı limanına demirlemek isteyen serseri, dipsiz bir tekneyim.. Bandırası olmayan, güvertesinde ateşböceği ışıltısında yaşayacağı aşka, yıldızların altında valsa susamış.. 

............... Egeden zeytin, Akdenizin portakal çiçekli kokuları var, kaptan köşkümün gizlediğim sır vermeyen bölmelerinde, lirik Venedik şişenin mantarı açılmamış diplerinde… Martılar ötüşürken sabah alacasında kahvaltın, kızıllığında batarken güneş akşam sefa çayların olmalıyım, sonrasında çekilen nikotinlere ortak, üflenen dumanlara hasret, izmarite serçe parmağında dokunuşlarım.. 

............... Vadileri uçsuz bucaksız, yollarının keşfedilmediği, egzotik, dalgasız, sahildeki tonlarının renkten renge raksettiği mini bir koy, o koyda sessiz, dipsiz iskele olmalısın, kıyına sadece benim yanaşacağım, diğer ve yabanıl teknecikler olmamalı yakınında, uzağında, dürbün mesafesinde… 

............... Tentelerim param parça açıkta beklemekten, pusulam yanlış yönlendirdi dümenimi, sahipsiz, kıyısız ıssız, tenhalara sürükledi yelkenlerim, rüzgarı yanlış algılayıp tersine rotalar düşürdüm güverteme.. oysa mülteci yalnızlıklarımı yazdığım kağıtları, doldurup her gece içtiğim galon şarap şişesine koymalı, atmalıydım çoktan denize, sahilde ulaşır diye belki sevdası yüreğinde gizli sevdalılara… 

............... Akdeniz, sıcak deniz, yordu beni efkar basan gecelerin yaz sıcağında volümsüz arabesk çığlıklarıyla, Müslüm babanın Akdeniz Akşamları Bir Başka Oluyor Hele Birde Aylardan Temmuz İse yi yorumlaması da Tuz-biber oluyordu parasız üniversite yıllarımda ekonomik olsun diye içtiğim Arjantin bardaklı biralara serptiğim tuz gibi… Ayılmalarıma mega esriklikler yüklüyordu acılı her bir arabesk…onlarca tekneye biniyor, dümensiz, pusulasız, rotasız ilerliyordum bilmediğim ülkelerin yabancı denizlerinde... Ve kayboluyordum.. 

............... Prangalı kaçak mahkum gibi gün ağarmalarında, dalgalar vururken yüzüme, tenime, uyanıyordum nerede olduğumu bilmeden, kumsalın denizle ahengini konuşlandırdığı noktada, ıssız adaya mı düşmüştüm geceden... Kalkıyor, silkiniyorum kum ve yosun kokularından..Sana gelirken, senin olmaya gelirken…Ada oluyorsun ıssız, sessiz sığındığım, liman oluyorsun tek kişilik iskelene yanaşmam, soluklanmam için… 



Sandalı fırtınalı denizlerde 

Ekvatora sürüklenmiş acemi balıkçıydım 

Vapurlar yol alırken okyanusta.. 

Takımadalar gördüm savrulmuşluğumda 

Alabora olan teknesel yüreğime 

Pusulam oldun gelişlerime, yönsüzlüğümde… 

10.2.2006 - Adana', '............... Serüvensiz seferlerden yorgun düşüp, dalgaların dansında alaboralar yaşayan, huzur, sevgi, sıcak, korunaklı limanına demirle...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-sigindigim-liman-im-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuk', 'tutuk-mehmet-postalli-lqvhz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Apansız tutukladı gözlerindeki büyü

Dilimden düşürmedim en sevdiğin türküyü', 'Apansız tutukladı gözlerindeki büyü Dilimden düşürmedim en sevdiğin türküyü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/tutuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Gelmişim', 'tek-gelmisim-aynur-avci-st7x5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tek gelmişim

Tek giderim kadehimde

Düşünürüm özlediğimde aşkı

Bir an maviyi gözlerinde yaşarım

Tekrar başa dönerim

Derinden yudumlarken yalnızlığı

Düşlerim geçmişte mutluluğu

Hatırlamaya çalışırım ama nafile

Benimle kalan bakışların

Bir kaç damla gözyaşı oluverir

Neyse boş ver

Tek gelmişim

Tek giderim kadehimle

Sanki hiç yaşamadım

Ben bu şehirde

Tramvay süzülürken yolunda

Vapur iskelede,onu bekler

Derinden bakarken geceye

Baykuşlar penceremde fasıl geçer

Ay mehtaba dalarken

Yüreğim paramparça

Ben sevgide maviyi,

Gözlerimde seni düşlerim

Yudumun sesinde yalnızlığımı

Gecenin yankısında,kendimi bulurum..', 'Tek gelmişim Tek giderim kadehimde Düşünürüm özlediğimde aşkı Bir an maviyi gözlerinde yaşarım Tekrar başa dönerim Derinden yudumlarken yaln...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tek-gelmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-021 Başkalarına bırakma! ..', 'ub-021-baskalarina-birakma-mehmet-coban-rrpl0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tartış kendini

Hesaplaş kendinle

Yapmazsan bunları

Tartışırlar seni

Hesaplaşırlar seninle

Bir toplum 

Tartışmazsa 

Tarihini, kendini

Hesaplaşmazsa 

Tarihiyle, kendisiyle

Başkaları 

Tartışır,

Tarihiyle, kendisiyle! ..

Başkaları 

Hesaplaşır

Tarihiyle, kendisiyle! ..

Doğru ol, 

Eğri olma,

Yiğidin hakkını ver

Haksız yiğit olma! ..

En güzel yiğit,

Kendini bilendir

Yiğide hakkını verendir! ..

Korsan engelleri, 

Düşünmenin,

Tartışmanın 

Hesaplaşmanın 

......................... önüne! …

Yasalarla, törelerle

Sudan bahanelerle

Geri kalmış düşüncelerle! ...

Başkaları gelir öğretir gerçekleri

Başkaları yıkar geçer engelleri

Sen, sen ol, 

Başkalarından öğrenme gerçekleri

Başkalarına yıktırma kendi engellerini

Sen, sen ol, 

Başkalarına bırakma kendi işini! ...

15.02.2006-İzmir', 'Tartış kendini Hesaplaş kendinle Yapmazsan bunları Tartışırlar seni Hesaplaşırlar seninle Bir toplum  Tartışmazsa  Tarihini, kendini Hesapla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ub-021-baskalarina-birakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinle', 'hasretinle-tahmine-yildirim-bd4ub', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sensiz yaşamak

Gömleği ateşten kuşanmak

Hayatı ölüm gibi sanmak

Hasretinle alev gibi yanmak

Sancılar giriyor başıma

Yalvartma Allah aşkına

Yaşanmaz bu acı tek başına

Hasretinle döndüm ben bir şaşkına

Gündüzü gece sanıyorum

Oralarda kendimi arıyorum

Her gün Tanrıya yalvarıyorum

Hasretinle iç huzuru buluyorum

Hayırlar diliyorum Yaradandan

Beni almasın diye sakın benden

Can çıkmayınca bu bedenden

Hasretinle yaşamamak gelmezki elden...

OCAK:2006', 'Seni sensiz yaşamak Gömleği ateşten kuşanmak Hayatı ölüm gibi sanmak Hasretinle alev gibi yanmak Sancılar giriyor başıma Yalvartma Allah aşk...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasretinle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YB-33 Karışık süt', 'yb-33-karisik-sut-mehmet-coban-1c634', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anılarımda bir amcam

Ne güzel anlatırdı gerçekleri

Bir, bir anlatırdı güzellikleri

Doğruları, eğrileri

Bir gün anlattı bir hikâye

Aktarmayı deniyorum size

Doğanın içinden gariban biri

Satmış, savuşturmuş her şeyi

Çıkıp gitmiş büyük şehre

Katılacakmış o da medeniyete

Cebinde bütün varlığı

Kalbinde doğallığın saflığı

Bir mahalle satın almış şehirde

Vermiş hava parasını sevine, sevine

Süt alıp satarak atılacakmış ticarete

Amacı, hizmet, ticaret, yerleşecek şehre

Dolaşmışlar mahalleyi eski sütçüyle

Öğrenmiş nereden alacak, satacak kime

Ertesi gün, almış sütü çıkmış ticarete

Bir, bir dağıtmış sütünü mahalleliye

Ertesi gün tekrar başlamış sefere

Bütün kapılar kapanmış bu sefer yüzüne

Sormuş ne oluyor? Diye, herkese..

Kovmuşlar kapıdan sütün bozuk diye..

Bulmuş mahallenin eski sahibini,

Utanmıyor musun sen? Demiş ona.

Hem satarsın mahalleni

Hem engellersin ticaretimi

Herkes çeviriyor beni sütün bozuk diye

Söyle bakalım niçin yapıyorlar böyle? 

Eski sütçü demiş sen ne yapıyorsun? 

Demiş, aldığım sütü aynen dağıtıyorum. 

Demiş eski sütçü. Olur mu? Hiç öyle

Yarı yarıya su karıştıracaksın süte

Onların ağzı böyle alışkın

Gerçek sütü bulunca olmuşlar şaşkın

Olur mu? Arkadaş öyle şey demiş

Öbürü bu iş böyle, çare yok demiş

Sütçü çaresiz suyu karıştırmış süte

Dağıtmış yine bütün mahalleye

Bütün mahalle tebrik etmişler

İşte şimdi öğrendin bu işi demişler

Düşünürüm hep o günden beri

Ülkemde olup bitenleri

Hiçbir şeyin safı, doğalı kalmamış

Sanki her şeye, sahtelik karışmış

Fikirler karışmış hakla batılla

İnançlar bulanmış her türlü sapıklıkla

Kölelikler özgürlük sözleriyle süslenmiş

Beyin yıkamaya bilgilenmek, 

Cahilliğe bilgelik denmiş! ..

Gerçeği arayan idealler dogmalarda

Düşünceler hapsedilmiş yasalarda

Parmaklar inip kalkıyor ha bire

Sanki senfoni orkestrası tabiler şefe

Ağır ve bozuk geliyor bize 

Düzgün ve açık fikirler! ..

Ağır ve bozuk geliyor bize

Doğal, saf düşünceler! ..

Tıpkı su katılmamış süt gibi

Dokunuyor bize gerçekler! 

Dokunuyor bize, 

Yalansız, riyasız sözler! ..

15.02.2006-İzmir', 'Anılarımda bir amcam Ne güzel anlatırdı gerçekleri Bir, bir anlatırdı güzellikleri Doğruları, eğrileri Bir gün anlattı bir hikâye Aktarmayı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/yb-33-karisik-sut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Hirsizi', 'kalp-hirsizi-hanifi-isikoglu-krrte', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni Seviyorum un

Degeri neydi? 

Söylermisin

Kalp hirsizi

Caldin Kalbimi

Benden

Ver geri

Inandim sevdim 

Seni

Bu sevgiden 

Zarar gördüm

Ver kalbimi

Geri

Kalp hirsizi

Sevemem artik

Hic kimseyi

Anladim 

Askin degerini

Kaptirmam

Kalbimi', 'Seni Seviyorum un Degeri neydi?  Söylermisin Kalp hirsizi Caldin Kalbimi Benden Ver geri Inandim sevdim  Seni Bu sevgiden  Zarar gördüm Ver ...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalp-hirsizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Törpüsü', 'omur-torpusu-mehmet-postalli-rkajq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir andan tutunuz yıllara kadar

Ah! Şu zaman var ya, ömür törpüsü

Salise, saniye ve dakikalar

Su gibi akar ya, ömür törpüsü 

Saat, gün, ay derken, çileli yıllar; 

Geçtikçe ömrünü çalan biri var

Karşına çıkan tüm olumsuzluklar

Canını sıkar ya, ömür törpüsü.', 'Bir andan tutunuz yıllara kadar Ah! Şu zaman var ya, ömür törpüsü Salise, saniye ve dakikalar Su gibi akar ya, ömür törpüsü  Saat, gün, ay d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/omur-torpusu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01-Keşke...', '01-keske-mehmet-emin-dogan-bd21q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gördüğüm lüzum üzere şiirlerimi bu platformdan kaldırdım. Dostlardan özür dilerim...', 'Gördüğüm lüzum üzere şiirlerimi bu platformdan kaldırdım. Dostlardan özür dilerim......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Doğan']::text[], 8.5, '{"poet":"Mehmet Emin Doğan","poet_slug":"mehmet-emin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/01-keske-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim', 'zalim-hanifi-isikoglu-9nki0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni terk edip

Giden sendin

Arkandan

Aglayan ben

Bana cektirdigin

Bu izdirabi

Bir baskasida 

Sana cektirsin

Zalim

Sabirliyim

Ben beklerim

Sende sürün

Benim gibi', 'Beni terk edip Giden sendin Arkandan Aglayan ben Bana cektirdigin Bu izdirabi Bir baskasida  Sana cektirsin Zalim Sabirliyim Ben beklerim Se...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zalim-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mucizeydiniz', 'mucizeydiniz-firuze-keles-y9qsz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dökülen beyaz taneler

Beni hiç üzmediniz.

O gece, hatırlıyorum

Mutluluğuma şahittiniz.

Işıkların altında

Sizi izledik

Ne güzeldiniz

Ne güzeldiniz...

Beyaz bir mutluluktu

Geceden gelen,

Hani derler ya

Ölsem de gam yemem...

Sizi izliyorduk

Sevdiğim ve ben.

Tanrıdan gelen

Mucizeydiniz.

15.02.2006', 'Dökülen beyaz taneler Beni hiç üzmediniz. O gece, hatırlıyorum Mutluluğuma şahittiniz. Işıkların altında Sizi izledik Ne güzeldiniz Ne güzel...', ARRAY['Türk Edebiyatı','Şiir','Firuze Keleş']::text[], 8.5, '{"poet":"Firuze Keleş","poet_slug":"firuze-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mucizeydiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 67', 'guncel-beyitler-67-huseyin-avdic-06a4i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '$u Insanlar

Sevgiden cok merhamete, acinmaya muhtactir $u insanlar.

Kötüler sevilmez, ama acinmaya hakki olandir onlar.

Berlin, $ubat 2006.', '$u Insanlar Sevgiden cok merhamete, acinmaya muhtactir $u insanlar. Kötüler sevilmez, ama acinmaya hakki olandir onlar. Berlin, $ubat 2006....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbaharı Kirletmeyin! ....', 'sonbahari-kirletmeyin-kadir-albayrak-zduwu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Severim sonbaharı…. Hazanı

Düşen yaprağı..

Yağmuru, cama vuran sesini

Sarısını severim sonbaharın

Yeşilin dökülmesini

Çırılçıplak dallarını

Ve yalnızlığını sokakların

Hazırlığını karakışın

Çünkü herkes sanır ki; 

Bitmiş yaz! .. İlkbahar

Oysa ben bilirim ki; 

Her sonbahar,

Gelecek yazların baharların habercisidir

Ve her sonbahar,

Çürümüş yeşilin “Yenileyicisidir! ..”

………….

Severim sonbaharı

Her sonbahar; Bir ilkbaharın başlangıcıdır

Belki her acı da, Bir mutluluğun başlangıcıdır

Diye, severim sonbaharı! ..

Beynimde ki tek veda, yaşadığım tek elveda

İçinde olsa da

Ben severim sonbaharı

Siz onu yetim bıraksanız da 

Yalnızlığa terk etseniz de

Ve ben de bir hazan günü

Yalnızlığa terk edilmiş isem de

Ben severim sonbaharı

Her sonbahar “Bir ilkbahara arifedir”

Ve her arife “Bir bayrama gebedir! ..”

…………..

Severim sonbaharı

Gidişini göçebe kuşlarının

Tütüşünü bacaların.

Harlanan ateşi, kızarmış kestaneyi

Alevlerin rengini, 

Denizlerin katlanmasını, 

Dalgaların kıyıları tokatlamasını

Severim kırbaç gibi rüzgarları

Özlediğim beklediğim kasveti getirir sonbahar

Tıpkı seni götürdüğü gibi! ...

Ve örter ayak izlerini çivi çiviyi söker misali

…………..

“Dikenler baki gül dökülse de dalından

Her sonbahar öper beni alnımdan! ..” 

…………..

Severim sonbaharı

Geçen ilkbahara inat! ..

Ya siz? ! .... Sizler; 

Sizler neyi seversiniz? ..

Meleşen kuzuları, çiçeklerin uzuvlarını mı? ...

Yıldızlarını gökyüzün de, temaşa etmek mi? ...

Gök kuşağının yedi rengini! ...

Sizler neyi seversiniz? .. Sizler neye hasretsiniz? ...

Ve siz! .... Sizler; Neyi beklersiniz? ...

Hep yeşil mi? .. Hep tebessüm mutluluk mu? 

Hep lalezar ve hep güller! .. Öyle mi? ..

Onu babam da sever! ...

……………..

Severim sonbaharı

Çünkü ben; Kimsenin sevmediği, sevemeyeceği

Sevmemesi gerektiği şeyleri sevmek istedim! 

Ben hayatım boyunca bir şeyi öğrenemedim

Ben sonbaharı sevdim! ... Çünkü; 

Ben sevgiyi bölüşemedim! .......

Siz sevmeyin! ..........

Siz yazı ilkbaharı hatta isterseniz kışı sevin

Sevin ki; “SONBAHARI KİRLETMEYİN! ..”

Diğer sevgiler gibi! ...

…………..

Elimde ki sonbahar “Gönlümde ki son sevgi! ...”', 'Severim sonbaharı…. Hazanı Düşen yaprağı.. Yağmuru, cama vuran sesini Sarısını severim sonbaharın Yeşilin dökülmesini Çırılçıplak dallarını ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/sonbahari-kirletmeyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devran Dönüyor Dostlar!', 'devran-donuyor-dostlar-sadik-dogan-cme4q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Devran dönüyor dostlar! 

yine aynı hikaye

hep o kumpanyalar. 

bir varmış, bir yokmuş... 

                 işte böyle başlar bütün masallar. 

sonra bilindik senaryolar: 

atılan çamurlar üstümüze, 

diri diri yakılan umutlar, 

kadınlar, erkekler, çocuklar, 

                yani öldürülen canlar 

                ve yitirilen insanlık. 

Devran dönüyor dostlar! 

               işte 21.yüzyıl, 

               işte ortaçağ. 

lisanlar, yüzler farklı belki 

               ama niyetler apaçık ortada. 

figüranlar oynuyor oyununu, 

ya oyun bozanlar 

yani mezarı kazılanlar. 

Devran dönüyor dostlar! 

yüzler gizlenmiş, 

          boyanmış gözler. 

                    her şey allak bullak 

                                    hep aynı maskeler. 

Devran dönüyor dostlar! 

dün sizdiniz kurbanlar

bu günkü kurbanlar biz; 

siz nasıl yürüdüyseniz ölüme 

yarınlarımızı yaşatmak için, 

neden sürüklendiyseniz kadere 

ve niçin geçtiyseniz bu yoldan

biz o inançla yaşıyoruz yoldaşlar! 

Devran dönüyor dostlar! 

karanlıklar kalkmıyor üzerimizden 

oysa biz maviliklere adanmışız; 

hakketmedik bunca işkenceyi

istemeyiz ışıksız geceyi 

biz yarınlara aşığız. 

ve savaşmak için yaratılmadık.

             kanla büyütmek başağımızı, 

             ekmeğimize kan doğramak, 

             şarabımızı kan kırmızısı içmek, 

             bayrağımızı kan ile çizmek, 

             hiç mi hiç aklımızdan geçmedi. 

Devran dönüyor dostlar! 

avuç içinde artık dünya. 

nere gitsem aynı sesler

nereye baksam aynı yüzler 

yani hep bir tornadan çıkmış insanlar. 

             susmalar hep bir ağızdan

             linçler hep bir koldan. 

vur deyince vuruluyor, dur deyince duruluyor. 

ey canlar, bakın canana nasıl kıyılıyor, 

ey insanlar, insanlık elden gidiyor. 

             bilinsin artık bilinsin

bizim kavgamız burada bitmiyor.

Davamız divanda görülecek, görülüyor…

Hesabımız zafere kadar sürecek, sürdürülüyor…

28.12.2005/Osmancık', 'Devran dönüyor dostlar!  yine aynı hikaye hep o kumpanyalar.  bir varmış, bir yokmuş...                   işte böyle başlar bütün masallar. ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Doğan']::text[], 8.5, '{"poet":"Sadık Doğan","poet_slug":"sadik-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/devran-donuyor-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oda Ne', 'oda-ne-tahmine-yildirim-cg7j5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neşe arıyorum bir türlü bulamadım

Sarhoş gibiyim sanki hiç kendime gelemedim

Bu güne dek kendime bir soru bile soramadım

Kaderim hep çoktı karşıma oda ne

Tam mutluluğu buldum derken 

İçme bir hüzün çöker erkenden

Delicesine sevip vede sevilirken

Sanki içimde bir ses diyorki oda ne.....', 'Neşe arıyorum bir türlü bulamadım Sarhoş gibiyim sanki hiç kendime gelemedim Bu güne dek kendime bir soru bile soramadım Kaderim hep çoktı k...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oda-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O şimdi Yıldızların yanında', 'o-simdi-yildizlarin-yaninda-necmiye-sarpkaya-n94dz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Babaannesinin den kalan  kokar ardıç çeyiz sandığına usul usul yaklaştı. 

İncitmekten çekinerek şefkatle kapağını açtı ve anneciğinin el emeği 

göz nurlarına baktı, tek tek elden geçirdi. Bir oyayı aldı evirdi çevirdi 

bunu liseyi bitirdiğim yıl yapmıştım dedi. Yanaklarına yaklaştırdı

Bir busecik kondurdu. Yatağın üzeri elişleri ile dolmuştu,toparladı 

tekrar yerlerine yerleştirdi. 

Beyaz uzun sabahlığı yerine koymaya kıyamadı. 

Üzerine geçirdi sobaya yaklaştı. Ellerini ısıttı. Pencereye doğru gitti camdan 

dışarı baktı, gözlerini gökyüzüne kaldırdı. Ay’a takıldı bir müddet,sonra 

yıldızlarla oyalandı,üç gün dedi. Tekrarladı üç gün kaldı. Burak gelecek içine 

bir huzur doldu,yanaklarının kızardığını fark etti. Birden aklına bir şey geldi 

uçacak gibiyim içim içime sığmıyor dedi.Başını tekrar kaldırdı bu yıldızlardan 

başıma taç yaptım boynuma gerdanlık, kollarıma bilezik, parmaklarıma yüzük,

belime kemer ışıl ışıldı bütün vücudu. Gökyüzü pelerinim olsun dedi. 

Ayı aldı tam orta yere taktı süper bir broş olmuştu.Her taraf ışıl ışıl keşke 

Burak beni böyle görebilseydi. Billur, peri kızlarına dönmüşsün, masal perisi 

deseydi. Askerden dönmüş olsaydı,o baktığımız gelinlik dedi. sevinçle 

ellerini açtı uçmaya çalıştı,duyguları kanatlanmıştı,aşk dedi,sevda dedi 

arkasından özlem dedi.Ne olurdu ayrılıklar hasretler yakmasaydı, 

o zaman kavuşmanın hazzı nerede kalacaktı. Az kaldı terhisine üç gün

sonra dönecek.

Bir anda gökyüzü hiddetlendi biraz önce aldığı yıldızlar teker 

teker kayboldular. Ay da saklanmıştı, zifiri bir karanlık ürperdi 

nerede peri kızı dedi.Tekrarladı. Arkasından bir kar yağışı başladı. 

Ellerini çırptı sobaya doğru yürüdü. İçine bir üşüme bir titreme 

gelmişti üzerindeki sabahlığa sarındı sıkı sıkı büründü

. 

Pencereye doğru yürüdü karşıdaki yapraksız ağaç gelin olmuştu evet

kolları dedi. Ona takacak taç kalmamıştı,yıldızlar yoktu gelinin 

takıları yoktu,elleri bomboştu, belindeki kemer de yoktu ya o hoş broş o 

muhteşem broş o da yoktu yerinde. Olsun ne yapalım böyle de güzeldi. 

Sadeydi asildi güzeldi. Gelin dedi. Aniden kendine geldi. Acı bir telefon sesi 

korktu kaçtı açamadı. Neden sonra gitti çekinerek ahizeyi kaldırdı yıllar 

geçmişti aradan adeta arayan Burak’ın annesi, hayırdır inşallah dedi.

-Kızım Burak hastane biz gidiyoruz. Kekelediğini duydu. 

Bayılmıştı. Gözlerini açtı annesi başucunda kolonyalar 

Ellerini şakaklarını ovalıyorlardı. Anne bırak şimdi ne oldu? 

Burak nerede? 

Annenin gözbebeklerinde bir hüzün yumağı kümelendi 

Hemen hastaneye gitmeliyiz. 

Hadi anneciğim ne duruyorsunuz 

Lütfen konuşun 

Lütfen bir şeyler söyleyin 

Bu bir rüya olmalı uyanınca sona ermeli 

Evet evet rüyadayım ben değil mi anne 

Kızım sen sağ ol bir çatışama da şehit olmuş 

O şimdi yıldızların yerinde yanında dedi. 

Hayırrrrrrrrrr 

Olamazzzzzzz 

Bu ne biçim şaka 

Billur tekrar bayılmıştı.

Teröre bir can bir fidan verilmişti 

Gencecik insanlar aileler yıkılmıştı', 'Babaannesinin den kalan  kokar ardıç çeyiz sandığına usul usul yaklaştı.  İncitmekten çekinerek şefkatle kapağını açtı ve anneciğinin el eme...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/o-simdi-yildizlarin-yaninda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNeRKeN..', 'i-nerken-neser-selman-zbs90', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eskiden bitmez gibi gelirdi, 

bitecekler.. 

Şimdi hüznü sarıyor,

duygusu boğuyor,

biteceğin.. 

Giderek azalıyor! . sanki her şey,

etrafta.. 

Değil korkum düşmek, 

inerken basamaklardan..

Bilincindeyim terk edilişin, 

var oluşuma, içimde taşıdığım.

Gecikmesini dilediğimdendir,

acele etmeyişim..', 'Eskiden bitmez gibi gelirdi,  bitecekler..  Şimdi hüznü sarıyor, duygusu boğuyor, biteceğin..  Giderek azalıyor! . sanki her şey, etrafta.. ...', ARRAY['Türk Edebiyatı','Şiir','Neşer Selman']::text[], 8.5, '{"poet":"Neşer Selman","poet_slug":"neser-selman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/inerken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Yıllarım', 'yorgun-yillarim-zeynep-aydinlioglu-ibufo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba yorgun yıllarım, merhaba 

Nasıl,geçti koskoca seneler. 

Sevgilerin pekiştiği, 

Acıların yaşandığı uzun yıllar! ... 

Sayfa sayfa, okumak gerek. 

Yeni doğmuş bebeği kucaklayışımızı, 

Sabah kahvesini yudumladığımız 

’o’ 

güzel 

günlerin geçtigini 

nasılda farketmemişim.! 

Ama geçen yılları... 

aynaya baktığımda anladım. 

O, 

derin 

çizgilerden, 

Saçlarımın renginden... 

===Şakaklarıma, kar mı yağmıştı! ? 

Yoksa ayanda mı bozulma vardı? ... 

Ama yılların geçtiğini 

artık kavga etmediğimizden anladım! . 

____çok çabuk geçmişti 

merhaba dediğim yıllar, 

çok geride kalmıştı! 

____ya, çocuklar... 

Kocaman olmuşta! fark etmemişim. 

Yani ben şimdi yaşlandım mı! 

__Yok canım,olamaz! 

Ben yaşlanmam.! 

Daha sevdiklerimle koşturacağım 

Belki ip atayacağım. 

__Yakan top oynayacağım… 

geriye baktığımda 

’o’ 

yorgun yıllar var... 

Acaba ben yaşımdan mı korktum! 

Yoksa yaşlanmaktan mı? 

ben hayatı ruhumdaki gibi yaşamalıyım. 

Yorgun yıllar peşim sıra gelsin.. 

bu yaşam sevgisiyle... 

Daha çok yorgun yıllara, merhaba derim.... 

__Aşkla, sevğiyle... 

Merhaba hayat yaşamak çok güzel…. 

(14.12.2005)', 'Merhaba yorgun yıllarım, merhaba  Nasıl,geçti koskoca seneler.  Sevgilerin pekiştiği,  Acıların yaşandığı uzun yıllar! ...  Sayfa sayfa, oku...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yorgun-yillarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Dinletiye Gittiğimi Söylemeyin, O Beni Şair Sanıyor...*', 'anneme-dinletiye-gittigimi-soylemeyin-o-beni-sair-saniyor-aynur-uluc-f7iqq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'On dört şubatta sevgililer günü nedeniyle pek çok etkinlik yapıldı, farklı yerlerde. İstanbul’da bir belediye de şiirle kutlamak istemişti bu günü. “Aşk denilince akla şiir gelir” diyerek. 

Kalkıp gitmek istedim, “ama önce bir programı soralım, bakalım” deyip telefon ettim. Dedim ki “arabesk içerikli bir program değil, değil mi? ” Dediler “ yoooook, çok güzel, bayılacaksınız” Edebiyat çevrelerinde sıklıkla gündeme gelen bir konu vardır: “Şiir halktan, halk şiirden koptu”. “Peki bu çevreler dışındaki şiir etkinlikleri, nasıl düzenleniyor acaba” diye düşündüm. Toplumun geniş kesimi şiiri nasıl yaşıyor? Tamam, televizyonda görüyorduk şiir (!)     kliplerindeki hali ama, gidip yerinde bir tespit fena olmazdı.

Oraya gittiğimde ilk olarak bir salon dolusu seyirci, girdi görüntüme. “En az bin kişi vardır” diyerek kaba bir hesap yaptım önce. Sonra bir genç çıktı sahneye. Sonra bir genç daha ve bir genç daha. Hiçbiri seyirciyle ilgi kurmuyordu. Çünkü gecenin esas kahramanları onlar değildi. Kendi kendineyken olduğu gibi önündeki enstrümanı çalmak yeterliydi anlaşılan onlar için. Sonunda seyirciyle ilgi kuran birisi geldi, elinde sazı ile. Sesi güzeldi, klipleri de varmış. Başladı türküler söylemeye. Arada bir de biraz sonra sahneye çıkacak olan “en bi en şair”den bahsediyordu.  Biraz sonra, sözü edilen “en bi kahraman şair” çıktı sahneye. Deterjan reklamlarına taş çıkartan beyaz ceketi, ucu sivrilikten yana gerekirse kendini koruma amaçlı da kullanabilecek ayakkabıları, ışık her vurduğunda göz doldurucu fularının arasından parlayıverecek şekilde ayarlanmış altın kolyesi ile. Ortalık yıkıldı. Şair çok fiyakalıydı.

Göz dolduran bir sesi vardı şairin. Hiçbir şekilde okuduğu eser sahiplerini söylememe huyu vardı. Ama bunun ne önemi vardı. Mühim olan şovdu. Hani şu “ must go on” olanından.Yer yer arabesk nağmeler eşliğinde ortaya döküverdiği dizeleri, yer yer seyirlik stand up komedi türü esprileri yöresel ağızdan öykünülen bir sesten izlerken gülüyordu herkes. Bu şiir işi çok eğlenceliydi canım. Çok gösterişliydi. Çok bi şovdu. 

Her şey tamamdı. Var olanla kol kola girmekten değil, ona karşı durmaktan beslenen, güzeli arayan sanat, anlaşılan attaaa gitmişti. Onun yerine gelen bu yanılsama, açık açık “aman ne iyi olmuş da, şu sevgililer günü var olmuş. Bugün çıktığım televizyon, radyo, canlı program dahil bu sekizincisi oldu. İyi para kazanılıyor valla böylesi günlerde” diyordu. Evet, böyle diyordu  ve insanlar gülüyordu.

Bu muhteşem(!)      sanat gecesine söylenecek söz yok. Yok artık söylenebilir bir şey. Şiir halktan kopmuş muydu, halk şiirden kopmuş muydu. Bu ülkede birtakım sözler, birtakım deyişler, birtakım gülüşler kendini feci halde şiir sanıyordu. “Şiir”i ben gördüm, çıkışta. İçin için ağlıyordu. 

Aynur Uluç

15-02-2006

* Başlık, Jacques Seguela’nın “Anneme Reklamcı Olduğumu Söylemeyin, O Beni Bir Genelevde Piyanist Sanıyor! ” isimli kitabından esinlenilmiştir.

Lacivert Öykü ve Şiir Dergisi

Mart, Nisan 2006', 'On dört şubatta sevgililer günü nedeniyle pek çok etkinlik yapıldı, farklı yerlerde. İstanbul’da bir belediye de şiirle kutlamak istemişti b...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anneme-dinletiye-gittigimi-soylemeyin-o-beni-sair-saniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelieceksin Diye', 'gelieceksin-diye-nevzat-gibey-ftek8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Giyindim kuşandım silahlarımı 

aşkımı elime aldım

saçın mızrak

bakışın ok

geleceksin diye seni kuşanıyorum

seni...

seni

uçan kuşlara

esen yellere anlatıyorum

bilsinler 

yar gelecek

bilsinler bir melek konacak

ansızın

yurtlarına

bir melek ki cenneti aladan

bugun 14 şubat 

ümidim

geleceğim

gören gözüm ferim ışığım

geleceksin diye dünden uykusuzum..', 'Giyindim kuşandım silahlarımı  aşkımı elime aldım saçın mızrak bakışın ok geleceksin diye seni kuşanıyorum seni... seni uçan kuşlara esen ye...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gibey']::text[], 8.5, '{"poet":"Nevzat Gibey","poet_slug":"nevzat-gibey","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelieceksin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğiz Dostlar', 'gelecegiz-dostlar-fatma-guven-3oaos', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erciyes''in yüksek doruğu,

Harran Ovası''nın enginliği,

Anadolu''nun doluluğunda,

Kültürlerin zengin bileşimiyle

Efes''i,Bergama''sı,Kapadokya''sıyla,

Yüzyıllara sığmayan mirasıyla,

Yüreklerimizle geleceğiz dostlar.

Köylümün sofrasında ki aşı,

Yüreğimizde ki sevginin nakışıyla,

İçimizin şefkati,asaletiyle,

Namerde amansız,sevdaya fermansız,

Tuttuğumuz eli bırakmayarak,

Yürüyeceğiz sizlerle dostlar.

                           15.02.2006', 'Erciyes''in yüksek doruğu, Harran Ovası''nın enginliği, Anadolu''nun doluluğunda, Kültürlerin zengin bileşimiyle Efes''i,Bergama''sı,Kapadokya''sı...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gelecegiz-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum.', 'gidiyorum-veysel-alkan-v2cf9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıl baştan ya kaçacak.

Ya bedenden can uçacak.

Kalır isem kan akacak.

Anam alıp, gidiyorum.

Dünkü enik, diş çıkartmış.

Buralarda zulmü artmış.

Haklı olmak, kabahatmış.

Anam alıp, gidiyorum.

Dinlenmezsem, soru sormam.

İstenmezsem, daha durmam.

Allah çarpsın, eli vurmam.

Anam alıp, gidiyorum.

Adam sayıp, tutmadılar.

Halim nedir, sormadılar.

Madem, sahip çıkmadılar.

Anam alıp, gidiyorum.

Bağım bahçam olmuş viran

Darbaşımı sarmış duman.

Zehir zıkkım olsun kalan.

Anam alıp, gidiyorum.

Gözyaşımı silen yok ki.

Meramımı bilen yok ki.

Ekmeğini bölen yok ki.

Anam alıp, gidiyorum.

Sözlerinden bir bir caydın.

Bıktım artık,beni baydın.

Yak kınayı, gözün aydın.

Anam alıp, gidiyorum.

Müslamanım,dinsiz miyim? 

Hainlere kinsiz miyim? 

Rol yapamam,''artiz''miyim? 

Anam alıp, gidiyorum.

Borcum çoktur,çok zararım.

Kalsam dahi, yoktur kar''ım.

Dönmem gayrı, son kararım.

Anam alıp, gidiyorum.

Artiz:Soru soran,derdini anlatan,

        İşçi,Çiftçi,Esnaf,Memur.

        Yönetenler,mağdurlara der.', 'Akıl baştan ya kaçacak. Ya bedenden can uçacak. Kalır isem kan akacak. Anam alıp, gidiyorum. Dünkü enik, diş çıkartmış. Buralarda zulmü artm...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gidiyorum-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıyırdım', 'siyirdim-durmus-kaya-flhgg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yar beni koynunda yatırsın diye,		

Canımı sıyırdım canımdan öte! 

Beni cennetine götürsün diye,

Kanımı sıyırdım kanımdan öte! 	

Çektim besmeleyi çaldım içeri,

Ne kadar can varsa aldım içeri,

Yarin gözlerinden daldım içeri,

Tenimi sıyırdım tenimden öte! 

Boynuma saçını bağlayıp astı,

Çoban yıldızıyla Merihe kastı,

Yarama gül yüzlü mührünü bastı

Ben’imi sıyırdım ben’imden öte! 

Bir faniye verdim mezar taşını,

Bulsun “hüvelbaki” yazan eşini! 

Kaf Dağı üstüne kurdu düşünü,

Sin’imi sıyırdım sin’imden öte! 

Üzengiyi kırıp kalbimle duydum,

Dünyadan ne varsa hepsini soydum,

Bir kara sevdayla içimi  oydum,

Beynimi sıyırdım, beynimden öte!', 'Yar beni koynunda yatırsın diye,		 Canımı sıyırdım canımdan öte!  Beni cennetine götürsün diye, Kanımı sıyırdım kanımdan öte! 	 Çektim besme...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siyirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İlçem', 'benim-i-lcem-recep-uslu-8i1po', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çıktım Akbaba tepesine

Daldım Gölpazarı''nın seyrine

Evler görüyorum beton yapılı

Göklere değen

Evler görüyorum kerpiç

Ben de evim diyen

Kavak ağaçları uzun

Yeşil çınarlara karışmış

Ayvalar çiçek açmış bahçelerde

Erik elmaya alışmış

Çıktım Akbaba tepesine

Daldım şehrimin seyrine

Otuz iki musluklu çeşmesi

Harıl harıl akıyor

Bir pazar kurulmuş ki neyleyim

Herkes istediğini alıyor

Şalvarın üstüne manto giyen kadınım

Mini etek giyen kızına

Cık-layarak bakıyor

Çıktım Akbaba tepesine

Daldım ilçemin seyrine

Sımsıcak düşünceler

Herkes birbirini tanımakta

Elele tutmuş arkadaşlar

İlçem gün gün kalkınmakta

1990', 'Çıktım Akbaba tepesine Daldım Gölpazarı''nın seyrine Evler görüyorum beton yapılı Göklere değen Evler görüyorum kerpiç Ben de evim diyen Kava...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/benim-ilcem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şansını Düşün', 'sansini-dusun-sevinc-kavuk-6l5rr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kim dedi bu sanatın deryasına uzan 

Duymadın mı hiç önce tanı, öğren

Sonra alıştırma da yap yeterince diye

Boğuldun, boğdun da inceliği derin

Yaradan neler doğurmuş kurbanı olayım

Yaratılanlardan neler aşinalığa yücelmiş

Kemer kemer gönlümün kementi gibisin

Bu sevgimin kadehi hem benti misin? 

Öyle bir zamana dayalı ki şimdi aşkınlık

Kusur etme hem nice kurbanın olayım

Ağlatmadan bırak şu kalemi elinden

Üzgün bak her kelime her cümlen de...

Var mı daha gücün hem yetecek kadar 

Artık bir süre için ayrıl 

Başarının hem dönüşüne şansını düşün....

Subat  2006 

Saat:.............(F.Halıcı´dan bu iki mısra: 

__________Kemer kemer gönlüme kement sensin 

__________Bu sevgiye kadeh sensin, bent sensin...', 'Kim dedi bu sanatın deryasına uzan  Duymadın mı hiç önce tanı, öğren Sonra alıştırma da yap yeterince diye Boğuldun, boğdun da inceliği deri...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sansini-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
