INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun', 'olsun-cengiz-suslu-6bj2k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saçlarım akla dolsun,belim bükülmüş olsun.

Razıyım,titresin elim,yalnız başım dik olsun.', 'Saçlarım akla dolsun,belim bükülmüş olsun. Razıyım,titresin elim,yalnız başım dik olsun....', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/olsun-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-mustafa-guclu-focvn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seviyorum o masmavi gözlerini

Seviyorum o tatlı sözlerini

Seviyorum  bebeğim seni

Gülüşünü seviyorum

Başını göğsüme dayayışını

Seninle elele ay ışığını

Masmavi gözlerinle bana bakışını

Tebesümünü seviyorum

Göremedim sen gibi bir eşini

Sonum biliyorum gidişini

Senin bana aşkım deyişini

Seviyorum deyişini seviyorum', 'Seviyorum o masmavi gözlerini Seviyorum o tatlı sözlerini Seviyorum  bebeğim seni Gülüşünü seviyorum Başını göğsüme dayayışını Seninle elele...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Guclu']::text[], 8.5, '{"poet":"Mustafa Guclu","poet_slug":"mustafa-guclu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seviyorum-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Söyleyim Kardeş', 'ne-soyleyim-kardes-sahin-yilmaz-sp2cz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne diyeyim, sonu yoktur bu isin, 

“Söz” desem, tüylerle kıllar kızıyor. 

Şarkısını yaptık kakanın, çişin, 

“Saz” desem, ojeli eller kızıyor. 

Kırık kalemiyle kılıç eğiyor, 

Tükürsem, zanneder rahmet yağıyor, 

Taş savursam zülfü yâre değiyor, 

“Kaz” desem, akıllı kullar kızıyor. 

Yunus desen, düşer balık izine, 

Elif desen, mertek sokar gözüne, 

Aşık olup karıncanın kızına, 

“Yaz” desem leylekler, filler kızıyor. 

Rastlarsam bir zat-ı aklıselime, 

O an kilit vuracağım dilime, 

Dikşinarden çıkardığın kelime 

“Tiz” desem, kekeme diller kızıyor. 

Anlasana! ben de senden farksızım, 

Dümen bozuk, yelkensizim, çarksızım, 

Sokakta üşürüm, evsiz barksızım, 

“Köz” desem, vicdansız küller kızıyor.', 'Ne diyeyim, sonu yoktur bu isin,  “Söz” desem, tüylerle kıllar kızıyor.  Şarkısını yaptık kakanın, çişin,  “Saz” desem, ojeli eller kızıyor....', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-soyleyim-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatsınlar', 'anlatsinlar-mustafa-guclu-840cy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerime sor

Seni nasıl aradığımı

Kalbime sor

Hasretinle nasıl yandığımı

Yüreğime sor

Sensiz nasıl ağladığımı

Anlatsınlar sana

Nasıl bin bir parçaya dağıldığımı

Gecelere sor

Uykusuzluğa nasıl direndiğimi

Sabahlara sor

Sana susuz bittiğimi

Yıllara sor

Saçımda aklar beklediğimi

Anlatsınlar sana

Seni ne çok sevdiğimi', 'Gözlerime sor Seni nasıl aradığımı Kalbime sor Hasretinle nasıl yandığımı Yüreğime sor Sensiz nasıl ağladığımı Anlatsınlar sana Nasıl bin bi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Guclu']::text[], 8.5, '{"poet":"Mustafa Guclu","poet_slug":"mustafa-guclu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlatsinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-sevinc-kavuk-1fm9g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haliai:  Mezarı Argos´ta bulunan kadınlara Haliai (Denizin Kadınları)         deniliyordu. Bunların Perseus ve Argoslular´a karşı savaşmak üzere Dionysos´un yanısıra Aigeus  (Ege Denizi)         adalarından gelmiş oldukları söyleniyordu. Savaşırlarken ölmüşlerdi.

Haliakmon:  Makedonya´da bir ırmak; tanrısı, Okeanos ile Tethys´in oğlu telakki ediliyordu.

Bir başka efsanenin anlattığına göre, vaktiyle, Tiryns sakinlerinden Haliakmon adında biri, bir delilik nöbeti sirasinda, kendini o zamana kadar Karmanor adını taşıyan ırmağa attı ve orada boğuldu. O tarihten sonra ırmağa, boğulan kişinin adı verildi. Daha sonraları, ırmağa bir üçüncü ad daha yakıştırıldı. Bu kez de ona Inakhos ırmağı denildi. İnakhos Argolis´te bir ırmak-tanrı. Argoslular´in söylediklerine göre, Inakhos, insan soyunun dünyaya gelmesinden önce yaşıyordu ve oğlu Phoroneus ilk insandı… (Mitoloji Sözlügü´nden)            

SANAT   SEN   OL  SANATÇILAR  YAŞASIN

CANA  CAN   KAT  FERGAT  FİGAN  AZALSIN

Bu sanattır işte bu önceden yaşamışlık

Bu sanattır böyle ölümsüzlük, öncülük

Tesadüflerce umut, okyanuslarca bilgi

Yüreklerden sevgi bulutlardan her olgu

Savaşırım inancımın uğruna şaşmadan

Taşar da akarım coşar da yürürüm ileri

Olsa da o yolda kalım ölüm aldırmadan

Geri dönmekse onur yapılanmaya yeni

İstenç özgürlüğüne katma vergisiyle

Girişmek hep her işe bu bilinç ile

Okulsuz, eğitimsiz, arkam dekansız

Üstlenmem en az bir sorumluluk bile

Her savaşa donan da çık, amansız ol

Rastlar ise yoluna arsız densiz gibilik

Çabalarına imanı kat hem hayasız ol

O bir zamanı da gerektirecekse eğer

Korkma asla enginlere kanatlarını aç

Bu dünyada amaç bu dünyada inanç

Hep senin yükselişine olacak muhtaç

Her imdata koşuşan hep önce sen ol

15.02.2006

Çarşamba 16.00', 'Haliai:  Mezarı Argos´ta bulunan kadınlara Haliai (Denizin Kadınları)         deniliyordu. Bunların Perseus ve Argoslular´a karşı savaşmak ü...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/efsane-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Kardeşim Suçmu', 'seviyorum-kardesim-sucmu-yusuf-onder-bahceci-03d15', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum kardeşim suçmu, günahmı,

Senin yönün ne tarafa sağmı, cenahmı,

Her gece ağlarım, bu gözyaşlarım ahmı,

Seviyorum kardeşim suçmu, günahmı.

Sevenler beni anlar, gerisi neleri anlar,

Sevenler her gece de, her gece ağlar,

Sana gelmek isterim, kaderim bağlar,

Seviyorum kardeşim suçmu, günahmı. 

Bütün Dünya bana hasım olsa, olsalar,

Üzerime yılanları, çıyanları da salsalar,

Hiç boş durmasalar, beni yargılasalar,

Seviyorum kardeşim suçmu, günahmı.

Dünya durdukça kâlbim seni sevecek,

Benim bu gözyaşlarım bil dinmeyecek,

Omuzumdan bu sevda yükü inmeyecek,

Seviyorum kardeşim, suçmu, günahmı...', 'Seviyorum kardeşim suçmu, günahmı, Senin yönün ne tarafa sağmı, cenahmı, Her gece ağlarım, bu gözyaşlarım ahmı, Seviyorum kardeşim suçmu, gü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-kardesim-sucmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başım Sağolsun', 'basim-sagolsun-hasan-cam-uy555', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başım sağolsun

Bir coşku sevinç, hasret vardı bende

Geçenyıl bu zamanlar, sevdama koşmuştum

Engel tanımamıştı gönlüm, kadife seslime

Ölümleri hiçe saymıştım, hıçkırıkla ağlayan yare

Canımda can bildiğim, hasret kokan gülüme

Sevmek başka 

Sevilmek başkaydı, tarifi yoktu duygularımın

Oysa hoyrat gönlüm, ızdıraba nefrete koşmuş

Bu günkü gibi yaşıyorum o dünleri benliğimde

Aşkımı dilenmiştim kapı kapı, çuvallamışım sevdamı

Ne dağlara tırmanmıştım kınalık ayıları gibi, sevmiştim

Başım sağolsun

Sen öldün, bu gün yıldönümün, anmak istedim seni

Bir fatiha bir amin demekten başka gelmiyor elimden

Yalnız bıraktın beni, sensiz sevda gecelerime

hiçe saydın bunca yıllarımı, nefretim oldun içimde

Ama yinede başka sevmedim, seni seviyorum sevdam

Başım sağolsun

Bekçisiyim asırlık sevgi çilemin, sen gibi terk etmedim

Dedimya, başka sevginin yeri yok bende, sevemedim

Haşa, yaradan dan başka secdemdin, seni öyle sevdim 

Yaktım tüm anılarını, dumanını seyrettim uçup gittin

Kalbime dokunmadım içinde sen vardın, seni öyle sevdim

Başım sağolsun

09 02 2006

Hasan Çam

Ümraniye İstanbul

[email protected]', 'Başım sağolsun Bir coşku sevinç, hasret vardı bende Geçenyıl bu zamanlar, sevdama koşmuştum Engel tanımamıştı gönlüm, kadife seslime Ölümler...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/basim-sagolsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Şiirleri 3', 'cocuk-siirleri-3-mehmet-ayhan-gunaydin-t2w63', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UZAYLI ÇOCUK

Uzun, upuzundu boyu,

Zihninde evren dolu.

Ayağıysa kocaman,

Yalınayakla dolaşan.

Laf etmez, dilimi bilmez,

Islık çalar, söz demez.

Çocuktu daha, ama uzaylıydı,

Orada, gökteki bir yıldızdandı.

Canı dünyalı çocuk görmek istemiş,

Uzun upuzun yoldan, taa uzaydan,

Kalkmış, dünyalı çocuk görmeye gelmiş.

M. Ayhan Günaydın.

    13 Şubat 2006 

          Ankara', 'UZAYLI ÇOCUK Uzun, upuzundu boyu, Zihninde evren dolu. Ayağıysa kocaman, Yalınayakla dolaşan. Laf etmez, dilimi bilmez, Islık çalar, söz dem...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuk-siirleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Şiirleri 4', 'cocuk-siirleri-4-mehmet-ayhan-gunaydin-n0sk7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'TUTUMLULUK

Tutumlu olmayı öğrenmeli,

Unutmamalı bunu.

Tanımalı ve bilmeli,

Usanmadan, anlat onu.

Malının bil değerini,

Lafta bırakma tutumu.

Uyar bütün çocukları,

Lakin kaçırmadan dozu.

Unutmayın cimriliktir fazlası,

Ki çocuklar bilsin aradaki farkı.

M. Ayhan Günaydın.

     13 Şubat 2006 

          Ankara', 'TUTUMLULUK Tutumlu olmayı öğrenmeli, Unutmamalı bunu. Tanımalı ve bilmeli, Usanmadan, anlat onu. Malının bil değerini, Lafta bırakma tutumu....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cocuk-siirleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilinden', 'dilinden-kamer-taskin-w784d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sana anlattı,

Herkes kendi dilinden,

Anlamadın hiçbir şey,

Ne gelir elinden.

Seni sana anlatmak,

Senin dilinden,

Dil bilmek, diller bilmek,

Gelmez elimden.', 'Seni sana anlattı, Herkes kendi dilinden, Anlamadın hiçbir şey, Ne gelir elinden. Seni sana anlatmak, Senin dilinden, Dil bilmek, diller bil...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dilinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırların Kokusu (I)', 'kirlarin-kokusu-i-hulki-can-h3527', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırların Kokusu (I) 

“Yastığının kenarına düşmüş siyah saçları

hareketsiz ve karanlık bir şelaleyi andırıyordu...

Nihayet çınar yaprağını, bir inci dizisine sarıp

onun dağınık saçlarına attıktan sonra, kaçtım.”

Firari, Bölüm 30, Rabindranath TAGORE

I. Moderato cantabile

Kırların kokusu

Uyuyor musun? 

Kırların gülü

Uyuyor musun? 

Bütün çocuklar

Uyuyor mu? 

Tatlı bir uyuşma ve yorgunlukla

Her şeyden uyku damlıyor mu? 

Kim gidecek maviliğin yurduna

Saçılan büyülü ışıklara

Ve kim söndürecek ezgileri

Kırların rengi solarken? 

Sen mi sevgili

Sen mi gideceksin

Rüyaların sokağına? 

Ki oraya inilir bir merdivenden

Piyano tuşları gibi sekerek

Düşen bir top gibi

Parıltısı yağmurun

Dökülmeden dallardan

Gelmeden gece

Hatıra kokan köşelere

Sönmeden ağaçlardaki turunculuk

Umudu kırılmadan

Bekleyen kızın

Siyah saçlı romantik kızın

Saçlarında hüzün rengi

Gözlerinde kanat çırpan ışığı

Batmakta olan bir güneşin

Donuk ve puslu bakışı

Kristalden damlara

Pırlanta renkli

Koyu lacivert akşama.

Menekşe kokulu eski evleri

Öpüverdi mor akşam

Gözyaşı gibi

Dökülüverdi

Rüyaların sokağına

Ki orada bir kız

Beklerken sevgisini

Kalbi uyanık ayak seslerine

Dünyanın ortasında duran

Gelecek sonsuz yoldan

Sanki bir beyaz gül

Süre duran bir rüya.

Lüle lüle

Birbirine karışan

Saçların gibi mor akşam

Gitmiştir maviliğin yurduna

Sevgi dolu akşam.', 'Kırların Kokusu (I)  “Yastığının kenarına düşmüş siyah saçları hareketsiz ve karanlık bir şelaleyi andırıyordu... Nihayet çınar yaprağını, b...', ARRAY['Türk Edebiyatı','Şiir','Hulki Can']::text[], 8.5, '{"poet":"Hulki Can","poet_slug":"hulki-can","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kirlarin-kokusu-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metrisin Yükü', 'metrisin-yuku-hulki-can-p22w1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“Ayın son güneşi doğmadan

Dorların reisi Herkaria ordusuyla İrisis suyunu geçti 

Mikene karşı yüksek tepelerde metrisler kurdu.” 

(Bu düş ise o halde gerçek O. H.Y.M.)

I. Büyür kundağında dikey ve siyah

Yüzer toprağında bilinçsiz ve parlak

Dor  oğan kalkar ağzı yirik

Derisinden balığı köpek bakan

Sıvı mantar hava domuz

Metris maskesi mayotzim 

Songu sır hisarlar ilahı 

Tüter burca salgın yası

Küre uçlu elinde tırpan 

Taşar tepegöz karanlık

Marşını haykırır şanlı tümen 

Sönmez güneşsin sen 

Budunlar üstünde

Kartal yuvalarında 

Hürdür ölüm seninle 

Gog cehennemi kudurur  bile bak

Enginler bağanla dolar bile bak

Sürer yıkarak yılkı ırkı  magog 

Bozulur zamanların saatleri

II. Bir gün 

O dondurucu ve karlı günlerden bir gün

Beklenmedik hüzünler getiren o günlerden bir gün

Yiyip içerken ademoğlu

Kocaya varırken kızlar 

Hamurlar açılır cezvede kahveler pişerken

Sıcak pideler yana yana ellerde taşınırken

Çerçeve camgöz aynalar buğulanırken

“Kuyunun kovada takırdadığı o boz sokaklarda

Atların sıcak sıcak kişnediği o erken saatlarda” 

Parlayan savaş boranı 

O taşan çok  iri sudan

İlk izler gibi dalar karda kalan

Sonsuzluk bataklığına zaman 

Elde süngü silah cenk türküsü ağızlarda 

Saldıracağız ta ki bitip 

Kandıracağız   tanrıları tekrar 

Diyerek geçip gitti ordular

Son hedefiniz ölümdür  ileri! 

III. Savaşlar bitmeyince  sonbahar

Hızlanmış gitgide düşen 

Cephede kalan birlik geri

Ulu ilin   kiliseleri 

Talan etmişler camileri

Herkes için yol bulan

Yokolup ansız nal çakan

Yaklaşırken yomsuz kış 

Çatı katlarından kutsuz evlerin

Varoşlarından kuşatılan ilin

Görülmüştü koruganların

Üzerinde hışırdayan ufukların

Yabancı yüzleri ilahların

IV. Yıllar sonra

Yıllar sonra bir gün

Arasından yıkıntıların

Göğsü madalyalarla dolu

Gelmeden yenilmez ordu

Anıtına meçhul erlerin

Konmadan siyah çelenk

Duaya karışıp kan ve köpük

Dalmadan yeni uykulara

Giysileri paramparça

Omuzlukları kurukafa 

Kaybolur sevgileri, umutları

Ölümün o yüce ülkesinde

“Yıkılmaz bir barış yolunda, 

Birlikte giden ulusların”

Sabah kalkınca 

Hala dumanı tüten yerküreye 

Açıp baktığımda penceremi

Ve işte hepsi ölmüş leşlerdi...', '“Ayın son güneşi doğmadan Dorların reisi Herkaria ordusuyla İrisis suyunu geçti  Mikene karşı yüksek tepelerde metrisler kurdu.”  (Bu düş is...', ARRAY['Türk Edebiyatı','Şiir','Hulki Can']::text[], 8.5, '{"poet":"Hulki Can","poet_slug":"hulki-can","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/metrisin-yuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam Sırasıdır', 'tam-sirasidir-hafiz-osman-sarac-2ncb4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '--------------------

uzaklığım uzaklığına eş 

sen bana yabancısın. 

yıllarca yaktı yüreğimi 

gözlerimden akan nemli ateş. 

artık sen de bensizsin 

önemli değil 

-gururum kırık değil 

paramparça 

ağlamıştım aylarca. 

şimdi 

yüreğimi yakan vatan sevdasıdır 

şimdi 

seni terketmenin tam sırasıdır! .. 

güneşi gizlemek kimin haddine 

gözyaşlarım kuruduysa içim yanıyor 

davul hiç vurulmamıştı böylesine dengine 

sen beni anlamıştın 

utanıyorum 

utanmıyorsun özgürlüğüne 

artık ölmek istemiyorum beni terkettin diye 

vatana canlar lazım 

şimdi 

içimde esen yaşam fırtınasıdır 

şimdi 

seni terketmenin tam sırasıdır! .. 

adını duyunca yüreğim hopluyor 

ölümcül bir hastalık gibi 

yakaladın beni 

polisler kardeşimi copluyor 

ben ne diye hala düşünüyorum seni 

ister gel görüşüme, ister gelme 

ben 

sen gibilerin yaşaması için 

vatan dedim sevdama 

mutluluğu hayal bildim 

şimdi 

kavuşmak 

benim gibilerin başkaldırmasıdır 

şimdi 

seni terketmenin tam sırasıdır! ..', '-------------------- uzaklığım uzaklığına eş  sen bana yabancısın.  yıllarca yaktı yüreğimi  gözlerimden akan nemli ateş.  artık sen de bens...', ARRAY['Türk Edebiyatı','Şiir','Hafız Osman Saraç']::text[], 8.5, '{"poet":"Hafız Osman Saraç","poet_slug":"hafiz-osman-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/tam-sirasidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Babilin Yükü', 'buyuk-babilin-yuku-hulki-can-0dkok', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Apeninlerdeki mermer sunak 

Pontifex maximus 

Karabaş yıldırhaç

Saldıray fellah 

Ruh kuran kara küp 

İfritin tahtı büyük şaday

Orakla biçildi bu yük sana

Senle büyüledi halkları 

Dünyanın tüm atamanları! 

Ve sende bulundu acunda 

Öldürülen insan kanları! 

Dünya zenginleri kusmakta mallarını

Gelin ve güvey seslerin azalmakta

Çoktan kaçtı kudüm ve ney çalanların 

Rakseden gılmanların ve huri kızların

Kığlı ellerinde muska ve tespihler

Boşa secde ediyor önderlerin boşa

Ve aymazca yakarıyorlar bilmedikleri tanrıya! 

Senle ağuladı halkları 

Dünyanın bütün kralları! 

Ve sende bulundu tüm evrende

Öldürülenlerin kanları! 

İşte bunun için dehşet saçan avarız

Yılan göz kobra zehri baldıran yük

Darlık, yokluk, ölüm, elem ve bukağı

Yağacak mülküne küresel kargaşa

Yakacak zülfünü uluslar alazda

Paylaşacaklar çapul edip malını

Aç, perişan ve çıplak 

Hiç uyanmayacaksın bir daha 

Alanlardadır yıkılışın alanlarda

Bu kez bitene dek son yaban uluman!', 'Apeninlerdeki mermer sunak  Pontifex maximus  Karabaş yıldırhaç Saldıray fellah  Ruh kuran kara küp  İfritin tahtı büyük şaday Orakla biçild...', ARRAY['Türk Edebiyatı','Şiir','Hulki Can']::text[], 8.5, '{"poet":"Hulki Can","poet_slug":"hulki-can","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/buyuk-babilin-yuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorsun', 'biliyorsun-hafiz-osman-sarac-pqpzj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Batıldan dönebilseydin, 

Nefsini yenebilseydin, 

Dünyada sönebilseydin, 

Nurdun Osman,biliyorsun! 

Örümcektir ağı ören, 

İbret alsın bunu gören, 

Paramparça ilin tören, 

Yurdun Osman,biliyorsun! 

Düşüncelerin derinde, 

Neler bıraktın gerinde, 

Kalelerin üzerinde, 

Surdun Osman,biliyorsun! 

İçi boş bir tassın diye, 

Kalaylandın passın diye, 

Musa ayak bassın diye, 

Tur''dun Osman,biliyorsun! 

Aklı nefsiyle fitlere, 

Takılmış kalmış çitlere, 

Maskara olmuş itlere, 

Kurdun Osman,biliyorsun! 

Ayrılmadın hiç sözünden, 

Çile çektin ta özünden, 

Turnayı yanlış gözünden, 

Vurdun Osman,biliyorsun! 

Tükeniyor savaşın da, 

Gideceksin genç yaşında, 

Gelip mezarın başında, 

Durdun Osman,biliyorsun!', 'Batıldan dönebilseydin,  Nefsini yenebilseydin,  Dünyada sönebilseydin,  Nurdun Osman,biliyorsun!  Örümcektir ağı ören,  İbret alsın bunu gö...', ARRAY['Türk Edebiyatı','Şiir','Hafız Osman Saraç']::text[], 8.5, '{"poet":"Hafız Osman Saraç","poet_slug":"hafiz-osman-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/biliyorsun-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-hafiz-osman-sarac-is04d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğinde şefkat,

gözlerinde nem.

tel örgüler arkasından

Allah''ın rahmetiyle

bana bakıyor annem.

olur oğlum olur diyor

çamaşırları getirdim.

ve babanın hac esansını

baban duymasın ama,

çamaşırlarına döke döke bitirdim.

ve ziyaret bitiyor,

daha söyleyecek çok sözü vardı,

dualara sarılıyor,

gözlerimde gözü kaldı.

yüreğinde şefkat,gözlerinde nem.

giderayak,

tel örgüler arkasından

Allah''ın rahmetiyle

bana bakıyor annem...', 'yüreğinde şefkat, gözlerinde nem. tel örgüler arkasından Allah''ın rahmetiyle bana bakıyor annem. olur oğlum olur diyor çamaşırları getirdim....', ARRAY['Türk Edebiyatı','Şiir','Hafız Osman Saraç']::text[], 8.5, '{"poet":"Hafız Osman Saraç","poet_slug":"hafiz-osman-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/annem-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi Öl', 'adam-gibi-ol-hafiz-osman-sarac-5epit', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boğulan için ne farkeder,

Okyanus,deniz,göl? 

Madem ki ecelin budur,

Adam gibi öl! ..

Ecelinde varsa boğulmak,

İçtiğin su boğar seni,

Dilediğin kadar,böl! 

Kurtaramaz ecelinden,

Kaçtığın vaha,sığındığın çöl! .

Her gidiş eceledir,

Hiçbirşeyden korkma; 

Adam gibi yaşa,

Adam gibi öl!', 'Boğulan için ne farkeder, Okyanus,deniz,göl?  Madem ki ecelin budur, Adam gibi öl! .. Ecelinde varsa boğulmak, İçtiğin su boğar seni, Diledi...', ARRAY['Türk Edebiyatı','Şiir','Hafız Osman Saraç']::text[], 8.5, '{"poet":"Hafız Osman Saraç","poet_slug":"hafiz-osman-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/adam-gibi-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Av', 'av-nevzat-ozkan-66iaz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'elde on iki numara

tek kırma düzce,

sazlıklarda dolaşırdık.

aniden havalanan 

bir türlü vuramadığımız

yeşil başlar peşinde.

av dönüşü,

kapısı yarı açık

camları buğulu,

sönmeye yüz tutmuş

fıçıdan bozma sobasıyla,

karşılardı bizi,

sigarayla karışık

gübre kokulu köy kahvesi.

sararmış,

tırnakları kirli parmaklarda

hızla hareket ederdi 

yıpranmış iskambil kağıtları.

tıraşı gelmiş yüzlere,

tütün sarısı dişlerden yayılırdı

piştili gülümseme.

av dönüşü

soluklandırırdı bizi

çay bardaklarına

sigara kokusu sinmiş

salaş köy kahvesi.', 'elde on iki numara tek kırma düzce, sazlıklarda dolaşırdık. aniden havalanan  bir türlü vuramadığımız yeşil başlar peşinde. av dönüşü, kapıs...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/av-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Çok Soğuk…', 'soguk-cok-soguk-ali-orhan-gunaydin-f9awq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşmüşüm sabah yola…

Gün yeni yeni yüzünü göstermeye başlamış,

sokak ışıkları yanıyor hala…

Düşünüyorum…

Ne işim var bu saatte,bu soğukta…

Yağan kar.

Yolda ben.

Ve adamın yüzüne şamar gibi çarpan soğuk…

Yürüyorum…

Ayaklarımın altında ezilen kar ve buzların sesiyle,

şarkı mırıldanıyorum…

Kimi kandırıyorum…

Söyleniyorum…

“Üşümüyorum…

  Üşümüyorum…”

Birkaç çöp karıştıran kedi, köpek var caddede…

Birde dondurucu soğuğa rağmen,

cıvıl cıvıl öten bir iki serçe…

Soruyorum, kendimce…

Ne işleri var acaba? bu soğukta,bu vakitte…

Bir tebessüm geliyor, soğuğun etkisiyle gerilen yüzüme...

Anlıyorum…

Onlar,eşlik ediyorlar yalnızlığıma bence…

İnsan işte…

Yaşam zor,hava soğukta olsa,

bir güzellik buluyor sevmeyi bilince..

…sevince…

İlerliyorum…

Yağan kar…

Yolda ben…

Hava mı? 

Soğuk…

Çok soğuk…

14/02/2006', 'Düşmüşüm sabah yola… Gün yeni yeni yüzünü göstermeye başlamış, sokak ışıkları yanıyor hala… Düşünüyorum… Ne işim var bu saatte,bu soğukta… Y...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/soguk-cok-soguk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gümüşsuyu', 'gumussuyu-hafiz-osman-sarac-4zsdv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasret,çiğnendi gümüşsuyu,

Dikkat et gözlerine! 

Bir bakarsın,döner gelirim; 

Ellerimde,paramparça hasretinle…

Hem bilirsin,

Dünya bir başkadır,

Sürprizlerle doludur,acı,tatlı,

Gözlerinde kara sevda yası,

Tutamazsın bazen sözünü; 

Gözlerin dolar…

Hatıra doludur şarkılar,

Ağlarsın...

Sevda anlaşılmazdır! 

Hasret,çiğnendi gümüşsuyu,

Dikkat et gözlerine...

Seni anlatırsa rüzgar,

Susarım; 

Dudaklarım çatlar! 

Ve karakış,

Rüzgarlıdır gümüşsuyu,

Dikkat et gözlerine....

En sevmediğim dakikaları yaşarım,

Sana dönüşümde; 

Yine de,bilinmez bir duyguyla,

Koşarım…

Yollar,aşılmazdır bazen,

Bitmez,tükenmez ömür! 

Ölmek isterim,sözümü bozmadan,

Bana yıkılırım,dağlarca,

Yalnız kalırım…

Seni istemiyorum,ama,

Yürek,paramparçadır gümüşsuyu,

Dikkat et gözlerine…

Zaman gelir,

Büyürüm,

Büyür derdim,

Büyür yüreğimde,sevda; 

Büyür,sana uzaklığım! 

Acı,aranmazdır…

Ve kahkahadan nefret doğar! 

Her yanım sarıldı,

Her köşe başı,sensin,

Esir olmak,bana yakışmaz…

Sen,beni anar mısın,bilmiyorum; 

Hayal,dağlar kadardır,

Büyük olmak,bizedir! 

Sevgi,olunca konu

Hasret,kalıcıdır! 

Ağlamak,ansızındır gümüşsuyu,

Dikkat et gözlerine…

Yine dağlara baktım,

Bulutlar sayılmazdı; 

Yıldızları andım! 

Gece,yapışsın yakama,

Ayın,yıldızların hesabı,benden sorulur; 

Dağlar,düşecek arkama! 

Dünya,yaşanasıdır! 

Er ölmek,bana mahsus,

Gece ağlanasıdır…

Beni anlamıyorsun,

Garip konuşuyorum gümüşsuyu,

Dikkat et gözlerine…

Rüzgara üfledim,

Adım,kulağına çalınsın! 

O nefes,benim,

Sen,kim bilir,kimin nefesindesin! 

Yıkıldım bazen gururumun yanına,

Bir nefes sustum…

Sonra,dikildim aynalara,

Ben kimim,diye,sordum,

Dikildim kayalara; 

Gururumu diktim! 

Yine sana doğru bakıyorum,

Çok uzaktasın,

Burnumun dibindesin; 

Göremiyorum...

Yine dağlar,

Yine rüzgar,

Yine sevda,

Yine anlaşılmaz sözler…

Ne o,ağlıyor musun? 

Söylemiştim sana,

Hasret,çiğnendi gümüşsuyu,

Dikkat et gözlerine...', 'Hasret,çiğnendi gümüşsuyu, Dikkat et gözlerine!  Bir bakarsın,döner gelirim;  Ellerimde,paramparça hasretinle… Hem bilirsin, Dünya bir başka...', ARRAY['Türk Edebiyatı','Şiir','Hafız Osman Saraç']::text[], 8.5, '{"poet":"Hafız Osman Saraç","poet_slug":"hafiz-osman-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/gumussuyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-hafiz-osman-sarac-3ufht', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O ellerin,

Hani, ilk tokalaştığımızda,yüzümü kızartan…

Hani, yumuşacık,

Hani, vedalaşırken,

Titreyen bir nabız gibi elimi sıkan…

Hani, “bırakma” dercesine,kavrayan…

O ellerin vardı ya,

Ne çok severdim serçe parmağını,

Ne kadar da sevimliydi,

Minicikti…

Bahse girerken tuttuğunda,

Serçe parmağım, serçe parmağını bırakmayacaktı; 

Bir ömür kumar oynayacaktı! ...

Bir daha,

Hiçbir zaman,

Elini tutmayacağım! ..

Tutarsam,

Bir daha,

Hiçbir zaman,

Bırakmayacağım! ..

O ellerin,

Sanki beden bir şeydi,

Elin değildi…

Ve sen,

Benden bir şeydin,

Elin değildin; 

Elin olmak,elinde değildi! 

O ellerin,

Ne kadar da sevimliydi…

O ellerin,

Hani, ilk tokalaştığımızda yüzümü kızartan…

Hani, yumuşacık…

Hani,

Ayrılan,

Ellerin…', 'O ellerin, Hani, ilk tokalaştığımızda,yüzümü kızartan… Hani, yumuşacık, Hani, vedalaşırken, Titreyen bir nabız gibi elimi sıkan… Hani, “bıra...', ARRAY['Türk Edebiyatı','Şiir','Hafız Osman Saraç']::text[], 8.5, '{"poet":"Hafız Osman Saraç","poet_slug":"hafiz-osman-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ellerin-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''a Emanet Ol', 'allah-a-emanet-ol-hafiz-osman-sarac-pru5y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Veda vakti geldi,elveda dostum, 

Nerde namert varsa var ona kastım. 

Sustuysam,şartlara isyanla sustum; 

Dert sorarsan bizde,bol arkadaşım, 

Allah''a emanet ol arkadaşım! 

Çalış çalış fukaralık bitmiyor, 

Borçlarımın faizine yetmiyor, 

Böyle gelmiş ama böyle gitmiyor; 

Ne el kaldı ne de kol arkadaşım, 

Allah''a emanet ol arkadaşım! 

Yurdu yönetenler düşmüş gaflete, 

Yolu çevirmişler hep dalalete, 

Alkış tutuyorlar bak ihanete; 

Ne sağ belli ne de sol arkadaşım; 

Allah''a emanet ol arkadaşım! 

Gözleri yalandır,sözleri sahte, 

Yalanla yaşarlar,özleri sahte, 

Gözyaşları yalan,yüzleri sahte; 

Gülmeleri bile rol arkadaşım, 

Allah''a emanet ol arkadaşım! 

Yönetenler ne bulduysa aşırdı, 

En sonunda sabrımızı taşırdı, 

Tavuk bile kümesini şaşırdı; 

Ne yumurta var ne fol arkadaşım, 

Allah''a emanet ol arkadaşım! 

Köroğlu yoluna bal diyor şeytan, 

Eline silahı al diyor şeytan, 

Çağdaş Çamlıbel''e dal diyor şeytan; 

Kalmadı çıkacak yol arkadaşım, 

Allah''a emanet ol arkadaşım! 

Dostum sana Allah sabırlar versin, 

Sen de benim gibi öfkeni yersin, 

Bittiğin an gelir,bir umut dersin; 

Yine de umutla dol arkadaşım, 

Allah''a emanet ol arkadaşım!', 'Veda vakti geldi,elveda dostum,  Nerde namert varsa var ona kastım.  Sustuysam,şartlara isyanla sustum;  Dert sorarsan bizde,bol arkadaşım, ...', ARRAY['Türk Edebiyatı','Şiir','Hafız Osman Saraç']::text[], 8.5, '{"poet":"Hafız Osman Saraç","poet_slug":"hafiz-osman-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/allah-a-emanet-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlanacak bir yerler var', 'baslanacak-bir-yerler-var-hafiz-osman-sarac-d4iev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başlanacak bir yerler var,

Izdırap yanıma yatmışım; 

Yanmışım; 

Güvendiğim dağlara kar yağar! 

Duvar çıkar üstüme,

Düşlerim kanar.

Of çeker bir garip adam; 

Yüreğim yanar! 

Ömrüme sığmayan acı,

Mısraya sığar! 

Öfke,damla damla dolar içime; 

Azim olur kin olur ateş olur,

Yüreğimde sevgi biter taş olur! 

Başlanacak bir yerler var; 

Sövmeli birilerine,

Söverek başlamalı güne! 

Ve bilemeli yüreği,

Öfke ile,isyan ile,kin ile,

Gülü sıksam kan damlar! 

Bir istisnası olmalı nefretin,

Bir mesaj göndermeli birine; 

‘’dostluklar bitende,

dostluk ürettik.

Sen pek dur küçük ozan; 

Dostlar bitse de,

Bitmedik! ..’’

En durulmaz yerinde duruyorum feleğin,

En durulmaz zamanda,

Şu genç yaşımda

Bir murada ermeden...

Duvara bin küfür,

Allah''a şükür...

Başlanacak bir yerler var; 

Allah bilir,

Dost anlar...', 'Başlanacak bir yerler var, Izdırap yanıma yatmışım;  Yanmışım;  Güvendiğim dağlara kar yağar!  Duvar çıkar üstüme, Düşlerim kanar. Of çeker ...', ARRAY['Türk Edebiyatı','Şiir','Hafız Osman Saraç']::text[], 8.5, '{"poet":"Hafız Osman Saraç","poet_slug":"hafiz-osman-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/baslanacak-bir-yerler-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanıyor Sözcüklerim', 'utaniyor-sozcuklerim-selahattin-yetgin-ddbkw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşınan halatlarla çektik biz aşkın gemisini birlikte

Seninle ördük sevda kozasını aşkın ipek böcekleriyle

Kırk bir yerinden yaralı gönlümüzü onardık sevgiyle

Gözyaşı ırmaklarında çağladık hasretin türküleriyle

Yüzünün kıvrımlarını boşuna resmetmişim içime. Serçe kıvrımı dudaklarını ezberleyememişim anladım. Solgun kır çiçeği saçlarını dağıtırken ellerimle, unutmuşum onları bedenime dolamayı. Gözlerinin enginlerinde kaybolmuş, yüreğinin küflü odalarında boşuna ışık aramışım.

Su gibi aktı gitti işte o güzel günler. Saatler alabildiğine hızlı döndü, gecenin kollarında yaralarımla bağıra bağıra seni aradım. ‘sen olmasan ne yaparım buralarda? ’ diye kaç kez sordum gidişinle kendime. Sen gidince de yaşam sürüyormuş anladım. Senden geriye kalanları toparlayıp, tıktım gönlümün en rutubetli mahzenlerine. Anılarının yüreğimi dağlayan yerlerine tuzlar basarak öfkemin tetiklerine bağlayıp boşalttım ne varsa içimde. Ne varsa attım, bitirdim senden kalan ne varsa.

Sen gidince, içimdeki vahşi hayvanları da saldım ininden. Onlarla birlikte kükredim, gece yarılarına sığındım. Aklımın yüzdelerini yüzünün aydınlığına tutup senden yansıyan her şeye siper ettim gövdemi. Mantığımı söktüm içimden, nerede olabilirsin sorularına bile boş verdim anlayacağın.

Bir nefes kadar yakınken bana, üzerindeki masum giysileri çıkarıp attın buralardan gidince. Şeytanla işbirliği yapıp, yüreğini sıkı sıkıya kapattın bedeninle birlikte. Buralarda yaşadıklarını, geçmişinin izlerini unutmaya çalışıyorsun şimdi. Yüreğine kilit, ellerine kelepçe, gözlerine mil çekip, dudaklarının öldüren zehrini şimdi bir başkasına kusuyorsun.

Akşamlar buralarda yine anlayacağın. İnsanlar kaybolan günün tatlı yorgunluğunu atmak için evlerine koşuşturuyorlar. Renkli caddeler, tıklım tıklım duraklar, o duraklarda bekleyen insanlar yine aynı. Kiminin gözleri saatte, kiminin gözleri beklediği birinde. Yorulmuş bedenler, suskunluk sergileyen binlerce insan mışıl mışıl uykuların düşlerine taşıyorlar bedenlerini.

Ben de onlardan biriyim. Her akşam kurduğum yalnızlık soframda bu kez sensizim. Yüreğimin çağlamasına alışıyor, vefasızlığına çeşitli yorumlar üreterek geçiriyorum sensizlik saatlerimi. Karıncalar ağıyor yorgun gövdeme, üzerime doğrulan namlulara bile aldırmıyorum. Hasretinin martı çığlıklarına karışınca kardelenlerim boynunu büküyor, acıların göğsümü yıkıyor yağmurlarda.

Yıllar haklı çıkardı sana olan sevdamı. O yıllarda harcadım bütün servetimi. O yıllarda kaybettim yaşam gücümü. Dağlara tırmanışım bitmedi, bitmedi sana olan yürüyüşüm. Zaferler kazandın ben seni sevdikçe. Seni sevdikçe kadeh kaldırdın yalnızlığına. Aldanışlarına mutlu gülüşler sürdün, sevgilerimin altında ezildin, bilmedin. Çiğnedin hışımla ayaklarının altına attığım sevda güllerimi. Zifir saçlarını gecelerde dağıttın, kadehindeki günah şerbetiydi bilmedin.

Aslına bakarsan, ben de kandırmışım kendimi buncadır. Türkü ülkene varmak için boşuna dokunmuşum mızrapsız sevdanın tellerine. Kurumuş denizlerde boşuna kulaç atmışım. Bahçende yetişen çürümüş elmaları dişlemişim yıllarca. Günler dönünce anladım hiçbir şeye değmediğini. Anladım, ateşimle bir kendimin yandığını. Yıkılan yapılarım onarılmaz bir daha. Kelimelerim suskunlukta, utanıyor yüreğim sana sevdam demekten. Utanıyor sözcüklerim artık sana yârim demekten.', 'Aşınan halatlarla çektik biz aşkın gemisini birlikte Seninle ördük sevda kozasını aşkın ipek böcekleriyle Kırk bir yerinden yaralı gönlümüzü...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/utaniyor-sozcuklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Sızım', 'kalp-sizim-dilek-hokkaomeroglu-ytfq6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş kızıllığında mavilerin

Hayaller düş denizinde

Rüyalar gelincik misali asi

Dudaklarda hercai gülümsemeler

Aşk kardelen...

Zehirli sarmaşıklar umutları kemiren...

Bir sen varsın baktığım 

Bastığım her yerde...

Yılgın yorgun gecelerimde

Adını ben koyamadım

Gözlerimde ki ateşin

Kalp sızımın...

Titrek ruhum bedenimde

Ellerimde bir mavi gül..

Adımların geçmişe inat

Yağmur yağıyor yine

Geleceğimize', 'Güneş kızıllığında mavilerin Hayaller düş denizinde Rüyalar gelincik misali asi Dudaklarda hercai gülümsemeler Aşk kardelen... Zehirli sarma...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalp-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yükselen', 'yukselen-sevinc-kavuk-s2kh2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hikmetinde çözümlenilemeyen o inceliği

Bak neler sardı aklımı fikrimi üç nokta her şey 

Hep ikili de yer ve gök, beden ve ruh gibi

*Sevgi artı sevgi aşırı

**Aşk artı aşk aşırı

***Sevda artısı son! kara sevda yangını

Eder bu da üç nokta, ama artılarında aklım

Biri iç içe, öteki sıralı, artılarıyla da yükselen

Yerde yaşar önünü eşeler kalmam ki 

Bir göğe bir ileriye bakıp şaşmadan yemin billah

Ne eder eylerim yine de yükselirim......anladım ya! 

15.02.2006', 'Hikmetinde çözümlenilemeyen o inceliği Bak neler sardı aklımı fikrimi üç nokta her şey  Hep ikili de yer ve gök, beden ve ruh gibi *Sevgi ar...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yukselen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vebâl Altında Yürek', 'veb-l-altinda-yurek-tulay-sustam-ymgo5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çehresi ihânete dönük bir yüzün

peçesi düşerken yere

sırtımı döndüğüm

aşıklar tepesi eğiliyor / diz(e)    lerime 

işlenmemiş 

günahlarıma el açıyorum

bir mendile düşen göz yaşını

kefenle eş değer sayıp

çeyiz sandığımda saklıyorum

yeşeren son umudun dalını

ince belinden kırıp 

aşkı! ...

toprak anaya emanet ediyorum', 'çehresi ihânete dönük bir yüzün peçesi düşerken yere sırtımı döndüğüm aşıklar tepesi eğiliyor / diz(e)    lerime  işlenmemiş  günahlarıma el...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vebal-altinda-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Başkasının Oldugun Zaman', 'sen-baskasinin-oldugun-zaman-hanifi-isikoglu-k2h5t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni düşünmedigim gün olmayacak

içimdeki çilem  dolmayacak

gönül bahçemin gülleri solacak

sen başkasının oldugun zaman

kalbim virane yıkık olacak

kollarım bomboş kalacak

resmine baktıkça gözlerim dolacak

sen başkasının oldugun zaman 

başkası saracak güzel tenini

yabancı eller tutacak elini

inan bu gerçekler büker belimi

sen başkasının oldugun zaman 

degiştirecekler soy ismini 

başka sına terk edeceksin kendini

işte ozaman unutursun beni 

sen başkasının oldugun zaman', 'seni düşünmedigim gün olmayacak içimdeki çilem  dolmayacak gönül bahçemin gülleri solacak sen başkasının oldugun zaman kalbim virane yıkık o...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-baskasinin-oldugun-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis Gibi', 'sis-gibi-munur-atakul-6nps9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duman karası, bir sevda bu...

Belli,bellirsiz zamanlarda görünüp; 

Hiç beklenmedik anlarda giden..

Ve, her gidişinde beni böyle; 

Anlamsızca mahveden; 

Seher sisi gibi,bir sevda bu..

Bazen umulmadık, mutluluklara taşıyan..; 

Hiç, onulmadık kederleri, üstüme salan.

Topu, topu, üç günlük bir sevda bu; 

Ama, olmadı, beni böyle derin yaralayan! 

O,konuşmadan, beni anlayan...

Bakışırken, insanı canından ayıran.

Çok fazla, güzelde değil! 

Ama nedir bu? beni böyle kendisine..; 

Umarsızca bağlayan.

Ne, gözleri deniz mavisi; 

Nede, saçları altın sarısı..

Lakin öyle bir sevdaki bu! 

Daha dün gibi! 

Gitti, ömrümün yarısı..

Fakat iyileşmedi; 

Duman karası bu sevdanın; 

İçimde bıraktığı derman olmaz; 

Mahşer yarası.

Tek, sıcak bir gülücük; 

Bütün aldığım.

ve o sıcaklığınadır, böyle bağlandığım.

Ve o hiç, ama hiç tanımadığım! 

Bir, çaresizlik sevdası bu; 

Lanet olsun! 

Böyle mecbur kaldığım.

Matakul

23/02/1992 hayallerde sevgili ararken', 'Duman karası, bir sevda bu... Belli,bellirsiz zamanlarda görünüp;  Hiç beklenmedik anlarda giden.. Ve, her gidişinde beni böyle;  Anlamsızca...', ARRAY['Türk Edebiyatı','Şiir','Münür Atakul']::text[], 8.5, '{"poet":"Münür Atakul","poet_slug":"munur-atakul","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sis-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ın (cc) Zaferi', 'allah-in-cc-zaferi-lokman-hamitoglu-to97s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ALLAH’IN (cc)  ZAFERİ

       ÇANAKKALE

Çanakkale dediğin bir tarihin resmidir

Seyyid onbaşılarla Mehmet ‘lerin ismidir

İmansız orduları iman ile deviren 

Şehitlerin eliyle Allah’ın zaferidir! .. 

Küfürün hezimete uğradığı bu yerde

Halid’lerin yeniden doğduğu bu devirde 

Oluk - oluk kan aktı şüheda ayaklandı

Hamza’yı aramadık böylesi bir mahşerde! .. 

Çanakkale geçilmez elimizde Kur’an var

Vatanımız bölünmez gönlümüzde iman var

Taharetsiz yaşayan dinsizin görmediği 

Ömer, Osman, Ali’yle yeşil sarıklılar var! .. 

Allahü Ekber dedik abdest namazımızla 

Yürek Tevhid’le coştu ana niyazımızla

Düşmanlar kahrolurken Gelibolu önünde 

Arş’u ala’ya çıktık şerefli kanımızla! .. 

On sekiz mart dediğin en şanlı günümüzdür

Geleceğe teminat onurlu dünümüzdür

Türk’ü, Kürt’ü, Çerkez’i, Laz, Zaza, Arabıyla

Düşmana ders olsun ki; hep bütünlüğümüzdür! .. 

                                                   Lokman Hamitoğlu', 'ALLAH’IN (cc)  ZAFERİ        ÇANAKKALE Çanakkale dediğin bir tarihin resmidir Seyyid onbaşılarla Mehmet ‘lerin ismidir İmansız orduları iman...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/allah-in-cc-zaferi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-munur-atakul-867rm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş kızılıyla 

Elveda derken gökten

Hurda bir otobüsle geçiyorum 

Halicin, köprüsünden...

Duygularım, öyle perişan

Öyle yalnızım`ki! 

Tıka,basa, dolu otobüste`ki! 

İnsanlar içerisinde...! 

Soğuk,mart gününde

Camda terlemiş damlalar gibi; 

Ara sıra küçük umutlar

Geliyor aklıma; 

Ben, kollarımı değiştiriyorum

Tavan demirlerinde.

Mutsuzluk, yeniden sarıyor; 

Karşıdaki mutlu çiftin

Gamsız gülüşlerinde.

Geldiğim gün, 

Sabredip şükretmişim

Hep, böyle olmaz 

Düzelir demişim ileride.

Aslında, bu bendeki

Bir kadına duyulan özlem,

Yada şöhrete olan 

İlgi alaka değil; 

Benim derdim

Bir başka şey 

Nasıl derler bilmemki,

Hani bir askerin,

Tezkere alacağı günün bir öncesi,

Yahut gelinlik bir kızın,

Gerdeğe gireceği gecesi; 

Veya idam mahkumunun

Edeceği son hecesi,

İşte, böyle bir şey gibi,

Duygularım aklımda; 

Açıkçası,ben senin kadar karışık,

Van gölü kadar durgun,

Asi Fırat kadar,

Coşkunum şu anda; 

Ben beni, anlatamadım, İstanbul

Sen, beni anla

Matakul

12/03/1986 İstanbulda karşıya geçerken', 'Güneş kızılıyla  Elveda derken gökten Hurda bir otobüsle geçiyorum  Halicin, köprüsünden... Duygularım, öyle perişan Öyle yalnızım`ki!  Tıka...', ARRAY['Türk Edebiyatı','Şiir','Münür Atakul']::text[], 8.5, '{"poet":"Münür Atakul","poet_slug":"munur-atakul","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/istanbul-391-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor', 'sor-hanifi-isikoglu-z4cyy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bilmek istiyorsan aşkımı

seni anlattığım gecelere sor

hıçkırıp aglayan susayan dilimden 

düğümlenip kalan gecelere sor

kör düğüm gibisin beni baglayan

kapanmaz yarasın bende kanayan

benimle beraber sana aglayan

yüregimin göz yaşlarına sor

aşkını unutmak inan imkansız

topraga götürün beni amansız

boşalan şişeler artık faydasız

yerlere vurdugum kadehlere sor', 'bilmek istiyorsan aşkımı seni anlattığım gecelere sor hıçkırıp aglayan susayan dilimden  düğümlenip kalan gecelere sor kör düğüm gibisin ben...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sor-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Âh Ettim Gençliğime', 'h-ettim-gencligime-burhanettin-akdag-j1x5v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir âciz serseriyim ömrüm geçti yollarda

Perişan ve pişmanım dersem de geçmez kâra

Boşa kürek çekerken derman bitti kollarda

Âh ettim gençliğime sarsam da geçmez kâra.

Derinden yâr sevmiştim gençliğimin emeli

Savrulurken saçları bel kırıp esnemeli 

Tutamadım gönlümde kaçırttım ne demeli? 

Âh ettim gençliğime varsam da geçmez kâra.

Hiç demedim düşerim tutmadım bir köşeyi

Bakmadım kör halime göremedim bir şeyi 

Çabucak geçti yıllar tükettim ben her şeyi

Âh ettim gençliğime vursam da geçmez kâra.

Kırdım döktüm topladım kalmadı gitti yele

Terk edip gitti yârim dalamam ben hayale

Menzil varmış ecele yoktur faydam iyâle

Âh ettim gençliğime sorsam da geçmez kâra.

Dedim ki olan olmuş bari adam olayım

Düşkünlere el verip gönüllerde kalayım

Hayır dualar alıp doğru yolu bulayım

Âh ettim gençliğime yorsam da geçmez kâra.

Ömrümün hasadında tarlamda yandı burçak

Öğrenmedim sevgiyi yüreğim pürçek pürçek 

Dünyada her şey yalan sadece halim gerçek

Âh ettim gençliğime görsem de geçmez kâra.

Bil ki bu beden sende emanettir, günü gelince geri alınacaktır.

(İnna lillâh ve inna ileyhi raciûn.) )  

(15.02.2006)', 'Bir âciz serseriyim ömrüm geçti yollarda Perişan ve pişmanım dersem de geçmez kâra Boşa kürek çekerken derman bitti kollarda Âh ettim gençli...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ah-ettim-gencligime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni Bekle', 'bekle-beni-bekle-salim-erben-hoymv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sarmasın seni kederle hüzün 

Bağ bozumunda gelirim güzün 

Şarkılar seni söyler iki gözüm 

Bekle beni bekle şafakla gelirim 

Uzak yoldayım tez dönemem 

Çatma kaşlarını ben göremem 

Islatma kirbiğini gayrı silemem 

Bekle beni bekle şafakla gelirim 

Felek sillesini vurdu bıraktı 

Ayırdı senden ciğerimi yaktı 

Ne hayal kurdum onuda yıktı 

Bekle beni bekle şafakla gelirim 

Öfkemi beli etmez kağıda yazarım 

Bazen de durup dururken azarım 

Bağırıp çağırıp kendime kızarım 

Bekle beni bekle şafakla gelirim', 'Sarmasın seni kederle hüzün  Bağ bozumunda gelirim güzün  Şarkılar seni söyler iki gözüm  Bekle beni bekle şafakla gelirim  Uzak yoldayım te...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekle-beni-bekle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atam...', 'atam-bahri-koksal-7kvh8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlayamadık seni bir türlü,anlatamadık

Tarihin yüzyıllarına koyduk,dinletemedik

Ağlamakla geçirdik,hiç ilerleyemedik

Törenlerde andık,hiç gülümseyemedik

Ülkemin gençlerine o yolu gösteremedik

Resimlerinle avunduk,izini göremedik

Kalbimizdesin dedik...Ama,yolunda yürüyemedik...', 'Anlayamadık seni bir türlü,anlatamadık Tarihin yüzyıllarına koyduk,dinletemedik Ağlamakla geçirdik,hiç ilerleyemedik Törenlerde andık,hiç gü...', ARRAY['Türk Edebiyatı','Şiir','Bahri Köksal']::text[], 8.5, '{"poet":"Bahri Köksal","poet_slug":"bahri-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/atam-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayim', 'dayim-tugba-simsek-dozig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dayicigim omrun bu kadarmis, neyleyim ben? 

Aglamak seni getirse, gunlerce hic durmadan aglarim

Yalvardim Allah''ima cennetin kapisinda olasin diye

Inanamiyorum hala toprak altinda olduguna

Malesef biraktin bizi, esini, cocuklarini...

30.01.2005

(sen asla ölmedin dayicigim...)', 'Dayicigim omrun bu kadarmis, neyleyim ben?  Aglamak seni getirse, gunlerce hic durmadan aglarim Yalvardim Allah''ima cennetin kapisinda olasi...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim Güzelmi Güzel', 'sevdigim-guzelmi-guzel-yusuf-onder-bahceci-17fx6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim bir sevdiğim var güzelmi güzel,

Sanki karlı dağlar ceylanı salınır gezer,

Aman gülüşünü sormayın bağrımı ezer,

Benim bir sevdiğim var güzelmi güzel.

Benim bir sevdiğim var güzelmi güzel,

Ben onu öyle sevmişim, evvel ve ezel,

Aşkı kâlbimi yakıyor, kül ediyor, güzel,

Benim bir sevdiğim var güzelmi güzel.

Benim bir sevdiğim var güzelmi güzel,

Onu nasıl vasfedeyim Leyla''dan güzel,

Onun peşinde çöllerdeyim, yok güzel,

Benim bir sevdiğim var güzelmi güzel,

Benim bir sevdiğim var güzelmi güzel,

Güzel olmuş neyleyim o şimdi el güzel,

Gözleri aklıma gelir elimde değil güzel,

Benim bir sevdiğim var güzelmi güzel,', 'Benim bir sevdiğim var güzelmi güzel, Sanki karlı dağlar ceylanı salınır gezer, Aman gülüşünü sormayın bağrımı ezer, Benim bir sevdiğim var ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdigim-guzelmi-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başkadır Benim Sevdam...', 'bir-baskadir-benim-sevdam-bahri-koksal-uxv2w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir başka olur benim sevdam

İlmek,ilmek nakışlıdır

Gönlümdeki duyguların

Her noktasına...

Tutkuludur güzelliklerinin

Her zerresine.

Saçlarının tellerine konan

Kumruların sevdasında

İlkbahar çiçeklerinin

Her renginde arar seni...

Bir başkadır benim sevdam

Gökteki yıldızlar kadar

Denizlerdeki sular kadardır.

Bazen bir yağmur damlasındadır

Bazen gökkuşağının bir rengindedir

Bazen de sabahın

Çiy düşmüş damlasındadır.

Gözünün rengindedir

Burnunun ucundadır

Bir akşam üstü

Batan güneşin kızıllığındadır.

Taa yüreğimin derinindedir

Benim sevdam.

Bitmez-tükenmez bir coşkuyla

Sendedir,seninledir

Ve tüm bedenimdedir senin sevdan...

                             Tirebolu-19 Eylül 2006', 'Bir başka olur benim sevdam İlmek,ilmek nakışlıdır Gönlümdeki duyguların Her noktasına... Tutkuludur güzelliklerinin Her zerresine. Saçların...', ARRAY['Türk Edebiyatı','Şiir','Bahri Köksal']::text[], 8.5, '{"poet":"Bahri Köksal","poet_slug":"bahri-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-baskadir-benim-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşver', 'bosver-munevver-senol-35dg2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Katladım devşirdim hayat kitabımı.

Kağıdım tükendi kalem yetmedi.

Şu darıı dünyada neler çektimde.

Onu benden başka kimse bilmedi.

                              

Bundan sonra inşallah gülerim diyorum.

Şimdi poliannacılık oynamaya karar verdim ben.

Eller gibi yalandan aşığım seviyorum.

Hayat seninle ne kadar güzel? demek isterdim amma 

ALLAH kahretsin elim gitmiyor yazamıyorum.

Hayatımda yalana yer yok, yapmacıkta yapamıyorum.

Fazla doğrulukta aptallık bunuda biliyorum.

Ama satmışım anasını ben bu dünyanın.

Savrulun önümden ben geliyorum boşver.', 'Katladım devşirdim hayat kitabımı. Kağıdım tükendi kalem yetmedi. Şu darıı dünyada neler çektimde. Onu benden başka kimse bilmedi.          ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bosver-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asigim', 'asigim-tugba-simsek-194ui', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Asigim askim, tutkunum sana ben

Sakayla aski karistirma lutfen

Inanmazsan daglara cikip haykiririm

Gel etme bebegim giriver su gonlume

Inanman icin daha ne yapayim ben? 

Melegim gel inat etme sev beni...

16.12.2004  19.53', 'Asigim askim, tutkunum sana ben Sakayla aski karistirma lutfen Inanmazsan daglara cikip haykiririm Gel etme bebegim giriver su gonlume Inanm...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/asigim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardan adam öldü', 'kardan-adam-oldu-seyit-ahmet-duzen-y5tb1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kardan adam öldü, güneş çarpmasıyla

Sevdası çığ gibiydi,soğuk ve tehlikeli

Ekspressiz bir otobüs gibi kenti dolaştı acısı

Son seferde şöfüre kendisi...

Önce çocuklar ağladı, sonra karakış

Gitti kardan adam bahar gelince,gitti

Kardan adam öldü,esmer bir kadında

Çırılçıplak bir kadına dokundu

Hissetmeden arzulu ateşini,sarıldı

Sevişti esmer teniyle,mavi gözleriyle

Sevişti geceyle,ayla, yıldızla

Gece hiç bitmedi...Bitti kardan adam.

Kardan adam öldü, bar taburesinde

Çilingiriydi: masası,alkolü ve çözüldü

Umarsız aşkalarını anlattı sağır duvarlara

Seviştiğini adını bilmediği bir kadınla

Ona tutulduğunu,mahvolduğunu

Uyansanıp şişelere çarptığı an, yine anımsadığını 

Kardan adam öldü, bir şairin yanlış imlasında

Söyleyemedi titrerken eksik,olan birşeyleri

Daha kış bitmemişti, kara yazılmamıştı adına

Ölmemeliydi kardan adam,gitmemeliydi

Ama öldü...(ben öldürdüm)', 'Kardan adam öldü, güneş çarpmasıyla Sevdası çığ gibiydi,soğuk ve tehlikeli Ekspressiz bir otobüs gibi kenti dolaştı acısı Son seferde şöfüre...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kardan-adam-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gicik', 'gicik-tugba-simsek-nvwwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gicik diye takilip yaklastin bana

Imrendim tatli huylarina, sokuldum sana

Canim yaniyor, seviyorum dedin bana

Inandim, guvendim, baglandim ben sana

Kirdin bigun kalbimi, biraktin beni bana

16.12.2004  19.35', 'Gicik diye takilip yaklastin bana Imrendim tatli huylarina, sokuldum sana Canim yaniyor, seviyorum dedin bana Inandim, guvendim, baglandim b...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gicik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask', 'ask-tugba-simsek-j8y02', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asik olmak neden bu kadar aci ve zor sanki sevgilim? 

Su kalbim senin icin oyle yanip tutusuyor ki sevgilim! 

Kalbinin sesini kalbime versende benim olsan sevgilim...

1.05.2005  21.37', 'Asik olmak neden bu kadar aci ve zor sanki sevgilim?  Su kalbim senin icin oyle yanip tutusuyor ki sevgilim!  Kalbinin sesini kalbime versen...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-547-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sehit', 'sehit-tugba-simsek-v3wje', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sehit olup kara toprak olmussun duydum ki

Evine, ocagina bir ates dusmus

Hani donusunu kutlayip eglenicektik

Inanamadim sensizlige, yok olup gidisine

Talihsiz yigidim, rahat uyu sen topraginda...

20.05.2005  16.51', 'Sehit olup kara toprak olmussun duydum ki Evine, ocagina bir ates dusmus Hani donusunu kutlayip eglenicektik Inanamadim sensizlige, yok olup...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sehit-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün Yaşlı mı Dilber', 'gozun-yasli-mi-dilber-i-rfan-kayagil-3g0wj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözün yaşlı mı dilber

Yolun taşlı mı dilber

Dolanıp yol bulayım

Kapında kul olayım

Saçın verme rüzgara

Açar gönlümde yara

Hızır gelmez imdada

Kulun düşmezse dara

Çaresizim gelemem

Bir nağme gönderemem

Aşkının tutsağıyım

Överim de yeremem

İrfan der neyleyim

Aşkını dileneyim

Yanmaktan köze döndü

Küllenmesin yüreğim', 'Gözün yaşlı mı dilber Yolun taşlı mı dilber Dolanıp yol bulayım Kapında kul olayım Saçın verme rüzgara Açar gönlümde yara Hızır gelmez imdad...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozun-yasli-mi-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk...', 'ask-bahri-koksal-5fkgn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimini mesut eder

Kimini deli.

Kimini mahveder

Kimini serseri.

Kimini yok eder

Kimini de zır deli.

İşte bunları yapan

Bu üç harfin eli...

                Tirebolu-1985', 'Kimini mesut eder Kimini deli. Kimini mahveder Kimini serseri. Kimini yok eder Kimini de zır deli. İşte bunları yapan Bu üç harfin eli...   ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Köksal']::text[], 8.5, '{"poet":"Bahri Köksal","poet_slug":"bahri-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-549-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölesiye Özlem', 'olesiye-ozlem-yasar-tezel-ui3uw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dil bilmezim,kınalı kuzu

Sevdalım

Senin yüzünden,bu halım

Gittin gideli,dinecek bu sızı

Söylenecek,hiç bir söz

Kalmadı

Kimden öğrendin,sen güzelim

Vebal almayı

Samanlık göçmedi,göçen gözleriniz

Anılar ölene kadar dı

Yıktın divaneyi

Saç sakalı bıraktı

İnan, farklı bir adam,

Olmam

Diyecekmisin,bu zavallı 

Kara sevdalı', 'Dil bilmezim,kınalı kuzu Sevdalım Senin yüzünden,bu halım Gittin gideli,dinecek bu sızı Söylenecek,hiç bir söz Kalmadı Kimden öğrendin,sen g...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olesiye-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 19 terkediş zamanı vol. 2', 'lirik-19-terkedis-zamani-vol-2-fevzi-cebe-818oc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'terkediş zamanı

burukluk olmalı kalbinde

ve yeni zamanlara isteğin

bir damla gözyaşı

geçmişin hatırasına

terk ediş zamanı

tüketilmemiş olmalı

düne ait her şey

bir suskunluk kaplamalı 

her yanını

gözleri, aklına gelir

sözleri ve dokunuşları

dokunuşların

ilk gece uykuya teslim olmak...

o kadar kolay değil

‘yatağa’ sığamamak

terk edildiğini

terk ettiğini...bilmek

23.05.2004 - Pazar Nöbette

rev. 15.02.2006', 'terkediş zamanı burukluk olmalı kalbinde ve yeni zamanlara isteğin bir damla gözyaşı geçmişin hatırasına terk ediş zamanı tüketilmemiş olmal...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/lirik-19-terkedis-zamani-vol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-tulay-i-cen-t4w31', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizliğin,hasretliğin adına,

Gurbet  dediler.

Özlemlerimi  gönderdim

Sana.

Rüyalarımı, hayellerimi,

gurbet teki  adrese.

Ulaşmadan  döndü  geriye.

Bahar  geldi, kış geldi.

Yazın  sıcağı,kışın soğuğu,

Yaktı bu  yüreği.

Beklerim inatla,   hasretle  seni,

Sürgün  oldu bu yürek seninle,

Gurbet te...

15/02/2006', 'Sensizliğin,hasretliğin adına, Gurbet  dediler. Özlemlerimi  gönderdim Sana. Rüyalarımı, hayellerimi, gurbet teki  adrese. Ulaşmadan  döndü ...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gurbet-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizligim', 'sensizligim-kemal-oguz-665gh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Avutuyorum kendimi.

Unutuyorum derdimi.

Sen olmadan Sensiz.

Sensizligim, Sensizligim.

Gecelerim hep Sensiz.

Yasamimda Sen varsin.

Damarimda kanimsin.

Sen benim tek canimsin.

Sensizligim, Sensizligim.

Rüyalarim hep Sensiz.

Arzu etsem gelmiyorsun.

Sevdim Seni bilmiyorsun.

Göz yaslarim silmiyorsun.

Sensizligim, Sensizligim.

Agliyorum hep Sensiz.

(Esslingen, 12 Eylül 1989)', 'Avutuyorum kendimi. Unutuyorum derdimi. Sen olmadan Sensiz. Sensizligim, Sensizligim. Gecelerim hep Sensiz. Yasamimda Sen varsin. Damarimda ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizligim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiskaniyorum', 'kiskaniyorum-tugba-simsek-o8exa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Icimin sizlayan yarasini

Bilmem anliyor musun? 

Seni O''nunla gordugumde

Kendimden geciyorum

Neden bana bu ceza

Ne yaptimda bilmiyorum

Seni O''nunla gormeye

Dayanamiyorum, kaldiramiyorum

Aslinda O senin, sana ait

Her zaman yanibasinda

Basucunda, kollarinda olabilir

Genede ben sizliyorum

Karismaya hakkim olmadigini

Adim gibi bilsem de

Genede dayanamiyorum

Kendimden geciyorum

Yinede duygularimi, kendimi

Icimdeki sizlayan yarayi

Anlamadin demi? Cunku,

Seni seviyor ve kiskaniyorum

20.02.2005   18.02', 'Icimin sizlayan yarasini Bilmem anliyor musun?  Seni O''nunla gordugumde Kendimden geciyorum Neden bana bu ceza Ne yaptimda bilmiyorum Seni O...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kiskaniyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-emrah-karakoc-dvn2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendime gelirim, kendim olurum

Bana manevi güç katar geceler

Aradığım mutluluğu bulurum

Gündüzden gözümde tüter geceler

Beklenenler gelir, muhabbet başlar

Hak aşkıyla akar gözlerden yaşlar

Daha bir heybetli görünür taşlar

ömürlere ömür katar geceler

Zaman törpülenir, su gibi akmaz

Huzur verir kalbe, kavurup yakmaz

Dümen, dalevere ve hile yapmaz

Kendi doğrusunda akar geceler

Bir anne uyanır kan uykusundan

Haz alır bebenin saf kokusundan

Su alır topraktan küçük bir fidan

Her şeye dost gözle bakar geceler

Emrah Karakoç''un kalemi yazar

Yüreği kuş olur havada gezer

Gölyaka''da duran o taze mezar

Gelir, kalp evinde yatar, geceler', 'Kendime gelirim, kendim olurum Bana manevi güç katar geceler Aradığım mutluluğu bulurum Gündüzden gözümde tüter geceler Beklenenler gelir, m...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/geceler-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AsLAN Kral.', 'aslan-kral-i-shak-ozlu-9pld4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'V:Kralımız çok yaşa.

G:Yalaaaan yalaaaan.

V:Sen AsLANsın...

G:Yalaaaaan yalaaan.

V:Sen KapLANsın.

G:Yalaaaan yalaaaaan.

Burası Adana dağları duman,

Kral gelmiş öfkesi çok yaman.

Tebaasına müjdeler getirmiş kral,

Krala çıplaksın diyor bir çoban.

V:Kral çıplak,

K:Kimdir o densiz.

    Tez huzuruma getirin.

     Ne dedin sen LAN.

Ç:İki yıldır açız kralım.

K:Zıkkımın kökünü ye LAN,

Ç:Birde yaşlı anam var kralım,

K:Sus LAN maraba,

   Anandan başlatma şimdi,

    Kodum mu oturturum uLAN.

Ç:Vaaay bana haaaa.

K:Sana LAN dümbük,hem sana hem gelmişine,hem geçmişine.

Ç:Canın sağolsun gaLAN kralım.

K:Sana ne getirdim haberin var mı? 

Ç:Var kralım.

K:Ne getirdim.

Ç:Küfür edebiyatı,

    Makam zorbalığı,

    Kibir ve aşağılama.

K:Az bile dahası arkadan gelecek.

Kralın sıfatı bellidir asLAN,

Orman kanununca konuşur''''sus LAN'''',

Yorma kendini yüce kralımız,

Buyur Bush koltuğuna yasLAN.

K:Bostancıbaşıııııııııııııııııııı,

B:Anlaşıldı kralım,

***Pata küte de pata küte.

Ç:Solum ameliyatlı,sağım zekaratta,

   Vuracaksınız arkama vurun.

Y:Bizde onu yapıyoruz zaten.

   İşimiz bu arkandan vurmak.

***Pata küte de pata küte.

Bir garip sakallı bozmasın keyfini,

Sensin Garbın-Şarkın en cini.

Maraba kısmına yüz vermeye gelmez,

Dilerse Paşa gönlün satarsın hepsini.', 'V:Kralımız çok yaşa. G:Yalaaaan yalaaaan. V:Sen AsLANsın... G:Yalaaaaan yalaaan. V:Sen KapLANsın. G:Yalaaaan yalaaaaan. Burası Adana dağları...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/aslan-kral-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-tugba-simsek-je89r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni seviyorum... Ben senden seni istiyorum... Ben senden hayatin guzelliklerini istiyorum... Ben senden beni sevmeni istiyorum...

Ben seninle yasamak istiyorum... Ben seninle var olmak istiyorum... Ben seninle bir omur boyu olmak istiyorum... Ben seninle yalnizca seninle olmak istiyorum...

Ben senden beni cok sevmeni istiyorum... Ben senden sonsuza dek benimle olmani istiyorum... Ben senden daima mutluluk istiyorum... Ben senden sevgi-saygi istiyorum...

Ben benim esim olmani istiyorum... Ben benim sirdasim olmani istiyorum... Ben benim askim-melegim olmani istiyorum... Ben benim hayatim olmani istiyorum...

Ben ikimizin dunyasini yalansiz istiyorum... Ben ikimizin dunyasini guven dolu istiyorum... Ben ikimizin dunyasini mutluluk dolu istiyorum... Ben ikimizin dunyasinda birbirimiz icin var olmak istiyorum...

7.05.2003  20.40', 'Ben seni seviyorum... Ben senden seni istiyorum... Ben senden hayatin guzelliklerini istiyorum... Ben senden beni sevmeni istiyorum... Ben s...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ben-248-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günüm...', 'dogum-gunum-bahri-koksal-9u4zr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bin dokuz yüz elli beş yılının

Bir kış günü doğmuşum

Ocak ayının üçü sabaha karşı

Yoksulluğun tam ortasına düşmüşüm.

Fitilli gaz lambasının titreyen ışığında

Köy ebeleri çok çektirmişler anama

Garibim ne çığlıklar atmış...

Anlatırdı da o yoksulluğu

Sabahın ayazındaki korkularını

Gözleri yaşarırdı anlatırken.

Babam da yokmuş yanında

Gölcük''te askerlik yapıyormuş

Bahriyeli olarak.

Benim adımı da

Bahriyeli oluşundan koymuş,

Köy ebem

Soğuk su dolu kazanın içine

Ayaklarımdan tutarak

Üç-dört kez batırıp çıkarmış beni

Canlı olsun diye.

Sonra bir çul parçasına sarıp

Anamın kucağına vermişler.

Öyle yapışmışım ki göğsüne

Çığlığım kesilinceye kadar.

Ablamdan yedi yıl sonra doğduğumdan

Erkek çocuk sevinci anamın yüreğinde

Kelebekler uçurmuş kış ortasında.

Yirmi beş yaşında doğurmuş beni

Kol-kanat germiş günlerce

Üzerime titremiş

Uzun kış gecelerinin ayazında.

Sonra; 

Mehmet dayım müjde vermiş babama:

''Bir oğlun oldu'' diye.

Uzunca bir aradan sonra

Babamdan mektup gelmiş

Önce sevincini belirtmiş

Sonra adını ''Bahri koyun'' demiş.

İşte ben,o günden bugüne

Yaşamın içindeyim

Bugündeyim,sizinleyim...

     ''Anamın hatırasına saygıyla...''

                                    Tirebolu-31 Aralık 2005', 'Bin dokuz yüz elli beş yılının Bir kış günü doğmuşum Ocak ayının üçü sabaha karşı Yoksulluğun tam ortasına düşmüşüm. Fitilli gaz lambasının ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Köksal']::text[], 8.5, '{"poet":"Bahri Köksal","poet_slug":"bahri-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/dogum-gunum-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Şarkılar Söylüyor Aşk', 'i-cimde-sarkilar-soyluyor-ask-kevser-gulistan-cakir-xj5l5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimde şarkılar söylüyor aşk

Veda makamından...

Notalar gittiğin yollara diziliyor

Sol anahtarsız ve ölçüsüz

İçimde şarkılar söylüyor aşk

Hasret makamından

Pişmanlık vokal yapıyor...', 'İçimde şarkılar söylüyor aşk Veda makamından... Notalar gittiğin yollara diziliyor Sol anahtarsız ve ölçüsüz İçimde şarkılar söylüyor aşk Ha...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/icimde-sarkilar-soyluyor-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa''yı Gördüm Kemal''i Gördüm', 'mustafa-yi-gordum-kemal-i-gordum-emrah-karakoc-amu2r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özgürce gezerken kırda - bayırda

Mustafa''yı gördüm Kemal''i gördüm

Şerle işimiz yok şükür, hayırda

Mustafa''yı gördüm Kemal''i gördüm

Her karış toprakta karasabanda

Demiryollarında, hava yolunda

Baktığım her yerde ve de en önde

Mustafa''yı gördüm Kemal''i gördüm

Tarihe bakarken, güne bakarken

Işığın geldiği yöne bakarken

Sümbüle bakarken, güle bakarken

Mustafa''yı gördüm Kemal''i gördüm

Mehmedim kışlada nöbet tutarken

Eminem halıya kirkit atarken

Fazıl Say şanıma şanlar katarken

Mustafa''yı gördüm Kemal''i gördüm

Karakoç''un canı kurban yoluna 

Lanet olsun ona düşman olana

Bakıp geçmişime, bakıp yarına

Mustafa''yı gördüm Kemal''i gördüm

Teninde gül açan cemali gördüm', 'Özgürce gezerken kırda - bayırda Mustafa''yı gördüm Kemal''i gördüm Şerle işimiz yok şükür, hayırda Mustafa''yı gördüm Kemal''i gördüm Her karış...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mustafa-yi-gordum-kemal-i-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasil Anlatsam', 'nasil-anlatsam-tugba-simsek-c3o88', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bende ki nasil bir tutku bilemiyorum

Zaman zaman soruyorum kendime

Cevap veremiyor, anlatamiyorum

Sana nasil anlatayim sevdigim

Hergun karsilasir, seninle bakisirdik

Yuregim kipir kipir olurdu

Ne yapacagimi sasirir, korkardim

Sevmekten, sana yaklasmaktan cekinirdim

Farkinda olmadan, hergun biraz biraz

Ne yaptigimi bilmeden yaklasmisim

Seni seyrediyordum, bana bakisin

Gozlerime bakisin hosuma gidiyordu

Sen gozlerime bakarak kacarken

Baskalari beni sevdigini anlatti

Tuaf oldum, gecelerce dusundum

Beni seveni sevmeli miyim dedim

Birgun baktim ki, karsikarsiyayiz

Oyle hos, oyle sicak bakiyordun ki

Ne dusundugumu bile bilmedim

Arzuna, sevdana karsilik vermisim

Beni sevdigini hayal ettim

Sadece beni istedigini dusundum

Birde baktim ki kapilmisim

Sevdana sevdalanip tutulmusum

4.09.2003   22.00', 'Bende ki nasil bir tutku bilemiyorum Zaman zaman soruyorum kendime Cevap veremiyor, anlatamiyorum Sana nasil anlatayim sevdigim Hergun karsi...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nasil-anlatsam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara tren', 'kara-tren-tulay-i-cen-s430y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekleyen yokmuş! ..

O son tren istasyonunda,

Kara trenin  son yolculuğuydu

Sana..

Kara trenle  yolladım,

Sana  yüreğimi.

Alırsın diye gardan,

Karşılamadın.

Seni  seven,

Seni  özleyen,

Yüreği...

Sevgi  yükledim,

Kara trene,

Rüyalarımı,

Özlemlerimi ve geleceğimi

Alırsın diye..

Bekleyen yokmuş,

O son istasyonda...', 'Bekleyen yokmuş! .. O son tren istasyonunda, Kara trenin  son yolculuğuydu Sana.. Kara trenle  yolladım, Sana  yüreğimi. Alırsın diye gardan...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-tren-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Sevgilim?', 'neden-sevgilim-tugba-simsek-9t4sc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oyle cok sevmisken ne oldu simdi

Aramaz, sormaz, gelmez oldun

Halimi, sevdami merak etmez oldun

Neden sevgilim, niye boyle oldun? 

Oysa ne cok sevmis istemistin

Seni sevmemi, sadece senin olmami

Herseye olmaz derken, sen olur dedin

Peki simdi neden yoksun sevgilim? 

Sabahlari hasretinle gozlerimi aciyorum

Aksamlari hasretle yataga giriyorum

Belki yarin gelirsin diye avunuyorum

Ama gelmiyorsun, neden sevgilim? 

25.04.2004  13.30', 'Oyle cok sevmisken ne oldu simdi Aramaz, sormaz, gelmez oldun Halimi, sevdami merak etmez oldun Neden sevgilim, niye boyle oldun?  Oysa ne c...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neden-sevgilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alismistim', 'alismistim-tugba-simsek-6hj63', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oyle alismistim ki bir tanem

Sabahlari seni yanimda gormeye

Seninle kahvalti yapip cay icmeye

Beraber sohbet edip gulmeye

Oyle alismistim ki bebegim

Senin varligini, kokunu hissetmeye

Her sabah opucugunle uyanmaya

Her gece yatarken sana sarilmaya

Oyle alismistim ki askim

Beni sevdigine ve hep sevecegine

Seninleyim, hep senin olacagim diye

Cunku, mutluydum sevdaliyim diye

2.05.2004  20.40', 'Oyle alismistim ki bir tanem Sabahlari seni yanimda gormeye Seninle kahvalti yapip cay icmeye Beraber sohbet edip gulmeye Oyle alismistim ki...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/alismistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalışalım', 'calisalim-emrah-karakoc-vaso0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel yurdun güzel ferdi

Çalışalım çalışalım

Atmak için gamı derdi

Çalışalım çalışalım

Güzelliğe yol yapalım

Her şeyden bol bol yapalım

Bu ülkeyi gül yapalım 

Çalışalım çalışalım

Büyük önder ATATÜRK''e 

Söz verdi bir koca ülke

Zeval gelmesin bu mülke

Çalışalım çalışalım

Dalgalansın bayrağımız

Daim olsun bayramımız

''Türk Çağı'' olsun çağımız

Çalışalım çalışalım

Çöpçü ol çöpleri topla

Doktor ol hastayı yokla

Bahçevan ol gülü kokla

Çalışalım çalışalım

Vataın ferahı için

Kendinize bir iş seçin

Avare gezmekten geçin

Çalışalım çalışalım

Karakoç der umutluyum

Çalışkan benim ulusum

Şehitler rahat uyusun

Çalışalım çalışalım', 'Güzel yurdun güzel ferdi Çalışalım çalışalım Atmak için gamı derdi Çalışalım çalışalım Güzelliğe yol yapalım Her şeyden bol bol yapalım Bu ü...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/calisalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Unutmayın', 'bizi-unutmayin-celal-topo-v62gl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlahi desenin izi silinmez ruhumuzdan

Çözerken zaman kördüğüm ömrümüzü

Hatırleyıp ta anan olur mu arkamızdan? 

Toprak dudaklarıyla öperken yüzümüzü...

Ahbaplar arasında biz yokuz artık

Solmuştur kırık çerçevelerdeki resmimiz

Zamanın kucağında ne anılar bıraktık

Dostluklarla geçmişti yaşanılan günlerimiz...

Yeni bir hayata başlarken bir başka yerde

Beklemeniz nafile sonsuzdur ayrılığımız

Dinlenirken ölümsüzlüğün gizli derinliğinde

Soluk bir sözcük olmasın dudaklarınızda adımız...

Antalya', 'İlahi desenin izi silinmez ruhumuzdan Çözerken zaman kördüğüm ömrümüzü Hatırleyıp ta anan olur mu arkamızdan?  Toprak dudaklarıyla öperken y...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bizi-unutmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Askim?', 'neden-askim-tugba-simsek-qsnoe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Askim neden biz yanyana gelemiyoruz? 

Neden beraber oturup sohbet edemiyoruz? 

Neden surekli birbirimizden ayriyiz? 

Askim neden sanki biz boyleyiz? 

ASkim neden biz biraraya gelemiyoruz? 

Neden ben kollarinda uyuyamiyorum? 

Neden gogusunde kalbinin sesini dinleyemiyorum? 

Askim neden sanki biz boyleyiz? 

28.05.2004  17.45', 'Askim neden biz yanyana gelemiyoruz?  Neden beraber oturup sohbet edemiyoruz?  Neden surekli birbirimizden ayriyiz?  Askim neden sanki biz b...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neden-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğan Güneş', 'dogan-gunes-emrah-karakoc-ydk1a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bir güneş doğdu 

Bilirim bugün de yakacak

O güneşle benim hasretim doğdu

Bilirim yine ağlatacak

Güneş olmak isterdim

Şu kısacık ömrümde

Seni görmek isterdim

Her gülümseyişimde

Çocuk olmak isterdim

Dağlara çıkmak

Uçurtma uçurmak isterdim

Şimdi yaşadığım her bir gün

Mazi oldu gönlümde anılıyor

Geleceğimde mazi olacak bir gün

Bilmem ki bu kaderim

Beni nereye taşıyor', 'Yine bir güneş doğdu  Bilirim bugün de yakacak O güneşle benim hasretim doğdu Bilirim yine ağlatacak Güneş olmak isterdim Şu kısacık ömrümde...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogan-gunes-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlatırdı', 'aglatirdi-emrah-karakoc-9cwwo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Esen deli rüzgarların 

Dili olsa anlatırdı

Erimeyen ol karların

Dili olsa anlatırdı

Çektiğimiz çileleri

Yediğimiz silleleri

Düştüğümüz şu halleri 

Anlatsalar ağlatırdı

Günün hep düne benziyor

Ruhun mazide geziyor

Her üst bir altı eziyor

Anlatsalar ağlatırdı', 'Esen deli rüzgarların  Dili olsa anlatırdı Erimeyen ol karların Dili olsa anlatırdı Çektiğimiz çileleri Yediğimiz silleleri Düştüğümüz şu ha...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglatirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-huseyin-celik-5m1fu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretle başlarım her doğan güne

Bir özlem tütüyor her dakikamda

İçimde bir acı volkan kaynıyor

Çok acı duyarım her tarafımda.

Ümide yer yok mu benim içimde? 

Bir şimşek çakıyor şu gözlerimde

Nereye giderim gurbet ellerde

Bir özlem tütüyor her dakikamda.

Bu gün neden güller boyun büküyor? 

Musluk şırıltısı ağıt yakıyor

Doğa sarhoş olmuş herkes ağlıyor

Bir özlem tütüyor her zamanımda.

Ben kendimde değilim çok içiyorum

Denizler içinde boğuluyorum

Sevgilim seni çok seviyorum

Bir hasret tütüyor her zamanımda.

Anam babam garip bende böyleyim

Bu acı dertlerimi kime söyleyim

Sevgilim gurbeti sensiz neyleyim

Bir özlem tütüyor her zamanımda.

Tatlı havası var benim köyümün

Tozlu toprak, taşlı garip yolunun

Mevlam acı şu zavallı kulunun,

Bir özlem tütüyor her tarafında.', 'Hasretle başlarım her doğan güne Bir özlem tütüyor her dakikamda İçimde bir acı volkan kaynıyor Çok acı duyarım her tarafımda. Ümide yer yok...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayat-304-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Düştük Biz', 'nasil-dustuk-biz-huseyin-celik-gu4pm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakamam yüzüne artık ayrıldık,

İnanmam sözüne artık dargınız.

Doğru söylesen de güvenmem artık,

Sevgilim bu hale nasıl düştük biz.

Gece karanlıkta hayal görürüm, 

Her geçen gün biraz daha ölürüm,

Yaşarken ölmüşüm bunu bilirim,

Sevgilim bu hale nasıl düştük biz.

Sabah olmaz yaşıyorsun düşlerde,

Bir sitem var şimdi o öpüşlerde,

Durmadın verdiğin tatlı sözlerde,

Sevgilim bu hale nasıl düştük biz.', 'Bakamam yüzüne artık ayrıldık, İnanmam sözüne artık dargınız. Doğru söylesen de güvenmem artık, Sevgilim bu hale nasıl düştük biz. Gece kara...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nasil-dustuk-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklayamadım', 'saklayamadim-huseyin-celik-k2zys', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni mısralarda anlatamadım

Gözlerinde gördüm güzel sevgini.

Ay ışığı düşmüş suyun üstüne

Deryalar içinde saklayamadım.

Karanlık ve sessiz gecelerinde

Hep seni düşündüm ağlayamadım.

Mahpus gecesinde zalim gurbetin

Dertlerini sensiz paylaşamadım.

Sahil kenarında parlayan kumlar

Aşık olanları sevenler anlar.

Bize fırsat vermiyor ki zalimler

Bu işte bir iş var anlayamadım.', 'Seni mısralarda anlatamadım Gözlerinde gördüm güzel sevgini. Ay ışığı düşmüş suyun üstüne Deryalar içinde saklayamadım. Karanlık ve sessiz g...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saklayamadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bosver munis abla', 'bosver-munis-abla-yasar-gurlek-l5ide', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ah  ablacim   kolaymi  hic  bos  vermekcok  zor  saygilarimla   gecmis  olsun  dileklerimle.....

BOSVER

bos  vermek  kolay  olsa

coktan  bos  vermistim

yapma  etme  yasar diye

bana cok  soylemistim

dinlemedi  yasar  beni 

simdi  boyle  yaniyor

asla af etmedim seni

hergun yaram kaniyor

munis ablam hastanmis

bos ver hayat bu diyor

bos verdikde yandik abla

bos vermeyle bitmiyor

sen uzulme  hastasin

hayat boyle geciyor

bos  verelim  dedik ama

felek bizi  seciyor

ah ile vah ile bosa gitti omrumuz

bos verdikde dindimiki  gozumuz

bos laf yedik bos konustuk 

bilinmedi  ozumuz

15-02-2006  munis  ablam  icin  yazdigim  siir   abla  saygilar  sunarin

yasar  gurlek

rotterdam  hollanda

========================================

** YANITLANAN MESAJ ********************

========================================

Gönderen: müniş

Alan: yasargurlekhollanda

Tarih: 15.02.2006 20:07:00

Konu: Boşver

--------------------

Değerli dostlarım gene hepinizi görünce beni yanlız bırakmadığınız için çok mutlu oluyorum, gerçi itiraf edeyim ben sizin  gücünüze yetemiyorum ama beni anladığınızdan eminim,doktorumunda tavsiyesi üzerine daha neşeli şeyler yazmaya   çalışacağım   şimdi oturdum br boş ver dim ama nasıl oldu bilmiyorum ama   boş vermeye kararlıyım yaşamak için  herkese   sevgilerimi gönderiyorum evet sevgiyle kalın.Münevver Şenol', 'ah  ablacim   kolaymi  hic  bos  vermekcok  zor  saygilarimla   gecmis  olsun  dileklerimle..... BOSVER bos  vermek  kolay  olsa coktan  bos...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bosver-munis-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahil Kenarı', 'sahil-kenari-huseyin-celik-y9gmy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çatlak dudağımdan süzülüyor kan

Oturdum sahile gözlerim yaşlı.

Dalmışım dalganın şırıltısına

O sessiz halimde uzunca zaman.

Aktı gözlerimden yaşlar durmadan

Ne günler görmüşüm bende bir zaman

Derinden ah çektim kalmamış derman

Dalmışım orada uzunca zaman.

Elimde sigara oltam denizde 

Bekledim orada hayli yalnızca

Bir balık yanaştı baktı garipçe

Konuştuk onunla hayli bir zaman.

Dalgalar vurdukça sahil boyuna 

Çocuk gibi daldım bende oyuna

Balıklar konuştu koyun koyuna

Bastım taş bağrıma uzun bir zaman.

Uzaktan ninniler ağıt sesleri

Geliyor yanıma o nefesleri

Ay doğarken denizdeki eseri

Seyrettim ben onu hayli bir zaman.

Yanımda kovamda beş altı balık

Duruyor içinde hepsi şımarık

Sahil yargıç oldu bende bir sanık

Yargıladı beni hayli bir zaman,

Mahkum etti beni uzun bir zaman.', 'Çatlak dudağımdan süzülüyor kan Oturdum sahile gözlerim yaşlı. Dalmışım dalganın şırıltısına O sessiz halimde uzunca zaman. Aktı gözlerimden...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sahil-kenari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yorganı', 'askin-yorgani-cemile-duzgun-042n1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ver gülü,bir gülü,her gülü yare

Ayrılık arada diken olmasın

Geliver,buluver bu derde çare

Hasretle gözyaşı döken olmasın…

Kalp kini erisin,nefreti solsun,

Ocaklar huzurla, neşeyle dolsun,

Sevda tarlasında bire bin olsun,

Isırgan tohumu eken olmasın…

Sevgi huzmeleri çavsın filize

Kimseyi çekmesin,kimse dehlize

Aldanmaz basanlar akıllı ize

Ayağına çelme takan olmasın

Gözü kararıp da ani irkilip,

Gönlünde ne varsa bir anda silip,

Bunalıp ölümü kurtuluş bilip,

Hüsran çatısına çıkan olmasın…

Sevgi uzun iştir bir güne sığmaz,

Buharlaşma yoksa, sağanak yağmaz,

Karanlık bitmeden yeni gün doğmaz,

Mazlumun başına çöken olmasın…

Sevgi emek ister,ilmikli halı,

Aşk büyülü akış, kin kara çalı,

Meltemle danstayken güllerin dalı,

Sihirli ahenkten bıkan olmasın…

Sevmeyi bilmeyen bunu böyle bil,

İnsan olamazken,hiç bir şey değil.

Yaratılan için Mevla’ya eğil,

Yakma ki,seni de yakan olmasın…

Sevda güllerinden sun kucak kucak,

Kalbin nuru yüzde görülür ancak

Üşüdükçe sarıl,sarıl sımsıcak,

Aşkın yorganını çeken olmasın…

Hoşgörü deryanın pupa yelkeni

Giderek hız alır,açık dümeni,

Dünya ganimettir; çölü, çimeni

Emeksiz almaya bakan olmasın,...

Cemo’yum uzarım ebedi aşka,

Bu kökten çoğalır dal başka başka

Herkes birbirini sevsin de keşke,

Gaflet dünyasına akan olmasın…', 'Ver gülü,bir gülü,her gülü yare Ayrılık arada diken olmasın Geliver,buluver bu derde çare Hasretle gözyaşı döken olmasın… Kalp kini erisin,n...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/askin-yorgani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir Körfezi', 'i-zmir-korfezi-huseyin-celik-vr5nl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İzmir körfezinde bir rafineri

Dumanları çıkar taki engine.

Bulutlar üstünde var bacaları

Yanaşır oraya büyük bir gemi.

Bembeyaz çatılı büyük ambarlar

Gözükür uzaktan oranın hali

Kimse bir şey demez oradaki işe

Gemi ayrılıyor boşalmış belli.

Teknoloji değil zehir saçıyor

Yanıyor ormanlar kıraç tepeler

Uzaktan geliyor bir tren sesi

Denizde tren var desem kim anlar.

Denizde balık var balıkta besin

Söyleyin onları hangimiz yesin

Zehir yemiş balık onları kusun

Deniz zehir olmuş kimler anlasın.', 'İzmir körfezinde bir rafineri Dumanları çıkar taki engine. Bulutlar üstünde var bacaları Yanaşır oraya büyük bir gemi. Bembeyaz çatılı büyük...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/izmir-korfezi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ormanlar Ve Denizler', 'ormanlar-ve-denizler-huseyin-celik-6chbj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ormana giderim elimde balta

Denize girerim yanımda olta

Çıkar elbet bir gün yollarım sapa

Ciğerler zehirle dolacak bir gün.

Mideler açlıktan yanacak bir gün.

Ağaçlar kesilir orman yok olur

Denizde balıklar kaybolur durur

İnsanlar açlıktan kıyılıp kalır

Ciğerler zehirle dolacak bir gün.

Mideler açlıktan yanacak bir gün.

Herkes kendi çıkarları peşinde 

Kimi iki kimi altı yaşında 

Bu ay değil  iki binin beşinde

Ciğerler zehirle dolacak bir gün.

Mideler açlıktan yanacak bir gün.

Eğer böyle gider kimse durmazsa

Bu gidişe bir dur diyen olmazsa

Bu ilkbahar değil sonraki yaza 

Ciğerler zehirle dolacak bir gün.

Mideler açlıktan yanacak bir gün.', 'Ormana giderim elimde balta Denize girerim yanımda olta Çıkar elbet bir gün yollarım sapa Ciğerler zehirle dolacak bir gün. Mideler açlıktan...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ormanlar-ve-denizler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karalama', 'karalama-nuray-sasihuseyinoglu-c4kqv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elime ne zaman bir kalem alsam,

İffeti yerinde- boş-kâğıt bulsam,

Yazdırır bir mısra bana hislerim.

Heyhât! Yazar yazar çizerim.....

Katledemediğim bir tek mısra yok.

Bu, zavallı şiirimin kaderi.

Bu tecelli göstermekte bir hakikat:

Dünyaya gelip de çizilmeyen yok! ......', 'Elime ne zaman bir kalem alsam, İffeti yerinde- boş-kâğıt bulsam, Yazdırır bir mısra bana hislerim. Heyhât! Yazar yazar çizerim..... Katlede...', ARRAY['Türk Edebiyatı','Şiir','Nuray Şaşihüseyinoğlu']::text[], 8.5, '{"poet":"Nuray Şaşihüseyinoğlu","poet_slug":"nuray-sasihuseyinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karalama-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluşu Özlemek', 'kurtulusu-ozlemek-nuray-sasihuseyinoglu-c8isc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boşlukta gençlik, haykırır, MEDET! ! ! ! ! 

Yurduma kol salmış; kin, öfke, ihanet! 

Zararsız olsa da başlarda niyet,

Neticede yok pek bunda inayet! ! ! 

Sallanıyor yerimiz, sallantıdayız,

Kimbilir ne büyük imtihandayız? 

Eller yağ derdinde, bizler candayız

Kurtar bizi Yâ Rab, bu felaketten! 

Biri çeker cenûba, biri şimâle

Sığmaz bu kadar hizip akla hâyâle...

Acımazsanız kendinize, acıyın istikbâle

İzin verin koşalım: En güzel geleceğe! ....', 'Boşlukta gençlik, haykırır, MEDET! ! ! ! !  Yurduma kol salmış; kin, öfke, ihanet!  Zararsız olsa da başlarda niyet, Neticede yok pek bunda ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Şaşihüseyinoğlu']::text[], 8.5, '{"poet":"Nuray Şaşihüseyinoğlu","poet_slug":"nuray-sasihuseyinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kurtulusu-ozlemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok''a', 'yok-a-nuray-sasihuseyinoglu-zu0q2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gece rüyamda 

Yine sen vardın.

Saçlarına  gül taktım,

Koklamadın mı? 

Sabaha uyandım,

Herşeyde sendin.

Sensizliğe selam verdim,

Sen almadın mı? 

Öğle arasında gizlice çıkıp

Bir yüzük almıştım,ince, gümüşten.

Taktım hayâline,

Saklamadın mı? 

Bir mektup yazmıştım,

Sana içimden.

Sen bana bir cevap 

Yollamadın mı? 

Beni de alırsın 

Diye ummuştum.

Ötelere giderken 

Beklemedin mi?', 'Dün gece rüyamda  Yine sen vardın. Saçlarına  gül taktım, Koklamadın mı?  Sabaha uyandım, Herşeyde sendin. Sensizliğe selam verdim, Sen alma...', ARRAY['Türk Edebiyatı','Şiir','Nuray Şaşihüseyinoğlu']::text[], 8.5, '{"poet":"Nuray Şaşihüseyinoğlu","poet_slug":"nuray-sasihuseyinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yok-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-nuray-sasihuseyinoglu-a396r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hey, Avrupa! 

Sen de amma zor çocukmuşsun ha! ...

Sana ayak uydurmak için

Kendimizi senin bir parçan saymak için,

Biz seni taklîde çalıştıkça

Sen kaçıyorsun uzağa.

Merhamet et hırçın kız,

Kaçmak, kurtulmak için

Biraz fazla değil mi bu hız? 

Müsaade et de adam olalım(!)

Ödediğimiz o kadar bedele,

Kimliğimize, özümüze, tarihimize,

Kültürümüze ettiğimiz ihanete

Değmez mi dersin? ! ! ! 

1991', 'Hey, Avrupa!  Sen de amma zor çocukmuşsun ha! ... Sana ayak uydurmak için Kendimizi senin bir parçan saymak için, Biz seni taklîde çalıştıkç...', ARRAY['Türk Edebiyatı','Şiir','Nuray Şaşihüseyinoğlu']::text[], 8.5, '{"poet":"Nuray Şaşihüseyinoğlu","poet_slug":"nuray-sasihuseyinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bedel-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşle Uyanmak', 'gunesle-uyanmak-nuray-acar-6k0yx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah güneşin avuçlarına uyandım 

Tatlı bir esinti saçlarımı savurdu, gülümsedim. 

Ey sıcak parlak ihtişamlı güneş, 

Selam sana seninle doğan güne de selam 

Güneş beni sevmiş olacak 

Tatlı bir dokunuş gönderdi kalbime 

İçim sıcacık olu verdi birden. 

Anladım sevgim karşılıklı imiş, yüreklendim 

Cesaret kapladı tüm benliğimi. 

Birden bulutlar çıktı, küstüm yaşama 

Bozgunculuk yapmasana sözcüklerimi gölgeleme 

Beyazsın diye kızmıyorum sanıp siyah düşüncelere salmasana 

Üstümde yığınlaşıp beni boğmasana 

Ey güneş söyle şu senin yaramaz buluta 

Bu gün gitsin benden uzaklara 

Keyfim de böylesi yerindeyken 

İnsanoğlu daha el sürmemiş ve olumsuz düşüncelerini salmamışken 

Bulutları çekin güneşin önünden 

Gölge etmesin düşüncelerimize 

İnsan olmak için böylesine çaba düşmüşken gönlümüze.', 'Bir sabah güneşin avuçlarına uyandım  Tatlı bir esinti saçlarımı savurdu, gülümsedim.  Ey sıcak parlak ihtişamlı güneş,  Selam sana seninle ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunesle-uyanmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerin Düşüncesi', 'askerin-dusuncesi-emrah-karakoc-3nmw3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Burdurda kurulan şanlı Tugayın

Kahraman erleri, selam sizlere

Toprağı suladı kanı Ata''nın

Al kanı çiğnetmek haram sizlere

Nice Mehmet geldi Maraş''tan, Van''dan

Vatan sevgisiyle çarpıyor kalpler

Ata''mız kahraman, bizler kahraman

Yerler uğulduyor bizimdir zafer

Yükselsin sancağım, yükselsin bayrak

Dün oldığu gibi, yarında hür''üm

Ölürsen şehitsin, sanma ki toprak

Sağ kalırsam gazi, hürmet görürüm

İman dolu kalpler, hedefimiz bir

Al bayrak altında toplnmışız bak

Kızarsa Mehmet''im alırsa tekbir

Zaferi musallat edecektir hak

Ata''nın çizdiği ilkeler ile

Hedefimiz her an ileri gitmek

Cumhuriyet denen halk düzeniyle

Görevdir bizlere vatana hizmet

Babam Burdur''daydı, bak bende geldim

Yarında inşallah kardeşim gelir

Şehidimin oğlu olamaz yetim

Vatanını seven kol - kanat gerer

Şanlı ugayımın kahraman eri

Ağlamak yakışmaz Türk kadınına

Anne''ye hizmette kalma sen geri

Açılsın cennetin kapısı sana

Sayın Tuğgeneral, Kumandanlarım

Vatanıma helal olsun kanlarım

Emrah Karakoç''um benim canlarım

Hepimiz kardeşiz bayrak altında', 'Burdurda kurulan şanlı Tugayın Kahraman erleri, selam sizlere Toprağı suladı kanı Ata''nın Al kanı çiğnetmek haram sizlere Nice Mehmet geldi ...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/askerin-dusuncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağkamıyorum', 'agkamiyorum-ali-fikri-karadeniz-p9fhn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ayrılık şarkısı söyler gözlerim.

Ben ağlamıyorum, hayır; 

Hayır ağlamıyorum...

Onlar yavaşça süzülüyorlar,

Kalbim eriyor yanaklarımda,

Adın hala dudaklarımda,

Gönlümde dualarım,

Yere düşer, bin parçaya bölünür umutlarım...! 

14 Şubat 2006 Sevgililer günü. (Bir gün değil, uyandığında Sonsuzluğuna yeniden aşık oluyorsan, senin için her gün sevgililer bayramı!)', 'Bir ayrılık şarkısı söyler gözlerim. Ben ağlamıyorum, hayır;  Hayır ağlamıyorum... Onlar yavaşça süzülüyorlar, Kalbim eriyor yanaklarımda, A...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/agkamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleket için', 'memleket-icin-levent-i-skenderoglu-wufgt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıkar artık boynundaki ilmiği

Bu idam sehpası  senin için kurulmadı

İn sehpadan aşağı 

Bu idam  sehpası  alçaklar için  kuruldu

Ölürken  bir basamak için yükselsin  diye

Ve  ham  insanlar  için....

İpek böceği örmedi kozasını

Anam göremedi yiğidini  kızını

Çarıklı  ayaklara düşmedi  soğuk

Yani  ölüm  uzak

Yıkım yok memlekette

Hepimiz memleketiz

Ölmekse  idam sehpasında  değil

Ölüm meydanda bize sorgusuz  sualsiz', 'Çıkar artık boynundaki ilmiği Bu idam sehpası  senin için kurulmadı İn sehpadan aşağı  Bu idam  sehpası  alçaklar için  kuruldu Ölürken  bir...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/memleket-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Hanım ve Biz', 'siir-hanim-ve-biz-nuray-acar-b6ovi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir hanım ve biz aynı sofrada iki dosttuk 

ve aynı sokakta iki komşu 

ve aynı yolda yürüyen yoldaştık biz 

Akşam sisini saldı mı dumanlaşan gökyüzüne 

ve çıkarken nefesimizi tutarak mahallenin yokuşuna 

Şiir hanım ve biz aynı sofrada iki dosttuk 

ve aynı sokakta iki komşu 

ve aynı yolda yürüyen yoldaştık biz 

Sabah kedi köpekten önce kapı önüne bırakılan 

bizim sesimizle başlayan sokak gürültüsüne 

bir bir karışan sütçü simitçi sonrasında eskici nayloncu 

Şiir hanım ve biz aynı sofrada iki dosttuk 

ve aynı sokakta iki komşu 

ve aynı yolda yürüyen yoldaştık biz 

İlk veda geldi bir cumartesi ezanında 

bilmezdim dünyadan göçenin anne ismiyle anıldığını 

ve hiç dili dilime değmemişken sohbetlerimizi yad ettim 

gözlerimizde başlayıp yüreğimizde demini bulan. 

Şiir hanım ve biz aynı sofrada iki dosttuk 

ve aynı sokakta iki komşu 

ve aynı yolda yürüyen yoldaştık biz', 'Şiir hanım ve biz aynı sofrada iki dosttuk  ve aynı sokakta iki komşu  ve aynı yolda yürüyen yoldaştık biz  Akşam sisini saldı mı dumanlaşan...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siir-hanim-ve-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazım Koyuncu ya', 'kazim-koyuncu-ya-aydin-guler-rcc1w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyduk ki engellemişler isminin 

Hopa da bir kültür merkezine verilmesini 

Oysaki; 

Yüreklerine kazımışsa  insanlar seni 

Boşver,

Kover gitsin 

Yel kayadan ne alır? 

Sen ki! ...

Hüznün türkülerini çığırıp 

İçine akıtırken acılarını 

Varsıl ile yoksul 

Ezen ile ezilenin 

Kavgasında hep taraftın. 

Çukurovanın yoksul marabası 

Yatağının hırçın bir çevrecisi 

Munzur da  bir kürt insanı 

Hemşin de   fırtına deresi 

Meksika da  topraksız köylü 

Fellucenin   tutuklusu 

Çernobilin mağduruyken 

Genç yaşında şifresini çözdüğün 

Hayatın kendisi kadar gerçektin. 

Varsın engellesinler adının 

Hopa da bir kültür merkezine verilmesini 

Yüreklerine kazımışsa yurttaşlar seni 

Boşver,

Kover gitsin 

Yel kayadan ne alır? 

İnsanlığın uzunca serüveninde 

Otuzlu yaşlarının izini sürerken 

Yitirip yüreklerimizde  sakladıklarımıza 

Kendinide   zamansız  katıp 

Kavganı ödünç vererek alanlara 

Selviler gibi ayakta ve dimdik 

Hayata dair  ne varsa anlamlar yükleyip 

Muhalif müziğinle tarihe  şerh koyarak 

Göçüp gittin bu  yaşamdan 

Karadenizin özgür  yaylalarına 

Her dilden kardeş türküleriyle 

Horona   durmak  için  uşaklarla 

Tıpkı öteki dostların  gibi 

Sessiz 

Ve de

Sitemsiz....', 'Duyduk ki engellemişler isminin  Hopa da bir kültür merkezine verilmesini  Oysaki;  Yüreklerine kazımışsa  insanlar seni  Boşver, Kover gits...', ARRAY['Türk Edebiyatı','Şiir','Aydın Güler']::text[], 8.5, '{"poet":"Aydın Güler","poet_slug":"aydin-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kazim-koyuncu-ya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yare Mektup', 'yare-mektup-emrah-karakoc-whlri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benden selam olsun gül yüzlü yare

Anlasın anlasın beni anlasın

Her yanımı sardı zalim bir yare

Ağlasın ağlasın bana ağlasın

Mutluluktan yana ümidim bitti

Güldüğüm günlerim eskidi gitti

Kaybettim her şeyi, gençliğim yitti

Bağlasın bağlasın, kara bağlasın

Rabbim''den dileğim mutlu olmandır

İlelebet mesut ve şen kalmandır

Uyutma umudu haydi uyandır

Çağlasın çağlasın sana çağlasın

Her an anmasanda unutma yeter

Gülüm, unutulmak ölümden beter

İnsanoğlu yanar ama zor tüter

Buğlasın buğlasın cana buğlasın

Sevdiğinden gelen bu en son name

Sakın yüz çevirip dudağın eğme

Sonra ayan olur bak yüreğime

Leylasın leylasın tama leylasın', 'Benden selam olsun gül yüzlü yare Anlasın anlasın beni anlasın Her yanımı sardı zalim bir yare Ağlasın ağlasın bana ağlasın Mutluluktan yana...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yare-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görenler bu senin ecelin desinler', 'gorenler-bu-senin-ecelin-desinler-ramazan-kayak-20t1g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sabah her akşam gel geç buradan

Görenler bu seni sevmiş desinler

Saçların yellerde seyran tutsun

Gözlerinden mavi denizler coşsun

Bakışların alev olsun yangın yerinde

Görenler bu seni yakmış desinler

Geçerken güllerini savur dürt yana 

Nerdeysem ulaşsın kokusu bana 

Gelip girmesen de benim dünyama

Sonbahar mevsiminde yapraklar gibi

Sarartıp atsan beni yağmurlara 

Görenler bu senin baharın desinler

Ben seni sevmişim can’ u gönülden

Laf anlamaz gönlüm ne gelir elden

Ne kovulmaktan anlar ne sevgisizlikten 

Dilenci gibi durmaz gelir peşinden 

Al götür pazarlara sat istersen 

Görenler bu senin kölendir desinler 

Peşinden götür gittiğin yerlere 

Düşür beni istersen dilden dillere 

Sör beni kıyısı olmayan denizlere

Sabahı olmayan uzun gecelere 

Götür beni umutların olmadığı yerlere 

Görenler bu senin ecelin desinler', 'Her sabah her akşam gel geç buradan Görenler bu seni sevmiş desinler Saçların yellerde seyran tutsun Gözlerinden mavi denizler coşsun Bakışl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gorenler-bu-senin-ecelin-desinler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşver müniş abla', 'bosver-munis-abla-munevver-senol-x0krk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ah ablacim kolaymi hic bos vermekcok zor saygilarimla gecmis olsun dileklerimle..... 

bos vermek kolay olsa 

coktan bos vermistim 

yapma etme yasar diye 

bana cok soylemistim 

dinlemedi yasar beni 

simdi boyle yaniyor 

asla af etmedim seni 

hergun yaram kaniyor 

munis ablam hastanmis 

bos ver hayat bu diyor 

bos verdikde yandik abla 

bos vermeyle bitmiyor 

sen uzulme hastasin 

hayat boyle geciyor 

bos verelim dedik ama 

felek bizi seciyor 

ah ile vah ile bosa gitti omrumuz 

bos verdikde dindimiki gozumuz 

bos laf yedik bos konustuk 

bilinmedi ozumuz 

15-02-2006 munis ablam icin yazdigim siir abla saygilar sunarin 

yasar gurlek 

rotterdam hollanda', 'ah ablacim kolaymi hic bos vermekcok zor saygilarimla gecmis olsun dileklerimle.....  bos vermek kolay olsa  coktan bos vermistim  yapma etm...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bosver-munis-abla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dem', 'dem-altay-taskin-zmifi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aşkın demine girdim

içemedim

merdivenlerden çıkmayı denedim

beceremedim

aşk horoz şekeriymiş

yaladım

yaladım

bitiremedim...', 'aşkın demine girdim içemedim merdivenlerden çıkmayı denedim beceremedim aşk horoz şekeriymiş yaladım yaladım bitiremedim......', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocukları ve Kent', 'sokak-cocuklari-ve-kent-aydin-guler-pokkz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Modernleşen hayatın sefilliğinde 

Sisler çökerken gecenin üzerine 

Sığındıkları kuytu köşelerde 

Nutku dahi kesilir sözlerin, 

Sadece çocukluklarının karabasanları değildir 

Acımasızca yüklenen üzerlerine,üzerlerine.

Hep küçük ayrıntılar gibi 

Bir türlü varlıklarında yoğunlaşılamayan 

Her an görülüp ama hiç fark edilemeyen 

Açlık,soğuk ve suistimallerle 

Bedenleri sürekli bir diken ürpertisindedir. 

Yarı aralık düş pencerelerinden 

Gizli dünyalarına açılan 

Küçücük yüreklerine sığdırmaya çalıştıkları 

Hiç durmaksızın akıp giden zamana carpan 

Sıcacık bir somun ekmeğinin hayalidir. 

Oysaki! ... 

Öteki yakasında kentin, 

Güce tapan kültürleriyle 

Ve maskelenmiş yüzleriyle haramiler,

Çöpten ve kumdan kalelerinde 

Keşfine çıkarlar yeni tutkuların. 

Soğuk ayaza keserken 

Çalınmış masum yaşamlarının 

Ağır sorguları altındadır bellekleri 

Ötekisi olmanın bilinciyle 

Zamanın yumuşak karnıdır artık öfke 

Tutuşturduğunda saçlarından geceyi isyan 

Gün olur elbet, 

Sancısını çeker şehir...', 'Modernleşen hayatın sefilliğinde  Sisler çökerken gecenin üzerine  Sığındıkları kuytu köşelerde  Nutku dahi kesilir sözlerin,  Sadece çocukl...', ARRAY['Türk Edebiyatı','Şiir','Aydın Güler']::text[], 8.5, '{"poet":"Aydın Güler","poet_slug":"aydin-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sokak-cocuklari-ve-kent-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyabildin mi?', 'duyabildin-mi-ali-fikri-karadeniz-x2mtw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay ışığında gözlerin düşüyor sulara,

Dalgalarda yakamoz uçlu saçların,

Seni getirir bana; 

Halbuki Sen, Sen çok uzaklarda...

Benimse gözlerime yıldızlar düşer,

Sonra tek tek kayarlar yanağımdan,

Kalbimin kıyılarını hırçın bir sevda döver,

Ve gönül rıhtımında rüzgara seslenirim,

''Seni çok seviyorum Birtanem''

Duyabildin mi? ... bilmiyorum! ! ! 

14 Şubat 2006 Sevgililer Günü', 'Ay ışığında gözlerin düşüyor sulara, Dalgalarda yakamoz uçlu saçların, Seni getirir bana;  Halbuki Sen, Sen çok uzaklarda... Benimse gözleri...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/duyabildin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anama Mektup', 'anama-mektup-emrah-karakoc-mxdb2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzaklara gitti unuttu deme

Nasıl unuturum sizleri Anam? 

Göz yaşım sel oldu coşuyor gene

Nasıl kuruturum ben sensiz Anam? 

Hayalin bir zaman gözümden gitmez

Günden güne artar hasretin bitmez

Yağınan bal yesem kömbeni* tutmaz

Hasret kaldım senin aşına Anam

Bilirim rüyanda görürsün beni

Eminim bu canım candan ileri

Bana zindan olan gurbet elleri

Ben ordayım diye seversin Anam

Ne güzel hayaller kurmuştum yazık

Ben neyleyim Anam bu düzen bozuk

Eski günler bana oluyor azık

Yad et o günleri an beni Anam

Gurbette geceler bir başka olur

Gözlerine avuç avuç yaş dolar

EMRAH''ın her geçen günde soluyor

Sen beni açılan gül bil can Anam

              *Kömbe: Ekinözü yöresine özgü bir çeşit ekmek', 'Uzaklara gitti unuttu deme Nasıl unuturum sizleri Anam?  Göz yaşım sel oldu coşuyor gene Nasıl kuruturum ben sensiz Anam?  Hayalin bir zaman...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anama-mektup-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark', 'fark-altay-taskin-rslmi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sırma saçlarına toka olayım

yanaklarına zamk

düşlerine mandal takayım

avucuna kamp

gözlerin buzlu deniz

sevgime darp

ayaklarım yoruldu

düzlükler sarp

adını unuttum

suratıma çarp

uyandım artık

ama sana attım fark...', 'sırma saçlarına toka olayım yanaklarına zamk düşlerine mandal takayım avucuna kamp gözlerin buzlu deniz sevgime darp ayaklarım yoruldu düzlü...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fark-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz Boşaldı Gözlerinden', 'akdeniz-bosaldi-gozlerinden-atilla-guler-i17m5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dikmiş kaşlarını geceye kedi

sesi çıkmaz

pusuda

köpekler yine uluorta seranatlarda yıldızlara

bihaber aşıkların geceyle dansından

aşina herkes sarhoş naralarına

ana-baba günü sokaklar

yalpalıyor hayat

sokağa atmış kendini

bir orada

bir burada

iyi geceler olacak son sözler

savunmasız uykulara yelken açarken

sonra günaydın eklenecek güneşin oklarına

araba klaksonları tırmalayacak kulakları

martı sesleri iyot kokularına karışıp

şarkılara eşlik ederken

onca hay huy arasında

ama şimdi

bir kadeh rakı zamanı

bir avuç leblebi

beyaz peyniri masadan kedi çaldı

bu yüzden bir köşeye sinmesi

Hamiyet abla ses verecek yine eskilerden

bir özgecan olacak Leyla birileri için

hal hatır sormadan çekip gitmişti gündüz

akşamın hüznü ondan

Akdeniz boşaldı gözlerinden

ardından

sevda ağlamadı...', 'dikmiş kaşlarını geceye kedi sesi çıkmaz pusuda köpekler yine uluorta seranatlarda yıldızlara bihaber aşıkların geceyle dansından aşina herk...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/akdeniz-bosaldi-gozlerinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vururum seni', 'vururum-seni-hanifi-isikoglu-zbz21', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'senin için  dağları aşarım

senin için deniz umman olurum

yar etmem yad ellere Dünyı yı yıkarım

gidersen yaşatmam vururum seni

seninle yazılmış benim kaderim

seninle tüm dertlere boyun eğerim

bırakmam usanmadan seni severim

sana bakan kem gözden korurum seni

seninle var oldum seninle ölürüm

seni unutmam ömür boyu severim

baş koydum yoluna gerekirse ölürüm

mahşerde de olsa bulurum seni', 'senin için  dağları aşarım senin için deniz umman olurum yar etmem yad ellere Dünyı yı yıkarım gidersen yaşatmam vururum seni seninle yazılm...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vururum-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Grizuda Maden İşçilerine', 'grizuda-maden-i-scilerine-aydin-guler-v932w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıradışı düşlerini; 

Üst üste biriktirerek sevdalanmıştılar kavgalarına,

Bulutlar sıkışık gökler dahi sıkıntılıydı 

Bıçak yarası sancılarına durmuşcasına 

Herşey yanlızlığı çağrıştırmaktaydı.

Vakitlerden  geceydi; 

Sıcak ve sağnak yağmaktaydı yağmur

Kokusuz renksiz   ve de  sinsice gelen 

Felaketin adı grizuydu.

İnsanlar; 

Umutsuzca kaçışmaktaydı köşe bucak 

Tekmil sırların dahi hesabının yapıldığı 

Her birşeyin ve herşeyin cirit attığı 

Sessiz çığlıkların, 

Uğultusuydu beyinlerini yemekte olan 

Devrilmek üzereyken gece üzerlerine 

Şaşkın karanlığın,sıcak koynunda 

Ağıtları türküleşirdi yüreklerinde 

Düşleri,sevdaları olurdu.

Ve onlar; 

Her biri ve her daim,ayrı ayrı 

Ateş,su ve çelik olur idiler 

Aydınlığa soyunmuş 

Sevdalara omuz veren...', 'Sıradışı düşlerini;  Üst üste biriktirerek sevdalanmıştılar kavgalarına, Bulutlar sıkışık gökler dahi sıkıntılıydı  Bıçak yarası sancılarına...', ARRAY['Türk Edebiyatı','Şiir','Aydın Güler']::text[], 8.5, '{"poet":"Aydın Güler","poet_slug":"aydin-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/grizuda-maden-iscilerine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darılma Dost', 'darilma-dost-emrah-karakoc-9py8e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ararım diye söz verdim 

Akşama dostum, akşama

Var geçerli nedenlerim

Sakın ha bana darılma

Unutmadım o sözümü

Çok özledim gül yüzünü

Görmeyim üzüldüğünü

Sakın ha dostum, sakın ha

Sen gül olsan bende bülbül

Konardım dalına her gün

Dünyadaki en güzel gün

Yanında dostum, yanında

Sakın darılma bana can

Yoluna fedadır bu can

Sen bu canda olmuşsun can

İnan can dostum inan ha

İnanmazsan mahvolurum

Sensiz hergün kahrolurum

Gidersen kalmaz gururum

Billahi dostum, bil aha

Bu sözlere inanmazsan

Beni yalancı sanarsan

Kalbinle beni kınarsan

Sor ALLAH''a sor ALLAH''a

Sensin bana hayat veren

Sensin bana gülü deren

Sensin rüyalara gelen

İnan can dostum Emrah''a', 'Ararım diye söz verdim  Akşama dostum, akşama Var geçerli nedenlerim Sakın ha bana darılma Unutmadım o sözümü Çok özledim gül yüzünü Görmeyi...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/darilma-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ölme', 'sen-olme-huseyin-sonmez-mx5ee', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum yavrum bugün,

Yine uykusuz sabahlayacaksın,

Benim gibi sende ağlayacaksın,

Kaybettiğin her şey için,

Bir somun ekmeğe,bir yudum suya,

Hasret kalarak,

Derin acılara korkulara

Kapılarak.

Sesini duyacak mı caniler? 

Nerede insanlık,nerede faniler? 

Bombaları atmayacaklar mı

Üstüne? 

Hayır yavrum,

Yine atacaklar! 

Senin yüreğine,

Yine bombalar düşecek,

Ülkene düşmanlar üşüşecek,

Her karış toprağını,

Haramiler bölüşecek,

Elinde bir gücün yok.

Tek gücün minik yüreğin,

Ne olur sen ölme,

Senin yerine,

Ben öleyim!', 'Biliyorum yavrum bugün, Yine uykusuz sabahlayacaksın, Benim gibi sende ağlayacaksın, Kaybettiğin her şey için, Bir somun ekmeğe,bir yudum su...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-olme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR BAŞKA DİLDeN 1', 'bi-r-baska-di-lden-1-levent-i-skenderoglu-f9z6f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varlığım nolaki bugünden gayrı

Elbet buluşuruz sağ yada sayrı

Gün geçermi can sen benden ayrı

Levent durmaz böyle savrulur gider', 'Varlığım nolaki bugünden gayrı Elbet buluşuruz sağ yada sayrı Gün geçermi can sen benden ayrı Levent durmaz böyle savrulur gider...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-baska-dilden-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR BAŞKA DİLDeN 2', 'bi-r-baska-di-lden-2-levent-i-skenderoglu-vyc8i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Var eden rabbim duysun sesimi

Koymasın içimde yar hevesimi

Daha kesilmedi işin kesimi

Yar mehtaba dura ben yara duram', 'Var eden rabbim duysun sesimi Koymasın içimde yar hevesimi Daha kesilmedi işin kesimi Yar mehtaba dura ben yara duram...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-baska-dilden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Durma Dünya ya Aç Gözlerini', 'haydi-durma-dunya-ya-ac-gozlerini-umut-gungor-k139n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Haydi durma dünya ya aç gözlerini,

Esip giden rüzgara saç sözlerini,

Sana uzanan sevgiye aç ellerini,

Geliyorum gülüm haberin olsun.

Dur bırakma daha gözyaşlarını,

Ne olur yıkma hilal kaşlarını.

Bırakma rüzgara gür saçlarını,

Geliyorum canım haberin olsun.

Kavurdun hasreti bugüne dek,

Pek zor olmuş sana anlıyorum pek,

Savur artık hasreti toprağa ek,

Geliyorum gülüm haberin olsun.

Katlandın sancılanırken yüreğin,

Yıkılmadı hayata karşı bileğin,

Müjde sana kabul oldu dileğin,

Geliyorum canım haberin olsun.', 'Haydi durma dünya ya aç gözlerini, Esip giden rüzgara saç sözlerini, Sana uzanan sevgiye aç ellerini, Geliyorum gülüm haberin olsun. Dur bır...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haydi-durma-dunya-ya-ac-gozlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR BAŞKA DİLDeN 3', 'bi-r-baska-di-lden-3-levent-i-skenderoglu-femop', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece vaktinde kederle doldum

Dediğin oldu Allah tan buldum

Babam şairmiydi ben şair oldum

Umudum kesile şaşıram şaşam 

Hak vaki getire toprağa düşem', 'Bu gece vaktinde kederle doldum Dediğin oldu Allah tan buldum Babam şairmiydi ben şair oldum Umudum kesile şaşıram şaşam  Hak vaki getire to...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-baska-dilden-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın İçinden', 'hayatin-i-cinden-aydin-guler-57v1c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlık çöktüğünde, 

Karanlığın uykusundadır  Ay. 

Uzunca solukladığımız ömrümüzde 

Derleyip,bir türlü adlarını koyamadığımız 

Gün boyu yazılarda hırsızlamacasına 

Aykırı firari düşlerimizdi 

Dolu dizgin koşturduğumuz. 

Ayazlarında gecelerin; 

Bir tek gizemin bilinmezliğini tetikleyen 

Yaşama dair kaygılarımız değildi, 

Sadece akları ve karaları değil 

Başka tonlarınıda görmeye çalışırdık renklerin.

Bazen; 

Tüm tonlarında hissederdik ihaneti içimizde 

Bütün kavramlar birbirine karışırdı,

Hiç te  hazır olmadığımız anlarda

Düşerdik te karanlığın puslu koynuna  aniden

Kuramadığımız hayallerimizin yanıbaşı gurbet 

Her bir şey  bize dert olurdu.

İstemeden yitirdiğimiz sevdalarımızla birlikte 

Kendimizce, 

Yarınlara taşımak gibi bir derdimizde vardı hayatı.

Acılar olmazsa büyüyemezdik belkide 

Belkide hiç! ... 

İlkbaharı muştulayamazdı bile cemre 

Direnci olmasaydı, 

Gelecek  güzel  günlere   dair...', 'Yalnızlık çöktüğünde,  Karanlığın uykusundadır  Ay.  Uzunca solukladığımız ömrümüzde  Derleyip,bir türlü adlarını koyamadığımız  Gün boyu ya...', ARRAY['Türk Edebiyatı','Şiir','Aydın Güler']::text[], 8.5, '{"poet":"Aydın Güler","poet_slug":"aydin-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayatin-icinden-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durdurun Dünyayı', 'durdurun-dunyayi-huseyin-sonmez-pfmdz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir hain saldırı insanlar ölüyor.

Diri diri yanıyor eriyor,sönüyor.

Yalan dünya haince dönüyor.

Durdurun dünyayı ben de ineceğim.

Nice umutlarla gelmiştim buraya,

Değer mi insan ömrü üç kuruş paraya? 

Girmesin zalimler sevdiklerimle araya,

Durdurun dünyayı ben de ineceğim.', 'Bir hain saldırı insanlar ölüyor. Diri diri yanıyor eriyor,sönüyor. Yalan dünya haince dönüyor. Durdurun dünyayı ben de ineceğim. Nice umutl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/durdurun-dunyayi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seveceksen, Böyle Sev..', 'seveceksen-boyle-sev-selma-sengoren-q1qhq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağları mesken eyle

Toprağınla sev gülünü

Yağmurların damlasına

Güneşine ser ömrünü

Merhameti aşk eyle

Şevkatinle sev beni

Yaprakların gölgesinde

Yeşilinle sev gözlerimi

Cesareti koy yüreğine

Mertliğinle nara eyle,

Gözyaşlarıma sitem etme

Sözlerini baldan eyle

Şıvgın akşamların gölgesinde

Çağlasın aşkın nağmelerde

Sen ol ki, bu alemde

Ölümüne sev beni…', 'Dağları mesken eyle Toprağınla sev gülünü Yağmurların damlasına Güneşine ser ömrünü Merhameti aşk eyle Şevkatinle sev beni Yaprakların gölge...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seveceksen-boyle-sev-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasi adına Mr. Buş''a ithaf', 'demokrasi-adina-mr-bus-a-ithaf-mikdat-bal-8iew4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Farkı var mı sorsak Buş’la Saddam’ın 

Farkı olur mu iki deli adamın 

Celladı oldular bir çok idamın

hem celladıydılar mağduru hemin 

Hani insan hakkı özgürlük bir de 

Cenevre Yasası acaba nerde

Buş’un çizmesiyle ezilir yerde 

Ülkemiz olmasın bunlara zemin

Utanma iğrenme duygunuz yoktur 

İnsanlığa sizin saygınız yoktur 

Aşağıladınız kaygınız yoktur

Abu Gareb’de kan akmıştı demin 

İki yüzlülüktür tüm yaptığınız 

Paradan ibaret tek taptığınız 

İnsanlıktır sizin hep kaptığınız

Demokrat Irak’ta söz hakkı kimin

Askerlerin neler etmiş Irak’ta 

Iraklılar karar versin bırak da

Katledip durdunuz çölde çorakta 

İnlettiniz halkı hep inim inim 

Buş utanmaz mısın, kendi halinden 

Demokrasi düşmez idi dilinden 

İpin ucu artık çıktı elinden 

Basra Körfezi’nde batıyor gemin

Sana da aynısı olsa ne olur 

Eden ettiğini bulsa ne olur 

Başınız belada kalsa ne olur 

Sonu berbat olur zalimin kemin 

Demokrasi deyip nasıl kandırdın 

Cahil Iraklıya öyle sandırdın 

Saddamları rahmet ile andırdın 

Herkes intikama ediyor yemin

Irak’ın freyadı dünyayı sardı 

Saddam’la iktidar kavgan mı vardı? 

Kıskançlıktan size bu dünya dardı 

Kurusun ellerin kalmasın nemin 

Bir gün ettiğini bulacaksın sen 

Resimlere bakıp bileceksin sen 

Abu Gareb de de kalacaksın sen 

Yıkılır saltanat yok olur cemin

Mikdatî der sende insanlık kayıp 

Hayvan derdim sana hayvana ayıp 

Esfelin esfeli daha acayip 

Firavun’la dahi sizlerden emin', 'Farkı var mı sorsak Buş’la Saddam’ın  Farkı olur mu iki deli adamın  Celladı oldular bir çok idamın hem celladıydılar mağduru hemin  Hani in...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/demokrasi-adina-mr-bus-a-ithaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağdat Yanıyor', 'bagdat-yaniyor-huseyin-sonmez-gl17w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Medeniyet diyarı Bağdat yanıyor,

Sirenler hiç durmadan,acımasızca çalıyor.

Geriye açlık, zulüm,ölüm kalıyor.

Medeniyet diyarı Bağdat yanıyor.

Yağıyor üstüne tonlarca bombalar,

Yakıyor her tarafı,zalim zorbalar,

Kalmamış ne yiyecek,ne giyecek urbalar,

Medeniyet diyarı Bağdat yanıyor.

Alevler yükseliyor,gökyüzüne,

Dünya seyirci; bakmıyor Bağdat''ın gözüne,

Güvenilir mi üç haraminin sözüne,

Medeniyet diyarı bağdat yanıyor.

Ana gibi yar Bağdat gibi diyar olmaz dediler,

Üstüne şiirler yazıp,türküler söylediler,

Osmanlı''dan sonra inim inim inlediler,

Medeniyet diyarı bağdat yanıyor.', 'Medeniyet diyarı Bağdat yanıyor, Sirenler hiç durmadan,acımasızca çalıyor. Geriye açlık, zulüm,ölüm kalıyor. Medeniyet diyarı Bağdat yanıyor...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bagdat-yaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepimiz kardeş birdik hep bir olacağız', 'hepimiz-kardes-birdik-hep-bir-olacagiz-halil-colak-ad078', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek millettir Türkü,kürdü,Arabi,Laz’ım

Hepimiz kardeş birdik hep bir olacağız

Diyarbakırlısından al Kahramanmaraşlısı

Hepimiz kardeş birdik hep bir olacağız

Erzurum’dan al git kardeş Kars’lısına

Hepimiz kardeş birdik hep bir olacağız

Trabzon undan uzan git Mersinlisine

 Hepimiz kardeş birdik hep bir olacağız

Antalya’sından Zonguldaklısına 

Hepimiz kardeş birdik hep bir olacağız

Orta ana dolusundan güneylisine

Hepimiz kardeş birdik hep bir olacağız

Karadeniz bölgesinden Akdenizlisine

Egelisinden başlayıp Marmaralısına

Trakya’nın Edirne’sinden doğunun Van’ına 

Hepimiz kardeş birdik hep bir olacağız

Avrupalı kendini bilmez itler bunu iyi bilsinler

Canavar haçlı zihniyeti devletler kendine gelsinler

Müslüman ülkeler kendine gelsin birlik olsunlar

Hepimiz de kardaş birdik hep birlikte olacağız

Halil Çolak 15.2.2006 Ankara', 'Tek millettir Türkü,kürdü,Arabi,Laz’ım Hepimiz kardeş birdik hep bir olacağız Diyarbakırlısından al Kahramanmaraşlısı Hepimiz kardeş birdik ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hepimiz-kardes-birdik-hep-bir-olacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-bekir-mutlu-gokcesu-dth0n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırmızı pabuçlar aldım sana

Biliyorum uymayacak ayaklarına

Olsun, aldım işte, istedim, öylesine

Bir çift top da kırmızı toka, saçlarına

Dayanamadım ısırdım tekini

Dişimin izi, başka bir şey değil yani

Sonra oturup öyle düşledim seni

O kadar masum ve güzeldin ki...

Ohhh unuttum ihtirası, uyuttum aşkı

Ruhuma huzurdun, yüreğimde mutluluk

Ne olur daha fazla büyümeyelim çocuk...

14/02/2006', 'Kırmızı pabuçlar aldım sana Biliyorum uymayacak ayaklarına Olsun, aldım işte, istedim, öylesine Bir çift top da kırmızı toka, saçlarına Daya...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuk-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Gerçeği', 'olum-gercegi-seyfet-bozcali-shqob', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstersen az yaşa isterisen çok,

Bu Dünya''ya bir kazıkta gel sen çak,

Doğru yaşa, iyilik yap sonu yok,

Önüne çıkacak ölüm gerçeği.

Ölüm bir gerçektir uzaklaş şerden,

Bir gün ayrılırsın,yardan diyardan,

Musalla taşına,düşersin birden,

İşte seni buldu ölüm gerçeği.

Seyfet der Azrail canın alıyor,

Nefes tükeniyor,Hakka yürüyor,

Bir metre karelik yere giriyor,

İşte kabre koydu ölüm gerçeği...

14.02.2006', 'İstersen az yaşa isterisen çok, Bu Dünya''ya bir kazıkta gel sen çak, Doğru yaşa, iyilik yap sonu yok, Önüne çıkacak ölüm gerçeği. Ölüm bir g...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-gercegi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-alper-yilmaz-sq4tp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ol mah durur karşımda arz-ı endam ederek

Nuru vurur pûr suya aks u raks ederek

Misba oldu ab-ı arz senin ışığından

Ab bile ah ü zar aşkından el aman ederek

Çoştu ol bîrenk dalgalandı heyecan ile

Dedi ki mahv u mest oldum imdat ederek

Dedim ki aynı haldeyim ey ruh-i vücud

Dememle işbu sözü duruldu indi selam ederek

Ne mah imişsin ey aşık-ı subh maşuk-i gece

Şu huy-i halimi çoşturdun seyrettim hayret ederek

Yalnız ol ab değildi aşk ile çoşan

Nur-i cemal-i mah çarptı beni herc ü merc ederek

Fikrî efkarlandı ol müthiş akisinden

Yansa ne olur ki bu dem susmalı tahammül ederek', 'Ol mah durur karşımda arz-ı endam ederek Nuru vurur pûr suya aks u raks ederek Misba oldu ab-ı arz senin ışığından Ab bile ah ü zar aşkından...', ARRAY['Türk Edebiyatı','Şiir','Alper Yılmaz']::text[], 8.5, '{"poet":"Alper Yılmaz","poet_slug":"alper-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gazel-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün', 'dogum-gunun-kazim-uzun-rif93', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karlı ve soğuk bir gündü,

Hayatımın en nadide

Çiçeklerinden biri

Kardelen gibi başını uzattığında

Hayata…

Yine senden uzakta,

Yine senden ayrı…

Pastanı keserken,

Kötülükleri hayatından uzaklaştırırcasına

Mumları söndürmek için

Tek nefesinle…

Yine senden ayrı,

Yine karlı ve soğuk bir hava

Ve hayatımın mecburi

Vaz geçilmezi,

Ama ıtır kokulu yari ANKARA…

Doğum günün kutlu olsun,

Varlığından gurur duyduğum

PRENSESİM…

Bilirim, yalnız değilsin

Neşe katıyordur şimdi

Kuzucum güzel danslarıyla sana…

Sabah kahvaltısının

Keyifli kızartılmış patatesinin

Lezzetli tadında gülümsemenizle

Oynarken bu coşkulu güne,

Aksa da gözlerimden

İki damla yaş…

Mutluyum yine de,

Birkaç duble link lik

Ve özlemim fıstıklarımla…

Seni Seviyorum PRENSESİM,

Nice mutlu yıllara…

(Ankara – 15.02.2006 – 22:54)', 'Karlı ve soğuk bir gündü, Hayatımın en nadide Çiçeklerinden biri Kardelen gibi başını uzattığında Hayata… Yine senden uzakta, Yine senden ay...', ARRAY['Türk Edebiyatı','Şiir','Kazım Uzun']::text[], 8.5, '{"poet":"Kazım Uzun","poet_slug":"kazim-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dogum-gunun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Vergisi', 'akil-vergisi-mevlut-yanar-1wjks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onbeşinci Lui''nin

Dalkavuklarından biri

 -Efendim dedi birgün

Bir fikrim var çok yeni

Aklıma bugün geldi

Akıllı olan herkes 

Versin akıl vergisi

Kimse itiraz etmez

Ben akılsızım demez

Kral bıyık altından 

Gülümsemiş ve demiş

 -Mükemmel bir fikir bu

Hemen hazırlık gerek

Git maliyeye söyle

Ama unutmasınlar

Bu vergi çok ağırca

Seni muaf tutsunlar

            Mevlüt Yanar

            04.01.2006      

                  Mevlüt', 'Onbeşinci Lui''nin Dalkavuklarından biri  -Efendim dedi birgün Bir fikrim var çok yeni Aklıma bugün geldi Akıllı olan herkes  Versin akıl ver...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Yanar']::text[], 8.5, '{"poet":"Mevlüt Yanar","poet_slug":"mevlut-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akil-vergisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinsizin Hakkından İmansız Gelir', 'dinsizin-hakkindan-i-mansiz-gelir-seyfet-bozcali-zdyct', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanın kişiye kulluğu bitsin,

Koruma zalimi def olsun gitsin,

Eğer diyorsanız şer devam etsin,

Dinsizin hakkından imansız gelir...

Bırak tütsün garibanın  ocağı,

Savunmasız diye bırak vurmağı,

Baka baka kul hakkını çalmağı,

Dinsizin hakkından imansız gelir...

Bozçalı der bunlar vicdan işidir,

Vicdan kişiliğin temel taşıdır,

Seni zelil eden bu göz yaşıdır,

Dinsizin hakkından imansız gelir...

   14.02.2006', 'İnsanın kişiye kulluğu bitsin, Koruma zalimi def olsun gitsin, Eğer diyorsanız şer devam etsin, Dinsizin hakkından imansız gelir... Bırak tü...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dinsizin-hakkindan-imansiz-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap', 'hesap-hanifi-isikoglu-lgl3l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şarkılarda şiirlerde

bir gün sana varacagım

kan kustugum gecelerde

senden hesap soracağım

çınlayan kulakların

ıslanacak yanakların

kuruyacak dudakların

senden hesap soracağım

göge değen ahlarımla

sabırtaşan yollarımla

zehir olan yıllarımla

senden hesap soracağım

erişemem sanma sana

unutupta anmasına

mazimizin anısına

senden hesap soracağım', 'şarkılarda şiirlerde bir gün sana varacagım kan kustugum gecelerde senden hesap soracağım çınlayan kulakların ıslanacak yanakların kuruyacak...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hesap-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalıklarda...', 'kalabaliklarda-ercan-akbay-5m8q2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin aradığın erkek benim,

    Caddelerde,marketlerde,otobüslerde....

    Benim aradığım kadın da sensin,

    Konserlerde,sinemalarda,tiyatrolarda.

    Ne sen beni görebiliyorsun,

    Ne de ben seni,

    Kalabalıklarda.......

                     15.2.2006', 'Senin aradığın erkek benim,     Caddelerde,marketlerde,otobüslerde....     Benim aradığım kadın da sensin,     Konserlerde,sinemalarda,tiyat...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalabaliklarda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim...', 'giderim-pinar-koc-ixu6b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Giderim……

Şeftali çekirdeklerinin kızıl renginde

İzler bırakarak dönülmeyen hayat yollarına

Kimsesizliğimin en derinlerine

Giderim………

Kimseyi kanatmadan,

Kimsenin yüreğini acıtmadan,

Sorgusuzca,

Merak edilmeden,

Ağlatmadan giderim,

Bilirim……….

Bilirim,

Bir sevdanın buruk  rengini,

Bir acının yüreğimde bıraktığı

Sancı dengini,

Ve bir damla gözyaşının

Tuzlu zevkini 

Severim…….

Ve ben severken bile

Yine merak edilmeden

Kendi yalnızlığıma 

Giderim………...

                                                  15.02.06', 'Giderim…… Şeftali çekirdeklerinin kızıl renginde İzler bırakarak dönülmeyen hayat yollarına Kimsesizliğimin en derinlerine Giderim……… Kimsey...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/giderim-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbik Dayı', 'i-bik-dayi-mevlut-yanar-8pkoh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nüktedan İbik dayı

Bir türlü fırsat bulamaz

Ölüm döşeğinde ki 

Komşusuna varamaz

Komşu kefeni yırtıp

Çıkınca gün yüzüne

Sokakta rastlaşırlar

 -Aşkolsun İbik Dayı

Nerdeyse ölüyordum

Zor kurtardım paçayı

Birgün kapımı açıp

Geçmiş olsun demedin

Doğrusu pek gücendim

Diye sitemler eder

İbik Dayı mahcuptur

 -Fakat der özür diler

Günün birinde tekrar

Yüzyüze gelmemize

Hiç ihtimal vermedim

Dokuz canlılığını

İnanki bilemedim

           Mevlüt Yanar

            02.01.2006', 'Nüktedan İbik dayı Bir türlü fırsat bulamaz Ölüm döşeğinde ki  Komşusuna varamaz Komşu kefeni yırtıp Çıkınca gün yüzüne Sokakta rastlaşırlar...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Yanar']::text[], 8.5, '{"poet":"Mevlüt Yanar","poet_slug":"mevlut-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ibik-dayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Rüyası', 'mutluluk-ruyasi-seyfet-bozcali-7z1c9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya için avunanlar,

Servetiyle övünenler,

Maddiyata güvenenler,

Mutluluğu bulamazki.

Şükür edip yetinmeğen,

Gerçek bir dost edinmeğen,

Çalışıpta didinmeyen,

İnsan mutlu olamaz ki..

Fukarayı görmeyenler,

Zekatını vermeyenler,

Gerçek yolu bulmayanlar,

Mutluluğu bulamaz ki.

Seyfet der insan sevmeli,

Hakkın rizasın almalı,

Tüm gerçekleri görmeli,

Yoksa mutlu olamaz ki...

          15.02.2006', 'Dünya için avunanlar, Servetiyle övünenler, Maddiyata güvenenler, Mutluluğu bulamazki. Şükür edip yetinmeğen, Gerçek bir dost edinmeğen, Çal...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mutluluk-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Yorgun Düştü', 'hasretin-yorgun-dustu-yilmaz-helimergin-um9xe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül panzehir tüter bin bir derdi mey eyler,

Zülüflerin yel olur fîgan türküsü söyler.

Akşam olur gün biter, tan yürür gece yiter

Sis yanar şafak gelir şemssöner bahtım gider.

Alev donar mum titrer zifir biçer gözlerim,

İnat eder zan dolar zikir çeker sözlerim.

Hazana yaprak düşer, semanın başı döner,

Miyâdı buruk kalbi ahu gözler kör eder.

Çekilir bir tek nefes salınır göz yaşları,

Yutulur bir tas kahır boşanır gam yaşları.

Ah yağar eyvah başlar ölür sensiz nefesim,

“Gül yüzlü yarim” olur duyulan en son sesim.

Bir sûfinin feryadı inler dağlar sinemi,

Ahu, kan içer ahdım içten yıkar hanemi.

Güneş yeni can verir esrik, uzak ve durgun

Tadılan ölüm anı olur sanki göz sorgun.

Volkan coşar, köz saçar gönül her yandığında

Kas katı buz kesilir tenin öz sandığında.

Yorgun, bitkin ve ölgün gamlı artık bedenim

Silik, sarhoş ve sisli sensiz gülen kaderim.

Ve şimdi sen gül yüzlüm ister gel ister ahdol,

İster ömrüme mıh çak ister feci ağıt ol.

 	15.02.2006 23:31:00', 'Gönül panzehir tüter bin bir derdi mey eyler, Zülüflerin yel olur fîgan türküsü söyler. Akşam olur gün biter, tan yürür gece yiter Sis yanar...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Helimergin']::text[], 8.5, '{"poet":"Yılmaz Helimergin","poet_slug":"yilmaz-helimergin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hasretin-yorgun-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can kuşum', 'can-kusum-hanifi-isikoglu-91eue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kanatlanıp uçamıyom

hiç bir dala konamıyom

göğüs tüyüm sensin benim 

sen olmazsan uçamıyom

her kuş gibi uçsam bile

havada denge sağlanmıyor

göğüs tüyüm sensin benim

sen olmazsan uçamıyom', 'kanatlanıp uçamıyom hiç bir dala konamıyom göğüs tüyüm sensin benim  sen olmazsan uçamıyom her kuş gibi uçsam bile havada denge sağlanmıyor ...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/can-kusum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Dostlara Müjde', 'eski-dostlara-mujde-isik-german-ersoy-pji4p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski dostlara müjde

Henüz ölmedim

Öldü diyenlerede

Hiç gücenmedim

Onlarda seviyorlardı 

Beni besbelli

Olmayan mezarıma

Getirdikleri

Çiçeklerden belli', 'Eski dostlara müjde Henüz ölmedim Öldü diyenlerede Hiç gücenmedim Onlarda seviyorlardı  Beni besbelli Olmayan mezarıma Getirdikleri Çiçekler...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eski-dostlara-mujde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nahlet olsun size,Nahletler olsun size', 'nahlet-olsun-size-nahletler-olsun-size-halil-colak-ztart', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ulu peygambere dil uzatan deyyuslara

Onun karikatürünü  yapan domuzlara

Gazetelerde ona kötü yazan kahpelere

Nahlet olsun size,Nahletler olsun size

Danimarka’nın insan kılığındaki itlerine

Ona destek haçlı zihniyetli de devletlere

Dinime dil uzatanda dengesiz kafirlere

Nahlet olsun size,Nahletler olsun size

Eblehe ibrettir başına gelen tarihte size

Ebabil kuşlarının taşları sizi getirir dize

Kuranı kerim bunları anlatır da bize 

Nahlet olsun size,Nahletler olsun size

Halil Çolak  15.2.2006 Ankara', 'Ulu peygambere dil uzatan deyyuslara Onun karikatürünü  yapan domuzlara Gazetelerde ona kötü yazan kahpelere Nahlet olsun size,Nahletler ols...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nahlet-olsun-size-nahletler-olsun-size-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akılsız Kafayı Ayaklar Taşır', 'akilsiz-kafayi-ayaklar-tasir-seyfet-bozcali-1okte', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akılsız kafayı ayaklar taşır,

Nereye git derse orya ulaşır,

Hep ezilir,hep horlanır dolaşır,

Akılsız kafayı ayaklar taşır...

Bu kafa çok ayakkabı eskitti,

Buna uydum tüm işlerim ters gitti,

O emretti mecbur o yöne gitti,

Akılsız kafayı ayaklar taşır...

Her yüze güleni dost sandı gitti,

Yanlış karar verip azmı yürüttü,

Asla gidilemez yerlere gitti,

Akılsız kafayı ayaklar taşır...

Bozçalı der böylelerin çok gördüm,

At artık kafayı geri dön dedim,

Karşıkinden bir çok azarlar duydum,

İşte bu kafayı ayaklar taşır...

         15.02.2006', 'Akılsız kafayı ayaklar taşır, Nereye git derse orya ulaşır, Hep ezilir,hep horlanır dolaşır, Akılsız kafayı ayaklar taşır... Bu kafa çok aya...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/akilsiz-kafayi-ayaklar-tasir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Vatanım', 'canim-vatanim-seyfet-bozcali-mmabb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ana kucağından farkın yok senin,

Sana helal gelse bende ölürüm,

Sevdandayım aşkın ile yanarım,

Can içinde cansın, canım vatanım...

Gözlerimi senin bağrında açtım,

Özgürce ovanda,dağında koştum,

Kalkındırmak için gücümle koştum,

Damarımda kansın,canım vatanım...

Tek seni sevmektir benim amacım,

Feda olsun sana takadım gücüm,

Bozçalı der sen olmasan ben hiçim,

Gözlerime fersin,canım vatanım...

            15.02.2006', 'Ana kucağından farkın yok senin, Sana helal gelse bende ölürüm, Sevdandayım aşkın ile yanarım, Can içinde cansın, canım vatanım... Gözlerimi...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canim-vatanim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
