INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşkeler', 'keskeler-birsen-ates-ilsy6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hangi duygu tamamlar ki

eksikliğini aşkın

kısa gelen yaşamda

düş kırıklarını

gönül kapıları

her daim açık mıdır

sonunda keşkeler

asılır boynuma

yılların ağır yükümüdür 

yalnızlığım

15.02.06', 'hangi duygu tamamlar ki eksikliğini aşkın kısa gelen yaşamda düş kırıklarını gönül kapıları her daim açık mıdır sonunda keşkeler asılır boyn...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/keskeler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi Vazgeçilmez Olan?', 'neydi-vazgecilmez-olan-melih-coskun-d9h2x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim mi giderek bulanan

Yoksa kendisi mi dünyanın 

Ayaklarımın ağrısı mı

Yüreğimin bitmek tükenmek bilmeyen sancısı mı? 

Sen miydin kendini ölürcesine sevdiren? 

Yoksa ben miydim ta kendisi sevdanın? 

Düşün, 

Neydi vazgeçilmez olan 

Sevmek mi,

Hayat mı? 

Marifet, ölebilmek mi sevda için

Yoksa sadece onun için yaşayabilmek mi? 

2004', 'Gözlerim mi giderek bulanan Yoksa kendisi mi dünyanın  Ayaklarımın ağrısı mı Yüreğimin bitmek tükenmek bilmeyen sancısı mı?  Sen miydin kend...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neydi-vazgecilmez-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niğetler Önemlidir', 'nigetler-onemlidir-seyfet-bozcali-rqdb6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan nasıl yaşarsa,öğlecede dirilir,

Ameline bakılıp,hesap doğru görülür,

Hoca topluma sorar adam nası bilinir? 

Cenaze namazında niğetler önemlidir...

İmam niyetin eder,cemaat aynen uyar,

Duyarlı olmak gerek,herkes bu hali duyar,

Bir son fazife ile herkes namazın kılar,

Arkasından beslenen niğetler önemlidir...

Hiç kimse gelmemiştir, bu dünyada boş yere,

Toprak olmak yok olmak,yok öğle şey bir kere,

Yeni bir hayat başlar,yok hiç kapı pencere,

O kişiyi anacak niğetler önemlidir...

15.02.2006', 'İnsan nasıl yaşarsa,öğlecede dirilir, Ameline bakılıp,hesap doğru görülür, Hoca topluma sorar adam nası bilinir?  Cenaze namazında niğetler ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nigetler-onemlidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım Bulutlara Emanet', 'umutlarim-bulutlara-emanet-tunahan-ermihan-hgm0u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdayı hazana terk eylemek varmış kaderde

Pes etmek ve dönüp sırtını bir dolu hayale

Kendi kendinin cellâdı olmak

Ve hatta buhran dolu saatlerde 

Bu satırları yazmak varmış kaderde

Sensiz nefes almak imkânsızken

Bunlar sanki olmuşçasına yazmak varmış kaderde

Tutunmuşum bir garip göçmen kuşun kanadına 

Umutlarım bulutlara emanet

Sözlerime soğuk çalınmış

Yüreğimde keskin bir sızı

Yağmurlara tutkun saçlarından göçüyorum bebeğim', 'Sevdayı hazana terk eylemek varmış kaderde Pes etmek ve dönüp sırtını bir dolu hayale Kendi kendinin cellâdı olmak Ve hatta buhran dolu saat...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umutlarim-bulutlara-emanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veri ver', 'veri-ver-reyhan-tataroglu-1bw1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ebede kadar

                                vede 

                                ezelden beridir

                                var - yok

                                herşey varlığına

                                veridir', 'ebede kadar                                 vede                                  ezelden beridir                                 var - yok ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/veri-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Y o k luğum kaç z a m a n...', 'y-o-k-lugum-kac-z-a-m-a-n-zafer-zengin-etnika-pv9es', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

an''ın kemirdiği şeydir beklemek

kopmaları öğrenememiştir kıyamet...

kızma; 

sarılıp öptüğünde

benden geriye 

ne kalıyor ki

haşarı 

çocuk içim şimdi

kızma; 

ödevim vardı

sana çalıştım

tembelliğim tuttu

bitirmiyorum

günler ayırıyorum sana

pazartesi

salı çarşamba

perşembeden sonra cuma

öğreniyorum günleri

işime yaradığında



iki gün tatil gözlerim

müsadenle

bayrağımı çekeceğim

bir sıkıntı yüreğim

görmedim ya

ölebilirim

insan özlerken ölür mü

hep merak ederdim

sevmeye başladım

pazartesileri

tüm günü

hatta gecesini

kızma; 

sarılıp öptüğünde

benden geriye 

ne kalıyor ki

şimdi gideyim

sen gelirsin

bekletmiyeyim

çakılmaktan uyuşmuş her yerim

her yanım bilmecedeyim

kapanmaz gözlerim

dilencinim

19 09 2005

.', '. an''ın kemirdiği şeydir beklemek kopmaları öğrenememiştir kıyamet... kızma;  sarılıp öptüğünde benden geriye  ne kalıyor ki haşarı  çocuk i...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/y-o-k-lugum-kac-z-a-m-a-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Irmak', 'kizil-irmak-dilek-hokkaomeroglu-6hy8a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...Deli gönül hüzün doldu yastadır 

Ateşten vaz geçti külü arıyor 

Lal olmuş dilleri bülbül hastadır 

Köşe bucak gonca gülü arıyor

Kızıl akşamlarda kızıldır yazı kışı

Gömleği umuttan sevdası kızıllıktan yana

At kendini sere serpe kızıllıklara

Kızıl sularda kızıl umutlarını ara

Yıka kara yazgını kızıl ırmakta

Sus bilmesin sevdanı kızıl kor karanlıkta

Bahar güllerinden bir demet 

Bırak sürüklensin aşk''a

Yağmur yağacak kızıl  sabahlarına

Yağdıkça ıslanacak ıslandıkça

Aşık olacak bir sevda...

Bulutlar gizlenecek güller avuçlarında

Resim çiz deseni aşktan yana

Güller ser yollarına...

Kıpırdasa da bir yürek

Titrek ve ürkek.

Tutmayacak ellerinden 

Gözlerinden akacak kızıl damlalar

Sevmek dersen hep içinde kalacak.

EY! 

Kızıl ırmak anıları göm sularına

Açılsa da yeni kapılar

Al anahtarını kızıl sularına

Yitikliğinde umutlara bir gönül verilmez

Yitik umutları al koynuna

Çiçek açabildiğinde

Yürek sevebildiğinde,

Sel ol delice kızıllıkla

Kuytularına sakla geceyi

Koynuna al sevdalıları..

Yıldız yağmurlarında yıka.

Ay şahit aşka

Birde kızıl karanlık sen..

Yürekte yangınlar,

Alev, alev ıslandılar,,

Kızıl ırmak akşamlarında

Ay şahit aşklarına

Birde delice seven yürekleri', '...Deli gönül hüzün doldu yastadır  Ateşten vaz geçti külü arıyor  Lal olmuş dilleri bülbül hastadır  Köşe bucak gonca gülü arıyor Kızıl akş...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kizil-irmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
