INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni hatırla', 'beni-hatirla-hanifi-isikoglu-93aqn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'oturmuş uzun uzun dalan 

her kelimede sevdigini anan 

herşeye küsmüş onun için yaşayan

bir delikanlı görürsen beni hatırla

sigarayı hep tersten yakan

her bakışı bir anlam taşıyan

hep kendi bildigini okuyan

bir delikanlı görürsen beni hatırla', 'oturmuş uzun uzun dalan  her kelimede sevdigini anan  herşeye küsmüş onun için yaşayan bir delikanlı görürsen beni hatırla sigarayı hep ters...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beni-hatirla-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-ufuk-bayraktar-96wpb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yalnızlık

karlı bir dağın

güneşe bakmayan yamacında

gezinmek gibidir.

üşütür

ama hissettirmez

ayrılamazsın

farkına varmadan

o tatlı uykundan uyanmazsın.

yalnızken

sözleri henüz yazılmamış

beste gibisindir.

her ezgiyi duyar

gelirsin  aşka

sonra anlarsın  ses yok

kendi sesinden başka.', 'yalnızlık karlı bir dağın güneşe bakmayan yamacında gezinmek gibidir. üşütür ama hissettirmez ayrılamazsın farkına varmadan o tatlı uykundan...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizlik-340-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam-Babam', 'anam-babam-i-rfan-kaban-gsssq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve yüzü kızardığında okunmuştur diye aklından geçenler

Aklını sevdiğim bilebilseydi ancak çekinmediğinde değişirdi gerçekler

Ve biz,böyle gelmiş böyle gitmesin diye yırtarken kıçımızı

Ne denli ağırımıza giderse gitsin  azdır geliyor,

bu korkaklığın kesmesi hızımızı

Ondan kork,bundan çekin, olama hiçbir zaman asla kendin

biz sıradaki gençliğimizi savmadan daha, 

yaşamak isterken yeni sökmüş bir şafakta

Hadisene, hadiseniz 

Evet,ağırımıza gidiyor; 

korkaklık nöbetini yaşımız kemale erdiğinde bize devretmeniz…

Dünya kurulduğundan bu yana kaç defa değişmiş babam,değişmiş anam

Korkulan kefeni yırttığında, özgürlük galebe çalmış zorunluluğa

Ve insan devinimi yeni boyut sokuşturmuş doğanın yeknesaklığına

Bilseniz,bir bilebilseniz değil; egemenin korkusundan vazgeçebilmeniz 

Yenilmek hiç problem değildi:  Teslim olmamayı becerebilseydiniz 

Ve siz olmadığınızda gelecekteki biz, işte; ne yazık o zaman, biz ümitleşiriz

Ve siz  doğanın çevirim yeknesaklığında öylesiniz, 

yalnızca; bizi dünyaya getirmişsiniz…

Ağır gelir,

tüm küfürlerden ağır gelendir sözün aşağılaması zaman mekan adamını

Adam yerine koymamaktır,boynuzlamaktır

Ne kızıyorsun,canım sen de boynuzlanma, kızarmasın yüzün

Günü idare edişin iyi de, gelecek adına bal gibi yüzsüzsün…

1982', 'Ve yüzü kızardığında okunmuştur diye aklından geçenler Aklını sevdiğim bilebilseydi ancak çekinmediğinde değişirdi gerçekler Ve biz,böyle ge...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kaban']::text[], 8.5, '{"poet":"İrfan Kaban","poet_slug":"i-rfan-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anam-babam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Gücü', 'askin-gucu-mehmet-isikoglu-79zg5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birleşti sevgiler birleşik kapta 

Öyle neşe yoktur rakı şarapta 

Verdi bana tadılacak lezzeti 

Açtı ah çiçeğim gönlü harapta 

Gürül gürül yandı aşkın ocağı 

Yeniden başladı yaşama çağı 

Doğamız büründü pembe bir renge 

Gerdi kollarını hayat kucağı 

Tomurdu açıldı gönül gülleri 

Aydınlandı mutluluğun yolları 

Yürekler birleşti sağlandı denge 

Yasaklar tutamaz artık kolları', 'Birleşti sevgiler birleşik kapta  Öyle neşe yoktur rakı şarapta  Verdi bana tadılacak lezzeti  Açtı ah çiçeğim gönlü harapta  Gürül gürül ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askin-gucu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sevgini Anlat', 'bana-sevgini-anlat-i-rfan-kaban-p1mex', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana sevgini anlat

Söyleminde tek bir çiçek adı olmasın

Bana sevgini anlat

Bir kuş bile şakımasın

Bana sevgini anlat

Yıldızlı geceler süslemesin öykünü

Yıldız da kaymasın

Bana sevgini anlat

Ne ayın şavkı vursun suya

Ne suda ışınları dans etsin güneşin

Ne yeşert ağaçları

Ne soldur yaprakları

Bir damla yağmur düşürmeden çorak toprağa

Bana sevgini anlat

Hiçbir canlı rol üstlenmesin öykünde

Olay tanığı bir şey olmasın

Ve tüm maddeleri doğanın yetersiz kalsın

Bana sevgini anlat

Benden başka anlayan olmasın

Anlatamıyor musun? 

Sende kalsın.', 'Bana sevgini anlat Söyleminde tek bir çiçek adı olmasın Bana sevgini anlat Bir kuş bile şakımasın Bana sevgini anlat Yıldızlı geceler süslem...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kaban']::text[], 8.5, '{"poet":"İrfan Kaban","poet_slug":"i-rfan-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bana-sevgini-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden İnsan', 'yeniden-i-nsan-i-rfan-kaban-xfu8s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayvandan geçtim

Biçim verdim maddeye

Tasarladım

Eşyayı yarattım

Cenneti yaratacaktım daha

Şeytan çıkıp ortaya

Tanrılıktan indirip kul etti beni

Dişim tırnağımda didinirim

Geçim derdi tanrılara yaramaz

Yitip gitti yeteneklerim

kaldı ki sınırları ömrün

yoksulluğun vekaleti çocuğuma kalır

şu şeytanın mülkiyet tarzı

sevgiyi kında tutar

kini çıkarır

maddeyi okşadıkça sanatkar elim

şu mavi gezegende yaşamak için

onu şekilden şekle  sokan bendim

yasalara çalım atan

şartların oluşumunu elinde tutan

o bendim

homo sapiens sapiens

Adem’le Havva da derler

Kısaca insan

şeytan eline geçirmiş üretkenliğimi

incinmiş o görkemli insanlık bilincim

oysa emeğim

yaratmanın doyumuna ulaşmak işimdi benim

üstesinden gelirdim toprağı çevirenin

burası benim

şansına küs diyenin

yenendim yedi iklimin zorluğunu

dize getirendim tüm canlıları

atomu bölendim

atom altı parçacıkları keşfedendim 

şeytanı da yenmek kolaydı

eğer içimizden çıkmasaydı

hani zorunluluğu yenip özgür olmak gibi

hani doğaya uymayıp

onu kendimize uydurduğumuz gibi

yaratmanın incitmeyen inceliği

gelip sosyal hayatımıza değmeli

yoksa

zor bir şey değil tanrı olmak

şu devasa mülkiyet kalelerinin düşeceği yerde

şu mavi gezegende

istedikten sonra 

yaratmanın doyumuna ulaşmayı bir kere...', 'Hayvandan geçtim Biçim verdim maddeye Tasarladım Eşyayı yarattım Cenneti yaratacaktım daha Şeytan çıkıp ortaya Tanrılıktan indirip kul etti ...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kaban']::text[], 8.5, '{"poet":"İrfan Kaban","poet_slug":"i-rfan-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yeniden-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şehir Ki...', 'bir-sehir-ki-murat-kilic-2-735v3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir şehir ki İstanbul.

güzelliği büyür de büyür sinemde.

her şeyine sevgi doluyum,

bir ayrıdır yeri güzel ülkemde.

karşılıksız sevgidir bendeki,

gönlüm bu sevginin ziyade bahtiyarı.

bir günüm gurbette geçse ki; 

gözümde tüter soğuğu,karı,insanları.

her yerinden ab-ı hayat fışkırır.

doyulur mu sana ey kutsal şehir.

her sırrın güzel her güzelin sır.

güzelliğinin aslı vatanlığındır.

aşıktır güzelliğine cümle alem.

sana yazılmış yazılacak her şey az.

sen benim can vatanım,ülkem,

bizi bizden ölüm bile ayıramaz.

sen öyle bir şehirsin ki,

baştan başa toprağında huzur var.

anlatamamanın ötesi sendeki.

dumanın başka tüter çiçeğin başka kokar.

tarih sende vücut bulur.

hayatlar verilmiş bir taşın için.

ben de uğruna öleyim ne olur,

bir yad basmasın toprağına senin.

bir canım var o da sana feda.

toprağında her taş kanımla ıslansın.

bir varım sensin yalan dünyada.

çünkü sen vatansın.', 'bir şehir ki İstanbul. güzelliği büyür de büyür sinemde. her şeyine sevgi doluyum, bir ayrıdır yeri güzel ülkemde. karşılıksız sevgidir bend...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-sehir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün doğmuşum.', 'bugun-dogmusum-veysel-alkan-2o73r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günlerden salıymış saat tam dokuz.

Şubat on altı yerlerde kar buz.

Babamsa bir değil, doğurmuş dokuz.

Otuz sene önce bugün doğmuşum.

Babam tam yirmi dört yaşında imiş.

Anamsa küçükmüş,yaşı on beşmiş.

Dedem ve ninem de torun istemiş. 

Otuz sene önce bugün doğmuşum.

Üç kilo imişim,bembeyaz yüzüm.

Üzüm gibi kara,iriymiş gözüm.

Nineme sorarsan,''babba'' ilk sözüm.

Otuz sene önce bugün doğmuşum.

Dedem,babasının adını vermiş.

Rahmetlinin namı; Hacı Veysel''miş.

Romanya''dan göçüp,buraya gelmiş.

Otuz sene önce bugün doğmuşum.

Ninem bir yıl bana analık yapmış.

Çünkü zavallı anam şifayı kapmış.

Fakirlikten olacak vereme karmış.

Otuz sene önce bugün doğmuşum.

Ağlarsam kolayca,durulmazmışım.

Geceler uyanıp,uyumazmışım.

Anamı canından,bıktırırmışım.

Otuz sene önce bugün doğmuşum.', 'Günlerden salıymış saat tam dokuz. Şubat on altı yerlerde kar buz. Babamsa bir değil, doğurmuş dokuz. Otuz sene önce bugün doğmuşum. Babam t...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bugun-dogmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik serçem', 'minik-sercem-hanifi-isikoglu-gcwqa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'benim minik serçem vardı

başı dertli çağresizdi

kayboldu bir gün aniden

dertli vede kimsesizdi

geldi bana sıgındı

neşeyi sevinci bende buldu

bir gün aniden kayboldu

başı dertli çağresizdi

haber geldi bulunmuş

sol kanadı kırılmış

tek umudu yaşamaktı

minik serçem vurulmuş', 'benim minik serçem vardı başı dertli çağresizdi kayboldu bir gün aniden dertli vede kimsesizdi geldi bana sıgındı neşeyi sevinci bende buldu...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/minik-sercem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devlet baba ana yasa', 'devlet-baba-ana-yasa-i-lhami-arslantas-rk6vn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Devlet babam idi anam da yasa,

Anama düşmedi nedense tasa,

Yandım anam öldüm kan kusa kusa

Sen benim derdime ağlamaz mıydın? 

…………Kanayan yaramı bağlamaz mıydın? 

Beşiz doğurmuştun dördü aç kaldı,

Suç işleyen zevat başa taç kaldı,

Elimde bir kalem bir de uç kaldı,

Sen benim derdime ağlamaz mıydın? 

…………Kanayan yaramı bağlamaz mıydın? 

Siyasetçi halka kafa tutuyor,

Amerika bizi ele  doluyor,

Azgın yerli yaban filler salıyor,

Sen benim derdime ağlamaz mıydın? 

…………Kanayan yaramı bağlamaz mıydın? 

Dedemiz  kanıyla bu güzel yurdu,

Kurtuluş  savaşı vererek kurdu,

Haramiler çete o gün de vardı,

Sen benim derdime ağlamaz mıydın? 

………Kanayan yaramı bağlamaz mıydın? 

Mazlum türküleri yaktı yamanlar,

Kısır  döngülerle geçti zamanlar,

Sömürdü duygudan medet umanlar,

Sen benim derdime ağlamaz mıydın? 

……….Kanayan yaramı bağlamaz mıydın? 

Der İlhami halâ umut var diye,

Dolaşa   dolaşa geldik son köye,

Derdi yazdım anam havaya suya,

Sen benim derdime ağlamaz mıydın? 

………Kanayan yaramı bağlamaz mıydın? 

30  ağustos 1981', 'Devlet babam idi anam da yasa, Anama düşmedi nedense tasa, Yandım anam öldüm kan kusa kusa Sen benim derdime ağlamaz mıydın?  …………Kanayan ya...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/devlet-baba-ana-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse bilmez', 'kimse-bilmez-hanifi-isikoglu-xw64m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'devir öyle olmuşki

ayıp günah kimse bilmez

herkes bir yol tutmuş gider

haksızlıgı kimse bilmez

yetim öksüz gariban mı

herkes tok kimse bilmez

para gözün kör olsun

haksızlıgı kimse bilmez

dünya dedigin ölümlü

parayı gören ölümü bilmez

insanlara acıyorum

haksızlıgı kimse bilmez', 'devir öyle olmuşki ayıp günah kimse bilmez herkes bir yol tutmuş gider haksızlıgı kimse bilmez yetim öksüz gariban mı herkes tok kimse bilme...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimse-bilmez-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Donmeyecek', 'donmeyecek-yasar-gurlek-gciea', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DONMEYECEK

Anladim  bu  dunyada  senden  bana  fayda  yok

Ben  galiba  baska  sevdim, seviyorum  hemde cok

Nerde  benim  canlarim  hani  hic   birisi  yok

Bu  yarali  gonlumun  tukenmez  derdi  cok

Beni  boyle  koyup  gitti  bilirim  hic  donmeyecek

Aciyla  yanan  kalbim  her  gun  seni  inleyecek

Nerdesin  ey  vijdansiz  hic  haber bir  iz  yok

Deli  divane  gonlumun  bitmeyen  derdi  cok

Yasar  gurlek  16-02-2006

Rotterdam    hollanda', 'DONMEYECEK Anladim  bu  dunyada  senden  bana  fayda  yok Ben  galiba  baska  sevdim, seviyorum  hemde cok Nerde  benim  canlarim  hani  hic...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/donmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan söyledin', 'yalan-soyledin-hanifi-isikoglu-udk65', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ela gözlü yarim benim

sevdim seni ne bileyim

sevgin bana haram oldu

bana yalan söyledin

bana yalan söylüyorsun 

sevmek ne bilmiyorsun

günahımı alıyorsun

bana yalan söyledin

gülmeyi unuttum sayende

hergün agladım kalpsiz

gururumu ezdin düşünmedin

bana yalan söyledin', 'ela gözlü yarim benim sevdim seni ne bileyim sevgin bana haram oldu bana yalan söyledin bana yalan söylüyorsun  sevmek ne bilmiyorsun günahı...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalan-soyledin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sondu Atesin', 'sondu-atesin-yasar-gurlek-j33xe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SONDU   ATESIN

Senin  icin  yazdim  bugun  gufteleri

Her  an  turku  olursun  dudaklarimda

Baglamamin  telinde  olur   besteler

Tum  alem   duysun  kalaklarinda

Sen  benim  ilham  perim  yakan  gunesim

Iki  cihandada  bulunmaz  senin bir  esin

Yoklugunda  buz  oldum  sondu  atesin

Nefesinin  sicakligi   var  dudaklarimda

Yasar  gurlek  16-02-2006

Rotterdam    hollanda', 'SONDU   ATESIN Senin  icin  yazdim  bugun  gufteleri Her  an  turku  olursun  dudaklarimda Baglamamin  telinde  olur   besteler Tum  alem   ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sondu-atesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyeretçiniz Var', 'ziyeretciniz-var-serpil-balcik-fykt4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgar eşliğinde deniz süzülüyordu odama,

Buyur ettim.

Sesi dışarıda kalmış

Onu da aldık içeriye.

Kokusu çantasındaymış,

Açıverdi kapağını.

''bu çanta bana dönüş için yetmez

fazla bavulun var mı? '' dedi.

Dedim, düşlerimi götürme mümkünse

Kokun da kalsın! 

''yok'' dedi,

''''onlar senin, gülücüklerini de bırakacağım,

ben kederini almaya geldim.''''

MART 2003', 'Rüzgar eşliğinde deniz süzülüyordu odama, Buyur ettim. Sesi dışarıda kalmış Onu da aldık içeriye. Kokusu çantasındaymış, Açıverdi kapağını. ...', ARRAY['Türk Edebiyatı','Şiir','Serpil Balçık']::text[], 8.5, '{"poet":"Serpil Balçık","poet_slug":"serpil-balcik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ziyeretciniz-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kosalim', 'kosalim-yasar-gurlek-8qwrg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KOSALIM

Ayrilik  yillarini  unutup  anmayalim

Yokluk  atesiyle  bir daha yanmayalim

Eski  yerimizde  yeniden  dolasalim

Mutluluga  sevgiye   gel beraber  kosalim

Yureklerde  yanan  aski  gel  yeniden yakalim

Kara  aci  gunleri  gerilerde   birakalim

Bilirsin  yasarini  gel  yeniden  cosalim

Mutluluga  sevdaya  gel  beraber  kosalim

Yasar  gurlek  16-02-2006

Rotterdam    hollanda', 'KOSALIM Ayrilik  yillarini  unutup  anmayalim Yokluk  atesiyle  bir daha yanmayalim Eski  yerimizde  yeniden  dolasalim Mutluluga  sevgiye  ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kosalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmiyorki Bedeli', 'bitmiyorki-bedeli-yasar-gurlek-3kce2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitmiyorki  bedeli

Haram  oldu  yasamak  inanki  sen  gideli

Yoklugunla  bittim  artik  oldum  divane  deli

Boyle  aska   sevdaya  bilmemki  ne  demeli

Yillardir  oduyorum  bitmiyorki  bedeli

Can  verdim  ben  verdim  kalbimide  goturdun

Yasarken  olu  ettin  beni  bende  bitirdin

Boyle  aska   sevdaya  bilmemki  ne  demeli

Yillardir  oduyorum  bitmiyorki  bedeli

Ah seni  bir  bulsam  gozlerinden  operdim

Inan sana   yillanmis  goz  yasimi  dokerdim

Boyle  aska   sevdaya  bilmemki  ne  demeli

Yillardir  oduyorum  bitmiyorki  bedeli

Yasar  gurlek  16-02-2006

Rotterdam    hollanda', 'Bitmiyorki  bedeli Haram  oldu  yasamak  inanki  sen  gideli Yoklugunla  bittim  artik  oldum  divane  deli Boyle  aska   sevdaya  bilmemki ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bitmiyorki-bedeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum Geliyorum Geliyorum Can', 'geliyorum-geliyorum-geliyorum-can-yasar-gurlek-f1sd0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geliyorum   Geliyorum    Geliyorum  Can

Unutamam  gozlerinin   rengini

Silememki  kalbimden  senin  sevgini

Unutmadim  bir  saniye  olsun  ismini

Geliyorum  geliyorum  geliyorum   can

Yillar  yili hep  boyle,  boyle  yasadim

Eskiden  (yasar,di)  asik  oldu  bak  adim

Hasretinden ne  nesem var nede  vuslatim

Geliyorum  geliyorum  geliyorum   can

Sensiz  bos  kalan kalbimi  doldurmalisin

Yillarca  hic  gulemedim  guldurmelisin

Dondugumu  tum  aleme  bildirmelisin

Geliyorum  geliyorum  geliyorum   can

Bas  koydum  bu  yola  inan  gelecem

Daglari  engelleri  asip  gelecem

Kadrini  kiymetini   nasil  bilecem

Geliyorum  geliyorum  geliyorum   can

Gelince  diz  cokup  elin  opecem

Yillanmis  goz yasimi orda  dokucem

Bizi  boyle  ayiranlarin  kokun sokecem

Geliyorum  geliyorum  geliyorum   can

Yasar  gurlek  16-02-2006

Rotterdam    hollanda', 'Geliyorum   Geliyorum    Geliyorum  Can Unutamam  gozlerinin   rengini Silememki  kalbimden  senin  sevgini Unutmadim  bir  saniye  olsun  i...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/geliyorum-geliyorum-geliyorum-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımın Nuru.', 'hayatimin-nuru-i-shak-ozlu-i8614', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siyah saçların savrulunca yelde,

Yeli kıskanırım değdiği telde.

Tek bir telin düşüp karışsa sele,

Uğruna bırakırım canı selde.

Kömür gözlerin hayatımın nuru,

Akçadır yüzün pınarlardan duru.

Koca gönlüme seslenmek dilersen,

Dilinde gayrı İsrafilin sur''u.

Bir nişan istersen gözlerine bak,

Görürsen beni sevda ateşin yak.

Mıh olup saplandığın yüreğime,

İlaç ol gözlerimden usulca ak.', 'Siyah saçların savrulunca yelde, Yeli kıskanırım değdiği telde. Tek bir telin düşüp karışsa sele, Uğruna bırakırım canı selde. Kömür gözleri...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayatimin-nuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karım', 'karim-esat-erbil-rnuka', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karıcığım

Ellerin elimde iyken ne mutlu

Yaşam... Sürdürdük

Yüzlerce mektup 

Beyaz güverçinler kanadında 

Bana gönderdin.

Şimdi o, mektupleri 

Yalnız tek başıma 

Okuyorum:

((Sen yanmazsan... Ben yanmazsam

    Karanlığı... Kimler boğar?)) .

Ardımızdan gelenleri 

Düşünelim 

Aydın bir gün doğacaktır

Gel dönelim hep beraber 

Eski yaşamımıza

Haydı koş bana 

Geç kalmadan

Neredesin... Bulamıyorum seni

Ayaklarım... ardımca gelemiyor

Arıyorum...

  Bulamıyorum...

Koyma 

    Özlem 

Beni öldürsün

Seni beklemekten!', 'Karıcığım Ellerin elimde iyken ne mutlu Yaşam... Sürdürdük Yüzlerce mektup  Beyaz güverçinler kanadında  Bana gönderdin. Şimdi o, mektupleri...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/karim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nesrinler Diyarından', 'nesrinler-diyarindan-esat-erbil-npx76', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzak yollardan...

Garip diyardan... Selamın aldım

Canlandıran duyğuna...

Gönlünde çizdiğine...

Düşünüp daldım.

Öyle düşündüm... Daldım... 

Uzun bir zaman

Kendim ile tartıştım 

Bir sonuca varmam için 

Ama vardım.. Varamadım...

Bilmiyorum! 

Düşüncelerim içinde 

Bir düşünceye kaldım

Beni sana bağlayan

Turlu... Turlu...

Nesneler vardırmıdır? 

Konuştuğumuz 

Tatlı bali Türkçe 

Dil mi? 

Yoksa... 

Canımızda dolaşan 

İkimizin kanı mı? 

Yada Erbil''in yüksk kalesi

Tanılan Çol minaresi

Gök börünün Diyarı mı? 

Ya eskiden tanılmış 

Garibiler...

Doğramacılar...

Cercislerin

Duyguları mı? 

Evet...

Bunların hepsi bizi 

Bir demir irade ile bağlamış

Tanrının kudretiyle

Daldasında saklamış

Nesrinler Diyarından...

Kucak dolusu sela...

Kocaman Kale''mizden

Sarı beyaz nergizler

Sana armağan 

Yeşil Kulamızdan.', 'Uzak yollardan... Garip diyardan... Selamın aldım Canlandıran duyğuna... Gönlünde çizdiğine... Düşünüp daldım. Öyle düşündüm... Daldım...  U...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/nesrinler-diyarindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Ver Kalbimi', 'geri-ver-kalbimi-esat-erbil-11dcp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalmadı bende 

Hiç bir hatıran

Geri ver benden 

Sağ aldığın 

Kimsesiz kalbimi.

Yokluktan geldim 

Yokluğa gideceğim,

Ama dünyalarce 

Değeri olan 

Dünyamı 

Seninle buluşan anda 

Terredütsiz 

Bedava bağışladım.

Ah keşkem 

Vermeseydim.

Her şeyi 

Güzel göriyordum

Kalbimin 

Sahibi sendin! 

Her şeyi 

Bir anda kayp ettim.

Lütfen 

Sana geldim 

Eli boş dönderme beni

İki gün doğru 

Sevdiğin kalbimi 

Bozulmadan 

Sağ selamet 

Geri dönder.', 'Kalmadı bende  Hiç bir hatıran Geri ver benden  Sağ aldığın  Kimsesiz kalbimi. Yokluktan geldim  Yokluğa gideceğim, Ama dünyalarce  Değeri o...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/geri-ver-kalbimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşırtma Kendini!', 'sasirtma-kendini-esat-erbil-0hohs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne yapmak istiyorsun? 

Bir türlü anlamadım

Sana aşığım 

Sana vurgunum

Sana deliyim

Yeter sende 

Kendin untma 

Bil insan olduğun

Bir azcık 

Merhamet eyle 

Çünkü insansın 

Bu nedenle 

Şaşırtma kendini

Hadini bil.', 'Ne yapmak istiyorsun?  Bir türlü anlamadım Sana aşığım  Sana vurgunum Sana deliyim Yeter sende  Kendin untma  Bil insan olduğun Bir azcık  M...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sasirtma-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim', 'hasretim-esat-erbil-9v2xh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Demiştim 

Sana 

Ayrılırsak 

Buluşacağız

İşte gör 

20 yıl sonra 

tekrar yüz yüze 

Geldik 

Ama durum tam ters

Sen bir başkasıyla 

Bense tek yalnız 

Ağardı saçlarımız 

Senin çocukların 

Ben kimsesiz

Sen değişildin 

Ben iysem 

Hala o, tanıdığınım

Sevgilerimle 

Bekliyorum 

Hasret 

Kaldığım 

Kucaklarına 

Kavuşamadım.', 'Demiştim  Sana  Ayrılırsak  Buluşacağız İşte gör  20 yıl sonra  tekrar yüz yüze  Geldik  Ama durum tam ters Sen bir başkasıyla  Bense tek ya...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hasretim-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra Bu İlk Şiir', 'senden-sonra-bu-i-lk-siir-birol-akbaba-f7km8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlasan da inanman göz yaşlarına

Sen değilmiydin giden, kalbimi kıra kıra

Yalan gözlerindeki renk, yalan bakışın

Sildim seni kalbimden yazmam bir daha

Ha ölmüşüm  ha yaşamış anma adımı bir daha

Şiiri olmuştu ruhumun senden gelen nefesi

Bu senden sonra yazdığım ilk şiir dizisi

Acı gibi görünse de işte yüreğimin sesi

Sildim seni kalbimden yazmam bir daha

Ha ölmüşüm ha yaşamış anma adımı bir daha

Çokmuydu yaşlı kalbimin çocuk neşesi

Gittin de ne oldu  sanki soldu gönül bahçesi

Yazı solgun sözün hükmü yok

Sildim seni kalbimden yazmam bir daha

Ha ölmüşüm  ha yaşamış anma adımı bir daha

Yine güneşi bekliyorum ezan sesleri uzakta

Gözler kapalı, Eller açıldı, ruhlar dua da 

Kış yalnızlığından bahara koşan yollarda

Sildim seni kalbimden yazmam bir daha

Ha ölmüşüm ha yaşamış anma adımı bir daha', 'Ağlasan da inanman göz yaşlarına Sen değilmiydin giden, kalbimi kıra kıra Yalan gözlerindeki renk, yalan bakışın Sildim seni kalbimden yazma...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senden-sonra-bu-ilk-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik-Kötülük', 'i-yilik-kotuluk-ekrem-sama-dphaz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kişinin etrafında görevli melekler,

İnsanın yaptığı amelleri denetler.

Kötülükler, geçici deftere yazılır,

İyilikler, silinmez yere; teker teker...

Kim ki; kötülüğüme pişman oldum, derse,

Tekrar yapmamak için Allah’a söz verse,

Tüm kötü amelleri defterden silinir,

Hangisi Nasuh gibi bir tevbe ederse...

(İstanbul:24.05.2004)', 'Kişinin etrafında görevli melekler, İnsanın yaptığı amelleri denetler. Kötülükler, geçici deftere yazılır, İyilikler, silinmez yere; teker t...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iyilik-kotuluk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık!', 'gel-artik-zulfikar-yapar-kaleli-8pwvp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Özel sevdiğini söyleyen güzel

Çatlamakta sabır taşı gel artık! 

Güz sonu bağlarım dökmede gazel

Alev aldı yürek başı gel artık! 

Yollar ki, yolcuyu menzile itmez

Canımı salarım canana gitmez

Hayatım zemheri güneş kâr etmez

Sel eyledim gözüm yaşı gel artık

Yaylada bacanın tüttüğü kadar

Çobanın kuzuyu güttüğü kadar

Bir busenin mutlu ettiği kadar

Mutlu etmez ekmek aşı gel artık

Dostum can her şeyi bilmiş olmalı 

Bu gün de ağlamış gülmüş olmalı 

Vuslatın zamanı gelmiş olmalı 

Ağarmakta kara kaşı gel artık

Desteksiz atılan sözden değildir.

Bilirim, dediğin özden değildir

Aşkın yürektendir, yüzden değildir

Yıldız gözler artık şaşı gel artık

İnsanlığı diktim yol ortasına 

Herkes öldü diye düşer yasına 

Sen ki, tükürürsün şerbet tasına 

Ben ki, yaşıyorum kışı gel artık', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Özel sevdiğini söyleyen güzel Çatlamakta sabır taşı gel artık!  Güz sonu bağlarım dökmede...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gel-artik-212-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evcil Kedi Kelimelerden', 'evcil-kedi-kelimelerden-i-brahim-ethem-uzun-4ecxb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benden gayri sair ara kendine

Eger melodiyi seviyorsan

Calmiyorum artik darbukami gobek atamazsin

Duygularimin uzerinde

Dusuncelerimin uzerinde

Defterlerimin uzerinde

Dizelerimin icinde

Deniz  gozlerimin onunde

Paylasacagim mutlulugum mevcut degil senle

Yagmur yagiyorken cevremde

Ulkem agliyorken icimde

Ayna agliyorken onumde

Agaclar agliyorken beni gordugunde

Caddeler agliyorken ben yurudugumde

Kalem agliyorken elimde

Elbiseler agliyorken giydigimde

Resimler agliyorken seyrettigimde

Kuslar agliyorken uzerimde

Su agliyorken ictigimde

Ekmek agliyorken yedigimde

Duygularda kalpazanligi sevmem

Yalan soylemeyi asla beceremem

Uzuntusuz bir erkek ara kendine

Dudagindaki uzumleri koparsin

Uzum ekmekten biktim zaten

Yollar da dar geliyor gecerken neden

Baska asik ara kendine

Atesi kalbinde saklayan

Kalbim oldu artik tahtadan

Yorgunum dunyadan

Yorgunum kendimden

Yorgunum senden

Yorgunum sesinden

Yorgunum sesimden

Yorgunum harflerden 

Yorgunum sevgiden 

Yorgunum   Rabbimden

Bana ragbet gosterme

Olsen de gosterme

Bagimsizim artik ben 

Kadinlarla iliskilerden

Surmeli gozlerden

Bagimsizim artik ben

Tum mazimden

Tum mustakbelimden

Bagimsizim artik ben

Tabularimdan 

Torelerimden

Kaderimden

Baska nakkas ara kendine

Ibrahim Ethem gibi

Aski, suya naksedebilen

Diledigi zaman onu silebilen

Elimdeki kalemi kirdim  simdi sevgiden 

Evcil kedi oldum kelimelerden', 'Benden gayri sair ara kendine Eger melodiyi seviyorsan Calmiyorum artik darbukami gobek atamazsin Duygularimin uzerinde Dusuncelerimin uzeri...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Uzun']::text[], 8.5, '{"poet":"İbrahim Ethem Uzun","poet_slug":"i-brahim-ethem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/evcil-kedi-kelimelerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmitasyon Kahraman', 'i-mitasyon-kahraman-ahmet-ferit-cosan-i7ku7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Keyifli kalabalığın

Bez bebeğisin şu an, yazık! 

Vaktinin mor dağlı gerillası

Yabanıl alkışlara şerefini satar

Yalan sözleri daha dudaklarından yakalar

Duvarlarda senin, 

İçki de senin,

İç içebildiğin kadar.

Dün kalın sesinle zulümleri

Bas-i ret etmiştin sen eski aşina,

Garip,

Bugünse daha ilk söküğünden firar etmiş haysiyetin.

Ruh dediğin biçaren, “işe yaramaz bir artık”

Gür, baskın küfürlere bulasan da alemleri, nafile

Kimseler inanmaz ki sersem azizliğine artık.', 'Keyifli kalabalığın Bez bebeğisin şu an, yazık!  Vaktinin mor dağlı gerillası Yabanıl alkışlara şerefini satar Yalan sözleri daha dudakların...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/imitasyon-kahraman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçip İçip Sızmayımda Neyleyim', 'i-cip-i-cip-sizmayimda-neyleyim-murat-demir-ytxy0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana derler neden dertli yazarsın

Satırlarda cümle cümle tozarsın

Uluorta lisanını bozarsın

Bu ortamda bozmayımda neyleyim

Can dediğin helak edip gitmişse

Bir sevda ki başlamadan bitmişse

İçimde ki ateşi kül etmişse

Satırlarda tozmayımda neyleyim

Gül misali yaprak yaprak solunca

Yüreğime gözyaşlarım dolunca

Hele birde gönül onsuz olunca

İnce ince yazmayımda neyleyim

Hasret denen gözlerimde bir kanca

Çivi gibi çakılmışsa o yarca

Acısı ki yakıyorsa hünharca

İçip içip sızmayımda neyleyim

Arıyorsam ebedilik uykuyu

Dizlerimden çekilmeden can suyu

Şuracıkta bir kürekle, bir kuyu

Ben kendime kazmayımda neyleyim', 'Bana derler neden dertli yazarsın Satırlarda cümle cümle tozarsın Uluorta lisanını bozarsın Bu ortamda bozmayımda neyleyim Can dediğin helak...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icip-icip-sizmayimda-neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağ Kalbime', 'yag-kalbime-nuray-acar-lz9ye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağ kalbime bir yağmur sonrası 

Toprak kokusunda 

Düşüncelerime gel 

Doğum yapan bedenin 

Zafer kazanmış yorgun edasında 

Mahcup  etme yeter ki 

Yokluğun öyle acı ki 

Körüm, dilsizim,hissizim 

Ta ki sen gelene dek 

Geldiğinde 

İşte doğdum 

Diyebilmeliyim 

Yakan sıcaklığında 

Erirken', 'Yağ kalbime bir yağmur sonrası  Toprak kokusunda  Düşüncelerime gel  Doğum yapan bedenin  Zafer kazanmış yorgun edasında  Mahcup  etme yeter...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yag-kalbime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkna Odaları', 'i-kna-odalari-omer-ekinci-micingirt-e3j8a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her yağmur damlası eşsiz nizamdır 

Su rüzgâr ateşi bilemezsiniz sen

Örtü İslam''dandır imanım tamdır 

Tespihteki taşı bilemezsiniz sen

Sokakları topla örtüyü bırak 

Namaz yok oruç yok zekâttan ırak 

İrtica hortlatıp çaldın çıngırak 

Hak için sarhoşu bilemezsiniz sen

Gece gündüz yaz kış yazın fişleyin 

Her türlü melânet şeri işleyin 

Elifsiz anlayış ile başlayın 

Zeybeği dadaşı bilemezsiniz sen

Sen papaz mısın nesin kardeşim

Açar kapatırım sana ne başım

Örtsem de açsam da hür vatandaşım

Alındaki beşi bilemezsiniz sen

"İkna odaları"  Ömer ne desin 

Büyükler buyurmuş ve karar kesin

Nerdesin adalet söyle nerdesin 

Bu bitmeyen koşu bilemezsiniz sen', 'Her yağmur damlası eşsiz nizamdır  Su rüzgâr ateşi bilemezsiniz sen Örtü İslam''dandır imanım tamdır  Tespihteki taşı bilemezsiniz sen Sokakl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yazmali-bas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haklısın', 'haklisin-nuray-acar-alxz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'haklı olduğumu anımsatıyor 

gözlerinden dudaklarıma 

akan sözcüklerin 

bir kez daha haklı çıktın 

kahretsin demiyorum 

çünkü haklısın', 'haklı olduğumu anımsatıyor  gözlerinden dudaklarıma  akan sözcüklerin  bir kez daha haklı çıktın  kahretsin demiyorum  çünkü haklısın...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/haklisin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize Düşer Durur Gözlerin', 'denize-duser-durur-gozlerin-huseyin-erdogan-d5xlu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her semaya bakışımda

seni görürüm ışıldayan yıldızlarda

sanki sen olursun gök yüzü

her gece öyle gelir bana

denize düşer durur gözlerin

yıldız yıldız çizilir resmin

dalgaların kıyıya her vuruşunda

yazılır her yere harika sözlerin

kazınır kayalara bütün güzelliğin

yaktıkça yakar beni hasretin

esen rüzgarları kokladıkça

seni çekerim içime doya doya

üstümde Allah var 

ben yalan söyleyemem

vallahi çarpılırım sonra

gece gündüz seni koklasam da

inan ömrümce doyamam sana

bazı gün batımlarında

Bostancı''ya inerim

ben buranın akşamını da 

bil ki çok çok severim

uzunca yürüyüşler yaparız 

seninle el ele sahilde

bazan Suadiye tarafına

sen de bu semti çok seversin ya

bazan da Maltepe''ye Kartal''a

ben de uzun yıllar yaşadım buralarda

ne bileyim işte şiirim seninle olunca

geceler bile pırıl pırıl gün oluyor bana

eğer seninle kavuşamazsak bu dünyada

ne olursun sevdiğim hayallerimizde olsa da

ellerimiz birbirinden hiç ayrılmasın ömrümüz boyunca

                                                            16.02.2006

                                                         Hüseyin Erdoğan', 'her semaya bakışımda seni görürüm ışıldayan yıldızlarda sanki sen olursun gök yüzü her gece öyle gelir bana denize düşer durur gözlerin yıld...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/denize-duser-durur-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etiket', 'etiket-hakki-hakan-kaya-hva1k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arama dengini, dengi değildir

Etin yanında, paça satılır

Aşka kapalı kalmış o yürek

Altın da olsa kaça satılır...', 'Arama dengini, dengi değildir Etin yanında, paça satılır Aşka kapalı kalmış o yürek Altın da olsa kaça satılır......', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/etiket-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolların Ne Suçu Var', 'yollarin-ne-sucu-var-yusuf-onder-bahceci-6nzie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolların ne suçu var, sevdiğim,

Dağların ne suçu var sevdiğim,

Çok sevdiğim, gönül verdiğim.

Yolların ne suçu var sevdiğim.

Sendin gözlerime gülüp giden,

Sendin sevdiğim deyip giden,

Sendin hep rüyalarıma giren,

Yolların ne suçu var sevdiğim.

Bilseydim, gönül verirmiydim,

Bilseydim sevgili dermiydim,

Bilseydim usul, usul giderdim,

Yolların ne suçu var sevdiğim.

Suçlu, seni fazlaca seven ben,

Suçlu, senin için cânını veren,

Suçlu güzel gözlerini de öven,

Yolların ne suçu var sevdiğim....', 'Yolların ne suçu var, sevdiğim, Dağların ne suçu var sevdiğim, Çok sevdiğim, gönül verdiğim. Yolların ne suçu var sevdiğim. Sendin gözlerime...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yollarin-ne-sucu-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelleme', 'guzelleme-tahsin-simsek-dbyms', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GÜZELLEME

Üstüne titremekten del’olur gönlüm

Tutkuyla kuşatır ikimizi, sevişmek

Akıp giden saatin kadrini bilirken

O, yangına dönüşen düşkünlüğüm

Laleleri toplarken ellerimi bırakma sakın

Sözcükler de yetmiyor bazen, sevişmek

İşteşliğine çok geç alıştık her şeyin

Sen belki de “birlikte erimek” derdin

İstekler büyüttük nemli topraklarda

Birleşmek gökkuşakları düşü, sevişmek

O kanat çırpışlardaki yoruluş

Yankıdır yıllardır, huzurun mağaralarında

Gönül koyma, özsuyumla çoğalan peteğim

“Dolduruyorum” dememden kızarır, sevişmek

Uzanıver ülkem gibi güneşe doğru

Kabına sığamadıkça çoğalan Kibele gönlüm

Bozkırları unutmuş bir göçebedir

Sevgiye susamış turaç boyunlu, sevişmek

Tepelerden koyaklara iplik iplik inerken

Bak incileşen, ışığınla girdiğim midyedir', 'GÜZELLEME Üstüne titremekten del’olur gönlüm Tutkuyla kuşatır ikimizi, sevişmek Akıp giden saatin kadrini bilirken O, yangına dönüşen düşkün...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Şimşek']::text[], 8.5, '{"poet":"Tahsin Şimşek","poet_slug":"tahsin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guzelleme-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Gitmeler Zamanı-', 'gitmeler-zamani-semsettin-kaya-nn0mq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hazan mevsimi geldi yine

kuşlar göçüp gitti buralardan

ufuklarda yankısı kaldı son çığlıklarının

ve rüzgarın şarkısı sustu

bir geçmiş daha yaşandı

gözler uzaklara bakar oldu

akıllarında çocukluk zamanlardaki delişmenlikler 

bir çizgi daha eklendi yaşlı yüzlere

hazan mevsimi geldi

ihtiyar omuzlara bir eğim daha eklendi toprağa doğru

kızıl yapraklar yere kapaklandı.

doğa yorgun, gökyüzü bulanık 

gidişlerin mevsimi hazan geldi

ve bir mesafe daha eklendi uzaklıklara

kapılara hüzün bulandı

ölümler yakın hissedilir bu mevsimde

apansız bir yolculuğa hazırlık yapılmaktadır

ihtiyar yüreklerde

biraz korkulu, biraz buruk ve küskün bazı şeylere

eksik kalmış cümleler

hafızalarda capcanlı çocukluk

söylenmemiş sırlar, ertelenmiş mutluluklar

erken biten zaman, 

gözlerin ardında bir yığın yaşanmamışlık

gitmeler zamanı şimdi

hüzünle beraber geldi hazan

17.01.2006

Ankara

(Berfin Bahar-Mart 2006 Sayı: 97)

semsettin.kayahotmail.com', 'hazan mevsimi geldi yine kuşlar göçüp gitti buralardan ufuklarda yankısı kaldı son çığlıklarının ve rüzgarın şarkısı sustu bir geçmiş daha y...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Kaya']::text[], 8.5, '{"poet":"Şemsettin Kaya","poet_slug":"semsettin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gitmeler-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Cehennemliksin! ....', 'sen-cehennemliksin-umit-tuna-8ssi0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık biliyor musun çiçekçinin önünden geçerken,

Senin en çok sevdiğin için benim için hiçbir anlam ifade etmiyor,

Artık biliyor musun gittiğimiz kafede tek başıma oturmak bana koymuyor,

Artık biliyor musun en sevdiğin elbisemi giyerken,

İçimde tuhaf bir duygu kendini ateşlemiyor.

Artık mazi benim için hiçbir anlam ifade etmiyor,

Artık gözlerinin kalbimi yenmeye gücü yetmiyor,

Artık o tatlı dilin yüreğime laf anlatamıyor,

Artık o tatlı gülüşün hiç tatlı gelmiyor.

Artık sıradan bir insansın benim için,

Sokaktan geçen her hangi bir kadınsın,

Sadece gözleri güzel olan bir kadın,

İşte artık değerin bu kadar.

Eskiden ne kadar değerliydin benim için,

Gözlerimde bir melek gibiydin,

Ama şimdi hak ettiğin yerdesin,

Benim için hiçbir anlam ifade etmemektesin,

Sen cehennemliksin! ...', 'Artık biliyor musun çiçekçinin önünden geçerken, Senin en çok sevdiğin için benim için hiçbir anlam ifade etmiyor, Artık biliyor musun gitti...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-cehennemliksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Harap Etme', 'kendini-harap-etme-yusuf-onder-bahceci-wk987', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel kendini harap etme be, dostum,

Şu Dünya''da kaç tane senin dostun,

Sakın ayağa düşme delerler postun,

Gel kendini harap etme be dostum.

Paran varsa sana beyim, bey derler,

Eğer makamın varsa el etek öperler,

Garibanın biriysen, sopayla döverler,

Gel kendini harap etme be dostum.

Benim gerçek dostum Odur Allah''ım,

Benim başka tutanacak yok ki dalım,

Ben her işimi ona havale ettim balım,

Gel kendini harap etme be dostum.

O dost ise bütün Alem düşman olsun,

Eğer O beni sevmezse kâlbim solsun,

Sonbaharda dökülen yapraklar olsun,

Gel kendini harap etme be dostum...', 'Gel kendini harap etme be, dostum, Şu Dünya''da kaç tane senin dostun, Sakın ayağa düşme delerler postun, Gel kendini harap etme be dostum. P...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kendini-harap-etme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Farklıydın', 'sen-farkliydin-umit-tuna-coloq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum ki,

Sende beni seviyorsun,

Sadece kafanı kurcalayan sorular var,

Onlar cevap istiyorsun.

Sor aşkım sor ne istersen bana,

Ne yaptıysam hep aşkımızın hatırına,

Bu büyük aşkı kaybetmemek adına,

Çünkü aşığım sana.

Seni hiç aldatmadım,

Seninleyken kimsenin koynunda yatmadım,

Kimseye sen diye sarılmadım,

Kimsenin ellerini tutmadım.

Çünkü hiçbir kız senin gibi değil,

Sen farklıydın sevgilim,

Belki de ben bunu sevdim,

Sadece senin için,

Canımdan bile geçtim! ...', 'Biliyorum ki, Sende beni seviyorsun, Sadece kafanı kurcalayan sorular var, Onlar cevap istiyorsun. Sor aşkım sor ne istersen bana, Ne yaptıy...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-farkliydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Bittin', 'sende-bittin-umit-tuna-zv1he', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani nerde güzelliğin,

Bak sende tükendin,

Bir zamanlar peşinden,

Onca insan sürükledin.

Ne oldu şimdi sana,

Bak bir tek dostun kalmadı yanında,

Hani nerde güzelliğin,

Bir zamanlar prenses gibiydin.

Hani nerde güzelliğin,

Bak iş de sende bittin,

Seni sevenlerin değerini bilmedin,

Şimdi ise sende terk edildin.

Yılların ağırlığı çökmüş yüzüne,

Kambur kambur üstüne,

Nerede o eski güzelliğin,

Nerede o eski gözlerin,

Bak iş de sende bittin.

Oysa seni zamanında ne çok sevmiştim,

Seni sevdiğim kadar kimseyi sevememiştim,

Hani nerde güzelliğin,

Bak iş de en sonunda,

Benim gözlerimde de bittin.

Yalnızlığa terk edildin,

Ama sen bunu hak ettin,

Düşeceğin bu durumu hiç hesap etmedin,

İş de sen hatayı burada işledin.

Yıllar sonra ancak fark ettin,

Şimdi aç gözlerini iyice bak,

Tek bir aşkın yanında olmayacak,

Senin adın kimsenin ağzında şarkı olmayacak,

Bak iş de,

Sende bittin,

Sende tükendin! ...', 'Hani nerde güzelliğin, Bak sende tükendin, Bir zamanlar peşinden, Onca insan sürükledin. Ne oldu şimdi sana, Bak bir tek dostun kalmadı yanı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sende-bittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir-leşme', 'bir-lesme-serif-koyan-pnlhv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir-leşme

Yürüyordu...

Kızdı! 

Yol kenarındakine bir tokat vurdu! 

O''nu düşünüyordu...

Seyretti.....

...............

..................

..............................

Döndü arkasına baktı...

Tabela durmuştu.

29.04.1991

Şerif Köyan

''Gözyaşı Kokusu''''nun yazarı', 'Bir-leşme Yürüyordu... Kızdı!  Yol kenarındakine bir tokat vurdu!  O''nu düşünüyordu... Seyretti..... ............... .................. .......', ARRAY['Türk Edebiyatı','Şiir','Şerif Köyan']::text[], 8.5, '{"poet":"Şerif Köyan","poet_slug":"serif-koyan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-lesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-umit-tuna-hktuv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendimi bildim,

Hayatı seninle öğrendim,

Daha 18’lik delikanlıyken ilk aşka yenildim,

Hayat ilk golünü attı bana.

1-0 yenik başladım hayata,

O gol çok şey öğretti bana,

Sakın beni susturma,

Senden yediğim golden sonra.

Dağıttım ben kendimi,

Şimdi gelsen tanıyamazsın beni,

Adım çıkmış zamparaya,

Her gece başka bir barda.

Her gece başka bir hatunla,

Bazen Rus bazen Alamanla,

Takılıp hayatımı yaşıyorum.

Ben artık hayata gol attım,

Hayata karşı savaşmayı başardım,

Ama senden yediğim golü unutmadım,

Ben o gol sayesinde bunları yaptım,

Kalbimi şeytana üç kuruşa sattım.

Beş para etmez bedenlerle yattım,

Seni unutacağımı sandım,

Ama hep yanıldım,

Hep kendimi kandırdım.

Sanki hep sen beni görüyorsun sandım,

Ama yine yanıldım,

Feryatlarımı duyarsın sandım,

Neler neler yaptım,

Ben sana doyamadım,

Bunun için ağladım,

Gel artık hayatım! ...', 'Kendimi bildim, Hayatı seninle öğrendim, Daha 18’lik delikanlıyken ilk aşka yenildim, Hayat ilk golünü attı bana. 1-0 yenik başladım hayata,...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/senden-sonra-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle İlk Defa', 'seninle-i-lk-defa-umit-tuna-43b8a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben hiç böyle sevmemiştim,

Sevdiğimi bu kadar belli etmemiştim,

Aşksız geçen gecelere isyan etmemiştim,

Kimseye bu kadar gönül vermemiştim.

Eli elime değdiğinde içim titriyordu,

Yan yana geldiğimizde içim ürperiyordu,

İçimden şu geçiyordu; 

Galiba ben bu sefer abayı yaktım.

Bu kıza kafayı fena taktım,

Bilmiyorum iyi mi yaptım,

Ama ben bu kıza taptım,

Bunu bir tek ona anlatamadım.

İçimden gelen bu duyguya karşı koyamadım,

En sonunda bende teslim oldum,

Bütün kalbimle onun oldum,

Çünkü seviyordum! ...', 'Ben hiç böyle sevmemiştim, Sevdiğimi bu kadar belli etmemiştim, Aşksız geçen gecelere isyan etmemiştim, Kimseye bu kadar gönül vermemiştim. ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seninle-ilk-defa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim Artık', 'sensizim-artik-umit-tuna-e5nnz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aklımdan silip atamıyorum,

Sensizliğe bir türlü alışamıyorum,

Çık git artık hayatımdan,

Seni hiç sevmiyorum.

En küçük bir şeyi,

Büyütür olduk,

Birbirimizi hep kırar olduk,

Birisi yüzünden yıkıldık durduk,

Git git artık o birisine git,

Benden sana izin git! ...', 'Aklımdan silip atamıyorum, Sensizliğe bir türlü alışamıyorum, Çık git artık hayatımdan, Seni hiç sevmiyorum. En küçük bir şeyi, Büyütür oldu...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensizim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye...?', 'sevgiliye-umit-tuna-60hyq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sevgilim vardı; 

Kumral yeşil gözlü hoş bir bayandı,

Bir sevgilim vardı; 

Bakışına canlar fedaydı.

Bir sevgilim vardı; 

Adı bende saklı,

Bir sevgilim vardı; 

Boyuna, posuna bakmakla doyulmazdı.

Bir sevgilim vardı; 

Görenlerin yüreğini hoplatırdı,

Bir sevgilim vardı; 

Yağmurun arkasından çıkan,

Gökkuşağı gibiydi,

Rengarenkti, güzeldi

Çok çok şirindi.

Bir sevgilim vardı; 

Unutmak imkansızdı,

Ayrılmak yalandı,

Ama olmadı.

Bir sevgilim vardı; 

Yoluna canım fedaydı,

Aşkıyla yüreğim yandı,

Kalbim gidişine dayanamadı.

Bir sevgilim vardı; 

Aşkı o tattırdı,

Bir sevgilim vardı; 

Terk edilmenin acısını o yaşattı.

Bir sevgilim vardı; 

Baş harfi NİLAY’dı,

Hayatta gördüğüm en güzel rüyaydı,

Gitse bile ismi yüreğime kazındı,

Bu gözler onun için kaç gece ağladı.

Bu bedenim karanlık sokaklarda,

Ayyaş ayyaş dolaştı,

Sarhoşken dahi ismini andı,

Bu kalbim seni unutmadı,

Senin aşkın bambaşkaydı,

Çünkü koskoca bir yalandı! ...', 'Bir sevgilim vardı;  Kumral yeşil gözlü hoş bir bayandı, Bir sevgilim vardı;  Bakışına canlar fedaydı. Bir sevgilim vardı;  Adı bende saklı,...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sevgiliye-155-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim', 'sevgim-umit-tuna-os9o9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyordum zaten,

Bu işin sonunun ayrılık olduğunu,

Hissediyordum benimle mutlu olmadığını,

Madem öyleydi

Niye girdin hayatıma? 

Hayatımı mahvettin,

Tek isyanım buna,

Böyle büyük bir sevdaya,

Yakışır mıydı? 

Bu elveda.

Elveda derken canın acımadı mı söyle ya,

Sen elveda derken içim acıdı,

Arkanı dönüp bakmadın bile,

İş de senin sevgin böyle.

Benim sevgim ise şöyle,

Seversem; ölümüne,

Gidersem; dönmemesine,

İş de canım bu işin özeti böyle,

Yüreğin varsa bana geri döneceğini söyle! ...', 'Biliyordum zaten, Bu işin sonunun ayrılık olduğunu, Hissediyordum benimle mutlu olmadığını, Madem öyleydi Niye girdin hayatıma?  Hayatımı ma...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum....', 'seviyorum-umit-tuna-rqurb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Az kaldı geliyorum,

Ben seni çok seviyorum,

Gözlerini görmek uğruna,

Her şeyden geçiyorum,

Ben seni manyak seviyorum.

Sensiz geçen gündüzüme,

Sensiz geçen geceme,

Sensiz geçen her saniyeme,

Artık isyan ediyorum,

Yeter! Artık be,

Yüzünü görmek istiyorum! ...', 'Az kaldı geliyorum, Ben seni çok seviyorum, Gözlerini görmek uğruna, Her şeyden geçiyorum, Ben seni manyak seviyorum. Sensiz geçen gündüzüme...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seviyorum-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cebimde ki mutluluk...', 'cebimde-ki-mutluluk-hidir-cam-ze1l0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan mutluluğu cebinde taşımalı

yavan ekmeğe mi kaldı

Bir parça üzerine sürmeli

Sonra da “Bektaşi’nin biri…” deyip

Otuz iki dişiyle gülmeli

İnsan mutluluğu cebinde taşımalı

Hasta yatakta mı

Pencereden bulutlara kaçmalı

Yağmurlarla sevişip

toprağa akmalı

İnsan mutluluğu cebinde taşımalı

Su gibi, şarap gibi

Her yaşta tatmalı

Her gününü bayram sayıp

Çocuklara dağıtmalı

İnsan mutluluğu cebinde taşımalı

Güzel koksun diye

Üzerine biraz sevda döküp

Aşk ile yoğurmalı

İnsan mutluluğu cebinden çıkarıp

Dört yana savurmalı', 'İnsan mutluluğu cebinde taşımalı yavan ekmeğe mi kaldı Bir parça üzerine sürmeli Sonra da “Bektaşi’nin biri…” deyip Otuz iki dişiyle gülmeli...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Çam']::text[], 8.5, '{"poet":"Hıdır Çam","poet_slug":"hidir-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cebimde-ki-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçmak istiyorum buralardan', 'kacmak-istiyorum-buralardan-ahmet-unal-cam-1iwfo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırakıp her şeyi geride

      ardıma bile bakmadan

Unutarak, unutularak

         pişmanlık duymadan

İçimde ne bir sızı

Ne de bir hatıra

         hatırlatacak o vefasızı

Veda edip 

    emeklerime,

       nice yıllara,

           nice umutlara

veda edip

Kaçmak istiyorum buralardan', 'Bırakıp her şeyi geride       ardıma bile bakmadan Unutarak, unutularak          pişmanlık duymadan İçimde ne bir sızı Ne de bir hatıra     ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kacmak-istiyorum-buralardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidermiş...!', 'gidermis-hasan-basri-kale-eq5uo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'azdan gelen,dayanamaz çoğa gidermiş

yalnız gelen,çoğalır ama yalnız gidermiş

dünyada sevdiğini, sevdiğine söyleyemeyen

ölünce beklemez, doğrudan cennete gidermiş..

*bâkî kalan bu kubbede bir hoş sadâ imiş...', 'azdan gelen,dayanamaz çoğa gidermiş yalnız gelen,çoğalır ama yalnız gidermiş dünyada sevdiğini, sevdiğine söyleyemeyen ölünce beklemez, doğr...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gidermis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-h-hikmet-esen-4ggf8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biçim, ve yöntem çelişkisinde insanlar.

Sevgiymiş, 

Dostlukmuş adı dikilen giysilerin.

Ama bedeni,

Bir numara ufakmış; 

Ya da beli çok darmış..

Görünen o ki,

Zehabın, vehme  dönüşmesi,

Dostlukların,

Gün batımıymış..

Nedir ki beklediğin diye,

Kendime bile,

Soramıyorum artık.

Çırılçıplaklığı,

Kefeni özlemlerimin.

Bir içten dost selamı adına,

Sevgiyi tüketmeler..

Oysa insanlar,

Bir görebilseler; 

Kim ister,

Gül teninde yareler.! ? 

20/05/1997', 'Biçim, ve yöntem çelişkisinde insanlar. Sevgiymiş,  Dostlukmuş adı dikilen giysilerin. Ama bedeni, Bir numara ufakmış;  Ya da beli çok darmı...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sitem-230-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek elini', 'cek-elini-tulay-i-cen-yan5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çek elini Munzurdan.

Kıyma binlerce  canlıya,

Kıyma  doğaya...

Munzurun suyuna  kan karıştırma..

Yıllarca  çağladı dağların,

Gözyaşı  gibi Munzur.

Vadinin  içinde efsanedir.

Sütün  suya  dönmesidir.

Ana sütüdür..

Kırk  gözeden akan,

Candır, canandır..

Çek elini munzurdan.

Kurutma  gözeleri,

Karartma Munzurdan  doğan 

GÜNEŞİ.

15/02/2006', 'Çek elini Munzurdan. Kıyma binlerce  canlıya, Kıyma  doğaya... Munzurun suyuna  kan karıştırma.. Yıllarca  çağladı dağların, Gözyaşı  gibi M...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cek-elini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Yıldönümü Geçti', 'kac-yildonumu-gecti-i-brahim-dikmen-2-33sm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni,beklediğime değdi

canım,

kaç yıldönümü geçti üstünden

sessizce gidişinin

kimbilir şimdi hangi meleklesin

Seni beklediğime değdi 

canım,

hala bakire bedenim

ve

hala düşlerim bakire

senden başka kimse okşamadı

saçlarımı

kimse öpmedi kiraz dudaklarımı

ve

kimse dokunmadı ak tenime

Seni beklediğime değdi 

canım,

sana geldiğim ilk günkü gibiyim

senden başkasını görmedi

gözlerim.

dokunmadı başka ellere

pamuk ellerim.

yüreğim sevmedi kimseyi

senin bıraktığın gibi

gül bahçesi gibiyim.

Seni beklediğime değdi

canım,

gelecekmişsin gibi

kendimi sana sakladım

ağladım belki yokluğuna

uyuyamadım geceler boyu

kaç yıldönümü geçti üstünden

sessizce yok oluşunun

Seni beklediğime değdi 

canım,

sende beni bekle sana yakınım

yakınım sana kavuşmaya

dünya ile vedalaşmaya

ahiretle kucaklaşmaya

sevdiğim beni bekler

tez elden

Azraile haber salın.', 'Seni,beklediğime değdi canım, kaç yıldönümü geçti üstünden sessizce gidişinin kimbilir şimdi hangi meleklesin Seni beklediğime değdi  canım,...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kac-yildonumu-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Döngüsü', 'ayrilik-dongusu-atanur-kurtulus-nvd40', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlemin yanacak gecelerimde,gündüzlerimde

Bir sahil ayazındaki gidişin

Oysa yokluğun...

Oysa yokluğun kalbimden sızan bir volkan gibi

Hertarafı yakıp kül ediyor 

Senden kalan küllerime su serpecek kavuşma günümüz

Bu şehir,o şehir sürgün yerim,

Biz tekrar yağmurda buluşacağız

Yağmurduk biz,büyük şimşekler olup, yağdık

Akarsu olduk,

Ayrılıp çok uzaklara gideceğiz

Büyüyeceğiz,bulanacağız,coşacağız

Dineceğiz ve tekrar yağmur olacağız bir gün

Ve ayrılık volkanını söndüreceğiz 

Ve yağmur sonrası toprak kokusu bahar kokusu olacağız...

''y.k''', 'Özlemin yanacak gecelerimde,gündüzlerimde Bir sahil ayazındaki gidişin Oysa yokluğun... Oysa yokluğun kalbimden sızan bir volkan gibi Hertar...', ARRAY['Türk Edebiyatı','Şiir','Atanur Kurtuluş']::text[], 8.5, '{"poet":"Atanur Kurtuluş","poet_slug":"atanur-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-dongusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hava Durumu', 'hava-durumu-h-hikmet-esen-rk6ls', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünceler, 

Sağanak halinde yer, yer.

Yaşam,

Parçalı bulutlu; 

Sırılsıklam, 

Kapkaranlık geceler.

Özlemlerde,

Islak toprak kokusu,

Sevdam sa,

Gönülde seyr-ü sefer', 'Düşünceler,  Sağanak halinde yer, yer. Yaşam, Parçalı bulutlu;  Sırılsıklam,  Kapkaranlık geceler. Özlemlerde, Islak toprak kokusu, Sevdam s...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hava-durumu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De @ li @ ce @ si @ ne', 'de-li-ce-si-ne-nazan-i-zmirli-cbk0l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''ayaklarım    kesilirdi

bedenim    su    yürüyen 

ağacın  gövdesinden   farksız

saçlarım  uçuşurdu  sesinin  rüzgarıyla

de  @  li @  ce @  si  @  ne

......................kıskançlıklarım  çok sana.''

sen  olmak  istedim 

seni  sen den  çalmadan

sevdim! 

hep  gülümsedim 

karşılık  beklemedim

sen    istemedikçe

seni   yaşamak  güzeldi

özlemlerinle.....

çok  mu  şey  istedim

sebebi  olduğun  coşkuyu

anlatan   sözcüklerde

umurumda    değildi 

umursamaz    alaycı

bıkkınlık   ifade  eden  sözlerin

altında  bir arzu, bin  hüzün gizliydi

erdemlerinde   gözlemlediğİm........

senede   bir   gün

seni   görmüşlüğüm

bir  ömür  birlikte  geçmiş  gibi

kokuna   hasretliğim

kıskançlıklarım  çok  sana

korkum  yok  bir  kadından  yana

kıskanırım! 

heeer  akşammm  uğradığın   balıkçını

balığı   sarhoş  eden  fesleğenli  rakını

uykunu   paylaştığın   yastığı, yorganını

sırlaştığın   sokak  lambanı

seni  benden  önce  saran

günün  ilk  sıcacık  ışınlarını

nefes  aldığın  havayı.........

isterdim! 

çok isterdim! 

sabahları  elalarına  ilk  bakan

yanaklarına  ilk  vuran 

suyun  damlacıklarında  olmayı

kıssssskanırımmmmmmmmm

kumrulara  öpücük vermek  için

sildiğin  camın  donmuşluğunda

üşüyen   parmaklarını    ısıttığın 

ve  hala  birlikte  telvesini

yalayamadığımız 

kulbu kırık fincanda

içini  yumuşatan

sert   kahveni

yudumlamanı

kıskanırım! 

biliyorum! 

teslim  olmadın

bana  olduğun  kadar

hiçbir  özde ki   ruha

senede  bir de olsa

yüreğim  bedenim

senden  yana

neden? 

bu  kaçışlar

neden? 

? ? ? ? ? ? ....... yarınlara........kıskançlıklarım.......? ? ? ? ? ? 

17.02.2006-antalya', '''ayaklarım    kesilirdi bedenim    su    yürüyen  ağacın  gövdesinden   farksız saçlarım  uçuşurdu  sesinin  rüzgarıyla de  @  li @  ce @  s...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/de-li-ce-si-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münişe özel', 'munise-ozel-munevver-senol-lufi5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Müniş abla bunu başarıyor...tüm saygılarımla...esen kalınız.





hazan sultan ayten 

Avusturya 

Bayan,  47 

15.2.2006 23:06 

 HAYATIN KAHRINI CEKMISSIN EN DERINDEN 

SEVDIGIN ACIMADAN VURMUS CAN EVINDEN 

YASAM GÜCÜNÜ KIMSE ALAMAMIS ELINDEN 

AYYÜZLÜM HERSEYE RAGMEN........ 

DIMDIK AYAKTA KALMAYI ÖGRENDIM SENDEN. 

Demek geldi icimden...Sözler yetmez...ayten.', 'Müniş abla bunu başarıyor...tüm saygılarımla...esen kalınız. hazan sultan ayten  Avusturya  Bayan,  47  15.2.2006 23:06   HAYATIN KAHRINI CE...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/munise-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahilde Islık Çaldım', 'sahilde-islik-caldim-mehmet-akif-tiryaki-cgv9u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acemi bilardocu oldum,

Sabahlara kadar oturdum,

Geceye günaydın dedim,

Yarınları ıskaladım.

Sahilde tek yürüdüm,

Yol boyunca ıslık çaldım,

Her gün kapı zili çalmaktan,

Bıktım, usandım.

Berem kulaklarımı örttü,

Paltomun yakası havaya kalktı,

Ayaklarım sanki bateri çaldı

Islıklar yol boyu ağzımdan süzüldü,

Sahili dümdüz gezdim,

İçimin rahatladığını sezdim

Sahil olmasa ben ne edecektim,

Deniz kokusu ile kendime geldim.', 'Acemi bilardocu oldum, Sabahlara kadar oturdum, Geceye günaydın dedim, Yarınları ıskaladım. Sahilde tek yürüdüm, Yol boyunca ıslık çaldım, H...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sahilde-islik-caldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Aydınlık', 'nasil-aydinlik-yasar-tezel-tummf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hükmü bitmiş,dinlerine sadık

Medeniyetler kurmuşlar,ruhları yıkık

Ebu Cehillerin torunları zulmediyor

Oğul sen kitabına sahip çık

Modern silahlar,denizde havadan

Cesareti yok bunların aklı kıt

Vuruyorlar mazluma açık açık

Oğul sen Nebine sahip çık

Kan emici vampir bunlar

Leş soyucu dalkavuklar

Sahib çık Rabbim duyar

Oğul kaleminle mücadeleye çık

Medine nedeniyetler baş şehri

Köleler o beldede efendi idi

Mekke fethinde hiç kan dökmedi

Oğul sen mazluma sahip çık

                                               16/02/2006', 'Hükmü bitmiş,dinlerine sadık Medeniyetler kurmuşlar,ruhları yıkık Ebu Cehillerin torunları zulmediyor Oğul sen kitabına sahip çık Modern sil...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nasil-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marjinalliklerimiz', 'marjinalliklerimiz-mehmet-akif-tiryaki-8o5s1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Donuk iki göz bir dudak,

Burnun yan tarafında bir damla,

Yavaş yavaş aşağı doğru kaysada

Umursamaz bir eda

Sessiz duruş

Çık şey ifade eder

Az şeymi? 

O damlada neler gizli

Toprağa düşen bir tohum misali

Kin açacak uzun zaman sonra,

Bekle,

Kara tohumlar toprağı delecek,

İçimden bir haykırış yükselecek

Iskaladığım zaman üzülürüm,

Önüme çıkanı deviririm

Sebepsiz savrulan yumruklar,

Donuk bakışlar,

Yavaş yavaş aşağı doğru akan yaşlar,

Marjinal hayattan parçalar', 'Donuk iki göz bir dudak, Burnun yan tarafında bir damla, Yavaş yavaş aşağı doğru kaysada Umursamaz bir eda Sessiz duruş Çık şey ifade eder A...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/marjinalliklerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran kuşum', 'hicran-kusum-elazigli-mustafa-kaya-2xymo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gölde boğulmuşum

bir yağmurla ıpıslak

bir rüzgarla savruk

ve kaybolmuşum 

gecelerin,

bitmeyen göklerinde.

aklından geçenleri biliyorum

kokun geliyor,

silinmez çizgilerinle.

avuç içlerim kanıyor.

ve,

aksin düşüyor

penceremin önüne

bakışlarımız buğulu

uyuyor gibi durgun

hicran kuşum …

Mustafa kaya

16.02.2006 / istanbul', 'bir gölde boğulmuşum bir yağmurla ıpıslak bir rüzgarla savruk ve kaybolmuşum  gecelerin, bitmeyen göklerinde. aklından geçenleri biliyorum k...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hicran-kusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Yıllık Sevda', 'bin-yillik-sevda-yunus-kara-lry79', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni sevdiğimde erguvanlar beyazdı

Ve İsa’nın eliydi seni gönlüme yazan.

Ya çarmıh oldun bana ya da alnımda çivi,

Avcı olup bekledi her dağ başında sevdan.

Dediler ceylan olmuş mecnun gezer çöllerde,

Bir yudum içer diye sabrımdan suya döndüm.

Acı bitti bu oyun,kapanırken son perde,

Yıldızdan habersizim güneşsiz aya döndüm.

Gül renkli zamanların sen kokarken nefesi,

Ben yine firardayım bini birden sormayın.

Saçların uçuştukça duyulur kaknus sesi,

Dergâhın kapısıyım piri benden sormayın.

Hesapsız varılmazmış sevda denen menzile,

Bu vuslatın her anı ömre bedel olmalı.

Yürekteki göz izi,yaradaki tuz ile,

Ya bir ışık,bir nefes,ya da ecel olmalı.', 'Ben seni sevdiğimde erguvanlar beyazdı Ve İsa’nın eliydi seni gönlüme yazan. Ya çarmıh oldun bana ya da alnımda çivi, Avcı olup bekledi her ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bin-yillik-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-yunus-kara-q1tkh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayağında halhal,burnunda hızma,

Bir gece habersiz yatağıma gel.

Yağmurlar adını yazarken cama,

Bir gece habersiz yatağıma gel.

Düşünme boşver görüp duyanı,

Teninde kaynasın gecenin kanı,

Dışarda bırakıp kederi gamı,

Bir gece habersiz yatağıma gel.

Hicranın,hasretin girip kanına,

Yıldızı ortak et ilk günahına.

Dudaklarında arzu,ellerin kına,

Bir gece habersiz yatağıma gel.

Usulca sokul ki yanmasın tenim,

Terinle can bulsun naçiz bedenim.

Beyhûde açılmış olmasın elim,

Bir gece habersiz yatağıma gel.

Bugüne sığdırıp dünü-yarını,

Bir buseye nakşet bütün varını.

Altüst et kaderin hesaplarını,

Bir gece habersiz yatağıma gel.', 'Ayağında halhal,burnunda hızma, Bir gece habersiz yatağıma gel. Yağmurlar adını yazarken cama, Bir gece habersiz yatağıma gel. Düşünme boşve...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/davet-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askeri güzelleme', 'askeri-guzelleme-bilal-i-lhami-koksal-7vpa4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman

Yattığım yerden seni aradım gökyüzünde

Biraz yorulmuşum

Sinirim kulaklarımın kırmızısında

Kırmızının yüklendiği çokca misyondan birisiyim

Sana kırmızıdan bir gül verecek vaktim olmadı

Seni eskisi kadar sevmeye çok uzağım

Ben çok uzaktayım

O kadar yeşil ki her yer

İçime kadar yeşil oldum

Ağzım burnum çam yaprağı...', 'Zaman Yattığım yerden seni aradım gökyüzünde Biraz yorulmuşum Sinirim kulaklarımın kırmızısında Kırmızının yüklendiği çokca misyondan birisi...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askeri-guzelleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suküt-ı Hayal', 'sukut-i-hayal-yunus-kara-gmz7j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlümün dalında işleyen gonca,

Açmayıp yazımı kışa çevirdin.

Leylâ’ya muadil bilirken aşkı,

Tüm gerçeklerimi düşe çevirdin. 

Kuşanıp sevdamı çıksam dağlara,

Seni yazsam,asırlara sağlara.

Derman diye mezardaki sağlara,

Vurduğum ankayı kuşa çevirdin.

Hülyanla mayalı durgun göl idim,

İzini izleyen gamlı yel idim,

Bentlere sığmayan azgın sel idim,

Sinende kuruyan yaşa çevirdin.

Bulutu delerken toprağım taşım,

Sana eğilirdi o asi başım,

Sona ulaşmışken azgın akışım,

Bütünsonlarımıbaşaçevirdin.', 'Gönlümün dalında işleyen gonca, Açmayıp yazımı kışa çevirdin. Leylâ’ya muadil bilirken aşkı, Tüm gerçeklerimi düşe çevirdin.  Kuşanıp sevdam...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sukut-i-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halim', 'halim-murat-alemdar-0rz3j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Halim  nemi olacak

Aynaya  bakıp cevaplamak  lazım aslında', 'Halim  nemi olacak Aynaya  bakıp cevaplamak  lazım aslında...', ARRAY['Türk Edebiyatı','Şiir','Murat Alemdar']::text[], 8.5, '{"poet":"Murat Alemdar","poet_slug":"murat-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/halim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus''tan Yunus''a', 'yunus-tan-yunus-a-yunus-kara-rydbz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kabul et Yunus’um beni yoluna,

Ham idim yanında olmaya geldim.

İnsan-ı kâmilin tarifi sende,

İnsanı insanda bulmaya geldim.

Seninle başlardı gönül seferi,

Sen idin bent olup durduran seli; 

Körkuyu gibiyim gittin gideli,

Sözünden feyz alıp dolmaya geldim.

Varamasın sana gönül yormayan,

Muhabbet yolunu senden sormayan.

Tanımasın bizi bizden olmayan,

Renklerden arınıp solmaya geldim.

Kokundan utanıp kızardı gülüm,

Sesine sevdalı şeyda bülbülüm.

Yetmeye ermeye biçilen ömrüm,

Yanında bin ömür kalmaya geldim', 'Kabul et Yunus’um beni yoluna, Ham idim yanında olmaya geldim. İnsan-ı kâmilin tarifi sende, İnsanı insanda bulmaya geldim. Seninle başlardı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yunus-tan-yunus-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Kendi Şiir', 'olumun-kendi-siir-alper-kuruk-e8iyd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölümün şiirini ölenler yazar

O yüzdendir ölümdeki bu sır,

Yaşayan ölüme ağıtlar düzer

İnsan var olalı bunca asır.

En güzel olsa gerek ölümü yaşamak

Ki yaşayanların hepsi kıskanç.

İnsan oğlu kefenleyip saklıyor

Öleni değil ölümü ak-pak.

Bundandır ölümü acıyla gömmek

Doğumu sevinçle karşılamak...', 'Ölümün şiirini ölenler yazar O yüzdendir ölümdeki bu sır, Yaşayan ölüme ağıtlar düzer İnsan var olalı bunca asır. En güzel olsa gerek ölümü ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumun-kendi-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yatağım', 'yatagim-yunus-kara-rclsv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne dertlerime bir çare,

Ne yalnızlığıma orta

Artık benden de âvare,

Ölümü bekleyen yatak.

Ben titrerim o gıcırdar; 

Cevap verir feryadıma.

Bir makber misali yatar,

Ölümüm gelir yâdıma.', 'Ne dertlerime bir çare, Ne yalnızlığıma orta Artık benden de âvare, Ölümü bekleyen yatak. Ben titrerim o gıcırdar;  Cevap verir feryadıma. B...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yatagim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yanmak', 'seninle-yanmak-yunus-kara-qa16g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah rüzgârla kokunu gönder,

Gonca yansın bağban yansın bağ yansın.

Bülbülün canına düşsün de ateş,

Zaman yansın devran yansın çağ yansın.

Kanatsın baharı goncanın harı,

Nergisten ders alsın yarin nazarı.

Öyle bir essin ki hasret rüzgârı,

Yürek yansın yara yansın dağ yansın.

Umudu gönüle,gönlümü sana,

Adadım ömrümü kara sevdana.

Külümden bir avuç koy ki zindana,

Zindan yansın,zincir yansın bağ yansın.

Hicrinle bin defa çalınmış kapım,

Vuslata darılmış kolum kanadım.

Tellere içini döksün mızrabım,

Ova yansın,tepe yansın dağ yansın.

Talihim Mecnûn”a yüreğim köze,

Yolcuyum nihayet kabuktan öze.

Gözümden bir damla düşsün denize,

Derya yansın,balık yansın ağ yansın.', 'Bir sabah rüzgârla kokunu gönder, Gonca yansın bağban yansın bağ yansın. Bülbülün canına düşsün de ateş, Zaman yansın devran yansın çağ yans...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seninle-yanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On artı yedi', 'on-arti-yedi-bilal-i-lhami-koksal-qw8x2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerden başlarsan başlayayım sonuna gelemeyeceğim pek belli

Aklıma gelen her şeyi çabucak unutmam lazım

Dahası şiirin ve kafiyenin en uzağındayım

Eskilerden bir gün şansı verilseydi bana

Yani sen gelseydin kasımın tam ortasından bir öncesi

Evet yağmur

Evet on yedi yaşındasın

Evetse ben hala senin on yedinci yaşın mıyım? 

Gözyaşlarımı biriktiriyor olmama şaşkınım

İçimi öyle bir ezdiler ki

Seni alıp öyle bir gittiler ki

Seni tanımasaydım

Sen gitmeseydin ben nerden bilirdim ki iett''nin arka koltuğuna 

Hüzünler saklamayı

Kimse görmeden sessizce ağlamayı

O kadar çok sevmeyi

İstanbulu..

Sen gittin ya içimdeki sen öyle bir büyüdü ki

Seni yazmayı denedim

Kelimeler öyle bir kanadı ki...', 'Nerden başlarsan başlayayım sonuna gelemeyeceğim pek belli Aklıma gelen her şeyi çabucak unutmam lazım Dahası şiirin ve kafiyenin en uzağınd...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/on-arti-yedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümde kal öyle', 'gonlumde-kal-oyle-yasar-tezel-s09mk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın sihirli değneğini

Vurdun küçük kalbime

Yıldızları saymakla bitmez

Miktar biçilmez o sevgiye

Tomurcuklanmışsa  çiçek

Ay ışığı görmüşse gece

Murad erse derviş

Ne sigara dert bitirir

Ne de zikir

Sen girdin,aşkım

Gül  bahçeme', 'Aşkın sihirli değneğini Vurdun küçük kalbime Yıldızları saymakla bitmez Miktar biçilmez o sevgiye Tomurcuklanmışsa  çiçek Ay ışığı görmüşse ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gonlumde-kal-oyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '3. Kitap "Çizginin Öteki Yüzü" - Dedem', '3-kitap-cizginin-oteki-yuzu-dedem-i-brahim-cosar-3d5kz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alçak boylu, epey şişman, göbekli,

Pamuk gibi yüzü vardı dedemin

Yanlış yapmaz, yürekli mi yürekli,

Doğrulukta gözü vardı dedemin.

Çuval alıp satır, para kazanır; 

Âlemi kendi gibi hep dürüst sanır,

Heyhat, her zaman da kendi aldanır

Dürüstlükte özü vardı dedemin.

Beş çocuk, bir hanım eline bakar,

Babamda haylazmış, canını yakar.

Gün gelirmiş dedem, hayattan bıkar

Direnmeye sözü vardı dedemin.

Kızları evlendi yürek delindi,

Oğul evlenince gelen gelindi.

Torunlar olunca nasıl sevindi,

Çekilecek nazı vardı dedemin.

Müthiş kışlar olur, diz boyu kardı; 

Okul çıkışında hava karardı

Kendisi üşür de, beni sarardı

Koruyucu yazı vardı dedemin.

Ömür boyu yalanı yok, yanlış yok! 

Hak yemezdi kendisinde kalmış yok! 

Can yakmazdı sıkıntıya salmış yok! 

Her çorbada tuzu vardı dedemin.', 'Alçak boylu, epey şişman, göbekli, Pamuk gibi yüzü vardı dedemin Yanlış yapmaz, yürekli mi yürekli, Doğrulukta gözü vardı dedemin. Çuval alı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Coşar']::text[], 8.5, '{"poet":"İbrahim Coşar","poet_slug":"i-brahim-cosar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/3-kitap-cizginin-oteki-yuzu-dedem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşu boşuna', 'bosu-bosuna-cemal-dursun-4pxqe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boşu boşuna 

Ağlamak bahar sabahı

Boşu boşuna sensiz zamanlar

Tutkusuz aşklar,

Geri dönüşlü ihanetler

Boşu boşuna

Ama ne hoş 

Öylesine

Boşu boşuna aşık olmak 

İmkanlı olmasada', 'Boşu boşuna  Ağlamak bahar sabahı Boşu boşuna sensiz zamanlar Tutkusuz aşklar, Geri dönüşlü ihanetler Boşu boşuna Ama ne hoş  Öylesine Boşu ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Dursun']::text[], 8.5, '{"poet":"Cemal Dursun","poet_slug":"cemal-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bosu-bosuna-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidip gelme meselesi', 'gidip-gelme-meselesi-cemal-dursun-t18ou', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karşımda bir güzel 

Besbelli aşka muhtaç

Ve ben hesapsız aşk dağıtan şair

Ama 

Bir şey var; 

Bir engel, 

Ne kadar ruhum git desede

İçimden biri gel der', 'Karşımda bir güzel  Besbelli aşka muhtaç Ve ben hesapsız aşk dağıtan şair Ama  Bir şey var;  Bir engel,  Ne kadar ruhum git desede İçimden b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Dursun']::text[], 8.5, '{"poet":"Cemal Dursun","poet_slug":"cemal-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gidip-gelme-meselesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun ayrılığı', 'onun-ayriligi-cemal-dursun-a4cf3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sürekli sevmesine rağmen 

Yürekli bir aşığa çatmamıştı ama

Yine daima sevecem der gibi

Bir hali vardı giderken

Buruk yarınlara,

Alnının zonklamaları

Miras,

Kalbinin kanaması

Yarası kalarak

Ayrılırken', 'Sürekli sevmesine rağmen  Yürekli bir aşığa çatmamıştı ama Yine daima sevecem der gibi Bir hali vardı giderken Buruk yarınlara, Alnının zonk...', ARRAY['Türk Edebiyatı','Şiir','Cemal Dursun']::text[], 8.5, '{"poet":"Cemal Dursun","poet_slug":"cemal-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/onun-ayriligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Işık Olmalı', 'bir-isik-olmali-temel-duran-d5rqw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ot gibi yaşamak insan işimi

Sanki biri çekmiş  yaşam fişini

Ne saçın düşünmüş ne de dişini

Hayat böyle ucuz değildir dostlar

Ne ekersen kalp de onu bulursun

Düşün düşün bir gün verem olursun

Bozulmasın düzen böylece dursun

Hayat böyle ucuz değildir dostlar

Korkulan şey oldu sustu sonunda

Çaba boşa gitmez  yarin yolunda

Elbet çiçek açar ağaç dalında

Hayat böyle ucuz değildir dostlar

Bir yuva kuralım var ile yoktan

Ne güzel söylemiş söyleyen çoktan

Emeği olmasa korkmazdım haktan

Hayat böyle ucuz değildir dostlar

Elden ne gelir ki zaman durmuyor

Yıllar acımasız akıp gidiyor

Herkes saçın çabuk ağarttın diyor

Hayat böyle ucuz değildir dostlar

Bu bir hastalık sa iyi ederim

Servetim yoluna feda ederim

Ben sevdim mi adam gibi severim

Hayat böyle ucuz değildir dostlar', 'Ot gibi yaşamak insan işimi Sanki biri çekmiş  yaşam fişini Ne saçın düşünmüş ne de dişini Hayat böyle ucuz değildir dostlar Ne ekersen kalp...', ARRAY['Türk Edebiyatı','Şiir','Temel Duran']::text[], 8.5, '{"poet":"Temel Duran","poet_slug":"temel-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-isik-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-ali-aldemir-2wvaw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilse boşaltıp kendi bedeninden

Verir miydi suyunu kalır mıydı,

Ağlamasaydı güneşle,kar

Sulu demirde son söz.

Olur muydu soğuk ışıltılı,

Ham demir, paslı demir,çelik

Düştü bir çığ sesiyle

Hem de çifte su içmiş demirin.

Kardelen tepeleri

Etekleri açmış dağlarda gül,

Ah 

   yüreğim 

      vururlar

         tanda

Göz kapaklarım düşer

Vurulur

   bir

      kuş 

         düşer,

Kalır kokusu izi yatağımda.

Pişman kardelen hem de bin

Kanadı yaralanmış gülün,

İçerken yaprak üstündeki

En son damlasını yağmurun

Ağlıyordu güneşle, kar

   Vurulmuş kardelen, 

      Yaralı gül

         Susmuş sesi kuşun

Ağlama güneşle,kar artık yeter,

İki yaşlı göz bende

Kalmasın 

   artık 

      ham demirde,

Paslı demirde son söz.', 'Bilse boşaltıp kendi bedeninden Verir miydi suyunu kalır mıydı, Ağlamasaydı güneşle,kar Sulu demirde son söz. Olur muydu soğuk ışıltılı, Ham...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/son-soz-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-yasar-tezel-f2pr4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ilık bir rüzgar,rengarenk doğa

Her yerde bin canlılık,çiğdemlerde

Uçuşan kelebekler,ötüşen kuşlar

Uyan artık uyan gönül

O gün coşku,o gün mutluluklar

Gök gürler,yağmurda yağar

Misk-i amber gibi kokar,toprak

Uyan artık uyan gönül

Okşasın saçlarımı ılık rüzgar

Sarsın kollarını belime yar

Yurduma gelmiş bahar

Uyan artık uyan gönül', 'Ilık bir rüzgar,rengarenk doğa Her yerde bin canlılık,çiğdemlerde Uçuşan kelebekler,ötüşen kuşlar Uyan artık uyan gönül O gün coşku,o gün mu...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahar-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonunu Bir Bilebilsem', 'sonunu-bir-bilebilsem-yusuf-onder-bahceci-f6xc9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bu sevdanın dikenli yolundayım,

Toprak olmuşum cânım, yolundayım, 

Acaba neler olacak ki telaşındayım,

Sevdamın sonunu ah bir bilebilsem.

Ben Karac''oğlan gibi güzel peşinde,

Dadaloğlu gibiyim, sevdiği peşinde,

Mevlana gibiyim, gel, gel desemde,

Sevdamın sonunu ah bir bilebilsem.

Güzel görenler, güzel sever bilseler,

Bizi böyle ayıranlar, eyvah deseler,

Ben seni nasıl severim, bir bilseler,

Sevdamın sonunu ah bir bilebilsem.

Benim sevdiğim güzel bunu bilirmi,

Gel desem, bir gün olur da gelirmi,

Önder onun için cânını verir, bilirmi,

Sevdamın sonunu ah bir bilebilsem.', 'Ben bu sevdanın dikenli yolundayım, Toprak olmuşum cânım, yolundayım,  Acaba neler olacak ki telaşındayım, Sevdamın sonunu ah bir bilebilsem...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonunu-bir-bilebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şâirin Doğuşu', 'bir-s-irin-dogusu-timur-i-likan-mk3bz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeni bir şâir doğuyor

Başı bulutlara yaslanmış

heybetli dağların arasından

Nice zorluklarla harmanlanmış

çile yüklü bir hayâtın arkasından

Yüreği sevgilerle dayayıp döşenmiş

milyonlarca gönlün arasından

Şiir şiir ışıklar saçarak

bir şâir doğuyor şiirler deryâsında

Yeni bir güneş doğuyor yıldızlar semâsında 

(16 Şubat 2006/ İstanbul)', 'Yeni bir şâir doğuyor Başı bulutlara yaslanmış heybetli dağların arasından Nice zorluklarla harmanlanmış çile yüklü bir hayâtın arkasından Y...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-sairin-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Açsın Yüzünde', 'gul-acsin-yuzunde-temel-duran-s2fuz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkı anlamak zor kimine göre

Şöyle etrafına baksan olmaz mı

Boş yere yaşadın sanki boş yere

Sen de Şirin gibi sevsen olmaz mı

Bu kadar inatla olur mu dersin

Kinle nefret ile erir gidersin

Gül gibi hayatı zindan edersin

Artık gerçekleri görsen olmaz mı

Her gün başka afra ile kalkarsın

Ne selam ne sabah ne için varsın

Aynaya baksana sen de insansın

İnsanlığa adım atsan olmaz mı

Gönlümde bir saray kurmuştum sana

Bir gün gelemedik şöyle yan yana

Bil ki bu dünyayı dar ettin bana

Silkinip özüne dönsen olmaz mı

Gönlüm senle güzel günler istiyor

Daralmıştır ufkun sana yetmiyor

Dertlerin çok mu ki çek çek bitmiyor

Kendin için yaşa biraz olmaz mı

Gül ki gül açılsın yoksa solarsın

Gönül sarayımdan çıkar gidersin

Küsmek çocuk işi hadi ne dersin

Gül açsın yüzünde gülsen olmaz mı', 'Aşkı anlamak zor kimine göre Şöyle etrafına baksan olmaz mı Boş yere yaşadın sanki boş yere Sen de Şirin gibi sevsen olmaz mı Bu kadar inatl...', ARRAY['Türk Edebiyatı','Şiir','Temel Duran']::text[], 8.5, '{"poet":"Temel Duran","poet_slug":"temel-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gul-acsin-yuzunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mim-ahmir-rengi-zpdme', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçemedim seni ey İstanbul,

Anadan geçtim,yardan geçtim

Senden vazgeçemedim.

Suyunu bardak bardak içtim

Havanı tüm gücümle içime çektim

Vapuruna binip boğazı geçtim,

Ama senden vazgeçemedim.', 'Geçemedim seni ey İstanbul, Anadan geçtim,yardan geçtim Senden vazgeçemedim. Suyunu bardak bardak içtim Havanı tüm gücümle içime çektim Vapu...', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/istanbul-392-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eh Beş Dakika Daha İzin', 'eh-bes-dakika-daha-i-zin-nuray-acar-zvg0p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Haydi hüzün kanatlarımdan düş artık,

bak uçmak da gelmiyor içimden zorlanmayayım 

mevsimler değişirken

ve göç hazırlığındayken  ben.

Şimdi alınmışsındır kesin, hele o dudak bükmelerin var mı alimallah öldürür insanı, 

peki peki  sana bir beş dakika daha izin 

sıkı tutun mecalim tükenirken

kazaya gitmeyesin

adresini bile bilmediğin sokak aralarına düşmeden.

Geldik sayılır bak bizim o meşhur çim saha 

şu kenardaki de köhne eğrelti teneke baraka.

Şimdi kana kana suda içmek istersin bilirim,

kurumuş damağına

yutkunduğun sözcüklerinin arasına damla damla.

Takıl bari şu titrek bacaklarıma 

kanatlarımdan da düş artık 

bak geldik suyu cılız akan dere kenarına.

İçtin mi suyunu keyfini de sürdün mü sefam olsun dediğin 

kanatlarıma tutunduğun zamanlara.

Şimdi terk etmek düşüyor bize bu mahalleden 

havalar soğumuş ayaz keskin öterken kulaklarımızda.

Belki gelirim, bilirsiniz gittiğim yılın ertesi 

hep bir daha dönmeyeceğim dediğim mahalleye.

Siz yinede kiraya vermeyin şu köşede caminin solundaki trafoyu sapı samanı da dökmeyin möbleli niyetine

Seneye inşallah yine misafiriniz olacağım elbette üç günden ziyade.', 'Haydi hüzün kanatlarımdan düş artık, bak uçmak da gelmiyor içimden zorlanmayayım  mevsimler değişirken ve göç hazırlığındayken  ben. Şimdi a...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/eh-bes-dakika-daha-izin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçlik', 'hiclik-nuray-acar-pa4ub', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiçim

koskoca görünmez bir hiçim 

Görünmezim

basbayağı görünen bir  görünmezim

Duygusuzum

taş kadar sert su kadar  duygusuzum

Ben

ben miyim yoksa

senin gözlerine yansıyan

bir gölge sen miyim

gölgeden deniz olur mu

güneşten gölge toprak 

benden bir ben olur mu 

yoksa hiç biri rüya kadar gerçek değil midir', 'Hiçim koskoca görünmez bir hiçim  Görünmezim basbayağı görünen bir  görünmezim Duygusuzum taş kadar sert su kadar  duygusuzum Ben ben miyim ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hiclik-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-mim-ahmir-rengi-m7v7j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yanda güneşi yeni gören gözdeki yaş

Öte yanda kızgın kumda güneşi terkeden baş,

Anlamak zor muydu denizin ilerde olduğunu

Ama kolay değil ömür geçer yavaş yavaş', 'Bir yanda güneşi yeni gören gözdeki yaş Öte yanda kızgın kumda güneşi terkeden baş, Anlamak zor muydu denizin ilerde olduğunu Ama kolay deği...', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/omur-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrılarla Kumar', 'tanrilarla-kumar-pinar-acar-1mtsf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günden ışığını çalan güneşle kumar oynuyoruz

Yüreğimizde bir coşkunluk

Damarlarımızda bir isyan

Yüreklerimize kanla karışık alkol pompalanıyor artık

Güneşle oturmuş kumar oynuyoruz sevgilim

Yüreğimizdeki ışığa oynuyoruz

Tanrıçalarsa ellerinde biralarıyla bize şans öpücükleri gönderiyor

-şansa ihtiyacım yok biliyorum-

Tanrılar kumardan anlamıyor sevgilim

Bizlerse sevişmelerimiz kadar ustayız

Taş çalıyorum çaldıkça kazanıyorum

Bütün günahları işliyorum umursamıyorum

Kucağımda kiralık bir tanrıça seni aldatıyorum

Yatağımızı düşünüyorum,aydınlatamadığımız odamızı

Hileyle kazandığım ışığı

Ertelediğimiz betimlemeleri

Herkesin öğrendiği karanlıktaki sevişmelerimizi düşünüyorum, ağlıyorum

Sonralamızı düşünüyorum.

Parlak ışıklar altındaki sevişmelerimizi kimseler öğrenemeyecek sevgilim

Herkes hala karanlıkta seviştiğimizi düşünürken

Biz vücutlarımızda bıraktığımız izlerin nedenlerini tartışacağız

Saatlerce yüzündeki çizgileri izleyeceğim

Bencilliğimize hiç aldırmadan 

Bütün günahkarların mutluluğuna içeceğiz

Düşünmekten vazgeçelim derken sonunda öğreneceğiz sevgilim

-tanrıların yüreği yok-

Oturup ağlayacağız seninle

Masallara inanmamaya yemin edeceğiz yine

Tanrıçaların koynunda bize aldırmayan tanrılara olan kinimizi bir kez daha haykıracağız 

''bütün tanrıların canı cehenneme''

-tanrıları cehenneme atacak bir tanrının olmadığını kendimizden bile saklayacağız-', 'Günden ışığını çalan güneşle kumar oynuyoruz Yüreğimizde bir coşkunluk Damarlarımızda bir isyan Yüreklerimize kanla karışık alkol pompalanıy...', ARRAY['Türk Edebiyatı','Şiir','Pınar Acar']::text[], 8.5, '{"poet":"Pınar Acar","poet_slug":"pinar-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/tanrilarla-kumar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorsun', 'geliyorsun-yasar-tezel-b6hpi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllardan sonra

Dönüyorsun

Resimlerim,resmin

Mektupları biliyorsun

Hasreti nasıl yendik

Bilmiyorum

Nemli havalardan

Dört mevsime

Gelin geliyorsun

Ne kadarda özlemişim

Söylemiştin

İnanmamıştım geleceğini

Kışın açan kardelen gibi

Yıllar sonra geliyorsun

Sorular,dedikodular

Düşündüren yalnızlığım

Karalanan sayfalar

Geceler karabasan

Bitti bitti artık

Hoş geldin

Dört gözle beklediğimi

Biliyorsun

Üç beş sayılı gün

Yaban

Eğri büğrü yollardan

Kovana,arı oğula

Bal peteğe  geliyorsun

Mutluyum dünyalar benim kadar

Seni seviyorum

                                 30/09/1989', 'Yıllardan sonra Dönüyorsun Resimlerim,resmin Mektupları biliyorsun Hasreti nasıl yendik Bilmiyorum Nemli havalardan Dört mevsime Gelin geliy...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/geliyorsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-mim-ahmir-rengi-xu4tx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana bir söz söyle ki ruhum aydınlansın

Bana bir bakış ver ki gözüm canlansın,

Kalbimin derinliklerinde bir alev,

Söyle umutlara,hiç ama hiç solmasın', 'Bana bir söz söyle ki ruhum aydınlansın Bana bir bakış ver ki gözüm canlansın, Kalbimin derinliklerinde bir alev, Söyle umutlara,hiç ama hiç...', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/umut-252-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-mim-ahmir-rengi-0ilab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş sonsuz ışığıyla dünyayı ısıtmakta

Benim bedenimse gemisiz bir rıhtımda,

Kalemi oynatır,koşarım coşarcasına

Yürekler birleşmiş,sevgiler uçarcasına

Tepeden tırnağa,rahmet boşalırcasına

Çizgiler eğri,yollar dolarcasına

Gazete,dergi ne varsa kapışılırcasına

Ne varsa ünlü,ünsüz hep yaşarcasına

Ben yaşıyorum yaşamak buysa...', 'Güneş sonsuz ışığıyla dünyayı ısıtmakta Benim bedenimse gemisiz bir rıhtımda, Kalemi oynatır,koşarım coşarcasına Yürekler birleşmiş,sevgiler...', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasamak-205-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye''min Herşeyi Var', 'turkiye-min-herseyi-var-yusuf-onder-bahceci-qu1xr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim Türkiye''min, her şeyi var,

Dört mevsim baharı, gülizarı var,

Bahçelerde güller ve zambaklar,

Benim Türkiye''min, her şeyi var,

Benim Türkiye''min her şeyi var,

Dostları sevinir, dostlarımız var,

Üç tarafımız deniz, kıyılarım var,

Benim Türkiye''min her şeyi var.

Benim Türkiye''min, yolları uzun,

Benim kâlbimde var hep hüzün,

Gelir diye, diye oldu bak güzün,

Benim Türkiye''min her şeyi var.

Yalçın dağlarımız, hep kârlı olur,

Yiğitleri güzel sever efkârlı olur,

Askere gider, vurulur şehit olur,

Benim Türkiye''min her şeyi var.', 'Benim Türkiye''min, her şeyi var, Dört mevsim baharı, gülizarı var, Bahçelerde güller ve zambaklar, Benim Türkiye''min, her şeyi var, Benim Tü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turkiye-min-herseyi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-mim-ahmir-rengi-vgjhc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürüyorum sahilde, sessizce

Unutmak istiyorum, gizlice

Bembeyaz bir ışık ve yalnızlık

Artık her şey hayal oldu gözümde', 'Yürüyorum sahilde, sessizce Unutmak istiyorum, gizlice Bembeyaz bir ışık ve yalnızlık Artık her şey hayal oldu gözümde...', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unutmak-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalakalırım', 'kalakalirim-yasar-tezel-k9fim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen

Seninle sensiz

Yalnız kalırım

Takılır gözlerim

Göğe

Yutkunurum

Boğazım kurur

Sonbahara bürünürüm

Çöker hüzün

Uzar mı uzar, gece

Yalnız kalırım

Onunla,onsuz

İki karşı ev

Yakın

Yaşar,ım

İki can içinde

Mutluluk

Gece geç vakit

Hala yanan

Yalnızlık lambasına

Şaşkın

Ona baka kalırım', 'Bazen Seninle sensiz Yalnız kalırım Takılır gözlerim Göğe Yutkunurum Boğazım kurur Sonbahara bürünürüm Çöker hüzün Uzar mı uzar, gece Yalnız...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kalakalirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ve Kendini Bıkmadan Bağışlayışla*', 've-kendini-bikmadan-bagislayisla-gul-yazganarikan-jp4sp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun bir yürüyüş  aslında her günümüz, 

...............................................Derken 

ve şu sinsi ömrün bir yerinde yaklaşıyorum, 

yaklaşıyoruz belki de en çok kendimize

Sorgu odasına çekiliyor yüreğimiz.

İçimizde bıçaklı, toplu, mermili bir savaş başlıyor,

Yüreğimiz ve beynimiz göğüs göğüse,

İnsan azıcık nefes almak istiyor, bir ağaç kovuğu, bir söğüt dalı

Bir pınar başı uzanmak istiyor dilediğince...Geçmişine ve geleceğine...

Bir uçurtmanın seyri gibi gençliğimiz,

Ve bir yelkenli gibi düşlerimiz açılıyor denize...

Ve tuttuklarımız ellerimizle, 

Gözlerimizle değdiklerimiz,

Dokunanlar tenimize, içimize, selimize,

Her biri kalıyor bir uçurum dibinde....

Ve yürüyoruz, 

omuz omuza olsak da sırtımızda bir aba gibi yalnızlığımız

Görmek istediklerini görüyor gözlerimiz, 

ve yalnızca duymak istediklerini söylüyor belki de sözlerimiz

Severken, aşık olurken aslında kendi siluetimizi arıyoruz karşıda ki kişi de

Kendimiz yapmaya çalışıyor benliğimiz, aslında yalnızca bir ayna belki de istediğimiz...

Ah bu yüreklerimiz ve ah şu kaybettiklerimiz kazandıklarımız, doymayı bilmeden yaşadıklarımız...

Aç belki hiç doymayan duygularımız, kıymet bilmeyen edalarımız.

Yorgunuz, yorulmuşuz iç savaşlarımızdan, dış düşmanlarımızdan... 

daha dün dost olduklarımız ve hançerleyenler bizi arkamızdan...

Yol uzun, yol tümsekli, yol dik, gün gün gece gideriz belki, sis çöker şu dağın ardından, kar yağar kayar ayaklarımız üşür ellerimiz ve en çok yüreğimiz,

 güneşi de görürüz yol sonlanmadan....

Düşe kalka, güle ağlaya belki sorarız kendimize, içimize, yanımızdakine.... Aşk ve mutluluk acaba nerde... Daha çok mu... 

Yolun yarısı geçmiştir oysa...... 

ARAYIŞLA....

VE KENDİNİ BIKMADAN BAĞIŞLAYIŞLA...', 'Uzun bir yürüyüş  aslında her günümüz,  ...............................................Derken  ve şu sinsi ömrün bir yerinde yaklaşıyorum,  ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ve-kendini-bikmadan-bagislayisla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehri Sevdalarımın', 'sehri-sevdalarimin-zeliha-bicer-ny4fb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denizin koca kayaları 

Vuruşunu seyrediyorum

Her hırçın dalgada 

Dimdik ayakta yaşam gibi

Deniz, hırçın ama 

Güzel bir kız edasında gösterişli

Kayalar sessiz vakur

Gökyüzünün maviliği,

Suya akseden kısmında

Laciverte dönen rengi

Dalgaların beyazlığında 

Martıların süzülüşü var

Vapurların düdükleri

Eskiden kalma bir şarkı 

Keman eşliğinde söylenen

İstanbul

Huzurum,hüznüm,ayrılıklarım

Şehri sevdalarımın

Kimsesizliğimi hep yanımda taşıdım', 'Denizin koca kayaları  Vuruşunu seyrediyorum Her hırçın dalgada  Dimdik ayakta yaşam gibi Deniz, hırçın ama  Güzel bir kız edasında gösteriş...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sehri-sevdalarimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece-2', 'bu-gece-2-nurdane-diken-q3uwq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle; 

Günâh dolu gecelerin

En karanlık köşesinde

Saklanmalıyız..

Merak dolu gözlere

Kara perdelerimizi çekip

Kötü bakışlardan 

Gizlenmeliyiz..

Sonra; 

Gece üryan olmalı

Karanlığından

İkimiz için

Desen desen olmalı

Güneşin rengarenk ışıkları gibi

Mest olmalıyız..

Ve; 

Aşıkların yaşadığı

Aşk gecelerinin

En ulaşılmazını

Yaşamalıyız..

Günah ve sevap

Geceden kalan olmalı

Ne kural, ne din 

Aramızda olmamalı

Sevmeliyiz...

Günah ve sevap

Onlardan çok ötede

Ama, onların içinde

Birlikte

Olmalıyız..

Günah; 

Tomurcuk tomurcuk açmalı

Özlemlerin en koyusu

Bedenlerimizi sarmalı..

Sevap; 

Bu geceden doğmalı..

Sonra; 

Biz bitkin

Biz solgun

Elele, göz göze

Güneş bizi ölgün bulmalı

Nefesimiz sevgililere dağılmalı...

03.01.98-19.30-İst..', 'Seninle;  Günâh dolu gecelerin En karanlık köşesinde Saklanmalıyız.. Merak dolu gözlere Kara perdelerimizi çekip Kötü bakışlardan  Gizlenmel...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bu-gece-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni icat Küfürler (Yeni Yetmelik)', 'yeni-icat-kufurler-yeni-yetmelik-ali-aldemir-j6dp2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sokaklar, bu kent değil mi? 

                    Kleopatra analı,

Yiyip bitiren tümden umutlarımızı, gerzekçe

Harcıâlem bir yaşamda, fistansız ayıplarla

Tüketen sonra yeni yetmeliğimizi,

Duman dağları arsında yudumlarken

Dünden kalma kekremiş çaylarını,

Demlerken babalarımız; 

    Hüzünleri, yokluğu ve çaresizliği,

      O kocaman mangal yüreklerinde

                           Bilmem kaçıncı kere, 

Uçkurdan rüşvetle konulmuş, kondularında,

“benim oğlum büyük, hemi de çok büyük adam çıkacak! 

Hele küçüğüm, mavişim onu hiç demeyin; 

O doktor çıkacak, büyük doktor,

Umudumuz, babasının kızı / Ah düşlerimiz /

Tüketmedi mi onları da,

Allahın her günü, ağız dolusu kusar gibi

Az tükürüp, 

Az sümkürmedik

Az savurmadık duvarlarına karşı hınçla

Sitemlerin en tumturaklısını,

(Ah ulan diyorum; ibret–i âlem için, yaksam mı bu kenti?) 

Onlarca göz önünde tehditlerle,

Çıkmasın sakın sesiniz, kıpırdamayın,

Galasında bir filmin, avantür

Kaç kere kanırtıldık,

 Kaç kere incindik, kirletildik,

Yitirdiğinde anlamını, bize kalanlar,

    Kaç kere yırttık gecelerin sessizliğini

Yeni icat küfürlerimizle! 

Zırlama, kes ulan

Alışamadın mı daha? 

Neyin nesi bu sızlanmalar,

Yediğin önünde! 

Arkanda yemediğinse! 

Krallar gibi giyinirken iyi,

   Sık dişini, hepsi iki dakkalık! 

Çok dinledik, dinlettiler dahası,

Falçata resitallerinin eşliğinde,

Hani o büyük kelli felli adamlar! ! ! 

Hamaset nutukları sallayan

Onlar var ya…

Nasıl da kudurur, köpekleşir, yalakalaşırlar

Dört köşe olurken zevkten

Akıtarak salyalarını kustururken! ! ! 

Kan kusarken biz…

Ben bu adam kılıklı iblislerin…

Kim kimin babasıdır belli olmayan

Bak durduk gene bozuldu asabım,

Ulan ben bunların, gelmişlerini, geçmişlerini

Yedi göbek sülalelerini,

…

Aldanmayın o afra tafralarına, hepsi fos

Yoktur yürekleri, tavuk kadar

Bilirim alayının ciğerini

Ne çare gel gör ki devir

Elleşmeyin bırakın ulan,

Yansın bu şehir, alev, alev 

Günahlarıyla yansın,

Kalsın baş başa küllerinin utancıyla

Az bu kente bu bedel,

Her santiminde ve her anında, uluorta

Savrulsun arsız rüzgârlarına karşı

Yeni icat küfürlerimiz,

Sonra not düşsün şöyle ustaca,

Bir ressam beyaz tuvaline,

Ah kafamız; dinlemez misin nasihatleri,

Yiğitlik var ya ser’de

Nasihati kim ipler! 

Delikanlılık bu boru mu? 

İlle de yeni yetmelik,

Ah kanımız, kaynayan yanımız, yok mu? 

Hadi bir dene, ne çıkar? Nasıl unutacaksın bak dertlerini! ! ! 

Sen kralısın bu alemin! ! ! Aslanım benim, koçum…

Bak şu gördüğün en iyisi tinerin! ! ! 

Hele bu bally diyecek yok, uçarsın be oğlum, kitabıma,

                                                                       Yeminle,

Böyle başladı yeni yetmeliğimiz,

Ah nasıl da söndürüldü, uçuk tozpembe hayallerimiz,

Ya bizden öncekiler? Sevdaları, düşleri, umutları…

Ak sütü gibi analarımızın,

Şimdi hepsi hayallerden bile ırak,

Ben bu kenti sallandırmayayım da ne yapayım? 

Her zulasını, daniskasını kancıklığının,

Kim kimi çelmeler, pazarlar en iyi kim kimi? 

Bellemişim hepsini iyicene,

Nasıl kurulur en iyisi tezgâhın, yolcularına o yolun? 

Ulan yaksam mı bu şehri? Geliyorlar yine kafama! 

Aklıma düşer bazen kaybettiğim gözyaşlarım gibi,

Yeni yetmeliğim, bu yüreğimin kaçıncı buruluşu? 

“Gitme, tükendim, gücüm yok,

Harcanacaksın, yazık edeceksin kendine, dön”

Vakitli vakitsiz bu ince ses kulaklarımı tırmalar,

A benim kadersizim, çilelim, ak saçlı, gözü yaşlı 

Mangal yürekli anam,

Bu toyluk, yeni yetmelik yok mu? 

İstesen de dönemiyorsun, bırakmıyorlar,

Sıcaklığını ararım sesinin, elinin sonra teninin kokusunu,

Nasıl da özledim, burnumda tütmektesin,

“Olmazmış ana gibi yar”

Ah bu geyikler büyüsünü aldandığımız, aklımızı alan,

Ah bu geyikler, ille de açlığımız, başkaldırımız,

Dallanıp omuzlarda ceketleri, açık üç düğmeyle bağrımız,

Sallayıp şakırdatarak tespihleri, voltalarda

Caka satıp, hava basarken, yumurta topuk yatık ökçeyle,

Bilmedik, bilemedik kepazelik, eşeklik, itlik olduğunu,

Nice sonra anladık, erdemini okumanın, eğitimin 

Ve de çalışmanın, üretmenin, alın terinin,

Dahası utancın, utanmaların, insan utanırmış,

Utanmayı bilmeliymiş,

Ve paylaştıkça azaldığını kederlerin,

Büyüdüğünü sevinçlerin ve yüceliğini bölüşebilmenin,

Çok geç anladık sevmeleri, çok geç dank etti kafalarımız,

Ah akılsız başımız, ahmaklığımız,

Altın vuruşlarla şırınga uçlarında

Ha bre törpüleyip durduğumuz, çocukluğumuz,

Sahipsiz gençliğimiz….', 'Bu sokaklar, bu kent değil mi?                      Kleopatra analı, Yiyip bitiren tümden umutlarımızı, gerzekçe Harcıâlem bir yaşamda, fist...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":118,"source_url":"https://www.antoloji.com/yeni-icat-kufurler-yeni-yetmelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özedoğru', 'ozedogru-yasar-tezel-u0ava', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman ve su akıp giden

Unutulan tarih

Sanat,musıki

Kaybolan ciddiyetimiz

Ana kucağımız,yurdumuz

Hükümsüz sandığımız

Üç kuruşa sattığımız

Geçmişe kızarak yaktığımız

islam,milliyetçiliğimiz

Mevlana,Yunus Emre miz

Osmanlıyı,Dede Korkutu

Alacaklar diye korkuyorum', 'Zaman ve su akıp giden Unutulan tarih Sanat,musıki Kaybolan ciddiyetimiz Ana kucağımız,yurdumuz Hükümsüz sandığımız Üç kuruşa sattığımız Geç...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozedogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Neye Kızarsın', 'soyle-neye-kizarsin-yusuf-onder-bahceci-vrs38', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yollar uzarsa sen yollara mı kızarsın,

Yârini eller almış, onlara mı kızarsın,

Alanı bırak sen, ayırana mı kızarsın,

Söyle neye kızarsın, nelere kızarsın.

Gözüne bakarak, yalana mı kızarsın,

Kalasa çivi çakar, çakar mı kızarsın,

Böyle oynanan, oyunlara mı kızarsın,

Söyle neye kızarsın, nelere kızarsın.

Yârin derdiyle yanar, yanar kızarsın,

Belki seninle oynuyor buna kızarsın,

Kızarsın, kızarsın da içinemi atarsın,

Söyle neye kızarsın, nelere kızarsın.

Çarşı, pazarda, fiatlara mı kızarsın,

Haberler hep yalan ona mı kızarsın,

Oynanan oyunları sen  bozamazsın,

Söyle neye kızarsın, nelere kızarsın...', 'Yollar uzarsa sen yollara mı kızarsın, Yârini eller almış, onlara mı kızarsın, Alanı bırak sen, ayırana mı kızarsın, Söyle neye kızarsın, ne...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soyle-neye-kizarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliler Delimidir Velimidir', 'deliler-delimidir-velimidir-yusuf-onder-bahceci-vqp1o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazı deliler delimidir, yoksa velimidir,

Bazıları akıllı geçinir, akıllıya deli denir,

Bazıları ise kendini böyle deliliğe verir,

Bazı deliler delimidir, yoksa velimidir.

Bir deli güzel konuşuyorsa bilki velidir,

Deli diye, onlarla dalga geçen delidir,

Bilelim ki Allah''ın evi, velilerin kâlbidir,

Bazı deliler delimidir, yoksa velimidir.

Veli kimdir dersen, veli Allah dostudur,

Kâlpleri Allah''ın aşkıyla yanar da durur,

Veliler hep gezer, Allah diyenleri bulur,

Bazı deliler delimidir, yoksa velimidir.

İnsan veli olsa ne olur deli olsa ne olur,

Hele sevdiğinden ayrıl bakayım ne olur,

İnsan çok akıllı olsa bile, belki deli olur,

Bazı deliler delimidir, yoksa velimidir....', 'Bazı deliler delimidir, yoksa velimidir, Bazıları akıllı geçinir, akıllıya deli denir, Bazıları ise kendini böyle deliliğe verir, Bazı delil...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/deliler-delimidir-velimidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fıkra', 'fikra-yasar-tezel-7vt6h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adı muzır

Dolaşır vızır vızır

Müstehcen ve açık

Bir Namık Kemal

Bir Hoca Nasreddin

Temel-i içine kattık

Karmakarışık

Ne kadar varsa

Bektaşiyle devam

Hep aynı yakıştırma

Uydurma ve saçma

Hakaret değildir,erdemlik

Bize yakışmalı,

Değerlere saygılı olmalı

Fıkra', 'Adı muzır Dolaşır vızır vızır Müstehcen ve açık Bir Namık Kemal Bir Hoca Nasreddin Temel-i içine kattık Karmakarışık Ne kadar varsa Bektaşiy...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/fikra-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Leyla Ol', 'sen-leyla-ol-sahin-yilmaz-xj2fu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgili, başını gögsüme yasla, 

Sevgimiz bir ömür bitmesin asla, 

Lütfeyle bade sun ilahi tasla, 

Nasibimse birkaç yudum alayım, 

Sen Leyla ol, ben Mecnunun olayım. 

Gözlerin kalbime çaglasın tezden, 

Dudakların güle benzesin hazdan, 

Sevdanın tarifi sorulsun bizden, 

Derd-i aşkın dermanını bulayım, 

Sen Leyla ol, ben Mecnunun olayım. 

Aşkımız, aşkların mihengi olsun, 

Onun ne benzeri, ne dengi olsun, 

Bütün şarkıların ahengi olsun, 

Bestem sensin, perde perde çalayım, 

Sen Leyla ol, ben Mecnunun olayım. 

Hastalara şifa versin bakışın, 

Ilhamı ol her oyanın, nakışın, 

Gülistanı utandırsın kokuşun, 

Rüzgar vursun, nerde isen bileyim, 

Sen Leyla ol, ben Mecnunun olayım. 

Bülbüller bizleri şakıyıp ötsün, 

Ask üstüne söylenecek söz bitsin, 

Melekler sevgime şahitlik etsin, 

Çok beklettin, artık çağır geleyim, 

Sen Leyla ol, ben Mecnunun olayım.', 'Sevgili, başını gögsüme yasla,  Sevgimiz bir ömür bitmesin asla,  Lütfeyle bade sun ilahi tasla,  Nasibimse birkaç yudum alayım,  Sen Leyla ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-leyla-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münişe özel 2', 'munise-ozel-2-munevver-senol-2kzl2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '12:11:00 

 Aktif Yap | Pasif Yap | Bu Görüşü Sil

 

Şiir: 385509 - Münişe özel 

Yazan: Aydın Sevgi-...Şiir_Adamı 

Gönüllerin Sultanı Münevver Şenol, 

Sen,güzel ol,iyi ol ve sağlıklı ol, 

Bizler senin can-ı gönül dostlarınız, 

Allah(c.c) ''a yalvar,bizlere duacı ol. 

... 

Senin dualarına ihtiyacımız var...aslında hepimizin birbirimze dua ihtiyacı var...dua ile kalın..huzurlu olun.. 

Saygılarım ve sevgilerimle.', '12:11:00   Aktif Yap | Pasif Yap | Bu Görüşü Sil   Şiir: 385509 - Münişe özel  Yazan: Aydın Sevgi-...Şiir_Adamı  Gönüllerin Sultanı Münevver...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/munise-ozel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık', 'pismanlik-munur-atakul-5dufp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçak mahkum gibi düştüm ocağına

Çok muhtacım bu gün sıcaklığına

Sarmanı bekleyemem boş kucağına

Eşiğe bir sedir sersende olur

Affımı olurmuş yaptıklarımın

Hükmünü görmedim taptıklarımın

Temyizi bozulmuş ağır suçlarımın

Cürmünü boynuma versende olur

Hiç şüphe etmedim bana sevginden

Öperim başka ele değmemiş ellerinden

Küfrü bile bilmeyen aziz dilinden

Yüzüme yağmurlar döksende olur

Hükmü olmasa bile beni son kez dinle

Ölmek arzusundayım senin ellerinle

O hazreti Ömer adaletinle

İlmeği boynuma çeksende olur

Onurun yakıştı hep omuzlarına

Gururun engeldir belki arzularına

Koynunda beslediğin yavrumuz hatırına

Seni son defa alnından öpsemde olur

Matakul

23/05/1999 nakkaştepede gece yarısı', 'Kaçak mahkum gibi düştüm ocağına Çok muhtacım bu gün sıcaklığına Sarmanı bekleyemem boş kucağına Eşiğe bir sedir sersende olur Affımı olurmu...', ARRAY['Türk Edebiyatı','Şiir','Münür Atakul']::text[], 8.5, '{"poet":"Münür Atakul","poet_slug":"munur-atakul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/pismanlik-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Sen Hali', 'askimin-sen-hali-ahmet-turan-altunsu-45jom', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir şehir gibiydi adeta kadın…

neonların ışıklarıyla yarışıyordu gözlerinin parıltısı.

varoşların kirli ve karmaşık sokaklarına inat,

renkli ve kalabalık caddeleri kadar görkemliydi; 

sanki, tek başına kendisiydi kâinat! 

bir şehir gibiydi adeta kadın...

eteklerinden dökülen asalet,

farkındasız çiğneniyordu kalabalık izdüşümde.

adımları kıvrak, bakışları tatlı sert; 

aklım esrikleşiveriyordu her görüşümde…

bir şehir gibiydi adeta kadın...

yılların yok edemediği sahaflar sokağında,

tezgâhlarda sergilenen ciltli kitaplar kadar dolu

ve yıllanmış belleğinde koca bir tarih sergileyen

ak saçlı Gülbeyaz nene’m kadar Anadolu! ..

bir şehir gibiydi adeta kadın...

bir yüzünde uygar kahvehanelerin entelektüel yansıması,

diğer yüzünde kıraathanelerin can çekişen melali...

hasılı, sıradan bir sevgili değildi kadın; 

aşk sözcüğümün, memleketim kokulu “sen” hali! ..

.....................16.02.2006 / Güdül / Ankara

..........................Ahmet Turan Altunsu

ahtual'' den......', 'bir şehir gibiydi adeta kadın… neonların ışıklarıyla yarışıyordu gözlerinin parıltısı. varoşların kirli ve karmaşık sokaklarına inat, renkli...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/askimin-sen-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-ada-ada-h64bk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbin hep kalbimde

Sıcaklığın içimde

Sevsende sevmesende 

Biliyorum sen bende bende sende

Geçmiyor bu acı

Geçmiyor zaman

Zaman ne amansız bir düşman

Umut tükeniyor

Bense boşluklarda savaştayım

Seviyorum seviyorum işte

Ama çaresiz gölgelerle başbaşayım

Yinede tükenmiyor 

Bitmiyor sevgim

Bitmesin hiç bitmesin

Yaşama sebebim hayatın anlamı

Umudum tükenmesin

Belki bir gün diyemiyorum....

Belki bir gün demeyi umut ediyorum', 'Kalbin hep kalbimde Sıcaklığın içimde Sevsende sevmesende  Biliyorum sen bende bende sende Geçmiyor bu acı Geçmiyor zaman Zaman ne amansız b...', ARRAY['Türk Edebiyatı','Şiir','Ada Ada']::text[], 8.5, '{"poet":"Ada Ada","poet_slug":"ada-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umut-253-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Nazire-1', 'sevgiliye-nazire-1-mualla-yasdiman-xbxzw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uçup gitsin bu sevda yıldızlara geceye

Serenâdlar akmıyor gönülden pencereye

Sevginin tarifini sığdırdın tek heceye

Sitem etsem ne çıkar gelmeyen sevgiliye', 'Uçup gitsin bu sevda yıldızlara geceye Serenâdlar akmıyor gönülden pencereye Sevginin tarifini sığdırdın tek heceye Sitem etsem ne çıkar gel...', ARRAY['Türk Edebiyatı','Şiir','Mualla Yasdıman']::text[], 8.5, '{"poet":"Mualla Yasdıman","poet_slug":"mualla-yasdiman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgiliye-nazire-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Görür Ne Konuşurum', 'ne-gorur-ne-konusurum-yusuf-onder-bahceci-864rv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazıları sevdiğinden ayrılır, ama sevdiği yanında olur.

Bazıları sevdiğini söyleyemez sağa, sola döner durur,

Bazıları çok sever, geceleri bildiği bütün duaları okur,

Suçum çok mu büyük, ne seni görürüm, ne konuşur.

Bazıları suç işler mahkum olur, yatar, çıkar ve kurtulur,

Bazıları sevmez ama diliyle çok sevdim diye konuşur,

Bazıları param çok, her şeyi satın alırım derde tutuşur, 

Suçum çok mu büyük, ne seni görürüm, ne konuşur.

Bazıları hüsnü kuruntu, beni çok sevdi diye zanneder,

Bazıları ise platonik aşktır başı hep bulutlarda gezer,

Önder yıllar yılı seni görmemiş de böyle şiirler yazar,

Suçum çok mu büyük, ne seni görürüm, ne konuşur.', 'Bazıları sevdiğinden ayrılır, ama sevdiği yanında olur. Bazıları sevdiğini söyleyemez sağa, sola döner durur, Bazıları çok sever, geceleri b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-gorur-ne-konusurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemile', 'cemile-munur-atakul-y3nlx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen eğme başını eğdiren gelsin

Ben zülfikar oldum tavımsa sensin

Kaldır şu başını semaya değsin

Töre pazarında köle cemile

Yaşın ondört`müydü onbeş`mi yoksa

Lanet`te haklısın töreniz buysa

Ben iblis zannettim babanmış oysa

Nasıl kıydı sana böyle cemile

Başlığı biçilmiş elli koyuna

Birde beşibirlik beyaz boynuna

Babası akranlı almış koynuna

Genç yaşta boğulmuş döle cemile

Dertli yüreğine sevgili gömmüş

Bahar çağlarında zemheri görmüş

Kısacık ömürü altıya bölmüş

Her parça intizar söyle cemile

Satılık aşkların o son durağı

Sıyrılmış gönlerden umut bayrağı

Şimdi bir ehilin mahsun çırağı

Vicdansız kulları eyle cemile

Kul kula yaparmı bu zalimliği

Verilmiş eline pembe kimliği

Kimlere şarlatsın dert imbiğini

Yüreğinde dönmüş göle cemile

Yafta takmayalım bir tek nazarda

Cemileler satılıyor pazarda

İnsan olan yürek yanar bu narda

Arzuyla düşmedi dile cemile

Yaradan yazmaz`ki böyle kaderi

Bu küçük yavrunun bumu ederi

Yırtılmış hayası bitmiş hederi

Yüksek kaldırımda çile cemile

Hep satılık olmuş çirkin pazarda

Babası dik dursun o dar mezarda

Terazisi adil ince mizanda

Alırsın hakkını ele cemile

Matakul

12/12/2005 bir hayat kadınına', 'Sen eğme başını eğdiren gelsin Ben zülfikar oldum tavımsa sensin Kaldır şu başını semaya değsin Töre pazarında köle cemile Yaşın ondört`müyd...', ARRAY['Türk Edebiyatı','Şiir','Münür Atakul']::text[], 8.5, '{"poet":"Münür Atakul","poet_slug":"munur-atakul","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/cemile-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrendi Artık', 'ogrendi-artik-ada-ada-gbj8d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnanmak çok zor geldi 

İnsanların şerefsizliğine

Yaşayıpta görünce

İnandım ben herşeye

Şeytanıda tanıdım ben

Meleğide

Ama tanıdık artık

Bende yüreğimde

Hani söz geçmezdi yaa

Yüreğime

Öğrendi işte 

Şeytanıda meleğide', 'İnanmak çok zor geldi  İnsanların şerefsizliğine Yaşayıpta görünce İnandım ben herşeye Şeytanıda tanıdım ben Meleğide Ama tanıdık artık Bend...', ARRAY['Türk Edebiyatı','Şiir','Ada Ada']::text[], 8.5, '{"poet":"Ada Ada","poet_slug":"ada-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogrendi-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakar aLMAZ aŞK', 'cakar-almaz-ask-oguzkan-bolukbasi-gt4g4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğruları doğuran yanlışlara hayran oluyorum

Her kaza sonrası bir doğru çıkıyor

Hasarı sürücüye ait bir dünya olsa neyse

Karşıdan gelen çarpıyor sana

Yolcu kaybediyor

Neyi varsa

Öteki kaçıp gidiyor

Var mı böyle trafik alemde

Sen arabayı iyi sürsen de bir acemi

Gelip seni alt üst edecek

Ve bunu gülerek seyredecek

Başına henüz bir şey gelmeyenler

Son gülen iyi gülecek diye bir şey yok', 'Doğruları doğuran yanlışlara hayran oluyorum Her kaza sonrası bir doğru çıkıyor Hasarı sürücüye ait bir dünya olsa neyse Karşıdan gelen çarp...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cakar-almaz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-ada-ada-33n37', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül pervane

Gönül divane

Gönül kırık

Gönül değil kendinle barışık

Gönül sever

Gönül üzer

Gönül çeker

Gönül bazen kaçar gider

Gönül umut

Gönül ışık

Gönül ahhh bu gönül

Gönül karmakarışık', 'Gönül pervane Gönül divane Gönül kırık Gönül değil kendinle barışık Gönül sever Gönül üzer Gönül çeker Gönül bazen kaçar gider Gönül umut Gö...', ARRAY['Türk Edebiyatı','Şiir','Ada Ada']::text[], 8.5, '{"poet":"Ada Ada","poet_slug":"ada-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-ada-ada-6aruj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün dolduruyorum aslında

Ruhum her gün biraz daha

Biraz daha anlıyor gerçeği

Hüzün, yalnızlık bir tokat gibi

Vuruyor kalbime, ruhuma, bedenime

Aramak boş 

Oldu bitti bir yerde

Dönüş yok yok.

Kaldım bıraktığın yerde...', 'Gün dolduruyorum aslında Ruhum her gün biraz daha Biraz daha anlıyor gerçeği Hüzün, yalnızlık bir tokat gibi Vuruyor kalbime, ruhuma, bedeni...', ARRAY['Türk Edebiyatı','Şiir','Ada Ada']::text[], 8.5, '{"poet":"Ada Ada","poet_slug":"ada-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sizi-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Günlerime Dönebilsem', 'eski-gunlerime-donebilsem-yusuf-onder-bahceci-ycqzc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski günlerime, bir dönebilsem,

Yine, senin hâyalinle olabilsem,

Kâlbimle değil, dilimle desem,

Eski günlerime, bir dönebilsem.

Sadece, gözlerine mi bakarım,

Sevmiyorum de bakim yakarım,

Kolundan tutup koluma takarım,

Eski günlerime, bir dönebilsem.

Gözlerine bakar kâlbini yakarım,

Kelebekler gibi, güllere konarım,

Seni alamazsam yanar, yanarım,

Eski günlerime, bir dönebilsem.

Şimdiyse sadece şiir yazıyorum,

Dertli yazınca, hemen ağlıyorum,

Kâlbimle Allah''ıma yalvarıyorum,

Eski günlerime, bir dönebilsem...', 'Eski günlerime, bir dönebilsem, Yine, senin hâyalinle olabilsem, Kâlbimle değil, dilimle desem, Eski günlerime, bir dönebilsem. Sadece, gözl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eski-gunlerime-donebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Nazire--3', 'sevgiliye-nazire-3-mualla-yasdiman-x15j2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdam bir fırtınadır

Gönlüm durulmayacak

Bu hasretin hesabı

Mahşerde sorulacak', 'Sevdam bir fırtınadır Gönlüm durulmayacak Bu hasretin hesabı Mahşerde sorulacak...', ARRAY['Türk Edebiyatı','Şiir','Mualla Yasdıman']::text[], 8.5, '{"poet":"Mualla Yasdıman","poet_slug":"mualla-yasdiman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgiliye-nazire-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkettiğimde', 'farkettigimde-nevher-i-smail-yilmaz-hwb3h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'farkettiğimde yaşlanmıştım

belki biraz uslanmış

çaptan düşmüş

ama hala

içimdeki o ateş var gibi

sanmışken

olan olmuş

ben ne desem

ne söylesem

çoktan paslanmıştım

önemlisi ne bilirmisin

kimler için üzülmüş

ağlanmış

diye 

şöyle bir baktığımda

geriye

en güzel yıllarımda

belki biraz deneyimsiz

biraz parasız pulsuz 

ama

gelecek var ya

o ateş kor gibi

sanmışken bile

bile bile

ben yanmışım

önemlisi ne bilirmisin

kimler için eğilmiş

kimlere dost diye

kanmışım.', 'farkettiğimde yaşlanmıştım belki biraz uslanmış çaptan düşmüş ama hala içimdeki o ateş var gibi sanmışken olan olmuş ben ne desem ne söylese...', ARRAY['Türk Edebiyatı','Şiir','Nevher İsmail Yılmaz']::text[], 8.5, '{"poet":"Nevher İsmail Yılmaz","poet_slug":"nevher-i-smail-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/farkettigimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Kararınca', 'gun-kararinca-nuray-acar-2el8v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün kararınca

Gölgeye dönüşüyor

Beden

Düşünceler aydınlanıyor 

Işık veriyor 

Kim bilir kime

Kiminle 

Kim olduğumuzu bile

Umursamadığımız 

Anlarda 

Gölgesiz bedenlere

Zamanın akmadığı

Anlara sürüklenirken', 'Gün kararınca Gölgeye dönüşüyor Beden Düşünceler aydınlanıyor  Işık veriyor  Kim bilir kime Kiminle  Kim olduğumuzu bile Umursamadığımız  An...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gun-kararinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam', 'anlatamam-nurhan-gokturk-c0icn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şarapla aşkın bitiminde,			

Benim için inançsız bir ölüm başladı.			

Yakamozlarla atışırken,			

Gözlerinden gelen bir yıldırgınlık,			

İçimi bir ezdi ki,			

Anlatamam.			

			

Semada yıldızlar birer, ikişer yanarken			

Bir adam düşle, loş sokaklarda yürüyen,			

Adımını her atışında,			

Senden gelen bir hoş seda ile			

Nasıl kahrolur,			

Anlatamam...

Nurhan Göktürk

(07Kasım1977/Niğde)', 'Şarapla aşkın bitiminde,			 Benim için inançsız bir ölüm başladı.			 Yakamozlarla atışırken,			 Gözlerinden gelen bir yıldırgınlık,			 İçimi...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anlatamam-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elinden Tutsam', 'elinden-tutsam-orhan-eren-uncu-r43qp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk yoksunu yüreğim sevmişti

Değerini bilmeden, zamanında

Sevdiğini de düşürmüştü yürekten

Şimdi her günüm yalnız, 

Bir eziyet

Kimi ararım bilinmez

Elinden tutsam, düşürürmüyüm,Seni? 

Belki de gün açar yarin

Yüreğimde bir kıpırtı

Sonbaharın yağmurları da geldi geçti

Kaç kaç yollar tükendi

Elinden tutsam,ıslatırmıyım,Seni? 

Yürümek istedim,yalnız

Kaçar adımlarla 

Sarılmışsın  bana

Yüreğime kar yağmış,zamanında

Hava ayaz, dona çalmış

Elinden tutsam üşütürmüyüm,Seni? 

15.02.2006

15:35', 'Aşk yoksunu yüreğim sevmişti Değerini bilmeden, zamanında Sevdiğini de düşürmüştü yürekten Şimdi her günüm yalnız,  Bir eziyet Kimi ararım b...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elinden-tutsam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşça kal', 'hosca-kal-volkan-i-ncel-n2i37', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorum hoşça kal

Sana bir tek ceketimi bırakıyorum

Hatırlarmısın ilk buluşmamızda giymiştim

Ve o akşam elimi ilk tuttuğun yer var ya

Dikkat ettin mi orda da  üzerimdeydi

Beraber simit ve çay ikram etmiştik sana

Çakmak cebinde senin hediyen çakmak var

Benden çok ceketim sevinmişti hediyene

Çünkü en çok onunlaydı

Hani seni otobüs durağından uğurlamıştım ya evine

Orada da   üzerimdeydi

Dirsekleri yıpranmıştır kusura bakma

Masaya yaslıyordum seni düşünürken

Ve sana yazarken

Dün  en son giydim onu 

En sevdiğin parfümümü sıktım

Şişe bitercesine

Buluştuğumuz yerlere götürdüm onu

Bir simitte ona ısmarladım

Son bir sigara yaktım 

O vermek istemese de hediyenle

Düğmesini dikmiştin hatırlar mısın

İpi iğneye ben takmıştım

Hatırla hepsini 

Simidi,çayı,sigarayı

Sana olan sevgimi 

Ve hoşça kal', 'Gidiyorum hoşça kal Sana bir tek ceketimi bırakıyorum Hatırlarmısın ilk buluşmamızda giymiştim Ve o akşam elimi ilk tuttuğun yer var ya Dikk...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hosca-kal-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli', 'deli-volkan-i-ncel-79w5h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana deli diyorlar

Neymiş? Sevda çekmişim

Bana abdal diyorlar

Neymiş? Türkü yakmışım

Bana hırsız diyorlar

Neymiş? Hakkım almışım

Bana yazık diyorlar

Neymiş? Acı çekmişim

Bana hep sus diyorlar

Neymiş? Gerçek söylemişim

Bilmem ben bu feleğin

Neyini neylemişim', 'Bana deli diyorlar Neymiş? Sevda çekmişim Bana abdal diyorlar Neymiş? Türkü yakmışım Bana hırsız diyorlar Neymiş? Hakkım almışım Bana yazık ...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deli-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DüşünMEK ve YAŞAMak...', 'dusunmek-ve-yasamak-erhan-demir-d8vzn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '...dÜŞÜN-MEK 

BAZEN 

GÜZELDİR

HAYATI 

SEVDİRİR...

DÜŞÜNMEKLE 

YAŞAMAK 

ARASINDA

BİR ŞİİR 

FİLİZLENİR...', '...dÜŞÜN-MEK  BAZEN  GÜZELDİR HAYATI  SEVDİRİR... DÜŞÜNMEKLE  YAŞAMAK  ARASINDA BİR ŞİİR  FİLİZLENİR......', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dusunmek-ve-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi yavruları', 'kedi-yavrulari-volkan-i-ncel-t1h3j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki küçük kedi yavrusu

Girmişler odama

Gecenin tam ikisi

Sabahın kaçıydı bilmem

	

Çıkmışlar yatağımın üstüne yan yana

Bir o yana,bir bu yana

Yuvarlanıyorlar

Umarsızca

Sıkıldılar

Biri tırnağını taktı çarşafa,çekti

Bir gözü siyah,diğeri renkli

Öteki kuyruk peşinde

Önce kendininki 

Sonra öteki

Nefes almam gerekti

Almasa mıydım

Oyunlarını bozdum bilmeden

Bozmasa mıydım', 'İki küçük kedi yavrusu Girmişler odama Gecenin tam ikisi Sabahın kaçıydı bilmem 	 Çıkmışlar yatağımın üstüne yan yana Bir o yana,bir bu yana...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kedi-yavrulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz.Muaz Bin Cebel R.A.', 'hz-muaz-bin-cebel-r-a-mikdat-bal-lvr1v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ashabı kiramın  büyüklerinden

Büyük kahramandı Muaz Bin Cebel

Helalı, haramı en iyi bilen

Vera’da sultandı Muaz Bin Cebel

On sekiz yaşında  Müslüman olmuş

Genç yaşında kalbi imanla dolmuş

Mekkenin fethinde bizzat bulunmuş

Mükemmel insandı Muaz Bin Cebel

Medineli idi Ensari idi

İslam kalasının hisari idi

Tek başına huküm tasarı idi

Fetva da yamandı Muaz Bin Cebel

Bedir, uhud, hendek, bir çok savaşta

Her zaman öndeydi her zaman başta

Hayberin fethine gitti genç yaşta

İslama kalgandı Muaz Bin Cebel

Şeref tekvadadır ne renk ne şekil

Bunda tekva yüce hem engin akıl

Huneyn savaşında Mekke’ye vekil

Genç yaşata atandı, Muaz Bin Cebel

Hem Mekke emiri hem de hocası

Kur’anı öğrendi ondan nicesi

İslama hizmetti gündüz gecesi

Ne büyük ummandı, Muaz Bin Cebel

Yemene atandı vali olarak

Toplanan zekatı bizzat alarak

Bazı kavgalara çözüm bularak

Allah’tan ihsandı, Muaz Bin Cebel

Resulullah onu yolcu ederken

Bu son görüşmemiz Muaz’a derken

Hep ağladı durdu yolda giderken

Gerçeğe inandı, Muaz Bin Cebel

Nebi sordu neyle edersin amel

Dedi Kur’an sünnet fetvama temel

Yoksa aklım ile, İslam mukemmel

Kur’ana uyandı, Muaz Bin Cebel

Mikdatî ashabın izinden gelen

Hakkı söyleyenler hakkı hak bilen

Hakka uyup böyle yaşayıp ölen

Böyle bir imandı Muaz Bin Cebel', 'Ashabı kiramın  büyüklerinden Büyük kahramandı Muaz Bin Cebel Helalı, haramı en iyi bilen Vera’da sultandı Muaz Bin Cebel On sekiz yaşında  ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hz-muaz-bin-cebel-r-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Düğünlerini Çok Severim', 'koy-dugunlerini-cok-severim-yusuf-onder-bahceci-wk4vo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Köy düğünlerini çok severim çünkü renkli olur,

Köy düğünlerinde gelenek ve  görenekler olur,

Köy düğünlerinin sağdıcı, kivresi, kahyası olur,

Köy düğünlerini çok severim çünkü renkli olur.

Gelin arabasının yolunu keserler, para isterler,

Gelin evden çıkarken kapıyı örter para isterler,

Gelin çıkarken sandığa oturup da para isterler,

Köy düğünlerini çok severim çünkü renkli olur.

Damadın abisini suya basar, kahkaha atarlar,

Gençler ise sin sin oynarlar, bilekleri bükerler,

Gelin ve damadın anne babası dünek dizerler,

Köy düğünlerini çok severim çünkü renkli olur.

Köyün yiğitleri, pehlivanları gelir güreş tutarlar,

İşte bu bölümde genç kızları hayalleri kurarlar,

Çaktırmadan, usulünce sevilene göz kırparlar,

Köy düğünlerini çok severim çünkü renkli olur.

Köy düğünleri üç gün ve üç gece devam eder,

Gelin alıp gelinir, düğün yemeği keyifle yenilir,

Misafirler dua eder, Allah''a Ismarladık denilir,

Köy düğünlerini çok severim çünkü renkli olur.', 'Köy düğünlerini çok severim çünkü renkli olur, Köy düğünlerinde gelenek ve  görenekler olur, Köy düğünlerinin sağdıcı, kivresi, kahyası olur...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/koy-dugunlerini-cok-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-hasan-kilic-a90mn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben artık gidiyorum,azığım acı tütün

Notalar avutmuyor içimdeki türküyü

Artık hayat dengine düşmüyor helal sütün

Ah kalbim,acılara bulanan martı tüyü

Ben artık gidiyorum,varsın unutulayım

varsın bulut rüzgara sevdalı kalsın biraz

Islığımı deli bir okyanusa salayım 

Belki biraz durulur içimde üşüyen yaz.', 'Ben artık gidiyorum,azığım acı tütün Notalar avutmuyor içimdeki türküyü Artık hayat dengine düşmüyor helal sütün Ah kalbim,acılara bulanan m...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kılıç']::text[], 8.5, '{"poet":"Hasan Kılıç","poet_slug":"hasan-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gidiyorum-212-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Nazire--4', 'sevgiliye-nazire-4-mualla-yasdiman-8ma2g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Toylar senin meyler benim bu gece

Keyif senin özlem benim bu gece

Bitsin bu aşk- sevda eğlen gönlünce

Akıl yoldan çıktı anla bu gece', 'Toylar senin meyler benim bu gece Keyif senin özlem benim bu gece Bitsin bu aşk- sevda eğlen gönlünce Akıl yoldan çıktı anla bu gece...', ARRAY['Türk Edebiyatı','Şiir','Mualla Yasdıman']::text[], 8.5, '{"poet":"Mualla Yasdıman","poet_slug":"mualla-yasdiman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgiliye-nazire-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖTÜR BENiDE SEVDALARINA', 'gotur-benide-sevdalarina-mehmet-emin-yesilmen-a2dfb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yudum daha içsem kar edermi,

Unuttururmu eskileri.

Bilmiyorum..,

Ama bir umut işte,

Bir anlık olsa bile..,

Nerden geldik,

Niye geldik,

Madem gelmişiz kahpe yaşam,

Yap bir kıyak işte

Benide al deli rüzgarlarına..,

Benide balık yap,

Benide götür tenhalara.

Ve delice olsun herşey.

Masum bir katilin haykırışıdır bu..,

Anla artık be yaşam,

Götür benide sevdalarına..,', 'Bir yudum daha içsem kar edermi, Unuttururmu eskileri. Bilmiyorum.., Ama bir umut işte, Bir anlık olsa bile.., Nerden geldik, Niye geldik, M...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gotur-benide-sevdalarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HATIRLATMAYACAK SENi', 'hatirlatmayacak-seni-mehmet-emin-yesilmen-i573l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'An gelecek

Yokluğundaki anlar dahi mutlu olacak

Her tarafı mutluluğa bürüyecem

Tüm mutsuzluk yok olacak

Adlandırma umut dolu hayatlar olacak..,

İstemediğimi yakacam,

Küllerden istediklerim olacak.

Şarkılar bestsliyecem mavi ateşte

Sen hiç olmayacaksın notalarda..,

Sadece düşlerimde ki kalacak bende

Gerisi uçuyor olacak ateşte, yok olup.

Bir daha sen gelmiyeceksin aklıma

Hiç olmamış sayacam.

Ne anılar, ne de hatıralar

Yalan olarak bilecem..,

Senin ne düşüneceğini bilmek istemiyecem

Ortak arkadaşlarımız olmayacak

Hiç bir şehir, hiç bir mekan

Hatırlatmayacak seni bana..,

Birden susacaklar bütün konuşabilenler.

Ne acı diye düşünenler olacak,

Güzel sevgilerin yok oluşuna dair.

Acıları paylaşmıyacaklar sıcakken,

Çünkü ben bu şehirde olmıyacam..,', 'An gelecek Yokluğundaki anlar dahi mutlu olacak Her tarafı mutluluğa bürüyecem Tüm mutsuzluk yok olacak Adlandırma umut dolu hayatlar olacak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hatirlatmayacak-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARANFiL', 'karanfil-mehmet-emin-yesilmen-0t38h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum ki ellerin karanfil kokuyor.

Uzaksın bana, belkide çok uzak.

Ama hissedebiliyorum,

Alabiliyorum karanfilin kokusunu..,

Gökten inen damlalar,

Yağmur değil aslında.

Uzakları yok eden mucize,

Ve duygu taşıyıcılarıdır..,

Özlüyorum her üşüdüğümde,

Ve de düşündüğümde hep ıslanıyorum,

Bir gün gelipte beni kurulayasın diye..,

                     (Yegenim Türkan''a)', 'Biliyorum ki ellerin karanfil kokuyor. Uzaksın bana, belkide çok uzak. Ama hissedebiliyorum, Alabiliyorum karanfilin kokusunu.., Gökten inen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karanfil-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜRÜMEK iÇiN YÜRÜYORUM', 'yurumek-icin-yuruyorum-mehmet-emin-yesilmen-gx0uf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürümek için yürüyorum bu gece.

Biran yürüdüğümü bile bilmeden,

Sadece seni düşünüyorum

Yağmur beni okşarcasına yağıyorken..,

Sen benimle değilsin ama,

Caddeler benim bu gece

Bu gece ki konuşkanlığım üzerimde

Ve hiç kimseyle konuşmaya dalıyorum..,

Korkuyorum geldikçe aklıma sensizlik,

Ve de sensizlikten doğan sessizlikten..,', 'Yürümek için yürüyorum bu gece. Biran yürüdüğümü bile bilmeden, Sadece seni düşünüyorum Yağmur beni okşarcasına yağıyorken.., Sen benimle de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yurumek-icin-yuruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-hasan-kilic-rb1zi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilinmez aşk ateşi nasıl yanar

Belki karanlığa gömülür

Belki esrarengize bürünür.

....ve belki yaşanır tatlı bir aşk...', 'Bilinmez aşk ateşi nasıl yanar Belki karanlığa gömülür Belki esrarengize bürünür. ....ve belki yaşanır tatlı bir aşk......', ARRAY['Türk Edebiyatı','Şiir','Hasan Kılıç']::text[], 8.5, '{"poet":"Hasan Kılıç","poet_slug":"hasan-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-550-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huylu Gönül', 'huylu-gonul-mustafa-benkli-vgl0g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir garip gönlüm var ki, bilmem, deli midir ne? 

Bazen bana râm olur, bazen tersine gider! 

Öyle bir içtendir ki, girebilsen içine,

Dünya gelse üstüne, kendi yoluna gider! 

.............Deli dolu huyundan garip gönlüm vaz geçmez...

Bakarsın, birden sönmüş, ne naz bilir, ne niyâz; 

Şayet coşar, çağlarsa, ne çağ, ne zaman dinler! 

Fasıldan, bir fasıla, sazlarda karar kılmaz; 

Gönlümün tellerinde bazen kendini dinler! 

.............Herkes geçer huyundan garip gönlüm vaz geçmez...

Kışın ayaz gününde gönlüne uçmak düştü; 

Sanki kendine rakip seçmişti martıları,

Denizin dalgasına kapılıp akşam üstü

İçime dolduracak sandım kıpırtıları! 

.............Dedim vazgeç huyundan garip gönlüm vaz geçmez...

Bazen de çok uzlaşır, kendindeyse imtiyaz; 

Beni kendimden alır, Menzillere götürür! 

Bir nefeslik an bulup, nefeslensem de biraz,

Aklım başımdan alır, fırıldağa döndürür! 

.............Desem kurtul huyundan garip gönlüm vaz geçmez...

Estetik anlayışı çok garip gelir bana; 

Ben kaş ile göz desem, o der ki gönül teli,

Ben deşem ki kardelen, o der ki gül-i rânâ; 

Garip yönelişleri bazen çıldırtır beni! 

.............Ve bu garip huyundan garip gönlüm vaz geçmez...', 'Bir garip gönlüm var ki, bilmem, deli midir ne?  Bazen bana râm olur, bazen tersine gider!  Öyle bir içtendir ki, girebilsen içine, Dünya ge...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/huylu-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N''olur İyi ol!', 'n-olur-i-yi-ol-rukiye-ozkat-akejb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öylesine ağır ki yaşam! 

Ya ben hep en çok yara aldığım yerden bakıyorum hayata! 

Deli gibi yazmak; eski defterler gibi..

Yüreğim şimdi öylesine ağrıyor ki; sol tarafım yok sanki.

Çünkü canımın canı yanıyor,

Çünkü ufacığım,tertemizim,yaramazım üzülüyor.

Sığmıyorum hiçbiryere ve lanet olsun ki burası değil bulunmak istediğim! ! 

Gözüm gözüne değsin,

Elim yüreğine ulaşsın,

Gözyaşlarım içine serpilsin,

İyi olsun! 

Dayanamam; iyi olsun! 

Yapamam..

Ey hayat! İstediğimiz yerlerin kapılarını açmadın bize,

Tam doğru anahtarı bulduk sandık,ya yerler değişmişti ya da kilit..

Ağrıyor bedenim,

Sol kolum yine benim değil sanki..

Herşey de ufacığım,herşeyde yaramazım..

Sen özüme girdin,

Sen ben,ben senim artık.

Acını en derinde,sevincini en içten hissediyorum ben.

N''olur üzülme! 

N! olur iyi ol!', 'Öylesine ağır ki yaşam!  Ya ben hep en çok yara aldığım yerden bakıyorum hayata!  Deli gibi yazmak; eski defterler gibi.. Yüreğim şimdi öyle...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/n-olur-iyi-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılarıma tutunurken canım yanıyor..', 'anilarima-tutunurken-canim-yaniyor-rukiye-ozkat-69v83', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben küçüktüm,herşey kocamandı.

Hayallerim öylesine büyüktü ki boyum yetişmiyordu görmeye.

Ben küçük ellerimle yağmur damlalarını topluyordum

Gri-yeşil sokaklarda..

Aslında ne kadar saf,büyümemiş bir çocuk 

Ve ne kadar ürkek olduğumu..Bu hayata dair.

Sevinçlerin bir,acıların ayrı hikayeleri..

Ne ırmak sularında yüzdürdüğüm hayallerim

Ne de içimi coşturan sevinçlerim var artık.

Ellerim öylesine titriyor ki

Anılarıma tutunurken canım yanıyor...', 'Ben küçüktüm,herşey kocamandı. Hayallerim öylesine büyüktü ki boyum yetişmiyordu görmeye. Ben küçük ellerimle yağmur damlalarını topluyordum...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anilarima-tutunurken-canim-yaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdüm!', 'buyudum-rukiye-ozkat-4zg7y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birgün büyürüm sandım.

Büyüdüm! dediğimde kollarımda uzanacak güç kalmamıştı

Ne de uzanılacak hayaller artık!', 'Birgün büyürüm sandım. Büyüdüm! dediğimde kollarımda uzanacak güç kalmamıştı Ne de uzanılacak hayaller artık!...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/buyudum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayacağım Seni! ...', 'arayacagim-seni-kadir-albayrak-zmln7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arıyorum! .. Ama bilmiyorum! 

Nerede bulacağım seni? 

Bir kağnının tekerinde mi,

Boncuk boncuk terlerin nefesinde mi? ..

Ya da kara sabanın darmadağın ettiği

Kapkara toprakların arasında mı? ..

Sahi; 

Nerede bulacağım seni? ....

………….

Belki gökkuşağının sekizinci renginde

Belki kör bir kuyunun o “katranlı zevkinde”

Kim bilir belki de bulunduğun yer,

Korkulu ümitlerin yaşandığı” o mahşer! ...”

Nerede bulacağım seni? ....

Delikli kuruş için kalkan avuçlarda mı,

Mevcudiyetini kaybetmiş yamaçlarda mı? 

Bir mezar üstünde ki eğreti taş,

Ya da taşa eğilmiş mahzun bir baş! ..

Belki buharlaşıp uçmuş bir damla göz yaşında

Belki de eceli misafir etmenin telaşında! 

Sahi; 

Nerede bulacağım seni? ....

………..

Dalgaların yavruladığı köpükler arasında mı,

Kıyıların sırılsıklam kumlarında mı? 

Namluyu terk eden merminin düşen kovanında mısın

Amaçsız yürüdüğü hedefin rotasında mı? 

Nerede? .... Nerede bulacağım seni? ..

Tozu dumana katmış çöllerde misin,

Dünya’ya gelmemiş “döllerde mi? ..”

Belki bir yüzün yaşlı çizgilerinde

Belki de yanık bir çığlığın ezgilerinde

Bestesi olmayan bir şiirin cümlesinde misin,

Bir gönlü paramparça etmenin hevesinde mi? ..

Sahi; Nerede,

Nerede bulacağım seni? ...

…………..

Üstüne adres yazılmamış bir zarfın içindesin belki! 

Kim bilir! .. Belki karanlık çoktan kucaklamıştır seni! ..

Dikenle kaplı toprak yığınlarının altında mısın,

Erişemediğim göklerin en yüce katında mı? ...

Zamanla dargın saatin son durduğu yerde mi,

Kuruyan yaraya basılmış neşterde mi? ...

Neredesin? ....

Bilmiyorum ama,

Arayacağım seni! ......', 'Arıyorum! .. Ama bilmiyorum!  Nerede bulacağım seni?  Bir kağnının tekerinde mi, Boncuk boncuk terlerin nefesinde mi? .. Ya da kara sabanın ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/arayacagim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyitimsi Sözler 1', 'beyitimsi-sozler-1-huseyin-avdic-i1u2c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyitimsi Sözler 1

En Büyük İsim

Yüce Rabb''in isimleri içinde en büyük güzel isim, ''rahmet'' ve ''acıma''dır.

Aşk ve sevgiyse sonra gelir, çünkü insanlık daha çok acınmaya muhtaçtır.

-----

Not: Yukarıdaki redifle sonlanan kafiyesiz mısralara ''Beyitimsi Sözler''

adını verdim. Nasıl ilham ediliyorsa, ben de o şekilde bırakıyorum.

Bu sözleri sanatla falan bozmak istemiyorum. Zaten kafiye avcılığı 

yapacak fazla zamanim da yoktur. Şair ustalarım, bu sözleri -eğer

mümkünse- serbest şiirle sanatlı şiir arası yeni bir tür kabul etsinler.

Veya şiir dışı da bırakılabilir. 

Berlin, Şubat 2006.', 'Beyitimsi Sözler 1 En Büyük İsim Yüce Rabb''in isimleri içinde en büyük güzel isim, ''rahmet'' ve ''acıma''dır. Aşk ve sevgiyse sonra gelir, çünk...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beyitimsi-sozler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamdan Alacaklı Olmak..! !', 'yasamdan-alacakli-olmak-h-hikmet-esen-m46ad', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seneler, 

Senelerce yıllandı, 

Anılar mahzeninde.. 

Hüznü damıtırken; 

Yapayalnız 

Gecelerde; 

Hava ayaz mı ayaz, 

Soluğum 

Üşümede... 

Yüreğim, 

Peşi sıra rüzgarların, 

Savrulurken ufuklara; 

Gitmeleri seviyor gönlüm, 

Bazen Altınoluk''un, 

Çakıl taşlarına, 

Bazen de 

Kazdağı''nın, 

Kekik kokularına... 

Sonu geliyor elbet ömrün. 

Yaşamdan vazgeçmek, 

Herşeye veda etmek, 

Kolay mı sanki..! ? 

Seneler, 

Elbette eskitti bedenimi, 

Ama düşlerim, 

Yaşlanmadı ki..! ! 

19/02/1999', 'Seneler,  Senelerce yıllandı,  Anılar mahzeninde..  Hüznü damıtırken;  Yapayalnız  Gecelerde;  Hava ayaz mı ayaz,  Soluğum  Üşümede...  Yüre...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yasamdan-alacakli-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-neslihan-uzel-fppee', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buruk güzelliğine sığındım sonbaharın 

Yazdan kalanlarımı avuttum.

Sarı yapraklara yazdım özlemlerimi, savurdum

Bin hasretle çırpındım, boğuldum 

Unuttum baharın uzak nefesini, güz oldum

Geçti bir mevsim daha tıpkı bir an gibi

Kuytu köşelerde saklı mutluluk hicran gibi

Küflü hatıralar kaldı sanki hiç yoklar gibi

Yazılmamış bir şiir, söylenmemiş ad gibi

Alamadım ki bir tad  yaşadığım lahzadan

Bulutlara yükledim hasretleri durmadan

Arayacak bu gönül bıkmadan, usanmadan

Son yaprak sararıp düşene dek ağaçtan.', 'Buruk güzelliğine sığındım sonbaharın  Yazdan kalanlarımı avuttum. Sarı yapraklara yazdım özlemlerimi, savurdum Bin hasretle çırpındım, boğu...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Üzel']::text[], 8.5, '{"poet":"Neslihan Üzel","poet_slug":"neslihan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umit-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-aysun-onat-m1mfj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canım ister canın ister,

Elimde olsa gelirim der! 

Neden bilmiyorum  beni ona çeken bir şeyler var,

Gizemli bir sesi var.

İnanmak istiyorum sevgisine beni tutan ne? 

Zaman gelecek beni de anlayacak.

Kader çıkardı seni benim karşıma,

Alladı pulladı gözümü  boyadı.

Parlak bir yıldız gibi,

Uykuma girer oldu,

Sabahlar olmasa da olur.

Umudum beklemek…

Zaman gelecek beni de anlayacak.', 'Canım ister canın ister, Elimde olsa gelirim der!  Neden bilmiyorum  beni ona çeken bir şeyler var, Gizemli bir sesi var. İnanmak istiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Onat']::text[], 8.5, '{"poet":"Aysun Onat","poet_slug":"aysun-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canim-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eli Kulağında Umutlar', 'eli-kulaginda-umutlar-h-hikmet-esen-akqww', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşam,

Bir türkü,

Bir şiir belki; 

Hüzzama dönüşmeden yel,

Haydi gel, 

Aç yüreğini

Yarınların doğum sancılarına.

İki büklüm tutkularla,

Esir olmak yaşama,

Kolayı bence işin..

Oysa,

Eli kulağında umutlara,

Gebe sokaklar başlar,

Köşebaşlarında..

17/08/2001', 'Yaşam, Bir türkü, Bir şiir belki;  Hüzzama dönüşmeden yel, Haydi gel,  Aç yüreğini Yarınların doğum sancılarına. İki büklüm tutkularla, Esir...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eli-kulaginda-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşer Günü', 'mahser-gunu-cemil-aygen-rdad8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Babamız 

Şen

Hayat doluydu

Nasıldı kelimeleri söyleyişi

Gülüşü nasıldı

Hatırlayın

Babamız

Yürek sıcaklığıydı

Gözleri masmavi

Hayatın yeni bir yaşamıydı

İyide 

Niye kendi başına

Alıp gitti kendini

Babamız

Hatırladığımız...

Oysa babamız

Hatırladığımız yanımızdaki

Sevgimiz... Sevgilimiz kalmalıydı

Biz neler yaptık da

Bizi bırakıp gitti Babamız

Neyi vardı acaba 

Anlıyamadığımız.....', 'Babamız  Şen Hayat doluydu Nasıldı kelimeleri söyleyişi Gülüşü nasıldı Hatırlayın Babamız Yürek sıcaklığıydı Gözleri masmavi Hayatın yeni bi...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mahser-gunu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca Olamadık', 'karinca-olamadik-yusuf-onder-bahceci-u0jxq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karınca olamadık bir türlü,

Hep cır cır böceği gibi cır,

Gören dostlar hâllere acır,

Karınca olamadık bir türlü.', 'Karınca olamadık bir türlü, Hep cır cır böceği gibi cır, Gören dostlar hâllere acır, Karınca olamadık bir türlü....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/karinca-olamadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-cemil-aygen-axoqx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen yaşlarda iken

Benim bir Öğretmenim vardı

Adı.. Hem öğretmenim

Hem Babamdı

Koca bir sınıfın içinde bana

Onun oğlu bile olsam

Bir talebe gibi bakardı

Beni çok severdi ''o''

Ben orta aldığım bir gün

Gizli gizli gözleri yaşardı

Çok ama çok üzüldüm

Orta aldığıma değil 

Onun ağladığına

Sonra söz verdim

Ve bir daha 

Ne öğretmenimi 

Ne de öğretmen olan Babamı

Hiç ağlatmadım.....', 'Sen yaşlarda iken Benim bir Öğretmenim vardı Adı.. Hem öğretmenim Hem Babamdı Koca bir sınıfın içinde bana Onun oğlu bile olsam Bir talebe g...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kizima-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-cemil-aygen-413xt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim sevgilim

Oturmuş daktilo başına

Yine yazıyor

Dalmış derinlere de

Acaba ne yazıyor

Bir ara kaldır başını bak

Bak yürek gözlerinle 

Senin için bu kalp nasıl çarpıyor

Bir soluklan hele Durakla

Takılıp kalma yazdıklarınla

Kimse şefin müdürün

Yormasın seni

Hiç değilse bir an beni sorduklarında 

Bak bahar pencerede

Papatyalar çiçek açmış

Yemyeşil olmuş tüm dünya

Bırak yazmayı nefes al

Sana seni seven 

Yüce bir yürekten

Koca bir selam var....', 'Benim sevgilim Oturmuş daktilo başına Yine yazıyor Dalmış derinlere de Acaba ne yazıyor Bir ara kaldır başını bak Bak yürek gözlerinle  Seni...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgilim-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle değil mi?', 'oyle-degil-mi-mikdat-bal-chu4q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başkasının unu için fareler

Kavga eder,birbirini pareler

Akıl edip bir el ele vereler

Hepsine yeterdi, Öyle değil mi? 

Sömürülüyoruz yanarken içler

Nemelazım dedik yol aldı piçler

Biz birlik olsaydık yabancı güçler

Çekip de giderdi Öyle değil mi? 

Okuyup öğrensek kimiz biz neyiz

İlmin ışğından alsaydık feyiz

Ozaman anlardık, patron hem beyiz

Düşmanlık biterdi, Öyle değil mi? 

Kuru kuru gider yaş da yaş olsa

Aranan adalet, iş ve aş olsa

Eşitlik olsaydı herkes baş olsa

Kim koyun güderdi, Öyle değil mi? 

Mikdatî der artık birlik olmalı

Kavgadan kaçarak ilme dalmalı

Bu dağınıklığa çare bulmalı

Bacamız tüterdi, öyle değil mi?', 'Başkasının unu için fareler Kavga eder,birbirini pareler Akıl edip bir el ele vereler Hepsine yeterdi, Öyle değil mi?  Sömürülüyoruz yanarke...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyle-degil-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne AŞK Ne Ben Ne de Sen', 'ne-ask-ne-ben-ne-de-sen-gul-yazganarikan-g7u99', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tutunduğun ve tutulduğun

Yalnızca kendinsin..

Tutundukların bir saç teli inceliğinde

Ayaklarını kesince yerden kalıverir elinde..

Tutuldukların, yanılgıları yüreğinin 

Kırık bir aynanın yansımaları,

Bir seyir defterinin limon suyuyla yazılmış yazıları

Diliniz aynı olsa da yüreğiniz değil aynı,

Sen bir kadın, o bir erkek

Sen bir erkek, o bir kadın

Kim demiş bir elmanın yarıları

Oysa farklı algılarınız, düşleriniz, sevgiye direnişleriniz...

Oysa birimiz elmaysak, belki üzüm, belki nar diğerimiz...

Belki nahoş lezzetiniz, belki ekşi, ya da bayacak kadar tatlı...

Ama olsun insanız hepimiz.... şart mı bir elma olmak, ikiye ayrılmak

Aşk farklı bir ağaç, bir dalında büyürken elmalar, diğer dalında ekşili narlar...

Bir dalı baharken belki, diğer dallarına tutulur karlar...

Belki çürür, kurur ağacın bir dalı diğer yanında belki çağla zamanı...

Aşk karmaşık bir durum ve karmaşık erkeğin ve kadının algıları

Aşk,kadın, erkek, meyve derken unuttum işte..

Ne diyordum ben! 

Kısaca..............................................

Anlaşılır gibi değiliz, NE AŞK, ne ben, ne de sen....', 'Tutunduğun ve tutulduğun Yalnızca kendinsin.. Tutundukların bir saç teli inceliğinde Ayaklarını kesince yerden kalıverir elinde.. Tutuldukla...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ne-ask-ne-ben-ne-de-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gerektiği Gibi Allaha Ram Olalım!', 'gel-gerektigi-gibi-allaha-ram-olalim-i-brahim-halil-demir-27kbb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgili aziz kardeş,gel gerektiği gibi olalım Allaha ram! 

Vallahi başka türlüsü bu fani dünyada bizlere haram,

İman merheminden başkasıyla şifa bulmaz yaram,

Gelmesinler fazla üstüme sonra dayanılmaz olur naram.

Kokar ülkemin her metre karesinde şehitlerin kanı buram-buram,

Olmasa şerefli insanlarımız söylesene ben buralarda nasıl duram.

Gerekirse yüce dağ başlarında seve-seve çatırlar kuram,

Kul olamazsam şayet, kendi silahımla kendi kendimi vuram.

Yalancı bir cennet olan ülkemin nimetleri takdire şayandır,

Bunları idrak etmeyen şeytanın atıyla cehenneme kayandır.

Allahtan korkan, Peygamberden utanan, ömür günlerini sayandır,

Menfeati için doğruları konuşmayan ise lanetlenmiş şeytandır.

Aklı selim düşünen her insan,canı gönülden eder bunları takdir,

Eşine benzerine çok az rastlanan atalarımız tarih kitaplarında tek dir.

Bu kadar asimile olduğumuz için belki de hakkımız iyi bir kötektir,

Kağnılarla bomba taşıyan ana ve ninelerimize saygılı olmayan dönektir.

16/02/2006', 'Sevgili aziz kardeş,gel gerektiği gibi olalım Allaha ram!  Vallahi başka türlüsü bu fani dünyada bizlere haram, İman merheminden başkasıyla ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-gerektigi-gibi-allaha-ram-olalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müzeyyen', 'muzeyyen-cemil-aygen-mapbp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani o incecik

Çıtı pıtı bir kız vardı

Mahallede

Hatırladınmı

Ulan elini tutsan 

Kırılırmı bu kız dediğin

Saçları taa beline kadar inen

Kısık gözleri kalın dudakları olan

İsmi Müzeyyendi

Hatırladınmı

Ulan bu kız kocaya gitse 

Sabahına ölür dediğin

İşte ben o kızla evlendim

O kızla be...Arkadaşım Mesut

Şimdi görsen

Tombul bir karım varya O

O Müzeyyen,İnanki o....', 'Hani o incecik Çıtı pıtı bir kız vardı Mahallede Hatırladınmı Ulan elini tutsan  Kırılırmı bu kız dediğin Saçları taa beline kadar inen Kısı...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/muzeyyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalim Yildiz', 'hayalim-yildiz-cem-veysel-gul-ny795', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saat sabahin dördü,

Gecenin ortasindayim.

Yine hayalimdesinizGökyüzünde yildizdan yildiza

Atlayarak dolasiyorum tarzan misali.

Cok yildiz kaydi bu dünyadan

Her biri ayri parlaklikta bizi aydinlatiyor.

Gögün ayri ayri köselerinden simdi.

Kimi cok sevdigimiz,

kimi sevgilimiz,

Kimi özledigimiz,

Kimi umutla bekledigimiz,

Kimi fikirleriyle bize yol gösteren,

kimide saygiyla andigimiz.

Her pencereden baktigimda

Ayri ayri parlaklikta ve büyüklükte isik saciyor.

Kimisi tek tek

Kimisi samanyolu coklugunda ve kardesce.

Yavas yavas soluklastiginizda bakiyorum ki tan agarmis.

Gün basliyor yeniden.

Isci isine,köylü tarlasina gidecek,

Burjuva icin gün ile gece zaten belirsiz.

Her giden gün yeni bir geceyi beraberinde getirecek,

Ve yeni sevdalara yelken acacagiz.

Ben yeniden ve daha parlak görecem sizi.

Dalindan cicek toplar gibi

Yildizdan yildiza dolanip duracagim

Yeni hayallerle...

Cem Veysel Gül

06/02/2006//04:55

Schwäbisch gmünd', 'Saat sabahin dördü, Gecenin ortasindayim. Yine hayalimdesinizGökyüzünde yildizdan yildiza Atlayarak dolasiyorum tarzan misali. Cok yildiz ka...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayalim-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdinden Neyleyimki', 'derdinden-neyleyimki-mehmet-sait-akkus-840mg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dilsizim sevdan lal etti

Yordu beni bir hal etti

Ummanda beni sal etti

Yar derdinden neyleyimki

Tükettin yürümez oldum

Kör ettin göremez oldum

Dil kestin diyemez oldum

Yar derdinden neyleyimki

Sevdana daldım bir kere

Tadını aldım bir kere

Aşkına yandım bir kere

Yar derdinden neyleyimki

Vuslata nail olursam

Aşkına mail olursam

Bu aşka kefil olursam

Yar derdinden neyleyimki', 'Dilsizim sevdan lal etti Yordu beni bir hal etti Ummanda beni sal etti Yar derdinden neyleyimki Tükettin yürümez oldum Kör ettin göremez old...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derdinden-neyleyimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler İstedi Diye Yürek Ağlamaz', 'gozler-i-stedi-diye-yurek-aglamaz-selahattin-yetgin-31b9a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağların en yücelerine çıkıyorum yine. Karlı yücelerde bağdaş kurup oturacağım. Sevginin hikayesini anlatacağım yıldızlara. Şu kısacık ömrü yalınayak yürümüşüm, farkında olmadığım güzellikleri elimin tersiyle itmiş, yaldızlı güzelliklere kanmışım. Sevmenin kolay olmadığı bu yerkürede kırılgan şarkılarla dost, vefasız insanlarla sırdaş olmuşum.

Yağmurlar yağmış mevsimlerce üstüme. Öfkelerimi toprağa tohum gibi ekmiş, her baharda açan öfke çiçeklerinden buket buket derlemişim onlara. Sahte gülücüklere kanmış, canımı verdiklerime kendimi hırpalatmışım. Yılmamışım, her fırtınada çadırımı toplamış yeniden çıkmışım dağlara. Rüyalarda gerçeği, günlük yaşamda sahtelikleri yaşamışım her an. Umutlarımı vermişim çocuklara. Onlara söğütten düdükler yapıp çığlıklarında mutlanmış, deli ırmak kenarlarında huzurla uyumuşum.

Mevsimler dönmüş durmadan. O mevsimlerin hızıyla öğünmüşüm un gibi. Çilelerimi yumaklara sarmış, yüreğimin katran nasırına göz yaşımı belemişim. Kaypak sevgileri gönlüme merhem niyetine sürüp acıların zehrini içmişim kana kana. Gözlerimdeki yaşı anılarla silip, sahte sevgilere ağıtlar yakmışım yıllar yılı. Yaşamın isimsiz tortularını biriktirmişim seni seven deniz yüreğimde.

Bu yıllarca ovalarına akan boz bulanık çaylarım da durulacak elbet. Aka aka ülkenin ovalarını yerle bir edecek,  millerin seni bana getirecek. Denizlere ulaşacağım, mavi umutlarım olacak benim de. Yıkılan, sular altında kalan kentlerim görecekler gök yüzünü. Göz yaşlarım boşuna akmayacak bir daha. Bunca sevmişliğim, sana yanıp yakılmışlığım da bitecek gülüm. Sonbaharda yaprağını döken her ağaç beni anlatmayacak bir daha.

Bir it gibi yaralarımı yalaya yalaya döneceğim hayata. Kanatlarımın üstünde evreni taşıyacak kadar güçlü olacağım. Tüm denizlere olta atıp melez zevklerimi tatmin edeceğim. Kokunu da atacağım içimden ve aşkın gibi sensizliğe de alışacağım. Yüreğindeki kirli döşeklerden bir şafak vakti kalkıp hiç bilmediğin, beni asla bulamayacağın uzak yüzyıllara yürüyeceğim.

Her gün yeniden okudum bana yazdığın son oyunu. Kimseyi karıştırmadım aktörlüğüme. Papatya falları açtım sevginin yapraklarını yolarak. Nereden başladıysam hep sen çıktın karşıma. Kendime alkışlar sundum beni izleyenlere inat. Sevgilermiş düşünceleri harmanlayan, yalnızlık daha sana doymadan kalkmış soframdan. Ellerimin yara bereleri sana isyanımdan, gönlümün, sana vurulmuşluğumun dışa yansıması anlayacağın.

Sen de kaç buralardan. Rüzgarının bana ulaşamayacağı yerlere çevir atının dizginlerini. Senden ne haber, ne de selam gelmesin istersen. Yüreğindeki yoksul özlemlere sarıl dilersen. Gözlerinden dökülen yaşları hiç görmeyeyim. Kısır sevgilerle gününü gün et. Sancılı yürüyüşlerle yolları kat et. Köşe başlarına korkak bakışlar atma sakın. Savurup saçlarını geriye, bir daha bakma gözlerime. Yanından sessizce gelip geçen bir yabancıyım bundan sonra. Dudağımdan dökülen ayrılık şarkılarını bile duyamadıktan sonra gönlümün en kutsal yerinde kalsan da artık fark etmez. Biliyorsun ki gülüm, ‘gözler istedi diye, yürek ağlamaz’! .', 'Dağların en yücelerine çıkıyorum yine. Karlı yücelerde bağdaş kurup oturacağım. Sevginin hikayesini anlatacağım yıldızlara. Şu kısacık ömrü ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gozler-istedi-diye-yurek-aglamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmışım O Yar İle Sevdası Arasında', 'kalmisim-o-yar-i-le-sevdasi-arasinda-i-brahim-halil-demir-mc2fo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalmışım o yar ile sevdası arasında,

Bulmuşum gençliğimi kaşları karasında,

Gizlemişim koca bir sevdayı gönül yarasında,

Çat kapı gelsen ne olur bir gece yarısında.

Şaşırmış kalmışım sevdanın en tehlikeli uçurumlu yollarında

Düşen aklar ayan beyan görünüyor şakaklarda.

Hep sen varsın sessizliği bozan naralarda,

Söylesene durarmıyım hiç sen yok ken buralarda.

Çok aramışım seni sevdanın çıkmaz sokaklarının karanlığında,

İstemiyerek kırmış olabilirim ölesiye sevdiğim yari dargın bir anımda

Çok güller ekmişim aşkın tarlalarına gönül saflığımla,

Tam doyasıya gülecek iken bırakmadı felek yine kaldı kursağımda.

Yoluna baş koyduğum bu beden her şeye hazır dünden,

Bindirmişler sevda gelinini aşkın atına, geliyor düğünden

Kesmek istediler zalimler bu aşkın suyunu kökünden,

Başaramadılar.zira seviyoruz birbirimizi canı gönülden.

Çektim sevda silahını en sevinçli bir anımda sıktım üç kez havaya,

Vazgeçmem kolay kolay,çünkü gönül vermişim ben bu davaya.

Çekmediğim sıkıntı işitmediğim kaba söz kalmadı bu sevda yolunda,

Teslim oldum zira tüketti beni deşilen sevda yarası kanaya- kanaya.

13/02/2006', 'Kalmışım o yar ile sevdası arasında, Bulmuşum gençliğimi kaşları karasında, Gizlemişim koca bir sevdayı gönül yarasında, Çat kapı gelsen ne ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kalmisim-o-yar-ile-sevdasi-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firavun Ask Kasidesi', 'firavun-ask-kasidesi-i-brahim-ethem-uzun-vhmlp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yuzlerce kadin avucumda yuzse de

Kiralicem sensin sadece

Nice kitap devirsem de

Ezberledigim kitap sensin sadece

Binlerce hece dudaklarimdan suzulse de

Gazelim sensin sadece

Yuce sema kara bulutlarla ortulse de

Gunesim sensin sadece

Omrumce sehir sehir gezsem de

Baskentim sensin sadece

Fikrimce kulturlerle sevissem de

Kulturum sensin sadece

Mevsimlerce dem gecse de

Zamanim sensin sadece

Benimle siir yazmayi denesene

Yoksa sen kelimelerim misin

Yoksa sen ilhamim misin

Yoksa sen dudagim misin

Yoksa sen sesim misin

Yoksa sen sihrim misin

Yoksa sen kalemim misin

Yoksa sen defterim misin

Yoksa sen ben misin

Nasil baska bir yere tasinacagim

Koskumu kalbine kurmussam

Nasil askindan intihar edecegim

Sen beni hala yasatiyorsan

Omur boyunca seni sevecegim

Yine de sevecegim seni 

Firavunlarin aska imani gibi

Gozlerimi ezeli yumsam bile', 'Yuzlerce kadin avucumda yuzse de Kiralicem sensin sadece Nice kitap devirsem de Ezberledigim kitap sensin sadece Binlerce hece dudaklarimdan...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Uzun']::text[], 8.5, '{"poet":"İbrahim Ethem Uzun","poet_slug":"i-brahim-ethem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/firavun-ask-kasidesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengarenk Yaşlarla Ağlayan Kalem', 'rengarenk-yaslarla-aglayan-kalem-murat-demir-fwbnt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bende değil ki herkeste elem

Kime sorsam diyor bozuldu alem

Rengarenk yaşlarla ağlayan kalem

Seni tutan eller ne imiş meğer

Yazan da çizen de benim diyen sen

Neler oldu neler seninle bilsen

Belki çıldırırsın belki de görsen

Seni kapan eller ne imiş meğer

Gönül istiyor ki binde bir bile

Adam gibi adam varsa sergile

Adalet evinde delalet ile

Seni satan eller ne imiş meğer

İnsan ayırmadan dönüp hepsine

Soran da çıkmıyor neden ise ne

İkiye ayırıp masa üstüne

Seni atan eller ne imiş meğer

Ezelsiz, ebedsiz çürümüşlere

Dünyasını nifak bürümüşlere

Çetli çetrefelli bunca işlere

Seni katan eller ne imiş meğer', 'Bir bende değil ki herkeste elem Kime sorsam diyor bozuldu alem Rengarenk yaşlarla ağlayan kalem Seni tutan eller ne imiş meğer Yazan da çiz...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/rengarenk-yaslarla-aglayan-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözünde Yaşla Gel', 'gozunde-yasla-gel-yusuf-onder-bahceci-fsv0w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün yollarında, güller görürsen,

Güller kırmızı olacak bunu bilirsen,

Uzun yıllar oldu sen bana gelirsen,

Gözünde yaş, bağrında taşla gel.

Bu Dünya''da sevdim ama olmadı,

Kâlbim, bir türlü aradığını bulmadı,

Sevdiğim de beni birgün sormadı,

Gözünde yaş, bağrında taşla gel.

Beni düşündüğünde kâlbim bilirdi,

Hâyalinle gözümden yaşlar gelirdi,

Kâlbim burkulur, tüylerim ürperirdi,

Gözünde yaş, bağrında taşla gel.

Şimdi yanımda yoksun ne olacak,

Sanki benim kâlbim mutlu olacak,

Yokluğunla kâlbim hep ağlayacak,

Gözünde yaş, bağrında taşla gel...', 'Bir gün yollarında, güller görürsen, Güller kırmızı olacak bunu bilirsen, Uzun yıllar oldu sen bana gelirsen, Gözünde yaş, bağrında taşla ge...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozunde-yasla-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarlabaşı', 'tarlabasi-bestami-kurtulus-fufki', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tarlabaşında bir hayalet geziyor

Martıların bile uyumadığı bir gecede

Onu herkes kendisi sanıyor

Her birimizden bir günah çalıp

Tersaneden denize atıyor

Yazgımız yalnızken mi gelir aklımıza

Yaşarken unutur muyuz nasıl sevdiğimizi

Nakaratlardan başka yok muydu bu şarkıda

Ölüm de korkutmazsa artık geceyi

Yok yere heba etmişiz gençliğimizi

Son seferinde, son yolcular gibi

Otobüsün kirli koltuklarında rahat

Her şehirde bir haliç olmalı

Her haliçte bir unkapanı

Ve şehirde kucaklar dolusu kabahat

Hayalet tarlabaşında geziyor

Martılar hala uykusuz

Çay karartmış içimizi

Her nefeste katran 

Her sevda bir sonrakinden korkusuz', 'Tarlabaşında bir hayalet geziyor Martıların bile uyumadığı bir gecede Onu herkes kendisi sanıyor Her birimizden bir günah çalıp Tersaneden d...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tarlabasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir Baksaydın', 'bana-bir-baksaydin-bestami-kurtulus-2y8hp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana bir baksaydın görecektin

Ben mavi tutkunu bir buluttum

Sağanağımla okşardım saçlarını

Sonra süzülürdüm koynuna

Bir baksaydın bir bilseydin

Ardınca maviyi terkedecektim

Bana bir verseydin ellerini

Ben yeşil vurgunu bir güneştim

Eski evinizin yolunda kaç kez

Duvar çatlağına çiçekleri ben ekmiştim

Anlasaydın, ah bir bilseydin

Baharımdan vazgeçecektim', 'Bana bir baksaydın görecektin Ben mavi tutkunu bir buluttum Sağanağımla okşardım saçlarını Sonra süzülürdüm koynuna Bir baksaydın bir bilsey...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-bir-baksaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Çocukluğum', 'yeniden-cocuklugum-turkan-yakin-lq0kh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nihayet bir bisikletim olmuştu.

Ama yaşımda kırktı hani.

Önemli değildi,

Çocuk ruhluydum çünkü.

Bisikletimi odama yerleştirdim.

Okşadım, sevdim.

Olmadı yetinmedim.

Odamda bisiklete bindim.

Hay Allah! cocuklar gibi şendim.

Tutamadım kendimi,

Bayramlık elbise giymiş gibi.

Heyecanlı ve neşeli,

Bir daha denedim binmeyi.

Düşmüştüm çünkü.

Oturdum güldüm halime,

Hay Allah, çok da komiktim.

Yakışmadı belki ama,

Ne yapayım.

Çok da geç gelmişti,

Yeniden Çocukluğum.', 'Nihayet bir bisikletim olmuştu. Ama yaşımda kırktı hani. Önemli değildi, Çocuk ruhluydum çünkü. Bisikletimi odama yerleştirdim. Okşadım, sev...', ARRAY['Türk Edebiyatı','Şiir','Türkan Yakın']::text[], 8.5, '{"poet":"Türkan Yakın","poet_slug":"turkan-yakin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeniden-cocuklugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Yarımı Kaybettim Bu Şehirde,', 'ben-bir-yarimi-kaybettim-bu-sehirde-nur-demirciler-mgwhl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir yarımı kaybettim bu şehirde,

hiç ummadığım bir anda,

nasıl yaktıysa sevda ateşini yüreğimde,

işte yine öyle bir anda,

gidiverdi....

tam da şu an,

tesellilerin işe yaramadığı,

hatta duymaya bile katlanamadığım

anlardan birindeyim.

Hiç birşey işe yaramayacak biliyorum,

zaman alıştıracak beni yaşananlara,

ben bir yarımı kaybettim,

canımın yandığı,

yüreğimin coştuğu,

sevdamı hapsettiğim öbür yanımı...

16/02/1999

İstanbul', 'Ben bir yarımı kaybettim bu şehirde, hiç ummadığım bir anda, nasıl yaktıysa sevda ateşini yüreğimde, işte yine öyle bir anda, gidiverdi.... ...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-bir-yarimi-kaybettim-bu-sehirde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlıkta Yokluk', 'varlikta-yokluk-musa-yasaroglu-g2q8f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir başlangıçtır doğum

Zamanın ilk safhasında

Dertlerin, kederlerin

Bir dizi olup 

Bir yumak olup

Yürekte tutuşmasında

Bir sebeptir hayat

Acıların katlanmasında

Hasretlerin, özlemlerin

Bir yığın olup

Bir hüzün olup

Gözlerde yaşarmasında

Bir sondur ölüm

Faniliğin son yamacında

Bedenlerin, heveslerin

Bir ümit olup

Bir korku olup

Mahşerde saflaşmasında', 'Bir başlangıçtır doğum Zamanın ilk safhasında Dertlerin, kederlerin Bir dizi olup  Bir yumak olup Yürekte tutuşmasında Bir sebeptir hayat Ac...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/varlikta-yokluk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Trafiği', 'aksam-trafigi-bestami-kurtulus-e5pk5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sayın eşiniz gibi

Sizin de saygın yüzünüzde

Sayısız sabır çizgileri gördüm

Saygısız bir akşam trafiğinde

Benim sizi farketmemi

Siz hiç farketmediniz

Bu benim için de hiç farketmez

Ama haddim değilse de söyleyeyim

Sizin gibi güzel yüzlü insanlar 

Her zaman dünyaya gelmez

Köprü altından süzülüp giden şilep bile

Benden daha yakın elbet dünyanıza

Siz bir heykel gibi susuyorsunuz kocanıza

O da sanki kanıksamış bu huyunuzu

Ama ben iki kapalı camın ardından aldım

Sizin pahalı parfüm kokunuzu

İyi ki benden habersizsiniz

Yoksa suçluluk duyardım

Hani bakışlarımdan diyorum

Rahatsız olabilirsiniz

Lütfen bana kızmayın

Şu sıkışık akşam trafiğinde

Çekilebilir tek şey sizsiniz

Hem şu kısacık tesadüf için 

Ömür boyu anılacak kadar güzelsiniz', 'Sayın eşiniz gibi Sizin de saygın yüzünüzde Sayısız sabır çizgileri gördüm Saygısız bir akşam trafiğinde Benim sizi farketmemi Siz hiç farke...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aksam-trafigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen''li Hayat', 'sen-li-hayat-musa-yasaroglu-52gzr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sen varsın yüreğimde

Bir sen varsın düşlerimde

Her hayalde senin ellerin

Saçlarımı tarıyor

Her an ateş olup gözlerin

Gözlerimi yakıyor

Sen ısıtıyorsun içimi

En soğuk gecelerimde

Sen tutuşturuyorsun

Sönüp gitmiş ruhumu

Bitmeyen hasretlerimin

Son nefesinden önce

Yağmurla yağıyorsun

Güneşle aıyorsun bahçemde

Ben biliyorum artık 

Gün sende, zaman sende, can sende

Ve beni sende yaşatan

Şu kısacık hayatım 

Yalnız senin elinde', 'Bir sen varsın yüreğimde Bir sen varsın düşlerimde Her hayalde senin ellerin Saçlarımı tarıyor Her an ateş olup gözlerin Gözlerimi yakıyor S...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-li-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecedeyim', 'gecedeyim-musa-yasaroglu-0w89d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyi yaşıyorum

Yüreğim buruk

Derin sessizlikte

Mehtaba dalmışım

Bir gülüyor bir ağlıyorum

Gözlerim onda 

O gözlerimde

Döndükçe dönüyor başım 

Dönüşsüz yokuşlarda

Belki de aşığım ona

Ya da hasretim

Sadeliğine

Tutkunum

Güzelliğine

Gecedeyim

Mehtabı yaşıyorum

Gözlerim onda 

O gözlerimde

Yalnız onu görüyor

Yalnız onda  yanıyorum', 'Geceyi yaşıyorum Yüreğim buruk Derin sessizlikte Mehtaba dalmışım Bir gülüyor bir ağlıyorum Gözlerim onda  O gözlerimde Döndükçe dönüyor baş...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecedeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İskitlerde Bir Yaprak Düştü Dalından', 'i-skitlerde-bir-yaprak-dustu-dalindan-bestami-kurtulus-cv03a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İskitlerde bir yaprak düştü dalından

O bir sardunyaydı saksıda

En körpesinde ömrünün

Bir hayalet gibi süzüldü geceye

Fotoroman düşleri naylon torbasında

İşporta tokaları, ucuz terlikleri

Deniz tuzu özleminde yüreği

Ilık su sevdasında terketti

Sülfür pusu bir ankara sokağını

Kaldırıma dalga dalga vurdu 

Ardınca saksı kırıkları

iskitlerde bir yaprak düştü dalından

Yeşili kanıyor soğuk taşlarda

En körpesinde ömrünün', 'İskitlerde bir yaprak düştü dalından O bir sardunyaydı saksıda En körpesinde ömrünün Bir hayalet gibi süzüldü geceye Fotoroman düşleri naylo...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iskitlerde-bir-yaprak-dustu-dalindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar Susmuştu', 'sarkilar-susmustu-bestami-kurtulus-rye5s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şarkılar susmuştu bir gün

Yarı insan iki gölgeydik

Yeşil ürkek adımlarımız

Ankara''da bir tutsak sonbahar

Burnumuzda gülseren kokusu

Güller solmuştu bir gün

İki kırık dünyaydık biz

Çaresiz iki sürgün

Sessizce yürüdük kaldırımları

Dışkapı''da başladı sulusepken

İçimizde hasret yangınları

Yarı insan iki gölgeydik

İki kırık dünyaydık biz

Artvinli''nin pastanesinde

Geçmişi kurcaladık

Gülsereni, yangınları

Dargın anılarımızı barıştırdık

Ve sonra çay vaktinde

Yaralarımızı tanıştırdık

Tükettik geçmişin geçmez saatlerini

O hande peşindeydi bir rüyada

Ben; bir yıldızın kayarken gökte bıraktığı

Yanık bir iz arıyordum

İçimde saklı duran derdimle

Sanki ben de yanıyordum', 'Şarkılar susmuştu bir gün Yarı insan iki gölgeydik Yeşil ürkek adımlarımız Ankara''da bir tutsak sonbahar Burnumuzda gülseren kokusu Güller s...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sarkilar-susmustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Evin Neşesi', 'cocuklar-evin-nesesi-yusuf-onder-bahceci-5h5rc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocuklarımız, onlar evimizin neşesi,

Çocuklar sanki hayatımın bilmecesi,

Konuştukları zaman sadece hecesi,

Anne, babaların gündüzü ve gecesi.

Çocuklar gülünce, anneleri gülüyor,

Baba eve geliyor, çocuklarım diyor,

Yemiyor, yediriyor, içmiyor, içiriyor,

Çocuklarımız,  onlar evimizin neşesi.

Baba, çocuğum adam olacak diyor,

Anne çocuğum terbiyeli olsun diyor,

İkisi de didiniyor, ikisi de, bil eriyor,

Çocuklarımız, onlar evimizin neşesi.

Çocuk olmayan evde sanki matem,

Çocuk olan evlerde, esiyor meltem,

Benim çocuklarım, hepsi bir tanem,

Çocuklarımız, onlar evimizin neşesi...', 'Çocuklarımız, onlar evimizin neşesi, Çocuklar sanki hayatımın bilmecesi, Konuştukları zaman sadece hecesi, Anne, babaların gündüzü ve gecesi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cocuklar-evin-nesesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlere Ağlanılmaz (!)', 'gidenlere-aglanilmaz-seyfettin-bilal-ozluk-r9yhk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son demlerimdeyim

Hala seni yaşamaya çalşıyorum gidenlerin ardından

Gidişin suskun gelişin zaten yoktu

Niye bu hale getirdin bilinmezliklerdeyim

Güneşin doğuşunu özlerken

Şimdi karanlık gündüzlerimle boğuşuyorum...

Gitmemeliydin böyle kaçarcasına

Gitme kal diyemem giden zaten gidecektir

Çünki gidenlere ağlanılmaz ama ben ağlarım

Ama inanmıyorum bu gidişine 

Sen asla yalan söylemezdin

Dedim ya bu gidişine inanmıyorum...

Bir anlık hataysa inanırım

Ama kaçmaksa zamansız bu gidişin

İşta bana en büyük yalanı söyledin

Benim kadınım yalan söylemez biliyorum

Gündüzlerimi bitirmeye ne hakkın vardı

Şimdi karanlık gecelerde yapayalnızım...

Dalgın yürek, şimdi ve kırgın

Sen böyle gitmezdin biliyorum

Gideceğini önceden söylerdin

Gidiyormusun, kaçıyormusun, gelmeyecekmisin

Ya kaçıyorsun ya da...! 

Dedim ya bu gidişine inanamıyorum...', 'Son demlerimdeyim Hala seni yaşamaya çalşıyorum gidenlerin ardından Gidişin suskun gelişin zaten yoktu Niye bu hale getirdin bilinmezliklerd...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidenlere-aglanilmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dersin..!', 'dersin-munevver-duver-nyksb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'El ele tutuştuğumuz, göz göze bakıştığımız

Bazen barışıp, bazen de kavga edip atıştığımız

Birbirimize kırılıp da intihara kalktığımız 

Günleri hatırlayıp ne mutluyduk dersin

Ayrılığımıza bakıp da ağladığımda

İç çekip de yüreğini dağladığında

Beni sevip de bana bağlandığında

Olanlara isyan edip seviyordum dersin 

İyi kötü, günler geçmişti

Şu deli gönlüm, ne çare seni seçmişti

Seninde kalbin beni sevmiş beni istemişti

Diyerek yarınlara ağlarım dersin

İşte kaybettim servetimi, ne büyük eksikmiş

Meğer o beni, deliler gibi sevmiş 

Bırakıp gidince ayrılık neymiş, gör demiş

Kaderine lanet etmiş, en büyük eşek benmişim dersin

Aklın başına geldiğinde beni arar da bulamazsın 

Çevrene dönüp, alık alık düşünceyle bakarsın

Geçmişi düşünüp, yaptıklarına için için yanarsın 

Kendine lanet edip, ne pişmanım dersin

15/8/2000-Saat 15.18

Seyhan ADANA

GÜNEYİN KIZI

Sevgili sekreterimiz Ayşe` ye hediyemdir.', 'El ele tutuştuğumuz, göz göze bakıştığımız Bazen barışıp, bazen de kavga edip atıştığımız Birbirimize kırılıp da intihara kalktığımız  Günle...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dersin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluyum', 'mutluyum-yasar-tezel-g4mdq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güvendiğim için,mutkuyum

Beynindeki kuruntular

Aktı gitti,göründü yolun sonu

Vakti geldi,mutluluğun

Herkes unuttu seni

Bir ben gözlerim yolu

Geleceksin

Evleneceksin benimle

Umutluyum', 'Güvendiğim için,mutkuyum Beynindeki kuruntular Aktı gitti,göründü yolun sonu Vakti geldi,mutluluğun Herkes unuttu seni Bir ben gözlerim yolu...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mutluyum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzlerin', 'i-zlerin-asude-gediz-qbi59', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayallerim küskün, umudum gibi

Hasretim yorgun, örseler tenimi

Düşlerim demlemiyor artık sevgimi

Mazine bak sevgili

susturuyor coşkunun izleri

Benim için sen

Bir bestesin, notaya tutkun

Bir güftesin, sevgiye yeminli

Bir fırtınasın, yerden yere vurdun

Mazine bak sevgili

İzlerin nasıl da coşkun 

Yakarışın hançer. Kanar  yüreğim de

Hazin bakar ufuk, 

Gül ne olur dinle

Tek kurşunla vurulmak çok mudur bir bedende

Maziye bak sevgili 

coşkulu izlerine

Aşka söz verdim ağlamayacağım artık

Yıldızlardan öğütlüyüm sığınmam hiçliklere

Sadece iki kelime, ne olur bütün yü-re-ğin-le 

Mazine bak sevgili

coşkulu izlerine', 'Hayallerim küskün, umudum gibi Hasretim yorgun, örseler tenimi Düşlerim demlemiyor artık sevgimi Mazine bak sevgili susturuyor coşkunun izle...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/izlerin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meltem Esmedi', 'meltem-esmedi-yusuf-onder-bahceci-3cxe4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgarlar içinde, en çok sevdiğim,

Meltem rüzgarıdır hemen söyleyim,

Deniz kenarında, yaylada gezdim,

Bir an olsun Meltem esmedi bana.

Yaşadığım yerlerde kasırgalar esti,

Esen rüzgarlar, hep nefesimi kesti,

Seni seven kâlbim kafeste hapisti,

Bir an olsun Meltem esmedi bana.

Buranın havası, çok latifdir dediler,

Güzel güzel eser cân verir dediler,

Beklediğim Meltemler, esmediler,

Bir an olsun Meltem esmedi bana.

Kâlbimde ne fırtınalar esti, yoksun,

Mahsundu kâlbim senden yoksun,

Tatlı tatlı Meltem, esse de yoksun,

Bir an olsun Meltem esmedi bana...', 'Rüzgarlar içinde, en çok sevdiğim, Meltem rüzgarıdır hemen söyleyim, Deniz kenarında, yaylada gezdim, Bir an olsun Meltem esmedi bana. Yaşad...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/meltem-esmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarim..Bestelenmiş..mp3 formatında Şenerden dinlemek için tıklayın', 'cocuklarim-bestelenmis-mp3-formatinda-senerden-dinlemek-icin-tiklayin-cengiz-suslu-cz7cp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman bana girdap gibi

                                 Başimda dönüp duruyor.

                                 Mesafeler mühim değil 

                                 Ben hep sizi düşünürüm.

                                 Yıldızlar kayar geceyle,

                                 Tüm renkler solar gizlice,

                                 Varlık biter yokta bile,

                                 Ben hep sizi düşünürüm.

                                 Babanız sizinle darda.

                                 Yoksunuz ya kalbim zorda,

                                 Yanımda olmasanızda,

                                 Ben hep sizi düşünürüm

         

                                 Rüzgar eser birden bire,

                                 Kokunuz çöker gönlüme.

                                 Yaşlar biter gözlerimde.

                                 Ben hep sizi düşünürüm.

                                 Sakın sanmayın terkettim.

                                 Her gün sizlerden sözettim.

                                 Yavrularım siz hasretim.

                                 Ben hep sizi düşünürüm.

                                 Sesleriniz kulağimda,

                                 Hıçkırıklar dudağımda,

                                 Inanin sizlayan bagrimda,

                                 Ben hep sizi düşünürüm.

                                 Yaşla dolmuş gözleriniz.

                                 Sitem dolu sözleriniz.

                                 Bu da bizim kaderimiz.

                                 Ben hep sizi düşünürüm.

                                 Gözleriniz dolar bir gün,

                                 Sessizliğe gömülür gün

                                 Ecel gelip çattığı gün,

                                 Ben hep sizi düşünürüm.

                                 Kılınır cenaze namazım.

                                 Nihayet sonlanır savaşım.

                                 Omuzlardayken naaşım.

                                 Ben hep sizi düşünürüm.

                                 Birer birer el değişir.

                                 Ömür sonla yer değişir.

                                 Dostum ağlar el sevinir.

                                 Ben hep sizi düşünürüm.

                                 Para puldan adam olmaz.

                                 Namus, şeref, mertlik yoksa.

                                 Mirasım elle tutulmaz,

                                 Ben hep sizi düşünürüm.

                                 Başlarınız eğilmesin, 

                                 Eller size  sevinmesin,

                                 Doğru olun düşman sevsin.

                                 Ben hep sizi düşünürüm.

                                 Topraklar atılır üstüme,

                                 Çiçekler dikilir postuma,

                                 El verirseniz dostuma,

                                 Ben hep sizi düşünürüm.

  12.02.1990', 'Zaman bana girdap gibi                                  Başimda dönüp duruyor.                                  Mesafeler mühim değil       ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/cocuklarim-bestelenmis-mp3-formatinda-senerden-dinlemek-icin-tiklayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-zahide-handan-erengil-9nlkp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gördüğüm düş müydü,yoksa 

Gerçek miydi anlayamadım.

Dün gece semayı seyrederken,

Yaratanın,bu güzelliklerine 

Hayranlıkla baka kaldım.

Mehtap geceye asılmış,nöbet tutuyor,

Yıldızlar sa göz kırpıp dans ediyordu.

Uzandım bir demet yıldız aldım,

Birden iki yıldız kayıverdi ellerimden.

Ah düşmeden bir tutuversem,

Düşünüyorum,ya kaybedersem? 

Yakalamak için ani bir hamle,

Ne yapsam da tutamıyorum,nafile.

Düşüyoruz sonsuza,bir ben bir de sen

Bir sesimi duyurabilsem,desem ki

Kavuşmayı umutla beklerken,

Ayrılmak niye bu kadar erken? 

Aklıma takılırken sen,

Boşluğa kayıp gidense ben', 'Gördüğüm düş müydü,yoksa  Gerçek miydi anlayamadım. Dün gece semayı seyrederken, Yaratanın,bu güzelliklerine  Hayranlıkla baka kaldım. Mehta...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yildizlar-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerle Muhabbet', 'hayallerle-muhabbet-yasar-tezel-9h8xa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimdeki terettüd,kırgınlık

Umutla beklenilen

Yıkılmayan gurur

Tebessümler başka 

Yüzler donuk

Bu kar beyazı,soğuk

Pazar günleri

Eli boş postacılar

Öldürecek beni

Gözlerimi kapatıyorum

Başka pazarlara

İçimde sıkıntı

Bi garip burukluk

Hoş seda

Gurbetle savaşım

Düşmanlarım da, çokluk

Seni sevmeden yoktu,güzelim', 'İçimdeki terettüd,kırgınlık Umutla beklenilen Yıkılmayan gurur Tebessümler başka  Yüzler donuk Bu kar beyazı,soğuk Pazar günleri Eli boş pos...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayallerle-muhabbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Temyiz ve Kerbela…', 'temyiz-ve-kerbela-naime-erlacin-utkjn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zamandan bilinir sanıklığımız

tanıklık 

hüküm ve beraat

böyleyken neyin izdüşümüdür darağacı 

hangi yangından kalma 

cama sıvaşan bu kalıcı iz

s o r a r ı z! 

mülteci kamplarında içimizin 

iskâna açılır öznel muhaceret

zulümden sorgulanır sorum ve sorumsuzluk

nehirler yılgın akar tuza 

ekmeğe utançla

küskün bir ay dokunur harfleri kırık elifba’ya

meşakkat bebeleri birikir nesebimizde

sabi’den inen kıpkızıl bir tokattır 

yanağımızda tüten

vakitsiz ecellerden o sıra 

istimlâk bedelleri tahsil eder inatçı bir melek

hangi tebaası şiirin

s o r a r ı z! 

vareste tutulur kan ve is’ten? 

en iyi çağ tanır ölüm bandıralı sessizliği

bir dilekçe yazılır 

kapı kulluğunu andırır suskuya 

etimizden düşen 

nafile ve çaresiz bir çığlıktır  t e m y i z! 

sur’dur üflenir soysuz sükûta

sanık 

el pençe divan 

kızarır arifin anlayan yüzü 

haysiyet divanında

içim ağrır iğdiş edildikçe sutur

ki yağmalanmıştı dünden

yarından mesul

bir yudum suya 

hasretliktir bu mânâ

:

söz

K e r b e l a…

(16 Şubat 2006)     – “ 6. Dekad “ Dosyasından…', 'zamandan bilinir sanıklığımız tanıklık  hüküm ve beraat böyleyken neyin izdüşümüdür darağacı  hangi yangından kalma  cama sıvaşan bu kalıcı ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/temyiz-ve-kerbela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solacak Palmiyeler', 'solacak-palmiyeler-hasan-cam-5ji2y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir üniversite kuruluyor, adı bende saklı

Alt yanı kadı köy, üst yanı çamlıca

Otada kaldı acı badem, yer küçük çamlıca

Yani aşağısı antalya, yukarısı palan döken

İçim sızladı, deyimim doğruysa

Sıra sıra dikili palmiyeler, bu bir katliam değilmi

Hatamı ediyor, yanılıyormuyum acaba

Yaradan doğayı, tabiatı yerli yerinde yaratmış

Neden sıcak iklimin ağaçları buralarda sıralanır

Zoraki olmayanı var etmekmi, günah yazık

Onlarca yaşındaki palmiyeler, milyarlar harcanmış

Budanmış dalları, başlarına hasırlar sarılmış

Amaç, güzel görüntü vermek, yapan bir üniversite

Ya birisi tutmaz kurursa, o paralara neler olmazki

Cahil zihniyetim almıyor bunu

Hatamı ediyor, yanılıyortmuyum acaba

Bir fidana can feda, tabiatı koruyana ne mutlu

İnsan değilki doyduğu yerde yaşasın, bir palmiye

Ne kadar, nereye kadar her kış hasırla saracaksınız

Dahası başka güzellikler, sedirler dikilemezmiydi

Örneklerini çok gördük

Büyük alış veriş merkezlerinde, soldu palmiyeler

Kışın buzdur çamlıcanın yolları, palmiyeler ne yapsın

Güzellik, katliammı olmalı, kim dur diyecek

Çamlıcaya, keşke ak deniz iklimini ekebilseydik

Kara denizde görmüştüm

Devlet, canım gürgen, meşe ormanını kazımış

Yerine çam ağaçları dikmiş, tabiatı değiştimi

Asla, o çamlar büyüyene kadar 

Yeniden büyüyen gürgenler, meşeler

Cami minaresini geçmiş, çamlarsa aralarında ufacık 

Tabiatı değiştiremeyiz, doğa yerinde korunmakla olur

Yazık, solacak palmiyeler

Çamlıcaya, keşke sıcak iklimi getirebilseydik

Yazık, solacak palmiyeler

16 02 2006

Ümraniye İstanbul

[email protected]', 'Bir üniversite kuruluyor, adı bende saklı Alt yanı kadı köy, üst yanı çamlıca Otada kaldı acı badem, yer küçük çamlıca Yani aşağısı antalya,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/solacak-palmiyeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-omer-dalman-vdfbq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aslında birçoğu sadece klavye tıkırdatıyor

sırtını kambur yapıp

yanına

üst üste dizdiği kahveleri alıp

leş gibi

kokuşmuş sigaralarını pompalayıp

gözlerini kanlı kanlı pörtletip

hilkat garibeleri gibi 

sadece

ellerinin altındaki o tuşlarla

hiçbir şeyden bahsetmiş olmasalar da

Dünya''ya ulaşabilmenin

faydasız keyfini yaşıyor...

birçoğu

hiçbir şeye el atmasa da

hiçbir derinliğe inmese de

ve inanmasa da

bomboş

tın-tın kafalarla ve kelimelerle

sadece klavye tıkırdatıyor...

(Temmuz 2005)', 'Aslında birçoğu sadece klavye tıkırdatıyor sırtını kambur yapıp yanına üst üste dizdiği kahveleri alıp leş gibi kokuşmuş sigaralarını pompal...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sadece-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyin peşindeyiz?', 'neyin-pesindeyiz-omer-dalman-xipqp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'neyin pesindeyiz? 

Kendimizin...

daha sonra da kendimizi olusturanin belki...

belki birine kavustugumuzda

ikisini de kucak kucaga yakalayacagiz

kim bilir? ..''

(Temmuz 2005)', 'neyin pesindeyiz?  Kendimizin... daha sonra da kendimizi olusturanin belki... belki birine kavustugumuzda ikisini de kucak kucaga yakalayaca...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/neyin-pesindeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç yıl?', 'kac-yil-omer-dalman-5e23h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'daha kaç bardak çay içmem lazım? ! 

kaç tane ''kaliteli geyik muhabbet'' üretmem lazım? 

ve kaç dizi ''zincirleme kahkaha''? ! ..

''sonunda ne tür bir kaz gelecek? '' gibisinden 

umutlu gülücüklerle bakmam lazım o Müdür''e

şu yazılarımı bir kitapta toplatmam için! ? 

daha kaç kere

o Müdür''ün yeniyetme, sahte sarışın

aslında çirkin de, yine de bir havaya bürünmüş

Müdür Sekreteri diye kendini bir miktar yüksek gören 

o Yılık Sekreter kızcağızın masasının önünde kırıtmam lazım? ! 

daha kaç ay, kaç yıl

belki de bir ömür mü dersin

bu arıkovanı gibi Plaza''nın uzak yollarında

burnumu asfaltlara sürtmem lazım? 

kaç yıl? 

kaç yıl daha

ayılara ''dayı'' demem lazım Allah''ım? 

kaç yıl? ..

(Ağustos 2005)', 'daha kaç bardak çay içmem lazım? !  kaç tane ''kaliteli geyik muhabbet'' üretmem lazım?  ve kaç dizi ''zincirleme kahkaha''? ! .. ''sonunda ne tü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kac-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesler sessizliğin düşsel diyarına..', 'sesler-sessizligin-dussel-diyarina-rukiye-ozkat-7fiyu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen ölüm daha kolay gibi gelir.                                                                 İnsan taşıyamaz olur yükünü artık.

Yüreğinin kamburu çıkar sanki.

''işte bunun için açık değil bana ulaşılası yollar'' diye haykırmak isterdim.

Mümkün değil şimdi.

Az önce bir ses vermiştim.

Artık bütün sesler sessizlik! ..

Her akşam kimi hayaller,kimi anılar,kimi sıkıntılar geçiyor

Otobüs camı yollardan.

Bakıyor,görüyor,ilerliyor ama anlamıyorsun nihayetinde.

Herşey beynine,yüreğine öylesine kazınıyor aslında

Ve sorarsan birşey yok ortada.

Ne ince ve keskin çizgiler çiziyorum 

Sözler başka diyarlara

Sesler sessizliğin düşsel diyarına gidiyor

Her sabah ve her akşam..', 'Bazen ölüm daha kolay gibi gelir.                                                                 İnsan taşıyamaz olur yükünü artık. Yüreğin...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sesler-sessizligin-dussel-diyarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varoluşun tek yasası ya da varoluşun çakmaktaşları', 'varolusun-tek-yasasi-ya-da-varolusun-cakmaktaslari-ali-veli-2z41r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seçimler sensen,neden başkaları tercih önceliği olanlardır

Sebep eylemsizlik mi ya da...

Her neyse...

Ben ki sonradan belirsiz olan ya da bütünleşemeyen

Sanki bir zaman sıçraması yaşamış ve

Varolduğum dünya ya yeniden dönmüş...

Ama herşey değişmiş

Bense bir nostaljik idol

Ben kimim,yerim neresi ya da varoluşum artık bana ait değil mi? ! ..

Sıkıştırılmış benliğin dürtüsü yalnızlık

Çıkışsızlığın sonucu,anlamsız karmaşalar

Dön gel tıkanıklığında sürüklenmek

Dur diyememenin çaresizliği

Amacım,haykırmak! ..

Ben gerçeğimin peşinde o çaresiz

Sarı bir avuntu var içimde,mayalı...

Dinginliğin sırrı mistizm mi ki

Varoluşumun çakmaktaşları

Yıldızların özünde var benim yalnızlığım

Saygı ve sevgilerimi sunuyorum sana,

Ey herşey ve hiçbirşey

Düalizmi bende sarmallama sakın,varoluşum

Yalnızlığımı safsatalaştırma

İçimdeki ses tüketiyor beni

Yeniden doğmak için

Yoksullaştırma beni gerçeğim

Birazdan bitecek tüm sanrılar

Ve ben huzura ereceğim

Bir an için hiçlik olacağım

Ve evrene hükmedeceğim

İnsan gerçeğim haykıracak

Ve huzursuzluk gölgeleyecek kalbimi

Git-gellerin kaosunda yorgun

Ve dinginliğin hafifliğinde

Bileceğim bilinmesi gerekeni

Ben olacağım

Varoluşun tek yasası...', 'Seçimler sensen,neden başkaları tercih önceliği olanlardır Sebep eylemsizlik mi ya da... Her neyse... Ben ki sonradan belirsiz olan ya da bü...', ARRAY['Türk Edebiyatı','Şiir','Ali Veli']::text[], 8.5, '{"poet":"Ali Veli","poet_slug":"ali-veli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/varolusun-tek-yasasi-ya-da-varolusun-cakmaktaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkınla', 'askinla-i-brahim-sarihan-4jsl0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gemi misaliyim ben sayende

Dalgalar bırakmaz, getirir sana

Rıhtımımsa gönül pencerende

Tüm hücrelerimle varım aşkına

Nefes gibi benliğine nüfuz ederim

Sevginle avunurken, katlanır özlemim

O ömre bedel parıldayan gözlerin

Yok mu, içimi eriten tap tatlı sesin

Muhtacım sana, inandım ben buna

Hayatımı adıyorum artık yoluna

Sevgiyi aşkı öğrettin, sevdiğim bana

İstesem de bırakamam, aşığım sana

Vurgun ettin sevdana kalbimi

Bir tek dileğim var hayli değerli

Narin parmağında olsun pırlanta

Yalnız benim olmalısın, aşkım hayatta

Hakkâri, 13 Mayıs 2003)', 'Bir gemi misaliyim ben sayende Dalgalar bırakmaz, getirir sana Rıhtımımsa gönül pencerende Tüm hücrelerimle varım aşkına Nefes gibi benliğin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askinla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-rukiye-ozkat-jh5hu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamanı öğreniyordum,

Ne kadar da basitti.

Saatler biraz karışık,

Aylar bir tekerleme gibi.

Mevsimlerde ilkbahara takılmıştı aklım; 

Yüreğim hep nisandı.

Akreple yelkovan birbirini kovalayacaktı

Dakikalar,saatler,günler,aylar,yıllar

İşte hepsi sığıyordu bir satıra.

Ve bu kadar kısaydı aslında.

Dakika ve yıl şimdi aynı oysa.

Yüreğim artık eylül...', 'Zamanı öğreniyordum, Ne kadar da basitti. Saatler biraz karışık, Aylar bir tekerleme gibi. Mevsimlerde ilkbahara takılmıştı aklım;  Yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zaman-298-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum Bütün Kâlbimle', 'seni-seviyorum-butun-k-lbimle-yusuf-onder-bahceci-canvg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana geliyorum bütün kâlbimle,

Seni seviyorum, bütün kâlbimle,

Dilimde neler var, gel bir dinle,

Sana geliyorum bütün kâlbimle.

Yıllarca gözyaşı döküp ağladım,

Durgun sular gibi akıp ağladım,

Yaralı aslan gibiyim kahırlandım,

Sana geliyorum bütün kâlbimle.

Senden ayrıldım da, güldüm mü,

Çok çileler çektim de öldüm mü,

Sende, birgün olsun sordun mu,

Sana geliyorum bütün kâlbimle.

Dünyalar benim olsa, gülemem,

Söylediğime bakma, gelemem,

Bu şartlarda inan sana eremem,

Seni seviyorum bütün kâlbimle.', 'Sana geliyorum bütün kâlbimle, Seni seviyorum, bütün kâlbimle, Dilimde neler var, gel bir dinle, Sana geliyorum bütün kâlbimle. Yıllarca göz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-seviyorum-butun-kalbimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '50.Gün- 1200 Saat', '50-gun-1200-saat-asli-yildiran-jw7sk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeryüzünde hangi varlık, hangi insan 

sadece ve sadece 50 günde 

yani sadece 1200 saatte bu kadar özlenir ki? 

Sen! Ben özlenirim diyorsundur şimdi

Doğru sen özlendin ölürcesine,

Yüreğimden tam 1200 kez hançerlenmişcesine yalnızca sen özlendin

Sen istendin Allah''tan 1200 saatte milyonlarca kere...

Bir yürek kıyametiydi özlemin,

Deli bir kasırgaydı yıkıp geçen heryeri

Sen bunları hiç bilmedin, hiç bir zamanda haketmedin ki

Ve yine sen bu kadar özlenmiş ve bu kadar istenmişken

Terkedildin, bir köşe başında ki o köşebaşı hiç unutulmayacak

Öylece yapayalnız bırakıldın

Şimdi söyle bana hayatımın celladı

Hiç sevmedin mi o Büyük İnsan''ı! ! ! 

O Büyük İnsan ki ömrünü sana adamıştı...

16.02.2006 / 50.Gün şiiri BÜYÜK İNSAN''lara', 'Yeryüzünde hangi varlık, hangi insan  sadece ve sadece 50 günde  yani sadece 1200 saatte bu kadar özlenir ki?  Sen! Ben özlenirim diyorsundu...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/50-gun-1200-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-ahmet-ali-okuyan-up0j8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anne sözü dinlemeyen

Bir çocuğa benzetirim kalpleri

Hep zamansız ağlayan bir çocuk gibi

Ummadığın anda aşık olabilen

Ne kadar olmaz dese bile insan

Son söz kalbe aitti her zaman 

Ölürken bile durduğu an…', 'Anne sözü dinlemeyen Bir çocuğa benzetirim kalpleri Hep zamansız ağlayan bir çocuk gibi Ummadığın anda aşık olabilen Ne kadar olmaz dese bil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ali Okuyan']::text[], 8.5, '{"poet":"Ahmet Ali Okuyan","poet_slug":"ahmet-ali-okuyan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-soz-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizans', 'bizans-ahmet-ali-okuyan-2ztmn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizans’ tan kalma

Soluk soluğa seslerini duyarım

Fatih’in askerlerinin

Surlara bırakılan tuzlu parmak izlerinden

Alırım kokusunu

Gecekondu sobalarının arkasına 

Kurusun diye asılan

Gözyaşlarının izlerini taşır

Sokakların

Ekmeğinin üstüne serpip

Islak şekeri

Sırtında çantası ile

Okul yolunda bir öğrenciyi andırır

Yağmur sonrası

Boğazında kalmış ıslak vapurlar

Her ezan sesi yeniden dirilişidir

Uyuyan topraklarının

Kim bilir kaç bilinmez olayın

Görgü tanığıdır

Kız kulesi

Ört pas etmeye çalışırken

Boğazın suları 

Kalıntıları…', 'Bizans’ tan kalma Soluk soluğa seslerini duyarım Fatih’in askerlerinin Surlara bırakılan tuzlu parmak izlerinden Alırım kokusunu Gecekondu s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ali Okuyan']::text[], 8.5, '{"poet":"Ahmet Ali Okuyan","poet_slug":"ahmet-ali-okuyan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bizans-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi gidiyorum', 'simdi-gidiyorum-ahmet-dalkiz-41fq5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi gidiyorum

Zamanı geldi artık ayrılığın 

Dilediğin gibi yaşa

Bilki biz ayrıldık

Elveda sana

Duyacağın son söz dudaklarımda

Şimdi gidiyorum

Eze eze ümitlerimi hayallerimi

Bir öfke bir hüzün var içimde

Gözlerim yaşarıyor yürüdükçe

Öksüz bir çocuk gibi 

Yollarda ezile büzüle

Anılarım solmuş sararmış

Son bahar yaprakları gibi

Beni terk ediyorlar

Uzayan yollara döküle döküle

Her şeyim sende kalsa bile

Gökteki bir yıldız olsan bile

Artık bir ben olurum 

Seni barındırmıyan içinde', 'Şimdi gidiyorum Zamanı geldi artık ayrılığın  Dilediğin gibi yaşa Bilki biz ayrıldık Elveda sana Duyacağın son söz dudaklarımda Şimdi gidiyo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Dalkiz']::text[], 8.5, '{"poet":"Ahmet Dalkiz","poet_slug":"ahmet-dalkiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/simdi-gidiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta', 'nokta-ahmet-ali-okuyan-htlp5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En yalnızıyım

Aynı buluttan kopan

Ve ağlayarak toprağa doğru koşan

Yağmur damlalarının

Bana avuç açar mı dersiniz

Onla başlayan bir cümlenin

Sonuna bir nokta olmam için…', 'En yalnızıyım Aynı buluttan kopan Ve ağlayarak toprağa doğru koşan Yağmur damlalarının Bana avuç açar mı dersiniz Onla başlayan bir cümlenin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ali Okuyan']::text[], 8.5, '{"poet":"Ahmet Ali Okuyan","poet_slug":"ahmet-ali-okuyan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nokta-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz ve Özgürlük', 'deniz-ve-ozgurluk-ahmet-ali-okuyan-5wemj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizi doldurarak

Özgürlüğünü genişleten insanoğlu

Uslu ve sessizce boyun eğerek

Geri çekilen denizin

Bir gün

Özgürlüğü için geri döneceğini

Hiç düşünmez mi?', 'Denizi doldurarak Özgürlüğünü genişleten insanoğlu Uslu ve sessizce boyun eğerek Geri çekilen denizin Bir gün Özgürlüğü için geri döneceğini...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ali Okuyan']::text[], 8.5, '{"poet":"Ahmet Ali Okuyan","poet_slug":"ahmet-ali-okuyan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/deniz-ve-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belden Aşağı', 'belden-asagi-mehmet-sukru-bas-nofat', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köroğlu sandık kendimizi

İndik Çamlıbel''den aşağı

Geldik dostlar bir araya,

Söyleştik belden aşağı.

Teve geldi bitti sohbet

O kutuda ne ki hikmet.

Ahlaksızlık oldu nimet

Seyrettik belden aşağı.

Kahkahalar çıktı arşa,

Hasret kaldık milli marşa

Şimşir tarak o kel başa

Vuruldu tenden aşağı 

Faziletin yerinde bir mez

Edep hayâ nedir bilmez.

Mefkûreye akçe vermez,

Kıvırtır belden aşağı.

Yaşantımız tele vole,

Pirenin sırtında deve.

Hoş sohbet kesildi evde,

Görüntü belden aşağı.

Yakamızda bitle pire,

Değin hele kusur kimde,

Mutlaka günün birinde,

Denilmez belden aşağı.', 'Köroğlu sandık kendimizi İndik Çamlıbel''den aşağı Geldik dostlar bir araya, Söyleştik belden aşağı. Teve geldi bitti sohbet O kutuda ne ki h...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/belden-asagi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-ahmet-ali-okuyan-e5uff', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşleri köstebeklerin

İşlerdi kanıma 

Sabahı olmayan aksamların ufkunda

Güneşi batarken kirpiklerinin 

Bir yağmur damlasına saklardım kendimi

Öylesine arardım seni

Bir şehrin göz değmemiş sokaklarında

Güneş ışıklarının ıslatamadığı topraklarda

Ya da solunulamamış hava ortamlarında

Öylesine bir sevdaydı gönlümü saran

Uçurum kenarlarında blörf yapan

Hayatın kollarına tutunamayan

Hepsi hepsi öyle bir sevdaydı

Bir satır yer kaplamayan

aralık 2000', 'Düşleri köstebeklerin İşlerdi kanıma  Sabahı olmayan aksamların ufkunda Güneşi batarken kirpiklerinin  Bir yağmur damlasına saklardım kendim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ali Okuyan']::text[], 8.5, '{"poet":"Ahmet Ali Okuyan","poet_slug":"ahmet-ali-okuyan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oylesine-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gel De Gör! * (Ali Babama)', 'gel-de-gor-ali-babama-hulya-karaca-xkrpi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adım adım gidiyorum zamanın ardından

Tek temennim mutluluk olsun mısralarda

Derman zerrede gizli beklerken öylece

Gelde bul beni babam

Uzak, çok uzaklardan bu sesleniş

Artık yanı başında değilim ki! 

Mutluluğun, huzurun daim olsun

Dinle de duy beni babam

Zincire vurulmuş, bendin hani

Aşıma uğramış demek emeklerin

Dünyanın kör bıçağıyla olmaz

Bak da gör beni babam

''Eğri olsada, düzü bul'' derdin

Hayat merdiveninden bir basamak verdin

Çıktımda inmesini bilemedim

Çok ıssız korkuyorum babam

Hülya Yapar

2006.Ocak.27.Cuma', 'Adım adım gidiyorum zamanın ardından Tek temennim mutluluk olsun mısralarda Derman zerrede gizli beklerken öylece Gelde bul beni babam Uzak,...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-de-gor-ali-babama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevapsızlar', 'cevapsizlar-murat-gulener-pvjm4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığı mı insanı korkutan

Yoksa şarkılar mı dertleri arttıran

İnsan mı Kendini dünyaya kaptıran

Yoksa dünya mı insanı yolundan saptıran

Gülmek mi dertleri unutturan

Yoksa dertlermi gülmeyi yutturan

Şiirler mi dertleri anlatan

Yoksa dertler mi şiirleri şiir yapan', 'Gecenin karanlığı mı insanı korkutan Yoksa şarkılar mı dertleri arttıran İnsan mı Kendini dünyaya kaptıran Yoksa dünya mı insanı yolundan sa...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cevapsizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-ahmet-ali-okuyan-e3qaw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana dünden kalma

Bugünsel düşlerin anahtarını veriyorum

Hazan mevsiminde kapanan pencerelerin

Ve tutuşturulan yürek bacalarının

Gökyüzüne bıraktığı isli ve hisli

Sözlerimi bırakıyorum

Avucuma sığmaz sözlerin

Cebinede

Bu yüzden kulağına fısıldıyorum

Ve bir gün kalbinin sesini dinlersin diye

Kulağım hep kapıda olacak…', 'Sana dünden kalma Bugünsel düşlerin anahtarını veriyorum Hazan mevsiminde kapanan pencerelerin Ve tutuşturulan yürek bacalarının Gökyüzüne b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ali Okuyan']::text[], 8.5, '{"poet":"Ahmet Ali Okuyan","poet_slug":"ahmet-ali-okuyan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sana-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Acısı', 'hasret-acisi-murat-gulener-8intf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aklım başımdan gitmişti ilk gördüğümde

Daha küçüktüm hasret ağlarını ördüğünde

Sana tek söz diyeceğim bana geri döndüğünde

Çok sevmiştim deme toprağa girdiğimde

	

Korkuyorum seni kaybetmekten

Seviyorum seni çok yürekten

Mutlu olacaksan bırakıp gitmekten

Yüreğimi de al yanında giderken

Ölmezsen yüreğimle yaşarken

Sevmeyi öğren henüz hayattayken

Sessiz denizler insanı kendine çeker

İnsansa anlayacağını zannedip içini döker

Kaybolur sessizlikte duygular birer birer

Hasret acısını ancak sevenler hisseder', 'Aklım başımdan gitmişti ilk gördüğümde Daha küçüktüm hasret ağlarını ördüğünde Sana tek söz diyeceğim bana geri döndüğünde Çok sevmiştim dem...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hasret-acisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Artık', 'don-artik-murat-gulener-4titq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep uzak mı bakacak gözlerin

Hep bensiz mi kalacak sözlerin

Uzaktaki bensiz sözlerini özledim

Kör oldu beklemekten gözlerim

Kaldıramıyor artık yorgun bedenim

Atmıyor eskisi gibi solgun yüreğim

Ne olur gel bir kere yüzün göreyim

Göreyim de gözlerim arkada ölmeyeyim

Dertlerle doldu her anım

Tek tesellim oldu hatıralarım

Bırak gururu gel beraber olalım

Hayata beraber yeniden doğalım', 'Hep uzak mı bakacak gözlerin Hep bensiz mi kalacak sözlerin Uzaktaki bensiz sözlerini özledim Kör oldu beklemekten gözlerim Kaldıramıyor art...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/don-artik-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sana Benziyordu', 'i-stanbul-sana-benziyordu-metin-yalti-z9oxq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sokağa öylece salınmış

Masum ve güzel yüzü

Toza, toprağa karışmış, kirli

Çocuklar vardır ya, sevimli.

Bağrına basmak geçer içinden

Çekinirsin hani…

Gelinlik giyinmiş İstanbul.

Yer, yer erimiş karları

O kirli yüzlü çocuklar gibi

Çekici, bir o kadar iticiydi…

Hep derdim ya sana

İstanbul’a benziyorsun da

Gülümserdin.

O munis gülüşünle 

Sen vardın hep aklımda.

Hani akşam haberlerinde

Gölgelenirdi ya yüzün hüzünlenip de

Köpüren bir deniz olurdu ya bakışların

Dalga dalga yükselirken öfken

Güzel olurdun genede

Her şeye rağmen

-Bahane aramaktı benimki -

Sevmeye başlardım hep yeniden.

Kaç gündür karlı İstanbul

Zaman zaman, lapa lapa yağıyor

Yer yer tipiye dönüşüyor kar.

Gene de her haliyle güzel İstanbul

Sana ne çok benziyor….

16.2.06', 'Sokağa öylece salınmış Masum ve güzel yüzü Toza, toprağa karışmış, kirli Çocuklar vardır ya, sevimli. Bağrına basmak geçer içinden Çekinirsi...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istanbul-sana-benziyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana - Vatan - ilk Defa Yaşananlar', 'ana-vatan-ilk-defa-yasananlar-sevinc-kavuk-frq6l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nice cevherler taşıyan bir vatandır ana da

sen de  benim gibi var olan o kucakta 

tüm annelerin elini öpen sımsıcaklığında 

vatan gibi ana da cihana kutlu ve mutlu olsun

dilerim hep sevgiye şefkatte ilk defa yaşananlar 

dolu yaşanmış olur, yaşanır da inşallah 

ilk defa yaşananlar... bu bir ömre değerlik...

ana sevgi, baba şefkat, bir adım daha, yürekliliğe...

bu bir yıldönümü her doğuşun o güzelliklerle...

bu bir kanat çırpışı, göz kırpışı, bir titreşim göğüste...', 'nice cevherler taşıyan bir vatandır ana da sen de  benim gibi var olan o kucakta  tüm annelerin elini öpen sımsıcaklığında  vatan gibi ana d...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ana-vatan-ilk-defa-yasananlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seveceğim1', 'seni-sevecegim1-mehmet-cengiz-zgfl3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yarında bir gündür 

yarında güneş doğacak

tek fark,

ufuktan doğan o güneş

artık, daha alımlı doğacak sabahlara

doğuşu kadar, batışınıda seveceksin

taktığın o mutluluk maskesini atıp

yürekten gülen gözler alacak yerini

haydi yüreğim, şahlan artık

demir attığını sandığın o yalnızlığın yerini

tertemiz bir sevda alacak

yakıp kavuracak belki ateşinde

ayna misali, yansı sende mecnu''na

dualarının bilmillahı yap onu...', 'yarında bir gündür  yarında güneş doğacak tek fark, ufuktan doğan o güneş artık, daha alımlı doğacak sabahlara doğuşu kadar, batışınıda seve...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Cengiz']::text[], 8.5, '{"poet":"Mehmet Cengiz","poet_slug":"mehmet-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-sevecegim1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakim Bey', 'hakim-bey-gunduzalp-kayihan-dgblp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çile dolu ömrüm çilelere sürgün

Mutlu bir günü olmadı,hep üzgün

Huzuru yok bir türlü,efkarda her gün 

Ber''at ister Hakim Bey bu ömrüm

Durdu bir köşede,umutsuzmu umutsuz

Canı burnunda,mutsuzmu mutsuz

Aşk kavgasında,suçsuzmu suçsuz

Ber''at ister Hakim Bey bu ömrüm

Derdini anlatır,kimse anlamaz

Canı sıkılır lakin yine de haykırmaz

Hapis edilmiş mülk-ü sevdaya,salınmaz

Ber''at ister Hakim Bey bu ömrüm', 'Çile dolu ömrüm çilelere sürgün Mutlu bir günü olmadı,hep üzgün Huzuru yok bir türlü,efkarda her gün  Ber''at ister Hakim Bey bu ömrüm Durdu ...', ARRAY['Türk Edebiyatı','Şiir','Gündüzalp Kayıhan']::text[], 8.5, '{"poet":"Gündüzalp Kayıhan","poet_slug":"gunduzalp-kayihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hakim-bey-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Ötesi', 'yillar-otesi-aynur-avci-tosr6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Burcu burcu kokan yıllar

Avucundan içtiğim acılar

Yudum yudum hatıralar

Yıllar ötesine alıp götürdün beni

Gönül gözümle sevdim seni

Bıraktığın  şehirde yine yalnızım

Sabahsız geceler de sakladım aşkımı

Çığlıklar yaşam oldu

Anılar arkadaş kaldı

Yine alıp götürdün beni zaman,

yılların acı sonsuzluğuna..', 'Burcu burcu kokan yıllar Avucundan içtiğim acılar Yudum yudum hatıralar Yıllar ötesine alıp götürdün beni Gönül gözümle sevdim seni Bıraktığ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yillar-otesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seveceğim2', 'seni-sevecegim2-mehmet-cengiz-pr4yg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 've yarında ben,

yine seni çok seveceğim

dudaklarının söyleyemediği aşkı sevgiyi...

karınca azmiyle taşıyacak,

ilmek ilmek işleyeceğim yüreğine.

saat 24 gün bitti.

ve ben,

bugünde yine sevemedim seni

mecnun kadar...

sen leyla olma, alma beni yüreğine...

bu gecenin elbet sabahıda var

zor sevdam...

yarın; mecnun''u kıskandıracak 

leyla''yı kahrından ağlatacak bir aşkı yaşayacağım...

seni seveceğim.', 've yarında ben, yine seni çok seveceğim dudaklarının söyleyemediği aşkı sevgiyi... karınca azmiyle taşıyacak, ilmek ilmek işleyeceğim yüreği...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Cengiz']::text[], 8.5, '{"poet":"Mehmet Cengiz","poet_slug":"mehmet-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-sevecegim2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Of Of Yaşam', 'of-of-yasam-aynur-avci-i1tuu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Of of dünyada ki yaşam

Neden damarlarıma işledin

Acımın taşınmazlığını

Yaşamdan zehirledin zehirledin hayatımı

Mutlu gün kaç defa sayar oldum

Böylemidir,doğmakla ölmek arası

İçine sevgiyi,aşkı katmadan

Yoğrulur mu insan? 

Karşıdan bakınca bir bütün

İçi enkaz olan

Bir yudum sevgiyle

Ayakta duran

Yaşadığını sanan

Acıdan insan', 'Of of dünyada ki yaşam Neden damarlarıma işledin Acımın taşınmazlığını Yaşamdan zehirledin zehirledin hayatımı Mutlu gün kaç defa sayar oldu...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/of-of-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Sevmişim', 'zamansiz-sevmisim-atilla-kizilkaya-4ur5n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni nasıl sevdiğimi 

Ben dahi anlayamadım

Bir gece uykumu bölüşünle 

Başladı sanırım

İşte o gecee yatağımdan kalktım

Ve bir çay demledim kendime

Seni nasıl sevdiğimi anlamak için

Belkide zamansızdı 

Seni sevişim

Çayımı yudumlarken

Bir sigara çekti canım

Ama sigarayı bırakmıştım

Belkide bir sigara içimi

Çözecektim seni nasıl sevdiğimi

Dedim ya sigarayı bıraktım

Ama seni bırakamam

Birazdan gün doğacaktı

Belki bir can bedenden ayrılacaktı

Ve yerine yeni doğan 

Çocuklara bırakacaktı

Bir gül açacaktı

Ve bir gün solacaktı

Bir aşk bitecek

Yeni bir aşk arayacaktı

Seni nasıl sevdiğimi anlayamadan

Karanlık çökecekti sokağıma

Ve küçük çocuklar gibi 

Bende korkacağım karanlıktan

Korkularımı yenerek düşünecektim

Seni nasıl sevdiğimi

Bu gece 

Yine kelimeler döküldü yüreğimden

Sonra birer birer mısra oldu

Şair olduğum aklıma geldi 

Seni bir kere daha sevdim

Ben seni 

Şair olduğum için sevmiştim

Ama ben seni

Zamansız sevmişim...', 'Seni nasıl sevdiğimi  Ben dahi anlayamadım Bir gece uykumu bölüşünle  Başladı sanırım İşte o gecee yatağımdan kalktım Ve bir çay demledim ke...', ARRAY['Türk Edebiyatı','Şiir','Atilla Kızılkaya']::text[], 8.5, '{"poet":"Atilla Kızılkaya","poet_slug":"atilla-kizilkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/zamansiz-sevmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin de oldu mu ağladığın', 'senin-de-oldu-mu-agladigin-durdu-mehmet-dalkanat-r2bs2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin de oldu mu ağladığın...

Ara sıra hıçkırmak istedin mi derdinden...

Oldu mu hiç boğazında kördüğüm..

Mal için mülk için para için değil de...

Aşk için sevda için...

Oldu mu ağladığın...', 'Senin de oldu mu ağladığın... Ara sıra hıçkırmak istedin mi derdinden... Oldu mu hiç boğazında kördüğüm.. Mal için mülk için para için değil...', ARRAY['Türk Edebiyatı','Şiir','Durdu Mehmet Dalkanat']::text[], 8.5, '{"poet":"Durdu Mehmet Dalkanat","poet_slug":"durdu-mehmet-dalkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/senin-de-oldu-mu-agladigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Tutmaz Elinden Insanın...', 'zaman-tutmaz-elinden-insanin-ozkan-budak-8og1o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman elinden tutmaz insanın,

Yasamak istersin bir daha o anı,

ve düşlersin olmak istediğin yeri...

biçare bakışlarla batmasını istemezsin ayın,

ve korkarsın geceden...

zaman elinden tutmaz insanın,

hatıralar başucunda 

dokundurtmaz bile..

uzanıp tutmaya calışırsın,

elin kayar gücün yetmez olur...

Zaman elinden tutmaz insanın,

sevdiklerin buğulu cam ardında kalır,

yarınların ise bir muamma...

Zaman elinden tutmaz insanın,

gecmişin yakın olur,

anıların ise cok uzak...

Ve sonsuzluk yani başında tükenmiş;

Yarınlar "dün"leri arar olmuş...', 'Zaman elinden tutmaz insanın, Yasamak istersin bir daha o anı, ve düşlersin olmak istediğin yeri... biçare bakışlarla batmasını istemezsin a...', ARRAY['Türk Edebiyatı','Şiir','Özkan Budak']::text[], 8.5, '{"poet":"Özkan Budak","poet_slug":"ozkan-budak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zaman-tutmaz-elinden-insanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı ekmek, Değişik yemek', 'ayni-ekmek-degisik-yemek-atil-kesmen-6s2d4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya, kaynar kazan ateşi

Hisler, kurşun yarası

Nasıl bir yaşam sancısı

Aynı ekmek,değişik yemek 

Bana düşen,haram sevdi

Toktum,öldü gönül sofrası

Kıtlık,yaşam enkazı

Kolum kanadım kırıldı

Aynı ekmek,değişik yemek

Bir sevgiydi,bin el oldu

Gündüzler geceye,gebe düştü

Su uyurken,yılan yürüdü

İnsanlık, sevgi diye yanarken

Güneş,ter doğurdu

Aynı ekmek,değişik yemek

Sevgi yerine,arzular yendi

Bir yol çizdim,kaldı acısı

Gözlerim,uçurum yarası

Ölüm gezer,görmez gözleri

Aynı ekmek,değişik yemek

Seven gönül,yakar kor ateşi

Yanan sevgi,kendine döner

Kan toprağa,düşer gezer

Gök, kurşuna hedef olmuş

Aynı ekmek,değişik yemek

Canı can da yemek,helal dendi.', 'Dünya, kaynar kazan ateşi Hisler, kurşun yarası Nasıl bir yaşam sancısı Aynı ekmek,değişik yemek  Bana düşen,haram sevdi Toktum,öldü gönül s...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayni-ekmek-degisik-yemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Arıyorum', 'bir-ask-ariyorum-aynur-avci-9h2x1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir elimde kalkan

Bir elimde hançer

Allahın bana bahşettiği

Ama bir türlü bulamadığım

Aşkı arıyorum,nerde var mı? 

Yoluna düştüm aşkın

Dağ tepe demeden

Dumanlı dağları aştım

Denizleri dolaştım,

Aşkımı arıyorum

Hani nerde var mı? 

Var ama-

Ayaklarımı yerden kesecek aşkın

Hançer yarası olduğunu nerden bileyim.

  

                                            10.2.2004

                                               Erdek

.

-', 'Bir elimde kalkan Bir elimde hançer Allahın bana bahşettiği Ama bir türlü bulamadığım Aşkı arıyorum,nerde var mı?  Yoluna düştüm aşkın Dağ t...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-ask-ariyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaylanın yollarına', 'yaylanin-yollarina-mikdat-bal-ejjgw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaylanın yollarına

Kavuşsam sularına

Kaç senedir hasretim

Yayla uykularına

Yaylanın havaları

Kuymaklı tavaları

Çok hoşuma giderdi

Hele bedavaları

Yaylanun tepeleri

Çoktur menkıbeleri

Güneş ile yan yana

Yüksek mertebeleri

Yediden yetmişine

Her kes gider işine

Kimi oduna gider

Kimi inek peşine

Gurbetten anıyorum

Özleyip yanıyorum

Daha görecek miyim

Göremem sanıyorum

DerMikdatî  gelirsem

Bir becerebilirsem

Gözlerim açık gider

Eğer burda ölürsem', 'Yaylanın yollarına Kavuşsam sularına Kaç senedir hasretim Yayla uykularına Yaylanın havaları Kuymaklı tavaları Çok hoşuma giderdi Hele bedav...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaylanin-yollarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çal', 'cal-muharrem-kemal-gunduz-33rit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çal, çalgı çal..

    Yüreğimi çalma

    Umudumu aşkımı

    Sevdamı hiç....

Çal ölümü gecelerden

     Acıları çal.

     Özlemi, düşünlerimden ayrılığı

     Hasretimi...

Sevgimi çalma

     Açan dalımı, baharımı

     Dünyamı, gençliğimi..

Çal istersen ayrılık şarkılarını

     Hüzün doldurup duygulara

     Hüsranla yenilmem için

     Karanlıkları çal

     İçlerinden zulümleri, işkenceleri

Sisli bulvarlardan yağmurları

     Işığa değme, aydınlığa ve ona asla...

Uykularını çal gecelerden birtanemin

      Beni düşünmesi için

      Umut doldurup yüreğine

      Çalıp kapıları ansızın

      Varması için bana

Barışı çalma

       Kardeşliği, dostluğu

       En temiz duyguların

       En güzel yarınların

Onuru olan insanlığı çalma..

13.04.1983  ANKARA', 'Çal, çalgı çal..     Yüreğimi çalma     Umudumu aşkımı     Sevdamı hiç.... Çal ölümü gecelerden      Acıları çal.      Özlemi, düşünlerimden...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Kemal Gündüz']::text[], 8.5, '{"poet":"Muharrem Kemal Gündüz","poet_slug":"muharrem-kemal-gunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmama uyan mı var', 'i-mama-uyan-mi-var-mikdat-bal-n9l1v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İmama uyan mı var

Sözünü duyan mı var

Açıp okuyan mı var

Bu insanlar kurtulmaz

Nice sohbet eyledi

Nice sözler söyledi

Bir kerecik şeyledi

Ama bu unutulmaz

Bu ne bicim cemaat

Beklemesin şefaat

Hoca yapmış kabahat

Artık sözü tutulmaz

Elbette köyden kaçar

Yoksa cemaat sı...r

Başına bela açar

Mescitler kokutulmaz', 'İmama uyan mı var Sözünü duyan mı var Açıp okuyan mı var Bu insanlar kurtulmaz Nice sohbet eyledi Nice sözler söyledi Bir kerecik şeyledi Am...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/imama-uyan-mi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlana ne demiş', 'mevlana-ne-demis-mikdat-bal-kxnf9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevlana ne demiş, onu bir düşün

Cesaret alırsın,düzelir işin

Allah var, O yeter, boştur telaşın

Selam ver mutlaka, cevap alırsın

Umutlu ol her an, kendine güven

Seversen çok olur,seni de seven

Dost mu sanıyorsun, seni her öven

Karşılıksız sev ki, sevap alırsın

Hissetikçe seni var eden gücü

Mahlükatı sana yâr eden gücü

Dünya yı geçici dâr eden gücü

Ondan af dilersen, tevvab olursun', 'Mevlana ne demiş, onu bir düşün Cesaret alırsın,düzelir işin Allah var, O yeter, boştur telaşın Selam ver mutlaka, cevap alırsın Umutlu ol h...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mevlana-ne-demis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ithaf', 'ithaf-deniz-zeynep-gurleyen-29pov', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O’nu anlayabilmek…

Bana verdiklerini…

….benden aldıklarını…

Ilk defa yaşıyorum sevdiğim,

ilk defa tadıyor masum ruhum temiz kirliliği...

Ufacıktım bende…seninle büyümüş kalbim, ruhum

…....duygularım…

Zamanın girdabında esir olanlardan farkımız ne..? 

Üstünlüğümüz yok! 

….ama ruhumuz var…

Nerede o ölümsüzler? 

Kendini şeytana satan toplumda Mecnun yaşamayı neylesin? 

Yürek mi dayanır sevdiğim? 

Dillere destan aşklar olan bir yer varsa söylesin dünya, bizde gidelim…

Ama sır vermez…

Kalbindedir derdi ömrümün yarısı…inanmak, güvenmek…

Şairlik bana kalmadı…

Kırık kalemimle yırtık kağıdıma yazarım yalnızca…

Deme sevdiğim ağlayamam, sözüm var…

Şairlik bana kalmadı…

Ne yalnız olmak nede olmamak bu bendeki..

Seninle yaşamaya başlamışken 

fırtınalara esir kalbim durgunluğa tıpkı tenindeki nefesim kadar yaklaşmışken…

Ben kalbimi zorladım…

„Hasretinden Prangalar eskittim“ demiş büyük şair…

Ben haykırdım…

Bana kalmamış sevdiğim…

Şimdi sen geldin ya…ne gam yumsam gözlerimi oyunlarımla dolu hayata…

Kalbimi sana vadettim…sen yeterki iste…

Senin elinden olsun sonu…

Bana kalmamış sevdiğim…

Aşk bize hiç doymamış…

1 şubat,2006, 16.33', 'O’nu anlayabilmek… Bana verdiklerini… ….benden aldıklarını… Ilk defa yaşıyorum sevdiğim, ilk defa tadıyor masum ruhum temiz kirliliği... Ufa...', ARRAY['Türk Edebiyatı','Şiir','Deniz Zeynep Gürleyen']::text[], 8.5, '{"poet":"Deniz Zeynep Gürleyen","poet_slug":"deniz-zeynep-gurleyen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ithaf-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir olalım, deme nerde?', 'bir-olalim-deme-nerde-mikdat-bal-v5qpy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir olalım,  deme nerde? 

Başlamalıyız bir yerde! 

Telafisi yok ilerde

Elden fırsat geçer dostum

Çok acele hem de seri! 

Ön safa geç kalma geri

Yoksa başka bir lideri

Başkaları seçer dostum

Silkin, kalk nefsine uyma

Gel kendini küçük sayma

Bu günü  yarına koyma

Yarın fırsat kaçar dostum

Meydanları boş bulanlar

Bunlar, parsayı  alanlar

Bil ki en yakın olanlar

Sana kefen biçer dostum

Fitne olurken vatanda

Bana ne dediğin anda

Huzurun olmaz cihanda

Gök başına göçer dostum', 'Bir olalım,  deme nerde?  Başlamalıyız bir yerde!  Telafisi yok ilerde Elden fırsat geçer dostum Çok acele hem de seri!  Ön safa geç kalma g...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-olalim-deme-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman “Seni Seviyorum” Desem', 'ne-zaman-seni-seviyorum-desem-humeyra-yilmaz-p0p22', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman “seni seviyorum” desem,

Kadınsı bir yalnızlık rengine bürünüyor,

Sesimde sığıntı umut heveslerim.

Telvesinde bir akşamın, 

Seni arıyor falcı bakışlarıyla hüzün.

Yüreğim kabarıyor,

Yıldızlar karaya vuruyor,

Karanın haberi olmuyor yükünden.

Yudumlarken acıyı kahve, gözlerimden,

Aynalı bir geçmiş ısınıyor şakaklarımda, 

Yağmurlar damla damla üşüyor. 

Ne zaman “seni seviyorum” desem,

Bu şehir üzerime yürüyor. 

Biliyorum ki yanmaktan korkuyor, yakılmaktan.

Kapanmamış sokakların kanlı izlerinde, 

Zamanın gölgesi uyanıyor, yüzümün yamalı yerinden. 

Her merdiven boşluğundan atıveriyor kendini,

Ne ütü ne de dikiş tutmayan sevdam.

Tırabzanlara takılıp kalıyor olasılıklarım 

Ve soruyu işaret ediyor, 

Göz göze gelmekten kaçındığım anlamsızlıklar.

Devrildi devrilecek gibi duruyor kaldırımlar üzerime.

Sendelerken yorgun düşlerim,

Tozu kalkıyor bedenimden telaşlarımın.

Sonra, hangi mevsimi giyinsem büyük geliyor. 

Ne zaman “seni seviyorum” desem 

Yangınlar kilitli kalıyor ay ışığında.

Tebeşir tozu ateşlerine mahkûm meydanlarım.

Yanmıyorum, yanılıyorum

Kıvılcım taklidi yapıyor ateş böcekleri

Kanmıyorum, kanıyorum.

İçimden tuttuğum gidişler bir bir gerçek oluyor.

Üfledikçe söndürülmüş mumlara,

Eriyor dudaklarım,

Çok katlı bir pastanın en üst katında.

Yenmiyorum, yeniliyorum.

Ne zaman “seni seviyorum” desem 

Gri dumanlar çöküyor ciğerimin başına,

Eteklerimde ise çiçeği burnunda yeşiller.

Çocuk oluyorum, hiç koşulmamış yollarda

Ki kolları rüzgâra aşina.

Sonra rüzgârla rüzgâr oluyorum. 

Dokunduğum yabancı bozkırlarda

Tanıdık, bildik izler bırakıyorum. 

İçim içimden taşıyor içimi içime

Ben anlatamıyorum, kimse de anlamıyor.

Bir kurşun daha kiralıyorum silahıma.

Hem katil hem de ceset oluyorum aynı kurşunla.

Yine pişman oluyorum satın almadığıma

Ne zaman “seni seviyorum” desem 

Demini almıyor çayım, 

Açık ve şekersiz içiyorum, hasretin gibi.

Alışkanlıklarım aklıma geliyor,

Aklım ise alışkanlıklarıma gidiyor

Fakat bir türlü karşılaşamıyorlar nedense! 

Eski şarkıların tozunu alırken, 

Hep yüreğimi kanatıyorum.

Yorgun nakaratlarda tekrarlanıyor hatalarım.

Özrümü kabahatimden daha pahalıya satmak isterken

Hepsi birden elimde kalıyor.

İşte bu yüzden,

Ne zaman “seni seviyorum” desem 

Yanımda olmuyorsun…', 'Ne zaman “seni seviyorum” desem, Kadınsı bir yalnızlık rengine bürünüyor, Sesimde sığıntı umut heveslerim. Telvesinde bir akşamın,  Seni arı...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/ne-zaman-seni-seviyorum-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Günceleri-2', 'gece-gunceleri-2-birsen-ates-ldx87', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mor menekşenin koynunda 

bir yalnızlıksın bende

rengini gecelerden alan

mavidir sevginin rengi

engin denizler gibi 

özgürce açılır limanlara

bir deniz var avuçlarım da

geceden şarkılar söyleyen

yüreğinin sesiyle ağlayan

ıslanan

umutlarımı üşümesin diye

yakamozda gezdirdiğim

sevgimi astım düşlerime

kucaklasın yaşamı diye…

16.02.06', 'mor menekşenin koynunda  bir yalnızlıksın bende rengini gecelerden alan mavidir sevginin rengi engin denizler gibi  özgürce açılır limanlara...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-gunceleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Saçlarını Çalmak Varmış*', 'saclarini-calmak-varmis-i-lker-unlu-ei2cz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Meger ne hummalı hastalıkmış gözlerin,saçların...

Saçlarını çalmak varmış sen görmeden,

Senle birlikteyken...

Birgün gidersen diye,

Şimdi onları okşamak varmış...

Ne hummalı hastalıkmış saçların,gözlerin...

Gözlerini fotoğraflamak varmış Senle birlikteyken,

Sen görmeden...

Birgün gidersen diye ona bakmak varmış...

Kağıda nice can katıpta öylece,

Şimdi nice gerçekten manalı oldugunu görmek varmış...

Şamil YAMAN-İlker ÜNLÜ', 'Meger ne hummalı hastalıkmış gözlerin,saçların... Saçlarını çalmak varmış sen görmeden, Senle birlikteyken... Birgün gidersen diye, Şimdi on...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saclarini-calmak-varmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yanılgı**1**', 'bir-yanilgi-1-mustafa-murat-aydogdu-whg01', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arada birde olsa seni görmek güzel şey

Bir an olsun bakabilmek gözlerine

Sonra kaçırmak gözlerimi hiç bakmamışcasına

Çünkü ne zaman baksam kayboluyorum gözbebeklerinde

Belki hakkım değil seni sevmek

Adını bile dün öğrendim aslında

Ama söz dinlemezki bu yürek

Sever hesapsız,sanki bin yıldır tanıyormuşcasına

Kim olduğumu bilmeyeceksin hiçbir zaman

Tek bilmen gereken şey

Seni amansız,zamansız ve onbinmilyon baloncuk gücünde

Seven biri var bu şehirde.

Belki yazdıklarım yani duygularım

Bir anlam ifade etmeyecek senin için

İşte bu yüzden kim olduğumu bilmeyeceksin

Yazılan bir kaç satır dışında

Yüreğimde saklı kalacak bu sevda.

Seni tanımamak bile çok güzel; 

Hayaller kurmak sana dair

Acaba O''da sever mi? diye,

Sonra bir anda dar gelir bana bu şehir

Ya varlığımdan bile haberdar değilse! 

Herhangi birinden farklı değilsem onun için

Umurunda bile değilse hislerim

Seni düşünebilmek güzel şey; 

Yorgun argın eve dönmek

Belki de sen uyurken

Sabaha kadar seni düşünmek.

Sen ümitsizlik nedir bilir misin? 

Sevmek ama neden sevdiğini bilmemek

Kendimin bile çözemediği bir duyguyu

İfade etmeye çalışmak ve karşılık beklemek

Bir kurşun bile atamadan

Yüreğinin tüm kalelerini teslim etmek,

Hemde hiç tanımadığın birine

Bunca aciz duygular içinde

Tek yapabildiğim şey,kendimi senden gizlemek,

Gücüm yetebildiğince...

Ne olduğunu tam olarak bilemediğim bu duygular içinde

İfade etmek zorundayken tüm hislerimi

Beni tanımayan,benimde tanımadığım birine

Seviyorum demek çok erken ve saçma galiba

Zaten beni sevmeni beklemiyorum senden

İstediğim seni tanımak,görebilmek arada sırada

İstemiyorsan yoluna çıkmam bir daha

Peşinden koşacakta değilim

Eğer bugün geldiysem kapına

Bilki tek suçlusu yüreğim,

Belki de sonsuz bir sevginin

Son satırları bu sözlerim

Bir parçası olmayı çok istediğim hayatına

Ve hiç yaşanmamış saydığım bu sevgiye

Veda ediyorum,

Di''li geçmiş zaman cümleleriyle; 

Teslim olunabilecek milyonlar arasından

Ben seni seçmiştim

Çünkü; Seni sevmiştim...!', 'Arada birde olsa seni görmek güzel şey Bir an olsun bakabilmek gözlerine Sonra kaçırmak gözlerimi hiç bakmamışcasına Çünkü ne zaman baksam k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/bir-yanilgi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yanılgı**2**', 'bir-yanilgi-2-mustafa-murat-aydogdu-u9o3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Artık seni tanımak istemiyorum; 

Tek bir ümit bile vermediğin halde sevgiye dair

Nedendir? Her geçen gün, sana biraz daha bağlanıyorum 

Korkarım ki yüreğim,bir gülüşüne tüm benliğimi değişecektir

Aslında ben bu kadar aciz değildim

Herşeyin üstesinden gelebilirim sanıyordum; 

Gözlerine yenildim! 

Neye yarar bilmiyorum

Belkide benden hiçhaz almayan birine

Yüreğimde kopan fırtınayı anlatmak,

Hemde onun için anlamsız kelimelerle.

Aslında biliyorum aşk yazılmaz,yaşanır

Ama bana arkadaşça görüşmeyi bile çok gören birine

Duygular yalnızca böyle anlatılır.

Artık seni düşünmek istemiyorum; 

Yüreğim sana teslim,bedenimse esirin

Karşında direnen yalnızca aklım,

Onuda kaybetmekten korkuyorum! 

İkimizde farklı gözlerle bakıyoruz birbirimize,

Sen bana hayatın bir parçası

Bense hayatımın bir parçası gözüyle.

Değer verdiğim ne varsa hayatta

Bir bir kaybettim hepsini,

Belkide bu yüzden inadım,

Bu yüzden,kaybetmek istemeyeşim seni.

Şundan emin olabilirsin ki; 

Hayatına girmiş yada girecek hiç kimse

Benim kadar sevemeyecek seni,

Hakkım olmasada senden isteğim

Ne olur o birileriyle kıyaslama beni

Hepsinden önemsiz,değersiz olmaya razıyım

Yeterki kirletme başkalarıyla sevgimi.

Bir gün sevgimden utanacağım

İnanki gelmezdi aklıma

Neden bu kadar uzaksın bana

Yanına gelmek istiyorum,korkuyorum,

Utanıyorum,çok büyük bir yanlış yapmışcasına

Artık bakamıyorum gözlerine

Çünkü biliyorum ki,yerim yok

Ne gözlerinde nede yüreğinde

Aslında sonu gelmez bu şiirin

Ne şiirin nede sevgimin

Zaten anlamı yoktur,sonu gelecekse sevginin

Bir yalandan ibarettir tüm sözler

Yarın bir başkasına söylenecekse eğer.

Her ne kadar boynumu büküp

Sana kızmış gibi yüzümü assamda

Dünümde,içimde ve yarınımda

Bilki,sen olacaksın yalnızca! 

Galiba en büyük yanlışım

Bu sevgiye senin gözünden bakamayışım

İzin ver,senin gözünden bakayım bu sevgiye; 

Hiç tanımadığın biri,olmadık bir zamanda

Seviyorum diye çıkıyor karşına

Nereden çıktı şimdi bu diyorsun,sonra hatırlıyorsun; 

Bunun gibi tipler daha öncede çıktı karşıma.

O kısa zaman dilimi içinde

Düşünmüyorum diyorsun,senin düşündüklerini

Ve değiştirmeyecek diyorsun

Senin sözlerin,benim hislerimi.

Sonra günler geçiyor üstünden

Haftalar,aylar ama aramıyorsun

Seni tanımasına izin vermiyor

Onu ise tanımak istemiyorsun

Kısacası sende aynı hata içinde

Yalnızca kendi gözünle bakıyorsun sevgiye! 

Merak ediyorum,birinin seni sevmesi

Neden bu kadar korkutuyor seni

Belki fırsat verirsen o saf aşığa

Vermeye hazırdır bu sevgiye tüm benliğini.

İstediğim ufacık bir yerdi yüreğinde

Orada olduğumu bilmek bile yetecekti bana

Sen ise bir yol üstünde,üç dakikayı layık gördün duygularıma,

Benim yüreğim karşılığında! 

Senin gözünden okuyabildiklerim bu kadar,

Eğer doğruysa düşündüklerim

Vazgeçmeyeceksen bu inadından

Zerre kadar yüreğinde bir ben yoksa

Ve asla mümkün değilse beni sevmen

Anlamak zorunda kalırım seni o zaman

Aslında ne garip şey,

Kendimi anlatmak isterken,benim seni anlamam.

Kısacası garip şey,sevdaya dair herşey

İstenmediğim bir kalbin kapısında

Fazlasıyla bekledim galiba,

Arkadaşlığına bile razı olan birine

Onu bile çok görüyorsan

Kelimeler kifayetsiz kalır bu sevgiye

Anlamın anlamsızlaştığı bu noktada.

Bir iş çıkışı yol üstünde

Ne yaparsan yap diye teslim ettiğim yüreğimi

Ve ayaklar altına aldığım gururumu

Geri istemektir bana düşen

Sen daha fazla çiğnemeden.

Artık sonuna geldim yolun

Yitirdiğim umutlar,uykusuz gecelerim

Ve birkaç damla gözyaşım,hediyem olsun! 

Aslında böyle bir sona

Galiba hazırlıksız yakalandım

Bilmiyorum nasıl yaparım ama; 

Elbet sensizde yaşarım...!', 'Artık seni tanımak istemiyorum;  Tek bir ümit bile vermediğin halde sevgiye dair Nedendir? Her geçen gün, sana biraz daha bağlanıyorum  Kork...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/bir-yanilgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BuLaMaDiM', 'bulamadim-canan-kosmaz-57yjr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BuLaMaDiM

Tek basima yasiyorum sanki,

Yüregimde kimseler yok,

Etrafimda insanlar var ama,

beni anlayani bulamadim Canim.

Neler yasadim simdiye kadar,

Anlatamiyorum yüregim kanar,

icimdeki Alevler durmadan yanar,

Beni anlayani bulamadim Canim.

Her gelen bir söz söyleyip gidiyor,

Bazi kullar iftirada atiyor,

Hasretin artik Yüregimi yakiyor,

Beni anlayani bulamadim Canim.

Belki ben anlatamiyorum derdimi,

belkide dinlemek istemiyorlar beni,

beni seven yokki hic senin gibi,

Beni anlayani bulamadim Canim.

Bütün Acilari ceke ceke yasadim,

Hasretinle hergün biraz daha yandim,

En sonunda Mutluluga artik inanmadim,

Beni anlayani bulamadim Canim.', 'BuLaMaDiM Tek basima yasiyorum sanki, Yüregimde kimseler yok, Etrafimda insanlar var ama, beni anlayani bulamadim Canim. Neler yasadim simdi...', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bulamadim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçükte Yüreğim', 'gocukte-yuregim-salim-calik-jgg9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'göçükte yüreğim

madenciliğe tutsak

      çocukların anasıyım

entari özlemi çeken kızların babası

ölenim/ kat kat galerilerde

göçükte kalanları bekleyen yüreğim

unutturmayacak halatların ucundaki ömrü

“geçmiş olsun” lu karşılamalar

yıllanmış acılar arasına sıkışık

günlük rahatlamalar

yanaklarımızı dövüyor gözyaşlarımız

  (ve öğrenemedik gözyaşlarının

                      rahatlatan satıcılığını) 

başkaldırının piç çocuğudur acılarımız

                               14.12.2001/ Armutçuk', 'göçükte yüreğim madenciliğe tutsak       çocukların anasıyım entari özlemi çeken kızların babası ölenim/ kat kat galerilerde göçükte kalanla...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gocukte-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-hasan-tahsin-azatli-uw322', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve oyun bitti

Perdeler kapandı

Yalnızlığa terk etti seyirci salonu

Gecenin sessizliğine kaldı 

O eşsiz replikler

Sona erdi tüm görkem, ihtişam

Sona erdi sahneler', 'Ve oyun bitti Perdeler kapandı Yalnızlığa terk etti seyirci salonu Gecenin sessizliğine kaldı  O eşsiz replikler Sona erdi tüm görkem, ihtiş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tahsin Azatlı']::text[], 8.5, '{"poet":"Hasan Tahsin Azatlı","poet_slug":"hasan-tahsin-azatli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BiTMeZ', 'bitmez-canan-kosmaz-3fo7u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BiTMeZ

Nasilda gecti onca Yillar,

Dertle dolu hayatan sirlar,

Izdirap veren O insanlar,

Bimez tükenmez Hasretin.

Nasilda Özlemisim seni,

Artik arayip sormuyorsun beni,

Bilemiyorum bu hasretin nedenini,

Bitmez tükenmez hasretin.

Neden halen ayriyiz biz,

gecmiyor Yüregimizdeki iz,

Dayanamiyor artik bedenimiz,

Bitmez tükenmez Hasretin.

Ne olursun birakalim artik,

Bizede Birtanem inan yazik,

Ömrümüz gecti bak artik,

Bitmez tükenmez Umutlar.', 'BiTMeZ Nasilda gecti onca Yillar, Dertle dolu hayatan sirlar, Izdirap veren O insanlar, Bimez tükenmez Hasretin. Nasilda Özlemisim seni, Art...', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitmez-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sevdim', 'seni-sevdim-mustafa-murat-aydogdu-wdnqp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En çok benim olanı severim sanıyordum,

Oysaki yanılmışım,en çok; Seni sevdim ben! 

                                       (Umarım mutlusundur)', 'En çok benim olanı severim sanıyordum, Oysaki yanılmışım,en çok; Seni sevdim ben!                                         (Umarım mutlusundu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/seni-sevdim-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GeL aRTIK', 'gel-artik-canan-kosmaz-eq1ba', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GeL aRTIK

Hasretin kor gibi Yüregimi yakiyor,

Hayalin gözümden bir türlü gitmiyor,

Caresini ariyor icim bulamiyor,

Yalvaririm dön gel artik Sevgillim.

Aramizdaki daglari artik asalim,

Gözümüzdeki perdeyi artik acalim,

Ne derlerse desinler aldirmayalim,

Yalvaririm dön gel artik Sevgillim.

Sen olmayinca kolum kanadim kirik,

Her engelli asacagim yikip,

Tek düsüncem seni koluma takip,

Yalvaririm dön gel artik Sevgillim.

Daha fazla dayanacak degilim,

herseyi göze alip gidelim,

Yeni bir hayati secelim,

Yalvaririm dön gel artik Sevgillim.', 'GeL aRTIK Hasretin kor gibi Yüregimi yakiyor, Hayalin gözümden bir türlü gitmiyor, Caresini ariyor icim bulamiyor, Yalvaririm dön gel artik ...', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-artik-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur', 'dur-yasar-tezel-zh3xh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Turp suyu iç

Yada şalgam

Acılı adana

Tavşanlı da acılı

Leblebi ye

Dur  bitmedi

Dibek ayran

Muhabbet

Memleketi görmeli', 'Turp suyu iç Yada şalgam Acılı adana Tavşanlı da acılı Leblebi ye Dur  bitmedi Dibek ayran Muhabbet Memleketi görmeli...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dur-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-salim-calik-f4s0x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne yürekte derman

ne düşlerde özgürlük

uyumlu sevdalar ardında

               dingin özlemler

birliktelikler topal

yitik yaşama sevinçlerimiz

seviniyoruz yaşadığımıza

                 23.08.2001/ Armutçuk', 'ne yürekte derman ne düşlerde özgürlük uyumlu sevdalar ardında                dingin özlemler birliktelikler topal yitik yaşama sevinçlerimi...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yitik-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'iNSaNLaR', 'insanlar-canan-kosmaz-ucom9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iNSaNLaR

Havada yine bir huzursuzluk var,

Barut kokusunu duyuyorum,

Yine kahrolasi savas basliyor,

insanlar birbirlerini Öldürüyor.

Neyi paylasamiyor insanlar,

Neyin kavgasini yapiyorlar,

Ne icin Savasiyorlar,

insanlar birbirlerini Öldürüyor.

Kimin malini kimden aliyorlar,

Dünya mali yine Dünyada kalir,

Bunu hic kavrayamiyorlar,

insanlar birbirlerini Öldürüyor.

Masum Cocuklar Vahsiyce katlediliyor,

aileler bir bir yikiliyor,

Hicbirsey eskisi gibi olmuyor,

insanlar birbirlerini Öldürüyor.', 'iNSaNLaR Havada yine bir huzursuzluk var, Barut kokusunu duyuyorum, Yine kahrolasi savas basliyor, insanlar birbirlerini Öldürüyor. Neyi pay...', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/insanlar-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KaRSILIKSIZ', 'karsiliksiz-canan-kosmaz-dptrt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KaRSILIKSIZ

Senin Askin gözlerimi kör etti Yar,

Hicbir sey göremez oldum,

Dogruyu yanlisi bilemez oldum,

Karsiliksiz sevdanla kavruldum.

Dostlarim bir bir yüz cevirdiler,

Ailedekiler bana deli dediler,

Töreler buna engel dediler,

Karsiliksiz Sevdanla kavruldum.

Bana Yar olamayacagini bile bile,

Seni beklerim Ömrüm yetikce,

Bana yüz vermesen bile,

Karsiliksiz Sevdanla kavruldum.

Sana deliler gibi baglanmisim,

Yüregime söz geciremiyorum,

Laf anlamiyor bu Kalbim,

Karsiliksiz Sevdanla kavruldum.', 'KaRSILIKSIZ Senin Askin gözlerimi kör etti Yar, Hicbir sey göremez oldum, Dogruyu yanlisi bilemez oldum, Karsiliksiz sevdanla kavruldum. Dos...', ARRAY['Türk Edebiyatı','Şiir','Canan Kosmaz']::text[], 8.5, '{"poet":"Canan Kosmaz","poet_slug":"canan-kosmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karsiliksiz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-salim-calik-z5w99', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni

sonbahar ölümlerinin

      kışa akan yalnızlığında

              aradım seni

seni hüzünlü iç çekişlerin

              kör derinliğinde

ilkbahar sevdalarının

      yaza akan bolluğunda

               özledim seni

seni denizi ilk kez kucaklayan

              bedevilerin şaşkınlığında

                     14.09.2001/ Armutçuk', 'seni sonbahar ölümlerinin       kışa akan yalnızlığında               aradım seni seni hüzünlü iç çekişlerin               kör derinliğinde ...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte İki Tip Gençlik', 'i-ste-i-ki-tip-genclik-seyfet-bozcali-ah48t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birisi kişilikli,ötekisi hoppala,

Birisi mütavazi,öbürü giyer son moda,

Birisi ilim alır,Öbürü hep barlarda,

İşte iki tip gençlik görüntüsü ortada...

Odası lüks döşeli,Bir yanda dolu barı,

Amerikan bardaysa,bolca viski ve rakı,

Tepişme müzik sesi,hiç düşünmez çevreyi,

İşte bu tip gençliğin,görüntüsü ortada...

Diğer  odada huzur,döşenişi çok sade,

Rafları kitap dolu,baş köşede seccade,

Çevresinde sevilir,çalışır gündüz gece,

İşte bu gençliğinde görüntüsü ortada...

İşte size tek gözlük,işte size iki tip,

Birinde aldanış var,uyuşmuş cebinde hap,

Biri asaletlidir,hem haya var hem edep,

İşte iki tip gençlik görüntüsü ortada...

Bir tarafta iman var,diğer tarafta boşluk,

Birinde ilim,ırfan,diğerinde sarhoşluk.

Birisi hayat dolu,ötekisinde boşluk,

İşte iki tip gençlik görüntüsü ortada...

Günahı sevabıyla,bu iki gençte bizim,

Hangisi övülmeli,göz sizin vicdan sizin,

Bir yanda gelecek var,Ötede vadi sisi,

İşte iki tip gençlik,görüntüsü ortada...

Seyfet der her şey açık,işte size iki tip.

Aynı ölçüyle baksak,sizce hangisi garip,

Birinde hep ziyan var,Öteki hakka talip,

İşte iki tip gençlik,Tüm görüntü ortada...

          16.02.2006', 'Birisi kişilikli,ötekisi hoppala, Birisi mütavazi,öbürü giyer son moda, Birisi ilim alır,Öbürü hep barlarda, İşte iki tip gençlik görüntüsü ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iste-iki-tip-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nizam-ı Cihan', 'nizam-i-cihan-hasan-tahsin-azatli-7108q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yiğit ölüyor

Bizim köyümüzde

Kimi kıvanç içinde

Naralar atıyor

Bir deli yatıyor

Bak şu dağlarda

Birkaç pusatlı yanında

Köyümüze çatıyor

Bir tüccar çıkıyor

Gözü bizim bağda

İki çizik atıyor kağıda

İmzalayacaksın diyor

Bir hain satıyor

Bütün köyü apansızca

Garip köylü darda

Yaşamaya çalışıyor', 'Bir yiğit ölüyor Bizim köyümüzde Kimi kıvanç içinde Naralar atıyor Bir deli yatıyor Bak şu dağlarda Birkaç pusatlı yanında Köyümüze çatıyor ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tahsin Azatlı']::text[], 8.5, '{"poet":"Hasan Tahsin Azatlı","poet_slug":"hasan-tahsin-azatli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nizam-i-cihan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşarım', 'seni-yasarim-ethem-turan-zb3ob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman, seni yaşarım 

İçime çektiğim nefesimde 

İçtiğim sigaramda

Güldüğüm,hatta ağladığım her anımda 

Seni yaşarım 

Yalan olsa da hayat 

Bir o kadarda güzel bence

Bazen coşarım 

Bazen küsüm sana 

Sevdiğime  olan kırgınlığım gibi

Kırgınım da

Mevsimlerin değişmesi gibi 

Değişiyorsun 

Ne zaman güleceğini bilemiyorum 

Umutla başladığım günümü

Yıkılmış terk ettiriyorsun

Hiç anlayamıyorum seni 

Bazen mest ediyorsun 

Hatta kuş olup uçasım geliyor

Bazen de ateşin alevi gibi 

Dalayıp geçiyorsun 

Nasıl uyum sağlanır sana 

Her şey bir yana 

Kıskandırmaların var ya 

Büs bütün kahrediyorsun 

Biliyorsun aslında 

Ben sadece seni yaşarım 

Sen benim zamanımsın 

Seni tüketirim  yalanda olsa

Mutlu olurum 

Her şeye rağmen severim 

Sarılırım sana 

Benim olduğunu düşlerim 

Umutla dolar içim 

Ben bir seni severim

Birde seni!', 'Zaman, seni yaşarım  İçime çektiğim nefesimde  İçtiğim sigaramda Güldüğüm,hatta ağladığım her anımda  Seni yaşarım  Yalan olsa da hayat  Bir...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/seni-yasarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup 7', 'mektup-7-salim-calik-c8e52', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir sevdadır yaşamak. soluk almaya yeni başlamışcasına, ölüme bir soluk kadar yaklaşmışcasına dolu dolu, ertelemeksizin dokunuşları, sevda sözlerini gecelere havale etmeksizin bir sevdadır yaşamak. İhanetin, yalanın, kahpeliğin yanı başımızda arkamızı dönmemizi beklediğini bilerek güvenmektir en umulmadık anlarda ve en umulmadık kişilere merhaba diyebilmektir yaşamak. 

yok sayıp tüm ayrılıkları bakışmalar armağan ederek güzellere, çocuklara ve geride kalanlara ömür bağışlayarak gidebilmektir yaşamak. yalnızlıklardan çoğulluklar çıkararak, kalabalıklar içinde bilinçlice yiterek denizde balık, gökyüzünde kuş, karada ağaç ve uzayda yıldız olabilmektir yaşamak. ve iç huzuruna ererek vicdanımız tarafından mahkum olmamaktır yaşamak.

     ey sevgili...!  ey güzeller güzeli....bıraktığımız iz izlek oluyor ardımızdakilere. söylenmiş olanlara ekleyerek sözlerimizi sevdaları büyütüyoruz yüreğimizde. kendimiz bile inanamayıp düşlerimizin büyüklüğüne anlıyoruz ki; sevdadır yaşamak. ve yaşamak her günü ve geceyi sevgililer günü ve gecesi ilan etmektir.

     her gece gökyüzündeki yıldızlarda birbirimizi çağrıştıracak yıldız kümelerine bakıp, birbirimize ulaşmak için ateş böceklerinin ışıklarıyla yola çıkabilme cüretidir sevda. bir çiçekten beklenmeyecek inat ve sabırla baharı muştulayan kardelenler gibi yokluklardan sevdayı ve sevgiliyi çıkarabilmektir yaşamak. 

     bir sevdadır yaşamak. kurşunlara, bombalara, tutukluluklara inat türkülerle, gülüşlerle, sevdanın özgürleştiren hamuruyla barışı bağırabilmektir yaşamak. ve yıllar da geçse sözümüzü, adımızı,kavgamızı miras bıraktığımız çocuklarımızın gönenciyle  kendimizden vazgeçebilmektir yaşamak.     	 

HAPİSHANE ŞARKISI     1

Göklerde kartal gibiydim,

Kanatlarımdan vuruldum; 

Mor çiçekli dal gibiydim,

Bahar vaktinde kırıldım.

Yar olmadı bana devir,

Her günüm bir başka zehir; 

Hapishanelerde demir

Parmaklıklara sarıldım.

Coşkundum pınarlar gibi,

Sarhoştum rüzgarlar gibi; 

İhtiyar çınarlar gibi

Bir gün içinde devrildim.

Ekmeğim bahtımdan katı,

Bahtım düşmanımdan kötü; 

Böyle kepaze hayatı

Sürüklemekten yoruldum.

Kimseye soramadığım,

Doyunca saramadığım,

Görmesem duramadığım

Nazlı yarimden ayrıldım.

	Sabahattin ALİ

25 Şubat 1907- 02 Nisan 1948

	Öldürülüşünün 57. yılında 98 yaşını da geride bıraktı Sabahattin Ali. Öldürenler Sabahattin Ali’yi öldürdükleri için, ama katil olarak yaşıyorlar halkımızın ve sanat dünyamızın bilincinde. Sanatın ve sanatçının ülkelerin gelişimindeki en etkili güç olduğunun anlaşılacağı, tüm insanlığın kavgasız ve barış içinde yaşayacağı günler de gelecektir mutlaka.', 'bir sevdadır yaşamak. soluk almaya yeni başlamışcasına, ölüme bir soluk kadar yaklaşmışcasına dolu dolu, ertelemeksizin dokunuşları, sevda s...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mektup-7-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup 8', 'mektup-8-salim-calik-3r6sr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni düşünerek büyütüyorum günlerimi. kendimi seni düşünerek. sevgilim benim. canım. baharı seni düşünerek karşılıyorum. sen ki cemremsin toprağıma düşen. sen ki ilk çiçeğimsin kollarımda açan.

     seni düşünerek varıyorum yitirdiğim ülkelere...içinde ağlayanların olmadığı, sarı saçlı Çingene çocuklarının çocuklarımızla büyüdüğü, dünyanın tüm ezilen halklarının kardeşliği oya gibi işlediği, yaşamı insani doğallığıyla dokuduğu ülkelere seni düşünerek ulaşıyorum.

     gecelerin güzelliğini seni düşünerek buluyorum. gözlerinin bir güneş gibi bedenimi ısıtıp, odamı aydınlatacağını bilerek söndürüyorum tüm ışıkları. yıldızların, ayın ve gezegenlerin saçtıkları ışığa senin sevdanın tüm enerjisini dahil ediyorum. ve etrafında deli divane bir uydu olup mutluluktan dolanıyorum tüm evreni.

     seni düşünerek kapatıyorum gözlerimi. ve yüreğimi ardına kadar açıyorum seni düşünerek. köylü kadınlarının ellerindeki nasırları izleyerek buluyorum üretkenliğin yolunu. madencilerin alnındaki fenerle tadına varıyorum emeğin sevince dönüşmesinin. kendimi buluyorum. ve alnımın akıyla seviyorum seni...

     çocuklarla sokak aralarını arşınlıyorum. gözüne girmek ve kendimi beğendirmek için olmadık işler yapıyorum. yaşımı ve bilinç durumumu bırakarak bir duvar dibine kahramanın olmaya soyunuyorum. seni düşünerek krallıklara, derebeyliklerine tek taraflı savaşlar ilan ediyorum. seni düşünerek yerleşik düşüncelerden arınıp devrimlere yöneliyorum.

	

     seninle yaşayabilmenin tadına varabilmek için seni üzen, seni ağlatan, seni hüzünlendiren, seni senden alan tüm kötülüklere başkaldırıyorum.  istiyorum ki, aramıza ne kötülüklerin izi, ne de kendileri girsin. biliyorum ki, mutlu bir sevda çevremizdekilerin mutluluğundan geçiyor. biliyorum ki, mutluluk acıların paylaşılmasından geçiyor. ve biliyorum ki, biz istemezsek sürmez bu bezirgan saltanatı.

     sevgilim benim. düşlerimin tahtına kurulmuş güzel. seninle olabilmek uğruna kendi krallığımı devirerek geliyorum sana. şanı, şöhreti, namı bırakarak aşıyorum kendimi. biliyorum ki, kendi iktidarından vazgeçemeyenlerin verebileceği birşey yok dünyaya... ve kendimi veriyorum sana. kendimi... tüm bildiklerimi, öğrendiklerimi, değerlerimi, kültürümü bağışlayarak sokak çocuklarına sana geliyorum. beni yeni baştan yaratman için kendimi parça parça dağıtıyorum sokaklarda...

     seni düşünerek hiçbir şey olmamanın erdemine varıyorum. senden öğrendiklerimle ulaştığım bilgeliğimi dünyanın pisliklerinin üzerine sürüyorum. ve bir kurşun oluyorum yoksulların ağızlarında. tükürsünler diye “hayının, celladın yüzüne” 

	

     şimdi seni sevmenin gönenciyle bulduğum varsıllıklara sarılıyorum sıkı sıkı. tüm anlamalarımı, kabullerimi gözden geçirerek, daha cesur ve daha bilge duygularla seviyorum seni. şimdi bir nevroz ateşi gibi yanıyorsun içimde. ve tüm sevdalılar, bu dünyayı değiştirmeye yola çıkmış olanlarla birlikte barışın, dayanışmanın türkülerini söylüyoruz memleketimizde. 

     tüm kavuştuklarımızın tarihini bayram ilan ediyoruz. bayram ilan ediyoruz tüm halkların elele tutuştuğu günleri. ve adını koyuyoruz ömrümüzün. sevdaların onbeş dakikaya, bir güne indirildiği dünyamızda yıllarca sürmüş sevdamızla geçiyoruz popüler kültür duraklarını. ve belki de tüm dünyaya inat doğanın sözüne uyarak elimizdekileri çoğaltıyoruz. 

     seni düşünerek başlıyorum yeni güne. ve seni yazmaya çalışarak. ve tarihimize not düşüyor olmak yetiyor günlerimizin çoğalmasına. biliyorum ki, bırakacağımız başkaca varlığımız olmayacak bizim. biliyorum ki seni düşünüyor olmak biraz daha büyütecek bilincimi. biraz daha beni. biraz daha dünyamızı...

     ve biliyorum ki, aslolan iyi yaşamaktır. sevdaları çoğaltarak... yeni sevdaları bahar çiçekleri gibi örgütlemektir yaşamak. bilinçle örerek yeni bir yaşamı şiirler, şarkılar, danslar eşliğinde el ele tutuşmaktır tüm insanlıkla ve kendi insanlığımızla...

                                                  04.03.2005   23:53  Armutçuk', 'seni düşünerek büyütüyorum günlerimi. kendimi seni düşünerek. sevgilim benim. canım. baharı seni düşünerek karşılıyorum. sen ki cemremsin to...', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mektup-8-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Moda', 'moda-salim-calik-htlho', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bellerde cep telefonları

duvarlarda resimler

varsıl otoları altımızda

ve açlık

boylu boyunca organlarımızda

                          04.09.2001', 'bellerde cep telefonları duvarlarda resimler varsıl otoları altımızda ve açlık boylu boyunca organlarımızda                           04.09....', ARRAY['Türk Edebiyatı','Şiir','Salim Çalık']::text[], 8.5, '{"poet":"Salim Çalık","poet_slug":"salim-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/moda-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kütahya', 'kutahya-yasar-tezel-9ptky', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Diyarlar var, sen başka

Bilmezler şehri emindir

Kütahya

Evliya Çelebinin şehri

Dönenlerde gizemi

Saray işlemeli çini

Ahmet yakuba

Çizdirmeli resmi

Ezan sesleriyle ulu caami

Yandıkça bol bol

Türkmen su içmeli

Çinilide yatsı namazı

Yoncalıda hamam sefası

Muratdağı,Ilıcası

Saman pazarı

Sedirler içi,sıcacık çay

Hisaraltı

Gözlemesi,yareni

Şipit yanında

Unutma 

Kütahya maden yatağı

Alimler duraği

Tahinli pidemiz

Türküleriyle

Ahmet Hisarlı

Germiyan konağı

Çeyizimiz,efemiz

Hayme Anası

Ekmekçi baba 

Medreseleride varya

Hisarda tasavvur

Hıdırlıkta  aşka,duaya

Yaban,ıyla Karaosmanoğlunun

Porsuk,

Temiz hava,çamlıca

Burası Kütahya

Medeniyettler eşiği

Çavdarhisar

Bor zengini 

Emetimiz var

Ateşinde çiçekler açar

Abide,Dumlupınar

Kütahyaya davet var', 'Diyarlar var, sen başka Bilmezler şehri emindir Kütahya Evliya Çelebinin şehri Dönenlerde gizemi Saray işlemeli çini Ahmet yakuba Çizdirmeli...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kutahya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp İlanı', 'kayip-i-lani-atilla-guler-vy7yh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir ilan gazetede

tam sayfa:

KAYIP! 

KENDİMİ KAYBETTİM! 

Bulanların insaniyet namına aşağıdaki adrese teslim etmesi rica olunur.

Getiren(ler)  tatminkar bir şekilde ödüllendirilecektir...

ben

…yokum

artık kendimi bulamıyorum

kayıp insanlarla dolu bu kayıp şehirde

bir anda yok oldu her şeyim

göz yaşlarım…gülüşlerim

deli öfkem…duru sakinliğim

hiçbir şeyim oldu bir anda her şeyim

ben kayboldum

kaybolduk biz 

batmadan güneş

kaybolmadan ufukta…iyice

lacivert akşamların ıssızlığında

sarhoş şarkılarına eşlik etmeden

bulsa biri beni

ya da ben bulsam kendimi

bu koca kayıp şehirde

kayıp bir insan! 

duyurulur

kendimi arıyorum

yorgunluk benden uzak

her gün…her gece', 'bir ilan gazetede tam sayfa: KAYIP!  KENDİMİ KAYBETTİM!  Bulanların insaniyet namına aşağıdaki adrese teslim etmesi rica olunur. Getiren(ler...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kayip-ilani-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olur Olmaz Anlarda, Bulunmaz yanında', 'olur-olmaz-anlarda-bulunmaz-yaninda-ramazan-ates-txkce', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapkara gecede yıldızlar parlar,

Yarasa çığlıkları geceyı yarar.

Ve uzaktan köpek havlamaları,

Gözlerim o anda sevgili arar.

Rüzgar vurur sallanır ağaçlar,

Hafif bir serinlik yüzlerde.

Bazen bir yıldız kayar,

O anda gözlerim sevgili arar.

Bazen bir keman sesi komşu evinde,

Kemancı, başımın tacı dertli çal,

Yanık yanık nameleri duyulur.

Benimde gözlerim sevgili arar.

Tutupda elinden mehtaba dalmak,

Geceyi, yıldızı, bulutu yarmak,

Uzanmak geceye, hayale dalmak,

Bak yine gözlerim sevgili arar,

Her gece gözlerim sevgili arar.

Ramazan Ateş/Enschede-16.2.2006', 'Kapkara gecede yıldızlar parlar, Yarasa çığlıkları geceyı yarar. Ve uzaktan köpek havlamaları, Gözlerim o anda sevgili arar. Rüzgar vurur sa...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olur-olmaz-anlarda-bulunmaz-yaninda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükürler Olsun Mevlam Bu Günleride Gördüm', 'sukurler-olsun-mevlam-bu-gunleride-gordum-seyfet-bozcali-v5qsv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsteklerim halloldu,dilekler kabul oldu,

Şükürler olsun Mevlam bu günleride gördüm.

Önce evlatlar verdin, sıra toruna geldi,

Şükürler olsun Mevlam,birde torunum oldu...

On Altı şubat günü,günlerden perşembeydi,

Saat ona gelmişti,kulak beklemekteydi,

Hanım telefon etti,Torunun oldu dedi,

Şükürler olsun Mevlam bir kız torunum oldu...

Yaşlılığım anladım,dedelere karıştım,

Rabbime niyaz ile bu günlere ulaştım,

Sevgiler eskimeden yenisine ulaştım,

Şükürler olsun Mevlam bu günlere kavuştum...

16.02.2006  Perşembe', 'İsteklerim halloldu,dilekler kabul oldu, Şükürler olsun Mevlam bu günleride gördüm. Önce evlatlar verdin, sıra toruna geldi, Şükürler olsun ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sukurler-olsun-mevlam-bu-gunleride-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle güle gurban', 'gule-gule-gurban-reyhan-tataroglu-fx1dp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sende mi bu diyarı terk ediyorsun gurban

                        Selamına  aleyküm selam demeden daha

                        Duygularım kervan yükü gibidir şu an 

                        Dostluklar unutulmaz,unutmayalım sakın ha! 

                        Hangi rüzgar götürür seni buralardan

                        Poyraz mı,karayel mi yoksa sam yeli mi

                        Kırklara,yedilere eşlik eden turnalardan

                        Söylesene hangisi,yoksa adam eli mi

                        Bu değirmen kimleri un etmediki

                        Ağızda bir lokma ekmek olmak gerek

                        Kimler Mevla için buğday ekmediki

                        Kimi sarı,kimi kırma,kimi de gerek

                        Lafa aldırma gurban git selamette

                        Hakka secdede dere,tepe fark etmez

                        Dünya yalpalıyor,sıra büyük alamette

                        Rabbim, sözlerinden haşa çark etmez

                        Ateşin kalır,bu diyarlardan gitsen de

                        Yazın beni,kışın bedeni yakar

                        Değil kalem,sopa ile davar gütsen de

                        Biliyorum,Hak için olacaksın vakar', 'Sende mi bu diyarı terk ediyorsun gurban                         Selamına  aleyküm selam demeden daha                         Duygularım ker...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gule-gule-gurban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimden Tutup Götürdüm Beni', 'elimden-tutup-goturdum-beni-ramazan-ates-rfbw3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni benden alıp kaçırmak için,

Alemden aleme uçurmak için,

Bir şey arıyorum,

Adını sen koy...

Gözlerim gözümden çekip almalı,

Ellerim elimden çıkıp gitmeli,

Bir şey istiyorum,

Adını sen koy...

Gönlüm gönlümden ayrılsın,

Ruhum uçup gitsin, aklım kaybolsun,

Bir şey diliyorum,

Adını sen koy...

Tutup da elimden götürsem beni,

Bulutlar üstünde yatırsam beni.

Bir şey hayalliyorum,

Adını sen koy.

Aklımı masaya koydum, düşündüm.

Yüreğim yanında, birazda ürktüm.

İkisi bir olmuş, yalan mı korktum,

Beni bana verecek bir şey isterim,

Adını boşver sen,  ben, SENİ isterim.

Ramazan Ateş/Enschede-16.2.2006', 'Beni benden alıp kaçırmak için, Alemden aleme uçurmak için, Bir şey arıyorum, Adını sen koy... Gözlerim gözümden çekip almalı, Ellerim elimd...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/elimden-tutup-goturdum-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki damla gözyaşı 3.Bölüm', 'i-ki-damla-gozyasi-3-bolum-ayhan-isin-9f7gt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arzu’nun babası son eşyaları da kamyona yüklemişti. Kemal,  babası annesi çok üzgündüler. Hiç bir zaman ayrılmamışlar çocuklukları bile beraber geçmişti. Seneler var dı ki bu kadar maddi sıkıntıları olmamıştı. Her zaman birbirlerine destek olmuşlar. Baba evlerini terk etmemişlerdi ama artık dayanacak halleri de kalmamıştı. Fakat çok ta uzak değildi şehir. Gidip gelmek mümkündü. Sabah bir minibüs gider akşam döner di. İş iyi olunca orada ev tutmak daha akıllıca gelmişti. Hem seneye Arzu’da Kemal’de Üniversite için dershaneye başlayacaklardı. Şehirde ev iki aile içinde bir avantajdı. İki aile birbirlerine sıkı, sıkı sarıldılar, helalleştiler. Arzu ile annesi kamyonun önüne oturdu, babası kamyonun kasasına. Kemal’lin annesi kamyon giderken, bir kova su döktü ve su gibi gidin su gibi gelin diye dilekte bulundu. Kemal kamyonun arkasından gücünün tükendiği yere kadar koştu. Gözlerinde yaşlar boşalıyordu. Hem arkadaşı, hem de sevgilisi gidiyordu. Bir an kendini yapayalnız boşlukta hissetti içi ürperdi. Yüreğinde bir sızı çız etmişti. 

 ……………. Arzu yol boyunca ağladı. Annesi onu teselli etmek için hafta sonları  ‘Kemal gelir yine oynarsınız’ diyordu. Ama nafile gözyaşları dinmek bilmiyordu. Tam kavuşmuşken duygularını açmışken, bu ayrılık hiçte iyi olmamıştı. Kemal’in kokusu sanki buram, buram yanı başından geliyordu. Ama söz vermişlerdi, bitmeyecekti aşkları. Yüce dağın karları erimeyecekti, Aşklarını sonsuza kadar saklayacaktı.

 ……………… Kemal’le Arzu ertesi sene dershaneye başladılar. Hafta sonları beraber dershaneye gidiyorlar. Kemal Cumartesi akşamları Arzu’larda kalıyor. Beraber ders çalışıyorlar. Bazen göz, göze geliyorlar, dakikalarca gözlerini ayıramıyorlardı. Arzu’nun annesi bu durumu fark ediyor ama ses çıkarmıyordu. Çünkü Kemal’i çok severdi. Hiç yanlış bir hareketini görmemişti. Bu konuyu Kemal’in annesiyle de konuşmuşlardı. Kemal’in annesi onlar kardeş gibi büyüdüler zannetmem ama aşk bu bellide olmaz böyle bir şey olsa kabul eder misin? Diye sormuştu. Oda babaları kabul ederse niye olmasın Kemal’den daha iyisini mi bulacağız diye konuşmuşlar ama daha çok erken önlerinde üniversite var. Belki kazanamazlarsa düşünürüz demişlerdi.

 ………………. Üniversite sınav sonuçları gelmiş, Arzu İstanbul’da Ziraat Fakültesini, Kemal Ankara Veteriner Fakültesini kazanmış sevinçleri kursaklarında kalmıştı. Kader yine ayıracaktı. Dört yıl ayrı kalacaklardı. Ama onlar dayanacaklar bitirecekler ve güzel kasabalarında hizmet edeceklerdi. Böyle karar almışlar ve okuldan sonra sonsuza kadar beraber olacaklardı. Babalarıyla ayrı, ayrı gittiler kayıtlarını yaptırdılar. 

……………… Kasabalarındaki okulda öğretmenler hem mezuniyet, hem de üniversiteye girenler için bir eğlence düzenlemişlerdi. Onlarda katıldılar bir kenarda oynayanları seyrediyorlardı. Garip bir hüzün vardı içlerinde. En son bir dans müziği eşliğinde öğretmenleri dans ediyorlardı. Birden Kimya öğretmenleri yanlarına geldi. Haydi, çocuklar siz niye dans etmiyorsunuz dedi ve zorla onları dansa kaldırdı. Onlar bu güne kadar böyle bir ortamda hiç bulunmamışlar dans bile etmeyi bilmiyorlardı. Ama öğretmenleri onlara gösterdi. Elleri ayakları karışmıştı. Kemal Arzu’nun ayaklarına basıyor. Arzu hep ayaklarına bakıyor. Birbirlerinden uzak duruyorlar. Bir türlü beceremiyorlardı. Sonra Arzu Kemal’le yaklaştı, artık çok yakındılar. Kemal’lin nefesini, kalp atışlarını bile duyabiliyordu. Şimdi uyum sağlamışlar sahnede kuğu gibi süzülüyorlardı. Artık öğrenmişler. Müziğin ve ahengin büyüsüne kapılmışlar. Kırk yıldır dans edebiliyorlarmış gibiydiler. Öğretmenleri onları alkışladılar. Kemal’de Arzu’da çok utanmışlar, yüzlerinden ateş çıkıyordu sanki! Ama dans etmeye devam etiler, çünkü dans etmek harika bir duyguydu. Arzu ve Kemal yaşadıkları her şey gözlerinin önünden geçti. Birbirlerini öpmek istediler ama burası küçük bir yerdi, dans etmeleri bile bayağı konuşulacaktı. Zaten öğretmenleri istemişti. Bahaneleri hazırdı masum bir dans. Müzik de bitmişti. Birbirlerini alkışladılar ve yerlerine döndüler. Kimya öğretmenleri yanlarına geldi. Bak nasıl oluyormuş çok şahane dans ettiniz, birbirinize de çok yakışıyorsunuz dedi. Sakın ayrılmayın bence demişti. İkisi de soğuk terler döktüler öğretmenleri böyle düşünüyorsa kim bilir. Başkaları ne düşünürdü. Ama zaten onlar çocukluktan beri beraberdiler. Korktukları gibi bir şey olmadı, hiç laf çıkmadı. Ama kasabalı onların evlenmesi için içlerinden geçirir, inşallah gerçekleşir derlerdi.

………………İkiside kasabada, şehirde çok güzel günler geçirdi. Artık okullarının açılmasına üç gün kalmıştı. Yalnız beraber bir gün geçirmek istiyorlardı. Her zaman aileleriyle birlikte gittikleri, deniz kenarına gitmek yüzmek ve piknik yapmaya karar verdiler. Akşam ailelerine ertesi gün arkadaşlarıyla buluşup bir yerlere gideceklerini söylediler izin aldılar. Gidecekleri yerden sabah bir minibüs geçer ve bir kasabaya gider dönüşte ancak akşam mümkün olurdu. Sabah erkenden kalktılar yanlarına biraz ekmek üzüm, peynir, domates, salatalı ve bir bidon su alarak çıktılar. 

………………Minibüse bindiler şoföre akşam bizi unutma diye tembih etiler ve orada indiler. Burası harika bir yerdi zeytin ağaçları sahilde denize yakın çınar ağaçları var,  muazzam bir kumsal kuytu bir koydu. Vardıklarında hafta arası olduğu içinde kimsecikler yoktu. Güzel bir gün olacaktı. Önce soyundular denize girdiler uzun, uzun yüzdüler şakalaştılar sonra eski günlerden bahsettiler yüce dağdan, sakladıkları gözyaşlarından yağmurda öpüştükleri o harika günden. Sonra denizin kumları okşadığı yerden kâh koşarak, kâh yürüyerek harabelerin olduğu yere geldiler. Aileleri harabelere girmemeleri için hep uyarırlardı. Onlar bu gün oraya gireceklerdi. Önce tereddüt ettiler sonra taşların üzerinden yürümeye devam ettiler. Dev gibi kayadan kesilmiş duvarlar bazı heykel parçaları testi kırıkları sanki ayak basılmamış gibi otlar bitmiş. Roma kemerleri gibi ardı ardına dizilmiş sütunlar vardı. Bunları arasında belki iki yüz yıllık beklide daha eski keçiboynuzu ağacı duruyordu yorgun bir hali vardı. Dibine geldiler keçiboynuzlarından yemeye başladılar. Kemal çakısı ile bir şeyler yapmaya çalışıyor. Arzu da keçiboynuzunu kemirmeye çalışıyordu. Kemal bağırdı. Nihayet bitti. Arzu bak ne yaptım. Bir kalp ve içinde AK yazıyordu. Niye daha önce düşünemedim. Evet, bizim sevgimiz saf ve temiz yani AK, yani beyaz! Ama ağaç için üzüldüm gövdesinde bir yara açtım. Canı acımıştır. Arzu boş ver bizim sevgimiz onu iyileştirir. Haydi, kıyıya yürüyelim bak orada bir yapı var. Bak çatısı cami kubbesi gibi yapılmış. Arzu bak çok güzel bir resim var içinde. Evet, bir erkek bir kadın erkeğin elinde sanırım defneyaprağı var. Kadına veriyor. Kadında çok güzel hop, hop benden güzel mi? Kemal hiç Arzu’ya böyle bakmamıştı. Arzu minyon yüzlü kaşları alınmış gibi incecik uzun, uzun kirpikleri, kahve renkli gözleri, biraz yukarı kalkık burnu, dolgun dudakları, ufacık ağzı, beline kadar uzanan saçları, ince beli dolgun kalçaları uzun düzgün bacakları, esmer teniyle sanki bir ressamın tuvalinden çıkmış gibiydi. Niye hiç aklına gelmedi diye hayıflandı içinden. Ama zaten hep aklında gözleri kalmıştı ışıl,  ışıldı. Baksana senden çok güzel o kadın ama bence bin yaşında vardır. Seni ben bir elime alırım görürsün güzelin kim olduğunu. Heh işte buradaki erkek hem senden güçlü hem de yakışıklı. Kemal böyle bir tepki beklemiyordu. Ama benim kadar sana âşık değil, dedi ve Arzu’nun belinden çektiği gibi dudaklarına yapıştı. Arzu ne olduğunu anlayamadan, Kemal’in sıcak ve şehvetli dudaklarını öpmeye başlamıştı bile. Çok uzun bir süre seviştiler ve zamanın nasıl geçtiğini bile düşünmediler. Arzu arada duvardaki resme gözü takılıyor. Sonra öpmeye devam ediyordu. Sanki onlarımı seyrediyorlardı. Bir ara duvardaki boşluğa gözü takıldı. Herhalde şömine gibi kullanmışlardı duvarda isler siyahlaştırmıştı. Bu sevgililerin evlerinin bir bölümüydü herhalde kim bilir ne şehvetli akşamlar geçirmişlerdi. Kemal hala öpüyordu artık o harika kokuyu da duymaya başlamıştı. Bu iki tenin birleşmesinden çıkan,  bazıları için kötü kokuyor diye bileceği ama onun için leylaklardan bile güzel kokan harika bir kokuydu. Arzu  ve Kemal artık yorulmuş duvara dayanmışlar, dileniyor dinleniyor sevişiyorlardı. Harika bir gündü bitmesini istemiyorlardı. 

……………… Her şey bitmemişti. Kemal mayosunun cebinden minik bir kutu çıkardı. Bu tek taş bir yüzüktü. Benimle,  evlenirmisin? Dedi. Arzu elini uzattı biz zaten yüce dağda evlenmiştik dedi. Kemal ben şimdi seninle evlenmek isterdim ama önümüzde üniversite var ve senin hayallerini yıkmak istemem. Onun için bazı şeyleri düğünümüze bırakmamız gerektiğine inanıyorum. Ne dersin aşkım. Ben her şeyin burada biteceğini düşlüyordum ama bekleyeceğiz acele etmeyeceğiz çok çalışacağız ve sonsuza kadar beraber olacağız Kemal değil mi?  Kesinlikle Arzu. Sakın verdiğim yüzüğü çıkarma bu bizim nişanımızın simgesi ama ben sana bir şey almamıştım. Bir dakika koşarak dışarı çıktı. Elinde bir defne dalıyla geri döndü ve buda benim nişanım olsun. Kitaplarının arasına koy, benim kokumu özlediğin zaman koklar nişanımızı unutmazsın. Bu armağan benim için çok değerli bunu hep saklayacağım ve gelinliğinin duvağına iliştireceğim dedi Kemal. 

……………… Sonra kalktılar dönmek için harabelerden ayrıldılar. Kumsalda yürüdüler denize girdiler. Getirdikleri azıkları yediler. Giyindiler sürekli öpüştüler, öpüştüler, öpüştüler. Akşam olmuş gökyüzü kızarmaya başladığında minibüse binmişlerdi.

…………….. Ertesi gün hazırlık yaptılar otobüs biletlerini aldılar. Yine günü beraber geçirdiler ama içlerindeki sızı hiç dinmedi. Arzu, Kemal’le çarşıdan iri bir gözboncuğu aldı bunu yanından sakın ayırma sana nazar deymesin dedi. Bu uzun bir ayrılık olacaktı. Sabah aileleri ile vedalaştılar ayrı, ayrı otobüslere bindiler.  Birbirlerine el salladılar. Yol boyunca ikisi de çok ağladılar. Ama yarıyıl tatilinde görüşeceklerini düşünerek kendilerini teselli ettiler.    

 		

             

 16–02–2006', 'Arzu’nun babası son eşyaları da kamyona yüklemişti. Kemal,  babası annesi çok üzgündüler. Hiç bir zaman ayrılmamışlar çocuklukları bile bera...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iki-damla-gozyasi-3-bolum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık Duygusu', 'pismanlik-duygusu-salim-erben-h7ax8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceler karanlık olur korkarım 

Şafak sökmeden yıldızlara bakarım 

Kara bulutlar döner yanı başımda 

Korkudan ben ağlarım anne 

Yastığım taştan yorganım bezden 

Usandım dağlarda söylene sözden 

Yürekten söküp atma düşsem de gözden 

Dağlarda pisi pisine ölürüm anne 

Saçım sakalım pislikle doldu 

Şeytan dağlarında sığınak boldu 

Aslan sandığımız çakal oldu 

Parça parça olmaktan korkarım anne 

İnsan diye hayvanlar bile tanımaz 

Bizde cenaze namazı kılınmaz 

Kurt kuş yer parçası bulunmaz 

Akıbetimden korkarım anne 

Biz ölümü çoktan hak ettik 

Duyduk sempati peşinden gittik 

Yüzlerce vatandaşı katlettik 

Çoluk çocuk demeden anne 

Apo’su Şemdin’i, Karayılan’ı 

Bir gün anlaşılır bunların yalanı 

Bin pişman dağda olanı 

Mezarımı bilen olmaz anne 

Salim ERBEN (Zalım)', 'Geceler karanlık olur korkarım  Şafak sökmeden yıldızlara bakarım  Kara bulutlar döner yanı başımda  Korkudan ben ağlarım anne  Yastığım taş...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/pismanlik-duygusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok daha işin vardır', 'cok-daha-isin-vardir-mikdat-bal-vauf4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok daha işin vardır, arkadaşım kendinle 

Meselâ bir kaç tane, ben diyeyim sen dinle 

Yazdıkların yorarsa, oturup dinlenirsin 

Niyet ciddi kararsa, islamla dinlenirsin 

İslam nedir sorulsa, sen, tereddütsüz din de 

Mükemmeldir, eksik yok, diken yoktur bu dinde 

Hatırlatmak istedim, biliyordun kendin de 

Bazısı fetva verir, birşey bilmezken dinde 

Dinlenirken, DİNlenir,dinlenmeyesi kişi 

Dinleyen, DİNlenmeden dinlenmek olur işi 

Sen boş ver el alemi, üzmeyesin kendini 

Üzmene gerek de yok, kendin bilirken dini 

Bir kumaş parçasına, iğne ile gül diken 

Diken bir usta ise, belli olur gül, diken', 'Çok daha işin vardır, arkadaşım kendinle  Meselâ bir kaç tane, ben diyeyim sen dinle  Yazdıkların yorarsa, oturup dinlenirsin  Niyet ciddi k...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cok-daha-isin-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterki Üzülme', 'yeterki-uzulme-ramazan-ates-27g39', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırak benim ellerimi,

Sana acı veriyorsa.

Bakma artık gözlerime,

Yüreğini yakıyorsa.

Seni mutlu ol isterim,

Her an neşe dol isterim.

İstemezsen gelme bana,

Aşkım seni sıkıyorsa.

Beni boşver, düşünme sen,

Unut gitsin, istemezsen.

Yüreğine sor bir defa,

Çek git artık sevmiyorsa.

Taş basarım ben gönlüme.

İnan düşmem hiç peşine.

Mutsuz isen sen benimle,

Bakma artık, gözlerime,

Acı verme sen kendine.

Ramazan Ateş/14.2.2006', 'Bırak benim ellerimi, Sana acı veriyorsa. Bakma artık gözlerime, Yüreğini yakıyorsa. Seni mutlu ol isterim, Her an neşe dol isterim. İstemez...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yeterki-uzulme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her söz nasıl şiir olsun?', 'her-soz-nasil-siir-olsun-mikdat-bal-nsvvf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neye yarar kalem kağıt 

Herkes yazamaz bir ağıt 

Bir bildiğin varsa tağıt 

Okuyanlar mahir olsun 

Senin gibi şair olsun 

Şiir yazmak içten gelir 

Yani ilham, hiçten gelir 

Sezgi denen güçten gelir 

Her söz nasıl şiir olsun? 

Herkes nasıl şair olsun? 

Herkes yazar anlayan yok 

Bu işi pilanlayan yok 

Şimdi şair olmayan yok 

Yazar ister zehir olsun 

Herkes nasıl şair olsun 

Şiir yazmak ciddi olay 

Bu meslekle etmem alay 

Evet bu iş değil kolay 

Hekes nasıl mahir olsun? 

Senin gibi şair olsun', 'Neye yarar kalem kağıt  Herkes yazamaz bir ağıt  Bir bildiğin varsa tağıt  Okuyanlar mahir olsun  Senin gibi şair olsun  Şiir yazmak içten g...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/her-soz-nasil-siir-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son-Uç', 'son-uc-reyhan-tataroglu-r9gdw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne çabuk geldin,ne çabuk çaldın kapımı

                        Daha dün gittin hayırlı günler dileyerek

                        Yeni tanıyorum hayatı, eşimi,dostumu,ahbabımı

                        Kah onun,kah bunun yanında zevk eyleyerek

                        Unutursun diyordum ziyaret etmeyi,belkide umarak

                        Çünkü ben öyle yapmıştım,işin kolayı buydu

                        Deliksiz uykular çekiyordum gerçeklere göz yumarak

                        Ne başım ağrıdı,ne dişim,ne de kulaklarım duydu

                        Taa ki ayak seslerini duyana kadardı bu saltanat

                        Öyle kararlıydın ki,elçiye zeval olmaz diyordun

                        Uçacak,kaçacak yerim kalmadı,kırıldı kol kanat

                        Sessizce selam verip,can evime giriyordun

                        Desem ki söz veriyorum hiç aklımdan çıkarmayacağım 

                        Telaşa kapılmanın anlamı yoktu,değişmeyecekti sonuç

                        Sultanın gönderdiği emirleri tutup,bir bir uyacağım

                        Burası başlangıç değil,artık burası dünyadaki son-uç', 'Ne çabuk geldin,ne çabuk çaldın kapımı                         Daha dün gittin hayırlı günler dileyerek                         Yeni tanıyor...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-uc-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Mi?', 'ben-mi-mikdat-bal-7p86w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben 

Mi? 

Seni

Sevdim

Yoksa

Sen 

Mi? 

Beni

Sevdin

Söyle

Sevdi

İsen

Sen de

Beni

Sevdim

Söyle

Bakma

Öyle

Karşılıklı

Söylenmeli

Pekişir

Aşk

Hayat

Böyle....', 'Ben  Mi?  Seni Sevdim Yoksa Sen  Mi?  Beni Sevdin Söyle Sevdi İsen Sen de Beni Sevdim Söyle Bakma Öyle Karşılıklı Söylenmeli Pekişir Aşk Hay...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-mi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Tut', 'zamani-tut-ramazan-ates-9u6bu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırakın siz artık, garezi kini,

Sevgiyi yaşasın güzel gönüller.

Hüzünle geçmesin kısacık ömür,

Mutlu olsun artık, gülsün hep yüzler.

Ömür kısa, ecel desen tez gelir,

Bir ömürse bir sevdaya az gelir.

Kaybedecek vakit mi var? Gün mü var? 

Saglık, sıhhat, sevgi dolsun gönüller.

Sevgi ömür uzatırmış diyorlar,

Elbette ki, bir şey bilip diyorlar.

Niye hala boşa gönül kırarlar? 

Sımsıcacık sarsın artık o kollar.

Gün geçmesin,  zamanı tut, anı tut,

Kini, garezi, nefreti gel unut.

Bir çiçek ver, bir tebessüm, bir umut,

Ta yürekten sevgi sunsun bu canlar,

Mutlu olsun, artık gülsün hep yüzler.

Ramazan Ateş/Enschede-14.2.2006', 'Bırakın siz artık, garezi kini, Sevgiyi yaşasın güzel gönüller. Hüzünle geçmesin kısacık ömür, Mutlu olsun artık, gülsün hep yüzler. Ömür kı...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zamani-tut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İspanyol', 'i-spanyol-ahmet-aksoy-sj8bh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '……………………….”bilinmezlere gebe çocuklar”

ellerimi sana bıraktım uzandıklarımı uzanacaklarımı

kuş tüyü yastıklar bıraktım bem beyaz çarşaflar

her şeyi anlattım yaşamı ve ölümü

bir anka kuşu kaldı nasıl ölür nasıl doğar

yazgısı örsle yazılırmış fidanın

tutuklu bırakılırmış bir ömür

herkes bin anka kuşudur doğar çeker ölür

büyük bir demircidir Tanrı', '……………………….”bilinmezlere gebe çocuklar” ellerimi sana bıraktım uzandıklarımı uzanacaklarımı kuş tüyü yastıklar bıraktım bem beyaz çarşaflar h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ispanyol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyada imajımız', 'dunyada-imajimiz-mikdat-bal-h3j1b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyada imajımız

Eskiden de var idi

Bütün dünya bizlere

Herşeyde uyar idi

Ekonomi düzelmiş

Ne kadar sürecektir

Yapılan bunca borcu

Kim geri verecektir

Batan gemi yan gider

Neyin artısı bunlar

Nekadar güvenilir

İMF li kanunlar

AB ye gireceksek

Giriş nasıl olacak

Yapılan kanunlarla

Her değer kaybolacak

Böyle bir vaziyette

AB bizi alır mı? 

Onlar gibi olursak

Bizde hayır kalır mı? 

Şimdi ki hükümete

Laf atan yok, söz genel

Bu gün güç kimlerdedir

Biraz o yana yönel

Burokrasi gitmeden

Kim gelirse fark etmez

Bilirim kısa anda

Ülke birden çark etmez

Sen ye torun ödesin

Fıkrasını duydun mu? 

Bu fıkraya inanıp

Oturup ta doydun mu? 

Bizim dededen kalma

Gronik borçlarımız var

Bunun yanında birçok

Gider harçlarımız var

Ülke bizim ülkemiz

Gidişatı bozuktur

Bizleri köstekleyen

Değişmeyen düzüktür

Ekmek çalanın eli

Yerinde kesiliyor

Devleti çalanların

Portresi asılıyor

Kendisi çaldırtmıyor

Çalanlara ne etti

Uzanı uzandırmış

Nemaları bitmedi

Yani onlar çalacak

Borç devlete kalacak

Böyle bir ikdidarın

Sonu nasıl olacak

AB ye ABD ye

Karşıyım, olacağım

Yaşadığım müddetçe

Hep böyle kalacağım

Onlardan bize fayda

Ne oldu ne olacak

AB çökmek üzere

İlerde yok olacak

Mikdat der selam olsun

Beni anlayanlara

Herkesle hemfikirle

Benle olmayanlara', 'Dünyada imajımız Eskiden de var idi Bütün dünya bizlere Herşeyde uyar idi Ekonomi düzelmiş Ne kadar sürecektir Yapılan bunca borcu Kim geri ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/dunyada-imajimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denklem', 'denklem-ethem-turan-o9qfz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçük bir çocuktum 

Çabucak büyümek için 

Hep büyüklerimle gezmeyi isterdim 

Zaman öyle hızlı geçti ki 

Bende anlayamadım 

Aşk sevgi konuşur zamanlara geldim 

Ama yine büyüklerle gezerdim 

Eski bir alışkanlık olsa gerek 

Sevdiğinden ayrılmak zorunda kalan

Büyüklerim hep derdi 

Biz artık dostuz 

Hep düşünür bir türlü çözemezdim 

İnsanın ömrünü 

Her şeyini, varını yoğunu

Yüreğini 

Önüne hiç düşünmeden sereceği 

Aşık olduğu biriyle nasıl dost olurdu

Hiç çözememiştim bu denklemi 

 Paylaşma duygusu küçük yaşlarda öğretilmişti 

Kardeşlerimizle ve arkadaşlarımızla

Oyuncağımızı,paramızı,kavgamızı  paylaşmıştık 

Okula başladık sıralarımızı kalemlerimizi 

Aynı oyun bahçesini ve dersliği paylaştık 

Büyüdük

Sevgimizi paylaştık 

Aynı otobüsü,aynı mahalleyi ve şehri paylaştık 

Öğretilmeyen  paylaşmaları da kendimiz öğrendik 

Ama bir şeyi paylaşmayı ne yüreğimize 

Nede ruhumuza  öğretemedik 

Sevdiğimizi paylaşamadık 

Ya bizim di yada değildi 

Biten aşkın, sönen ateşin alevi olmayacağı gibi 

Parlamayacağını  ve de ısıtmayacağını 

Sönen ocak üstünde yeni yemek pişmeyeceğini 

Öğrenemedik 

Seven gönüle de anlatamadık 

Oda anlamak istemedi belki 

Şimdi bir daha düşünüyorum 

Paylaşmaları öğrenmişken 

Seni paylaşmak hiç olur mu 

Olurmu ki?', 'Küçük bir çocuktum  Çabucak büyümek için  Hep büyüklerimle gezmeyi isterdim  Zaman öyle hızlı geçti ki  Bende anlayamadım  Aşk sevgi konuşur...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/denklem-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazalum memleketun', 'yazalum-memleketun-mikdat-bal-0bvsc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yerel şive ile Çaykara dan bir dostum bana bir şiir göndermişti ona cevaben

yazılmıştı

Yazalum memleketun

Halini ahvalini

Şairler güzel yazar

Bulunca emsalini

Sağdan sıfırlar bitti

Gelmesun sola sıra

Sola sıra gelurse

Beş para etmez lira

Düzelme var diyorsun

Ne düzeldi bir göster

Bu yazduğun haberler

Biraz tafsilat ister

Bizde birluk yok iken

AB de birleşilmez

Türkiye beyuk, öyle

Kolayca üleşilmez

Severum memleketi

İnsanini daha çok

Zenginler zaten dertsuz

Onlarun problemi yok

Sıfır atılmasından

Anlayamadum bişe

Hesap makinaları

Satanlar döndi köşe

Başka ne kârı oldu

Geri geldi kuruşlar

Akıl bırakmadı ki

kafamuza vuruşlar

Kumbara satanlarda

Aldıler nasibini

Pazara geturdiler

Hukümetun ipini

Yetmiş yıldur Türki YE

Gelen yer giden yeyur

Uyanmak artuk farzdur

Her şeyumuz gideyur

Vergiyi toplayana

Dediler ki mali YE

Bunu bildirmek lazim

Kaymakama Valiye

Zaten millet bilmiyor

Fazla okutmadılar

Okuyanlar da zaten

Nasihat tutmamışlar

Başlarken ilkokula

İlk ders “uyu yat uyu”

Böyle bir şey öğrenen

Tembellik olur huyu

Yazıyı söker sökmez

Anlamazken hitabi

Çocuk alır eline

Bir “ okuma” kitabi

Çocuğe okumamak

Böylece aşilanur

Okuyup anlaması

Önceden karşilanur

Anladun mi kardaşum

Nicun okumayuruk

Türküm Doğruyum deruk

Bu sözde durmayuruk

Ne zaman düzelecek

Kardaş bizum halumuz

Acaba bu dünyada 

var midur emsalumuz

Derum ki bu hususta

Milleti uyaralım

Bilduğumuz ne varsa

Millete duyuralum', 'Yerel şive ile Çaykara dan bir dostum bana bir şiir göndermişti ona cevaben yazılmıştı Yazalum memleketun Halini ahvalini Şairler güzel yaza...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/yazalum-memleketun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her haslet almış hasar', 'her-haslet-almis-hasar-mikdat-bal-qyvs6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlayış firar etti

İnsanlık zarar etti

Beni ihtiyar etti

Dedikodu, yapanlar

Her haslet almış hasar

Edebsiz zehir kusar

Ötlekler buna susar

Bunlar yoldan sapanlar

Tek tip bir  medeniyet

Moda oldu deniyet

Yoldan çıktı cemiyet

Olduk Haktan kopanlar', 'Anlayış firar etti İnsanlık zarar etti Beni ihtiyar etti Dedikodu, yapanlar Her haslet almış hasar Edebsiz zehir kusar Ötlekler buna susar B...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-haslet-almis-hasar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kent', 'kent-fatma-guven-p0u1s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yitik kentiyim; 

Gün yüzüne çıkmamış sırların.

Tek damlada derya, tohumda ekin,

 Kadranında,geri saymada zaman; 

An geldiğinde açığa çıkan ışınım.

Yıkık kentiyim; 

Gün yüzüne çıkmamış sırların.

Karanlık ellerin çizdiği,

Çentiklerin, resimlerin, çizgilerin,

Kayıtları yüreğimde, usumda.

Kent! .....

Hayatta,

Ayakta,

Konuşmakta,

Anlayana çok şey anlatmakta...', 'Yitik kentiyim;  Gün yüzüne çıkmamış sırların. Tek damlada derya, tohumda ekin,  Kadranında,geri saymada zaman;  An geldiğinde açığa çıkan ı...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kent-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozuyorum', 'tozuyorum-ramazan-ates-ygydg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Toz pembe dünyada,

Toz kaldım artık.

Kime kondu isem,

Süpürdü beni.

Pembesi kayboldu,

Tozu göründü.

Kimi feryat etti, kimi fırça attı,

Süpürdü ben.

Mikrop diyerek şimdi,

Ahh, kaçan kaçana.

Kimi dışarı attı, camı açıpda,

Süpürdü beni.

Yüreklere ateş olup yakandım,

Şimşek olup gözlere bakandım,

Şimdi toza, dumana döndüm,

Kime kondu isem,

Süpürdü beni.

Ramazan Ateş/Enschede-16.2.2006', 'Toz pembe dünyada, Toz kaldım artık. Kime kondu isem, Süpürdü beni. Pembesi kayboldu, Tozu göründü. Kimi feryat etti, kimi fırça attı, Süpür...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tozuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küpeleri Kirazdan', 'kupeleri-kirazdan-mevlut-yanar-no7zo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağların arkasında dünya var

Köyler var bahçeler içinde

Kirazlar kıpkırmızı

Oturmuş kiraz dudaklım

Küpeleri kirazdan

Umarım beni anar

Beni düşünür birazdan

Dağların arkasında dünya var

Evler var dere boylarında

Çocuklar derede çimer

Kiraz dudaklım düşünür

Benim huysuzluğumu

Kulaklarında yok küpesi 

Seyrektir gülmesi

Dağların arkasında dünya var

Kahveler var yol boylarında

Kahveler var yıkılası

Kiraz dudaklım evde

Düşünür yapayalnız

Onun dünyasından hüzünlü bakar

Gözleri üzüm karası

Dağların arkasında dünya var

Fabrikaların bacaları filtreli

Sıra sıra trenler

Binipte eve gitmeli

Şehir parkında çocuklar

Evde gülümser

Pembe dudaklı  sevgili

                                Mevlüt  Yanar', 'Dağların arkasında dünya var Köyler var bahçeler içinde Kirazlar kıpkırmızı Oturmuş kiraz dudaklım Küpeleri kirazdan Umarım beni anar Beni d...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Yanar']::text[], 8.5, '{"poet":"Mevlüt Yanar","poet_slug":"mevlut-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kupeleri-kirazdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sahnelik Figüran', 'bir-sahnelik-figuran-senol-ozuturk-kiqfz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mahkum kalmak gözlerinde yıllarca,

Ayağına sermek bütün şiirleri,

Seni sevmek.

Bir sözünle ölmek,

Bir sözünle beklemek,savrulmak cümlelerde seni sevmek

Yazdıklarımda, çizdiklerimde 

Satır arasına gizlenmiş hecede,

Sararmış sayfalarda aramak yüreğini 

Seni sevmek.

Bitmeyen senaryo seni sevmek 

Bense bir sahnelik figüran.

Gözlerine bakmak 

Onca yılı alır ömür arasından.

2005 Ankara', 'Mahkum kalmak gözlerinde yıllarca, Ayağına sermek bütün şiirleri, Seni sevmek. Bir sözünle ölmek, Bir sözünle beklemek,savrulmak cümlelerde ...', ARRAY['Türk Edebiyatı','Şiir','Şenol Özütürk']::text[], 8.5, '{"poet":"Şenol Özütürk","poet_slug":"senol-ozuturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-sahnelik-figuran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz yasi', 'goz-yasi-ayla-efe-ojrjq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dogdugum an geldin aktin gözlerimden

Hic kurumadin cagladin yeniden

Yapamiyorum aglamadan ne gelir elden.

Göz yasim kurumamaya yeminmi ettin? 

Gelen aglatti,giden aglatti,

Her dert icerimi derinden yakti.

Simdi gözlerim aglamaktan bikti

Göz yasim kurumamaya yeminmi ettin

Kavusunca aglar gözlerim

Ayrilinca caglar gözlerim

Gurbet elde sizlar gözlerim

Göz yasim kurumamaya yeminmi ettin.

Ayla efe

KREFELD ALMANYA', 'Dogdugum an geldin aktin gözlerimden Hic kurumadin cagladin yeniden Yapamiyorum aglamadan ne gelir elden. Göz yasim kurumamaya yeminmi ettin...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/goz-yasi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşatılmış Mısralar', 'kusatilmis-misralar-senol-ozuturk-lngvp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuytu bir köşeye bırakmışım

Voltasını hasrete vurduğum aşkı.

Çocukça bahane, delicesine yalnızlık

Gözlerinin hayalini kurduğum gündü ayrılık.

Kurşunun önüne atlamak,

Umarsızca gözlerine bakmak,

Kenarından geçmek gibi uçurumun

Sebepsizce ellerini tutmak                                     

Kar tanesi misali 

Birbirine değmeden.

Yıldızlar kadar yakın 

Yüreğin kadar uzak.

Şafağındayken sensizliğin 

Parçalanmış bir hüzün dağılır

İtiraf mısraları kuşatmışken.

Savurur yüreğimi 

Gözlerinin bitmek bitmeyen işgali.', 'Kuytu bir köşeye bırakmışım Voltasını hasrete vurduğum aşkı. Çocukça bahane, delicesine yalnızlık Gözlerinin hayalini kurduğum gündü ayrılık...', ARRAY['Türk Edebiyatı','Şiir','Şenol Özütürk']::text[], 8.5, '{"poet":"Şenol Özütürk","poet_slug":"senol-ozuturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kusatilmis-misralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk milleti', 'turk-milleti-ayla-efe-jwi4h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'TÜRK MILLETI

Dagilmisiz dünyaya

Kismetimizi aramaya

Horlanmisiz heryerde

Yinede yilmaz türk milleti

Zaman olmus güclenmisiz

Bazi zaman param parca,

Dayanmisiz  viyana kapilarina

Korku vermisiyz Avrupaya

Bende bu Milletin bir ferdiyim

Misafir isci almayada

Onurumu cignetmeden

Calisiyorum yasamaya

Ayla Efe krefeld almanya

21.9.95', 'TÜRK MILLETI Dagilmisiz dünyaya Kismetimizi aramaya Horlanmisiz heryerde Yinede yilmaz türk milleti Zaman olmus güclenmisiz Bazi zaman param...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/turk-milleti-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkemde Çocuk Olmak', 'ulkemde-cocuk-olmak-mevlut-yanar-71e0m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar zor

Ne kadar

Ülkemde çocuk olmak

Yok artık çellik çomak

Birkaç on yıl öncesi

Ayağımızda lastik

Her gün oyun oynardık 

Ne sınav endişesi

Ne dershane çilesi

Yaşımızla yaşıttık

Ne kadar zor 

Nekadar

Ülkemde çocuk olmak

Yok artık çellik çomak

Altmışlı yıllardaydı

Sığır sıpa güderdik

Pantolonumuz yırtık

Ruhumuz sapsağlamdı

Annemiz bizi sever

Babamız da överdi

Ah onlar ne günlerdi

Ne kadar zor 

Ne kadar

Ülkemde çocuk olmak

Yok artık çellik çomak 

                       Mevlüt Yanar', 'Ne kadar zor Ne kadar Ülkemde çocuk olmak Yok artık çellik çomak Birkaç on yıl öncesi Ayağımızda lastik Her gün oyun oynardık  Ne sınav endi...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Yanar']::text[], 8.5, '{"poet":"Mevlüt Yanar","poet_slug":"mevlut-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ulkemde-cocuk-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Off Of Dedim Sustum', 'off-of-dedim-sustum-ramazan-ates-p6qt0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçtim aynanın karşısına,

Tepeden tırnağa süzdüm kendimi.

Söyleyecek bir söz bulamadım,

Sustum.

Simsiyah saçlarım vardı,

Ağarmış, bembeyaz olmuş.

Ağarmakla kalmamış, yarısı dökülmüş,

Öylece baktım. Ne diyebilirdim? 

Sustum.

Gözlerimin feri gitmiş sanki,

Kırışıklıklar oluşmuş altlarında.

Yüz hatlarım değişmiş sakallarım ağarmış,

Bıyığımı düzelttim, baktım birazda,

Sustum.

Ağzımı açmadım, açamadım,

Hem sustum, hem dişlerimden korktum,

Yarısı çürümüş yarısı takma,

Dedim ki içimde; oğlum sen var ya, neyse,

Sustum.

Omuzlarım dik dururdu eskiden,

Gögüs ileri, karın içeri.

Omuzlar düşmüş, çıkmış karın göbek,

Bu ben miyim diye soru geldi aklıma,

Sustum.

Ayakta dursamda bakmayın bana,

Ağrı bir gün kafamda, bir gün kolumda.

Biliyorum artık yolum yakında,

Gerçekler bu diyecektim ama

Sustum.

Suskun halım bu ise var sen hesap et,

Ya birde konuşsa, ortalık felaket.

Uçarı sanırdım halen kendimi,

Gerçeği görünce tutuldu dilim,

Sustum.

Sanmayın ben artık hayata küstüm,

Sadece bu günlük birazcık, 

Sustum.

Enschede-16.2.2006', 'Geçtim aynanın karşısına, Tepeden tırnağa süzdüm kendimi. Söyleyecek bir söz bulamadım, Sustum. Simsiyah saçlarım vardı, Ağarmış, bembeyaz o...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/off-of-dedim-sustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Gidiyor Dakikalar', 'kayip-gidiyor-dakikalar-hatice-bediroglu-afnt9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gün 

Bir öncekinden daha beter 

Derinleşiyor yokluğun 

Kumbarada birikiyor kelimeler 

Acıtıyor sesleri kulaklarımı 

Oh olsun! Çekiyor gece 

Yapıştırıyor azarı kızgın şimşekler

Bulutlarsa yufka yürekli 

Bırakıyor serin damlalarını 

Ateş gibi yanan başıma 

Sanki! 

Dağ oturmuş omuzlarıma

Atağa kalkmış hüzünler 

Her bir hücreme 

Eklemiş kendini Sonbahar 

Doğmayı beklemekte tomurcuklar

Ah! 

Kayıp gidiyor avuçlarımdan 

Sancıdan kıvrım kıvrım dakikalar

'' Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 - 

www.haticebediroglu.net', 'Her gün  Bir öncekinden daha beter  Derinleşiyor yokluğun  Kumbarada birikiyor kelimeler  Acıtıyor sesleri kulaklarımı  Oh olsun! Çekiyor ge...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kayip-gidiyor-dakikalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırbaç', 'kirbac-asima-azra-45c92', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırbaç…

esmer öfkeni saç…

Sende acımalıyım herkesten çok

sana sancımalı

….tende kesif yaralar aç.

Kırbaç…

zaman bayat ilaç…

Seni okumalıyım her şeyden çok

sana yutkunmalı

….dilde esrar perdeni aç.

Kırbaç…

gözün safir kılıç 

sözlerin bulamaç

hadi…

vur ve kuytuna kaç…', 'Kırbaç… esmer öfkeni saç… Sende acımalıyım herkesten çok sana sancımalı ….tende kesif yaralar aç. Kırbaç… zaman bayat ilaç… Seni okumalıyım ...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kir-bac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir zamanlar', 'bir-zamanlar-ayla-efe-s9enp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevgilim vardi yillar önce,

Taparcasina sevmistim onu,

Bekledim yillarca onu

Gelmedi hic hayallerimin sonu

Ugruna göz yasi döktüm

Günlerce yoluna baktim

En son beklemekten biktim

Simdi oldu bir zamanlar.

Artik inancim kalmadi aska

Sevilen zalim seven hasta

Bir zamanlar bende sevmistim ama! ! ! 

Simdi oldu bir zamanlar...', 'Bir sevgilim vardi yillar önce, Taparcasina sevmistim onu, Bekledim yillarca onu Gelmedi hic hayallerimin sonu Ugruna göz yasi döktüm Günler...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-zamanlar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-ayla-efe-9gti3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Savaslarla atomlarla

Türlü türlü dumanlarla

Kirlettiler dünya seni

Mahfettiler dünya seni.

Petrol icin indik kalbine

Roketle delip ciktik göge

Kiyameti bile bile

Harap ettik dünya seni

Yesile hasret kaldik

Beton binalari diktik

Hayvanlara yazik ettik

Nasil kurtaralim dünya seni?', 'Savaslarla atomlarla Türlü türlü dumanlarla Kirlettiler dünya seni Mahfettiler dünya seni. Petrol icin indik kalbine Roketle delip ciktik gö...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dunya-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinim', 'dinim-kamil-at-1nker', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sırtımdan vurdular dinsiz diye

Yobaz derimi yüzecek kansız diye

Nesimi''de yüzüldü kefensiz diye

Dinim güzellik derim güzellik.

Yok öyle boş boşa insan kesmek

Yok öyle yarım-yamalak esmek

Kimsede kalmaz, zehir kusmak

Dinim güzellik derim güzellik.

İnsan ayırır bilinen hayırsız dinler

Rüyada bile görmem yok cinler

Dinler yüzünden başladı kinler

Dinim güzellik derim güzellik.

Darağacında urgan vursalar

Karşımda ateş yakıp kudursalar

Her yanımı kuşatıp silahla sarsalar

Dinim güzellik derim güzellik.

Kamil At daha da vazgeçmem

Acı içme suyu''ndan gayrıyı içmem

Kafama göre takıldım kin seçmem

Dinim güzellik derim güzellik.', 'Sırtımdan vurdular dinsiz diye Yobaz derimi yüzecek kansız diye Nesimi''de yüzüldü kefensiz diye Dinim güzellik derim güzellik. Yok öyle boş ...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Tam Zamanı Cesaretin', 'simdi-tam-zamani-cesaretin-melih-coskun-st2dt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi tam zamanı cesaretin 

Ve yüzüne tükürmenin

Kalbini, daralan halkaların arasında 

Her gün biraz daha çok sıkıştıran esaretin

Dinle

Kalabalıkların 

Kulakları sağır eden haykırışını 

Dokların

Örslerin 

Ve rotatiflerin 

Hep bir ağızdan söylediği 

O muhteşem zafer şarkısını

Bizim tabutlarımız

Kapakları çivi tutmayan 

Bizim yumruklarımız 

Tonlarca toprakla örtülse de üzeri

Yerçekimine meydan okuyan 

Bizim ölülerimiz 

Mezarlarına sığmayan 

Haydi delikanlım 

Şimdi tam zamanı cesaretin 

Sözün mü var zalimden sakınacağın 

Kaç günün var daha 

Kaybedilmiş düşlerinden öte

Esir yaşayacağın... 

Unutma

Her şair militandır biraz

Ölmez zalimin kurşunuyla…

2005', 'Şimdi tam zamanı cesaretin  Ve yüzüne tükürmenin Kalbini, daralan halkaların arasında  Her gün biraz daha çok sıkıştıran esaretin Dinle Kala...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/simdi-tam-zamani-cesaretin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sessizlik Susamıştı Sesine', 'sessizlik-susamisti-sesine-nurten-altinok-hu1o1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'table width=''%80'' align=''center''tr                                 

