INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemiciler', 'gemiciler-ayla-efe-81y64', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '. 

acilirlar deryaya, 

ugrarlar arada bir limana, 

bogusurlar dalgalarla, 

cile yüklü gemiciler... 

Her limanda bir sevgili, 

Anariz arada seni, 

unuttunmu sevgimizi? 

Maymun istahli gemiciler... 

Kiminiz yelkencisiniz, 

kiminizde dümenci, 

Micolar icinizde en genci, 

Yelkenler fora vira vira heyyyy', '.  acilirlar deryaya,  ugrarlar arada bir limana,  bogusurlar dalgalarla,  cile yüklü gemiciler...  Her limanda bir sevgili,  Anariz arada s...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gemiciler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '06 Gölge Oyunu', '06-golge-oyunu-murat-baltaci-3jlxs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Farzet ki,

Bir gölge oyunuyduk biz,

Hayat; 

Beyaz, ipek bir perde,

Aşk; 

Perdenin ardında yanan ışık,

Bizler ise,

Kuklalardık....

Ve farzet ki,

Birgün aniden

Işıklar sönüverdi...

Yarım kaldık bi''tanem,

Yarım kaldık...', 'Farzet ki, Bir gölge oyunuyduk biz, Hayat;  Beyaz, ipek bir perde, Aşk;  Perdenin ardında yanan ışık, Bizler ise, Kuklalardık.... Ve farzet ...', ARRAY['Türk Edebiyatı','Şiir','Murat Baltacı']::text[], 8.5, '{"poet":"Murat Baltacı","poet_slug":"murat-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/06-golge-oyunu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-76 (M.S.) 14/02/2006', 'mektuplar-76-m-s-14-02-2006-mahzun-doga-sae6s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırakıp gittiğin bu yerler 

yıkılsa yeridir

müstehaktır

başımıza taş yağsa

her yanımızı buz kesse

zamanıdır 

Bu kadar büyümüşken ellerin ellerimde

nasıl kaçar yanaklarındaki uykularım

omzuma alışmışken başın

ellerimiz yapışmışken birbirine

gitmenin zamanı mıydı

bir sabah vakti öğlenden sonra

Zaman şimdiki geniş zaman

aşkın tufanı şimdi

hasret-i alem

Sözlerim sesine kızgın 

kollarım kucağına kırgın

gözlerim bakışlarına kör

ayaklarım son adımında durmuş 

gittin ve gittin

Yokluğun yoktan az

varlığın vardan çok şimdi', 'Bırakıp gittiğin bu yerler  yıkılsa yeridir müstehaktır başımıza taş yağsa her yanımızı buz kesse zamanıdır  Bu kadar büyümüşken ellerin ell...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mektuplar-76-m-s-14-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-77 (M.S.) 15/02/2006', 'mektuplar-77-m-s-15-02-2006-mahzun-doga-cale9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni kime anlatsam

ağzı açık kalıyor

dili tutuluyor

Seni kime anlatsam

aklını kaybediyor

kalbini arıyor

Seni kime anlatsam

kendisini azalıyor

fakir kalıyor

Seni kime anlatsam

aynadan düşüyor

Seni kime anlatsam

kendisini anlıyor

çaresiz kalıyor

Seni kime anlatsam

herkes ölüyor

kimse kalmıyor

Seni kime anlatsam

anlamıyor', 'Seni kime anlatsam ağzı açık kalıyor dili tutuluyor Seni kime anlatsam aklını kaybediyor kalbini arıyor Seni kime anlatsam kendisini azalıyo...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mektuplar-77-m-s-15-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilgiye çağrı', 'bilgiye-cagri-i-brahim-ziyali-71j9j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar yalnızım yine

sokaklar bomboş? 

eve doğru yürüyorum ellerim ceplerimde.

Bir an bakıyorum gökyüzüne

ayın ondördü ne hoş.

Kimseler yok,olmaz da zaten

çoktan uyudu herkes kalırmı bu saate

yarın yine var çalışmak

ya uyumazsan

olurmu

o zaman geri kalınır hem işten hem güçten.

Uyuyun bakalım

hemde gerine gerine

bir sağa bir sola dönün

olmadı mı

bir de sırtüstünü deneyin

iyice rahatlaşın hele 

kabarık döşeklerinizde.

Hiç düşünmeyin,konuşmayın

geçmişten gelecekten

hem size ne canım

tarihten matematikten

onlar büyük adam işi

desenize memnunsunuz cehaletten.

Olmaz efendiler! 

çıkarın başlarıniziı gömdüğünüz kumdan

etrafınıza bir bakın ve görün lütfen

çatmayın kaşlarınızı

dinleyin tahammül edin

doldurun içinizdeki dolmaz denilen boşları

arayın biraz,zahmet edin canım

o kadar olur,elbet bozulacak rahatınız

dertlenin çilesini çekin 

bilirsiniz ham meyvanın tadı olmaz

olgunlaşın

göreceksiniz

size ulaşmak için uzanacaklar elleriyle

yetişemeyecekler.

O zaman anlayacaklar

terketmeli rahatı

vazgeçmeli olur olmaz şeyden

düşünmeli konuşmalı

geçmişten gelecekten

anlamalı tarihten matematikten

Eyvah

kurtulmak en başta

bilgisizlikten cehaletten.

                             

                          (08.Aralık,1995/ Kdz.Eregli)', 'Ne kadar yalnızım yine sokaklar bomboş?  eve doğru yürüyorum ellerim ceplerimde. Bir an bakıyorum gökyüzüne ayın ondördü ne hoş. Kimseler yo...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ziyalı']::text[], 8.5, '{"poet":"İbrahim Ziyalı","poet_slug":"i-brahim-ziyali","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bilgiye-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arafat', 'arafat-yasar-akbas-gl01o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Filistin’in Efsanevî liderine İthaf olunur.)     

Bir sevdaya bir ömür yetmiyormuş, Arafat.

Sevdan gönüle indi,öksüz kalmaz, Arafat.

Bağımsızlık yolunda, bir türküsün dudakta,

Yiğitçe bir tavırla, örnek oldun yarına.

  

Güyâ amca oğlu! Denksiz savaşı  yapanlar,

Kan ve zülüm üstünde refâhı arayanlar.

     

Nefret ve gözyaşıyla medeniyet yazılmaz.

Yüreği olan insan zalimi onaylamaz.

İmrenmişsin Denktaş’a ''senin hâmin var.'' diye

Rabbim isterse eğer neler olmaz,seyreyle.

Nice Musalar büyür, Firavun himmetinde

İntikam günü gelir, getirir ellerinde.

Sevdalar bastırılmaz,tıpkı bomba,köz gibi,

Hürriyet ihtiyaçtır,hava gibi su gibi.

Yaktığın meşaleler sevdanı aydınlatır,

Zulümler yüreklerin kinlerini parlatır.

Zaman senin lehine, hele çarklar dönsün bir! 

Zalimleri öç korkutur,titriyordur tir tir.

Güvendiği kaleler,elbet düşer bir günde,

Hiç sabahsız gece yoktur,yoktur koca âlemde. 

Canlı bomba silahın, mazlumun atom gücü,

İstese de zalimin,zalimin yok o gücü.

''Ebabil kuşu'' gibi, yetişmiş çocukların,

Sapanı ellerinde,hoş gelecektir bahtın.

Dostum, Osmanlı gerek zâlimi durdurmaya,

Soykırımın hesabın, hesabını sormaya.

Kim cesaret ederdi, zulüm ünü satmaya,

Osmanlı olsa idi,olsa idi hayatta.

Zulmün gücü çoksa da,mazlumlar gâlip gelir,

İnanan insanlara,er geç zafer görünür.

Gam çekme sen  Arafat,ne bugün ne yarın da,

Düşlerin gerçek olur,Filistin diyarında.

Ramallah ve Gazze''de  destanın yazılacak.

Sana kabir kazanın mezarı kazılacak.

HÜR,MÜSTAKİL FİLİSTİN,FİLİSTİN KURULACAK,

TARİH YAZACAK ADIN,SEVGİYLE TAÇLANACAK.', '(Filistin’in Efsanevî liderine İthaf olunur.)      Bir sevdaya bir ömür yetmiyormuş, Arafat. Sevdan gönüle indi,öksüz kalmaz, Arafat. Bağıms...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akbaş']::text[], 8.5, '{"poet":"Yaşar Akbaş","poet_slug":"yasar-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/arafat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-78 (M.S.) 16/02/2006', 'mektuplar-78-m-s-16-02-2006-mahzun-doga-l2na3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiçbir şey değiliz hiçbirimiz 

Et ve kemik yığınıyız 

biçimsiz ve çirkin 

yersiz ve gereksiz

Hiçbir anlamımız yok

bildiğimiz bilmediklerimizin öbür adı

hiçbir aklığımız kalmamış

al ve karayız

Hiçbir değerimiz yok

aciz ve güçsüzüz 

ölebiliyoruz', 'Hiçbir şey değiliz hiçbirimiz  Et ve kemik yığınıyız  biçimsiz ve çirkin  yersiz ve gereksiz Hiçbir anlamımız yok bildiğimiz bilmediklerimiz...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mektuplar-78-m-s-16-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğa acıkmak', 'dostluga-acikmak-i-lhami-arslantas-434dn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canı avucunda gönülden sunan,

Bir garip ozanım dost diye yanan,

Yeter ki dostum ol gönülden inan,

Sevginle sarhoş et gül ile öldür.

Baş yastıkta gönlüm sana uykusuz,

Sevgiye aç, fakir yatmaz kaygısız

Olmasın istemem bu can duygusuz,

Sevginle sarhoş et ye çöl ile öldür.

Bağrına bas beni ne diyor yürek,

Sonra da al getir bel, kazma, kürek,

Mezar eşmek için son karar gerek,

Sevginle sarhoş et bel ile öldür.

Bu can benim değil can sensiz olmaz,

Sensiz olacaksam dost densiz olmaz,

Muhabbet yarınsız bu günsüz olmaz,

Sevginle sarhoş et tel ile öldür.

Der İlhami açıl kızıl, mor, beyaz,

Dostluk sevdasıyla her anım ayaz,

Dostluğa el açtım ederim niyaz,

Sevginle sarhoş et dil ile öldür.

………………..Ne olur gel dostum yüzümü güldür', 'Canı avucunda gönülden sunan, Bir garip ozanım dost diye yanan, Yeter ki dostum ol gönülden inan, Sevginle sarhoş et gül ile öldür. Baş yast...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dostluga-acikmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Mührü Alnımın', 'huzun-muhru-alnimin-guzin-eye-dundar-bjyx0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durdu zaman, takvimler 

bir yerinde saatin

evde ölü bir telaş

çığlık birikmiş 

sesine annemin

soluk resimlere

iliştirdim dört harf

dilsiz ay babam olsun dedim

inandı  çocukluğum

hasret  zarf

içinde 

sahipsiz mektubum

dedim: unutma 

ne olur arada gel

çözülen uykularıma

beni incinmişlikten sakın

senin içindi çocukluğum

şımarıklığım,korkularım

şimdi hüzün mührü alnımın

duymadın...', 'Durdu zaman, takvimler  bir yerinde saatin evde ölü bir telaş çığlık birikmiş  sesine annemin soluk resimlere iliştirdim dört harf dilsiz ay...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huzun-muhru-alnimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olamadım...', 'olamadim-aysun-elagoz-vit1p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğinde umut,

Gözlerinde ışık,

Dudağında türkü,

İçinde mutluluk,

Özlenen,

Beklenen,

İstenen...

Dert ortağın,

Sıcağın,

Yarının,

Baharın....

Olamadım...

Sen bensiz oldun ama

Ben sensiz olamadım....', 'Yüreğinde umut, Gözlerinde ışık, Dudağında türkü, İçinde mutluluk, Özlenen, Beklenen, İstenen... Dert ortağın, Sıcağın, Yarının, Baharın.......', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olamadim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan!', 'yalan-nazan-i-zmirli-ck7w0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'üzgünüm! 

hayatımda 

biri  var

dedi

adam

gülen gözlerinin

ardından.

içine akan yaşlarını

gizliyemiyorsun 

dedi 

kadın.

üzgünüm! 

yalan! 

12.02.2006-antalya', 'üzgünüm!  hayatımda  biri  var dedi adam gülen gözlerinin ardından. içine akan yaşlarını gizliyemiyorsun  dedi  kadın. üzgünüm!  yalan!  12....', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalan-202-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Beton Tabut', 'bir-beton-tabut-muammer-erturan-tvvbp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sağım beton

solum beton...

Dokunmuşluğum toprağa

koklamışlığım yeşili

tırmanmışlığım bir ağaca

ne zamandı en son? ..

Dalında bir elma

bir şeftali

bir üzüm

görmüşlüğüm hatta

kaç zaman önceydi? ..

Unuttum gitti...

Altım beton

üstüm beton...

Tonlarca gri...

Birileri

enikonu iş edinmiş kendine

renksizleştirmeyi...

Ve diri diri tıkmayı 

cümlemizi

bir beton tabuta...

(21 Eylül ''99)', 'Sağım beton solum beton... Dokunmuşluğum toprağa koklamışlığım yeşili tırmanmışlığım bir ağaca ne zamandı en son? .. Dalında bir elma bir şe...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-beton-tabut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Konuşmamız...', 'son-konusmamiz-mustafa-komuscuoglu-j2f9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokluğunun boşluğunda kaldı hayatım

Tırmanacak,tutunacak bir dal bulamadım

Tam yeşil otlar bitiyordu ki gönlümün kenarında

Geldin,biçtin ve gittin

Son konuşmamızı hatırlıyorum da şimdi

Bin olan derdimi,binbir ettin

Ne kadar kapı varsa umuda dair

Hepsini üstüme kilitleyipte gittin

Ve yarım kalmış buruk bir sevdayı

Henüz doğmamış çocuklara vasiyet ettin

Her gidişin sadece hüzün verirdi gönlüme

Oysa bu gidişin ferman verdi gözlerime

Bana şimdi gençliğim kadar uzak sevdiğim

Seninle son konuşmamız hala kulaklarımda

Keşke dolu bir silah verseydinde bana

O gün hiç konuşmasaydık,hep sussaydık

Ve her cümlen yerine bir kurşun sıksaydım

Şu insafsız,şu vicdansız,şu söz dinlemez kalbime

Ve söndürseydim oracıkta bu küllenmeyen ateşi 

Birkaç kurşunun o son bestesiyle...', 'Yokluğunun boşluğunda kaldı hayatım Tırmanacak,tutunacak bir dal bulamadım Tam yeşil otlar bitiyordu ki gönlümün kenarında Geldin,biçtin ve ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-konusmamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih tekerrür', 'tarih-tekerrur-nazan-i-zmirli-ufif1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''tarih  tekerrür 

 derdi

 büyük  babam

 ne demek istiyor derdim, içimden onu  anlamadan''

anlamaya  çalışıyordum

tekerrürü

lügattaki anlamında.

yaşadıkça

günler  yılları  kovalayıp

ve  tilki  dönüp  dolaşıp 

kürkçü   dükkanında

asılınca.

yedili   yaşlarımda 

cumhuriyet gazetesi

rövaşta

öldü,öldürüldü

kaçtı  kaçırıldı

haklar çalındı

battı, düştü

kundaklama

suikast

petrol kavgası

eğitim sorunları

açlık sınırı

sahipsiz kundak

vs. vs. vs..........

17 yaşlarda

aynı  gündem 

27..''de.37 ''de.....aynı gündem

kavgamız,  koşuşmamız

inançlarımız   yetmiyor

bizden  hızlı  koşan 

pes etmeyen

biri  var  ki  o

tekerrürlü

zaman

aynı! herşey  aynı 

tekerrürün  anlamı

aydınlandı.

kundakta ki  yedisinde

sokağa

açlık   sınırında ki

çalmaya

eğitimde sorun yok

her şey  toz pembe 

sayesinde

bulutlarda

kimbilir  ne   acı 

tekrarlar yaşayacak

bu  dünya

yuvarlanıp

tekerrürler

ay  ışığında  sığınıp

neon   ışıklarla

aydınlandıkça.

büyükbaba

seni  anlamak 

en az üç tekrarımı aldı

ben  büyüyorum olgunlaşıyorum

neden  herşey  yeniden  yeniden

sormuyorum  artık  kendime 

ama  kanatan bir şey var içimi

keskiiiiin  keskiiiiin

yetememek   herşeye.....

17.02.2006-antalya', '''tarih  tekerrür   derdi  büyük  babam  ne demek istiyor derdim, içimden onu  anlamadan'' anlamaya  çalışıyordum tekerrürü lügattaki anlamınd...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/tarih-tekerrur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata dair..', 'hayata-dair-aysun-elagoz-txv2g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çelimsiz ümitler yeşerir yüreğimde..

Güneşli sabahlarda

Mavi ve parlak gökyüzüne

Takıldığında gözlerim..

Türkülerimi,

Daha bir derinden söylerim..

Kaybolur gider 

İçimde yılların biriktirdiği nefret tortuları,

Ve aldırmadan acılara gülümserim...

Tüy kadar hafifler o zaman

Taşımaktan yorulduğum ağır bedenim...

Çoktan uçup gitmiştir

Beni telaşa sürükleyen

Sinsi, hain, umutsuz düşüncelerim..

Hayatın beni sevdiğini hissederim..

Ben de onu özgürlük kadar,

Yar kadar,

Yüreğim kadar severim...', 'Çelimsiz ümitler yeşerir yüreğimde.. Güneşli sabahlarda Mavi ve parlak gökyüzüne Takıldığında gözlerim.. Türkülerimi, Daha bir derinden söyl...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayata-dair-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakat', 'sakat-muammer-erturan-reqvi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kâr üstüne kâr

hırsıyla sırf

kurulmuş kat kat

zemin sakat

bina sakat

bani sakat...

Fay hattının

insafına kalmış hayat

sakat kere sakat...

(1 Aralık ''99)', 'Kâr üstüne kâr hırsıyla sırf kurulmuş kat kat zemin sakat bina sakat bani sakat... Fay hattının insafına kalmış hayat sakat kere sakat... (1...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sakat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliği Yaşarım', 'sensizligi-yasarim-aysun-elagoz-oq1a4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman dayasam düşüncelerimi,

Anıların omzuna...

Ne zaman yokluğun dolsa yüreğime,

Çaresizlik siner gözbebeklerime...

Ve sel olup akarlar yanaklarımdan...

Avuçlarıma...

Ben o gözyaşlarında

Sensizliği yaşarım...

Ne zaman saklasam özlemlerimi,

Sahte mutlulukların ardına...

Ne zaman kaybetsem yaşama sevincimi,

Buruk bir hüzün siner yüzüme...

Ve isyan olup taşar dudaklarımdan...

Umursamazlığına..

Ben o umutsuz anlarda

Sensizliği yaşarım..', 'Ne zaman dayasam düşüncelerimi, Anıların omzuna... Ne zaman yokluğun dolsa yüreğime, Çaresizlik siner gözbebeklerime... Ve sel olup akarlar ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizligi-yasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esra', 'esra-hikmet-feridun-demir-m620j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Issız kalbime, ılgit ılgit aktın

Hüzünlü gönlüme bir şarkı 

Küllere bezenmiş kalbime ılık bir rüzgar

Aşk çölümde ki sesizliğe bir Nida

Sevda rüzgarımızda dans eden Aşk kelebeğim.

Sevgilim, kalbime baharın güllerini ektin.

Yokluğunla  bana aşkı yazdırdın.

Sohbetin bana hep bir şarkı, gülüşün bir ömür

Kıvırcık saçların tel tel, rüzgarlarında Rüyalarımın

Bağırmak geliyor içimden dur gitme demek

Yalım yalım yanan gönlümde bir boşluk

Yanlızlığına alışmak zor gelsede

Belki uzaklarda oluşun bir ilaç 

Bırak Kalbime sunduğun sıcaklığı,

götürme birlikte bitmesin bu Aşk... 

Deniz mavisini kaybediyor, 

Mehtap son ışınlarını gömüyor sulara

Haykırmak geliyor içimden sensızliğini

Hüzün sarıyor karanlıkla birlikte, birde yokluğun...

Sonra sonra bu son mısrayı 

Gözlerimde damla damla hüzüne rağmen

geride bıraktığın, henüz yaşanmamış Aşkımıza

Armagan ediyorum, Sevgilim, Esram, Cananım….

17.02.2006

Wermelskirchen/Almanya', 'Issız kalbime, ılgit ılgit aktın Hüzünlü gönlüme bir şarkı  Küllere bezenmiş kalbime ılık bir rüzgar Aşk çölümde ki sesizliğe bir Nida Sevda...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/esra-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürüden Proleter', 'suruden-proleter-muammer-erturan-hxhxe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karnını doyurur başkalarının...

Giydirir başkalarını...

Konutlar yapar başkalarına...

Başkaları için gelmiştir

dünyaya sanki...

Ve geldiği gibi gider...

Oldu olacak tek mülkü,

zincirleri...

Ve lakin der ki ona

ağalar, paşalar, efendiler:

Bu senin kaderin...

Beş parmağın beşi de bir mi ki,

herkes bir olsun...

Kökü dışarda ideolojiler

şer tohumları ekmeye çalışıyor usuna...

Buna meydan verme! ..

Vermez nitekim...

Büyük sözü dinler...

Büyük sözüyle savaşa gider

icabederse

ve dövüşür en önde...

Barış günlerindeyse

en gerilerinde kalır yaşamın

büyük sözüyle gene...

Devlete-millete zeval vermesin

yeter ki Tanrı,

o kaderine razı...

Proletarya çarpışadursun

onun için,

umurunda bile olmaz

sürüden proleterin...

(Haziran ''79)', 'Karnını doyurur başkalarının... Giydirir başkalarını... Konutlar yapar başkalarına... Başkaları için gelmiştir dünyaya sanki... Ve geldiği g...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/suruden-proleter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümlü Milleti', 'olumlu-milleti-muammer-erturan-tamge', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sür atını 

işgâl orduları komutanı edasıyla

dal arasına ak tomarların 

yalın kalem, 

peşinde zehir zemberek sözcükler 

her telden... 

Dilinden cengâver 

dil mi var! ? . 

En büyük aşkları sen yaşadın

en büyük adamıydın kavganın

en çok da senin hakkın ölümsüzlük

değil mi ya! .. 

Hadi ya! .. 

Anlatama da meramını 

ölümlü milletine

göreyim senin ölümsüzlüğünü... 

Onlar ki

ölümsüz bir jüri kesilir 

gide gele,

o jürinin elinde işte

okunup okunmayacağı esamenin 

ilerleyen zaman içinde... 

(Temmuz ''03)', 'Sür atını  işgâl orduları komutanı edasıyla dal arasına ak tomarların  yalın kalem,  peşinde zehir zemberek sözcükler  her telden...  Dilind...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olumlu-milleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutkan', 'unutkan-muammer-erturan-5yk24', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutkanlaşmışım

Unutkancığım! 

Unutkanlaşmışım...

Unutulmazları

unutturan

unutkanlığını da

unutmayı

unutturmuş,

unutkanlığım...

(''97)', 'Unutkanlaşmışım Unutkancığım!  Unutkanlaşmışım... Unutulmazları unutturan unutkanlığını da unutmayı unutturmuş, unutkanlığım... (''97)...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unutkan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zengin Adamin Simarik Oglu! (makale)', 'zengin-adamin-simarik-oglu-makale-guner-kaymak-36agg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'div align=''center''centerdtfont color=''#0000ff'' size=''2''a name=''source2''emobject id=''Player5'' height=''46'' width=''154'' classid=''clsid:6BF52A52-394A-11d3-B153-00C04F79FAA6''

