INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanıyor', 'kaniyor-hidir-altas-7rkcl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Davullar, zurnalar çalıyor

Gençler birlite halay çekiyor

İnsanlar coşmuş eğleniyor

Benimse yüreğim yaralı kanıyor

Herkes sevdiğini almış geziyor

Mutluluktan yüzleri gülüyor

Kollarına kanat takmış uçuyor

Benimse yüreğim yaralı kanıyor

Delikanlı mektup gelmiş okuyor

Okudukça yerinde zıplayıp duruyor

İyi haber almış hep seviniyor

Benimse yüreğim yaralı kanıyor

Turhani oturmuş yere dertleniyor

Sevdiğiyle bir arada konuşamıyor

Çünkü taaa uzaklarda duruyor

Benimse yüreğim yaralı kanıyor

AŞIK TURHANİ-ANTALYA', 'Davullar, zurnalar çalıyor Gençler birlite halay çekiyor İnsanlar coşmuş eğleniyor Benimse yüreğim yaralı kanıyor Herkes sevdiğini almış gez...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaniyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amaç Üzüm Değil', 'amac-uzum-degil-yusuf-onder-bahceci-hm8uz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masalar da, dansözleri oynatıyorlar,

Her çeşit  naneleride habire yiyorlar

Tarike de köpekler gibi saldırıyorlar,

Amac üzüm değil, bağcıyı dövmek.

Tarik edep, tarik yol ve usül demek,

Tarik hiç kimseye, zarar vermemek,

Tarik Allah, Allah demek ve ermek,

Amaç üzüm değil bağcıyı dövmek.

Sahte tarikler yol kesici, kuzgunlar,

Her tarafları yalandır, kimdir bunlar,

Ey Millet inanmayın sahtedir bunlar,

Amaç üzüm değil, bağcıyı dövmek.

Gerçek alimler, Peygamber varisi,

Diğerleri makam ve mevkii delisi,

Gerçek Müslümanın, Allah''ı Velisi,

Amaç üzüm değil, bağcıyı dövmek.', 'Masalar da, dansözleri oynatıyorlar, Her çeşit  naneleride habire yiyorlar Tarike de köpekler gibi saldırıyorlar, Amac üzüm değil, bağcıyı d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/amac-uzum-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13 Fırtına', '13-firtina-murat-baltaci-yow73', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinde bulurum,

		Denizlerin masumluğunu.....

			Ve, kaybolurum lodosunda...

				Bir balıkçı teknesi gibi...

	Denizlerde solurum,

		Gül Kurusu kokunu...

			Kaybolurum lodosunda...

				Bir yağmur tanesi gibi...

Fırtınam olursun...

Savurursun....

Savurursun....

Savurursun....', 'Gözlerinde bulurum, 		Denizlerin masumluğunu..... 			Ve, kaybolurum lodosunda... 				Bir balıkçı teknesi gibi... 	Denizlerde solurum, 		Gül ...', ARRAY['Türk Edebiyatı','Şiir','Murat Baltacı']::text[], 8.5, '{"poet":"Murat Baltacı","poet_slug":"murat-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/13-firtina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağı Olmayan Çiçek (139)', 'topragi-olmayan-cicek-139-i-brahim-arslan-azj3b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprağı Olmayan Çiçek,

Bu yılda sevgisiz büyüyecek.

Damla damla gözyaşları,

Su yerine üzerine dökülecek...

Toprağı Olmayan Çiçek,

Seneler birgün gibi geçecek,

Günler kovalayacak günleri,

Yaprakların dökülecek...

Toprağı Olmayan Çiçek,

Güneşi olmayan çiçek,

Gökleri yırtsın ahın

Bu hasret bitmeyecek...

Toprağı Olmayan Çiçek,

Suyu olmayan çiçek,

Sonunda seninde birgün,

Yerinde yeller esecek...

Toprağı Olmayan Çiçek,

Bu yılda hüzünlerle büyüyecek.

Damla damla gözyaşları,

Su yerine üzerine dökülecek...

                    23.11.1998', 'Toprağı Olmayan Çiçek, Bu yılda sevgisiz büyüyecek. Damla damla gözyaşları, Su yerine üzerine dökülecek... Toprağı Olmayan Çiçek, Seneler bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/topragi-olmayan-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-i-smail-kocamaz-xu69p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş bir doğar,

Ardından karanlık gelir.

Ağaç baharda yeşillenir,

Kış olur, doğa uyur.

Bebek bir güler, bir ağlar

Büyürken düşer, kalkar.

Bir acı düşer yüreğine,

Sevinç gelir sonra bir süre.

Sevda öyle mi oysa...', 'Güneş bir doğar, Ardından karanlık gelir. Ağaç baharda yeşillenir, Kış olur, doğa uyur. Bebek bir güler, bir ağlar Büyürken düşer, kalkar. B...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kocamaz']::text[], 8.5, '{"poet":"İsmail Kocamaz","poet_slug":"i-smail-kocamaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayat-305-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlasam', 'aglasam-gultekin-toga-oxa9e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dost sinesine koysam başımı,

          Hıckırıp içimi çeksem ağlasam.

          Çağlayana dönmüş hicran yaşımı,

          Debreşen yürekle döksem ağlasam.

          Öyle dolmuşum ki bulutlar gibi,

          Özlemim uluşur aç kurtlar gibi,

          Yaşadım dünyayı yük sırtlar gibi,

          Bu beyhude yükü yıksam ağlasam..

          Hariçten bakmakla insan bilinmez,

          Kalbi dağlıların izi silinmez,

          Bir kere gitti mi geri gelinmez,

          Canımın ardından baksam ağlasam..

         Ömür mecarası hüzün Sentezi,

         Sıksan göz yaşıdır gülsen de bazı,

         Tek emelim kaldı Hakk olsa razı,

         Bu aciz başımı büksem ağlasam..

        

        Ozan Sentezi', 'Bir dost sinesine koysam başımı,           Hıckırıp içimi çeksem ağlasam.           Çağlayana dönmüş hicran yaşımı,           Debreşen yürek...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aglasam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiler Vardı', 'sevgiler-vardi-i-smail-kocamaz-smhn0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiler vardı yüreklerde yaşayan,

Yaşadığı yüreklerde ölümsüzleşen,

Sevgiler vardı gözlerden taşan,

Gözlerde tükenmez ışık saçan.

Sevgiler vardı, sevdalı ellerinde,

Ellerini tuttuğunda bedeni yakan.

Sevgililer yaşardı bu ellerde,

Eşi benzeri bulunmayan.', 'Sevgiler vardı yüreklerde yaşayan, Yaşadığı yüreklerde ölümsüzleşen, Sevgiler vardı gözlerden taşan, Gözlerde tükenmez ışık saçan. Sevgiler ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kocamaz']::text[], 8.5, '{"poet":"İsmail Kocamaz","poet_slug":"i-smail-kocamaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgiler-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgin yeter bana', 'sevgin-yeter-bana-tevfik-karinca-jaiol', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak bende kalsın yalnızlığım

kulağım kirişte olsun

Umudum sende 

Martılar uçsun gökyüzünde

Uyku tadında gecelerde

Yalnız seni

Yalnız seni getirsin bana gördüğüm düşler

Seni sen gibi yaşamak

küçük mutluluklar yaratsın yüreğimde

Sen yine alıp başını git

Seni sevmedim diyemezsin ya

Küçük tatlı bir sürpriz olsun

Bir gün çıkıp aniden gelişin

Seninle gönüldaşız

Sımsıkı dost

Hem sevgili hem arkadaşız

Çıkarsız

Ha belki yarınsız

Ne önemi var ki

Halvet olmuşuz gerdek gibi

Varsın görünmesin 

umut kuyusunun dibi

Sevgin yeter bana', 'Bırak bende kalsın yalnızlığım kulağım kirişte olsun Umudum sende  Martılar uçsun gökyüzünde Uyku tadında gecelerde Yalnız seni Yalnız seni ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevgin-yeter-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığınayım Sonunda', 'siginayim-sonunda-seyfet-bozcali-u1s3s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doruğuna ulaşayım yolların,

Akışıyla boğuşayım suların,

Selamıyla buluşayım yellerin,

Rahmetine sığınayım sonunda...

İnsanların mutlu,tatlı gülüşü,

İki dostun gönül ile buluşu,

Dertlerini karşılıklı bölüşü,

Sevgi ile boyanayım sonunda...

Pir yüzlünün ihlas dolu duası,

İnsanların gönül alma çabası,

Tatlı olur kanaatin çorbası,

Kaşıklayarak kanayım sonunda...

Musallaya geleceyim bilirim,

Bodrum kata ineceğim görürüm,

Bir gün toprak olacağım bilirim,

Bozçalı der öleceğim sonunda...

      18.02.2006', 'Doruğuna ulaşayım yolların, Akışıyla boğuşayım suların, Selamıyla buluşayım yellerin, Rahmetine sığınayım sonunda... İnsanların mutlu,tatlı ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siginayim-sonunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dram Ki (140)', 'bir-dram-ki-140-i-brahim-arslan-zko2w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ah çeksem sesimi duyarmısınız,

Ben Irak''ta katledilmiş çocuğum...

Ey insan haklarından bahsedenler...

Artık bu feryat figanımı duyun...

Göremedim anamı,memleketi

Daha açmadan gözlerimi yumdum...

Filistin''de doğmak vahşet demekti...

Suyun rengi kırmızı oldu,suyun! 

Haç işareti koydular karnıma

Buruk bir sevinçle Cennet''e uçtum

Çabuk kavuştum anne ve babama,

Ey insanlar siz rahatça uyuyun...

                                16.7.99 ve 2006 versiyonu...', 'Bir ah çeksem sesimi duyarmısınız, Ben Irak''ta katledilmiş çocuğum... Ey insan haklarından bahsedenler... Artık bu feryat figanımı duyun... ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-dram-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külün Icinden Gelis', 'kulun-icinden-gelis-gultekin-toga-fmgw8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümden betermiş zalim ayrılık,

Ölüm gözlerimde küçüldü artık,

Çektiğim acının besbeteri yok,

Geliyorum sönmüş külün içinden..

Yakacak sanırken pişirdi beni,

Fikir deryasına düşürdü beni,

Görünce bilenler şaşırdı beni,

Gülüyorum sönmüş külün içinden.

Acı öğrenmenin bir fidanlığı,

Ateşlerde kızdı çilemin tığı,

Hayatı,Dünya´yı tüm insanlığı,

Buluyorum sönmüş külün içinden..

İnanarak gelecek o sabaha,

DayandIm hayatta bir tek Allah´a

Umudumu yeni baştan bir daha,

Alıyorum sönmüş külün içinden..

Sentezi´yim uçsam yuvama doğru,

Köz bir kapı imiş deva´ma doğru

Alevlerden gectim kıvama doğru,

Doluyorum sönmüş külün içinden..', 'Ölümden betermiş zalim ayrılık, Ölüm gözlerimde küçüldü artık, Çektiğim acının besbeteri yok, Geliyorum sönmüş külün içinden.. Yakacak sanır...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kulun-icinden-gelis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalından Koparsa Gül', 'dalindan-koparsa-gul-yusuf-onder-bahceci-umeqh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalından koparsa bir gül,

Solar artık bir çaresi yok,

Güzel sevip, ayrılmışsan,

Ağlar artık bir çaresi yok.

Neden diye diye ağlarsın,

Sabaha kadar yalvarırsın,

Ne kadar da böyle safsın,

Ağlar artık bir çaresi yok.

Böyle Allah, Allah dersin,

Allah''ım bir teselli dersin,

Kendinide heder edersin,

Gelmez artık, çaresi yok.

Bir gün görürsün, sabahı,

Belki bırakırsın ah ile vahı,

Ömrün bitti kalmadı ki ahı,

Dönmez artık çaresi yok....', 'Dalından koparsa bir gül, Solar artık bir çaresi yok, Güzel sevip, ayrılmışsan, Ağlar artık bir çaresi yok. Neden diye diye ağlarsın, Sabaha...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dalindan-koparsa-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncindim', 'i-ncindim-gultekin-toga-aeysh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Israrla sormayın nerdesin? diye

Gönlün ummadığı yere incindim.

İçimde göç ettim onuncu köye,

Gözü açık bakar köre incindim.

Kalabalıklarda yalnızlığım var

Gönlümü isimsiz bir hüzün sarar,

Elbette ki insan muhabbet arar,

Yüreğinden kopuk sere incindim..

Şifreler uymuyor tutmaz frekans

Karanlık sevgiye vermiyor ki şans,

Gönül kurağına vermem tolerans,

Dostluk  yakan ateş,kora incindim..

Daracık bakışlar mengene bana,

Neler çektiğimi bak anlasana,

Özde saygım vardır ama insana,

Hal bilmeze ben bir kere incindim.

Dilin oklarıdır gönlüne değen,

Sen Sentezi ol da bu işi beğen,

Daha gonca iken gülüme yağan,

Doluya darıldım kara incindim', 'Israrla sormayın nerdesin? diye Gönlün ummadığı yere incindim. İçimde göç ettim onuncu köye, Gözü açık bakar köre incindim. Kalabalıklarda y...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/incindim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darağacı (141)', 'daragaci-141-i-brahim-arslan-6zyz8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatı darmadağan eden ağaç,darağacı

Tek meyva armağan eden tek ağaç...

Darağacı

Ne güneşi var,ne suyu,ne dalı,ne yaprağı...

Her zaman bahtiyar,her zaman melek

Darağacı..', 'Hayatı darmadağan eden ağaç,darağacı Tek meyva armağan eden tek ağaç... Darağacı Ne güneşi var,ne suyu,ne dalı,ne yaprağı... Her zaman bahti...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/daragaci-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gam Değirmeni', 'gam-degirmeni-gultekin-toga-rbj60', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül süzül yere doğru,

            Bak artık çılgın değilim,

            Ateş yurdu yaptın bağrı,

            Çok piştim, yılgın değilim..

            Talihim beni eğitti

            Bu yüreğim gam öğüttü,

            Duymak,hissetmek öğretti,

            Bilirim,bilgin değilim..

            Seyrekleşti solum,sağım,

            İs veriyor is ocağım,

           Güze döndü ömür çağım,

           Boşuna solgun değilim..

           İnadından hiç caymadın,

           Özlemi zarar saymadın,

           Neşeli bir gün koymadın,

           Yaz bozun,silgin değilim..

                     

           Çok sürdü gafletim,gafım,

           Önce banadır her lafım,            

           Boş işte boş bir tarafım,

           Vakti var dolgun değilim..

           Yıllar aktı dolamadım,

           Maksudumu bulamadım,

           Sentezi,ham,olamadım,

           Acıyım olgun değilim..', 'Gönül süzül yere doğru,             Bak artık çılgın değilim,             Ateş yurdu yaptın bağrı,             Çok piştim, yılgın değilim.. ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gam-degirmeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gümüş Bilye', 'gumus-bilye-i-smail-kocamaz-iwknw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cocukken elime bir bilye geçti,

O kadar çok parlıyordu ki,

Ona bakmaktan çok hoşlanıyordum,

Onu elimden bırakamıyordum.

Adını gümüş bilye koydum,

Onunla hiç oynayamıyordum,

Kaybolacak diye korkuyor,

Elimden bırakmıyordum.

Bir gün çıktım sokağa,

Arkadaşlarımla oynamaya

Çok sevdiğim oyundu misket,

Oynamaya yoktu bende cesaret.

Arkadaşlarım beni  zorla soktular oyuna,

Gümüş bilyem ile başladım oynamaya.

Oynadıkça artıyordu heyecanım,

Bu oyundan çok zevk aldım.

Unuttum bir an bilyemin değerini,

Çıkardım oyunun keyfini.

Koydum diğerlerinin yanına,

Çok sevdiğim gümüş bilyemi.', 'Cocukken elime bir bilye geçti, O kadar çok parlıyordu ki, Ona bakmaktan çok hoşlanıyordum, Onu elimden bırakamıyordum. Adını gümüş bilye ko...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kocamaz']::text[], 8.5, '{"poet":"İsmail Kocamaz","poet_slug":"i-smail-kocamaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gumus-bilye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davetkar Umut', 'davetkar-umut-gultekin-toga-khq54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Azmini yitirme az daha gayret,

Taş bir kımıldasın gerisi gelir..

Çiçek tek başına kalırsa hayret,

Kelebekler uçar arısı gelir..

Cemre düşüversin kara toprağa,

Erişir ırmaklar en coşkun çağa,

Düğün eder gibi ovaya,dağa,

Çiğdemin, nevruzun serisi gelir

Gönül sevgi eri usanmaz,yılmaz,

Umudu her mevsim yeşildir solmaz,

Sevda yoludur bu asla boş kalmaz,

Birisi giderken birisi gelir..

Duyguların savaş meydanı mıyım

Acılar safağı,gam tanı mıyım? 

Tükenip bitmeyen yas günü müyüm? 

Aklıma ben kimim sorusu gelir..

Karanlığa ecel doğan ışıktır,

Sentezi´nin gönlü aşka beşiktir,

Bu günler yüreğin delik deşiktir,

Elbet gülmenin de sırası gelir..', 'Azmini yitirme az daha gayret, Taş bir kımıldasın gerisi gelir.. Çiçek tek başına kalırsa hayret, Kelebekler uçar arısı gelir.. Cemre düşüve...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/davetkar-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Ciksin', 'gozlerim-ciksin-gultekin-toga-1g5on', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Usandım hep benden,usandım bizden,

Onları görmezse gözlerim çıksın.

Mıhlanarak doruklara,merkezden,

Yanları görmezse gözlerim çıksın..

Krallar,sultanlar,şahlar nerede? 

Şehvet abidesi şuhlar nerede? 

Boyu selvi yüzü mahlar nerede? 

Dünleri görmezse gözlerim çıksın..

Hoş görü sallanır,asılmış ipte,

Empati duygusu turşudur küpte,

Yürekleri çöl eyleyen sebebte,

Kinleri görmezse gözlerim çıksın..

Barış dilde kalmış,bak yürek başka,

Bu çelişki geçit vermez ki aşka,

Ya siyah,ya beyaz diyerek başka,

Tonları görmezse gözlerim çıksın..

Beden göçmüş ama ruh köyde durmuş,

Gönül o hep yanık kaydede durmuş,

Varoşlarda hayatları kararmış,

Canları görmezse gözlerim çıksın..

Dost o ki vefayı sevgiyle karar,

Genişte herkes var dar günde arar,

Sentezi ömrüne verilir karar,

Sonları görmezse gözlerim çıksın', 'Usandım hep benden,usandım bizden, Onları görmezse gözlerim çıksın. Mıhlanarak doruklara,merkezden, Yanları görmezse gözlerim çıksın.. Krall...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozlerim-ciksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Sultan', 'adi-sultan-hasan-uzel-ocrcm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adı Sultan soyadı Vefasız

Hatası yanlış yanlışı hata

Doğrusu ben ben uzaklarda

Yine ayrılık yine tecavüz aslında

Kaybediş bu belki de kayboluş

Sonu olmayan karanlık bir yokuş

Acı,ıstırab,bir gram mutluluk

Belki de o mutluluğun bedeli bu uğursuzluk

Gözyaşları neden akar niçin? 

Islanan yanakların suçu ne? 

Çekilen dertler deli mi ne

Sevmek mi aman uzak olsun be!', 'Adı Sultan soyadı Vefasız Hatası yanlış yanlışı hata Doğrusu ben ben uzaklarda Yine ayrılık yine tecavüz aslında Kaybediş bu belki de kaybol...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adi-sultan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Böyle Yapıyoruz', 'neden-boyle-yapiyoruz-seyfet-bozcali-w99up', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ülkemizin temelini,nefret ile sarsıyoruz,

İnsanların emeline,ön yargıyla bakıyoruz.

Hakaretle vicdanları,kötülükle lisanları,

Gönül eri insanları,Boş laflarla sarsıyoruz.

Hak hukukun şifasını,ilmin güçlü yuvasını,

Alimlerin davasını,Kulak ardı ediyoruz.

Şehit yatan toprakları,Al-yıldızlı bayrakları,

Seyfet der bunca hakları,Boş hayelle sarsıyoruz....

       18.02.2006', 'Ülkemizin temelini,nefret ile sarsıyoruz, İnsanların emeline,ön yargıyla bakıyoruz. Hakaretle vicdanları,kötülükle lisanları, Gönül eri insa...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neden-boyle-yapiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Daha Yazalım', 'bir-siir-daha-yazalim-yusuf-onder-bahceci-k3tbk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel seninle, bir şiir daha yazalım,

Yazdığımız şiirde, acıları anlatalım,

Sakın ha birbirimizi ağlatmayalım,

Gel seninle, bir şiir daha yazalım.

Yazdığımız şiirlerde ümitler olmalı,

Yazdığımız şiirlerde duygu olmalı,

Yazdığımız şiirlerde seni sormalı,

Gel seninle, bir şiir daha yazalım.

Gücün yetermi bir daha yazmaya,

Yazıp, yazıp böyle hep ağlamaya,

Böyle dualar ediyorum bil Allah''a,

Gel seninle, bir şiir daha yazalım.

Bu şiir güzel ve sonu mutlu olsun,

Bu şiir de sabır, sebat, inat olsun,

Şiirde sözden dönen alçak olsun,

Gel seninle, bir şiir daha yazalım...', 'Gel seninle, bir şiir daha yazalım, Yazdığımız şiirde, acıları anlatalım, Sakın ha birbirimizi ağlatmayalım, Gel seninle, bir şiir daha yaza...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-siir-daha-yazalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Sever misin?', 'cok-sever-misin-nurdane-diken-jzrno', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yâr saçında gül olsam, kapında sümbül olsam

Yolumda ölür müsün? benimle gelir misin? 

Sevdanda ateş olsam, ruhunda bir yer bulsam

Kül edip eler misin? yoksa çok sever misin? 

Yıldızsız gecelerde, göklerde parıldarım

Sevginle ötüşürüm, özleme sarılanım

Mihnete katlanırım, ömrüne karılanım

Zindana atar mısın? yoksa çok sever misin? 

Deli gönül inleme! yaramı hep kanatma! 

Sevmeyene kul olma! geçenleri unutma! 

Kısmetime sal beni, aşkımı sen uyutma! 

Kalbimi satar mısın? yoksa çok sever misin? 

Sen bana gelmez isen, ben sana geliyorum

Bulutlara sarılıp, kar gibi kalıyorum

Gönlüme sapladığın, hançeri biliyorum

Bırakıp gider misin? yoksa çok sever misin.

Zemheri ayında ben, ısıtan ateşinim

Yetimim, garibanım, senin güzel eşinim

Sevginin perisiyim, yolunun güneşiyim

Elinle iter misin? yoksa çok sever misin?', 'Yâr saçında gül olsam, kapında sümbül olsam Yolumda ölür müsün? benimle gelir misin?  Sevdanda ateş olsam, ruhunda bir yer bulsam Kül edip e...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cok-sever-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem''e (142)', 'annem-e-142-i-brahim-arslan-fmbc8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herşey seni hatırlatır bana,ne çare

Avutamam gönlümü,avutmak istesemde

Ölsemde unutamam, ölsemde

İşkencedir bana her an,gülsemde...

Herşey seni hatırlatır bana,ne çare...

Herşey seni anımsatıyor bana,unutmadım...

Günler,aylar,sensiz yaşanan baharlar

Ve hatıralar sende başlar...

Ondan akar gözümden yaşlar,

Herşey seni anımsatıyor bana,unutmadım...

Herşey yaşandı,bugün gözümde canlandı mazi..

Bir sıcacık bakışın,yine bak yine

Öyle muhtacım ki senin sevgine,

Beni bir daha öpsene anne,

Herşey yaşandı,bugün gözümde canlandı mazi..

Herşey seninle başladı,seninle bitti

Bir soluk aldım,aldığım gün ağladım...

Büyüdüm,büyüttün,ellerinle yürüttün,unutmadım

senle öldüm,sen öldüğün gün,yaşamadım...

Herşey seninle başladı,seninle bitti...

                                      6.6.1999', 'Herşey seni hatırlatır bana,ne çare Avutamam gönlümü,avutmak istesemde Ölsemde unutamam, ölsemde İşkencedir bana her an,gülsemde... Herşey s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/annem-e-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile Müzesi', 'cile-muzesi-gultekin-toga-q9u5f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağların koynundan sızan gözeyi,

         Merak ediyorsan gözlerime bak..

         Çilelerle nakışlanmıs müzeyi

         Arama uzakta özlerime bak..

         Adalet içindir yürek atışım,

         Yalnız zalimedir ben deki hışım,

          Muhabbete meşaledir ateşim,

         Gel gör yangınımı,közlerime bak..

         Hayatım boyunca maske takmadım,

         Öze döndüm kabuklara takmadım,

         Zalimin suyuna göre akmadım,

         İşte çırılçıplak yüzlerime bak..

         Boyuna posuna,ününe bakmam,

         Bana özü lazım gönüne bakmam

         Haksızın şahından sözümü çekmem

         Kimle paylaşıyom kozlarıma bak..

       

         Hakk benim mefkurem deneme beni

         Dobra dobur diye kınama beni,

         Sentezi ´yim elden tanıma beni,

         Beni benden öğren sözlerime bak.', 'Dağların koynundan sızan gözeyi,          Merak ediyorsan gözlerime bak..          Çilelerle nakışlanmıs müzeyi          Arama uzakta özleri...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cile-muzesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bir Reklam Değildir.', 'bu-bir-reklam-degildir-mehmet-dogan-8-jwl3q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alayım elime kalemi 

Yazayım başıma geleni

Sen söyle hayta veli emmi

Neresi şu bizim com nokta

Aklıma gelirsin bazı an

Kimdiki seni böyle bozan

Yıkılsın bu bozuk düzen

Neresi şu bizim com nokta

Bağı kursak haciz gelir

Yurdu kursan taciz gelir

Uckurumuz mu rehin kalır

Neresi şu bizim com nokta

Yörük ne bilirki bayramı

Lak lak mı içerdik ayranı

Geldi işte vakti tam zamanı

Neresi şu bizim com nokta', 'Alayım elime kalemi  Yazayım başıma geleni Sen söyle hayta veli emmi Neresi şu bizim com nokta Aklıma gelirsin bazı an Kimdiki seni böyle bo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 8']::text[], 8.5, '{"poet":"Mehmet Doğan 8","poet_slug":"mehmet-dogan-8","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-bir-reklam-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bu', 'gonul-bu-gultekin-toga-bco2n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çiçek gibi açar dost ikliminde,

       Düşmanlığı,kini sevmez bu gönlüm.

       Hep yaşamak ister mest ikliminde

       Muhabbetsiz anı sevmez bu gönlüm.

       O dostudur mazlum olan herkesin,

       Hayranıdır hakca haykıraran sesin,

       Sevdası dorukta, inancı kesin,

       Köşe,bucak,yanı sevmez bu gönlüm.

      Duygu bir yüreğin şelalesidir,

     Duygusuz insanlar baş belasıdır,

     Heyacan insanin velvelesidir,

     Buz kesilmiş,donu sevmez bu gönlüm.

    Arının derdi ne? Çiçeğe deli,

    Kendimi yiyecek yaptığı balı? 

    Emsaldir belada bülbülün hali,

    Aşktan özge konu sevmez bu gönlüm.', 'Çiçek gibi açar dost ikliminde,        Düşmanlığı,kini sevmez bu gönlüm.        Hep yaşamak ister mest ikliminde        Muhabbetsiz anı sevm...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-bu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdim Sade Konuşmak', 'derdim-sade-konusmak-yusuf-onder-bahceci-gkr9t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sana buradan, bak yalvarıyorum,

Allah''ın adıyla da sana and veriyorum,

Senin bu hâline de, böyle deliriyorum,

Ben sana buradan, bak yalvarıyorum.

İyi biliyorum sende şiirleri okuyorsun,

Okuyorsun, okuyorsun, kahroluyorsun,

Beni mutlu zannetme sen yanılıyorsun,

Ben sana buradan, bak yalvarıyorum.

Sakın beni yanlış anlama, ayıramam,

Kalleşlerin bu yaptığına dayanamam,

Şartlar müsait olsa seni, bırakamam,

Ben sana buradan, bak yalvarıyorum.

Benim derdim sade senle konuşmak,

Konuşmak, derdine hep ortak olmak,

Ahlaksız değilim ben sonumuz toprak,

Benim derdim sade senle konuşmak...', 'Ben sana buradan, bak yalvarıyorum, Allah''ın adıyla da sana and veriyorum, Senin bu hâline de, böyle deliriyorum, Ben sana buradan, bak yalv...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derdim-sade-konusmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yola Çıktım', 'yola-ciktim-gultekin-toga-9gi8l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir noktadan yola çıktım,

     Bugunden yarına doğru.

     Düşündüm,canımı sıktım

     Yüzeyden derine doğru.

     Öksüzüm canan olmadan,

     Koştum delice ardından,

     Yanmak için can attım can,

     Öz aşkın koruna doğru..

     Özlüyorum mahkum gibi,

     Göz yaşım akar kum gibi

     Eriyorum bir mum gibi,

     Kalbimin yarine doğru..

      Dışarıdan mikrop gelir

      Zayıf noktaları bulur,

     Hücre savaşırken ölür,

     Dönüşür irine doğru.

     Sentezi çare nerede? 

     Senden parça var yarada,

     Baht demirledi karada,

     Feleğin darına doğru..', 'Bir noktadan yola çıktım,      Bugunden yarına doğru.      Düşündüm,canımı sıktım      Yüzeyden derine doğru.      Öksüzüm canan olmadan,   ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yola-ciktim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Kaldı', 'dost-kaldi-gultekin-toga-q8uwm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çekti gitti niceleri,

             Azımız dost kaldı bize,

             Ayaz gurbet geceleri,

             Buzumuz dost kaldı bize..

             Gönül oldu boyun büken,

             Umut bakı,ufka bakan,

             Sicim sicim yağmur döken,

             Gözümüz dost kaldı bize..

             Gam yükleri katar katar,

             Her gamda bir volkan patlar,

             Nöbet gibi gelir tutar,

             Sızımız dost kaldı bize.

             Çilenin ayrılmaz eşi,

             Istırapın azı dişi,

             Yaktı ayrılık ateşi,

             Közümüz dost kaldı bize.

             Derinleştikce Sentezi

             Fikr hayatın tadı tuzu,

             Gösterdi ki bugun,mazi; 

             Özümüz dost kaldı bize..', 'Çekti gitti niceleri,              Azımız dost kaldı bize,              Ayaz gurbet geceleri,              Buzumuz dost kaldı bize..        ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dost-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevapsızlık', 'cevapsizlik-hasan-kostak-3lx93', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Açlık artık alışkanlık haline gelmeye başlamıştı

Aslında suçlu bizdik

Son paramızı içkiye

Son duygumuzuda aşka veriyorduk

Bir sebep olmasına gerek yoktu

Biri bişey söylese

Biz oluyorduk hemen

Ve sonlarımızı kullanıyorduk 

Dostlar ah o dostlar

Hep onlar vardı

Bilinmezlikler oluyordu

Geçmişten,gelecekten,umutlardan,korkulardan

Cevaba azda olsa yaklaşsak

Ya biz kaçıyorduk

Yada biri kaçıyordu

Ve bu sona ulaşamamak 

Bitmeden 

Yeniden başlamak 

Herşeye rağmen hepsi güzeldi 

Özledim

AMASYA', 'Açlık artık alışkanlık haline gelmeye başlamıştı Aslında suçlu bizdik Son paramızı içkiye Son duygumuzuda aşka veriyorduk Bir sebep olmasına...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kostak']::text[], 8.5, '{"poet":"Hasan Kostak","poet_slug":"hasan-kostak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cevapsizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıkamış Şehitlerine', 'sarikamis-sehitlerine-seyfet-bozcali-j8moo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allahu ekber ismin ne güzel senin,

Şehit askerlerle süslü eteğin,

Bunca yıldır yaslı kalmış yüreğin,

Onları bağrında saklayın dağlar,

Bir tarihin nabzı burada atar...

Sendedir doksan bin Şehit mezarı,

Vatan özlemiyle karlı diyarı,

Rahmet yeli okşar şanlı mezarı,

O günleri anın ağlayın dağlar,

Bir cok acıları saklayın dağlar...

Çok can ağıt yaktı kabir başında,

Bulut yaşlar döktü,mezar taşında.

Melek gıpta etti,şehit düşünde,

Bu koç ataları bekleyin dağlar,

O günkü acıyı saklayın dağlar...

Seyfet der okuruz,onlara rahmet,

O kahramanlara sunmalı hürmet,

Allahu Ekber dağı sana bir zahmet,

O kahraman ırkı bekleyin dağlar,

Mahşere dek onu saklayın dağlar...

      KARS/     Sarıkamış Şehitlerine

18.02.2006', 'Allahu ekber ismin ne güzel senin, Şehit askerlerle süslü eteğin, Bunca yıldır yaslı kalmış yüreğin, Onları bağrında saklayın dağlar, Bir ta...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sarikamis-sehitlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Yörük Anam...', 'ah-yoruk-anam-mehmet-dogan-8-em5jh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah Yörük Anam

Gece rengiydi saçların 

Tel tel güneşlere mi tarattın 

Bembeyaz seriliverdi 

Kara günlerin... 

Başındaki aktan çok 

Ak döşeklere mi yattın Anam 

On bir çocuk doğurdun 

Çoğumuzu dağlarda taşlarda yitirdin 

Harcadın ziyan ettin emeklerini 

Acıların fayı tetiklenir de 

Sabır taşı çatlamaz mı 

Yılların artçı depremlerine nasıl direndin 

Gülümsedin 

Yüreğinden sevgiler sağdın 

Sevinçler icat ettin 

Kimsin 

Nesin 

Necisin 

Böyle metanet 

Böyle cesaret 

Böyle bir şefkat nerede Yörük Anam söylen 

Ben emerken terli miydi sinen 

Bir esinti koptu yaylalardan 

Çam püren kekik kokuları sürdü getirdi 

Böyle mi tüter tenin 

Burnumun direğini sızlatır 

Kilimlerinde İlmek ilmek motiflerin 

Çilelerime hasret nakışları mı dokudun 

Nasıl anlatırım anam nasıl 

Duygularım ifadesiz 

Kelimelerim kifayetsiz 

İradesiz kaldım 

Gizli bakışlarını çevir 

Aklımı fikrimi yoluna yönelt...', 'Ah Yörük Anam Gece rengiydi saçların  Tel tel güneşlere mi tarattın  Bembeyaz seriliverdi  Kara günlerin...  Başındaki aktan çok  Ak döşekle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 8']::text[], 8.5, '{"poet":"Mehmet Doğan 8","poet_slug":"mehmet-dogan-8","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ah-yoruk-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesilmedik Karpuz Derler', 'kesilmedik-karpuz-derler-yusuf-onder-bahceci-h8y96', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani derler ya sen adamı nereden bileceksin,

Kesilmedik karpuzdur sen nerden bileceksin,

Biraz konuşturup, yüz hatlarını inceleyeceksin,

Şunu bil İnsanların yüzleri kâlplerinin aynasıdır. 

Adamı tanımak istiyorsan beraber yemek ye,

Önüne eti koy bakayım, sana dönderiyor mu,

Ayrıca da beraber, şöyle bir yolculuk et hele,

Kendisi yan gelip yatıyor, acaba benmi diyor.

Çok fazla gevezelik ediyorsa aman uzak ola,

Hele hele çok övünüyorsa belki bir tuzak ola,

Çek, senet, banka, borsa deyip te duruyorsa,

Benim bu tür işlerle fazla işim yok uğurlar ola.

Adam, adam olmalı ve adam gibi konuşmalı,

Adam karşısındakine, kibar ve nazik olmalı,

Adamın kâlbi ve dilinde, Allah kelamı olmalı,

Şunu bilki İnsanların yüzleri hep temiz olmalı.', 'Hani derler ya sen adamı nereden bileceksin, Kesilmedik karpuzdur sen nerden bileceksin, Biraz konuşturup, yüz hatlarını inceleyeceksin, Şun...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kesilmedik-karpuz-derler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-nuray-acar-urcm0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Görünmez bir yaradır çığlık

Boğazda sancıdır

Ruhundaki derin acıdır

Dokuz boğumda çığlık

Boğazda yaradır

İçinden kanar, kanatır 

Doğum yapmış kadının 

Haykırışındaki acı feryattır

Çığ gibi düşer bedene 

Güneşin gölgesinin düştüğünde

Toprağa yansıdığı gibi', 'Görünmez bir yaradır çığlık Boğazda sancıdır Ruhundaki derin acıdır Dokuz boğumda çığlık Boğazda yaradır İçinden kanar, kanatır  Doğum yapmı...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ciglik-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf Ediyorum', 'i-tiraf-ediyorum-yavuz-dogan-jnm6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kabir duvarının altında kalmış canın 

Toprağında yastıktım, itiraf ediyorum. 

Aşkı azık eylemiş günah dolu şeytanın 

Ekmeğine katıktım, itiraf ediyorum. 

Rehnedilmiş aşkların hapsolduğu kafeste 

Sam yelinin ortağı vuslat kokan nefeste 

Hasreti zikreyleyen umursamaz bir seste 

Aşkı zindana tıktım, itiraf ediyorum. 

Kimisi karanlığı kendine yar ederken 

Kimisi karanlıkta kendini var ederken 

Kimisi karanlığa aşkı ihbar ederken 

Karanlıklardan çıktım, itiraf ediyorum. 

Ne düzeni düzensiz düzenin bekçisiydim 

Ne devrimci bir aşkın suskun tüfekçisiydim 

Ne şeytana kul olmuş suçun emekçisiydim 

Yalnız aşka âşıktım, itiraf ediyorum. 

Çünkü sevdaya hasret kalmış dudağım kadar 

Silmekten yorulduğum ıslak yanağım kadar 

Unutulmuş bir ada ve başparmağım kadar 

Yalnızlığımdan bıktım, itiraf ediyorum. 

Şimdi suçuma ortak kaç kırgın kalem varsa 

Çekmekten usandığım ne kadar çilem varsa 

Bende aşka birikmiş kaç korsan eylem varsa 

Hepsine kurşun sıktım, itiraf ediyorum 

Ve artık tüm sözlerim ışığın gölgesiyken 

Yüreğin bir işgalden arınmış bölgesiyken

Sarf ettiğim her cümle bir ihbar belgesiyken 

Ömrümde bir çağ yıktım, itiraf ediyorum.', 'Bir kabir duvarının altında kalmış canın  Toprağında yastıktım, itiraf ediyorum.  Aşkı azık eylemiş günah dolu şeytanın  Ekmeğine katıktım, ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Doğan']::text[], 8.5, '{"poet":"Yavuz Doğan","poet_slug":"yavuz-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/itiraf-ediyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aniden Gelirim, Biliyorsun', 'aniden-gelirim-biliyorsun-bahri-yildirim-fsu5i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kadar çabuk solamazsın

Bir demet gül değilsin ya! 

Unutmazsın biliyorum

Değilsin ya vefasız

Uzağa gitmek için

Değilki  bu  küçücük ayrılık

Sana gelmek için

Kendimi terkediyorum

Değişiyor adresim.

Şurada ne kaldıki kavuşmaya

Bir nefes,bir nefes daha

Ya da bir cigara çekimi

Hemen alınma yani

Şurada ne kaldiki sana

Sana geliyorum.bir tanem

Yüreğim sen dolu sevda

Solmazsın biliyorum

Kırılgan gül değilsin ya

Al yüreğini eline

Bak! Gelmişim bile..

Yeterki:

Sen candan iste.', 'Bu kadar çabuk solamazsın Bir demet gül değilsin ya!  Unutmazsın biliyorum Değilsin ya vefasız Uzağa gitmek için Değilki  bu  küçücük ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aniden-gelirim-biliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mühür', 'muhur-nuray-acar-n6kbz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dünya özel günleri anma peşinde, 

oysa herşey insan içinde, 

kimi yürekten söyler 

kimi dilden, 

....................... şöyle bir geçer 

aşkı anlatır bakan gözler 

gözlerin mühürünü de 

........................ yürekler gizler 

bu sırra erince gönüller 

ölsede beden 

....................... ruhta silinmez izler', 'dünya özel günleri anma peşinde,  oysa herşey insan içinde,  kimi yürekten söyler  kimi dilden,  ....................... şöyle bir geçer  aş...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/muhur-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem Artık Baharı', 'i-stemem-artik-bahari-mehmet-134-hzuvx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sensizken sevdim,

Ben bu aska bir ömür verdim,

Sensiz mutluluga erdim,

Bir bahar günü kaybettim seni,

İstemem artık baharı.', 'Seni sensizken sevdim, Ben bu aska bir ömür verdim, Sensiz mutluluga erdim, Bir bahar günü kaybettim seni, İstemem artık baharı....', ARRAY['Türk Edebiyatı','Şiir','Mehmet 134']::text[], 8.5, '{"poet":"Mehmet 134","poet_slug":"mehmet-134","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/istemem-artik-bahari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Offf', 'offf-nuray-acar-gyw7a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'offfff 

nereden düştüm 

bu aşka... 

şiirin 

tutkulu 

kuyusuna... 

uykusuz bıraktığı 

gecelere 

hüzüne boğduğu 

günlere 

ya bırakırsa 

korkusu... 

azrailinkini 

bastıracak 

cinsten... 

dedim ya 

nereden düştüm 

bu 

aşka....', 'offfff  nereden düştüm  bu aşka...  şiirin  tutkulu  kuyusuna...  uykusuz bıraktığı  gecelere  hüzüne boğduğu  günlere  ya bırakırsa  korkus...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/offf-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engel', 'engel-nuray-acar-4d6qz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden 

engel koyarsınız 

ayaklarımın 

dibine 

Bilmez misiniz 

aceleci olduğumu 

adımlarımı çarçabuk attığımı 

ve 

tökezlemem an meselesi 

Elinizden geliyorsa 

bırakın 

ısrarcı 

engelleri 

kaldırın 

mertçe 

şu kısacık 

trajikomik yaşamdan 

tutun şimdi 

bir ucundan 

yaşama devam etmek adına', 'Neden  engel koyarsınız  ayaklarımın  dibine  Bilmez misiniz  aceleci olduğumu  adımlarımı çarçabuk attığımı  ve  tökezlemem an meselesi  El...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/engel-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Seven', 'gercek-seven-nuray-acar-b99xu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevseydi baktığında gözleri 

Saçlarımın karasında özlemi 

Oysa buğday başaklarındaydı gözleri 

Yabancıydı aradığı neydi 

Seher vakti kuşlar yuvaya döner misali 

Düşlerim ayağıma geldi demiştin 

Peşim sıra benimle olmak için çırpınırken 

Zaman mı seni yanılttı sen mi yalancıydın 

Bak halen kulaklarımda gecenin kuytu karanlığında 

Kaderimdin demiştin ellerin avuçlarımda 

Sendin beni kendine konuk eden illaki sen sen diyen 

Şimdi boş bir kutu misali tozlu raflara sindirilen 

Ferhat oldun dağları deldin ovama geldin 

Telli duvaklı gelin edip diyarına sürükledin 

Gurbette sılayı özlettin yar sen neyledin 

Yoksa boşa mı geçti senelerim 

Yanlışı nerede yaptım 

Ah mı aldım bu cezaya çarptırıldım 

Meyve verdim yıllar sonra 

Sevindim diyemedim 

Beni ben gibi sevseydin 

Benim seni senden ziyade.', 'Sevseydi baktığında gözleri  Saçlarımın karasında özlemi  Oysa buğday başaklarındaydı gözleri  Yabancıydı aradığı neydi  Seher vakti kuşlar ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gercek-seven-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-nuray-acar-1k7e0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu ümit denen duygu olmasa 

nerde bizde yaşama çelme atacak yürek 

bir var bir yoksun düş müsün gerçek mi 

sormasamda ümidimsin 

sıcak içten insanca 

bir gün gelirde ümit kuş gibi 

pencereden gökyüzüne süzülürde giderse 

sonsuzluk ülkesine 

selam durmak düşer mendil sallayan ellere 

gözlerde bir kaç damla anı yüklü gözyaşıyla', 'Şu ümit denen duygu olmasa  nerde bizde yaşama çelme atacak yürek  bir var bir yoksun düş müsün gerçek mi  sormasamda ümidimsin  sıcak içten...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umit-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dog günesim', 'dog-gunesim-ayla-efe-185oe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu kollarima

Kalbim köle yollarina

Iyi olan kullarina

Önce sen dog günesim

Sevgin isitsin icimi

Gami keder buharlassin

Kin garezi uzaklassin

Sen dogunca günesim.

24.04.1988 krefeld  Almanya', 'Sevgi dolu kollarima Kalbim köle yollarina Iyi olan kullarina Önce sen dog günesim Sevgin isitsin icimi Gami keder buharlassin Kin garezi uz...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dog-gunesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark', 'fark-muammer-erturan-cc7a6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşüyor yakandan düşler...

Düşsüzleşiyorsun...

Alışmalara alışıyorsun

daha da beteri...

Herkes gibi

alıyorsun gardını,

herkese...

Herkes gibi

pusuyorsun ya da

karanlık varoşlarında yalnızlığın...

Herkesleşiyorsun yani

enikonu...

Tek farkın,

farksızlaştığının farkındasın...

(''99)', 'Düşüyor yakandan düşler... Düşsüzleşiyorsun... Alışmalara alışıyorsun daha da beteri... Herkes gibi alıyorsun gardını, herkese... Herkes gib...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/fark-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-nuray-acar-xdr4r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaçmayın görüyorum sizi 

yıldızlar 

biriniz sağımda biriniz solumda 

nasılda muzipsiniz bakışlarınızda 

Şen şakrak gülümseyerek 

gidiyorum kutuplara 

buzullar ülkesine 

en yakın orada bulurum 

bekli de dokunurum sizlere 

En yüce dağlara çıkarım belki 

bayrak olacak elimde sizin kadar parlak 

sizin kadar alımlı 

ihtişamınıza hayranken gizliden gizliye 

sizi kendime bağlayacağım 

Ve yeryüzüne gökkuşağından kayarak 

ineceğim belki en uzun nehirlere 

belki de okyanusta minik bir adacıkta 

soluklanacağız yıldızlarla 

Saçlarımızda bir yığın yıldız yağmuruyla 

deniz kabuklarından iyot yüklü mavilikleri 

taşıyacağız gökyüzüne 

Yıldızları maviliklerin derinliklerine indireceğiz 

ben düşlerimi gerçekleştirirken 

güzel güneş sakın ışıma 

İşim bittiğinde tüm ihtişamını ver maviliklere 

yıldızların pırıltısını denizin koyu mavisine 

güneşin sıcak sarısını denizin serin sularına 

Yerçekimi kaçsın buralardan birbirine girsin 

girift bir hal alsın güzelliğinde 

yıldız yağmurundan iyot yüklü dalgalar 

düşleri gündüze sal 

gerçeği düşlere', 'Kaçmayın görüyorum sizi  yıldızlar  biriniz sağımda biriniz solumda  nasılda muzipsiniz bakışlarınızda  Şen şakrak gülümseyerek  gidiyorum k...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yildizlar-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın Yeri Bu', 'yangin-yeri-bu-nuray-acar-i2xmj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yangın yeri bu 

Bu beden ki külleri ha uçtu ha uçacak 

Biri sesimi duysa canım acımıyor sanacak 

Yangın yeri bu 

Bu beden ki külleri ha uçtu ha uçacak 

Bakıyorsun var gibiyim 

Vallahi gölgeyim gölge 

Yakınıma gel gör diyeceğim amma 

Yangın yeri bu 

Bu beden ki külleri ha uçtu ha uçacak', 'Yangın yeri bu  Bu beden ki külleri ha uçtu ha uçacak  Biri sesimi duysa canım acımıyor sanacak  Yangın yeri bu  Bu beden ki külleri ha uçtu...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yangin-yeri-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk..', 'ataturk-ayla-efe-1rk6s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cumhuriyeti kuran

Düsmani yurtdan kovan

Hürriyete kavusturan

Sen oldun ATATÜRK

Senin adinla okuduk

Senin adinla yazdik

Bunca diyar gezdik

Yok senin gibi büyük

Adin yazili kalbime

Seni övmek az bile

Anarim adini her nefesimde

ATATÜRK ATATÜRK ATATÜRK:', 'Cumhuriyeti kuran Düsmani yurtdan kovan Hürriyete kavusturan Sen oldun ATATÜRK Senin adinla okuduk Senin adinla yazdik Bunca diyar gezdik Yo...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ataturk-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçum Sabit', 'sucum-sabit-ahmet-uslu-astla-0rymk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sevmekti tek suçum,

Başka bir suçum var mı? 

Onu da bilmiyorum.

Ama bildiğim bir şey var:

Seni severek büyük bir suç işledim.

Seni sevmekti suçum,

Evet mapusta yatmam bu suçtan,

Suç sayılmaz belki de adaletin önünde,

Belki de gülerler bana bu da suç mu diye! 

Ama ben biliyorum ki:

Benim suçum sabit.

Beni, suçlu bulmalarını isterdim.

Bana zulüm etmelerini,

zindanlarda çürümeye bırakmalarını,

asmalarını isterdim beni.

Nasıl sevebildim seni,

Nasıl değer verebildim,

Nasıl ölüme gittim senin için.

Kendimi suçlu hissediyorum,

Kendime suçlu diyorum.

Sırf:

Seni sevdim diye.

Seni sevmekti benim suçum.

Suçlamasalarda,

Suçsuz bulsalarda beni,

Benim suçum sabit.

Ben suçumu yaşayarak çekiyorum,

Yaşamak suç olana kadar.', 'Seni sevmekti tek suçum, Başka bir suçum var mı?  Onu da bilmiyorum. Ama bildiğim bir şey var: Seni severek büyük bir suç işledim. Seni sevm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uslu Astla']::text[], 8.5, '{"poet":"Ahmet Uslu Astla","poet_slug":"ahmet-uslu-astla","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sucum-sabit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Gecenin Sabahıydı', 'hangi-gecenin-sabahiydi-nurhan-gokturk-snqe9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangi gecenin sabahıydı o sabah, 

İçimde kırılmış lığın o tuhaf tadı,

Issız odaların yüzüme çarpan soğukluğu,

Duvarlardaki resimlerde kaybolmuş yüzler,

Sağa sola atılmış kirli çamaşırlar,

Hangi gecenin sabahıydı o sabah,

Açık pencereden içeri dolan yosun kokusu,

Islak dudaklarımda uçuk çıkaran rüzgar,

Hangi gecenin sabahıydı o sabah,

Uykularda kaldım uyanamadım bu düşten,

Korkuyorum anılardaki yüzünü kaybetmekten,

Görmek istiyor gözlerim tüm gerçekleri,

Kaldırın perdeleri,

Anladım! ....

 Terk edildiğim gecenin sabahıydı bu sabah

Nurhan Göktürk

(16 Nisan 2004/Antalya)', 'Hangi gecenin sabahıydı o sabah,  İçimde kırılmış lığın o tuhaf tadı, Issız odaların yüzüme çarpan soğukluğu, Duvarlardaki resimlerde kaybol...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hangi-gecenin-sabahiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Biz Yaptın', 'bizi-biz-yaptin-nuray-acar-y807a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni marş yaptık 

Besteledik dile doladık can yaptık 

Sen ki bizi biz yaptın 

Yalan yanlış kötü ne varsa 

Uğramıyorsa şimdi bizim sokağa. 

Söylemiştin paylaşmak bilgi denizidir 

Sizlerin rehberliğinde bizlerin gözünde 

Çoğaldıkça evreni sarıyor 

Ve bu deniz işte böyle doluyor', 'Seni marş yaptık  Besteledik dile doladık can yaptık  Sen ki bizi biz yaptın  Yalan yanlış kötü ne varsa  Uğramıyorsa şimdi bizim sokağa.  S...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bizi-biz-yaptin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-ayla-efe-gnfrv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha çocuk yasta kaldim sensiz,

Öksüz ve boynu bükük

Senelerce habersiz

Simdi yine ayri düstük.

En son kavustum derken

Ayirdi felek bizi

Alinca mektubunu

Kapliyor icimi derin sizi

Elimde su an resmin

Seninde solmus acilardan rengin

Icimi ceker ahhhhh anacigim derim,

Gelipte izin zamani seni

Ayla Efe

krefeld', 'Daha çocuk yasta kaldim sensiz, Öksüz ve boynu bükük Senelerce habersiz Simdi yine ayri düstük. En son kavustum derken Ayirdi felek bizi Ali...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/annecigim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Bayram Dilekleri Bendenizden', 'i-yi-bayram-dilekleri-bendenizden-nuray-acar-zihvi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şekersiniz illaki en kalitelisinden karamelli 

Öptüm yanaklarınızdan 

Çaktırmadan da dudaklarınızdan 

Kızardınız eğdiniz başınızı utangaçlıkla 

Bayramları seviyorum sınırlama yok diye 

Belki şen şakrak oluyor bütün ebeveynler 

Yaramazlıklarımızı hoş görüyorlar 

İşte çocuk olduğumuzu bu bayramda anımsıyorlar 

Bayramları seviyorum, 

Bayramlık giymesem de 

Elini öpecek büyüklere sahip değilken de 

Bayramları seviyorum 

Vallahi bunu içten söylüyorum yalanım var ise çarpsın bayram beni. 

Kocaman bir dağ olsun şekerden 

Aldıkça eksilmesin gizliden geceden yığılsın stoktan 

Şekerleri dağıtalım en yüksek binalardan balon niyetine 

Kapsın çocuklar birde çocuk olduğunu unutmak istemeyen yürekler 

Bayramınız kutlu olsun sıcak bir yudum çay içinizi ısıtıyorsa soğukta 

Selamım da eritsin kötü niyetli düşünceleri gelsin tüm samimiyetiyle.', 'Şekersiniz illaki en kalitelisinden karamelli  Öptüm yanaklarınızdan  Çaktırmadan da dudaklarınızdan  Kızardınız eğdiniz başınızı utangaçlık...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/iyi-bayram-dilekleri-bendenizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İspiyon 2', 'i-spiyon-2-hasan-kostak-eam72', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçmişi anlatıyor bu kelimeler

Yazıldığı anda bile bayattılar

İspiyonlayın bayatlamışlar o aşkı

Sorguluyorum sizi

Nazlı olmayan bir aşktı

Çekiciliği sert ve lider haliydi

Bu durum onu dahada ulaşılmaz kılıyordu

Güzellikler ona yakışıyordu

Örnek olmuştu diğer aşklara

Bırakın güzel günleri

Başka sorgulamada anlatırsınız

Neden bitti bu aşk anlatın bakalım

Bu sert lider aşk bir anda başkaldırdı

Liderler tek gitmezlerdi

Yüzüstü bıraktı geride kalanı

Oysa geride kalan grurunu çöpe atmıştı

Tadını çıkar istersen diyordu

Sorgulanmayı ve sorgulamayı kabul etmedi lider

Gitti sessiz bir başkaldırıyla

Bizde bilmiyoruz niye gitti

Bütün bildiklerimiz bunlardır 

Ne yapalım bu kelimeleri

Salalım gitsin 

Aşkları,mutlulukları,hüzünleri,ayrılıkları

Herkese ispiyonlamaya devam etsinler

Beypazarı', 'Geçmişi anlatıyor bu kelimeler Yazıldığı anda bile bayattılar İspiyonlayın bayatlamışlar o aşkı Sorguluyorum sizi Nazlı olmayan bir aşktı Çe...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kostak']::text[], 8.5, '{"poet":"Hasan Kostak","poet_slug":"hasan-kostak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ispiyon-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Seli', 'duygu-seli-nuray-acar-rgvnw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağma yağmur böylesine hızlı 

Acelen olmasın seni özlüyor iken 

Şu duygu selindeki insan yüreklerimiz 

Korkmasam şehri su basacak diye 

Setler kurardım önüne 

Betondan zeminlere 

Yüksek duvarlarla çepeçevre 

Söyleyeceklerimi akıtsam 

Göz pınarlarımdan avuçlarına 

Karışsa yağmur sularına 

Bulansan acımdan kederimden 

Sense arıtsan tüm saflığınla 

Yağma yağmur böylesine hızlı 

Acelen olmasın seni özlüyor iken 

Şu duygu selindeki insan yüreklerimiz.', 'Yağma yağmur böylesine hızlı  Acelen olmasın seni özlüyor iken  Şu duygu selindeki insan yüreklerimiz  Korkmasam şehri su basacak diye  Setl...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/duygu-seli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Kapıyı Bezirgan Başı', 'ac-kapiyi-bezirgan-basi-ahmet-yozgat-d4fpd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Oyunlarda ebemiz hep sen olurdun.

Sevgi değer Hakan ağabey

Yani çelik çomakta bey

''De hey! '' çekerdin halayda

Saklambaç oyununu pek sevmezdin

Hemen çatıverirdin kaşı 

Bilirdik gönlünden geçeni o an

Ve başlardık avaz avaz bağırmaya

Mahallenin boş arsasında biz:

''Aç kapıyı bezirgan başı! ''

2/:

Açılırdı hayalimizde bin bir çatallı kapı

Bir ucu uzardı ta İstanbul''a kadar,

Sahipsiz boş arsamızın,

Diğer ucunda yer alırdı Konya, ya da Karaman

Ya da bulurdu alt sınırı Mersin''i, Kaş''ı.

Düşerdik ki pek yaman: aman aman! 

Bağırırdık küçük, büyük: 

''Aç kapıyı masalcıbaşı! ''

3/:

Peş peşe dizilirdi küçükler.

Muğla ile Ardahan arasına

Eller mengene olur, kenetlenirdi 

Öndeki oyundaşımızın beline.

Lastik gibi gerilirdi uzuneşek

Çeldiğin çelik komşu ülkeye düşerdi

Hakan ağabey, sen anında çatardın kaşı

Biz de düşerdik yere pek yaman: aman aman! 

O zaman bağırırdık yanık yanık:

''Aç kapıyı muhafız başı! ''', '1/: Oyunlarda ebemiz hep sen olurdun. Sevgi değer Hakan ağabey Yani çelik çomakta bey ''De hey! '' çekerdin halayda Saklambaç oyununu pek sevm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ac-kapiyi-bezirgan-basi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağzı Kulağında Erbay Ağabey', 'agzi-kulaginda-erbay-agabey-ahmet-yozgat-nxrj3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Erbay Kücet''e''

1/:

O bizim Erbay ağabeyimizdir,

Ağzı kulaklarına varan anlı şanlı beyimizdir,

Komik fıkralar meşin çantasında,

Islık cebinde neşeli kahkahalar taşır,

O gülünce ağzı kulaklarına ulaşır.

Trabzonlu Temel''in asker arkadaşıdır bildiğim kadarıyla,

Namık Kemal ile silistre''de de çarpışmıştır,

Yani Baltacı komutasında Katerina yengemize karşı,

Bir de utanmadan anlatır bunu,

Onun unu her zaman çuvalında hazırdır,

Eleğini asmaz duvara, her daim elindedir.

Beynindedir muzipzade tilkiler,

O bizim Erbay ağabeyimizdir,

Gülelim diye bekler...

İster ki neşelenelim ve kam alalım dünyadan,

Bir dayısının kayınbiraderi İncili Çavuş''tan dem vurur,

Bir döner halasının oğlu Bekri Mustafa''dan...

O bizim Erbay ağabeyimizdir,

Bir Fransız,

Bir İngiliz,

Ve Bir Türk''ten komik fıkralar dökülür dudaklarından,

Çünkü o dağarcığında bin bir neşeli anekdotlar taşır,

O gülünce ağzı kulaklarına ulaşır.

2/:

Aslında o herkesin Erbay ağabeysidir,

Ama yine de ''Ağabey...'' der herkese,

Her bir sese kulak verir,

Yan cebinde neşeli hatıralar taşır,

O gülünce ağzı kulaklarına ulaşır. 

3/:

Aslında o Erbay ağabeysidir cümle milletin,

Yani herkes ile koklaşır düğün dernekte, 

Ve sevişsekte, dövüşsekte hepimizle anlaşır.

Sağ kulağının ardında neşeli sohbetler taşır,

O gülünce ağzı kulaklarına ulaşır. 

4/:

Dedik ya o Erbay ağabeysidir tel dikişli kitapların,

''İlerleyelim Beyler'' diye uyarır otobüsteki uyuşukları,

Bazen sapıtır (Ahmetyozgat''ın aklına uyup,) 

''Kendi Kilisesini Kendisi Kurar''

Trajikomik öyküler yazar kimi zaman insanlar gülsün diye.

Bayramlarda hediye şiirler dağıtır cıvıltılı çocuklara, 

Yani ''Fıkır Fıkır Fıkralar''ın ardına düşer,

Kimi zaman ''Şirin Şiirler'' deryasına sürer atını,

Ama her daim dudağının kenarında kırmızı gülücükler taşır.

O gülünce ağzı kulaklarına ulaşır.

5/:

Yani ey şiir ehli,

Başka söze ne hacet,

İşte budur bizim Erbay Kücet...', '''Erbay Kücet''e'' 1/: O bizim Erbay ağabeyimizdir, Ağzı kulaklarına varan anlı şanlı beyimizdir, Komik fıkralar meşin çantasında, Islık cebind...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/agzi-kulaginda-erbay-agabey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmakarışığım', 'karmakarisigim-nuray-acar-x8j5f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'içerdesin duvarlarla başbaşa 

bir rüzgar eser aniden 

nereden geldiğini haber bile vermeden 

karmakarışık saçlarınsa 

inatla gelir gözlerinin önüne 

beni hisset beni yaşa der 

sana sıkıntı veriyorsam da 

şak diye damarını keserler 

her yer kızıl kan 

yeryüzüne çıkmayı bekleyen artezyen 

içinde sen minik bir karaltı 

nokta bile değilken 

melteme bile söz geçirememişken 

sen mi duracaksın engin dağlara göğsünü gererek 

limanları zapt mı edeceksin başka çıkışın yokken 

köprüleri mi uçuracaksın yolların bile patikayken 

açken fırını mı yakacaksın açlığına inat 

sen ne yaptığını bilmeden değil 

sen düşmanını görmeden paçalarını sıvamışken 

günün düş mü gerçek mi olduğunu 

hayal meyal anımsarken 

zamanın elindeki şımarık oyuncaksın sen 

ve içinde kendine labiretler oluştururken 

duvarlarını gökyüzüne uzattığın 

temellerini mağmaya ulaştırırken 

ey garip gerçek 

sen insanoğlu aciz kul 

bil düşmanı ama o seni bilmeden 

sinsice fark ettirmeden saliselerden bile kısa 

insan gibi yaşa duyguların rüzgarında 

ama aklın sağlam halatlarında.', 'içerdesin duvarlarla başbaşa  bir rüzgar eser aniden  nereden geldiğini haber bile vermeden  karmakarışık saçlarınsa  inatla gelir gözlerini...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/karmakarisigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmet Devam Et', 'ahmet-devam-et-ahmet-yozgat-rcmvk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Dağlarda bir küçük çoban

Kırık kavalı yavan yavan ağzında 

İnce ve uzunca çalar benim için:

''Ahmet hey Ahmet! 

Çobanlığa devam et.''

2/:

Tamirhanede bir küçük çırak 

Pervanesi bozuk araç motoru önünde

Çekiç, tokmak ve balyoz ile düzeltir

Düzeltir sırf benim için:

''Ahmet hey Ahmet! 

Çıraklığa devam et.''

3/:

Kasabada bir yaşlı bakkal

Bozuk terazisi önünde 

Kilo kilo tartar benim için:

''Ahmet hey Ahmet! ..

Bakkallığa devam et.''

4/:

İnşaatta bir usta boyacı

Kılı dökük fırçası sağ elinde 

Duvarları boyar benim için:

''Ahmet hey Ahmet! 

Boyacılığa devam et.''

5/:

Dairede bir yaşlı memur

Plastik çerçeveli gözlüğü

Ha düştü ha düşecek gözünden

Ya da kayacak burnunun kemerinden

Rengi solmuş ceketinin ipliği

Sarkıyor kırk yerinden

Bütün deneyimleri benim için:

''Ahmet hey Ahmet! 

Memurluğa veda et.''

6/:

Cami avlusunda bir yaşlı dede  Yetmiş yıllık yaşadıkları ardında 

Puslu önü ise ıpıssız 

Bazen dalıyor uzaklara fersiz gözleri 

Taa altmış yıl öncesine 

Anımsıyor dağlardaki küçük çobanlığını 

Hatta tamirhanedeki çıraklığını 

Sonra bakkaldı bir zamanlar 

Bir aralık inşaatlarda boyacı 

Yaşadıklarını tekrarlar bir bir 

Anımsar acı acı 

Hele o dairedeki memurluk yılları 

Gitmez bir türlü bakışlarının önünden 

İki damla yaş akar 

Yaşlı gözlerinden istemeden

Bir yaşlı dedenin eli kayar omzuma

Bütün tecrübeleri benim için:

''Ahmet hey Ahmet! ” der

“Çocukluğa devam et...''', '1/: Dağlarda bir küçük çoban Kırık kavalı yavan yavan ağzında  İnce ve uzunca çalar benim için: ''Ahmet hey Ahmet!  Çobanlığa devam et.'' 2/: ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ahmet-devam-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Armero', 'kaybolan-armero-altay-taskin-p51on', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizlerden uzaklarda bir ülke Kolombiya,

Şirin bir şehri var Armero, bize yabancı adı,

Evlerinde yaşayan mutlu insanları vardı.

Bir gece, rüyalarında bile görmedikleri

Acı olayla karşı karşıya kalacaklardı.

Bugüne kadar onların bildiği o, cansız bir dağdı,

Dört yüz sene gibi uzun bir zamandan

Beri suskunluğunu korumuş,

Kimsenin aklından geçmiyordu,

Bu dağın canlanıp nice canları yakacağı.

Sıcaklığı ile dağların zirvesindeki buzulları bile

Eritip önüne geleni yakıp yıkarak kilometrelerce ilerleyip

Kızgın lavlarıyla koca bir şehri yutacaktı,

Nevado del Ruiz yanardağı...

Arkasında pençesinin altında binlerce ceset,

Üstünde feryat eden yetim çocuklar, dul kadınlar

Ve kaybolmuş bir şehrin üç-beş ağacı ile üç-beş yapısını bırakıyordu.

Tüm dünya insanlarını canevinden vurmuştu,

İnsanların yapacağı birşey kalmıştı,

Ancak, çamur yığınlarına bulanmış cesetleri çıkarmak,

Hayatta kalanların yaralarını

Ve yaralı yüreklerin acılarını dindirmeğe çalışmak...', 'Bizlerden uzaklarda bir ülke Kolombiya, Şirin bir şehri var Armero, bize yabancı adı, Evlerinde yaşayan mutlu insanları vardı. Bir gece, rüy...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kaybolan-armero-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkım', 'yikim-nuray-acar-vczwm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya süprizleriyle ağlatıyor çoğu zaman 

hangi yaş grubundan olduğunu sorgulamadan 

geriye yığınlarca soğuk anı yüklü taş binalar bırakmışken 

dünyayı öğrenmeye aday cahil yolcularız biz 

han yıkıldı hancı kayıp 

ne yiyecek kaldı ne yatacak kuru bir saman 

yer silkelendi derinden 

ne eser kaldı ne yol ne kervan 

kavga bitti yorgan gitti 

ne oldu ne bitti 

biz cahil kullar öğrenemedi 

dünyanın afetlerdeki öfkesini 

acıyın diyemezsin sen acıdın mı 

suyunu kuruturken kimyasal kuyularında 

ağacını keserken kör baltanın acımasızlığında 

kul olamadık ne bedene ne ruha 

kendi kör umursamazlığımızda 

adam sende boşversene diyen manasızlığımızda', 'Dünya süprizleriyle ağlatıyor çoğu zaman  hangi yaş grubundan olduğunu sorgulamadan  geriye yığınlarca soğuk anı yüklü taş binalar bırakmışk...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yikim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alattin Daldan Dala Uçuyor', 'alattin-daldan-dala-ucuyor-ahmet-yozgat-52f4b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Yedi yaşında daha, 

Uyanamazken sabaha, 

Alattin tamircide açtı gözünü 

''Levye,'' dedi Cabbar usta 

''Kriko, kurbağacık...''

Çırak Alattin bir türlü 

Anlamadı ustasının sözünü.

2/:

Bir eline makas, diğer eline tarak, 

Alattin mahalle berberinde çırak, 

Usta haşin.... Usta huysuz, 

Bir gün saçkıran kaptı Alattin, 

Ertesi gün uyuz. 

3/:

Alattin marangozda çekti tulumu, 

Ustaya lazım olunca rende, 

''Derhal usta, ama... 

Bu mu rende? Yoksa bu mu? ''

4/:

Sonunda okul heyledi Alattin ''i, 

''Bak.'' dedi öğretmen, 

Öğretti A''yı, Be''yi

Seçti mesleğin en iyisini...', '1/: Yedi yaşında daha,  Uyanamazken sabaha,  Alattin tamircide açtı gözünü  ''Levye,'' dedi Cabbar usta  ''Kriko, kurbağacık...'' Çırak Alattin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/alattin-daldan-dala-ucuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Almanya’daki Bizim Çocuk', 'almanya-daki-bizim-cocuk-ahmet-yozgat-t31db', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz Türküz,

Ama aile boyu yaşarız,

Almanya''nın şirin bir kasabasında,

Bura bizim ikinci vatanımız,

Zümrüt ormanlarına,

Dalar gözlerimiz,

Düz ovaları bizi çağırır,

Koşarız koşarız,

Atılırız serin ırmaklarına,

Sayın ki Almanya değil de,

Burası sevgili Türkiyemiz,

Köyleri köylerimiz,

Kentleri kentlerimiz, 

Saçları sarışın olsa da, 

Gözleri olsa da maviş, 

Biz birbirimize benzeriz,

Biz Türküz,

Ama yaşarız, Dik çatılı evlerinde Almanya''nın

İkinci vatanımız burası bizim.', 'Biz Türküz, Ama aile boyu yaşarız, Almanya''nın şirin bir kasabasında, Bura bizim ikinci vatanımız, Zümrüt ormanlarına, Dalar gözlerimiz, Düz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/almanya-daki-bizim-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylin''in Öykücüğü', 'aylin-in-oykucugu-ahmet-yozgat-oqhj3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A/:

Küçük Aylin bir sabah 

Heyecanla fırladı yatağından 

O sırada kasabanın duvarları aktı 

Güneşin doğma zamanı yani

Ufuklar sarışın mı sarışın 

Aylin atınca yorganı üzerinden

Dağlar dağlara baktı 

Dağlar güneşe yataktı

Aylin’in annesi ardındaydı dağların 

Yani buraya çok çok uzaktı. 

B/:

Küçük Aylin bir sabah 

Heyecanla tuttu yolunu dağların 

Yürüdüğü yollar kapalı ve apaktı 

Aylardan zehir gibi bir aralık 

Diz boyu beyazdı toprağı kucaklayan 

Durdu minik Aylin karın ayak ucunda 

Kıvrılan yollara baktı 

Ardındaydı karlı dağların annesi 

Yani buraya çok çok uzaktı.

C/:

Küçük Aylin bir sabah 

Heyecanla aştı koca dağın sırtından 

Bata çıka karlara 

Asılmasa aşağı doğru ayakları 

Küçük kız kanat açıp uçacaktı

Ne tenhaydı çevresi o anda

Ne de görünürde kim kimse vardı

Uzaklarda upuzaklarda

Keskin dişli kurtlar ulumaktaydı

Yüreciği kuş gibi pır pırdı! 

Doğrusu Aylincik çok korkmaktaydı

Annesi ardındaydı karlı dağların 

Yani buraya çok çok uzaktı.

D/:

Küçük Aylin bir sabah 

Heyecanla uzanıp ve yanıp özlemiyle annenin 

O tepe senin... Bu tepe benim 

Bir elinde korkunun hiç sönmeyen ateşi 

Öteki elinde pır pır eden bir yürek 

Şen şakrak türküler söyleyerek 

Upuzaklardaki anneye ulaşacaktı

Oysa doluydu dağların omzu 

Dört bir yan tepeleme kardı

Ardındaydı karlı dağların annesi 

Yani buraya çok çok uzaktı.

E/:

Küçük Aylin bir sabah

Kargalar rüyasından uyanmadan

Sürülmeden daha

Meşe odunu yanan ocağa tarhanalar

Heyecanla özlemini kuşanıp beline

Dağların çağrısına uydu

Sabahtı ama yine de uykuluydu

Akan her yerinden uykuydu

Uysa uyuşukluğuna ayaklarının

Küçük Aylin belki de 

Daha yolun başında donacaktı

Oysa anneciği ardındaydı 

Önündeki bu karlı dağların 

Belki de şuracıktaydı.

F/:

Küçük Aylin bir sabah

Ah, ah! Sormayın

Ne sabahtı o sabah? 

Kopup dumanlı doruklardan

Kocaman bir teker gibi çığ dalgaları

''Bu Aylin''dir, Aylinciktir

Bu mini minicik bir kızdır

Üstelik çok da özlemiştir annesini.'' demedi

Tutup kocaman eliyle ince kolundan

Aktı... Aktı... Aktı...

İndirdi... Taa aşağılara

Ulaştırdı özlemine küçük kızı

Ama küçük kızın kaskatıydı artık 

O mini minnacık bedeni

Annesi dibindeydi çığlı dağların 

Yani şuracıktaydı...', 'A/: Küçük Aylin bir sabah  Heyecanla fırladı yatağından  O sırada kasabanın duvarları aktı  Güneşin doğma zamanı yani Ufuklar sarışın mı sar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/aylin-in-oykucugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-muammer-erturan-6q18u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar çok şey

yarım kalacak

ne kadar çok iş 

bitmemiş...

Ne kadar çok şey

ne kadar çok iş 

başlamadan bitivermiş...

Yeniden başlayabilsem

diyeceksin,

çok farklı olurdu kesin...

Herkesin dediğinden

farklı birşey

dermiş gibi sanki...

(26 Haziran ''99)', 'Ne kadar çok şey yarım kalacak ne kadar çok iş  bitmemiş... Ne kadar çok şey ne kadar çok iş  başlamadan bitivermiş... Yeniden başlayabilsem...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sanki-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berber Kekliğinoğlu’nun Şiiri', 'berber-kekliginoglu-nun-siiri-ahmet-yozgat-inr5i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ne zaman dökülse saçlarımız, 

Kara kalem kaşlarımızın üstüne, 

Hepimizin aklına, 

Berber Kekliğinoğlu gelirdi.

Bir elinde sivri ve paslı makas, 

Öbür elinde plastik tarak, 

Eğilecek saçlar üstüne mırıldanarak.

2/:

Ne zaman sarksa saçlarımız, 

''Merhaba! '' berber Kekliğinoğlu amcamız.

Ne zaman kapansa kulaklarımız Ucu kıvrık zülfümüz yürüse,

Yanaklarımızın üstüne usulca.

Doğruca,

Gideriz berber Kekliğinoğlu''a.

Önümüzde camı kırık bir ayna,

Bir Üsküdar akşamı pusluca,

Bir dalgalı deniz manzarası...

Sağ elinde ucu kırık makası,

Öbür elinde mavi plastik tarak,

Ha dokundu ha dokunacak saçlarımıza,

Kediler gibi mırıldanarak.

Ne zaman ensemizde lülelerimiz uzasa, 

Yolumuz yine düşecek berber Kekliğinoğlu''a.', '1/: Ne zaman dökülse saçlarımız,  Kara kalem kaşlarımızın üstüne,  Hepimizin aklına,  Berber Kekliğinoğlu gelirdi. Bir elinde sivri ve paslı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/berber-kekliginoglu-nun-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berber Süslü', 'berber-suslu-ahmet-yozgat-bf12t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Peyik pazarındaki süslü berber 

Çevredeki herkesi süsler

Ancak tıraş edemez kendini 

Derbeder mi derbeder.

2/:

Peyik pazarındaki süslü berber 

Çevredeki herkese kahkül döker

Herkes ona gelir tıraş için

Süslü berber herkesi süsler

Ama tıraş edemez kendini.

3/:

Peyik pazarındaki süslü berber 

Bir başka şehre gider

Arkadaşı bir başka berbere 

Uzayan saçlarını kestirmeye.', '1/: Peyik pazarındaki süslü berber  Çevredeki herkesi süsler Ancak tıraş edemez kendini  Derbeder mi derbeder. 2/: Peyik pazarındaki süslü b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/berber-suslu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çırağın Şikayeti', 'bir-ciragin-sikayeti-ahmet-yozgat-nh0oa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Çırağım kasabanın sanayi sitesinde 

Oto tamircisinin birinde

Oraya girdiğimde boyum bir karış

Yaşım daha yediydi

Şimdi yaşım on dörde girdi

Ama boyum bir karış hala

Üzülsem de yararsız 

Durumum böyle diye

Her anahtarı kafama yediğimde

Her şeyi yeniden anımsarım

Örneğin, ustamın adı Hıdır 

Bilekleri nah böyle 

Göğsü orman gibi kıllıdır.

2/:

Daha kasım ayında başlarım 

Ta ciğerden ve kötü kötü öksürmeye 

Bütün kış akar burnum

Nezle benim kardeşim

Gripse sürekli taşıdığım gururum

Basit bir çırağım ya ben! 

Değmem hastaneye götürülmeye

Her tokmağı kafama yediğimde

Her şeyi yeniden hatırlarım 

Mesela, ustamın adı Hıdır 

Bilekleri nah böyle 

Elleri nasırlı nasırlıdır.', '1/: Çırağım kasabanın sanayi sitesinde  Oto tamircisinin birinde Oraya girdiğimde boyum bir karış Yaşım daha yediydi Şimdi yaşım on dörde gi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-ciragin-sikayeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Köyde bir Minik Kız', 'bizim-koyde-bir-minik-kiz-ahmet-yozgat-xr7fb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Bizim köyde bir minik kız...

Gözleri sanki sarı ışıklı yıldız.

Belki adı Merve,

Adı belki Kamile,

Adı Saniye belki de, 

Adı Sonay.

Yusyuvarlak bir yüzü var

Sanki ağustos gecelerinde dolunay.

2/:

Bizim evde bir minik kız...

Gözleri güler ta dipten dibe

Körebe oynar dedesiyle. Belki adı Havva,

Adı belki Ayşe,

Adı Zühal belki de, 

Adı Nadide.

Sorar en uygun zamanda:

''Baba okul ne nerede? ''

3/:

Bizim okulda bir minik kız...

Maharetli elleri ufacık tefecik.

Derste şarkı mırıldanıp

Paydosta türkü söyler.

Marş okur bayramlarda.

Belki adı Canan,

Adı belki Fadime,

Adı Elif belki, 

Adı Şekercik.

Sesi sanki ipek gibi incecik:

''Cik cik de cik cik! ''', '1/: Bizim köyde bir minik kız... Gözleri sanki sarı ışıklı yıldız. Belki adı Merve, Adı belki Kamile, Adı Saniye belki de,  Adı Sonay. Yusyu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bizim-koyde-bir-minik-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Köylüler', 'biz-koyluler-ahmet-yozgat-a5gi8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Biz köylüler

Yani sizin köylüler,

Saf oluruz birazcık.

Yazın çatısız damlarda yatarız hepimiz,

Kimimiz uykusunda gezer gece yarısı

Bu yüzden sık sık yuvarlanırız

Saçaklardan iki adam boyu aşağı.

Kah kolumuzu, kah bacağımızı kırarız

Plastik ciklet nedir bilmeyiz,

Yaz ayları kengerdir bizim sakızımız:

''Cık cık da cık cık! ...''

Yani saf oluruz birazcık.

2/:

Biz köylüler

Yani sizin köylüler,

Sakar oluruz birazcık.

''Vur.'' deyince öldürürüz sağlamı,

Ateşi söndürürüz ''Üfle.'' deyince

Az buz değiliz çorak tarlalarda,

Ticarette ise hiç mi hiç uz değiliz,

Aha bundan katar katarız dağlarda,

Şehirlerde bir elin parmağı kadarız.

Otomobil nedir bilmeyiz

Bizim taşıtlarımız rahvan atlarımız:

''Cık cık da cık cık! ...''

Yani sakar oluruz birazcık.

3/:

Biz köylüler

Yani sizin köylüler,

Açıkgöz oluruz birazcık.

Çabuk dolsun diye güğümlerimiz

Sarıkızın sütüne kaynak suyu katarız

Batarız durduk yerde diken gibi

Bütün sevmediklerimizin kaba etine

''Çayımıza küp şeker alalım.'' diye,

Çift sarılı yumurtayı kendimiz yemez

Pazarda ölmüş eşek fiyatına satarız.

''Ak,'' dediğimize ''Kara,'' der ama

''Nuh,'' der, ''Peygamber,'' demeyiz.

''Cık cık da cık cık! ...''

Yani açıkgöz oluruz birazcık.

4/:

Biz köylüler

Yani sizin köylüler,

İnat oluruz birazcık.

Az gideriz, ''Çok git.'' denilen yere

''Gitme.'' denilen yere ise uz gideriz,

Deveden önce atlarız hendekten

''Aman ha! '' demeden dalarız

Delidolu derelerin ortasına

Bin batman yük vururuz 

Zavallı kocamış merkeplerin arkasına

Gelince coşkun çayın ortasına

Taban direr saatlerce kalırız

Sakinleşince ortalık, nedense

Tozu dumana katarız.

Parmak ısırtırız herkese

''Cık cık da cık cık! ...''

Yani inatçı oluruz birazcık.', '1/: Biz köylüler Yani sizin köylüler, Saf oluruz birazcık. Yazın çatısız damlarda yatarız hepimiz, Kimimiz uykusunda gezer gece yarısı Bu yü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/biz-koyluler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boyacı Nurettin', 'boyaci-nurettin-ahmet-yozgat-4kx7l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Taa yıllar önce, şu kadarcıktı.

Bizim mahallenin boyacısı Nurettin,

Her sabah, tin tin tin! 

Babasının arkasından giderdi atölyeye.

2/:

Evlerinde babaydı koca Hıdır.

Boya atölyesinde ise sinirli usta.

Ne kadar bildiği varsa,

Boya, boyacılık ve badana üstüne,

Öğretirdi çırağı Nurettin''e.

3/:

Günlerden bir gün geldi,

Emekli oldu boyacı Hıdır usta.

Artık usta Nurettin boyuyor evleri.

Üstüne yok bu hususta...', '1/: Taa yıllar önce, şu kadarcıktı. Bizim mahallenin boyacısı Nurettin, Her sabah, tin tin tin!  Babasının arkasından giderdi atölyeye. 2/: ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/boyaci-nurettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor SEVDAM', 'mor-sevdam-munevver-erilmez-q4yb6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mor sevdalarımda buldum seni

Lâlede, menekşede, gülde

İstanbul-Antalya yolunda

Tarlalarda, gelincikte, sarmaşıkta

Yarışıyordu bayrak, bayrak

Mor Sevdalım; 

Salonumun duvarlarında

Kırmızı gelinciğe inat

Ben de varım diyordu

Sevdalım, Morum, Sarım, Çiçeğim

Neredesin Sevdiceğim

Güneş açtı, yağmura inat

Gökyüzü masmavi, 

Şimşekler çaksa da

Deniz çağırıyor bizi,

Uslu bir çocuk gibi.

Mor Sevdamı,

Bırakıp gidemedim.

Sana,

Seni nasıl sevdiğimi,

Söyleyemedim.

Mor Sevdalardan ırak,

Bir hayat düşünemedim 

Created by Crazyprofile.com', 'Mor sevdalarımda buldum seni Lâlede, menekşede, gülde İstanbul-Antalya yolunda Tarlalarda, gelincikte, sarmaşıkta Yarışıyordu bayrak, bayrak...', ARRAY['Türk Edebiyatı','Şiir','Münevver Erilmez']::text[], 8.5, '{"poet":"Münevver Erilmez","poet_slug":"munevver-erilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mor-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın Kimse Olmasın Selamım Dosta Ulaşsın', 'varsin-kimse-olmasin-selamim-dosta-ulassin-nuray-acar-bd8py', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir selam almaktı amacım 

tuşlara dokununca ki heyecanım 

önce adımı yazdım dikkatle 

bir dost gelipte bulamaz ise, 

ne derim diye 

kapıda bırakmak adet değil bizde 

ev sahibinden daha kıymetlidir diye 

Yanlızlık kor gibi serde olunca 

dostluk kor gibi canda olunca 

her ne hikmetse 

bilinmez isede 

Sırlı bir dünya şu elde 

ben söyler ben dinlerim 

belki biraz sitem eylerim 

şiir benim ne haddime 

ben dost bir yürek beklerim. 

adını nuray diyip 

gülümseyin 

bir çift gözü izleyin 

gülümseyen yüzüme bakıyor gibi 

uzaklara bir selam eyleyin', 'Bir selam almaktı amacım  tuşlara dokununca ki heyecanım  önce adımı yazdım dikkatle  bir dost gelipte bulamaz ise,  ne derim diye  kapıda b...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/varsin-kimse-olmasin-selamim-dosta-ulassin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyürler Bizim Çocuklar', 'buyurler-bizim-cocuklar-ahmet-yozgat-fnbyq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'L/: Ağlayarak doğar bizim çocuklar 

Saklambaç oynayarak büyürler Gümüşi gölgeleri düşer 

Yanakları üstüne uzun kirpiklerinin

Bakarlar yıldızlar gibi ışıl ışıl 

Gökyüzünde maviye ve güneşteki sarıya

Kimsenin görmediğini görürler 

Duyarlar hiçbir kulağın duymadığını

Ağlayarak doğarlar bizim çocuklar 

Körebe oynayarak büyürler.

2/:

Yağmurlarda kalmış oğlaklar gibi 

İlk baharda ıslak doğar çocuklar 

Temmuz sıcağında kuruyarak büyürler

Elleri yumucuk ama bereketli

Kocaman bir harman yeri kadar Ağustosla burun buruna ayakları 

Hırsla kavrar çatlayan toprakları

Bir yaramaz güneş yakar onları

Çorak eylül gibi kokar bahtları

Ipıslak doğarlar bizim çocuklar  Büyürler kuruyarak.

3/:

Dünyadan habersiz doğar çocuklar 

Yaşamı öğrenerek büyürler

Bilmezler ateşin ''cıs'' 

Suyun boğucu olduğunu Her adımda yeniden tanırlar hayatı

Beyinlerinin gizemini keşfederler

Yumuk ellerini, minik ayaklarını Yani kocaman yüreklerini Veya içlerinde saklanan kendilerini

Ve her dokunuşta eşyayı tanırlar

Habersiz doğar bizim çocuklar 

Öğrenerek büyürler.

4/:

Çevrelerini sevindirerek doğar çocuklar

Büyüklerini üzerek büyürler

Düğünde, bayramda sevinci 

Savaşta, ölümde tasayı 

Yaşamdaki tüm acıyı öğrenirler

Yorgunluğu her yokuşta 

Karanlık geceyi aydınlık gündüz içinde

Geçimde dert denilen şeyi

Kendisine gereken her nesneyi

Heceyi, sözcüğü ve tümceyi

Çevresinde pervane olan herkesi

Sevindirerek doğar çocuklar

Üzerek büyürler büyüklerini.

İki Boyacı Kardeşin Şiiri

I/:

İki kardeş boyacıyız

Kentin en kenar mahallesinde

Ve o mahallenin en yoksul evinde

Bir ben ağabey olarak

Bir de küçük kardeşim Veli

İkimiz geçindiririz evimizi

Ben boya sandığını taşırım 

Kardeşim Veli küçük daha 

O taşır teneke oturağı ancak.

II/:

Ayakkabı boyasının hasını

Cilanın en badem yağlısını

Kullanırız yıllardan beri

Müşterinin en iyisini 

Ben ayağından tanırım da 

Kardeşim Veli küçük daha 

O tanıyamaz kim, kimdir? 

Kim bahşiş verir? 

Kim inkar eder vereceğini? 

III/:

Ben bazen uzanırım Cebeci''ye 

Hatta Yenişehir istasyonuna 

Gecekondular semti Mamak''a 

Kentin ortasındaki kalabalık Kızılay''a

Hatta Gençlik Parkına

Kardeşim Veli küçük daha 

Ancak takılabilir bizim sokağa.

IIII/:

''Parlamazsa para yok bizde.'' diyerek

Geçim teknemiz bir elimizde

Öbür elimizde ise 

Boyayıp fırıncının pabuçlarını 

Parasız aldığımız yanık ekmek

Kuğulu parka ineriz her pazar

Ekmek teknemiz bir elimizde

Öbür elimizde ise 

Boyayıp simitçinin pabuçlarını

Beleşe aldığımız simitin artık gevreği

Bir küçük kardeşim Veli ısırır ucundan 

Bir ben onun ağabeyi olarak

Bir küçük kardeşim Veli... 

Bir de ben azar azar...

Kardeşim Veli küçük daha

Yeter ona bu simitin çeyreği.', 'L/: Ağlayarak doğar bizim çocuklar  Saklambaç oynayarak büyürler Gümüşi gölgeleri düşer  Yanakları üstüne uzun kirpiklerinin Bakarlar yıldız...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/buyurler-bizim-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cabbar Emmimizin Kısa Öyküsü', 'cabbar-emmimizin-kisa-oykusu-ahmet-yozgat-l1ld4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

“Cabbar emmi,” derdik ona biz.

O yaşadıklarıyla sanki bir deniz.

Sırtındaki eski paltosu

Ardındaki yavuz köpeği ile

Yıllar sonraki kendimiziz.

2/:

“Cabbar emmi,” derdik ona biz.

Görseniz siz de beğenirsiniz.

Enliydi elleri bir yaba gibi 

Sopası kalın ve gürgendendi.

Bir günden bir güne

O bize ''of” bile demedi.

3/:

“Cabbar emmi,” derdik ona biz.

Susardı hep, hakaret bile etseniz.

Sevgi sızardı göz pınarlarından.

Yanakları sevinçten gerilirdi.

4/:

“Cabbar emmi,” derdik ona biz.

Tanısanız eminim siz de severdiniz.

Damlara karların yığıldığı bir kış günü

Elleri ayaz, bıyıkları buzdu.

Donduğunda yaşı ya otuz dokuz 

Ya da kırk dokuzdu.', '1/: “Cabbar emmi,” derdik ona biz. O yaşadıklarıyla sanki bir deniz. Sırtındaki eski paltosu Ardındaki yavuz köpeği ile Yıllar sonraki kendi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cabbar-emmimizin-kisa-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemal Dayının Çiçekleri', 'cemal-dayinin-cicekleri-ahmet-yozgat-ox0iu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Her gün aynı saatte 

Cemal dayı geçer gider: 

Giderken ''Tak tak tak! '' eder

Tanırız onu sesinden 

''Gör bizi Cemal dayı 

Eğil bir de bize bak.'' 

2/:

Cemal dayının ayakları 

Bazen basar üstümüze  Kırılır orta yerinden belimiz 

Biz yol kıyısında yer tutan

Tohumsuz, susuz ve gübresiz 

Yani kendi kendine 

Büyüyen kimsesiz çiçekleriz

3/:

Cemal dayı su taşır 

Meydandaki çeşmeden eve 

Taşır döke döke 

Hele bir de kovası delikse 

Değmeyin keyfimize 

Kana kana içeriz 

Biz yol üstünde

Tohumsuz ve gübresiz 

Büyüyen yoksul çiçekleriz', '1/: Her gün aynı saatte  Cemal dayı geçer gider:  Giderken ''Tak tak tak! '' eder Tanırız onu sesinden  ''Gör bizi Cemal dayı  Eğil bir de bize...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cemal-dayinin-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-nuray-acar-tpjtz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaz kalemle kağıda 

beyazlıkları şifrelercesine 

kömür tozuna sıvaşan parmak aralarında 

düz bir zemin bulduğunda 

bileklerine ağrılar girercesine 

illaki iz bırakacaksan 

yaz 

yaz güneşin sıcağında 

ter içinde tuz kristalleri 

buharlaşan aklının oyunlarında 

buz gibi suyu düşle 

bedenin geceye hasret 

yaz', 'yaz kalemle kağıda  beyazlıkları şifrelercesine  kömür tozuna sıvaşan parmak aralarında  düz bir zemin bulduğunda  bileklerine ağrılar girer...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaz-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevat Ağabeyin Bakkaliyesi', 'cevat-agabeyin-bakkaliyesi-ahmet-yozgat-hdbkg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Bereket bakkaliyesiyim 

Kasabanın Demir ağabeyinin

Açılırım her sabah erkenden 

Kapanmam akşama kadar.

2/:

Siftah yapanım emekli Üzeyir amca

Okumuş adam olur kendisi

Kedisi, köpeği bile kültür zengini

Sabahleyin ilk gazeteyi

Okumadan rahat edemez

Gidemez evine haberleri öğrenmeden.

3/:

Dedim ya bereket bakkaliyesiyim 

Kasabanın Demir ağabeyinin

Açılırım her sabah erkenden 

Kargalar ''gak! '' demeden

Ev hanımı Pembe teyze

Mahmur gözlerini süze süze

Atar ikinci adımı içeri

Onun tek derdi

Ekmeğin en sıcağını almak

Demir ağabeyin görevi de

Hizmetin en iyisini sunmak tabii ki

Dedim ya bereket bakkaliyesiyim ben

Bu yüzden ekmeğin en çıtırını satarım.

3/:

Şen bakkaliyesiyim 

Kasabanın Demir ağabeyinin

Açılırım her sabah erkenden 

Sepetini sarkıtır tepemden ablam Halime 

Altı ıslak bebesine bez ister

Bebesi Elifcik yesin diye

Taze süt ve süzme bal ister.

4/:

Tek bakkaliyesiyim 

Kasabanın Demir ağabeyinin

Sayın ki sizden biriyim 

Çırak Selami açar kapımı erkenden

Kapanmam ta geceye dek

Şükür iyidir işlerim 

Arı kovanı gibiyim

Vızır vızır işlerim.', '1/: Bereket bakkaliyesiyim  Kasabanın Demir ağabeyinin Açılırım her sabah erkenden  Kapanmam akşama kadar. 2/: Siftah yapanım emekli Üzeyir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/cevat-agabeyin-bakkaliyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Bizim Sıvacı Ustaları', 'su-bizim-sivaci-ustalari-ahmet-yozgat-6scbo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Biz birer sıvacı ustasıyız

Yapayalnız yatarız geceleri inşaatlarda

Çok uzaklardayız sevdiklerimizden

Sıcak olsun diye evleriniz 

Yıl boyu duvarlarınızı sıvarız

Soğuk tuğlalara siner kokumuz.

2/:

Biz birer sıvacı ustasıyız

Aylar var ki uzağız köyümüzden

Ama sağlam olsun diye sizin yerleriniz 

Nasırlı ve kocaman ellerimiz

Yirmi kat aşağıda harç karar da 

Denizlerin kabuklu kumundan 

Fabrikaların betonundan

Sırtımızda yukarı çıkarırız.

3/:

Biz birer sıvacı ustasıyız

Aylar var ki uzağız evimizden

Ama sağlam olsun diye sizin evleriniz 

Duvarlarınıza çimentodan nakış dökeriz

Sıcacık olsun diye kışın evleriniz

Size emeğimizi hediye ederiz.

4/:

Biz birer sıvacı ustasıyız

Aylar var ki yalnız ve uzağız elimizden

Ama sıcak olsun diye sizin evleriniz 

Yüreğimizden harç karıp 

Duvarlarınıza sevgimizi sıvarız.', '1/: Biz birer sıvacı ustasıyız Yapayalnız yatarız geceleri inşaatlarda Çok uzaklardayız sevdiklerimizden Sıcak olsun diye evleriniz  Yıl boy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/su-bizim-sivaci-ustalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiftçi Ve Oğullarının Şiiri', 'ciftci-ve-ogullarinin-siiri-ahmet-yozgat-yez90', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bizim köylü yaşlı çiftçinin böğrüne, 

Saplanınca dayanılmaz bir ağrı, 

Bıraktı babasından kalan karasabanı. 

Çözdü yarı yaşlı yorgun atlarını, 

Dört çekerli tahta arabasından

Demir dirgen ve tahta yabadan

Elini eteğini çekti

Bizim köylü yaşlı çiftçi

Galiba buradan gidecekti. 

2/:

Çevresine çağırdı oğullarını, 

Bostan boruk ekili bahçeden, 

Üzüm koruk dikili bağdan, 

Ve verimsiz çorak tarladan.

Daha durumunu yaban yad duymadan

Gideceğini bu dünyadan.

Vasiyetini söyleyecekti.

3/:

Yaşlı çiftçinin çevresini, 

Sarınca izbandut gibi oğulları. 

Yükseltti hasta adam cılız sesini, 

Usul usul dedi ki: ''Vasiyetim, 

Sakın ha bozmayın birliğinizi, 

Tıpkı ben ölmemişim gibi.''

Sonra göründü yaşamın dibi

Göçtü bu dünyadan yaşlı çiftçi

Geldiği ilk gün ki gibi.', '1/: Bizim köylü yaşlı çiftçinin böğrüne,  Saplanınca dayanılmaz bir ağrı,  Bıraktı babasından kalan karasabanı.  Çözdü yarı yaşlı yorgun atl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ciftci-ve-ogullarinin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Olasım Gelir', 'cocuk-olasim-gelir-ahmet-yozgat-vej3y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Sıkıldığım anlar olur

Yaşımdan ve yaşadığımdan.

Bazen kaçıp buralardan 

Köyüme dönesim gelir.

Bırakıp olgun yaşımı 

Çocuk olasım gelir.

2/:

Ak saçlı adamlara 

''Amca,'' diyesim gelir.

Kesip manavdan almayı

Bağlardan yolasım gelir.

Cayıp olgunlaşmaktan 

Çocuk olasım gelir.

3/:

Silip gerçek hayatı 

Rüyaya dolasım gelir.

Açıp hapsolduğum kafesi 

Kendimi salasım gelir.

Vazgeçip yaşlanmaktan 

Bebek olasım gelir.', '1/: Sıkıldığım anlar olur Yaşımdan ve yaşadığımdan. Bazen kaçıp buralardan  Köyüme dönesim gelir. Bırakıp olgun yaşımı  Çocuk olasım gelir. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cocuk-olasim-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gececi Dursun ağabey', 'gececi-dursun-agabey-ahmet-yozgat-l6tws', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Mahmur gözünü açınca solgun gece

Ben ona bakarım kocaman kocaman

O bana miniminnacık gülümser

Sonra da Dursun ağabey işine gider.

Doksan dokuz merdivenli apartman gibi

Kat kat yükselmiş bir sefer tasıyla.

Lap lap basarak azman ayaklarını

Uykulu ve soğuk kaldırımlara...

2/:

Mahmur gözünü açınca yorgun gece

Bizim mahalleli Dursun ağabey

O kocaman elleriyle kavrar gündüzü.

Gözleri kocaman ve çakmak çakmak

İlk işi bana göz kırpmak...

Bir erkenci Dursun ağabey,

Bir de karşı evin bacasındaki leylek,

Bir de ben tabii ki...

Kargalardan daha erkenden

Üçümüz de ayaktayız.

Birbirimize gülümseyerek

Kutlamaktayız kendimizi.

3/:

Mahmur gözünü açınca ağaran gece

Ben alelacele cama çıkarım,

Hacı leylek amca isli bacaya...

Beş katlı sefer tasıyla

Lappadanak lappadanak basarak

Uykulu uykulu gerneşen sokaklara,

Sanayideki işine gider

Hepimizin sevgili ağabeyi Dursun.

Gözleri yanar çakmak çakmak...

İlk işi kınalı gagalı leylek ablaya

''Yesin.'' diye yem atmak

Tabii ki göz ucuyla bana bakmak.', '1/: Mahmur gözünü açınca solgun gece Ben ona bakarım kocaman kocaman O bana miniminnacık gülümser Sonra da Dursun ağabey işine gider. Doksan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gececi-dursun-agabey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihin Beldesi', 'tarihin-beldesi-altay-taskin-lhq95', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nice destanlara ismin yazılmış

Armağanların olmuş her kıtaya

Şerefine ağır toplar dökülmüş

Sızlanmış yürekler senin aşkına

Dünya senin için hayaller kurmuş

Sana sahip çıkmak isteyenler de

Beyaz kefenlere birbir dürülmüş

Şanına yaraşmaz başka ellerde

Olmak, toprağına adım attırmak

Tarih oluk oluk kanlar akıtmış

Geride kalanlar sana yetişmek

İçin, dar adımlarını açmışlar

Ama yetişemezler yerin yüksek

İşlemeli saraylarının şanı

Göğe erişmiş zarif minareler

Yaşatmak ve yaşamanın üçlüsü

Toprak su hava seninle elele

Etrafın yedi tepen gülzar dolu

Bir yanda Silivri bir yanda Şile

Sensin her gece milyonların düşü

İzinden çok insanlar faydalanmış

İster hasta ister mutlu olanlar

İyiliklerin unutulmaz olmuş

Tarihi açıp kapatan kapılar

Avrupa ve Asya selama durmuş

Dünya beldelerinin altın tacı

Yer ve gök şahidin senin en içten

Şu eserlerin ebedi kalıcı

Tanımadık senin gibi yücelen

Taşın toprağın cana can katıcı', 'Nice destanlara ismin yazılmış Armağanların olmuş her kıtaya Şerefine ağır toplar dökülmüş Sızlanmış yürekler senin aşkına Dünya senin için ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tarihin-beldesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genceli Atlı Çerçi', 'genceli-atli-cerci-ahmet-yozgat-qca6v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I/:

Eski bir haritada yer tutan noktaleyin

Kışın dağlarında azgın kurtları uluyan

O uzak köylerin birinde

Ele avuca sığmayan

Bir avuç çocuktuk biz.

Saplı samanlı harmanlarda toplanırdık

Gün boyu aşık oynamaktı işimiz.

Hepimiz ne meşin topu tanırdık,

Ne de toparlak cam bilyelerimiz vardı.

Yani oyuncak yoksulu bir avuç boncuktuk.

Ama yine de oyundan oyuna uçtuk.

Iı/:

Biz ne zaman ki,

Onu tanıdık,

Hayatımız bir şenlendi,

Bir şenlendi ki sormayın...

O bir atlı çerçiydi.

Adı ismail''di onun

Ama Genceli''ydi lakabı. 

Iıı/:

Ağustosta güneşli bir günde, 

Geliverdi yavan köyümüze Genceli.

Konup en orta meydanımıza, 

Dikip mavi gözlerini gözlerimize, 

İleri uzatıp kemikli elini 

Dedi ki: ''Açıl çuvalım açıl! 

Ve saçılın içindekiler dört bir tarafa! ''

Iııı/:

Gerçekten açıldı o tılsımlı çuval

Biz bakarken aval aval.

Çuvalın içindenden çıktı

Envai çeşit nesne.

Uçtu ulaştı herkese.

Gün doğdu yoksul ellerimize.

Iıııı/:

Çerçi Genceli İsmaik sayesinde

Meşin top girdi hayatımıza 

Renk renk camdan bilyeler girdi

Plastik bebek, naylon cıngırdak,

Kaynana zırıltısı, balon gürültüsü,

Dilli düdük, dilsiz kaval....

Yani biz olanlara bakarken aval aval

Oyuncak katarları geçti hayatımızdan 

Haberdar olduk ilk kez 

Sihirli masal kitaplarından.', 'I/: Eski bir haritada yer tutan noktaleyin Kışın dağlarında azgın kurtları uluyan O uzak köylerin birinde Ele avuca sığmayan Bir avuç çocukt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/genceli-atli-cerci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-munevver-erilmez-isu2a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle hasretim ki gülen yüzlere

Doğru sözlere,çalan sazlara

Riyasız,yalansız  Bakan GÖZLERE', 'Öyle hasretim ki gülen yüzlere Doğru sözlere,çalan sazlara Riyasız,yalansız  Bakan GÖZLERE...', ARRAY['Türk Edebiyatı','Şiir','Münevver Erilmez']::text[], 8.5, '{"poet":"Münevver Erilmez","poet_slug":"munevver-erilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hasret-333-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümser, Hep Gülümserdi', 'gulumser-hep-gulumserdi-ahmet-yozgat-71byw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Her sabah erkenden çıkardı,

Geçtiğim yolların kıyıcığına.

Minik bir gülücük taşırdı,

Pembe ve küçük ağzının kenarında.

Gök yüzü gibi maviydi gözleri.

Adı Gülümser''di.

Gülümser, hep gülümserdi.

2/:

Her sabah o da benim gibi 

Giderdi atölyedeki işine.

Kınalı elini anacığına sallardı.

Elma gibi yanakları top top...

Hop hop ederdi yüreciği.

Okşanmaya hazırdı küçük elleri.

Adı Gülümser''di.

Gülümser, hep gülümserdi.', '1/: Her sabah erkenden çıkardı, Geçtiğim yolların kıyıcığına. Minik bir gülücük taşırdı, Pembe ve küçük ağzının kenarında. Gök yüzü gibi mav...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gulumser-hep-gulumserdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe de Yol Gider', 'gunese-de-yol-gider-ahmet-yozgat-6ucot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bizim küçük Mustafa,

Kahvaltıda kereviz yer,

Ispanak ise en yakın arkadaşı.

Güçlü ki devler kadar. ''Hop,'' der kaldırır her taşı.

2/:

Bizim küçük Mustafa,

Bir gün, bir yolun başında durur

Elinde o yolun haritası...

Sırtında meşin çantası,

Yüreğinde yemyeşil umuduyla,

Çıkar güneşe yolculuğa.

3/:

Bizim küçük Mustafa,

Ayağında çift tekerli kaydırağı,

Elinde o yolun haritasıyla,

Bulutlarda bulur bir keçi yolu

Keyfine yok diyecek

Sürer güneşe yolculuğu.', '1/: Bizim küçük Mustafa, Kahvaltıda kereviz yer, Ispanak ise en yakın arkadaşı. Güçlü ki devler kadar. ''Hop,'' der kaldırır her taşı. 2/: Biz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gunese-de-yol-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeseydin Bilirdim', 'sevmeseydin-bilirdim-yusuf-onder-bahceci-dqe6j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni seven kâlbim hep senle meşgul,

Sen beni sevmeseydin, bunu bilirdim,

O güzel gözlerin, gözlerimin önünde,

Sen beni sevmeseydin bunu bilirdim.

Kâlpten kâlbe bir yol var gider derler,

Sevenler birbirlerini kalpten severler,

Şartlar müsait olmaz ki, bunu bilirler,

Sen beni sevmeseydin bunu bilirdim.

Vallahi büyü yapmışlar biliyorum ben,

Ne yapayım, birşey gelmez elimden,

İşte böyle şiirler yazarım, kâlbimden,

Sen beni sevmeseydin bunu bilirdim. 

Beddua etmiyor seni terketmiyorum,

Seni öyle sevdim ki hep bekliyorum,

Bir punduna getirirsem de biliyorum,

Sen beni sevmeseydin bunu bilirdim...', 'Seni seven kâlbim hep senle meşgul, Sen beni sevmeseydin, bunu bilirdim, O güzel gözlerin, gözlerimin önünde, Sen beni sevmeseydin bunu bili...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmeseydin-bilirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halaya Duran Kızlar', 'halaya-duran-kizlar-ahmet-yozgat-04z34', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Köy meydanında, davuluna vuranda,

Aşağı köyden davulcu Haydar.

Bizi de alın aranıza,

Halaya duran kızlar.

Seyre çıksın cümle yıldızlar.

Tepiklerimizin altında toprak sarsılsın,

göğe kalksın bin batman toz...

2/:

Haydar da Haydar hani,

Davulu has koyun derisinden.

Koluna dolanan kaytanı kayış,

Düğün evine varış

Sanki gürültülü göğe tırmanış.

Haydar’ın tokmağı demirden

Bir vurdu mu “Güm! ” diye

Kıvılcım sıçrar her yerinden. Salkım kahküllü kızlar,

Alın aranıza,

halayınıza bizi de katın...

3/:

Nerede düğün, Haydar orada.

Sıra sıra kızlar köyün ortasında.

Oğlanlar katmer katmer dam başlarında.

Büyük, küçük demeden,

Herkes durur halayın halkasına.

Aşağı köyden davulcu Haydar,

Demir gibi tokmağını vuranda davuluna

Halaya duran kızlar,

Bizi de alın aranıza.

3/:

Haydar da Haydar doğrusu,

Yok üstüne bir daha.

''Dum dum dum! '' deyince davulu,

Bağırır delikanlılar:

''Ha ha ha! ...''

Sanki bağırır bütün dünya:

''Ha ha ha! ...''

Hele hey, ha bir daha! 

Çekelim ağırlama...”', '1/: Köy meydanında, davuluna vuranda, Aşağı köyden davulcu Haydar. Bizi de alın aranıza, Halaya duran kızlar. Seyre çıksın cümle yıldızlar. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/halaya-duran-kizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hans İle Hasan', 'hans-i-le-hasan-ahmet-yozgat-u2zbd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hans''ın saçı sarı, cildi apak,

Burnu kırmızı ve koskoca.

Uyanır sabah erkenden. 

Dua eder uzunca,', 'Hans''ın saçı sarı, cildi apak, Burnu kırmızı ve koskoca. Uyanır sabah erkenden.  Dua eder uzunca,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hans-ile-hasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönerci Yozgatlı Mustafa', 'donerci-yozgatli-mustafa-ahmet-yozgat-yayll', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Hey! 

Mustafa ağabey, 

Kes bir döner, pilav üstü; 

Mustafa''nın yerinde tüm gençler ayaküstü...

Dönerci Mustafa usta biler palasını,

Üstüne yok bu hususta, 

Helal ettirir parasını... 

2/:

Say ki İstanbul''da bir köşe başı, 

Mustafa ağabeyin dönerci dükkanı, 

çatıktır kara kaşı, bıyığı kaytandır onun, 

Çalışır ocak başında, 

Terine karışır kanı... 

3/:

Mustafa''nn yeri aynalı,

Tezgahı has gürgenden, 

Erkenden dolar insanlar, 

Kimi Sivaslı, kimi Konyalı,

Gurbet elde mekan tutar...

4/:

Mustafa horlanmaya inat, 

Maşallah asar girişe, 

Başladı mı işe, 

Kolaylaşır zorluğuna rağmen, 

Dinine yandığım hayat... 

5/:

Mustafa döner... Döner tezgah, 

Memleket burnuna tüter, 

Yozgat’taki köyde olmak vardı şimdi, 

Ah... Ah! ...', '1/: Hey!  Mustafa ağabey,  Kes bir döner, pilav üstü;  Mustafa''nın yerinde tüm gençler ayaküstü... Dönerci Mustafa usta biler palasını, Üstü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/donerci-yozgatli-mustafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatı Beleş Oğlanın Şiiri', 'hayati-beles-oglanin-siiri-ahmet-yozgat-yxjp5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

A oğlan, keleş oğlan! 

Kaf elinde sihirbaza çırak oldun,

Ama usta medyum olamadın.

Limanda hamallara yoldaş oldun,

Ama usta hamal olamadın.

Çarşıda berberlere yamak oldun,

Ama usta berber olamadın.

Neden olmadın? Niye olmadın? 

A Keloğlan, keleş oğlan.

Hayatı beleş oğlan.

Senden adam olmayacak

Kaldırımları ölç oğlan.

2/:

A oğlan, keleş oğlan! 

Aş evinde aşçılara yamak verdim,

Pirinci kavurmadın.

Tarlada çiftçilere ortak verdim,

Tınazı savurmadın.

Sultana vezir verdim,

Sebat edip durmadın.

Niye durmadın? Neden durmadın? 

A keloğlan,keleş oğlan.

Hayatı beleş oğlan.

Senden adam olmayacak

Kaldırımları ölç oğlan.', '1/: A oğlan, keleş oğlan!  Kaf elinde sihirbaza çırak oldun, Ama usta medyum olamadın. Limanda hamallara yoldaş oldun, Ama usta hamal olamad...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hayati-beles-oglanin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çift Kalpli Er Olaydım', 'cift-kalpli-er-olaydim-mustafa-benkli-kiy79', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine hükmetti gönlüm, dedi ki, ben er olaydım; 

Ravzâyı Mutahhâra Yolu`nda Kıtmîr olaydım! 

Makam-ı Müntehâ`da Nebî-i İmâm-ı zîşân

Sağında salâttaki ilk cemmaaten olaydım! 

Yanında da o sâdık, O,  Ebûbekir-i zîşân; 

Mânayla, maddede tek, ruh olup huzura koşan,

Kalbiyle tek bir olup, gönlünde zikr ile coşan

Mevlâya kalbi açık, Rabıtalı er olaydım! 

Et ile tırnaktan da, öte, vuslata erişmiş,

Mânayla, maddede de, tek bir olmuş ve erimiş,

Birisi o ten kalbi, biri aşk ile doluşan,

Gönülü aşkla yanan, O çift kalpli er olaydım! 

Çift kalpli bam başka şey, iki kalpli ise başka,

Gönlümde, bu çift kalple meftunu olduğum aşka

Ruhunda gönül kalbi, kafesinde pır pır coşan

Aşkıyla Rabbe eren, çift kalpli er ben olaydım!', 'Yine hükmetti gönlüm, dedi ki, ben er olaydım;  Ravzâyı Mutahhâra Yolu`nda Kıtmîr olaydım!  Makam-ı Müntehâ`da Nebî-i İmâm-ı zîşân Sağında s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cift-kalpli-er-olaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydar''ın Köydeki Kahvaltısı', 'haydar-in-koydeki-kahvaltisi-ahmet-yozgat-w9zx1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Köydeki kahvaltımda

Bu yaz sadece yumurta var.

Yufka ekmeğiyle yumurta değerlidir 

En az şehirdeki kahvaltım kadar

“Haydi durma ye Haydar.”

2/:

Köydeki kahvaltımda

Bu yaz sadece yayla çorbası var.

Yufka ekmeğiyle çorba

Yanındaki taze ve yeşil soğanla 

Bilin ki çok değerlidir

En az şehirdeki kahvaltım kadar.

“Haydi durma ye Haydar.”

3/:

Köydeki kahvaltımda

Bu yaz sadece taze çökelek var.

Yufka ekmeğiyle çökelek değerlidir 

En az şehirdeki kahvaltım kadar.

“Haydi durma ye Haydar.”', '1/: Köydeki kahvaltımda Bu yaz sadece yumurta var. Yufka ekmeğiyle yumurta değerlidir  En az şehirdeki kahvaltım kadar “Haydi durma ye Hayda...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haydar-in-koydeki-kahvaltisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmail''di Onun Adı', 'i-smail-di-onun-adi-ahmet-yozgat-eu7ga', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I/:

İsmail''di onun adı. 

Yan komşunun tek oğluydu

O yüzdendi biraz yaramazlığı,

Ve sanırsam ondan dolayı 

İsmail''in dünyayı umursamazlığı.

Her daim ayağında gıcır gıcırdı 

Has deriden Sümerbank potinleri.

Ia/:

İsmail''di onun adı.

Babası terzi Şakir ustaydı

O yüzdendi yeni ceketinin düğmelerinin 

Gözümüzü alan sedefi parlaklığı

II/:

Her sabah komşu bahçeye atlar

Altın renkli kayısıları yolardı.

Kıyardı çağlayken daha meyvalar.

Sonra bizim civcivleri taşlardı. 

Her oyun ortasında kırmadık cam 

Ve yarmadık top bırakmazdı. IIa/:

İsmail''di onun adı

Haşlardı kasabadaki tüm çocukları. 

Günlerden bir uğursuz gün o gelince 

Mahallenin ne tuzu, ne de tadı kaldı.

İsmail''di onun adı 

Ailesinin yüz karasıydı.

Sopasını yemeyen kalmadı çevrede

Kafamda bakın hâlâ 

Attığı o koca taşın yarası.', 'I/: İsmail''di onun adı.  Yan komşunun tek oğluydu O yüzdendi biraz yaramazlığı, Ve sanırsam ondan dolayı  İsmail''in dünyayı umursamazlığı. H...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ismail-di-onun-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Çocukları', 'kar-cocuklari-ahmet-yozgat-2e2lj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

O amansız karlı tipide 

Okullarına koşan çocuklar.

Altlarında gürgenden kızakları 

Amansız dağları aşan çocuklar.

Yürüyün karda gıcır gıcır Kar size bir şey yapmaz.

Kıllı papak çok yakışır başınıza.

O amansız tipide 

Okula koşuşan çocuklar.

2/:

Altlarında hızlı kayakları 

Koca dağları aşan çocuklar.

Erzurum''un kışında 

Doğayla savaşan çocuklar.

Sığmayın küçük sınıflara 

Sokaklara kadar taşın çocuklar.

Üşüyün ayazda bıcır bıcır

Kış size bir şey yapmaz.

Sıcak papak çok yakışır kafanıza.

Altlarında kızakları 

Dağları aşan çocuklar.', '1/: O amansız karlı tipide  Okullarına koşan çocuklar. Altlarında gürgenden kızakları  Amansız dağları aşan çocuklar. Yürüyün karda gıcır gı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kar-cocuklari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Çocuğunun Bir Günü', 'koy-cocugunun-bir-gunu-ahmet-yozgat-wpuut', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A/:

Köyümüzde sabah olur 

İlk önce ibikli horozlar öter:

Ü-ürü-üüüüüüüü... 

Ben hemen kalkarım yerimden.

Kınalı horozlara bakarım 

Çilli tavuklar bana bakar.

B/:

Köyümüzde öğlen olur

Koyunlar gelir yaylımdan:

Me me me meeeee... 

Hemen sürerim onları ağılına.

Mor gözlü koyunlara bakarım

Kara gözlü kuzular bana bakar.

C/:

Köyümüzde ikindi olur

İnekler gelir kırlardan:

Mö mö mö mööööö... 

Hemen sürerim onları ahırına.

Sarı ineklere bakarım 

Ala tosunlar bana bakar.

D/:

Köyümüzde akşam olur

Ailem gelir tarladan

Yorgun argın babam gelir 

Anam gelir döküle döküle 

Oflaya puflaya gelirler kardeşlerim. 

Gireriz hep birlikte evimize

Ben onlara bakarım özlem ile

Onlarda bana bakar.', 'A/: Köyümüzde sabah olur  İlk önce ibikli horozlar öter: Ü-ürü-üüüüüüüü...  Ben hemen kalkarım yerimden. Kınalı horozlara bakarım  Çilli tav...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/koy-cocugunun-bir-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memo Dayının Öyküsü', 'memo-dayinin-oykusu-ahmet-yozgat-2hwve', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/...

Şu Memo dayı hoş çobandı,

Çocukluğumdan arta kalandı,

Koyunu sürüyle olan bir kasabadan.

Belinde halı desenli azık çantası,

Dağarcığında kalaylı ayran tası,

Yanında tepeleme yufka ekmek,

Ve kar beyazı çökelek, Bu bütün yiyeceği idi onun yıl boyu.

Huyu, sakin ve derindi.

Memo dayı sahibi sayılırdı

Mor dağların ve yeşil yaylaların,

Sayın ki her bir yerin. 

2/...

Şu Memo dayı hoş adamdı,

Sararmış ve sarkık bıyıklarıyla,

Sanki tek izdi kadim tarihten kalan.

Cebindeki aşınmış çaput cüzdanı,

Ya tamtakır ve bomboştu onun 

Ya da kıyıcığında beş on kuruşçuk...

O her zaman yoksul mu yoksuldu

Kısmeti azıcık, yaşamı usul usuldu.

Bazen çeşme başlarında ağzında bir türkü

Bazen dağlar başında sırtında kürkü

Mavi gözleri taramakta olurdu ufukları

Çayırları yayılırken kıpır kıpır koyunları.

Tüm rüzgarların sahibi idi Memo dayı

Barınağı o dik kayalıkların serin gölgesi,

Tek içeceği güneş altında

Soğuk kaynakların lezzetli suyu...

Huyu Memo dayının sakin ve derin 

Bu hoş çoban sahibi idi ta uzakların,

Hem de dağlar kadar upuzakların...

Sayın ki göz alabildiğine her yerin...

Ve yemyeşil hayallerin

Unuttuğum şirin köylerin...', '1/... Şu Memo dayı hoş çobandı, Çocukluğumdan arta kalandı, Koyunu sürüyle olan bir kasabadan. Belinde halı desenli azık çantası, Dağarcığın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/memo-dayinin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Ol Gönül', 'asik-ol-gonul-gultekin-toga-5xtrb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne Leyla,ne Aslı ne de Şirine,

Yaradan Hüda´ya aşık ol gönül,

Servet bilip helal alın terini,

Haramdan cudaya aşık ol gönül..

Gözüm yoktur makam,rütbe,payede,

Şerefli yaşarım ben bu sayede,

Karnımın tok oluşundan ziyade,

Manevi gıdaya aşık ol gönül..

Dost dinlenir; gücenmeden.küsmeden,

Gülden koku gelmez rüzgar esmeden,

Haksızlığın karşısında susmadan; 

Haykıran sedaya aşık ol gönül..

Bakınca geçici faniliklere,

İşledi dostdoğru yön iliklere,

Kapattım kapımı suniliklere,

Katıksız sadeye aşık ol gönül..

İnsan hayattadIr hicap ederse,

Sentezi hak yolda her neyim varsa,

Sebildir..gün gelir icap ederse,

Canımı fedaya aşık ol gönül', 'Ne Leyla,ne Aslı ne de Şirine, Yaradan Hüda´ya aşık ol gönül, Servet bilip helal alın terini, Haramdan cudaya aşık ol gönül.. Gözüm yoktur m...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asik-ol-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-selcen-boyar-un9tg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensizlik,

