INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanım var', 'i-syanim-var-hanifi-isikoglu-k7kfs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'senin beni terk edişine deyil

seni seviyorum diyişine deyil

senin beni övüsüne deyil

bırakıpta gidişine:İSYANIM VAR

senin bana gelişine deyil

terk edipte gidişine deyil

sana aşık olduguma deyil

başkasıyla oluşuna:İSYANIM VAR

benim yakışıklılıgıma deyil

senin güzeligine deyil

ikimizin sevgisine deyil

haber sizce gidişine:İSYANIM VAR', 'senin beni terk edişine deyil seni seviyorum diyişine deyil senin beni övüsüne deyil bırakıpta gidişine:İSYANIM VAR senin bana gelişine deyi...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isyanim-var-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliği yanlızlıkla paylaşıyorum', 'sensizligi-yanlizlikla-paylasiyorum-mustafa-komuscuoglu-opy9n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazılmamış ne varsa ben yazmadım

Söylenmemiş ne varsa ben soylemedim

Dizginledim kalemimide gönlümüde

Aşkımızı kagitlara aşikar etmedim.

Sensizliği yanlızlıkla paylaştım

Derdimi birtek duvarlara anlattım

Kimbilir uykusuz kaç geceyi atlattım

Birde sensizliği yanlızlıkla paylaştım

Şimdi öyle alıştım ki yanlızlığa

Artık donmeni bile beklemiyorum

Dilsiz duvarları buldum ya kendime

Artık derdime ortak can bile aramıyorum

Ama tuhaftır ki....

Sensizliği hala yanlızlıkla paylaşıyorum', 'Yazılmamış ne varsa ben yazmadım Söylenmemiş ne varsa ben soylemedim Dizginledim kalemimide gönlümüde Aşkımızı kagitlara aşikar etmedim. Sen...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kömüşcüoğlu']::text[], 8.5, '{"poet":"Mustafa Kömüşcüoğlu","poet_slug":"mustafa-komuscuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensizligi-yanlizlikla-paylasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D/üşüyorum', 'd-usuyorum-birsen-ates-6vwm6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızlığındı sadece

yıllardır bana tutunan

umutlarım sendeydi

görmediğin

cümlelerde yüklem gibiydi

sana olan hasretim

bir ömür beklediğim

sen o olmalısın

dilime takılmış bir şarkı gibi

günlerdir yüreğimde sesin

gelmeye kalksam yüreğine

ellerim sürüklenir zincirlere

ancak durdurabildiğim

yine de gel

son haykırışlarım

isyanım olsa da gerçeğe

düşlerde kalma sen

sevgiyle biriktirdiğim özlemim

söyleyemeden geçip gittiğim

kifayetsiz sözlerim

yere düşmesin diye gururum

adımlarımı bağladım gözlerine

yürürken sendelediğim

bilmiyorsun

çığlık çığlığa

hep sana d/üşüyorum

19.02.06', 'yalnızlığındı sadece yıllardır bana tutunan umutlarım sendeydi görmediğin cümlelerde yüklem gibiydi sana olan hasretim bir ömür beklediğim s...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/d-usuyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarım seninmiş', 'ruyalarim-seninmis-umran-aldic-9huth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyurken  uykumda  aramışım  seni

Hıçkırarak  anmışım  güzel  ismini

Haberim  yok  bilmiyorum  dövmüşüm  kendimi

Yolmuşum  saçlarımı  ayrıldık  deyi.

Sabah  olunca  kocam  bir bir  söyledi.

Hala mı  kalbinde  dedi  onun yeri.

Diyemedim  seni  gene çok  sevdiğimi.

Oysaki  mutluyum  sıcak  yuvam  var.

Canımdan  çok  seviyorum  iyi  eşimi

Beş  yaşında  tatlı  canım  yavrum  var.

Neden  hala  düşünürüm  bilmemki seni.

Unuttum  sanmıştım  taa  yıllar  önce

Anılar  kalmıştı  senden  öylesine

Kim  derdiki  taa  içimde....

Rüyalarım  bile  seninmiş  anlayamadım.', 'Uyurken  uykumda  aramışım  seni Hıçkırarak  anmışım  güzel  ismini Haberim  yok  bilmiyorum  dövmüşüm  kendimi Yolmuşum  saçlarımı  ayrıldı...', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruyalarim-seninmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zikzak', 'zikzak-muammer-erturan-swq7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaya,

......uzaya,

............uzaya,

..................zikzak; 

............kısala,

........kısala,

....kısala

tiktak; 

....büyüye,

........büyüye,

............büyüye

...............boşluk; 

.............küçüle,

.........küçüle,

....küçüle

kaybolur olduk...

(14 Mart 97)', 'Uzaya, ......uzaya, ............uzaya, ..................zikzak;  ............kısala, ........kısala, ....kısala tiktak;  ....büyüye, .........', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zikzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilim', 'dilim-muammer-erturan-jg7ei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilimlerden bir dilim...

Ve dilim dilim kendisi de...

Ve dilim dilim 

her bir dilimi...

Zamanlardan bir zaman...

Bir ömür...

O ömürde bir an; 

bir ''şey'' gibi değil,

birey gibi yaşanan...

O ömrü ömür yapan

o an işte...

Dilimin diliminin dilimi...

(28 Eylül ''99)', 'Dilimlerden bir dilim... Ve dilim dilim kendisi de... Ve dilim dilim  her bir dilimi... Zamanlardan bir zaman... Bir ömür... O ömürde bir an...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dilim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Oyuna Bir Bilet', 'i-ki-oyuna-bir-bilet-muammer-erturan-k95zm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üç yıldır mahpusum 

oturduğum evde 

iki de sürgünüm var, 

ilki semtten semte

ikincisi iki sokak öte

üçüncüsü de beklenmekte her an... 

Üstelik 

elektriğim kesik hanidir

sayacı bile sökülmecesine... 

O kadarla kalsa gene iyi 

ne mum alacak para 

ne para alacak biri 

ne bir beklenti var 

açılır diye kapılar...

Koş vatandaş koş! 

Sefaletin kralı burdaa! .. 

Kralın sefaleti ya da... 

İki oyuna bir bilet

bu oyunlar bedavaa! ..

(Ağustos ''99)', 'Üç yıldır mahpusum  oturduğum evde  iki de sürgünüm var,  ilki semtten semte ikincisi iki sokak öte üçüncüsü de beklenmekte her an...  Üstel...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-oyuna-bir-bilet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ödeşsek', 'odessek-muammer-erturan-q6ysa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke hesap sorsa

bütün aşklarım...

Ne almışım onlardan

onlar benden ne

kimin hakkı kalmış kimde

görsek hele...

Keşke hesap sorsa

bütün dünya...

Ne vermişim ona

o bana ne

dönebilirse gene de

öyle dönse...

Keşke hesaplaşsak

hepsiyle hemen

ve ödeşsek hepten...

(23 Haziran ''98)', 'Keşke hesap sorsa bütün aşklarım... Ne almışım onlardan onlar benden ne kimin hakkı kalmış kimde görsek hele... Keşke hesap sorsa bütün düny...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/odessek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az susarken', 'az-susarken-akin-akca-1moil', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biraz susarken, az

demin içtiğin bardağı itekliyorsun; 

meğer ucunda cd kalemi varmış..

paralel bir uzantıda,

sonra diğer uzantı kalemden

çay bardağına değiyor

diğer uçta -

içinde izmaritler birikmiş olan

tuhaftır ki; 

ittiğin giderken

çay bardağı durmuyor,

sana doğru ilerliyor -

iteklediği o kalemciğin.

taşıdıklarını da görmek lazım,

bu bir köprü ise

ki öyle, durmuyor.

doğaçlama

ikinci versiyon

-

biraz susarken, az

demin içtiğin bardağı itekliyorsun; 

meğer ucunda cd kalemi varmış..

paralel bir uzantıda,

sonra diğer uzantı kalemden

çay bardağına değiyor

diğer uçta -

içinde izmaritler birikmiş olan

tuhaftır ki; 

ittiğin giderken

çay bardağı sana durmuyor,

doğru ilerliyor -

iteklediği o kalemciğin.

taşıdıklarını da görmek lazım,

bu bir köprü ise

ki öyle, durmuyor.

doğaçlama', 'biraz susarken, az demin içtiğin bardağı itekliyorsun;  meğer ucunda cd kalemi varmış.. paralel bir uzantıda, sonra diğer uzantı kalemden ça...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/az-susarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken emekli ölüvermek', 'erken-emekli-oluvermek-seref-ozturk-usta-12gsk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İt gibi bir yaşamı 

...çekip de yakasından

.....vuru verdik toprağa gölgesinden.

Kalıbı dinlendirmek 

...vedasız gidivermek

.....diyorlar adına ölümün.

Oy sa adam gibi

...yaşamaktı dilek

.....hiç yorulmadı 

.......örs''e çekiç vuran bilek.

En verimli çağımızda

... tam ustalaştığımız da

.....çalıp hayatı bizden

.......aylaklığa emekli öldük işimizden.', 'İt gibi bir yaşamı  ...çekip de yakasından .....vuru verdik toprağa gölgesinden. Kalıbı dinlendirmek  ...vedasız gidivermek .....diyorlar ad...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/erken-emekli-oluvermek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefes alma fırsatı', 'nefes-alma-firsati-akin-akca-iaok4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kim fırsata umut kazanmak der? ? 

benden umut kazanmayacak keder! ! 

sadece bir ilerleyecek er! 

evet, gerekirse hepsini 

de önüne serer! ! sormalı kaç kereler? 

inkar etmeye bitirimsin, 

bitişsiz kereler.

doğaçlama', 'kim fırsata umut kazanmak der? ?  benden umut kazanmayacak keder! !  sadece bir ilerleyecek er!  evet, gerekirse hepsini  de önüne serer! ! ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nefes-alma-firsati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Mevsim Gündemdesin', 'her-mevsim-gundemdesin-bahaettin-karakoc-3aqcg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırmızı bir geyik yanıyor güz ırmaklarında 

Gözleri bengi bengi bir orman 

Zamanı kaşıyan parmaklarında 

Benek benek kan…

Ayaklarına keçe bağlanmış bütün atların 

Silinmiş yazıları kitapların 

Tohum, merhametine sığınmış bulutların 

Öylesine üryan…

Yeniden yeşeren otların koşturan yeşili 

Görkemli tabiatın en zengin dili 

Gönül pırrr diye uçan bir keklik çili 

Yürek bir yanık harman…

Her ağacın arkasına sen saklanmışsın 

Yerden göklere dek germişsin sessizliği 

Öteğen bir kuştur bıraktığın ışın 

Ya da sultanca bir ferman…

Sabahtan akşama, akşamdan sabaha 

Bir kirmen gibi seni eğirir ruhum 

Dağ, orman, deniz, gökyüzü... aha 

Her yıldız kılıfını yırtmış bir can…

Ey mutluluğumun müziği şiir mayam 

İksirinin karışmadığı sular sığ, söyleşiler ham 

Bense gözlerini dinlemek istiyorum bu akşam 

Bütün sevdalı kuşlardan…

Bahaeddin KARAKOÇ (Kar Sesi – Ocak Yayınları – ANKARA)', 'Kırmızı bir geyik yanıyor güz ırmaklarında  Gözleri bengi bengi bir orman  Zamanı kaşıyan parmaklarında  Benek benek kan… Ayaklarına keçe ba...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/her-mevsim-gundemdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak Aşığı Hancı Hervane', 'hak-asigi-hanci-hervane-hanci-pervana-a0n3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hancı pervanenin okuma yazması yoktur nöbet yerinde hz peygamberimiz hz fatma imam hüseyin ve imam hasan dan ders almıştır ders esnasında kimse yanına yaklaşamamış şafak vaktinden önleye kadar tabur etrafını cevirip beklemiştir hakkın imamıdır sonsuz ilmim gelmektedir yunus emre hatayı sultan daimi ve sümmanı gibi aynı ruhu taşımaktadır aşağıda kendi sıfatlarını anltmaktadır

HANCI PERVANE.540

O yar bağı demanında

Bende  ayrancıda  zamanında

O yar gürçistanda zöhre hanım tamamında

Hayalim üççetim hesabı görülür ançak

Aslı nuru cihan mubarek olunca

Evliyalar da açar sancak hey

Ta tevekkil gaf gayretinde

Çim cemal ullaha var hikmetinde

İnne ale muhammet alinin gayretinde

Ah hele okudukça ya hu

Evarahta ançak evrahta anaçak

O yar gürçistanda bende izmire

Tevekkil durmuşum hele bir yüze

Yüz yirmi dört bin nebiden süzülmek için geldim size

Ah hele la mekan ilminin düşmüşüm öze

Hancıyam bu sözü pervazı imam olarak heey

İmanın kavimdir cim ile dala

Elif lem elifle gayretin ala

Ah hele la mekan ilminde ruhum kala

Hayalin üççetim geldim bu yola

Dostlar bağında temaşa ala ala

Hancıyam diyerim sözüm evraha

Kündü kenzulahta bulur vallaha

Aliyul abayı  sitretil muntada

Elhemdulullaha ah hele resullahtan cemala

Bu sözüm kala eyler eeey

HANCI PERVANE

Aradım hecesin zatını bildim

Sırrı su bahan o noktada gizlidir

Aslı bir noktadır tahtı sarayda

Tecelli gösterir her bir eşyada

Elleme esmayı bay kibri yada

Sebel messep o noktada gizlidir

Ya tabib dört isim gönderdi ol gani subahan

Dört kitap yazılıp inmezden evvel

Dört isim kıtında ne idi yenen

Ab yanıp çiğde pişmezden evvel

Hakikat ilminden noktayı birden

Sırrı sırılulahtan...........

Tah ezel evrahtan gabaga hüseyninde

İlmi simiyada kef inen nundan

İlmi kudureti didara karşı

Ehette ehemde gözümün yaşı

Tecellah kıldımda hakka ben karşı

Kudret kandilinde durduğum zaman

Tekellim gelince dili pervane

İsmimizi koydular hancı pervane

Kudret kandilinde ta ah ezel cana

Zühre hanımınla aldığım zaman

Doluyla kadefi içtik pirinde

Firdezi alede hemen yerinde

Kırklar meclisinde yusuf kenan pazarında

Dağıldı kadefler aldım dilimde

Erenler yükünü merdan olunca

Hayel bastı birden dem oldu anca

Yıkandık yuğrulduk kuruldu sancak

Muhamed mustafa nuru huda hak

O zaman tecallah kıldık gelince

Evrakımız pekte nuru cihanda

Tekellim gösterdik aşıkların an meydanda

Kırklar meclisinde hicap ihsanda

Hicaptan kudretten nur geçti elime

Söylesem bende hemen dilime

Hakikat ilminde firdez yerine

Nuru cemalına bir oldum hakka yareb', 'hancı pervanenin okuma yazması yoktur nöbet yerinde hz peygamberimiz hz fatma imam hüseyin ve imam hasan dan ders almıştır ders esnasında ki...', ARRAY['Türk Edebiyatı','Şiir','Hancı Pervana']::text[], 8.5, '{"poet":"Hancı Pervana","poet_slug":"hanci-pervana","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/hak-asigi-hanci-hervane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterki Gel', 'yeterki-gel-seyfet-bozcali-r97xe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim olursan ol demiş,

Ayrım yapmakta neymiş,

Dost bağına dal demiş,

Mevlanamız gel demiş...

İnsanlığı bulda gel,

Kalmasın önde engel,

Güneş gibi olda gel,

Kurtuluşa dal demiş...

Kalmasın hiç dert tasa,

Kanma fitne, fesata,

Muhabbet olmasada,

Gel burada var demiş...

Tebrizi güneşinden,

Mevlana''nın aşkından,

Seyfet''in şiirinden,

Gel nasibin al demiş...

19.02.2006', 'Kim olursan ol demiş, Ayrım yapmakta neymiş, Dost bağına dal demiş, Mevlanamız gel demiş... İnsanlığı bulda gel, Kalmasın önde engel, Güneş ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeterki-gel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bas-tacimsin', 'bas-tacimsin-seyfet-bozcali-v7nx5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acı günlerde ilacım,

Gönül sızım,altın tacım,

Ne kadar yalvarsam açım,

Dualarım baş tacımsın....

İbadetle, niyazlarla

Hak yolunda ahbaplarla,

Hakka açılan ellerle,

Dualarım baş tacımsın...

Seyfet anlatır dillerle,

Ayetlerle,Hadislerle,

Hakka açık gönüllerle,

Dualarım ilacımsın...

       19.02.2006', 'Acı günlerde ilacım, Gönül sızım,altın tacım, Ne kadar yalvarsam açım, Dualarım baş tacımsın.... İbadetle, niyazlarla Hak yolunda ahbaplarla...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bas-tacimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım Hamdolsun Doğru Yoldayım', 'anladim-hamdolsun-dogru-yoldayim-seyfet-bozcali-5e8ud', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçmişimi şöyle yoklayıverdim,

Baktım ki hamdolsun doğru yoldayım.

Çok kötü zamanlar yaşadım,gördüm,

Anladım hamdolsun doğru yoldayım...

Kardeş,kardeşi öldüren zamandı,

Sağ,sol sarmış zaman kötü zamandı,

Bir çok gençlik siyasilere  kandı,

Kanmadım hamdolsun doğru yoldayım,

Ta küçük yaşlardan, bağlıydım dine,

Hep uzak durmuşum nefretle,kine,

Ne buna inandım,ne ötekine,

Uymadım hamdolsun doğru yoldayım...

Seyfet der tek yola gönlümü verdim,

O yolda mutluluk,huzuru buldum.

Başımı Rahman''ın yoluna koydum,

Anladım hamdolsun doğru yoldayım...

              10.10.1983', 'Geçmişimi şöyle yoklayıverdim, Baktım ki hamdolsun doğru yoldayım. Çok kötü zamanlar yaşadım,gördüm, Anladım hamdolsun doğru yoldayım... Kar...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anladim-hamdolsun-dogru-yoldayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-altay-taskin-hfq0n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'arife günü çıkmaz sokakta

gün ısmarlamışım mutluluğa

bülbüller ağıtta gül ağacında

oturdum iki elim şakağımda

mutluluğum kalmış başka bayrama...', 'arife günü çıkmaz sokakta gün ısmarlamışım mutluluğa bülbüller ağıtta gül ağacında oturdum iki elim şakağımda mutluluğum kalmış başka bayram...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bayram-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-tahmine-yildirim-skh2g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hüzünmü çöktü yüreğine

Nazarlar değmesin gönlüne

Ver ellerini ver benim ellerime

Kederleri bırak bir tarafa arkadaş

Yapma üzme kendini 

Bırakma bu kadar benliğini

Kapat kötülüklere hep gözlerini

Hep neşeye yer ver hayatında arkadaş.

                                                          MAYIS

                                                           2004', 'Hüzünmü çöktü yüreğine Nazarlar değmesin gönlüne Ver ellerini ver benim ellerime Kederleri bırak bir tarafa arkadaş Yapma üzme kendini  Bıra...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/arkadas-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığa', 'karanliga-seyfet-bozcali-rds58', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunca yıldır boşa geçen zamanı,

Çıkarıpta yolladım karanlığa.

İlahiden hep bekledim amanı,

O yılları bağladım karanlığa...

Yaşamımı sordum o gecelerde,

Cevabını bulmadım hecelerde,

İsteklere baktım çok yücelerde,

Dua edip ağladım karanlığa...

Tüm zamana çileleri işledim,

Yaşamıma yeni baştan başladım,

Kötü geçen günü dönüp taşladım,

Nefret ile yolladım karanlığa...

Yaradanın isteğiğle yoğruldum,

Kulluk vazifemi ifaya durdum,

Bozçalı der kötü nefse  uymadım,

Şeytan ile yolladım karanlığa...

19.02.2006', 'Bunca yıldır boşa geçen zamanı, Çıkarıpta yolladım karanlığa. İlahiden hep bekledim amanı, O yılları bağladım karanlığa... Yaşamımı sordum o...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karanliga-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pir Elinden Bade İçmedim', 'pir-elinden-bade-i-cmedim-yusuf-onder-bahceci-vt5ow', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben, Pirlerin elinden, bade, made içmedim,

Dünya''dan geçtim ama, senden geçmedim,

Güzellerin içinde, inan başkasını seçmedim,

Ben, Pirlerin elinden, bade, made içmedim.

Ben senin ellerinden, ecel şerbetini içmişim,

Seni öyle sevmişim, hemde, gönül vermişim,

Ne kadar da cahilmişim, bir şey bilmemişim,

Ben Pirlerin elinden, bade, made içmemişim. 

Söyle bade mi içmek gerekir, böyle sevdaya,

Beni böyle ateşlere atan yakan kara sevdaya,

Ben seni arıyorum hâla, çöllere atan sevdaya,

Ben Pirlerin elinden, bade, made içmemişim.

Pir elinden bade içilecekse, bu denilecekse,

Seni nasıl sevdiğimi Alem''in hepsi bilecekse,

Uğruna cânı verdiğim, cânım geri gelecekse,

Ben Pirlerin elinden, bade, made içmedim.....', 'Ben, Pirlerin elinden, bade, made içmedim, Dünya''dan geçtim ama, senden geçmedim, Güzellerin içinde, inan başkasını seçmedim, Ben, Pirlerin ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pir-elinden-bade-icmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik Mevsimler', 'eksik-mevsimler-nihal-gungor-t60mm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Noksandı,hayatımda kaybolmuş iklimler.

Birbirinin aynı geçen yavan zincirlemeler.

Umrumda değil gelecek kötü günler.

İyiki ısındı küre,

iyiki yağdı kar.

Tamamlandı eksik mevsimler.', 'Noksandı,hayatımda kaybolmuş iklimler. Birbirinin aynı geçen yavan zincirlemeler. Umrumda değil gelecek kötü günler. İyiki ısındı küre, iyik...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eksik-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Puşt''a', 'o-pust-a-omer-dalman-8ccvu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir daha yaranmayacağım o imansıza

o puşta

o hiçbir meziyete değer vermeyen

moral bozan ukalaya! 

çok var etrafımızda bunlardan

bilirsiniz

belki bilmezsiniz şanslıysanız...

karanlığı yanıbaşında barındıranlar bilir

bu acıyı çekmişlerdir.

ellerini kollarını bağlamıştır bu puştlar.

geç kalmadan

merhamete düşmeden

biletlerini kesmekten başka çareleri yoktur

yoksa yazık olur onlara

yazık olur ışığa! 

hay şu lanet Karanlığın bağrımızdaki temsilcileri! 

sakın ola ki yaranmayalım o imansızlara

o puştlara

en yakından en uzağa bizleri emen, bitiren

o vampirlere! 

sakın ha! ..

(Şubat 2006)', 'bir daha yaranmayacağım o imansıza o puşta o hiçbir meziyete değer vermeyen moral bozan ukalaya!  çok var etrafımızda bunlardan bilirsiniz b...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/o-pust-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daral Geldi', 'daral-geldi-tahmine-yildirim-vs0fu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çığ var gönlümde

Duyduğum her sesten kıpırdıyor

Yuvarlanıp gidecekmiş gibi

Çözemiyorum ben bu işi

Var olan birşeyler var ama 

Zorlanıyorum anlamakta

Esas olan zoru anlamak ama

Ben yinede anlıyamıyorum

Bir karanlık var bir köşemde 

Bir türlü aydınlatamıyorum

Ben ışık yakmaya çalıştıkça

O karanlık kendine eş arıyor

Canım sıkılıyor stresliyim

Gevşememe izin verilmiyor

Kim bu zatı muhterem 

Terket beni her kimsen

Seni sevmedim seni sevemem.

                                                             NİSAN

                                                                          2004', 'Bir çığ var gönlümde Duyduğum her sesten kıpırdıyor Yuvarlanıp gidecekmiş gibi Çözemiyorum ben bu işi Var olan birşeyler var ama  Zorlanıyor...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/daral-geldi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Yak Bir Sigara', 'haydi-yak-bir-sigara-yusuf-onder-bahceci-1vgrd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haydi yak bir sigara, dumanını savurda küllerine bak,

Haydi yak bir sigara, dumanını savurda fallarına bak,

Haydi yak bir sigara, dumanını savurda yollarına bak,

Haydi yak bir sigara, dumanını savurda hâllerine bak,

Haydi yak bir sigara, dumanını savurda gözlerine bak,

Haydi yak bir sigara, dumanını savurda yürekleri  yak,

Haydi yak bir sigara, dumanını savurda suçlarına bak,

Haydi yak bir sigara, dumanını savurda dumanına bak...', 'Haydi yak bir sigara, dumanını savurda küllerine bak, Haydi yak bir sigara, dumanını savurda fallarına bak, Haydi yak bir sigara, dumanını s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/haydi-yak-bir-sigara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalini Kuramazdım', 'hayalini-kuramazdim-omer-dalman-iymkw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün akşam eve döndüğümde

senden sonra

ama ''senli'',

hayallere daldım utanmazca

ağza alınmayacak...

daha ne kadar biliyordum seni

huylarını? 

olsun! 

yaptım işte ne gerekiyorsa! 

gerçeğe uzanan kolu olmasa

hayalini de kuramazdım, biliyorum.

onun için dün akşam eve döndüğümde

senden sonra

pek bir ''senli''

hayallere daldım

pek bir utanmaz

pek bir ağza alınmayacak

pek yüz kızartan! ..

tadın da ne kadar güzeldi! ? 

daha ne kadar biliyordum seni

huylarını? 

bilemem ama

gerçeğe uzanan kolu olmasa

hayalini de kuramazdım.

(Şubat 2006)', 'Dün akşam eve döndüğümde senden sonra ama ''senli'', hayallere daldım utanmazca ağza alınmayacak... daha ne kadar biliyordum seni huylarını?  ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayalini-kuramazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler', 'dusler-altay-taskin-bgx9y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'testi kırılsın su aksın

saç kırılsın görünsün başın

ışık kırılsın göz yanılsın

gece düş kırılmasın

çocuğun avucunda tomurcuk o

baksın...baksın...

umutlar yumağında o

bırak düşleri kırılmasın...', 'testi kırılsın su aksın saç kırılsın görünsün başın ışık kırılsın göz yanılsın gece düş kırılmasın çocuğun avucunda tomurcuk o baksın...baks...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dusler-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde Sakarya?', 'nerde-sakarya-seyfet-bozcali-sse3v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar kan ağlayıp dururdun,

O Necip Fazıl''ın nerde Sakarya,

Bir çok şairede   yar,yaren oldun,

Onurlu akışın  nerde Sakarya? 

Azmı şehit verdik siperlerinde,

Su yerine kan akıttık kalbinde.

Şimdi mutlumusun emin ellerde,

Sevgiyle dol,gururla ak Sakarya...

El ele vermeli Ata''nın nesli,

Destanlar yazmalı kalmalı yaslı,

Kalbinde durmasın imanın paslı,

Çok  süründün ayağa kalk Sakarya...

Seyfet derki sana hoştur niyetim,

Çağı aydınlatır medeniğetin,

Suskun,suskun akıp bırakma yetim,

Çağla,çağla sevgiyle ak Sakarya...

19.02.2006', 'Bir zamanlar kan ağlayıp dururdun, O Necip Fazıl''ın nerde Sakarya, Bir çok şairede   yar,yaren oldun, Onurlu akışın  nerde Sakarya?  Azmı şe...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nerde-sakarya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Söyleyeyim Nasıl Diyeyim', 'nasil-soyleyeyim-nasil-diyeyim-yusuf-onder-bahceci-u40vb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim bütün dertlerimin yârdır dermanı,

Doktor, tabib, hepsinin yok ki dermanı,

Beni bu sevdalara böyle, salanı, salanı,

Ben nasıl söyleyeyim de nasıl diyeyim. 

Bir gözlerime gülse, birşeyim kalmaz,

Yıllardır çileyi çektim şikayetim olmaz,

Benim kâlbimde, garez ile kin olmaz,

Ben nasıl söyleyeyim de, nasıl diyeyim.

Yârimin güzel gözleri ile, o tatlı sözleri,

Kâlbime düşürdü bak, ateş ile közleri,

Ciğeri beş para etmez diyenin sözleri,

Ben nasıl söyleyeyim de, nasıl diyeyim.

Bırakayım, kâlbimde ki ateş yansın mı,

Ağustos da bedenim böyle donsun mu,

Sevdayı kimse duymasın, duymasın mı,

Ben nasıl söyleyeyim de, nasıl diyeyim...', 'Benim bütün dertlerimin yârdır dermanı, Doktor, tabib, hepsinin yok ki dermanı, Beni bu sevdalara böyle, salanı, salanı, Ben nasıl söyleyeyi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-soyleyeyim-nasil-diyeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazim Benim', 'mazim-benim-tahmine-yildirim-yzpmj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoruldum dinlen diyenim yok

Aksine hep eleştiriliyorum

Saygı duyanım yok

Yoruldum otur diyenim yok

Bir karar aldım kendimce

Artık hiç susmuyacağım

Haksızlıklarla hep savaşacağım

Ezdirmiyeceğim kendimi

Taktir görürmüyüm bir gün onuda bilmem

Ama yine de hak ettiğimi sanıyorum

İç güdülerim böyle diyor

İnşallah hayallerim ölmez

Bazen herşeyin sonu gibi sanki

Hançerler saplanıyor yüreğime

Kanıyor içim yavaş yavaş

İşte o zaman çok üşüyorum.

                                                                                 NİSAN

                                                                                              2004', 'Yoruldum dinlen diyenim yok Aksine hep eleştiriliyorum Saygı duyanım yok Yoruldum otur diyenim yok Bir karar aldım kendimce Artık hiç susmuy...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mazim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmezmiş Sana', 'degmezmis-sana-hayrullah-ozkan-zp2gz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Emek ettim,emek nedir bilmdin,

Geç farkettim yarim, değmezmiş sana.

Sevgi verdim, sevgi nedir bilmedin,

Geç farkettim yarim, değmezmiş sana.

Yalan sözlerinle kandırdın beni,

Sevdana düşürüp yandırdın beni,

En sonunda candan bezdirdin beni,

Geç farkettim yarim,değmezmiş sana.

Bir kerecik bile gülmedin yüze,

Acı dahi olsa hasretim söze,

Sonbaharımdayım,çıkamam yaza,

Geç farkettim yarim,değmezmiş sana.

Engeller hep bana,yol senin olsun,

Dikenler hep bana gül senin olsun,

Zehir ben içeyim,bal senin olsun,

Her şeyden vazgeçtim,değmezmiş sana.', 'Emek ettim,emek nedir bilmdin, Geç farkettim yarim, değmezmiş sana. Sevgi verdim, sevgi nedir bilmedin, Geç farkettim yarim, değmezmiş sana....', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Özkan']::text[], 8.5, '{"poet":"Hayrullah Özkan","poet_slug":"hayrullah-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degmezmis-sana-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dön Diyemem', 'sana-don-diyemem-yusuf-onder-bahceci-gazn4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben erkeğim sana dön diyemem,

Seni sevmişim gel, gel diyemem,

Sevmesen bile yine de gidemem,

Ben erkeğim sana dön diyemem.

Bu savaş erkekçe olmadı öleyim,

Bu hâllerde ben nasıl da diyeyim,

Sadece şiir yazarak, söyleyeyim,

Ben erkeğim sana dön diyemem.

Gelsin beni kandırsınlar göreyim,

Onların hepsini, ters, yüz edeyim,

Senin için cânı veririm, neyleyim,

Ben erkeğim sana dön diyemem.

Ben şimdi çoşkun sel önündeyim,

Diyeyim sade senin derdindeyim,

Mecnun, Kerem''in kaderindeyim,

Ben erkeğim sana dön diyemem...', 'Ben erkeğim sana dön diyemem, Seni sevmişim gel, gel diyemem, Sevmesen bile yine de gidemem, Ben erkeğim sana dön diyemem. Bu savaş erkekçe ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-don-diyemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acısız', 'acisiz-hafize-kilic-2-v94ho', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben senden 

Çeyrek  hayat arasına, 

biraz sevgi istiyorum. 

Acısız olsun lütfen.

Çok şeymi istedim senden.

Gurbet Meleği', 'Ben senden  Çeyrek  hayat arasına,  biraz sevgi istiyorum.  Acısız olsun lütfen. Çok şeymi istedim senden. Gurbet Meleği...', ARRAY['Türk Edebiyatı','Şiir','Hafize Kılıç 2']::text[], 8.5, '{"poet":"Hafize Kılıç 2","poet_slug":"hafize-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/acisiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Bir ben', 'bir-sen-bir-ben-memur-zeki-78id4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEN…

Belki de haklısın çekinmekte

İçindeki geceden korkmakta haklısın belki kim bilir.

BEN…

Her gördüğümde sana sarılmayı istemez miyim

Arzulamaz mıyım sımsıkı elinden tutmayı

Hayal etmez miyim başımı omuzuna dayamayı

İstemez miyim sanırsın dizinde yatmayı

Bilmezsin ki nasıl içim gider.

Bilemezsin ki…

SEN…

Belki de haklısın çekinmekte

Gecenin bilinmezlerinden korkmakta haklısın.

BEN…

Seni doyasıya yaşamak istiyorum diye 

Sana özlemsiz kalmak istiyorum diye

Üstelik gözüm gönlüm zırıl zırıl açken

Doyurmak için bunca acıyı çektiriyorum diye

Lanet olsun… 

Yuh olsun bana...

SEN…

Kederli gecelerime katık oluyorsan sürekli

Yokluğunu avuntusuzca çökertiyorsan yastığımdaki çukura

Gözlerine bakabilme cesareti verebiliyorsan bana

Hiç konuşmasam da dinliyorsan beni

O zaman anlarsın beni 

O zaman gözlerinin içinde boğulmama yardım et

O zaman gözlerinin içinde kendimi öldürmeme izin ver lütfen

BEN…

Başarmalıyım RAĞMEN SEVGİNİ kazanmayı, 

Başarmalıyım sevilebilmenin tadını almayı

Sıkılmış bir yumruk gibi değil,

Dua eder gibi duruyorsam karşında 

İbadetimi eksik etmiyorsam gece gündüz

Bunun için can vermeyi de bilir ve başarırım.

VE…

SENLE BEN…

Nefes almak gibi kolaysa senle yaşamak

Can vermek gibi zor senden uzakta kalmak

Bilsem ki yüreğim cehennem ateşiyle yanacak

Bilsem ki buzullarda senden uzakta donacak

Bilsem ki ben onu parçaladıkça o binlerce kez çoğalacak

Yine de istemem sen yoksan eğer içinde...

                                                                    19.02.2006 02:55:33', 'SEN… Belki de haklısın çekinmekte İçindeki geceden korkmakta haklısın belki kim bilir. BEN… Her gördüğümde sana sarılmayı istemez miyim Arzu...', ARRAY['Türk Edebiyatı','Şiir','Memur Zeki']::text[], 8.5, '{"poet":"Memur Zeki","poet_slug":"memur-zeki","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bir-sen-bir-ben-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistinli Çocuk - 1', 'filistinli-cocuk-1-agah-adiguzel-gozn7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Filistinli çocuk

Tutar gözleriyle kurşun sesini

Vurur uzak tepelere yürek atışı



Beyaz   gülünü  koparır gecenin

sapan tutan elleriyle

çağın yüreğine bırakır

Karanlığın esmer yüzlü çocuğu

Vahşi esaretin yarış atı

düşlerin  Akdeniz kıyılarında,

		

Sen ki tuzlu kumsalımın kıyıcıları

yanıp külleriyle geçmişin

Aldanıp vurulursun,

Filistin gecelerine

Bir kurşun uzaklığı yaşamın 

Kaç yüzyıl öncesinde

Satılmış geleceğin   kurşunlara

Ve takılmıştı gözlerin 

İsrail tanklarına

Bu yüzden

boyuna öleceksin,

boyuna güleceksin.', 'Filistinli çocuk Tutar gözleriyle kurşun sesini Vurur uzak tepelere yürek atışı Beyaz   gülünü  koparır gecenin sapan tutan elleriyle çağın ...', ARRAY['Türk Edebiyatı','Şiir','Agah Adıgüzel']::text[], 8.5, '{"poet":"Agah Adıgüzel","poet_slug":"agah-adiguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/filistinli-cocuk-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-asude-gediz-r9eqg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevmek bir yaşam biçimi

sevdiğini bilmekse doping gibi

Senden ayrı olsamda

boş bulduğum her anda dalarım sana 

seninle yaşadığım her saliseyi

uzun metrajli bir film gibi yaşarım hayatımda

Bazı geceleler 

yazarım seni  hece hece

anılarım yalnızlığıma çare

Ama Sen! 

kafamda  bir soru 

hayatımda

çözemediğim bilmece', 'Seni sevmek bir yaşam biçimi sevdiğini bilmekse doping gibi Senden ayrı olsamda boş bulduğum her anda dalarım sana  seninle yaşadığım her sa...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilmece-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım', 'agladim-yusuf-onder-bahceci-a4cer', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Albümde ki resimlere baktım, baktım ağladım,

Sigara üstüne, sigara yaktım, yaktım ağladım,

Yıllarca hep yollarına baktım, baktım, ağladım,

Yazılan mektupları da, yaktım, yaktım ağladım,

Senin için hâyalleri kurdum, kurdum, ağladım,

Gelirsin diye, yollarına çıktım, çıktım, ağladım,

Senin için, güzel şiirleri yazıp, yazıp, ağladım,

Senin için, en güzel besteleri yapıp,  ağladım,

Senin için, Allah''a dualar edip, edip, ağladım,

Ama heyhat sen bir kere sormadın, aramadın...', 'Albümde ki resimlere baktım, baktım ağladım, Sigara üstüne, sigara yaktım, yaktım ağladım, Yıllarca hep yollarına baktım, baktım, ağladım, Y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/agladim-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğim', 'melegim-serkan-kukrer-umltd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Banu''ma

Nereye baksam seni görüyorum

Usulca biri sokuluyor yanıma

Sıcacık elini tutuyorum

Sımsıkı sarılıyorum, ayrılmamasına

İpek saçlarını hissediyorum

Birden bir bahar rüzgarı esiyor

Mis gibi kokunu duyuyorum

Artık melekler nasıl olurmuş

Biliyorum...

19.02.2006', 'Banu''ma Nereye baksam seni görüyorum Usulca biri sokuluyor yanıma Sıcacık elini tutuyorum Sımsıkı sarılıyorum, ayrılmamasına İpek saçlarını ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Kükrer']::text[], 8.5, '{"poet":"Serkan Kükrer","poet_slug":"serkan-kukrer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/melegim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşırı Korku, Aşırı Ümit (Düz Yazı)', 'asiri-korku-asiri-umit-duz-yazi-ali-kilic-kakiz-z5u3s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsan emanetçidir, bir gün emanetini teslim edecektir. Emaneti taşıyanların şiarı:

Sebep ve çarelerden olumlu sonuç alamayanlar, Cenab-ı Hakka el açarak, ilahi yardımı tecelli etmesini isterler...

    Ama sıkıntıya düşen inkarcıya gelince:

Bu noktaya gelen ve onu kahreden sebepler üçtür:

Çaresizlik,ümitsizlik ve inançsızlık.

Ravi rivayet ediyor:

    '' Müminin korku ile ümidi tartılacak olursa denk gelir '' Bu Resûlûllahın sözüdür.

Korku ve ümit ilâhi muhabbete ulaştıran iki kanattır. Aşırı korku, ümitsizliğe, aşırı ümit itaatsizliğe yol açar.

-Ne yapayım kaderim böyleymiş..

-İman olduktan sonra günah zarar vermez, benim kalbim temiz..

-Ben kaderimi kendim çizerim..

      Ruhun kalbden ayrıldığı zaman, dilin tutulduğunda, gözlerinin feri kesildiği an, gerçeği gördüğünde, çırpınman sana hiç bir yarar sağlamayacak. Takatın varsa söyle ben kaderimi kendim çizerim,  günah zarar vermez bana..

Resûlûllah s.a.v.:

     Kızına hitaben:'' Ey Fatıma amelinle kendini ateşten kurtar..'' buyurmakta.

     Şu dünyadan milyonlarca daha büyük ve geniş Cennete çağıran, mucizeler ihsan den parmağını kaldıran Resûle selât ve selam olsun.

Liege / 1988', 'İnsan emanetçidir, bir gün emanetini teslim edecektir. Emaneti taşıyanların şiarı: Sebep ve çarelerden olumlu sonuç alamayanlar, Cenab-ı Hak...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asiri-korku-asiri-umit-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklemek', 'seni-beklemek-memur-zeki-n2s3o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimde ne mektubun, ne de bir tek resmin  var

Duvarlarla konuşurum, aynamdaysa ismin var

Sığmıyorsun diye yüreğime sakın bana gücenme 

Çünkü o yürekte yine senin cismin var

Beklemek çok tatlıymış, murat alanlar diyor

Geceler tanıktır bak, Zeki halâ bekliyor

Kullar inanmasa da Tanrılar hep gülse de

O dönmüş kıblesine aynaya gülümsüyor

Uçurum kenarında bir ömür bekle desen

Bilirim ki yanımdasın, beklerim ölene dek

Çağırsan aşağıdan “gel-gel” diye el etsen

Hiç beklemem atlarım yanına gelene dek

Beklemek elbet güzel, ama “seni beklemek”

Umutla, heyecanla bir seveni beklemek

Tükense tüm umudum kalmasa heyecanım

Seni beklemek güzel, güzel seni özlemek

Şu yorgun bedenimle uçmak, seni beklemek

Bütün kötülüklerden kaçmak seni beklemek

Adresleri unutmak telefonu düşürmek

Çölde bir çiçek gibi açmak seni beklemek

Üşüyor mısralarım, titrer ellerim sensiz

Elini tutmayacaksam ben yaşarım bedensiz

Bir ömür bekle dersen beklerim geleceksen

Yetmezse vadem küsme ben beklerim kefensiz…

                                                            19.02.2006 04:14:25', 'Elimde ne mektubun, ne de bir tek resmin  var Duvarlarla konuşurum, aynamdaysa ismin var Sığmıyorsun diye yüreğime sakın bana gücenme  Çünkü...', ARRAY['Türk Edebiyatı','Şiir','Memur Zeki']::text[], 8.5, '{"poet":"Memur Zeki","poet_slug":"memur-zeki","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-beklemek-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hav (a)  Yaz', 'hav-a-yaz-ahmet-zekai-yildiz-omqnk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Meraklı soru

Yalancı yanıt

Üşüttüm

Hav (a)   yaz

Köpek balık

Deve kuş

San-at

Bal-in-aa

(O)   tel ayıları

Kir-alık ilişkiler

Taks(i)   tli uyku

Av-un-tuu

Ah vah

Oh yuh

(P)   ara pul

Ev-li dul

Tan(rı)      kul

Rep rak raks

Masa bardak

Rakı su

Rakursi

(I)  şık

İşaret parmağı

O

(D)   ağ

Uzaklardaki(sin)   

Sen

Be(n)   

B(iz)   

Ha-yat

Tabu(t)', 'Meraklı soru Yalancı yanıt Üşüttüm Hav (a)   yaz Köpek balık Deve kuş San-at Bal-in-aa (O)   tel ayıları Kir-alık ilişkiler Taks(i)   tli uy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hav-a-yaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İHANET”ten Öğrendiklerim Var', 'i-hanet-ten-ogrendiklerim-var-kerem-kayar-230vg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '…/Gözlerimde bugün daha bir sen var 

Hatta > seni yaşıyorum diyebilirim 

Kalbimin hizasında saklı kolyenin 

İçinde halen resmin duruyor mer/i şekilde 

Bir mazi var senden kalan / münebbih gibi 

Deruni asayişi bozuyor 

anlayamayacağın bir durum... /

_____İşte bu gecelerde

_____Mengene gibi mısralar 

_____Sıkarken Anlamsızlaştırıyor ne varsa 

Dudaklarının değdiği 

Vücudumun tüm ayrıntılarına 

Mil çekilmişçesine 

Sıcaklığını ve kokusunu muhafaza ediyor.../ 

Akrep > yelkovan ile yarışırken 

Kendimi kandıra biliyorum / seni sevmediğime 

_____Ama Tanrı''yı 

_____Kimi zaman susuyorum, 

_____Sükût ederken / kalanlarınıda tüketiyorum 

Ve…/… düşünüyorum > biliyor musun 

Ne yaşıyorsun diye / sorarsalar

Ne cevap vereceğimi…(. 

_____Sanırım yaşadığımı yanıtlayacak 

_____bir betimlemem kaldı. 

…/Kendi isteği ile tecavüze uğramış bir kadının 

Kendini aklaması için tuttuğu bogart şapkalı bir dedektiftim

Ve “Clint Easwood” sen oldun affedilmeyen / suçlu yoktu. 

_____Bu onlara vereceğim cevaptı...(

…/Sonra kendime dönüyorum 

Çok mu zor diyorum 

kalbimize sıkılan / kalleş ihanet kurşununu 

_____Çıkarmak 

Ve...

O an kendime > gülüyorum 

Adabımuaşeret kurallarını aşarak > 

Tanrı ile aramdaki mesafeyi sorguluyorum…/ 

Bana verdiği / ulvi sevgi bunu hak etti mi? 

Sen beni > Tanrı''nın kurallarına göre yargılamadın 

Sen beni > bir heliaste gibi yargıladın 

Sokrates’i zehirleyen / Atinalılar gibi davranıp 

Hilekâr gibi cezalandırdın_____.

_____Suçumu ben biliyorum 

_____Hayli sevmiştim

Sokrates gibi haklı bir şekilde cezalandım_____. 

Çok onurlu olan bendim / ölürken

Sanma ki / Azrail''e teslim ettim ruhumu_____. 

Benzetme işte_____.

Ne > Atinalıları

Ne > seni / mutlu edecek yetkim kalmadı

Çok maço oldum / bu sıralar öyle değil mi_____? 

Bakma mısraların ağırlığına 

ihanet öğretti_____ 

Cümle kalabalığının faydasını_____ 

Beyefendi lügatımı > rafa attım işte 

Sevmeye sınır koydum_____.

_____İhanet ettirmeyecek kadar sevmek 

Seviyesi > karınca kararınca 

Pardon ya / dedim ya > resmin halen kolyemde 

_____Senin saçların >> sarımıydı >>', '…/Gözlerimde bugün daha bir sen var  Hatta > seni yaşıyorum diyebilirim  Kalbimin hizasında saklı kolyenin  İçinde halen resmin duruyor mer/...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/ihanet-ten-ogrendiklerim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aşk', 'bu-ask-yilmaz-turkyilmaz-yae67', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Can cana,

Yan yana,

Ten tene bu aşk! 

Bu aşk iki kişilik.

Yani; sen kadar,

Yani; ben kadar...

Bu aşk alev alev,

Bu aşkta ateş var,

Seni beni kavuracak kadar...

Bu aşk seni sen yapar,

Bu aşk beni ben yapar,

Bu aşk; bizden nice kopyalar çıkaracak kadar! ...

Bu aşk tutku bazen sen gibi,! ? 

Bu aşk hüzün bazen ben gibi! 

Bu aşk dayanılmaz bazen; 

İçinde ayrılıklar barındıracak kadar...

Bu aşktı bizi içine çeken,

Bu aşktı boyumuzu aşan, belimizi büken.

Hep bu aşktı özlediğimiz! ? 

Bu aşktı burnumuzda tüten...

Bu aşk sırılsıklam şimdilik! 

Gözyaşlarımızla herkesi ıslatacak,

Fırtınalarıyla okyanusları kıskandıracak  kadar...

                                19.02.2006 - ANTALYA', 'Can cana, Yan yana, Ten tene bu aşk!  Bu aşk iki kişilik. Yani; sen kadar, Yani; ben kadar... Bu aşk alev alev, Bu aşkta ateş var, Seni beni...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-ask-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temennilerin', 'temennilerin-cetin-erdogdu-kaxl3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'eller kalkıp  yumruk olup''da tokuştukça havada

hep bir eksik vurdu kavgalar birbirine.

prometeusun ateşini, çalsak ta,

şiirin dizelerinde 

tutuşan sevdadan

başka bir şeyi ifade etmedi bize

demirin tavına vurduk 

geniş tabanlı çekiçlerle 

kızgın örsün üstünde

ki hepimiz gençliğimizi aradık bu tavda

sanki bütün yaşadıklarımız 

o zamandan kalmaydı

zaman eskidi

eskiyen zaman içinde

yıpranmış sevdalara söz sardık

kabuk bağlamış yaralara kavgaları

ne bir delikanlının başında sevda döndü 

ne kavak yelleri esti

bir döneme damgasını vurup

dar ağacının kemendinden rüzgar gibi geçti

on yedisindeydi 

sevdalar... 

kavgalar...

on yedisinde çarpıştı göğüs göğüs’e...

koynunda tek kişilik sevda yatmadı hiç

ve hiç bir zaman yalnız taşımadı sevdaları yüreğinde

ezilmiş…

sömürülmüş…

hırpalanmış… 

dövülmüş… 

sövülmüş… 

inkar edilmiş bir halkın mücadelesini yatırarak

işte bu sevdalardı hala dilimizde şarkı

yüreğimizde ezgi

gözümüzde hasret olan

bu sevdalardı idamlardan arta kalan 

yeniden açan gülleri

yeni canlara  taşıyan...

Gözümden süzülüp yanaklarımda asılırken hüzünler

bardağın saydam beyazlığında 

pul, pul parladı anasonlu yıldızlar

Ay sarhoştu,

gece sarhoş

söz verdik bir kere 

karanlıklarda çakmak çakmaya

söz verdik bir kere

tanrıların ocağından ateşi çalmaya

Söz verdik bir kere

yasa koyucuların mahkemesinden adalet çalmaya

Lanet okumadık hiç yaşadığımız Dünyaya

ki Dünya halkları kardeşti 

Dünya görüşümüzde

Ne üç, ne onüç, nede yirmiüç 

unutturamaz o vurgun yemiş yıllar bize

senin o dik duruşunda çelik bakışlarındaki cesaretini

Eren ilahların mahkemesinde

arkasında inzibatlar 12 Eylülü resmediyorlar

Eren''in kaşları çatık yüzünde öfke seli

dilinde belli ki onurun, cesaretin, yiğitliğin sesi 

ve salonu çınlatan tavizsiz sözleri

''Bir gün mutlaka sizin yerinizde halkımız olacak, sizi ve koruduğunuz düzeni yargılayacak doğru kararı verecek''...

temennilerini çoktan yükledik küfemize

Bu yüzden ağırdır küfemiz

bu yüzden taşınmazdır

çünkü senin temennilerin ezilen Dünya halklarının temennileridir.

Bu yüzden değerlidir...', 'eller kalkıp  yumruk olup''da tokuştukça havada hep bir eksik vurdu kavgalar birbirine. prometeusun ateşini, çalsak ta, şiirin dizelerinde  t...', ARRAY['Türk Edebiyatı','Şiir','Çetin Erdoğdu']::text[], 8.5, '{"poet":"Çetin Erdoğdu","poet_slug":"cetin-erdogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/temennilerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kediler', 'kediler-nevzat-ozkan-xteru', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şubat başı

mart henüz gelmedi.

ayı mı şaşırmışlar,

yoksa erken mi kızışmışlar.

akasya ağacının üst dalına tünemiş,

mırıldaşıyor

birbirinden azgın üç kedi.

dişisi beyaz renkli,

yer yer dumanlı.

cilveli mi cilveli

alımlı mı alımlı.

erkeğin biri sarı

kibar ve çapkın.

kumral olan hem saldırgan 

hem azgın.

sinsi kara,

tüylerini kabartmış

bekliyor aşağıda.', 'şubat başı mart henüz gelmedi. ayı mı şaşırmışlar, yoksa erken mi kızışmışlar. akasya ağacının üst dalına tünemiş, mırıldaşıyor birbirinden ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kediler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiras', 'i-htiras-mehmet-tas-6ect6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çatlak dudaklarım arzuya hasret

Öp beni

Öp beni yeniden yeşersin umudum.

Kıraç topraklar kadar hasretim suya

Öp beni

Öp beni,kansın arzuya dudaklarım.

Bir çift kolun hasreti içimi titretiyor

Sar beni

Körpe sıcaklığında kar gibi eriyeyim

Tazecik bir gonca açtın gönlümde

Sev beni

Sev beni de

Doğsun sabahlarca

Kararan akşamlara inat sevgilerim.', 'Çatlak dudaklarım arzuya hasret Öp beni Öp beni yeniden yeşersin umudum. Kıraç topraklar kadar hasretim suya Öp beni Öp beni,kansın arzuya d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ihtiras-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Araf', 'araf-hakki-karadeniz-4ngb6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve Tanrı buyurdu:Cennet de yok

cehennem de yok sana.

Araf''ta kalacaksın bundan böyle,

gülmek yok sana; sen sen oldukça.

Yüzün gülmeyecek bir daha,

ağlayacaksın yaşadıkça ve ölümden sonra.

Ağla hadi! 

Söndürebilir belki gözyaşların bu cehennemi,

ağla,sadece ağla.', 'Ve Tanrı buyurdu:Cennet de yok cehennem de yok sana. Araf''ta kalacaksın bundan böyle, gülmek yok sana; sen sen oldukça. Yüzün gülmeyecek bir...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Karadeniz']::text[], 8.5, '{"poet":"Hakkı Karadeniz","poet_slug":"hakki-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/araf-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutköy Durağında Bir Akşamüstü', 'umutkoy-duraginda-bir-aksamustu-mehmet-tas-yok4u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutköy durağında bir akşamüstü

Geç kalmış bir bestenin şarkısı çalınıyordu.

Notalar kırık dökük savrulurken yollara

Vuslata şahit olan yıldızlar gülümsüyor

Bulutlar sevincinden gözyaşı döküyordu.

Gül bahçesi olmuş ki, gönül seyri doyulmaz

Umut köy durağında bir akşamüstü

Bir adam gönül bahçesinden gül deriyordu.

Umutköy durağında bir akşam üstü

Ürkek bir ceylanın mahzunluğunda

Yılların tozlu aynasından yürekler

Akşamın alacalığına sevdalarını yolluyordu

Gök nurlu, yer nurlu, yüzler daha da nurlu

Gönülde ılık ılık bir sevda ki gururlu

Yeniden var olmanın sevinciyle dopdolu

Bir adam ve bir kadın öylece bekliyordu.

Umutköy durağında bir akşam üstü

Bir adam,bir kadın ve zaman duruyordu..

Hala görür ki geçen bütün sevda çekenler

Kaldırım taşlarına gölgeleri vuruyordu.', 'Umutköy durağında bir akşamüstü Geç kalmış bir bestenin şarkısı çalınıyordu. Notalar kırık dökük savrulurken yollara Vuslata şahit olan yıld...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umutkoy-duraginda-bir-aksamustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dumanı Üstünde', 'dumani-ustunde-yilmaz-turkyilmaz-dl0rc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevgi tomurcuğu patlıyor kendince! ? 

Aşk kol geziyor yine sürgünde.

Alev vaaar; alevcik var! 

Aşk çiniler pişirmiş ateşte...

Neslihanları özel kılmış bu töre! ? 

Ender bulunur şimdi yiğitler.

Avcunu yalasın; 

Gezsin; havasını alsın; 

Kendini değiştirsin sizleri kıskananlar...

Bu kadar anlamsız mı bu yaşam; 

Sevgisiyle sarmaş dolaş dönerken dünya? ...

Dalından düşen yapraklara bak! 

Bir deli rüzgar elinde oyuncak! ? 

Kader mi yani? 

Ordan oraya savrulmak...

Çiğ; şebneme karışmış; 

Gül''se bülbüle tuzak! ? ...

Güneş düşer içime,

Aydınlanır tüm gerçeklerim.

Beşikler sallanır,

Höyükler darmadağın Anadoluda.

Sevda harmanları savrulur; 

Antik kınalar karılır! 

Bin davul sesi duyulacak yakında...

Sevenin aslı sevgi; Nesli sevgi! ? 

Çağlardan öte sıtk-ı sadıklar koruyacak.

Bizi yeniden nazlı; narin analar doğuracak...

(Neslihan hanımefendiye)   09.02.2006', 'Bir sevgi tomurcuğu patlıyor kendince! ?  Aşk kol geziyor yine sürgünde. Alev vaaar; alevcik var!  Aşk çiniler pişirmiş ateşte... Neslihanla...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dumani-ustunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler İnce Bir Ağrı İçimde', 'geceler-i-nce-bir-agri-i-cimde-mehmet-tas-zpu98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceler uzun,geceler sessiz

Geceler bir ince ağrı içimde

Vay be can! 

Vay ki vay! 

Hasretin koymuyor beni

Iylım ıylım akıyor damarlarımda

Bir şarkı tutturup derinden derine

Yıldızlara anlatıyorum seni....

Vay be can! 

Gözlerin geliyor aklıma

Saçların,ellerin

Ve gülüşün.......

Bir yıldız düşüyor avuçlarıma

Solgun bir tebessüm takılıp dudaklarıma

Düşen yıldızı öpüyorum

Oy be can! 

Boşa takvimlere yükleme suçu

Zaman saçlarımda bir beyaz örtü

Gördüğüm düşlerin sonu boş çıktı

Vay be can

Hasretin koymuyor beni

Yıldızlar ağlıyor bu gece gökte

Sularda mehtaba bir hüzün çöktü

Seni anlatacak kimse yok şimdi

Beni bu hasrete mahkum etme can

Ellerin diline koyup gitme can

Bir şarkı çalıyor uzak bir yerde

Rüzgar kokusunu getiriyor saçlarının

''''Ben sana muhtacım.

Sana muhtacım can! ! ! 

Geceler uzun geceler sessiz

Geceler bir ince ağrı içimde

Beni yokluğuna alıştırma can

Her şeye tahammül eder de gönlüm

Ölümü yenmeye gücüm yetmiyor

Sensizlik ölümdür bunu bil gayrı

Azrail''den önce bir kez gel gayrı...', 'Geceler uzun,geceler sessiz Geceler bir ince ağrı içimde Vay be can!  Vay ki vay!  Hasretin koymuyor beni Iylım ıylım akıyor damarlarımda Bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/geceler-ince-bir-agri-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyecek Bu Sevda', 'bitmeyecek-bu-sevda-mehmet-tas-c35d0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belli ki bitmeyecek bu sevda

Ne vazgeçeceğim senden

Ne de sana yar olmak var kaderde

Bir tren rayı gibi ikimiz

Birbirimizle var olacağız

Bütün istasyonlar yakın olsa da

Biz bir olamayacağız....

Buram buram kanayacak içimizde hasret

Rüzgarlarla haberleşip

Rüzgarlarla selamlaşacağız.

Günbatımlarında

Aynı öksüz havayı koklaşacağız.

Belli ki bitmeyecek bu sevda

Ne sen geleceksin

Ne de ben cesaret edeceğim dağları aşmaya

Karlı dağ yamaçlarında

Kardelen çiçeklerinde sevişeceğiz.

Akreple yelkovanı gibi zamanın

Kavuştuğumuz yerde ayrılacağız.

Bitmeyecek bu sevda

Sıcaklığında ellerinin

Ellerim erimeyecek

Gözlerim yıldızlarda ışık ışık

Sonsuzluğunda alemin

Ruh olup kavuşacağız...', 'Belli ki bitmeyecek bu sevda Ne vazgeçeceğim senden Ne de sana yar olmak var kaderde Bir tren rayı gibi ikimiz Birbirimizle var olacağız Büt...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bitmeyecek-bu-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Karanlığımda', 'yine-karanligimda-hasan-cam-8qf4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ufka baktığımda, yüreğimi burkuyor kızıl gurup

Şehabete kapılıyorum o an, sanki içimde kor

Dağlıyor bağrımı, sönüyor meşalelerim, bir bir

Koca dağlar saklıyor, ardına alıyor güneşimi

Rüzğarlarım esmeye başlıyor birden, hoyratca

Sen gibi okşamıyor tenimi, yakmıyor yüreğimi

Kuşlar bile küsüyor, çekirgeler alıyor yerini

Yıldızlar süslüyor mehtabımı, yine karanlığımda

Bir hayat, can bıraktı ardında, ne bahar, ne kışta

Mevsimleri yerinde saydı çiçeksiz, yolları yokuşta

Kumrular ağlıyor, zaman daralıyor her kalp atışda

Hüzünleri yaşıyor yüreğim, her sabah doğuşunda

Rüzğarlarım esmeye başlıyor birden, hoyratca

Sen gibi okşamıyor tenimi, yakmıyor yüreğimi

Kuşlar bile küsüyor, çekirgeler alıyor yerini

Yıldızlar süslüyor mehtabımı, yine karanlığımda

17 02 2006

Ümraniye  İstanbul

[email protected]', 'Ufka baktığımda, yüreğimi burkuyor kızıl gurup Şehabete kapılıyorum o an, sanki içimde kor Dağlıyor bağrımı, sönüyor meşalelerim, bir bir Ko...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yine-karanligimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrılar Dans Eder Yüreğinde', 'tanrilar-dans-eder-yureginde-selahattin-yetgin-7v8mw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğinin sığ menzillerinden hicranlı bir sevdaya yürüyorum

Göğsümdeki arsız bir zamanla, düşlerimi salıyorum suretlerine

Sevda güle vuslat sızısıyla yürürken ruhumun izini sürüyorum

Eksik yaşadığım ne varsa yaşamak istiyorum kutsal yüreğinde

Şiirlerimin nöbeti bitince yosun gözlerini özlemekten vazgeçeceğim. Hasret türküme saz olan yüreğinin mızrap dokunuşlarını başka gözlerden bekleyeceğim. Acımı içime gömüp, biçare yalnızlığıma sövüp, bir daha denizlerden gelişini istemeyeceğim. Seni hatırlatan şarkılar susunca, gönlüm çaresizliğin bastonuna tutununca su damlam, bu acılar atlasında, yüreğinin coğrafyasında yaşamayı terk edeceğim.

Anıların fırtına kucaklaşmasını yüreğine dolayınca, kare kare anılardan en içlisine ağlarsın. Islanmayı özleyen yanaklarına sızınca yaşlar, ağrır sol yanın. Oysa, acılardır şerbetindeki kızılcık, sevdadır içini kemiren umarsız kılçık. Hayata gülücükler beleyerek, ruhuna başka sevda urbası biçerek ve kaderine kahrederek döner bu anlaşılmaz küre, günlerin yalan ve çürük tespihini hışımla çekerek.

Her yaşanılan anla, arsızca geçen zamanla bir çığ topu oluyorsun sen dağlarımda. Eksik yaşadığım ne varsa, ne varsa sevmenin tadına varılamamış bizimle kalsın, bizimle tamlansın istiyorum. Öfkemin alacasına gözlerin düşüyor gönlüm azıksız kalınca. Örümcekler imparatorluğunun ormanlarına dalıp, ateşlenmeleri unutan taş ocaklarında buluyorum seni. Yüreğim ellerinde paramparça, gönlüm dilindeki şarkılarla çocukça, bedenim bedeninde kasırgalara karışıyor yağmurlarla.

Kimi, yitirilmiş ve örselenmiş düşlerimi salıyorum dönüşümsüz suretlerine. Hiç kapanmayacak davalar iliştiriyorum dosyama. Gözlerin ve dudaklarının yalvarışında demir kapılar kapanıyor suratıma. Kilitleniyorum yüreğine, vurgun ve vakitsiz sevdalar ve birbirimizi düşündükçe bizi farklı limanlara götüren anılarla, damla damla çoğalan sancılarla okyanuslar arıyoruz kendi şiirimizi okuyacağımız. O hırçın dalgalar üzerinde sıra sıra yürek coşkularımızı okuyup, şiirlerimizdeki kutsal damlacıklarla yeni denizler, okyanuslar oluşturmak istiyoruz.

Gülüşlerinin kolları sarınca gövdemi, bedenimdeki bütün acılarım yüzyıl ötelere gider ansızın. Tutulan dilimi kahkahalarına yükleyerek, bitimsiz bir aşk filminin seyrine dalarım. Yüreğinin mavi perdelerinden sevda sözcükleri akarken, ben gözlerinin kuyularında susuzluğumu gideririm. Kıyımlara, tufanlara ve sancılarıma son verir, dudaklarının mevsim çiçekleriyle başka bir dünyanın sevdalısı olurum.

Beklediğimiz mutluluk kutlamalarında sensiz bir yıldız gülüşü daha düşerdi boşluklardan kayarak. Gönlümüzden geçen, ancak gururu seçen kelimelerimiz kor yüreğimizin zindanlarında sancılara karışırdı. Kadehler birbirine çarpıyordu o deniz ışıltılı meyhanede. Unutuluşa boşalırken zaman, dilindeki kahır şarkıları hep aldanışa okunuyordu. Akrep sinsi düşlere yol alırken sarhoş fısıltılar gün ışıklarıyla yeniden dansa duruyordu. Dizginlerini bıraktığımız bir sevişmenin en mahrem yerlerinde köpüklü denizler doluyordu odamızdan içeri ve biz karanlıklarda bile birbirimizin ellerini buluyorduk.

Güneşin hiç batmadığı efsunlu gözlerinde yontun var oldukça, kıyında kaygısız çiçeklerin, koparılmamış, karalanmamış şiirlerin olacağım ben. Tanrıların gözlerine sürdüğü rimelle, dudaklarına dokunduğu elle, bedenine bahşettiği asaletle göz alıcı bir dünya gibi duruyorsun yüreğimde. Defalarca biçimlendirilmiş, dünyanın bütün çocuklarının sevinci yüklenmiş, en bitimsiz seraplarla gönlü donatılmış, emsalsiz bir resimsin sen. Yeryüzünün bütün cennet kuşlarını omuzunda taşıyor, bukle bukle kıvır saçlarında hayal ötesi imparatorluklar aşıyorum ben.

Hiç yaşanmamış bir bahar duruyor gönlümün yeşertilerinde. Bülbülün aşığı gül, gülün sırdaşı bülbüldür her devirde. Yüreğim nicedir rehinlerde ve bir sevdanın tanığıydı. Öpüldüğüm zaman ördek yanaklarımdan yırtılırdı sesim, kesilirdi nefesim. Uyanışlarımın zemherilerinde sözümü sakınmaz, hiçbir gelgitten yıkılmaz, en çarpıcı şiirlerle onulmaz olurdum ben. Altı üstü sevda yasası ve kurşun bile döksen siliniyor yazısı. Sesi olmayan, soluğu sevdayla buluşmayan hiçbir tümce şiir, konuşmanın sağılmadığı, hükümsüzlüğün yaşanmadığı hiçbir sevda aşk değildir.

İzmaritlerin biriktiği çingene sepetlerinde ve bu ‘alım satım dünyasında’ yitik düşler taşırız gönlümüzde. Suya istemeden karışan sevinçlerin yutkunmasında hiç durmadan çevrilir gönlümüzün sarı sayfaları. Ölümlerde tanığımız olmaz, mızrapsız sazımız sevdikçe susmaz, anlamlar, sesler ve görüntülerle dönen bu yer kürede biliyorsun ki şarkılar olmadan yaşanmaz. Zamandır onulmaz bağlarımızı onaran. Bazen bir sözcük geçer usundan ve şiire dönüşür özün. Beyaza düşülen notlarla kimi bir hüzne, kimi de bir gülümsemeye dokunarak yüreğinin şarkısını bestelersin uzak kentlerde.', 'Yüreğinin sığ menzillerinden hicranlı bir sevdaya yürüyorum Göğsümdeki arsız bir zamanla, düşlerimi salıyorum suretlerine Sevda güle vuslat ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tanrilar-dans-eder-yureginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah canım memleketim', 'ah-canim-memleketim-mikdat-bal-det6e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çiçekler beyaz kızıl

Ah canım memleketim

Arılar vızıl vızıl

Ah canım memleketim

Çayırlar yeşil yeşil

Her taraf ışıl ışıl

Uyursun mışıl mışıl

Ah canım memleketim

Kırları diken çalı

Çimenler yeşil halı

Her balı anzer balı

Ah canım memleketim

Duman yüzer karadan

Güneş doğar aradan

Nasıl çıktım oradan

Ah canım memleketim

Pınarlar pırıl pırıl

Çayları şırıl şırıl

Uykusu mırıl mırıl

Ah canım memleketim

Duru suları akar

Ormalar çıra kokar

Ağaçlar göke bakar

Ah canım memleketim

Erimez karı buzu

Yaylada koyun kuzu

Çobanlar verir tuzu

Ah canım memleketim

Bitmez telaşı işi

Başkadır yazı kışı

Bulunmaz onun eşi

Ah canım memleketim

Dar yollar kıvrım kıvrım

Onlar tanımaz evrim

Araba yolu devrim

Ah canım memleketim

Nakrat

Sensiz her geçen  günüm

Ağlarım inim inim

Sen yarınım, sen dünüm

Ah canım memleketim', 'Çiçekler beyaz kızıl Ah canım memleketim Arılar vızıl vızıl Ah canım memleketim Çayırlar yeşil yeşil Her taraf ışıl ışıl Uyursun mışıl mışıl...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ah-canim-memleketim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyes', 'piyes-husam-hasret-mzohs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birinci perdede söyleşi titiz

Bir ömrü yansıtır düğümlü nesne

Ancak bir olayla başlar bu roman

Her bölümde betim yeni olacak

İkinci perdede açıklanır giz

Hakikat yayılır, kaybolur fitne

Kaygısız canlanır o eski orman

Doğanın gözünde yaşam bulacak

Üçüncü perdede her bir şey temiz

Mutlu bir sonuçla kapanır sahne

Ölmez konusunda kökleşir zaman

Değerine karşı değer alacak', 'Birinci perdede söyleşi titiz Bir ömrü yansıtır düğümlü nesne Ancak bir olayla başlar bu roman Her bölümde betim yeni olacak İkinci perdede ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/piyes-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-ada-ada-sk776', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen beni,

Benden iyi bilemezsinki

Duygularımı içimde

Göremezsinki

Neyi neden yaptığımı

Sezemezsinki

Sen seni içimden

Silemezsinki

Hatıralar her yanda

Görmüyorsunki

Zincir olmuş dertlerim

Kırmıyorsunki

Umutlarım yok oldu

Umut vermiyosunki

Sen beni ben gibi 

Sevmiyorsunki

İnatcııı Keçiii', 'Sen beni, Benden iyi bilemezsinki Duygularımı içimde Göremezsinki Neyi neden yaptığımı Sezemezsinki Sen seni içimden Silemezsinki Hatıralar ...', ARRAY['Türk Edebiyatı','Şiir','Ada Ada']::text[], 8.5, '{"poet":"Ada Ada","poet_slug":"ada-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sitem-232-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme İşte', 'gitme-i-ste-ada-ada-h7y9m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her duyguyu 

En sıcağından yaşadık senle

Ama daha yaşanacak

Çok şey var önümüzde

Ömür dediğin 

Geçmek bilmez kahır işkence

Sen yoksan bende yokum

Artık bu şehirde

En sevdiğimiz şehirdi 

İstanbul ikimizinde

Martta gidicem demiştinn

Gitmeeee İştee Gitmeeee', 'Her duyguyu  En sıcağından yaşadık senle Ama daha yaşanacak Çok şey var önümüzde Ömür dediğin  Geçmek bilmez kahır işkence Sen yoksan bende ...', ARRAY['Türk Edebiyatı','Şiir','Ada Ada']::text[], 8.5, '{"poet":"Ada Ada","poet_slug":"ada-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gitme-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşralı', 'tasrali-gultekin-toga-dwdxe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Taşralıyım,eller nasır,bel bükük,

Teri haksızlara ark edilenim..

Derdim sayısızdır,çilem çok büyük,

Ömrü acılarla gark edilenim..

Bir dem süremeden ömür tükendi,

Çocuklarda aynı ateşe yandı,

Seçimden seçime olup efendi,

Sonra senelerce terk edilenim..

Dibe ışık vermez başın çırası,

Lakin bizi bulur isi,karası,

Öz Yurdunda örf adedi,töresi,

Üç beş kefereye sirk edilenim..

Bazen somun olup,bazen civata,

Malzemeyim roman,güzel sanata,

Havyar yiyip,viski içen su zata,

Sosyal içerikli kürk edilenim..

Sentezi duyulur sen hele sayda,

İlimden,teknikten görmedik fayda,

Okulsuz,doktorsuz,yolsuz bir köyde,

Askerlik yaşında fark edilenim..', 'Taşralıyım,eller nasır,bel bükük, Teri haksızlara ark edilenim.. Derdim sayısızdır,çilem çok büyük, Ömrü acılarla gark edilenim.. Bir dem sü...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tasrali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarım Geç Kalmazsın', 'umarim-gec-kalmazsin-ali-taskiran-u0vgp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yalnızlığın sessizliğinde

her nasılsa birgün apansız

gerçeğin farkına vardığın an

buz gibi olur kaskatı donarsın

ve sanki şoklanmış hissine kapılırsın

birşeyler acıtır kanatır içini

ta derinden 

haykırır bağırırsın 

avazın çıktığı kadar

ve birden şimşekler çakar içinde

yanlış olan  ya da eksik olan  neydi diye 

sorarsın kendi kendine

hesap kitap işi derken

batıl inanç ve cehalet perdelerini

çekip atarsın üstünden

ve sonunda koşarsın 

her neyse ona', 'yalnızlığın sessizliğinde her nasılsa birgün apansız gerçeğin farkına vardığın an buz gibi olur kaskatı donarsın ve sanki şoklanmış hissine ...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkıran']::text[], 8.5, '{"poet":"Ali Taşkıran","poet_slug":"ali-taskiran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/umarim-gec-kalmazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düdük', 'duduk-gultekin-toga-z6noy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimisi düşüncem,fikrim var sanır; 

        Aslında düdüktür öttürülüyor.

        Üç buçuk pahaya adam utanır,

        İnancı, vicdanı sattırılıyor.

        Yarına uzanmaz küf temelleri,

        Zulüm gitarının paslı telleri,

        Hainin,alçagin pis emelleri,

        Kutsal dava diye yutturuluyor..

        Alev ayrı düşer gibi bir közden,

        Gerçek kahramanlar gizlenmiş bizden,

        Tüm ayrı duranlar kaynaktan özden,

        Kahramanlar diye yutturuluyor.

       Garip kalmış hakikate uyanlar,

       Baş tacı edilir çalıp soyanlar,

       Aklımı kiraya vermem diyenler,

       Zindana kodese attırılıyor,

      Önce sağ sol  ne ateşmiş o öyle,

      Sağduyudan zerre varmıydı söyle,

      Hak mıdır başını kumlara kuyla,

      Kardeş kardeşine çattırılıyor,	

        Kimi küser adı dargına çıkar

        Kimi anlar adı yorguna çıkar

        Kimisinin yolu sürgüne cikar

        Katmerli acılar tattırılıyor..

        Sentezi nefreti kovup boşayak,

        Kalbimize yalnız aşkı döşeyek,

        Koymazlar ki kardeş kardeş yaşayak,

        Aramıza nifak kattırılıyor..', 'Kimisi düşüncem,fikrim var sanır;          Aslında düdüktür öttürülüyor.         Üç buçuk pahaya adam utanır,         İnancı, vicdanı sattır...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/duduk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekil Aşklar', 'tekil-asklar-mehmet-korkmaz-lwrgh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tekil aşklar gibi

 İşsizliğimiz

 Sessizliğinde 

 Kendini çoğaltan

 Çoğunluğuz

Sıkı sıkıya sarılsak da

Kürek saplarına

Günü kurtarmaktır

Derdimiz 

Düşer bandajı yaramızın

Yama tutmaz cebimiz

 Astar 

 Eskimiş

 Bin sitem indirsek de 

 İşsizliğin yırtık yüzüne

 Akşam sofralarında 

 Çoğalır sesimiz de 

 Tekil aşklar yutkunuşu

Değişmiyor bir başına

Sesli konuşmak

Alanları  doldurup

Sesleri çoğaltmayınca

Kazmalarken

Yerin bağrını

Bir inşaat çukurunda

Yağmura tutulur terimiz

Buharlaşır hıncımız

Yeryüzüne yeniden yağarız

Bir buluşsa damlalarımız

Sel olacağız', 'Tekil aşklar gibi  İşsizliğimiz  Sessizliğinde   Kendini çoğaltan  Çoğunluğuz Sıkı sıkıya sarılsak da Kürek saplarına Günü kurtarmaktır Derd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Korkmaz']::text[], 8.5, '{"poet":"Mehmet Korkmaz","poet_slug":"mehmet-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tekil-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmedim', 'degismedim-gultekin-toga-mksxu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tenbih,nasihatin suda ki yazı,

Bin musibet gördüm değişmedim ben..

Bela tavşan oldu ben de bir tazı,

Peşinde iz sürdüm değişmedim ben..

Aklımı hapsetmiş sanki dört duvar,

Beynim güzelliği,iyliği kovar,

Nefsimin elinde davarım davar,

Bir noktada durdum değişmedim ben..

Anlamazsın beni sıradışıyım,

Mekanım bir nokta süre dışıyım,

Kimse emin değil körün taşıyım,

Çok gönüller kırdım değişmedim ben..

Yalan değil hakikattır bu sözler,

Benden ateş aldı, tutuştu közler,

Sentezi inatla yolumu gözler,

Allah etsin yardım,değişmedim ben..', 'Tenbih,nasihatin suda ki yazı, Bin musibet gördüm değişmedim ben.. Bela tavşan oldu ben de bir tazı, Peşinde iz sürdüm değişmedim ben.. Aklı...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degismedim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Aklımdasın....', 'aklimdasin-sair-salma-z5pxa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''''Çok sevdiğim..ve değer verdiğim  Gazo''dan  ''''

Hasretini çekerim.... 

Bağrı yanık türküleri söyleyememenin..... 

Birde senin hasretini çekerim..... 

uzaklarda oluşundandır. 

Simsiyah gecelerime.. 

beyaz benekler olursun. 

Çoğalır....çoğalır kapatırsın karanlıklarımı. 

Hasretliğini çekerim..... 

mesafelerini kısaltmak istediğim.....sensizliğin. 

Birde senin hasretini çekerim..... 

burcu..burcu özlemlerle. 

Yangınlarımın yalazları çizerken seni...... 

artar da...artar yakışların...sımsıcak ve acımtrak. 

Bir senin hasretliğini çekerim... 

adını hasret koyduğum için. 

Zeminsiz yollardan gelmektedir...vuslatlarım. 

belki bir hazirana rastlar....belkide bir eylül e. 

Hasretini nasıl çizersem çizeyim..... 

her bitiminde benzer şekli......gül e. 

Yorgun yılların....çizgileri sert olur..... 

sevdalı yüreğimde. 

Hasretini çekerim...can parçam... 

Kazılmışsın....Yazılmışsın....Aklımdasın. 

.................Gazanfer.....17/02/2006...saat:04.12...seni seviyorum :)))', '''''Çok sevdiğim..ve değer verdiğim  Gazo''dan  '''' Hasretini çekerim....  Bağrı yanık türküleri söyleyememenin.....  Birde senin hasretini çeke...', ARRAY['Türk Edebiyatı','Şiir','Şair Salma']::text[], 8.5, '{"poet":"Şair Salma","poet_slug":"sair-salma","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aklimdasin-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünden Bugüne', 'dunden-bugune-salih-erdem-gbdem', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir dost görünse dünden çıkıp

değişen bir şey yok

hep bıraktığımız gibi

zamanı

……….sonsuza uzatıp gidiyoruz

dedikodu

…………lakırdı

…………………geçim derdi

ve çoklarının kabaran alın damarlarında atar

memleket meselesi

zaman duruyor

…………………o fotoğraftaki gibi

gün tepelerden aştı mı 

akşam bir başka iner şehre

işçiler evlerine döner

kükürt dumanları soluyup

kimi sakalını kaşır

kimine şarkı türkü yeter

kimine dedikodu

avutamam gönlümü

alıp başını gitmek ister

yol bilmez

…………..dur bilmez

önce boş sokaklarda adım adım

kederlenirde cansız taşlar

garipliğimi kimse bilmez

…………………….adım adım dağılırım

yolum barlara düşer

bira tonik votka

çiklet yarıştırır gibi çeneler

duymadan biri diğerini

sözde dostluklar

yalnızlıkları bir daha

……………...bir daha deşer

oturup taburede

bilmediğim diyarlara giderim

ölgün neon lambaları

gizler yalancı yüzleri

………………arsız gözlerden

konuşmalardan anlarsınız

bilinmez diyarların

………………yaşanmamışlarını

gitarın telleri titreşir

ince sarı başaklar dökülür

içimdeki sevgi hasrete

…………..…bekçilerin gözleri geceye büyür

kafesli pencerelerde bir gelin gölgesi yürür

binyıllık şehrin içinde

………………….gölgeler geçmişe

yaşlı gözleri meraklı

kuş kalbi korkulu

işi gücü olmayanlar bile uykuda

çarşaflar buruşuk sarhoş

çocuklar mışıl mışıl

televizyonda gece yayını

bildik melodileri çalıyor

saatin tiktakları yirmi sekiz şubat başını

çöp bidonlarını kediler rahat bırakmıyor

rahatlığın aklımı

yollar yumuşacık şimdi

…………………….duymuyor

yanağındaki ağır aksak adımları

geceler ateşten bir şal

dolanır boynuma

………..sıkar anılar

kaç adımlık gün var ki dünyada

daha ötesini sorma yar

19.02.1995-03.00 Safranbolu', 'bir dost görünse dünden çıkıp değişen bir şey yok hep bıraktığımız gibi zamanı ……….sonsuza uzatıp gidiyoruz dedikodu …………lakırdı …………………geçi...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/dunden-bugune-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şok', 'sok-gultekin-toga-ftw78', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gün başka çeşit şok yaşıyorum,

Aklın alışması kolay değil ki..

Ellerim çenem de dolaşıyorum,

Bu çıkan cenaze, alay değil ki..

Çenem de efkarın güçlü kolu var,

Ümit güllerime vurur dolular,

Ummadığım dağa kar yağıyor kar,

Tanıyıp bildiğim olay değil ki.

Durum Hakk´´a ayan akıl ötesi,

Yüksel nolur yüksel sabrın çıtası,

Gönül tellerin de ağıt notası,

Köroğlu barıyla,halay değil ki..

Sentezi belli ki örste çeliksin.

Çaresiz olana katlanacaksın,

Acı ilaçlardan tatlanacaksın,

Bu şok mevsimidir balay değil ki', 'Her gün başka çeşit şok yaşıyorum, Aklın alışması kolay değil ki.. Ellerim çenem de dolaşıyorum, Bu çıkan cenaze, alay değil ki.. Çenem de e...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vicdan Rahatlığı', 'vicdan-rahatligi-rahim-recep-akdora-wrlff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '……………………Matbaada çalıştığım işçi arkadaşlarıma

Son ana kadar bir umut beklentisi

Biten umudun acısıydı biriken gözlerinde

Bir insaf belki çorap olurdu çocuğunun ayağına

Bir insaf belki bir gömlek olacaktı bayramlık

Belki bir pantolon

Belki küçük bir harçlık

Olmayan insafın gelmeyen umudu

İşçi arkadaşlarımın bekleyişinde.

Yılların haksızlığıdır tokun açı anlamama gerçeği

Emek bir gülümseyiştir insafsızlığın boyalı suratında

İyi niyetin bedeli yorgunluk, alın teri dökmek

Patron duyarsızlığı bir kambur adaletsizliğin sırtında

Mehmet, sen yine de kuşgözünü iyi mıhla

Sen, Ertan düzgün dola kutuna bandını

Bekir dikkatli vur çekicini mıhına iz yapmasın dosyaya

Çalışmak erdemdir Hasan sakın kirletme işçi adını

İşçinin teri içkisidir işverenin

Yada bir banknot dansözün göbeğine yapıştırılan

Yada bir orospunun bir gecelik bedeli

Yada kumar masasına umursamadan saçılan

Sen tutkalını iyi sür gözlüklü arkadaş, Servet

Sen Doğan, Erdoğan iyi kıvırın kenarlarını bandın

Sen de Hüseyin kutunun köşelerine dikkat et

Ahmet sen de boynuzun düzgün oynat kırışık kalmasın

Kesin şu yemek kavgasını işçi yemese de olur

Görevimiz çalışmak, üretmek, çok üretmek

Yeterin artık konuşmayın şu para konusunu ne olur

İşçinin bayramı mı olurmuş, yeter bize tuzla-ekmek

Yine geldik, yine geleceğiz, tekrar geleceğiz

Bir yazgıdır işçiye çalışmak, alın teri dökmek

İçki mi, çeşmede su bol

Dansöz mü, bir dergi al 

Malzemesi kadın eti, pezevenklerin ürettiği

Futbol mu, bir oyundur

Düşüncelerimizi körelttiği

İşçi misin  hakkın yok düşünmeğe

Senin en bitmez hakkın üretmek

Neyine gerek senin yemek

Haydin çalışalım

Bizi beklemekte mıhlar, çekiçler

İtiraz etmeden yaşamaya alışalım 

Vicdan rahatlığı bize yeter

23 Şubat 2002

Ceylan albüm', '……………………Matbaada çalıştığım işçi arkadaşlarıma Son ana kadar bir umut beklentisi Biten umudun acısıydı biriken gözlerinde Bir insaf belki ço...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/vicdan-rahatligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen + Ben = İkimiz; Biz', 'sen-ben-i-kimiz-biz-ali-taskiran-pheh8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen ve ben

her ikisi de 

tam istediğim gibi

hem özel

hem de evrensel 

özde bir

bilgelik sevgisi yolunda 

meçhul birer yolcuyuz 

hayra ve şerre giden

belki birbirimizin içinde

herşeyiz

belki de hiçbirşey değiliz

ama biz 

kimiz

neyiz

anlamı ne yaşadığımızın 

ve de öldüğümüzün...', 'sen ve ben her ikisi de  tam istediğim gibi hem özel hem de evrensel  özde bir bilgelik sevgisi yolunda  meçhul birer yolcuyuz  hayra ve şer...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkıran']::text[], 8.5, '{"poet":"Ali Taşkıran","poet_slug":"ali-taskiran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-ben-ikimiz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitirilen', 'yitirilen-fitnat-sahan-zy6ua', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluğum işte şu ağaçta asılı kaç zamandır,

ve ben kaç zamandır gülmüyorum,biliyor musun

sen gideli uzun zaman olmuş,baharı gördüğümüz pek yok

bütün çiçekler kurumuş.

işe yaramaz bir paçavra gibi kullanıyorum şimdi yüreğimi..

önüme gelene dağıtıyorum.

bir gün onu da asmak geçiyor ya içimden bir erik ağacına; 

sonra aklıma geliyorsun kıyamıyorum sana..

iki adım ötede..

gözüme bir ağaç daha ilişiyor,

ağaçtan düşen çaresizlik mi

eğip alıyorum sanki benimmiş gibi

şimdi sen yerine çaresiliğime sarılıp,yalnız ona ağlıyorum...

(12.3.04)', 'Mutluluğum işte şu ağaçta asılı kaç zamandır, ve ben kaç zamandır gülmüyorum,biliyor musun sen gideli uzun zaman olmuş,baharı gördüğümüz pek...', ARRAY['Türk Edebiyatı','Şiir','Fitnat Şahan']::text[], 8.5, '{"poet":"Fitnat Şahan","poet_slug":"fitnat-sahan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yitirilen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-volkan-i-ncel-tiplx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünüyordum Yalnızlığımı

.......................................

Bir Masa,Bir Dolap

Bir Kitap Var

Ha Birde Lamba İle Dört Duvar

Artık Yalnız Değilim', 'Düşünüyordum Yalnızlığımı ....................................... Bir Masa,Bir Dolap Bir Kitap Var Ha Birde Lamba İle Dört Duvar Artık Yalnı...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizim-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yaşamlık', 'i-ki-yasamlik-fitnat-sahan-cgq77', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iki yaşamlık canım kalmış,

kime fark ettireyim  kendimi..

görmeyen göz..

duymayan kulak misali..

yitirdim artık tüm hayallerimi..

adresim kayıp..

telefonum kesik..

istemiyorum sormasınlar beni..', 'iki yaşamlık canım kalmış, kime fark ettireyim  kendimi.. görmeyen göz.. duymayan kulak misali.. yitirdim artık tüm hayallerimi.. adresim ka...', ARRAY['Türk Edebiyatı','Şiir','Fitnat Şahan']::text[], 8.5, '{"poet":"Fitnat Şahan","poet_slug":"fitnat-sahan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iki-yasamlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Kalbe Yüz Sürer', 'akil-kalbe-yuz-surer-yasemin-sezer-tulgar-zl0x0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanrılar yaratıldı insanlarda

Doyumsuz zihinlere vitamin niyetine

Kırmızı, pembe, sarı doğdu

Devran tutan güneşlerde

İnsan olanın tuttuğu cevher

İki nokta arası doğru işte

Akıl kalbe yüz sürer

Sayısız cümbüş seferinde

Asıl olan aşka döner

Kitab-ı mucize de

Bin ayetten duayı

Okutur semah niyetine

19.02.06', 'Tanrılar yaratıldı insanlarda Doyumsuz zihinlere vitamin niyetine Kırmızı, pembe, sarı doğdu Devran tutan güneşlerde İnsan olanın tuttuğu ce...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/akil-kalbe-yuz-surer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izdırap', 'izdirap-huseyin-celik-9ckcc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Izdırap veriyor bana 

Alıp verdiğim her nefes 

Aşkın o işveli saatlerinden 

Gün gelip bıkacağımızı

Nerden bilirdim ey sevgili

Nereden bilirdim

Hani sevecektik birbirimizi

Nerde gece karanlığı gözlerin

Kaybolup giderken sigaramın dumanı

Gözlerime bakamaz artık

Mehtapsız gece karanlığı gözlerin

Ellerin o yumuşak ellerin

Şimdi kim bilir kimlerin avucunda

Kimler okşuyor siyah saçlarını

Kimler öpüyor bal dudaklarını

İçtikçe kaybolan aklım

Sevdikçe karışan  zihnim

Şimdi gelsen de girsen şu lanet kapıdan

Sarhoş bedenimi kaldırsan şu masadan

Bulanık gören gözlerime bakıp

Ellerini uzatsan ellerime

Hadi gidelim desen hadi gidelim

Kaldırsan masadan çıksak oradan

Bütün acılarımı bıraksam orda

Hatırlamasam o lanet günlerimi

Yine sevda dolu aşkı yaşasak

Bir daha ve bir daha

Gözlerine baksam

O yumuşak ellerinden tutsam

Saçlarını okşasam

Ve o halimizde hep kalakalsak.', 'Izdırap veriyor bana  Alıp verdiğim her nefes  Aşkın o işveli saatlerinden  Gün gelip bıkacağımızı Nerden bilirdim ey sevgili Nereden bilird...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/izdirap-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-huseyin-celik-hg1qs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessizce ağladım sessizce yandım

Bu ne biçim acı ne biçim kader

Sevgilim ben sana doymadan öldüm

Bu ne biçim acı ne biçim kader

Yollarıma yağdı kar ile boran

Benden başkasına olasın haram

Merhemsiz şifasız kanayan yaram

Bu ne biçim acı ne biçim kader

Aşkını saklayan yürek taş olsun

Sana çiçek veren eller kırılsın

Endamına bakan gözler kör olsun

Bu ne biçim acı ne biçim kader', 'Sessizce ağladım sessizce yandım Bu ne biçim acı ne biçim kader Sevgilim ben sana doymadan öldüm Bu ne biçim acı ne biçim kader Yollarıma ya...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kader-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Yar', 'guzel-yar-huseyin-celik-eu5to', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göçmen kuşlar gibi oradan oraya

Mevsim mevsim dolaşırım güzel yar

Bazen dağ başında bazen ovada

Yoruldukça konaklarım güzel yar

Şu mavi göklerde gönlüm şenlenir

Vadilerde ırmaklarda dinlenir

Yüzlerinde çiçeklerin allanır

Gözlerini özlemişim güzel yar

Ceylan gibi bakan gül gibi kokan

Özlerim ben seni sevgilim her an

Aşkın ateşiyle kalbimi yakan

Sözlerini özlemişim güzel yar,', 'Göçmen kuşlar gibi oradan oraya Mevsim mevsim dolaşırım güzel yar Bazen dağ başında bazen ovada Yoruldukça konaklarım güzel yar Şu mavi gökl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-yar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-huseyin-celik-5ou7o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevinçten gözleri parlayan güzel

Bir haber mi aldın sevgili yarden

Gözlerin mektubu çok mahzun süzer

Bir haber mi aldın sevgili yarden

Titredi ellerin yüreğin coştu

Heyecanlı halin ne kadar hoştu

Mektuba sarılman ne güzel işti

Bir haber mi aldın sevgili yarden

Mektubu açınca öylece kaldın

Bir yaprak misali sarardın soldun

Sevinçli haldeyken şimdi ne oldun

Bir haber mi aldın sevgili yarden

Düşmesin elinden ne zarf ne kağıt

Ağlamasın gözlerin nedir bu ağıt

Toplanmışlar başına verirler öğüt

Bir haber mi aldın sevgili yarden', 'Sevinçten gözleri parlayan güzel Bir haber mi aldın sevgili yarden Gözlerin mektubu çok mahzun süzer Bir haber mi aldın sevgili yarden Titre...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mektup-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık aşk', 'satilik-ask-volkan-i-ncel-9j5rt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uğruna öldüğüm sen miydin  güzelim

Rüzgarlar esmişte dökmüşsün gazelin

Dalgalar vurdukça kıyılar gezerim

Sevdandan kurumuş yaprak gibiyim

Aklım artık almıyor seni mi sevmişim 

Allah yalanı sevmez pek de güzelmişsin

Parayı pulu aman pek severmişsin

Evimi banka yapsam yine gelir misin

Boşuna içmişim hep boşa delirmişim

Azıcık param olsa zaten gelirmişsin 

Namusu iffeti sen böyle bilmişsin

Birde pavyon açsam bana döner mi sin.', 'Uğruna öldüğüm sen miydin  güzelim Rüzgarlar esmişte dökmüşsün gazelin Dalgalar vurdukça kıyılar gezerim Sevdandan kurumuş yaprak gibiyim Ak...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/satilik-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ne Güzeller Gördüm', 'ben-ne-guzeller-gordum-huseyin-celik-0erxv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimi arı kimi çiçek 

Ben ne güzeller gördüm 

Gördüğünde sevilecek

Ben ne güzeller gördüm

Kimi sarı kimi esmer 

Kiminin gözleri mosmor 

Hepside bir şeyler ister 

Ben ne güzeller gördüm 

Aşık oldum candan sevdim 

Sensiz ne yaparım derdim 

Ondan sonra oldu derdim 

Ben ne güzeller gördüm 

Kimi sevdi kimi kaçtı 

Çoğununda gözü açtı 

Gönül kuşu artık uçtu 

Ben ne güzeller gördüm 

Gece gündüz yalnız kaldım 

Aşkın ateşiyle yandım 

Gül çiçektim artık soldum 

Ben ne güzeller gördüm 

Asıl güzellik gönülde 

Yiğit dururmuş sözünde 

İlkbaharımda yazımda

Ben ne güzeller gördüm 

Hüseyin im gördüm güzel 

Değmemişti eline el

İstiyorum gönlü güzel 

Ben ne güzeller gördüm', 'Kimi arı kimi çiçek  Ben ne güzeller gördüm  Gördüğünde sevilecek Ben ne güzeller gördüm Kimi sarı kimi esmer  Kiminin gözleri mosmor  Hepsi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-ne-guzeller-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar yapragı', 'sonbahar-yapragi-seckin-eren-42qzs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sonbahar yapragı gibiyim 

savrulup gidiyorum

savrulurken de

seni düşünüyorum', 'sonbahar yapragı gibiyim  savrulup gidiyorum savrulurken de seni düşünüyorum...', ARRAY['Türk Edebiyatı','Şiir','Seckin Eren']::text[], 8.5, '{"poet":"Seckin Eren","poet_slug":"seckin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sonbahar-yapragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Göz Gördüm', 'i-ki-goz-gordum-huseyin-celik-ks7je', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın ateşiyle yanıp tutuşan

Hüzünle bakışan iki göz gördüm

Damlalar süzülür yanaklarına

Hüzünle bakışan iki göz gördüm 

Öyle dertli dertli dalgın baktılar 

Sızladı yüreğim canım yaktılar 

Damlalar sel oldu coşup aktılar 

Hüzünle bakışan iki göz gördüm

Biri Leyla biri Mecnun misali

Islanmış elinde beyaz mendili

İkisi de kaybetmişler yarini

Hüzünle bakışan iki göz gördüm

Keremi Şirini Aslıyı gördüm', 'Aşkın ateşiyle yanıp tutuşan Hüzünle bakışan iki göz gördüm Damlalar süzülür yanaklarına Hüzünle bakışan iki göz gördüm  Öyle dertli dertli ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iki-goz-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mışlı Hikaye', 'misli-hikaye-volkan-i-ncel-6ztng', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzak bir şehirde bir sevgi yaşarmış 

Bu sevgi sevgiliye hasret bir yürekten taşarmış

Görenler sevenin sevebileceğine şaşarmış

Fakat sevenin bedeni sevgi olup akarmış

Bir gün sevene kötü bir haber ulaşmış

Güya sevdiği başka bir yürekten dolaşmış

Seven şok olmuş gülmüş bu işe şaşmış

Kendince sevdiği başkalarına körmüş topalmış

Oysa rivayetler gerçekmiş haberi göklere varmış

Seven dualar etmiş Allah a yalvarmış

Kuşlar bile dilsiz olmuş kimseler konuşmamış

Seven yollara düşmüş yarine ulaşmış

Sevdiğim demiş ne iş sana neler olmuş

Varlığı demiş sevdiği cüzdanını göstermiş

Etrafı demiş sevdiği albümünü göstermiş 

Boynu bükülmüş sevenin başını öne eğmiş

Bir fısıltı gelmiş yücelerden kaldır başını demiş

Garibanmış seven bir tek işi varmış 

Üzerinde ve valizinde iki kat elbisesi varmış

Sökmüş kalbini seven masanın üzerine  bırakmış

Huriler girmiş koluna onu cennete çıkartmış

Bu dünyada gerçek olan ne para pul nede çıkarmış

Yakmış Allah sevdiğini sevenin acısını ondan çıkartmış', 'Uzak bir şehirde bir sevgi yaşarmış  Bu sevgi sevgiliye hasret bir yürekten taşarmış Görenler sevenin sevebileceğine şaşarmış Fakat sevenin ...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/misli-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldattım Seni', 'aldattim-seni-volkan-i-ncel-lsxw7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağladım aldattım seni 

Dağladım sensiz kalbimi 

Bağladın sen kaderimi

Git artık git

Haykırdım sesim çıkmadı

Bağırdım duyan olmadı

Uyudum rüyan olmadı

Git artık git

Bıraktın sensiz olmadı

Elimden tutan olmadı

Gelseydin süren dolmadı

Git artık git

Yolunda öldüm olmadı

Denedim senle olmadı

Ağladım aldattım seni

Git artık git', 'Ağladım aldattım seni  Dağladım sensiz kalbimi  Bağladın sen kaderimi Git artık git Haykırdım sesim çıkmadı Bağırdım duyan olmadı Uyudum rüy...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aldattim-seni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyan Olup Giden Ne', 'ziyan-olup-giden-ne-ali-taskiran-8782u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ziyan olup giden ne

kimbilir acaba

belki  ben

belki de sen

didin uğraş dur

bütün çaba 

biraz rahat nefes almak

ve de insan olabilmek

yemek içmek uyumak 

çalışmak sadece bunun içinse 

nerde duygu düşünce zengini olmak

yorgun argın olunca insan

ne düşünmeye

ne de duygulanmaya 

mecali  kalır

bu sürgit ömür törpüsü yaşam 

ne bırakır senden geriye

çıldırır delirirsin

böylece rahatlamış olursun

ama zavallı ama çıplak

ve de sanki oklanmış  gibi

işin en kötüsü de

bu senaryoyu yazanın 

ve rolü seçenin

sen olduğunu bildiğin gün 

ya hepten ölürsün

ya da hepten doğarsın', 'ziyan olup giden ne kimbilir acaba belki  ben belki de sen didin uğraş dur bütün çaba  biraz rahat nefes almak ve de insan olabilmek yemek i...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkıran']::text[], 8.5, '{"poet":"Ali Taşkıran","poet_slug":"ali-taskiran","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ziyan-olup-giden-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zafer Günü', 'zafer-gunu-huseyin-celik-09wpe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '30 ağustos zafer bayramına

Gün olur tokmaklar vurulur,

Davullar çalınır gümbür gümbür 

Gün  olur savaş çıkar kan çıkar 

Gün olur kurbanlar kesilir cephede

Baş kesilir bağır kesilir can kesilir

Gün olur ak yazması al olur

Şan olur şeref olur namus olur

Dar olur meydanlar koç yiğitlere

Geçitler yol vermez dağlarda duman 

Göz gözü görmez kan buharından

Aman Yarabbi der ihtiyarı genci 

Görmemiştik üzüntülü sevinci 

Bir kurtuluş mücadelesidir yüreklerde 

Cesaret dolu göğsümüz bu güçlü bileklerde 

Şahlanır atları nal sesi kişneme sesi

Düşmanın topuğunda kanla dolmuş ensesi

Bu ne müthiş bir zafer bu ne müthiş komutan 

Bak sevinçten ağlıyor toprak altında yatan

Ana baba matemli kutluyorlar sevinçten

Oğlu şehit kızı şehit torun şehit can şehit

Şehit olan herkese yerler gökler bin şahit

Ne güzel bir mertebe ne güzel bir makammış 

Şehit olmak nasipten nasipte olmak varmış

Tarihi zafer dolu Türk ordusu ayakta 

Zaferine şu müthiş zaferi katmakta 

Baş komutan ayakta bu ne asil bir Türk

Hedefiniz ak deniz emretmekte Atatürk', '30 ağustos zafer bayramına Gün olur tokmaklar vurulur, Davullar çalınır gümbür gümbür  Gün  olur savaş çıkar kan çıkar  Gün olur kurbanlar k...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/zafer-gunu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumartesi Gecesi', 'cumartesi-gecesi-volkan-i-ncel-irqao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir cumartesi gecesi 

Yalnızım yine burada

İçim sızladı gülüm 

Ağlıyor musun  yoksa

Kalbime vuruyor 

Süzülen gözyaşların

Hiç aklımdan çıkmadın

Unuttum sanma sakın

Bir cumartesi gecesi 

Yalnızım yine burada

Tenim ürperdi gülüm

Üşüyormusun yoksa

Ellerimde kuruyor 

Dökülen gözyaşlarım

Ben seni unutmadım 

Ayrıldık sanma sakın', 'Bir cumartesi gecesi  Yalnızım yine burada İçim sızladı gülüm  Ağlıyor musun  yoksa Kalbime vuruyor  Süzülen gözyaşların Hiç aklımdan çıkmad...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cumartesi-gecesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir An Olur ki', 'oyle-bir-an-olur-ki-huseyin-celik-ivhqf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamanda gayri geçmez oldu

Gece on ikidir çaldı saatim

İçime bir garip sancılar doldu

Kalmamış gördüm ki takatim

Heyhat nede çabuk geçmiş

Geçmez dediğim bu koca asır

Saçıma aklar düşmüş belim bükük

Bedenim çizgi çizgi ellerim nasır

Tarihin anıları satır satır

Hece hece alnımın ortasında

Ne sıladan haber var ne yardan

Artık kurumuş güller avucumun ortasında 

Bir musalla taşımı şu gördüğüm

İki arşın uzanmış tam karşımda 

Ben yare hasret giderim gönül

Kara yazılar varmış bahtımda

Eyvah eyvah derim durmadan 

Bir sapmaya sıkıştırırlar beni

Ne acırlar halime nede sorarlar

Ben ahirete gittim gideli', 'Zamanda gayri geçmez oldu Gece on ikidir çaldı saatim İçime bir garip sancılar doldu Kalmamış gördüm ki takatim Heyhat nede çabuk geçmiş Geç...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyle-bir-an-olur-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoh Duygulandım', 'coh-duygulandim-huseyin-celik-fukqi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Köye gettim goyun guzu meleşir

İnehler möö dedi çoh duygulandım

İnadından galhmaz oldu eşşem

Bi çifte addıda çoh duygulandım

Aşam olup tavıhları düneddih

Uyuz iti yuvasına yolladdıh

Avradınan ha şu yataa yaddıh 

Bi öpücüh verdi çoh duygulandım

Sabah olup horozlarım ötünci

Saa sola bi çırpıda kaçinci

İnehleri bizim avrat sağınci

Bi bardah süt içtim çoh duygulandım,

Dırahdöre bindim verdim ara gaz,

Bir elimde küreh bir elimde saz

Çehtim uzun hava ve avaz avaz 

Baardım bi müddet çoh duygulandım

Bide bahtım tarlamıza gelmişim

Gavını garpızı çoh özlemişim

İki baş mor soğan peenir yemişim

Pancar tarlasında çoh duygulandım

Aha bizim koyün halıdır bunlar

İnehle davarla geçer zamanlar

Dinleyin derdimi beyler ağalar

Galbimde yaram var çoh duygulandım', 'Köye gettim goyun guzu meleşir İnehler möö dedi çoh duygulandım İnadından galhmaz oldu eşşem Bi çifte addıda çoh duygulandım Aşam olup tavıh...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/coh-duygulandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulursun belanı', 'bulursun-belani-volkan-i-ncel-br1zp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalan yere söz verip yıktın dünyamı

Çok bekledinmi söyle böyle bir anı

Bir hiç uğruna gittin yaktın çıramı

Elbet Allah verecek senin belanı

Bir garip aşık idim yolunda ölen

Ufak bir tebessüme dünyayı veren

Bunları haketmedim al hatıranı

Elbet Allah verecek senin belanı

Dönüp dolaşıp bir gün bana gelirsen

Mutsuz oluşuna ben inan üzülmem

Unutamam beni dertlere attığın anı

Elbet Allah verecek senin belanı', 'Yalan yere söz verip yıktın dünyamı Çok bekledinmi söyle böyle bir anı Bir hiç uğruna gittin yaktın çıramı Elbet Allah verecek senin belanı ...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulursun-belani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-huseyin-celik-fjgg8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerinden tutmayı isterdim

İsterdim gözlerine bakmayı

Bağrına yaslanıp ta uzun bir zaman 

Kalbinin sesini dinlemeyi isterdim

İsterdim sımsıkı sarmayı

Okşamayı öpmeyi

Saatlerce sevişmeyi isterdim

Seninle baş başa koyun koyuna

Yalnız kalmayı isterdim

Uyumayı isterdim sabahlara dek

Ve bir öpücükle uyanmayı isterdim

İsterdim sımsıkı sarmayı okşamayı öpmeyi

Göz yaşını silmeyi 

Dertlerine derman olmayı

Teselli etmeyi gülmeyi güldürmeyi

İsterdim el ele yürümeyi

Çılgınca koşmayı isterdim

Ve bir ağaç altında oturmayı

Güzel güllerden dermeyi

Papatyadan taç yapmayı

Saçlarına takmayı

Öpmeyi isterdim usulca incitmeden

Dokunmayı isterdim ellerine

Sarmayı isterdim  bedenini

Ve yavaşça uzanmayı isterdim hemen oracıkta

Teslim olmayı isterdim bütün bedenimle

Saatlerce kölen olmayı isterdim

Mutluluğu yakalamak için günlerce

Beraber olmayı isterdim seninle 

İsterdim okşamayı öpmeyi koklamayı

Saatlerce göz göze gelmeyi

Ya sen eyy sevgili  Sen ne isterdin?', 'Ellerinden tutmayı isterdim İsterdim gözlerine bakmayı Bağrına yaslanıp ta uzun bir zaman  Kalbinin sesini dinlemeyi isterdim İsterdim sımsı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/isterdim-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyitimsi Sözler 4', 'beyitimsi-sozler-4-huseyin-avdic-u3z0g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Iyilik

Kar$iliksiz yapilan i$, yardim ve hizmettir iyilik.

Allah icin yaptigin iyilik, eder seni cennetlik.

Berlin, Aralik 2005.', 'Iyilik Kar$iliksiz yapilan i$, yardim ve hizmettir iyilik. Allah icin yaptigin iyilik, eder seni cennetlik. Berlin, Aralik 2005....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/beyitimsi-sozler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm', 'gordum-huseyin-celik-llkpt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu hayatın bir acı günü

Düşünceli dalgın bir güzel gördüm

Yaklaşıp yanına merhaba dedim 

Dönüp te bakınca ağlıyor gördüm 

Dedim ki ey güzel neden solmuşsun

Hazana uğrayıp çok mahvolmuşsun

Bitkin bir haldesin yorulmuş musun 

Dertleştikçe onu ağlıyor gördüm 

Dedi ki bir yiğit sevmiştim bende

Bir sızı var şimdi çarpan kalbimde

Şehit düşmüş duydum Diyarbakır da

Konuştukça onu ağlıyor gördüm 

Garibim ah çekti öyle derinden

Yer oynadı sandım yerli yerinden

Bir rüzgar esiyor gayet serinden

Titriyor bir halde ağlıyor gördüm

Teselli edeyim dedim ben onu

Böyle olur dedim dünyanın sonu

Öyle bir dağıldı inan bu konu

Sitem kar bir halde ağlıyor gördüm 

Ela gözlerinden yaş damla 

Akıp gidiyordu kederle gamla

Öyle akıyordu sel oldu damla

İki gözü çeşme ağlıyor gördüm', 'Sevgi dolu hayatın bir acı günü Düşünceli dalgın bir güzel gördüm Yaklaşıp yanına merhaba dedim  Dönüp te bakınca ağlıyor gördüm  Dedim ki e...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gordum-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 69', 'guncel-beyitler-69-huseyin-avdic-eumf3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kârda Ve Zararda Olanlar

Zamani kullanmada inancsizlar ve hem inkârcilar zarardadir.

Inanclilar ve Allah''a teslim olanlarsa; kazanctadir, kârdadir.

Berlin, $ubat 2006.', 'Kârda Ve Zararda Olanlar Zamani kullanmada inancsizlar ve hem inkârcilar zarardadir. Inanclilar ve Allah''a teslim olanlarsa; kazanctadir, kâ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Gitme!', 'dur-gitme-abdusselam-bugur-31gxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dur gitme! sevgili,muhtacım sana

Rüzgarım ol, kum olayim sevda fırtınasında.

Dur gitme! hayalım gidecek; ben gideceğim

Kararır güneşim kime ben ne diyeceğim! 

Dur gitme! hayal dünyam: yüreğim sarsılır

Debeder olur, ruhum''da gırdaplar açılır.

Gitme dur! dilime dolanır nalinli türküler

Yokluğun saldırır: içime yakıp tüketen ateşler.

Gider isen buralar senin ile gidecek

Gitme dur! gidişinle güneşim sönecek...''', 'Dur gitme! sevgili,muhtacım sana Rüzgarım ol, kum olayim sevda fırtınasında. Dur gitme! hayalım gidecek; ben gideceğim Kararır güneşim kime ...', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dur-gitme-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A kahpe felek!', 'a-kahpe-felek-veysel-alkan-ifg7b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benmiyim eğlencen, tek oyuncağın? 

Düşmedim elinden A kahpe felek.

Sadece benden mi var alacağın? 

Bırak şu yakamı A kahpe felek! 

Ne yapsam ne etsem fayda etmedi.

Yıllardır ödedim,borcum bitmedi.

Ömrümü aldın da daha yetmedi.

Bırak şu yakamı A kahpe felek! 

Gücün bana yeter,banasın kinli.

Cümlealem özgür,ben hipotekli.

Anamdan doğalı,dertliyim dertli.

Bırak şu yakamı A kahpe felek! 

Sayende, rahatlık bilemedim be! 

Dünyada huzuru göremedim be! 

Gönlümce bir kere gülemedim be! 

Bırak şu yakamı A kahpe felek! 

Not:Kalıplaşmış bir ifade olan kahpe felek''ten

kasıt kesinlikle Cenab-ı ALLAH değildir.

Yaşanmış olan olumsuzluklara karşı bir 

ifadedir.Gönül dostlarımın

beni anlayacağından eminim..', 'Benmiyim eğlencen, tek oyuncağın?  Düşmedim elinden A kahpe felek. Sadece benden mi var alacağın?  Bırak şu yakamı A kahpe felek!  Ne yapsam...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/a-kahpe-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tütsü', 'tutsu-omer-dalman-qxxgt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıklıkla kendini soluman lazım

sonra arada bir

akşamdan akşama belki bir “tütsü”...

ama her dakika olmaz! 

tıpkı sevgili’yi

her dakika içine çekmemen gerektiği gibi

sadece -uygun ölçüde-

tadına doymamak şartıyla...

sonra yine kendini solumalısın

çünkü tamamen “tütsü” olamazsın.

tütsü de “sen” olamaz.

Bu dengeli bir alışveriş...

ara buluşmalarla tada bakış

keyfine varış

ve

çeşitliliklerin birbirine sunusu...

Öncelikle ve sıklıkla

kendini soluman lazım.

(Şubat 2006)', 'Sıklıkla kendini soluman lazım sonra arada bir akşamdan akşama belki bir “tütsü”... ama her dakika olmaz!  tıpkı sevgili’yi her dakika içine...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tutsu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Olsun', 'haberin-olsun-volkan-i-ncel-oj9cl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş Batar Ay Divane                        

Ben Giderim Gurbet Ele                        

Tenin Hasret Kalır Tene                      

Haberin Olsun

Derede Sular Durulur                       

Güllere Baykuş Vurulur                   

Gün Olur Hesap Sorulur                     

Haberin Olsun                                          

                     

Bir Yoldur Dağlara Çıkar                

Aşıklar Oraya Kaçar                            

Dert Uçurum Olur Yutar                    

Haberin Olsun.', 'Güneş Batar Ay Divane                         Ben Giderim Gurbet Ele                         Tenin Hasret Kalır Tene                       H...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haberin-olsun-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum', 'agliyorum-volkan-i-ncel-ii1zp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlıyorum Dertlere                               

Ağlıyorum Kedere                                   

Ateş Düşsün Gönlüne                            

Sende Ağla Yar                                          

Sevda Bize Hep El Olmuş                       

Bütün Yollar Çamur Dolmuş           

Sevdadan Aşıklar Ölmüş                    

Geride Vicdansız Kalmış                      

Göz Yaşlarım Hep Kan Oldu               

Yüreğim Acıyla Doldu                          

Buralarda Hüzün Kaldı                      

Gel Artık Ağlamayacağım Yar       

Gözlerimi Kapatınca                             

Tatlı Rüyaya Dalınca                          

Yüzün Birden Kaybolunca                

Ağlıyorum Yar.', 'Ağlıyorum Dertlere                                Ağlıyorum Kedere                                    Ateş Düşsün Gönlüne                   ...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agliyorum-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Gökyüzü', 'yeni-gokyuzu-utku-demir-sqsp6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gururla taşımıştım yüreğimde seni 

Bulutların yumuşacık yatağına

Güneşin çeşmesinden akmaktaydı

Kanı sıcak şüphesiz sevgim

Yıldızların göz kırpışlarında

Dünyamızın hayalleri simgelenerek

Kazındı ayın umut ışığına

Bak nasıl değiştirdin gözyüzünü? 

Bulutlardan armağan süreğen gözyaşlarım

Güneşte yetim kalmış bir gülümseme

Gecelere hüzünle bırakır beni

Yıldızlar sönüpte gelir maziden

Ayda yinelenen kederli bakışlar

Teslim kalbime vurur yıldırımları 

Düşerim ahesli ıstırap çizgisine', 'Gururla taşımıştım yüreğimde seni  Bulutların yumuşacık yatağına Güneşin çeşmesinden akmaktaydı Kanı sıcak şüphesiz sevgim Yıldızların göz k...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yeni-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Bırakın', 'sadece-birakin-omer-dalman-qotfu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lütfen

lütfen beni tek göz bir odaya kapatın! 

Orada bir mum ışığında

sadece bir şeyler yazayım! 

Kapı altından yemek bırakın aradabir ve

sadece gidin! 

Gidin! ..

İçerisi bombok koksa da gidin! ..

Bırakın fareler de dolaşsın sağımda, solumda! 

Yeter ki gölge etmeyin! 

Lütfen

bir süre kafes pencereden bile bana bakmayın! 

Gözlerinizi göstermeyin! 

İçime şeytanı çağırmayın

sadece bırakın! 

Oturayım, yatayım, ağlayayım,

yazayım, düşüneyim, dalayım koyu mavi denizlerime

dibinde boğulayım

ama lütfen beni bırakın! ..

Yoruldum...

Bittim...

Biraz dolayım...

Nolur

sadece

biraz bırakın...

(Aralık 2003)', 'Lütfen lütfen beni tek göz bir odaya kapatın!  Orada bir mum ışığında sadece bir şeyler yazayım!  Kapı altından yemek bırakın aradabir ve sa...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sadece-birakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğin', 'sessizligin-oguzkan-bolukbasi-qz69r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hangi kapıyı çalsam

sevgili

siz olmalıydınız ardında yüzüme çıkan

sevgilisiz kapıları açan

ve yalnız bırakan tüm cümleleri dudaklarımda

akları şakaklarımda

sesin taaa uzaklarda

ne telefonun ucunda

ne başucumda bir resim güzelliğin

şimdi

yalnızca sessizliğin', 'hangi kapıyı çalsam sevgili siz olmalıydınız ardında yüzüme çıkan sevgilisiz kapıları açan ve yalnız bırakan tüm cümleleri dudaklarımda akla...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sessizligin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış Resimleri', 'baris-resimleri-omer-dalman-lc4cp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herkesin içinde ne bombalar atılıyor

ne savaş oyunları oynanıyor

ne yerler fethediliyor

elden gidiyor

sahip bile olunamıyor da

dışa karşı hep barış resimleri çiziliyor

sakin denizler, kumsallar

mutluluk ve

elindekiyle yetinmişlik oynanıyor.

Onun içindir ki Elçiler bile

yardım için içeri giremiyor

kapıda ‘mutluluk’ yazdığından

içeride savaş olmadığını zannedip...

Halbuki tek gerçek

herkesin içinde bombalar atılıyor

savaş oyunları oynanıyor

yerler fethediliyor

dışa karşı barış resimleri çiziliyor.

Kollar koparsa birgün

mideler deşilirse

kafalar koparsa, patlarsa

suç dışarıda aranmasın...

(Mart 2005)', 'Herkesin içinde ne bombalar atılıyor ne savaş oyunları oynanıyor ne yerler fethediliyor elden gidiyor sahip bile olunamıyor da dışa karşı he...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/baris-resimleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar Olsun', 'yaziklar-olsun-volkan-i-ncel-d29go', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Sabah Uyandım 

Sen Yoktun Yanımda

Keşke Bakmasaydım 

Çalan Telefona

Ayrıldık Demek Kolay Sana

Çok Büyük Olay Bu Bana

Nasıl Kıyarsın Sevdama

Yazıklar  Olsun Sana

Kendimden Geçmişim 

Öyle Bir İçmişim

Sen Kıymet Bilmedin                

Ben Seni Çok Sevdim', 'Bir Sabah Uyandım  Sen Yoktun Yanımda Keşke Bakmasaydım  Çalan Telefona Ayrıldık Demek Kolay Sana Çok Büyük Olay Bu Bana Nasıl Kıyarsın Sevd...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaziklar-olsun-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk', 'yokluk-hasan-uzel-x0yuz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu yokluk başka yokluk

Aşk mı hayat kavgası mı? 

Nedir bu kaybedişler

Kazanmak bize haram mı? 

Ettik kavgamızı hayatla

Delikanlı''ca

Sevdik sevgiliyi aşkla

Mecnun''ca Ferhat''ça

Sevdik öylesine sevdik''ki

Göremedik karşılık 

Ne yarda ne dostta

Bizim yarimiz ayrılık dostumuz acılarmış aslında

Bazen bana diyorum''ki

Allah sevdiği kul''a çektirirmiş

Tek tesellim bu amma

Ona layık kul değilim''ki', 'Bu yokluk başka yokluk Aşk mı hayat kavgası mı?  Nedir bu kaybedişler Kazanmak bize haram mı?  Ettik kavgamızı hayatla Delikanlı''ca Sevdik s...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yokluk-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sevgiler', 'eski-sevgiler-isik-german-ersoy-iysra', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Porto Fino ya-

-Şarkı sözü olarak yazdığım bu şiirim Antoloji Com. aracılığı ile tüm

  kompozitörlere açıktır.-

Nerde o eski sevgiler

Nerde eski sevgililer

Gizli bir yerde saklı belki

Hatıralar dünkü gibi...

Nerde o eski dostluklar

Nerde o arkadaşlıklar

Sararmış bir albümde belki

O resimler dünkü gibi...

Eski yıllar geri gelmiyor

Ama izler silinmiyor

Her an her yerde her kadehte

O günler yadediliyor...

Nerde o eski şarkılar

Nerde o eski duygular

Sanki hep yanımızdalar

Aramızdan ayrılanlar.', '-Porto Fino ya- -Şarkı sözü olarak yazdığım bu şiirim Antoloji Com. aracılığı ile tüm   kompozitörlere açıktır.- Nerde o eski sevgiler Nerde...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/eski-sevgiler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümün Yaşıyla Islandım Gülüm', 'gozumun-yasiyla-islandim-gulum-gultekin-toga-xb0bq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç kurak kalmadı benim yüreğim,

Gözümün yaşıyla ıslandım gülüm..

Istırap balına göz,göz peteğim,

Derdin her rengiyle süslendim gülüm,

Av oldum gurbetin sert pençesine,

Asıldım ayrılık,gam kancasına,

Kuşun uçmasına,gül goncasına,

Bakıp duygulandım,hislendim gülüm..

Her adım ötesi sanki bir pusu,

Bitmedi huzurun derin uykusu,

Hayel ekmek oldu,ümitlerim su,

Bir ömür onlarla beslendim gülüm..

Yaymadım derdimi hiç ortalığa,

Dönderdim içimde bir yanar dağa,

Sevginin peşinde çığlık çığlığa,

Feryat,figan ettim,seslendim gülüm..

Böyle yanıyorsam vardır bir közü,

Sentezi´ye kördür talihin gözü,

Rahatlamak için belki de bazı,

Efkar dağlarına yaslandım gülüm', 'Hiç kurak kalmadı benim yüreğim, Gözümün yaşıyla ıslandım gülüm.. Istırap balına göz,göz peteğim, Derdin her rengiyle süslendim gülüm, Av ol...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozumun-yasiyla-islandim-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olmuş?', 'ne-olmus-aysegul-avci-58bax', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kızgınım kötülük ortaklığına,

Yine serseri ruhum aldı da beni benden...

Birisi birisine bir tokat atmış,

Diğeri diğerine yumruk sallamış,

Birinin ötekinden ne farkı varmış,

İkisi de bir kötüye ortakmış...

Keçi misali iki kişi direnmiş,

Birbirlerine benimki,seninki demiş,

Her an kötülük hortlamak üzereymiş,

Madem ki menfaatine zararı yokmuş,

Kişiliğin ruhun seninle hoşmuş,

Seninki olmuş, onunki olmuş,

Ne olmuş? ...', 'Kızgınım kötülük ortaklığına, Yine serseri ruhum aldı da beni benden... Birisi birisine bir tokat atmış, Diğeri diğerine yumruk sallamış, Bi...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Avcı']::text[], 8.5, '{"poet":"Ayşegül Avcı","poet_slug":"aysegul-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-olmus-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Bilsin', 'ne-bilsin-koksal-akar-chh5q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mecnun edip diyar diyar gezdiren

Yollarına yandığımı ne bilsin.

Muhabbete şeker, şerbet ezdiren,

Dillerine yandığımı ne bilsin.

Beni koyup yadellere koşarken,

Minnet ile karlı dağlar aşarken.

Gözlerimden damla damla taşarken,

Sellerine yandığımı ne bilsin.

Bir çınardım, yar eliyle devrilen.

Ateşlerde yanıp yanıp kavrulan...

Saçlarının yellerinde savrulan,

Küllerine yandığımı ne bilsin.

Usanmışım sevdasından, narından,

Çok çekmişim hasretinden, zarından....

Aman derken boranından, karından,

Yellerine yandığımı ne bilsin.

Abdal olup divanına duranda,

Seyyah olup gurbetlere varanda,

Dert sazının sinesine vuranda,

Tellerine yandığımı ne bilsin.

Vakti tamam şimdi gençlik çağının,

Duman almış yücesini, bağının.

Her seherde girip sevda bağının,

Güllerine yandığımı ne bilsin.', 'Mecnun edip diyar diyar gezdiren Yollarına yandığımı ne bilsin. Muhabbete şeker, şerbet ezdiren, Dillerine yandığımı ne bilsin. Beni koyup y...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-bilsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylar''dan Kasım''dı', 'aylar-dan-kasim-di-hasan-uzel-41azo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben zaten sevmezdim kış mevsimini

Aylardan Kasım''dı tanıdığımda seni

O kadar sıcaktın''ki üşümüyordum bile

Nerden bilirdim sonradan buz keseceğini

Ben zaten sevmezdim kış mevsimini

Aylardan Kasım''dı yüreğime yazdığımda seni

Öylesine yazmıştım''ki nakış nakış

Nerden bilirdim dertleri işlediğimi

Ben zaten sevmezdim kış mevsimini

Aylardan Kasım''dı tuttuğumda ellerini

Öylesine masumdu''ki ellerin ellerimde

Nerden bilirdim kayıpta gideceğini

Ben zaten sevmezdim kış mevsimini

Aylardan Kasım''dı gözlerimden akan yaş

Yanınday''ken malum olmuştu belki''de

Sensizlik,acı,ayrılık yavaş yavaş

Ben sevmezdim kış mevsimini

Aylardan Kasım''dı öptüğünde beni

Öylesine yediverendi''ki busen

Nerden bilirdim elveda öpücüğü verdiğini', 'Ben zaten sevmezdim kış mevsimini Aylardan Kasım''dı tanıdığımda seni O kadar sıcaktın''ki üşümüyordum bile Nerden bilirdim sonradan buz kesec...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aylar-dan-kasim-di-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimler Geçer', 'mevsimler-gecer-isik-german-ersoy-mh0rc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsimler sürekli

Gelir geçer

Ama

Nedense hep

Baharlar kalır

Anılarda', 'Mevsimler sürekli Gelir geçer Ama Nedense hep Baharlar kalır Anılarda...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mevsimler-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamız Ne Renk?', 'sevdamiz-ne-renk-hasan-uzel-f6ssn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizim sevdamız ne renk? 

Ayrılığın rengi ne? Ya acıların? 

Mutluluğunda bir rengi varmıdır? 

Gözyaşları hep ıslakmıdır? 

Mor sevdaların açık yeşilindemiyiz? 

Yoksa karanlık siyahın uçuk mavisindemi? 

Acının rengini bilmem amma tadını bilirim

Ayrılık tenceresinde pişer çok yedim

Gel sevdamızın rengi siyah olsun

Ayrılığın rengi acıların rengi de

Bırak mutluluk hep beyaz kalsın

Bilirsin her beyazın sonu siyah,anlarsın

Bırak gözyaşlarıda hep ıslak kalsın

Bilirsin acılar düğümlenir kursağımda

Bırak yüreğime damla damla çağlasın

Bilirsin gözlerim ağlamayı öğreniyor aslında', 'Bizim sevdamız ne renk?  Ayrılığın rengi ne? Ya acıların?  Mutluluğunda bir rengi varmıdır?  Gözyaşları hep ıslakmıdır?  Mor sevdaların açık...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdamiz-ne-renk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklamak', 'saklamak-isik-german-ersoy-bg3yb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tanrı

Yaptıgı hiçbir şeyi

Kullarından saklamazken

Kulları

Niçin yaptıklarını

Tanrıdan saklar

Acaba', 'Tanrı Yaptıgı hiçbir şeyi Kullarından saklamazken Kulları Niçin yaptıklarını Tanrıdan saklar Acaba...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/saklamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurdumun Dağları.1', 'yurdumun-daglari-1-ahmet-yozgat-1cxid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Yurdumun dağları yalçın...

Bakarım uzaklardan dağlarına yurdumun 

Sivri zirveler ve en çetin kayalıklar görürüm 

Bağırırım: Heeey, diye, 

Sesim yankılanır: Çın, çın! 

Sesime ses verir yamaçlar: Avaz avaz! 

Yurdumun dağları yalçın mı yalçın...

Yurdumun dağları türkü türkü 

Yurdumun dağları turkuvaz mı turkuvaz...

2/:

Yurdumun dağları beyaz...

Yeşil ovalara basar kocaman ayakları 

Küheylan sağrılı yaylalara 

Yaslanır karlı omuzları

Bağırırım: Heeey, diye, 

Sesim yankılanır: Avaz avaz! 

Yurdumun dağları bozlak bozlak, 

Yurdumun dağları turkuvaz mı turkuvaz...

3/:	

Yurdumun dağları sarı...

Sarışın çiğdemlerin vatanı yol kenarları 

Aslanlar gibi çocuklar, 

Bir ellerinde kazgıçları 

Öbür ellerinde çökelekli azıkları 

Bağırırlar: Heeey, diye, 

Sesleri yankılanır: Avaz avaz! 

Yurdumun dağları sarı mı sarı... 

Yurdumun dağları şiir şiir,

Yurdumun dağları turkuvaz mı turkuvaz...

4/:

Yurdumun dağları kırmızı... 	

Yıldız gibi, hilal gibi, 

Yurdumun dağları bayrak gibi

Gelincikler gelin olmuş, davullu zurnalı 

Halaya durmuş oğlu kızı 

Bağırırlar: Heeey, diye, 

Sesleri yankılanır: Avaz avaz! 

Yurdumun dağları kırmızı...

Yurdumun dağları şarkı şarkı,

Yurdumun dağları turkuvaz mı turkuvaz...

5/:

Yurdumun dağları yeşil...

Bürünmüş çimenini yamaçlar

Göğe yürümüş capcanlı ağaçlar 

Çamlar, gürgenler, çınarlar 

Uzaktan bizleri çağırırlar: 

Ali, Barış, Emre, Sevgi, Seçil! 

Çocuklar yanıt verir: Heeey, diye, 

Sesleri yankılanır: Avaz avaz! 

Yurdumun dağları yeşil...

Yurdumun dağları beste beste, 

Yurdumun dağları turkuvaz mı turkuvaz...', '1/: Yurdumun dağları yalçın... Bakarım uzaklardan dağlarına yurdumun  Sivri zirveler ve en çetin kayalıklar görürüm  Bağırırım: Heeey, diye,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yurdumun-daglari-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın İzdüşümü Nedir', 'sevdanin-i-zdusumu-nedir-yusuf-onder-bahceci-y8pgm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdanın izdüşümü acaba nedir,

İnsan hangi duygularla cânı verir,

Sevdiğin çekip gitse bile sevilir,

Sevdanın izdüşümü acaba nedir.

Hesapla, kitapla olmuyor bunlar,

Şiirleri yaz bakalım kim ne anlar,

Beni kâlbinden vurulanlar, anlar,

Sevdanın izdüşümü acaba nedir.

Halk sevgisi, Hâk sevgisi karışık,

Benim duygularım böylesi karışık,

Önder''im bu ezalara çoktan alışık,

Sevdanın izdüşümü acaba nedir.

Yunus neden söyleyiben gezmiş,

Mansur neden cânından bezmiş, 

Kulunu seven Allah''ıda severmiş,

Sevdanın izdüşümü acaba nedir.', 'Sevdanın izdüşümü acaba nedir, İnsan hangi duygularla cânı verir, Sevdiğin çekip gitse bile sevilir, Sevdanın izdüşümü acaba nedir. Hesapla,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdanin-izdusumu-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kuyunun Masalı', 'bir-kuyunun-masali-ahmet-yozgat-b271e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Gıcır gıcırdır sana has sesin, 

Acıklı bir türküyü söyler gibisin

Sanki gizli gizli ağlarsın kuyu.

Bunca bol ve soğuk suyu 

Bilmem ki nerden alırsın? 

Alçakgönüllü ve suskunsun

Şır şır akan çeşmelere inat,

Durursun öylece unutulmuş bir yerde

Devasın sanki bin bir derde...

2/:

Gıcır gıcır kıvranan çıkrığın

Buram buram burulan halatınla

Ve has çam ağacığından kovanla

Şır şır akan çeşmelere inat

Kışın ılımanlaşan

Ağustosta buz kesen suyun

Devadır bin bir derde 

Huyun bir yaşlı bilge sanki, 

Durursun öylece unutulmuş bir yerde.

3/:

Gıcır gıcır sesin gelir

Yedi kat yerin altından

Yaşlı ninem bir yudum çekip suyundan

Der, ''Hicaz''dan bunun suyu.''

Bir Yunus ilahisi söyler gibi

Sanki gizli gizli ağlarsın kuyu.

Soğuk suyun bazen katık

Yavan sofralarda ekmek yanında

Bazen çekilirsin derinlere

Yeşil kızlara, kınalı gelinlere

Nazım nazım nazlanırsın

Anladım yorgunsun ve yaşlısın, 

İzin sana. Uyu istersen artık.', '1/: Gıcır gıcırdır sana has sesin,  Acıklı bir türküyü söyler gibisin Sanki gizli gizli ağlarsın kuyu. Bunca bol ve soğuk suyu  Bilmem ki ne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-kuyunun-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiir Sana Çocuğum', 'bu-siir-sana-cocugum-ahmet-yozgat-sphts', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Sanadır bu masalsı şiir,

Bu rengarenk şiir sanadır çocuğum.

Say ki bir nazarlık,

Yuvarlak bir mavilik üstüne,

Bir nokta beyaz damlamış.

Al tak çocuğum,

Göğsün üstüne madalya gibi.

Ya da kulağına küpe diye,

Muska da olur kuğular gibi boynuna

Oyununa takım oyuncusu da olur

Saklambaç da olur boş arsada

Çelik çomak da olur...

2/:

Bu masalsı şiir sanadır çocuğum,

Yatanda yatağına al onu sıcak koynuna.

Rüyalarında kanatlı bir at olsun

Dolsun çeşme suları gibi gönlüne

Önüne yol bilir kılavuz olsun

Sanadır bu ılıman şiir,

Bu şiir sanadır çocuğum.

Güneşsever ağustosun ortasında, 

Ya da uzak ve kurak bir kasabada.. 

3/:

Sanadır bu köpüklü şiir. 

Susadığında al bir yudum iç çocuğum, 

Kalaylı tasta ayran gibi. 

Ya da buz gibi kuyu suyu say ki

Veya bol şekerli şerbet... 

Bu şiir sanadır çocuğum, 

İç kana kana iç ilelebet.', '1/: Sanadır bu masalsı şiir, Bu rengarenk şiir sanadır çocuğum. Say ki bir nazarlık, Yuvarlak bir mavilik üstüne, Bir nokta beyaz damlamış. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bu-siir-sana-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirim Fener Sanki', 'siirim-fener-sanki-ahmet-yozgat-mzckz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Şiirim bir fener gibidir

Gah yanar. Gahi söner...

Aydınlatır geceleyin yolumu.

Gündüzleyin aydınlık güneşe rağmen 

Sağımı ve solumu onunla seçerim

Fark derim onunla selli sulu dereleri

Geçerim üzerinden köprüler kurup

Bazen bir küçük köy olur uzakta.

Bazen bir çiftlikte Ali Baba 

Yani şiirim aydınlık bir fener,

Bazen yanar, bazen söner...

2/:

Şiirim bir fener gibidir

Gah yanar. Gahi söner...

Denizin ortasında bir ıssız ada

Robinsonlara sığınak olur.

Kanadı kırılmış göçmen kuşlar,

Ona konarlar uçuş molalarında

Kaybolmuş yollarında yalapşap giden

Pusulasız ve yaşlı balıkçı takaları

Anaları ağlatan amansız fırtınalarda

Ya da amansız bir borada

Dümeni kopmuşken ortalarından

Savrulmuşken gündelik rotalarından

Şiirim yetişir imdada

Balıkçılar bayılır bağırmaya:

Heyamola uşaklar heyamola! 

Görünür sahilin kayalıkları

Kılavuz olan şiirimle ben yırtarım,

Umutları örten karanlıkları.

Yani şiirim bir fener,

Bazen yanar, bazen söner...

3/:

Şiirim bir fener gibidir

Gah yanar. Gahi söner... 

Açık denizlerde gemiler onu gözler. 

Onu özler yalnız denizciler.

Gagasında minik bir balıkla, 

Yuvasına dönen yoksul martılar, 

Çukur çeneli garibim balıkçılar, 

Uzun ve derin soluklarla, 

Kıvrım kıvrım kıyılarda kulaç atan, 

İnce belli ve kıvrak kollu yüzücüler, 

Kıyıları dolduran gözler onu gözler, 

Yani şiirim bir fener, 

Gah yanar, Gahi söner...

4/:

Şiirim bir fener gibidir

Gah yanar. Gahi söner...

Ay karanlık gecelerde

Kutup yıldızı gömülmüşse bulutlara

Kuytulara kaçmışsa demirkazık

Gündüz, güneş kızı doğurmamışsa eğer.

Dert değil ki. Ben varım.

Çevreme yaydığım aydınlıkla

Kocaman bir ay dede kadarım

Sönmüşse kutup yıldızı

Kararmışsa gündüzün güneş kızı

Şiirimin ışığı yeter dünyaya.

Dalgalar dağlarla yarıştığında,

Geniş okyanus. Ya da koca Marmara

Yuttuğunda şen şakrak sahilleri

Evleri karanlıklar boğduğunda

Kuytu bir sığınağım çocuklara.

Yani şiirim bir fener,

Bazen yanar, bazen söner...', '1/: Şiirim bir fener gibidir Gah yanar. Gahi söner... Aydınlatır geceleyin yolumu. Gündüzleyin aydınlık güneşe rağmen  Sağımı ve solumu onun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/siirim-fener-sanki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkı Amcam Haklı Ama', 'hakki-amcam-hakli-ama-ahmet-yozgat-dvnly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Haklısın Hakkı amca.

Biliyorum ki çok haklısın.

Çıkmamalıyım sözünden büyüklerin.

Oturmalıyım. Onların otur dediği yerde.

Kalk dediği yerde kalkmalıyım.

Bakmalıyım büyüklerimin eline

Gözlerine bakmamalıyım.

Bakışlarımı yere dikmeliyim

Gitmemeliyim kafamın estiği yere

Haklısın be Hakkı amca

Çıkmamalıyım sözünden büyüklerin.

Oturmalı. Otur dediği yerde.

Kalk dediği yerde. Kalkmalı...

Ama. Küçük bir çocuğum ben de.

Bazen de tepem atmalı.

2/:

Haklısın Hakkı amca.

Kara yerden mavi göğe kadar,

Haklısın hem de.

Ama. Çocuğum ben de.

O kadar geniş ki hayallerim,

Bir ucu burada düşlerimin

Diğer ucu yıldızlara kadar.

Oyunlarım buradan başlar

Uzanır ekvatora kadar

Yani bu kocaman dünya bana dapdar.

Ellerim ta uzaya kadar uzanır. 

Ben koşarım, hayalimin sonuna kadar.

Haklısın be Hakkı amca

Çıkmamalıyım sözünden büyüklerin.

Oturmalı. Otur dediği yerde.

Kalk dediği yerde. Kalkmalı...

Ama. Küçük bir çocuğum ben de.

Bazen de tepem atmalı...', '1/: Haklısın Hakkı amca. Biliyorum ki çok haklısın. Çıkmamalıyım sözünden büyüklerin. Oturmalıyım. Onların otur dediği yerde. Kalk dediği ye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hakki-amcam-hakli-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Uzakta', 'ben-uzakta-c-cataltepe-h6zhq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben uzakta,

Yürek yar ile

Beklerim

Sabah durulugunda bir merhaba

Beklerim bir dervis sabriyla...', 'Ben uzakta, Yürek yar ile Beklerim Sabah durulugunda bir merhaba Beklerim bir dervis sabriyla......', ARRAY['Türk Edebiyatı','Şiir','C Cataltepe']::text[], 8.5, '{"poet":"C Cataltepe","poet_slug":"c-cataltepe","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-uzakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Koyun', 'mor-koyun-ahmet-yozgat-ts2k1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A/...

''Me de me...'' diye diye,

Meleyişin var ya mor koyun...

Bize bu durum say ki bize bir oyun.

Mor şapkalı minik bir çoban,

Elinde kavalı ince ve uzun, 

Değneği meşenin en filizlisinden

Belinde desenli çantası

Parmakları yününden kilim dokur.

A/a...

Mor koyun meler

Mor kahküllü küçük çoban

Neler düşünür kim bilir? 

Mor koyun türkü okur.

B/...

''Me de me...'' diye diye,

Yavruna ünleyişin var ya mor koyun.

Bize bu durum sanki bir oyun.

Göbeği sarışın bir koyun gözü,

Kahverengi kök üstünde yükselir,

Ve yeşil yapraklar sunar

Topraktan emdiği tüm lezzetini

Etini tutasın diye sen

Yünün daha uzun ve parlak olmalı

Gümüş dişli bir tarak

Bukle bukle tarasın saçlarını.

B/b...

Senin melemen mor koyun

Say ki capcanlı bir oyundur bize.

Otlarsın yumuşak otlu çayırlarda

Otlarsın yeşil otları da tatlı tatlı melersin

Sesin yankılanır koyaklarda çın çın,

Kuş uçmaz dağları delersin.

B/c...

Mor koyun meler.

Mor kahküllü küçük çoban

Neler düşünür neler...

Mor koyun türkü okur

Yalnız çoban sıkılır tek başına

Karşı kayalıklara hey heyler.

Koyunun mor yününden

Kilim desenli çanta dokur...', 'A/... ''Me de me...'' diye diye, Meleyişin var ya mor koyun... Bize bu durum say ki bize bir oyun. Mor şapkalı minik bir çoban, Elinde kavalı ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/mor-koyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gelince İnsan', 'bahar-gelince-i-nsan-ahmet-yozgat-mzsie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'A/...

Gelince bahar salkım saçak 

İnanın insan bir hoş oluyor. 

Çiçekleniyor bozkır gibi gözleri. 

Elleri küçük bir serçe kuşu misali, 

Uçuyor ha babam uçuyor... 

Kuru kuru parmak aralarından, 

Kocaman akasya ağaçları dal veriyor.

Elma ağaçları bel veriyor

Tırmanalım diye biz sırtına

Bir fırtına esiyor doruklarında

Eteklerinde dağların ateş yanıyor

Eriyor ha babam eriyor 

Şakaklarını kaplayan karlar. 

Bahar gelince insan, 

Bir elma, bir portakal, bir incir

Ya da oluyor sarışın bir muz. 

Ya siz, siz de bir hoş musunuz? 

B/...

Bahar gelince insan bir hoş oluyor.

Yüreği top oynuyor boş bir arsada, 

Ya da bir yanı uçurum sahalarda. 

Dağlarda mor kuzular gibi meliyor. 

Kara gözlü koyunlarla arkadaş 

Kardeş oluyor altın kanatlı kelebeklerle. 

Durup denizler kıyısına el sallıyor

Saçları dalgalı denizcilere 

Dalıyor ha babam dalıyor, 

Yosunlu diplerine duru göllerin. 

Balıkhanelere konuk oluyor. 

Bir uskumru, bir balina, bir hamsi

ya da oluyor şıppadanak bir yunus. 

Ya siz, siz de bir hoş musunuz?', 'A/... Gelince bahar salkım saçak  İnanın insan bir hoş oluyor.  Çiçekleniyor bozkır gibi gözleri.  Elleri küçük bir serçe kuşu misali,  Uçuy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bahar-gelince-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Serçe', 'suskun-serce-ahmet-yozgat-kulu5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'A/...

Bir suskun serçeyim ben kasabanızda,

Ve sevinç kokulu söğüt dallarında.

Gerektiğinde bile ötmeyişim,

Kuş dili bilmezliğimden değil ha.

İş var işin içinde...

Bir yaramaz mı yaramaz

Laf söz anlamaz komşu çocuğu,

Her yıl nisan ayı gelince,

Dadanır kırılgan yuvama.

Ben yaparım, o bozar

Yuva bozmak onun için eğlence.

B/...

Bir suskun serçeyim ben kasabanızda,

Gökyüzü kızlarının saçı bulutlarda.

Dil bilmezliğimden değil ha ötmeyişim,

İş var işin içinde...

Sıcak bir yuvamın olmayışından.

C/...

Bir suskun serçeyim ben kasabanızda,

Akşam üstlerinin hüzünlü dam saçağında.

Gerektiğinde bile ötemeyişim,

Kuş dili bilmezliğimden değil ha.

İşin içinde iş var...

Akşamlar gibi yalnızlığımdan. 

C/...

Bir suskun serçeyim ben kasabanızda,

Karlı çam ağaçlarının iğneli fıçılarında.

Kuş dili bilmezliğimden değil ha ötmeyişim,

İş var işin içinde...

Sarışın pamuk ağızlı bir yavru,

Yalnız yaşamımın bütün özlemi.

Döşü gümüş rengi kadifeden,

Kanatları has ipekten olmalı.

Ç/...

Bir suskun serçeyim ben kasabanızda,

Yağmurlardan kaçan şemsiyeler altında.

Kuş dili bilmezliğimden değil ha ötmeyişim,

Bir yaramaz komşu çocuğu,

Her gün ortasında sıcak yuvama dadanır.

Akşam işten dönünce yuvaya,

Bakarım ki ne göreyim? 

Tek eserim çilli yumurtam alınmış.

Ağlaya ağlaya kalakalırım 

Koyu karanlık gecenin yalnızlığında.

Suskunluğuma ses verir uzaktan

Kıştan arta kalan nazlı kumrular...

D/...

Bir suskun serçeyim ben. Kasabanızda,

Bütün annelerin gözü yaşlı yalnızlığından

Bir parça da düşer payıma benim

Bedenim büzülür bir ağaç kovuğunda

Kuş dili bilmezliğimden değil suskunluğum,

Çilli yumurtamın kırılışından.', 'A/... Bir suskun serçeyim ben kasabanızda, Ve sevinç kokulu söğüt dallarında. Gerektiğinde bile ötmeyişim, Kuş dili bilmezliğimden değil ha....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/suskun-serce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Vardı Bir Yok Oldu', 'bir-vardi-bir-yok-oldu-ahmet-yozgat-u9027', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/...

Bir vardılar, bir yok oldular.

Geçmiş zamanın lezzetli masalları

Ermez buna bir türlü aklım 

Anlamam ki neden kayboldular? 

Sayın ki onlar değil de ben kayboldum.

Bir koca boşluk şimdi çocukluğum.

Ne masal masal matidas.

Ne de masal masal maniki.

Öyle ki,

Bir vardı, bir yok olmuş.

Sayın ki,

Bütün çocukluğum kaybolmuş.

2/...

Bir vardılar, bir yok oldular,

O güzelim bilmeceler.

Bilmem ki neden kayboldular? 

Sayın ki ben kayboldum.

Bir karanlık kuyu şimdi çocukluğum.

Ne bilmece, bildirmece artık.

Ne de el üstünde kaydırmaca.

Öyle ki,

Bir vardı, bir yok olmuş.

Sayın ki,

Tüm hayallerim kaybolmuş.

3/...

Bir vardılar, bir yok oldular.

O ince uzun tekerlemeler.

Hiç anlamam neden kayboldular? 

Sayın ki ben kayboldum.

Bir koca boşluk şimdi küçüklüğüm.

Ne o o o eveleme, geveleme,

Ne de kovalama deve kuşunu.

Öyle ki,

Bir vardı, bir yok olmuş.

Sayın ki,

Rüyalarımın hepsi kaybolmuş.

4/...

Bir vardılar, bir yok oldular,

Kan ter içinde şaşırmacalar.

Aklım ermez niye kayboldular? 

Sayın ki ben kayboldum.

Bir koca boşluk şu an küçüklüğüm 

Ne bir berber, bir berbere

Ne de gel beraber, diyor.

Açalım bir berber dükkanı.

Öyle ki,

Bir vardı, bir yok olmuş.

Sayın ki,

Yaşamımın bir bölümü kaybolmuş.', '1/... Bir vardılar, bir yok oldular. Geçmiş zamanın lezzetli masalları Ermez buna bir türlü aklım  Anlamam ki neden kayboldular?  Sayın ki o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/bir-vardi-bir-yok-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daldım Geometriye', 'daldim-geometriye-ahmet-yozgat-7sw2h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ne önümde dört dörtlük kare,

Ne arkamda mükemmel üçgen var.

Makas gibi bir açının arasındayım.

Top oynuyorum kocaman noktalarla.

Virgüllerle sekerek sek sek...

Ben Ahmet''im. 

Ben Fatma''yım, 

Ben Lale

Zaten hep çizgilerle oynarım.

Ya kırarım, ya eğerim, ya da bükerim,

Kırpar kırpar çevreme yıldız ekerim.

2/:

Oyunda sobemin sahası üçgen prizma.

Bir zıplarım, Mısır''da piramitlere binerim.

İnerim silindirlerin yuvarlak dibine,

Enine, uzununa ünlem ekerim.

Su çekerim kesik konilerle kuyudan.

Minareden külah çalar,

Koni diye satarım dondurmacılara.

Bir bu yana eğilirim, 

Kaykılırım bir öbür yana

Paralelkenarlarla yan yana durur

Geometri dersinde halay çekerim. 

Tırmanırım kare prizmalara.

Ya kırarım, ya eğerim, ya da bükerim,

Kırpar kırpar çevreme yıldız ekerim. 

3/:

Bilirim sen tostoparlak bir küresin. 

Nokta kadar küçücüksün. 

Dünyalar ve yıldızlar kadar iri... 

Üçgen prizma diye yaramazın biri, 

Başsız omzuma konar. 

Dönüşürüm anında şirin bir eve 

Dalgın dalgın bakarım 

Çevremi saran her bir şeye 

Ardından dalarım amcam geometriye

Ya kırarım, ya eğerim, ya da bükerim,

Uzaya yıldız ekerim.', '1/: Ne önümde dört dörtlük kare, Ne arkamda mükemmel üçgen var. Makas gibi bir açının arasındayım. Top oynuyorum kocaman noktalarla. Virgüll...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/daldim-geometriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boncuk Gözlüme Şiir', 'boncuk-gozlume-siir-ahmet-yozgat-dc3b4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A/:

Çocuğumun gözleri boncuk. 

Güneş vurur ışıl ışıl

Ay vurur yalap yalap...

Sanki uçar ışıltılı derinliklerden

Konar gözbebeklerine 

Bir dantelli kelebek 

Gerer şeffaf kanatlarını 

Çocuğumun boncuktan gözlerine.

B/:

Çocuğumun gözleri zeytin. 

Güneş gözlerine vurur,

Geceden arta kalan bir yıldız

Çocuğumun gözlerinde geceler 

Çocuğum uyanır sabaha, 

Rengarenk bakar gri dünyaya.

Çocuğum kahkahalarla güler,

Çocuğumun gözleri zeytinler gibi kara 

Yanakları yayılır ufuklara. 

C/:

Çocuğumun gözleri damla. 

Bulutlar vurur şıpır şıpır

İpekten göz kapaklarına. 

Dökülür üstümüze uzaklardan 

Mavi yüklü bulutlar.

Gözyaşı sağanağında kalan

Bütün analar sırılsıklam ıslanırlar

Gererler şeffaf şemsiyelerini 

Korurlar çocuğumun boncuktan gözlerini.

Ç/:

Çocuğumun gözleri iri mi iri. 

Güneş gözlerine vurur onun, 

Yansır tüm renkler çevreye çizgi çizgi

Bir ezgi buharlanır mavi havaya

Gerer şeffaf kanatlarını türküler 

Çocuğumun boncuk gözlerine. 

O gözler iri gözler

Damlalar gibi diri gözler

O beni özler her yalnız kaldığında

Ben onu daha çok özlerim

Çocuğumun gözleri boncuk, 

Çocuğum çok çocuk...', 'A/: Çocuğumun gözleri boncuk.  Güneş vurur ışıl ışıl Ay vurur yalap yalap... Sanki uçar ışıltılı derinliklerden Konar gözbebeklerine  Bir da...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/boncuk-gozlume-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pabucu Yarım Amet''e Şiir', 'pabucu-yarim-amet-e-siir-ahmet-yozgat-detx0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Amet abi, Amet abi... 

Ayağındaki pabucun yarım,

İhtiyacım var daha sana

Ben daha yarın kadarım.

Şiir yaz benim için, 

Şiir yaz ve yuvarla boş arsaya

Amet abi pabucu yarım,

Haydi çık dışarıya 

Hep birlikte çember oynayalım. 

2/:

Amet abi, Amet abi... 

Şiirinin serin soluğu ulaşsın, 

Gökyüzünden yukarılara bile. 

Biz çocuklara can olsun, 

Tıkanan çiçeklere nefes... 

Herkes ama herkes sana koşsun, 

Şiirinde kendini bulsun...

Terledim sek sek oynamaktan

Çelik çomaktan susadım

Şimdi bir bardak su ol

Serin beyitlerin su...

Nerenden akar o şır şır çeşme? 

Nerende kazılı o derin kuyu? 

Amet abi pabucu yarım,

Çık dışarıya kuyu kazalım.

3/:

Amet abi... Amet abi...

Del sarışın yaprakları,

Kitaplardan dışarı taş. 

Yavaş yavaş yol almak yakışmaz sana

Bir o yana bir bu yana 

Tembelce sallanmak niye? 

Tekerleme ol. Şekerleme ol

Ebe ol. Sobe ol...

Amet abi pabucu yarım,

Çık dışarıya şiir yazalım.', '1/: Amet abi, Amet abi...  Ayağındaki pabucun yarım, İhtiyacım var daha sana Ben daha yarın kadarım. Şiir yaz benim için,  Şiir yaz ve yuvar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/pabucu-yarim-amet-e-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin Rengine', 'gozlerinin-rengine-tahmine-yildirim-1ijyr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak içimden bakmak geldi gözlerine

Derinlere dalıyorum kendimden geçiyorum

Seninle beraber olduğumu düşünüyorum

Vurgunum sana seni çok seviyorum.

                                                                             NİSAN

                                                                                                2004', 'Bak içimden bakmak geldi gözlerine Derinlere dalıyorum kendimden geçiyorum Seninle beraber olduğumu düşünüyorum Vurgunum sana seni çok seviy...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozlerinin-rengine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babamı Öpesim Gelir', 'babami-opesim-gelir-ahmet-yozgat-pf1mq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Aman da aman! 

Babamın bıyığı ne kadar da kocaman 

Urgan bulamadığım zaman 

Salıncak kurasım gelir.

2/:

Aman da aman! 

Babamın şakağı ne kadar da kocaman

Sayın ki yokuş aşağı iniş

Karlı dağ bulamadığım zaman

Kızak kayasım gelir.

3/:

Aman da aman! 

Babamın göğsü ne kadar da kocaman 

Sayın ki sanki bir harman 

Yatak bulamadığım zaman 

Uzanıp sırt üstü yatasım gelir.

4/:

Aman da aman! 

Babamın sırtı ne kadar da kocaman

Sayın ki yumuşak halı, sert semer 

Tahta atım olmadığı zaman 

Atlayıp sırtına gidesim gelir.

5/:

Aman da aman! 

Babamın elleri ne kadar da kocaman

Sayın ki tarlada nakışlı gürgen yaba 

Rüzgarı yakaladığım anda

Dağ gibi tınazlar yığılı bir harmanda 

Kendimi savurasım gelir.

6/:

Aman da aman! 

Salıncak kurasım gelir 

Kızak kayasım gelir 

Uzanıp yatasım gelir 

Atlayıp gidesim gelir 

Kendimi savurasım gelir 

Yani babamı öpesim gelir...', '1/: Aman da aman!  Babamın bıyığı ne kadar da kocaman  Urgan bulamadığım zaman  Salıncak kurasım gelir. 2/: Aman da aman!  Babamın şakağı ne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/babami-opesim-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çam Oluklu Çeşmenin Öyküsü', 'cam-oluklu-cesmenin-oykusu-ahmet-yozgat-m9887', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Akar çam oluklu çeşmemiz,

Akar karpuz çatlatan sular

Şırıl da şırıl...

O gece akar, gündüz akar

Ben ise hep ona bakarım.

Haziran çöker döşüme,

Susuzluktan yanarım.

2/:

Bizim çam oluklu çeşmemiz,

El sallar bana karşıdan,

Susuz taylar gibi ona koşarım.

Lülesine dayarım kuruyan ağzımı...

Ohh ki ne oh! 

İçerim içerim ve kanarım.

3/:

Oturur çeşme başına bilge ninem,

Bir doktorleyin çatar kaşını:

-Suyu şifadır, der.

Gerçekten de şifadır sanırım

Tüm kalbimle nineme inanırım.

Ne zaman şıpır şıpır nezle olsam,

Karnım kıvır kıvır ağrısa,

Ya da Ağustos güneşi altında

Çatlayacak gibi olsa başım,

Koşarım susuz taylar gibi,

Çam oluğun başında dururum,

Dayarım ağzımı çam oluğuna çeşmenin

Soğuk ve şifalı suyunu içerim 

Ve ta derinlerden derim: Ohh! 

Anında şifa bulurum.', '1/: Akar çam oluklu çeşmemiz, Akar karpuz çatlatan sular Şırıl da şırıl... O gece akar, gündüz akar Ben ise hep ona bakarım. Haziran çöker d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cam-oluklu-cesmenin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek Biziz', 'gelecek-biziz-ahmet-yozgat-lc8xp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hişt hişt! Hey çocuk, 

Bekle bizi, Biz geleceğiz. 

Hişt hişt! Hey çocuk inan kendine, 

Sen geleceksin.', 'Hişt hişt! Hey çocuk,  Bekle bizi, Biz geleceğiz.  Hişt hişt! Hey çocuk inan kendine,  Sen geleceksin....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gelecek-biziz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzler', 'i-zler-samiha-i-kbal-xuexd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hala hayal kırıklarını anlatır annem

Yaşama dair bildiklerini

Anne olmanın inceliklerini

Bakıp annemin buğulu gözlerine

-Konuş diye bağırdım

Hep doşruyu söyleyen yalanım ben

Tırnaklarımı söksen sesim çıkmaz

Ucunda evlat olunca

Kalbim bir atar bir atmaz

Evladın gözüne bakınca

Hep doğruyu söyleyen yalanım ben', 'Hala hayal kırıklarını anlatır annem Yaşama dair bildiklerini Anne olmanın inceliklerini Bakıp annemin buğulu gözlerine -Konuş diye bağırdım...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/izler-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-ahmet-yozgat-v12qe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Yaşlı ve gün görmemiş aralık, 

Çırpar ak abasını. 

Ak bir ışık gibi kar, 

Akar da babam akar...

2/:

Takvimin başı ocak, 

Gelmiştir çok uzak yoldan. 

Çırpar ayağının tozunu. 

Ak bir ayaz gibi kar, 

Akar da babam akar...', '1/: Yaşlı ve gün görmemiş aralık,  Çırpar ak abasını.  Ak bir ışık gibi kar,  Akar da babam akar... 2/: Takvimin başı ocak,  Gelmiştir çok u...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kar-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Dersem Gel Anne', 'elma-dersem-gel-anne-ahmet-yozgat-q326d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Elma dersem... Gel e mi? 

Uzak ve tozlu yollardan anne.

Ne boylu poslu dağlar kessin yolunu. 

Seni ne seller, ne yeller durdurabilsin, 

Elma dersem gel anne 

Ne olur al o sımsıcak kucağına bebeni

Özlemle kucakla beni.

2/:

Armut dersem... Çıkma e mi? 

Sıcacık yüreğimde kal anne.

Günler sel gibi aksa üstünden

Yedilik haftalar ve otuzluk aylar,

Bana unutturmasın seni.

Armut dersem kal orada e mi anne? 

Kal da yalnız koyma bebeni.

Akar da babam akar...', '1/: Elma dersem... Gel e mi?  Uzak ve tozlu yollardan anne. Ne boylu poslu dağlar kessin yolunu.  Seni ne seller, ne yeller durdurabilsin,  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/elma-dersem-gel-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsli Paslı Baca', 'i-sli-pasli-baca-ahmet-yozgat-spd00', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A/:

Simsiyah isli paslı baca... Acaba? 

Her ilk baharda konuk ettiğin

Hani nerde o leyleklerin? 

Bak aylardan nisan oldu,

Hatta mart oldu, mayıs oldu...

Uzakların habercisi o göçmen kuşlar

Ne uzattılar kınalı gagalarını,

Aramızdaki mor dağların ardından,

Ne de ''Tak tak tak! '' edip

''Merhaba.'' dediler bize.

Neden ses vermediler söyle

Onları çağıran özlem yüklü sesimize? 

B/:

Kapkara isli paslı baca... Acaba? 

Neden bu bahar gelmediler? 

O gagaları kınalı hacı leylekler

Bilesin ki onu bekler Ayşeler

Mehmetler hep onu bekler.

C/:

Mosmor isli paslı baca... Acaba? 

Her nisan sularında bir sabah

Sana usulca konuk olan 

O ak pak hacı leylek amcalar 

Neden uzatmadılar kınalı gagalarını 

Uzak ufukların ardından 

Niye çırpmadılar nakışlı kanalarını 

Süzülmediler havada neden? 

Daha onlar buralara gelmeden

Yuvayı onarmamız boşuna mı? ... 

Hoşuna mı gitmiyoruz artık onların? 

Ç/:

Simsiyah isli paslı baca, 

Hacı leylek amcalar, 

Bu yıl, bu nisanda

Gelmeyecek kanımca.

Sen çevreye yaydığın isinle yapayalnız

Ve sonsuza dek öylece kalacaksın

Sanırım yapayalnızca...', 'A/: Simsiyah isli paslı baca... Acaba?  Her ilk baharda konuk ettiğin Hani nerde o leyleklerin?  Bak aylardan nisan oldu, Hatta mart oldu, m...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/isli-pasli-baca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Kasabam', 'hayal-kasabam-ahmet-yozgat-2e547', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Dursam bir uçurumun başında

Karşımda kocaman ve dik duvar

Ne var ne yok çekilse iki yana

Erise çevrem, dünyam tükense, 

Silinse kahverengi gözlerimden, 

Beni kuşatan her şey

Haykırsam alabildiğince: 

''Heey hey! '' 

2/:

Atlasam uzun kuyruklu uçurtmama, 

Ulaşsam hayalimdeki kasabama. 

Yıksam dünden kalan tüm yapıları 

Yeniden kursam o hayal kasabamı

Birer birer tıklayıp kapıları,

Yüreğimi avuç avuç dağıtsam

Kucağıma doluşsa evsiz, barksız

Yani sevgisiz kalan her şey. 

Haykırsam olabildiğince: 

''Heey hey! ''

3/:

Durup dinlese beni çevremdekiler. 

Derleyip dünyadan getirdiğim, 

Minik masalları anlatsam onlara. 

El çırpsa insancıklar, 

Şapkalarını fırlatsalar havaya,

Yuvaya benzetip sımsıcak yüreğimi

Konuklarımı ağırlasam

Mutlu olsa tüm kasabam

Kasabamda barınan börtü, böcek

Yani soğukta kalan her şey.

Haykırsam olabildiğince: 

''Heey hey! ''', '1/: Dursam bir uçurumun başında Karşımda kocaman ve dik duvar Ne var ne yok çekilse iki yana Erise çevrem, dünyam tükense,  Silinse kahveren...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hayal-kasabam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezelden Arkadaşız Sizinle', 'ezelden-arkadasiz-sizinle-ahmet-yozgat-k8auf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Üstümde uçan tüm kuşlar,

Sayın ki serçe benim için.

Bütün serçeler de benim.

Onlar pır pır uçarken,

Beyaz bulutlar ülkesinden...

Ben bin dört köşe olurum,

Bayramdan arta kalan sevincimden.

Bu yüzden kuşlar ve ben, 

Arkadaşız ta ezelden.

2/:

Ufkumda yükselen tüm dağlar,

Sayın ki volkan benim için.

Bütün volkanlar da benim.

Onlar kıpkızıl ateş kusarken,

Uzak zamanların ortasında...

Ben zıp zıp zıplarım bu zamanda,

Artakalan bayramlık sevincimden.

İşte bu nedenle dağlar ve ben, 

Kol kolayız ta ezelden.

3/:

Çevremde açan tüm çiçekler,

Sayın ki gül benim için.

Bütün güllerde benim.

Onlar ışıl ışıl ışık saçarken,

Sarayların has bahçelerinden...

Ben koklar, bayılırım,

Bayramdan artakalan sevincimden.

Bu sebeple çiçekler ve ben, 

Koklaşırız ta ezelden.

4/:

Yuvanızı dolduran tüm çocuklar,

Sayın ki kardeş benim için,

Bütün kardeşler de benim.

Onlar nazlı nazlı boy atarken,

Annelerinin sevgili kucağından...

Ben ninniler söylerim,

Bayram artığı sevincimden.

İşte bu yüzden çocuklar ve ben, 

Arkadaşız ta ezelden.', '1/: Üstümde uçan tüm kuşlar, Sayın ki serçe benim için. Bütün serçeler de benim. Onlar pır pır uçarken, Beyaz bulutlar ülkesinden... Ben bin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ezelden-arkadasiz-sizinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Biz İdik', 'biz-biz-i-dik-ahmet-yozgat-8uz7z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Evvel zaman içindeydi sanırım... 

Bir adam duruyordu karanlıklar arasında. 

Elleri nasırlıydı

Ve şakağı kahır yüklü 

Bıyığı siyah mı siyahtı.

O adam bana baktı sevgi ile

Ben hayretle ona baktım...

2/:

Kalbur saman içindeydi sanırım... 

Bir kadın duruyordu sisler ardında. 

Elleri kıvrım kıvrım kınalıydı 

Sevgi yüklü yüreciği yaralı 

Gözleri siyah mı siyahtı. 

O kadın bana baktı sevgi ile

Ben hayretle ona baktım...

3/:

Cinler cirit oynuyordu sanırım... 

Bir çocuk duruyordu puslu bir havada. 

Pamuk elleri yumuk yumuktu

Ela gözleri bir yudumluk 

Saçları siyah mı siyahtı.

O çocuk bana baktı sevgi ile

Ben hayretle ona baktım...

1/a:

Evvel zaman içindeyken 

Orda duran babammış meğer.

Bu haber dünyaya değer! 

2/a:

Kalbur saman içindeyken

Orda duran anammış meğer.

Bu haber dünyaya değer! 

3/a:

Cinler cirit oynarken 

Orda duransa benmişim meğer.

Bu haber dünyaya değer! 

4/:

Babam. Anam. Ve ben,

Buluştuk aynı zamanda,

Eski ama sıcak bir hamam içinde

Tanıştık. Ve...

Başladık kendi masalımızı yaşamaya...', '1/: Evvel zaman içindeydi sanırım...  Bir adam duruyordu karanlıklar arasında.  Elleri nasırlıydı Ve şakağı kahır yüklü  Bıyığı siyah mı siy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/biz-biz-idik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açıl Demir Kapım Açıl', 'acil-demir-kapim-acil-ahmet-yozgat-d7j3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

İçimde tam bin yıldan beri

Kilitli duran demirden kapı, 

Hiç ama hiç ummadığım bir zamanda, 

Birden bire açılacak biliyorum.

Merakla bekliyorum...

Çıkıp gelecek içerden, 

On yaşımdaki ben. 

Beyninde büyüme özlemi, 

Şimdinin küçülme özlemine denk 

O çocuk arzuyla büyüyecek, 

Küçüklüğünün kıymetini bilmeyen

2/:

Mutlaka açılacak biliyorum,

Merakla bekliyorum... 

Açılacak beş yaşın üzerine, 

Bin bir kilitle ve sımsıkı kilitlenen, 

O pas tutmuş çelikten kapı.

Turaçlar gibi uçarak çıkacak içerden, 

Hiç tanımadığım ben. 

Kahverengi gözlerinde yaş,

Yavaş yavaş ve zaman içinde kayarak

Bilmediğim bir dille ağlayarak, 

O çocuk arzuyla büyüyecek, 

Minikliğini aşağılayarak.', '1/: İçimde tam bin yıldan beri Kilitli duran demirden kapı,  Hiç ama hiç ummadığım bir zamanda,  Birden bire açılacak biliyorum. Merakla bek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/acil-demir-kapim-acil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatallı Kapının Öyküsü', 'catalli-kapinin-oykusu-ahmet-yozgat-vyvp6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Bir varmışla bir yokmuş

Sayın ki çatallı kapı...

Bir kere tutuldu mu onların sapı,

Bırakılmaz bir daha asla.

Açılır gıcırtıyla ta ardına dek.

Girilir alacakaranlıktan içeri,

Kıvrıla kıvrıla Kaf dağına gidilir.

O sırada masalcı bilge ninenin biri,

Oturmuştur Kaf dağının yamaçlarına.

Avuç avuç bir varmış,

Kucak kucak bir yokmuş derer.

''Yok mu beni dinleyen? '' der mır mır.

''Biz varız ya işte nine

Sınırsız zamanımız 

Tüm masalları dinlemeye yeter.''

2/:

Bir varmışla bir yokmuş

Yapışık ikiz kardeştir...

Biri Keloğlana yoldaştır kardeşlerin

Diğeri ise azman devlere eştir

Şimdi masalcı bilge ninenin biri

Oturmuştur çatallı kapının aralığına

Deste deste bir varmış,

Tomar tomar bir yokmuş derer elleri.

''Yok mu beni dinleyen? '' der.

''İşte biz varız ya nine

Zamanımız tüm masallara yeter.''', '1/: Bir varmışla bir yokmuş Sayın ki çatallı kapı... Bir kere tutuldu mu onların sapı, Bırakılmaz bir daha asla. Açılır gıcırtıyla ta ardına...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/catalli-kapinin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumun Hayal Perdesi', 'cocuklugumun-hayal-perdesi-ahmet-yozgat-fkb9d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

-G i r i ş-

Ne zaman gün kızarsa nal gibi

Akşam çökse bir dev gibi çatılara 

Bulutlar yaprak gibi titrerler. 

Yırtılırlar ortasından ufuklar

Çıka gelir çocukluğum uzaktan

Rap rap rap! Çakı gibi

Tef çalar. Perde kurar...

2/:

-Perde Bir-

Bir kadın ışıl ışıl gülümser

Bir baba üzerime eğilir ılık ılık 

Yumuşacık bir şey konar alnıma

''Şap! '' eder damla gibi

Perde kapanır. Işıklar söner...

3/:

-Perde İki-

Gözlerimin zeminini ören kare,

Dolar gün be gün ve tatlı tatlı.

Bir kelebek dolanır çevremde

''Pır pır'''' ederek ve bin kanatlı

Der ki o an şarkılı bir ses:

''Bak bu annendir senin.

Babandır bu, bu da ninen...''

Kare dolar habire.

Mırıl mırıl türkülü bir ses:

''Bu da yaşlı ve bilge dededir.'' der...

Perde kapanır. Işıklar söner...

4/:

-Perde Üç-

Korkutucu sesleriyle kurtlar ulur dağlarda.

Karanlık geceler uzar ha uzar.

Oturtur torununu dizi dibine,

Saçlarına kar yağmış bir bilge nine,

Akmaya başlar ilk masalına

O an Keloğlan iner avuçlarıma

Tatlı mı tatlı ve mırıltılı bir ses:

''Bir varmış, bir yokmuş...'' der

Perde kapanır. Işıklar söner.

5/:

-Perde Dört-

Pamuk beyazlığında ve yumuşak bir el,

Mavi nazar boncuğu asar omuzlarıma.

Okur kuru dudaklarıyla mırıl mırıl,

Okur gözleri kapalı...

Omzumda rengarenk çantam,

Saçlarım lüle lüle taralı.

Yeni boyalı ve gıcır gıcırdır,

Şu anda ayaklardaki pabuçlar.

Kalbimden serçeler uçar.

Pamuk beyazlığında bir el,

Yumuşacık saçımı okşar,

''Saklasın Rabb''im nazardan'' der

Perde kapanır. Işıklar söner.

6/:

-Perde Beş-

Mızrap tutan bir el dokunur,

Uzun saplı bağlamanın teline.

Fidaydayı söyler ince bir ağız.

Siyah takım elbiseli bir adam,

Kalın kaşlı ve karayağız...

Açar o uğursuz siyah deriden çantasını.

Bir kere parlar usturası,

Makası ''Şak! '' eder.

Bir acı yayılır bacaklarıma.

Kara giysili adam sırıtarak:

''Oldu da bitti, maşallah! '' der

Perde kapanır. Işıklar söner.

7/:

-Perde Altı-

Ay doğar oylum oylum dağlar ardından, 

Gün doğar gözüme ipil ipil, 

Salkım salkım söğütler dökülür, 

Yosun yeşili serin sulara. 

Bizim mahalleden bakınca, 

Diğer mahalle görülür. 

Ayşe kızın saçları sarı, 

Gözleri dut kurusu. 

Ayşe okuldan sıra arkadaşım, 

Gönlümün tarifsiz duygusu.

Ayşe kızın anası yabancı değil

Uzaktan akrabası babamın 

İçimden bir ses, 

Nefes nefese... Der: 

''Bu kız çocukluğumun sevdası...''

Perde kapanır. Işıklar söner...

8/:

-Son Perde-

Ne zaman güneş kızarsa karşımda,

Pencereme usulca ve sinsice,

Sinse karanlık bir yaygı gibi akşam.

Ela galsa gözlerim uzaklara.

Çocukluğum yorgun argın,

Çıkıp gelse karşıdan,

Perde kursa ufuklara,

Tiril tiril titrese gönül kuşum.

Şu kadın yani çocuklarımın anası,

Biraz asabidir de eşim,

Tutup uçundan camdaki perdelerin,

Çeker ve kapatıverir önümü.

Ne gurubun kızılı kalır,

Ne de temsili çocukluğum.

Der: ''Sofra hazır! ''

Perde son kez kapanır,

Bütün ışıklar söner...', '1/: -G i r i ş- Ne zaman gün kızarsa nal gibi Akşam çökse bir dev gibi çatılara  Bulutlar yaprak gibi titrerler.  Yırtılırlar ortasından ufu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":106,"source_url":"https://www.antoloji.com/cocuklugumun-hayal-perdesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Kedinin Bir Günü', 'bizim-kedinin-bir-gunu-ahmet-yozgat-7w56h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizim sevimli mestan kedi:

Sabah erkenden bana: 

''Süt isterim.'' dedi.

Bizim sevimli mestan kedi:

Sabah erkenden bana:

''Ciğer isterim.'' dedi.

Bizim sevimli mestan kedi,

Oturdu benimle masaya, 

Sütü içti. Ciğeri yedi. 

Bizim sevimli mestan kedi:

Masadan kalkarken bana:

''Sağ ol ağabey.'' dedi.

Bizim sevimli mestan kedi:

Süründü bacağıma:

''Sevilmek isterim.'' dedi. 

Bizim sevimli mestan kedi:

Mırıl mırıl mırladı:

''Oyun isterim.'' dedi.

Bizim sevimli mestan kedi,

Çıktı benimle arsaya,

Sevdirdi kendini arkadaşlara,

Katıldı tüm oyunlara.

Bizim sevimli mestan kedi:

Bütün dostlara:

''Teşekkür ederim.'' dedi.', 'Bizim sevimli mestan kedi: Sabah erkenden bana:  ''Süt isterim.'' dedi. Bizim sevimli mestan kedi: Sabah erkenden bana: ''Ciğer isterim.'' dedi....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bizim-kedinin-bir-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe Hanım', 'serce-hanim-ahmet-yozgat-m5x13', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/... 

Çok severdi mini minnacık evini, 

Kahverengi küçük serçe hanımcık. 

Bir de eşini severdi tabii ki...

Doyamazdı sımsıcak yuvasına,

Kahverengi küçük serçe hanımcık, 

Bir de yavrusuna doğal olarak...

1/a:

Hanım serçecik... Canım serçecik, 

Buldun işte sığınacak bir bahçecik. 

2/...

Her sabah erkenden kalktığında, 

Eşini işe uğurlardı sevinçle.

Yavrusunu ise komşu boş bahçeye 

Evcilik oynamaya yollardı sevine sevine.

2/a:

Hanım serçecik... Canım serçecik, 

Buldun işte mutluluğu hemencecik.

3/...

İşe giden eşini özlerdi.

Kahverengi küçük serçe hanımcık, 

Bir de gün boyu boş bahçede 

Komşu yavrularla evcilik oynayan, 

Minicik yavru serçeyi özlerdi.

3/a:

Hanım serçecik... Canım serçecik,

Neden yavrun bir tanecik? 

4/...

Her gün akşam olduğunda yuvada, 

Kahverengi anne serçe hanımcık.

Oturup pencereye hanım hanımcık, 

Başlardı beklemeye.

4/a:

Hanım serçecik... Canım serçecik,

Hüzünlendin hemencecik.

5/...

Görüp gözledikten sonra yuvayı

Çıktı yine bu akşam, 

Kahverengi küçük serçe hanım, 

Bir söğüt dalındaki yuvanın eşiğine.

Gelecekti az sonra işe giden, yorgun eşi.

''Hanım hazır mı sofra? '' diyecekti

Belki de usulca öpecekti

''Anne.'' diyecekti minik yavru

Oyunu yarım bırakıp gelince

Serçe hanım gülümseyecekti.

5/a: 

Hanım serçecik... Canım serçecik,

Mutlu oldun hemencecik.

6/...

Nihayet göründü karşıdan, 

Yuvanın yorgun argın babası.

Tıka basa dolu gibi gagası

''Hanım hazır mı sofra? '' dedi

Öptü usulca yanağından karısını

Yavrusunu sordu ardından

O yoktu henüz görünürlerde

''Biraz bekleyelim de...'' 

Ama bütün gece dönmedi,

Serçelerin oyun sever yavrusu.

Devrisi sabah yine sürdü bekleme

Ümitle devam edecekti 

Her akşam zavallı anne serçe, 

Yavrusunu bekleyecekti yine.

Bilemeyecekti yavrusunun evcilik yerine

Tuzağına düştüğünü avcılık oyununun.

6/a:

Hanım serçecik... Canım serçecik,

Yaralandın gepgencecik. 

7/...

Birkaç gün önce yavru serçecik,

Oynamak için evcilik,

Diğer minik yavrularla.

Komşu boş bahçeye varmıştı ama:

''Hiç canım istemiyor evcilik oynamayı...''

Demişti kendi kendine

Oradan geçmekteymiş bir kara kedi:

''Benim canım ise avcılık oynamak istiyor.''

Diye karşılık vermişti bizimkine

Hemen masum bir av olmuştu,

Bizim küçük yavru serçe.

Kara kedi ise olmuştu bir zalim avcı.

Başlamıştı çok tehlikeli bir oyun

Arkada hain kurt, önde masum koyun 

Avcı iştah ile yalanmıştı, 

Ağaçların çevresini dolanmıştı.

Az sonra olan olmuştu, 

Ne yazık ki avcı avını vurmuştu. 

7/a:

Hanım serçecik... Canım serçecik,

Yalnız kaldın gepgencecik.', '1/...  Çok severdi mini minnacık evini,  Kahverengi küçük serçe hanımcık.  Bir de eşini severdi tabii ki... Doyamazdı sımsıcak yuvasına, Kah...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/serce-hanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şır Şır Çeşme', 'sir-sir-cesme-ahmet-yozgat-i3t2s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Şır şır çeşmemiz; 

Yazın sopsoğuk. 

Kışın ılıman,

Ama her zaman,

Suyun tertemiz. 

2/:

Şır şır çeşmemiz; 

Tatlı suyunu,

Şimdi bizler içeriz. 

3/:

Sır şır çeşmemiz; 

Geçmişte içmiş, 

Suyunu dedelerimiz.

4/:

Şır şır çeşmemiz; 

Gelecekte tadacak, 

Tadını bebelerimiz.

5/:

Şır şır çeşmemiz; 

Nesiller boyu biz, 

Sana teşekkürler ederiz.', '1/: Şır şır çeşmemiz;  Yazın sopsoğuk.  Kışın ılıman, Ama her zaman, Suyun tertemiz.  2/: Şır şır çeşmemiz;  Tatlı suyunu, Şimdi bizler içer...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sir-sir-cesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şen Serseri', 'sen-serseri-hulki-can-3eyfj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gölgeliklerden 

Issız parklardan

Neon ışıklarından

Saç sakal bir yanda 

Sigara ve içki şişenle

Kaçıp gidiyorsun 

Ey şen serseri.

Ardında bıraktıkların

Onun aşkı için 

Kendini üzme ey kalbim

Kadınım benim

Kızım benim

Pırlanta gözlüm

Gözbebeğim 

Aygın baygın bakıyor

Ben kızım ama diyor

Ben de erkeğim diyorum

Kurtul büyü ne var bunda

Kim demiş yalandır sevmek? 

Hangi yalancı demiş bunu? 

Eğer sevmek yalansa

Yaklaşma o zaman

İstersen sana dönmem bir daha

Sevmem seni bir daha 

Aylak canım yansa da

Yoruldum ölüm göz kapaklarımda

Kaldırıma sızıp kalmışım

Paltomu çekip almışlar

Saatim

Ayakkabılarım

Param uçup gitmiş

Neyse ki sigaram ve şişem

Yanımdalar  hala. 

Çingene çocuklar başımda

Kıkır kıkır gülüşüyorlar

Kim aldı lan ayakkabıları diyorum

Abi sen ne içtin diyor biri

Bir çığlığı taşıyor sokak

Çöp bidonları arasındayım 

Kent uyanmış hızlı adımlarla

Yerde yatan sarhoşa bakıyor

Hastasınız hepiniz hasta

Ben yerdeyim kaçak ama

 Siz ayakta uyuyorsunuz

Açılın toplanmayın

Savulun et kafalar

Mutluyum ben mutluyum

Beyoğlunun bir ara sokağında

Karlı kaldırımlarda

Çoraplarla dolanıyorum

Ayakkabısız yürümek kötü 

Ama daha kötüsü yokluğun

Sevdim, sevdim

Çok sevdim ölesiye

Ölüm gibidir sevgi

İyi bir şey olsaydı

Önce tanrılar ölmez miydi

Yaşamayı öğreniyorum

Yaşadıkça yaşayacağım

En güzel içkileri içeceğim bu akşam

Gelmezsen eğer

Hesabı ödemeden kaçacağım', 'Gölgeliklerden  Issız parklardan Neon ışıklarından Saç sakal bir yanda  Sigara ve içki şişenle Kaçıp gidiyorsun  Ey şen serseri. Ardında bır...', ARRAY['Türk Edebiyatı','Şiir','Hulki Can']::text[], 8.5, '{"poet":"Hulki Can","poet_slug":"hulki-can","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/sen-serseri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü', 'turku-ahmet-yozgat-8g4a2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağrırsa bir yerim, 

''Haydi baba...'' derim.

''Bir türkü söyle bana.'' 

Türkü ilâç gibidir. 

Babam çok iyi bilir,

Hangi ağrıya hangi türkü iyi gelir.', 'Ağrırsa bir yerim,  ''Haydi baba...'' derim. ''Bir türkü söyle bana.''  Türkü ilâç gibidir.  Babam çok iyi bilir, Hangi ağrıya hangi türkü iyi g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/turku-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyunu Severim', 'oyunu-severim-ahmet-yozgat-uxlzz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Annemi severim. 

Babamı daha çok,

Bir de oyunu tabii ki.

2/:

Dedemi severim. 

Ninemi daha çok, 

Bir de körebeyi tabii ki.

3/:

Ağabeyimi severim, 

Ablamı daha çok, 

Bir de çelik-çomağı tabii ki.

4/:

Halamı severim,

Amcamı daha çok, 

Bir de kovalamacayı tabii ki.

5/:

İnsanları severim, 

Tüm canlıları daha çok, 

Bir de uçurtmayı tabii ki.

Severim canım gibi, 

Çevredeki her bir şeyi.

Başı beyaz başlıklı dağı, 

Örtüsü yeşil olan ovayı, 

Şırıltısı ninni gibi dereyi, 

Kuzu güttüğüm tepeyi, 

Bir de sobeyi tabii ki.', '1/: Annemi severim.  Babamı daha çok, Bir de oyunu tabii ki. 2/: Dedemi severim.  Ninemi daha çok,  Bir de körebeyi tabii ki. 3/: Ağabeyimi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/oyunu-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Allah''ın Günü', 'her-allah-in-gunu-ahmet-yozgat-lspap', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Takvimdeki her Allah''ın günü; 

Televizyon ekranında görünen, 

Kara kaşları çatık amcalar.

Ellerinde kocaman bir mikrofon, 

Durmadan birbirini karalar. 

2/:

Takvimdeki her Allah''ın günü; 

Televizyonda görünen, 

Siyah takım elbiseli amcalar.

Ellerinde soğuk tabancalar, 

Patır patır birbirini yaralar.

3/:

Takvimdeki her Allah''ın günü; 

Televizyon karşısında otururlar, 

Masum Alicikler,

Ve mazlum Ayşecikler,

Hiçbir şeyden habersiz Fatmacıklar,

Hayran hayran olanları izlerler...', '1/: Takvimdeki her Allah''ın günü;  Televizyon ekranında görünen,  Kara kaşları çatık amcalar. Ellerinde kocaman bir mikrofon,  Durmadan birb...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/her-allah-in-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parasız Yatılı', 'parasiz-yatili-ahmet-yozgat-n045u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kazanamadım,

Geçen yıl parasız yatılıyı,

Evden kaçmayı denedim.

Kazanamazsam eğer,

Bu yıl da parasız yatılıyı.

Annem,

Ya da babam,

Denesin evden kaçmayı. 

Benden çok kazanmayı 

İstediklerine göre onlar.

Kaçak olmak da onların hakkı.', 'Kazanamadım, Geçen yıl parasız yatılıyı, Evden kaçmayı denedim. Kazanamazsam eğer, Bu yıl da parasız yatılıyı. Annem, Ya da babam, Denesin e...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/parasiz-yatili-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koskocaman Amcalar', 'koskocaman-amcalar-ahmet-yozgat-ov9kq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Kocaman kocaman şiirler yazan, 

Koskocaman amcalar.

Kendiniz okuyun yazdıklarınızı, 

Ben körebe oynayacağım.

2/:

Kocaman kocaman öyküler yazan, 

Koskocaman amcalar.

Kendiniz okuyun yazdıklarınızı,

Ben saklambaç oynayacağım. 

3/:

Koskocaman amcalar, 

Yazmayın kapağına.

O kocaman kitapların, 

Çocuk şiiri diye,

Ya da çocuk öyküsü diye.

Gerçek sanıyorum yazılanı, 

Yani aldanıyorum.

Bütün harçlığımı verip, 

Alıyorum kitabı.

İşte o zamana sizin, 

Koskocaman yalancılar,

Olduğunuza inanıyorum.', '1/: Kocaman kocaman şiirler yazan,  Koskocaman amcalar. Kendiniz okuyun yazdıklarınızı,  Ben körebe oynayacağım. 2/: Kocaman kocaman öyküler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/koskocaman-amcalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teyzem Zühal', 'teyzem-zuhal-ahmet-yozgat-76y5c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zühal teyzem gelince bize,

Hemen başlar söze:

''Kızım kola içme! '' 

''Oğlum şeker yeme! '' 

''Televizyon seyretme sakın! ''

''içme terli terli suyu ha! ''

''Erken uyu! ''

Ne olursun Zühal teyze, 

Her gün gelmesen bize.

Gelirsen gel ama 

Hemen başlama söze.', 'Zühal teyzem gelince bize, Hemen başlar söze: ''Kızım kola içme! ''  ''Oğlum şeker yeme! ''  ''Televizyon seyretme sakın! '' ''içme terli terli suy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/teyzem-zuhal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-ahmet-yozgat-7mcyk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kocaman dağlar, 

Karşımda durur.

Başına bulut bağlar, 

Gece uyur, gündüz uyur.

2/:

Kocaman dağlar, 

Bir bana bakar, 

Bir çorak ovaya.

Üzülür ve yağmur ağlar.', 'Kocaman dağlar,  Karşımda durur. Başına bulut bağlar,  Gece uyur, gündüz uyur. 2/: Kocaman dağlar,  Bir bana bakar,  Bir çorak ovaya. Üzülür...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/daglar-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya Atına Binerim', 'ruya-atina-binerim-ahmet-yozgat-x9hkl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Binerim her akşam, 

Rüyamın kır atına

Bir çırpıda çıkarım, 

Göğün birkaç katına

Kır atımın yelesini tutarım,

Yıldızlardan dünyaya, 

Işıktan çiçek yapıp atarım, 

2/:

İşte böyle her akşam ben, 

Rüya atıma binerim,

Sürerim sürerim geceler boyu

Hiç canım istemez ama

Sabah olunca inerim.', '1/: Binerim her akşam,  Rüyamın kır atına Bir çırpıda çıkarım,  Göğün birkaç katına Kır atımın yelesini tutarım, Yıldızlardan dünyaya,  Işık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruya-atina-binerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-ayse-adlim-hq5dq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğdun bebeğim

Yaşayacaksın bilmeden

Çocuk olacak

Annen, baban için

Öğrenci olacak

Kitabın, kalemin

Öğretmenin

Başarın için

Genç kız olacak

Önce namusun için

Ailen çevren için

yaşayacaksın

Bir gün evleneceksin

Kadın olacak

Kocan için

Anne olacak

Çocukların

Sevenlerin için

yaşayacaksın

Kimse seni

Duygularını

İsteklerini

Arzularını sormayacak

Onlar hep

Sırasını bekleyecek

Yaşanmak isteyecekler

Belki de zaman zaman

Sen bile duymayacaksın

Duymazlıktan geleceksin

Hep susturulmuş

Hep bastırılmış

kalacaklar

Ne olur bebeğim

Sen bari

Her şey için

Herkes için yaşarken

Ne olur biraz da

Kendin için yaşa', 'Doğdun bebeğim Yaşayacaksın bilmeden Çocuk olacak Annen, baban için Öğrenci olacak Kitabın, kalemin Öğretmenin Başarın için Genç kız olacak ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bebegim-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulağına Kiraz Asan', 'kulagina-kiraz-asan-ahmet-yozgat-u7s6a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kulağına kiraz asan,

Küpeli küçük kardeş.

Küpe olsun kulağına, 

Duyduğun güzel şeyler.', 'Kulağına kiraz asan, Küpeli küçük kardeş. Küpe olsun kulağına,  Duyduğun güzel şeyler....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kulagina-kiraz-asan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemin Adresi Yüreğim', 'annemin-adresi-yuregim-ahmet-yozgat-3ov9y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

İstemem,

Amasya''dan elmayı, 

Kaymağı ise Afyon''dan, 

Sizin olsun Diyarbakır karpuzu. 

Vazgeçtim şen şakrak rüyalarımdan. 

Alın toz pembe hayallerimi. 

Bana verin yalnızca 

O güzeller güzeli annemi! 

2/:

İstemem,

Adana''dan beyaz pamuğu, 

Konya''dan ise esmer buğday... 

Ya da sizin olsun sarayı İstanbul''un 

Vazgeçtim bayramlık rüyalarımdan. 

Alın gül kokulu hayallerimi. 

Bana verin yalnızca 

O güzeller güzeli annemi! 

3/:

İstemem, 

İncirini Aydın''ın 

Güneşi sizin olsun Mersin''in. 

Edirne peynirini severim ama

İstemem yağlı kaymağını Afyon''un. 

Vazgeçtim rengarenk rüyalarımdan. 

Alın altın renkli hayallerimi. 

Bana verin yalnızca 

O güzeller güzeli annemi! 

Korkma Ufacık Çocuk

1/:

De bana mini minnacık çocuk

Neden ellerin ufacık? 

Bu turuncu Akdeniz portakalı. 

Bu sulu elma Amasya''dan. 

Muş''tan bu kadife tüylü ayvacık.

Al eline bunları usulcacık.

2/:

Söyle bana mini minnacık çocuk 

Neden ellerin ufacık? 

Isırmaz bu karabaş köpek. 

Bu mırnav kedi tırmalamaz. 

Bu ise oyuncak bir ayıcık. 

Al haydi eline usulcacık.', '1/: İstemem, Amasya''dan elmayı,  Kaymağı ise Afyon''dan,  Sizin olsun Diyarbakır karpuzu.  Vazgeçtim şen şakrak rüyalarımdan.  Alın toz pembe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/annemin-adresi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Daha mı Asla!', 'bir-daha-mi-asla-ahmet-yozgat-ypk4r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Bir...

Bir gün...

Bir gündü bulutlu mu bulutlu 

Unutup sevgili babamın uyarısını 

Şemsiyesiz çıktım dışarı 

Caddede yağmura yakalandım 

Islandım ki sırıksıklam.

Eğer uyaran babamsa 

Sözünden çıkmak mı bir daha asla.

2/:

Bir...

Bir gün...

Bir gündü güneşli mi güneşli 

Duymayıp babamın gerçek uyarısını 

Gölgeliksiz çıktım dışarı 

Güneşe çarpıldım ki yandım cayır cayır.

Eğer uyaran sevgili babamsa 

Güneşte kalmak mı bir daha asla.', '1/: Bir... Bir gün... Bir gündü bulutlu mu bulutlu  Unutup sevgili babamın uyarısını  Şemsiyesiz çıktım dışarı  Caddede yağmura yakalandım  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-daha-mi-asla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elmayı Yaratmış Portakalı da', 'elmayi-yaratmis-portakali-da-yusuf-onder-bahceci-zhov8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşünübiliyormusun elmayı yaratmış, portakalı da,

Sade portakal mı, turunç, limon, greyfurt dallar da,

Toprağa, tohumlarını atıyorsun ve bakıyorsun da,

Birinden kabak yetişiyor, diğerinden ise salatalık.

Toprak aynı toprak, su aynı su, peki nedir konusu,

Kabak yerde yetişiyor, elma ve armut ağaçlar da,

Durup şöyle bir düşünmek gerek, işin sırrı burada, 

Düşünübiliyormusun elmayı yaratmış, portakalı da,

r', 'Düşünübiliyormusun elmayı yaratmış, portakalı da, Sade portakal mı, turunç, limon, greyfurt dallar da, Toprağa, tohumlarını atıyorsun ve bak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/elmayi-yaratmis-portakali-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma Ufacık Çocuk', 'korkma-ufacik-cocuk-ahmet-yozgat-zf6qz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

De bana mini minnacık çocuk

Neden ellerin ufacık? 

Bu turuncu Akdeniz portakalı. 

Bu sulu elma Amasya''dan. 

Muş''tan bu kadife tüylü ayvacık.

