INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koleksiyoncu', 'koleksiyoncu-ahmet-yozgat-s97il', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne pul koleksiyonum var Ayşe gibi

Ne de Zühal gibi kelebek koleksiyonum

Kart koleksiyonu da yapmadım 

Esinlenip Mahmut''tan

Ben yürek topluyorum 

Hüzünlü yürekler...

Sevdalı yürekler... 

Ve umutlu yürekler...

Yapıyorum dünya dolusu 

Bir sevgi koleksiyonu', 'Ne pul koleksiyonum var Ayşe gibi Ne de Zühal gibi kelebek koleksiyonum Kart koleksiyonu da yapmadım  Esinlenip Mahmut''tan Ben yürek topluyo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/koleksiyoncu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-ahmet-yozgat-ehgx4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

İlkbaharda neşelenen ağaçlar

Hüzünlenir sonbaharla birlikte

Sararır yeşil  yapracıklar 

Birer birer koparlar dallarından

Akarlar ha babam akarlar

Ben onlara bakarım çipil çipil

Onlar bana bakarlar...

2/:

Kıştan haber ulaşır

Sokaklara sonbaharla birlikte

Sanki birer mektup olur yapracıklar 

Çöpçüler postacı sanki

Toplarlar ha babam toplarlar

Ben onlara bakarım çipil çipil 

Onlar bana bakarlar...', '1/: İlkbaharda neşelenen ağaçlar Hüzünlenir sonbaharla birlikte Sararır yeşil  yapracıklar  Birer birer koparlar dallarından Akarlar ha baba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonbahar-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balinayı Davet', 'balinayi-davet-ahmet-yozgat-1w3r2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Denizlerin gezgini tombul balina

Bugün yaş günüm benim 

Davet etsem seni de 

Gelir misin yanıma? 

2/:

İstemen kocaman hediyeler

Ne yeşil yosun okyanustan 

Ne de denizden istiridye incisi

Tek başına kendin gelsen yeter bana

Oluversen davetlilerimin 

En ilginci ve de en birincisi.', '1/: Denizlerin gezgini tombul balina Bugün yaş günüm benim  Davet etsem seni de  Gelir misin yanıma?  2/: İstemen kocaman hediyeler Ne yeşil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/balinayi-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rakamlardan Mesaj Var', 'rakamlardan-mesaj-var-ahmet-yozgat-kjcjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '5/:

Beş:

''Arıyorum kendime 

Şöyle elli ayaklı 

Güzel mi güzel bir eş.''

6/:

Altı:

''Beşin üstüyüm

Yerim yedinin altı.''

7/:

Yedi:

''Sağırım biraz 

Af buyurun 

Altı ne dedi? ''

8/:

Sekiz:

''İki sıfır üst üste

Yani sıfırlar ikiz.''

9/:

Dokuz:

''Tek rakamların en büyüğüyüm 

Ve bir rakamlı sayıların ağabeyi

Sekizin arkasından 

Önce gelirim ondan

Sağım solum önüm arkam sobe

Bana uyak bulmayan ebe.''

10/:

On:

''Sayıların ilk çifti

Bir bey ile sıfır hanım

Yaşarlar sıralarında 

Sevda ile 

Umutlu ve mutlu

Oğulları bir sürü 

Kızları dolu dolu.''

11/:

On''um:

''Çift rakamların ilki 

Tek rakamlarda sonum.''', '5/: Beş: ''Arıyorum kendime  Şöyle elli ayaklı  Güzel mi güzel bir eş.'' 6/: Altı: ''Beşin üstüyüm Yerim yedinin altı.'' 7/: Yedi: ''Sağırım bira...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/rakamlardan-mesaj-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaptıklarımdan Utandım', 'yaptiklarimdan-utandim-ahmet-yozgat-gzu1p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ressamdım

Bin bir renge boyardım 

Koca koca kağıtları

Günlerden bir gün 

Ebemkuşağını gördüm

Yaptıklarımdan utandım 

Ressamlığı bıraktım.

2/:

Müzisyendim 

İçli türküler yakardım

Kamış kavalım elimde 

Günlerden bir gün

Kınalı keklikler kondu bahçeme 

Yanık seslerini dinledim

Utancımdan inledim 

Müzisyenliği bıraktım.', '1/: Ressamdım Bin bir renge boyardım  Koca koca kağıtları Günlerden bir gün  Ebemkuşağını gördüm Yaptıklarımdan utandım  Ressamlığı bıraktım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yaptiklarimdan-utandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Atlılar', 'son-atlilar-ahmet-yozgat-js73p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Sular gibi akarak 

Son atlılarda geçtiler

Ben oradaydım.

2/:

Arkalarında taylarını 

Ve tozlarını bırakarak

Seller gibi çağlayarak 

Son atlılar da geçtiler

Ben oradaydım.

3/:

Kapatıp dizginlerini

Ve kolanlarını bağlayarak

Yıldızlar gibi kayarak 

Son atlılar da geçtiler

Ben oradaydım.

4/:

Arkalarında taylarını 

Ve nal izlerini bırakarak

Seneleri sayarak 

Son atlılar da geçtiler

Ben oradaydım.

5/:

Işık sürüp yüzlerine 

Bize el sallayarak

Ne yazık ki ağlayarak 

Son atlılar da geçtiler

Ben oradaydım.

6/:

Geride bizi bırakarak 

Silinmez iz bırakarak

Bir oğlan bir kız bırakarak 

Son atlılar da geçtiler

Ben oradaydım...', '1/: Sular gibi akarak  Son atlılarda geçtiler Ben oradaydım. 2/: Arkalarında taylarını  Ve tozlarını bırakarak Seller gibi çağlayarak  Son a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/son-atlilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Civciv Kokan Çocuklar', 'civciv-kokan-cocuklar-ahmet-yozgat-naxsk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Civciv kokan çocuklar 

Gelirler güle ağlaya

İncecik kanatlarıyla uçarak 

Bir melek gibi mavi dünyaya

Konarlar yaşamın ince kulpuna.

2/:

Civciv kokan çocuklar 

Yatarlar annelerinin döşlerine

Açılır ipekten kanatları

Bir menekşe gibi mavi dünyaya 

Uçarlar kendi düşlerine.

3/:

Civciv kokan çocuklar 

Mini minnacık ayaklarla

İlk adımlarını korka korka

Basarlar kahverengi toprağa

Yürürler kendi hayallerine.

4/:

Civciv kokan çocuklar 

İnerler hayata sevine sevine

Unuturlar çabucak çocuk olduklarını 

Büyümüş gibi koşarlar işlerine

Bakakalırız biz arkalarından

Bir daha geri dönmeyecek gibi

Acele acele gidişlerine...

www.ahmetyozgat.com', '1/: Civciv kokan çocuklar  Gelirler güle ağlaya İncecik kanatlarıyla uçarak  Bir melek gibi mavi dünyaya Konarlar yaşamın ince kulpuna. 2/: ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/civciv-kokan-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yaz Amca', 'bir-siir-yaz-amca-ahmet-yozgat-x2kv9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Amca bir şiir yaz bana 

Minik minik açılsın ağzı 

Elleri yumuk yumuk olsun 

Uzansın ta gökyüzüne 

Işık saçan yıldızları kavrasın.

2/:

Amca bir şiir yaz bana 

Bal aksın orta yerinden

Kenarından şeker aksın 

Kırpışsın gözleri usul usul 

Sadece benden yana baksın.

3/:

Amca bir şiir yaz bana 

Serçe kanatlı olsun

Olsun karaca sekişli 

Öyle hızlı koşsun ki 

Rüzgardan atlı olsun.

4/:

Amca bir şiir yaz bana 

Bal olsun ilk dizesinde 

Son dizesi börek olsun 

Şiirimin tam içinde 

Kocaman bir yürek olsun.

www.ahmetyozgat.com', '1/: Amca bir şiir yaz bana  Minik minik açılsın ağzı  Elleri yumuk yumuk olsun  Uzansın ta gökyüzüne  Işık saçan yıldızları kavrasın. 2/: Am...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-siir-yaz-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Uzanıyorum', 'sana-uzaniyorum-sair-demet-s3v36', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'avuçlarında kaybolan ellerimle

sana uzanıyorum 

tutup yeşertmek için seni

sözcüklerimiz birer yarasa

gün ışığında uçamıyor

yakana asılı bir utanç olmuş

göğsüne takılan saçlarım

ellerim o kadar az

kollarım o kadar kısa ki

eksiklikler getiriyorum sana

düşle yamanmış sevda

gece aynalara düşünce karışıyor saçlarım

bir ben bir deniz tutuyor seni

konuştuğun uçurumlarda 

yankılanan ismimin isim anası kim

gözlerimi al defter aralarında kurut

şimdibenim sustuğum sözcükler

düşlerinden mektup olur çıkar mı...

kendini kanatmadan alabilir misin

gülü avucuna...', 'avuçlarında kaybolan ellerimle sana uzanıyorum  tutup yeşertmek için seni sözcüklerimiz birer yarasa gün ışığında uçamıyor yakana asılı bir ...', ARRAY['Türk Edebiyatı','Şiir','Şair Demet']::text[], 8.5, '{"poet":"Şair Demet","poet_slug":"sair-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-uzaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Topak Taş', 'bir-topak-tas-ahmet-yozgat-lxeh1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Bekler beni her sabah

Sokakta topak bir taş

Sanki ''Merhaba...'' der bana 

Ve usulca her gelene geçene:

''İyi günler satıcı amca...''

''Bol şanslar işçi abla...''

2/:

Çok komik gelir bana

Nedendir bilmem o anda

Topak taşın selam verişi

İşlerine giden insanlara

Dokunurum yumru yumru yanağına 

Ayağımın ucuyla usulcana

Nedense topak taş bundan 

Doğrusu ya hiç hoşlanmaz

Sanırım ki çok üzülür 

Çünkü o sırada ağızcığı büzülür

Siz onu taş kalpli sanırsınız ya

Bizim sokaktaki topak taş ağlar

Ve akıtır gri gözlerinden 

İki damla altın yaş

Vazgeçer insan olmaktan

Yine taşlaşır yavaş yavaş...

www.ahmetyozgat.com', '1/: Bekler beni her sabah Sokakta topak bir taş Sanki ''Merhaba...'' der bana  Ve usulca her gelene geçene: ''İyi günler satıcı amca...'' ''Bol ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-topak-tas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Rüzgâr', 'bizim-ruzg-r-ahmet-yozgat-4tlr2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Tuzlu rüzgâr

Hızlı rüzgâr 

Dolanırsın minnacık köyleri

Ve kocaman şehirleri

İşini seve seve

Taşırsın sırtında bizim eve 

Sırtında bütün mevsimleri.

2/:

Kaşlı rüzgâr

Gözlü rüzgâr

Esersin deli deli 

Dolanırsın dere, tepe

Tipi olursun kışta kar için

Yağmur olursun nisanda sepe sepe 

Görürsün her bir yeri.

3/:

Yazlı rüzgâr

Kışlı rüzgâr

Bazen türkü söylersin

Bir marş tutturursun bazen de

Koşarsın uygunsuz adımlarla hedefine 

Bazen de söylersin mırıl mırıl bir ninni

Uyutursun mışıl mışıl 

Ağlayan bütün bebekleri.

4/:

Yedi başlı rüzgâr

Devler gibi güçlü rüzgâr 

Yüklenip sırtına bulutları

Taşırsın bazen uzaklardaki denizden

Üstümüzden ''Vuu! '' diyerekten

Uçaklar gibi geçer gidersin

Sevindirirsin bizleri.

5/:

Gözleri yaşlı rüzgâr

Bazen buz gibi ayazlı

Bazen de ateşli rüzgâr 

Asmaları kuru bağlar ağlatır seni

Kıraç dağlarda yüzünü asarsın

Bozkırlarda ıslık çalar

Solgun bahçeleri sularsın 

Büyütürsün bütün çiçekleri.

www.ahmetyozgat.com', '1/: Tuzlu rüzgâr Hızlı rüzgâr  Dolanırsın minnacık köyleri Ve kocaman şehirleri İşini seve seve Taşırsın sırtında bizim eve  Sırtında bütün ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bizim-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dilenci', 'bir-dilenci-ahmet-yozgat-bhqdc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Dilenci

1/:

Bir dilenci her sabah 

Mendil açar köşeye

Oradan geçen bir beye:

''Allah rızası için'' der

İster:

''Bir ekmek parası! ''

2/:

Bir beyse fırın işletir

Yani günde bin bir ekmek üretir

Binini satar gün içinde

Ekmeklerin artar biri.

3/:

Bir bey her akşam 

Pişirdiği somunlardan 

Artanını çöpe atar 

Unutur zavallı dilenciyi.

www.ahmetyozgat.com', 'Bir Dilenci 1/: Bir dilenci her sabah  Mendil açar köşeye Oradan geçen bir beye: ''Allah rızası için'' der İster: ''Bir ekmek parası! '' 2/: Bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-dilenci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kocaman Olsam', 'kocaman-olsam-ahmet-yozgat-hv04b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Kocaman olsa ağzım 

İçsem denizlerin suyunu...

2/:

Kocaman kocaman olsa adımlarım 

Koşsam koşsam uzaklardaki çöllere ulaşsam

Dudağı çatlayan kıraç topraklara 

Cömert bulutlar gibi boşaltsam 

Ağzımdaki denizlerin suyunu.

3/:

Kocaman olsa yüreğim

Tüm insanların sevgilerini toplasam...

4/:

Kocaman kocaman olsa adımlarım 

Koşsam koşsam uzaklardaki çocuklara ulaşsam

Sevgisiz büyüyen çorak avuçlara 

Cömert ırmaklar gibi boşaltsam 

İnsanların sevgilerini.

5/:

Kocaman olsa ellerim 

Devşirsem ovaların bereketini...

6/:

Kocaman kocaman olsa adımlarım 

Koşsam koşsam uzaklardaki şehirlere ulaşsam

Karnı acıkan çocuklara 

Dağıtsam bütün yiyecekleri.

www.ahmetyozgat.com', '1/: Kocaman olsa ağzım  İçsem denizlerin suyunu... 2/: Kocaman kocaman olsa adımlarım  Koşsam koşsam uzaklardaki çöllere ulaşsam Dudağı çatl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kocaman-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkarcı Arkadaşım', 'cikarci-arkadasim-ahmet-yozgat-e6asd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Celal ceviz verirse 

En iyi arkadaşım odur.

Ayşe verirse elma 

O olur can arkadaşım.

Ceviz vermezse celal 

Eğer Ayşe elma vermezse

Bende kendime 

En iyi arkadaşlar ararım.', 'Celal ceviz verirse  En iyi arkadaşım odur. Ayşe verirse elma  O olur can arkadaşım. Ceviz vermezse celal  Eğer Ayşe elma vermezse Bende ken...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cikarci-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitap Macerası', 'kitap-macerasi-ahmet-yozgat-7mgnf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Okuldan çıkınca her gün 

Dönerim, dolaşırım 

Evime ulaşırım.

2/:

Önce salona girerim 

Selam veririm herkese

Sonra odama girerim 

Çantamı açarım hemen

Kitabıma girerim sonra 

Sayfaların içindeki odacıkları 

Gezerim, dolaşırım

Binerim bir rüzgarın sırtına

Kuşlarla yarışırım

Keloğlan''ın arkasından 

Kaf dağı''na ulaşırım

Bir tahta kılıç kuşanırım

Askerlere karışırım

Tahta atlara binerim

Devlerle savaşırım

Kötüleri yenerim

İyilerle buluşurum.

www.ahmetyozgat.com', '1/: Okuldan çıkınca her gün  Dönerim, dolaşırım  Evime ulaşırım. 2/: Önce salona girerim  Selam veririm herkese Sonra odama girerim  Çantamı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kitap-macerasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartopu Parası', 'kartopu-parasi-ahmet-yozgat-0495a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Bir hafta tüm harçlığımı verdim 

Bir beyaz top aldım kendime

Futbol oynadım yaz boyunca

Yağmur demeden, çamur demeden.

2/:

Ya kış boyunca oynadığım 

Koca koca kartopları paralı olsaydı

Ne yapardım ben? 

www.ahmetyozgat.com', '1/: Bir hafta tüm harçlığımı verdim  Bir beyaz top aldım kendime Futbol oynadım yaz boyunca Yağmur demeden, çamur demeden. 2/: Ya kış boyunc...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kartopu-parasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardan Adam Ne İster?', 'kardan-adam-ne-i-ster-ahmet-yozgat-xll69', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aralıkta yağan kar üşümez de

Ocakta kardan adam üşür neden? 

Doğrusu merak ettim 

Sordum dedeme

Dedem: ''Üşümez oğlum,'' dedi

''Eğer üşüseydi kardan adam

Bir de sizden kardan ev isterdi.''

www.ahmetyozgat.com', 'Aralıkta yağan kar üşümez de Ocakta kardan adam üşür neden?  Doğrusu merak ettim  Sordum dedeme Dedem: ''Üşümez oğlum,'' dedi ''Eğer üşüseydi k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kardan-adam-ne-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Dere Gider Nere?', 'bizim-dere-gider-nere-ahmet-yozgat-bn7e4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Bizim köyün içinden geçen 

Kıyısı kahverengi küçük dere

Gelir kim bilir ta nereden 

Gider kim bilir nereye? 

Sabah olsun demeden

Ve demeden gece

Köyden köye hece hece 

Bazen aşarak kocaman dağları 

Ovaları çizim çizim çize çize

Derin derin yaylaları yararak 

Ulaşır uzaklardaki koca denize.

2/:

Bizim köyün altından geçen 

Suyu bulanık küçük dere

Çıkar bizim çeşmeden geze geze

Gece oldu demeden

Ve hiçbir zaman demeden gündüz

Bu köyden o şehre dümdüz

Bazen dökülerek kocaman çağlayanlardan 

Yolları eğri doğru çize çize

Köprü altlarını derin derin yararak 

Ulaşır haritadaki engin denize...

www.ahmetyozgat.com', '1/: Bizim köyün içinden geçen  Kıyısı kahverengi küçük dere Gelir kim bilir ta nereden  Gider kim bilir nereye?  Sabah olsun demeden Ve deme...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bizim-dere-gider-nere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş İle Değiş Tokuş', 'kus-i-le-degis-tokus-ahmet-yozgat-lpied', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Hey küçük kuş, minik kuş 

Sen kanatlarını ver bana

Ben sana vereyim kollarımı

Kuş kardeş kanatlarla kolları

Edelim mi değiş tokuş

2/:

Hey küçük kuş, minik kuş

Sen tatlı ötüşünü ver bana

Ben sana vereyim ballı dilimi

Kuş kardeş karşılıklı dilleri

Edelim mi değiş tokuş

3/:

Hey küçük kuş, minik kuş

Sen bitmez sevgini ver bana

Ben sana vereyim tükenmez yüreğimi

Kuş kardeş karşılıklı sevgileri

Edelim mi değiş tokuş.

www.ahmetyozgat.com', '1/: Hey küçük kuş, minik kuş  Sen kanatlarını ver bana Ben sana vereyim kollarımı Kuş kardeş kanatlarla kolları Edelim mi değiş tokuş 2/: He...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kus-ile-degis-tokus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Avcı Amca', 'dur-avci-amca-ahmet-yozgat-vqsm3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Avcı amca dur 

Tek doğrult tüfeğini vur beni 

Acımaz mısın o kara kargaya? 

Söyle vurmaya nasıl varır elin? 

O kara karga

Ya yuvasına çöp taşıyan bir baba 

Ya da bir ana yavrusuna koşan bir.

2/:

Avcı amca dur

İstersen doğrult tüfeğini vur beni 

Nasıl kıyarsın o pamuk tavşana? 

Söyle nasıl kıyarsın vurmaya onu? 

Bilmez misin ki? 

O, ya bir baba yuvasına yiyecek taşıyan 

Ya da yavrusuna koşan bir ana.

www.ahmetyozgat.com', '1/: Avcı amca dur  Tek doğrult tüfeğini vur beni  Acımaz mısın o kara kargaya?  Söyle vurmaya nasıl varır elin?  O kara karga Ya yuvasına çö...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dur-avci-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak İle Soğuk', 'sicak-i-le-soguk-ahmet-yozgat-gnd3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Babam her akşam

Sobayı ateşleyince 

''Sıcaktan zarar gelmez.'' der

Doğrusu o her şeyi bilir 

Ama yanılıyor mu bu kez acaba? 

Soğuğun da sıcağın da

''Azı karardır

Ama çoğu zarardır.''

www.ahmetyozgat.com', 'Babam her akşam Sobayı ateşleyince  ''Sıcaktan zarar gelmez.'' der Doğrusu o her şeyi bilir  Ama yanılıyor mu bu kez acaba?  Soğuğun da sıcağı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sicak-ile-soguk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Nasıl Rüya?', 'bu-nasil-ruya-ahmet-yozgat-7s00e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedense her gece 

Korkunç oluyor rüyam

Hele yanımda yoksa cesur babam 

Uzaklardaysa korkusuz ablam 

Yürekli annem yatağımda değilse

Bir öcüler giriyor düşüme 

Bir karabasanlar

Gulyabaniler üstüme üstüme geliyor 

Torbalılar kovalıyor ardımdan gece boyu

Kara gonculuzlar tutuyor kolumu 

Kara kuralar kafamı yarıyor 

Hortlaklar dişimi kırıyor

Her gece hep böyle 

Korkunç oluyor rüyam

Sonra geliyor odama atak babam

Korkuyorlar bütün yaratıklar babamdan 

Bense nedense korkuyorum onlardan.

www.ahmetyozgat.com', 'Nedense her gece  Korkunç oluyor rüyam Hele yanımda yoksa cesur babam  Uzaklardaysa korkusuz ablam  Yürekli annem yatağımda değilse Bir öcül...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-nasil-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüdüm Üşüdüm', 'usudum-usudum-ahmet-yozgat-1o46x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En sonunda kış geldi 

Yani hayatıma soğuk geldi

''Üşüdüm üşüdüm...''

Ama daldan elma düşüremedim.

Halbuki yazın sıcakken havalar

Ne çok olurdu ağaçlarda elmalar

Düşürür düşürür yerdim.

www.ahmetyozgat.com', 'En sonunda kış geldi  Yani hayatıma soğuk geldi ''Üşüdüm üşüdüm...'' Ama daldan elma düşüremedim. Halbuki yazın sıcakken havalar Ne çok olurdu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/usudum-usudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satıcıyım Ama...', 'saticiyim-ama-ahmet-yozgat-iq6a7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Nasıl tanımazsınız beni? 

Yaz sıcaktır demeden

Soğuktur kış demeden

Sizin mahalle pazarındayım 

Sağ kenardaki tezgahta satıcıyım

Yağ satarım 

Bal satarım

Bal da yemem yağ da yemem

Çoğu zaman yarı tok

Yarı aç yatarım.

2/:

Nasıl anımsamazsınız beni? 

Akşam geç demeden

Sabah erken demeden

Sizin sentin pazarındayım 

Sol kenardaki tezgahta satıcıyım 

Kazak satarım 

Gömlek satarım

Bayramda bile kazak giyemem 

Gömlek de giymem düğünde bile

Çoğu zaman yarı açık

Yarı çıplak yatarım.

www.ahmetyozgat.com', '1/: Nasıl tanımazsınız beni?  Yaz sıcaktır demeden Soğuktur kış demeden Sizin mahalle pazarındayım  Sağ kenardaki tezgahta satıcıyım Yağ sat...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/saticiyim-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar Nereye Gider?', 'sokaklar-nereye-gider-ahmet-yozgat-rdbhb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Bizim evin önünden 

Bir uzunca sokak geçer

Şu köşede sağa döner 

Döner sola bir sonraki köşede 

Uzaklaşır döne döne 

Köşelerle kol kola.

2/:

Bizim evin önünden

Bir daracık sokak geçer

Her eve uğrar 

Birer kova su içer

Baharda toz toprak demez 

Kışda kar buz demez

Bizim sokak uğrar da her eve 

Hiç birinin kapısından içeriye giremez

Uzaklaşır döne döne 

Yalnızlıkla kol kola...

www.ahmetyozgat.com', '1/: Bizim evin önünden  Bir uzunca sokak geçer Şu köşede sağa döner  Döner sola bir sonraki köşede  Uzaklaşır döne döne  Köşelerle kol kola....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sokaklar-nereye-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yağdı Yaşasın!', 'kar-yagdi-yasasin-ahmet-yozgat-s8cwj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Yaşasın! 

Kar yağdı...

Şimdi kartopunun zamanı

En iyi ben oynarım bu oyunu

Bakın devirdim kenan''ı

Yeniverdim canan''ı 

Pes ettirdim yaman''ı.

2/:

Yaşasın! Karyağdı...

Şimdi kardan adam zamanı

En iyi ben yaparım bu adamı 

Bakın turuncu havuçtan burnuna

Ne kadar da komik değil mi? 

Bu da yünlü atkısı

Kafası ister eski bir kasket

Bu adam bana yalnız bana ait 

Kimsenin yok katkısı.

www.ahmetyozgat.com', '1/: Yaşasın!  Kar yağdı... Şimdi kartopunun zamanı En iyi ben oynarım bu oyunu Bakın devirdim kenan''ı Yeniverdim canan''ı  Pes ettirdim yaman...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kar-yagdi-yasasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acep Ne Yaparım?', 'acep-ne-yaparim-ahmet-yozgat-mzgbu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Sayı sayarım 

Resim yaparım 

Yazı yazarım

Ya ellerim olmasa ben ne yaparım? 

1a/:

Yaşasın ellerim! 

Çok yaşasın ellerim! ...

Siz olmasanız ben ne ederim? 

2/:

Şehri gezerim 

Köyü gezerim 

Okula giderim

Ya ayağım olmasa ben ne ederim? 

2a/:

Yaşasın ayaklarım! 

Pek yaşasın ayaklarım! ...

Siz olmasanız ben yerimden nasıl kalkarım? 

www.ahmetyozgat.com', '1/: Sayı sayarım  Resim yaparım  Yazı yazarım Ya ellerim olmasa ben ne yaparım?  1a/: Yaşasın ellerim!  Çok yaşasın ellerim! ... Siz olmasan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/acep-ne-yaparim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemin Giysileri', 'annemin-giysileri-ahmet-yozgat-8lhdn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Annemin kahverengi kazağı bol 

Pileli beyaz eteği uzun

Kareli mavi ceketi geniş 

Ağzı tüylü pabuçları kocaman

Annem çarşıya çıktığı zaman 

Anne olmak isterim

Kazak bol olsa da 

Uzun olsa da etek

Olsa da geniş ceket

Kocaman bu pabuç demez 

Üzerime çekerim 

Ayağıma giyerim

Kendiminki dururken 

Aksilik bu ya

Annemin ölçüsüz giysilerini 

Giymeyi ne çok isterim.

www.ahmetyozgat.com', 'Annemin kahverengi kazağı bol  Pileli beyaz eteği uzun Kareli mavi ceketi geniş  Ağzı tüylü pabuçları kocaman Annem çarşıya çıktığı zaman  A...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/annemin-giysileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaramaz Tebeşir', 'yaramaz-tebesir-ahmet-yozgat-vr0jo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Beyaz tebeşir söyle nedendir? 

Bizim öğretmenin elinde 

Güzel şeyler yazarsın karatahtaya

''Üç iki daha beş eder.'' 

''Leylekler sıcak ülkelere gider.'' 

''Kızılırmak dökülür karadenize.''

Ve daha neler neler...

2/:

Geçirince seni eline 

Şu bizim haylaz yılmaz

İşte o zaman durmaz oturmaz

Başlarsın taşa ağaca kapıya 

Şöyle şöyle şeyler yazmaya:

''Ali ayşe''yi seviyo''

''Buraya çöp döken eşektir.''

''Bunu yazan tosun.'' 

''Herkes okusun.''

3/:

Beyaz tebeşir de hele

Senden midir bu güzellik

Ya da bu çirkinlik kimdendir? 

www.ahmetyozgat.com', '1/: Beyaz tebeşir söyle nedendir?  Bizim öğretmenin elinde  Güzel şeyler yazarsın karatahtaya ''Üç iki daha beş eder.''  ''Leylekler sıcak ülke...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yaramaz-tebesir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninemin Gözlüğü', 'ninemin-gozlugu-ahmet-yozgat-ffhqb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabah erkenden kalkar

Ninem gözüne gözlüğünü takar

Döner bana bakar 

Gün boyu örgü örer

Yine döner bana bakar 

Sepet dolusu dikiş diker

Bir daha döner bana bakar 

İğneye iplik takar

Teker teker yamar tüm yırtıkları 

Gözlüğünün üzerinden 

Döner döner yine bana bakar

Yıldızlar gibi gülümser 

Anlar içimden geçeni

İtina ile çıkartır gözlüğünü 

Getirir benim gözüme takar

O anda dünya silinir önümde 

Başım fırıldak olur 

Döner de ha babam döner...

Bulanır midem ağzıma gelir

Ninemi gördüren gözlük 

Nedense bilmem kor ateş olur

Benim gözlerimi yakar.

www.ahmetyozgat.com', 'Sabah erkenden kalkar Ninem gözüne gözlüğünü takar Döner bana bakar  Gün boyu örgü örer Yine döner bana bakar  Sepet dolusu dikiş diker Bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ninemin-gozlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşan Yağmur Damlası', 'konusan-yagmur-damlasi-ahmet-yozgat-jpgm8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Pıt! '' dedi yağmur damlası 

Düştü ansızın ucuna burnumun

Yekindi hızla ayağa kalktı 

Dikti gözünü gözüme 

Baktı...baktı...baktı...

Gülümsedi dudağının ucuyla usulca

Bana: ''Şemsiyen? ...'' dedi 

''Haydi hemen onu aç.''

''Yok ki...'' dedim

Tekrar ''Pıt! '' dedi yağmur 

''Öyleyse durma kaç.''

Bir daha ''Pıt! '' dedi yağmur

''Bir saçak altı bul kendine.''

Bir bir daha ''Pıt! '' dedi yağmur 

''Islanırsın sonra.'' 

Bir bir bir daha ''Pıt! '' dedi yağmur 

''Sonra demedi deme...''

O anda geliverdim kendime

Hemen bir saçak altı buldum

Islanmaktan kurtuldum.

www.ahmetyozgat.com', '''Pıt! '' dedi yağmur damlası  Düştü ansızın ucuna burnumun Yekindi hızla ayağa kalktı  Dikti gözünü gözüme  Baktı...baktı...baktı... Gülümsed...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/konusan-yagmur-damlasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimiz Üşüse', 'yuregimiz-ususe-ahmet-yozgat-8ulg2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Kışın elimiz üşüse,

Hemen harlı sobaya tutarız,

Isınır ateş gibi,

Buz kesen elimiz,

Ya yüreğimiz üşüse, 

Acaba ne ederiz? 

2/:

Karda ayağımız üşüse, 

Yetişir imdadımıza çoraplarımız,

Isınır ateş gibi,

Buz kesen ayağımız,

Ya yüreğimiz üşüse, 

Acaba ne yaparız? 

www.ahmetyozgat.com', '1/: Kışın elimiz üşüse, Hemen harlı sobaya tutarız, Isınır ateş gibi, Buz kesen elimiz, Ya yüreğimiz üşüse,  Acaba ne ederiz?  2/: Karda aya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuregimiz-ususe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık', 'karanlik-ahmet-yozgat-jl4rk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Bütün küçük kardeşler gibi

Korkarım karanlıktan ben de 

Giremem tek başıma asla

O ışıksız odamıza

Eğer yanımda biri varsa 

Hiç mi hiç korkutamaz beni

Tüm yer yüzü bile ışıksız olsa.

2/:

Bütün küçük kardeşler gibi 

Korkarım ben de karanlıktan 

Yatamam tek başıma asla

Çekerim hemen kafama yorganımı

Ancak yanımda biri yatarsa 

Hiç mi hiç korkutamaz beni

Tüm gök yüzü bile karanlık olsa.

www.ahmetyozgat.com', '1/: Bütün küçük kardeşler gibi Korkarım karanlıktan ben de  Giremem tek başıma asla O ışıksız odamıza Eğer yanımda biri varsa  Hiç mi hiç ko...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karanlik-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedemin Gözlüğü', 'dedemin-gozlugu-ahmet-yozgat-zpwka', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dede canın gözlüğü çekti ilgimi

''Bakayım hele şuna.'' diye aldım elime

''Eyvah.'' tutamadım düşürdüm yere 

Kırılıverdi gözlüğün camı 

Ben kaşıyarak kafamı:

''Şimdi ne etsem? '' 

''Nereye gitsem? '' derken 

Aklıma geliverdi birden

Hemen daldım mutfağa 

Elime aldım çekici, keseri

İşe yaradı yağ şişesinin dibi.

www.ahmetyozgat.com', 'Dede canın gözlüğü çekti ilgimi ''Bakayım hele şuna.'' diye aldım elime ''Eyvah.'' tutamadım düşürdüm yere  Kırılıverdi gözlüğün camı  Ben kaşıy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dedemin-gozlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıllı Musluk', 'akilli-musluk-ahmet-yozgat-umosd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Banyomuzun musluğu 

Bilirim bir şey düşünemez 

Konuşamaz hiçbir şey

Ama banyomuzun musluğu 

Akıllıdır yine de

Bilse de bilmese de 

Yaşar şu ünlü atasözünü

Damlaya...damlaya 

Göl eder banyomuzu.

www.ahmetyozgat.com', 'Banyomuzun musluğu  Bilirim bir şey düşünemez  Konuşamaz hiçbir şey Ama banyomuzun musluğu  Akıllıdır yine de Bilse de bilmese de  Yaşar şu ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/akilli-musluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-mesut-egribas-mchtu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Git merhem olma yareme, kanarsa kanasın.

İstemem tesellini, gözyaşlarım aksın durmasın.

Yansın sinegahım,kavrulsun aşkınla her dem

Bırak, öldürsün beni bu dert derman bulmasın.', 'Git merhem olma yareme, kanarsa kanasın. İstemem tesellini, gözyaşlarım aksın durmasın. Yansın sinegahım,kavrulsun aşkınla her dem Bırak, öl...', ARRAY['Türk Edebiyatı','Şiir','Mesut Eğribaş']::text[], 8.5, '{"poet":"Mesut Eğribaş","poet_slug":"mesut-egribas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/git-167-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aman Be Baba!', 'aman-be-baba-ahmet-yozgat-py1au', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Oooo! 

Eveleme

Geveleme

Ne demek istiyorsun? 

Söylemiyorsun neden gerçeği.

2/:

Oooo! 

Eveleme

Geveleme

Dosdoğru olarak 

Düzgün cümle kurarak...

3/:

Oooo! 

Eveleme

Geveleme

Eğip bükmeden ne söyleyeceksen

Söylesene artık be baba! 

4/:

Oooo! 

Eveleme

Geveleme

Biliyorum ben de artık 

Beni ta uzaklardan buraya 

Getirmediğini bir leyleğin.

5/:

Oooo! 

Eveleme

Geveleme

........

www.ahmetyozgat.com', '1/: Oooo!  Eveleme Geveleme Ne demek istiyorsun?  Söylemiyorsun neden gerçeği. 2/: Oooo!  Eveleme Geveleme Dosdoğru olarak  Düzgün cümle kur...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aman-be-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna - Tarak', 'ayna-tarak-ahmet-yozgat-zytc1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeter be canım ağabey! 

Bırak elinden o sivri dişli tarağı

Görmüyor musun babanı 

O da senin gibi

Elinde tarak karşısında aynanın

Her gün saatler boyu 

Hışır hışır tarayarak 

Yoldu kafasındaki tüm saçlarını

Yeter be canım ağabey! 

Vazgeç aynadan taraktan

İbret al dazlak babamdan.

www.ahmetyozgat.com', 'Yeter be canım ağabey!  Bırak elinden o sivri dişli tarağı Görmüyor musun babanı  O da senin gibi Elinde tarak karşısında aynanın Her gün sa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayna-tarak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadersiz Küçük', 'bir-kadersiz-kucuk-ahmet-yozgat-g9lat', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Ah kadersizim ah! ...''

Diyerek severdi onu anası

Elsiz, ayaksız

Parasız ne demek

Anlardı da küçük çocuk 

O küçücük yüreğiyle

Bilemezdi bir türlü 

Kader ne demek? 

Kadersiz ne demek? 

Anladı sonunda küçük çocuk 

Hayatta ''Kadersizim'' diyeni kalmadığında 

Kadersizliğin bütün anlamını.

www.ahmetyozgat.com', '''Ah kadersizim ah! ...'' Diyerek severdi onu anası Elsiz, ayaksız Parasız ne demek Anlardı da küçük çocuk  O küçücük yüreğiyle Bilemezdi bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-kadersiz-kucuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birşey Anlamadım Dünya''dan', 'birsey-anlamadim-dunya-dan-yusuf-onder-bahceci-izsjx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şey anlamadım ben bu Dünya''dan,

Dostlar hâtır sorar böyle şekli riyadan,

Sevdiğimi isterim Cenabı Kibriyadan,

Bir şey anlamadım ben bu Dünya''dan.

Anlayanlar varsa, şöyle beri gelsinler,

Neler anlamışlar, hele bana desinler,

Hatır, gönül kırmasın sevdim desinler,

Bir şey anlamadım ben bu Dünya''dan.

Şöyle yârindan ayrılan, bulup soralım,

Kardeşim hâlin, ahvalin nasıl diyelim,

Bir dokunalım bakalım bin ah işitelim,

Bir şey anlamadım ben bu Dünya''dan.

Bilenler Dünya''nın vefası olmaz derler,

Bilenler Dünya vefasız güzeldir derler,

Bunu bilmeyenler, birgün iflas ederler,

Bir şey anlamadım ben bu Dünya''dan....', 'Bir şey anlamadım ben bu Dünya''dan, Dostlar hâtır sorar böyle şekli riyadan, Sevdiğimi isterim Cenabı Kibriyadan, Bir şey anlamadım ben bu D...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birsey-anlamadim-dunya-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Demek Ne Demek?', 'kis-demek-ne-demek-ahmet-yozgat-cvb2d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Kış demek

Ellerde yeşil eldiven demek 

Sırtta kahverengi kaban demek 

Ayakta siyah postal demek 

Boyunda kırmızı atkı demek

2/:

Azgın tipide ya da ayazlı karda

En büyük mutluluk

Nedir bilir misiniz siz? 

Sırta sıcak kaban 

Ayağa sıcak potin

Ele sıcacık eldiven giymek

Yünlü atkı dolamak boyuna 

Öylece devam etmek kartopu oyununa.

www.ahmetyozgat.com', '1/: Kış demek Ellerde yeşil eldiven demek  Sırtta kahverengi kaban demek  Ayakta siyah postal demek  Boyunda kırmızı atkı demek 2/: Azgın ti...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kis-demek-ne-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Tiryaki Baca', 'bizim-tiryaki-baca-ahmet-yozgat-6bcui', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizim çatıyı bekleyen baca

Püfür püfür üfler kış boyu

Bol dumanlı sigara

Ama yaz gelince bırakır tiryakiliği

Sigarayı atar bir tarafa

Nisan gelince öksürür kütür kütür 

Mayıs ayında temizler boğazını

Beyaza boyar kara ağzını

Bizim baca akıllıdır babamdan

''Niye? '' derseniz eğer 

Bırakmaz hiç tütünü babam

Yazın da içer kışın da içer

Hiç bıkmadan, asla usanmadan.

www.ahmetyozgat.com', 'Bizim çatıyı bekleyen baca Püfür püfür üfler kış boyu Bol dumanlı sigara Ama yaz gelince bırakır tiryakiliği Sigarayı atar bir tarafa Nisan ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bizim-tiryaki-baca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Koltuk', 'kirik-koltuk-ahmet-yozgat-038vu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

He-hey şişko çocuk! 

Dikkat et biraz

Ben tahtadan bir koltuğum 

Ama yine de canlı sayılırım

Dikkat etmezsen sonra 

''Çat! '' diye kırılırım.

2/:

He-hey yaramaz bebe! 

Senin iki bacağın var

Benim ayaklarım dört tane

Topal edersen beni

Annen azarlar seni 

Sonra bulamazsın bahane.

www.ahmetyozgat.com', '1/: He-hey şişko çocuk!  Dikkat et biraz Ben tahtadan bir koltuğum  Ama yine de canlı sayılırım Dikkat etmezsen sonra  ''Çat! '' diye kırılırı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirik-koltuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Örümcek', 'bizim-orumcek-ahmet-yozgat-ztms2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahçemizdeki uzun bacaklı örümcek 

Bahar olunca sevinerek gelecek.

Bahçemizdeki boncuk bedenli örümcek

Akıllıca ve usluca duracak

Hiç haylazlık etmeyecek.

Bahçemizdeki incik gözlü örümcek 

Gece karanlık demeyecek 

Gündüz aydınlık demeyecek.

Bahçemizdeki kara derili örümcek

İncecikten ipek gibi bir ağ örecek

Bahçemizdeki benim gibi akıllı örümcek 

Ben ördüğü ağını görünce 

Çok ama çok sevinecek.

Bahçemizdeki ince tenli örümcek 

Kış çöküp kar yağınca üşüyecek

Hüzünlenerek geldiği gibi gidecek.

www.ahmetyozgat.com', 'Bahçemizdeki uzun bacaklı örümcek  Bahar olunca sevinerek gelecek. Bahçemizdeki boncuk bedenli örümcek Akıllıca ve usluca duracak Hiç haylaz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bizim-orumcek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boyalarım', 'boyalarim-ahmet-yozgat-7mpg3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çantamda dolu boyalarım var

Kuru boyam baş parmak boy 

Sulu boyam el kadar

Kafamda kurduğum 

Rüyalarımsa dünyalar kadar 

Hayallerimse dağlarca

Sorsam küçük boyalarıma 

''Yeter misiniz? '' diye

Dünyalar kadar rüyayı 

Dağlarca hayalleri 

Sonuna kadar boyamaya.

www.ahmetyozgat.com', 'Çantamda dolu boyalarım var Kuru boyam baş parmak boy  Sulu boyam el kadar Kafamda kurduğum  Rüyalarımsa dünyalar kadar  Hayallerimse dağlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/boyalarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sütlü Mısır', 'sutlu-misir-ahmet-yozgat-1ojd8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Şu bizim mısırcı amca 

Her gün, sabah olunca

Uzun sokakta ''Sütlü mısır'' satar 

Nedense bizim mısırcı amca

Mısırın sütüne su katar.

2/:

Şu bizim mısırcı amca 

Her gün, sabah olunca

Bulunduğumuz kalabalık sokakta 

Sütlü mısırına su katar 

Üstelik bizim mısırcı amca

Sulu süt mısırını pahalı satar

Kuyruk olur alıcılar.

3/:

Şu bizim sütçü amca 

Her gün, sabah olunca

Uzun sokakta ''süt'' satar 

Nedense bizim sütçü amca

Sütüne su katar.

4/:

Şu bizim sütçü amca 

Her gün, sabah olunca

Bulunduğumuz uzun sokakta 

Süt bidonuna musluk suyu katar 

Üstelik bizim sütçü amca

Sulu sütünü ucuz satar

Yüz çevirir alıcılar...

www.ahmetyozgat.com', '1/: Şu bizim mısırcı amca  Her gün, sabah olunca Uzun sokakta ''Sütlü mısır'' satar  Nedense bizim mısırcı amca Mısırın sütüne su katar. 2/: Ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sutlu-misir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışık Sarmaşık', 'karisik-sarmasik-ahmet-yozgat-v5hao', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Bahçemizdeki sarmaşık 

Ne kadar da karışık? 

Bir ucu bizim penceremizde 

Karşı evde bir ucu.

2/:

Bahçemizdeki sarmaşık 

Bulmaca gibi dolaşık

Girişi beri yanda

Çıkışı ta karşı uçta.

3/:

Bahçemizdeki sarmaşık 

Ne kadar da karışık

Bir ucu coğrafyada 

Geometride bir ucu.

4/:

Bahçemizdeki sarmaşık 

Kafam gibi karışık

Kökü bahçemizde ama

Dalları yıldızlarda.

www.ahmetyozgat.com', '1/: Bahçemizdeki sarmaşık  Ne kadar da karışık?  Bir ucu bizim penceremizde  Karşı evde bir ucu. 2/: Bahçemizdeki sarmaşık  Bulmaca gibi dol...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karisik-sarmasik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Kapı', 'bizim-kapi-ahmet-yozgat-ld6v7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Uğurlar beni her sabah

Karşılar her akşam beni

Bizim evin kapısı 

Sökmez pervazını 

Kırmaz menteşesini

Durmadan açılır kapanır da

Hiç çıkarmaz sesini.

2/:

Bizim evin kapısı 

İşini hiç aksatmaz

Ben iş yapmam parasız 

Babam her ay aylık alır

Ama bizim evin kapısı 

Ay başında maaş almaz.

www.ahmetyozgat.com', '1/: Uğurlar beni her sabah Karşılar her akşam beni Bizim evin kapısı  Sökmez pervazını  Kırmaz menteşesini Durmadan açılır kapanır da Hiç çı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bizim-kapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek', 'yurek-ahmet-yozgat-ge4e8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Döşümdeki doğal davul

Çalar durmadan:

''Dan dan da dan dan...''

Hiç ara vermez 

Bıkmaz usanmaz

Çalar durmadan: 

''Dan dan da dan dan...''

Derisini yarmadan 

Tokmağını kırmadan.

www.ahmetyozgat.com', 'Döşümdeki doğal davul Çalar durmadan: ''Dan dan da dan dan...'' Hiç ara vermez  Bıkmaz usanmaz Çalar durmadan:  ''Dan dan da dan dan...'' Derisi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yurek-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Karga Yeşil Ördek', 'kara-karga-yesil-ordek-ahmet-yozgat-2vcpg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Kara karga ''Gak! '' dedi 

Peyniri uyanık tilki yedi

''Pencereden bakayım.'' derken 

Sütü bir çocuk içti

Acıdım zavallıya

Sofradaki kırıntıları 

Verdim bizim kara kargaya

Haydi siz de acıyın ona

Sofranızda artan kırıntıları

Verin acıkan kara kargaya.

2/:

Yeşil ördek ''Vak! '' dedi 

Deredeki yosunu balık yedi

''Pencereden bakayım.'' derken

İçti gölün suyunu bir sarı inek.

Acıdım zavallıya 

Soframızdaki kırıntıları 

Verdim bizim paytak ördeğe

Haydi  acıyın ona siz de

Sofranızda artan kırıntıları

Verin acıkan paytak ördeğe.

www.ahmetyozgat.com', '1/: Kara karga ''Gak! '' dedi  Peyniri uyanık tilki yedi ''Pencereden bakayım.'' derken  Sütü bir çocuk içti Acıdım zavallıya Sofradaki kırıntıl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kara-karga-yesil-ordek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış', 'kis-ahmet-yozgat-s8j8f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gece

Beyaz ve çiçekli yorganımı

Üzerime çekince

Ben ısınıyorum da 

Nedense bilmem

Sopsoğuk oluyor hava 

Bürününce beyaz karı 

Üzerine düz ova.

www.ahmetyozgat.com', 'Her gece Beyaz ve çiçekli yorganımı Üzerime çekince Ben ısınıyorum da  Nedense bilmem Sopsoğuk oluyor hava  Bürününce beyaz karı  Üzerine dü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kis-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğret-Menimi Anımsadım', 'ogret-menimi-animsadim-ahmet-yozgat-b87xk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabah yataktan kalkınca

Banyodaki aynaya baktım 

Her zamanki gibi yine bu sabah

O da ne? 

Sağ kulağım

Daha büyük göründü

Sol kulağıma göre gözüme

Sevgili öğretmenim

Nedense bilmem bu sabah

Hatırladım birden seni.

www.ahmetyozgat.com', 'Bu sabah yataktan kalkınca Banyodaki aynaya baktım  Her zamanki gibi yine bu sabah O da ne?  Sağ kulağım Daha büyük göründü Sol kulağıma gör...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ogret-menimi-animsadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınıfımız', 'sinifimiz-ahmet-yozgat-0aeui', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Sınıfımız kocaman 

Evimizin üç misli

Badanalı duvarları 

Resimler ile süslü.

2/:

Sınıfımız gül kokar 

Koklarım ''snıf snıf! ''

Gün boyu içindeyiz 

Evimiz gibi sınıf.

www.ahmetyozgat.com', '1/: Sınıfımız kocaman  Evimizin üç misli Badanalı duvarları  Resimler ile süslü. 2/: Sınıfımız gül kokar  Koklarım ''snıf snıf! '' Gün boyu iç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sinifimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Dede', 'ay-dede-ahmet-yozgat-unzmg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ali''nin dedesi var 

Yok ki benim dedem

Ali''nin odası penceresiz

Benim odamın penceresi kocaman

Hem de camsız ve perdesiz.

2/:

Ali''nin varsa bir dedesi

Neden üzüleyim ki 

Benim de ay dedem var

Geceleri ay dedem dolar

Perdesiz ve camsız penceremden içeri.

www.ahmetyozgat.com', '1/: Ali''nin dedesi var  Yok ki benim dedem Ali''nin odası penceresiz Benim odamın penceresi kocaman Hem de camsız ve perdesiz. 2/: Ali''nin va...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ay-dede-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-aynur-avci-1uad9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben her gece

Şerefe kadeh kaldırırım

Her gece sana aşık olurum

Düşündükçe yudumlar dolar taşar

Aşka ağlar,içerim duygularıma

Ben her gece sana,aşık olurum

Yıldızlar etrafımda döner,geceye vurur

Sokaklar sevda kokusundan çıldırmış

Ben her gece sana yalnızım

Ben her gece kadehimde

Yalnız sana sorhoş olurum..', 'Ben her gece Şerefe kadeh kaldırırım Her gece sana aşık olurum Düşündükçe yudumlar dolar taşar Aşka ağlar,içerim duygularıma Ben her gece sa...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sana-144-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmek', 'gulmek-cenk-aksal-qdqn5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ölüme gülmek istiyorum

apansızca,hissetmemek

ve en mutlu anımda

çekip gitmek hayattan...

zaten her mutlu anın sonu:

ölmek değilmi:ayrılıklardan! 

ve acılar çekmek,aşk''tan

binlerce kez ölmek değilmi

inadı bitmez sevdalardan....', 'ölüme gülmek istiyorum apansızca,hissetmemek ve en mutlu anımda çekip gitmek hayattan... zaten her mutlu anın sonu: ölmek değilmi:ayrılıklar...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulmek-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Soba', 'bizim-soba-ahmet-yozgat-uqnh3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizim soba kuru kuru odun yer 

Atıştırır kova kova kömürü

Sıcaklık yayar bizim soba odaya.

Bol bol yemek yerim ben 

Bardak bardak süt içerim

Sıcaklık yayılır tüm vücuduma.

www.ahmetyozgat.com', 'Bizim soba kuru kuru odun yer  Atıştırır kova kova kömürü Sıcaklık yayar bizim soba odaya. Bol bol yemek yerim ben  Bardak bardak süt içerim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bizim-soba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokulu Çorap', 'kokulu-corap-ahmet-yozgat-cky7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Annemi bir türlü anlamıyorum

''Koksun,'' diye kolonya döker gömleğime

Ceketime lavanta sürer 

2/:

Bir türlü annemi anlamıyorum

Nedense ''Kokuyor,'' diye 

Tutar çoraplarımı sokağa atar.

www.ahmetyozgat.com', '1/: Annemi bir türlü anlamıyorum ''Koksun,'' diye kolonya döker gömleğime Ceketime lavanta sürer  2/: Bir türlü annemi anlamıyorum Nedense ''Ko...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kokulu-corap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokulu Araba', 'kokulu-araba-ahmet-yozgat-6qcns', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sayın ki her gri akşamlarda,

Yatağıma yatmadan önce, 

Yani uykum gelince...

Kırmızı arabamı park ederim, 

Sarı çiçekli yorganımın altına

Bir sevinir, bir sevinir ki sevgili arabam, 

İki sevgili misali onunla...

Gece boyu yatarız koyun koyuna,

Her şey hoş, güzel de,

Ama bir de

Şu benzin kokusu olmasa,

Burnumun direğini kıran, 

Bir bulut gibi saran küçük odamı,

O zaman yüreğime sokarım arabamı...

***', 'Sayın ki her gri akşamlarda, Yatağıma yatmadan önce,  Yani uykum gelince... Kırmızı arabamı park ederim,  Sarı çiçekli yorganımın altına Bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kokulu-araba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Uçurtma', 'merhaba-ucurtma-ahmet-yozgat-a35ta', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aylardan nisan geldi yine

Yani girdik uçurtma mevsimine

Bu yıl uçurtmamın üstüne 

Koskocaman bir yürek çizdim

Satır satır selam yazdım 

Uzaklarda ışılayan yıldızlara

Okuyunca yazdığımı ay dede

Sarışın yıldızlar çizdiğimi görünce 

Öyle sevindiler öyle sevindiler ki

Göz kırptılar birer birer

Gülümsediler...gülümsediler 

''Merhaba küçük kardeş.'' dediler bana

Ve dünyadan uzanıp mavi gökyüzüne 

Başını sallayan uçurtmama

''Merhaba küçük kardeşler.'' dediler 

Dünyadan uzanıp lacivert gökyüzüne 

El sallayan herkese..

www.ahmetyozgat.com', 'Aylardan nisan geldi yine Yani girdik uçurtma mevsimine Bu yıl uçurtmamın üstüne  Koskocaman bir yürek çizdim Satır satır selam yazdım  Uzak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/merhaba-ucurtma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkasına Sığındık...', 'arkasina-sigindik-murat-karasu-ml0od', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybolup yalnızlıkların karalarında

Şüpheler içinde hasretlere sığındık.

Gidecek kapımız kalmadığında

                Gurur yangınlarının arkasına sığındık.

Ne zamanlar gelip geçti yaşanamadan

Gözlerdeki gözyaşlarına dokunduk...

Her gecenin bir sabahı var deyip

                Seher vakitlerine sığındık.

Dal gibi kırılıp dağıldığımızda

Gül yüzlü insanların kalplerine sığındıık.

Bu dünyanın merhametsizliğini bilip

                Anaların ellerine sığındık...

Kapkara günlerin ağırlığı çöktüğünde

Ay ışığının aydınlığına sığındık.

Vurup geçtiğinde bir kötü söz 

                Dillerdeki vefalara sığındık...', 'Kaybolup yalnızlıkların karalarında Şüpheler içinde hasretlere sığındık. Gidecek kapımız kalmadığında                 Gurur yangınlarının ar...', ARRAY['Türk Edebiyatı','Şiir','Murat Karasu']::text[], 8.5, '{"poet":"Murat Karasu","poet_slug":"murat-karasu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/arkasina-sigindik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlayın Komşular', 'hatirlayin-komsular-ahmet-yozgat-refkx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Merhaba Ali amca 

Komşumuz Ayşe teyze 

Mahalle bakkalı Veli dayı

Merhaba mahalleli kara karga 

Saçağımıza yuva kuran minik serçe merhaba

Ve kış uykusunda mışıl mışıl uyuyan ayı

Ne olur unutmayın beni

Kış kapıya dayanınca 

Ben komşunuz minik karıncayı.

2/:

Merhaba ayakkabıcı Yusuf amca 

Yufkacı Elif teyze merhaba

Merhaba marketçi Refik ağabey

İyi günler yalnız elma ağacı 

Tarlalardaki sarışın buğday başağı

Tarlasını eken çiftçi dayı

Ve bereketli eylül ayı

Ne olur anımsayın beni

Kar kapıya dayanınca

Ben komşunuz kara karıncayı.

www.ahmetyozgat.com', '1/: Merhaba Ali amca  Komşumuz Ayşe teyze  Mahalle bakkalı Veli dayı Merhaba mahalleli kara karga  Saçağımıza yuva kuran minik serçe merhaba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hatirlayin-komsular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Amca Sabah Abla', 'aksam-amca-sabah-abla-ahmet-yozgat-e3pt5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Giydi simsiyah urbasını 

Geliyor korkutucu akşam amca

En iyisi ben yatayım 

Sıcak kuştüyü yatağıma

Gelenek dek odama

Beyaz ve çiçekli urbalı sabah abla

Gözlerimi kapayım

2/:

Giydi kalın paltosunu 

Göründü ürkütücü akşam amca

En iyisi ben yatayım 

Sıcak ve renkli rüyalara dalayım

Gelenek dek dünyaya

Sarı saçlı ve güneşli sabah abla

Gözlerimi kapayım.

www.ahmetyozgat.com', '1/: Giydi simsiyah urbasını  Geliyor korkutucu akşam amca En iyisi ben yatayım  Sıcak kuştüyü yatağıma Gelenek dek odama Beyaz ve çiçekli ur...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aksam-amca-sabah-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Köpek', 'kucuk-kopek-ahmet-yozgat-ah6xq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

İstisnasız her sabah 

Bir küçük karabaş köpek 

Yolda beni çevirecek

''Hav hav! '' diyecek 

Acıktığını hissettirecek.

2/:

İstisnasız her sabah

Bir küçük ve uzun kulaklı köpek

Beslenme çantamı gösterecek

''Hav hav! '' diyecek.

3/:

İstisnasız her sabah 

Bir küçük ve kıllı köpek 

Verdiğim ay çöreklerini 

İştah ile yiyecek

''Hav hav! '' diyecek.

4/:

İstisnasız her sabah

Bir küçük köpek erkenden

''Hav hav! '' diyecek bana 

Ta yürekten teşekkür edecek.

www.ahmetyozgat.com', '1/: İstisnasız her sabah  Bir küçük karabaş köpek  Yolda beni çevirecek ''Hav hav! '' diyecek  Acıktığını hissettirecek. 2/: İstisnasız her sa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kucuk-kopek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ Dede', 'dag-dede-ahmet-yozgat-f0xtr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Penceremden bakan koca dağ

Hatırlatır bana 

Ak saçlı ve yaşlı dedemi

Hemen koşar açarım penceremi 

Uzatırım minnacık ellerimi

Ak saçlı yaşlı dağ

Geri çevirmez isteklerimi.', 'Penceremden bakan koca dağ Hatırlatır bana  Ak saçlı ve yaşlı dedemi Hemen koşar açarım penceremi  Uzatırım minnacık ellerimi Ak saçlı yaşlı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dag-dede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Emmi', 'coban-emmi-ahmet-yozgat-vryni', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Al kalın kabanımı çoban emmi 

İstersen lastik botlarımı da al

Yaldızlı yatağımı,

Çiçekli yorganımı, 

Kuş tüyünden yastığımı 

Ve pelüş battaniyemi

Hatta sıcacık odamı da al

2/:

Çoban emmi

Ver bana sen de sadece 

Işıl ışıl yıldızlı gecelerini

Sürün ve köpeğin sende kalsın

Ver bir de sırtındaki keçeden kepeneğini.

www.ahmetyozgat.com', '1/: Al kalın kabanımı çoban emmi  İstersen lastik botlarımı da al Yaldızlı yatağımı, Çiçekli yorganımı,  Kuş tüyünden yastığımı  Ve pelüş ba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/coban-emmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğme', 'dugme-ahmet-yozgat-m19y6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Kahverengi ceketimdeki ak düğme 

Kavuşturursun birbirine iki yakamı 

Haydi bir iyilik daha et 

Kavuştur bana köyümüzdeki anamı

2/:

Pembe gömleğimdeki al düğme

Ulaştırırsın sağ yakamı sol yakama

Tut ellerimden bir iyilik daha et 

Ulaştır beni de almanya''daki babama

3/:

Lacivert kabanımdaki çoban düğmesi 

Önümü kapatırsın soğukta sapasağlam

Şimdi bir başka kentte askerde ağabeyim 

Evlenip göçtü bir başka şehre ablam

Özlemiştir sanırsam 

Kavuştur beni de sevdiklerime

Köyümüzde tek başına kalmada annem 

Almanya''da bir fabrikada çalışan babam

Özlemiştir sanırsam

Ne olur ulaştır beni de evime...

www.ahmetyozgat.com', '1/: Kahverengi ceketimdeki ak düğme  Kavuşturursun birbirine iki yakamı  Haydi bir iyilik daha et  Kavuştur bana köyümüzdeki anamı 2/: Pembe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dugme-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgun', 'vurgun-cenk-aksal-t4z3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gün:

binlerce yalan ve sen,

bense vurulmuşum gözlerine,

yalansız dolansız,saf

ve sen yalancı gözlerinde,

binlerce gül kurusu hüzün,

yüreğime indirdiğin:

yüzlerce hançer yarası....

işte bu son gün,

yalan dolan,sahte aşkım

herşey sana vurgun....', 'bir gün: binlerce yalan ve sen, bense vurulmuşum gözlerine, yalansız dolansız,saf ve sen yalancı gözlerinde, binlerce gül kurusu hüzün, yüre...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vurgun-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizgi Filminizi Çizeyim E Mi?', 'cizgi-filminizi-cizeyim-e-mi-ahmet-yozgat-ck15c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Bıraktırıp boş arsada canım körebeyi 

Çekip sokaktan beni 

Ekran başına mıhlayan

Çizgi filminizi çizeyim e mi? 

Bırakın ellerimi

Azat edin gözlerimi... 

2/:

Bıraktırıp öteki odada sevgili annemi 

Alıp kucağından beni 

Ekran başına mıhlayan

Çizgi filminizi çizeyim e mi? 

Bırakın bedenimi

Azat edin beynimi...', '1/: Bıraktırıp boş arsada canım körebeyi  Çekip sokaktan beni  Ekran başına mıhlayan Çizgi filminizi çizeyim e mi?  Bırakın ellerimi Azat ed...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cizgi-filminizi-cizeyim-e-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Olmak İstiyorum?', 'neler-olmak-i-stiyorum-ahmet-yozgat-5r29t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I/:

Baba olmak istiyorum 

Ellerinden tutup götürmek için 

Lunaparka çocuklarımı.

II/:

Öğretmen olmak istiyorum 

Tutup çekmemek için 

Nazik kulağını öğrencilerimin.

III/:

Anne olmak istiyorum 

Zorlaya zorlaya kaldırtmamak için 

Zarif kızıma evdeki ağır eşyaları.

IV/:

Asker olmak istiyorum 

Ne olursa olsun vurmamak için 

Savaşlarda mini minnacık çocukları.

VI/:

Nine olmak istiyorum 

Kış mevsiminde anlatmak için 

En güzel ve anlamlı masalları.

VII/:

Kasap olmak istiyorum 

Bizim mahalle mırnavlarına 

Vermek için lezzetli ciğerleri.

VIII/:

Doktor olmak istiyorum 

İyileştirmek için hastalıklarını 

Yoksul ve kimsesiz hastaları.

IX/:

Hakim olmak istiyorum 

Kesinlikle ayırmamak için 

Boşanmak isteyen anne babaları.

X/:

Toprak olmak istiyorum 

Yetiştirmek insanlar yesin diye 

En güzel ve en görkemli meyveleri. 

XI/:

Yağmur olmak istiyorum 

Bolluk - bereket olmak için 

Sarı tarlalara ve yeşil çayırlara.

XII/:

Güneş olmak istiyorum 

Isıtmak hatta terletmek için 

Kışın soğuğunda üşüyen çocukları

XIII/:

 Adam olmak istiyorum 

İnsan gibi yaşamak 

Ve yaşatmak için hayatı.', 'I/: Baba olmak istiyorum  Ellerinden tutup götürmek için  Lunaparka çocuklarımı. II/: Öğretmen olmak istiyorum  Tutup çekmemek için  Nazik k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/neler-olmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Amca', 'bayram-amca-ahmet-yozgat-11c32', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Uzaklardaki bayram amca

Gelsene haydi

Canım şeker istedi

2/:

Uzaklardaki bayram amca

Gelsene haydi

Çocuklar seni özledi

3/:

Uzaklardaki bayram amca

Neredesin gel haydi

Aradan tam bir yıl geçti...', '1/: Uzaklardaki bayram amca Gelsene haydi Canım şeker istedi 2/: Uzaklardaki bayram amca Gelsene haydi Çocuklar seni özledi 3/: Uzaklardaki ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bayram-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye Bak', 'geceye-bak-aynur-avci-atgsr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Binbir eda ile süzülür

Dağın ardından güneş

Akşama sitem eder gibi

Ayın kızıllığı bulutlara sıkışmış 

Gecenin heyecanı,yüreklerin atışında

Sevişenler,yıldızların süzülüşünde

Kuşların gece seslenişi

Bir elin dokunuşu gibi

Geceye ayak uydur

Mutlu ol sende

Beni düşünme artık

Geceler hep senin

Gündüzler benim  olsun..', 'Binbir eda ile süzülür Dağın ardından güneş Akşama sitem eder gibi Ayın kızıllığı bulutlara sıkışmış  Gecenin heyecanı,yüreklerin atışında S...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geceye-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tom Ve Jeri', 'tom-ve-jeri-ahmet-yozgat-e8uag', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ne zaman dişlerini gösterse 

Ve nerede kovalasa 

Egoist bir kedi 

Zavallı bir fareyi

Hatırlarım hemen 

Şu bizim yaramaz çizgi Tom''u 

Ve zavallı çizgi Jeri''yi.

2/:

Ne zaman tırnağını gösterse

Ve nerede kovalasa

Yaramaz bir kedi

Zavallı bir fareyi 

Atılır miniği kurtarırım 

Kovalarım zalim kediyi.', '1/: Ne zaman dişlerini gösterse  Ve nerede kovalasa  Egoist bir kedi  Zavallı bir fareyi Hatırlarım hemen  Şu bizim yaramaz çizgi Tom''u  Ve ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tom-ve-jeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Yüzünden...', 'ayrilik-yuzunden-sahin-kars-vu5eb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arı çiçek, bülbül gülden ayrılmış,

Ah edip iniler zâr ile şimdi.

Nazlı goncam bana niye darılmış? 

Başlıyor davamız, hâr ile şimdi.

Virâne ömrümü eyledim pazar,

Bekledim o güzel dost gelir gezer.

Ne selam gönderir ne mektup yazar,

Açıldı aramız yâr ile şimdi.

Yüreğimiz şimşek gibi çakarken,

El eleydik geleceğe bakarken.

Bahar idi ben gurbete çıkarken,

Yüce dağlar kaplı kar ile şimdi.

Felek katlimize buyurdu ferman,

Hayatın çarkında eyledi kirman.

Şahin''in dizinde kalmadı derman,

Ayakta duruşu  ''ar  ile şimdi.', 'Arı çiçek, bülbül gülden ayrılmış, Ah edip iniler zâr ile şimdi. Nazlı goncam bana niye darılmış?  Başlıyor davamız, hâr ile şimdi. Virâne ö...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-yuzunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür Uçurtma', 'ozgur-ucurtma-ahmet-yozgat-8cmdd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I/:

Gök yüzünde özgürdü

Uçuşan kuşlar gibi

Rüzgar kanatlı uçurtmam

Çıktı mı bulutlar ülkesine 

Baş baş yapardı

Bir sağına bir soluna.

2/:

Upuzun teller gerdiler gökyüzüne 

Ellerinde kara penselerle amcalar

Plastikten telefon telleri önce 

Sonra çelikten elektrik telleri

Çıkmasın diye gökyüzüne 

Özgür uçurtmalar

Sonunda olan oldu 

Uçurtmasız kaldı çocuklar...', 'I/: Gök yüzünde özgürdü Uçuşan kuşlar gibi Rüzgar kanatlı uçurtmam Çıktı mı bulutlar ülkesine  Baş baş yapardı Bir sağına bir soluna. 2/: Up...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozgur-ucurtma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceleyin Aritmetik', 'geceleyin-aritmetik-ahmet-yozgat-goodr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Her gece yatağıma girince

Başlarım aritmetik dersine

Her saniyede bir koyun atlarsa çitten

Bir dakikada kaç tane atlar? 

Bir, iki, üç, dört....

2/:

Her gece yatağıma girince

Başlarım aritmetik dersine

Beş, altı, yedi, sekiz....

Çok geçmeden karışır her şey

Dönerim başa gerisin geri

Bir saatte on muydu? 

Yüz müydü? 

Yoksa bin miydi? 

3/:

Her akşam yatağıma girince

Başlarım aritmetik dersine

Uykuya karışır gece

Kafamdaki rakamların hepsine

Uyku bulaşır

Koyunlar birbirine karışır

Bir, beş dokuz, dört....

Dönüp başa tekrar mı saysam? 

Veya bırakıp matematik dersini 

En iyisi mışıl mışıl uyusam.', '1/: Her gece yatağıma girince Başlarım aritmetik dersine Her saniyede bir koyun atlarsa çitten Bir dakikada kaç tane atlar?  Bir, iki, üç, d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/geceleyin-aritmetik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-osman-ergun-uu02u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey sevgili...

Güllerini istemem,

Dikenlerini al yeter.

Gülmezsen, gülme yüzüme.

Ama kızma sus, yeter.

İstemezsen bana gelme,

Uzaklara da gitme.

Olduğun yerde kal yeter.

Sev seveceksen eksiklerimle.

Ya da beni sal yeter.

İki arada bırakma beni.

Çok yoruldum bil yeter.

Anıların senin olsun,

Beni hatırandan sil yeter.

19.02.2006', 'Ey sevgili... Güllerini istemem, Dikenlerini al yeter. Gülmezsen, gülme yüzüme. Ama kızma sus, yeter. İstemezsen bana gelme, Uzaklara da git...', ARRAY['Türk Edebiyatı','Şiir','Osman Ergün']::text[], 8.5, '{"poet":"Osman Ergün","poet_slug":"osman-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yeter-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marifet İnsanda Şiirde Değil', 'marifet-i-nsanda-siirde-degil-yusuf-onder-bahceci-zso5y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Marifet çok şiir yazmada değil marifet insanda,

Bir insanda marifet yoksa suçu ağırdır mizanda,

İnsanlarda övünme hastalığı var, kızılır inadın da,

Marifet çok şiir yazmada değil marifet insanda.

Yazdığım şiirlerde neyi anlatmam gerekir, nedir,

Sevdiğimin gözleri ceylan, siması dolunay bedir,

Yazılan şiirlerde, yâr kendine nasıl da etmiş esir,

Marifet insanda, marifet çok şiir yazmada değil.

Benim hiç kimseyle bir alıp veremediğim yoktur,

Benim böyle duygulu şiirlerim inanın pek çoktur,

Yollara bakarım hep yoldan gelecek yolcu yoktur,

Marifet insanda, marifet çok şiir yazmada değil.

Çok şiir yazalım, yazalım da sevilenleri anlatalım,

Çok şiir yazalım, gelin dertlerimizi karıp, katalım,

Çok şiir yazalım da kâlplerden kasavetleri atalım,

Marifet insanda, marifet çok şiir yazmada değil...', 'Marifet çok şiir yazmada değil marifet insanda, Bir insanda marifet yoksa suçu ağırdır mizanda, İnsanlarda övünme hastalığı var, kızılır ina...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/marifet-insanda-siirde-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarzan', 'tarzan-recep-uslu-f4qoi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tarzan benim

Çocukluk arkadaşım

Birlikte oynadık kavaklıkta

Ara kesmeyi

Top sahasındaki

Kova otlarından

Birlikte şapka ördük

Gece karanlıklarında

Son evin boşluğundan

Bahçelere bakıp

Birlikte koştuk evlerimize

Arkamızdan biri

Tutacak sanılan

Korkularımızı

Birlikte yaşadık

Boynumuzdaki sandıkla

Ayakkabı boyamayı

Kazimanın sinemasının

Reklamını yapmayı

Bobin aralarında

Gazoz satmayı

Birlikte yaptık

Bir liraya aldığımız

Köpek öldüren şarabını

Şişeden

Hamamın arkasında

Gizli gizli

Birlikte içtik

Orta okul çağlarına gelinceye değin

Tarzan benim çocukluk arkadaşım

Tarzan''ı tanıyanlar tarzanı bilir

Sonra ayrıldı yollar elden ne gelir

Şimdi

Ne ben Tarzan''ı tanırım ne Tarzan beni

Deli Bilalle Tarzan Gölpazarı''nın gülü

14.02.2006', 'Tarzan benim Çocukluk arkadaşım Birlikte oynadık kavaklıkta Ara kesmeyi Top sahasındaki Kova otlarından Birlikte şapka ördük Gece karanlıkla...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tarzan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alp Dağında Bir Küçük Kız', 'alp-daginda-bir-kucuk-kiz-ahmet-yozgat-vpdbv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Yaşar bir küçük kız 

Kafaları beyaz başlıklı alp dağlarında

Pos bıyıklı yaşlı ve bilge dedesi

Üç beş sevimli kıl keçisi.

2/:

Koşar bir küçük kız 

Kayaları duvar gibi sarp yamaçlarda

Kendisi yumruk kadar minicik

Ama alp kadar kocamandır yüreği.', '1/: Yaşar bir küçük kız  Kafaları beyaz başlıklı alp dağlarında Pos bıyıklı yaşlı ve bilge dedesi Üç beş sevimli kıl keçisi. 2/: Koşar bir k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/alp-daginda-bir-kucuk-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alır Beni Bir Gece', 'alir-beni-bir-gece-ahmet-yozgat-kary7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Ummadığım bir zamanda

Guguklu saat yediyi vururken

Ya da sekizde, dokuzda veya onda

Alır beni sıcacık yatağımdan

Götürür kekik kokulu kırlara 

İnim inim inleyen bir kaval sesi.

2/:

Beklemediğim bir zamanda

Guguklu saat sekizi vururken

Ya da dokuzda, onda veya on birde 

Alır beni bu mavi dünyadan

Götürür rengarenk hayal ülkesine 

Ilık ılık akan bir masal sesi

3/:

Şaşırdığım bir zamanda

Guguklu saat dokuzu vururken

Ya da onda, on birde veya on ikide 

Alır beni kuş tüyü beşiğimden

Götürür mışıl mışıl uyku diyarına 

Yanık yanık inleyen bir ninni sesi.', '1/: Ummadığım bir zamanda Guguklu saat yediyi vururken Ya da sekizde, dokuzda veya onda Alır beni sıcacık yatağımdan Götürür kekik kokulu kı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/alir-beni-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Anne?', 'neredesin-anne-ahmet-yozgat-95359', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ne kadar çok istiyorum bir bilsen

Akşamları ninnilerinle uyumak

Ve sabahları uyanmak ılık nefesinle 

Söyle neden duyulmaz sesin 

Nerdesin anne, anne nerdesin? 

2/:

Ne kadar çok istiyorum bir bilsen 

Küsmek, kırılmak veya naz yapmak sana 

Bin bir çeşitli kahvaltı sofrasında

Söyle neden duyulmaz sesin 

Nerdesin anne, anne nerdesin? 

3/:

Ne kadar çok istiyorum bir bilsen 

Akşamleyin daha yatağa girmeden önce 

Kaf dağından getirdiğin masalını dinlemek

Söyle neden duyulmaz sesin 

Nerdesin anne, anne nerdesin?', '1/: Ne kadar çok istiyorum bir bilsen Akşamları ninnilerinle uyumak Ve sabahları uyanmak ılık nefesinle  Söyle neden duyulmaz sesin  Nerdesi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neredesin-anne-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farecik Ne Yiyecek?', 'farecik-ne-yiyecek-ahmet-yozgat-4th8y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Bu sabah

Kahvaltı masasına koydu annem

Dolapta kalan en son peyniri

Herkes yedi afiyet üzere

Ancak ben yemedim

İnce ince ve uzun uzun düşündüm:

''Ya bulamazsa dolapta? ...'' diye

Bizimle birlikte yaşayan küçük farecik 

Yemek için bir parçacık peynircik.

2/:

Bu sabah

Kahvaltı masasında kalan 

En son peyniri aldım,

Götürdüm göstermeden anneme

İkram ettim odamdaki fareme

Bir yedi bir yedi ki afiyetle

Bu günlük de görevimi yaptım böylece...', '1/: Bu sabah Kahvaltı masasına koydu annem Dolapta kalan en son peyniri Herkes yedi afiyet üzere Ancak ben yemedim İnce ince ve uzun uzun dü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/farecik-ne-yiyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Labirent Bulmacadaki Tavşan', 'labirent-bulmacadaki-tavsan-ahmet-yozgat-w9zrt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Ressam amca, resimci amca 

Ne olur yapma bir daha 

İç içe geçmiş duvarlarıyla

Piramidi andıran lağabeyrent bulmaca

Ara sabaca işin yoksa

Akşamaca ara...

2/:

Ressam amca, resimci amca 

Saatlerce arıyorum 

Ama bir türlü bulamıyorum

Sağ yanı zorluyorum

Tıkanıyor önüm

Deniyorum solu

Gerisin geri dönüyorum

Söyle bana nasıl bulsun? 

Zavallı yavru tavşancık

Çıkıştaki annesine ulaşan yolu

3/:

Ressam amca, resimci amca

Nereye ulaşır bu sokak

Ya bu cadde nereleri dolaşır

Çıkaramam bir türlü

Aklım karışır

Söyle bana nasıl bulsun? 

Sıkıştı yine küçük hayvancık...', '1/: Ressam amca, resimci amca  Ne olur yapma bir daha  İç içe geçmiş duvarlarıyla Piramidi andıran lağabeyrent bulmaca Ara sabaca işin yoksa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/labirent-bulmacadaki-tavsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilebilir Miyim?', 'bilebilir-miyim-ahmet-yozgat-h9el9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bilmem büyütebilir miyim? 

Acaba güneşli yaz günlerinde 

Acaba gözlerimden akan yaşlarla

Kırlarda susuz kalan çiçekleri 

Ve ayak altında ezilen çimenleri.

2/:

Bilmem gezdirebilir miyim? 

Acaba tutup yumuk ellerinden

Papatyalı, çiğdemli parkları, 

Ve elmalı armutlu bahçeleri 

Zavallı yatalak nineleri 

Ve mini minnacık bebekleri.

3/:

Bilmem doyurağabeylir miyim? 

Acaba karlı kış günlerinde

Soframızda artan kırıntı ekmeklerle

Aç kalan kül rengi serçeleri 

Ve göçememiş öksüz leylekleri.', '1/: Bilmem büyütebilir miyim?  Acaba güneşli yaz günlerinde  Acaba gözlerimden akan yaşlarla Kırlarda susuz kalan çiçekleri  Ve ayak altında...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bilebilir-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-cemaleddin-ozmen-y69al', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kurbanın olayım bakma yüzüme,

Senden sonra hisseder oldum,dünyanın döndüğünü.

Çek gözlerini gözbebeklerimin üstünden

Senden sonra anladım yağmurun yere düştüğünü

Bulutlar yere indi bilir misin,yağmurunu bırakarak

Gözlerin gibi oldu dünya,yanıp kavrulan

Her nefes sur sesi çıkartır.Senden sonra

Çocuklar ölür,yaşlılar toprak olur.Senden sonra

İnsanların yüzleri karardı.Taş üstünde taş bulamadılar.

Her köşeye mitili çekilmiş bombalar kondu.

Göğe bakmaktan korkan,yere bakmaktan imtina eder olduk.

Senden sonra kıyameti yaşayan ben oldum.

Her yer boşaldı,ummana döndü dünya,

Hiç kimse kalmadı.Karıncalar bile yok oldu.

Dön arkanı bakma yüzüme,git artık 

Yaşayacak kimse kalmadı senden sonra.', 'Kurbanın olayım bakma yüzüme, Senden sonra hisseder oldum,dünyanın döndüğünü. Çek gözlerini gözbebeklerimin üstünden Senden sonra anladım ya...', ARRAY['Türk Edebiyatı','Şiir','Cemaleddin Özmen']::text[], 8.5, '{"poet":"Cemaleddin Özmen","poet_slug":"cemaleddin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-sonra-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup Yağmuru', 'mektup-yagmuru-ahmet-yozgat-orqlb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I/:

Bin bir kanat dolusu 

Beyaz güvercin geldi 

Bin bir kanat dolusu 

Beyaz beyaz zarf ile

Bin bir kanat dolusu 

Güleç yüzlü beyaz güvercin 

Kondu gök yüzünü dolduran ak bulutlara

Bin bir kanat dolusu beyaz güvercin

Birer birer açıp kırmızı gagalarını

Boşalttı bulutlardan üstümüze

Selam yüklü yağmur damlalarını

İstanbul''daki babalar 

Gurbetteki ağabeyler 

Neler neler söylediler

Koyup zarf içine 

Birer parça ıpılık yüreklerinden

Kendilerini bekleyen küçük kardeşlerine 

Ve yollarını gözleyen minik oğullarına 

Ya da kınalı kızlarına gönderdiler.

II/:

Bin bir kanat dolusu beyaz güvercin 

Getirdiler çok uzaklardan 

Bin bir selam yüklü mektupları

Aracı edip ak bulutları

Boşaldı üstümüze

Selam yüklü yağmur damlaları

Almanya''daki babalar 

Askerdeki ağabeyler 

Neler neler dediler

Koyup zarf içine 

Birer parça sıcacık yüreklerinden

Kendilerini bekleyen eşlerine 

Ve yollarını gözleyen sevgililerine 

Ya da tüm bizlere gönderdiler...', 'I/: Bin bir kanat dolusu  Beyaz güvercin geldi  Bin bir kanat dolusu  Beyaz beyaz zarf ile Bin bir kanat dolusu  Güleç yüzlü beyaz güvercin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/mektup-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümüzü Özlüyorum', 'koyumuzu-ozluyorum-ahmet-yozgat-weixh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Ellerimi kınalama ne olur? 

Önümüzdeki bayramda anne

Kınalı bayramlarımızı bıraktığımız

Uzaktaki köyümüzü özlüyorum 

Özlüyor özlüyor üzülüyorum.

2/:

Pembe şerbet yapma pekmezden ne olur? 

Ablamın düğününde anne

Serin temmuzlarımızı bıraktığımız

Uzaktaki kuyumuzun suyunu özlüyorum 

Özlüyor özlüyor üzülüyorum.', '1/: Ellerimi kınalama ne olur?  Önümüzdeki bayramda anne Kınalı bayramlarımızı bıraktığımız Uzaktaki köyümüzü özlüyorum  Özlüyor özlüyor üzü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/koyumuzu-ozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüyor aklıma', 'dusuyor-aklima-ufuk-nazim-cs3ij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollar yollar

Düşüyor aklıma.

Seni unuttum diye mi? 

Dostum 

Her gün böyle yağmurlar

Düşüyor aklıma.

Nerede nerede sesin

O hırçın nefesin.

Toprağa niye bakıyorsun

Böyle sessiz nedensiz.

Yarın doğacak

Soylu guneşimiz

Yıkayacak ışık ışık

Senin toprağını

Dostum nereye 

Nereye gidiyorsun.

Süphan dağında 

Kürtçe bir türkü söylüyorsun

Siphan siphane....

Sen ağır ağır

Irayıp göğe

Ufka hüznünü

Niye takıyorsun

Dostum nereye

Nereye bakıyorsun...', 'Yollar yollar Düşüyor aklıma. Seni unuttum diye mi?  Dostum  Her gün böyle yağmurlar Düşüyor aklıma. Nerede nerede sesin O hırçın nefesin. T...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dusuyor-aklima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümü Özlüyorum', 'koyumu-ozluyorum-ahmet-yozgat-je64k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ellerimi kınalama ne olur? 

Önümüzdeki bayramda anne

Kınalı bayramlarımızı bıraktığımız

Uzaktaki köyümüzü özlüyorum 

Özlüyor özlüyor üzülüyorum.

2/:

Pembe şerbet yapma pekmezden ne olur? 

Ablamın düğününde anne

Serin temmuzlarımızı bıraktığımız

Uzaktaki kuyumuzun suyunu özlüyorum 

Özlüyor özlüyor üzülüyorum.', '1/: Ellerimi kınalama ne olur?  Önümüzdeki bayramda anne Kınalı bayramlarımızı bıraktığımız Uzaktaki köyümüzü özlüyorum  Özlüyor özlüyor üzü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/koyumu-ozluyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Afrikalı Çocuk', 'bir-afrikali-cocuk-ahmet-yozgat-43w1q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Karnı küp gibi çöp gibi boynuyla 

Afrikalı zavallı bir çocuk

Bakar siyah siyah 

Kendisine beyaz beyaz bakanlara

Bir büyük ekmek ister 

Büyük ekmeği vermezsek eğer 

Ekmeğin yarısını ister 

Ekmeğin yarısını da vermezsek eğer

Çeyreğini ister ekmeğin 

Ekmeğin çeyreğini de vermezsek eğer

Birkaç kırıntı ister

Karnı küp gibi çöp gibi boynuyla 

Afrikalı zavallı bir çocuk

Alamazsa bir kırıntıyı da bizden 

Tüm ülkelere küser.

2/:

Karnı küp gibi çöp gibi boynuyla 

Afrikalı siyah bir çocuk

Bakar boncuk boncuk 

Kendisini beyaz beyaz süzenlere

Bir büyük sevgi ister 

Büyük sevgiyi vermezsek eğer 

Sevginin yarısını ister 

Sevginin yarısını da vermezsek eğer

Çeyreğini ister sevginin 

Sevginin çeyreğini de vermezsek eğer

Birkaç kırıntı ister

Karnı küp gibi çöp gibi boynuyla 

Afrikalı zavallı bir kara çocuk

Alamazsa bir sevgi kırıntısını da bizden 

Tüm insanlığa küser...', '1/: Karnı küp gibi çöp gibi boynuyla  Afrikalı zavallı bir çocuk Bakar siyah siyah  Kendisine beyaz beyaz bakanlara Bir büyük ekmek ister  B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-afrikali-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğur Böceğim', 'ugur-bocegim-ahmet-yozgat-zq2ok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Kim bastı parmak parmak? 

Bu kırmızı puanları sırtına 

De bana uğurlu uğur böceğim.

2/:

Kim dikti parmak parmak? 

Beyaz gömleğinin üstüne

Bu kırmızı puanları 

De bana uğurlu uğur böceğim.

3/:

Kim yaktı parmak parmak? 

Minnacık ellerine bayramda

Kınayı nokta nokta 

De bana uğurlu uğur böceğim.', '1/: Kim bastı parmak parmak?  Bu kırmızı puanları sırtına  De bana uğurlu uğur böceğim. 2/: Kim dikti parmak parmak?  Beyaz gömleğinin üstün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ugur-bocegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun Aşkım', 'yoksun-askim-tahmine-yildirim-ft2qc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimden geldi seni aradım

Telefonuna cevap vermedin

İçim burkuldu sanki birden

Yoksun aşkım nerelerdesin

Son mesajıma cevapta yazmadın 

Aramadığın gün gün bitmiyor anlayamadın

Yoksa benden daha önemli birşaymi var

Yoksun aşkım nerelerdesin

Gecenin bir vakti şiirler yazdırdın bana

İçimden şu anda kızmak geliyor sana

Katlanamıyorum anlasana sensiz hayata

Yoksun aşkım nerelerdesin.

                                                                     EYLÜL

                                                           2000', 'İçimden geldi seni aradım Telefonuna cevap vermedin İçim burkuldu sanki birden Yoksun aşkım nerelerdesin Son mesajıma cevapta yazmadın  Aram...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoksun-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçan Uykular Nereye Gider?', 'kacan-uykular-nereye-gider-ahmet-yozgat-yvqdf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Gece yarısı uykusu kaçtı

Kocaman bir evde küçücük bir çocuğun

Kaçtı uykuları 

Başka başka kocaman evlerde 

Başka başka minicik  çocukların

2/:

Gece yarısı düştüler çocuklar

Peşine kaçan uykularının

Uykular döndü dolaştı yolları 

Döndü dolaştı yolları çocuklar

Çocuklar uyku peşinde 

Sonunda kaf dağı''na ulaştılar

3/:

Gece yarısı kaçan uykularla 

Uykuları kovalayan çocuklar 

Kaf dağındaki rengarenk rüyaları 

Tam ortasından paylaştılar.', '1/: Gece yarısı uykusu kaçtı Kocaman bir evde küçücük bir çocuğun Kaçtı uykuları  Başka başka kocaman evlerde  Başka başka minicik  çocuklar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kacan-uykular-nereye-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülcan''ım!', 'gulcan-im-asik-seheri-0dswo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen Ey! 

Güller Padişahı''nın Yüzünün Teri! 

Ürkek ve nazlı ceylanın mahmur gözleri! 

Leyla''nın alnında parıldayan nûr! 

Cân''a aşk kokuları bahşeden sürûr! 

Ay yüzlün sana kurban olsun güneşim! 

Nazlı yarim, sevgilim,  biricik eşim! 

Ilık nefesinle hayat bulsun da canım,

Mest u hayran olayım sana Gülcan''ım!', 'Sen Ey!  Güller Padişahı''nın Yüzünün Teri!  Ürkek ve nazlı ceylanın mahmur gözleri!  Leyla''nın alnında parıldayan nûr!  Cân''a aşk kokuları b...', ARRAY['Türk Edebiyatı','Şiir','Aşık Seheri']::text[], 8.5, '{"poet":"Aşık Seheri","poet_slug":"asik-seheri","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulcan-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Olacak', 'can-olacak-ahmet-yozgat-3d9zg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Sofrada yeşil salataya doğradığım 

Kan kırmızı canım domatesler

Damarımda kan olacak 

Akacak ılgıt ılgıt.

2/:

Yemekten sonra yediğim 

Kan kırmızı canım elmalar

Boğazımda can olacak 

Yürüyecek kımıl kımıl.', '1/: Sofrada yeşil salataya doğradığım  Kan kırmızı canım domatesler Damarımda kan olacak  Akacak ılgıt ılgıt. 2/: Yemekten sonra yediğim  Ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/can-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Benzesin Keloğlan', 'bana-benzesin-keloglan-ahmet-yozgat-nladr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Bir masal daha anlat bana bu gece

Bal akıt ağzından masalcı amca

Tıpkı bana benzesin keloğlan

Yaşlı anası benim anama

Kasabaları benzesin bizimkine

Yoksul kulübeleri evimize benzesin

Şalvarının dizlerindeki yaması

Benzesin benim süslü yamama.

2/:

Bir masal daha anlat bana 

Pekmez akıt ağzından masalcı amca 

Kaf dağı''ndaki devlerin en irisi

Benzesin bizim battal amcaya

Hani var ya şu ''Het hüt! '' Diye

Çocukları bastonuyla kovalayan 

Aşağı bağın bekçisi...

3/:

Bir masal daha anlat haydi bana 

Süt akıt ağzından masalcı amca

Tıpkı ablama benzesin 

Dünyalar güzeli padişah kızı

Benzesin kaderi kaderimize

Sarayları bizim eve benzesin

Sırtına bindiğim tılsımlı ankanın hızı

Kırmızı bisikletime benzesin.

1/:

Bir masal daha anlat bana 

Gül akıt ağzından masalcı amca

Tıpkı bana benzesin şehzade

Bilge babası benim babama benzesin

Ülkeleri benzesin ülkemize

Benzesin büyülü dilleri dilimize

Sihirli gülleri gülümüze benzesin.', '1/: Bir masal daha anlat bana bu gece Bal akıt ağzından masalcı amca Tıpkı bana benzesin keloğlan Yaşlı anası benim anama Kasabaları benzesi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bana-benzesin-keloglan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geyik Ağabey', 'geyik-agabey-ahmet-yozgat-tdsx3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Söyle bana geyik ağabey 

Başındaki çatal çatal boynuzların

Neye yarar geyik ağabey? 

Kaçarken can düşmanından 

Sık ağaçlı koca ormanda.

2/:

Söyle bana geyik ağabey 

Kafandaki çatal çatal boynuzların

Zarar vermez mi sana? 

Takılmaz mı kuru dallara? 

3/:

Söyle bana geyik ağabey

Avlanmak üzereyken su başında

Korumak için kedini 

Neyle saldırırsın düşmanlarına?', '1/: Söyle bana geyik ağabey  Başındaki çatal çatal boynuzların Neye yarar geyik ağabey?  Kaçarken can düşmanından  Sık ağaçlı koca ormanda. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geyik-agabey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tuzlu Bir Tuzsuz', 'bir-tuzlu-bir-tuzsuz-ahmet-yozgat-k2lnn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Zavallı annem

Bir gün tuzlu yapar

Pişirdiği yemeği

Babam yemez kalkar sofradan

Ablam batırmaz kaşığının ucunu

Bense hemen kıvırırım burnumu

Hiç sormayın delidolu ağabeyimi

Bu gün de olmaz yiyen 

Annemin tuzlu yemeğini 

Kalmaz sofrada hiç kimsenin isteği.

2/:

Zavallı annem ertesi gün 

Tuzsuz yapar yemeği

Babam çatar kaşını

Ablam koşar okulun kantinine 

Ben de hamburgere 

Hiç sormayın aklı havada ağabeyimi 

Bu gün de olmaz yiyen 

Annemin tuzsuz yemeğini

Kapanır sofrada herkesin isteği.

3/:

Zavallı annem 

Az koyar tuzu olmaz 

Çok koyar olmaz tuzu

Bir türlü ortasını bulamaz

Zavallı annem ne bilsin

Ayak üstü beslenmeye alıştığımızı

Bu gidişle kimselere yaranamaz.', '1/: Zavallı annem Bir gün tuzlu yapar Pişirdiği yemeği Babam yemez kalkar sofradan Ablam batırmaz kaşığının ucunu Bense hemen kıvırırım burn...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-tuzlu-bir-tuzsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen aşık değilsin', 'sen-asik-degilsin-ali-riza-unal-lty0c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen aşık değilsin a benim cancağzım çünkü sen sevgiliyi-

Tanımıyorsun sen onda hata kusur aramadasın ve hata-

Kusur görmedesin,eğer senin arzun sevgin sana aşk zannı- veriyorsa sen büyük bir gaflette bir yanılmadasın seninki ancak arzu hevadan başka bir şey değil  yoksa sende bu şaşılık bu ikilem olmazdı ve sen o sevgilinin sevgisinde yok olurdun gel ben sana aşktan biraz haber vereyim aşık sevgi-

Sine sevgilisine öyle bir göz yummadaki, onda ne mal ne mülk, ne ana ne baba, ne evlat ne kardeş,ne akraba ne dünya ne ahiret ne din ne iman kalmaz onun dinide imanıda-

Mihrabıda kıbleside sevgilisidir ebu kays bu gün leylaya aşık ise din leylanın dinidir bunlar garip ama gerçek sende bu leylaya tapıcılık varmıki o öyle bir sıtmada öyle bir hummadırki

 Ona dünyanın hiçbir hekimi çare bulamaz hiçbir ilaç şifa olamaz,onun ilacı sevgilisinden bir nefes ses,bir göz kıpmasıdır,o göz kırpmaya aşığın gönlü ebedi bir ömür tükenenmez bir hayat bulur,bunu tatmayan bilmez,o göz kırpma ister iyi ister kötü olsun,ister tebessüm ister kahır

Görünsün  o aşık bilir sengiliyi sevgilisini onun kahrınında

Arkasında vuslat muştuşu yakındır Hayyyy Alllaaaah bu ne –

Aşk aman Allahım amaaan ya medet,) :! ! ! İşte o, o cefadan o-

Kahırın içinden sıyrılırda  vefasının  vuslat meyvelerine ulaşır- o kara bulutların karanlığında  altı çamur üstü yağmur

İken bile  hoş bir alemdedir e  a benim  cancağazım işte aşkın haberini aldın gerçi bizim aşkımızı tam anlatmaya kalksak denizler ve okyanuslar mürekkep olsa yer yüzünün –

Tüm ağaç ve otları kalem olsa, gökte melekler yerde insanlar

Katip olsa bunların hepsi biterde bizim aşkımızın sonu gelmez sen en iyisi  böyle bir aşığı bulda onun ekmeğine suyuna katık bari ol buda yoksa sende, sen yaşadığını zan eden bir uykucu ölüsün ölü. Bilmem anlatabildikmi acaba?  :)

A benim canım a benim cancağazım :) ..', 'Sen aşık değilsin a benim cancağzım çünkü sen sevgiliyi- Tanımıyorsun sen onda hata kusur aramadasın ve hata- Kusur görmedesin,eğer senin ar...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-asik-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasım Dayı', 'kasim-dayi-ahmet-yozgat-09wss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Uçuşur başımda kelebek gibi karlar

Yağmurlar süzülür yüzümden

Buluşur kış ile sonbahar

Kasım dayı gelince 

Bizim yoksul kenar mahalleye.

2/:

Kırmızı kiremitli çatılar ıslak ıslak

Dar sokaklar çamur çamur bulaşır

Zavallı babalar evlere odun taşır 

Torba torba kara kömür taşır

Yaz yorgunu kenar mahallemiz 

Beklediği karakışa ulaşır.', '1/: Uçuşur başımda kelebek gibi karlar Yağmurlar süzülür yüzümden Buluşur kış ile sonbahar Kasım dayı gelince  Bizim yoksul kenar mahalleye....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kasim-dayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedemin Diyecekleri', 'dedemin-diyecekleri-ahmet-yozgat-gzl2j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

''Bizim zamanımızda...'' Diye

Bir başlarsa konuşmaya

Pamuk sakallı geveze dedem

Sonu gelmez diyeceklerinin

2/:

''Bizim zamanımızda...'' Diye

Bir başlarsa konuşmaya

Kaç kere anlattı bilinmez bana

Adanalı çavuşunun dediklerini

Ve seferberlik öykülerini

3/:

''Bizim zamanımızda...'' Diye

Bir başlarsa konuşmaya

Bitiremez düşmanlarını kese kese

Anlatır bana koridorda

Sana anlatır sokakta ayaküstü

Ve anlatır önüne gelen herkese', '1/: ''Bizim zamanımızda...'' Diye Bir başlarsa konuşmaya Pamuk sakallı geveze dedem Sonu gelmez diyeceklerinin 2/: ''Bizim zamanımızda...'' Diye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dedemin-diyecekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Dalında Öterdim', 'gul-dalinda-oterdim-yusuf-onder-bahceci-rkigq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben evvel ce gül dalında öter dururdum,

Şimdi viran bağlarda baykuşmu oldum,

Huma kuşu gibi, yolları bekler dururum,

Ben evvel ce gül dalında öter dururdum.

Görsen kargalar gülüyor şimdi hâlime,

Turnalar geçer gider, ne derim yârime,

Göçmen kuşlar, döndüm Hacı Leyleğe,

Ben evvel ce gül dalında öter dururdum. 

Serçe kadar olamadım ben Dünya''da,

İspinoz kuşu gibi, titrer dururum daha,

Kırlangıçlar gibi birden dalamadım da,

Ben evvel ce gül dalında öter dururdum.

Keklik gibi ötsen, sekerek de yürüsen,

Eyvah, eyvah diye dizlerini hep dövsen,

Sen yaralı kartala döndün bunu bilirsen,

Ben evvel ce gül dalında öter dururdum...', 'Ben evvel ce gül dalında öter dururdum, Şimdi viran bağlarda baykuşmu oldum, Huma kuşu gibi, yolları bekler dururum, Ben evvel ce gül dalınd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-dalinda-oterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Kuşları', 'su-kuslari-ahmet-yozgat-ejkg3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Bir kuşluk vaktiydi 

Kuşlar kanat salladılar

Ben çıktım hızla evimizden 

Evinizden sen daha hızlı çıktın 

O çıktı en sonunda en hızla evlerinden.

2/:

Bir kuşluk vaktiydi 

Kuşlar el salladılar

Ben geldim koşa koşa 

Mahalledeki çeşme başına 

Sonra uça uça sen geldin

O da geldi sonunda çeşme başına.

3/:

Bir kuşluk vaktiydi

Kuşlar dil salladılar

Ben pek çok içirdim 

Sen benden daha çok içirdin 

Sonunda en çok da o içirdi

Avucundaki serin suyu 

Güneşte yanmış ve susamış kuşlara.', '1/: Bir kuşluk vaktiydi  Kuşlar kanat salladılar Ben çıktım hızla evimizden  Evinizden sen daha hızlı çıktın  O çıktı en sonunda en hızla ev...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/su-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşe Giden Adam', 'i-se-giden-adam-ahmet-yozgat-dyjoc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Her ne zaman

Açsam çiçekli perdesini odamın

Bir adam bana bakar 

Durup karşı kaldırımdan

Çiçek açar yanağım 

Yıldız yıldız gülümserim

Hemen açarım camı

El sallarım

El sallar o da bana.

2/:

Ben rahat edeyim diye 

Her sabah erkenden

İşe giden o adam

Yani benim sevgili babam

Uzun uzun bana bakar 

Durup karşı kaldırımdan

Çiçek açar yanağı 

Yıldız yıldız gülümser

Hemen açarım camı

El sallarım

El sallar o da bana...', '1/: Her ne zaman Açsam çiçekli perdesini odamın Bir adam bana bakar  Durup karşı kaldırımdan Çiçek açar yanağım  Yıldız yıldız gülümserim He...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ise-giden-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanı Bozuk Para', 'kani-bozuk-para-ahmet-yozgat-cbpqg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Doldurup ceketimin yan cebine 

Bir avuç bozuk parayı 

Bu sabah yine fırladım çarşıya

Ağız birliği etmiş gibi 

Oradaki tüm satıcılar:

''Az.'' Dediler 

''Uz.''Dediler 

''Bu para yetmez.'' Dediler

2/:

Çok iyi biliyorum

Az da değil

Uz da değil bu para

''Bu paralar bozuk...'' Diye 

Hiçbir şey vermediler', '1/: Doldurup ceketimin yan cebine  Bir avuç bozuk parayı  Bu sabah yine fırladım çarşıya Ağız birliği etmiş gibi  Oradaki tüm satıcılar: ''Az...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kani-bozuk-para-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanç Kardeşin Mesajı', 'kiskanc-kardesin-mesaji-ahmet-yozgat-9qsd8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söyle neden doğdun? 

Benden sonra küçük açıkgöz

Bir de kardeş olacaksın

Söyle hangi kardeş yapar? 

Senin yaptığını 

Herhangi bir kardeşine.', 'Söyle neden doğdun?  Benden sonra küçük açıkgöz Bir de kardeş olacaksın Söyle hangi kardeş yapar?  Senin yaptığını  Herhangi bir kardeşine....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kiskanc-kardesin-mesaji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüksek Ağaçlardayım', 'yuksek-agaclardayim-ahmet-yozgat-ic7a5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ağaçlara tırmanıyorum

Yüreğim uçuyor pır pır

Sayın ki sanki kocaman bir kuşum

Öyle hafifliyorum öyle hafifliyorum ki

Çok mutlu ediyor beni

Bu kadar yükseğe uçuşum.

2/:

Ağaçlara tırmanıyorum

Yongalar yırtıyor avuçlarımı

Bacaklarıma sivri dikenler batıyor 

Ben hiçbir şey duymuyorum

Çok mesut ediyor beni

Bu kadar yüksekten bakışım.', '1/: Ağaçlara tırmanıyorum Yüreğim uçuyor pır pır Sayın ki sanki kocaman bir kuşum Öyle hafifliyorum öyle hafifliyorum ki Çok mutlu ediyor be...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuksek-agaclardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Hırsızı', 'zaman-hirsizi-ahmet-yozgat-z9dp4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Bir hırsız dadandı ki sormayın 

Geceleri bizim mahalleye

''İllallah! '' Dedirdi tüm ahaliye

Yerde para görse almaz

Ama saatlere dayanamaz

Görse kimin yanında bir boş zamanı 

Anında kapar ve kaçar

Ömrümüzde kocaman bir delik açar

2/:

Bir hırsız dadandı ki sormayın 

Bizim yoksul mahalleye

''Aman Allah! '' Dedirdi tüm ahaliye 

Çalıp bütün boş zamanları 

Döndürdü bizi deliye.', '1/: Bir hırsız dadandı ki sormayın  Geceleri bizim mahalleye ''İllallah! '' Dedirdi tüm ahaliye Yerde para görse almaz Ama saatlere dayanamaz ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zaman-hirsizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
