INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simitçi Kardeş', 'simitci-kardes-ahmet-yozgat-urwnr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Sonunda saat oldu yedi

Yani geçiş saati simitçinin

Önce sıcak sıcak kokusu gelir 

Ardından çıtır çıtır kendi

İçi simit dolu kahverengi sepetinin

Görüntüsü öyle hoş, öyle hoş ki.

2/:

Sonunda saat oldu yedi 

Onun ''Simitçiii! ...'' deyişi

Kolları ya da bacakları gibi

İpinceciktir

Simitleri de yüreği gibi sıcacık

Somurtkan yüzü de gülecek 

Para kazanabilse azıcık.', '1/: Sonunda saat oldu yedi Yani geçiş saati simitçinin Önce sıcak sıcak kokusu gelir  Ardından çıtır çıtır kendi İçi simit dolu kahverengi s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/simitci-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlü Güzel', 'gonlu-guzel-belgin-turan-9dbrx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzellik  dediğin  ne  ki, kalbe  süzülen  ışıktır,

Coşkunun en  şahı  ile,   yüreği  yakan  bakıştır,

Gönlünde hep yüceltiğin, o hiç bitmeyen bir aşktır,

Güzel  olan  ruh da  güzel  o sönmeyen bir  ışıktır.

Belgin Turan                                        09.06.2005

''Güzden Önce Aşktan Sonra'' adlı şiir kitabımdan alınmıştır.

Gündüz Kitabevi Yayınları

Demet 7. Sokak No:7/b

Yenimahalle/Ankara', 'Güzellik  dediğin  ne  ki, kalbe  süzülen  ışıktır, Coşkunun en  şahı  ile,   yüreği  yakan  bakıştır, Gönlünde hep yüceltiğin, o hiç bitmey...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gonlu-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Arsa Katliamı', 'bos-arsa-katliami-ahmet-yozgat-drjwy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Tükendiler tek tek 

Boş arsaları mahallemizin

Bir apartman dikildi 

Eksildi bir boş arsa daha

Körebeye mezar oldu sonunda

Derin temeli o apartmanın da.

2/:

Yirmi katlı bir site dikildi

Mahalleden eksildi 

Kocaman bir boş arsa daha

Saklambaç da kurban edildi sonunda 

Yirmi katlı sitenin açılışında.

3/:

Bu sefer sıra geldi

Büyükçe bir iş hanına

Bir boş arsa daha kapandı sonunda 

Çelik çomağımız da odun oldu 

Mahalle fırınının külhanında.', '1/: Tükendiler tek tek  Boş arsaları mahallemizin Bir apartman dikildi  Eksildi bir boş arsa daha Körebeye mezar oldu sonunda Derin temeli o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bos-arsa-katliami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalışkanın Hali Başka', 'caliskanin-hali-baska-ahmet-yozgat-muckj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Sınıfta en ön sıradayım

Parmaklarım hep havada 

Ben havalardayım

Sorular geliyor peş peşe

Yanıtları hazırlamışım 

Taa akşamdan

Bazen Avrupa''da 

Bazen de Amerika''dayım

Geziniyorum tarihin sayfalarında

Coğrafyadaki en uzak diyarlardayım

Rakamlar arasında koşuyorum son hızla

Arkadaş oluyorum uzayda bir yıldızla.

2/:

sınıfta en ön sıradayım

Parmaklarım hep havada 

Ben havalardayım 

Ardıma geçiyor tembelleri sınıfın 

Kendimi savunmadayım

Zil çalıyor sonunda

Eller üzerinde havalardayım.', '1/: Sınıfta en ön sıradayım Parmaklarım hep havada  Ben havalardayım Sorular geliyor peş peşe Yanıtları hazırlamışım  Taa akşamdan Bazen Avr...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/caliskanin-hali-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Ördek', 'guzel-ordek-ahmet-yozgat-3sc1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Mavi gölde gün boyu yüzen 

Ayakları perdeli paytak ördek

Yeşile kim boyadı güzel başını? 

2/:

Mor çayırlarda öte öte gezen 

Kül renkli çayır kuşu

Kim dokudu kilim gibi nakışlı kanadını? 

3/:

Ulu dağlarda tek başına uçan 

Kıvrık gagalı soylu kartal 

Kim tıraş etti keloğlan gibi başını? 

4/:

Kahverengi tarlalarda yem arayan 

Başı yerde dolaşan tarla kuşu 

Kim taradı prenses gibi saçaklarını? 

5/:

Dumanlı kaf dağında masal arayan 

Bin bir yaşındaki zümrüt anka kuşu 

Kim koydu seni şehzade gibi masallara?', '1/: Mavi gölde gün boyu yüzen  Ayakları perdeli paytak ördek Yeşile kim boyadı güzel başını?  2/: Mor çayırlarda öte öte gezen  Kül renkli ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guzel-ordek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara Öğüdü', 'sigara-ogudu-ahmet-yozgat-pjvxm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen neden içersin? 

Püfür püfür dumanlı sigaranı baba

Sonra bana dönüp de: 

''İçme bu zıkkımı.'' Dersin 

''Aman evladım aman.'' 

''Bak bizim halimize! ''

Önce dönüp kendine ver o öğüdü

Sen içme sigarayı baba

O zıkkımı eğer bırakırsan sen 

Ben içmem zaten...', 'Sen neden içersin?  Püfür püfür dumanlı sigaranı baba Sonra bana dönüp de:  ''İçme bu zıkkımı.'' Dersin  ''Aman evladım aman.''  ''Bak bizim hali...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sigara-ogudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cıs!', 'cis-ahmet-yozgat-nvm0x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman uzatsam elimi 

Ortalıkta yanan ateşe

Annem atlar oturduğu köşeden: 

''Cıs, cıs! ''

Bırak da anneciğim 

Tecrübe edeyim ne olur? 

Kendim ''cıs'' olduğunu ateşin.', 'Ne zaman uzatsam elimi  Ortalıkta yanan ateşe Annem atlar oturduğu köşeden:  ''Cıs, cıs! '' Bırak da anneciğim  Tecrübe edeyim ne olur?  Kendi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Biberon Ninni', 'bir-biberon-ninni-ahmet-yozgat-4aito', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyandı gece yarısı minik

Ağladı yırtına yırtına

''Uyusun.'' Diye annesi

 Su içirdi olmadı...

Süt içirdi olmadı...

Şekerli şerbet içirdi olmadı...

Ballı şerbet içirdi olmadı...

''Uyusun.'' Diye annesi 

Boşaltıp biberondaki

Sütü, şekeri, balı ve suyu

Yerine ninni doldurdu

İçince ninniyi 

Minik mışıl mışıl uyudu.', 'Uyandı gece yarısı minik Ağladı yırtına yırtına ''Uyusun.'' Diye annesi  Su içirdi olmadı... Süt içirdi olmadı... Şekerli şerbet içirdi olmadı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-biberon-ninni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelenek Bozulmasın', 'gelenek-bozulmasin-ahmet-yozgat-f1pst', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sürekli taşırım 

Arka cebimdeki lastik sapanımı

Ne serçe vurmak için 

Ne de taşlamak için sığırcıkları

Ne camları kırmak için 

Ne de taşlamak için sokak lambalarını

Ne dalları kırmak için 

Ne de taşlamak için kuş yuvalarını

Ne akranlarımı vurmak için 

Ne de taşlamak için çatıdaki bacaları 

Sapanımı taşımamın nedeni bir tek 

Bozulmasın diye gelenek.', 'Ben sürekli taşırım  Arka cebimdeki lastik sapanımı Ne serçe vurmak için  Ne de taşlamak için sığırcıkları Ne camları kırmak için  Ne de taş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelenek-bozulmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyitimsi Sözler 5', 'beyitimsi-sozler-5-huseyin-avdic-wmiix', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küfürdür Allah''a

Allah''in $anina yaki$maz, O''na ''baba'' demek.

Küfürdür Allah''a, Isa''yi O''na ''ogul'' etmek.

Berlin, $ubat 2006.', 'Küfürdür Allah''a Allah''in $anina yaki$maz, O''na ''baba'' demek. Küfürdür Allah''a, Isa''yi O''na ''ogul'' etmek. Berlin, $ubat 2006....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/beyitimsi-sozler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Dallı Ağaç', 'kirik-dalli-agac-ahmet-yozgat-r83pw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ağaçlar üzülecek 

Yaramazın birinin acımadan kırdığı

Solgun dalına bakıp da hüzünlenecek.

2/:

Ağaçlar dillenecek 

Yaramazın birinin 

Yakalayıp parmağının ucunu:

''Sağ ya da sol kolunu

Koparsam senin nasıl olur? '' diyecek.', '1/: Ağaçlar üzülecek  Yaramazın birinin acımadan kırdığı Solgun dalına bakıp da hüzünlenecek. 2/: Ağaçlar dillenecek  Yaramazın birinin  Yak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kirik-dalli-agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Aldı', 'cocuklar-aldi-ahmet-yozgat-fbsz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Bir küçük mahalleye

Çıkageldi bir şekerci

Kimse tatlı şekerleri almadı 

Ama çocuklar aldı.

2/:

Bir küçük mahalleye

Çıkageldi bir hayalci

Kimse renkli hayalleri almadı 

Ama çocuklar aldı.

3/:

Bir küçük mahalleye

Çıkageldi bir bebekçi

Çocuklar bebekleri almadı 

Ama anne babalar aldı...', '1/: Bir küçük mahalleye Çıkageldi bir şekerci Kimse tatlı şekerleri almadı  Ama çocuklar aldı. 2/: Bir küçük mahalleye Çıkageldi bir hayalci...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuklar-aldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Çırakın Acıları', 'kucuk-cirakin-acilari-ahmet-yozgat-yeu4w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ustam çok üşüyor minik bedenim

Bu şubat sabahında

Demir anahtarlar buz gibi

Yapışıyor ellerim

Kuramıyorum kirikoyu 

Sökülmüyor cıvata

Stepneler tekerleniyor üstüme

Yediğim anahtarlar kafama

Tatmadığım acıları veriyor

Ustam minicik ellerimle 

Doğrusu çok zorlanıyorum 

Tutunurken acımasız yaşama.', 'Ustam çok üşüyor minik bedenim Bu şubat sabahında Demir anahtarlar buz gibi Yapışıyor ellerim Kuramıyorum kirikoyu  Sökülmüyor cıvata Stepne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kucuk-cirakin-acilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninemin Öfkesi', 'ninemin-ofkesi-ahmet-yozgat-20i33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Zamane çocukları bunlar.'' dedi mi ninem

Bilirim ki fark etmeden basmışım 

Yine damarına damarına

Bilirim çaresini bu durumun

Hemen koşarım yanına 

Balık gibi atlarım kucağına:

''Hadi canım ninem 

Rahmetli dedemi bana anlatsana''

O anda geçer yaşlı ninemin öfkesi

Ta uzaklara dalar gözleri 

Bir yaprak gibi titrer incecik sesi

O anda ne siniri kalır 

Ne de deniz dalgasına benzeyen öfkesi

Başlar tane tane anlatmaya:

''bir gün rahmetli....''', '''Zamane çocukları bunlar.'' dedi mi ninem Bilirim ki fark etmeden basmışım  Yine damarına damarına Bilirim çaresini bu durumun Hemen koşarım ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ninemin-ofkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeteeer!', 'yeteeer-ahmet-yozgat-9uool', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tek ben miyim sanki? 

Geleceği bu dünyanın

Yok mu sanki? 

Emaneti alacak başka kişi

Matematik cellat olup boğuyor 

Sayılamaz kadar çok olan sayılarıyla beni

Fizik çuval olup yüklendi sırtıma 

Kimya derseniz hakeza 

Damar damar biyoloji... 

Tarih ki bulanmış savaşlara...

Coğrafya ırmak olup akıyor üzerime

Mantık...

Sosyoloji...

Ruh bilimi...

Hepsi birbirinden beter

Yeteeer! 

Bana hayat bilgisi.', 'Bir tek ben miyim sanki?  Geleceği bu dünyanın Yok mu sanki?  Emaneti alacak başka kişi Matematik cellat olup boğuyor  Sayılamaz kadar çok o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeteeer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-necmiye-sarpkaya-7q5qh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilsizlerin dillerini çözmedin mi

En abus çehreleri güldürmedin mi

Katı yürekleri yumuşatmadın mı

Zalimleri edeplendirmedin mi

Hükmedenlere hükmetmedin mi

Yıllar yıllar yılı

Ben sustum sen söyle

Mevlana şems, Yunus Emre

Şeyh Edebali  Akşemsettin  edip

Hikmetli sözler söyletmedin mi

Ben sustum sen söyle

Ferhat’a dağlar deldiren

Aslıya Kerem eyleyip

Diyar-ı  gurbet gezdiren

Züleyhaya Yusuf olup sultan eyleyen

Sen değil misin? 

Ben sustum sen söyle

İçli şiirler yazdıran

Yanık türküler söyleten

Hazin besteler

Ezgiler nağmeler dizdiren

Sen değil misin? 

Öylesine katı

Öylesine hayatsız

Öylesine nefessizlere nefes

Elsiz kolsuzlara el kol olan

Sen değil misin

Dize getirmedin mi prensleri sultanları

Kralları hükümdarları diktatörleri

Acıları bal eylemedin mi

Elem kederleri kar eylemedin mi

Mehtabı kucaklatmadın mı duyarsız yüreklere

Meltemlere döndürmedin mi fırtınaları

Ben sustum sen söyle sen söyle

Dünden bugüne çocuklukları getiren

Maziye set çektiren

Bıçakları koç eyleyen

Ateşleri gül eyleyen

Sen değil misin

Saçlar başlar ağartan

Mor halkalar oluşturan

Aynalara kah dost kah düşman eyleyen

Sen değil misin sen değil misin

Ben sustum sen söyle sen söyle', 'Dilsizlerin dillerini çözmedin mi En abus çehreleri güldürmedin mi Katı yürekleri yumuşatmadın mı Zalimleri edeplendirmedin mi Hükmedenlere ...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ask-553-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sığmıyorum', 'ben-sigmiyorum-ahmet-yozgat-54p8g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şen şakrak kahkaham sığmıyor 

Küçücük odamızın duvarlarına

Fışkırıp pencereden dört bir yana

Dağılıyor bütün dünyaya

Babamla oynuyorum 

Onun kocaman kocaman elleri 

Gıdıklıyor çenemi

Kollarım kuşların kanadı sanki 

Durmuyorlar yerlerinde

Sonsuz mutluluğum sığmıyor 

Göğsümdeki minicik yüreğime

Fışkırıyor dışarı 

Çevreye dağılıyor.', 'Şen şakrak kahkaham sığmıyor  Küçücük odamızın duvarlarına Fışkırıp pencereden dört bir yana Dağılıyor bütün dünyaya Babamla oynuyorum  Onun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-sigmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta Babam', 'usta-babam-ahmet-yozgat-gyebi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Babam yapı ustası

Bir elinde keseri 

Öbür elinde malası

Onun en büyük eseri

Bir ömür boyu

Bütün evlerini yaptığı

Kendi küçük kasabası.

2/:

Babam yapı ustası 

İşine erkenden gider

Benim aslan babam

Sabahtan akşama kadar

Çivi çakar bam bam bam.

3/:

Babam yapı ustası 

Tam kıvamında harç yapar

Harca emeğini katar 

Hatta terini katar.

4/:

Babam yapı ustası 

Kale suru gibi duvar örer

Duvara emeğini gömer 

Hatta yüreğini gömer.

5/:

Babam yapı ustası 

Akşam olunca iş biter

Aslan babam sevine sevine

Sıcak ekmek getirir 

Soğuk evine...', '1/: Babam yapı ustası Bir elinde keseri  Öbür elinde malası Onun en büyük eseri Bir ömür boyu Bütün evlerini yaptığı Kendi küçük kasabası. 2...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/usta-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Gizledin Yaralı Kâlbi', 'neden-gizledin-yarali-k-lbi-yusuf-onder-bahceci-e9qhz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden gizledin benden yârali kâlbi,

Senin dert ortağınım, seninle hasbi,

Seninle ne güzel olmuştum, kesbi,

Neden benden gizledin yaralı kâlbi

Ne olursa olsun, bana demeliydin,

Seni seviyorum, lakin demeliydin,

Bana demeliydin be söylemeliydin,

Neden benden gizledin yaralı kâlbi.

Bu yaptığın doğru değil olamaz bu,

Yıkamadım bir türlü, saçma gururu,

Gönlümün süruru, gözlerimin nuru,

Neden benden gizledin yaralı kâlbi.

Ne olurdu, bana hepsini deseydin,

Dertlerini benle, benle, bölseydin,

Bende senin için cânı verseydim,

Neden benden gizledin yaralı kâlbi...', 'Neden gizledin benden yârali kâlbi, Senin dert ortağınım, seninle hasbi, Seninle ne güzel olmuştum, kesbi, Neden benden gizledin yaralı kâlb...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-gizledin-yarali-kalbi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşluk Ve İkindi', 'kusluk-ve-i-kindi-ahmet-yozgat-9afqx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedense çok severim

Kuşluk ve ikindileri

Vakitlerin içinde

Alıp ardıma parlak güneşi 

Uzatınca boş ve düz arsalarda gölgemi

O anda keyfime yoktur diyecek

Büyümüş sanıyorum kendimi

Yaşasın kuşluk vakti

Vakitlerin içinde 

Ve yaşasın ikindi.', 'Nedense çok severim Kuşluk ve ikindileri Vakitlerin içinde Alıp ardıma parlak güneşi  Uzatınca boş ve düz arsalarda gölgemi O anda keyfime y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kusluk-ve-ikindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Minik Sevgilime Akrostiş', 'canim-minik-sevgilime-akrostis-zihni-duygun-t4938', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canımız

Evimizin

Yoncası

Dünyamızın

Aşısı

Mutluluğumuzun

Emeği

Rüyalarımızın

Varlığı

Ereğimiz', 'Canımız Evimizin Yoncası Dünyamızın Aşısı Mutluluğumuzun Emeği Rüyalarımızın Varlığı Ereğimiz...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/canim-minik-sevgilime-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 70', 'guncel-beyitler-70-huseyin-avdic-0z1kj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aldananlar Ve Kurtulanlar

Hic ölmiyecekmis gibi ya$amakta olan insanlar bir aldanistadir.

Yarin ölecekmis gibi âhiretine cali$anlarsa, kurtulustadir.

Berlin, $ubat 2006.', 'Aldananlar Ve Kurtulanlar Hic ölmiyecekmis gibi ya$amakta olan insanlar bir aldanistadir. Yarin ölecekmis gibi âhiretine cali$anlarsa, kurtu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yüklü Kelebek', 'sevgi-yuklu-kelebek-ahmet-yozgat-c6uvm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sırmadan kanatlı

Zümrüt yeşili renkli

Bizim süslü kelebek

Elime konup sevgi emecek

Sonra gökyüzüne göçecek 

Sevgi yüklü kelebek

İlişip ucuna apak bulutların

Kucak kucak çocukların üstüne 

Benim selamımı dökecek

Sonra buluttan buluta sekecek

Göçecek ülkeden ülkeye 

Bizim sevgi yüklü kelebek 

Barış ekecek, huzur ekecek.', 'Sırmadan kanatlı Zümrüt yeşili renkli Bizim süslü kelebek Elime konup sevgi emecek Sonra gökyüzüne göçecek  Sevgi yüklü kelebek İlişip ucuna...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-yuklu-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimci Geldi', 'i-simci-geldi-ahmet-yozgat-7ajlu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabahlardan bu sabah

Satıcılardan bir satıcı

Sokağımızda tezgah açtı

Ne incik ne de boncuk sattı kızlara

Ne de iğne iplik yaşlı ninelere

Bu satıcı isim sattı bizlere

Kimi ince:

''İnci'' dedi kendine 

Kimi uzun olanı seçti:

''Kemalettin'' adını beğendi

Kimi yenide karar kıldı:

''Sarp'' olabilir dedi

Eski kimiye uzandı:

''Abdülhamit'' adına sarıldı

Herkes beğendi yakışanı kendine

Ben de ''Ahmet''i'' aldım elime

Sevine sevine

Taktım döşüme.', 'Sabahlardan bu sabah Satıcılardan bir satıcı Sokağımızda tezgah açtı Ne incik ne de boncuk sattı kızlara Ne de iğne iplik yaşlı ninelere Bu ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isimci-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedemin Dili Bir Acayip', 'dedemin-dili-bir-acayip-ahmet-yozgat-1kb1z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabahlardan bu sabah

Satıcılardan bir satıcı

Sokağımızda tezgah açtı

Ne incik ne de boncuk sattı kızlara

Ne de iğne iplik yaşlı ninelere

Bu satıcı isim sattı bizlere

Kimi ince:

''İnci'' dedi kendine 

Kimi uzun olanı seçti:

''Kemalettin'' adını beğendi

Kimi yenide karar kıldı:

''Sarp'' olabilir dedi

Eski kimiye uzandı:

''Abdülhamit'' adına sarıldı

Herkes beğendi yakışanı kendine

Ben de ''Ahmet''i'' aldım elime

Sevine sevine

Taktım döşüme.', 'Sabahlardan bu sabah Satıcılardan bir satıcı Sokağımızda tezgah açtı Ne incik ne de boncuk sattı kızlara Ne de iğne iplik yaşlı ninelere Bu ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dedemin-dili-bir-acayip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökler Ağlıyor', 'gokler-agliyor-ahmet-yozgat-z3igv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'A/:

Bu gün gökler ağlıyor 

Ona bakıp ben de ağlıyorum

Gök yüzünün gözleri yaşlı 

Yaşlı benim gözlerim

Göğün gözleri ''yaşlı'' 

Ama benim gözlerim ''çocuk''

B/:

Bu gün gökler ağlıyor 

Hüzünlenip ben de ağlıyorum

Göğün gözünden süzülen her damla

Yağmur oluyor düşüyor tarlalara

C/:

Bu gün gökler ağlıyor 

Dalıyorum derinlere ben de ağlıyorum

Gökler yağmur yağmur ağladıkça 

Ben daha çok ağlıyorum

Emiyor toprak göğün göz yaşlarını

Çayırlarda çimen oluyor

Ağaç oluyor bahçelerde

Yeşil kaplıyor bütün dünyayı

D/:

Bu gün gökler gülüyor 

Ama ben ağlıyorum

Yüreğim emiyor göz yaşlarımı

Sevgi oluyor, huzur oluyor

Kaplıyor bütün dünyayı

E/:

Bu gün gökler gülüyor

Ona katılıyorum 

Katıla katıla ben de gülüyorum.', 'A/: Bu gün gökler ağlıyor  Ona bakıp ben de ağlıyorum Gök yüzünün gözleri yaşlı  Yaşlı benim gözlerim Göğün gözleri ''yaşlı''  Ama benim gözle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gokler-agliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Yalnızlık', 'merhaba-yalnizlik-kiymet-sonmez-b3x6b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siyah beyaz bir türk filmi izledim dün gece,

Şarkıcı kadın,

‘’Elvada bütün gençliğim, elvada bütün hatıralar diyordu’’

Sanki o değil, ben söyledim o şarkıyı.

Öyle ya ne gençlik kaldı,

Ne de o gençliği hatırlatacak anı.

Nasılda uçup gitmiş elimden,

Meğer ben sadece o yaşı geçirmişim,

Ama ne çocuk, nede genç olabilmişim.

Büyümeden yaşlanmışım meğer....

Yaşlanmışım ama,

Hiçbirşeyimde olmamış.

Ne dolu dolu bir sevda yaşamışım,

Nede çoluk çocuğum olmuş.

Bütün ailem iyi kötü bir yuva kurmuş,

Hatta güzel sevdalar da yaşamışlar.

Her ailede bir kurban olur ya

Bizim aileninde kurbanı ben olmuşum.

Küçükken büyük olmanın sorumluluğu,

Genç olmadan olgun olmanın zorunluluğu,

Ailenin geçimini sağlamanın yükümlülüğü,

Şimdi geçmiş o güzel yıllar hep,

Şimdi yaşarım desem nasıl? 

Körelmiş bütün duygular,

Ağarmış saçlarlarmı? 

Yüze düşmeye başlayan kırışıklarlarmı? 

Demir tavında dövülür a kızım.

Bırak artık geriye dönmeyi,

Madem kurban sen seçildin,

Uzat boynunu da adak yerine gelsin.....

Ve söyle yine ‘’merhaba yalnızlık yine ben geldim’’

‘’Elvada bütün gençliğim, elvada hatıralar’’

Geçmişten getirdiğim birtek sen varsın,

Yalnızlık,

Doğarkende vardın, bütün yaşamımda da vardın,

Ölürken de bir tek sen olacaksın,

Onun için geçmişe kapayıp gözlerimi,

Yine sana diyorum merhaba yalnızlık.........', 'Siyah beyaz bir türk filmi izledim dün gece, Şarkıcı kadın, ‘’Elvada bütün gençliğim, elvada bütün hatıralar diyordu’’ Sanki o değil, ben sö...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/merhaba-yalnizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çobanlar', 'cobanlar-ahmet-yozgat-s3d6f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'A/:

Dağların yalnız adamları 

Yani unutulmuş çobanlar

Subaşlarında kara koyunlarına

Dertli ve yanık kaval çalarlar.

B/:

Kırların yalnız adamları 

Yani unutulmuş çobanlar 

Kilim dokumalı azık çantalarını 

Çözüp bellerinden 

Çayırların döşüne sofra kurarlar.

Ç/:

ufukların yalnız adamları 

Yani unutulmuş çobanlar 

Yanık tandır ekmeğinin yanına 

Kocaman ve nasırlı yumruklarıyla 

Bir baş kuru soğan kırarlar.

C/:

Yaylaların yalnız adamları 

Yani unutulmuş çobanlar

Sürülerini süre süre 

Ta yıldızlara çıkarlar.

D/:

Dünyanın yalnız adamları 

Yani unutulmuş çobanlar 

Yüzleri yerde koyunlarıyla 

Ve kurt korkutan köpekleriyle 

Yıldızlar altında yatarlar.', 'A/: Dağların yalnız adamları  Yani unutulmuş çobanlar Subaşlarında kara koyunlarına Dertli ve yanık kaval çalarlar. B/: Kırların yalnız adam...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cobanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıkmış Ağaçkakan', 'acikmis-agackakan-ahmet-yozgat-gzgzs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A/:

Yaşlı bir ağaçkakan

Yıllardır penceremin önünde duran 

Asırlık çınar ağacını

Gelirken kakar: Tak tak! 

Giderken ''Tak tak! '' kakar...

Ağacın budak deliğinden öz yaşı akar.

B/:

Yaramaz bir ağaçkakan

Komşum Levent dayının tahta bacağını

Gelir kakar...

Gider kakar...

Levent dayı bir bacağına bakar

Bir de döner acıkmış kuşa bakar

Kıyamaz zavallıya.

Ama yine de gözünden yaşlar akar.', 'A/: Yaşlı bir ağaçkakan Yıllardır penceremin önünde duran  Asırlık çınar ağacını Gelirken kakar: Tak tak!  Giderken ''Tak tak! '' kakar... Ağa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/acikmis-agackakan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Ağaç', 'o-agac-ahmet-yozgat-jgro6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'A/:

O ağaç

Yol üstünde

''Şipşirin görüneyim.'' Diye

Her gelene, her geçene

Eğilir ve selam verir...

B/:

O ağaç

Yol üstünde

''Şipşirin görüneyim.'' Diye

İlkbaharda pespembe olur

C/:

O ağaç

Yol üstünde

Şirin görüneyim diye

Yazın yemyeşile bürünür.

Ç/:

O ağaç

Yol üstünde

''Şipşirin görüneyim.'' Diye

Sapsararır her sonbaharda.

D/:

O ağaç

Yol üstünde

''Şipşirin görüneyim.'' Diye

Her mevsim bir türlü giyer

Ama bulamaz beklediği ilgiyi

Sonunda kış çökünce havaya

Soyunur bütün renklerini

Yani öldürür kendisini.', 'A/: O ağaç Yol üstünde ''Şipşirin görüneyim.'' Diye Her gelene, her geçene Eğilir ve selam verir... B/: O ağaç Yol üstünde ''Şipşirin görüneyim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/o-agac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sevgilime Akrostiş', 'canim-sevgilime-akrostis-zihni-duygun-r0cz5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ciğerim yanıyor pare pare

Eşimden evimden ayrıyım diye

Meyhanelerde geziyorum avare

İçiyorum dertlerim bitsin diye

Leyla’sız Mecnun’um bîçare

Evime dönüp öpsem diye

Bir tanemsin kız

Aşığım sana kız

Hakikat bu kız

İçimdesin kalbimdesin kız

Rüyalarımdasın gönlümdesin kız

Eşin benzerin yok senin kız

Artık	     Duygun’um

Kadere	  Uygunum

Dertsiz      Yorgunum

Evimin      Gündüzüyüm

Neşenin   Uğrağıyım

İçip de      Neyleyim

Zihni’nin 	…', 'Ciğerim yanıyor pare pare Eşimden evimden ayrıyım diye Meyhanelerde geziyorum avare İçiyorum dertlerim bitsin diye Leyla’sız Mecnun’um bîçar...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/canim-sevgilime-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Battı', 'gun-batti-ahmet-yozgat-a8574', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'A/:

Bu günde sabah oldu ve gün doğdu 

Altın ışıklar yaktı çevreyi 

Güzel güneş gün boyu parasız aydınlattı

Gölgede kalan serin köyleri 

Loş evleri ve boş odaları

Ancak yaktı kavurdu 

Gün boyu açıkta çalışanları.

B/:

Bu günde akşam oldu ve gün battı

Sayın ki ben de battım

Yani karanlık battı gönlüme.

Ç/:

Bu günde akşam oldu ve ay doğdu 

Gümüş ışıklar aktı çevreye 

Güzelim hilal girdi pencereden evlere

Oturdu en baş köşeye

Mutlu ve umutlu masallar anlattı 

Minicik bebelere

C/:

Bu günde sabah oldu ve hilal battı

Sayın ki ben  de battım

Yani iğne battı gönlüme.', 'A/: Bu günde sabah oldu ve gün doğdu  Altın ışıklar yaktı çevreyi  Güzel güneş gün boyu parasız aydınlattı Gölgede kalan serin köyleri  Loş ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gun-batti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Ay Doğacak', 'bu-gece-ay-dogacak-ahmet-yozgat-1wa7x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'A/:

Bizim köyde erken çöker geceler

Akşamın gri yüzü birazdan

Tez elden kararacak

''Ben korkarım karanlıktan.''

''Haydi gülümse küçüğüm.'' 

Bu gece ay doğacak.

B/:

Bizim köyde uzun olur geceler

Daracık sokakları birazdan

Karanlıklar saracak

''Ben korkarım yalnızlıktan.''

''Haydi gülümse küçüğüm.''

Bu gece ay doğacak.', 'A/: Bizim köyde erken çöker geceler Akşamın gri yüzü birazdan Tez elden kararacak ''Ben korkarım karanlıktan.'' ''Haydi gülümse küçüğüm.''  Bu g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-gece-ay-dogacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökten Ne Düştü?', 'gokten-ne-dustu-ahmet-yozgat-tbvfp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'A/:

Gökten üç damla düştü

Biri çorak tarlalara 

Biri de kıraç kırlara

Biri de biz çıkmayalım diye 

Yumuşak kerevetlere...

B/:

Gökten üç şiir düştü

Biri renkli rüyalara 

Biri de lezzetli masallara

Biri de biz okuyalım diye 

Güzelim kitaplara...', 'A/: Gökten üç damla düştü Biri çorak tarlalara  Biri de kıraç kırlara Biri de biz çıkmayalım diye  Yumuşak kerevetlere... B/: Gökten üç şiir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gokten-ne-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Köşkümü Yıktı', 'gonul-koskumu-yikti-sahin-kars-kscbq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu garip gönlümde dert perde perde,

O dosttan aldığım beter mi beter.

Sevdanın ateşi tutuştu serde,

Yanar oylum oylum tüter mi tüter.

Özüm ayağına turap eyledi,

İçirdi göz yaşım şarap eyledi.

Yıktı gönül köşküm harap eyledi,

Virânemde baykuş ötermi  öter.

Hayâli gönlümün sılası oldu,

Sevdası ömrümün çilesi oldu.

Şahin bu zalimin kölesi oldu,

Götürüp pazarda satar mı satar.', 'Şu garip gönlümde dert perde perde, O dosttan aldığım beter mi beter. Sevdanın ateşi tutuştu serde, Yanar oylum oylum tüter mi tüter. Özüm a...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-koskumu-yikti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak Uçurtma', 'tutsak-ucurtma-ahmet-yozgat-v4aqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Sardılar bizim mahallenin üstünü 

Binlerce örümcek ağı gibi

Bir o yana dönerek

Bir bu yana bükülerek

Parmak kalınlığında çelik teller

Ve bakır teller urgan gibi 

Sicim gibi plastikten kablolar.

2/:

Geldi uçurtma mevsimi 

Canı uçmak istedi uçurtmamın

Yol kesen çelik teller, 

Plastik haydut kablolar

Ve katil bakır teller 

Uçurtmama yol vermediler.

3/:

Uçurtmam tutsak şimdi 

Takıldı kaldı bir çelik tele

Yüzü küskün, kuyruğu düşük 

İpi sarkıyor çamurlu yerlere.

www.ahmetyozgat.com', '1/: Sardılar bizim mahallenin üstünü  Binlerce örümcek ağı gibi Bir o yana dönerek Bir bu yana bükülerek Parmak kalınlığında çelik teller Ve...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tutsak-ucurtma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlardan Nal Çaktım', 'yildizlardan-nal-caktim-ahmet-yozgat-vbxou', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Nalı düştü tahta atımın 

Bizim küçük azgın dereye

Çaktım hemen ayağına 

Ay dedeyi nal diye

Tahta atın düşen nalının yerine.

2/:

Tahta atım sıçradı uzaklara 

Savurdu kaf dağındaki bulutları

Anka gibi süzüle süzüle 

Atladı bütün hudutları

3/:

Nalı düştü tahta atımın 

Bizim büyük azgın nehire 

Yıldızlardan nal çaktım 

Ayağına atımın nalın yerine.

4/:

Tahta atım sıçradı gökyüzüne 

Savurdu pamuklar gibi bulutları

Bir duman gibi süzüle süzüle 

Dolaştı bütün yurtları.', '1/: Nalı düştü tahta atımın  Bizim küçük azgın dereye Çaktım hemen ayağına  Ay dedeyi nal diye Tahta atın düşen nalının yerine. 2/: Tahta at...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yildizlardan-nal-caktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde Dedemin Dünyası?', 'nerde-dedemin-dunyasi-ahmet-yozgat-3ivmv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Böyle bırakmamıştı size 

Dedemin dünyası nerde? 

Göklerinde leylekler uçardı

Takla atardı nazlı güvercinler

Kuşlar havada sürüyle 

Dedemin dünyası nerde? 

Armağandı bana yaş günümde 

Dedemin yeşil dünyası nerde? 

2/:

Böyle kirli değildi çevre 

Tertemiz sular gürül gürüldü

Emmimler göçmemişti henüz şehire 

Dedemin dünyası nerde? 

Bana armağandı yaş günümde 

Dedemin mavi dünyası nerde?', '1/: Böyle bırakmamıştı size  Dedemin dünyası nerde?  Göklerinde leylekler uçardı Takla atardı nazlı güvercinler Kuşlar havada sürüyle  Dedem...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerde-dedemin-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpek Böceğim', 'i-pek-bocegim-ahmet-yozgat-45da3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Görmek istemiyor canım

Geçen yayaları kırmızı ışıkta 

Engel olamıyorsam eğer onlara 

Bir daha görmeyeceğim

Çevremi ipeklerle 

Ör ipek böceğim...

2/:

İşitmek istemiyor canım

Şehrin yüksek gürültüsünü 

Engel olamıyorsam eğer ona 

Bir daha işitmeyeceğim

Etrafımı ipeklerle 

Ör ipek     böceğim...

3/:

Solumak istemiyor canım

Kirli havasını şehrin 

Engel olamıyorsam eğer ona 

Bir daha solumayacağım

Her yanımı ipeklerle 

Ör ipek böceğim...', '1/: Görmek istemiyor canım Geçen yayaları kırmızı ışıkta  Engel olamıyorsam eğer onlara  Bir daha görmeyeceğim Çevremi ipeklerle  Ör ipek bö...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ipek-bocegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Kirlense Yakam?', 'ne-zaman-kirlense-yakam-ahmet-yozgat-s2hb7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman kirlense yakam 

Korkarım aynalardan

Ne zaman dişim kirlense

Bakarım insanların yüzüne

Ama bakamam aynalara

Ne zaman çapaklansa gözüm

Aynada görünce kendimi

Utanırım kızarır yüzüm.', 'Ne zaman kirlense yakam  Korkarım aynalardan Ne zaman dişim kirlense Bakarım insanların yüzüne Ama bakamam aynalara Ne zaman çapaklansa gözü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-zaman-kirlense-yakam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüme Dur Civcivim', 'buyume-dur-civcivim-ahmet-yozgat-di8bh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Böyle daha güzelsin 

Büyüme dur civcivim

Benim evim senin evin 

Kalırsan bu halinle

Seni avucumdan yemlerim. 

2/:

Civcivim dur büyüme 

Daha güzelsin böyle

Böyle daha iyisin 

Büyüme dur civcivim

Benim ailem senin ailen. 

3/:

Eğer devam ederse 

Bu mini minnacık halin

Seni başımda gezdiririm 

Dur bu halinle fazla büyüme 

Daha güzelsin böyle.', '1/: Böyle daha güzelsin  Büyüme dur civcivim Benim evim senin evin  Kalırsan bu halinle Seni avucumdan yemlerim.  2/: Civcivim dur büyüme  D...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buyume-dur-civcivim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Fil', 'koca-fil-ahmet-yozgat-qz728', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Hey fil amca fil amca

Kulakların yaprak yaprak

Kütük gibi bacakların

Çok kadar kocamansın

Ama ne kadar da uysalsın.

2/:

Hey fil amca fil amca

Sallarsın kulaklarını

Bir o yana bir bu yana kuyruğun

Ne kadar da uysalsın

Sen hiç kızmaz mısın? 

3/:

Hey fil amca fil amca

Salla hortumunu 

Ve bir o yana bir bu yana 

Kamçı gibi kuyruğunu 

Beni de al sırtına.

4/:

Hey fil amca fil amca 

Seni çok seviyor çocuklar

Ya sen seviyor musun onları? 

Ve ne kadar acaba?', '1/: Hey fil amca fil amca Kulakların yaprak yaprak Kütük gibi bacakların Çok kadar kocamansın Ama ne kadar da uysalsın. 2/: Hey fil amca fil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/koca-fil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemşire Abla', 'hemsire-abla-ahmet-yozgat-5p4tn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Beyaz önlüklü hemşire abla

''Sus! '' yapıyorsun herkese

Ama hep sen konuşuyorsun 

2/:

Ama nedense hemşire abla

''Sus'' yaptığını görünce

Susup kalıyorum öylece

3/:

Yalancı hemşire abla

Hiç inandırıcı değilsin bence

Susan da yiyor iğneyi 

Susmayan da koluna bir iyice...', '1/: Beyaz önlüklü hemşire abla ''Sus! '' yapıyorsun herkese Ama hep sen konuşuyorsun  2/: Ama nedense hemşire abla ''Sus'' yaptığını görünce Sus...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hemsire-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telefonun Kordonu', 'telefonun-kordonu-ahmet-yozgat-5xtpi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Evimizdeki telefonun kordonu 

Çıkar evden dışarı

Ve uzar gider ilden ile

Yok mudur bunun sonu? 

2/:

Evimizdeki telefonun kordonu 

Bağlar beni döne döne

Kuzeydeki bir kasabadaki ablama 

Güneydeki bir ildeki ağabeyime 

Bağlar beni her bir yöne.

3/:

Evimizdeki telefonun kordonu 

İşe başlayıp bizim evden

Girer ve çıkar her eve 

Selam verir o evlerde herkese.

4/:

Evimizdeki telefonun kordonu 

Kulak verir duyduğu her bir sese 

Tekrar tutar uzun yolu

Bu şehirden o şehire.', '1/: Evimizdeki telefonun kordonu  Çıkar evden dışarı Ve uzar gider ilden ile Yok mudur bunun sonu?  2/: Evimizdeki telefonun kordonu  Bağlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/telefonun-kordonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasamak icin', 'yasamak-icin-kemal-oguz-iul20', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazi insanlar yakinirlar,

Fazla kilo almaktan.

Habire yer tikinirlar,

Börek, cörek, pastadan.

Yürüyemez olurlar,

Alinan kilolarindan.

Bazende aglasirlar,

Agri ve sizilarindan.

Alisik degildirler,

Acliklarini gidermeye.

Doyana kadar yerler,

Hepsi dolar mideye.

Spor yapmaz dayatirlar,

Gezinti bile yapmazlar.

Gecerler TV. karsisina,

Kanal, kanal dolasirlar.

Findik, fistik cerezler,

Sorarsaniz hic yemezler.

Hergün ihtiyac olan suyu,

Susamazlarsa icmezler.

Günümüzün hastaligi,

Tehdit ediyor sagligi.

Biraz diet yaparsaniz,

Önlersiniz sismanligi.

Bilmenizde var fayda,

Benden Size tavsiye.

Yemek icin yasama,! 

Yasamak icin ye.!

(Filderstadt, 20 Subat 2006)', 'Bazi insanlar yakinirlar, Fazla kilo almaktan. Habire yer tikinirlar, Börek, cörek, pastadan. Yürüyemez olurlar, Alinan kilolarindan. Bazend...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yasamak-icin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakmayın Bayrakları', 'yakmayin-bayraklari-ahmet-yozgat-mcsdt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Durun! 

Çevresine öfke saçan amcalar 

Durun! 

Yakmayın o bayrakları

Bilin ki yaktığınız her bayrak 

Süsüdür rengarenk düşlerinin 

Bir minik dünyalı kardeşin.

2/:

Durun! 

Dört bir yana öfke saçan amcalar 

Durun! 

O bayrakları yakmayın

Bilin ki ateşlenen her bayrak 

Süsüdür mavi göklerinin 

Uzaklarda bir onurlu ülkenin.', '1/: Durun!  Çevresine öfke saçan amcalar  Durun!  Yakmayın o bayrakları Bilin ki yaktığınız her bayrak  Süsüdür rengarenk düşlerinin  Bir mi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yakmayin-bayraklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılı Yoklama', 'yazili-yoklama-ahmet-yozgat-tmix4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öğretmenim

Hışım gibi girip dershaneye

''Çıkartın bakayım kağıtları 

Yazılı yoklama yapacağım...'' deme

Çok korkuyorum nedense

Birisi köşeyi dönünce durdurup sana 

''Çıkar paraları...'' deyip de

Ödetse kabarık faturaları 

Korkmaz mısın doğru söyle? 

Hah işte ben de aynı öyle.', 'Öğretmenim Hışım gibi girip dershaneye ''Çıkartın bakayım kağıtları  Yazılı yoklama yapacağım...'' deme Çok korkuyorum nedense Birisi köşeyi d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yazili-yoklama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşiz Biz', 'kardesiz-biz-ahmet-yozgat-6bqec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Dünyayı idare eden 

Ya da idare ettiğini sanan 

Kocaman kafalı amcalar

Düşmanımız da olsanız

Siz bizi tutamazsınız

Yaşasın bizim küçük davamız.

2/:

Biz dünyalı çocukların 

Annesi ayrı olsa 

Ayrı olsa da babası

Yine de kardeşiz hepimiz 

Uzun sözün kısası

Yaşasın bizim küçük davamız.

3/:

Dünyayı sözde yöneten

Ya da yönettiğini sanan

Koca kafalı amcalar

Düşmanımız da olsanız

Siz bizi yenemezsiniz 

Yaşasın bizim küçük davamız.

4/:

Dünyayı sözde yöneten

Ya da yönettiğini sanan

Küçük beyinli amcalar 

Düşman olsanız da siz 

Birbirinizi de kırsanız 

Bizi yıkamazsınız

Yaşasın bizim küçük davamız.

5/:

Biz dünyalı çocuklar 

Annemiz ayrı olsa da 

Ayrı olsa da babamız

Yine de hepimiz kardeşiz 

Siz bunu böyle bilesiniz

Yaşasın bizim küçük davamız.', '1/: Dünyayı idare eden  Ya da idare ettiğini sanan  Kocaman kafalı amcalar Düşmanımız da olsanız Siz bizi tutamazsınız Yaşasın bizim küçük d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kardesiz-biz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kurbağa', 'kucuk-kurbaga-ahmet-yozgat-6s7ij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Bizim komşu küçük kurbağanın 

Patlak patlak bakar bana 

Şaşkınlık dolu gözleri.

2/:

Sürünerek yerlere 

Evimizin altında akan dere

Küçük kurbağanın evi.

3/:

Bizim komşu kurbağanın evine

Yani küçük dereciğe lağım akar

Bu duruma kızar bizimki

Patlak patlak çevreye bakar

İşte onun için şaşkındır 

Küçük kurbağanın sözleri.', '1/: Bizim komşu küçük kurbağanın  Patlak patlak bakar bana  Şaşkınlık dolu gözleri. 2/: Sürünerek yerlere  Evimizin altında akan dere Küçük ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kucuk-kurbaga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Bitişik Komşular', 'bizim-bitisik-komsular-ahmet-yozgat-98pwt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Duvarı bitişik komşularımız 

Nerede görseler beni

Meyve yüklü bahçelerinden

Kırmızı elma ya da olgun armut

Veya kiraz koparıp

Verirler hediyemi.

2/:

Annem mutfakta çorba pişirir

Tencereye kokulu nane eker

Duvarı bitişik komşular 

Alır kokusunu nane kokulu çorbanın

Sanırım canları çeker.

3/:

Bende davranırım hemen

''Bana ne bana ne.'' demeden

Nane kokulu çorbadan 

Duvarı bitişik komşulara 

Dağıtırım teker teker.', '1/: Duvarı bitişik komşularımız  Nerede görseler beni Meyve yüklü bahçelerinden Kırmızı elma ya da olgun armut Veya kiraz koparıp Verirler h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bizim-bitisik-komsular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sümüklü Böcek', 'sumuklu-bocek-ahmet-yozgat-57gev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sümüklü böcek kardeş 

Al benim mendilimi

Haydi haydi utanma

Akan burnunu silersin

Eğer mendil kullanmazsan

Ceketinin kolunu pislersin

Dinle beni yabana atma sözümü 

Utanma sümüklü kardeş

Uzat o minnacık elini 

Al haydi benim kağıt mendilimi.', 'Sümüklü böcek kardeş  Al benim mendilimi Haydi haydi utanma Akan burnunu silersin Eğer mendil kullanmazsan Ceketinin kolunu pislersin Dinle ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sumuklu-bocek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılay''a Teşekkür', 'kizilay-a-tesekkur-ahmet-yozgat-jbzyj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bir gece saat üçte ansızın 

Hızla salladı her yanı deprem 

Yıkıldı gitti o güzel evim

Çok geçmedi, çat kapı:

''Kimdir o bayım? '' 

''Ben kızılay''ım.''

2/:

Bir gece saat beşte 

Azgın seller yürüdü üstümüze

Sürüdü indirdi bizim köyü denize

Çok geçmedi, çat kapı:

''Kimdir o bayım? '' 

''Ben kızılay''ım.''

3/:

Bir gece saat onda ateş uçuştu 

Birbirine bitişik evler tutuştu

Çok geçmedi, çat kapı:

''Kimdir o bayım? '' 

''Ben kızılay''ım...''', '1/: Bir gece saat üçte ansızın  Hızla salladı her yanı deprem  Yıkıldı gitti o güzel evim Çok geçmedi, çat kapı: ''Kimdir o bayım? ''  ''Ben kı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kizilay-a-tesekkur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemin Günü', 'annemin-gunu-ahmet-yozgat-md4bw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Benim güzel anneme 

Cimri amcalar

Koskocaman bir yılda

Tek gün ayırmışlar.

2/:

Siz o tek günü 

Kendi annenize verin

Benim anneme yetmez 

Bütün günleri senenin.', '1/: Benim güzel anneme  Cimri amcalar Koskocaman bir yılda Tek gün ayırmışlar. 2/: Siz o tek günü  Kendi annenize verin Benim anneme yetmez ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/annemin-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktor Amca', 'doktor-amca-ahmet-yozgat-6u4k3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doktor amca büyüdüm artık ben

Bak başladım okula da 

Her geldiğimde sana

''A'' dedirme

Biz ''a'' yi çoktan geçtik

Biliyorum ''b'' yi de 

Bırak ''a'' ile ''be''yi

Bana söylet biraz da 

''Ce''den sonraki harfleri.', 'Doktor amca büyüdüm artık ben Bak başladım okula da  Her geldiğimde sana ''A'' dedirme Biz ''a'' yi çoktan geçtik Biliyorum ''b'' yi de  Bırak ''a''...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/doktor-amca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aileler Arası Meydan Savaşı', 'aileler-arasi-meydan-savasi-ahmet-yozgat-p2k5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Var ya

Benim aslan babam

Döver senin cılız babanı

Demirden yumruklarıyla.

Yaa! 

Bir daha dalaşma bana

Babama derim seni sonra haa! 

2/:

Var ya

Aslan annem benim

Döver senin zayıf anneni

Sipsivri topuklarıyla.

Yaa! 

Bir daha dalaşma bana

Anneme derim seni haa! 

3/:

Var ya

Benim aslan ağabeylerim

Döver seninkileri

Kendi güçlü çeteleriyle.

Yaa! 

Bir daha sakın dalaşma bana

Ağabeylerime derim seni haa!', '1/: Var ya Benim aslan babam Döver senin cılız babanı Demirden yumruklarıyla. Yaa!  Bir daha dalaşma bana Babama derim seni sonra haa!  2/: ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aileler-arasi-meydan-savasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılbaşı Sevinci', 'yilbasi-sevinci-ahmet-yozgat-h7uyg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yılbaşındaki sevinç 

Çıktı eski yıl diye mi? 

Yoksa yeni yıl girdi diye mi? 

Yılbaşındaki kutlama

Son masraf mı eski yıldan? 

Yoksa yeni yıldan hediye mi? 

Doğrusu anlamıyorum hiç 

Nedir yılbaşındaki sevinç?', 'Yılbaşındaki sevinç  Çıktı eski yıl diye mi?  Yoksa yeni yıl girdi diye mi?  Yılbaşındaki kutlama Son masraf mı eski yıldan?  Yoksa yeni yıl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yilbasi-sevinci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar Benim', 'sokaklar-benim-ahmet-yozgat-5n7vf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Olunca bu günde akşam

Alın sizin olsun

Kocaman apartmanlar

Sizin olsun o sıcacık odalar

Yalnızca ıssız sokaklar benim.

2/:

Olunca bu günde akşam 

Alın sizin olsun 

Nazlı çocuklarına 

Hediye taşıyan babalar

Sizin olsun o sıcacık çorbalar

Yalnızca soğuk sokaklar benim.

3/:

Olunca bu günde akşam

Alın sizin olsun

Sevgi dolu bütün dünyalar

Ben mi kimim? 

Ben sokak çocuğuyum

Yalnızca karanlık sokaklar benim.', '1/: Olunca bu günde akşam Alın sizin olsun Kocaman apartmanlar Sizin olsun o sıcacık odalar Yalnızca ıssız sokaklar benim. 2/: Olunca bu gün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sokaklar-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otobüs Yolculuğu', 'otobus-yolculugu-ahmet-yozgat-f97pg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Severim arkada oturmayı sınıfta

Ama en önde oturmaya 

Bayılırım minibüste.

2/:

Nedense cam kenarı

Tam bana göre 

Eğer otobüste isem.

3/:

Ama okulda bunun tam tersi

İtibar etmem en öne

Orta sıra keyfime göre.', '1/: Severim arkada oturmayı sınıfta Ama en önde oturmaya  Bayılırım minibüste. 2/: Nedense cam kenarı Tam bana göre  Eğer otobüste isem. 3/:...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/otobus-yolculugu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekçe', 'dilekce-recep-uslu-uaqvw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereye nasıl verilir

Dilekçe

Bilemiyorum

Ben insanlıktan

İstifa ediyorum

Gözünün içine baka baka

Yalan söyleniyor

Üzülüyorum

Yetimi öksüzü bırak

Tüm insanların

Hakkı yeniliyor

Sessiz kalıyorum

Sevgi kalkmış gönüllerden

İnanç kalmamış

Kim daha çok dolandırdı

Milletle birlikte gülüyorum

Ben insanlıktan

İstifa ediyorum

24.06.1996', 'Nereye nasıl verilir Dilekçe Bilemiyorum Ben insanlıktan İstifa ediyorum Gözünün içine baka baka Yalan söyleniyor Üzülüyorum Yetimi öksüzü b...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dilekce-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pet Çevreye Hücum', 'pet-cevreye-hucum-ahmet-yozgat-5diql', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ben bir pet şişeyim 

Az önce içti bir afacan içimi

Yani bu andan sonra bomboşum

Ben şimdi özgürüm yani başıboşum

Yaşasın tüm pet şişeler

Yaşasın petten çevre.

2/:

Ben bir pet şişeyim 

Yalnız ve tek başıma

Hiç korkmuyorum şehirde

Çünkü yalnız değilim

Ve değilim bir başıma

Yaşasın tüm pet şişeler

Yaşasın petten çevre.

3/:

Ben bir pet şişeyim 

Sabırsızlıkla doluşmak için 

Bekliyor hemcinslerim

Geniş caddelere 

Kocaman denizlere

Ve aklınıza gelen her yere 

Az değiliz sayımız on binlerce

Yaşasın tüm pet şişeler

Yaşasın petten çevre.', '1/: Ben bir pet şişeyim  Az önce içti bir afacan içimi Yani bu andan sonra bomboşum Ben şimdi özgürüm yani başıboşum Yaşasın tüm pet şişeler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/pet-cevreye-hucum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramın Bayramı', 'bayramin-bayrami-ahmet-yozgat-nf19r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Bazen bayraklarla gelirim

Bazen torba torba şekerle

Çocukları sevindiririm

Kurduğum rüzgarlı salıncaklarla 

Döndürdüğüm koca koca dolaplarla

Çarpışan zararsız otolarım 

Eğer umutlandırırsa onları

Gönenirim ben de 

Sararım sarmalarım 

Dünyadaki bütün çocukları

2/:

Bazen kurbanlarla gelirim

Bazen davul zurnalarla

Kurduğum uçarı kaydıraklarla 

Döndürdüğüm koca koca dolaplarla

Koşuşan zararsız otolarım 

Eğer mutlandırırsa onları

Gönenirim ben de 

Sevindiririm bütün çocukları.', '1/: Bazen bayraklarla gelirim Bazen torba torba şekerle Çocukları sevindiririm Kurduğum rüzgarlı salıncaklarla  Döndürdüğüm koca koca dolapl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bayramin-bayrami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehir Güle Güle', 'nehir-gule-gule-ahmet-yozgat-iqiu6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Uzaklardan kıvrıla kıvrıla gelip 

Geçip evimizin alt yanından 

Kıyısında evirip önümü 

Öpüp ıslak ıslak elimi 

Giden nehir güle güle.

1/A:

Kıvrılarak dolanarak 

Kasaba kasaba gezinip

Savrularak şehir şehir

Güle güle giden nehir.

2/:

Bereket taşı her yere

Uğradığın şehirlere 

Herkese selam söyle benden 

Giden nehir güle güle.

2/A:

Durulup bulanarak 

Kasaba kasaba atlayarak 

Uğrayarak şehir şehir

Güle güle giden nehir.', '1/: Uzaklardan kıvrıla kıvrıla gelip  Geçip evimizin alt yanından  Kıyısında evirip önümü  Öpüp ıslak ıslak elimi  Giden nehir güle güle. 1/...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nehir-gule-gule-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tembel Karınca', 'tembel-karinca-ahmet-yozgat-tv8fw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Karıncalar obasında

Belki de ilk defa çıktı

Böyle bir tembel karınca

Oba halkı çalıştıkça 

O uzandı sırt üstü yattı.

2/:

Geldi yemek saati

Bizim tembel karınca

Kurulunca baş köşeye

Bir şey gelmedi önüne

Tembel karınca anladı 

Sonunda ettiği hatayı 

Başı düştü önüne.', '1/: Karıncalar obasında Belki de ilk defa çıktı Böyle bir tembel karınca Oba halkı çalıştıkça  O uzandı sırt üstü yattı. 2/: Geldi yemek saa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tembel-karinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenciler', 'dilenciler-ahmet-yozgat-hs7b8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Bizim sokaktaki dilenciler 

Asıp bir elini havaya 

Bütün gün dilenirler.

2/:

Bizim sokaktaki dilenciler

''Bir ekmek parası ağabey''den başka

Bir tek söz bilmezler nedense? 

3/:

Bizim sokaktaki dilenciler 

Bin ekmek parası alsalar 

Yine de bir ekmek parası isterler.

4/:

Bizim sokaktaki dilenciler

''Bir ekmek parası ağabey''den başka

Bir tek söz söylemezler nedense?', '1/: Bizim sokaktaki dilenciler  Asıp bir elini havaya  Bütün gün dilenirler. 2/: Bizim sokaktaki dilenciler ''Bir ekmek parası ağabey''den baş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dilenciler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Plastik Deniz', 'plastik-deniz-ahmet-yozgat-9edv7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz yeşil dostu

Mini minnacık çevrecileriz

İstemeyiz katiyen plastik deniz

Her aldığı şeyi ne olur? 

Denizlere atmasın elleriniz

Balıklar yüzsün mavi sularda

Yüzmesin ne olur? 

Başıboş pet şişeleriniz

Biz yeşil dostu

Minik çevrecileriz

Hiç ama hiç istemeyiz

Kirlenmesin tertemiz çevremiz.', 'Biz yeşil dostu Mini minnacık çevrecileriz İstemeyiz katiyen plastik deniz Her aldığı şeyi ne olur?  Denizlere atmasın elleriniz Balıklar yü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/plastik-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanadı Kırık Leylekler', 'kanadi-kirik-leylekler-ahmet-yozgat-x7mhu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizim göçebe leylekler göçecekler 

Bu kışın da sıcacık ülkelere

Yazın köyümüze geri gelecekler

Ama bizim kırık kanatlı 

Ya da kırık bacaklı leylekle 

Bu kış nasıl edecekler? 

Katılamayacaklar her yılki göçe 

Arkada kalacaklar onlar 

Herkes güneydeki diyarlara gidince 

Bu durumundan çok hüzünlenecekler

Yazın kendilerinin olan

Kara bacalardaki mutlu yuvalarını

Kışın gurbet el bilecekler

Belki de ayrılığa dayanamayacaklar

Bizim zavallı kırık leylekler 

Belki de kendilerine kıyacaklar.', 'Bizim göçebe leylekler göçecekler  Bu kışın da sıcacık ülkelere Yazın köyümüze geri gelecekler Ama bizim kırık kanatlı  Ya da kırık bacaklı ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kanadi-kirik-leylekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şoför Mahmut Ağabey', 'sofor-mahmut-agabey-ahmet-yozgat-mmjau', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Şoför Mahmut ağabeysiyim 

Okul yolunda bütün öğrencilerin

Bizim emektar minibüse 

Yolları yetmez semtlerin

Silinir gözümde her şey

Geçince ben direksiyona

2/:

Dedim ya şoför Mahmut ağabeysiyim 

Okul yolunda bütün öğrencilerin

Uçururum düldülü yokuşta ve düzde

Gideceğimiz yere en hızlı ben ulaşırım

Ne zaman bir okul önünde gidecek olsam

Yavaşlar ve anında kaplumbağalaşırım

Onun için şoför Mahmut ağabeysiyim 

Dikkatli, dikkatsiz tüm öğrencilerin.', '1/: Şoför Mahmut ağabeysiyim  Okul yolunda bütün öğrencilerin Bizim emektar minibüse  Yolları yetmez semtlerin Silinir gözümde her şey Geçin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sofor-mahmut-agabey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orta Meydan', 'orta-meydan-ahmet-yozgat-0jfsh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Adresim şehrin ortası 

Tüm yollar bana çıkar

Ya da benim anası geniş yolların

Çiçeklerle süslü bir alanım.

2/:

Adresim şehrin ortası 

Çevrelediği beton duvarların 

Fıskiyeli bir havuza sahibim.

3/:

Adresim şehrin ortası 

Konup kalktığı ve sulandığı yerim 

İnsanlara alışkın cesur kuşların

Sayın ki ziyaret yeriyim 

Kentteki bütün insanların.

4/:

Adresim şehrin ortası

Bilirim kimdir gezinen üstümde

Tanır beni insanların ayakkabısı.', '1/: Adresim şehrin ortası  Tüm yollar bana çıkar Ya da benim anası geniş yolların Çiçeklerle süslü bir alanım. 2/: Adresim şehrin ortası  Çe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/orta-meydan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozuk Musluk', 'bozuk-musluk-ahmet-yozgat-wmdcg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oğlunuz ya da kızınız

Veya kendiniz nezle olsanız

Koşmak olur bilirim hastaneye işiniz

Sayın ki biz de nezleyiz

Gün boyu damlıyoruz 

Ve akarak giriyoruz koca geceye

Bizi neden 

Bir tamirciye götürmezsiniz?', 'Oğlunuz ya da kızınız Veya kendiniz nezle olsanız Koşmak olur bilirim hastaneye işiniz Sayın ki biz de nezleyiz Gün boyu damlıyoruz  Ve akar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bozuk-musluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otobüs Durağı', 'otobus-duragi-ahmet-yozgat-uw1v6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ben kırmızı boyalı bir otobüs durağıyım 

Teker teker durur önümde otobüsler 

Altımda yolcular durur

Islanan üstleri yağmurda 

İnsanların altımda kurur

2/:

Ben kırmızı boyalı bir otobüs durağıyım 

Güvercin kuşları konar tepeme

Eteğime kediler sürünür

Karda kalan yolcular

Üzerlerine beni bürünür. 

3/:

Ben kırmızı boyalı bir otobüs durağıyım 

Kısmet kısmet üstüne

''Seni seviyorum.'' yazıp iki afacan

Ellerindeki sivri çiviyle boyalı bedenime

Özlem mesajı kazırlar sevdiklerine

Bense alınırım üzerime

''Seviyorlar beni.'' diye 

Sevinirim kendi kendime.', '1/: Ben kırmızı boyalı bir otobüs durağıyım  Teker teker durur önümde otobüsler  Altımda yolcular durur Islanan üstleri yağmurda  İnsanların...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/otobus-duragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söndür Beni', 'sondur-beni-ahmet-yozgat-metsw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İtfaiyeci amca 

İşte ben ateşim

Ne olur söndür beni

Bakma böyle harlı harlı yandığıma 

Aslında yakmak istemiyorum ben de

İnan ki hiç kimseleri

İstemem ağlamasın çocuklar

Anneler, babalar üzülmesin

İster miyim hiç ocaklar sönsün? 

İtfaiyeci amca 

Bunlar için söndür beni 

Yakmak istemiyorum ben de hiç kimseyi.', 'İtfaiyeci amca  İşte ben ateşim Ne olur söndür beni Bakma böyle harlı harlı yandığıma  Aslında yakmak istemiyorum ben de İnan ki hiç kimsele...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sondur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozmayın Yuvamı', 'bozmayin-yuvami-ahmet-yozgat-yui7v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Ben bir evsiz kuşum 

Günlerce yollardayım 

Ve günlerce aç susuz uçmuşum.

2/:

Ben bir evsiz kuşum 

Unutulmuş bir şehrin 

Yetim bir sokağında 

Eski bir direk bulmuşum.

3/:

Ben bir evsiz kuşum 

Çalışıp çabalamış

Yetim sokaktaki direğe

Yuvamı kondurmuşum.

4/:

Ben bir evsiz kuşum 

Çocuklar bozmayın yuvamı

Ben bir öksüz kuşum 

Sizinle komşu olmuşum.', '1/: Ben bir evsiz kuşum  Günlerce yollardayım  Ve günlerce aç susuz uçmuşum. 2/: Ben bir evsiz kuşum  Unutulmuş bir şehrin  Yetim bir sokağı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bozmayin-yuvami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döne Döne Yan Yunus', 'done-done-yan-yunus-yusuf-onder-bahceci-td5ct', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey Koca Yunus, Taptuk Emre Dergahından,

Dergahından eğri odunu geçirmeyen ol mürit,

Dergaha kimbilir ne hayallerle geldin bir ümit,

Dergahta kapılandın, horlandın, denilmişti git,

Gitmedin, yitmedin, sen kâlbini gerçek verdin,

Hey Koca Yunus, Taptuk Emre Dergâhından,

Geçer mi zannederdin, Şeyhin Müritlerinden,

Hak Çalabım, Hak Çalabım derdin, söylerdin,

Dertli Dolap neden inilersin, derdin ne derdin,

Taptuk Emre Dergahında ağlayuben gezerdin,

Hey Koca Yunus, Taptuk Emre Dergahından,

Bizim Yunus''mu denilen hep gönüllere girilen,

Deyişleri dilden dile söylenen fazlaca sevilen,

Hey Koca Yunus Taptuk Emre Dergâhından,

Taptuğun tapusunda, kul olanlardı kapısında,

Gönül Allah''ın yapısında, hep gönüllere girdin,

Bir kez gönül yıktın ise bu kıldığın namaz değil,

Dedin dedin seven gönüllere işte böyle girdin,

Hey Koca Yunus, hey Miskin Yunus, Cân Yunus,

Gönüllerin dergahında döne, döne yan Yunus....', 'Hey Koca Yunus, Taptuk Emre Dergahından, Dergahından eğri odunu geçirmeyen ol mürit, Dergaha kimbilir ne hayallerle geldin bir ümit, Dergaht...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/done-done-yan-yunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım Küçük Söğüt', 'arkadasim-kucuk-sogut-ahmet-yozgat-alxrd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani arkadaştık seninle 

Yardım edecektik hani 

Dar günde birbirimize

Ben sulayacaktım seni

Toprağını gübreleyip

Budayacaktım uzayan dallarını

Sen de yağmurda karda

Beni koruyacaktın

Yaptım görevlerimi ben

Ama ya sen? 

Yıldırım çektin üstüne 

Ben altına sığınmışken.', 'Hani arkadaştık seninle  Yardım edecektik hani  Dar günde birbirimize Ben sulayacaktım seni Toprağını gübreleyip Budayacaktım uzayan dalları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arkadasim-kucuk-sogut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Söğüt Ağacım', 'kucuk-sogut-agacim-ahmet-yozgat-hyihl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani arkadaştık seninle 

Yardım edecektik hani 

Dar günde birbirimize

Ben sulayacaktım seni

Toprağını gübreleyip

Budayacaktım uzayan dallarını

Sen de yağmurda karda

Beni koruyacaktın

Yaptım görevlerimi ben

Ama ya sen? 

Yıldırım çektin üstüne 

Ben altına sığınmışken.', 'Hani arkadaştık seninle  Yardım edecektik hani  Dar günde birbirimize Ben sulayacaktım seni Toprağını gübreleyip Budayacaktım uzayan dalları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kucuk-sogut-agacim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezgin Domates', 'gezgin-domates-ahmet-yozgat-0wefl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tarlaların nemli koynundan 

Patladım çıktım dünya yüzüne 

Böyle bir ilkbahar sabahı

Ayşe gördü ilk önce beni

Ahmet sevindi 

Mahmut çırptı elini beni görünce

Yeşile boyadım 

Dünyayı önce 

Kızardım sonra

Bir haziran sabahı 

Yüklendim kamyonlara

Çarşılara düştü yolum 

Pazarları gördüm göz ucuyla 

Tezgahlarda mıncıklandı bedenim 

Kantarlar tarttı

Dolduruldum kocaman sepetlere

Derken ulaştım bir gün 

Salata olmak için evlere', 'Tarlaların nemli koynundan  Patladım çıktım dünya yüzüne  Böyle bir ilkbahar sabahı Ayşe gördü ilk önce beni Ahmet sevindi  Mahmut çırptı el...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gezgin-domates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanımış Sevdiğim', 'yalanimis-sevdigim-tayyip-sag-4d74g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimden akan yaşlar sel oldu,

Bir yar sevdim şimdi bana el oldu,

Dağlar gibi sevdamıza ne oldu,

Demek hepsi yalanımış sevdiğim.

Kaybolan yıllarım gitti boşuna,

Ateş düştü yüreğimin başına,

Gönlüm dargın çıkma sakın karşıma,

Demek hepsi yalanımış sevdiğim.

Ben Leyla''mı yüreğimde aradım,

Mecnun gibi çıkıp çöle sormadım,

Ziyan olmuş ömrü, ömür saymadım,

Demek hepsi yalanımış sevdiğim.

               23.12.2005

  Unutma; Mezarda yatan insanlara ölü demek doğru değildir.Onlar

Dünyasını değiştirmiş insanlardır.

   Gerçek ölüler, bu Dünya''da varlığı hissedilmeyen, hayattan kopmuş, mücadele gücü kaybolmuş ve yaşam savaşı yapamayan insanlardır.

                            6.1.2006', 'Gözlerimden akan yaşlar sel oldu, Bir yar sevdim şimdi bana el oldu, Dağlar gibi sevdamıza ne oldu, Demek hepsi yalanımış sevdiğim. Kaybolan...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalanimis-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Ayrı Babam Ayrı', 'annem-ayri-babam-ayri-ahmet-yozgat-nzfwn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babam bir ucunda oturur bu şehrin 

Annemse oturur diğer ucunda

Ben kalmışım arada

Bir gün babama koşarım 

Anneme koşarım ertesi gün 

Özlem dolu yüreğim avucumda

Sevgili anneme kavuştuğumda 

Ayrılırım özlediğim babamdan

Sevinç ve üzüntüyü

Aynı anda yaşarım

Atamam hiç bir zaman 

Kafamdan ayrılığın hüznünü

Hasretle beklerim 

Hep birleşeceğimiz günü.', 'Babam bir ucunda oturur bu şehrin  Annemse oturur diğer ucunda Ben kalmışım arada Bir gün babama koşarım  Anneme koşarım ertesi gün  Özlem d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/annem-ayri-babam-ayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluyum', 'mutluyum-tahmine-yildirim-bpbd1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutlu olmak okadar kolayki aslında

Seni mutlu eden birileri varsa yanında

Çok şükür bu arlar bunlar benim yakınımda

Mutluyum ben bu gün bu güzel akşamda

İçimdeki o coşku havalandı gidiyor

İfade edemiyeceğim duygular bedenimi sarıyor

Böyle olunca mutluluk kendiliğinden geliyor

Özel bir bir çaba harcamak gerekmiyor

Ne varki sanki her gün böyle olsam

Keşke hiç mutsuz olmak zorunda kalmasam

Her gün çok hızlı koşan o mutluluğu yakalasam

Yanımı yöremi hep mutluluklarla donatsam

Yo yo karar verdim artık hep böyle olmaya

Kendimi kendimin üzmesine izin yok artık asla

Herkes beni delirmişim bile sansa

Ben bunu başarabilmeyi başaracağım pekala.

                                                                                 EKİM

                                                                         2005', 'Mutlu olmak okadar kolayki aslında Seni mutlu eden birileri varsa yanında Çok şükür bu arlar bunlar benim yakınımda Mutluyum ben bu gün bu g...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mutluyum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurbağanın Bacağı', 'kurbaganin-bacagi-ahmet-yozgat-6xc1e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir yeşil kurbağayım 

Bu da arka bacağım

Göstermek için size

Elektriği

Kasım kasım kasılacağım

Neye yarar kasıldığımı görmek? 

Beni öldürmenizi 

Hiç bir zaman anlamayacağım.', 'Ben bir yeşil kurbağayım  Bu da arka bacağım Göstermek için size Elektriği Kasım kasım kasılacağım Neye yarar kasıldığımı görmek?  Beni öldü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kurbaganin-bacagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saz heyeti', 'saz-heyeti-aysenur-yazici-zt4wa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'boyuna uygun bir çukur kazdılar

derinliği iki metre

...uzunluğu boyu gibi...

ittiler içine bedenini boylu boyunca

sendeledi, ama vazgeçmedi...

..''gerek yok''  dedi,

...''ben kendim inerim...! 

inerim de, yatarım da

ben kendimi bilirim''...

dik durabildiğim gibi,dik de ölebilirim...

kürek kürek toprak attılar

ağzında birikti ilk,toprağın tadı..

saz heyetini koydular başucuna

...onlar çaldılar

...sevmeyenler oynadı...

sevmeyenlerdeydi bereketi...

dişlerinin arasında 

gıcırdarken kumun tadı

O sadece sustu ve ölümü bekledi...

bekleyecek başka ne kalmıştı ki

.... ''şartınız bu ise ölümü de severim''....dedi

gök mavisi kapandı önce gözünde

taze toprak kokusu kekrek güzelliğiyle

burun deliklerine doldu

...büyümemiş fidanların tohumları,

...çim taneleri,kuru yapraklar

...böcek yumurtaları, sigara izmaritleri

...kuş pislikleri...

teninde dondular

derin bir son nefes aldı

hayat bir anda durdu! 

sonra, sevdikleri geçti kara bir perdenin önünden

acele acele

ecele ecele

gözyaşı düşmedi...

biri geldi akşam mezarına işedi...

tükürdü bir sonraki gün,..öylesine geçerken

boşuna sevaplarının ödülünü bekledi

ya da iyilik sandığı şeylerin

son anda kurtaracağını onu aşk acısından...

bu kara kutunun solucanları 

koltukaltlarından yemeye başlamadan

son bir mucize 

olur ya...bekledi

...gelmedi! 

örttüler onu.

sesini kesti....

uzun uzun nem çekti saçları çukurdan

kırmızı yosunlar gibi serildiler ıslak...

içi titredi....

umutlarını hatırlayarak

yadigâr ne varsa kucaklayarak...

derinden bir saz sesi sızdı toprağın içine

kulakları ölmemişti! ! 

yaylı tambur acı bir su gibi akıyordu üzerine

klarnetin içli hıçkırıkları,

ve kanundan yükselen sızı

...''geber'' diyordu

geber namussuzun kızı! ...

insanları mutsuz eden, kifayetsiz....

defettiler her şeyin belası kızı

...defederek  defnettiler...

bu hayat hırsızını, arlanmaz uslanmazı...

herşey kurtuldu! 

dünyada açlar doydu

vatan hainleri bir bir tövbekâr oldu

aşıklar kavuştu,

hasta bebeler iyileşti

şehitler huzur buldu

insanlar olmayan vicdanlarını buldu...

...kimbilir kaç insanın hayatı yoluna girdi...

pis olan tek şey temizlendi...

asrî mezarlıktaki en taze bedendi...

bugünlük...

kırmızı böceklerin bayramı...

saz heyetinden şevk almış

ete saldırıyorlardı...

...toprağın iştahı kabarmış

ah..bak yarın gelecek olanların

yeri de ayrıltılmış! 

kusurlu isen yok ol

...ki her şey temizlensin...

ki...hayattan keyif almak için bekleyenler

yokluğunla yeniden bedenlensin....

aldığın nefesin yarısını sevdiğine vermeyi bil

ki...günah temizlensin....

cehennemin dibi

   15:27

Tarabya

Andrea and', 'boyuna uygun bir çukur kazdılar derinliği iki metre ...uzunluğu boyu gibi... ittiler içine bedenini boylu boyunca sendeledi, ama vazgeçmedi....', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/saz-heyeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal Arısı İle Eşek Arısı', 'bal-arisi-i-le-esek-arisi-ahmet-yozgat-fb535', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Balarısı çiçek arar 

Eşek arısı pislik

Balarısı güle konar 

Gübreye eşek arısı

Balarısı bal yapar 

Eşek arısı çalar

Balarısı benzer 

Komşumuz Basri ağabeye

Eşek arısı ise

Diğer komşumuz Avni''ye.', 'Balarısı çiçek arar  Eşek arısı pislik Balarısı güle konar  Gübreye eşek arısı Balarısı bal yapar  Eşek arısı çalar Balarısı benzer  Komşumu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bal-arisi-ile-esek-arisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımda Park', 'kaldirimda-park-ahmet-yozgat-row1n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözüm size değil 

Otoparktaki otolar

Ne demeliyim bilmem? 

Kaldırımı kapatan 

İşgalci otolara

Orası değildir oto kaldırımı

Hiç de değil sizin için

Ben yayayım terk edin derhal 

Benim kaldırımımı 

Kendi yerinize geçin.', 'Sözüm size değil  Otoparktaki otolar Ne demeliyim bilmem?  Kaldırımı kapatan  İşgalci otolara Orası değildir oto kaldırımı Hiç de değil sizi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kaldirimda-park-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asılmayın Arkamdan', 'asilmayin-arkamdan-ahmet-yozgat-x321u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Mahalleli bir yaramaz

Ne zaman geçsem oradan

Duramaz oturamaz

Asılır arkadan.

2/:

Mahalleli bir yaramaz 

Ne zaman geçse oradan

Bir traktör ya da bir kamyon

Asılır arkasından.', '1/: Mahalleli bir yaramaz Ne zaman geçsem oradan Duramaz oturamaz Asılır arkadan. 2/: Mahalleli bir yaramaz  Ne zaman geçse oradan Bir trakt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/asilmayin-arkamdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Sövenler', 'gunese-sovenler-zeynal-yaman-94s5h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya Râb! Öyle bir fitne asrında yaşıyoruz ki her şey perişan

Güneşe ''karanlık'' diye söverlerken bile her taraf ürüşan

Sorun, yarasaların kendi zindanını aydınlık sanmasında

Demek ki ışığa düşman oluyor bir kez karanlğa alışan', 'Ya Râb! Öyle bir fitne asrında yaşıyoruz ki her şey perişan Güneşe ''karanlık'' diye söverlerken bile her taraf ürüşan Sorun, yarasaların kend...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gunese-sovenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut Kondu', 'bulut-kondu-ahmet-yozgat-017mi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Dün yıkılan gecekondumuzu 

Bu gün şu buluta kondursam 

Yine yıkarlar mı acaba? 

En yükseği bile yıkan 

Buldozerle amcalar...

2/:

Dün yıkılan gecekondumuzu 

Bu gün ay dedeye kondursam 

En yükseğe bile çıkan

O buldozerli amcalar 

Ay dedeye çıkamazlar.

3/:

Dün yıkılan gecekondumuzu

Bu gün bu buluta kondursam 

Işık takarlar mı acaba? 

En yükseğe bile takan 

Elektrikçi amcalar...

4/:

Dün yıkılan gecekondumuzu 

Bu gün ay dedeye kondursam 

Elektrikçi amcalar 

Takmazlarsa takmasınlar.

5/:

Dün yıkılan gecekondumuzu 

Bu gün o buluta kondursam

Merdiven kurarlar mı acaba? 

En yükseğe bile ulaşan 

Marangoz amcalar...

6/:

Dün yıkılan gecekondumuzu 

Bu gün ay dedeye kondursam 

İyiliksever amcalar 

Bizi burada unutmasınlar.', '1/: Dün yıkılan gecekondumuzu  Bu gün şu buluta kondursam  Yine yıkarlar mı acaba?  En yükseği bile yıkan  Buldozerle amcalar... 2/: Dün yık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bulut-kondu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Matematik', 'sevgilim-matematik-ahmet-yozgat-trbfa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Yaşım kaç sen söylersin 

Kilomun kilogramı senden sorulur 

Boyumun metresini ve santimini 

Söylersin bir çırpıda tik tik tik

Sen her şeyi bilirsin 

Sevgili matematik.

2/:

Kaç lira babamın maaşı? 

Annemin cüzdanında kaç para var? 

Alacağımız kaç para? 

Bakkala borcumuz ne kadar? 

Söylersin bir çırpıda tik tik tik

Sen her şeyi bilirsin 

Sevgili matematik.

3/:

Uzunluğu yolların ne kadar kilometre? 

Kaç metre apartmanların boyu? 

Sınıfımızın eni kaç kulaç? 

Söylersin bir çırpıda tik tik tik 

Sen her şeyi bilirsin 

Sevgili matematik.

4/:

Odada yanan ışık kaç kilovat? 

Uçan kuşun hızı

Dükkanda alış veriş yapan kızı

Vereceğimizi, alacağımızı

Söylersin bir çırpıda tik tik tik

Sen her şeyi bilirsin 

Sevgili matematik.

5/:

Pazarda değiş tokuş yapan tüccarlar

Yalnızca sana baş vururlar

Çocukların haftalık harçlığını

Sana düşer ince ince hesaplamak 

Derslerden aldığı notu öğrencilerin

Söylersin bir çırpıda tik tik tik 

Sen her şeyi bilirsin 

Sevgili matematik.', '1/: Yaşım kaç sen söylersin  Kilomun kilogramı senden sorulur  Boyumun metresini ve santimini  Söylersin bir çırpıda tik tik tik Sen her şey...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevgilim-matematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Problemler Haber Verdi', 'problemler-haber-verdi-ahmet-yozgat-te9p3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Kuytu bir yerde bir sütçü

İki litre sütüne

Bir litre su katarsa...

Problemler haber verdi

Duyunca bunu çocuk: 

''Sütçü amca dur su katma 

İçeceğim saf sütüme.'' dedi

Hatayı engelledi.

2/:

Kuytu bir yerde bir depo

Dolup tek musluktan 

Yüz litre bir saatte 

Boşaltırsa diğer vanadan...

Problemler haber verdi

Duyunca bunu çocuk:

''Bir musluktan doldurup 

İkincisinden boşaltma 

Dur sucu amca terkosu.'' dedi

Yanlışlığı önledi.', '1/: Kuytu bir yerde bir sütçü İki litre sütüne Bir litre su katarsa... Problemler haber verdi Duyunca bunu çocuk:  ''Sütçü amca dur su katma ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/problemler-haber-verdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sel Aldı Toprağımı', 'sel-aldi-topragimi-ahmet-yozgat-c318d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ben verimli bir tarlaydım 

Şu karşı ki yamaçta

Kenarımda karaağaçlar vardı

Akasyalar boy atardı

Humus topraklı orta yerimde

Çıkageldiler her sonbaharda 

Yeni bileylenmiş keskin baltalar

Ne karaağaçlar kaldı çevremde

Ne de güzelim akasyalar.

2/:

Ben verimli bir tarlaydım 

Şu karşı ki yamaçta

Kenarımdaki yeşil yemişler 

Ve salkımlı akasyalar

Birer birer devrildiler

Bayram etti acımasız baltalar

Çevremdeki son ağaç kesilince 

Sel geldi üstteki tepelerden 

Sıyırdı bütün toprağımı 

Unuttum geride kalan 

Verimli ve yeşil çağlarımı.', '1/: Ben verimli bir tarlaydım  Şu karşı ki yamaçta Kenarımda karaağaçlar vardı Akasyalar boy atardı Humus topraklı orta yerimde Çıkageldiler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sel-aldi-topragimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Çalınmazdı Klakson', 'hani-calinmazdi-klakson-ahmet-yozgat-jx998', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Şoför amcalar durun! 

''Vank vank! ''

Öyle ne yaptınız? 

Bastınız düğmemize bizleri bağırttınız

Bakın karşınızda bir uyarı levhası

Diyor ki: ''Burada çalınmaz korna.''

Bu işareti eğer dikkate almaz iseniz 

Bak polis amca şu kenarda 

Aralıksız ceza kesiyor size.

2/:

Şoför amcalar durun! 

''Vank vank! ''

Öyle ne yaptınız? 

Bastınız düğmemize bizleri bağırttınız

Bir bebek uyurken karşı evde 

Uyandı sizin yüzünüzden

Bir yaşlı çok sızlandı gürültünüzden

Okulda yapılan müzik dersi bozuldu 

Hastalar rahatsızlandı koğuşlarda

Çatılarda kuşlar... 

Ağaçlarda yapraklar kımıldadı

Yer yerinden oynadı

Durun artık şoför amcalar durun

Bakın karşınızda bir uyarı levhası

Diyor ki: ''Klakson çalınmaz.''

Senin için bu kurallar 

Mutlaka kurala uymalısınız...', '1/: Şoför amcalar durun!  ''Vank vank! '' Öyle ne yaptınız?  Bastınız düğmemize bizleri bağırttınız Bakın karşınızda bir uyarı levhası Diyor k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hani-calinmazdi-klakson-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pastel Boyalar', 'pastel-boyalar-ahmet-yozgat-gy833', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Biz rengarenk pastel boyalarız 

Çocukları gün boyu oyalarız

Tutup çatılardan ak güvercinleri 

Kanatlarını sarı 

Gagalarını kırmızı boyalarız

Yani biz rengarenk pastel boyalarız 

Renge bularız bütün kuşları

2/:

Biz rengarenk pastel boyalarız 

Boz ovalara yeşil hatlar çekeriz 

Deniz üstünde mavi mavi sekeriz

Önce eflatun yağmurlar yağdırırız

Damla damla mor dağlara

Sonra üstünüze gökkuşağı çizeriz

Biz rengarenk pastel boyalarız 

Aman ha hor kullanmayın bizi 

Kızarsak sizi de boyalarız.', '1/: Biz rengarenk pastel boyalarız  Çocukları gün boyu oyalarız Tutup çatılardan ak güvercinleri  Kanatlarını sarı  Gagalarını kırmızı boyal...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/pastel-boyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muz Kabuğu', 'muz-kabugu-ahmet-yozgat-4tkjv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman ve nerede

Atılmış bir muz kabuğu

Görsem herhangi bir yerde

''Düşüp kaymayayım.'' diye 

Dolaşırım yanından

Oysa bana düşen

Kaldırıp o kabuğu yerden 

Tutup atmak çöp kutusuna

Böylece hem kendimi kurtarmak 

Yuvarlanmaktan yere 

Hem de başkalarını, ''Düşmesin.'' diye.', 'Ne zaman ve nerede Atılmış bir muz kabuğu Görsem herhangi bir yerde ''Düşüp kaymayayım.'' diye  Dolaşırım yanından Oysa bana düşen Kaldırıp o ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/muz-kabugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muzun Kabuğu', 'muzun-kabugu-ahmet-yozgat-fsfrx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman ve nerede

Atılmış bir muz kabuğu

Görsem herhangi bir yerde

''Düşüp kaymayayım.'' diye 

Dolaşırım yanından

Oysa bana düşen

Kaldırıp o kabuğu yerden 

Tutup atmak çöp kutusuna

Böylece hem kendimi kurtarmak 

Yuvarlanmaktan yere 

Hem de başkalarını, ''Düşmesin.'' diye.', 'Ne zaman ve nerede Atılmış bir muz kabuğu Görsem herhangi bir yerde ''Düşüp kaymayayım.'' diye  Dolaşırım yanından Oysa bana düşen Kaldırıp o ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/muzun-kabugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Mahallem', 'benim-mahallem-ahmet-yozgat-pnzn7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bu ev benim evim

Bu ev ise tavukların kümesi

Hemen onun yanı başına 

Uzun kulak tavşanı yerleştirdik 

Az ötede karabaşın 

Tuğladan kulübesi

''Buraya yakıştı.'' dedik

Şu yanda vızır vızır 

İşliyor arı kovanı

Hemen onun yanı

Barakası kazların.

2/:

İşte bunlar benim mahallem 

Muhtarım ben de

Babam annem ablam

Ve ağabeyimden oluşuyor

İhtiyar heyetim de...', '1/: Bu ev benim evim Bu ev ise tavukların kümesi Hemen onun yanı başına  Uzun kulak tavşanı yerleştirdik  Az ötede karabaşın  Tuğladan kulüb...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benim-mahallem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakkal - Market', 'bakkal-market-ahmet-yozgat-yqb8g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ortasında bizim mahallenin

''Veresiye'' yazarak 

Vererek borca

Bir emektar yoksul bakkaliye 

Karşıladı gereksinimimizi yıllarca

Bundan sonra bakkal-market karşı karşı 

Şenlendi bizim yaşlı çarşı.

2/:

Sonra günlerden bir gün 

Herhalde perşembeydi

Hazirandı aylardan 

Bir market çıkageldi

Bundan böyle galiba alışveriş oradan

Yani şimdi bakkal-market karşı karşı 

Şenlendi bizim yoksul çarşı.', '1/: Ortasında bizim mahallenin ''Veresiye'' yazarak  Vererek borca Bir emektar yoksul bakkaliye  Karşıladı gereksinimimizi yıllarca Bundan son...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bakkal-market-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Patlamış Zamanın Ar Damarı', 'patlamis-zamanin-ar-damari-zeynal-yaman-md4e8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Patlamış zamanın ar damarı

Hem suçlu hem güçlü üretir durur

Her gafletin vardır elbet şamarı

İnince yıllarca meletir durur', 'Patlamış zamanın ar damarı Hem suçlu hem güçlü üretir durur Her gafletin vardır elbet şamarı İnince yıllarca meletir durur...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/patlamis-zamanin-ar-damari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Yemekler Arkadaşım', 'tum-yemekler-arkadasim-ahmet-yozgat-s2hls', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Mutfakta tüm yemekler 

Sayın ki arkadaşım 

Ayırt etmem hiçbir şey

Değerlidir benim için 

Soframa gelen her şey

Her yemeği severim 

Onlar da beni sever.

2/:

Değerlidir benim için dedim ya

Hemen hemen bütün yemekler 

Çıtır çıtır ateş tüten çörekler 

Mis kokan üzümlü kekler

Tane tane ayrılan pirinç pilavı

Buz gibi yoğurttan yayık ayranı

Pastırmalı kuru fasulye

Ninem önüme önüme iter:

''Ye evladım ye! '' diye

Yerim ayırmam hiçbir şeyi

Her yemeği severim 

Onlar da beni sever.', '1/: Mutfakta tüm yemekler  Sayın ki arkadaşım  Ayırt etmem hiçbir şey Değerlidir benim için  Soframa gelen her şey Her yemeği severim  Onlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tum-yemekler-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Bisiklet', 'sari-bisiklet-ahmet-yozgat-jsx19', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ben bir yaşlı bisikletim 

Rengim uçuk sarı 

Ankara''dır uzakta kalan memleketim

Nedense bilmem göremez

Pedalımdaki hasarı cimri sahibim

2/:

Ben bir paslı bisikletim 

Okula taşırım oğlu her sabah 

İşçi babayı fabrikaya

Bazen huysuzlaşırım ah ah! 

Tam ortasında yolun 

Sıkışır zincirim araya.

3/:

Ben bir yamalı bisikletim 

Oğul kızar bu halime 

Baba çarpar gidonuma elini

''Verip hurdacıya seni,'' deseler de 

Ve deseler: ''Alacağım yenisini...''

Kıyamazlar bilirim

Oğul ile baba sırtımda

Bazen okula, fabrikaya bazen

Gider gider gelirim.

3/:

Ben bir emektar bisikletim 

Ne oğul ne de baba

Kızsalar, köpürseler de 

Bulamazlar benim gibisini.', '1/: Ben bir yaşlı bisikletim  Rengim uçuk sarı  Ankara''dır uzakta kalan memleketim Nedense bilmem göremez Pedalımdaki hasarı cimri sahibim 2...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sari-bisiklet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali, Celal Ve Ben', 'ali-celal-ve-ben-ahmet-yozgat-vc8iw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ali doğdu ilk önce 

Celal ondan sonra doğdu 

Ben doğdum aynı yılda

Açtı kocaman avuçlarını 

Kara bahtlı babalarımız 

Üstümüze yıldızlar saçtı

Ve karagözlü analarımız

Omuzlarımıza yıldızlar astı

2/:

Ali büyüdü ilk önce 

Celal ondan sonra büyüdü 

Ben büyüdüm aynı yıllarda

Açtı kocaman avuçlarını 

Kara bahtlı babalarımız 

Önümüze olanaklar saçtı

Ve kara saçlı analarımız

Yemediler kendileri 

Yalnızca bize yedirdiler

Kendileri giymediler 

Hep bize giydirdiler

Somunun en sıcağını

Yemeğin en lezzetlisini

Ve giysilerin en kırmızısını 

Ve sarı sarı çiçeklisini.

3/:

Ali okudu ilk önce 

Celal ondan sonra okudu 

Ben okudum aynı yıllarda

Açtı kocaman kitaplarını 

Siyah takım elbiseli hocalarımız 

Önümüze ışık ışık bilgi saçtı

Kara bahtlı ve ak saçlı analarımız 

Her sabah el sallayıp ardımız sıra

Okula uğurladılar

Merak içinde beklediler dönüşümüzü

Soldurmamak için dudaklarımızdan

O masum gülüşümüzü

Attılar ateşlere kendilerini.

4/:

Ali asker oldu ilk önce 

Celal ondan sonra asker oldu 

Ben asker oldum aynı yılda

Açtı kocaman avuçlarını 

Haki üniformalı komutanlarımız 

Önümüze mermiler saçtılar

Kara bahtlı ve ak saçlı analarımız

Beklerken ucu yanık mektuplarımızı 

Gözleri ıslak 

Biz dağlar başında: Tak! Tak! 

Vurulduk tam göğsümüzden 

Hüzünlü kuşlar uçtular üstümüzden 

Şehrimize ulaştılar.

5/:

Ve dediler:

''Ali şehit oldu ilk önce 

Celal ondan sonra şehit oldu 

O da şehit oldu aynı günde...''', '1/: Ali doğdu ilk önce  Celal ondan sonra doğdu  Ben doğdum aynı yılda Açtı kocaman avuçlarını  Kara bahtlı babalarımız  Üstümüze yıldızlar ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ali-celal-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yazık çok geç geldin', 'ne-yazik-cok-gec-geldin-selcen-boyar-b7e4h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaralarım baş tutmuşken,

        Gönlüm taşa kesti derken,

              Umutlarım bitti derken,

        .................................Geldin.....! 

                         Ne yazık çok geç geldin....! 

Yıllar bitti gitti derken,

          Güller soldu açmaz derken,

               Gönlüm dolu taşmaz derken,

        ..................................Geldin....! 

                         Ne yazık çok geç geldin....! 



                                               20.02.2006', 'Yaralarım baş tutmuşken,         Gönlüm taşa kesti derken,               Umutlarım bitti derken,         .................................Ge...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ne-yazik-cok-gec-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta Nokta', 'nokta-nokta-ahmet-yozgat-ox0vf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ben mini minnacık bir noktayım 

İmla sıralamasında en sondayım

Virgül: Sevgili kız kardeşim

Eşim: İki nokta üst üste

Ünlemin altındayım 

Üstündeyim virgülün

Geçer cümleye son olmakla 

Tüm vaktim ve bütün günüm

2/:

Ben mini minnacık bir noktayım 

Bu şiire kondu adım

Kitabın en sonundayım...', '1/: Ben mini minnacık bir noktayım  İmla sıralamasında en sondayım Virgül: Sevgili kız kardeşim Eşim: İki nokta üst üste Ünlemin altındayım ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nokta-nokta-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimdi Avuçlarımdan Kayan', 'hayallerimdi-avuclarimdan-kayan-zeynep-nilgun-gokceoz-gxsln', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boş sokaklarda dolaştım gecenin karanlığında 

Telaşla geçtim başıboş düşüncelerin yanından 

Sanki hep yakınımdaydın 

Sanki hem soru hem cevaptın, 

Boynum büküktü zamanın firarlarında 

Ben deli bir sevdanın üşüyen yüreği 

Sen, kabına sığmaz rüzgarların bedeni 

Gökyüzü ben, sen yıldızların seveni 

Hayat ise kafa tuttuğum 

Üryan hayallerin direnişi. 

Vefasız bir zamanın pençesinde sevgim 

Gözlerim mağrur bir akşam yıldızının kollarında 

Ve ben isimsiz sokaklarda 

Kimsesizliğin sustuğu anlarda 

Aşkımın son gerçeğini soluyorum, 

Ben el değmemiş düşlerde kaybolan 

Sen, bilmediğim çiçeklerin dili 

Bil ki her şey acımasız 

Bil ki ağladığım akşamlar 

Gecelerden daha insafsız. 

Diz çöküyor düşlerim solmuş uykularımda 

Gecenin çiyi düşüyor kırılgan umutlara 

Üşüyorum sensiz esen rüzgarlarda 

Arıyorum seni gümüş rengi ay ışığında, 

Ben bir sevgi tutsağı 

Sen, tükenmeyen sevdamın sevişmeleri 

Bitmeyecek sandığım aşkımın 

Mahkum olmuş gerçekleri 

Bir gün ansızın giderken 

Sancılanacak içimin kutsal hasretleri.', 'Boş sokaklarda dolaştım gecenin karanlığında  Telaşla geçtim başıboş düşüncelerin yanından  Sanki hep yakınımdaydın  Sanki hem soru hem ceva...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayallerimdi-avuclarimdan-kayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarımda Taşım Ağlar', 'mezarimda-tasim-aglar-tayyip-sag-kp80z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel bana yar olmazsan,

Bu yüreğim durmaz ağlar,

Aşkınla canım alırsan,

Mezarımda taşım ağlar.

Dertli bülbül konmuş güle,

Gezer durur daldan dala,

Senin için düştüm yola,

Tükenmeyen yollar ağlar.

Güneşin battığı yerde,

Hüznün kalır gözlerimde,

Sitem dolu sözlerimde,

Canlanan anılar ağlar.

Bir menzile varamadım,

Geçti ömrüm tutamadım,

Yaralarım saramadım,

Mahsun geçen yıllar ağlar.

        25.4.2005', 'Güzel bana yar olmazsan, Bu yüreğim durmaz ağlar, Aşkınla canım alırsan, Mezarımda taşım ağlar. Dertli bülbül konmuş güle, Gezer durur dalda...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mezarimda-tasim-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Senfoni', 'sensiz-senfoni-eyup-boran-63eeg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden yoksun aksamlar,

trajik bir romanın son sayfasıdır cevrilen.

Sonsuzluga acılan bir penceredir yasanan. 

Dayanamaz olur yoklugunda yüregim,

boslukta uzayda bir yerlerde dolasir ellerim.

Kahreden bir gecedir baslayan,

Bos gözler ve anlamsiz yüzlerdir beni bekleyen.

Bir tutam dost,

                 güftesi kirik bir ezgidir

senden geriye kalan.

Girerim karanlik bir denize,

bir isik vurmaz yüzüme.

Türkülerin sesini duyarim derinlerden 

mirildanmak isterim 

gücüm yetmez

                    söylemez dilim,

                                       yangina düser yüregim.

Ne bir nefes,

                 ne bir umut yesermez sesimde.

Yok olus anidir oysa kimse bilmez,

icimdeki cocuk öksüz kalmistir gercekte.

Buz yanginidir baslayan tenimde.

Boguluyorum yine sensizligin denizinde,

sensiz bir senfoni basliyor gecenin icinde.', 'Senden yoksun aksamlar, trajik bir romanın son sayfasıdır cevrilen. Sonsuzluga acılan bir penceredir yasanan.  Dayanamaz olur yoklugunda yür...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Boran']::text[], 8.5, '{"poet":"Eyüp Boran","poet_slug":"eyup-boran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensiz-senfoni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret', 'nefret-zeynal-yaman-6y1cz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nefretle bakarsak eğer birbirimize

Kan ve gözyaşı katarız kaderimize', 'Nefretle bakarsak eğer birbirimize Kan ve gözyaşı katarız kaderimize...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nefret-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Öğreniyorlar', 'nereden-ogreniyorlar-yusuf-onder-bahceci-mlfmk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ahmet Amca Hacca gidiyor Hac''dan geliyor,

Eşi, dostu Allah kabul etsine gidiyor, soruyor,

Hacı Emmi misafirlerine hayır, dualar ediyor,

Zemzemler içiliyor, Medine hurması yeniliyor.

Biraz sonra başka konulara geçiliyor deniyor,

Hacı Amca artık, ölçü, tartı, işi, gücü bırakırsın,

Hayretle bakıyorum ve vallahi çok şaşıyorum,

Nereden öğreniyorlar böyle nasihat vermeyi.

Neden ölçüyü, tartıyı bıraksın, neden ki yatsın,

Hacı Amca gitmiş, görmüş daha çok çalışsın,

Peygamber diyor, iki günü eşit olan ziyanda,

Nereden öğreniyorlar böyle nasihat vermeyi.

Akıllı, mantıklı olmak gerekir, oyundur bunlar,

Ahmet Amca Hac''dan gelmiş ölçer ve tartar,

Ancak Allah''ı tam bilmeyenler eksikce tartar,

Nereden öğreniyorlar böyle nasihat vermeyi...', 'Ahmet Amca Hacca gidiyor Hac''dan geliyor, Eşi, dostu Allah kabul etsine gidiyor, soruyor, Hacı Emmi misafirlerine hayır, dualar ediyor, Zemz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nereden-ogreniyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-tahmine-yildirim-rzn7d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu yaz benim dönüm noktam oldu

İçime sanki buket buket güller doldu

Hep çok güzellikler gelip beni buldu

Başıma sanki en talihli talih kuşu kondu

Daha önce hiç tanımadığım duygular beni buldu

Tamam mine işte aradığın tam buydu

Sana tepsi tepsi  güzellikler sunuldu

Hayallerinin hepsi yavaş yavaş gerçek oldu

                                                                            EKİM

                                                                         2005', 'Bu yaz benim dönüm noktam oldu İçime sanki buket buket güller doldu Hep çok güzellikler gelip beni buldu Başıma sanki en talihli talih kuşu ...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yaz-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Inkar', 'inkar-eyup-boran-uw9ms', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Icime düstügünden beri 

icim simsicak.

Ama tenim üsüyor yoklugunda,

düslerim intiharda,

bedenim inkarda kendini.

Gözlerin büyüdükce büyüyor 

karanlik odamda,

Denizini ariyorum sensiz ve sessizce.', 'Icime düstügünden beri  icim simsicak. Ama tenim üsüyor yoklugunda, düslerim intiharda, bedenim inkarda kendini. Gözlerin büyüdükce büyüyor ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Boran']::text[], 8.5, '{"poet":"Eyüp Boran","poet_slug":"eyup-boran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/inkar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
