INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üc', 'uc-eyup-boran-1qo7u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üc uzun gün

                  Bu sehirde,

Üc uzun yol

                  boyunca,

Üc kirik hayal

                  kalmis sadece.', 'Üc uzun gün                   Bu sehirde, Üc uzun yol                   boyunca, Üc kirik hayal                   kalmis sadece....', ARRAY['Türk Edebiyatı','Şiir','Eyüp Boran']::text[], 8.5, '{"poet":"Eyüp Boran","poet_slug":"eyup-boran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uc-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-082 Körebe...', 'ub-082-korebe-mehmet-coban-35xxk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kör,

Olmamı istediler

Görsen de görme

Duysan da duyma 

Dediler! ........

En güzel yaşam

Görmedim 

Duymadım 

Bilmiyorumdur 

Dediler! …..

Görürsen, 

Duyarsan, 

Bilirsen,

Başın derde girer

Dediler! ......

Ebe,

Yaptılar beni

Saklandı gerçekler

Saydırdılar sürekli

Saydırmayı bitirmediler

Kaldırma başını

Etrafa bakma dediler

Körebe 

Oldum,

Gözüm kapalı

Açtırmadılar hiç

Haksızlığa,

Zulümlere karşı! ..

Beynimi yıkadılar

Bilgi, bilim diye

Güç, kuvvet diye

Sopa gösterdiler

Yasa, adalet diye..

Yol gösterdiler

Çıkara çıkarcıya

Mahkûm oldu halk

Efendilikle, köleliğe

Hala sayıyorum

Biri beni uyandırsın

Beğenmedim bu oyunu

Tekrar saydırsın! ....

20.02.2006-İzmir', 'Kör, Olmamı istediler Görsen de görme Duysan da duyma  Dediler! ........ En güzel yaşam Görmedim  Duymadım  Bilmiyorumdur  Dediler! ….. Görü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ub-082-korebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fıs Fıs', 'fis-fis-sumer-kucuk-m11ou', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyandım

Bir fısıltı

Kulak verdim konuşuyor,

Konuşuyorlardı

Fıs fıs

Kalktım yürüdüm

Pazarda fıs fıs

Çarşıda fıs fıs

Gazetelere baktım

Fıs fıs

Kitaplara baktım

Fıs fıs

Düşündüm

Demek ki yaşıyoruz

Fısıltı dünyasında

Onun için fıs fıs', 'Uyandım Bir fısıltı Kulak verdim konuşuyor, Konuşuyorlardı Fıs fıs Kalktım yürüdüm Pazarda fıs fıs Çarşıda fıs fıs Gazetelere baktım Fıs fıs...', ARRAY['Türk Edebiyatı','Şiir','Sümer Küçük']::text[], 8.5, '{"poet":"Sümer Küçük","poet_slug":"sumer-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fis-fis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarpılmayın', 'carpilmayin-yusuf-onder-bahceci-8ze3s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adam kafaya koymuşsa mutlaka çarpar,

Masayı, kasayı çarpanı, Allah'' da çarpar,

Allah''ın yaptıklarından, kim hesap sorar,

Adam kafaya koymuşsa mutlaka çarpar.

Etrafında pervane olur, döner, dönerler,

Ya kefil ederler veyahut, paranı isterler,

Param yok deyince de küser, küserler,

Adam kafaya koymuşsa mutlaka çarpar.

Adamın adam olmaya niyeti yok bellidir,

Adam parazit, adam, hırsız tiyniyetlidir,

Adamın mayası bozuk belki de acındırır,

Adam kafaya koymuşsa mutlaka çarpar.

Merhamet duygularıyla sakın kanmayın,

O tipler her yolu denerler siz inanmayın,

Doğru insanlarla sohbet edin yanmayın,

Adam kafaya koymuşsa mutlaka çarpar...', 'Adam kafaya koymuşsa mutlaka çarpar, Masayı, kasayı çarpanı, Allah'' da çarpar, Allah''ın yaptıklarından, kim hesap sorar, Adam kafaya koymuşs...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/carpilmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce....', 'dusunce-mehmet-coban-1b81c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünce 

Düşündüm

Düşmeden 

Düşünmedim

Düşmeden 

Düşünebilseydim

Düşmezdim.

Düşünelim

Düşmeden! ..

20.02.2006-İzmir', 'Düşünce  Düşündüm Düşmeden  Düşünmedim Düşmeden  Düşünebilseydim Düşmezdim. Düşünelim Düşmeden! .. 20.02.2006-İzmir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dusunce-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Çok Sevdiğim Rabbim', 'en-cok-sevdigim-rabbim-kiymet-sonmez-14tjb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşam uykuya dalarken en son aklınıza gelen,

Sabah uyandığınızda ilk aklınıza gelen kim? 

Benim Rabbim......

Akşam Ayetel Kursi ile iyi geceler diliyorum,

Yanına birkaç sure daha ekliyorum

Sabah yine Ayetel Kursi ile günaydın diyorum.

Vakit daha dar olduğundan,

Çok bir şey diyemiyorum.

Ama gün içinde,

Evden çıkarken,

Çalışırken,

Yolda yürürken,

O daima benimle diye,

Bende onunla konuşuyorum...

Derdimi de ona açıyorum,

Hoşnutluğumuda şükürle ona söylüyorum

Ve O beni bıkmadan usanmadan dinliyor, dinliyor,

Taaki ben yorulana, uykuya yenik düşene kadar.

İşte insanın uykuya dalarken en son düşündüğü,

Uyandığı zaman ilk düşündüğü,

En çok sevdiğiymiş,

Benimde en çok sevdiğim, tek ve eşi olmayan Rabbimdir.', 'Akşam uykuya dalarken en son aklınıza gelen, Sabah uyandığınızda ilk aklınıza gelen kim?  Benim Rabbim...... Akşam Ayetel Kursi ile iyi gece...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/en-cok-sevdigim-rabbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teloğlan İle Korkuluk', 'teloglan-i-le-korkuluk-ahmet-yozgat-nj109', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir varmış, bir yokmuş...

Dilde var, elde yokmuş.

Dilde olan gevezelik,

Elde olmayan cömertlikmiş,

Cömertlik dediğin elde bulunmaz.

Ciddiyet dediğin kelde bulunmaz.

Oysa kelde sadece saç olmaz sanırdım,

Nereden biliyorsun derseniz,

Eskiden bir kel tanırdım.

Onun adı Keloğlandı,

Aman bir yaman, bir yamandı.

Anasını boyardı, babasını satardı.

Şekere tuz, tuza biber katardı.

Geceleri çıkar Kaf dağında yatardı,

O yatadursun Kaf dağında,

Biz başlayalım bu şirin masalımıza...

Bir varmış, bir yokmuş.

Günlerden bir gün...

Oklavayı kapmış yaşlı anası 

Başucuna dikilmiş, sırtüstü yatan Teloğlan''ın

Demiş ki sinirli bir ses ile:

''Bre hayta! 

Böyle boşu boşuna yatılır mı bu zamanda? 

Kalksana. Kalkıp da işine baksana.''

Oklava bir başında, bir kıçında şaklayınca 

Teloğlancık, başlamış yalvarmaya: 

''Yapma ana, etme ana! 

Kurban olayım sana! 

Kalktım işte baksana.''

Teloğlan yoksul, anne yoksul, 

Kulübe tamtakırmış. 

Elde yok, avuçta yokmuş. 

Aile çok fakirmiş. 

Tüm varları, yoklar ufacık bir tarlacıkmış. 

İşler sarınca iyice sarpa

Oracığa ekermişler bir ölçek arpa.

Ama gel gör ki...

Tarlanın çevresi bir dolu karga imiş.

Meretler ne söz anlarmış, ne lâf dinlermiş.

Varsa yoksa boğazları...

Ne bulursa yerler, ne bulursa yutarlarmış.

Teloğlan kovalamasa tüm tarlanın ömrü bir saatlikmiş.

Bir elinde gürgen değnek, diğerinde meşe sopa...

Teloğlan bir o yana koşuyormuş, bir bu yana:

''Pır pır... Kış kış...'' diyerek. 

Sinirli sinirli söylenerek.

Aman vermiyormuş hain kargalara.

Ama can bu, nasıl dayansın gün boyu kovalamacalara? 

Bir gün değil, beş gün değil. 

Kargalarla savaş sürecekmiş tam beş ay.

Vay başına gelenlere bizim oğlanın vay! 

Bu onulmaz bekçilik canına tak etmiş Tel''in.

Usanıp bir iyice işinden:

''Hain kargalar gelin. 

Bundan sonra tarla da tapan da sizin.'' demiş.

Sonra da toprağa yüzükoyun uzanmış.

Kargalar fırsat bilip üşüşmüşler ekine. 

Tam darı ekecekken buğdayların köküne...

 Teloğlan''ın arkasından bir ses duyulmuş:

''Ne o evlât, ne bu hâl? '' 

Teloğlan fırlayıp kalkmış ayağa.

Bir sola bakmış, bir sağa:

''Aman o da ne! '' 

Karşısında bir adam sanki kurbağa... 

Gözleri koskocaman, burnu bir kene. 

Kısıkmış sesi. Sırtında kilim heybesi... 

Elinde kocaman bir asa... 

Yani görüntü tamam, bir de vraklasa.

''Sen de kimsin'''' diye sormuş Tel ona.

Adam demiş: ''Boş ver onu, bunu. Hele gel buraya.''

Bizimki korka korka yaklaşmış kurbağaya.

Garip kılıklı adam uzatıp benekli elini: 

''Yabancı değilim, bir yoksul yolcuyum. 

Gelirim her yıl. Beni tanır buralar. 

Tarlalara konmasın diye kargalar, korkuluk satarım. 

İstersen eğer sana da bir korkuluk satayım.'' Diye tanıtmış kendini. 

Teloğlancık merak edip demiş ki: 

''Nedir o, bir bakayım? '' 

Çıkarmış kurbağa heybesinden bir korkuluk:

''Bunu,'' demiş. ''Çak tarlanın ortasına. 

Kargalar konmasın bir daha arpalara.''

''Peki,'' demiş Teloğlan. ''Ücreti nedir bunun? '' 

''Çok değil.'' demiş kurbağa. 

''Çıkan ürünün yarısı... 

Şu yanı benim tarlanın, senin olsun bu yarısı.'' 

Olurdu, olmazdı derken el sıkıp anlaşmışlar. 

''Hasat vakti gelirim.'' deyip gitmiş korkuluk satıcısı.

Teloğlan geçirmiş bir kazığa aldığa korkuluğu.

Tarlanın ortasına çakmış.

Olacak ya. 

Korkuluk çakılınca yeryüzüne bir hâller olmuş göğe.

Bir yağmur, bir yağmur ki sormayın.

Yağmuru içen toprak, patlamış tabak tabak.

Kuru otlar gövermiş.

Kuru dallar yeşermiş.

Bu arada korkuluk da almış nasibini yağmurdan.

Yaprakları fışkırmış, orasından burasından.

Boy dersen on kulaç birden uzamış.

Koca tarlanın üstünü bile kaplamış.

Olmuş sanki bir katana.

Seslenip bizim Teloğlan''a:

''Heey ufaklık,'' demiş. ''Ne arıyorsun burada? ''

Telo şaşkın: ''Bu tarla benim. Bekliyorum tarlamı.'' 

Korkuluk hırçınlaşmış:

''Sus, kızdırma kafamı. 

Fazla görünme gözüme. 

Haydi şimdi al voltanı. 

Karşılık verme sözüme.'' 

Sonra uzatmış kolunu azman korkuluk.

Koca ovayı göstermiş: 

''Görüyor musun? '' demiş. ''Benim kardeşlerimi. 

Her tarlada bir tane var. 

Bundan böyle buralar sizlere olacak pek dar.''

Sonra da bir tekme vurmuş Teloğlan''ın arkasına.

Atıvermiş zavallıyı ta uzaklara.

Orada rastlamış bizim oğlan, diğer atılanlara.

Meğerse onlar da korkulukçuya kanmışlar.

Birer korkuluk satın almışlar.

Dikmişler tarlalara.

Kızarak zavallı kargalara.

Olan olmuş. İşte sonuç ortada.

Ne arpa kalmış elde ne de tarla.

Yana yakıla akıl sormuşlar:

''Ne yapalım? '' diye Teloğlan''a

Teloğlan düşünmeye başlamış.

Düşünmüş, taşınmış, ensesinden kaşınmış: 

''I-ıh! '' demiş kafasını sallamış.

Bulamamış kurtuluşa çıkılacak bir kapı.

Vurarak muzipliğe demiş ki:

''Yutmuşuz bizler hapı.''

Ne edelim, nerelere gidelim derken.

Çıka gelmiş korkulukları satan açıkgöz adam. 

Demiş: ''Hayrola? '' bizimkilere.

Demişler: ''Hayrın karşı gele! 

Bize bu korkulukları sattın. 

Tarlaların yarılarına yattın. 

Başımıza belâ ettin korkulukları. 

Yağmur yağdı, böyle oldu. 

Senin korkuluklar bizi tarladan kovdu.'' 

Kurbağa patlatıp gözlerini, eğip bükmeden sözlerini: 

''Kurtarayım sizi ama isterim ücretimi.'' demiş.

Teloğlan sormuş: 

''Nedir ücretin? '' 

Kurbağa gözlü adam:

''Pek bir şey değil canım.'' demiş. 

Yumurtanın sarısı, tarlanın kalan yarısı...''

''Ne diyorsun sen? '' diye kızmış köylüler.

Korkulukçunun üzerine sinirle yürümüşler.

Keloğlan: 

''Durun.'' demiş korkulukzedelere.

Ardından tarlasının kalan yarısını vermiş.

''Bu Tel''in bir bildiği vardır.'' diye.

Bakmayıp ileriye, geriye.

Köylüler de ''Tamam.'' demişler.

Böylece iş bağlanmış tatlıya.

Korkulukların efendisi kaşımış kafasını.

Açmış sırtında taşıdığı sihirli torbasını:

''Eker teker püf! '' demiş.

Bir toz serpmiş havalara.

Tozlar dönüşmüş güveye.

Güveler saldırmışlar tarlalara.

Yapışıp korkuluklara kemir kemir kemirmişler.

Azman ot adamları anında devirmişler.

Ardından kargalar gelip güveleri bitirmişler.

Tarlalar kurtulunca dönmüş Teloğlan köylülere:

''Tutun şu sahtekârı! '' demiş.

Tutmuşlar kötü kalpli köseyi.

''Bağlayın şu direğe! '' demiş Tel.

Direğe bağlamışlar.

''Bundan böyle korkuluk sensin. 

Ekinlerimizi sen koruyacaksın! '' 

Teloğlan almış güve torbasını kuşağına yerleştirmiş:

''Yoksa,'' demiş. ''Sihirli güveleri salarım üzerine.''

''Ben ettim, sen etme Teloğlan.'' demiş uyanık.

Rol yaparak ağlamış yanık yanık:

''Beklerim tarlaları, kondurmam kargaları. 

Bundan böyle yapmam gayrı haksızlık. 

Otururum sarayımda alık alık.'' demiş.

Teloğlan, bu sözlere gülüp geçmiş.

Sevinmiş tüm köylüler.

Ne korkuluk kalmış, ne de güveler.

Kargalar da uçup gitmiş.

Bu masal da burada bitmiş.

Mutlu olmuş Teloğlan.

Memnun olmuş köylüler.

Biz çıkarken kerevete onlar murada ermişler.', 'Bir varmış, bir yokmuş... Dilde var, elde yokmuş. Dilde olan gevezelik, Elde olmayan cömertlikmiş, Cömertlik dediğin elde bulunmaz. Ciddiyet...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":186,"source_url":"https://www.antoloji.com/teloglan-ile-korkuluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teloğlan İle Çiçek Kızlar', 'teloglan-i-le-cicek-kizlar-ahmet-yozgat-0kj8y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir varmış, bir yokmuş...

Zamanlardan bir zamandayız.

Mevsimlerden ilk bahardayız.

Günlerden bir gün Teloğlan''ın anası,

Elinde kocaman sopası ile dikilip oğlunun başına,

Yumup gözünü, açmış ağzını: 

''Bre Tel oğlum,'' demiş. 

Ne bir mesleğin, ne de evde bir emeğin var. 

Sen de eller gibi çıkıp dışarı, bir iş ara kendine. 

Bu tembellikle aç kalacağız bir gün. Sonra demedi deme.''

Bunun üzerine bizim Teloğlan:

''Ya Allah! '' deyip vurmuş yollara.

Az gitmiş, uz gitmiş. 

Dere, tepe düz gitmiş.

Altı ay bir güz gitmiş.

Dönüp bakmış ardına...

Meğerse bir arpacık yol gitmiş.

Ne ise masal buya...

Biz bakmayalım buğdaya, arpaya.

Hiçbir vakit dönmeyelim arkaya.

Teloğlan''ı takip edelim.

O nereye gidese biz de gidelim.

Vara vara varmış Tel''in yolu bir sarayın önüne.

Demiş bizimki kendi kendine: 

''Akşam olmak üzere. 

Yatayım burada bu gece. 

Sağ salim ulaşayım gündüze.''

Bu karar üzerine Teloğlan atmış adımını.

Burası kocaman bir salonmuş.

Tabanı halı kaplıymış.

Som mermerdenmiş dört yanı. 

Teloğlan''ın ardı sıra 

Kapanmış girdiği demir kapı.

Kilitlenen kapıyı zorlamış bizimki.

Ama açamamış bir türlü.

Nasıl açsın ki? 

Kapı kapı değilmiş sanki.

Ne menteşe varmış, ne de bir kol.

Demiş kendi kendine: 

''Teloğlan kaderine razı ol! 

Unut geriyi ileri yürü.''

Bu kararın ardından üç beş adım atmış.

O sırada açılmış gizli bir kapak.

Bir  kuyu ayağının altında... 

''Ne oluyor? '' demeden yuvarlanmış boşluğa.

''Tutunayım,'' diye sağa sola saldırmış. 

Ama ne sağ varmış, ne de sol.

''Teloğlan kaderine razı ol! '' 

Bir süre düşmüş ve çakılmış sert tabana.

Gözleri karanlığa alışınca doğrulmuş.

''Burası ne büyük böyle? '' diye düşünmüş.

Yuvarlak bir taş oda imiş burası. 

Ortasında kendisi.

Çevrede ne bir in, ne de bir cin varmış.

Oda, ova kadarmış. 

Odanın duvarlarında bir sürü kol ve tokmak...

Tehlikeli olur mu bu kollara dokunmak? 

Teloğlan bu korkar mı hiç? 

Asılmış kolun birine: Fooş! 

Aaa ne hoş, demeyin.

Sanki delinmiş gökyüzü, başlamış yağmaya.

Ama ne yağmur! Şarıl şurul...

Teloğlan şaşırmış:

''Yağmuru durdurmak gerek. Ama nasıl? ''

''Eğer şu kolsa yağdıran bu seli,''

''Durduran da o olmalı...'' demiş. 

Tekrar asılmış kola ama nafile tabiî.

O olmadı, belki bir başkası...

Teloğlan öteki kolu indirmiş aşağıya.

Yağmur durmuş ama başlamış kar yağmaya.

Ama bir kar ki lapa lapa...

Şiddeti zemheri kadar...

Bir kış ki sormayın, dondurucu ayaz var.

İlikleri üşümüş, bizim zavallı Teloğlan''ın

Takırdamış dişleri:

''Bu işleri nereden sardım başıma? '' demiş 

Ve pişmanlıkla hayıflanmış.

Kışı durdurmak için yerinden fırlamış.

''Olur mu, olmaz mı? '' dememiş.

Birer birer tüm kolları denemiş.

Bu olmamış. Öteki. O olmamış. Beriki derken...

''Şak! '' diye kolun biri kesivermiş tipiyi.

Ama aksilik bu ya.

Asılmışmış meğerse bir başka yanlış kola.

Bu sefer de başlamış gök gürlemeye.

Başlamış şiddetli şimşekler çakmaya.

Başlamış yıldırıcı yıldırımlar düşmeye.

Gök, gök olalı görmemiş imiş böyle bir olay.

Söylemesi kolay. Ama yaşaması çok zormuş.

Teloğlan zıpır zıpır zıplamaya.

Köşe bucak hoplamaya başlamış.

Ama çok sürmemiş, yorulmuş bu gidişle.

Demiş kendi kendine:

''Bir kol daha çekeyim, şimşekten kurtulayım.''

Yapmış hemen kafasından geçeni.

Gitmiş kolun birine eli.

Bununla birlikte kesilivermiş toz duman.

Aman aman! O sırada ne olmuş bakın.

Bir güneş, bir aydınlık, sanki ilkbahar ortalık.

Karlar erimiş, çekilivermiş tabana.

Sular buharlaşmış, çıkıvermiş tavana.

Kuruyan topraktan otlar fışkırmış.

Çiçekler çıkmış üç tane.

Ortalık olmuş gülistan.

Teloğlan baygın, Teloğlan mestan

Oda olmuş bağ, bostan.

Çiçekler öyle güzel öyle renkliymiş ki...

Dünyada yokmuş benzerleri.

Çiçekler öyle kokuluymuş ki...

Bayıltırmış herkesi.

Teloğlancık sevinçle koparmış birini.

Burnuna götürmek üzereymiş.

''Dur ey yiğit.'' demiş çiçek ona.

Teloğlan demiş şaşırarak:

''Bak şu konuşana! Sen canlısın. 

Hem de Konuşuyorsun benimle... 

Bu ne iştir söylesene.''

Çiçek kızda bir cilve, bir işve:

''Ay Teloğlan Teloğlan! Hepimiz sana kurban... 

Biz biz idik, biz idik. Üç kız kardeş idik. 

Bu sarayın sahibi yeşil dev kaçırdı bizi. 

Hepimizi tohum yapıp ekti yerin altına. 

Bekliyorduk yıllardır bizi kurtaracak yiğidi. 

İşte geldin sonunda sen buraya. 

Tabiî ki bizi yeşil devden kurtarmaya.''

Teloğlan hindi gibi kabarmış:

''Tabiî ki geldim gelmesine de... 

Sizleri de kurtaracağım ama... 

Şimdi bu karanlık kuyudan kim kurtaracak beni? ''

Çiçek kızlar demişler:

''Korkma yiğit, hele sarıl boynumuza.'' 

Teloğlan yapmış deneni.

`Ne oluyor? '' demeye kalmadan,

Hızlıca uzamış çiçeklerin gövdesi. 

Yukarı çıkmış gül kızların bedeni.

Olan olmuş, bulmuş kendini bizimki yer yüzünde.

Çırpmış ellerini şaşkınlık ve sevinçle

Ama... İşte aması var her işin.

Duyulmuş bir ses ki sayın ki boru.

Kaplamış sağı solu:

''Kimsin sen? Ne arıyorsun sarayımda? ''

Teloğlan öyle bir korkmuş ki görünce yeşil devi.

Demiş kendi kendine:

''Hemen kaçmaktır kurtuluşun yolu.'' 

Ama dev bu kocaman parmağıyla enselemiş bizimkini.

Demiş ki titreterek dağları:

''Söyle bakalım insanoğlu. 

Kırk katır mı ister canın? 

Yoksa kırk keskin satır mı? ''

Teloğlan yalvar yakar olarak:

''Dev dayı israf etme de sende kalsın. 

Bir gün belki gerekli olur o katırlar. 

Bir gün belki lâzım olur o güzelim satırlar. 

Ben gideyim buradan ufak ufak... 

Anam beni hatırlar. Üzülür kadıncağız.''

O sırada unutulan sarmaşık boylu kızlar,

Uzatıp ince dallarını yeşil devi dolamışlar.

''Ne oluyor? '' dedirtmeden sütunlara bağlamışlar.

Sonra dönüp Teloğlan''a demişler:

''Şimdi bizi kopar dalımızdan.''

Emir kulu Teloğlan...

Kızlar ne diyorsa o olmalı. 

Hak yerini bulmalı.

Kopan çiçekler bir bir dünya güzeli olmuşlar.

Yitirdikleri yaşamı yeniden bulmuşlar.

Bu sırada tutsak olan dev, başlamış yalvarmaya: 

Teloğlan bu, kıyar mı hiç bir canlıya.

Tövbe ettirmiş deve. Çözmüş bağlayan dalları.

Sonra yanına almış dünya güzeli kızları.

Ve de torba torba altınları...

Veda etmiş yeşil deve.

Sağ salim dönmek için eve, 

İzine basa basa vurmuş yola. 

Uzaklaşmış güzellerle kol kola. 

Bazen mola vererek, 

Bazen saatlerce yürüyerek 

Az gitmiş, uz gitmiş.

Masal masal matitas...

Tas tas soğuk sular içmiş yolda.

Çayırla çimen biçmiş sağda solda.

Teloğlan ermek için amaca, 

Yolu sardırmış dik bir yamaca.

Altı ay, bir güz daha gitmiş.

Var varadan vararak, sür süreden sürerek...

Asya''dan, Amasya''dan, Tire''den sürünerek...

Ben deyim uzunca bir süre.

Siz deyin göz açıp kapayana kadar 

Bir zamanmış geçen aradan.

Başladığı gibi bitense işte bu masalmış.

Yaşam gerçek, masallarsa yalanmış.

Ermiş onlar murada, biz çıkalım kerevete.

Şişmanlamamak için başlayalım diyete.

Hareketlenmiş masalın sonu.

Başlamış masalcının en tatlı oyunu.

''Pat! '' demiş. Bir elma düşmüş gökten.

Teloğlan kapmış onu.

Bir elma daha düşmüş. Onu da ben kapayım.

Sanırım bir tane daha düşecek yukarıdan.

Burada bekleyin, onu da siz kapın.', 'Bir varmış, bir yokmuş... Zamanlardan bir zamandayız. Mevsimlerden ilk bahardayız. Günlerden bir gün Teloğlan''ın anası, Elinde kocaman sopas...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":199,"source_url":"https://www.antoloji.com/teloglan-ile-cicek-kizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizliğim', 'caresizligim-necmettin-davulcu-5zwmw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ölmek çare olsa

pamuk ipliğine bağlayacağım çaresizliği

binecek bir gemi bulsam dönüşü olmayan

gideceğim bu diyarı terkedip

bir umuda bağlayıp çaresizliği

git deseler gideceğim

                   -koyvermez ki çaresizliğim-

sen çaresizliksin

çaresizliğim sen

çaresizliğime çare yine sen

ölümü bile sevebilirim

koynuma alıp

okşarım bir vakit saçlarını

çaresizliğimle

git deseler gideceğim bu diyarı terkedip

                                      -korkuyorum çaresizlikten-

sen çaresizliksin

çaresizliğim sen

çaresizliğime çare yine sen

20.02.2006', 'ölmek çare olsa pamuk ipliğine bağlayacağım çaresizliği binecek bir gemi bulsam dönüşü olmayan gideceğim bu diyarı terkedip bir umuda bağlay...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/caresizligim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köpek Salyaları Akarken Hanemize', 'kopek-salyalari-akarken-hanemize-zeynal-yaman-c57os', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben Bosnalıyım

Parça parça olmuş bağrım

Yaralıyım...

Bomba alevlerinde kaybettim

Evlad-ı ıyâlimi! 

Şimdi tek başına tunçtan bir nefer

Heykel kesildim zalimlerin karşısında

Direniyorum! 

Ben Bosnalıyım

Öz eşkimden suladım öz toprağımı

Kan akıyor pınarlarımdan 

İliklerime kadar işlemiş acı

Soğukta üşümüşüm ne olur? 

Ben Bosnalıyım

Eşimi yitirdim bir seher vakti

Anamı-babamı yakmışlar diri diri! 

Topyekûn çıldırmış insanlık

Ben çıldırmışım ne olur? 

Bakın şu Sinanî camiye

O da benim gibi öksüz! 

Başımızı isteyenler koparmışlar başını

Tevhidi haykıran minarenin...

Allahuekber diyeni yok

Ezanlar susmuş artık

Ben susmuşum ne olur? 

Ben Bosnalıyım

Her yanım harap

Viraneye döndü gülzarım

Baykuşlar geldi geleli

Bülbüller terk etti bahçemi! 

Kan soluyor hava

Her yanda leş kargaları

Konuyor asrın çürümüş vicdanına...

Köpek salyaları akarken hanemize

Yağmurda ıslanmışım ne olur? 

Ben Bosnalıyım

Bağladılar ellerimi ambargoyla

Kolum-kanadım kırık! 

Irzını kaybetmiş insanlık

Üç-beş mâsumun ırzına geçmişler ne olur? 

Çok şey olur, çook...

1994', 'Ben Bosnalıyım Parça parça olmuş bağrım Yaralıyım... Bomba alevlerinde kaybettim Evlad-ı ıyâlimi!  Şimdi tek başına tunçtan bir nefer Heykel...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kopek-salyalari-akarken-hanemize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı ki', 'olmadi-ki-mesut-ozturk-y3oxv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir derdim var, bahsedeyim dilersen.

Bir yaram var, göstereyim istersen.

Bir öyküm var anlatayım dinlersen.

 Benim hiç dinleyenim, olmadı ki..

Acı çektim, bir ah bile demedim,

Yoksul kaldım, ama haram yemedim.

Aşık olup, yüreğini verendim,

Benim bir sevenim olmadı ki.

Hatrım soranımda olmuyor,

Yaban elde telefonum çalmıyor,

Bir tanıdık, bir dost uğramıyor,

Benim candan dostum olmadı ki.

Yanlız kalmak için mi doğdum? 

Buralarda sürünüp harap oldum,

Ne yaptım da bunları buldum? 

Elimden tutanım olmadı ki', 'Bir derdim var, bahsedeyim dilersen. Bir yaram var, göstereyim istersen. Bir öyküm var anlatayım dinlersen.  Benim hiç dinleyenim, olmadı ki...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olmadi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-mesut-ozturk-pcmsm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne olursun beni biraz anla,

Aşkı verip, sevgini tamamla.

Olmuyor böyle yalan dolanla.

Yaşamak çok zor geliyor bana..

Ağlayacaksan gel benimle ağla,

Ne işin var geçilmez dağla,

Gönlünü eğer bağlarsan bana,

Sevgimi kalpten veririm sana.

Gülyüzlüm, güzel gözlüm, candan tavırlı sevgilim.

Yazılarında seni gördüğüm,

Kokularında seni teneffüs ettiğim, 

Mektubunu dün akşam aldım.

Senin aşkından Mecnun olmuş, Çöllerde geziyorum.

Sevginden Ferhat olmuş, Dağlarda içiyorum.

Kerem gibi aşık olmuş, saz çalmayı bilmiyorum.,

Bildiğim tek şey, seni canımdan çok seviyorum', 'Ne olursun beni biraz anla, Aşkı verip, sevgini tamamla. Olmuyor böyle yalan dolanla. Yaşamak çok zor geliyor bana.. Ağlayacaksan gel beniml...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendinize gelin!', 'kendinize-gelin-mesut-ozturk-ijr7t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bombalar patlıyor, çocuklar ölüyor,

Raketler uçuyor, analar ağlıyor,

Yaralanan gaziler, yürekler dağlıyor,

Düşman silah donanmış, Kendinize gelin.

Yetim olan yavrular, Dul kalan kadınlar,

Düşmana karşı durup, ölmeye hazırlar,

Mehmetciğim şehit olmuş, yerde akıyor kanlar.

Vatan elden gitmeden, Kendinize gelin.

Birlik beraberlik günüdür bugün,

Atalar yaşamış, bunları hergün,

Namus görevidir, inan her Türkün

Düşma kapıya dayanmış, kendinize gelin.

Şehitlerden yadigar, Alyıldızlı bayrağı, 

Peygamberden hediye, Allah yazan sancağı,

İndirmeye yeltenecek şerefsiz alçağı,

Alnından vurmak için, kendinize gelin.', 'Bombalar patlıyor, çocuklar ölüyor, Raketler uçuyor, analar ağlıyor, Yaralanan gaziler, yürekler dağlıyor, Düşman silah donanmış, Kendinize ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kendinize-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesut', 'mesut-mesut-ozturk-6hy6l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ismimi Mesut koymuşlar,

Bu Dünya´da gülüp sevinsin diye,

Herhalde, bir yanlışlık yapmışlar,

Gülmek, sevinmek benim neyime.

Aynaya baktım, dün akşam yine,

Hançer saplı, sanki yüreğimde,

Adım Mesut, Hayatım değíl,

Mutluluklar benim neyime.

Bir dileğim var dostlarım sizden,

Mutluluk uğramaz, uzaktır bizden,

Ağlamak kader, kalmış ezelden,

Tatlı yaşamak benim neyime.

Bu diyardan birgün gidersem,

Acılara dayanamayıp, pes edersem,

Yaşamak yerine, ölüm seçersem.

Adı Mesut`tu yazın kabrime', 'Ismimi Mesut koymuşlar, Bu Dünya´da gülüp sevinsin diye, Herhalde, bir yanlışlık yapmışlar, Gülmek, sevinmek benim neyime. Aynaya baktım, dü...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mesut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaykara''ya Hasret.', 'caykara-ya-hasret-mikdat-bal-wjthj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tarlalar belleniyor, bahara giriyorken

Şimdi başka mesgale vardır Çaykaramızda

Cemre toprağa düştü her şey yeşeriyorken

Yüksek yüksek tepeler kardır Çaykaramızda

İnsanları sevecen hiç bir yerde yok eşi

İş bitmez Çaykarada yok baharı yok kışı 

Gurbetçi var her evden kalanların çok işi

Geçim kaynakları kıt dardır Çaykaramızda

Medarı iftiharı Uzungöle çok yakın

Çaykaraya gelenler unutmasınlar sakın

Cenneti bilmezseniz Uzungöle bir bakın

O cennetten bir bahçe yerdir Çaykaramızda

Ormanlar sakız kokar, her bir derde devadır

Okşijeni bol olur o ne temiz havadır

Orada yaşayana bu nimet bedavadır

Yaylaya gidip gelmek kârdır çaykaramızda

Yardımlaşmada buldu, insanımız çareyi

Dünyanın fitneleri bozmadı bu yöreyi

Gençler evden alırlar ananeyi töreyi

Büyüğe saygısızlık ardır Çaykaramızda

Orda doğdum büyüdüm, gurbet girdi araya

Otuz dort sene oldu hasretim Çaykara’ya

Bazen sıla-I rahim merhem olur yaraya

Ebedi kalabilmek zordur Çaykaramızda

Mikdatî’yim uzaktan hasretiyle yanarım

Hep onu düşünürüm, sık sık onu anarım

Yediden yetmişine selam sevgi sunarım

Her canı benim için yârdir Çaykaramızda', 'Tarlalar belleniyor, bahara giriyorken Şimdi başka mesgale vardır Çaykaramızda Cemre toprağa düştü her şey yeşeriyorken Yüksek yüksek tepele...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/caykara-ya-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerin Konusunu Seçelim', 'siirlerin-konusunu-secelim-yusuf-onder-bahceci-zrooh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dostlarım gelin şiirlerin konusunu seçelim,

Şiirlerde güzel duygular olmalı iyi seçelim,

Kutsal değerlerimize, böyle sahip çıkalım,

Dostlarım gelin şiirlerin konusunu seçelim.

Gerekirse şiir dereden, tepeden de yazılır,

Kutsal değerlere dil uzatanlara fazla kızılır,

Şair arkadaşlara sitem etmem kâlbi kırılır,

Dostlarım gelin şiirlerin konusunu seçelim.

En güzel şiir Allah''ın gönderdiği Kuran''dır,

Güzeli, doğruyu anlatan şiire cevaz vardır,

Şiirlerde tema, haksızlıklara fazla isyandır,

Dostlarım gelin şiirlerin konusunu seçelim.

Konular güzel olursa okunur ve okutturulur,

Bu şiir ne güzel denir belki de dua okunur,

Kutsal öz değerlerini övenler belki kurtulur,

Dostlarım gelin şiirlerin konusunu seçelim...', 'Dostlarım gelin şiirlerin konusunu seçelim, Şiirlerde güzel duygular olmalı iyi seçelim, Kutsal değerlerimize, böyle sahip çıkalım, Dostları...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siirlerin-konusunu-secelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atlar', 'atlar-bekir-necati-q96fb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Atlar ki,

Çıplak çayırların üzerinde

Dört nala 

Çırıl çıplak, 

Çayırların üzerinde,

Yele karşı.

Eğersiz sırtları,

Gemsiz ağızları,

Nefes nefese.

Koşuyorlar hala,

Rüzgar kanatlılar

Koşuyorlar, 

Koşumsuz,

Alabildiğine çıplak çayırların üzerinde

Koşuyorlar hala, dört nala.

Koşuyorlar,

Eğersiz, 

Gemsiz,

Güneşe doğru...

Koşuyorlar rüzgarın oğluna

Soluk soluğa…', 'Atlar ki, Çıplak çayırların üzerinde Dört nala  Çırıl çıplak,  Çayırların üzerinde, Yele karşı. Eğersiz sırtları, Gemsiz ağızları, Nefes nef...', ARRAY['Türk Edebiyatı','Şiir','Bekir Necati']::text[], 8.5, '{"poet":"Bekir Necati","poet_slug":"bekir-necati","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/atlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Gülün Hikayesi', 'beyaz-gulun-hikayesi-duygu-devrim-8qqg5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer ki sevgilim ölürsem sensiz

Elinde bir beyaz gülle Beni uğurla! 

Daha öldüğümün ilk gecesi 

Girmezsem rüyana,

Beyaz güllerle süslü o yastığını parçala....

Ve aradan geçsede uzun yıllar 

Güneşli, güzel bir günde 

Yapayalnız yürürken yollarda 

Düşerse yanağına bir damla yaş

Beyaz bir mendille kurula

Ve bilki, hala seni seviyor

Hala, senin için ağlıyorumdur.

Ve gün gelirde unutursan beni

Seversen başka birini

Anlat ona! 

Anlat nasıl sevdiğimizi...

Anlat sevdiğim! 

Beyaz gülün hikayesini.......', 'Eğer ki sevgilim ölürsem sensiz Elinde bir beyaz gülle Beni uğurla!  Daha öldüğümün ilk gecesi  Girmezsem rüyana, Beyaz güllerle süslü o yas...', ARRAY['Türk Edebiyatı','Şiir','Duygu Devrim']::text[], 8.5, '{"poet":"Duygu Devrim","poet_slug":"duygu-devrim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beyaz-gulun-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-deli-mavi-kuy4w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bazen bulut olup sardın başımı 

bazen şimşek çakıp yaktın saçımı 

yağmur gözlerinden saldın yaşımı 

ben senle ıslandım kurumam artık........murat aydın doma

şimdi uzaklarda gurbet eldesin

kuşun kanadında esen yeldesin

yüreğimde akıp coşan seldesin

gel desen burada duramam artık..........Hülya Ekmekçi

Bu alemde sensiz, neylerim gönül 

Yaktı beni derdin, soramam artık 

Canım sana feda, eylerim gönül 

Tutmuyor kollarım, saramam artık........Burhanettin Akdağ 

Nefesim yeterde,yaşarsam eğer 

O kadar beterde,değilmiş meğer 

Çekilen kederde,herşeye değer 

Gitme kal desede,kalamam artık..........Öner Tarık BERKUL

Ben bende duramam, canım sıkılır 

Mahzun bakışına, gönlüm takılır 

Gülmedi şu bahtım, kalbim kırılır 

Haramdır buralar, kalamam artık.........Burhanettin Akdağ

gurbet ele vardın kaldın derbeder 

günlerin ayların gam ile keder 

sel olur çağlarsın yoların gider 

ben sende bulandım durulmam artık.......murat aydın doma

Öyle sevmiştim ki, sevgilim seni 

Dünyam değişmişti, sorarken beni 

Bekledim gönlünü, bana vermeni 

Yine de gelmezsen, aramam artık.........Burhanettin Akdağ 

Tam otuz yıl oldu alıştım sana 

Sensiz koca dünya dar gelir bana 

Aldığın her nefes can verir canaİ 

İnan senden ayrı kakamam artık..........Ahmet Sefer Koçer

Seninle soludum, kızıl gülleri 

Seninle yaşadım, eşsiz günleri 

Seninle tanıdım, kara yelleri 

Yalvarsan burada, duramam artık.........Burhanettin Akdağ

Gösterdin hep bana, derin sevgini 

Tanımam cefada, senin dengini 

Çekilmez Veysel''in, sabır engini 

Ben sana kayıtsız, olamam artık.........Veysel KOŞAR 

Düşünce yâdıma, bir ışık seli 

Gözlerim arar da bulamaz seni 

Hasretin gönlümün dinmeyen yeli 

Dönüşü yoktur o yılların artık..........Hasan Ekrem 

Zorluklarla geçti senelerimiz 

Ama yılmadık hiç karagözlü can 

Daim perçinleşti saygı sevgimiz 

Son bulsun zorluklar gülelim artık.......Fatma Çağlayan

Doluya doldurdum; dolu almadı, 

Boşa koydum; bu kez boştu,dolmadı 

Senelerce kurdum, gerçek olmadı,. 

Düşlerimi hayra yoramam artık...........İ.Yavuz Bildik

Bakmayı bilmedin, hep şaşı gördün, 

Acın acım idi, derdimdi derdin, 

Tamiri mümkün mü kalbimi kırdın, 

Hüsn-ü cihan olsan aramam artık..........Şahin Yılmaz

Bir selvi boyluya yaktık abayı 

Toy-düğün eyledik kurduk yuvayı 

Küçücük bir köyde yaptık balayı 

Sensiz saraylarda duramam artık..........Ahmet Sefer Koçer

Gün oldu zirvede savurdum estim, 

Gün geldi dilimde kelâmı kestim 

Artık kahırlıyım,kendime küstüm, 

Gönlümün karını küremem artık............İ.Yavuz Bildik 

Şarkımız dillerde söylensin artık 

Nağmeler tellerde çalınsın artık 

gözümüz yollarda bilinsin artık 

Sensiz bu ellerde yapamam artık.........Öner Tarık BERKUL 

Ekmek kavgası için gurbetteyim ben 

Çoluk çocuğuma hasretteyim ben 

Yaşamdan bıkmışım nefretteyim ben 

Gelmek istesemde gelemem artık..........İbrahim Coşar

Kimse bilmez sen bilirsin halimi 

Düşüp kalktım,bir sen tuttun elimi 

Kırdı ise dağla benim dilimi 

İnanki ben sensiz olamam artık..........Ahmet Sefer Koçer

Sensiz geçen günler, büktü belimi 

Koparttı yalnızlık, gönül telimi 

Artık kim tutacak, öksüz elimi 

Sevdayı bir daha, göremem artık.........Burhanettin Akdağ

Ömrümce hep seni aramışım ben 

Simdi yüreğimde kanımdasın sen 

Yaşamın anlamı yerleşti kalbime 

Sevda nağmeleri hiç susmaz artık........Fatma Çağlayan

Sokak lambaları, bir bir yanarken

Adımlarım yavaş, seni anarken

Şüphelenir yağmur, tene konarken

Ağlayan kim acep, bilemem artık.........Hülya Ekmekçi

ateşlere düştüm sularda kandım 

bülbülün dilinde güllerde yandım 

teninde kendimi sarmaşık sandım 

sarıldım dalına soyulmam artık..........Murat Aydın Doma

Bir kez daha geldi, sevgili günü 

Neleri kaybettin, hatırla dünü 

Belki de yaşardık, şimdi bugünü 

Kalbine gülleri, deremem artık..........Burhanettin Akdağ

Bir sevda besledim sana pek yaman 

Eşiğine varıp dilerim aman 

Ömrüm sona erip geçmekte zaman 

Bu postu kapına seremem artık...........Şemsettin DERVİŞOĞLU

Bana mı kızmışsın, kaşda sitem var, 

El ayak soğumuş, tende matem var, 

Dudaklar küsmüş mü, neden hatem var, 

Boynu bükük sana, bakarım artık..........Veysel KOŞAR

Sevda düşleriyle yatıp uykuya 

Eş tutardım seni,gökteki aya. 

İster balveren ol,ister papatya 

Balına konmayı istemem artık! .............Dursun Elmas

Öyle yorgunum ki, kalkmıyor elim 

Öyle üzgünüm ki, bitmiyor zulüm 

Öyle kırgınım ki, tutmuyor dalım 

Yalvarsan da şimdi, duramam artık.........Burhanettin Akdağ

Zirveme kar oldun, düştün başıma 

Titreyen dil oldum,güldün halıma 

Musalladır kalbim, girdin kanıma 

İki can bir teniz, bilesin artık..........Veysel KOŞAR

dağlar der ki bana, şimdi başım kar

hele yarın ola, yazdan haber var

olmayacak asla, sana ova dar

bundan böyle güze, darılmam artık............Hülya Ekmekçi', 'bazen bulut olup sardın başımı  bazen şimşek çakıp yaktın saçımı  yağmur gözlerinden saldın yaşımı  ben senle ıslandım kurumam artık...........', ARRAY['Türk Edebiyatı','Şiir','Deli Mavi']::text[], 8.5, '{"poet":"Deli Mavi","poet_slug":"deli-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/sevgiliye-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Büyüyen Bir Yangın Yokluğun', 'i-cimde-buyuyen-bir-yangin-yoklugun-atilla-guler-nvngz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah’ım

biliyorum

nedir hazzımdan doğan günahlarım

...düşlerimde oynaşıyor kızıl aşüfte

türküler çağlıyor kalbimde

yakası bağrı açılmadık

halaya durmuş allı güllü

soluğumda dolanır şehvet

davula vurulduğunda çıkan her seste

…aşk/benzeri bir titreyiş

sadece seninle

dinle

bizi anlatıyor şiirde inleyen her dize

ne denli uzak olsa da

oyunlar oynar sevda

sımsıcak

yüreğe vurulmuş mutluluğun rüyası içinde

esaretindeyiz yangınların

küçülür okyanuslar

kuzey daha da yaklaşır güneye

gülücükler yapışır gözlere

bak…güneş doğmuş yüreklerde

inanmasa da başkaları 

dokun…içine çek nefesinle

gör…nasıl koşuyor mutluluk

bizden yana

sen her çaldığında aklımı

kaybolurum düşler diyarının rengarenk yollarında

biliyorum

nedir günahlarım

gerçek yalan olamaz ki

içimde...sıcağın/yangının

…kösnül bir hara düşmüş beden

şiirlerimden yükselecek alev

kurtuluş yok…biliyorum

çekiyor günahları aşknatıs

kaçmıyorum', 'Allah’ım biliyorum nedir hazzımdan doğan günahlarım ...düşlerimde oynaşıyor kızıl aşüfte türküler çağlıyor kalbimde yakası bağrı açılmadık h...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/icimde-buyuyen-bir-yangin-yoklugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Ne Yaparsa Kendine Yapar', 'kim-ne-yaparsa-kendine-yapar-yusuf-onder-bahceci-p99rm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Meydanı boş bulanlar, hep atıp, tutuyor,

Benim Necip Milletim se bakıp duruyor,

Allah korkusu olmayanlar, çok aldatıyor,

Diyorum kim ne yaparsa kendine yapar.

Siz istediğiniz kadar parke taşları sökün,

İç çamaşırlarınızı çıkartın her yerinizi açın,

Biz sadece sizlere acırız, derdiniz ne için,

Diyorum kim ne yaparsa kendine yapar.

Adam bağırıyor ne yapayım aç mı öleyim,

Rezilce soyunmuş, böyle dikkat çekeyim,

İnşallah gazeteler çeker, bir de göreyim,

Diyorum kim ne yaparsa kendine yapar.

Bırakın bu lafları, simit satanlara hayranım,

Ekmeğin yanında varsa, katıkdan ayranım,

Kâlbim hep Allah''a şükreder işte beyanım,

Diyorum kim ne yaparsa kendine yapar...', 'Meydanı boş bulanlar, hep atıp, tutuyor, Benim Necip Milletim se bakıp duruyor, Allah korkusu olmayanlar, çok aldatıyor, Diyorum kim ne yapa...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kim-ne-yaparsa-kendine-yapar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Bilmek... (Çocuk Şiirleri 6)', 'sevmeyi-bilmek-cocuk-siirleri-6-mehmet-ayhan-gunaydin-obpwe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEVMEYİ BİLMEK

 (Çocuk Şiirleri 6) 

Allah bana akıl vermiş,

Düşün, öğren, bil demiş.

Başıma da  iki göz,

Her şeyleri gör demiş.

Annem söyledi bir de,

Sevmek için kalp vermiş,

Güzel olur sevince,

Sevmek ki gerekliymiş.

Başka yere sığmazmış,

Kainatı Yaratan.

Tek bir yere sığarmış,

Annem söyledi inan.

O yer, benim kalbimmiş,

Diğer adı yürekmiş.

İçimde taşıdığım,

Meğer, ne büyük şeymiş.

Onun için önemli,

Sevmeyi öğrenmeli,

Herkesi ve her şeyi,

O yüzden sevmeliymiş.

M. Ayhan Günaydın.

    20 Şubat 2006 

          Ankara', 'SEVMEYİ BİLMEK  (Çocuk Şiirleri 6)  Allah bana akıl vermiş, Düşün, öğren, bil demiş. Başıma da  iki göz, Her şeyleri gör demiş. Annem söyled...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevmeyi-bilmek-cocuk-siirleri-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gittikçe ben...', 'sen-gittikce-ben-evren-dalgic-aun8h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şehir sana muhtaçtı; 

ve sessizdi sen giderken bağrından.

usulca diz çökmüştü bastığın kaldırımlar

boynunu bükmüştü o sevdiğin şarkılar.

ya ben; 

ben kime kalmıştım böyle 

hangi yamalı hayalleredir çırpınışlar.

yazık ki yokluğuna gebe bir gecenin; 

kucağına düşmüş zavallı biriyim.

yalnızlığımla dertli; 

hasretinle kederli penceremde,

donuk bakışlarımı ela gözlerine takıp; 

hüznümden soğuk bir nefes daha çekmeliyim.

ve gövdemi eğmeliyim hasretinin karşısında; 

boynumu koymalıyım hasret satırının altına; 

sen gittikçe ben; 

yüreğimde bir ben daha öldürmeliyim

(Ankara 2006)', 'şehir sana muhtaçtı;  ve sessizdi sen giderken bağrından. usulca diz çökmüştü bastığın kaldırımlar boynunu bükmüştü o sevdiğin şarkılar. ya ...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-gittikce-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yöneticiler', 'yoneticiler-yalanci-murat-t82cg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir synyf bu yöneticiler 

Gerçekten de yetenekli ki?iler. 

Bir yöneticiye bir araba çarpmy? bir gün ve kolu kopmu?

Tazminat istememi? ve i?inin ya?amyna yansytty?y aly?kanlyk üzere 

“Öbür kolum yerinde ya daha ne isteyim” demi?

Öyle ya evi arabasy ve taksitlere gidecek parasy olduktan sonra 

Yyi bir ?ekilde ya?atacak kadar yani

Kime ne kadar para kazandyrmy? 

Kim bunun hakkyny ne kadar çalmy? 

Ne fark eder? 

Kraldan çok kralcy, 

Çok kazandyran iyi ya?ayan ve böylece de soyulmaya boyun e?mekte mantyk bulan

Gerçekten de yetenekli ki?iler. 

Hakkyny aramayan köpektir lafyny 

Tarihe gömen, 

Nazik kibar zeki 

ve enayi 

Yöneticiler.', 'Bir synyf bu yöneticiler  Gerçekten de yetenekli ki?iler.  Bir yöneticiye bir araba çarpmy? bir gün ve kolu kopmu? Tazminat istememi? ve i?i...', ARRAY['Türk Edebiyatı','Şiir','Yalancı Murat']::text[], 8.5, '{"poet":"Yalancı Murat","poet_slug":"yalanci-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yoneticiler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseriler', 'serseriler-yalanci-murat-6jdhz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Serseriler bir ö?leden sonra zincirlerinden bo?andylar 

Kah hüzün kah vurdumduymazlykla

Serseriler 

Bulabildikleri her ?eyi içtiler. 

Serseriler ertesi gün pi?mandy yaptyklaryna 

Bu yüzden güne?in tekrar ba?tan çykarycy co?turucu etkisini beklemeye ba?ladylar 

Güne? bir çyksyndy 

Hayat zaten zincirden bo?anyrcasyna hareket etmelerini gerektirecek fenalyklary yapardy

Güne? bir çyksyndy 

Serseriler pi?manly?y bak nasyl da unutacaklardy. 

Serseriler bir güne bir bulut kesi?i 

Serseriler zamanyn içinde zamandan hyzly.', 'Serseriler bir ö?leden sonra zincirlerinden bo?andylar  Kah hüzün kah vurdumduymazlykla Serseriler  Bulabildikleri her ?eyi içtiler.  Serser...', ARRAY['Türk Edebiyatı','Şiir','Yalancı Murat']::text[], 8.5, '{"poet":"Yalancı Murat","poet_slug":"yalanci-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/serseriler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehrin Geceleri', 'bu-sehrin-geceleri-omer-karakas-94tdr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alaca karanlığın ıslattığı sokakta

Başım önüme düşmüş, ruh gibi yürüyorum

Yar diyorum, acab yar durur hangi durakta

Gel-gitler arasına sıkışmış soruyorum.

Üç-beş tane yıldızı zor seçiyorum yalnız

Ay kaçında bu akşam bulutlar arkasında

Perde perde uzanmış gölgelerden bir deniz

Ve her biri korkumun sanki şahikasında

Ne bir eşlik eden var geçerken onca cengi

Sineme cesareti ne körükleyen berdüş

Ve öyleki, mekanlar giymiş o ander rengi

Gecenin kucağında ölü doğarken her düş

Yalnızlık gırdabına mı düşmüş arabalar? 

Çıldırtan sessizliğin kesilmez mi hiç sesi? 

Bu gönül sevgilide ne bulur da çabalar? 

...Ki kavuşma uğruna heba eder kafesi? 

Bu ayrılık acısı, sonu gelmez hezeyan

Sürgünleri vermekten geri durmaz her gece

Ve ölüm soğuğunu hissettirdikçe zaman

Sanki; düşmemi bekler kuytulardan bin cüce

Sahibinin kovduğu sokak kedisi gibi

Yarasa anılarda teselli arıyorum

Ah, ander koca şehir; ah, gönlümün sahibi! 

Bir gün yüzü gösterin, kaçtır yalvarıyorum....', 'Alaca karanlığın ıslattığı sokakta Başım önüme düşmüş, ruh gibi yürüyorum Yar diyorum, acab yar durur hangi durakta Gel-gitler arasına sıkış...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karakaş']::text[], 8.5, '{"poet":"Ömer Karakaş","poet_slug":"omer-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-sehrin-geceleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Üç', 'on-uc-yalanci-murat-wzx2x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'On üç uzun gün sonra yanynda olaca?ym 

Saçlaryny da?ytaca?ym uykuya dalacaksyn 

Sonra deniz kenarynda elimi tutacak küçük elin

On üç gün var aramyzdan senin ile benim. 

Bu ?iiri her gün bir eksilterek yazaca?ym 

Geçen her saniye susuzlu?umu gideren bir damla 

Kalan her saniye syrtymda kyrbaç 

On üç uzun gün sonra oradayym.', 'On üç uzun gün sonra yanynda olaca?ym  Saçlaryny da?ytaca?ym uykuya dalacaksyn  Sonra deniz kenarynda elimi tutacak küçük elin On üç gün var...', ARRAY['Türk Edebiyatı','Şiir','Yalancı Murat']::text[], 8.5, '{"poet":"Yalancı Murat","poet_slug":"yalanci-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/on-uc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir dost.', 'bir-dost-dilek-kadioglu-56msp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Meral Özcan''a 

..........................İthaf olur..

Güldüğünde güller açar yüzünde 

Her mevsim bahar olur

Güneş sıcaklığını yitirir 

Sımsıcak yüreğinin yanında

Okyanus kadar derindir 

Yüreğinde ki sevgi

Gözlerinde ki güzelliği 

Bakmasını bilen görür

Yüreğinde ki sevgiyi

Hissetmek isteyen anlar

Gözlerinde ki parıltı yarı ağlamaklı 

Dokunsan damlamaya hazır birkaç damla

Hüzün birikintisi var göz bebeklerinde 

Gözlerinin arkasına sığınarak susar 

Sezdirmez

Hissettirmez

Susar…

Tanıyanlar bilirler 

Çocuksu yüreğini

Elma şekeri,

Kağıt helva 

Uçan balon

Mutlu etmeye yeter 

Çocuksu yüreği

Hiç düşünmeden 

Saklambaç oynayabilir 

Hüznünün arkasına sığınarak

Adının manasını taşıyor

Dişi ceylan 

Uysal 

Sessiz 

Sakin

Gözlerindeki çocuksu bakışın

Yüreğinden sevgi tomurcuğu

Umutların hayallerin

Sana senin kadar yakın olsun

Bir dost..', 'Meral Özcan''a  ..........................İthaf olur.. Güldüğünde güller açar yüzünde  Her mevsim bahar olur Güneş sıcaklığını yitirir  Sımsı...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bir-dost-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitap Okuma Üzerine', 'kitap-okuma-uzerine-yalanci-murat-2zb18', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yok zaten belli fikrin savunucusu belli bir yolun yolcusu kitaplar ve görmek istedi?ini görmek için okuyanlara için de?il laflarym 

Fakat sayyn okurlarym 

Dikkat ediniz büyük ve ba?ymsyz yazarlary okurken hiç tarty?mayyz o zatlarla. 

Ço?u büyük yazarlar nice fikirler sürerler 

Hemen hemen her ?eyle ilgili 

Fakat neden kabul ederiz ki onlary hemencecik? 

Oysa her büyük yazar her büyük kitap ve içindeki türlü saptamalar 

Do?ru mu de?il mi tarty?masynyn önünü açarlar bizlere. 

Okura dü?en tarty?maktyr büyük yazaryn fikirleri üzerinde

Kendiyle ve ölüyle.', 'Yok zaten belli fikrin savunucusu belli bir yolun yolcusu kitaplar ve görmek istedi?ini görmek için okuyanlara için de?il laflarym  Fakat sa...', ARRAY['Türk Edebiyatı','Şiir','Yalancı Murat']::text[], 8.5, '{"poet":"Yalancı Murat","poet_slug":"yalanci-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kitap-okuma-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Al', 'beni-al-oguzkan-bolukbasi-eomlk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlhamım yaşamaktan gayrı ne olabilir

Ağlamaktan çok uzakta değil kahkahalar

Zaman

Hem saklar, hem de paklar kirini

Sabretmek dedikleri budur

Yoksa aldığın her lokma boğazına otururdu

Günahkar adapların aşk bozgunları varken

Gözlerini kapadığında ne görüyorsan o benim

Ya hiçbir şey, ya içindir 

Nereye saklandıysam

Nerede yakalandıysam

Teninde dolaşırken ellerim

Yaşam en doyulmaz biçimdir dudaklarında

Dudakların en güzel seçimdir

Bunca kötülük varken aşk niye

Peki desem ki

Aşk varken bunca kötülük niye

/İlhamım yaşamaktan gayrı ne olabilir

Ağlamaktan çok uzakta değil kahkahalar/

Bahçesine saklandığım çiçekler gibi kokuyorsun

Rüzgarın estiği yöndeyim

Sen yoksan da kokunu taşıyan rüzgarın…

Yine dudakların diyeceğim

Nedir diyeceksin bu dudaklara düşkünlüğün

Her serüven dudaklarda başlar önce

Ama ben hasretim dudaklarına

Belki sana küskünlüğüm dür dudakların

Öpsen geçecek acılarım

Gözlerini kapadığında ne görüyorsan o benim

Beni al……', 'İlhamım yaşamaktan gayrı ne olabilir Ağlamaktan çok uzakta değil kahkahalar Zaman Hem saklar, hem de paklar kirini Sabretmek dedikleri budur...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/beni-al-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleşelim Gönül Dilinden', 'soyleselim-gonul-dilinden-yusuf-onder-bahceci-hvymh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel seninle söyleşelim şöyle gönül dilinden,

İnsanların kâlbini bilirsin gözlerinin dilinden,

Bu insanlar selamette iseler senin dilinden,

Dostum sana ne mutlu diyorum, dilimden. 

İnsanları eşşek arısı gibi dalamamak gerek,

Katırlar gibi çifteleri de savurmamak gerek,

Eşşek gibi, böylesi inatlara, varmıdır gerek

Gel seninle söyleşelim şöyle gönül dilinden.

Atın huyu iyidir diyorsun seni sırtından atıyor,

Develer çok kindar bir gün intikamını alıyor,

Filleri sorma kafaları atınca dümdüz ediyor,

Gel seninle söyleşelim şöyle gönül dilinden.

Lamaya az yaklaşıyorsun, yüzüne tükürüyor,

Maymun sana acaip el, kol hareketi yapıyor,

Ayılar ormanda geziyor insanlara saldırıyor,

Gel seninle söyleşelim şöyle gönül dilinden.

Yılanlar yerde sürünüyor, sessizce sokuyor,

Sivrisinek çok küçük lakin kanımızı emiyor,

Devekuşlarının nasıl olduğu pek bilinmiyor,

Gel seninle söyleşelim şöyle gönül dilinden.

Horozlar şu zavallı tavukları rahat koymuyor,

Çuluk öyle kabarıyor, en büyük benim diyor,

Kargalar o acaip sesleriyle feryatlar ediyor,

Gel seninle söyleşelim şöyle gönül dilinden.

Güvercinlere pek lafım yok, güzeldir vallahi,

Kartallar, şahinler av peşinde gezer, billahi,

Avcıların tüfeği ise her an yanında olur ilahi,

Gel seninle söyleşelim şöyle gönül dilinden.

Hayvanların meziyeti çok saymakla bitmez,

İnsanda ki huylar hayvanlarla kıyas edilmez,

Ahseni Takvin üzere yaratmış eziyet etmez,

Gel seninle söyleşelim şöyle gönül dilinden....', 'Gel seninle söyleşelim şöyle gönül dilinden, İnsanların kâlbini bilirsin gözlerinin dilinden, Bu insanlar selamette iseler senin dilinden, D...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/soyleselim-gonul-dilinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayalı Göl (Bu Göl Çok Maya Tutar)', 'mayali-gol-bu-gol-cok-maya-tutar-salih-erdem-hguzi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kanunları tart’ıymış

Ülkem için art’ıymış

Medeniyet şartıymış 

Gölümüz maya tutar

Önce birlik dağılsın

Düşmanların ağılsın

Sütlü memen sağılsın

Postumuz saya çıkar

Hürmet saydın şer yüzü

Doğru bildin her sözü 

Badem ettin kör gözü

Ceddime boya katar

Varlığınla fakirsin

Emsaline hakirsin

Borçlarına şükürsün

Yoksulum kaya yutar

Memleketi bir dolaş

Okul cami şer bulaş

Yoktan yere hır dalaş

Huzurum kıya batar

Atan çizmiş bak düne

Kutlu yoldur git güne

Yengeç gibi yan yana

Menzilim haya tutar

Erdemoğlu kalk uyan

Kudretine tut dayan

Dudağına söz ziyan 

Arsızım hayâ satar

16.12.2005 17:23 AYDIN', 'Kanunları tart’ıymış Ülkem için art’ıymış Medeniyet şartıymış  Gölümüz maya tutar Önce birlik dağılsın Düşmanların ağılsın Sütlü memen sağıl...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mayali-gol-bu-gol-cok-maya-tutar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Yollara', 'dus-yollara-rifki-kaymaz-5afbk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öteye hasret ruhum...

- Düş yollara yollara! 

Orda mesut olursun,

- Düş yollara yollara! 

Uçursa beni rüzgar,

Uçursa diyar diyar.

Ah...Orada neler var

- Düş yollara yollara! 

Ora dağdır içimde,

Ve en güzel biçimde...

Yollar yumak içimde,

- Düş yollara yollara! 

Kilitli kabukta öz...

Eşyadan yıldı bu göz.

Ufuk, ellerimi çöz! 

- Düş yollara yollara! 

Rıfkı Kaymaz', 'Öteye hasret ruhum... - Düş yollara yollara!  Orda mesut olursun, - Düş yollara yollara!  Uçursa beni rüzgar, Uçursa diyar diyar. Ah...Orada...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dus-yollara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıvılcım Hazine', 'kivilcim-hazine-omer-dalman-te5x9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne Marquise De Sade''lar

ne Dostevski''ler

ne Yunus''lar

hatta Gothe''ler dolanıyordur aslında aramızda da

çığırtkanlar gibi gür, cengaverler gibi sert

ortaya çıkmak

bu zamanda kimin harcı? ! 

hele Bura''da! 

kolay mı o kadar! ? 

uy, sesini kes, kolla arkayı

ver sırtını bir duvara zamanı bu yeğenim! 

kolay olur mu o kadar ha? ! ..

o senin dediğin eskidendi...

hakkı verilmiş aşkların

hakkı savunulmuş doğrular''ın

uğruna ölünmüş ideallerin

tadına doyulamayan sapkınlıkların

cesaretle not edildiği artık birer anı

birer efsane! 

''ulaşılması güç'' damgası vurulmuş

aslında ulaşılması istenmeyen

keşfi bir kıvılcım kadar kolay hazine...

(Şubat 2006)', 'Ne Marquise De Sade''lar ne Dostevski''ler ne Yunus''lar hatta Gothe''ler dolanıyordur aslında aramızda da çığırtkanlar gibi gür, cengaverler gi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kivilcim-hazine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asalak', 'asalak-kamer-taskin-cvvfz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nefesinde soludum,

Koşuşunda yoruldum,

Duruşunda dinlendim, 

Üzüntünde ağladım,

Neşende güldüm,

Asalak sandın,

Anlamadın, a salak', 'Nefesinde soludum, Koşuşunda yoruldum, Duruşunda dinlendim,  Üzüntünde ağladım, Neşende güldüm, Asalak sandın, Anlamadın, a salak...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/asalak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-nevzat-ozkan-bogbk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gören gözler görmüyor

gözlük taksan ne fayda.

Veysel olup görmesen

görsen,

görenlerden fazla.', 'gören gözler görmüyor gözlük taksan ne fayda. Veysel olup görmesen görsen, görenlerden fazla....', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozler-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincire vurdum.', 'zincire-vurdum-i-shak-ozlu-vfje6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seven yüreğimi zincire vurdum,

Sevdayı duyan halkalar çözüldü.

Yedi kapılı zından kurdum,

Dört duvarından gözyaşı süzüldü.

Yürek içten içe göz dıştan ağlar,

Yare adanmış sözlerim yas bağlar.

Gönül ferman bulsa yarin yoluna,

Kavuşmaya yol verir dağlar taşlar.', 'Seven yüreğimi zincire vurdum, Sevdayı duyan halkalar çözüldü. Yedi kapılı zından kurdum, Dört duvarından gözyaşı süzüldü. Yürek içten içe g...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zincire-vurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz üşüyorum', 'sensiz-usuyorum-begum-aysal-ags2i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmurlar ıslatamıyor beni

ayazlar üşütmüyor

seni düşünürken ben

hayat duruyor 

tüm mevsimler sana özeniyor

ağlayamıorum sensiz

boğazıma birşeyler düğümleniyor ama

yutkunamıyorum 

ellerimde Umudum seni bekliyorum

herşeyi siliyorum

bir sen kalıyosun yüreğimdeki resimlerde

şimdi fırça ellerimde

her yere senin adını yazıorum

seni özledikçe içim acıyor

acıdıkça kan damlıyor

ve ben her kızıllığa seni anlatıyorum

böylelikle her yanımda senin adın dolaşıyor

ve sen mevsimlerin adı oluyorsun 

çünkü benim her yanımda mevsimler dolaşıyor

bir yanım yazken öteki yanım kara kış oluyor

o yüzden ben seni severken üşüyorum

ben sensizken üşüyorum', 'yağmurlar ıslatamıyor beni ayazlar üşütmüyor seni düşünürken ben hayat duruyor  tüm mevsimler sana özeniyor ağlayamıorum sensiz boğazıma bir...', ARRAY['Türk Edebiyatı','Şiir','Begüm Aysal']::text[], 8.5, '{"poet":"Begüm Aysal","poet_slug":"begum-aysal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-usuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günüm', 'dogum-gunum-neslihan-uzel-1y980', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şubatın sonu, en kısa ay... 

Doğmadan çalmış şans ömrümden bir kaç günü...

Dostlar kutladılar bir bir, hepsi mutluydular

İyi ki doğdum! iyi ki varım! 

Ne düşler, ne hayaller, ne özlemler yitip gitmiş

Anımsamıyorum. 

Dolaştım sokakları,  yağmur yağıyordu

Bilmem ki... ne arıyordum

Koybolmuş düşlerimi gördüm köşe başlarında

Islanmışlar

Her dönemeçte vurdular yüzüme soğuk nefeslerini

Kalleş! Dercesine

Bir maviye satmıştım düşlerimi 

Gördüm kabus olmuşlardı

Yitirdiğim hayallerim oynaşıyordu sokak lambalarının harelerinde

Ya özlemlerim? Onlar hala benimlemi? 

İyi ki doğdum! İyi ki varım! 

Yağmur yağıyordu, 

Sokaklarda bilmem ki... ne arıyordum.

19 şubat 2006', 'Şubatın sonu, en kısa ay...  Doğmadan çalmış şans ömrümden bir kaç günü... Dostlar kutladılar bir bir, hepsi mutluydular İyi ki doğdum! iyi ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Üzel']::text[], 8.5, '{"poet":"Neslihan Üzel","poet_slug":"neslihan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dogum-gunum-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamamen duygusal...', 'tamamen-duygusal-reyhan-tataroglu-p12zx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dokunsalar ağlayacağım; 

                                   kimsesizler,kimi sessizler

                                   başı okşanmadık yetimler

                                   hayatın kötülüklerine itilmiş

                                   bitirimler...

                                   sahipsiz gençler

                                   anlamsız sevinçler

                                   elleri öpülesi

                                   sırtlarda, başlarda 

                                   gezdirilesi...

                                   kiminin babası

                                   kiminin annesi

                                   babaannesi, dedesi 

                                   belkide ninesi...

                                   terk edilmişler...

                                   işsizler güçsüzler

                                   suçunu bilmeyen

                                   suçsuzlar

                                   açlar, açıklar

                                   akıllılar, kaçıklar

                                   ağlayanlar, üzülenler

                                   yalnızlıkta süzülenler

                                   sevipte sevilmeyenler

                                   sevilipte sevmeyenler

                                   mazlumlar, garipler

                                   çaresizlikten muzdaripler

                                   mutsuzlar, umutsuzlar

                                   katıksız sofralardaki tuzlar

                                   ölüler,diriler

                                   gelip giden biriler...

                                   daha neler neler...

                                   dokunmuyor gurban dokunmuyor 

                                   dokunsalar ağlayacağım; 

                                   hem de susmamak üzere...', 'dokunsalar ağlayacağım;                                     kimsesizler,kimi sessizler                                    başı okşanmadık ye...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/tamamen-duygusal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancıyla büyür özlem', 'sanciyla-buyur-ozlem-selahattin-yetgin-jq7pd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sancıyla büyüyen bir özlemin derinliklerine

denizin dalgaları hüzün taşıyorlar durmadan

kırmızı ağlarken yoruluyorum düşünmekten

kaybolmuş bir zamanın anıtlarını arıyorum

yoksun işte yüreğimdeki hatıralarla öksüzüm

özlemine sığındığım gecelerde uzak evlerdeyim

duvarlara adını işliyor yalnızlığımı didikliyorum

gecenin saçaklarına takılıyor seninle şu bedenim

fısıltının ormanlarında seni soruyor bulamıyorum

yoksun işte sevdanın kanını denizlere tükürüyorum

gelebilme ihtimallerinin tedavülsüz kayıtlarında

olup olmadık yerde sen geliyorsun aklıma fikrime

bir deniz iken yol aldığım korsanları yitik sularda

gümüşleri saklı ormanlarda kalıntılarını arıyorum

yoksun işte şarkılarla dost onlarla bile güçsüzüm

bir kar tanesince inmeyi beklerim gecelerde üstüne

sabun misali avucumdan kayan zamana aldırmayarak

umut pazarlarında yüreğini arıyorum yolunda sürünerek

şimdi yoksun göğsümdeki bu hançerle yaşayamıyorum

uykusuz gözlerimdeki tutkunun perdesini çekemiyorum

düş gülü yetiştirmişim seni sevdikçe özlem bahçemde

ipsiz uçurtmaların peşinden türkülerle aradım ben seni

çok denedim sensiz ölmeyi gözlerinde kurşunlanmayı

şimdi yoksun haberin olmasa da hatıralarını okşuyorum

baharların erken bittiği bu koca kentte sensiz ömürsüzüm', 'sancıyla büyüyen bir özlemin derinliklerine denizin dalgaları hüzün taşıyorlar durmadan kırmızı ağlarken yoruluyorum düşünmekten kaybolmuş b...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sanciyla-buyur-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TeZaT...', 'tezat-erhan-demir-k9q3l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi, sonsuz

Aşk, akan nehir

Hayat, acımasız

Unutmak, zor

Yaşamak, güzel

Alışmak korkulu

Ömür, sınırlı

Dünya, fani

Ölüm, garanti

Bu dünya yalanmış 

Anladım... 

Bu dünya ölümlüymüş

Ağladım... 

Kimseye de kalmazmış

Sanmazdım.

Ama O''na kalacak...', 'Sevgi, sonsuz Aşk, akan nehir Hayat, acımasız Unutmak, zor Yaşamak, güzel Alışmak korkulu Ömür, sınırlı Dünya, fani Ölüm, garanti Bu dünya y...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tezat-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım kalan Şiir', 'yarim-kalan-siir-harun-kaya-3-dhexz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Az önce güzeller güzeli,

Binlerce yıl  süpürsede bu sokakları  az önce son gidişin,

Yaşlı sokak lambasının altında 

Sımsıcak bakışınla son kez içimi ısıtışın.

Kocaman bir soru işaretinin noktasına 

Zar zor tutunmuş zavallı yüreğim,

Vermiş ümitsizliğiyle sırt sırta çırpınır durur nafile.

Sevme desem sislenecek gözleri oyması yasak çocukcasına,

Ha desem coşacak  kapıp sürükleyecek önüne geleni deli fıratcasına.

En kötüsü sonunu bile bile,

Sonbahar yaprağı ve kurumuş bir  dal gibi 

Ayrı düşeceğimizi bile bile sana cevap verişim.

Ne aptalca...! 

Dün esrayı gördüm istiklal cadesinde,

Hani postanenin olduğu sokağın tam köşesinde,

Selam verecektim vaz geçtim...

Ne cevap verecektim  bana ne oldu büyük sevdanız,

Nerede şimdi uğruna öldüğün kadın derse? 

Ya ben sana söylemiştim aşk yalan, 

Yalanın ömrü yatsıya kadardı derse. 

Ne dersin can özüm, ne dersin iki gözüm

Biz hatayı sevmeklemi yaptık sence,

Ama değilmidirki insanı toprağa, toprağı insana gömen,

Adamı adam eden bu amansız bu zamansız sevdaya gem vurmak imkansız.

Dilim alışmış bir kere  ne desen boş,

Aklımda sana bir türlü itiraf edemediğim sevgim,

Dudaklarımda sigara misali tiryakiliğim kahırlarımla,

Tam ortasında duruyorum kimsenin bitiremediği bu yolun.

Bir gözüm sizin sokağı gözler bir gözüm daha öbür,

Bir ayağım hadi git ona der bir ayağım bok yeme yerinde dur.

Öyle bunaldım ki bu ölesi benden,

Üçe kadar saysam bası versem mavzerin tetiğine diyorum,

Yusuf yusuflar ikiden sonrasını bilmiyor,

Atsam kendimi diyorum uçsuz dipsiz kuyulara,

Bacaklarıma sözüm geçmiyor,

Yani anlayacağın  hayatımın sahibi,

Boşa koysam dolmuyor, 

Doluya koysam, damlalar kan gölü oluyor.

Bazen eski günlerim gelip yansıyor rakı şişesine,

Hani benim içmediğim senin beni terketmediğin günler,

Hala yarınlar için umut suladığımız,

Gözlerimizden sadece pembe yaşlar döktüğümüz anlar,

Düşündükçe düşümü yeşerten,

Yeşerdikçe kalbimi hoplatan anılar,

Sonra  beni terkedip gittiğin  ve bu şehri  yoldaş ettiğin 

Sonbaharın vazgeçilmezi yağmurlar,

Neydi seni bana düşman eden hatırlamıyorum bile,

Ne dersin gönül kuşum,

Sence biz hatayı konuşmamaktamı yaptık.

Sen bakma sitem ettiğime 

Belkide ben memnunum hayatımdan,

Hoşuma bile gidiyor içerken sohbet beklemek yalnızlığımdan,

Yalnızlığım bile sensiz iyice,

Sen olmayınca ayırmak isteyende yok kahırlarımdan.

Hani dedin ya sen olmayınca bana dar gelecek bu şehir diye,

Hani ağlardında dayanamazdım,

Doyamazdım bakmaya avuçlarımdaki yüzüne,

Gel gör şimdi beni inanamazsın görsen,

Tekmelemişler  gibi uykusuzluktan şişmiz gözlerime,

Aslında genede  sitemim yokya,

Birde dadanmasaydı  şu kanlar tükürüğüme.

Şikayet etmeyeceğim söz verdim kendime,

Binlerce sözle zincirlediğim 

Ve binlerce kez dinletemediğim gibi gönlüme,

Ooooooo  bak saat kaç olmuş, 

Rakımızda bitmiş iyimi, 

İstersen ben bir koşu gidip alayım,

Daha iyisi bir koşu alıp buralara hiç dönmeyeyim,

Kendine iyi bak olurmu güzeller güzeli,

Koy bir son yakıştırmayalım  sevdamıza,

İyi yada kötü bir kulp takmayalım aşkımıza,

Bırak gitsin,,,,

Bırak kaybolsun gözden dönüşü mechul göçmen kuşar gibi,

Her sene aynı mevsim acaba diye bekleyelim,

Başımız havada boynumuz tutulana dek izleyelim.

Her şey böyle bitmemiş sona ermemeiş kalsın aklında.

Bensiz sen..... 

Senden ziyade ben....

Tüketemediğim ömrüm.. 

Yada en önemlisi yarım kalmış bu şiir gibi...

                                Harun KAYA

(c)     bu şiirin her türlü telif hakkı şairin kendisine ve /veya temsilcisine aittir', 'Az önce güzeller güzeli, Binlerce yıl  süpürsede bu sokakları  az önce son gidişin, Yaşlı sokak lambasının altında  Sımsıcak bakışınla son k...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/yarim-kalan-siir-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biyografim..! ! !', 'biyografim-halis-tekel-r5b4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

                Ben tarih kaleminin yazamadığı yerden		Mülteci duygularımla geldim bu tarihe		namelere sığmayan dört dilden 			hepinizi selamlıyorum, muhabbet ile				

	ben notası bestesi yapılmamış bir sözün	arındırılarak yabancı kelimelerden			yabancı yazılan cümlenin, 				yetim noktasında geliyorum.				ve mahsun bülbülün kederli ıslığıyla			ve gülün bülbüle olan sevdasıyla 			hepinizi selamlıyorum saygılarla				

					

	II				

	evvela; insanım				

	iki kolum iki bacağım 				ve daha uçurulmamış birde kellem var				

	Karakaşlı karagözlüyümdür				ama yakışıklı olduğum söylenemez.				

	ne sağcıyım nede solcu				harita metoduyla hiç aram yok			

	bozuk yumurta kokusu kokan			ispiyoncu duygularım				sanatkar olmak çıkarcılığımdır			yoktan nakışlı maceramdır				bu benim hikayemdir…				

	III				

                güneş sımsıcak  ekmek misali ellerime düştüğünde	bir Pazar  sabanın mahurluğunda  doğdum					

	annem bir parça mavi deniz ile kundaklamıştı beni

                o gündendir denizin bende ki güzelliği, ve maviliği	oysa leğenin rengi maviymiş 			ben deniz sanmışım 					

	doğduktan iki hafta sonra gözlerim açılmıştı		yan komşumuz  fahriye teyze söylerdi			tıpkı maymuna benzermişim			

                yani kendisine benzermişim…			aman a duymasın…				allah rahmet eylesin					

					

                emzirirken beni annem hep dalardı		bazende, uyuya kalırdı				uyandırırken, süt kokan memelerini ısırırdım bazen	oradandır şu büyüklük korkum		saçlarımı okşarken, hep nemlenirdi gözleri		ağlamak geliyordu içinden				ama ağlayamıyordu				çünkü ağlarsa eğer 				benimde gözlerim  hoyratça çoşardı  o zaman…					

					

                günler geçtikçe…				yavaş yavaş sütten kesildiğini hissediyordum   annemin...	

                artık göz yaşıma anlam vermeye başladım	sebebsiz mi ağladım üç  yıl  boyunca 			elbette değil…					

                dört yaşında çözüldü dilimdeki kelepçeler		ve anne demeye başladım, 					

-ağlama bebeğim…				

-ben ağlarım anne					

-emzik ağzında neden hala ağlarsın…		

-büyümekten korkarım anne…					

	belli ki akıllı bir topraktan değilmişim.			anem beni büyütmek isterken 			ben koca yusufa inat 				çocuk olmak istiyorum derdim	

-Dur bekle yavrum beni dinle		

 Söyle yavrum, neden çocuk olmak istersin		

-Gözlerin görmez mi anne? 				

-Neyi yavrum…					

-görmek istemediklerini…		

-bilmezmisin yavrum büyüklük şahlıktır,,		

-sen insan doğurdun anne, deniz değil		

-Ne biçim bir hayattır yaşadığın.			

-Ben daha  ne yaşadım ki annem		

-Çıkart beni bu girdaptan			

  durdur içimde kayan toprakaları	

  tufanlar kopuyor beynimde     		

  söyle neden cocuk kalmak istersin			

-Tek sebeb için ağlamak				

-Hangi sebebtir böyle vijdansızca	

  musluklarını açar gözlerinin			

-Pişikten. Pişikten annem. Sadece pişikten…					

					

                  IV					

	

                Beş yaşında iki ayak üzerinde yürümeyi		altı yaşında küfretmeyi			

                yedi yaşında bir şeyleri özleyi öğrendim		sekiz yaşında, aşağı sokaktaki			sümüklü handana aşıktım…				dokuz yaşında iğrendim ondan			ve  vazgeçtim sevdasından				

	on yaşında babamı tanıdım			

                uzun boylu kaşın ortasında imza			menevişten uzaktı gözleri				kar yağmıştı inceden saçaklarına				

-Hanım oğlan hangi cehennemde…			

-Çocuk olmakta bey				

-Neden iş aş peşinden koşmaz hanım		

-Çünkü çocuk olmakta bey.				

-Bırak artık çocuk demeyi hanım 			

-Hakikat budur bey…				

-Hakikat karın doyurmaz bilmezmisin? 		

-Hakikat söylersin bey…					

					

                 V

              

                ilk saçları tarama devri rüzgar ile		

                ve şekiller vermeye başaladım hayata		Taş dedim				değil dedim					kuş dedim					Değil dedim					bulutlardan şüphelendim 				değil dedim					ve ressamlıktan vazgeçtim böylece			aynalarda…					

					

	

                 VI					

                yoktum ben artık olmayan yerlerde			sarı hazanlar geliyordu üzerime			büyüyordum artık				kahretsin ki büyüyorum					

	eski ayaklarım					eski başım					eski midem					eski annem değilim ben artık		

                on bir yaşında 			

                ölüm tehlikesiyim 					

	büyüdükçe büyüyorum				ve katili oluyorum  çocukluğumun  her gün		içimde suçluluk duygusunu hissederek		adam öldürmüşcesine ve geberirmişcesine		Vijdan azabı çekiyordum her sabah ezanından  sonra...				

                ölüm bana yakışmıyor anne				ölüm bana yakışmıyor…					

	

	VII			

	

                on dört yaşıma demir atarken			yosunlarını koklattılar hayatın 			sokak sokak aramaya başladım				

	boyalim mi abey				

	parlamasa bedava				

	VIII				

		

	şaşıyorum vallahi bu aşıklara			kırlarda hoplayıp zıplamak varken			ve deliler gibi sevişmek dururken			Kuru kuru ne bakarsınız şehire			neylesiniz... 				

	deniz mi sandınız? …				benim gibi…				

				

	IX			

					

	saat dokuzu çeyrek geçiyor 		heykeldeki kule söyler				kız kulesini anımsattı be				ikisini de görmedim ama				kime ne…				

					

                X				

					

	ekmek peşinden koşarken				hayatı dinledim kaldırımlardan			caddelerden, sokakalardan				yeşilden, kırmızıdan ve beyazdan			şekiller vermeye başladım hayellerime 		anlamsızca yürüdüğüm yollara, 			anlam vermeye başladım				on altı yaşımda…				

							imreniyorum				

	her şeye imreniyorum artık				Sokak köpeklerine 				Yerde ki sigara izmaritine				dört yaşında ki çocuğun küfrüne			başını gezegenden gezegene vuran sarhoşa		ve yolunu bilmiden yürüyen yolcuya			çalana, çırpana, 				

	vuruna, vurulana,				

					

	XI				15

					

	artık boğuluyordum				sığamıyordum bedenime				gün geçtikçe, türlü türlü acılar çekkiyordum,		ıssız bir yer gördüm mü				alırdım yüreğimi ellerime 				taştan taşa vururdum				

					

	nereye kadardı bu duygular				veya ne zaman son bulucaktı yaşantım		ne zaman bir şarkıyı ıslık yapıp			ellerimi cebime koyup 				kafamı eğmeden yüreyeceKtim				

	artık ağacımdan kopmalıydım		kendi şarkımı söylemeliydim mesela			rüzgara bırakmalıydım kendimi			bir şey beni kendine çeker 				

					

	evden kaçacaktım 				kararlıydım,				

	gece saat ikiydi,				

	karanlıktı, 				

	üstüme şu paltoyu alıp				

	kaçtım,				

	nefesim çırıl çıplak				

	heyecandan ölecektim,				durmadan koştum, koştum				durmadan				

	ama neden ağlıyorum				neden…				

					

                XII		

					

	buraya 				

	bursa dediler				

	gümüş kubbeli şehir			Yeşil cübbeli nehir				

	su bakiresi				

	Bakire meryem ana dediler				

					

	ve mülteci korkular				yalnızlık duydusu içerisinde				renklendirmeden dalgalandırdım bayrağımı		yürümeye başladım				akşam saatlerinde aheste aheste			ve sevişmeleri gördüm sokaklarda			ama ben sadece istikamet belirlemeden 		yürüyordum amaçsızca				

                bütün renklere sövüp saydım			siyah beyaz vaveyla anılarımı hatırlarken		gökyüzüne başımı kaldırıp 				gözyaşımın görmesini istedim yaratanın		çünkü içimde isyan bayrağı				küfür edermişcesine dalgalanıyordu.			renklere…

                ve yirmi dört yaşıma lüzümsüz yürüyorum....', 'I                 Ben tarih kaleminin yazamadığı yerden		Mülteci duygularımla geldim bu tarihe		namelere sığmayan dört dilden 			hepinizi se...', ARRAY['Türk Edebiyatı','Şiir','Halis Tekel']::text[], 8.5, '{"poet":"Halis Tekel","poet_slug":"halis-tekel","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/biyografim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla Sevdam', 'agla-sevdam-i-sa-tekin-mma43', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizim için bir umuttu yıldızlar

Gökyüzü ağlıyor şimdi

Venüs küskün yıldızlarımız kaydı

Bulutlar bir bir dağılıyor

Ve anılarımı yüreğime gömdüm

Ağla sevdam

Bıraktığın gibi değilim

Mor dağlara bakamam

Seherlerde uyanamam

Ben bende değilim

Güneşe bakamaz gözlerim

Ağla sevdam

Gökyüzüne bakamıyorum artık

Mavi sevdalar benden uzak

Uykusuz geceler hain birer tuzak

Olsanda olmasanda bu sevda benden uzak

Geçmişe çizgi çektim

Ağla sevdam

Bakır rengi umutlarım paslandı

Kalaylayamıyor acı çeken yüreğim

Dokuz şiddetinde zelzele yedim

Her yanım dağılmış yaralıyım

Pişmanlıklar fayda etmiyor

Ağla sevdam

Sevdamızın yıllanmış mavisine

Canım can çekişmekte

Bağrım yanmaktadır kor kor

O da üç damla gözyaşı ile söner

Ve söndükçe bu alev

Yanma sırası sendedir

Ağla sevdam', 'Bizim için bir umuttu yıldızlar Gökyüzü ağlıyor şimdi Venüs küskün yıldızlarımız kaydı Bulutlar bir bir dağılıyor Ve anılarımı yüreğime gömd...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/agla-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Kaynagi', 'siir-kaynagi-gultekin-toga-5ivb5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne pirden bade içtim,

Ne de yardan şerbeti,

Yaşadım ve hissettim

Ayrılığı gurbeti,

Dolan kalbim döküldü

Duygular şiir oldu.

Kanadı kırık kuşa,

Buğzettim değen taşa,

Düşmüş gibi ateşa,

Çıkmak istiyor dışa,

Ciğerlerim söküldü,

Kaygılar şiir oldu..

Merhamet dolu cana,

Muhabbet gülü cana,

Hakikat dili cana,

Kurban böyle insana,

Gönlüm tutkun yakıldı,

Saygılar şiir oldu.

Güçsüzüm...Imdadına,

Koşamam yardımına,

Dokunuyor çok bana,

Tüm yüzsüzler adına,

Utancından çekildi,

Yaygılar şiir oldu..

Sentezi gir belaya,

Yar sevilmez kolaya,

Özümde duya duya,

Bir gözleri sılaya,

Bakışlarım çakıldı,

Sevgiler şiir oldu..', 'Ne pirden bade içtim, Ne de yardan şerbeti, Yaşadım ve hissettim Ayrılığı gurbeti, Dolan kalbim döküldü Duygular şiir oldu. Kanadı kırık kuş...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/siir-kaynagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadını Anlamak', 'bir-kadini-anlamak-ahmet-simsiki-0q59p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamak çarpı anlamak onu,

milyon kere anlamakla toplamak,

ne hesap makinesi,ne çarpım tablosu,

işte bir kadını anlamak.

Bu idrakin sonu çıldırmak,

ve ötesi derviş kürsülüğüne varır,

ne muazzam tefekkür,ne manayı iştiyak.

işte bir kadını anlamak.

Beynimin kılcalı bir urgan gibi kaba,

bilmiyorum nasıl dolanmış bu küçücük tasa,

bu bedenle bu beyni taşımak,

işte bir kadını anlamak', 'Anlamak çarpı anlamak onu, milyon kere anlamakla toplamak, ne hesap makinesi,ne çarpım tablosu, işte bir kadını anlamak. Bu idrakin sonu çıl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-kadini-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-ahmet-simsiki-rukvv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu kibrit çöpünü kürdan yaptım,

şundan da balık ızgara

şunu rakıya çevirdim

bi dikişte içtim.

Beğenmediğin şeyi yatak yaptım,

kuştüyü de yastık

bir de hayal kurdum ki

görsen inanmazsın

sonra horozdan saat yaptım

geceye kurdum

vurdum başımı uyudum.', 'Şu kibrit çöpünü kürdan yaptım, şundan da balık ızgara şunu rakıya çevirdim bi dikişte içtim. Beğenmediğin şeyi yatak yaptım, kuştüyü de yas...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayal-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Hesap…', 'yanlis-hesap-ali-orhan-gunaydin-okcxs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oturdum dün akşam, geleceğimiz için bir hesap yaptım…

önce,seni senle çarptım…

böldüm sana sonra sonucu,

           olmadı! 

sanırım, yanlışlık yaptım…

bu kez senle seni topladım…

toplamı senden çıkardım…

olmuyor bir türlü anlayamadım,

yine hata yaptım…

kızma ama… 

ben senden ne zaman bir sonuç çıkartabildim ki,

şimdi çıkartayım…

neyse, hata senden değil, benden sanırım…

yine hesabın sonucu

acı oldu ama, kader bu,

elimden gelmez bir şey 

ne yapayım…

geleceğimiz mi? 

bırakalım kaderin eline, 

nasıl çizerse… 

bizde,öyle yaşayalım…

20/02/2005', 'Oturdum dün akşam, geleceğimiz için bir hesap yaptım… önce,seni senle çarptım… böldüm sana sonra sonucu,            olmadı!  sanırım, yanlış...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yanlis-hesap-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bir Günüm Daha Geçti', 'sensiz-bir-gunum-daha-gecti-baris-yegin-87ay4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir günüm daha sensiz geçti,

Bir gülüm daha sensiz soldu.

Sensiz  akşamım sabah olmuyor,

Sabahım akşam olmuyor.

Sensiz bir günüm bile geçmiyor,

Sabah olmuyor,güneşim doğmuyor,

Sensiz bir gün dahageçmiyor,

Akşam olmuyor,ay doğmuyor.', 'Bir günüm daha sensiz geçti, Bir gülüm daha sensiz soldu. Sensiz  akşamım sabah olmuyor, Sabahım akşam olmuyor. Sensiz bir günüm bile geçmiy...', ARRAY['Türk Edebiyatı','Şiir','Baris Yeğin']::text[], 8.5, '{"poet":"Baris Yeğin","poet_slug":"baris-yegin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensiz-bir-gunum-daha-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötelere Yolculuk Arzusu', 'otelere-yolculuk-arzusu-nuri-yilmaz-dkfn5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen ruhumu sarar esintiler.

Hal böyle olunca beni alıkoyar hayaller.

O zaman kafes kırılır, ruh seyahata çıkar.

O zaman ruh pınarım kaynamaya başlar.

*****            *****            *****

Seherlerde ruhumu okşayan bir ılık meltem var.

Bu gün içimi saran bir yolculuk heyecanı var.

Bu gün bende dostlara varamak arzusu var.

Bu gün gönlümün bestelediği bir öteler türküsü var.

Bu gün bende ötelere uçmak arzusu var.

*****            *****            *****

İstiyorum, bu gün bir kuş olup uçmak.

Ahbabların penceresine konmak istyorum.

İstiyorum, şimdi bir nehir olup çoşmak.

Ahbabların yöreğinde akmak istiyorum.

İstiyorum, bir nesim olup nazlı nazlı esmek.

çicekleri bir bir  okşamak istiyorum.

*****            *****            *****

İstemem solsun ruhumu saran laleler, güller.

İstemem susun ruhumdaki kuşlar.kuşcuklar.

İstemem ölsün içimdeki kelebekler.

İstemem dinsin bendeki yağmurlar.

İstemem kesilsin dünyamdaki nehirler.

İstemem bitsin coğrafyamdaki kışlar, yazlar,baharlar.

*****          *****            *****

İstiyorum, bu gün bir yolcu trenine binmek.

Menzilerimi köşe bucak gezmek,

Ve istiyorum bütün dostlarıma varmak,

Giderkende hepsini alıpta gitmek.

Arzuluyurum, bütün menzilerimi götürmek.

Ötelere ve daha ötelere uçmak

*****            *****            *****

Cenetede olsam özleyeceğim menzilerimi. 

Hak dostları; annemi babamı ve kardeşlerimi

Hasretiyle söyleyeceğim bu hüzünlü dünyanın şarkısını.

Aanımsayacağım, anlatacağım dünya maceralarımı.

Ney gibi yanacağım bu günlere.

İçimi dökeceğim kavalara bağlamalara.

*****            *****            *****

Sanmaki burada biter

Ruhun arzuladığı bu emeler.

Cenete karşı karşıya anlatılacak

Safi hatıraları dostlara dostlar.

*****            *****            *****

Çünkü dünya esmanın tecellisi...

Çünkü dünya ahiretin mezrası..

Ve çünkü ahiret dünyanın meyvesi...

Şubat/2006/Bağcılar/İst.', 'Bazen ruhumu sarar esintiler. Hal böyle olunca beni alıkoyar hayaller. O zaman kafes kırılır, ruh seyahata çıkar. O zaman ruh pınarım kaynam...', ARRAY['Türk Edebiyatı','Şiir','Nuri Yılmaz']::text[], 8.5, '{"poet":"Nuri Yılmaz","poet_slug":"nuri-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/otelere-yolculuk-arzusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilebilseydim', 'bilebilseydim-alaaddin-kulcuoglu-p49kz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrümün yaprakları sararıp

Bir bir dökülürken önüme

Ben baktım 

Ve sadece güldüm ölüme

Gülebilseydim keşke

Ölebilseydim

Bilebilseydim

Başka bahar var mıdır

Yoksa bu sonbahar mıdır.', 'Ömrümün yaprakları sararıp Bir bir dökülürken önüme Ben baktım  Ve sadece güldüm ölüme Gülebilseydim keşke Ölebilseydim Bilebilseydim Başka ...', ARRAY['Türk Edebiyatı','Şiir','Alaaddin Külcüoğlu']::text[], 8.5, '{"poet":"Alaaddin Külcüoğlu","poet_slug":"alaaddin-kulcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bilebilseydim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delilik Yaparsak Affeyle Yarab', 'delilik-yaparsak-affeyle-yarab-yasar-akbas-w8wnr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mazarratın katli vâcip mi? Yârab! 

Ölürse pislikler biter mi? Yârab! 

Dünyamız kuşatmış zâlimle, deyus; 

Delilik yaparsak affeyle,Yârab! 

İnsanı yaratıp nefis vermişsin,

Nefisin emrine akıl vermişsin,

Zavallı, bîçâre vicdan  ne etsin? 

Delilik yaparsak affeyle,Yarab! 

Nefisler doymuyor neyi yese de

Mazlûmu,fakiri acın ölse de

Etmiyor yardımı,hâlin bilse de

Delilik yaparsak affeyle,Yârab! 

Hayatın ön şartı; öldürmek midir? 

Öldürüp sonra da sevdirmek midir? 

Ağlanacak hale güldürmek midir? 

Delilik yaparsak affeyle,Yârab! 

Kardeş kardeşini sevmiyor neden? 

Kaçıyorlar birbirinin derdinden,

Bahsedilmez hatır ile gönülden,

Delilik yaparsak affeyle, Yârab! 

İnsanlar usanmış sohbetten, sözden; 

Yürekler paslanmış garezden, kinden; 

Yarınlar kötüyse eğer bugünden

Delilik yaparsak affeyle,Yârab! 

Sevdânın türküsün çalmıyor ozan,

İdraki gönüle vermiyor ezan,

Çaresizlik mazlumları ağlatan, 

Delilik yaparsak affeyle, Yârab! 

Yalakalık, riyakârlık tüm yanlar

Harâmiler bırakmamış meydanlar,

Helâl lokma aramıyor insanlar,

Delilik yaparsak affeyle, Yârab! 

Söz vermiştik sana Galü Belâda

Emanetin tutacaktık en başta,

Menfaatte sıradayız en başta,

Delilik yaparsak affeyle, Yârab! 

‘Lut’ Kavmiyle cehâletle yarışta,

‘Nuh’ Kavmiyle şeytanlıkta sınavda,

Hayvan gibi yaşıyoruz dünyada,

Delilik yaparsak affeyle, Yârab! 

Hürriyet diyenler adam öldürtür,

Barış kisvesiyle kardeş dövdürtür,

Erkeğe, kadına ırza geçtirtir,

Delilik yaparsak affeyle,Yârab! 

Âdemoğlu ‘Kabilleri’ geçtik biz, 

İnsanlığı silip silip attık biz,

Mangırları ilah yaptık, ilah biz,

Delilik yaparsak affeyle, Yârab! 

Canlı cansız putlar yaptık kafada,

Aslan olduk fırsatları bulanda,

Bey görüldük insanlarda sıfatça,

Delilik yaparsak affeyle, Yârab! 

Akbaş''ı, affeyle mazlûmu, Yârab! 

Nimetin şükrünü unuttuk, Yârab! 

Serapmış, şu dünya koskoca serap,

Islah et bizleri, affeyle,Yârab! 

                                                 (25.06.2004)', 'Mazarratın katli vâcip mi? Yârab!  Ölürse pislikler biter mi? Yârab!  Dünyamız kuşatmış zâlimle, deyus;  Delilik yaparsak affeyle,Yârab!  İn...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akbaş']::text[], 8.5, '{"poet":"Yaşar Akbaş","poet_slug":"yasar-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/delilik-yaparsak-affeyle-yarab-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Köhnemis Çag Devrilir', 'bu-kohnemis-cag-devrilir-gultekin-toga-dv4sf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hesabım çok sağlam dersin,

Ne tasa var,ne gam dersin,

Yoluna devam edersin,

Üzerine çığ devrilir..

İçi kof adı devlenir,

Tek gücüm diye kevlanır,

Ava giderken avlanır,

Başlarına ağ devrilir..

Belki bugün yatar ahı,

Mazlumların tutar ahı,

Baş edemez padişahı,

Volkan patlar dağ devrilir..

Hakk olacak,hak kazanan,

Buluşacak kul yazınan,

Bugün yatakta uzanan

Hasta kalkar,sağ devrilir..

Binmişler kinin sırtına,

Zulumleri bir fırtına,

Saraylarının altına,

Denizlerce yağ devrilir..

Sentezi hiç etme tasa,

Karargahta büyür Musa; 

Bismillahla değer asa,

Bu köhnemiş çağ devrilir...', 'Hesabım çok sağlam dersin, Ne tasa var,ne gam dersin, Yoluna devam edersin, Üzerine çığ devrilir.. İçi kof adı devlenir, Tek gücüm diye kevl...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-kohnemis-cag-devrilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz''e', 'aziz-e-emrah-karakoc-4fqo7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakma şimdi yüzümün güldüğüne

Bende yıldırımlar çaktı AZİZ''İM

Sevgiyi yaşarım gücüm yettiğince

Zalimler yoluma çıktı AZİZ''İM

Ne ümit besledim ne hayal kurdum

Ne bir sevgi buldum ne vefa buldum

Sevgi denizinde yittim, kayboldum

Hainler rotamı yaktı AZİZ''İM

Mutluluk karşımda duruyor sandım

Güzellik peşimden geliyor sandım

Her hayalde kaybetmekten usandım

Dert bana kafayı taktı AZİZ''İM

Sevgi vardı önce, muhabbet vardı

İnsan, insanlara güven duyardı

Bu can her gördüğün adam sayardı

Eskiden namussuz yoktu AZİZ''İM

Yalanı bilmezdik doğruluk rehber

En büyük servetti alnımızda ter

Bugünkü halimiz beterden beter

Düzenbazlık belim büktü AZİZ''İM

İnsanlar sözünün peşine düşmez

Derdini dinleyip senle bölüşmez

Mutlu olduğunda durup gülüşmez

Bu arzuhal beni yıktı AZİZ''İM

Ağlasam hasretle dolaşsam sersem

Bu gönlü çıkarıp yoluna sersem

sen yaşaman için canımı versem

Duyanlar derler ki; haktı AZİZ''İM', 'Bakma şimdi yüzümün güldüğüne Bende yıldırımlar çaktı AZİZ''İM Sevgiyi yaşarım gücüm yettiğince Zalimler yoluma çıktı AZİZ''İM Ne ümit besledi...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aziz-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmaz sensiz gülüm', 'yasanmaz-sensiz-gulum-i-lker-kesemen-4uxtd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyormusun...

Ev sensizken 

Oda sensizlik le kokarken 

Bu kent sensiz öksüz ken nerdesin gülüm 

Ben seni sevdim 

Birinden de şunu öğrendim 

Evlat derdi bana 

``Yarsız yaşanmaz geceler gündüz olmaz 

Gözünden se hayali hiç kaybolmaz``derdi

Biliyormusun...

Ben seni nasıl kıskandım 

Ben senin için nasıl savaştım 

Ve senin için nasıl ağladım bilirmisin 

Gülmeyi unutum 

Ağlar; resmin ile avunurdum 

Eve her gelişim de ise 

Sensiz odan da oturur ağlardım 

Saygılarımla                                  30,12,2004', 'Biliyormusun... Ev sensizken  Oda sensizlik le kokarken  Bu kent sensiz öksüz ken nerdesin gülüm  Ben seni sevdim  Birinden de şunu öğrendim...', ARRAY['Türk Edebiyatı','Şiir','İlker Kesemen']::text[], 8.5, '{"poet":"İlker Kesemen","poet_slug":"i-lker-kesemen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasanmaz-sensiz-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buda kendi huyumca', 'buda-kendi-huyumca-tuncay-akdeniz-qrlat', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buda Kendi Huyum’ca 

Dünya benim diyen,baksa ibrete, 

Kabirler sıralı.boylu boyunca. 

Yeri göğü dolu, şükür rahmete, 

Nimeti bilmiyor,karnı doyunca. 

Yiğidin göğsünde,imandır kale, 

Yazmaz kitabında,namertlik hile. 

Ser verir sır vermez,rüzgara yele, 

Değişmez libası,mertlik huyunca. 

Sevgi gönüllerin yürek sevdası

Kula kul olmanın,yoktur faydası, 

Cilveli oyunun,çıkar foyası, 

Astarı yüzünden,alıp soyunca, 

Ruhu emanettir,namahrem beden, 

Göz ile beyindir,sebepsiz neden. 

Ateşe dumanlık,vicdandır eden, 

Herkes nasibini,alır payınca. 

Dört iklimi vardır,bak tabiatın, 

Devamı yok beyim,bu saltanatın. 

Dolu almamışsan,bur dan beratın, 

Boşa kabul görmez,özden cayınca 

Ruhsuzlaşan beden,kalmış avare, 

Kendini ölümsüz,sanmış biçare. 

Hatır sayar olmuş, varına göre, 

Gaflet uyanır mı,nefse uyunca 

Tuncayım hükmetme çağa asıra

Belki tuzu fazla bastım nasıra

İster sürgün edin,beni mısıra 

Bilmem hatamıdır, hakkı sayınca.', 'Buda Kendi Huyum’ca  Dünya benim diyen,baksa ibrete,  Kabirler sıralı.boylu boyunca.  Yeri göğü dolu, şükür rahmete,  Nimeti bilmiyor,karnı ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/buda-kendi-huyumca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çorak Çöller Gibi', 'corak-coller-gibi-emrah-karakoc-ev112', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çorak çöller gibi susuzum sana

Yağmur ol da dostum yağ yüreğime

Kalbimin hasretle çarptığı anda

Bitir şu hasreti bitir be gel be

Yaşam için balık muhtaçsa suya

Bülbül nasıl huzur bulursa gülde

Sen kuş gibi uçsan ben ise yaya

Koşarak gelirim senin peşinde

Gurbetin içinde bir sılam oldun

Huzur verdin canım sen yüreğime

Sen yanımda olda yaşamım dursun

Senle geçen günüm sanki saniye

Bende ibadettir sana ağlamak

Sensiz bu bedenim yaşasın niye

İstemem sen yoksan ağa, bey olmak

Bu gönül şen oldu sen varsın diye

Tartılmaz bu sevgi hiç bir tartıyla

Hicranın kanayan yara kalbimde

Ne olursun yaren el olma bana

Bu can mutluluğu buldu sayende', 'Çorak çöller gibi susuzum sana Yağmur ol da dostum yağ yüreğime Kalbimin hasretle çarptığı anda Bitir şu hasreti bitir be gel be Yaşam için ...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/corak-coller-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞıK KAR', 'sik-kar-ahmetnecat-ucur-dfzac', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oldu mu oldu şahane, o eski kış,

Bembeyaz dantel işlendi, nakış nakış

Yağıyor karlar, motif motif,akış akış

İstemeden geldi, ıslık ve de alkış…

Nazlanıyordu bir haftadır karakış

Her yer büründü kara, bugün geldi kış

Gözler olsa da kara, bembeyaz bakış

Yağıyor kar yağdıkça, bitmesin bu kış

Sen benim yazımsın olsa da kara kış,

Değil ki kalbim kara, kara olan kış

Nedense biz kara demişik; beyaz kış

Kar, beyaz, bembeyaz, olamaz kara kış

Ak kara hakarettir; demek kara kış

Bembeyaz kar varken, denir mi SİYAH kış…

Renkler mi şaşkın, biz mi isteriz alkış

Ak aktır, kara kara, istemez alkış

Beyaz hangi mevsim, sanki kara da kış

Çatık kaş, hor bakış, sitem mi can yakış

Bu da kışa başka açıdandır bakış

Sevgidir yürekteki mevsim, yaz ve kış

Yürüsen karda hiç belli etmez izini kış

Kara değil, bembeyazdır artık beyaz kış

Yaşa ki aşkla, yaşat aşkı yaz ve kış

Yoksa AŞK; şebektir yaz, maskaradır kış!', 'Oldu mu oldu şahane, o eski kış, Bembeyaz dantel işlendi, nakış nakış Yağıyor karlar, motif motif,akış akış İstemeden geldi, ıslık ve de alk...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sik-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir damla için...', 'bir-damla-icin-mustafa-murat-aydogdu-s5ep4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özür dilerim; 

Bu gece yine sen düştün aklıma

Kendimle hesaplaştım dakikalarca

Çekilip bir kenara.

Dakikalarca diyorum,

Her anım seninle doluyken

Kendime yalnızca dakikalar ayırabiliyorum

Özür dilerim; 

Seni canımdan çok sevdiğim için

Binlerce sevilebilecek insan varken dünyada

Yüreğimi yalnız sana vermişim,

Sen ise bir başkasıyla evlenmişsin.

Özür dilerim; 

Tutamadım gözyaşlarımı,

Dokunan da yok; Dokunsalar ağlayayım

Sonra suçu onlara atayım,

Kaçmaya çalışırken bu sevgiden

Sana çıkıyor bütün yollarım.

Özür dilerim; 

Hala seni beklediğim için.

Sevgini,sevdiğini küçümsemek değil niyetim

''''Nasılsa ayrılır,bir gün bana döner''''gibi sözler

Bu güne kadar hiç düşünmedim.

Aslında ben seni değil,sevgini istedim; 

Bir aşk filminin en acıklı sahnesinde

Usulca süzülürken yanaklarından gözyaşların

Beni düşünüyor olmanı,hiç olmazsa o damlalardan birinin

Gözlerinden benim için düştüğünü bilmek istedim.

Asla,senin için yapamayacağım bir şeyi

Senden istemedim,beklemedim.

Sana ağladım; Bahsi geçen filmin her karesinde

Yetmedi,binlerce filmde,şarkıda,şiirde.

Sana ağladım; Pokemonlarda

Pikachu,Ash''i terkettiğinde.

Sana ağladım; Alt kata indirirken masayı,merdivenlerde.

Sana ağladım; Askerde eğitim alanında

Selam vermeyi öğrenirken,tam 600 kişi içinde...

Uzar da gider benim gözyaşlarımın öyküsü

Uğruna döktüğüm binlerce damlaya karşılık,

Hiç değilse bir damla,benim için ağlasana! 

Hala yazıyorsam sana

Aşkımı anlatamadığımdandır sevdiğim

Hala yaşıyorsam bu gün

Benim için akacak,o bir damla gözyaşını bekliyorum,

Onca kahrıma rağmen,

Direndim; 

Sırf bu yüzden ölmedim!', 'Özür dilerim;  Bu gece yine sen düştün aklıma Kendimle hesaplaştım dakikalarca Çekilip bir kenara. Dakikalarca diyorum, Her anım seninle dol...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-damla-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-tunahan-mulla-cp576', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuksu duygular kaplı vücudumda aşkında

Sensiz geçen yolların kokusu kaplamakta 

Beynimi.

Aşk ve sen kokmalı tenimin heryerinde

Bir aşk duygusu

Birde sen

İçimdeki dokunuşun felsefi hali var

Hala dudaklarımda aşkım ve sen

Sonu ne olursa olsun seniş yaşamalı

Aşk dolu yüreğinde.', 'Çocuksu duygular kaplı vücudumda aşkında Sensiz geçen yolların kokusu kaplamakta  Beynimi. Aşk ve sen kokmalı tenimin heryerinde Bir aşk duy...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Mulla']::text[], 8.5, '{"poet":"Tunahan Mulla","poet_slug":"tunahan-mulla","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-554-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım', 'alisamadim-seyfet-bozcali-3zwxv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Habire Dünya''da koş,

Her şey yalan her şey boş,

Dışardan bakana hoş,

Bense alışamadım.

Yine geçmişe daldım,

Yine uykusuz kaldım,

Hatırladım çok güldüm,

Düne alışamadım.

Biraz gezeyim dedim,

Şiir yazayım dedim,

Dörtlük dizeyim dedim,

Söze alışamadım.

Bozçalı''nın sözüne,

Uyku girmez gözüne,

Gerçeklerin özüne,

Girdim alışamadım.

        20.02.2006', 'Habire Dünya''da koş, Her şey yalan her şey boş, Dışardan bakana hoş, Bense alışamadım. Yine geçmişe daldım, Yine uykusuz kaldım, Hatırladım ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/alisamadim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın çizgilerim', 'alin-cizgilerim-mustafa-murat-aydogdu-cdk8b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanların dertleri,alındaki çizgilerden ibaretse eğer; 

Ya benim hiç derdim yok,

Ya da alnımda yeteri kadar yer yok!', 'İnsanların dertleri,alındaki çizgilerden ibaretse eğer;  Ya benim hiç derdim yok, Ya da alnımda yeteri kadar yer yok!...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/alin-cizgilerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve yine sen gülüm', 've-yine-sen-gulum-i-lker-kesemen-7ah1k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülleri bilirsin 

Hani pembelerini 

Sende sever din kırmızı olanları 

Hepsi dalında; sen sevgim ile güzel din 

Gülerken gözlerin parlar 

Sen ağlarken ben dayanamaz dım 

Güzelliği de ben senle anladım 

Sende olmasan ben ne yapardım 

Bilirmisin ıssız geceleri 

Ya beyaz ile siyahı 

Uzaktaki sılayı 

Bilirmisin sen gülüm 

Gittim bende senle olduğumuz yerlerden 

Ağladım da sensiz akşamlar da 

Yanlızlıkta yetmişti canıma 

Yokluğunda kahreder di beni bilirmisin 

İnsanları severdim 

Bazen de fakir geçinirdim 

Sılayı ve yanlızlığı en iyi ben bilirdim 

Sensiz gülmesini bile beceremez dim 

Saygılarımla                                    29,12,2004', 'Gülleri bilirsin  Hani pembelerini  Sende sever din kırmızı olanları  Hepsi dalında; sen sevgim ile güzel din  Gülerken gözlerin parlar  Sen...', ARRAY['Türk Edebiyatı','Şiir','İlker Kesemen']::text[], 8.5, '{"poet":"İlker Kesemen","poet_slug":"i-lker-kesemen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ve-yine-sen-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtirafımdır!', 'i-tirafimdir-enes-ates-8g9kt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiirlerim; 

        Kabına sığmayan bir gökyüzüdür ta''katsiz! 

Sözlerimse; 

         Dağlardan topladığım vakitsiz kır çiçekleri...', 'Şiirlerim;          Kabına sığmayan bir gökyüzüdür ta''katsiz!  Sözlerimse;           Dağlardan topladığım vakitsiz kır çiçekleri......', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/itirafimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyalar', 'papatyalar-omer-osman-avci-qkkid', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kafayı fallara taktım

Yüzlerce papatya koparttım

Son yaprakta da olsa

Sevecek sandım

Yanıldığımı anladım…

Özür dilerim PAPATYALAR,

Boşuna canınızı yaktım...', 'Kafayı fallara taktım Yüzlerce papatya koparttım Son yaprakta da olsa Sevecek sandım Yanıldığımı anladım… Özür dilerim PAPATYALAR, Boşuna ca...', ARRAY['Türk Edebiyatı','Şiir','Ömer Osman Avcı']::text[], 8.5, '{"poet":"Ömer Osman Avcı","poet_slug":"omer-osman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/papatyalar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Çiçeği-8', 'ates-cicegi-8-adnan-durmaz-91kw7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah Del'' İzzet 

Dön de gel

Öldüysen diril de gel

Ala beygirin üstünde

Kasal da gel- kurul da gel

            dedi Safiye Teyzesi

            gözlerinden on on döktü

Kimlere darılsın gelsin

Nesine kurulsun gelsin

Namusunu on paralık ettiler

Hatçe''sine sarılsın /gelsin

            dedi Çatallı Teyzesi

            gözlerinden seller aktı

Babası gelmezse gelmesin

Altınımız pul oldu

Gelip gözleri görmesin

Körpecik kızımız dul oldu

      	dedi Eşe Teyzesi

            Hatçe''nin bağrını yaktı

Çapulcu konar üstüne

Esas yiğitlerden geri kalanın

Varıp ırzıyla oynarlar

Boynu buruk- dalı kırık olanın

            dedi Fadime Teyzesi

            sesi yürekleri söktü

Ağladı Filik kadın

Ağladı kanadı kırık Hatçesi

Haberler geliyor uzak cephelerden

Memleket paylaşılıyor

Bir yerlerde şehirler yanıyor

Açlık orduları dolaşıyor dağlarda

Sırtları bit kıvıldıyor

Gavurun soluğu ensemizde

Bir ocağın bir umudu olanlar

Yüreklerde ağıt olup yandılar

Köpekler uludu aç sokaklarda

Boşalmış hanelerde öttü baykuşlar

Zaman kan gibi aktı

Katmerledi acıyı başka acılar

Gülmeyi unuttular

Zaman sancı gibi aktı

Uykusuz koyarak geceleri 

Eridi kar 

Dağlar masmavi baktı

Bahar söyledi yayla yeli

Titredi sinesi tohumsuz kalan toprak

Gür ekinlerin yerinde

           kangal dikeni yeşerdi

Zaman avcı gibi aktı / insan av

Sağnaklar boşuna indi nadasa

Boşa gitti tarlada tav

Korkuda ve yoklukta kürnemiş kalabalık

Çalmaya- savaşmaya- teslim olmaya hazır

Canı derdine düşmüş çaresizlikten

Hatçe''nin yaresini unuttular

Su yolunda görenler laf çarptılar

Gittin de gürleyi gürleyi

Şimdi geldin oturursun

Neyin varsa zay olmuş

Utanmadan el içine çıkıyor

Çeşmenin başında esvap yıkıyor

Kendini el değmemiş çiçek sanıyor

Neyine kurulursun Filiğ''in kızı

Hatçe ağladı da sustu

Çıkmadı evden dışarı

Yüklük odasına pustu

Bir telaş sardı Filiğ''i

Sokağa çıktı bağırdı

Sövdü- saydı- kargış etti

Derler ki Aziziye''ye gitti

Papaz Aptil''in yanına 

Aptil Ağam kurban olam yoluna

Ocağına düştüm / hal böyle böyle

Git Kar'' Üseyin''e söyle

Aptil Kadir Ağa bindi atına

Yanında adamları / vardı Karacalar''a

Üğü Kayası''nda boru çaldı Kör Durmuş       

Kara Hüseyin''e haber ettiler

Dedi- Aptil Ağa beni hiç sevmez

Adama boşuna papaz demezler

Korkacak falan değilim

Var çekin atımı gidelim

Hac''Ahmet Ağa''nın evinde buluştular

Aptil Ağa ağır adam

Varlıksa varlık onda

Tarlaysa tarla- ağalıksa ağalık

El etse hökümet ayağa kalkar

Kapısında yüz köpek beslenir

Göz kırpsa adam vururlar

Gel benim deli oğlum Hüseyin dedi

Kocaman kafasında şinik gibiydi fesi

Taslak suratında keder

Sen burada eşkiyalık edersin

Haberin var mı ola memleket gitti gider

Ordumuz yenildi tüm cephelerde

Sustu / dalıp gitti derine

O ara kahve verdiler

Ben buraya bunun için gelmedim

Elin körpe kızını zay edip attın

Atmadım Aptil Emmi

Helallığına aldım

Kaçırmak benden mi adet

Kancıkladı zaptiyeler

Durdu 

Çevresine baktı

Çıkın len dışarı

Çıktı içerdekiler

Kader buymuş Aptil Emmi

Sen beni sevmezsin emme

Doğru düzgün ordu olsa

Sonra ben değmem yoksula

Varlı olanı soyarım

Gavur şurdan çıkıp gelse

Ben de kellemi koyarım

Filik kızına gelince...

Sözünü kesti Aptil Ağa

Bak hey benim Deli Oğlum

Filiğin kocası yiğit adamdı

Sana yakışmazdı alıp kaçırmak

Gelin sizi sulh edeyim

Allah''ın emrince evlenin

Tamam Aptil Emmi / dedi sevinçle

Çetecilikten de vaz geç

Oturaklı bir adam ol

Şimdi vatan savunmanın vaktidir

Gittiğin yanlış bir yol

Yedi düvel bağrımıza süngü dayamış

Anlattı Aptil Ağa 

Dinledi Kar'' Üseyin

Filiğin kapısına atlılar geldi akşamleyin

Oturup konuştular

Ağız tadı / kutu kutu lokum koydular

O günün çocukları anlatırlar ki

Aziziye''de tevir tevir donattılar Hatçe''yi

İpek keme entari / meydani

Al- yeşil- mor kadife sayalar

Livali ayakkabı / Trablus kuşak

Başına da yapraklı maşallah

Bacağına püsküllü top şalvar

Hatçe''yi donattılar

Karacalar Köyü''ne düğün kurdular

Dört gece- dört gündüz çalgı çaldı aptallar

Doymadık aç kalmadı

 Ağalar- beyler indi yaylı arabalarla

       	ve hükümet adamaları

Rakıcı Anton''dan yük yük rakı taşındı

Seyirlik çıkarıp- kaşık kırdılar

Uzak cepheleri

Ve Kar'' Üseyin''in sicilini unuttular

Gönülsüz gelin oldu Hatçe kız

Gönülsüz güldü oynadı

Gelin giderken ağladı

Gerdeğe girdiler hiç konuşmadan

Yattılar- kalktılar

Hiçbir dağ yoktu

Hiçbir yol hiçbir ırmak

Hatçe''nin içindeki küslük kadar....

Kaç gün geçti aradan 

Aylar aktı sular gibi

İki baş yastığa geldi

Dem oldu Hatçe Gelin 

            Kar'' Üseyinden zevklendi

Başını duvarlara vurdu yalnız kalınca

Dövdü bağrını

Gün oldu

dizme dizme cebe taktı koluna

Aş pişirdi / sofra kurdu...

Kar'' Üseyin hanesi bu

Al atlı iner- kır atlı biner

Unutuldu verilen söz Aptil Ağa''ya

Çeteciliğe devam ettiler

Yedi iklim- dört bucaktan kara haberler

Dediler Kar'' Üseyin cepheye asker sevk eder

Kıtlık hışım gibi zaptetmiş ortalığı

Onun hanesinde yokluk ne gezer...

Geceler devrildi günler dürüldü

Bazan tek adam kalmadı ortalıkta

An geldi bin bir ayak bir ayağa derildi

Köyler mezarlığa döndü

Kuş pisliği sıvandı kapılar

Cephede kalanlardan arta kalanlar

       	kıranda- kıtlıkta talanlandılar

Dağlar dolusu kaçak

       	çift süren kadınlara saldırdılar

Umut ateşleri söndü...

Bir asker kaçağı anlatıyordu

Neylesek fayda vermedi / yenildi ordu

Yediğimiz otlar ağudan acı

Ağzımın yarası- yüzlerimizin şişi

Bir iğdelik bulduk bilmem nerede

Günlerce iğde yedik tam sekiz kişi

Üçü öldü sonra / geriye kalan beşi

İğdenin unları durmaz midede

İsraf olmasın diye yuttuk çekirdekleri...

Yaralı bir asker anlatıyordu

Yaralı bir ata saldırıverdik

Hiç birimiz pişirmedik

Herkes çiy çiy yapıştı bir yerine

Say ki birer aç köpektik

Ne damarlarımızda kan kalmış

      	ne de dizimizde derman

Herkes kaptı bir yanını koparttı

Bana ise çavı kaldı

On kişi koştu peşimden

Kapıp paypança ettiler

Dinleyenler acı acı güldüler

Anlatan ağlıyordu...

devam edecek', 'Ah Del'' İzzet  Dön de gel Öldüysen diril de gel Ala beygirin üstünde Kasal da gel- kurul da gel             dedi Safiye Teyzesi             ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":208,"source_url":"https://www.antoloji.com/ates-cicegi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müslümanın Dirliği Ancak Kendi Birliği', 'muslumanin-dirligi-ancak-kendi-birligi-umut-gungor-t2lyg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Densizin biri çıkıp rasulüme sövüyor,

Serdengeçtim sinirden dizlerini dövüyor,

Bazıları durmadan avrupayı övüyor,

Rasulüme sövenin birliğini istemem.

Papazın haddinemi vatanıma karışsın,

Dostlarıyla birlikte dağ bayır dolaşsın,

Sıkıyorsa ilkönce ecdadımla barışsın,

Rasulüme sövenin birliğini istemem.

Müslümanın dirliği ancak kendi birliği,

Deniz bile yıkamaz beyindeki kirliği,

İstemem uzak olsun ecnebinin birliği,

Rasulüme sövenin birliğini istemem.

Eşkiyaya nota yok ektiğime kota var,

Vallahi bu seyirde saptırılmış rota var,

Bu gemide dümende mutlaka bir hata var,

Rasulüme sövenin birliğini istemem.

Devamı yarın...', 'Densizin biri çıkıp rasulüme sövüyor, Serdengeçtim sinirden dizlerini dövüyor, Bazıları durmadan avrupayı övüyor, Rasulüme sövenin birliğini...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/muslumanin-dirligi-ancak-kendi-birligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mikdat Bal İbrahim Coşar 4. MSN Atışması', 'mikdat-bal-i-brahim-cosar-4-msn-atismasi-mikdat-bal-a4ww5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evvvel gurbetçiden döviz gelirdi

Acep gurbetçiyi küstüren nedir

Şimdi aramızda küslük belirdi

Acep gurbetçiyi küstüren nedir..........İbrahim Coşar

Bir pasport verdiler saldılar bizi

Firenkler sahipsiz buldular bizi

Her izin gelişi yoldular bizi

Kabahat bizleri küstürenedir...........Mikdat Bal

Çocuk Avrupa da  doğup büyüdü

Bilmem aldımı ki milli öğüdü

Kendi ülkesinden neden soğudu

Acep gurbetçiyi küstüren nedir.....İbrahim COŞAR

Ne öğretmen geldi ne de bir hoca

Neyi anlatayım derler koskoca

İkinci nesili ittiler suça

Kabahat alaka kestirenedir......Mikdat Bal

Eski militanlar hepsi kaçtılar

Gidip Avrupa da zehir saçtılar

Türkün düşmanına avuç açtılar

Acep gurbetçiyi küstüren nedir.....İbrahim COŞAR

Sayım oldu bizi saymadılar hiç

Vatana rüşvetsiz koymadılar hiç

Kaba davranıştan caymadılar hiç

Sözüm bize umut kestirenedir......Mikdat bal

Gitmek istenen yol  derler Avrupa 

Ancak gemi tekler yapar hep yalpa

Bizi isterler mi,sorarsak halka

Acep gurbetçiyi  küstüren nedir....İbrahim COŞAR

Gökyüzü yağmadı bize parayı

Bire on sattılar bize merayı

Bellediler bize akla karayı

Sözüm hep bizleri kıstıranadır......Mikdat Bal

Avrupa birliği girersek eğer

Bize verirler mi acaba değer

Belki arkamızdan hepsi de söver

Acep gurbetçiyi küstüren nedir........ İbrahim COŞAR

Havadan kuş kapsak bizi almazlar

Bunlar bize düşman hiç dost olmazlar

Bizi üzmekten de geri kalmazlar

Dostlukları bayrak astıranadır……….Mikdat Bal

Duyarız orada örgütler faal

Türkler aleyhine çalışma ne hal

Alırlar mı diye bakıyoruz fal

Acep gurbetçiyi  küstüren nedir.....İbrahim COŞAR

Baş köşeyi kaptı Türk düşmanları

Allahsız kitapsız danışmanları

Domuz eti yeyip var şişmanları

Kozlar şimdi Türkü susturanadır......Mikdat Bal

Evvel Türkiye’de hepsi zıttılar

Vurdu birbirini kan akıttılar

Gözler kararmıştı,vatan sattılar

Acep gurbetçiyi küstüren nedir....İbrahim COŞAR

Anavatanımız güzeldir diye

Yatırımlar yaptık özeldir diye

Ekonomi biraz düzeltir diye

Küslük bize zehir kusturanadır.....Mikdat Bal

Dinledim dostları umut azaldı

COŞAR’ın  sözleri nerede kaldı

Avrupa rüyası görmek güzeldi

Acep gurbetçiyi küstüren nedir.....İbrahim COŞAR

Mikdatî’ sizi üzmek istemem

Ancak burda yetim gezmek istemem

Bunu vatanımdan sezmek istemem

Sevgim bize sevgi estirenedir…………….Mikdat Bal', 'Evvvel gurbetçiden döviz gelirdi Acep gurbetçiyi küstüren nedir Şimdi aramızda küslük belirdi Acep gurbetçiyi küstüren nedir..........İbrahi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/mikdat-bal-ibrahim-cosar-4-msn-atismasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuktuk', 'cocuktuk-muzaffer-cura-ixfa9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukçaydı kavgalarımız.

En kötüsü,

oyuncaklarımızı toplayıp,

bükük dudak,

kalkık kaş,

oyun bozmalara varan.

Bazen sırt çevirip, diğer çocuklara,

ve diğer oyuncaklara,

biraz da kavga çıkardığımıza bin pişman.

Sonu evlerimize uzanan.

Erken dönüşlerimize şaşan annemize,

haklılığımızı anlatan,

masum bir şikayetti zaman.

Ertesi gün hiç bir şey olmamış gibi,

aynı yerde buluşan.

aynı oyuncakları paylaşan..

çocuktuk,

çabuk küsüp, çabuk barışan.', 'Çocukçaydı kavgalarımız. En kötüsü, oyuncaklarımızı toplayıp, bükük dudak, kalkık kaş, oyun bozmalara varan. Bazen sırt çevirip, diğer çocuk...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Cura']::text[], 8.5, '{"poet":"Muzaffer Cura","poet_slug":"muzaffer-cura","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocuktuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla 1', 'agla-1-mustafa-kamil-yuksek-rnt1t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağla

bardaktan boşalırcasına

gözlerin şişsin

ve ellerin ıslak, bir dilek tut

Allah''a yakın şeytana uzak

Ağla...

ama çakallar görmesin yaşlarını

geceler feryad etsede hıçkırıklarından

Onurludur yaşların doğurgansa sevdan 

en ateşli savaşlardan erişilmez sırlar hisseder

kanlı hülyalar beslenen 

iğrenç düşler düşer, 

lanetli sehbalara 

ipsiz urganlarla bağlı

adı Demokrasi Tanrısı

Ağla...

öyle ağla hıçkırıksız ve kollarında yükü

sevdana sevgini söyle.....

Analar ağlamamış öyle

ne miş''li nede di''li

hiçbir zaman yaşamamış o anı

Ağla......

sevdan katlimize vurgun katlimiz sevdana...

Ağla..... iki gözüm 

ferman var sevdalara...

sehbalar devrik....

urgan benim boynumda 

ben ölürüm katlimize vurgun sevdalara......

Dur...

öylece ve hareketsiz

birazda çaresizleri oyna...

Vur...

kininin vaverayanıyla, olanca şiddetinle vur 

Ağlama..........

ödenmiş diyetimiz 

son nokta 

Ağlama iki gözüm boşver Ağlama........', 'Ağla bardaktan boşalırcasına gözlerin şişsin ve ellerin ıslak, bir dilek tut Allah''a yakın şeytana uzak Ağla... ama çakallar görmesin yaşlar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kamil Yüksek']::text[], 8.5, '{"poet":"Mustafa Kamil Yüksek","poet_slug":"mustafa-kamil-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/agla-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz Can''a İthaftır', 'aziz-can-a-i-thaftir-emrah-karakoc-xhg1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Biz seninle eskiden su içmedik testiden''

İnsanın pişmanlıkları vardır

''Yapamadım'' der

Yada ''yapmasam daha iyiydi''

Benimde pişmanlıklarım oldu

Yaşadıklarıma da, yaşayamadıklarıma da

Yoksul bir çocukluk yaşadım

Gömleğim yeniyse,Pantolonum hep eskiydi

Ve hiç bir zaman iskarpinlerim olmadı

Ama mutluydum, hiç hayal kırıklığım olmadı

Elbisem eskiydi ama hep tertemizdi

Ahh! Canım Anam o konuda pek titizdi

Sevgi canlısıdır anam, bana hep güzellikler öğretti

Bir radyomuz vardı

Zeki Müren dinlerdik

Sonra Barış Manço, Özay Gönlüm, Erkan Sürmen

Hele birde kısa dalgadan

Türkiye''nin sesini bulduk muydu

Değmeyin keyfimize...! 

Radyo tiyatroları, arkası yarınlar, çocuk bahçeleri

Haftanın çocuk şarkısı ve türküler geçidi

Bedia Akartürk, Süreyya Davulcuoğlu

Meddahlarla, tekerlemelerle, haberlerle

Hafta sonu lig maçlarıyla, Avrupa kupalarıyla

Radyo yetiyordu bize...

Şimdi çeşit çeşit radyo

Ayrı ayrı tv kanalları var

Ama o Delta Radyo''nun tadı yok

Gurbetteyim, sıladan uzak

Elbiselerim yine temiz, ama yeni

Dedim ya dostum, yaşamın tadı yok.

Düzen mi bozuldu bizmi düzeni bozduk bilmiyorum

İnsanlar iki yüzlü olmuş, hep sözler sahte

Ne vefa kalmış ahte, nede kürsü kalmış iskembe adında

Kül savuran sobamızda Anamın pişirdiği kömbelerde yok

Olan tek şey onların hayali, anıları...

Ahh can dostum, görmeni isterdim çocukluğumu

Yada birlikte yaşamak isterdim o günleri

Kızak kayardım kızakları bir birine çarparak

Top oynamak için evden kaçardım

Akşam eve dönmek hep korku verirdi bana.

Ya da babamın soğuk kış gecelerinde

Üç beş kuruş için bir yük odun sarıp boz eşeğe

Ova köylerine gittiği günlerde

Soğuk yatakta, babam şimdi ne halde diye

Tedirgin olan yüreğimi görmeni isterdim.

Mahalle takımlarıyla maç yapardık

Ben takımın golcüsüydüm

ALLAH var yukarda iyide kaleciydim

Ama kalecilik sarmazdı beni

İlla bir Tanju olacaktım büyüyünce

Simoviç olmak kimin umurunda

Güzel goller atardım hem sağ hem sol ayakla

Ama o ilk kafa golümü attığımdaki 

Sevincimi görmeni isterdim.

Çocukluğum çok güzeldi

Herkesçe çok sevilir, okulda da çalışkandım

Doğru sözlüydüm, yardımseverdim

Ve ikinci sınıftan sonra hep sınıf başkanıydım

Hep Pekiyi olan karnelerimi görmeni isterdim.

Görmedin istediklerimi görmende olanaksız

Şimdi tek bir şey istiyorum biliyormusun

Ölümümü görmeni istiyorum.

Öldüğümde yanımda olmanı ve mezarımı kazmanı

Çok görme bana bunu olur mu

Ama olur ya ağlarsan, ağlama dayanamam

Sana ağlamak yakışmaz, hep gül sen dost

Ama yaşadıklarından da ibret al

Cenab''ı Hakk ''Her şeyde bir hayır vardır muhakkak'' buyurmuştur

Bu bir yüreğin dosta mektubudur, GÖRÜLMÜŞTÜR', '''Biz seninle eskiden su içmedik testiden'' İnsanın pişmanlıkları vardır ''Yapamadım'' der Yada ''yapmasam daha iyiydi'' Benimde pişmanlıklarım ol...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/aziz-can-a-ithaftir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüğüm Gün', 'oldugum-gun-sultan-mustafa-wl07z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölürsem 

Derine

Daha derine

En derine gömün beni

Bir bulut gönderin denizlerden

Ağlasın üstüme çisil çisil

Dostum dilek tutsun fal açsın

Ateşinde karanlık zamanların

Çengilerin çiçekli şarkılarında

Halaylar çekilsin ağıtlar üstüne

Köçekçe oynarken mezar taşım

Göğe ağsın cinler ecinniler

Ve öldüğüm gün

Toprağım soğumadan 

Ne iz varsa benden kalan

Silinsin hafızalardan', 'Ölürsem  Derine Daha derine En derine gömün beni Bir bulut gönderin denizlerden Ağlasın üstüme çisil çisil Dostum dilek tutsun fal açsın Ate...', ARRAY['Türk Edebiyatı','Şiir','Sultan Mustafa']::text[], 8.5, '{"poet":"Sultan Mustafa","poet_slug":"sultan-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oldugum-gun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazık', 'kazik-esin-cinar-blyqf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kazık

Kabircilere kazık atacağım

Tek kişilik kabirde 

Herkese inat 

Kalbimde seninle yatacağım

Esin Çınar

(30.05.2005/20.02.2006)', 'Kazık Kabircilere kazık atacağım Tek kişilik kabirde  Herkese inat  Kalbimde seninle yatacağım Esin Çınar (30.05.2005/20.02.2006)...', ARRAY['Türk Edebiyatı','Şiir','Esin Çınar']::text[], 8.5, '{"poet":"Esin Çınar","poet_slug":"esin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kazik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-bahaettin-karakoc-zlpsz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğarken gülümse 

Acıyı tatmamış yüreğinle 

Bir siyah bir beyaz 

Gök ırgalansın…

Büyürken gülümse 

Çağlayanlar gibi 

Bir erguvan renginde bir yeşil 

Ufuklar çalkalansın…

Severken gülümse

Rıza diye, tiryak diye

Bir pembe bir sarı

Sevgin yarınlara dal-budak salsın…

Daha çok gülümse pîrliğinde 

Süzülmüş oğul balı renginde 

Bengi-su tadında 

Taşlar topraklar sevdalansın…

Hep ileriye bak gülümse 

Her zaman sevgiliyle birlikte ol 

Vuslat renginde 

Taş-toprak hülyalara dalsın…

Ölürken gülümse 

Tazele aşkını son nefesinde 

Birazcık gözyaşı bulunsun sesinde

Gökyüzü hep ıslak mavi kalsın…

Bahaeddin KARAKOÇ (Ley ü Nehar Aşk – Türk Diy. Vak. Yay.  ANKARA -1997)', 'Doğarken gülümse  Acıyı tatmamış yüreğinle  Bir siyah bir beyaz  Gök ırgalansın… Büyürken gülümse  Çağlayanlar gibi  Bir erguvan renginde bi...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gulumse-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak Yoldur Bizim Yolumuz', 'hak-yoldur-bizim-yolumuz-seyfet-bozcali-7oy7y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Resulümün  güzel örnek ahlakı,

Rahman''ın yoludur bizim yolumuz.

Sahabi Kiram''ın nur yıldızları,

Kur''anın yoludur bizim yolumuz...

Gittikçe güçlenen imanımızla,

Sünnetle yoğrulan irfanımızla,

Dualarımızla,Evliyamızla,

Ayetler yoludur bizim yolumuz.

Bize emanettir Kur''anla sünnet,

Onlara sarılmak büyük fazilet,

Rahman''ın katından süzülür Hikmet,

Hakikat yoludur bizim yolumuz...

Uğrunda  aşıklar çileye dalmış,

Batıldan,fitneden uzakta kalmış,

Bunca evliyalar takvaya dalmış,

Yunus''lar yoludur bizim yolumuz...

            20.02.2006', 'Resulümün  güzel örnek ahlakı, Rahman''ın yoludur bizim yolumuz. Sahabi Kiram''ın nur yıldızları, Kur''anın yoludur bizim yolumuz... Gittikçe g...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hak-yoldur-bizim-yolumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Oldu Yine Akşam', 'aksam-oldu-yine-aksam-necla-aktan-jfitk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşam oldu yine akşam 

Karardı ortalık

Ruhum alacakaranlık 

El ayak çekildi 

Kapılar kapandı

Perdeler çekildi 

İn cinle top peşinde 

Zor gececek bugün de 

Yazsan,çizsen,okusan

Bugün de yarına zor erişecek 

Dün gibi 

Ya da evvelki 

Ya da bir önceki 

Ya da herhangi bir gün 

Gibi günlerden 

Sahi hangisiydi 

Günlerden neydi

Hepsi aynı gibiydi 

Takvimlerin de anlamı gitti 

Akşam oldu yine akşam', 'Akşam oldu yine akşam  Karardı ortalık Ruhum alacakaranlık  El ayak çekildi  Kapılar kapandı Perdeler çekildi  İn cinle top peşinde  Zor gec...', ARRAY['Türk Edebiyatı','Şiir','Necla Aktan']::text[], 8.5, '{"poet":"Necla Aktan","poet_slug":"necla-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aksam-oldu-yine-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İnsana Sevgi Notları', 'bir-i-nsana-sevgi-notlari-muzaffer-cura-tccer', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hepimizin var bir geçmişi.

O, geçmişte yaşadığımız,

yitirdiklerimizin gizli düşü.

Sevmeye gelince; 

o ayrı bir ustalık ve hüner işi.

Bir sanat yani...

Yada güzel bir tablo yapmak gibi,

bir sevdayı bir bedende yaşatmak.

Ya da bitmemiş bir tablo gibi,

kurumuş fırçalarda boyalar.

herşey yarım yamalak...

Korumayı bileceksin özelini! 

Toz kondurmayacaksın özeline,

kondurursan da,

temizliyeceksin.

Özür dilemeyi, gönül almayı bileceksin.

Ana -baba, akraba tamam ama,

yaşamın da senin olduğunu düşüneceksin.

Kendin ve onun için, güzel düşler kuracaksın.

Kurduğun bu düş; 

güzel bir toplum yaratmanın da bir parçası olmalı.

Ondaki farklılıkları, bir ayrılık değil,

ilişkinizin bir zenginliği olarak göreceksin.

Kendi güzel yanlarınla onu etkilemeyi,

ve onun güzel yanlarından beslenmeyi bileceksin.

Ama onu, asla değiştirmeye yeltenmeyeceksin.

Bilmeliyiz ki her insan; 

farklı şeylerden korkar.

Her insanın cesareti, dokunması.

sesi, nefesi,

ve sevgiyi yaşama şekli farklıdır.

Bazen sen Hanya dersin, o Konya! 

Ama ara bir yerde buluşmayı becereksin.

''benden'' daha  çok ''biz'' demeyi öğreneceksin.

Tüm bunlar; 

sevmek diye bir derdi olan, insanı ilgilendiren konular.

Diğerleri mi? 

Boşver sen onları.

Onlar otu-ayrığı hayatın,

kör, sessiz kuyuları.

Ve dışarda,

güzel güneşli bir hava.

Yağmur ve toprak kokusu.

çıldırasıya bir bahar.

Yeşillikleri, erik ağacı ve bembeyaz çiçekleriyle.

en güzel davetiye,

bir insanı sevmek isteyen kişiye!', 'Hepimizin var bir geçmişi. O, geçmişte yaşadığımız, yitirdiklerimizin gizli düşü. Sevmeye gelince;  o ayrı bir ustalık ve hüner işi. Bir san...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Cura']::text[], 8.5, '{"poet":"Muzaffer Cura","poet_slug":"muzaffer-cura","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-insana-sevgi-notlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (116) '' İslam Bizim Dinimiz...''', 'maniler-116-i-slam-bizim-dinimiz-abdullah-atay-ovvlb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözler benzer kömüre

Yanarım yarsız ömre

Sevip de sevilenin

Düşer gönlüne cemre...

Bu gönül bakar yola

Yürek yarsız kerbela

Sen kendini bilmezsen

Başa gelir her bela...

Dağlarda kara tiren

Odur yari getiren

Bu hasretlik değil mi

Beni yiyip bitiren...

Ağzındaki sakızı

‘çat pat çat pat’ patlatır

Gidi zalimin kızı

‘Gelcem’ diye atlatır...

Akşamlarda gün solar

Gönüle hüzün dolar

Gerçek aşkı bulanlar

Sevdasıyla ün salar...

Şu dağların beleni

Hiç çevirmez geleni

Yüce tanrım hoş tutar

Sevmesini bileni...

Dilinde tatlı sözle

Yoksul yetimi gözle

Dünya malın olsa da

Gidersin bir top bezle...

İslam bizim dinimiz

Asla yoktur kinimiz

Hoşgörü sevgi saygı

Budur asıl yanımız...', 'Gözler benzer kömüre Yanarım yarsız ömre Sevip de sevilenin Düşer gönlüne cemre... Bu gönül bakar yola Yürek yarsız kerbela Sen kendini bilm...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maniler-116-islam-bizim-dinimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Diye Diye', 'ah-diye-diye-yavuz-agir-nv1pg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül penceremi açtım

Yar diye diye

Yandım tutuştum birtanem

Gir diye diye.

Sevdanın rüzgarları eser başımdan

Aşk diye diye

Götürür beni uzaklara

Tanıtır  dost diye diye

Gel bir kerecik sar beni

Can diye diye

Ömür biter bakarsın

Vah diye diye

Ah diye diye....', 'Gönül penceremi açtım Yar diye diye Yandım tutuştum birtanem Gir diye diye. Sevdanın rüzgarları eser başımdan Aşk diye diye Götürür beni uza...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ah-diye-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
