INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solumdaki Sen', 'solumdaki-sen-serkan-turna-6bb2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl bir esaretsin sen

İleriye tek bir adım atamıyorum

Geriye dönmek istiyorum

Her adımda yine sen...

İki dünya arasında 

Sarhoş geçiyor hayatım

Sağımdaki melek şahit

Günahlarımın sebebisin sen.', 'Nasıl bir esaretsin sen İleriye tek bir adım atamıyorum Geriye dönmek istiyorum Her adımda yine sen... İki dünya arasında  Sarhoş geçiyor ha...', ARRAY['Türk Edebiyatı','Şiir','Serkan Turna']::text[], 8.5, '{"poet":"Serkan Turna","poet_slug":"serkan-turna","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/solumdaki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salında Gel', 'salinda-gel-mehmet-sait-akkus-16vs8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Salında gel

Koynuma gir

Yüreğime gir

Ruhuma gir

Tenin tenime

Elin elime değsin

Sıcak nefesin yüzüme vursun

Seni içimde hissetmek istiyorum

Bir bilsen senin için

Yüreğimde neler hazırladım sana

Sana bir saray hazırladım

Yollarını yazdıklarımdan

Halı yaptım yollarına

şiirlerden duvar yaptım

Sana sevdamdan dam yaptım

Seni öyle sevmişimki

Ölürcesine sevmişim

Delicesine sevmişim

Seni canımdan çok sevmişim

Ben seni manyakça sevmişim', 'Salında gel Koynuma gir Yüreğime gir Ruhuma gir Tenin tenime Elin elime değsin Sıcak nefesin yüzüme vursun Seni içimde hissetmek istiyorum B...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/salinda-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz imkansız', 'sensiz-imkansiz-arzu-dincer-rdlzv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz imkansız,

Tutunuyorum saçlarından,

Tamamlamaya ürktüğüm hayata.

Bir damla düşüyor,

Yüreğimin,

Sensiz kalma korkusu bürümüş,

Kederli yanına…

Senleyken bile, sensizlik boğuyor

Gökyüzü kararıyor

Ama…

Nafile yağamıyor

Bulutlar korkak, bulutlar bi çare

Düştü düşecek cemre,

Cemre, seninle yüreğime.

Sensiz imkansız

Saatler yelkovansız, akrepsiz..

Bozkırlaşmış kalabalık şehir..

Yapayalnız ve bi o kadar çıplak! 

İçimi ürpertiyor..

Nefesinin karışmadığı hava! 

Düşler kaldırıyor perdelerini,

Ve sahne.

Alkışlar adını çırpınıyor,

Uçuşmuyorsa sesler sensiz..

Sessizlik kaplıyor

Gölgen oluyor gölgem…

Sensizlik imkansız.', 'Sensiz imkansız, Tutunuyorum saçlarından, Tamamlamaya ürktüğüm hayata. Bir damla düşüyor, Yüreğimin, Sensiz kalma korkusu bürümüş, Kederli y...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensiz-imkansiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeytin Gözlüm', 'zeytin-gozlum-ramazan-bozkurt-jqnug', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızım şimdi ve senden çok uzaktayım 

Ömrümü adım adım mutsuz yaşıyorum

Kâbus dolu gecelerim,zifiri karanlıktayım

Seni arıyorum hep ZEYTİN GÖZLÜM

Çektiğim çileye,derdime aldırmıyorum

Eller mutlu olmuş ben nedir bilmiyorum

Yıllar geçse de aradan hiç unutamıyorum

Seni düşünüyorum hep ZEYTİN GÖZLÜM

Her güzele koşuyorum sen değilsin bakıyorum

Yürürken arkamda sen geliyorsun sanıyorum

Rüyalarımda hep bana gelirken görüyorum

Seni bekliyorum hep ZEYTİN GÖZLÜM

Bütün dileklerimde seni diliyorum

Dualarımda Allahtan seni istiyorum

İnan ki aşkından eriyip bitiyorum

Tek seni seviyorum ZEYTİN GÖZLÜM', 'Yalnızım şimdi ve senden çok uzaktayım  Ömrümü adım adım mutsuz yaşıyorum Kâbus dolu gecelerim,zifiri karanlıktayım Seni arıyorum hep ZEYTİN...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Bozkurt']::text[], 8.5, '{"poet":"Ramazan Bozkurt","poet_slug":"ramazan-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zeytin-gozlum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Çocuğum...(Çocuk Şiirleri 7)', 'ben-cocugum-cocuk-siirleri-7-mehmet-ayhan-gunaydin-szr5z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BEN ÇOCUĞUM…

(Çocuk Şiirleri 7) 

Ben çocuğum,

Dinleyin büyüklerim.

Çevrem güzel olsun,

Dünyamı güzel isterim.

Ağaç yeşil olmalı,

Çiçekle dolmalı her yer.

Çöle dönmüş dünyayı,

Söyleyin kim ister.

Sağlıklı yaşam benim en büyük hakkım,

El ele verin dünyayı böyle bir yer yapın

Yapamazsanız eğer,

Sizden bir gün hesap sorarım bakın.

Dinleyin beni, dinleyin büyüklerim,

Zor değil başarmanız, biraz gayret gösterin.

Ben çocuğum ben miniğim,

Sevgili büyüklerim.

Çok şey istemem sizden,

Geleceğime saygı gösterin…

M. Ayhan Günaydın.

    20 Şubat 2006 

          Ankara', 'BEN ÇOCUĞUM… (Çocuk Şiirleri 7)  Ben çocuğum, Dinleyin büyüklerim. Çevrem güzel olsun, Dünyamı güzel isterim. Ağaç yeşil olmalı, Çiçekle dol...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-cocugum-cocuk-siirleri-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babakale''de Olmak Vardı Şimdi', 'babakale-de-olmak-vardi-simdi-zeki-ergin-v3ldg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'akşam yaklaşınca

düşlememek olası değil

şimdi aklimanda 

Babakalede olmak vardı

ızgarada kupa balığı 

tam zamanıdır şimdi

sevenler için kalkardı kadehler

sessizlik çökerken bağlara

Hayri şiirler okurdu Yusufla

Orhan daha bir sıkı sarılırdı sazına

güneş Egeden yansırken dağlara

_erenköy 21şub06

_dağlara ver sırtını yt:haz09', 'akşam yaklaşınca düşlememek olası değil şimdi aklimanda  Babakalede olmak vardı ızgarada kupa balığı  tam zamanıdır şimdi sevenler için kalk...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/babakale-de-olmak-vardi-simdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm rehin kaldı ye’dieminde', 'gonlum-rehin-kaldi-ye-dieminde-salih-erdem-51lya', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sabahtı sevda zırhım yarıldı

Mal varlığım tespit ile derildi

His merkezim zapt oldu serildi

Gönlüm rehin kaldı ye’dieminde 

Bu nasıl sevmektir can pahasına

Bilseydim girmezdim aşk sahasına

Azalarım düşmüş hak davasına

Gönlüm rehin kaldı ye’dieminde

Çileye defterim o gün açıldı

Bilirkişi davam için seçildi

Bütün kusur sessiz cana biçildi

Gönlüm rehin kaldı ye’dieminde

Oysa hesap eski dimağda nihan

Kumanda beyinde azam figüran

Başlar bir ağızdan feryadı figan

Gönlüm rehin kaldı ye’dieminde

Ufkumu duygunla sildin sen diye

Hem kör hem de sağır ettin sen diye

Yurdumu gedaya kattın sen diye

Gönlüm rehin kaldı ye’dieminde

Ecelim bir sözde düşen ter midir? 

Düşmeyen ne bilir hâlim zor mudur? 

Davamın hâkimi aşka tor mudur? 

Gönlüm rehin kaldı ye’dieminde

Ben suçlu değilim içim hoş serin 

Sevgisiz hayata etmem ki yemin

Duygumu öldürüp diyemem âmin

Gönlüm rehin kaldı ye’dieminde

Uğruna bir ömür saçılan hazal

Sesiyle ruhumda raks eden gazel

Derdime gülünden em çalan güzel

Gönlüm rehin kaldı ye’dieminde

Doğurgan hüznünle beni aşerme

Kuruyan dalımdan aşka yeşerme

Dönülmez ufkuma yelken şişirme

Gönlüm rehin kaldı ye’dieminde

Erdemoğlu ne suç sabit görüldü

Ne de beraata ilam verildi

Meçhul duruşmaya dosyam sürüldü

Hal sürüncemede hissim dürüldü

Gönlüm rehin kaldı ye’dieminde

28.10.2005 17.20

31.10.2005 19.35 AYDIN

Geda: 1.Dilenci. 2.Yoksul, fakir

Hazal: Kuruyup dökülen ağaç yaprağı

Hal: 1.Çözme, çözülme 2.Karışık bir sorunun içinden çıkma, sonuca varma', 'Bir sabahtı sevda zırhım yarıldı Mal varlığım tespit ile derildi His merkezim zapt oldu serildi Gönlüm rehin kaldı ye’dieminde  Bu nasıl sev...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gonlum-rehin-kaldi-ye-dieminde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ağlayacağım', 'ben-aglayacagim-ramazan-bozkurt-qgxfr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün de sen geçmedin kapattım penceremi

Aşkıma karşılık vermedin diye herşeye küsmüşüm

Sen sevmedin işte yaktın cayır cayır yüreğimi

Gün doğmuş doğmamış bana ne zaten ölmüşüm

Süslenip gezersin ben ölürüm de bakamam

Gururumu yenip de artık seninle konuşamam

Üzülmene,bana kızmana inan ki dayanamam

Susarım da içimde volkanlar gibi kaynarım

Niye bilmem ki,beni niye sevmedin

Seni nasıl sevdiğimi galiba  bilmedin

Yüreğmi acımadan yollarına sererdim

Çıldırsam da sensiz,artık uzak duracağım

Mutluluklar sana mademki sevmiyorsun

Fazla yaşamam böyle bunu biliyorsun

Herşeyde serbestsin zaten elin oluyorsun

Bakma yıkılan halime git,ben ağlayacağım.

   

        (21.02.2006)', 'Bugün de sen geçmedin kapattım penceremi Aşkıma karşılık vermedin diye herşeye küsmüşüm Sen sevmedin işte yaktın cayır cayır yüreğimi Gün do...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Bozkurt']::text[], 8.5, '{"poet":"Ramazan Bozkurt","poet_slug":"ramazan-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-aglayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Mehmet Akif', 'sair-mehmet-akif-mehmet-akif-tiryaki-aaiic', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben şair olmuşsam herkes şair olabilir be

Yazın sizde bir şiir gönlünüzce

Gönderin antolojiye

Hayat nasıl olsa geçiyor öylede böylede

Veya dinleyelim

Eskilerden bir nihavent söylede...', 'Ben şair olmuşsam herkes şair olabilir be Yazın sizde bir şiir gönlünüzce Gönderin antolojiye Hayat nasıl olsa geçiyor öylede böylede Veya d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sair-mehmet-akif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asabiyet şiiri', 'asabiyet-siiri-volkan-i-ncel-8t6dl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimseye verilecek hesabım yok

Hesap sorulacak bir olay da yok

Hesap soracak bir adam da yok

Ne yani niye doğdun deseler

Konuşmam mı gerek

Konuşma deseler

Susmam mı gerek

Bu dünyada yaşarken

Birilerine hesap vermek mi gerek

İlla ki biri huzurumu kaçıracak

Sonunda bardağı taşıracak

Aç kalınca birine söylemek mi lazım

Aç isem kader,bu benim yazım

Laf yok; birazcık ekmek lazım

Git çalış diyecekler,sonra ekmek verecekler

Yok anam; kim veriyor sana bu yetkiyi

Benden önce doğduysan başın göğe  erdi mi

Merak ettim acaba bulutlara değdi mi

Benim kadar aklın yoksa yaşamaya hakkın yok

Diyorlar

Senin kadar aklım var da boş konuşmaya vaktim yok

Sen benim kadar düşünsen,üç gün geçmez yersin bok

Sen neyi düşünürsün

Para nasıl yapılır

Beş para etmez zengine,nerede nasıl tapılır

Ben neyi düşünürüm

Hayat nelerden ibaret

Doğruyu bilmek zannımca en büyük ibadet

Sen ancak ölürken dersin kelime-i şehadet

Ben ölüm aptallık derim

Çok, çok büyük rehavet

Asıl olan yaşam derim,ölüm elbet gelecek

Mümkünü burada bulmaktır,mutluluk ve saadet

Herkese ölüm müstahak

Elbet ecel gelecek', 'Kimseye verilecek hesabım yok Hesap sorulacak bir olay da yok Hesap soracak bir adam da yok Ne yani niye doğdun deseler Konuşmam mı gerek Ko...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/asabiyet-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her zaman aşka', 'her-zaman-aska-volkan-i-ncel-nt593', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her zaman bir zaman vardır aşka

Bir yolda yürürken

Ya da boş,boş dururken

Bir meyveyi seçerken

Bir yudum su içerken

Her zaman bir adım gider aşka

Bir otobüs geçerken

Yaprak yere düşerken

Bir gözyaşı  dökerken

Pantolonu giyerken

Her bakış bir bakış yapar aşka

Bir şans elden kaçarken

Ölürken ve yaşarken

Bir ibadet yaparken

Yıldızlara bakarken', 'Her zaman bir zaman vardır aşka Bir yolda yürürken Ya da boş,boş dururken Bir meyveyi seçerken Bir yudum su içerken Her zaman bir adım gider...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/her-zaman-aska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap ve Kadın', 'sarap-ve-kadin-volkan-i-ncel-8qaur', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şarabım nasıl böyle masum durabilirsin

Hadi başımı döndürsene

Anladım sende beni sevmekten korkuyorsun

Gel dudağıma değsene

O kadın beni sana nasıl tanıttı

Sen kendin denesene

Belki aynı tat aynı koku olacak

Hatıralar hep kalacak

Bakalım kim daha çok dayanacak

Kim daha çok yanacak', 'Şarabım nasıl böyle masum durabilirsin Hadi başımı döndürsene Anladım sende beni sevmekten korkuyorsun Gel dudağıma değsene O kadın beni san...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sarap-ve-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen bensin', 'sen-bensin-volkan-i-ncel-7810t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar vurdu yüzüme vefasızlığımı

Utandım

Döndüm yüzümü gölgelerden ışığa

İrkildim

Aya bakarken gözlerim,savunamadım seni

Pişmanım

Kirpiklerimde hissettim

Gerçektin

Düştün yanağıma

Islandım

Ağladım çıksın diye damlaların

Ağladım

İncittim seni diye

Korktum

Kırdım sandım kalbini

Bir mendil çıkartıp yüzümden 

Sildim 

Bastım bağrıma', 'Bir rüzgar vurdu yüzüme vefasızlığımı Utandım Döndüm yüzümü gölgelerden ışığa İrkildim Aya bakarken gözlerim,savunamadım seni Pişmanım Kirpi...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-bensin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeği Sevmek', 'cicegi-sevmek-volkan-i-ncel-47c0m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilir misin  çiçeği sevmesini

İncitmeden dermesini

Anlar o da sevenleri

Ona değer verenleri

Hoyratsa dokunuşun yapraklarına

Solar çiçek,solar ama

Ona bir isim takmazsan

Kucaklayıp da  sarmazsan

Hele gururuyla oynarsan

Solar çiçek,solar ama', 'Bilir misin  çiçeği sevmesini İncitmeden dermesini Anlar o da sevenleri Ona değer verenleri Hoyratsa dokunuşun yapraklarına Solar çiçek,sola...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cicegi-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mikdat Bal İbrahim Coşar 5. MSN Atışması', 'mikdat-bal-i-brahim-cosar-5-msn-atismasi-mikdat-bal-071mq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vatandan ayrılıp ayrı düşünce

Hep ağladım gülemedim, Coşarî

Hasret kazanına düştüm, pişince

Eridim de bilemedim Coşarî..........Mikdat Bal

Bir gün olsun gurbet ele çıkmadım

Vatanıma hasretlikte çekmedim

Dostum oldu yollarını bekledim

Ben gurbetçi olamadım Mikdatî….İbrahim Coşar

Genç yaşımda neler geçti başımdan 

Ayrı düştüm ana baba, eşimden

Gözlerim sel oldu akan yaşımdan

Hep çağladı silemedim Coşarî..........Mikdat Bal

Çarşamba’da  bende memur olmuşum

Evlenmişim mutlu yuva bulmuşum

Senin gibi dosta hasret kalmışım

Ne mal ne mülk alamadım Mikdatî....İbrahim COŞAR

Dertlerimiz çoktur çare bulunmaz

Balık suda yaşar ayrı kalınmaz

Malla mülkle asla mutlu olunmaz

Vatanımda ölemedim Coşarî......Mikdat Bal

Çoluk çocuk büyüdükçe zorlandım

 İsteklerim olmayınca harlandım

 Hak istedim, büyüklerce horlandım

 Dert büyüdü gülemedim Mikdatî.......İbrahim Coşar

Ters bakarlar çünkü Türktür aslımız

Eşkıyadır gözlerinde uslumuz

Göre göre zayi oldu neslimiz

Bırakıp da gelemedim Coşarî......Mikdat Bal

Çok zor gelir el yanında çalışmak

Rızkım için onla bunla dalaşmak

Burda zordur patronlara yanaşmak

Bende taviz veremedim Mikdatî.......İbrahim Coşar

Bura garip bir yabancı diyardır

Ayrı düşmek cehenneme ayardır

Gurbetçiler nerde olsa seyyardır

Bir yere kök salamadım Coşarî..........Mikdat Bal 

Şükür hasret kalmadık biz vatana

Saygı duyduk,hürmet ettik atana

Memleketi beş kuruşa satana

Gönlümde yer veremedim Mikdatî.........İbrahim Coşar

Mecbur kaldık zor işlerde çalıştık

Zamanla biz her eleme alıştık

Çelik gibi olduk artık geliştik

Başka çare buladım Coşarî.........Mikdat Bal

Lokma artık aslanların ağzında

Ne kışında hayır var ne yazında

Hiç birinin ayarı yok sazında

Akort edip çalamadım Mikdat’i İ.Coşar

Mikdatî’yim işte böyle çekeriz

Hep ağlarız yaşımızı dökeriz

Kader deriz boynumuzu bükeriz

Daha adam olamadım Coşarî......Mikdat Bal

Coşar’iyim dedim şiir yazayım

Kötülerin planını bozayım

Dost edinip, diyar diyar gezeyim

Çok dost buldum,doyamadım Mikdatî......İbrahim Coşar', 'Vatandan ayrılıp ayrı düşünce Hep ağladım gülemedim, Coşarî Hasret kazanına düştüm, pişince Eridim de bilemedim Coşarî..........Mikdat Bal B...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/mikdat-bal-ibrahim-cosar-5-msn-atismasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakımsız', 'bakimsiz-volkan-i-ncel-vk62r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sigaradan sararmıştı dişlerim

Ve artık toparlanmıyordu düşlerim

Uyku yatağımda kalmıştı

Kalem masamda

İçkim kadehteydi

Sen ise meçhulde

Gülleri avuçluyordum nefretle

Dikenleri bir,bir kalbimde

Ellerim titriyordu artık

Döşümde dayanılmaz bir ağrı

Ayrılık

Yüzleri  görmüyordu gözlerim

Yoksa bakamıyor muyum

Dünya bomboş olsa da

Ben seninle doluyum', 'Sigaradan sararmıştı dişlerim Ve artık toparlanmıyordu düşlerim Uyku yatağımda kalmıştı Kalem masamda İçkim kadehteydi Sen ise meçhulde Güll...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bakimsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay', 'dolunay-volkan-i-ncel-baib5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sakla kalbine koru beni

Yalnız gecelerde tut ellerimi

Kimseler kalmadı yanı başımda

Sen gitme dolunay tut ellerimi

Çiçekler güneşi görünce açtı

Yalnızlık ve korku meçhule kaçtı

Kabardı yüreğim sel oldu taştı

Sen gitme dolunay huzurum kaçtı

Karanlık geceme güneşim oldun

Gittiğin anlarda sarardım soldum

Islandı gözlerim yaş ile doldum

Sen gitme dolunay sil gözlerimi', 'Sakla kalbine koru beni Yalnız gecelerde tut ellerimi Kimseler kalmadı yanı başımda Sen gitme dolunay tut ellerimi Çiçekler güneşi görünce a...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dolunay-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazanoglu ozanimiza saygilar...', 'kazanoglu-ozanimiza-saygilar-yasar-gurlek-9t1zg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KAZANOGLU

Kozanoglu  cosmustur  askin  seliyle

Gonlumuze  girdi  tatli  diliyle

Sen  ne  bicim  bir  beysin  kazanoglu

Allah    yardimcin olsun ey  kazanoglu

Sazindan dokersin tatli nameyi

Kendini bilmeze yedir naneyi

Gel  beraber yikalim su  meyhaneyi

Allah    yardimcin olsun ey  kazanoglu

Ceylan dergahina hos geldin derim

Allahtan sana omur dilerim

Ah  varipda opsem  ellerin

Allah    yardimcin olsun ey  kazanoglu

Gurbette duydum  sazin  sozunu

Soyledikce  bildim  ozunu

Rabbim soldurmasin bahar  yazini

Allah    yardimcin olsun ey  kazanoglu

Yasar   derki    kazanoglu  benim  sahimdir

Onun ile bir gun tanismak  ahimdir

Senin gibi  dost bana  lazimdir

Allah    yardimcin olsun ey  kazanoglu

21-02-2006 

Yasar  gurlek

Hollanda', 'KAZANOGLU Kozanoglu  cosmustur  askin  seliyle Gonlumuze  girdi  tatli  diliyle Sen  ne  bicim  bir  beysin  kazanoglu Allah    yardimcin ol...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kazanoglu-ozanimiza-saygilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız', 'i-mkansiz-volkan-i-ncel-pootz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırmızı gül sarı olursa

Çöl tepelerinin karı olursa

Ben sevdanı unutacağım

Batmış dükkanın karı olursa

İnekler siyah süt verirse

Kutuplar arasına ip gerilirse

Ben aşkını hepten yıkacağım

Ölmüş ninem mezardan gelirse

Çiçekler arısız bal verirse

Yumurta kırılmadan civciv gelirse

Ben buradan çekip gideceğim

Dinozorlar devri gelirse', 'Kırmızı gül sarı olursa Çöl tepelerinin karı olursa Ben sevdanı unutacağım Batmış dükkanın karı olursa İnekler siyah süt verirse Kutuplar ar...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/imkansiz-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berduş', 'berdus-volkan-i-ncel-0qg59', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sırtını yaslamış tozlu duvara

Korkmayın tanırım yok bir numara

Her şeyini satmış vermiş kumara

Kardeşleri de  yatırmış bir güzel tımara

Kaçmış ellerinden yollara düşmüş

Tiksinmiş ardından insanlara küsmüş

Takati kalmamış açlıktan bayılmış  düşmüş

Mezarlık yolunda kendinden geçmiş

Neşeliydi zamanla neşe saçardı

Bela gelecek diye hepten kaçardı

Gariplere her zaman kucak açardı

Bir kuruşu olsa onlara saçardı

Alıp koyduk onu yatacak bir dört duvara

Korkmayın zararsız çatmaz adama

Eğer ki yapsaydı birine numara

Feleğe yapardı çoktan numara', 'Sırtını yaslamış tozlu duvara Korkmayın tanırım yok bir numara Her şeyini satmış vermiş kumara Kardeşleri de  yatırmış bir güzel tımara Kaçm...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/berdus-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Krallar da Ölür', 'krallar-da-olur-volkan-i-ncel-dxy0g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Krallar da  ölür büyük bir ihtişamla

Krallar da ölür köşklerde,saraylarda

Bazen yolda savaşlarda

Can giderken yalvarır gözünde yaşlarla

Tahta  sırtını verip canlar yakarken

Onun yüzü hep güler garipler ağlarken

Bir tek duvarlar görür onu ağlarken

Bir de Azrail görür  can diye ağlarken', 'Krallar da  ölür büyük bir ihtişamla Krallar da ölür köşklerde,saraylarda Bazen yolda savaşlarda Can giderken yalvarır gözünde yaşlarla Taht...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/krallar-da-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefil', 'sefil-volkan-i-ncel-66yzz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir buket gül aldı

İçine bir tek  karanfil

Tüm parasını harcadı,parasız kaldı sefil

Akşamdan kalan paketten bir sigara yaktı

Dumanıyla birlikte göğe bir miktar kan kalktı

Yolun hep solundan giderdi

Boynu bükük hüzünle vitrinleri süzerdi

İşsiz,aşık ve perişan gezerdi

Çalışmayıp kendince sitem ederdi

Gelip geçenler  bir haline,birde gül dolu eline baktı

Sandılar ki herhangi bir bahçeden kopardı

Hızlı adımlarla döndü köşeyi mutluydu

Çünkü sevdiği kadına gidiyordu

Kim beklerdi dört teker ecel olacak

Gelip bu sefilin canını alacak

Kaldırımda yakalamıştı eceli

Sonu böyle olmuştu haktan tecelli', 'Bir buket gül aldı İçine bir tek  karanfil Tüm parasını harcadı,parasız kaldı sefil Akşamdan kalan paketten bir sigara yaktı Dumanıyla birli...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sefil-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemeyi Ne Bilirsin Sen', 'ozlemeyi-ne-bilirsin-sen-sair-emre-bulut-acll1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana aşktan hiç söz etme 

Sen sevmeyi ne bilirsin 

Bir aşk için ölesiye 

Beklemeyi ne bilirsin 

Düşündükçe içim yanar 

Ders vermemiş sana yıllar 

Taştan farksız kalbin mi var 

Özlemeyi ne bilirsin sen', 'Bana aşktan hiç söz etme  Sen sevmeyi ne bilirsin  Bir aşk için ölesiye  Beklemeyi ne bilirsin  Düşündükçe içim yanar  Ders vermemiş sana yı...', ARRAY['Türk Edebiyatı','Şiir','Şair Emre_bulut']::text[], 8.5, '{"poet":"Şair Emre_bulut","poet_slug":"sair-emre-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlemeyi-ne-bilirsin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenir gider', 'tukenir-gider-kenan-bicer-zjklp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güller dalında güzeldir 

sevdalılar sevdikçe güzel

maşuk aşığına gül goncası der

gülleri ayaklarına serer

aşıklar mutlu ama

güller kuruyup gider

uzun sürmez sevdaları

mevsimlik kopup gider

güllerin günahını

yalan aşıklar çeker

kaderi devri alem

incecik solup gider

dönmesine döner dünya

ama gün gelir

sevgisiz tükenir gider

aşk yalanını yine 

kim ölesi düşler

belkide görünmeyen mucizeler 

aşkı cihan eyler mi eyler', 'Güller dalında güzeldir  sevdalılar sevdikçe güzel maşuk aşığına gül goncası der gülleri ayaklarına serer aşıklar mutlu ama güller kuruyup g...', ARRAY['Türk Edebiyatı','Şiir','Kenan Biçer']::text[], 8.5, '{"poet":"Kenan Biçer","poet_slug":"kenan-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tukenir-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşmayacağım arkadaş', 'konusmayacagim-arkadas-volkan-i-ncel-jut93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba arkadaş

İyi akşamlar

Şuraya ilişsem sakıncası yoksa

Hayır terk etmedi

Gözlerim mi? 

Benim gözlerim  yalancıdır

Gülerken ağlar

Konuşmayacağım zaten

Tabii sen sanıyorsun ki

Başlayacağım anlatmaya saatlerce

Önce saçları diyeceğim,kızıl bir güldü

Kadife,kadife idi yumuşak

Dokununca,aralayınca parmaklarınla

Beyaz,beyaz görünürdü altından teni

Teni ipekti

Hiçbir mezatta bulamazdın

Dünyaları versen alamazdın

Başlamışken gözlerinden de bahsedeceğim sanıyorsun değil mi

Bin bir  benzetme yapacağım

Yok zeytin,yok kömür 

Ya da elmas diyeceğim kapkara

Elleri pamuk gibi Adana’dan

Gece ile gündüz paylaşırken zamanı 

Tarlaya serpilen en güzel tohumdan çıkmıştı diyeceğim

Bir sigara verirsen daha fazla konuşmam

Anlatmam sana dudaklarını

Günün her saati; eriyen kar suları gibi  serin ve tatlıydı demem

Terk etmedi diyorum ya! 

Ya da öyle zannediyorum

Söylemeyeceğim arkadaş

Sen de ne meraklısın

O benim sevdiğim ve terk etmedi beni

Anlatmayacağım,uyandığımda yatağımda olmadığını

Toparlanıp erkenden çekip gittiğini', 'Merhaba arkadaş İyi akşamlar Şuraya ilişsem sakıncası yoksa Hayır terk etmedi Gözlerim mi?  Benim gözlerim  yalancıdır Gülerken ağlar Konuşm...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/konusmayacagim-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyaymış', 'ruyaymis-volkan-i-ncel-tyro7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kargalar geziniyor bak ıssız şehrin üstünde

Sanki ölüm kokusu çıkıyor kentten

Sessizlik hakim olmuş tüm caddelere

Terk etmişler virane gama,derde,kedere

Işıklar yanmıyor hiç,hava da olanca soğuk

Bir inilti geliyor derinden sanki,hissiz ve boğuk

Sanki o da terk edilmiş şehirle

Bir el uzanıyor kargaların ardından

Bir el kapkara olmuş kederinden yasından

Kargalardan aman diliyor,alın bu karanlıktan

Kargalar geziniyor bak ıssız şehrin üstünde

Sanki alay ediyorlar benimle cak,cak gülerek

Onlara da mı   söyledin terk edip gittiğini

Ölümsüz aşkımızın ölmeden bittiğini

Dalıp,dalıp çıkıyor kargalar kafamın üstüne

Yolup,yolup atıyorlar saçlarımı kendi dibine

Kovalıyorum bitap düşen yaralı yüreğimle

Bak; hatıran olan resmin kararmış,ellerimde

Gidin diyorum buradan güçlüyüm daha ölmedim

Bende kaldı yüreğim kargalara vermedim

Kan ter içinde kaldım,aklım uçtu gitti sanki

Ölürdüm bu rüyada öpmeseydin inan ki', 'Kargalar geziniyor bak ıssız şehrin üstünde Sanki ölüm kokusu çıkıyor kentten Sessizlik hakim olmuş tüm caddelere Terk etmişler virane gama,...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruyaymis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Limonlu sevda', 'limonlu-sevda-volkan-i-ncel-kwwtw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Limonlu sevdam,biraz ekşili

Öpünce hemen tatlanır

Birazcık görmese

Meraktan delirir

Ben gelince saklanır

Sevdam sararır 

Güneşin batışıyla

Ben kalırım 

Hayat yol alır

Uyanır bakarım

Sevdam uçup gitmiş

Dilimde ekşi

Tadı kalır', 'Limonlu sevdam,biraz ekşili Öpünce hemen tatlanır Birazcık görmese Meraktan delirir Ben gelince saklanır Sevdam sararır  Güneşin batışıyla B...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/limonlu-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi ayırırlar', 'bizi-ayirirlar-volkan-i-ncel-yw0ow', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doruklara kar mı yağdı

Bizim ele kış mı geldi

Ayıran dikenli teldi

Sanki yüreğimi deldi

Yolları kapanmış kardan

Bir haber gelmiyor yardan

Yansın bizleri ayıran

Yok mu bizi bir kayıran

Bir yaralı ceylan idin

Neden bu dağlardan indin

Bizi ayırırlar bildin

Neden bir haber vermedin', 'Doruklara kar mı yağdı Bizim ele kış mı geldi Ayıran dikenli teldi Sanki yüreğimi deldi Yolları kapanmış kardan Bir haber gelmiyor yardan Ya...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bizi-ayirirlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Türkiye Düşüm', 'buyuk-turkiye-dusum-yusuf-ziyaeddin-sivaslioglu-fchks', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağız bir ata bindim

Yollara düştüm

Düşlerimin peşinde

Otuz altı yıl koştum.

Karlı dağlarına çıktım

Soğuk pınarlarından içtim

Vatan diye kendimden geçtim

Sakıncalı duruma düştüm.

Yiğitlerle tanıştım

Merdiyle el tutuştum

Namerdin şerriyle

Nice yıl boğuştum.

Yağmurdan bereketi

Çamurdan toprağı tanıdım

Vatanımdır diye

Taşına, toprağına sarıldım.

Yüreğimde sevdim çocukları

Zamanla acıdı canları

İstedim Mahşer Gününde

Dik dursun diye başları.

Yıl iki bine  geldi

Gençlere bıraktık yarışı

Sakın düşünmeyin Gençler,

Ordusuz bir barışı.

Gençler, bu düşün adı

Büyük Türkiye Davası

Yağız atlar koşacak

Türkiye yerini bulacak.

(İstanbul, 20 Şubat 2006)', 'Yağız bir ata bindim Yollara düştüm Düşlerimin peşinde Otuz altı yıl koştum. Karlı dağlarına çıktım Soğuk pınarlarından içtim Vatan diye ken...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/buyuk-turkiye-dusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum', 'dogum-volkan-i-ncel-mxl4t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben erken terkedilmişliğime ağlıyordum

Onlar ise bilimden bahsediyorlardı

Ben bulamayacağıma ağlıyordum

Sıcaklığını rahmin

Onlar ise sevinçten

Ben yüz yıl erken doğmuştum

Ne yedi ayı?', 'Ben erken terkedilmişliğime ağlıyordum Onlar ise bilimden bahsediyorlardı Ben bulamayacağıma ağlıyordum Sıcaklığını rahmin Onlar ise sevinçt...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dogum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiddet', 'siddet-volkan-i-ncel-8hrnc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni as

Doğra beni

Lime,lime her hücremi

Kaz elinle

Kanım akıt

Dök yerlere,at sinemi

Savur külüm 

Dağdan,dağa

Gübre eyle

At toprağa

Her parçamı 

Uzaklara

Sınır eyle yolla beni

Vazgeç deme 

Vazgeçemem

Senden başka

Yar seçemem

Candan gayrı 

Neyim kaldı

Yetmez ise sarma beni', 'Beni as Doğra beni Lime,lime her hücremi Kaz elinle Kanım akıt Dök yerlere,at sinemi Savur külüm  Dağdan,dağa Gübre eyle At toprağa Her parç...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siddet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ver Eşeğimi Felek', 'ver-esegimi-felek-volkan-i-ncel-gf921', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yetmiyor mu  bin bir çile

Sevme dedin,sevdim bile

Hasret kaldı bülbül güle

Hasret koyma beni felek

Acıyı ilaç eyledim

Geceleri kaç eyledim

Bilmem ki sana neyledim

Naçar koyma beni felek

Yuvarlarım gitmez kaya

Ömür yetmez öbür aya

Eşek varken beni yaya

Koyma dedim koydun felek

Çıktım,çıktım tepe bitmez

Kurak çölde güller bitmez

Derman bitti beden gitmez

Ver eşeğim alma felek', 'Yetmiyor mu  bin bir çile Sevme dedin,sevdim bile Hasret kaldı bülbül güle Hasret koyma beni felek Acıyı ilaç eyledim Geceleri kaç eyledim B...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ver-esegimi-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasta Sevdalı', 'hasta-sevdali-volkan-i-ncel-cowy3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıtmalı sevda nöbetine tutuldum

Ellerim istem dışı titriyor

Kalbim benden habersiz çarpıyor

Soluk alışlarım düzensiz

Düşüncem yok oluyor

Kelimeler saçma

Konuşsam desem ağlıyorum

Bir noktam yok,dağılıyorum

Kapılar kapalı cereyan yapıyor

Kendi nefesim dönüp beni çarpıyor

Üşüttüm böbreğimi

O da sızlıyor

Helaya girmem yeter idrar akıyor

Titremeler aralıksız,iyice arttı

Gözlerim dünyaya sanki son kez baktı

Acilen bir sevda bulup sevmem gerekli

İlacım olmalı onda

Beni iyi etmeli

Halden anlasın yeter o da gerekli

Şöyle doksan altmış doksan,melek yürekli', 'Sıtmalı sevda nöbetine tutuldum Ellerim istem dışı titriyor Kalbim benden habersiz çarpıyor Soluk alışlarım düzensiz Düşüncem yok oluyor Kel...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasta-sevdali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alemciler', 'alemciler-reyhan-tataroglu-glvk7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşadıkları; 

                                 ne bu alem

                                 ne öbür alem

                                 bunlarda

                                 bi alem...', 'yaşadıkları;                                   ne bu alem                                  ne öbür alem                                  bun...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/alemciler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdamlığım Ben(ktb alnt)', 'i-damligim-ben-ktb-alnt-sedat-kocabey-3tyji', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hem derdimi çektin hemde çilemi,

Müebbete mahkum idamlığım ben.

Herzaman affettin aşkta hilemi,

Müabbete mahkum idamlığım ben.

Zindanlara atsan hakkın var derim,

Aldığım nefeste katkın var derim,

Çekipte vurmaya yetkin var derim,

Müebbete mahkum idamlığım ben.

Hep kötü gününde yalnız bıraktım,

Yanına gelmeyip uzaktam baktım,

Unuttum kaç kere canını yaktım,

Müebbete mahkum idamlığım ben.

Gözümü bağlayıp kurşuna dizsen,

Parça parça edipderimi yüzsen,

Sesimi çıkarmam başımı ezsen,

Müebbete mahkum idamlığım ben.', 'Hem derdimi çektin hemde çilemi, Müebbete mahkum idamlığım ben. Herzaman affettin aşkta hilemi, Müabbete mahkum idamlığım ben. Zindanlara at...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/idamligim-ben-ktb-alnt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın da Yaşıyalım(ktb alnt)', 'birakin-da-yasiyalim-ktb-alnt-sedat-kocabey-pury4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Es geçmeyin çocuk deyip sözümüze kulak verin,

Sizden arta kalanları yarınlara taşıyalım,

İmha edin silahları demet demet güller derin,

Savaşmayıp barışında bırakında yaşıyalım.

Hani bize emanetti bu dünyanın geleceği,

Kimbilir ne zor günler var çocukların göreceği,

Daha başlarken belliydi bunun uzun süreceği,

Savaşmayıp barışında bırakında yaşıyalım,

Üstümüzde kara bulut nefes bile alamazken,

Koklamaya hasret kaldık çiçek bile bulamazken,

Talan olmuş bu dünyada hayal gerçek olamazken,

Savaşmayıp barışında bırakında yaşıyalım.', 'Es geçmeyin çocuk deyip sözümüze kulak verin, Sizden arta kalanları yarınlara taşıyalım, İmha edin silahları demet demet güller derin, Savaş...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birakin-da-yasiyalim-ktb-alnt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik yap...', 'i-yilik-yap-reyhan-tataroglu-vq4nx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'söylendi...

                              şaşkın şaşkın

                              hiç olur mu

                              iyilik sebepsiz

                              tabii ki...

                              sebep biz

                              sebep siz

                              böyle düşünmeyen 

                              edepsiz

                              fiiliyattan önce niyet

                              güzel olursa zihniyet

                              yapılan faaliyetlerde 

                              çekilmez hiç eziyet

                              yarım hurma hediye

                              veriyorsun ne diye

                              kimi arar,kimi bulur

                              rıza...rıza... diye diye

                              öyle bir hale bürün

                              Hak olsun dünürün

                              aşk ile yan ki

                              iyilik dolsun ürünün

                              buyuruyor; 

                              var ki öyle kullarım

                              birbirini tanımaz

                              yine de iyilik yapar

                              kimselerce tanınmaz

                              gıpta ile bakacak 

                              peygamberler,şehitler

                              sureler,ayetler, hadisler 

                              de şahitler...', 'söylendi...                               şaşkın şaşkın                               hiç olur mu                               iyilik sebep...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/iyilik-yap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşkelerin Sonuçsuz Kaldığı An', 'keskelerin-sonucsuz-kaldigi-an-hasan-can-d6mwl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrı dünyaların birleştiği keder durağıdır gece,

Hep aynı hüzünler yaşatır koynunda,

Umutları saklar karanlığına güvenerek,

Aşkın telaşına düşenleri çekiverir dipsiz kuyularına.

Ayrılığın sebep olduğu yalnızlık,

Acının ibresini biraz daha yükseltir.

Güzel yaşanmışlıklar canlanır bir an,

Sonra hüzne bürür hatıralar, gözler nehre dönüşür...

Her insan gecede bulur doğrularını,

Karanlıkta yüzleştiği kişi kendisidir.

Başka bir bedenin derdine düşmektense,

Kendi derdinin ortağı olur...

Tutarlı olmak zor boşluğun kaçınılmaz olduğu,

Dudakların bile kelime üretmekte zorluk çektiği,

Her an acının başka bir acıya büründüğü,

Yeni yeni hatıralardan serzeniştekyen....', 'Ayrı dünyaların birleştiği keder durağıdır gece, Hep aynı hüzünler yaşatır koynunda, Umutları saklar karanlığına güvenerek, Aşkın telaşına d...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/keskelerin-sonucsuz-kaldigi-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoktun be Annem(ktb alnt)', 'yoktun-be-annem-ktb-alnt-sedat-kocabey-aee9n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimden ağlamak geldi bu akşam,

Gözümde yaş olup aktın be annem,

Özlemin bağrımı deldi bu akşam,

En mutlu günümde yoktun be annem.

Elime kınalar yakıldığında,

Başıma duvaklar takıldığında,

Yüreğim daralıp sıkıldığında,

En mutlu günümde yoktun be annem.

Kalbimin üstüne koydum resmini,

En kutsal duadan saydım ismini,

Yanımda bulurken her an cismini,

En mutlu günümde yoktun be annem.

Siyah saçlarını kimler taradı,

Besleyip büyüttün kime yaradı,

Gözlerim heryerde seni aradı,

En mutlu günümde yoktun be annem.

Aklımdan çıkmıyor ansız gidişin,

Gözümün önünde cansız gidişin,

ALLAHTAN revamı bensiz gidişin,

En mutlu günümde yoktun be annem.', 'İçimden ağlamak geldi bu akşam, Gözümde yaş olup aktın be annem, Özlemin bağrımı deldi bu akşam, En mutlu günümde yoktun be annem. Elime kın...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yoktun-be-annem-ktb-alnt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka İsteğin Varmı?', 'baska-i-stegin-varmi-mustafa-uzun-80qmh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülüyorsun kıkır,

Yaşıyorsun tıkır tıkır,

Oynuyorsun şıkır şıkır,

Başka bir isteğin var mı? 

Göbek açık, yırtmaç yana,

O bar değil, gel bu bara,

Meze, rakı, yak sigara,

Başka bir isteğin var mı? 

Allan pullan süslen güzel,

Köpüklerde ıslan güzel,

Şusi, havyar beslen güzel,

Başka bir isteğin var mı? 

Her şey sana kucak kucak,

Bu dünyada kim kalacak,

Hızlı yaşa keyfine bak,

Başka bir isteğin var mı?', 'Gülüyorsun kıkır, Yaşıyorsun tıkır tıkır, Oynuyorsun şıkır şıkır, Başka bir isteğin var mı?  Göbek açık, yırtmaç yana, O bar değil, gel bu b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Uzun']::text[], 8.5, '{"poet":"Mustafa Uzun","poet_slug":"mustafa-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baska-istegin-varmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sen', 'ya-sen-hasan-cam-jfeex', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hançer, kılıç, kınında saklı, ya sen 

Yağmur bulutlarda, yavru ana koynunda

Günahlar cehennemde, sevaplar cennette

Sevdan yüreğimde, en derinde

Ya sen,

Ben sevdamı kaybettim, sevgimi değil

Her acını duydum kalbime sarıldım, hançer diye

Ama seni buldum hep, yine sen vardın

Çıban başı oldu gönlüm, ağrı dağı sandım

Ya sen

Susmaya, unutmaya çalıştım olmuyor

Avade ömrüm, gül, yaprak gibi soluyor

Dağları, taşları deldim, kalemleri tükettim

Sayfalar bitti, sevdan beni yoruyor

Ya sen 

Her ezan duvamsın, yanıltmasın çan sesleri

Sanmaki bu sevda aciz, bizden utansın

Silemiyor gönlüm, içimde hisleri, yüzümde çizgileri

Yargılıyor sinem, içime çökmüş sensiz hüzünleri

Ya sen

21 02 2006

Ümraniye İstanbul

[email protected]', 'Hançer, kılıç, kınında saklı, ya sen  Yağmur bulutlarda, yavru ana koynunda Günahlar cehennemde, sevaplar cennette Sevdan yüreğimde, en deri...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ya-sen-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastahane Günlerim', 'hastahane-gunlerim-munevver-senol-hm0rx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kollarım delik deşik hep kanımı aldılar.

Beni sanki kanbankası sandılar.

Buyurun buyurun ayağımdan da alın.

Alın bak, almassanız hatırım kalır.

Yaa kardeşim bunebiçim iştir böyle! 

Buna can mı dayanır? 

Beni insan değil kan bankası sandılar.

Kollarım yetmezmiş gibi elimin üstünüde deldiler.

Bir de süs olsun diye kelebeği koydular.

Kelebek dediğime bakmayın sakın.

Bizim bildiğimiz kon kon kelebek yaldızlı böcek değil.

Bu arı gibi iğnesini damarına batıran can yakan kelebek.

Neyse sabret Müniş bu da geçecek elbet.

Sen nelere dayandın da bir kelebekten mi korkucan? 

Bir iyileşte bak, 

Yürümeyeceksin koşacaksın.

Ha gayret Müniş göreyim, 

Şiir dostların bekliyor seni.

Yürümek ne kelime 

Yürümeyeceksin koşacaksın koşacak.

23.07.2003', 'Kollarım delik deşik hep kanımı aldılar. Beni sanki kanbankası sandılar. Buyurun buyurun ayağımdan da alın. Alın bak, almassanız hatırım kal...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hastahane-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlediğim Yardır Benim(ktb alnt)', 'ozledigim-yardir-benim-ktb-alnt-sedat-kocabey-l9uwj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep doğrudan yana oldum,

İçim dışım birdir benim,

Hakka giden bir yol buldum,

Sanma gözüm kördür benim.

Hem okudum hemde yazdım,

Kararmadım hep beyazdım,

Kum eledim kerpiç dizdim,

Alnımdaki ter''dir benim.

Sevdan kora döndü bende,

Can emanet bu bedende,

Teslim etmeden gel sende,

Özlediğim yar''dır benim.

Bazen haksız bazen haklı,

Ne süslüyüm ne pasaklı,

İçimde ne sırlar saklı,

Bir bildiğim vardır benim.', 'Hep doğrudan yana oldum, İçim dışım birdir benim, Hakka giden bir yol buldum, Sanma gözüm kördür benim. Hem okudum hemde yazdım, Kararmadım ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozledigim-yardir-benim-ktb-alnt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öcü', 'ocu-hidir-altas-qe7l7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilinden gocunduğun ırkın

İnsanı bir zamanlar eyyy Almanya

Sıkıştığında gemilerine kapıyı

Ardına kadar açmıştı be

Türkçe konuşuyor diye staddan

Kolundan tutup atarken dışarı

Tarihini düşündünmü ey Almanya

Cihan harbinden çıkınca

Dost diye çağırdın insanımızı

Köle gibi çalıştırdın fabrikanda

Adammı oldun şimdi eyyy Almanya

Benim işçimin tırnak sızısı var

Yediğin her lokmada düşünsene

Öcü bildiğin TÜRK insanının

Hizmeti vardır her sokağında

Turhani kızar oldu eziyetlerine

Hele kapı dışarı ettiğin gence

Utanmazlığına kuduruyor şimdi

20.02.2006 aşık Turhani-ANTALYA', 'Dilinden gocunduğun ırkın İnsanı bir zamanlar eyyy Almanya Sıkıştığında gemilerine kapıyı Ardına kadar açmıştı be Türkçe konuşuyor diye stad...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ocu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahtekar(ktb alnt)', 'sahtekar-ktb-alnt-sedat-kocabey-l0xkr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Durduk yere dirilttin gönlümdeki volkanı,

Nasılda göremedim boynumdaki halkanı,

Hep içime akıttım siğnemdeki al kanı,

Seni gidi vefasız seni gidi riyakar,

Seni gönül hırsızı seni gidi sahtekar.

Ne biraz vicdanın var nede bir pişmanlığın,

Ne istedin sevgimden nedir bu düşmanlığın,

Bumu aşka mükafat bumudur insanlığın,

Seni gidi vefasız seni gidi riyakar,

Seni gönül hırsızı seni gidi sahtekar.

Her sözünde bir yalan har işinde bir hile,

Parmağında oynattın koca şeytanı bile,

Ölüm marşı söylettin şu güzelim bülbüle,

Seni gidi vefasız seni gidi riyakar,

Seni gönül hırsızı seni gidi sahtekar.

Taşmı taşıyorsun o kalbinin yerinde,

Hiç mi sızı duymadın ta içinde derinde,

Senide yakan olur elbet günün birinde,

Seni gidi vefasız seni gidi riyakar,

Seni gönül hırsızı seni gidi sahtekar.

Hangi yaşı ellesen kuruyup sararıyor,

Göğe başını diksen gün bile kararıyor,

Çek elini üstümden nefesim daralıyor,

Seni gidi vefasız seni gidi riyakar,

Seni gönül hırsızı seni gidi sahtekar.

Sanmaki unuturum bana yaptıklarını,

Hangi söz imar eder bende yıktıklarını,

Süpürüp çöpe attım bütün artıklarını,

Seni gidi vefasız seni gidi riyakar,

Seni gönül hırsızı seni gidi sahtekar.

Seninle ödeşiriz elbet günün birinde,

Sana ait herşeyi gömdüm ta en derinde,

Seni çekip vururdu kim olsaydı yerimde,

Seni gidi vefasız seni gidi riyakar,

Seni gönül hırsızı seni gidi sahtekar.', 'Durduk yere dirilttin gönlümdeki volkanı, Nasılda göremedim boynumdaki halkanı, Hep içime akıttım siğnemdeki al kanı, Seni gidi vefasız seni...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sahtekar-ktb-alnt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak ayakla basıp', 'ciplak-ayakla-basip-fatma-guven-ln2y5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çıplak ayakla basıp toprağın bağrına, 

Ayaklarımı yaktım sıcaklığıyla.

Bir bırakılmışlık kendimi,

Teslim edilmişlik,

O doyulmayan ılıklığa.

Ben de benzemişim biraz toprağa.

Anladım varlığım suçlu.

Sıcaklığım,içtenliğim! ...

İnan yok yüreğimde bir kötülük.

Baştan çıkarma çabası,

Yada baştan çıkarılmışlık.

Yüreğimden gelen sıcaklığa, 

Sararım her şeyi.

Ne yapayım şimdi? 

Sorayım mı tanrıya! ....

Neden beni böyle yarattın diye! 

Kimi cana can katmak,

Kimi yoldaşa yoldaş olmak, 

Dost yüreklere ise dört elle,

Sarılmaktır muradım.', 'Çıplak ayakla basıp toprağın bağrına,  Ayaklarımı yaktım sıcaklığıyla. Bir bırakılmışlık kendimi, Teslim edilmişlik, O doyulmayan ılıklığa. ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ciplak-ayakla-basip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim İçin', 'bizim-i-cin-i-smail-zengin-l0ehr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbi açıktı geride kalanların

Giden için

Hüznü büyüktü bekleyenlerin

Biten için

Sevgi doluydu artık herkes

Solan için

Yapacak hiçbir şeyleri yoktu 

Onun için

Sessizlik yapılamazlıktı 

Tümü için

Anlamışlardı ölüm 

Bizim için.

Bir fırsattı aslında

Ağlamak için

Rahatlamak,susmak,

Derin derin düşünmek için.

Acizliği tam hissetmek,

Geçiçiliği anlamak için

Aslında ağlıyordu her biri

Kendi için

Anlaşıldı ölüm

Bizim için.', 'Kalbi açıktı geride kalanların Giden için Hüznü büyüktü bekleyenlerin Biten için Sevgi doluydu artık herkes Solan için Yapacak hiçbir şeyler...', ARRAY['Türk Edebiyatı','Şiir','İsmail Zengin']::text[], 8.5, '{"poet":"İsmail Zengin","poet_slug":"i-smail-zengin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bizim-icin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-mustafa-ceylan-kk8rc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzayan yollarda seni beklerim

Titreyen gölgeme basıp öyle git.

Özledim buseni sızlar her yerim

Buseni gölgeme asıp öyle git.

Ateş-i aşkınla hep yanayım mı? 

Oturup bir güzel ağlayayım mı? 

Ayrıldık diyorsun inanayım mı? 

Selâmı, sabahı kesip öyle git.

Gonca bir dudakta duran gülüştüm

Her gece rüyâmda senle öpüştüm

Bir cemre misali toprağa düştüm

Rüzgâr ol, üstümden esip öyle git.

Aşkıma şahitti bu dağ bu deniz

Bitmezdi güzelim asla sevgimiz

Yaşamam imkânsız bitanem sensiz

Gözümden, gönlümden düşüp öyle git.

Bu dertli âşığı sarhoş ettin de

Terkedip uzağa çekip gittin de

İstersen son defa ''seviyorum'' de

Etmeden vedanı küsüp öyle git.

Gittiğim Cennetse sensiz istemem

Bilirsin hasreti sonsuz istemem

Kırarım aynayı bensiz istemem

Bakma sen yüzüme susup öyle git.

Unuttun Ceylan''ı köşe başında

Hicranı dururken gözün yaşında

Gömüp de kabire ahir yaşında

Ahrete bileti kesip öyle git.', 'Uzayan yollarda seni beklerim Titreyen gölgeme basıp öyle git. Özledim buseni sızlar her yerim Buseni gölgeme asıp öyle git. Ateş-i aşkınla ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/git-168-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşyalar', 'esyalar-i-smail-zengin-e7qjp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni ancak bana durgun durgun bakan eşyalar anlar

Evet bu bakışta bir anlam,bir derinlik var.

Gecenin uzayıp giden sessizliğinde,kendini dinletişinde

Bana beni bulduran bir huzur,bir dinginlik var.

Sessizce girerim odalara,salona

Bana nazar eden varlıklarla kol kola

Ne ihanet ederler ne terk ederler

Ben dost olmuşum onlarla.', 'Beni ancak bana durgun durgun bakan eşyalar anlar Evet bu bakışta bir anlam,bir derinlik var. Gecenin uzayıp giden sessizliğinde,kendini din...', ARRAY['Türk Edebiyatı','Şiir','İsmail Zengin']::text[], 8.5, '{"poet":"İsmail Zengin","poet_slug":"i-smail-zengin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/esyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatlı Kaplumbağa', 'kanatli-kaplumbaga-mehmet-kiyak-ximiz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevdim, değer verdim,

Seni başımın tacı ettim,

Beni anlarsın diye.           

Seni göklere çıkardım,

Kanat taktım,

Yükselsin diye.  

Sense hep havalarda kaldın,

Hep yükseklerden baktın.

“Gel kalbimde kal”, dedim,

“Kabuğun var”, dedin.

Bakıyorum da,

Ayakların yere basmıyor,

Şimdi burnun pek havada! 

Oysa,

Senin kanatların benim,

A kaplumbağa! 

19.02.2006

Mehmet KIYAK', 'Seni sevdim, değer verdim, Seni başımın tacı ettim, Beni anlarsın diye.            Seni göklere çıkardım, Kanat taktım, Yükselsin diye.   Se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kıyak']::text[], 8.5, '{"poet":"Mehmet Kıyak","poet_slug":"mehmet-kiyak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kanatli-kaplumbaga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Tanımadın mı Anne?', 'beni-tanimadin-mi-anne-faik-danisman-cmf8l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koynundan alıp uzak kentlere,

Sürgün ettiler Anne..

Aldılar benden sıcaklığını,

İçime bir buz kütlesi koydular anne…

Çalıp şefkatini üzerimden,

Yüreğimde derin izler bıraktılar Anne

Duvarları üstüme,

Kapıları yüzüme  örttüler Anne,

Sardığın kundakta kaldı son kimliğim

Çocukluğumu benden çaldılar Anne

Kelepçelerin pasında saklıydı benliğim

Çırılçıplak,yalınayak,aç,sersefil

Zifiri karanlık gecelerde,

İçimi acıttılar..…

Ağlayışlarımı duymadın mı Anne? 

Seni yazdım her beyaz çizgide…

Dizlerine yatıp, konuştum saatlerce seninle

Beni hissetmedin mi Anne? 

Zaman karanlık bir ay çalıyor duvarlarıma

Gölgeler siyah beyaz çiziyor suretini

Yüzünü hatırlayamıyorum Anne

Beynimin içinde el olsan da uzaktan

Kalbim anne diye feryat ediyor yeniden

Bana masal anlatsana Anne…..

Bu hayatta en çok seni sevdim… bilmiyorsun

Doyamasam da  kokuna, hücrelerime işledin

Dokunamasam da …benim en kutsalımdın…

ve seni öyle özledim ki Anne…….bilemezsin.

isyankar değilim ……….yıllara hesap soramam

günahkar hiç  değilim…..kadere cevap veremem

karnında taşıdığın günlerin hatırı var.,inkar edemem

Bağışla beni güzel Annem….

İşte karşındayım yılların hesap sancısıyla

Sevgisiz büyümüşlüğüm,öksüzlüğüm üzerimde

Şefkatin olmasa da,merhamet niyetine

Ellerin dolaşsın başımda saatlerce

Bedenime sıcaklığın girsin….

Artık kucakla beni güzel Anne…

Şaşırdın ……Suskunluğun lal oldu dilinde

Soğuktun…..Kolların dal oldu bedeninde

Üşüdüm……Yüzün donuk bir ay çizdi yüreğimde

Yoksa  ……. Beni tanımadın mı Anne?', 'Koynundan alıp uzak kentlere, Sürgün ettiler Anne.. Aldılar benden sıcaklığını, İçime bir buz kütlesi koydular anne… Çalıp şefkatini üzerimd...', ARRAY['Türk Edebiyatı','Şiir','Faik Danışman']::text[], 8.5, '{"poet":"Faik Danışman","poet_slug":"faik-danisman","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/beni-tanimadin-mi-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca hüzün...', 'yalnizca-huzun-mustafa-murat-aydogdu-vm4hp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Henüz doğrulmadan,yere düşerken

Hepiniz bir olun,halime gülün,

Alemin payına güller düşerken

Bana aşktan kalan; Yalnızca hüzün

Kıskanıyor sanıp,kızmayın bana

Aman! Aldırmayın,keyfini sürün

Razı olmalıdır herkes payına,

Bana aşktan kalan; Yalnızca hüzün

Yıllarca koştum aşkın peşinden,

Altında ezildim bu ağır yükün

Binlerce mutlu aşk dizesinden

Aklımda kalanlar; Yalnızca hüzün', 'Henüz doğrulmadan,yere düşerken Hepiniz bir olun,halime gülün, Alemin payına güller düşerken Bana aşktan kalan; Yalnızca hüzün Kıskanıyor sa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizca-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-ahmet-simsiki-ft8lt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susadım,

çocuksadım kendimi,

yasak derelere girdim,

ıslattım gömleğimi.

Acıktım,

ağzıma götürdüm kirli elimi,

evimiz taa bininci katta,

Annem komşuda,

bende elinden aldım,

Mustaa''nın ekmeğini.', 'Susadım, çocuksadım kendimi, yasak derelere girdim, ıslattım gömleğimi. Acıktım, ağzıma götürdüm kirli elimi, evimiz taa bininci katta, Anne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cocuk-145-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biteceksen bit!', 'biteceksen-bit-mustafa-murat-aydogdu-rgu4o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nedir? Bende seni ayakta tutan

Umudum kaldı mı? Kaldı mı ümit? 

Bu sevgide yalnız benim yıkılan

Sevda mısın nesin,biteceksen bit! 

Her gece hasretle ağlayan; Benim,

Geceyi sabaha bağlayan; Benim,

Artık bir meçhule daldı gözlerim

Sevda mısın nesin,biteceksen bit!', 'Nedir? Bende seni ayakta tutan Umudum kaldı mı? Kaldı mı ümit?  Bu sevgide yalnız benim yıkılan Sevda mısın nesin,biteceksen bit!  Her gece ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biteceksen-bit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Gibi Doğsan Bile Kar Etmez', 'gunes-gibi-dogsan-bile-kar-etmez-adem-torun-2n4br', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni özleyebilmek seni şimdi 

gecmişe dönüp seni sevmek tekrar...

cıldırasıya seni demek o özlemle

fırtınalı gecelerin götürdüğü

bilmiyesiye..

ve nisan yağmurunun karıştırdığı sele

sonunda gitmek seni özleyen o günlere

yine özlüyorum diyen o dillere

mevsim mevsim bekledim

kar yağarken gül topladım

öldüresiye arkadaş oldu sigaram

ne günler gecirdim seni beklerken

suskun bir hal aldım

içim seninle konuşur.

bir yürek ki, catalda olsa dayanmıyor

bir yürek ki bu hasrete daynamıyor

ve yine seni özleyebilmek seni

kaldıramadı artık bu acıları bu beden

cıkmadı hasretinle bucan bu tenden

canıma can katıp gelsen bile kar etmez

bir cana kaldım birde hasretine

bahceler hasret kalşdı acacak beyaz güle

cicekler boynunu büktü doğmayan güneşe

güllerde kırgın artık dalına konmayan bülbüle

ciceklere güneş gibi doğsanda farketmez', 'seni özleyebilmek seni şimdi  gecmişe dönüp seni sevmek tekrar... cıldırasıya seni demek o özlemle fırtınalı gecelerin götürdüğü bilmiyesiye...', ARRAY['Türk Edebiyatı','Şiir','Adem Torun']::text[], 8.5, '{"poet":"Adem Torun","poet_slug":"adem-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gunes-gibi-dogsan-bile-kar-etmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hanımeli''ne', 'hanimeli-ne-ahmet-simsiki-p6nvk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben hanımeline aşığım,

akşam serinliğide vurgun,

hanımelinin sarısına.

ben hanımelini kokladımda,

dün akşam üzeri,

akşam serinliğiyle aramıza,

bir soğukluk girdi.

ben hanımeline aşığım.', 'ben hanımeline aşığım, akşam serinliğide vurgun, hanımelinin sarısına. ben hanımelini kokladımda, dün akşam üzeri, akşam serinliğiyle aramız...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hanimeli-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuturum seni', 'unuturum-seni-mustafa-murat-aydogdu-ktqnr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızlar bir gün aya küserde,

Karanlık aleme dönmezse geri

Ve bulutlar eşlik etmezse güneşe

Ben o gün unuturum seni

Aşkınla akmazsa yaşlar gözümden

Gönlüm sevginden kestiyse ümidi,

Yani ben bu dünyadan göçersem

İşte o an unuturum seni

Umutlar tükenir,hasret dinerse

Gidenler bir daha dönmezse geri

Ve bir gün dokunursak güneşe,

Ben,o gün unutacağım seni.', 'Yıldızlar bir gün aya küserde, Karanlık aleme dönmezse geri Ve bulutlar eşlik etmezse güneşe Ben o gün unuturum seni Aşkınla akmazsa yaşlar ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unuturum-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Kadar Sevgilimsin', 'sonsuza-kadar-sevgilimsin-durdane-demirkoparan-cv8tu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gelmiş geçmiş,

Ve gelecek

Bu hayatta

Varmı senin bir eşin daha

Nasıl bir varlıksın

Nasıl bir varlıksın ki

Yıllardır 

Ellerimi bırakmadın

Har düştüğümde

Her ağladığımda

Nefes alamadığımda

Bıktığım anda yaşamaktan

Yanımdaydın

Yaşama sebebim 

Ağlayacak tek omuz

Gülecek tek sebebimdin

İyi davrandım iyiydin

Kötü davrandım iyiydin

Anlayamadım önceleri 

Belki bilemedim kıymetini

Affet…

Ama şimdi

Anladım ki

Tek sevgilim

Hayatımın tek anlamı

Dayanağı

Gözlerimin ışığı

Geleceğim

Yarına umutlarım

Ve beni bırakmayacak

Sonsuza kadar bırakmayacak

Sevgilim 

Sensin annem

Hakkını ödeyemem

Seni sevmekten

Çok sevmekten 

Başka bir şey yapamam

Sonsuza kadar sevgilimsin

Seni çok seviyorum

     “ Annem ”', 'Gelmiş geçmiş, Ve gelecek Bu hayatta Varmı senin bir eşin daha Nasıl bir varlıksın Nasıl bir varlıksın ki Yıllardır  Ellerimi bırakmadın Har...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sonsuza-kadar-sevgilimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-mustafa-murat-aydogdu-gxbwt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün ağlıyorum,yarınım meçhul

Gözümde hep böyle yaş mı olacak? 

Yaralı gönlümde kalmadı huzur

Bu sevda benim sonum olacak

Aldığım nefesin sayısı belli

Bu hayat elbet bir son bulacak

Her sevginin varsa eğer bedeli,

Bu aşkın bedeli,ölüm olacak!', 'Bugün ağlıyorum,yarınım meçhul Gözümde hep böyle yaş mı olacak?  Yaralı gönlümde kalmadı huzur Bu sevda benim sonum olacak Aldığım nefesin s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bedel-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya', 'papatya-metin-soydeveli-dsoen', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç şikayetimiz yoktu

Saplarımızı koparırken dipten

Çok da kıymet ifade etmiyordu

İçimizden en güzellerini seçmen

Bir başa taç örüleceğimizi bildiğimizden

Hiçte umduğumuz gibi çıkmadı

Gönüllere, başlara taç olmayı beklerken; 

Yerlere atılıp çiğnendik, hiç yoktan

Umutla sevgi falı bakıyordun belki sen

Ama teker teker koparıyordun bedenimden', 'Hiç şikayetimiz yoktu Saplarımızı koparırken dipten Çok da kıymet ifade etmiyordu İçimizden en güzellerini seçmen Bir başa taç örüleceğimizi...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/papatya-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra Sen Kalır', 'senden-sonra-sen-kalir-ahmet-simsiki-ma9re', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bende,senden sonrası kalır ancak,

ben önceden,

seni olmayanmışım sadece.

bende silinir,senden gayrı

ne varsa

ne yoksa.

sen gittin gideli,

sadece sen varsın.

ben önceden,

seni benden gitmeyenmişim sadece.

bende yazılır,senden gayrı

ne varsa

ne yoksa.', 'bende,senden sonrası kalır ancak, ben önceden, seni olmayanmışım sadece. bende silinir,senden gayrı ne varsa ne yoksa. sen gittin gideli, sa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senden-sonra-sen-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Bir Coğrafyayım Şimdi', 'kayip-bir-cografyayim-simdi-faik-danisman-pzht3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kayıp bir coğrafyaya uyarladım kendimi, 

Güneşsiz,çiçeksiz,ormansız,

Çırılçıplak bir ülkeyim şimdi… 

Bir uçurtmanın kuyruğuna asıp özgürlüğümü, 

Kestiler ipimi zamansız.. ….. 

Durmadan dönüyorum etrafımda, 

Çıkışsız bir labirentte gençliğim.. 

Çalıntı bir ninniydi sanki, 

Yakamoz kokan bir gecede silah sesleri, 

Yaşamdan bir kesit,bir orman müziği melodisi belki de… 

Barut kokusu karbondioksit..! 

Çatlaklarım vardı yer yer tenimde, 

Kırılganlığım yansıyordu yüzüme. 

Ve vurdum duymazlığınız üzerimde, 

Nasıl da kıydınız düşlerime… 

Yitik sevda,çorak toprak koydunuz adımı. 

Bir gonca güldüm dalımda dikenlerle serpiştirdiniz dallarımı.. 

Nerede mor dağlarım,yeşil çimenlerim, 

Ak renklerim, al renklere büründü sayenizde.. 

Şimdi kuş seslerine hasret dallarım. 

Deli dolu bir yağmuru esirgediniz benden. 

Gözlerime ödettiniz bedelini. 

Yalancı maviliğine aldandım gökyüzü. 

Oysa hep karanlıkta bıraktın bir yanımı…. 

Artık inanmıyorum size..! 

Karanlık dehlizlerin ürkek bakışlarında gizli sevmeleriniz. 

Bir ütopyanın en yüksek sehpasında, 

Mühürlenmiş parmak izlerim. 

Mahkum ettiniz beni.ipsiz,dipsiz bir kuyuya… 

Duymadınız yakarışlarımı,duymak istemediniz belki de. 

Dokunamadınız göz yaşlarıma. 

Zincirlenmiştim oysa ellerimden, 

Prangalı ayaklarımla.çarmıha gerdiniz diri diri.. 

Beni hiç görmediniz mi? 

Rastlamadınız mı yasak kokan bir gecede.? 

Yani beni öldürüp üzerimi bile örtmediniz mi? 

Bir çığlıktım oysa, 

Boğazına kelimeler düğümlenmiş sessiz bir çığlık… 

Bir melodi belki, de yürüyüş marşına benzeyen, 

Ve ayak seslerinden özgürlük tutkusu fışkıran 

Bir çocuktum belki güneş gibi gözlerim. 

Donuk yüzüm,yanaklarıma süzülen yaşlar benim. 

Sevgisiz büyümüşlüğüm,öksüzlüğüm başkaydı. 

Başımın üstünde bir el gezinmedi, 

Merhamet niyetine olmasa da.,. 

Sevgi hatırına bir küçük tebessüm istedim … 

Bir zılgıttım öfke dolu,isyan dolu,ama coşkulu. 

Renk cümbüşüme ayak uyduramadınız. 

Beni hep sorguladınız. 

Oysa sizden öncekiler beni defalarca sorguladıkları için, 

Ben hep böyle çıplaktım.. 

Zamana sığmadı sevdam, 

Diyetler yarım kaldı bedenimde 

Verilmesi gereken son bedelse yüreğim, 

O çoktan rehin,gelip almanızı bekliyor.', 'Kayıp bir coğrafyaya uyarladım kendimi,  Güneşsiz,çiçeksiz,ormansız, Çırılçıplak bir ülkeyim şimdi…  Bir uçurtmanın kuyruğuna asıp özgürlüğü...', ARRAY['Türk Edebiyatı','Şiir','Faik Danışman']::text[], 8.5, '{"poet":"Faik Danışman","poet_slug":"faik-danisman","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/kayip-bir-cografyayim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksulluk işte', 'yoksulluk-iste-i-lker-kesemen-vkx3t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine sen geldin aklıma 

Sevda kuşu kondu tahtıma 

Bakışların la varya 

Ben birden aşık oldum sana 

Çokta insan tanıdım 

Bazılarıyla hatta oturup ağladım 

Kimisine kanayan yaramı anlattım 

Ve ben sonun da seninlede ağladım 

Yaylala rı bilirmisin 

Yeşilliği severmisin 

Çobanlık edermisin 

Peki bir dilim ekmek ve su istermisin 

Sabah olur bazen 

Ben senleyim halen 

Güneş doğar gün başlar 

Ben senle yaşlanır ağlarım halen 

Ben türküler le büyürken 

Sen yine üstüme gülerken 

Ben hasretin ile yanarken 

Sen yine gülüp geçerken 

Ağlamakta deyil sana 

Gülmek yakışır ömrünçe yarim 

Saygılarımla', 'Yine sen geldin aklıma  Sevda kuşu kondu tahtıma  Bakışların la varya  Ben birden aşık oldum sana  Çokta insan tanıdım  Bazılarıyla hatta ot...', ARRAY['Türk Edebiyatı','Şiir','İlker Kesemen']::text[], 8.5, '{"poet":"İlker Kesemen","poet_slug":"i-lker-kesemen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yoksulluk-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler Sana Emanet', 'siirler-sana-emanet-ahmet-simsiki-0imhk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiirler sana emanet,

Amman! gözün gibi bak.

ben gidince artık,

birkaçını sat.

aman,ilk yazdıklarımdan olsun,

onunla bakkalı öde.

çok iyileri dursun,

onlarla da beni özle.

Şiirler sana emanet,

kitabı kapalı tut,

uslu durmayan olursa

bana şikayet et.', 'Şiirler sana emanet, Amman! gözün gibi bak. ben gidince artık, birkaçını sat. aman,ilk yazdıklarımdan olsun, onunla bakkalı öde. çok iyileri...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siirler-sana-emanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...', 'sen-mustafa-murat-aydogdu-7db60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen,benim baharım

Sen,benim yarım,

Ve ben baharları hep yarım yaşadım.

Bir yanım çiçek açarken,

Karla kaplıydı bir yanım

Sen,benim canım

Bilmiyorum,sensiz nasıl yaşarım.

Sen,benim yalnızlığım

Sen dünyayı seçerken,ben dünyadan vazgeçip

Bir sana bağlanmışım.

Sen,benim hayallerim

Çünkü seni artık,

Yalnızca hayallerde görebilirim

Çok yazık!', 'Sen,benim baharım Sen,benim yarım, Ve ben baharları hep yarım yaşadım. Bir yanım çiçek açarken, Karla kaplıydı bir yanım Sen,benim canım Bil...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-770-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rıza Şen diye biri', 'riza-sen-diye-biri-ahmet-simsiki-26z8o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rıza Şen,

hiç tanımam kendisini,

yüzünüde görmedim

adınıda duymadım! 

adını söyleyen de olmadı

işte öyle uydurdum.

Allah bilir ya,kimdir? 

derdi nedir? 

kaç çocuk babası bakalım,

ya da kimin oğlu? 

akıllı mı,delimidir? 

ne iş yapar,yapamaz yahut,

kimin sevdiği? 

kimi sevdiği,

Rıza Şen,

hiç tanımam kendisini.', 'Rıza Şen, hiç tanımam kendisini, yüzünüde görmedim adınıda duymadım!  adını söyleyen de olmadı işte öyle uydurdum. Allah bilir ya,kimdir?  d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/riza-sen-diye-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daraba', 'daraba-sair-met-wk0ab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'unuttuğum kadınların kıskacında

                                                dar

                                      ağacında

pençelediğim yakası avucumda

gözyaşları terimle karışıyor

                                             haşır

                                             neşir

                                           oluyor

sensiz bensiz

sessiz soluksuz

betsiz benizsiz

uykumdan uyandırıyor daraba

                             ve bir araba

                        kalkıyor seraba

                                           Dur! 

                           beni de götür.

19.09.2005

Erzin-dan', 'unuttuğum kadınların kıskacında                                                 dar                                       ağacında pençeledi...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/daraba-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rakı ve Balık', 'raki-ve-balik-metin-soydeveli-g3g3w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu akşam sofrada

Balık ve rakı vardı.

Sevinçli ve mutluydum

Sana kavuşmuş kadar.

Balık ve rakı

Ancak tamamlardı

Birbirini

Seninle ben kadar.', 'Bu akşam sofrada Balık ve rakı vardı. Sevinçli ve mutluydum Sana kavuşmuş kadar. Balık ve rakı Ancak tamamlardı Birbirini Seninle ben kadar....', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/raki-ve-balik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen Eğer', 'gidersen-eger-hulya-ekmekci-ferib', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanadım kırılır uçamam sensiz

Bir garip olurum gidersen eğer

Tomur olsam dalda açamam sensiz

Derde yar olurum gidersen eğer

Ummanda küreksiz bir sal olurum

Şu kurak çöllerde bil kavrulurum

Kum tanesi olup hep savrulurum

Seraba dönerim gidersen eğer

Göğü süsler kuşlar yeri karınca

Gözü yaşlı gece güne varınca

Güneş ovaları kol kol sarınca

Dağda kar olurum gidersen eğer

Dolaşsam gün boyu tepe ve bayır

Ağlar kavak çınar küser bak çayır

Böyle giderse bil yok benden hayır

Dallarım kırılır gidersen eğer

Aynada görürüm gülmez bir yüz

Durgun bakar bir çift şavkı sönmüş göz

Baharlar dururken neden olsun güz

Açmadan solarım gidersen eğer', 'Kanadım kırılır uçamam sensiz Bir garip olurum gidersen eğer Tomur olsam dalda açamam sensiz Derde yar olurum gidersen eğer Ummanda küreksiz...', ARRAY['Türk Edebiyatı','Şiir','Hülya Ekmekçi']::text[], 8.5, '{"poet":"Hülya Ekmekçi","poet_slug":"hulya-ekmekci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidersen-eger-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette Gece', 'gurbette-gece-bilal-toy-tluvj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Devrilir aydinligin uzerine koca katran kazani

Silinir yeryuzunden birer birer daglar

Gunes caresiz izler bu talani

Gurbette aksam boyle baslar

Ozlem bu vakitlerde coker adamin ustune 

Sessizlige bogulur her yan

Yalnizlik yankilanir sadece

Gurbette, sirtini dayadigin duvardan', 'Devrilir aydinligin uzerine koca katran kazani Silinir yeryuzunden birer birer daglar Gunes caresiz izler bu talani Gurbette aksam boyle bas...', ARRAY['Türk Edebiyatı','Şiir','Bilal Toy']::text[], 8.5, '{"poet":"Bilal Toy","poet_slug":"bilal-toy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gurbette-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nikah Şekeri', 'nikah-sekeri-sair-met-3zfk6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırık kalpler kulübü

                      ölümü

                       ölünü

                           ölü

Dudağında pöpü

Boşver düğünü derneği

Demoklesin değneği

Nikah şekeri

Yala yala bitmez

Balla pekmez', 'Kırık kalpler kulübü                       ölümü                        ölünü                            ölü Dudağında pöpü Boşver düğünü de...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nikah-sekeri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Çagdan Yunus Emre´ye Mektup', 'bu-cagdan-yunus-emre-ye-mektup-gultekin-toga-k3o2g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya barut kokar,bulut kan döker,

Merhamet fakiri gözler kin bakar,

Selamın altından menfaat çıkar,

Sicak sevgi nerde....buz gibiyiz buz,

Yunus,ayağının tozu degiliz..

Nefis hükümdardır çogu bedende,

Kimde para çoksa o gider önde,

Dünya bir sevdadır kulun kalbinde,

Bu yüzden nefretiz,bu yüzden kiniz,

Yunus,ayağının tozu değiliz...

Sende sevgi dorukları döverdi,

Yaratılmış her nesneyi severdi,

Bizde nefis kolu şeytana verdi,

Günahlarımızı yuyamaz deniz,

Yunus ayağının tozu değiliz..

Ehli küfrü zaten anlatmak boştur,

İman diyarInda hangi şey hoştur,? 

Şerhaneler dolu,mabetler boştur,

Asırlar var ağlanacak haldeyiz,

Yunus ayağının tozu değiliz..

Sadakat duygusu yaralı bugün,

Bilmeyiz tevekkül nereli bugün

Sevgi de saygı da paralı bugün,

Maddenin peşinde çagıl çagılız,

Yunus ayağının tozu değiliz..

Parça parça Muhammed´´in(Sav)    Ümmeti,

Zaptırakta erenlerin himmeti,

Ayakta kalmamız Hakk´ın zimmeti,

Dört bir yanda gizli müstemlekeyiz,

Yunus,ayağının tozu değiliz,

Gönül kırmak marifeti kibirin,

Adalet elinde zorba,cebirin,

Hasedin,fitnenin,kin,garez.kirin,

Küme küme toplandığı ağılız,

Yunus Ayağının tozu değiliz..

Kurtar Yücce Allah kurtar bizleri,

Kafirler kantarda tartar bizleri,

Bu dehşet yürekten yırtar bizleri,

Gaflet tepemizde kesildi balyoz,

Yunus,ayağının tozu değiliz..

Hakk´in badesini içen Yunus´um,

Allah´´in aşkıyla uçan Yunus´um,

Odunun düzünü seçen Yunus´um,

Bugün dürüstlerin adları keriz(? !) 

Yunus,ayağının tozu değiliz...

Daraldıkca sığınırız tarihe,

Kanun destek olur soysuz güruha,

Sentez der:milletce sendeki  ruha,

Susuz kalmış çiçek gibi hasretiz,

Yunus ayağının tozu değiliz..', 'Dünya barut kokar,bulut kan döker, Merhamet fakiri gözler kin bakar, Selamın altından menfaat çıkar, Sicak sevgi nerde....buz gibiyiz buz, Y...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/bu-cagdan-yunus-emre-ye-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helvadan Putlar', 'helvadan-putlar-nermin-altindag-ogdci', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırık zincirlerle döşeli yollarda

Ayaklarım birbirine dolandı

Helvadan putlar yaptım

Kâbenin sahibi vardı

Tek derdim develerim olmalıydı

Ben koyun oldum

Onlar sahipsiz kaldı

Yaptığım putlara taptım

Yüzüm yağmura dönük

Yürümeyi unuttuğum yollarda

Bir ileri, bir geri

Her düşüşte yeniden kalkmak için

Yedim helvadan putlarımı

Affediniz

Açtım...', 'Kırık zincirlerle döşeli yollarda Ayaklarım birbirine dolandı Helvadan putlar yaptım Kâbenin sahibi vardı Tek derdim develerim olmalıydı Ben...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/helvadan-putlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dış Politika', 'dis-politika-sair-met-jzbh6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kazıklı humma

                veba

Kuşku palazı

Kulak ayazı

Kara merhem

İnce elem

Kedi gribi

Ense semirmesi

merhumlar makberde

                            vakıa

                   dış politika

(Erzin-dan)', 'Kazıklı humma                 veba Kuşku palazı Kulak ayazı Kara merhem İnce elem Kedi gribi Ense semirmesi merhumlar makberde              ...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dis-politika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Nasıl Dünya Dostlar', 'bu-nasil-dunya-dostlar-seyfet-bozcali-r6e8q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu nasıl Dünya dostlar? Hep zülüm hep işkence,

Tabiatın bağrında,kıyılır bunca gence,

Kabarır ıştahı kurdun,kokusunu alınca,

Bir ayağı afganistanda,ötekisi Irak''ta.

Ananın gözü yaşlı,emzirir geleceği,

işgalci ruhlar saldırıp,yıkar bunca ocağı,

Genç kızlar ağıt örer,cehizine,sandığa,

Bonba sesleri yıkar hayelleri Irak''ta.

Adamın emeği toz,Divanedir çöllerde,

Yamyamlar yerli gibi,onlar yaban ellerde,

Yanağında bot izi,nice işkencelerde,

Çocuk babayı arar,Babaysa çok uzakta.

Akbabalar uçuşur,cellatlarsa her yerde,

İşkenceler diz boyu,sürüp gider ekranda,

Açlık yoksulluk sarmış Ektopya,Somalide,

Bilemişler dişleri,insanlar hep tuzakta.

Özgürlük göremeyiz,komşularda hep öğle,

Dünya zalimlerinmi,Zalimlikmidir Dünya.

Bombalarla büyüyen çocuk görürmü rüya,

Güçlüler güçlendikçe,mazlumlar hep tuzakta.

             21.02.2006', 'Bu nasıl Dünya dostlar? Hep zülüm hep işkence, Tabiatın bağrında,kıyılır bunca gence, Kabarır ıştahı kurdun,kokusunu alınca, Bir ayağı afgan...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-nasil-dunya-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karakızım', 'karakizim-sair-met-hdp7u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara kızım...

Bahsızım! 

Yazısızım! 

Eteklerimde ziller

      arabada piller

    bahçede güller

             renk renk

Aldatmak gerek

Kara kızım

Hem bahtsız,

Hem yazısızım! 

01-02 Ekim 2005

Erzin-dan', 'Kara kızım... Bahsızım!  Yazısızım!  Eteklerimde ziller       arabada piller     bahçede güller              renk renk Aldatmak gerek Kara k...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karakizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğin varsa', 'gelecegin-varsa-abdusselam-bugur-sw1vd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geleceğin varsa

Durma! 

Hemen gel sevgili

Kalbimde yap şaheserini! 

Ne diliyorsa

Gönlüm! 

Yerine getir şimdi

Gönlümün sültanı! ...', 'Geleceğin varsa Durma!  Hemen gel sevgili Kalbimde yap şaheserini!  Ne diliyorsa Gönlüm!  Yerine getir şimdi Gönlümün sültanı! ......', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gelecegin-varsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Dört Mevsimi Var', 'askin-dort-mevsimi-var-metin-soydeveli-7r6p7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkın dört mevsimi var

Sanma ki hepsi bahar

Birinde yaz

Birinde kış

Diğeri sonbahar

Önce gözler konuşur

Tatlı bir gülüş boşaltır gönül yayını

Sonra eller birleşir

Başlar sönmez bir gönül yangını

Koro halinde açar

Gök kuşağı renginde

Bütün çiçekler

Erdim dersin; işte BAHAR

Ok bakışlar deler sineleri

Kor dudaklar yakar tenleri

Geçti modası pembelerin

Şimdi bütün renkler yeşil, sarı

İşte... Bütün kavuruculuğuyla, YAZ.

Sıkı sıkı sarılmak ister bedenler

Sanki düşercesine gazel olmuş yapraklar

Gönülde esmeye başlayınca fırtınalar

İşte kızıl, bakır tüm renkler

Geldi hüzünlere gebe SONBAHAR

Korkma aşktan, hazanın sonu KIŞ olsa da

Her mevsimde aşkı gönlünce, doya doya yaşa

Aşk, sevmek, her mevsimde güzel, bunu bil

Korkma, sevmek sınırlı hürriyet değil.', 'Aşkın dört mevsimi var Sanma ki hepsi bahar Birinde yaz Birinde kış Diğeri sonbahar Önce gözler konuşur Tatlı bir gülüş boşaltır gönül yayın...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/askin-dort-mevsimi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektup', 'sevgiliye-mektup-ahmet-zekai-yildiz-8zow3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne bahar eski bahar bundan sonra,

Ne de senin gibi kokar çiçekler.

Gittiğin günden beri kalp/sızım 

Nefes alıyorum hepsi o kadar.

1950 model cinemeccanicadan

Sararmış yırtık perdelere yansıtılan

Titrek, siyah-beyaz film kareleri gibi

Bulanık, uzak anılarımız geçiyor gözlerimden.

Gözlerimi seni ilk gördüğümde kaybetmiştim zaten.

Sesine hasret kulaklarım sağır tüm seslere.

Biliyorum.

Hiç bir şey eskisi gibi olmayacak.

Çırpınışlarım boşuna.

Ah o sağanak kaprislerin,

Örneğin gelmeyişin

Ve ya yalandan da olsa 

Bir merhaba demeyişin, terörüm oldu.

Beni katlettin.

Ölüm, 

İntihar ağacı gibi hep başımın üstünde.

Sinirlerim başkaldırmış başıma.

Tansiyon hiper.

Yaşama sevimcime pusular kuruyor bedenim,

Habire habire..

Gündüzler yetmedi bu gerilime.

Geceler seri katilim.

Şimdilerde ölüp ölüp diriliyorum.

Ne yapabilirim, elimde değil.

Mutsuzum anlayacağın.

Sen mutlu kal sevgilim.', 'Ne bahar eski bahar bundan sonra, Ne de senin gibi kokar çiçekler. Gittiğin günden beri kalp/sızım  Nefes alıyorum hepsi o kadar. 1950 model...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevgiliye-mektup-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlarım(çapkın)', 'kadinlarim-capkin-denizhan-arici-cnhe2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne kadınlar geçti

sarışını kumralı esmeri

ne kadınlar sevdim

kiminde aşk kimine şevkat verdim 

bir kaç kadın vardı

bazısı oynak bazısını soymak gerekirdi

ben çok kadın gördüm

azı gülüm oldu

çoğu zulüm

ama herbirinin içinde bir kördüğüm vardı

çözmek ölüm gibi gelirdi

bir o kadarda meşekatliydi

her kadından birşeyler öğrendim

hepsini ayrı sevdim

aslında hepsi için birdi sevgim

ancak her biri farklı yanımı severdi

yani özeldi sevgim

kadınlarım önemlidir benim için

bazısı ağlatırdı için için

kimini ise  kadehlere koyup

şarap tadında için

ben ne kadınlar sevdim

hiç birinde kendimi göremedim

birkaç hayat çıkarmışım yaşamalarından 

farkında değildim

zaman olur hayat seçerdim

bugün aysel yarın leman olurdu

iki gün sonraki 

buyrun gelsin sıradaki', 'ne kadınlar geçti sarışını kumralı esmeri ne kadınlar sevdim kiminde aşk kimine şevkat verdim  bir kaç kadın vardı bazısı oynak bazısını soy...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Arıcı']::text[], 8.5, '{"poet":"Denizhan Arıcı","poet_slug":"denizhan-arici","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kadinlarim-capkin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanser ve Balkondaki Kahkahalar', 'kanser-ve-balkondaki-kahkahalar-ramazan-topoglu-p913q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirler ve hayat bazen; 

Hiç el ele tutuşmamış

Hiç sevmemiş

Hiç öpüşmemiş

Bekar iki cimri 

Yaşlı kardeşin

Babadan kalma evlerindeki

Eski koltukları 

Ve solmuş perdeleri kadar

Can sıkıcı

Şimdiki zaman gibi

Şiirler ve hayat bazen; 

Sevgiye doymuş

İkisi kız, üçü oğlan

Beş kardeşli ailenin

Eşleri ve çocuklarıyla

Bayramlarda baba ocağında

Yemek sonrası

Babaya ayıp olmasın diye

Balkonda  toplanıp

Şen şakrak

Kaçak sigara içişleri gibi

Keyifli

Geçmiş zamanlardaki gibi', 'Şiirler ve hayat bazen;  Hiç el ele tutuşmamış Hiç sevmemiş Hiç öpüşmemiş Bekar iki cimri  Yaşlı kardeşin Babadan kalma evlerindeki Eski kol...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Topoğlu']::text[], 8.5, '{"poet":"Ramazan Topoğlu","poet_slug":"ramazan-topoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kanser-ve-balkondaki-kahkahalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar', 'bulutlar-ahmet-uslu-astla-kd791', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine yağmur havası var bugün,

Ve yine yağmur yüklü bembeyaz bulutlar...

Yavaş yavaş kapanıyor hava,

Ve yavaş yavaş siyaha çalıyor bulutlar.

Yine yağmur havası var bugün,

Her yağmur yağdığında olduğu gibi:

Yine hüzün çöküverdi yüreğime,

Yine sensizlik çöktü üzerime! 

Yine yağmur havası var...

Belkide kendime benzetiyorum yağmuru,

Belki de ben oluveriyorum:

Bembeyazken kararan bulutlar.

Kapanıyor yine hava,

Sanırım yine yağmur yağacak.

Kararırken bulutlar:

Sen hatrıma geliyorsun,

Seni hatırladıkça bende kararıyor,

Ben de sessizleşiyorum.

Usul usul yağmur yağmaya başladı.

Seni hatırladım yine ve:

Gözyaşlarımda yağmaya başladı.

Belki de bu yüzdendir:

Yağmuru sevmeyişim,

Belki de sensindir:

Bulutları bana sevdirmeyen.', 'Yine yağmur havası var bugün, Ve yine yağmur yüklü bembeyaz bulutlar... Yavaş yavaş kapanıyor hava, Ve yavaş yavaş siyaha çalıyor bulutlar. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uslu Astla']::text[], 8.5, '{"poet":"Ahmet Uslu Astla","poet_slug":"ahmet-uslu-astla","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bulutlar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müslümanın Birliği Ancak Kendi Birliği (2)', 'muslumanin-birligi-ancak-kendi-birligi-2-umut-gungor-b83n6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Taş atan çocuklara tanklarla yürüdüler,

Kadın bebek demeden yerlerde sürüdüler,

Filistini Irakı zulüme bürüdüler,

Rasulüme sövenin birliğini istemem.

Ne Bosnayı gördüler nede Çeçenistanı,

Ruslara bıraktılar komşu Afganistanı,

Kurcalayıp duruyorlar şimdi Pakistanı,

Rasulüme sövenin birliğini istemem.

Talabani barzani Kerkükü bölüşüyor,

Papanın simsarları geriden gülüşüyor,

Bunlar her zaman bize zulümü görüşüyor,

Rasulüme sövenin birliğini istemem.

Eşkiyaya bir türlü çıkarmıyor sesini,

Irakla doldurmaya çalışıyor nefisini,

Cümle alem biliyor eskisi yenisini,

Rasulüme sövenin birliğini istemem.

Kıbrısa aşikar ezelden iştahları,

Akdenizde yalanır canavar timsahları,

Müslümana kokuyor kepaze kursakları,

Rasulüme sövenin birliğini istemem.', 'Taş atan çocuklara tanklarla yürüdüler, Kadın bebek demeden yerlerde sürüdüler, Filistini Irakı zulüme bürüdüler, Rasulüme sövenin birliğini...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/muslumanin-birligi-ancak-kendi-birligi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuzluk', 'susuzluk-ahmet-uslu-astla-4znfs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç susuz kaldın mı sen? 

Hiç kurudumu dudakların,

Çatladı mı susuzluktan? 

Su diye haykırdın mı hiç,

Senin kısıldı mı bu yüzden? 

Anlaman için beni,

Anlayabilmen için bu şiiri:

Susuz kalman,susuzluk çekmen gerekiyor.

''Sen beni suyun insanı sevdiği kadar sevdin,

Bense seni insanın suyu sevdiği kadar...''

Yani anlayacağın:

Suyun insana ihtiyacı yoktu ama:

İnsan susuz imkansızdı.', 'Hiç susuz kaldın mı sen?  Hiç kurudumu dudakların, Çatladı mı susuzluktan?  Su diye haykırdın mı hiç, Senin kısıldı mı bu yüzden?  Anlaman i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uslu Astla']::text[], 8.5, '{"poet":"Ahmet Uslu Astla","poet_slug":"ahmet-uslu-astla","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/susuzluk-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ağacın Dibinde Ellerim Kaldı', 'bir-agacin-dibinde-ellerim-kaldi-sultan-i-nan-1t5fp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayat hep hüzünlü çığlıktı 

dokundum tellerine icimden akan ezginin 

gözü kaçmış beş numara şişteydi aşk 

geldi ve çekti biri ipini 

dayansam 

kapın akşam 

dokunsam 

ellerinde kelepçeli şehir 

hangi dağına kaldırsam seni bu eşkıya ruhun 

hangi mağaranın kuytuluğunda sarsam 

hudut mu olsam yasaklı ülkene 

böyle upuzun yatan ceset olmuşken 

aksam mı gözlerine nehir nehir 

hadi söyle 

hangi günün ikindisinde gömülmeliyim seninle 

biz hamam böcekleriyle çekildik bu şehrin nemli ıssızlıklarına 

şimdi en mahrem yerlerin upucun kılları arasında dolaşan günahız 

şehvet suları değil sensizliğimize bakıp organlarımızdan akan 

coplanmış düş... üflesen yıkılacak enkaz 

ve ben bir milim ötende duran yelkenli şaşkın ve soluksuz 

vurgun yemiş denizine saldığım her gemi 

oysa yaşamak vardı 

ekmek arasında alıp istavriti 

senide katıp önüne bu iskeletin 

altını üstüne getirip 

eminönünden unkapanına dişleye dişleye 

yeniden yazmak bu serüveni 

istermisin parklarda hortlasın yeniden aşk 

yeniden yıldızlarla donansın gökyüzü 

güneş başka doğsun 

sen güneş olup başka vurmuş ol leylaklarıma 

ve hergün aynı karmaşalıkla beynin en ufak kıvrımlarında dahi 

yitirmeden sevincini 

durmadan birbirine sarılan iki sarmaşık olalım 

sen daha başka ol bana 

ben daha başka olayım 

uzansın kıyılarımıza lodos 

ve biz hep boğulalım 

mora dönüyor tüm renklerim 

sıçrıyor kan morda beynime 

ağlıyorum işte bak 

hadi durdur icimdeki sağnakları 

hadi kalk...

öte dünyalarımın adamı 

benbahar1111', 'hayat hep hüzünlü çığlıktı  dokundum tellerine icimden akan ezginin  gözü kaçmış beş numara şişteydi aşk  geldi ve çekti biri ipini  dayansa...', ARRAY['Türk Edebiyatı','Şiir','Sultan İnan']::text[], 8.5, '{"poet":"Sultan İnan","poet_slug":"sultan-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-agacin-dibinde-ellerim-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefes', 'nefes-asude-gediz-6m0lp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-I-

gözü kara 

deli aşık

acıya tutkun

inlemeyi inletmeyi seven

duygularının esiri 

kıskançlık sarmış bedenini

bir okadar bağlı ve yabani

hovarda yürekli 

romantik 

kalbim olduğunu  hissettiren 

kapkara gözlerle sözlerini  mühürleyen

hassas

izi var  her yerde

kendi gelmeden nefesini bırakıp

atmosferi titreten

bir nazar fırlatıp  inleten

nasılda hissederdi yolun değiştiğni

işte  karşımda 

elinde bir gül  titreyen

istersen gülme 

selamsız bir sabah olsun iste

bir bakış ki üryan eden

delip geçen 

-II-

Bir şarap ki

eskidikçe kıymetlenen

o sokak nerden çıktı birden 

yıllar sonra gözlerinde nem

yine o bakış kurşun 

yüreğimden 

hoş mudur ızdırap vermek 

bilmem

madem bensizliği seçtin

vazgeçtim senden

istesemde diyemem

-III-

Gam yüklenmiş  martılara 

yazgı kara mı kara

iki hasta yaşlı  ana

''bekleyelim biraz aşkım'' 

bir sandık birde kefenmiş beklediğin

yakışmadın', '-I- gözü kara  deli aşık acıya tutkun inlemeyi inletmeyi seven duygularının esiri  kıskançlık sarmış bedenini bir okadar bağlı ve yabani hov...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/nefes-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizden Evrene', 'sizden-evrene-altay-taskin-vcq2v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'elinizde çiçekler

el ele göz göze

neşe saçarsınız evrene

demet demet

sepet sepet

çiçeklerde böcek

kanat açar

uçarsınız uzaklara

seven kalpler

mutlu yüzler

sizden evrene

denizleri aşar

dağları deler

tutuşursunuz el ele

kucak dolusu

binbir selam

sizden evrene', 'elinizde çiçekler el ele göz göze neşe saçarsınız evrene demet demet sepet sepet çiçeklerde böcek kanat açar uçarsınız uzaklara seven kalple...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sizden-evrene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksulluk Ana ve Çocukları', 'yoksulluk-ana-ve-cocuklari-seyfet-bozcali-fk8d1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ana iki çocuk,

dolaşıyor köşe bucak

çalı,çırpı topluyor küçücük eller,

morarmış surat,çatlamış dudak,

Ana burnundan soluyor

zor tutuyordu kendini,

onun için ölümdü ağlamamak...

Kıraç merada

koyun nasıl yavrusunu koruyorsa

anada öyle koruyordu yavrularını.

Bakınıp duruyordu onlara,

gergin bedeni dikleşirdi bazen

evlatlarımı çakallara kaptırmam

sokaklara salmam derdi

salanlarada kızardı.

Yuvasını kuran serçe kuşu gibi

hep çalı çırpı toplardı.

Dilenmezdi

dilenenleride sevmezdi,

Çok hastaydı

hastalığını belli etmezdi

Kimseye muhtaç olmadan

ölmek isterdi.

Mahalleli bakardı ara sıra,

sonunda kapıcı oldu

küçük bir villaya

az ücretle

çok işler yapardı

hiç doktor görmedi

sonunda 

hastalığa yenik düştü

Anneler gününde

öldü.

Belediye tarafından

sahipsizler 

mezarlığına 

gömüldü.', 'Bir ana iki çocuk, dolaşıyor köşe bucak çalı,çırpı topluyor küçücük eller, morarmış surat,çatlamış dudak, Ana burnundan soluyor zor tutuyord...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yoksulluk-ana-ve-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz''ime', 'aziz-ime-emrah-karakoc-tjj3g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Kardeşimin ruhuna ithaf olunur) 

Veda ettin yaşamaya

Mekan kurdun Gölyaka''ya

''Son ver artık ağlamaya

Dur'' de gardaş, duram Aziz

Ateş kavurup yakarya

Çok acıttın beni varya

''Her gördüğün düşü hayra

Yor'' de gardaş, yoram Aziz

AZİZ''im ALLAH aşkına

Bir nasihat eyle bana

''Yüzün kabrimin taşına

Sür'' de gardaş, sürem Aziz

Çok severdim seni serden

Bir ses ver gittiğin yerden

''Beni her gün esen yelden

Sor'' de gardaş, soram Aziz

Bilirsin doymadım sana

Alışamam yokluğuna

''Bak açtım kabrimi aha

Gir'' de gardaş, girem Aziz

Mutlu edeyim diye seni

Gönderirim hediyeni

''Kabrime bütün gülleri

Ser'' de gardaş serem Aziz

Çok severdin Annemizi

Yaktın gardaş yaktın bizi

''Sen Annemi Annen gibi

Gör'' de gardaş, görem Aziz

Karakoç der yaktın beni

Hasretinden ettin deli

''Gönül evine türbemi

Kur'' de gardaş, kuram Aziz', '(Kardeşimin ruhuna ithaf olunur)  Veda ettin yaşamaya Mekan kurdun Gölyaka''ya ''Son ver artık ağlamaya Dur'' de gardaş, duram Aziz Ateş kavuru...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aziz-ime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 60 (''iyi uykular'')', 'lirik-60-iyi-uykular-fevzi-cebe-dtkia', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'melodilerim

sadece melodiler''im

anladınız mı

açık her şey

ve ortada

kaybettirdiler

içimdeki derin sıkıntıyı keşfetmedin biliyorum

kızgın değilim sana

ya da kırgın...

kimim ki ben

kızacak kadar kral değilim

krallığım yok ve vaat edilmedi

affedecek kadar tanrı değilim

tanrı olmak? 

hiç istemedim

bir ot olmalıyım

kurumaya yüz tutmuş 

yüzlerce, benim gibi yüzlercesiyle

salınıvermeliyiz

rüzgarın bizim için üflediği

ve yalnız bizim anladığımız bir melodiyle

bizim anladığımız bir fısıltıyla

okşamalı kurumaya yüz tutmuş gövdelerimizi

...müteşekkirim

törenlerin ihtişamından

gözlerin değmediği

bozkırlara uzandım

tanrı okşadı bizi

kuşandık

ve bindiğimizi düşledik

atlarımıza

ve yürüdük güneşin battığı yere doğru hep

güneşin battığı yere...

... yeniden doğacağımız yer...orasıydı

ve bizim yönümüz, doğuş değil batış...tı

orada kaybolacaktık

eriyip dağılacaktık

eridik ve dağıl...dık

her an

düşlerinize giren...bizleriz

bedenlerinize çok sıkışsanız da 

elimiz, rüyalarınızda

yastığa beraber koyuyoruz başımızı

‘iyi uykular’

08.08.2005 – 00:43', 'melodilerim sadece melodiler''im anladınız mı açık her şey ve ortada kaybettirdiler içimdeki derin sıkıntıyı keşfetmedin biliyorum kızgın değ...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/lirik-60-iyi-uykular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-fethi-aslan-4iyri', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özlediğimden değil,

bir merak.

Öylesine bir merak.

Hani bakar ya insan posta kutusuna

beklediği mektup olmasada,

sadece bir merakla.

Işte öylesine bir merakla

Kapının eşiğine takılıyor gözlerim.

Bir ordu giriyor yüreğime

teslim alınıyor sabahlarım.

Boran,fırtına,kar

böyle gecelerin sonunda 

işte öylesine bir merakla

yollara takılıyor gözlerim.

Beklediğimden değil,

işte öylesine bir merakla

seni arıyor gözlerim.', 'Özlediğimden değil, bir merak. Öylesine bir merak. Hani bakar ya insan posta kutusuna beklediği mektup olmasada, sadece bir merakla. Işte öy...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oylesine-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anlatabilsem', 'bir-anlatabilsem-salim-erben-v6mqi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir anlatabilsem iki kelimeyle 

Duygularımdaki gizli sırları 

Bir anlayabilsem anladığını 

Defalarca tekrarlamazdım. 

Eğitilmiş papağan gibi 

Seni hiç sıkmazdım seviyorum diye 

Sihirli kelime kullanmazdım şiirlerimde 

Sayfalar taşmazdı ayrı ayrı kelimelerle 

Sevmek yada sevilmek 

Her satırda rastlamazdın bunlara 

Sevilmek nasıl bir şey 

Sevildiğini bilmek nasıl bir duygu 

Bunları sormazdım sana 

Ben seni ölümüne sevdim

Yüreğimi ortaya koyup sevdim

Ben sevdim mi 

Candan gönülden severim

Başkalarına benzemem 

Bir anlatabilsem 

Kafamdaki beynimdeki içimden geçenleri 

Bu kadar uzun uzun yazmazdım 

Yeminler edip ağlamazdım 

Anlatamıyorum, hep bende kalıyor 

Bilmiyorum yalanı dolanı 

Yüz yüze gelsem unuturum 

Senin için kurduğum en güzel cümleleri 

Bağışla zalım bağışla beni 

Bende çok seviyorum seni 

Bir duyurabilsem sesimi 

Boğazıma tıkanan kelimeleri 

Senin için saklı en güzelleri 

Salim ERBEN (Zalım', 'Bir anlatabilsem iki kelimeyle  Duygularımdaki gizli sırları  Bir anlayabilsem anladığını  Defalarca tekrarlamazdım.  Eğitilmiş papağan gibi...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-anlatabilsem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurbağa Prens ve Denizkızı', 'kurbaga-prens-ve-denizkizi-nermin-altindag-3qg53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“bizim gözlerimizden deliler öpmüş olmalı

Yoksa böyle aykırı 

Olmazdık

Değil mi Yusuf? ...” 

... Çobanyıldızı…

**********************************************************************************

Bu şehir, bu deniz, bu yosun kokusu… Ahîrkapı açıklarına demir atmış gemilerin suni yakamozları… sen varsın o ışıkların altında, kokun var. 

……. sonra kurbağa prens istiridyenin kabuğunu öpecek. Kabuğun içinden devrik sadrazamın denize hediye ettiği kızı çıkacak. Kız kurbağa prensin dudaklarını arayınca prens ağlayacak. Hahambaşı Arapça dualar okuyacak. Ben dilsiz dua edeceğim: “My God, beni bağışla, help mi ya rabbelalemin…” ben nece edersem edeyim dualarımı, o hep duyacak… 

Ay yok bu gece. Hava ılık… her yer yosun kokusu, senin kokun… bir yıldız kadar görünen uçak önce bir bulutu aydınlattı, sonra o bulutla birlikte görünmez oldu. Selam yolladım sana, aldın mı? 

…… kurbağa prensin dudaklarındaki mühür bir damla gözyaşı ile bozulacak. Devrik sadrazamın denize hediye ettiği kızı ağlayacak, kurbağa prens aynadan Çobanyıldızı’nın baktığını hiç bilmeyecek. Prens, kızın dilenmek için açtığı avucuna kulağı kopuk bir banknot bırakacak. Kızın ayakları dökülen pulların arasından ortaya çıkacak…

Seninle her konuştuğumuzda bir deprem daha oluyor yüreğimin çorak ülkelerinde. Öfkemi çıkartacak bir tek duvar bulsam… başımı vura vura kanatacağım… her depremden sonra el açtığım yıkıntıların arasında dilendim utanmadan… o kadar açtım ki… ama hiç hırsızlık yapmadım… 

……. kurbağa prens aslında çirkinliği yüzüne maskelemiş… devrik sadrazamın denize hediye ettiği kızı sevginin sadakası olmadığını bilirmiş. Çobanyıldızı, aynanın arkasında kurbağa prensten şiirlerini gizlermiş…

Aşk diye bir şey yok. Olsa olsa herkes sadece kendine aşık olur. Karşısında aksini görür, yine kendine aşık olur… Çobanyıldızı kuyuya bu yüzden düşer, kurbağa prens işte bu yüzden bu kadar çirkin, devrik sadrazamın kızı işte denize bu yüzden hediyedir. 

……. Şair bu masalın sonunu kurbağa prense bırakmış…

Dilenmek için avucumu her açtığımda bana sadece cam kırıkları kaldı. Bir de sen vardın aksimin yansıdığı aynalarda. Oradan hiç çıkma. İçimi hep acıt ki yaşadığımı bileyim. Devam et bu oyuna. Ben de sırf sen mutlu oluyorsun diye sürdürmeye devam edeyim. Şimdi elin bende. Dur kaçma… elimi sana vermeliyim… ben… kimsesiz bir şairim…', '“bizim gözlerimizden deliler öpmüş olmalı Yoksa böyle aykırı  Olmazdık Değil mi Yusuf? ...”  ... Çobanyıldızı… *****************************...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kurbaga-prens-ve-denizkizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Söz Versem', 'ben-soz-versem-salim-erben-wwh98', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzatsam elimi tutar mısın 

Alıp koynuna yatar mısın 

Ben söz versem bir ömür 

Sen sözünü tutar mısın 

Tutsam elini uzak demesem 

Bir gece ansızın çıka gelsem 

Sana bir ömür vaat etsem 

Sarılıp koynumda yatar mısın 

Uzatsam elimi,hadi gidelim desem 

Yüreğimi koyup seni sevsem 

Seninle ağlayıp seninle gülsem 

Sen yeminini tutar mısın 

Şiirler yazsan benim adıma 

Kulak versem feryadına 

Bir kere baksan tadıma 

Sen acı tatlıdan anlar mısın? 

Hadi desem kaçalım gelir misin? 

Sen beni tanıyabilir misin? 

E nasıl olacak bu iş 

Hadi söyle bakalım zalım 

Bir numaram diye 

Sen benim gibi sever misin? 

Salim ERBEN (Zalım', 'Uzatsam elimi tutar mısın  Alıp koynuna yatar mısın  Ben söz versem bir ömür  Sen sözünü tutar mısın  Tutsam elini uzak demesem  Bir gece an...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-soz-versem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gönül Cezvesinden', 'bu-gonul-cezvesinden-seyfet-bozcali-jghit', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taşar oldu gözlerimden damlalar,

Rahmet yağmuru gibi yeşertti gönülleri,

Açtı lisan hazinesini,düşünce ummanına,

Dostluklar  kaynatıldı bu gönül cezvesinde...

                   21.02.2006', 'Taşar oldu gözlerimden damlalar, Rahmet yağmuru gibi yeşertti gönülleri, Açtı lisan hazinesini,düşünce ummanına, Dostluklar  kaynatıldı bu g...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bu-gonul-cezvesinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz''ime... / 2', 'aziz-ime-2-emrah-karakoc-o2csj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Kardeşimin ruhuna ithaf olunur) 

Habersizce gittin ama

Gittiğini duydum Gardaş

Sana küstüm kızdım sanma

Dizlerime vurdum Gardaş

Koşarak geldim evine

Sesim değmedi sesine

Sormadın beni sebep ne

O an yanan kordum Gardaş

Vardım gittiğin farkına

Sen diye baktım Arkın''a

Sarılayım dedim ama

Tuttum beni durdum Gardaş

Çoktu sevilecek yanın

Nasıl aktı o al kanın

Korkma yaşayacak namın

Ben çıkla sen oldum Gardaş

Senden önce çöldüm Aziz

Ben seninle güldüm Aziz 

Şimdi yoksun soldum Aziz

Sen yaktın kavruldum Gardaş

Ararım her yerde seni

Bulurum her şeyde seni

Çok özledim dostum seni

Resminle avundum Gardaş

Karakoç der oldu olan

Güzelliktir senden kalan

Minnettarım sana canan

Doğru yolu buldum Gardaş', '(Kardeşimin ruhuna ithaf olunur)  Habersizce gittin ama Gittiğini duydum Gardaş Sana küstüm kızdım sanma Dizlerime vurdum Gardaş Koşarak gel...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aziz-ime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şelalede', 'selalede-muammer-erturan-cjsdo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Davetkâr bir su sesi,

kaplar laciverti...

Hınzır mı hınzır bir fırtına,

körükle gider yangına...

Ve sıyrılır aşağılara doğru

allı morlu ötüsü hazinelerin

yavaş yavaş... 

Ve ışıldar sinesinde gecenin,

ayın şavkı vurmuş

gümüş bir heykel...

Ve salınır sularında şelalenin

aheste mi aheste,

utangaç mı utangaç,

aç mı aç...

Ve çıkagelir

nerelerden kimbilir,

kimbilir hangi yolun yolcusu

bir adam...

Ve ikiye ayrılır lacivert...

Ve ikiye ayrılır sular...

Ve ikiye ayrılır evren

merkezinden tam...

Ne tek bir söz...

Ne tek bir hece...

Kendine özgü gizemince

yol alır,

şelalede gece...

(''98)', 'Davetkâr bir su sesi, kaplar laciverti... Hınzır mı hınzır bir fırtına, körükle gider yangına... Ve sıyrılır aşağılara doğru allı morlu ötüs...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/selalede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Rüzgarı', 'sevda-ruzgari-altay-taskin-umvj5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevda rüzgarı duvara çarpmış

kelepçelenmiş

sevgiliye uzanan el

dikenli alıç boynuna set

yazıdaki acıklı türkü

nutkuna yılgınlık çekmiş

sevgilinin umudu suya düşmüş

nal seslerinin ninnisiyle

sevda rüzgarı uykuya geçmiş...', 'sevda rüzgarı duvara çarpmış kelepçelenmiş sevgiliye uzanan el dikenli alıç boynuna set yazıdaki acıklı türkü nutkuna yılgınlık çekmiş sevgi...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevda-ruzgari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet bir insanı ezdiği zaman', 'gurbet-bir-insani-ezdigi-zaman-mikdat-bal-u09xq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gurbet bir insanı ezdiği zaman

Genç yaşında çöker dağılır gider

Haytına küser bezdiği zaman

Dünyadan da bıkar dağılır gider

Yoksa el tutanı yoksa desteği

Kalmaz ideali kalmaz isteği

Farketmez rüzgarın nerden estiği

Başın kuma sokar dağılır gider

Göz yaşı döküşü her anlık ise

Gönlü harap olup viranlık ise

Geleceği mechul karanlık ise

Hep geriye bakar dağılır gider

Pes eder terkeder savaşlarını

Hiç belli ettirmez telaşlarını

İçine akıtır göz yaşlarını

Dişlerini sıkar dağılır gider

Mikdatî der gönlüm başlar yanmaya

Vaz geçtim sılamı her gün anmaya

Umut olmayınca geri dönmeye

Gemileri yakar dağılır gider', 'Gurbet bir insanı ezdiği zaman Genç yaşında çöker dağılır gider Haytına küser bezdiği zaman Dünyadan da bıkar dağılır gider Yoksa el tutanı ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gurbet-bir-insani-ezdigi-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Şükür', 'cok-sukur-seyfet-bozcali-g02pd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat muammasını,

Sırrın muhtavasını,

Gönlümün tasasını,

Şükür seninle aştım...

Ördü ağları felek,

Gönlüme sabır destek,

Umuda takdir istek,

Şükürlerle kavuştum...

Ateş yüreğe düştü,

Başımdan neler geçti,

Dermansız dertler açtı,

Dualarımla aştım...

       21.02.2006', 'Hayat muammasını, Sırrın muhtavasını, Gönlümün tasasını, Şükür seninle aştım... Ördü ağları felek, Gönlüme sabır destek, Umuda takdir istek,...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cok-sukur-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz''ime... / 3', 'aziz-ime-3-emrah-karakoc-3eedg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Kardeşimin ruhuna ithaf olunur) 

Sen gittin ya canım gardaş

Ağlıyorum Aziz diye

Cansız dediğimiz şu taş

Taş ağlıyor Aziz diye

Kanadın açıp uçmuyor

Uçup ta neşe saçmıyor

Avcılardan hiç kaçmıyor 

Kuş ağlıyor Aziz diye

Gözüm yaşı savrulurken

Yürek yanıp kavrulurken

İçim içten eriyorken

Dış ağlıyor Aziz diye

Aylar hep perişan oldu

Bahar saçlarını yoldu

Yazın gülen yüzü soldu

Kış ağlıyor Aziz diye

Olumsuzluk geldi dile

Dedi niye kırdım, niye? 

Pekalayla mükemmelle

Hoş ağlıyor Aziz diye

Karakoç yandım tükendim

Kardeşi kendim bilirdim

Hayallerim ve ümidim

Düş ağlıyor Aziz diye', '(Kardeşimin ruhuna ithaf olunur)  Sen gittin ya canım gardaş Ağlıyorum Aziz diye Cansız dediğimiz şu taş Taş ağlıyor Aziz diye Kanadın açıp ...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aziz-ime-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık bir maziden gelin!', 'artik-bir-maziden-gelin-veysi-arslan-0m846', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'oysa cenazesi bol bir maziden

ambulanslar geçmezdi! 

bir ülkede

cümleler diri diri yeraltında 

sonsuz tatildedir,

yerüstünde şemsiye tutanların tümü yalancıdır! 

düşenler geri gelmemiştir oysa

düşen taşın hesabını kimse ödememiş

kimse kayıt tutmamıştır kıyımlarına...! 

şehirler dövülmüş

ayakbağı görülen isimler gömülmüştür

aşk ancak ölünce anılmıştır

militan seccadelerde kuyruk yılanları pusu atmış

rehn olmuş hayaller kalaşnikov ucunda uçurulmuş

bir karşıdan bir yandan bir ortadan vurulmuş...

işte o ülkede

şiire fırça atanlar

yüreğime kendilerini dikenlerdir,

o ülkede yazanlar

kendilerine kurşun sıkanlardır! 

oysa cenazesi bol bir maziden

hala bir ambulans geçmedi

yaralıydım,onlar yaralıydı

okuyan yaralıydı

yazdıkça çivi söken derinlik yaralıydı

yara ve düş içinde

düşen çocuklar gelecekti

ben ve ambulans bekliyoruz 

o limanda

artık gelin diyorum

soğumasın elleriniz!', 'oysa cenazesi bol bir maziden ambulanslar geçmezdi!  bir ülkede cümleler diri diri yeraltında  sonsuz tatildedir, yerüstünde şemsiye tutanla...', ARRAY['Türk Edebiyatı','Şiir','Veysi Arslan']::text[], 8.5, '{"poet":"Veysi Arslan","poet_slug":"veysi-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/artik-bir-maziden-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemre', 'cemre-omer-dalman-hx18c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Cemre-memre nedir baba? 

geç Allahaşkına böyle şeyleri! 

bahar geliyorsa gelir dümdüz işte! '' derdim

umursamazdım ama

bu akşamüstü işten dönerken

eve yürüdüm ve olan oldu! 

sanki Cemre benim kucağıma düşmüştü! ? 

havadaki koku -daha da bir alıp, götürücü-

rüzgarın tenime dokunuşu daha bir yumuşak

yıldızların o akşamüstü parıltıları daha berrak

sanki gözgöze gelmek için

sarhoş etmek için beni

hepsi elbirliğiyle uğraşıyorlar! ..

sallana sallana eve vardım neyse ki.

şiir yazacağım

yazı yazacağım, maillerime bakacağım güya! 

nerdeee? ! 

almışım kucağıma Cemre''yi

kolay mı öyle her planladığımı yapmam? ! 

öyle bir binmiş ki Cemre''nin ağırlığı üstüme

kolumu kıpırdatamaz olmuşum, haberim yok! 

bu ne güzel gevşeme

bu ne sarhoşluk

bu ne keyif Allah''ım! ? 

Peki Cemre:

büyük konuşmamayı

bilmeden konuşmamayı artık öğrenmem lazım.

şimdi bugün seninle ilk defa tanıştım.

kim bilir yarın daha kimlerle tanışacağım! 

(Şubat 2006)', '''Cemre-memre nedir baba?  geç Allahaşkına böyle şeyleri!  bahar geliyorsa gelir dümdüz işte! '' derdim umursamazdım ama bu akşamüstü işten dö...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cemre-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-83 (M.S.) 20/02/2006', 'mektuplar-83-m-s-20-02-2006-mahzun-doga-fdkq7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamın sayılmamış sayılarını sayı-klıyoruz

elimizde binlerce sıfır

ve hacmi henüz belirlenmemiş şeklimiz

yokluğa varlık öğretiyoruz

Zamanın bütün değerleri yirmi şimdi

günün adı yirmi

saat yok''u yirmi geçmiş

zaman ellerine bir kalmış

yarın çoktan geçmiş yüzünü

Boyumuzu aşmış denizler içindeyiz

bütün köpekbalıkları boğulmuş

ve gitmişsin

bütün anaforlar üzerimize yığılmış

Vakit ellerinden çok geçmiş

tek''liğinin sayısıszlığını sayıyoruz', 'Yaşamın sayılmamış sayılarını sayı-klıyoruz elimizde binlerce sıfır ve hacmi henüz belirlenmemiş şeklimiz yokluğa varlık öğretiyoruz Zamanın...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mektuplar-83-m-s-20-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göremedim...', 'goremedim-durdane-demirkoparan-7gfy7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki  göremedim  seni

Işığın yansımadı  yüreğime

Belkide

Belki  izin vermedim

Ne kendime

Ne  sana 

Korktum

Sevmekten  korktum

Aşk  yaraladı beni

Belki  anlatamadım

Belki  anlamadın

anlamak istemedin

Aşk  ağır  geldi  yüreğime

Sana  bekle  diyemedim

Üzemezdim seni

Bu duyguyu tatmışken

En ağırından

Gülüşünü  sevdiğim

Soldurmak istemedim

Sıcacık  yüreğini

Sen  ne  sevgiler

Ne  güzellikler

Hak ediyorsun

Belki unuttun beni

O çok sevdiğin gözlerim

Gülüşüm

Silindi yüreğinden 

Ama  özledim işte

Sıcacık  gülüşünü

Sesini

Ve 

Kocaman yüreğini

Affet göremedim…

Affet göremezdim...', 'Belki  göremedim  seni Işığın yansımadı  yüreğime Belkide Belki  izin vermedim Ne kendime Ne  sana  Korktum Sevmekten  korktum Aşk  yaraladı...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/goremedim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antalya''yı Gam Almış...', 'antalya-yi-gam-almis-i-brahim-ethem-bingul-tlctr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mavi denizine,yeşil tepelerine

Huzur veren ılık nefesine

Bakmaya doyulmaz o güzelliklerine

Hüzün değmiş,hasret çökmüş

Göz yaşları dolmuş gülen gözlerine...

Antalya''yı gam almış

Kasvetine özlem dolanmış

Anılarının güzelliği her yanı sarmış

Gözlerim bir dostu arar

Yüreğimde öylece sızı kalmış...

www.iebingul.com', 'Mavi denizine,yeşil tepelerine Huzur veren ılık nefesine Bakmaya doyulmaz o güzelliklerine Hüzün değmiş,hasret çökmüş Göz yaşları dolmuş gül...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/antalya-yi-gam-almis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşksın', 'asksin-aydin-bastan-2p50z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşksın

Bir sen varsın, bir de ben

İçimdeki alevim,

damarımdaki kansın.

Sen benim yüreğimde açan

Nar çiçeğisin.

Sen özlediğim sevdamsın.

He an beklediğim sen,

Kara sevdamsın.

Sen yaşadığım en güzel aşksın.

Cihan 21/02/2006 Salı', 'aşksın Bir sen varsın, bir de ben İçimdeki alevim, damarımdaki kansın. Sen benim yüreğimde açan Nar çiçeğisin. Sen özlediğim sevdamsın. He a...', ARRAY['Türk Edebiyatı','Şiir','Aydın Baştan']::text[], 8.5, '{"poet":"Aydın Baştan","poet_slug":"aydin-bastan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/asksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelkenler Değdi Suya', 'yelkenler-degdi-suya-muammer-erturan-jx1p6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu kara bulutlar 

bu kıskançlık şimşekleri 

oldu mu şimdi, 

bilmez misin ki ben

sen olmadan asla… 

Nerden estiyse esti

nasıl kestiyse kesti yerden ayaklarımı 

deli dolu bir fırtınaydı işte… 

Kapılıp büyüsüne çılgın dalgaların 

koyverdim kendimi sulara 

o sarhoşlukla... 

Her kulaç 

yeni bir ufuk demekti

her ufuk 

yeni bir güneş 

her güneş 

yeni bir umut... 

Tut ki yakaladık kaçırdıklarımızı 

kaçıracaklarımızı hatta

bu ezber bozumunda…

Sandım ki 

seni de sarar 

bu sıra dışı macera,

sarhoşluk bu ya... 

Ayılınca ancak 

yelkenler değdi suya... 

(''96)', 'Bu kara bulutlar  bu kıskançlık şimşekleri  oldu mu şimdi,  bilmez misin ki ben sen olmadan asla…  Nerden estiyse esti nasıl kestiyse kesti ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yelkenler-degdi-suya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk artık seni sevmiyorum!', 'ask-artik-seni-sevmiyorum-veysi-arslan-8x4hb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zayıf bir bataryayla çalıyorum geceni 

aslını kaçırmış bir fotokopiden

ne düşerse artık payına! 

bense heceliyorum artık uzunluklarımı

kısalmış pantolonla yama tutuyorum hayata

sen ki aşk koksa gün utanır

en ünsüz lügatlardan taş kaldırımlara

aynı şehirde yatan iki yarasanın

radarlarında rehin kalır geçmişim! 

ağır bir hüzzam,kaç litre alkol

kaç şizofren cümle yetişir ki imdadıma! 

aşk artık seni sevmiyorum

artık kumaşlardan geçilen her iğne

daha eza,

ki işkence şehr-i istanbulda dilsiz kalmaktır

fransız olmak cezayir sokağında! 

aşk kaçbedeni talan etsede imgem

sadece acıyorum şehitlerine

ki artık sana da acıyorsam

şayet seni bir halktan 

daha çok seviyorsam

pimini çek

esir kıl kendini

yalnızlığıma dokunma!', 'zayıf bir bataryayla çalıyorum geceni  aslını kaçırmış bir fotokopiden ne düşerse artık payına!  bense heceliyorum artık uzunluklarımı kısal...', ARRAY['Türk Edebiyatı','Şiir','Veysi Arslan']::text[], 8.5, '{"poet":"Veysi Arslan","poet_slug":"veysi-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-artik-seni-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul sevgiliye....', 'mechul-sevgiliye-ercan-akbay-88yod', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum

   Siyah gece de, ak umutlarla.

   Seni şekillendiriyorum

   Gözlerim açık,dost yıldızlarla..

   Seni bekliyorum

   Her şafak yeniden,taşan sabrımla..

   Sen ey...meçhulde ki sevgili

   Seni özlüyorum,

   Bitmeyen yalnızlığımla...

                            13.4.1978', 'Seni düşünüyorum    Siyah gece de, ak umutlarla.    Seni şekillendiriyorum    Gözlerim açık,dost yıldızlarla..    Seni bekliyorum    Her şaf...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mechul-sevgiliye-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Islığında Celebin', 'i-lk-isliginda-celebin-muammer-erturan-02uk6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sürüden ayrılmak zor...

Çok zor...

Epeyce yürek istiyor...

Epeyce emek...

Özenmek başka şey kuşlara,

uçmak başka...

Sürüden ayrılmak zor...

Çok zor...

Kopulamıyor öyle hemen...

İlk ıslığında celebin

kuzu kuzu dönen

sen değilsin ilk...

(''98)', 'Sürüden ayrılmak zor... Çok zor... Epeyce yürek istiyor... Epeyce emek... Özenmek başka şey kuşlara, uçmak başka... Sürüden ayrılmak zor... ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ilk-isliginda-celebin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günler Bi'' Tuhaf', 'gunler-bi-tuhaf-muammer-erturan-glvwe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşamlar 

sultasında kopuşların... 

Bakakalmalar ardı sıra

kalakalmalar umarsız 

sövüp saymalar soyuna sopuna 

böyle mahkûmiyetin hay! .. 

İple çekilir oldu sabahlar 

özlemle dolu...

Güneşim oldu ışıl ışıl

ve pırıl pırıl ufkum

ve kanatlarım pasparlak

ve kavak yelim

ve gönül telim gümbür gümbür

ve sevişken kuşum,

aslımı buldum özünde... 

Keşke donabilse zaman

batmayabilse gün...

Bu son faslında ömrümün 

günler bi'' tuhaf gene... 

(''01)', 'Akşamlar  sultasında kopuşların...  Bakakalmalar ardı sıra kalakalmalar umarsız  sövüp saymalar soyuna sopuna  böyle mahkûmiyetin hay! ..  İ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunler-bi-tuhaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet Çocukları', 'cumhuriyet-cocuklari-hasan-gorgu-hp7l8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saçlarını süpürge göğüslerini siper ettiler

Kol kanat gerdiler emeklerini verdiler

Soğanı katık samanı yatak yaptılar

Ağladılar güldüler

Gerektiğinde öldüler

Hamurlarını alın teriyle yoğurdular

Adam olacak çocuklar doğurdular

Analarının ak sütü gibi helal ettiler

Adam gibi bir memleket bıraktılar

Karşılık beklemeden çekip gittiler

Cumhuriyet çocuklarıydı onlar

Vatan evladıydılar

Atmadılar satmadılar üstüne yatmadılar

Bırakıp kaçmadılar

Adam gibi adamdı onlar

Yastıkları bir karış toprak

Yorganları bir avuç sararmış yaprak oldu

Cumhuriyet çocuklarıydı onlar', 'Saçlarını süpürge göğüslerini siper ettiler Kol kanat gerdiler emeklerini verdiler Soğanı katık samanı yatak yaptılar Ağladılar güldüler Ger...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cumhuriyet-cocuklari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hasretin Oğluyum', 'ben-hasretin-ogluyum-omer-temel-z5qvk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben hasretin oğluyum.

Babam gurbet.

Kızkardeşim var,

Mayınlı sınırların ötesi.

Hele birde,

Kara gözlü sevgilim:

Yusuf’tan daha derin,

Kör kuyu,kara zindan.

Uzatsan elin yanar,

Yüreğimin korundan.



                                             25.06.2005', 'Ben hasretin oğluyum. Babam gurbet. Kızkardeşim var, Mayınlı sınırların ötesi. Hele birde, Kara gözlü sevgilim: Yusuf’tan daha derin, Kör ku...', ARRAY['Türk Edebiyatı','Şiir','Ömer Temel']::text[], 8.5, '{"poet":"Ömer Temel","poet_slug":"omer-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-hasretin-ogluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Kadar Olamayanlara', 'kus-kadar-olamayanlara-ramazan-ates-ljpqw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hiç sevdasını sunan kuş gördün mü? 

Bir güvercin, bir kumru yada bir serçe.

Önce etrafında aşk nameleri söyler,

Kıvranır, dolanır, olmadık cilveler saatlerce.

Tabi erkek kuş bu etrafda dolaşıp kur yapan,

Dişide bir eda, bir naz, kaçar ama yan gözle bakar.

Oda sevlanmıştır ama, gel görki hemen he demez,

Tıpkı Aslı’nın Kerem’e, Leyla’nın Mecnuna yaptığı gibi.

Sonunda ikna olur dişi, kabul eder aşkı.

Ve erkekde bir gurur, bir başka öter şimdi.

Cilve yapar, gider boynuna dolanır,

Ve en önemlisi de sevgilisini diğerlerinden kıskanır.

Kuş diye hafife alırız ama,

Kuşdaki de gönül, onunda adı sevda.

Bir birine boyunlarını sürer, koklaşırlar,

Gagalarıyla öpüşür, oyle oynaşırlar.

Eşini kıskanır, yaklaştırmaz başka kuşu,

Kuş deyip geçme, ondada var namus duygusu.

Ölümü göze alır, korur sevdiğini,

Kucaktan kucağa vermez, bilir sevginin kıymetini.

Kuş kadar olamıyanlar utansın.

Ramazan Ateş/Enschede-21.2.2006', 'Sen hiç sevdasını sunan kuş gördün mü?  Bir güvercin, bir kumru yada bir serçe. Önce etrafında aşk nameleri söyler, Kıvranır, dolanır, olmad...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kus-kadar-olamayanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On yıl sonrasına yavruma mektup', 'on-yil-sonrasina-yavruma-mektup-yusuf-ziya-leblebici-g5n8t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana nasıl anlatsam yavrum

Anlayamayacaksın biliyorum.

Onun için de bu mektubumu

On yıl sonrasına gönderiyorum…

Gözlerimizi kaç kez mühürledik

Görmek istemediklerimiz kaybolsun diye.

Umutlarımızı hep önümüze koyduk

Hep bir kaç adım ilerledik

Her adımda çelme takıldı yavrum.

Erkekler ağlamaz diyorum ya sana

Ama sen, yine de inanma

Gözü olan her canlı

Bazen engel olamaz gözyaşlarına…

Sana anlattığımız güzellikler, hep masallarda yaşanıyor

Sevgi dolu hikayeler, kitaplardan hiç çıkmıyor.

Sana şimdi bunları nasıl anlatayım yavrum

Büyüyünce sen göreceksin

Ben anahtarı önüne koyuyorum

Uyduğu kapıları sen açacaksın.

Neden ağladığımı artık sorma

İnsanlık dışı hayvanlaşmalar

Sevabı günahla karıştırmalar

Ardını döndüğünde sırtından vurulmalar

Bittiğinde, 

Söz….ağlamayacağım...

Seni, beni eğitecek, tedavi edecek

Ve halkını düşünecek.

Bizleri ezmeden, 

düşündüklerimize suç demeden

emeğe emek diyen

“işte bu benim halkım” diyecek

bir düzen geldiğinde,

söz…ağlamayacağım…

Senin gibi binlerce yavrunun tokluğunda

Seni okula gönderirken cebine harçlık koyduğumda

İstediğin oyuncakları önüne doldurduğumda,

Söz….ağlamayacağım…

Bak yavrum; 

Yanaklarını tuttuğumda elime gelen sıcaklığı

Sen de yaşayacaksın günün birinde

Sana anlattığımız masalları

Sen de ballandıracaksın dilinde.

Okuyacaksın, kelimeler ekmeğin suyun olacak

Yarınlarına yol, yollarına yolcun dolacak

Seni besleyen bu harfler, damarında kanken

Başka harfler düşman olup karşına çıkacak

Okuyacaksın yavrum, kinli gözlere baktığında

Mum gibi eritecek, yeni filizler sunacaksın baharlara

Kediden daha nankör

Köpekten daha kuduz insanlar göreceksin.

İnsandan daha uysal, daha sadık hayvanlar bileceksin.

Zaman her şeyi gösterecek yavrum.

Göreceksin gözkapakların kapalı olsa da

Hissedeceksin kulakların duymasa da.

Her şeyden önemlisi, yaşayacaksın

İhanetleri, sevgileri

Yaşayacaksın esareti, özgürlük hasretini

Seveceksin, sevmek sevilmek kadar güzel olmasa da.

Belki de ölümü seveceksin, uğruna can koyduğun davada

Hak vereceksin sana bunları yazan babana! 

Ama on yıl sonra; ben hala yaşıyorsam

Yarınlara umutla gidelim kolkola…

Çünki, o zaman beni daha iyi anlayacak

Ve haklısın babam diye kucaklayarak

Haydi gidelim diyeceksin şu yarınlara! ..', 'Sana nasıl anlatsam yavrum Anlayamayacaksın biliyorum. Onun için de bu mektubumu On yıl sonrasına gönderiyorum… Gözlerimizi kaç kez mühürled...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/on-yil-sonrasina-yavruma-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri Renkte Hayatın Yüzüne Çalınan Kırmızı', 'gri-renkte-hayatin-yuzune-calinan-kirmizi-atilla-guler-4xfc3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kuyruğuna bağladığım umutlarımı da alıp

ucuz bir ateş ardında yitiklere koşan uçurtmamdan

aldım kırmızıyı

tek renk seyrediyor yoluna benden yoksun

katlanılmaz oldu dırdırına hayatın

her gün yeni bir şamata/patırtı gürültü

b ı k t ı r d ı

kestirememiş tanrı önceden

payıma düşen pastanın bulaşacağını/elime

ellerimin arasında kayıyor kir

sınavımı vereli öyle uzun zaman oldu ki

ben bile unuttum

sonucunda geçtim mi/kaldım mı

geçtimse niye hala gri dünya

kaldımsa niye hala dünyadayım

her melodide kanıma işleyen acı

öfkeli bir şarkıcıda patlak verecek bir gün

…biliyorum

görmediğini sandığın gözlerim göreli ömürler tükendi

her an…her saniye

biraz daha uzaklaşıyor tin inançtan

seks satıyor/alanın haddi hesabı yok

aç ölüyor/hani…nerede duyan

Ayla Hanımın mavi tuvaletine gitmeyen pabucu ayağını sıkmış

sokakta bir evsizin yalın ayağında yatan insanlığım

utanıyorum

her an

her saniye

tek renk seyrediyor yoluna

hayat

“life is a bitch”

gerisi palavra

tin ölüyor

ruhuna dua okunmaz artık

inanç sıkıntılı bir cinayete kurban

her an

her

kanayan her yaraya sarılan bant dindirmiyor kanı

her yer kırmızı', 'kuyruğuna bağladığım umutlarımı da alıp ucuz bir ateş ardında yitiklere koşan uçurtmamdan aldım kırmızıyı tek renk seyrediyor yoluna benden ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gri-renkte-hayatin-yuzune-calinan-kirmizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Roman-III-', 'roman-iii-nurten-koroglu-rbox7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin ikliminde laleler yetişiyor biliyorum

devir senin devrin

ben çöl ortasındayım

gecesi ayaza çekilen

sabahında,çatlamış dudaklarıma 

bir damla su verin! 

serseri,kelimelerim bedenimden ağır

hayat ondanda ağır

yine  yazıyor kalemim  bu romanı

nafile duyan yok! 

sırtımı dayadım  buz dağına

  gören yok elemimi

bağır dizelerim bağır! 

kırma gönül kalemini

ağla ağlayabildiğin  kadar! 

senin  ikliminin  vicdanı sağır.

SON....', 'Senin ikliminde laleler yetişiyor biliyorum devir senin devrin ben çöl ortasındayım gecesi ayaza çekilen sabahında,çatlamış dudaklarıma  bir...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/roman-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Omuz omuza', 'omuz-omuza-yusuf-ziya-leblebici-389q5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Omuz omuza verip

Gidelim yarınlara

Hep bir araya gelip

Çıkalım aydınlığa

Unutmayın hepimiz

İnsanız, insanlarız

Yalnız kalsak birimiz

Kurda düşen lokmayız

Gel kardeşim yanıma

Gel de gir şu koluma

Dosta doğru koşalım 

Verip omuz omuza

Sevdaların uğruna

Dağların doruğuna

Hep beraber çıkalım

Çıkalım şu dağlara

Dev gibi yürekleri

Kan kaynayan gençleri

Cehalet inadına

Tutalım şu elleri

Yusuf Ziya el tutar

Havaya güller saçar

Verip omuz omuza

Dostluğa dostluk  katar', 'Omuz omuza verip Gidelim yarınlara Hep bir araya gelip Çıkalım aydınlığa Unutmayın hepimiz İnsanız, insanlarız Yalnız kalsak birimiz Kurda d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/omuz-omuza-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok şimdi! .. (anılara dem)', 'yok-simdi-anilara-dem-yusuf-ziya-leblebici-x34cq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''canı çıkmayasıca milcanlar

top değil bunların dertleri

valla fışkıların ardına düşmüşlerdir...''

........Elif Kadın''ın ince sesine 

Zeynep Teyze''den yanıt gelir; 

''Yok anam yok,

bizim gobeller haggad topa getmiş

Allah o toplarını yara da

papuçları yarılmaya emi...''

.......Yazın kavurucu sıcağında

lastik çizmeler vursa da ayağımızı

Baba burunu yüklendim mi topa

İndirmez miydik evlerin camını! 

Taşlardan kurduğumuz kalelerde

adam yetmeyinde tek kale,

kalabalıksak misketine...

Hele de kazaklara yapıştırmışsak

dokuzlu, onlu numaraları

kıran kırana, çamura yatan yatana...

Ardından değirmene, yanındaki derede çimmeye...

.........''Gavurun bebeleri gaçmış gene tepelere

üstbaş çamur dönecekler akşama

Valla anam gollarım kopuyo çitilemekten''

......Fatma Bacı söylene dursun kendi kendine

Menşir Bibi memnundur gelecek çiğdemden; 

''Gız öyle emme, bebeler de bir şeyler topluyo

Gızıp durma be! .. Hem çorbana yarma geliyo...''

....Düşe kalka çıktığımız tepelerde

Saldırmaz mıydık o çiğdemlere? 

Sonra da mahalleye inip; 

''...Çiğdem çiğdem çiçeği....

Kimi bulgur, kimi yulaf, kimi de yarma

vermez miydi o güzelim çiçeklere? ..

Ne pencerelerden bağıran o kadınlar

Ne de çiğdem karşılığı alınan yarmalar

Yok şimdi sokak aralarındaki

Birbirimizi kırdığımız o maçlar! 

Heyhat; Nede çabuk geçti yıllar

Ne çiğdem kaldı koklayacak

Nede arkadaş sarmaş dolaş olacak

Tek sokaklar kaldı

Bir de  / her tarafımızı saran sahte insanlar

Etrafımızı kuşatan soğuk betonlar...', '''canı çıkmayasıca milcanlar top değil bunların dertleri valla fışkıların ardına düşmüşlerdir...'' ........Elif Kadın''ın ince sesine  Zeynep T...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yok-simdi-anilara-dem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar''a', 'ruzgar-a-hasan-tahsin-azatli-mj034', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öldüğümde ağlayacak mısın Rüzgar? 

Gözyaşı dökecek misin bir kasım sabahında

Islak memleket toprağı kokan mezarıma

Çünkü o gözyaşları birer incidir Rüzgar,

Birer pırlanta,birer yıldız adeta

Eğer sen önce ölseydin Rüzgar,

Terkedilmiş bir köy kahvesi gibi

Elem dolu sonumu beklerdim

Ne mutlu bana ki,ben gözlerimi kaparken

Sen hayattasın Rüzgar

Eğer sen önce ölseydin,

ben kurumuş bir dere yatağı olurdum adeta

Olur ya,bir gün bir sahil evinde dinlenirken,

Ya da bir parkta otururken,

Otobüs beklerken belki de

Bir şarkı mırıldanırsan eskiden

Bil ki dudaklarımdadır o şarkı Rüzgar

Bil ki dudaklarımdadır o', 'Öldüğümde ağlayacak mısın Rüzgar?  Gözyaşı dökecek misin bir kasım sabahında Islak memleket toprağı kokan mezarıma Çünkü o gözyaşları birer ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tahsin Azatlı']::text[], 8.5, '{"poet":"Hasan Tahsin Azatlı","poet_slug":"hasan-tahsin-azatli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruzgar-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut İpliği', 'umut-i-pligi-muammer-erturan-a57o1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlık dolu bir boşluk

tutunacak yeri yok 

senli düşlerden başka...

Almışım karşıma

dalmışım derinine gözlerinin, 

gülümsüyorsun 

çocuksu ve masum... 

Seni anlatıyorum sana 

bendeki seni 

anlıyorsun, 

karşılık bile veriyorsun 

zaman zaman... 

İnanmazsan bana sor! ..

Sonra... 

Sonrasını sorma! .. 

Sonra nasıl savrulduğumu

nasıl kavrulduğumu

un ufak olduğumu nasıl

ve nasıl küstüğünü güneşin,

sen misin giden...

İşte böyle... 

Bir elimde boş makara 

sar sar dolmaz,

bir elimde umut ipliği 

sarmasam olmaz...

(10 Ocak ''80)', 'Yalnızlık dolu bir boşluk tutunacak yeri yok  senli düşlerden başka... Almışım karşıma dalmışım derinine gözlerinin,  gülümsüyorsun  çocuksu...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/umut-ipligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum-I-', 'gidiyorum-i-nurten-koroglu-k7l3e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yükleme bana

tüm veballeri

böyle alıp başımı

gidiyorum diye

sanma ki yara değil

her yaşanan içimde

sanma ki gerçek değil

yalan dediğim bile

Bil ki rüyalarımdadır her gece

tutamadığım ellerin

dokunamadığım o tenin

öylece girerken düşlerimin koynuna

ah yine

yine,kurşunluyor beni gözlerin

Yaşadığım o günler 

gençliğimi hırpalarcasına

büyük yaralar açıyor bedenime

sevgi dedim,

hüzün doldurdum yüreğime

Biraz daha kalırsam eğer

viran edecekler

kendim bile giremediğim

sevgi bahçelerimi

koparıp atacaklar bir gün biliyorum

gözlerinden izlerimi

Gidiyorum; 

şimdi dilimde acı bir türkü

ayaklarımda yorgun yıllar

bilinmez; 

nereye kadar götürürler

sevgiye dair

tüm yaşadıklarım

ve de yaşayacaklarım

hepsi,

hepsi bu kadar

Gidiyorum işte 

ey gözleri gece karası

ey bakışları sevda yarası

günlerce,gecelerce

kapısında ağladığım

sesimi duymayan yar

yok ki mucizeye dair

tutunacak bir tek dal

gidiyorum ben

sen hoşçakal', 'Yükleme bana tüm veballeri böyle alıp başımı gidiyorum diye sanma ki yara değil her yaşanan içimde sanma ki gerçek değil yalan dediğim bile ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/gidiyorum-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turna Başımı Eğdi (Turnalardan Cevap var)', 'turna-basimi-egdi-turnalardan-cevap-var-ramazan-ates-nlrut', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Turnalardan cevap var; 

Sen diyor insanoğlu dinle beni; 

Çağrını duydum, belki haklısın.

Cevap vermedim eskiden beri.

Sana bir kaç soru, cevap ver bana,

Ondan sonra sitem et, kız bana.

Sizce sevda nedir? Aşk nedir? 

Sevgi nedir? Nasıl sevilir? 

Sen Turna’ya değil kendinize bak hele,

İnsan olup insan eti yiyenler,

Vahşice, canice dünyayı kan edenler.

Niye bize bakıp feryat figan edersin? 

Sevgi dediğinize inanıyormusunuz? 

Siz birbirinize güveniyormusunuz? 

Bir birinizin gözünü oymuyormusunuz? 

Niye bize bakıp isyan edersin öyle? 

Hangi sevgi bir haftayı geçiyor? 

Hangi yuva sevgi ile büyüyor? 

Kuşlar bile artık size gülüyor.

Turna’lara niye isyan edersin? 

Mecnun’musun bana hesap sorarsın? 

Kerem’misin, Aslı için yanarsın? 

Hangi sevda tarihlere geçicek? 

Turna’lar kime, neyi söylesin? 

İnsan değil cani olup çıktınız,

Para, pulda, hep şehvette aklınız.

Siz, her değeri yıktınız,

Niye bana bakıp isyan edersin? 

Ağır oldu insanoğlu sözlerim,

Kör olaydı, bu günleri görmeyeydi gözlerim.

Ben Turna’yım artık uzak uçarım,

Kendimi korumak için, inan sizden kaçarım.

İster küs, ister darıl, ben buyum, budur sana cevabım işte.

Ramazan Ateş/Enschede-21.2.2006', 'Turnalardan cevap var;  Sen diyor insanoğlu dinle beni;  Çağrını duydum, belki haklısın. Cevap vermedim eskiden beri. Sana bir kaç soru, cev...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/turna-basimi-egdi-turnalardan-cevap-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soldurma...', 'soldurma-zulfikar-yapar-kaleli-hrr1l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Bence yaptığından utanan kişi

Ne beni çağırsın, ne kendi gelsin! 

Aşkın ne zamanı, ne de var yaşı

Ne bana bil desin, ne kendi bilsin! 

Yeter ki; üzülme benim yüzümden

Gerisi mi? Boş ver, aldırma sakın. 

Alınma nazımdan, küsme sözümden

Zemheri gülünü soldurma sakın.

İki el bağrımda çaresiz iken,

Dal gibi tutmalı, tutulmalıydın...

Yüreğim kuruyup çoraklaşırken,

Yar gibi sarmalı, sarılmalıydın...

Bugün olmasa da yarın, ilerde

Darılsan da canın sağ olsun senin.

Kar bahara küsmüş zemherilerde

Sinen ki; gül açan bağ olsun senin.

Geç gördüm gerçeği kusura bakma

Bir elimde kalem, seni yazarım

Beni yakıyorsun kendini yakma! 

Güzelliği aklım almaz, bozarım! 

Artık Kaleli’nin dağları kardır

Her mevsim başında duman eksilmez

Tepesi sevdadır, eteği yârdır

Bilin ki dilinden aman eksilmez', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Bence yaptığından utanan kişi Ne beni çağırsın, ne kendi gelsin!  Aşkın ne zamanı, ne de ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/soldurma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '… Gülümse', 'gulumse-birsen-ates-2xl6p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gittiğin yerlerde dinle

esen rüzgarların sesini

getir hayalimi yüzüne 

kanarken bile yaran

gülümse

söyledim çok sevdiğin martılar

sesimi getirecek sana 

getir aklına söylediklerini

yine gülümse

dikişi sökülmüş arzuları

biriktirdim geceye

dudaklarımdan 

sürükle beni yıldızlara

her an her yerde

getir beni düşlerine

gülümse

21.02.06', 'gittiğin yerlerde dinle esen rüzgarların sesini getir hayalimi yüzüne  kanarken bile yaran gülümse söyledim çok sevdiğin martılar sesimi get...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gulumse-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olabilmek', 'olabilmek-kamer-taskin-ixouf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uykusuz gecelerin uykusu,

Kimsesizlerin kimsesi,

Yakan güneşin serinliği,

Çaresiz dertlerin çaresi,

Bilinmeyen bilgilerin bilgesi,

Olabilmektir aslolan,

Gerisi hep yalan.', 'Uykusuz gecelerin uykusu, Kimsesizlerin kimsesi, Yakan güneşin serinliği, Çaresiz dertlerin çaresi, Bilinmeyen bilgilerin bilgesi, Olabilmek...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olabilmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıncı Geçişim Bu Yoldan', 'kacinci-gecisim-bu-yoldan-melih-coskun-4zkdv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaçıncı geçişim bu yoldan

Ve kaçıncı kere 

Yoksun rüyalarımda 

Öyle güzeldi ki

Hiçbir zaman gelmeyeceğini bilerek 

Yine de beklemek seni 

Yürümek tenha sokaklarda 

Dilimde masmavi ezgilerle.

Sensiz dinlediğim bütün şarkılarda 

Kederli parmaklarıyla dokunuyor yalnızlık 

Göğsümün bamteline

Suyu çekilmiş bir kuyu kadar anlamsız şimdi bakışlarım

Sesini kaybetmiş bir keman kadar duygusuz  

Akdeniz’im 

Sana geldim 

Bir parça lacivert vermez misin bana

Öpmez misin gözlerinden anılarımın...

2005', 'Kaçıncı geçişim bu yoldan Ve kaçıncı kere  Yoksun rüyalarımda  Öyle güzeldi ki Hiçbir zaman gelmeyeceğini bilerek  Yine de beklemek seni  Yü...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kacinci-gecisim-bu-yoldan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık', 'yazik-nedret-celen-eysc9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi üretip

Acı tüketenlere

İhanete uğrayıp

Dostluk bileyenlere

Umut dileyip

Hüsran olanlara

Hayallerine bile

Gem vuranlara

Doğruyu yanlışı

Ayrı tutanlara

Yazık değil mi? ...', 'Sevgi üretip Acı tüketenlere İhanete uğrayıp Dostluk bileyenlere Umut dileyip Hüsran olanlara Hayallerine bile Gem vuranlara Doğruyu yanlışı...', ARRAY['Türk Edebiyatı','Şiir','Nedret Çelen']::text[], 8.5, '{"poet":"Nedret Çelen","poet_slug":"nedret-celen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yazik-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-yurdagul-ozay-n6a8o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hepsi birer birer ayrı ayrı efsanedir

Okumasını bilene başlı başına

Bir dostluk hikayesidir

Arandığı an da en iyi arkadaş

Sunulan yüreklerde hem eş hem de sırdaş

İstendiğinde en güvenli sığınaktır kadın

Bazıları bir sırdır

Kendi gizeminde öylesine güzeldir

Bazıları dağlar kadar sağlam

Bazıları denizler gibi engin

Ama o ne enginliğine bakar ne de yüceliğine

Dosttur onlar dostum sevdiklerine

İsterse bir dilberin umurunu alır

Yiğitlik mertlik sadece erkeklerde mi olur

Onun şanını gücünü de taşır

Dağların görkemliliği bile

Bazen kadının yanında hiç kalır

Çünkü her yiğidi her güzeli 

Doğuran bir kadındır 

O gürül gürül akan bir sevdadır

İsterse suya inmiş bir ceylanın

Mahzunluğuna bürünür 

Ürkütülürse ele geçmez sır olur

Kadın deyip geçmeyin sakın

İsterse bu dünyaya dur dedirtir

Yüreğinin kıvrımındaki aşktır

Kadını böylesine güzelleştiren

Alnında tomurcuklanan terdir 

Onu böylesine yücelten

Ondaki şefkat özveridir ana dedirten

Ve rüzgârın getirdiği kır kokuları gibidir

Yürekten sevene kadın

Gönülden içirir mutluluğu

Eğer ki erkeğine düşerse kadın

İşte o zaman başlı başına

Bir ömürdür bilene

Bir ömre bedeldir dedirten kadın

Yaşarken öldüren ölürken yaşatandır kadın', 'Hepsi birer birer ayrı ayrı efsanedir Okumasını bilene başlı başına Bir dostluk hikayesidir Arandığı an da en iyi arkadaş Sunulan yüreklerde...', ARRAY['Türk Edebiyatı','Şiir','Yurdagül Özay']::text[], 8.5, '{"poet":"Yurdagül Özay","poet_slug":"yurdagul-ozay","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kadin-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sewusen', 'sewusen-ercan-cengiz-lzya3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sewusen

yemek içmek için de olsa 

ne bir bardak elimin altında, ne tabak 

Dersim''in ''delisi''yim can''lar sağ olsun 

evleri sıcak, sofralarında yerim var 

yatmak, kalkmak için de olsa 

bir yatağım bir evim olmadı 

zamanım yoktu üst baş almaya 

alamazdım da 

Dersim''in ''deli''siyim can''lar sağ olsun

tepeden tırnağa giyiniğim Munzur’dan 

neler çektiğimi bilirler

Sewusen''im ben Sewusen 

bir öğretmen eliyle kıydılar canıma

çocuklarımı düşünün / onlar ki yüzümü 

görmüşlerdi divane döndüğüm yollarda

-Sewusen''i vuran öğretmen 

deli raporu alır, kurtulur...-

Toprak Tutsun Külümü', 'Sewusen yemek içmek için de olsa  ne bir bardak elimin altında, ne tabak  Dersim''in ''delisi''yim can''lar sağ olsun  evleri sıcak, sofralarınd...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sewusen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanışma Kararı', 'tanisma-karari-sevinc-kavuk-rt7hw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'benden olsun bir ilk söz

tanışma kararı aldım ya hani

zaten yüreğimin sesi gümbür güm

kamaştırıyor gözlerimin ışığı ne biçim

olsun, ben hakkımı kullanacağım

kadınım, seviyorum elbette 

bağımsız, doyumsuzluğumca hem 

seçimlerde özenimim olmalı tabii ki 

ama bana yetiyor düşüncemle birlikte 

ruhumda taht kurabilecek bir sevgili 

tamam, ciddiyetim de olmalı şimdi

başka bir kadından daha iyiyim diyebilecek 

tüm benzer küstahlıklar beni çok aşar 

yoksa paylaşmak değil ürküten 

hem de seviyorum derken

seviliyorum demeye

peki şimdi? 

gerisi allah kerim mi? 

bir tanem

elin, kaşın, gözünle değil

ben de ne olabileceğini düşün bir

şans mı…bitlenmeyendedir o…

ne aklını yüreğinde, ne yüreğini aklında

20.02.2006', 'benden olsun bir ilk söz tanışma kararı aldım ya hani zaten yüreğimin sesi gümbür güm kamaştırıyor gözlerimin ışığı ne biçim olsun, ben hakk...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tanisma-karari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku Yaşla Sönmezmiş', 'korku-yasla-sonmezmis-yasemin-sezer-tulgar-zuly9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vakarlı nakşolmak yaşına

Gergef gerçekliğine acılar

Oysa...

Büyümek ağlayamamakmış

Gerildikçe şakakların 

Hüner gülebilmekmiş sırçaya

Kusamaz yutkunurken acıyla

Omzundaki yavan ele

El sürmekmiş dostça

Yalnızlığı hazmetmekmiş erin

Adem sofrasında konak

Tokalaşırken kadehle şarap

Can kırmadan bilmekmiş yerin

Büyümek anlamakmış

Kurusunda boğulurken gözlerin

Korku yaşla sönmezmiş

Sebatmış işin

20.02.06', 'Vakarlı nakşolmak yaşına Gergef gerçekliğine acılar Oysa... Büyümek ağlayamamakmış Gerildikçe şakakların  Hüner gülebilmekmiş sırçaya Kusama...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/korku-yasla-sonmezmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlama', 'taslama-i-brahim-ugur-toprak-n2qs8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Muhasır Medeniyetler seviyesinin üzerine

çıkaracağım deseler de inanma sakın.

Ve boşuna ortak bir nokta arama

80 yıl önceki zihniyetle

Şimdiki zihniyet arasında

Çünkü bulamayacaksın! ..

80 yıl önce milletin efendisiydi köylü

Bugün ise çok iyi bir artist kendisi

İki zihniyet arasındaki farkları da arama

Bulmakla bitiremezsin çünkü

Koca bir ömrü harcasan da...

Uyan artık yattığın şu derin uykudan

Silkelen ve kendine gel

At üzerinden şu ölü toprağını

Bakmayı birak 

Artık gör sana yapılanları

Farkına var yapılacak olanların

Seneler önce önünü ilikleyip önünde

Can kulağıyla dinlerken seni Cumhurbaşkanın

Bugün elini sokup gözünün ta içine

Sana ''lan'' diye hitap etmekte Başbakanın

Daha da vahim olanı

Yaşadığın şehre göre dinin değişmekte

Elhamdülillah Müslümanım derken

Bir bakmışsın gavur olup çıkmışsın

Farkında bile olmadan

Dedim ya

Kaldır kafanı bir bak

Neler olup bitiyor

Sen farkında bile olmadan

Bir an evvel görsen iyi olur

Yoksa,

Ananı da alıp yanına

Gitmek zorunda kalırsın bu diyardan

Neyse,

Anlayana sivrisinek saz demiş eskiler

Bir şarkıda da der ki:

''Bana kara diyen dilber

Gözlerin kara değil mi? ''

Bana gavur diyen Kasımpaşalı Başbakan

Sorarım, acep kendisi ne kadar Müslüman? 

Gene tutamadım işte şu dili

Naparsın

Dediği gibi üstad Ümit Yaşar''ın:

''Serde de kör olası şairlik var''

20.02.2006

İzmir', 'Muhasır Medeniyetler seviyesinin üzerine çıkaracağım deseler de inanma sakın. Ve boşuna ortak bir nokta arama 80 yıl önceki zihniyetle Şimdi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/taslama-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunun Anatomisi', 'yoklugunun-anatomisi-orbay-eken-btbni', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yokluğun

varlığına benzer

Kararsız bir akışkanlık 

nötrler bizi...

Birden kelimeler

tutuşur ağzımda

Merkezinde ben

dünyanın...

Kaybolup kaybolup

kalabalıklarda

bulduğum 

insanları 

koyarım yerlerine...

Sen beni koysanda

kendi yerine,

ben kendimi koyamıyorum

senin yerine...', 'Yokluğun varlığına benzer Kararsız bir akışkanlık  nötrler bizi... Birden kelimeler tutuşur ağzımda Merkezinde ben dünyanın... Kaybolup kayb...', ARRAY['Türk Edebiyatı','Şiir','Orbay Eken']::text[], 8.5, '{"poet":"Orbay Eken","poet_slug":"orbay-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yoklugunun-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Falcı Değil', 'falci-degil-sevinc-kavuk-4rhif', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep bir merhaba´dır ilk adım, arkadaşlığa

Konuşulur ordan burdan doğallığıdır hem bu

Öpüşülür yanaktan görüşmek üzere hakkıyla 

İnsanlık hali, düşer elbet bir iş´de bu arada

Sevgi akımıdır sürer gider derken bir gün

Anlamıştır sanıp ben söylemiştim hani de

Beklemek hakkım deyip, umdum diye de

Ekler durur eklemesine de ben şaşkınım

İyisin hoşsun da sorun nedir, dert neydi

Anlamakta zorlandığıma az baksana bari

Aç ağzını yum gözünü paraladın hoş da

Falcı değil o benim, arandığın öyle tuhaf ki 

Derdini dinlerim yüreğim sana geniş

İsteğini söylersen düşünerek aşılır

Küp değilim, bu dolduruş nahoş gidiş 

Ancak bir kaptan öbürüne boşaltılır

Eğer bir dert varsa susma konuş onu

Aklından geçtiyse de saklama şunu

Biraz ondan bundan kaçırdığın var ya

Dertlere çare olur hem hoşluk duyumu

Sohbet yarenliğidir acısıda olur hem balı da

Anlayana kadar katık da olur duygularımıza 

Sözünde bu aklım halindedir gözüm ancak da

Falcı değil o benim, nedir bu tutum, bu halin? 

29.02.2005', 'Hep bir merhaba´dır ilk adım, arkadaşlığa Konuşulur ordan burdan doğallığıdır hem bu Öpüşülür yanaktan görüşmek üzere hakkıyla  İnsanlık hal...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/falci-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ne Zaman Seni Yazsam', 'ben-ne-zaman-seni-yazsam-seval-kemertas-bi2av', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben ne zaman seni yazsam

eksilir ezilir

her kelime,her sözcük

deli otlar boy verir içimde

ışığım söner,

hüzün sızar yürek yırtıklarımdan...

ben ne zaman seni yazsam

içimde upuzun bir güz

kilidini kırar karanlığın

dalgaların koynunda boğulur yüzün

bir alev girdabında

menzili şaşmış mermiler ilişir düşlerime...

ben ne zaman seni yazsam

siyah perdeler çekilir gündüzlerime

mahkum uykularımda hep aynı rüya

bedenim,yüreğim deprem dalgası

tutulur bütün yollar

geceler kan tükürür ihanetine...

ben ne zaman seni yazsam

gecelere sığınan bir yurtsuz

bir yaprak kadar sahipsiz

ve bir ölü kadar dilsizim

bir yağan yağmur kalır gözlerimde

bir de yüreğimde zemheri..ayaz

21,02,2006    23,18', 'ben ne zaman seni yazsam eksilir ezilir her kelime,her sözcük deli otlar boy verir içimde ışığım söner, hüzün sızar yürek yırtıklarımdan... ...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-ne-zaman-seni-yazsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '6. Durak', '6-durak-cumhur-karahan-fg9sj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın içindeki karanlıkları yapıştırıyorum,

En can alıcı gündüzlerime…

Umutları çıkarıp torbamdan; 

Serpiştiriyorum bir tutam, yalnızlığıma

Bulunması imkansız son bir vilayet kaldı içimde

Hangi iklimin kirlenmiş haritası bu? 

Şehir ve ben şimdi başbaşayız

Bir fırtına uzanıyor yanıbaşımıza

Acı acı siliyorlar beni mısralarımdan

Tahta bir vapura atlayıp kaçmalı bu düşten

Hiç bir söz etmem söz, ayrılırken…

İçimdeki savaşlarımla çıkıyorum karşıma

Yeşil kalmayı becererek her yangında

Hangi şiirimin kırık yanları bu ciğerime saplanan? 

Seni aramayan kalmadı bu şiirde

Bütün şehirleri yıkıp gidiyorum, 6. durak dahil…

Sağ çıkmayı başarıyor bir yanın mutlaka

Beni bekliyor ayrılıklar bu durakata

İçimde son bir vilayet kaldı bulunması imkansız

Bir tek 6. durak kaldı aranmadık

M.C.K', 'Aşkın içindeki karanlıkları yapıştırıyorum, En can alıcı gündüzlerime… Umutları çıkarıp torbamdan;  Serpiştiriyorum bir tutam, yalnızlığıma ...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Karahan']::text[], 8.5, '{"poet":"Cumhur Karahan","poet_slug":"cumhur-karahan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/6-durak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonra', 'sonra-ufuk-bayraktar-w9yim', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sonra geceyi sessiz bir dost bildim

yanında huzur buldum.

kayan yıldızlar gibiydi

karanlıkta sigaram

ve yanan tütünün çıtırtısını duydum

ki o kadar sessizdi odam.', 'sonra geceyi sessiz bir dost bildim yanında huzur buldum. kayan yıldızlar gibiydi karanlıkta sigaram ve yanan tütünün çıtırtısını duydum ki ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sonra-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zıkkım', 'zikkim-mustafa-eren-5rxzv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ZIKKIM

Şimdi kurmalı bir çilingir sofrası.

Fıçılar dolusu zıkkım bulmalı.

Hortlatmalı cümlesini anıların,

Toplayıp etrafına,

Şerefe içmeli bu akşam...

  ******

Çocukluğum bir tabakta,

Öbüründe  gençliğimdeki yıllar.

Salatası   aşklarım bu sofranın.

İşte  mezesi hatıralar.

Haydı şerefe içelim bu akşam...

  ****

Yıllar sonra bu masada buluştuk,

O bıçkın delikanlı karşımda.

Sağ yanımda afacan çocukluğum.

Solumda binbir cefa dolu bir yaşam,

Haydı şerefe zıkkım içelim bu akşam...

   *****

                                     Mustafa Eren

                  DiDiM       21 şubat 200', 'ZIKKIM Şimdi kurmalı bir çilingir sofrası. Fıçılar dolusu zıkkım bulmalı. Hortlatmalı cümlesini anıların, Toplayıp etrafına, Şerefe içmeli b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Eren']::text[], 8.5, '{"poet":"Mustafa Eren","poet_slug":"mustafa-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zikkim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim Ben', 'ogretmenim-ben-nedret-celen-ym4v5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde yıldızlarla yarışan

Yeryüzünde cehaletle savaşan

Yalçın kayalıklardan yol açıp

Körpecik dimağlara ulaşan

Onlarla gülen,onlarla ağlayan

Öğretmenim ben

Aşılmayan yüce dağlarda

Uçsuz bucaksız ovalarda

Kır çiçekleri derleyen

Gonca güllere şekil veren

Sevgiyi ilmek ilmek işleyen

Öğretmenim ben

Toz,toprak ve çamurdan

Üstüme yıkılacak gibi köhne damdan

Batıp çıktığım diz boyu kardan

Yılmayan

Umudu yalnızca gelecek olan

Öğretmenim ben

Mahrum kalsam da

Kara tahtadan,sıradan

Olmasın varsın sandalyem masam

Yine de imar edeceğim varlık var:

insan

Sıcacık bakışlardan azmini alan

Bir güzel sözcükle mutlu olan

Öğretmenim ben

Edirne, Ardahan,Van''da

Yurdumun her bucağında

Yanan bir meşale olmaktan

Duyduğum gurur

Emanetini aldığım Atam''dan

Öğretmenim ben', 'Gökyüzünde yıldızlarla yarışan Yeryüzünde cehaletle savaşan Yalçın kayalıklardan yol açıp Körpecik dimağlara ulaşan Onlarla gülen,onlarla ağ...', ARRAY['Türk Edebiyatı','Şiir','Nedret Çelen']::text[], 8.5, '{"poet":"Nedret Çelen","poet_slug":"nedret-celen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ogretmenim-ben-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokum', 'yokum-naciye-bildim-j2fd8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben yokum artık bundan sonra

Ve bundan sonra herşeye pes.

Sevildim sevilmedim,

Yenildim yoruldum.

Yok yok...Bundan sonra sevmek mi

Valla tövbeler olsun..', 'Ben yokum artık bundan sonra Ve bundan sonra herşeye pes. Sevildim sevilmedim, Yenildim yoruldum. Yok yok...Bundan sonra sevmek mi Valla töv...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yokum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-naciye-bildim-3eoce', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya bir çalar saat,

Sağ adım akrep,sol adım yelkovan.

Yada sol adım akrep,sağ adım yelkovan,

her ne olursa olsun,biri önde gider.

Her saat dönümünde çalar saat

Gözyaşlarıyla bir kuş çıkar haykırır,

İçindeki isyanını anlatır.

Gün gelir,büyüsü bozulur,

Fersiz kalan gözler yorulur.,

Kuş çıkmaz yuvasından

Yelkovan ve akrep,

Hep aynı sayıyı gösterir durur.

Çarklar arasındaki insan,

Sessiz ve sakin sonsuza dek uyur...', 'Dünya bir çalar saat, Sağ adım akrep,sol adım yelkovan. Yada sol adım akrep,sağ adım yelkovan, her ne olursa olsun,biri önde gider. Her saat...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dunya-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Oluyor', 'neler-oluyor-tahmine-yildirim-rvuct', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçim burkuluyor 

Yüreğim yanıyor

Beynim sancıyor

Bana neler oluyor

Ateşim var sanki

Bacaklarım tutmuyor

Kollarımsa isyanda 

Bana neler oluyor

Hayallerim ölüyor

Güvenim sarsılıyor

Sevincim yıkılıyor

Bana neler oluyor

Tanıyamıyorum kendimi

Korku sarıyor tüm bedenimi

Yitiriyormuyum kendimi 

Bana neler oluyor.                                             MAYIS:2001', 'İçim burkuluyor  Yüreğim yanıyor Beynim sancıyor Bana neler oluyor Ateşim var sanki Bacaklarım tutmuyor Kollarımsa isyanda  Bana neler oluyo...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neler-oluyor-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Geçirme', 'vakit-gecirme-naciye-bildim-axfkl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece o tatlı uykundan uyanıp,

Bir tek sigaranın dumanıyla boğulursan.

İçinde geç kalmışlığın azabı,

Yüzünde geçen yılların izi.

Yanaklarında salıvermişsen,

İzinli izinsiz gözyaşlarını

İşte o an yanında ben olmayacağım...

Akında ben,fikrinde bensem

Ne olur sil beni,sök at

hemde hiç vakit geçirmeden.

               13.10.1995', 'Bir gece o tatlı uykundan uyanıp, Bir tek sigaranın dumanıyla boğulursan. İçinde geç kalmışlığın azabı, Yüzünde geçen yılların izi. Yanaklar...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vakit-gecirme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-naciye-bildim-taqc0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi çok kolay gelir insana,

Unutmak benziyor sahte oyuna.

Gelmeye gör,bu iş başına

Elveda dedirtir tüm yaşantına.', 'Şimdi çok kolay gelir insana, Unutmak benziyor sahte oyuna. Gelmeye gör,bu iş başına Elveda dedirtir tüm yaşantına....', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unutmak-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Patalojik Kumarbaz', 'patalojik-kumarbaz-gultekin-toga-1efpf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akıl dumura uğradı

                        İrademe inme indi,

                        Nefsin hızarı doğradı

                        Her sefer de beni yendi.

                        Belli değil kışım,yazım,

                        O ekmeğim,aşım,tuzum

                        İflah olmaz kumarbazım,

                        Ta...İliklerime sindi.

                        Param yoksa borç alırım

                        Aldatır, haraç alırım,

                        Gerekirse aç kalırım,

                        Kumarsız hep başım döndü

                        Yolunda her şey mübahtir,

                         Kul olmuşum, o bir şahtır,

                         Benim bu halim bir ahtır,

                         Bilmem içimde ne söndü

  

                         O kelepçe,ben mahkumum,

                         Söndü ışıkk,söndü mumum

                         İçler acısı durumum,

                         Ümüdime baykuş kondu.

                         Bir ikilem yaşıyorum,

                         Serseri dolaşıyorum,

                         Her şartta ulaşıyorum

                         Hayatın merkezi kendi

                    

                         Sillindi eş,çoluk çocuk,

                         Halim belli açık seçik,

                         Kalbim tutsak ruhum göçük,

                         Sanki dağ sırtıma bindi..

                         Bıktım yalancı gezmekten

                         Sevenlerimi üzmekten,

                         Bu labirentte yüzmekten

                         Yüzümün nuru silindi..

                   

                         Yaradanım gören sensin,

                         Alan sensin veren sensin,

                         Yüreğimden tövbe gelsin,

                         Desin dilim şeytan yandı..

                     

                        Sentezi der silkin,doğrul,

                        Maneviyat ile yoğrul,

                        Yaradana kul olup kul,

                        Şeytanına kur nur bendi...', 'Akıl dumura uğradı                         İrademe inme indi,                         Nefsin hızarı doğradı                         Her sefe...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/patalojik-kumarbaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* GeCe; ZaMaNDıR SaDeCe *', 'gece-zamandir-sadece-mine-ozdemirtas-sus5u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biliyorum

sana göre gece; 

zamandır sadece

bana gelince; 

artık 

bütün zamanlar gece.

sararmış bir sayfa gibi

kenarlarım

bükülüyor  içime.

tüm çareleri 

çaresiz

kurban veriyorum çarelere

bilsem ki

delilik ilaç olacak yarelere

soyunur 

tırmanırdım minarelere

ama 

yarın kimseye vadedilmedi

mutluluk 

boyumuz kadar

ne uzar göklere

ne düşer yerlere

ancak

hak ettiğim kadar yaşar yüreğim

ve ancak

hak ettiğim kadar sevda yüklenir kelimelere

fazlasını beklemek 

ne haddime

biliyorum bir tanem

senin için gece; 

zamandır sadece

beni dert etme

benim için

artık

bütün zamanlar gece

22/02/2006', 'biliyorum sana göre gece;  zamandır sadece bana gelince;  artık  bütün zamanlar gece. sararmış bir sayfa gibi kenarlarım bükülüyor  içime. t...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gece-zamandir-sadece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret kuşları..', 'hasret-kuslari-birol-i-scan-hcbcj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahtan uçurdum hasret kuşlarını

Kanatları pek ağırdır epeyce uzun  yolları.

Kuş bakışı sevdalar yükledim kanatlarına

İnciler zeytin dalları menekşeler güller.

Hüzünlü  Bir masaldan kalma camdan ayakkabıları.

Gün daha doğmamışken tan yeri kızarmadan 

Çiğ damlaları arzuluyken gül yapraklarına

Muratlarına ermemişken üstelik,yani

Herkes uykudayken sessizken ortalık

Tamda sabah ezanları okunurken.

Sabahtan uçurdum hasret kuşlarını

Kanatları pek ağırdır epeyce uzun yolları..', 'Sabahtan uçurdum hasret kuşlarını Kanatları pek ağırdır epeyce uzun  yolları. Kuş bakışı sevdalar yükledim kanatlarına İnciler zeytin dallar...', ARRAY['Türk Edebiyatı','Şiir','Birol İşcan']::text[], 8.5, '{"poet":"Birol İşcan","poet_slug":"birol-i-scan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Eserin', 'senin-eserin-yurdagul-ozay-y29zj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gideceğini bilseydim 

Bir gün böyle uzaklara

Kilitlerdim bu kalbimi

Düşmezdim kara sevdaya

Ne vefanın adı kalmış

Ne sevdanın tadı kalmış

Aşka tutsak o yeminler

Demek  ki  hep bir yalanmış

Nasıl diner şimdi yaram

Bozuldu  felekle aram

 Gece gündüz hesap sorar

Mazideki her hatıram

Bu sevdaya ömür verdim

Sendin benim bütün derdim

Görmezdi gözler dünyayı

Öyle yandım öyle sevdim', 'Gideceğini bilseydim  Bir gün böyle uzaklara Kilitlerdim bu kalbimi Düşmezdim kara sevdaya Ne vefanın adı kalmış Ne sevdanın tadı kalmış Aşk...', ARRAY['Türk Edebiyatı','Şiir','Yurdagül Özay']::text[], 8.5, '{"poet":"Yurdagül Özay","poet_slug":"yurdagul-ozay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-eserin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Gördüğümüz Gerçekler', 'gec-gordugumuz-gercekler-hayrettin-turk-udhig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyüdükçe insanlar

Hayalleri küçülür,

Bir gülümsemeyle yetiniriz gün gelir

Gün gelir onu da bulamayız…

Doyamadığımız anlara ah eder

Avucumuzda iken okşamadıklarımıza yanarız

Hayallerle yetinir

Yok olmak ister

Olamayız…

Doruk yapar duygularımız

Zirveden uzaklaştıkça biz

Yumuşarız önce

Musallanın sıcak suyuna hazırlanır gibi

Ağlamayı öğreniriz

Eteklerimizde hayalde kalmış hayaller,

Geç gördüğümüz gerçeklerimizle

Kuytularda gözyaşlarımızı

Saklamayı öğreniriz...

21.02.2006', 'Büyüdükçe insanlar Hayalleri küçülür, Bir gülümsemeyle yetiniriz gün gelir Gün gelir onu da bulamayız… Doyamadığımız anlara ah eder Avucumuz...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gec-gordugumuz-gercekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim birgün', 'gelirim-birgun-hanifi-isikoglu-lrcxe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gelmedim diye darılıp küsme

umutlarım el vermez gelmek isterdim

arayıp sormuyom diye sakın gücenme

yaban elde askerim gelirim birgün

bekle beni unutma sakın

beni düşünüpte aglama 

sayılı gün çabuk geçer

askerim gelirim birgün

nöbette hep seni düşünür

burda hep seni anarım

seni hep gecelerden sorarım

yaban elde askerim gelirim birgün', 'gelmedim diye darılıp küsme umutlarım el vermez gelmek isterdim arayıp sormuyom diye sakın gücenme yaban elde askerim gelirim birgün bekle b...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelirim-birgun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorum işte', 'yasiyorum-iste-hanifi-isikoglu-e256o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşamak zor olsada

kaderim böyle yaşıyorum

her günüm kederle geçse

bende sizler gibi yaşıyorum işte

sevdim hiç sevilmedim

herkesten binbir darbe yedim

hayatım böyle geçti benim

bende sizler gibi yaşıyorum işte

benim için zor olsada 

kaderim böyle yaşıyorum

herkes beni kötü bilse

bende sizler gibi yaşıyorum işte

ha öyle ha böyle yaşıyorum işte

dertli kederli olsam bile

bazen neşelenip gülüyorum işte

bende sizler gibi yaşıyorum işte', 'yaşamak zor olsada kaderim böyle yaşıyorum her günüm kederle geçse bende sizler gibi yaşıyorum işte sevdim hiç sevilmedim herkesten binbir d...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Isikoglu']::text[], 8.5, '{"poet":"Hanifi Isikoglu","poet_slug":"hanifi-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasiyorum-iste-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Dikeni', 'ates-dikeni-guzin-eye-dundar-8l8by', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kuşlar bile yuvalanmadı

dallarına

dikenlerinde kurudu gözyaşım

yağmur sonrası

şaşkın telaşım

kelebek rüzgarı fırtınalar

yarım kaldı

şarkılar

hüzzam ağlıyor

sol yanımda

al...çözülmüş mavi uykular sana

demek ki ya hep ya hiç 

ortası olmadı hayatın

işte...!  mevsim sonbahar

bir çiy damlası

çalar zamanı

gözlerim kanar', 'kuşlar bile yuvalanmadı dallarına dikenlerinde kurudu gözyaşım yağmur sonrası şaşkın telaşım kelebek rüzgarı fırtınalar yarım kaldı şarkılar...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ates-dikeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlikte', 'sensizlikte-birsen-ates-uykri', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'anlatamam 

kopan bir fırtınanın

darmadağın bıraktıklarını

çaresiz bir gecede 

feryat figan çığlıklarımı

aklıma takılı hala giderken

üşümüş bakışların

rüzgar ektim fırtına biçtim

şimdi savrulmaktayım

sensizlikte

22.02.06', 'anlatamam  kopan bir fırtınanın darmadağın bıraktıklarını çaresiz bir gecede  feryat figan çığlıklarımı aklıma takılı hala giderken üşümüş b...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizlikte-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şansım Var mı?', 'sansim-var-mi-sevinc-kavuk-bkin6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana alışabilecek misin

Ve seni özledim diye bir de söylenirken

Şansım var mı sevdiğim

Bazen duygularımın bir an bu önceliğine 

Yöneldiğimde yanımdayken seni

Özledim deyişimi de anlatabilmeye? 

Sen bazen konuştuğunda da yine

Sadece o sözüne yöneldiğim anlar

Senin halini ama sonradan ancak

Algılayabildiğimi anlatabilmeme

Şansım var mı bir tanem

Seni seninle özlemlerle bir yaşama? 

Bir tek dileğim var sadece

Bana alışabilmelisin! 

Şansım var mı buna? 

22.02.2006

Çarşamba 01.10', 'Bana alışabilecek misin Ve seni özledim diye bir de söylenirken Şansım var mı sevdiğim Bazen duygularımın bir an bu önceliğine  Yöneldiğimde...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sansim-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ne Zaman Gulecegim Yarenler 1997', 'ben-ne-zaman-gulecegim-yarenler-1997-yasar-gurlek-oi9gn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olgun  armut  gibi  dussem  patlarim

Dertlerimin  ustune  nice  dertler  katarim

O vefasiz  yara  kin  nefret  yas  tutarim

Ben  ne  zaman  gulecegim  bilenler

Niye  boyle  cizilmis  si  benim  yazim

Benim  dertlerime  ortaktir  sazim

Gun  gectikce  artar  bagrimda  sizim

Ben  ne  zaman  gulecegim  bilenler

Sabir tasi  olsam catlardim  coktan

Yaniyorum  arkadas  boyle  hic  yoktan

Vefa  gorecekmiyim  bir  gun  o  dostan

Ben  ne  zaman  gulecegim  bilenler

Daglamislar  gibi  bagrim  yaniyor

Sargi  tutmaz  yaralarim  kaniyor

Gonul  her  guzelde bal  var  saniyor

Ben  ne  zaman  gulecegim  bilenler

Bu  kara  yazimla  bende cok  gezdim

Usandim  kendimden  canimdam  bezdim

Vura  vura  bagrima  cigerim  ezdim

Ben  ne  zaman  gulecegim  bilenler

Ozan  yasar  akiyor yaslar  damla  damla

Gezerim  bu  alemi  dert  ile   gamla

Sevemem  baska  yar  sevemem  asla

Ben  ne  zaman  gulecegim  yarenler

Yasar  Gurlek

HOLLANDA

Roterdam  18-06-1997', 'Olgun  armut  gibi  dussem  patlarim Dertlerimin  ustune  nice  dertler  katarim O vefasiz  yara  kin  nefret  yas  tutarim Ben  ne  zaman  ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ben-ne-zaman-gulecegim-yarenler-1997-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bittim yeter 1997', 'bittim-yeter-1997-yasar-gurlek-3six5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bulbul  gul  dalinda  oter

Yaktin  beni  yaktin  yeter

Yaza  gelmen  guze  gelmen

Tukenip  bak  bittim  yeter

Aglarim  halim  bilmen

Akar goz yasim  silmen

Ipe  gelmen  sapa  gelmen

Eridim  bak  bittim  yeter

Gunde  bin  sefer  olurem

Bir  gel  desen  gelirem

Birak  gayri  gulun  derem

Oldum  bak  bittim  yeter

Gozu  yasli  yatiyorum

Derde  dertler  katiyorum

Senmsiz  nasil  yasiyorum

Bittim  bak  bittim  yeter

Care  olmaz  derdem   tabib

Boynuma  takacam  bir  ip

Dertler  bende cokcada  dip

Tasiyamam bittim  yeter

Kara  sevdamiyim  neyim

Asik  yasar  benim   beyim

Ben  yarime  daha ne  deyim

Bitsin  artik  bitsin  yeter

Yasar  Gurlek

HOLLANDA

Roterdam  13-06-1997', 'Bulbul  gul  dalinda  oter Yaktin  beni  yaktin  yeter Yaza  gelmen  guze  gelmen Tukenip  bak  bittim  yeter Aglarim  halim  bilmen Akar go...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bittim-yeter-1997-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar elinden 1997', 'yar-elinden-1997-yasar-gurlek-874gw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben  yanlizim yaraliyim

O vefasiz  yar  elinden

Ben  ne  bahti  karaliyim

O  hayirsiz  yar  elinden 

Yatilmazki  yarsiz  cansiz

Zaman  gecmez  sozsuz  sazsiz

Hayat  bana  oldu  tatsiz

O  vijdansiz  yar  elinden

Nasil  girdin  sen  dunyama

Agliyorum  yana  yana

Olmusum  bir  divana

O insafsiz yar  elinden

Uyku  tutmaz  beni  gece

Ismin  dillerimde  hece

Bak  hallerim  oldu  nice

O sefasiz  yar  elinden

Yasar  derki  nolur  halim

Kiriktir  kolum  dalim

Zehir  olur  bana  balim

O cefasiz  yar  elinden

Gulde  bulbul  otusuyor

El  yariyle koklasiyor

Yasar  yanliz  bak  yaniyor

O sefasiz  yar  yuzunden

Yasar  Gurlek

HOLLANDA

Roterdam  03-06-1997', 'Ben  yanlizim yaraliyim O vefasiz  yar  elinden Ben  ne  bahti  karaliyim O  hayirsiz  yar  elinden  Yatilmazki  yarsiz  cansiz Zaman  gecme...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yar-elinden-1997-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haymana kaplica yollari 1997', 'haymana-kaplica-yollari-1997-yasar-gurlek-iwc70', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaplicanin  yollarinda

Akasya  var  dallarinda

Mevla  canimi  alsin

Guzelin  kollarinda

Kaplicada  islandim

Mermerlere  yaslandim

Hani ben bir  aslandim

Oleydim  kollarinda

Suya  girdim  yuzmeye

Yare  mani  dizmeye

Doyulurmu  gezmeye

Sevdigim  kolarinda

Kaplicam  bas  asagi

Oldum  yarin  usagi

Unutamam  kusagi

Oleydim  kollarinda

Dustum  baglar  yoluna

Sallar  takmis  koluna

Zalim karsidan   gelir

Salinada  salina

Yuru  haymanalim

Yuru  edalim

Ben  daha  olmedim

Sana  kurbanim

Yasar  Gurlek

HOLLANDA

Roterdam  09-06-1997', 'Kaplicanin  yollarinda Akasya  var  dallarinda Mevla  canimi  alsin Guzelin  kollarinda Kaplicada  islandim Mermerlere  yaslandim Hani ben b...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/haymana-kaplica-yollari-1997-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Geri Gelirmi 1996', 'giden-geri-gelirmi-1996-yasar-gurlek-f7ppz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Felek  tuta tuta  senimi  tutu

Acimadan  seni  gurbete atti

Gavur  parasina bak  seni  satti

Gitme  dost  giden  geri  gelirmi

Zuluflerin  sari  dokmusun  yuze

Goren masallah  desin  gelme  sen  goze

Doyulurmu  dunyada tatli  bir soze

Gitme  canan  giden  geri gelirmi

Ne  kadar dert varsa  biner  omzuma

Tas  cali  diken  cikar benim  yoluma

Dost  bildiklerimde biner    dalima

Gitme  dost  giden  geri  gelirmi

Binilen  dal  kirilmazmi

Tassiz dikensiz  yol  olmazmi

Sirtimdan  dert  inmezmi

Gitme  canan  giden  geri gelirmi

Yasar  Gurlek

HOLLANDA

Roterdam  24-02-1996', 'Felek  tuta tuta  senimi  tutu Acimadan  seni  gurbete atti Gavur  parasina bak  seni  satti Gitme  dost  giden  geri  gelirmi Zuluflerin  s...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/giden-geri-gelirmi-1996-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Banamidir ceza evi cotbus almanya 1998', 'banamidir-ceza-evi-cotbus-almanya-1998-yasar-gurlek-pch0v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Banamidir  banamidir  kara  yazilar  banamidir

Benim kime  ne zararim  var  felek  ahtin  banamidir

Ne  anadan  gulmus  idim  nede  babadan

Banamidir  banamidir  felek  kastin  banamidir

Hep  agladim  ben  benimle

Gulemedim  hic   seninle

Kendimi  yaktim    elimle

Felek  kahrin  banamidir

Goz  yaslarim  akar  kalbe

Nerdesin  ey  dostum gelbe

Felek yeter   artik   gulbe

Felek  ahdin banamidir

Kara  kara  gunler hep  bana doguyor

Insan boyle  yasamaktan  soguyor

Hapishanede insan olu gibi  oluyor

Banamidir  banamidir  felek  kastin  banamidir

Aklimi  bastan  alan  aldi

Beni  hapislere  saldi

Gozlerim  yollarda kaldi

Felek  zulmun  banamidir

Yasar  Gurlek

ALMANYA

Cottbus   04-03-1998', 'Banamidir  banamidir  kara  yazilar  banamidir Benim kime  ne zararim  var  felek  ahtin  banamidir Ne  anadan  gulmus  idim  nede  babadan ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/banamidir-ceza-evi-cotbus-almanya-1998-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözde DOGRUCU Davut', 'sozde-dogrucu-davut-gultekin-toga-kdmkm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğrucu Davutmuş adam birader.

En küçük hatani yüzüne vurur.

Kendisini sorsan Ulu hira der,

Gönül kırmasını hazine görür..

Ancak o kadardır egoist, obur,

Yedi zincir kırar yanin da sabır,

Kör etmiş gözünü kara bir kibir,

Çökmüş, bağdaş kurmuş,özüne gurur..

Sözü kazma gibi çakılır,eşer,

Mahcup etmek için zorlayıp deşer,

Zayıf tarafının peşine düşer,

Refize etmenin izine yürür..

Kabus etmek ister rüyalarını

Bırak gerçek çekmez hülyalarını

Dili kürek olur salyalarını

Ayna eylediğin sözüne kürür,

Sentezi uzak kaç  böylelerinden,

Semtine yaklaşma korun,kirinden,

Düşman uzak olsun onun şerrinden,

Dost diye çaldığın sazına ürür', 'Doğrucu Davutmuş adam birader. En küçük hatani yüzüne vurur. Kendisini sorsan Ulu hira der, Gönül kırmasını hazine görür.. Ancak o kadardır ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sozde-dogrucu-davut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soguktan 1998', 'soguktan-1998-yasar-gurlek-pzgjb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim  yarali  bagrim

Yine  yara  aldi bugun

Gozlerimden  yaslar  akar

Agliyorum her  an  her  gun

Sucsuz  yere  mapuslarda

Yatar  gezer  sizlarim  ben

Ne  istedinki  benden

Yakip  gittin beni  sen

Sen  usudunmu   benim  gibi

Tas  duvarlar  arasinda

Demirden  kapilar

Celikten  tel  orguler

Sen  ne  bilirsin

Yanlizligi  sen  ne  bilirsin

Sessizligi

Sevda  bahcemde  acan  guller  bile  soldu

Soguktan  ayriliktan yanlizliktan,

Ayriliktan   mapusluktan,

Hayatimin   en  zor  gunleri,

Bu dort  duvar  arasinda

Demirden  kapilar hep  yuzume  kapali,

Hep  yanlizlik,hep sensiz,

Yasar  Gurlek

ALMANYA

Cottbus   02-03-1998', 'Benim  yarali  bagrim Yine  yara  aldi bugun Gozlerimden  yaslar  akar Agliyorum her  an  her  gun Sucsuz  yere  mapuslarda Yatar  gezer  si...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/soguktan-1998-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaos', 'kaos-gultekin-toga-1jp98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yol ateşe gider

Yanmaya mı susadın? 

Dalı keserken hızar

Binmeye mi susadın? 

Kaos gizemli duyu,

Kör düğüm etmek huyu

Ömrüne kazıp kuyu,

İnmeye mi susadın? 

İhtirasla ateşe

Yel gibi koşa koşa,

Bu çıkmazda boş boşa,

Dönmeye mi susadın? 

Eşek çukura düşse,

Bir daha geçmez ölse,

Çelik kazıklı örse,

Konmaya mı susadın? 

Hani bebekler varya,

Ateş ile oynarya

Yirmi yaşından orya

Dönmeye mi susadın..

Sağ duyuyu mühürle,

Kaosu hortlat hürle

Suya küsüp zehirle

Kanmaya mı susadın? 

Darılıp hizmet ile,

Aran yok zahmet ile,

Şeytanı rahmet ile,

Anmaya mı susadın..

Anla çok geç olmadan,

Değerin hiç olmadan,

Feleği güç olmadan,

Yenmeye mi susadın? 

Sentezi´yi yakma bak,

Zaten göçük yıkma bak,

Varken sevmek, yaşamak,

Sönmeye mi susadın?', 'Bu yol ateşe gider Yanmaya mı susadın?  Dalı keserken hızar Binmeye mi susadın?  Kaos gizemli duyu, Kör düğüm etmek huyu Ömrüne kazıp kuyu, ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kaos-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakmaz Adam', 'birakmaz-adam-gultekin-toga-rkw6f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıfırmış özünde ne yapsın adam? 

Eline bir koltuk geçti bırakmaz..

Ayakları yerden kesildi ki tam,

Sanki kuş oldu da uçtu birakmaz..

Artık etiketi,fiyakasi var,

Sorana,görene bir cakası var,

Nasıl sevinmesin plakası var,

Daha yukarıyı seçti bırakmaz..

Kendini götürür zirveye koyar,

Yapmacık maskeler yüzünü boyar,

Onu sivriltenin gözünü oyar,

Kimliği ortaya saçtı bırakmaz..

Kendi egosunu tatmin yolun da,

Halka hizmet lafı yalnız dilin de,

Dağları yaratmış sanki ilin de,

Herşeye bir kılıf biçti bırakmaz..

Sentezi Eşekte altın semer var,

Ama gene eşek post neye yarar,

Çukur ZirveleŞse nereye kadar,? 

Kendi gerçeğinden kaçtı bırakmaz..', 'Sıfırmış özünde ne yapsın adam?  Eline bir koltuk geçti bırakmaz.. Ayakları yerden kesildi ki tam, Sanki kuş oldu da uçtu birakmaz.. Artık e...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birakmaz-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ciban Basi 1997', 'ciban-basi-1997-yasar-gurlek-di676', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda  diye yandi  kalbim

Eriyipte  tukendim

Sevda  nedir  bilmez  iken

Onuda  senden  ogrendim

Yasar  yanar  yandi  yeter

Yaralarim  oldu beter

Doktor  nester  aldi  keser

Bendeki  bu  yaralari

Ciban  basi   ciban  basi

Sen  oldun yar  ciban  basi

Hani  mene  dermandin  sen

Her  zorluga  gurmendin  sen

Tabib  nester  elde   keser

Hani  derde  dermandin  sen

Ciban  basi   ciban  basi

Sen  oldun yar  ciban  basi

Hep guler  hic  aglamazdim

Dinmez  oldu gozum  yasi

Yasarimiz  yasarimiz  boynu  bukuk  ozanimiz

Bir  yar  sevdik  eller gibi  bozuldu  bak  duzenimiz

Ciban  basi  sen  olursan duzelmezki duzenimiz

Elim  kolum tutmaz  oldu kalmadiki  yazanimiz

Yasar  Gurlek

HOLLANDA

Roterdam  20-04-1997', 'Sevda  diye yandi  kalbim Eriyipte  tukendim Sevda  nedir  bilmez  iken Onuda  senden  ogrendim Yasar  yanar  yandi  yeter Yaralarim  oldu b...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ciban-basi-1997-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyamadim 1997', 'doyamadim-1997-yasar-gurlek-ja0kh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kara  kasa  kara  goze

Yar dilinden  bir  cift  soze

Bakmayla doymadim  yuze

Sevdigime  doyamadim

Zuluflerin  perdelenmis

O dillerin sekerlenmis

Yanaklarin gullenmis

Cananima  doyamadim

Salinir  yuruyusu  guzel

Bagrim yanar  erir  ezel

Gel  yarama  melhem  tez  el

Guzelime  doyamadim

Yasar  Gurlek

HOLLANDA

Roterdam  05-06-1997', 'Kara  kasa  kara  goze Yar dilinden  bir  cift  soze Bakmayla doymadim  yuze Sevdigime  doyamadim Zuluflerin  perdelenmis O dillerin sekerle...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/doyamadim-1997-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Yaratmis 1997', 'neler-yaratmis-1997-yasar-gurlek-25zek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zalim  olma  insan  oglu

Bak  allah  neler  yaratmis

Ornek  al  iyi  kulu

Gor  allah  neler  yaratmis

Kimi  calar  kimi  yakar

Cehenneme  kendi kosar

Akil  fikir  nasil  sasar

Bak  allah  neler  yaratmis

Dogru  yolun  basini  bul

Allah icin iyi  kul  ol

Ne  olursan  ol  yine  gel

Gor  allah  neler  yaratmis

Koca  koca  daglar  durur

Gunes  sana  isik  verir

Yer  gok  semaya  durur

Bak  allah  neler  yaratmis

Yasari,yim  yazdim  hakka

Nasip eyle  bana  takva

Ruyamda  gorunur  mekke

Gor  allah  neler  yaratmis

Varipta  kabeyi  gorsem

Topragina  yuzum  sursem

Haci  olup bende  donsem

Bak  allah  neler yaratmis

Yasar  Gurlek

HOLLANDA

Roterdam  19-05-1997', 'Zalim  olma  insan  oglu Bak  allah  neler  yaratmis Ornek  al  iyi  kulu Gor  allah  neler  yaratmis Kimi  calar  kimi  yakar Cehenneme  ke...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/neler-yaratmis-1997-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben gönlünde yoksam', 'ben-gonlunde-yoksam-mikdat-bal-z6dx0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben gönlünde yoksam eğer, arama

Bulamazsın semalarda değilim

Aradığın et kemikten yâr ama

Bulamazsın yıldızlarda değilim

Gönlüne sor sorma artık nerdeyim

Ne yıldızda ne gökte ne yerdeyim

Gönlünü aç sorma hangi derdeyim

Göremezsin bulutlarda değilim

Harap etti seni hayal düşlerin

Bu dünyada ağlamak mı işlerin

Ağlayarak yağmur oldu yaşların

Buharlarda yağmurlarda değilim

Düşünerek yorma gülüm kafanı

Seviyorsun biliyorum vefanı

Kimse bilmez sefanı ya çefanı

Şafaklarda ufuklarda değilim

Mikdatîyim gönüldedir yerimiz

Bunu bilsin ikimizden birimiz

Böyle kalsın ebediyen sırrımız

Uzayda da fezada da değilim', 'Ben gönlünde yoksam eğer, arama Bulamazsın semalarda değilim Aradığın et kemikten yâr ama Bulamazsın yıldızlarda değilim Gönlüne sor sorma a...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-gonlunde-yoksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makaracı', 'makaraci-gultekin-toga-c2qve', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tiksindi bu şehir senden,

Ne ilçe ne köyün kaldı,

Yılandaki zehir senden,

Ne emmi ne dayın kaldı..

Dokun uymaz bu diyara,

Kendine başka yer ara,

Çevirdin türlü makara,

Oynadığın oyun kaldı..

Hani tatlıydın,şirindin 

Bir masum poza büründün

Çakalken kuzu göründün,

Çalılarda tüyün kaldı..

İyi niyet taşıyanı,

Bulup oldun kaşıyanı,

Okladın çok yaşıyanı,

Kan fışkırtan yayın kaldı.

Bu kaçıncı yalan dolan,

Tez zamanda gelsin belan.

Nice garibana ulan,

Kazdığın çok kuyun kaldı..

Kanuna gecirmiş çember

Ya defol git ya da geber

Isıttı herkes beraber,

Son dökümlük suyun kaldı..

İylik sana göre degil

Sıkış bir köşeye yığıl

Kötülüklerinle boğul

Ne ada ne kıyın kaldı,

Sentezi cok ikaz etti,

Yoldu herkesi kaz etti,

Davul delindi, saz bitti,

Ne şölen ne toyun kaldı..

                                   

.

.', 'Tiksindi bu şehir senden, Ne ilçe ne köyün kaldı, Yılandaki zehir senden, Ne emmi ne dayın kaldı.. Dokun uymaz bu diyara, Kendine başka yer ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/makaraci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aczine Düştüm Sevdanın', 'aczine-dustum-sevdanin-muhacir-muhammed-dg3d0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalemim var, ama ben,

Yazamam aşkını,

Ne yere, ne de göğe.

Aczine düştüm sevdanın.

Sen sevdahane,

Ben kapında köle.

Aczine düştüm sevdanın,

Aşk iklimim; karanlık ve sensiz.

Vuslat sularında,

Umut yelkenim, rüzgarından mahrum…

Aczine düştüm sevdanın,

Yoksa neyime seni anlatmak.

Her harf beni anlatır aslında.

Beni bana anlatır usulca.

Bana seni anlatır.

Bu aşkın hicranı,

Bir beni, bir de harfleri yandırır.

Alevler seni yazmıyorsa gök bulutlarına,

Gönül buhurdanlığımda gözyaşı yanmıyorsa,

Ruhumun göklerinde güneş,

Bana nispet yanmıyorsa, 

Söz dizmek neye yarar.

Yazılan şiirler,

Kavrulan gönüller,

Ümmeti yıkayan gözler,

Seni bize getirmiyorsa neyler? 

Neyler Sevgili, ne eyler? 

Gelmiştin bir zamanlar,

Gelişinle söndürüp ateş-i mecusiyi,

Yakmıştın Ümmet’inin gönlünde; AŞK_I MUHAMMEDİ’yi

Aydınlanmıştı çağlar…

Şimdi küllendi bu ateş,

Aşkın gönül hicreti bitti.

Bizde bittik! 

Ama sen bitirmezsin.

Sen başlarsın…

Gel ve yakin bir fethe başla…

Biz gönül şehirlerimizin kapılarını ardına kadar açtık,

Elimizde şehrin anahtarları,

Seni bekliyoruz.

Sen küheylan koştur,

Ayağını bastığın çöller yeşersin.

Biz seni bekliyoruz,

GÖNÜL SEFERİN MUBAREK OLSUN EY RASUL! ! ! !', 'Kalemim var, ama ben, Yazamam aşkını, Ne yere, ne de göğe. Aczine düştüm sevdanın. Sen sevdahane, Ben kapında köle. Aczine düştüm sevdanın, ...', ARRAY['Türk Edebiyatı','Şiir','Muhacir Muhammed']::text[], 8.5, '{"poet":"Muhacir Muhammed","poet_slug":"muhacir-muhammed","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/aczine-dustum-sevdanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asilik Ve Asillik', 'asilik-ve-asillik-muhacir-muhammed-1fav6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldırımlar ateş pahasıydı,

Kelimeler yetmiyordu susuzluklara,

Ve insan bir nefes çekti özüne...

Yani çekmeliydi aslında...

Ve bir Ebuzerr bildi kendini,

Çünkü bilirdi ki; asillik, asilikdeydi.

Mücadele mi, mücahede mi diye durdu okyanus; 

Ve cevap o kadar uzun sürdü ki, pes etti.

Kardeşi bildi ucuz kahramanlıkları,

Yırtındı durdu kendi özünde,

Yenildi karanlıklara...

Meydan okumalıydı nehirler,

Sessiz durmamalıydı yağmurlar,

Ve yalnız kalmamalıydı ses veren sesler.

Bir Münadi beklenir durur,

Ahirzaman çığlığında,

Beklenir bir nida ki; ''fe eyne tezhebun? ''! ! ! 

Kınında bir kılınç mıyız? 

Yoksa bir nefer mi, bilinmeyenin önünde? 

Yani yırtılmak nedir bilmez mi karanlık,

Bir sağ bırakmadı,yalnız kaldık.

Asillik bitti, asiler kaldı,

Asi olunmayacaklara...

Halbuki; ASİLİK; ASİLLİKTİ,

VE ASİLLİK AŞIKLIKLA MÜMKÜNDÜ,

AŞK İSE BİR RUHDU, RUHUN SAHİBİNE AİT! ! !', 'Yıldırımlar ateş pahasıydı, Kelimeler yetmiyordu susuzluklara, Ve insan bir nefes çekti özüne... Yani çekmeliydi aslında... Ve bir Ebuzerr b...', ARRAY['Türk Edebiyatı','Şiir','Muhacir Muhammed']::text[], 8.5, '{"poet":"Muhacir Muhammed","poet_slug":"muhacir-muhammed","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/asilik-ve-asillik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicretimi Kabul Eder misin?', 'hicretimi-kabul-eder-misin-muhacir-muhammed-xvyss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmem daha ne kadar dayanır,

Canan’a can tüketti bu yürek…

Nefesinde solurum sevgilinin adını.

Heyecanım bir bakışıdır.

Sözüm Sana’dır…

Her aşk sana açılan bir kapıdır,

Her gözyaşı aşka davet,

Hasretime bir gaib şahittir.

Sözüm Sana’dır…

Her sözüm için adına nişan kestim.

Her sözüm sanadır şimdi, her söz sana…

Sözlerini dizerim cümlelerime…

Hayat bulur dilim…

Kalbim sana atar gayrı,

Gayrı vazgeçmem hasretimin vuslat sancısından…

Kalbim sana doğru atar,

Çünkü hasretim Sana’dır…

Sanadır hasretim…

İnan ki en çok sana hasretim,

Bir soluğuna muhtaç bu çağ şahidimdir,

En çok sana muhtacım.

Ey çölleri bakışıyla cennet eyleyen sevgili,

Bilirim zordur ama seni beklerim,

Gönlümün sabır kıyılarında,

Soyundum tüm madenlerimden,

Yalınkılınç huzurundayım,

Çünkü en çok sana muhtacım.

Anlatamıyorum beni bana,

Anlayamadı seni dünya,

Yitirildi senle bulduğum yitikler.

Sessizce ayrıldı ceylan sahilden,

Kelebekler muhtaç kaldı ziya’na.

Adına hasretler şimdi senle,

Benim hesabıma gözyaşı düştü.

Mavi bir hayalin göğe serzenişi bu benim ki.

Yıldırımların insan kolladığı vakitlerin,

Kanayan yaraların sancılarının,

Ve ışıksızların karanlık hayallerinin,

Amansız ve apansız mekanındayım

Adı dünyaymış, ben sensizlik diyorum.

Sen olsaydın, böyle mi olurdu? 

Karanlıklar ilmek ilmek ilişirken benliğime,

Anlamlarım anlamını yitirirken,

Soluklarım haykırmaya yetmediği zamanlarda,

Tam, “bitti”dediğim bir anda,

Bir el tutar elimden,

Öyle ki sıcaklığı aynı sen,

Kokusu aynı sen,

Zaman: giden sevgilinin ardından

Selam salarım sen diyarına,

Her seher gönlüm çırpınır senden yana,

Gözyaşlarım sana doğru yol bulur,

Peki ben sensiz neylerim şimdi? 

Beni unut, Bilal’ini, Zeyneb’ini,

Ebu Hureyre’ni niye yalnız bıraktın? 

Hadi sevgili, Hadi Rahmet Pınarı,

Onların hatrına gel, güldür bu kirli yüzleri,

Unut bizi, ama gel yeter ki…

Gel ve arındır bizi…

Her şeye yeniden başla, çoğalt neşelerimizi..

Seninle okuyalım her ayetini Vedud olan Rabbimin…

Şimdi gelsen şu gelen Ramazanla,

Öpüp koklasam seni doyasıya,

Gözyaşı akıtsam yüreğime taa derinden,

Yıkasa bu yakarışım hatalarımı,

Sen; “hadi kalk” desen, “daha çok işimiz var”…

Ben tutsan o gül ellerinden,

Ruhum dağılsa o an huzur ile…

Ve haykırsam dört bir yana, “sevgilim Muhammed” diye,

“bakın” desem, “bakın Resulullah gelmiş,

dünyamıza cennetin güneşi gelmiş”

“Fahri Kainat gözyaşlarımıza dayanamaz demiştim,

O bizi bırakmaz demiştim” desem,

Haber salsam her bir yöne,

Ezanlar senin için okunsa,

Ve dünya yine gül kokmaya başlasa,

Başlasa göklerin baharı,

Yağsa yerlerin rahmeti o gün.

Dağlar, taşlar, beton şehirler seninle bulsa kendini,

İnsanlar sıralansa caddelere iki yönden

Parmaklarıyla gösterseler seni,

Sinelere sığdırılan aşklarımızı haykırsak sana yağmur yağmur,

Yine okşasan yetimlerimizin başını,

Yine esen rüzgardan daha cömert olsan,

Yine sarsan ümmetini şefkat kanadınla,

Ve yine diriltsen, gittiğinden beri diriltemediğimiz,

İslam Nurunu…

Ama ne fayda rüyalarımdan bile uzaksın,

Biliyorum benim hatam,

Çünkü hayatımdan uzaksın.

Olmuyor işte, olmuyor,

Ne yapsak, ne etsek de sensiz olmuyor

Olmuyor

Olmuyor

Bir gece vaktiydi,

Kalbimin yıldızlarda attığı bir sıraydı…

Yine sen düştün yüreğime,

Sen oldun umudum,

Sen oldun avunduğum,

Sen oldun Sevdiğim…

O gün bu gündür beklerim…

Eğer doğmayacaksan kıyılarından gönlümün,

Yeşertmeyeceksen avuçlarımdaki kardelenleri,

Vakit güzken…

O halde kabul buyur beni Sevdiğim,

Senden başka kime gideceğim..? 

Kimin kollarında bulacağım felahımı,

Aşkınla yetim düşmüşken…

Kim kaldı senden başka,

Başımı okşayacak,

Gözyaşlarımı teskin edecek..? 

İşte yollarındayım karanlıktan aydınlığın,

Bahçesinden bu dünyanın, bir güldür Hicretim sana…

Zehirli sarmaşıklar, zakkumlar onların olsun.

Varsın Yunus’ları balıklar yutsun,

Ben firariyim senin aşkına.

Şu dünyanın kanlı coğrafyalarından,

İnsanların ateş kuyularından,

Bu batağın tam ortasından çıktım…

Çünkü bıktım…

Tevbelerim tevbe mi bilmiyorum,

Rahman’ın affına sığınıyorum,

Şefaat sahibinin kollarına atılıyorum; 

Kabul eder misin Hicretimi..? 

Cenneti olur musun, bu cehennem kaçkınının,

Bir soluk olur musun, kan kusan ciğerlerime,

Ateş paresi yüreğime, bir dirhem su olur musun Ey Sevgili..? 

Hicretimi kabul eder misin? 

Bu kirli Muhacir’i,

Bu zelil Muhacir’i,

Bu mücrim Muhacir’i,

Sevdana layık olmayan,

Olamayan Muhacir’i, 

Sarar mısın Ey Rahmet Peygamberi?', 'Bilmem daha ne kadar dayanır, Canan’a can tüketti bu yürek… Nefesinde solurum sevgilinin adını. Heyecanım bir bakışıdır. Sözüm Sana’dır… Her...', ARRAY['Türk Edebiyatı','Şiir','Muhacir Muhammed']::text[], 8.5, '{"poet":"Muhacir Muhammed","poet_slug":"muhacir-muhammed","theme":"Türk Şiiri","is_hero":false,"total_lines":134,"source_url":"https://www.antoloji.com/hicretimi-kabul-eder-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Rüzgar, Ellerimde Yağmur', 'yuregimde-ruzgar-ellerimde-yagmur-muhacir-muhammed-66664', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yaprak göğün nefesinde kayboldu,

Rüzgarımdır, hesapsız yürek çırpınışlarım,

Kaybettim tüm tutkularını ömrümün,

Yüreğimde bir tek, rüzgar ve nefes kaldı.

Umuda gözlerimi diktim.

Tohumlarını bekler toprağı yüreğimin.

Kurşunlara selam durur ki,

Beklediği muhasip bir gündür.

Kazanacak ellerimdeki yağmurlar,

Ki, neşesi bir dua kadar yalın,

Umudu yangınıdır, seyfinde aşkın,

Arkası bir dağ kadar engin.

Yüreğimde esen rüzgarlar,

Kazanacak ellerimdeki yağmurlar.

Yağmurlar ki, atomlarında sevdayı taşırlar.

Kazanacak ellerimdeki yağmurlar,

Ve o gün, dönüşür hüzünler bile sevince,

Gönlün sahibini gönülden sevince.

Filistinli çocuğun ellerinde taş yağmur olur,

Yağar Aksa’nın ateş dolu bağrına.

Vahyin bereketiyle,

Bir yağmur düşer toprağa,

Vahiy, gökkuşağının neşesiyle karışır yağmura,

Açılır çiçek çiçek tüm insanlığa,

“ Ve Allah gökten bir su indirdi,

Yeryüzüne ölümünden sonra hayat verdi,

Bununla Allah, dinleyecek bir topluluk için ibretler verdi”*.

*Nahl Suresi 65', 'Bir yaprak göğün nefesinde kayboldu, Rüzgarımdır, hesapsız yürek çırpınışlarım, Kaybettim tüm tutkularını ömrümün, Yüreğimde bir tek, rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Muhacir Muhammed']::text[], 8.5, '{"poet":"Muhacir Muhammed","poet_slug":"muhacir-muhammed","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yuregimde-ruzgar-ellerimde-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızlanış', 'sizlanis-muhacir-muhammed-k1de4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ateş yaktım yüreğimin tam ortasına

Isınası ruhları,ısıtmak adına.

Güneş gibi yalın kılıç çıktım,

Tağut karşısına.

Kalp atışlarını duymazdan gelip sevdanın

İğne deliğinden alan seller gibiyim.

Geçmişim,tozpembe arkamda,

Gençliğim işte burada avucumda.

Önümdeyse reelden uzak karanlık,

Görülmeyen bir aydınlık.

Dikenli tellere dolanmış zihinler.

Teneke kalplerde pişen susuz aşklar...

Tanımlanamayan bir dünyada kurulmaya çalışılan,

Sanal bir düşün hain girdabı...

‘Bir balığın suya kanışı gibi’ bir düşünceyle bezenmiş,

Barış bayrakları dikilen sarp kayalıkların zirvesi...

Gökte, bir arab’ın kanıyla sulanmış,

Üç yıldızın destansı hikayesi,

Etrafı fahiş domuzların çamur banyosu yaptığı,

Bir Mescid’in portresi var avucumuzda...', 'Bir ateş yaktım yüreğimin tam ortasına Isınası ruhları,ısıtmak adına. Güneş gibi yalın kılıç çıktım, Tağut karşısına. Kalp atışlarını duymaz...', ARRAY['Türk Edebiyatı','Şiir','Muhacir Muhammed']::text[], 8.5, '{"poet":"Muhacir Muhammed","poet_slug":"muhacir-muhammed","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sizlanis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Olsun', 'ask-olsun-muhacir-muhammed-jx0q4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aslında içimden ne geliyor biliyormusun... 

gecenin Ud’unu dinlemek Emirgan’ın göbeğine

rüzgar ney nameleri üflerken kuru yapraklara,

ben sensizliğe bilensem, hiç bilmeden…

sabahın ayazı vurmasa da sensizlik kadar,

üşümek sabah abdestini alırken…

güneş doğana kada r tesbihalleşsem kumrularla.

Dört bir yandan sarsa yar sevdası.

Bilirim pervaneyi yakar nar…

Öğleni kovalasam bir Filistin çoşkunluğunda,

Sonra ikindiye varsam Medine dinginliğinde…

Yeminler içsem İkindi Vaktine,

“Vel As’r” desen! 

Sonra sussam.

aslında içimden ne geliyor biliyormusun... 

çamlıca tepesine çıkıp, osmanlı kahvemi yudumlayıp gecenin ortasına kadar Naat yazmak,

 sonrada bir  çilehanede sabaha değin secde etmek... 

taki alnın çürüyene dek,

geçse dünyanın zilleti, çirkefin gölgesinden.

Bende dünyadan geçsem

eyüpte, bir kabrin yanında sonsuz dinlenceye çekilsem... 

ve ardından hesaba çekilmek

sonra bana soranlara... 

''neden geldin''? diye... 

sorunca Resulullah... 

''niye geldin'' diye...

 sensiz olamadım, sonsuz oldum diyebilmek...

ellerin uzanamadığı memleketlere uzanan yüreğim... 

bir dost yüreğine tutunan yüreğim... 

tutunamadıysa Medinenin gül sevdasına...

 artık neyleyeyim dünyayı... 

Hüdayi yolunu kaybetmişse Üsküdar...

 İskenderpaşa, hatmelerle coşmuyorsa

Metin Yüksel vurulmuyorsa cami avlusunda... 

İsmailağa’da Mahmut efendi, ''evladım, nasılsın'' demiyorsa

Yoksa bu dünyada Said Nursi gibi, ''Saçlarım kadar başım olsa,

 Hakk yoluna olsun feda'' diyen bir yürek... 

Artık neyleyeyim dünyayı...

 hüznü boşayıp, aşk-ı Resul’le nişanlanmıyorsa gözyaşım... 

hikmetin ve risaletin gülleri kokmuyorsa terimde... 

duvar afişlerinde ayetler hadisler yankılanmıyorsa... 

dünya hala eski dünyaysa... 

çocuklar anne sütünün kokusunu duymadan,

 barut ve kan kokusu duyuyorsa... 

bırakın beni... 

bırakın Allah aşkına... 

hicretim kabul olsun................. 

kabul olsun................ 

olsun.................

 yeterki aşk olsun

yeterki kardeşlik olsun.... 

yeterki sevda olsun, 

muska diye taşınan yüreklerde... 

olsun kardeşim... 

olsun be…

bu şiir sana hediyem olsun...', 'aslında içimden ne geliyor biliyormusun...  gecenin Ud’unu dinlemek Emirgan’ın göbeğine rüzgar ney nameleri üflerken kuru yapraklara, ben se...', ARRAY['Türk Edebiyatı','Şiir','Muhacir Muhammed']::text[], 8.5, '{"poet":"Muhacir Muhammed","poet_slug":"muhacir-muhammed","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/ask-olsun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Yollardayım...', 'yeniden-yollardayim-muhacir-muhammed-3nmdt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayretteyim dokundu kalbime,

Sevginin tebessümü.

Baharın toprağa,

Kelebeğin çiçeğe dokunuşu gibi.

Hayallere bulandı sevdalar.

Bir düş gibiydi,

Ama bir yanım, 

Hep öykündü senden yana.

Şimdi yırtıyorum sessizliğimi,

Yeniden başlar mı ümidin visali? 

Ekinler büyür mü gelmeden baharı? 

Olur, diyorum, düşüyorum yollara yeniden…

Tütüyor şimdi hayal penceremden,

Kar misali meleklerin sahiplendiği umutlarım.

Yazıyor kalem sevda defterine adımı,

Ve düşüyorum yollara yeniden…

Yolların önünde dağlar yok belki,

Ama hayat var…

Hayat; tuzağıdır gönlümün,

Tuzaklarından şeytanın.

Hayatı da silip düşüyorum yola…

Duramam gayrı ıraktır yollar,

Yollara vurgun değilim ama…

Yolun sonundakinedir hasretim,

O’nadır vurgunum…

Aşkımı alıp üstüme düşüyorum yollara…

Düşüyorum yollara yeniden,

Adını koyamıyorum yolların,

Hepsi sevdadan demetler kokuyor,

Korkuyor ey yol ve Yolun Sahibi,

Muhacir’in korkuyor.

Ötelese de dünyayı ve içindekileri,

Dünyadan korkuyor…

Bırak git, bırak git beni,

Ben bu yolların yolcusuyum,

Ben gönlüne sevdayı gömmüşüm,

Filizlensin diye Cennet gülleri…

Sulayıp güllerimi düşüyorum yollara…

Yolların hasreti yine deydi ya yüreğime,

Yollar yeniden büyür böğrümden ufka doğru…

Ben bu yolların yolcusuyum,

Beklide sevdalıların sonuncusuyum,

Düşüyorum yollara yeniden

Yüreğime nefis çökmeden.', 'Hayretteyim dokundu kalbime, Sevginin tebessümü. Baharın toprağa, Kelebeğin çiçeğe dokunuşu gibi. Hayallere bulandı sevdalar. Bir düş gibiyd...', ARRAY['Türk Edebiyatı','Şiir','Muhacir Muhammed']::text[], 8.5, '{"poet":"Muhacir Muhammed","poet_slug":"muhacir-muhammed","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yeniden-yollardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çocuğun Neşesi Kadar Masum muydu Hayat? ? ?', 'bir-cocugun-nesesi-kadar-masum-muydu-hayat-muhacir-muhammed-3egbw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çocuğun neşesi kadar masum muydu hayat? ? ? 

Gülüşünde kaybolacak kadar çocuk muydu…

Heyhat kararıyor aydınlıklar,

Uykuları bölünüyor çocukların.

Saadeti arayan bunca yığın,

Asr-ı Saadetten bihaber mi acep? 

Ve sen Ey Nebi…

Sana Gül diyen bunca Ümmet,

Bülbüllükten neden kaçar acep? 

Her çocuğun yüreği, sensin Ya Resulalllah...

Öyle saf, öyle temiz,

Bir çocuğun gözlerinde ki sevinç sensin,

Ağladığında bir çocuk,

Bedir’deki bir duadasın…

Ben garibim, bu aşkın garibiyim…

Bazen Bağdat’ın, bazen Kudüs’üm ama…

Medine’nin yolcusuyum…

Vücudum çöllerin kumlarına sarılı,

Sanma ki anlımda başımdaki sarıktır,

Boyu boyuma kefendir.

Dudaklar susamışsa bile, 

Ben Muhammed’sedim,

Her çocuğun yüreği, sensin Ya Resulalllah...

Bir pencerede baba yollarına dikilmiş,

Nemli gözler gibi bakışlarım.

Gelsen, bir gelsen, bir gelişle gelsen…

Ben o çocuğun neşesiyle koşsam yollarına,

O çocuğun neşesiyle sarılsam boynuna…

Hasretimin busesinden incinir misin Ya Resul? 

Çünki, her çocuğun yüreği, sensin Ya Resulalllah...

Öyle saf, öyle temiz, öyle narin.

Kelebek kanadından toz toplar gibi…

Gurbetineyim, sılam sensin,

Mülteciyim, sana iltica ederim,

Her mekan soğuktur bana,

Ben ancak gönlünde ikamet ederim.

Adına söz sıralamaktan, Rabbime sığınırım,

Ben bilirim ki, bununla ancak aşkıma aşk katarım.

Bunu şiirden sayma çünkü sen…

Sen, tüm zamanların en güzel şiirsin,

Mısra tadında sararsın ümmetini.

Küçük ellerin semaya kalkışıdır, çocuk…

Melekler imrenir dudaklardan dökülenlere…

Her “Rabbim” diyişine,

Bir melek atar kendini yer semasına…

Bir yetim miniği dinlerken,

Tüm melekler saf saf…

Benimde sana yetimliğim düşer,

Gönül tezgahımdan…

Minik ellere iki damla gözyaşı düşer,

Ve senin gül yanakların ıslanır,

Çünkü her çocuğun yüreği, sensin…

Ağlasam kollarında incinir misin?', 'Bir çocuğun neşesi kadar masum muydu hayat? ? ?  Gülüşünde kaybolacak kadar çocuk muydu… Heyhat kararıyor aydınlıklar, Uykuları bölünüyor ço...', ARRAY['Türk Edebiyatı','Şiir','Muhacir Muhammed']::text[], 8.5, '{"poet":"Muhacir Muhammed","poet_slug":"muhacir-muhammed","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/bir-cocugun-nesesi-kadar-masum-muydu-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koyunlar', 'koyunlar-mikdat-bal-y0y1i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çobanlık en zor meslek, hayali bile zordur

Uyku ilacı gibi, beyaz başlı koyunlar

Uykun kaçtığı anda aklın dimağın yordur

Önünden bir bir geçer beşli beşli koyunlar

Koyunlarla uğraşmak, insanları uyutur

Çünkü koyun dualı, uysal olmak huyudur

Beyaz beyaz koyunlar bazıları koyudur

İnsanı mest ediyor beyaz dişli koyunlar

Uykuların kaçınca haline üzülürler

Uçuşurlar bir anda sanırsın süzülürler

Dalarsın bir hülyaya karşında dizilirler

Koro halinde meler eşli eşli koyunlar

Mikdatî der koyunun cemaline doyulmaz

İnsana amadedir, yoksa bunlar kıyılmaz

Ne temiz yaratıklar, faydaları sayılmaz

Kurban olur insana yaşlı yaşlı koyunlar', 'Çobanlık en zor meslek, hayali bile zordur Uyku ilacı gibi, beyaz başlı koyunlar Uykun kaçtığı anda aklın dimağın yordur Önünden bir bir geç...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/koyunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş''le Söyleşi', 'gunes-le-soylesi-h-hikmet-esen-enpw3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık yavaş yavaş hazırlan

Haydi bakalım Güneş

Yakındır doğman.

Biliyorsun

Görevin bu doğacaksın; 

Niye bu nazlanman.

Doğ ki  aydınlansın

Karanlığa gömülenler.

Serilsin gözler önüne

Gizlenen kötülükler.

Belki o zaman dağılır 

Bu çürümüş gölgeler.

Yepyeni

Umut çiçekleri açar belki

Sevdalı gönüllerde

Sabah serinliğiyle.

Üzülüyorsan

Utanıyorsan eğer gördüklerinden. 

Bil ki

Doğmanla yok olacak

Akşamdan kalan

Tüm bu gölgeler.

Aydınlık

Yaşam demek

Sense aydınlık

Yeter karanlığa boğduğun

Bitsin bu ayrılık..

26/08/1977

.....İzmir.....

H Hikmet Esen', 'Artık yavaş yavaş hazırlan Haydi bakalım Güneş Yakındır doğman. Biliyorsun Görevin bu doğacaksın;  Niye bu nazlanman. Doğ ki  aydınlansın Ka...', ARRAY['Türk Edebiyatı','Şiir','H Hikmet Esen']::text[], 8.5, '{"poet":"H Hikmet Esen","poet_slug":"h-hikmet-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gunes-le-soylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Bülteni', 'hayat-bulteni-ahmet-agdere-vtocd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ganyan: Tanrı kulu

Sürpriz: İblis yolu

Plase: Yâr kolu', 'Ganyan: Tanrı kulu Sürpriz: İblis yolu Plase: Yâr kolu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hayat-bulteni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviş Benimle de', 'sevis-benimle-de-sevinc-kavuk-oa303', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağlarda yanık

Kavuşulmaz uzaklığından hoş şarkısı

Renkli ve canlı

Ahenkli mısralar demetinin kokusu duyulur

Sevda kucağı

Yol üzeri uğrak mekan olmaya da yüz tuttu 

Panoraması 

Ben o şiirlerde gezinirken içimde dolanlarla

Dilim lâl, gönlüm hoş......................durma 

…….……...………………......…ne olur

…….…...………..…….…beynimle 

...….....……………..yüreğimle 

.…........…….hep bitesiye 

.......seviş benimle de

........22.02.2006

Çarşamba 05.05', 'Dağlarda yanık Kavuşulmaz uzaklığından hoş şarkısı Renkli ve canlı Ahenkli mısralar demetinin kokusu duyulur Sevda kucağı Yol üzeri uğrak me...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevis-benimle-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların beni anlıyor', 'saclarin-beni-anliyor-elazigli-mustafa-kaya-squcr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'saçların uzamalı. 

sevmekten yorulmam. 

yosun bağlayan hasretim 

saracak saçlarını 

rüzgar savuracak 

yağmur yuyacak. 

geceleri uykumdan alacak 

tüm çıkmazlarıma 

kement atacak. 

serbest kalmalı 

çöz saçlarını

değsin ruhuma 

ruhum yanmalı

adını anmalıyım 

beni tek

saçların anlıyor

yüreğimi yakarak

ellerimden tutarak … 

Mustafa kaya 

22.02.2006 / kavacık 

www.mustafakaya.net

Mustafa kaya 

22.02.2006 /  kavacık', 'saçların uzamalı.  sevmekten yorulmam.  yosun bağlayan hasretim  saracak saçlarını  rüzgar savuracak  yağmur yuyacak.  geceleri uykumdan ala...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/saclarin-beni-anliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliği bu dünyada yaşamak', 'sensizligi-bu-dunyada-yasamak-halil-colak-776ew', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin sinesinde rüyaya giren sevgilim

Gökte ay dolunay olup süsler gökyüzünü

Mutluluk başlarr kışkırtıcı dolunay altında

El ele tutuşur yaşarız tutkulu sevgilerimizi

Rüyada  heyecan kaplar bedenlerimizi

Heyecandan titreyen dudaklarımda

Serenat olarak çıkan sevgi sözcüklerini

Uykudan uyandığın da sevgililer

En zor olan sen olmadan güzelim

Sensizliği bu dünyada yaşamak



Halil Çolak 22.2.2006 Ankara', 'Gecenin sinesinde rüyaya giren sevgilim Gökte ay dolunay olup süsler gökyüzünü Mutluluk başlarr kışkırtıcı dolunay altında El ele tutuşur ya...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizligi-bu-dunyada-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilinin sessizligi huznu', 'sevgilinin-sessizligi-huznu-ulya-erkman-n3hoh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mehtap yildizlar ve 

Bahcende sen

Gecenin sessizligidir sadece

Dusuncen

Isitmezsin bile sessizligi 

Susleyen

Uzaklardan sesi 

Gelen

Siril siril akan suyu

Isitmezsin daldaki kusun

Sessizlige sarkisini

Meltemlerin sarildigi agaclarda

Yapraklarin fisiltisini

Mahrumsun isitmekten

Sessizligin bu kismini

Dusunursun sade sessligi

Dinlemezsin melodinin yarisini

Dusunursun sevgilinin sessizligini

Hatirlamayisini

Onun sessizliginde de isitmezsin

Bir suyun akisini

Onun sessizliginde de isitmezsin

Bir kusun sarkisini

Onun sessizliginde de iisitmezsin

Yapraklarin fisiltisini

Sevgilinin bu hasletleri sessizliginde bile 

Olmezken

Sana bir suyun akisi gibi siril siril

Sozler soylemisken

Bir kusun otusundeki gibi coskun

Sozler hissettirmisken

Yapraklarin fisiltisi gibi her firsatta

Sana sevgiler fisildamisken

Nedir seni huzne

Goturen? 

O sessizlikteki sevgiyi 

Dusunsen

Sessizliginde bile sevgilisi

Hala sensen

Bence huznu birakip

Sadece sevinsen', 'Mehtap yildizlar ve  Bahcende sen Gecenin sessizligidir sadece Dusuncen Isitmezsin bile sessizligi  Susleyen Uzaklardan sesi  Gelen Siril si...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sevgilinin-sessizligi-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Zehir', 'tatli-zehir-sadettin-deren-60z3w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurulmuş saat zembereğini düşün

Gerilmiş yayda bir ok...

Dört dakikaya ayarlanmış bir dinamit kalıbı ellerimde,

İlahlardan yollanmış bir şimşeğim sana,

Beni anlıyor musun? 

Elektrikli sandalyedeyim tut ki,

Tut ki beş bin volta ayarlı şalterler,

Keban barajı boşaldı-boşalacak üzerime,

Düşün ki kurtuluşum ellerinde,

Beni titriyor musun? 

Pençesindeyim bir kartalın taa yükseklerde

Bıraktı-bırakacak üşüyorum...

Yirmiyedi yerimden bıçaklandım,komadayım,

Yalnız senden uyuyor bana kan,Semra pozitif...

Beni kanıyor musun?', 'Kurulmuş saat zembereğini düşün Gerilmiş yayda bir ok... Dört dakikaya ayarlanmış bir dinamit kalıbı ellerimde, İlahlardan yollanmış bir şim...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tatli-zehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopuşlar XVII', 'kopuslar-xvii-erol-dal-ym7qq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umudun tükendiği yerde

Bir kadeh bekler sizi; 

İçilmeye, unutmaya hazırdır hep.

Ne olursa olsun yaşınız,

Tükendiyse umutlarınız,

Yakında; 

Erişilmez bulutlardasınız.

Sağınızda bir melek

Solunuzda bir melek

Sizi izleyecek. 

Erişince arşa

Ne aş bulacaksınız yiyecek,

Ne de bir yudum su,

İçecek..

Sadece,

Kaynayan kazanda

Umutlar görünecek hep.

                             87/09/Mekan', 'Umudun tükendiği yerde Bir kadeh bekler sizi;  İçilmeye, unutmaya hazırdır hep. Ne olursa olsun yaşınız, Tükendiyse umutlarınız, Yakında;  E...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kopuslar-xvii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-nurcan-avsar-8mqnl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gölgeden yaşamdı bizimkisi...

Ya her mutlu duygunun arkasından yürüdük

Ya da her hüznün önünden,

Kimi zaman küçücük 

Kimi zaman kocaman...

Ne davalarımıza 

Ne sevdalarımıza 

Ne de sevdiğimize hakimdik

Karaltısıydık bedenimizin...

Gölgeden yaşamdı bizimkisi...

Gölgesinde dünyanın...', 'Gölgeden yaşamdı bizimkisi... Ya her mutlu duygunun arkasından yürüdük Ya da her hüznün önünden, Kimi zaman küçücük  Kimi zaman kocaman... N...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Avşar']::text[], 8.5, '{"poet":"Nurcan Avşar","poet_slug":"nurcan-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/golge-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanıyorum...uyuyamıyorum', 'uyaniyorum-uyuyamiyorum-elazigli-mustafa-kaya-gkmm9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir rüya,

yokuşlarda gördüm 

suları

ibrahim’i yakmayan ateşi

buldum

gözleri yaşaran

taşlar

ve,

saçlarını getiriyor 

bir rüzgar

erikler olmuş ağacın

gölgesinde seni

buldum

ince bir hüzün yaşıyor

menekşe kokulu

gamzelerin

leylaklarla kaplanıyor

çöller

ve,

uyanıyorum

uyuyamıyorum …

Mustafa kaya

21.02.2006 /  beyazıd', 'bir rüya, yokuşlarda gördüm  suları ibrahim’i yakmayan ateşi buldum gözleri yaşaran taşlar ve, saçlarını getiriyor  bir rüzgar erikler olmuş...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uyaniyorum-uyuyamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şımarmak bile yakışıyor sana', 'simarmak-bile-yakisiyor-sana-elazigli-mustafa-kaya-sqvkt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimbilir yakışmış olmalı

şımarmak                         

o şımarıklık bile güzel 

gözlerinde..

saçlarına vurmuş

ipek duyguların 

hangi şarkı yakışır kimbilir 

şimdi diline. 

kuşlar uçuyor 

yürüdüğün her yere

mor sümbülleri 

hatırladım 

doğduğum köyde

dikenler arasında                 

bir gül vardı

aldırmadım dizlerimin

kanamasına

bir ince sevda uğruna

çektiğimi                   

bilir köyün gelincikleri..

ağlama ne olur

benim gibi

suskunluğunu at,                       

öpesim gelen                 

gamzelerindeki hüznü                          

acılarıma kat …

 Mustafa kaya

22.02.2006 / sarayburnu', 'kimbilir yakışmış olmalı şımarmak                          o şımarıklık bile güzel  gözlerinde.. saçlarına vurmuş ipek duyguların  hangi şar...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/simarmak-bile-yakisiyor-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Sevgi Seliyim', 'ben-bir-sevgi-seliyim-huseyin-erdogan-bdoot', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'biliyor musun 

ne denli özlediğimi seni? 

hasretinin 

yakıp kavurduğunu beni? 

bilsem ki 

yanacağım ömrüm boyunca

sana kavuşma umudumu yitirmem asla

mahşerde bile 

bekleyeceğim seni umutla

ben bir meltem yeliyim

eser dururum senden yana

ben bir sevgi seliyim

taşarım yalnızca senin dünyana

bir tek günaydınınla bile

bir güneş gibi doğarsın günüme

seni sevdiğimden beri

dönüp de hiç bakmıyorum artık

senden önceki dünüme

ne olursun sen de ömrünce

beni müebbete mahkum et yüreğinde

                                  22.02.2006

                              Hüseyin Erdoğan', 'biliyor musun  ne denli özlediğimi seni?  hasretinin  yakıp kavurduğunu beni?  bilsem ki  yanacağım ömrüm boyunca sana kavuşma umudumu yitir...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-bir-sevgi-seliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin  "siz hiç ay aşığında ağladınız mı" Kitabından', 'nerdesin-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-1ineg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son kaç asrı can evinden vurdular

Osman Gâzi neredesin nerdesin 

Camileri samanlığa verdiler

Orhan Gâzi cihân hayran nerdesin 

Arşivlerim lime lime satıldı 

Krokiler ve tapular yırtıldı 

Yutkun yutkun içe attım dert oldu 

Mimar Sinan koca irfan nerdesin 

Efe zeybek dadaş barı ar oldu 

Leylâ yoktur bir buselik yâr oldu 

Nikâh kıymak flört çıktı zor oldu

Akşemseddin edeb püryan nerdesin

Şiir yazar mâzisinden huzursuz 

İzzet iffet horlanıyor fütursuz

İfşâ etti o safahat kusursuz 

Duy  Akif’im sana kurban nerdesin', 'Son kaç asrı can evinden vurdular Osman Gâzi neredesin nerdesin  Camileri samanlığa verdiler Orhan Gâzi cihân hayran nerdesin  Arşivlerim li...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerdesin-156-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- Kızıl Yağmur', 'kizil-yagmur-i-smail-hakki-kavurmaci-hp3do', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'biliyor musun bir sen varsın 

ışık 

su 

hayat 

sadece sende var 

senle var 

hayat ağır 

akıntı hızlı 

günler aylar ve yollar 

önemini yitiriyor 

hasret büyüyor 

vuslat! 

o kadar çok hayallerim oldu ki 

vuslat üstüne… 

yağmur yağdı 

toprak sevindi 

ben de sevindim 

ay doğdu 

deniz şenlendi 

ben de şenlendim 

hasret giderdi denizle ay 

toprakla kızıl yağmur 

bana da 

bu büyük sevdaların bulaşma sevincinden 

bir buruk teselli düştü 

evler yanar içi alev alev 

camlarda yansımaları hoş yakamozlar 

yangın var yürekte 

gözlere düşen ise 

çığlığa bile mecali kalmayan 

bir çaresiz tebessüm 

akşamı olmayan gün 

sabahı olmayan gece 

baharı olmayan kış 

ve sonunda kavuşma ümidi olmayan yol 

hasret büyüyor dağ gibi 

yangın gibi sel gibi 

ve bir çaresizlik 

çığ gibi 

içim patlıyor yüreğim daralıyor 

bir damla gözyaşı 

bir alaca karanlık 

bir güz sessizliği 

ve dudaklarda 

yürekten kaynayan bir hasret 

bir çaresizlik türküsü 

hasretim ah hasretim 

denizle ay gibi hasretim 

çekilince bulutlar aradan 

kaynar yüreğim coşarım 

sen uzaktasın dolunay 

ben sana hasretim 

ben sana vurgunum… 

“bizim vedamız dönmek üzere değildi 

bizim aydınlığımız birbirimizin 

gözlerinde kalmıştı sevgilim” 

biliyor musun bir sen varsın 

ışık 

su 

hayat 

sadece sende var senle var…dı 

şimdi sen yoksun 

ışık yok 

su yok 

ben de yokum 

Bir söz duymuştum; “Önemli, güzel şiirler şairlerin kulağına ilham perisince fısıldanır”..

Ben şairlik iddiasında değilim. Yazdıklarıma da şiir değil “Coşkularım” diyorum. Yüreğimde kopan fırtınalardan, çağlayanlardan, coşkulardan kalemime sıçrayan damlacıklar.

“Kızıl Yağmur”, bana göre yazdıklarım arasında en önemlilerinden birisi ve bu benim kulağıma fısıldandı. Bir deneme yazısı okumuştum, ismi Kızıl Yağmur, yazarı Gamze Özen. İşte o yazıdan bir ilham perisi uçuştu, omzuma kondu ve “biliyormusun bir sen varsın …”la başlayan sözcükleri kulağıma fısıldadı.

Kızıl Yağmur’un yazarını tebrik ediyorum. Duygu dolu denemesinden dolayı ve teşekkür ediyorum, coşkularımdan birkaç damlacığın daha kalemime sıçramasına vesile olduğu için. 

İsmail Hakkı Kavurmacı

2001 Erzurum', 'biliyor musun bir sen varsın  ışık  su  hayat  sadece sende var  senle var  hayat ağır  akıntı hızlı  günler aylar ve yollar  önemini yitiri...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/kizil-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez mi Bunca Yandığım', 'yetmez-mi-bunca-yandigim-zeynal-yaman-4cdm2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Melâli paylaşıyor gözlerin benimle

Bir demmiş meğer geçen ömür seninle

Ne hazin bir hikâyedir ölmek zehrinle

Yetmez mi bunca yandığım gam u derdinle? 

Bak ebr-i nisanıma yağan yağmur mudur? 

Seninçün ağlayan bu gözler mahmur mudur? 

Şu sendeki inat aşılmaz bir sur mudur? 

yetmez mi bunca yandığım gam u derdinle

Gel şu ıstırap asrını saadet eyle

Her gün hatırımı sor bunu âdet eyle

Yandım diyorum ah efendim medet eyle! 

Yetmez mi  bunca yandığım gam u derdinle? 

Zeynel''im zamana yâr olmadı bu gönlüm

Hep senin için figan eyledi bülbülüm

Ben ki bin diken ortasında açan gülüm

Yetmez mi bunca yandığım gam u derdinle? 

1997', 'Melâli paylaşıyor gözlerin benimle Bir demmiş meğer geçen ömür seninle Ne hazin bir hikâyedir ölmek zehrinle Yetmez mi bunca yandığım gam u ...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yetmez-mi-bunca-yandigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yaylaya Çıktı Gönlüm', 'yine-yaylaya-cikti-gonlum-zeynal-yaman-p1ocr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine yaylaya çıktı gönlüm

Çiçek derliyor demet demet

Sevda okuyor kayaların başında

Türkü söylüyor memleket memleket...

1991', 'Yine yaylaya çıktı gönlüm Çiçek derliyor demet demet Sevda okuyor kayaların başında Türkü söylüyor memleket memleket... 1991...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yine-yaylaya-cikti-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler Ve Bakışlar', 'gozler-ve-bakislar-alper-kuruk-3sq8l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayata bir bebek gözüyle bakıyorum

Süt beyaz dağlar,tepeler

Sanki değsen süt fışkıracak memeler

Hep süt süt akıyor dereler

Baktıkça acıkıyorum...

Hayata bir çocuk gözüyle bakıyorum

Her tarafta oyun,oyuncak her yer

Birini kırıyor,birini bırakıyorum

Her şeyden çarçabukça bıkıyorum...

Hayata bir genç gözüyle bakıyorum

Gördüğüm her renk toz-pembe,

Cıva gönlümce akıyorum

Bir türlü içim içime sığmıyor benim de...

Roma''yı NERON mu yakıyor? 

Beni mi yakıyorlar? 

Ben mi yakıyorum? 

Hayata bir çapkın gözüyle bakıyorum

Neye baksam gördüğüm ya sevgi, ya aşk

Gün gelip aşktan da sıkılıyorum

Serseri bir mayınım denizde

Yine birilerine ha çarptım,çarpıyorum...

Bir de evli gözüyle bakıyorum hayata

Çevremde eşim,çocuklarım...

Erişmek hem güç, hem kolay böyle saltanata

Anlıyorum ki bu evrende

Bir nokta olsam ben de varım...', 'Hayata bir bebek gözüyle bakıyorum Süt beyaz dağlar,tepeler Sanki değsen süt fışkıracak memeler Hep süt süt akıyor dereler Baktıkça acıkıyor...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gozler-ve-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Sokaklar', 'sensiz-sokaklar-omer-osman-avci-hor3x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmem 

Gecenin sıfır kaçındadır zaman

İçimdeki senli duygularla

Ve… bir mahkumun voltalarıyla dolaşıyorum

Bu uğursuz şehrin sokaklarını

Ayaklarımın altında

Titreyen, korkak kaldırımlar

Bir de

Başımda yalpalayarak dolaşan

Şu sarhoş bulutlar

Attığım her adımda   

Arayıp seni bulurlar…          

İşte bak o kadarda sessiz değil 

Sensiz sokaklar

İn-cin seyircisiz top oynuyorlar

Hem de sabahlara kadar…', 'Bilmem  Gecenin sıfır kaçındadır zaman İçimdeki senli duygularla Ve… bir mahkumun voltalarıyla dolaşıyorum Bu uğursuz şehrin sokaklarını Aya...', ARRAY['Türk Edebiyatı','Şiir','Ömer Osman Avcı']::text[], 8.5, '{"poet":"Ömer Osman Avcı","poet_slug":"omer-osman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerken', 'beklerken-cengiz-kapusuz-4kkyt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklerken gecenin karanlığını,

Yakamozlarla birlikte gel.

Bil sahilde seni beklediğimi,

Her parıltıda seni göreceğimi.

Beklerken soğuk yatağımda

Bil sensiz üşüyeceğimi.

Hatta rüyalarımda,

Seni göreceğimi.

Beklerken o mum kokulu,

Bu sensiz soğuk odada,

Yeter ki gel,

Şu üşümüş yüreğimi,

Açıyorum sana,

Isıtsan da ısıtmasan da…', 'Beklerken gecenin karanlığını, Yakamozlarla birlikte gel. Bil sahilde seni beklediğimi, Her parıltıda seni göreceğimi. Beklerken soğuk yatağ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beklerken-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Çıktım Yollardayım', 'yine-ciktim-yollardayim-sahin-erturk-dxqr2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ankara’dan,Muş’a kadar

Gözlerimde sanki radar

Aşkı bilen arıyorum

Yine çıktım yollardayım

İstanbul’da Hafize var

Adana’da Hatice var

Trabzon’da Halime var

Yine çıktım yollardayım

Palandöken yol vermedi

Erzincanlı koy vermedi

Kayserili söz vermedi

Yine çıktım yollardayım

Akdeniz’de her gün bahar

Güneydoğu sıcak diyar

Erzurum’da diz boyu kar

Yine çıktım yollardayım

Cemile’nin nazı vardı

Emine’nin hırsı vardı

Feride’nin sözü vardı

Yine çıktım yollardayım

Sabırlıyım,kararlıyım

Bazen yaban kollardayım

Köylerdeyim koylardayım

Yine çıktım yollardayım

(22.02.2006)    

(Şiirdeki isimler Sanaldır)   

Karaborsa Sevgi adlı

5.nci şiir kitabımdan', 'Ankara’dan,Muş’a kadar Gözlerimde sanki radar Aşkı bilen arıyorum Yine çıktım yollardayım İstanbul’da Hafize var Adana’da Hatice var Trabzon...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yine-ciktim-yollardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünen', 'gorunen-turan-tuncer-r1536', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GÖRÜNEN

İçimde atesler yanarda sönmez

Nice yigitler gittiler, geriye gelmez

Akli selim adam ahimi almaz

Ben idim,kurdun postunda kuzu görünen! ! ! 

Kötü adamın bini, bir para eder,

Aheste olup sabreden, uzun yol gider,

Kelâm eden için, tatlı söz yoksa eğer dilinde

Ben idim, bal peteğinde, zehir görünen! ! ! 

Ah edipte sebebi sen olma, sakın

Gelmez sandığın o gün, sana dünden de yakın

Akil ol, sevgi geçer akçe çevrene bir bakın

Ben idim zemheri soğuğunda yanar görünen.! ! ! 

Her şey aşikâr olur, saklanır sanma

Küçük hevesler için, ateşlerde yanma

Dünya bozulsada, sen kötü olma

Ben idim bir gülüş uğruna, Mecnun görünen! ! ! 

Saklamam adımı, gelenler bir ders alsın

Kelâm edecek isen, kötüsü sende kalsın

Hapset içinde benliği, sen yaşa şeytan yansın

Sen ol şeytana kanmayıp, insan görünen! ! ! 

Adım ''Kuşcu''dur, ne yapsan boşa

Ne  yazılmışsa mutlak o  gelecek başa

Ölüm bizim için, hiç gerek yok telaşa

Ben idim kefende,  nasihat görünen! ! ! 

18 Şubat 2006 /İst

Akladraz_Kuşcusu', 'GÖRÜNEN İçimde atesler yanarda sönmez Nice yigitler gittiler, geriye gelmez Akli selim adam ahimi almaz Ben idim,kurdun postunda kuzu görüne...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gorunen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-ali-arslan-gtewp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vedası zordur aşkın

ne diyeceğini bilemezsin:

Düğümlenir... Tutulur nutkun...Söyleyemezsin...

Çatallanır dilin, kıvranır

anlatamazsın! 

Gözyaşı dökmek ister canın:

Dökülmez... Kurursun...Akıtamazsın...

Buzdan bir damla olur 

çözemezsin! 

Eli eline o kadar yakın:

Uzanırsın... Korkarsın...Boşta kalır gibisin...

Mesafeler artar devamlı kavuşmak bir kâbustur 

değdiremezsin! 

Yaşadıkların gelir aklına:

Hatırlarsın... Düğümlenir... Hayal sanırsın...

Bir sis bulutudur zaman,

sürüklenirsin, uçurumun başındasın 

ölemezsin! 

Ayrılığın ipi dolandığında,

vedası zordur aşkın:

Sarılır...Dolanırsın... Kördüğümsün...

Ne aşk ne de sen aşktan, imkânsız

kurtulamazsın!', 'Vedası zordur aşkın ne diyeceğini bilemezsin: Düğümlenir... Tutulur nutkun...Söyleyemezsin... Çatallanır dilin, kıvranır anlatamazsın!  Gözy...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/vedasi-zordur-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanat Yaptım Sanıyorlar', 'sanat-yaptim-saniyorlar-sahin-erturk-gxxkp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Erkekleri,Kadın gibi

Kadınları,Erkek gibi

Hopluyorlar,zıplıyorlar

Müzik yaptım sanıyorlar

Açılıyor,saçılıyor

Sahnelerde sevişiyor

Fahişeyle yarışıyor

Sanat yaptım sanıyorlar

Ağızları lağım sanki

Küfür dolu yaşıyorlar

Onla,bunla yatıyorlar

Sanat yaptım sanıyorlar

Aşkı onlar kirletiyor

Çalışmıyor beyinleri

Kandırıyor KERİZLERİ

Sanat yaptım sanıyorlar

Sanatcılar köşelerde

Onlar hergün döşeklerde

Bulaştılar pisliklere

Sanat yaptım sanıyorlar

Ar damarı çatlamışlar

Vücudunu satan kızlar

Kültürsüzler,Kumarbazlar

Sanat yaptım sanıyorlar

(22.02.2006) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Erkekleri,Kadın gibi Kadınları,Erkek gibi Hopluyorlar,zıplıyorlar Müzik yaptım sanıyorlar Açılıyor,saçılıyor Sahnelerde sevişiyor Fahişeyle ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sanat-yaptim-saniyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nankör Kedi', 'nankor-kedi-sahin-erturk-vbqce', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deli ediyorsun DELİ

Sevmiyorsun beni belli

Yaptığımı unutmuşsun

Kadir,kıymet bilmiyorsun

Sana derler,nankör kedi

(21.02.2006)', 'Deli ediyorsun DELİ Sevmiyorsun beni belli Yaptığımı unutmuşsun Kadir,kıymet bilmiyorsun Sana derler,nankör kedi (21.02.2006)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nankor-kedi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla Yıkamazlar', 'asla-yikamazlar-yusuf-onder-bahceci-z43d8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnandım bu Milleti asla ve asla yıkamazlar,

Ol Peygamber için ağlayan, milyonlar var,

Resule şiir okuyan çocuk, parmak kadar,

İnandım bu Milleti asla ve asla yıkamazlar.

Baktım, ağlayanlar hep gerçekten ağlıyor,

Ağlayanlar elleriyle yüzlerini hep kapatıyor,

Ağlayanlar gerçek ağlıyor, riyakâr olmuyor,

İnandım bu Milleti asla ve asla yıkamazlar.

Cânım sana fedadır Yâ Resulallah diyorlar,

Sana yapılan  hakaretleri, bize dir, diyorlar,

Senin için cânımızı veririz, ne mutlu diyorlar,

İnandım bu Milleti asla ve asla yıkamazlar.

Kurulan tezgâhların ardı arkası hiç bitmiyor,

Milletimiz çok neciptir, oyunlarına gelmiyor,

Onlar, Şefaat Yâ Resulallah, şefaat diyor,

İnandım bu Milleti asla ve asla yıkamazlar...', 'İnandım bu Milleti asla ve asla yıkamazlar, Ol Peygamber için ağlayan, milyonlar var, Resule şiir okuyan çocuk, parmak kadar, İnandım bu Mil...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asla-yikamazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canparem', 'canparem-murat-demir-37lge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölçtüğünde santim santim boyumu

Bilemedim kazacaksın kuyumu

Ondandır ki akıl denen suyumu

Senden gayri bulandıran olmadı

Şu kocaman dünya bana oldu dar

Seni sevip sana derken canım yar

Hayatımda gözlerimi bu kadar

Senden gayri sulandıran olmadı

Kapanmıyor gönlümdeki  pencerem

Taşacaksa taşsın sevda tencerem

Beni böyle diyar diyar canparem

Senden gayri dolandıran olmadı

Ben mademki kulun oldum bir kere

At dilersen istediğin her yere

Bana zaten siperlerden sipere

Senden gayri yol aldıran olmadı', 'Ölçtüğünde santim santim boyumu Bilemedim kazacaksın kuyumu Ondandır ki akıl denen suyumu Senden gayri bulandıran olmadı Şu kocaman dünya ba...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canparem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün Uyansam', 'birgun-uyansam-yusuf-onder-bahceci-khqj2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün uyansam bu derin uykularımdan,

Aralasam gözlerimi göz kapaklarımdan,

Baksam ki Güneş doğmuş sabahından,

Bir gün uyansam bu derin uykularımdan.

Afyon yutmuş gibiyim, çok fazla uyudum,

Bana yapılanları hâyal ve meyal duydum,

Yıllardır uyuyordum bilki aniden uyandım,

Bir gün uyansam bu derin uykularımdan.

Bir gün uyansam bu derin uykularımdan,

Allah, Allah derim gördüğüm esrarından,

Bize ne kadar mal, mülk düşmüş ondan,

Bir gün uyansam bu derin uykularımdan.

Yıllarca uyumuş, uykudan ne bulmuşum,

Yata, yata hasta oldum, bil yorulmuşum,

Uzun yıllar kaybettim ben mahvolmuşum,

Bir gün uyansam bu derin uykularımdan....', 'Bir gün uyansam bu derin uykularımdan, Aralasam gözlerimi göz kapaklarımdan, Baksam ki Güneş doğmuş sabahından, Bir gün uyansam bu derin uyk...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birgun-uyansam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı-Vefalı Canan', 'sarki-vefali-canan-husam-hasret-rtaa2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkımızda güzelim vefalı bir canansın

Gözlerin tesellisi, gönül okşayan cansın

Bırakma seni seven hicran oduna yansın

Gözlerin tesellisi, gönül okşayan cansın', 'Aşkımızda güzelim vefalı bir canansın Gözlerin tesellisi, gönül okşayan cansın Bırakma seni seven hicran oduna yansın Gözlerin tesellisi, gö...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarki-vefali-canan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taht-ı Belkıs', 'taht-i-belkis-arafat-arik-skmh3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yakıcı cazibe,kaçıp yakalanılan,

Mistik bir efsanenin, ulaşılmaz ecesi.

Sen varılmaz bir ufuk, her kez vardım sanılan,

Ve cevabı kendinde saklı, sır bilmecesi.

Sen koktun derininde, koklanan her çiçeğin,

Damla damla biriktin, aktığın her nefeste,

Kaç kez kanına girdin, hapsettiğin gerçeğin,

Ve kaç can paraladın, çağırdığın her seste.

Kaç ceylan boyun büktü,yokluğunun bahtında,

Kaç umut çare saydı, uğrunda intiharı,

Kaç Belkıs ağırlandı gözlerinin tahtında,

Ve kaç asır arandı, göklerinin baharı.

Efsunlu hikayeler ille de seni yazdı,

Lokman hekim seninle emledi yaraları,

Kaç hüzün, bedeninde sen için mezar kazdı,

Ve kaç matem giymedi, sen diye karaları.

Kaç şair sende buldu, yoğrulduğu mayayı,

Kaç aşık gözyaşıyla senin resmini çizdi,

Kaç günahkar yormadı, sen diye her rüyayı,

Ve kaç Mecnun sen diye, uçsuz çöllerde gezdi.

Ah esrârengiz tutku! nere kaçılır senden,

Göklerin nârı biter, seninki hiç bitmez mi? 

Bu kaçıncı ölüşüm, insaf et çekil tenden,

Ve kaçıncı dönüşüm, çiğnediğin yetmez mi? 

10-ŞUBAT-2006', 'Sen yakıcı cazibe,kaçıp yakalanılan, Mistik bir efsanenin, ulaşılmaz ecesi. Sen varılmaz bir ufuk, her kez vardım sanılan, Ve cevabı kendind...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/taht-i-belkis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı-Olsa', 'sarki-olsa-husam-hasret-qxv10', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda o kadar hoştur sonu kavuşmak olsa

Doyulmaz bin bir gece ondan konuşmak olsa

Acı küsmek ardından tatlı barışmak olsa

Doyulmaz bin bir gece ondan konuşmak olsa', 'Sevda o kadar hoştur sonu kavuşmak olsa Doyulmaz bin bir gece ondan konuşmak olsa Acı küsmek ardından tatlı barışmak olsa Doyulmaz bin bir g...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarki-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tokat Sesi', 'tokat-sesi-aynur-avci-mrt2i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her tokat sesi

Gecenin derinliğinde

Şimşeklerin çakışı gibi

Daha fazlasında izi kalan

Hak edilmeyen davranış biçimindeki

Büyük çığlıkların

Yaşanan bir ömüre yansımasıdır..', 'Her tokat sesi Gecenin derinliğinde Şimşeklerin çakışı gibi Daha fazlasında izi kalan Hak edilmeyen davranış biçimindeki Büyük çığlıkların Y...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tokat-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz değil dertler', 'caresiz-degil-dertler-seref-ozturk-usta-4y3gk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kez daha küstüm

.....darılmadım inan ki

Ne aşkın acısını

.....ne yürek sancısını

Geçen bunca zamanı

.....heba eyledik sanki

Ben seni yitireli

.....kendimi bitireli

Sanma asırlar geçti

.....geçen sade bir an ki

Bilmem nasıl sevmeli

.....nasıl da söylemeli

Ben korudum aşkımı

.....sana bitmez sevdam ki

Biraz gayret etmeli

.....az da çile çekmeli

Çaresiz değil dertler

.....inan sende derman ki

                                                                                   22/02/2006', 'Bir kez daha küstüm .....darılmadım inan ki Ne aşkın acısını .....ne yürek sancısını Geçen bunca zamanı .....heba eyledik sanki Ben seni yit...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/caresiz-degil-dertler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-aynur-avci-u1dmj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alıştım gecenin karanlığına

Alıştım rüzgarın sesine

Sensiz kendime alışamadım

Sabıra vurdum yalnızlığı

Olmuyor -olmuyor..', 'Alıştım gecenin karanlığına Alıştım rüzgarın sesine Sensiz kendime alışamadım Sabıra vurdum yalnızlığı Olmuyor -olmuyor.....', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/olmuyor-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandırıyor Dediler', 'kandiriyor-dediler-yusuf-onder-bahceci-4a1xd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O seni Allah diyerek kandırdı dediler,

O çok riyakâr, mendeburdur dediler,

O parayı, pulu çok çok sever dediler,

Allah adını diyerek kandırıyor dediler.

Allah adıyla kandıran kendini kandırır,

Allah kâlbi temiz olanları tez inandırır,

Yalanlarla kandıranı ateşinde yandırır,

Allah adını diyerek, kandırıyor dediler.

Ben Allah''ı bilirim, başka şey bilmem,

Allah adıyla kandırdığını ben bilemem,

Gözümdeki yaşları dahi ben silemem,

Allah adını diyerek, kandırıyor dediler.

Aldanırsam, Allah''ın adıyla aldanayım,

Zararı yok, Dünya''da biraz ağlayayım,

Bu dertlerimi hangi dostuma yanayım,

Allah adını diyerek, kandırıyor dediler....', 'O seni Allah diyerek kandırdı dediler, O çok riyakâr, mendeburdur dediler, O parayı, pulu çok çok sever dediler, Allah adını diyerek kandırı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kandiriyor-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bırakacağım', 'seni-birakacagim-aynur-avci-flx7w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni çok sevsemde

Aşkına esir olamam

Izdırap oldun bana

Umudum kalmadı sende

Başka sevgiye dönüp

Seni bırakacağım..', 'Seni çok sevsemde Aşkına esir olamam Izdırap oldun bana Umudum kalmadı sende Başka sevgiye dönüp Seni bırakacağım.....', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-birakacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Bacılar Tanıyorum', 'ne-bacilar-taniyorum-yusuf-onder-bahceci-s3vom', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben ne bacılar tanıyorum erkeklerden erkek,

Kalleşlerin gözüne sokuyor binlerce mertek,

Morfin yemiş gibi uyuyanları biz nasıl dürtek,

Ben ne bacılar tanıyorum erkeklerden erkek.

Ben ne bacılar tanıyorum erkeklerden erkek,

Ne erkekler tanıyorum çalarlar da dümbelek,

Hep kalleşlere gülmez elbet, bu kahpe felek,

Ben ne bacılar tanıyorum erkeklerden erkek.

Bıyığına bakıp, bakıp ta bir adam sanmayın,

Şöylece bir laf atın hele bakalım bir yoklayın,

Çaktırmadan kavun gibi altını da bir koklayın,

Ben ne bacılar tanıyorum erkeklerden erkek.

Soytarılar gibi şakalar, dalkavuklar, taklalar,

Vatan, Millet derken içinden parayı sayıklar,

Gezdiğim pazarda çok görürüm salatalıklar,

Ben ne bacılar tanıyorum erkeklerden erkek.....', 'Ben ne bacılar tanıyorum erkeklerden erkek, Kalleşlerin gözüne sokuyor binlerce mertek, Morfin yemiş gibi uyuyanları biz nasıl dürtek, Ben n...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-bacilar-taniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük 4', 'dortluk-4-aynur-avci-zx9cv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kediler tırmalıyor yüreğimi

Aşk acısı gibi mutsuzum

Düşündükçe içime çöker ayrılık

Sıcak öpüşün düğümü

Çözülmez olur..', 'Kediler tırmalıyor yüreğimi Aşk acısı gibi mutsuzum Düşündükçe içime çöker ayrılık Sıcak öpüşün düğümü Çözülmez olur.....', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-4-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Suçluyum Beni Atın Ateşlere (Beni, ateşe suçsuz olanlar atsın; zira bu hak yalnız onlara verildi)', 'ben-sucluyum-beni-atin-ateslere-beni-atese-sucsuz-olanlar-atsin-zira-bu-hak-yalniz-onlara-verildi-zeynal-yaman-r0uyn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mademki gamsız biriyim şu âlemde; 

Ben suçluyum, beni atın ateşlere...

İşte boynum, ferman edin bir kalemde

Ben suçluyum, beni atın ateşlere...

Bombalar emerken gözlerin yaşını

Sorun:''Nasıl yastığa koydun başını? 

Nerde tükettin ekmeğini-aşını? ''

Ben suçluyum, beni atın ateşlere...

''Neden hâlâ gözlerinde yaş yok? '' deyin

Ve ağzınıza ne gelirse söyleyin

Bir de ''İnsan mısın sen? '' diye ekleyin

Ben suçluyum, beni atın ateşlere...

Mademki gamsızlığım zulme destektir

Zalime yardımdır, mazluma köstektir

Utanmaz hâllerin encamı kötektir

Ben suçluyum, beni atın ateşlere...

Sorun bana:''Zulüm nerde, sen nerdesin? 

Neden zalime karşı çıkmıyor sesin? ''

İsterseniz yatırın bıçakla kesin

Ben suçluyum, beni atın ateşlere...

''Bunca feryat var iken nasıl uyudun? 

Şeytan mısın ki sen şeytanlara uydun? ''

Sorun.''İzzeti kendinden nasıl soydun? ''

Ben suçluyum, beni atın ateşlere...

Kirletilen her şeyin vebâli benim 

Bozuldu mu acaba insanlık genim? 

Yanmak için var bin bir çeşit nedenim

Ben suçluyum, beni atın ateşlere...

Hakk''ın huzuruna varınca, ne derim? 

İnanın ki bundandır benim kederim

Mezarımda bile rahatsız pederim

Ben suçluyum, beni atın ateşlere...

Şeytandan kaçar iken şeytana döndüm

Bir güneş idim artık dürülüp söndüm

Ben insanlığı toptan mezara gömdüm

Ben suçluyum, beni atın ateşlere...

Zalimler girerken tarihin kanına 

Sorun:''Neden sahip değilsin ervahına? ''

Sonra götürün cehennemin yanına

Ben suçluyum, beni atın ateşlere...

Zulüm dalga dalga âleme yayıldı

Sağır sultanlar bile duyup ayıldı

Uyuyanlar her yerde suçlu sayıldı

Ben suçluyum, beni atın ateşlere...

Gelin bu Zeynal''ın suçlarını sayın

Sonra ibrettir diye âleme yayın 

Gözyaşlarına bakıp da aldanmayın

Ben suçluyum, beni atın ateşlere...', 'Mademki gamsız biriyim şu âlemde;  Ben suçluyum, beni atın ateşlere... İşte boynum, ferman edin bir kalemde Ben suçluyum, beni atın ateşlere...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ben-sucluyum-beni-atin-ateslere-beni-atese-sucsuz-olanlar-atsin-zira-bu-hak-yalniz-onlara-verildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret', 'nefret-aynur-avci-x8b81', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşlarım hasret kokuyor

Sen yine yoksun

Küskünüm yıldıza aya

Unut artık sevgimi

İstemem dönme geri

Anılar yeter bana

Küskünüm yıllara

Küskünüm,yıldıza aya..', 'Yaşlarım hasret kokuyor Sen yine yoksun Küskünüm yıldıza aya Unut artık sevgimi İstemem dönme geri Anılar yeter bana Küskünüm yıllara Küskün...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nefret-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-murat-onat-uiibb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ANA

Elinde bir tespih yüzünde bir nur

İman huzuru yüzünden okunur

Baktığında sanki melek dokunur 

Beyaz tülbentin çok yakışır sana

Bizi de duanda unutma ana

Kalbinde hep şükür dilinde zikir

Bize misk-i amber elindeki kir

Dolanır yuvanda  bir yaşlı tekir

Uzanıver harlı soba yanına

Bizi de soğukta unutma ana

Cümle alem bir ağızdan bağırsın

İstiğna düsturun kula sağırsın

Beklersin bir melek seni çağırsın

Bir gün gider isen gerçek yurduna

Bizi de dünyada unutma ana 

                                              2005', 'ANA Elinde bir tespih yüzünde bir nur İman huzuru yüzünden okunur Baktığında sanki melek dokunur  Beyaz tülbentin çok yakışır sana Bizi de d...', ARRAY['Türk Edebiyatı','Şiir','Murat Onat']::text[], 8.5, '{"poet":"Murat Onat","poet_slug":"murat-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ana-279-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Ver', 'bos-ver-aynur-avci-68shl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boş ver bırak sevişsin yüreklerimiz

Biz olmadan,engellere aldırmadan

Aşk yoluna baş koymuşuz

Boş ver bırak gitsin,

Gittiği yere kadar

Aldım yüreğimi elime

Yürüdüm mutluluk denizine

Düşsede cemre yere

İbadetim mavinin özgürlüğünde..', 'Boş ver bırak sevişsin yüreklerimiz Biz olmadan,engellere aldırmadan Aşk yoluna baş koymuşuz Boş ver bırak gitsin, Gittiği yere kadar Aldım ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bos-ver-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-mehmet-akif-tiryaki-lx67n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şair olacakmışım

Olmaz olayım be,

Çok mu lazım şairlik

Cep delik yok  metelik

Öyle değilmi be

Söylesene ahretlik.', 'Bir şair olacakmışım Olmaz olayım be, Çok mu lazım şairlik Cep delik yok  metelik Öyle değilmi be Söylesene ahretlik....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sair-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümü Kopardılar', 'gulumu-kopardilar-yusuf-onder-bahceci-83g3x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gülüm vardı, onlar acımadılar ve kopardılar, 

Sadece Gülümü kopardılar kâlbi söküp aldılar,

Seviyorum, çok seviyorum dedim inanmadılar,

Bir gülüm vardı, onlar acımadılar ve kopardılar.

Kâlbinde merhamet olmayanlar, neleri bilirler,

Önder gece, gündüz ağlıyor, belki de gülerler,

Ben ağlarım gözümde ki yaşları kimler silerler,

Bir Gülüm vardı, onlar acımadılar ve kopardılar.

Ben ağlaya, ağlaya Leyla''yı buldum, kurtuldum,

Aradığım Leyla Hak''mış bulunca da unutuldum,

Gördüğüm her güzelde, ben Leyla''ya tutuldum,

Bir Gülüm vardı, onlar acımadılar ve kopardılar.

Şimdi çöllerde gezmiyor gönüllerde geziyorum,

Nerde Leyla kokusu alsam kalbimle seziyorum,

Leyla''sı ile birlikte, ben, Yüce Allah''ı seviyorum,

Bir Gülüm vardı, onlar acımadılar ve kopardılar...', 'Bir gülüm vardı, onlar acımadılar ve kopardılar,  Sadece Gülümü kopardılar kâlbi söküp aldılar, Seviyorum, çok seviyorum dedim inanmadılar, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulumu-kopardilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komik Şiirler', 'komik-siirler-timur-i-likan-vwpaj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'FARELER

Önce fareler terk edermiş

batan gemiyi

Siz siz olun 

en son terk edin

batan gemiyi

  ZÜĞÜRT

Zenginin malı

çenesini yorarmış

züğürdün

Sen zengin ol ki, boşa

yorulmasın hiç çenen

 HAVLAYAN KÖPEK

Havlayan köpek ısırmazmış

Havlarken ısıran köpeğe

dünyâ tarihinde rastlanmadı

şimdiye dek

        BALIK ADAM

Denizden babam çıksa yerim

Ben bir balıkadamın oğluyum da

(22 Şubat 2006/ İstanbul)', 'FARELER Önce fareler terk edermiş batan gemiyi Siz siz olun  en son terk edin batan gemiyi   ZÜĞÜRT Zenginin malı çenesini yorarmış züğürdün...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/komik-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-aynur-avci-l2kjv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her nefes alışımla seni çizdim

Her nefes alışımla seni yazdım

Sildim artık hasreti,özlemi

Izdırap olmasın ayrılık bir daha

Yüreğimden sen kokuyorsun..', 'Her nefes alışımla seni çizdim Her nefes alışımla seni yazdım Sildim artık hasreti,özlemi Izdırap olmasın ayrılık bir daha Yüreğimden sen ko...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-771-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-tamer-kayar-l8t2b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece usul usul pencereme yağarken

Kendi karanlığımda yitirdim yalnızlığımı.

Beni bir de yalnızlığım terketmişti! 

Ondan arda kalan yalnızlığım,

Nerdesin..? 

Beni kendine mahkum etme...', 'Gece usul usul pencereme yağarken Kendi karanlığımda yitirdim yalnızlığımı. Beni bir de yalnızlığım terketmişti!  Ondan arda kalan yalnızlığ...', ARRAY['Türk Edebiyatı','Şiir','Tamer Kayar']::text[], 8.5, '{"poet":"Tamer Kayar","poet_slug":"tamer-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalniz-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahilde Sonbahar', 'sahilde-sonbahar-i-rfan-tansel-turhan-0ni2k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hüzünlü esen rüzgar ve 

Çaresiz savrulan yapraklar...

Balıkçılardan başka kimse yok,

Birde sahile vuran umutlar...

Çık sen de bir tur at şöyle,

Yürü ağır adımlarla kumsalda...

Ama,

Dalgaların silemeyeceği izler,

Bırakma ardında...', 'Hüzünlü esen rüzgar ve  Çaresiz savrulan yapraklar... Balıkçılardan başka kimse yok, Birde sahile vuran umutlar... Çık sen de bir tur at şöy...', ARRAY['Türk Edebiyatı','Şiir','İrfan Tansel Turhan']::text[], 8.5, '{"poet":"İrfan Tansel Turhan","poet_slug":"i-rfan-tansel-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sahilde-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Sokağında Vurdular Beni', 'ask-sokaginda-vurdular-beni-tulay-sustam-dbdag', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne tutunacak

demir parmaklıklarım vardı

ne de hayat duvarına sarılacak

sarmaşıklarım

bir saçların vardı

bir saçların...

bir teline

gece / kondu

gecenin üşüyen elleriyle sardım seni', 'ne tutunacak demir parmaklıklarım vardı ne de hayat duvarına sarılacak sarmaşıklarım bir saçların vardı bir saçların... bir teline gece / ko...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-sokaginda-vurdular-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekçe', 'erkekce-harun-kaya-3-nv3h5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlıktan korkup gözünü kapamak gibidir aşka sırtını dönmek,

Baksanda bakmasanda aşk hep orada durur.

Sen erkekçe göğsünü gerip yüzünü dönmezsen,

O seni kalleşçe sırtından vurur...........

           Harun KAYA

   (c)        bu şiirin her türlü telif hakkı şairin kendisine ve/veya temsilcisine aittir', 'Karanlıktan korkup gözünü kapamak gibidir aşka sırtını dönmek, Baksanda bakmasanda aşk hep orada durur. Sen erkekçe göğsünü gerip yüzünü dön...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/erkekce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Teli Yar Çalıyor', 'gonul-teli-yar-caliyor-arzu-dincer-xslnq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yar, yaram olmuş kanıyor,

Kan’a zülfüyar bulanıyor,

Gönül teli titriyor.

Yarin bakışları bade,

Badenin içinde hale,

Gönül teli titriyor.

Yar, kelamında iğne,

İğnenin battığı yerde,

Gönül teli titriyor.', 'Yar, yaram olmuş kanıyor, Kan’a zülfüyar bulanıyor, Gönül teli titriyor. Yarin bakışları bade, Badenin içinde hale, Gönül teli titriyor. Yar...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gonul-teli-yar-caliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben,Güz Ve Şehirler...', 'ben-guz-ve-sehirler-murat-karasu-wqu12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzümde buruk bir tebessüm

Her imza yalnızlık çizgisi

Diyar diyar gezer gözlerim

Hasretlerde saklıdır hüzün.

Hangi mevsim durulur yüzün

Ve hangi saat sürülür yüreğim? 

Hep banamı bu kör akşamlar

Bu sokaklar...

Bu girdaplar...

Son sözümü söylemedim daha

Daha kalemimi kırmadım

Ve yüzümü dağlara dönmedim.

Güz gelir ben giderim

Şehirler gider.

Ben,güz ve şehirler...', 'Yüzümde buruk bir tebessüm Her imza yalnızlık çizgisi Diyar diyar gezer gözlerim Hasretlerde saklıdır hüzün. Hangi mevsim durulur yüzün Ve h...', ARRAY['Türk Edebiyatı','Şiir','Murat Karasu']::text[], 8.5, '{"poet":"Murat Karasu","poet_slug":"murat-karasu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-guz-ve-sehirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç Dikelim', 'agac-dikelim-mustafa-bilgili-jchre', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Muhabbet besleyip güzel vatana,

Gelin her tarafa ağaç dikelim.

Saygı gösterelim şehit yatana,

Her şehit için bir ağaç dikelim.

Sevgimiz her zaman kalıcı olsun,

Vatanın her yanı mis gibi koksun,

Bizden sonra gelenler hazine bulsun,

Gelin her tarafa ağaç dikelim.

Ormanı bol olan ülkede kıtlıkta olmaz,

Yağmur eksik olmaz,güllerde solmaz,

Ağacın kıymetini dikmeyen bilmez,

Gelin her tarafa ağaç dikelim.

Bu vatanın kalkınması,refahı için,

Tek çare vardır bence; yeşili seçin,

Mevla uzun ömür versin her çocuk için,

Gelin her tarafa ağaç dikelim.

Bu vatan hepimizin sahip çıkalım,

Cehaleti temelinden yıkalım,

Bir çicekle yaz gelirmi demiş atalar,

Gelin her tarafa ağaç dikelim.

                                                   17.01.1997', 'Muhabbet besleyip güzel vatana, Gelin her tarafa ağaç dikelim. Saygı gösterelim şehit yatana, Her şehit için bir ağaç dikelim. Sevgimiz her ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/agac-dikelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşluk', 'kusluk-harun-kaya-3-v5p66', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülerken güller açsın avuçlarında,

umutsuzluk kapını çalan son komşun olsun.

geç kalmışlığın pişmanlığını tattırmasın rabbim sana,

her gülümseyişinde vakit hep kuşluk olsun.

         Harun  KAYA

   (c)   bu siirin her türlü telif hakkı şairin kendisine ve/veya temsilcisine aittir', 'Gülerken güller açsın avuçlarında, umutsuzluk kapını çalan son komşun olsun. geç kalmışlığın pişmanlığını tattırmasın rabbim sana, her gülüm...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kusluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlâdiyelik Şiir', 'evl-diyelik-siir-timur-i-likan-xudwa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir şiir yazdım ki senin için

oku oku hiç eskimez

hiç yıpranmaz bile

İlk günkü tâzeliğini korur her zaman

fırından yeni çıkmış

dumanı üstündeki 

bir ekmeğin tâzeliğinde

Naftalin filan da istemez öyle

Derin dondurucuya da ihtiyâcın olmaz

İstediğin kadar sakla

Ömür boyu garantili bu şiir

Evlâdiyelik senin anlayacağın

(22 Şubat 2006/ İstanbul)', 'Öyle bir şiir yazdım ki senin için oku oku hiç eskimez hiç yıpranmaz bile İlk günkü tâzeliğini korur her zaman fırından yeni çıkmış dumanı ü...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/evladiyelik-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüyüm', 'oluyum-harun-kaya-3-j938u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarısını değil hepsini göndereyim sana kalbimin.

yokluğunda deliyim.

kalbim olmayınca kalpsizim ama,

sen olmayınca ölüyüm.

                         Harun KAYA

  (c)   bu şiirin her türlü telif hakkı şairin kendisine ve/veya temsilcine aittir', 'Yarısını değil hepsini göndereyim sana kalbimin. yokluğunda deliyim. kalbim olmayınca kalpsizim ama, sen olmayınca ölüyüm.                  ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/oluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum yakmak', 'mum-yakmak-harun-kaya-3-zbwr3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapatma gözlerini korkutmasın seni karanlık,

kurtulmak kolaydır ondan bir mum yakmak kadar.

utanma doğrularından zordur adam gibi adamlık,

yüreğinle çık yola ve git gide bildiğin yere kadar.

    Harun KAYA', 'Kapatma gözlerini korkutmasın seni karanlık, kurtulmak kolaydır ondan bir mum yakmak kadar. utanma doğrularından zordur adam gibi adamlık, y...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mum-yakmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay''ı Özleyen Kurtlar', 'ay-i-ozleyen-kurtlar-nal-n-yildiz-1wco0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay''ı özleyen kurtlar gibi

Hasretten kudurduğumuz,

Dağınık, ağır başlarımızı kaldırıp

Gecenin yüzüne karşı saatlerce uluduğumuz

Ve belki de hiç kavuşamayacak

Sürgünzedeler olduğumuz

Bilinir tarafımızdan...

Durmadan debeleniriz

Bu çamur deryasında,

Bir kalp mesafesi uzaktayız aslında

Varla yok arasında

Buzdan bir buhar gibi

Uçuşan seferileriz,

Ayın karanlık yüzü

Silinir tarafımızdan

Açlıkla, okşanmayan başlarımızla

Ve yüreğimize saplanan o  gümüş kurşunla

Terbiye edildik

Boynumuzda hayatın diş izleri

Tırnaklarımızda kan ve toprak

Yırtsak da kendimizi

Utanmayıp avazımız çıktığı kadar bağırsak da

Yankımaz yalnızlık burçlarında sesimiz 

Bilinir tarafımızdan...

Ay, 

Ay...', 'Ay''ı özleyen kurtlar gibi Hasretten kudurduğumuz, Dağınık, ağır başlarımızı kaldırıp Gecenin yüzüne karşı saatlerce uluduğumuz Ve belki de h...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ay-i-ozleyen-kurtlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufuk Çizgisi', 'ufuk-cizgisi-nuray-acar-vloje', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ufuk çizgisine bak diyorsun

Ufku bilmeyen ne anlasın

Anlayacağı gözlerindeki anlamı çözmek iken

Bir ufuk çiz şöyle başparmağın ile ileri doğru

Ucu semaya ulaşan

Bir ışın olsun illaki de anlat en detaylısından

Kazısın hafızasına

Adın aklına geldiğinde

Ufuk belirsin hafızasında ve başparmağını 

Gayri ihtiyari uzatsın  semaya

Hiç çekinmeden ileriye

Aklımız bize oyunlar oynasın

Gözlerimize bu filmi izletsin

Yaşam gelip geçiyor iken 

Ufuk çizgisi kaybolmasın

Düşüncelerimizden

Düşünmek için sıra bekleyen

İçimizde neler varsa 

Bir bir kanatlansın 

Semaya doğru 

Ufuk çizgisinde kaybolana dek

İzlesin

İzletsin

Berraklığını yitirmeden', 'Ufuk çizgisine bak diyorsun Ufku bilmeyen ne anlasın Anlayacağı gözlerindeki anlamı çözmek iken Bir ufuk çiz şöyle başparmağın ile ileri doğ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ufuk-cizgisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni', 'beni-harun-kaya-3-baptu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gök çökecek üstüme yutacakta kara toprak,

Her şeye rağmen deliler gibi seveceğim seni,

Zaten yok aklımla koyacağım boynumu ortaya,

Kurban edeceğim yollarına beni.

        Harun KAYA

(c)       Bu şiirin her türlü telif hakkı şairin kendisine ve/veya temsilcisine aittir', 'Gök çökecek üstüme yutacakta kara toprak, Her şeye rağmen deliler gibi seveceğim seni, Zaten yok aklımla koyacağım boynumu ortaya, Kurban ed...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/beni-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe', 'serce-nal-n-yildiz-xgd2x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir serçe tıpırdıyor tanıdık

Üstelik doğuştan 

Kanadı kırık

Ona seni anlatıyorum

Tek kanatla uçuyor

Karlı dağlar aşıyor

Seninse penceren kapalı,

İnanmazsan aç bak

Baharı kırık kanatlı bir serçe getirdi', 'Bir serçe tıpırdıyor tanıdık Üstelik doğuştan  Kanadı kırık Ona seni anlatıyorum Tek kanatla uçuyor Karlı dağlar aşıyor Seninse penceren kap...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/serce-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçiyor Olacak', 'geciyor-olacak-gul-yazganarikan-3x2aq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Süreceğim seni bu topraklardan,

Çetin bir savaş olacak 

Ordularım seni yenecek elbet

Taş üstünde taş kalmayacak....

Süreceğim seni, 

Ardına bakmadan kaçacaksın,

Sözlerini de vereceğim ateşe,

Gözlerini de vuracağım tam ortasından

Tek bir iz, tek bir nefes

 ve bir yalandan ibaret olacaksın...

Öyle kara ki gözüm korkmuyorum senden

Yüzleşeceğim o onursuz yokluğunla

Kalleş kurşunların işlemeyecek bağrıma

Çelik bir yelek gibi giyeceğim ihanetlerini üstüme

Ve vuracağım seni gülüyorken yüzüne...

Süreceğim öyle bir gidişin olacak ki....

Yalpalacak bacakların, 

İçime kurduğun o hasret köyünü de tutuşturacağım

Tutuşacak sana dair ne varsa,

Alev alev yanacak hatıralarım

Ve alev alev yanacak bağrım

Ağlamayacağım sen giderken...

Süreceğim seni toprağımdan

Silip atacağım ne var ne yok, yakıp yıkacağım, savuracağım rüzgarın kollarına

Bu topraklarda esir olarak bile duramayacaksın sen...

Sürgün sevdaların en ağır işkencelerine sürüyorum seni ben 

Şafak karanlığı parçalarken göğsünden,

Geçiyor olacak deli bir sevda gökyüzünden...', 'Süreceğim seni bu topraklardan, Çetin bir savaş olacak  Ordularım seni yenecek elbet Taş üstünde taş kalmayacak.... Süreceğim seni,  Ardına ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/geciyor-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma Düştüğünde', 'aklima-dustugunde-i-lknur-cekici-2mj1r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklıma düştüğünde

Geceme katık ettim seni

Günüme meze

Sonra......

Çıkardım hüznü takvimlerden

Sıyrıldım karanlıktan

Uyandım umuda

Yetmedi.....

Tebessüm iliştirdim yüzüme

Sevda ekledim şiire

Gözlerini gördüm her yeşilde

Sonunda....

Aşk ektiğim toprak

Hasat verdi mutluluğa

Soyundu yüreğimiz tertemiz yarınlara', 'Aklıma düştüğünde Geceme katık ettim seni Günüme meze Sonra...... Çıkardım hüznü takvimlerden Sıyrıldım karanlıktan Uyandım umuda Yetmedi......', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aklima-dustugunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar Çiçeğim', 'nar-cicegim-kibar-tavasav-ozme5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şey bomboş 

Bir gıdım sevgi gerek yüreğine 

Milattan önce bir obada 

Atımla dur durak bilmeden karış, karış gezen bir veliyim 

Gözlerini arayan 

Dilime konacak bahar çiçeklerindeki polenlerinden 

Bal özleri toplayan bir deliyim 

Aşk yanıktır bende yanık ben böyleyim 

Bir tas süt verir misin bana obanın yürekli kızı 

Kaldın gözlerimin aynasında 

Gece gündüz seni özleyen biriyim 

Nar çiçeğim 

Sen istersen ben kendimi de unuturum, ellerinin kokusunu da 

İki damla yavru gözyaşı dökerim toprağa 

Unuturum kendi kendimi 

Sen istersen ben taşı sıkarım yüreğimde suyunu çıkarmak için 

Yalnızlıkla konuşurum bir ömür boyu 

Dere kenarında bir çakılın yosunu olurum 

Çiçek olurum kırda, bayırda 

Gökyüzünde ağlatan güneş olurum baharlarda 

Yollara kaldırım taşı olurum 

Sen istersen gözlerinin yaşı olurum pınarında 

Sarkarım kirpiklerine tutunup da gözlerinden 

Sen istersen ben özlem olurum yüreğinin akan derinlerinden 

Mavi bulut olurum rüzgarla raks eden 

Bir karınca olurum gönlünün vadilerine kış gelmeden 

Ağustos böceği olurum yaz sıcaklarında meltem yeli püfür, püfür eserken 

Sen istersen ben aşk gülü olurum kalbinin kapakçığını tıklarken 

Saz olurum 

Söz olurum 

Şiir olurum gözlerine damla, damla düşerken 

Sen istersen bir şarkı olurum diline söylenir belki 

Yıldız olurum gökyüzüne, delinir 

Yağarım belki yeryüzüne 

Sen istersen ben bir şiir olurum kalbinin dudaklarına 

Çatlamaz,  yumuşacık dokunurum 

Sen beni söylerken gülümsetirim 

Sen istersen ben yok olurum yerin dibine 

Magma beni yakar, kemiklerim çıtır, çıtır erir döner aleve 

Sen istersen bir çisi olurum kalbine, serinletir püskürmelerim 

Ben gömüleceksem senin altına gömülmeliyim 

Ben bir nar ağacı, sense benim çiçeğim 

Nar çiçeğim', 'Her şey bomboş  Bir gıdım sevgi gerek yüreğine  Milattan önce bir obada  Atımla dur durak bilmeden karış, karış gezen bir veliyim  Gözlerini...', ARRAY['Türk Edebiyatı','Şiir','Kibar Tavasav']::text[], 8.5, '{"poet":"Kibar Tavasav","poet_slug":"kibar-tavasav","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/nar-cicegim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- Hiç bir aşk cezasız kalmaz...-', 'hic-bir-ask-cezasiz-kalmaz-oner-kaciran-k87kv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alışmalısın

bırakıp gidenlere

Sana düşen unutmak

Yanmaz kalbin en azından

damarlarındaki kanı çeken

aşka

Alışmalısın

geride kalanlarla 

hayatın sana sunduklarına

Bu öyle bir yaşamak ki

Bir daha dönmeyecek olanın özlemi

kahreder insanı

El ayak çekilir yürekten

Artar bir kat çektiğin acı

vazgeçemezsin beklemekten

Bir kucak dolusu kaçış

....terkedilmişlik 

........aldatılmışlık

ve,

geride kupkuru bir kalakalmışlık

Öğrenirsin,nasıl bir şeydir

Görmediğin,koklamadığın

dokunmadığın,ulaşamadığın

birine aşık olmak 

ne demek

Alışırsın aşkını kaybetmeye

Anlarsın önemli olmadığını 

ki, 

çok da önemli değildir

aşkın kendisidir 

aşık olunan

Bir kez öğrendin mi aşık olmayı

daha delice aşklar bulur seni

çekilir canın tüm uzuvlarından

Alışırsın aşk acısına

bağımlı olursun.

Sevgiliyi yok edebilirsin

Sevgini  asla

Değişen sen olursun

Ve,

Anlarsın,

öğrenirsin ki 

hiç bir aşk cezasız kalmaz....

05.02.2006 

Hiçleşmenin acısı sarar..', 'Alışmalısın bırakıp gidenlere Sana düşen unutmak Yanmaz kalbin en azından damarlarındaki kanı çeken aşka Alışmalısın geride kalanlarla  haya...', ARRAY['Türk Edebiyatı','Şiir','Öner Kaçıran']::text[], 8.5, '{"poet":"Öner Kaçıran","poet_slug":"oner-kaciran","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/hic-bir-ask-cezasiz-kalmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun İşi Bitmiştir', 'onun-i-si-bitmistir-yusuf-onder-bahceci-mobyk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir insan ki aşk şiirleri yazıyorsa,

Yazdığı şiirleri, okuyup ağlıyorsa,

Şiirleri hep dertli, dertli oluyorsa,

Onun işi bitmiştir, sevilmemiştir.

Allah''ım neden, neden diyorsa,

Hep düşünüyor içini çekiyorsa,

Eli iki de bir telefona gidiyorsa,

Onun işi bitmiştir, sevilmemiştir.

Hâyali gözünün önüne geliyorsa,

Yüzünde, tebessüm beliriyorsa,

Arada bir kahkahayla gülüyorsa,

Onun işi bitmiştir, sevilmemiştir.

Ellerini birden önüne uzatıyorsa,

Gözleri ufuklara dalıp gidiyorsa,

Sevdiğini de böyle eller alıyorsa,

Onun işi bitmiştir, sevilmemiştir...', 'Bir insan ki aşk şiirleri yazıyorsa, Yazdığı şiirleri, okuyup ağlıyorsa, Şiirleri hep dertli, dertli oluyorsa, Onun işi bitmiştir, sevilmemi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/onun-isi-bitmistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtlar Sofrası', 'kurtlar-sofrasi-cenk-aksal-6pcue', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kızgın bir çekirge sürüsü üşmüş,

kan kızılı akan nehrimin üstüne..

oltamı salladığım iskelede:

yaralı ceylan iniltileri,içli içli,

sırtımdaki urbam sırılsıklam,

ağır aksak koşmaya çalışıyorum,

neredesin ey sevgili:

yüreğim şimendifer misali,

ha patladı ha patlayacak,

ben sana demedim mi:ceylanım,

ansız ayrılıklar divane eder beni..

ve sende düşersin kurtlar sofrasına:

kanatırlar seninde yüreğini,

kışı geçtik ilkbaharda mevsim,

ben bittim,sen tükenmişsin..

kızgın çekirge sürüsü giderse,

kan kızılı nehrimin üzerinden,

ve kurtlar yeni bir sofra bulursa:

sarmak için yaralarını ceylanımın

döneceğim mutlaka bilesin,

yemyeşil akacak nehrimin kenarına...', 'kızgın bir çekirge sürüsü üşmüş, kan kızılı akan nehrimin üstüne.. oltamı salladığım iskelede: yaralı ceylan iniltileri,içli içli, sırtımdak...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kurtlar-sofrasi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimileri', 'kimileri-baris-polat-m72if', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimileri için,

Bir tiyatroda oynanan oyun gibi

Kimileri için,

Sirkte komiklik yapan palyaçoydu sana olan sevdam

Zaman bile için için gülüyordu

Senin lehine döndürüyorum kadranımı diye

Fakat bilmiyordu geçen her dakika her saniye,

Yüreğim yüreğinle iç içe geçiyor

Ama insanlar ve zaman bilmesede

Allah biliyor sana olan sevdamı

Gürül gürül yanan alevli aşkımı

Seni seviyorum,seviyorum diye', 'Kimileri için, Bir tiyatroda oynanan oyun gibi Kimileri için, Sirkte komiklik yapan palyaçoydu sana olan sevdam Zaman bile için için gülüyor...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimileri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Mumum', 'kirmizi-mumum-hulya-endogan-b2i0h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çiçek şekilli kırmızı mum

Gümüş çizgili tabağıyla bütün olan mum

Sensin benim

Keyfim,neşem

Benim özışığımsın

Sensiz ben karanlıktayım

Nefes aldığım mekanın ışığısın

Dün yanıyordun, bugün ve yarın da yanacaksın

Yanınca ışığını saçan alevim

Kaçıyor tüm karanlık senden

Hiç bir muma benzemiyorsun

Sahip olduğun her ışığın hakkını veriyorsun

Sen böylece asil ışığına ulaşıyorsun

Sonsuz kırmızılığında yüzüyorsun

Dalgalara kapılmadan, ışığına sahip çıkıyorsun', 'Çiçek şekilli kırmızı mum Gümüş çizgili tabağıyla bütün olan mum Sensin benim Keyfim,neşem Benim özışığımsın Sensiz ben karanlıktayım Nefes ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Endoğan']::text[], 8.5, '{"poet":"Hülya Endoğan","poet_slug":"hulya-endogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirmizi-mumum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masajı Bitir Sevgilim', 'masaji-bitir-sevgilim-sevinc-kavuk-1ypg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vücut yüzeyindeki el, elektrik, su ile bir de

Buna telepatiksel o bir duyum da katılırsa

Hem ne hoş olur çesitli işlemler biçimiyle 

İyileştirme bakım yöntemi denilmiş buna

Ovma, ovuşturma, bu duyumsanan...

Çağırırken acaba masör mü denilsinmiş

Sevgili, arkadaş, hemcinsim de oluruna

Bu bir dokunumla öylesine sohbet arası

Okşanma, sevgiler, hem duyumlanır...

Kolonya, pudra olsun varsın malzeme

İkinci bir masajı daha istesem kremle

Bu rüyamın hakkını gerçek düşlersem

Yorma, sorma da! her an yaşanır....

Tadı damağımda kalmalı bir de üstüne

Türk kahvesi yudumlarken de keyfime 

Katık edersen bir şiir, bir şarkı sohbete

Dokun dokunabileceğin kadar ruhuma! 

Dolaşılırsa bu huzurla şöyle sahil, şehir

Elim elinde kalsın, dola kolunu ne olur! 

Sar ince belime seni duyumsamalıyım

Masaji bitir sevgilim al bedenim senin! 

18.02.2006', 'Vücut yüzeyindeki el, elektrik, su ile bir de Buna telepatiksel o bir duyum da katılırsa Hem ne hoş olur çesitli işlemler biçimiyle  İyileşt...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/masaji-bitir-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-baris-polat-70aev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tarih kitaplarında okunmasını isterdim

Sana olan sevdamı,sana olan sevgimi

Senin için neleri göğüslediğimi,yendiğimi

Gazetelere manşet olmak isterdim

Sevdiği için çıldıran,ağlayan kişi diye

Kutuplarda buz olmak isterdim.Senin''de güneş

Sana baktıkça nasıl eridiğimi görmen için

Ayyaş olmak isterdim,sokaklarda,

Naralar atarak aşkımı haykırmak için

Baş ucuna yastık olmak isterdim,

Üzerine yorgan,yorgun gecelerini,

hafifletmek isterdim.', 'Tarih kitaplarında okunmasını isterdim Sana olan sevdamı,sana olan sevgimi Senin için neleri göğüslediğimi,yendiğimi Gazetelere manşet olmak...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isterdim-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ferman Sende', 'ferman-sende-sahin-erturk-knvdo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ferman sende güzelim

Emir ver,dağ deleyim

Emir ver,kent yakayım

Tatmin olamam dersen

Ferman eyle öleyim

(22.02.2006)', 'Ferman sende güzelim Emir ver,dağ deleyim Emir ver,kent yakayım Tatmin olamam dersen Ferman eyle öleyim (22.02.2006)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ferman-sende-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözemediğim Duygularım Düşüncelerim', 'cozemedigim-duygularim-dusuncelerim-yusuf-onder-bahceci-ilofx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çözemediğim duygularım, düşüncelerim, şiirlerim,

Soruyorum neden kendimi kendimi heder ederim,

Senden ayrılır giderim, fakat kendi kendimi yerim,

Çözemediğim duygularım, düşüncelerim, şiirlerim.

Ellerin ellerimde, hâyal ederken engin denizlerde,

Gözlerin gözlerimde, aklım ise hep sende, sende,

Dünya bana vız gelir, sen istersen haydi ölelim de,

Çözemediğim duygularım, düşüncelerim, şiirlerim.

Ben neden bu hâle geldim, bir türlü anlamıyorum,

Arkadaşlarına türlü şakalar eden, lider olan, ben,

Şimdi hayata küsen, karaları giyen, matem eden, 

Çözemediğim duygularım, düşüncelerim, şiirlerim.

Duyguları, düşünceleri, şiirleri teraziye koyalım biz,

Duyguların ve düşüncelerin altında nasıl da eziliriz,

Şiirleri yazarız, acaba,  biraz kendimize mi geliriz,

Çözemediğim duygularım, düşüncelerim, şiirlerim....', 'Çözemediğim duygularım, düşüncelerim, şiirlerim, Soruyorum neden kendimi kendimi heder ederim, Senden ayrılır giderim, fakat kendi kendimi y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cozemedigim-duygularim-dusuncelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beynini Okudum Ve Yazdım', 'beynini-okudum-ve-yazdim-tulay-sustam-vjt9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o dediğin

herhangi biri

herhangi biri o

benim için

o dedikleri 

sensin

sen dediğim ben

ben seni(ni)  m', 'o dediğin herhangi biri herhangi biri o benim için o dedikleri  sensin sen dediğim ben ben seni(ni)  m...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beynini-okudum-ve-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Lal', 'yalnizlik-lal-meral-yagcioglu-xkqcc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızlık ses vermiyor

siyahlara bürünmüş

cehennem zebanisinin kucağında

cenderedeyim sanki

gecenin zift karasında

paylaşmak istedim iyi kötü ne varsa

sohbet etmekti tek niyetim

seslendim 

“yalnızlık söyle neden 

bu ömür törpüsü susuşun,sessizliğin”

çağırdım çığlıklarla 

kar etmedi

ağladım yükseldi hıçkırıklarım ayyuka

ömrüm çürüdü

ses vermiyor

inatla ses vermiyor yalnızlık

duvara vurdum başımı

cevaben tok bir ses 

taç yaptı başıma acıyı

oysaki  neler ummuştum hayattan

yalnızlıktan çıt  yok

ritmini kaybetmiş olmuş lal

el vermiyor

ulaşmak için aydınlığa 

birlik olmuş kaderle

örüyor ağını 

gömüyor dehlizlere

çizmiyor kalem resmini mutluluğun

göz görmüyor, karanlık tuval

karalıyorum hayalen

mürekkebim kızıl

kan damlıyor kalem

ağlıyor şiir

yazıyorum çaresiz

		18/10/2005', 'yalnızlık ses vermiyor siyahlara bürünmüş cehennem zebanisinin kucağında cenderedeyim sanki gecenin zift karasında paylaşmak istedim iyi köt...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yalnizlik-lal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilk bahar meltemi', 'ilk-bahar-meltemi-mustafa-topatan-sg269', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ilk bahar meltemiyle geldin

zemheri firtinalar kopardin icimde

sultan tahtina oturdun gönlümün

yok ettin icimdeki yarenlerimi', 'ilk bahar meltemiyle geldin zemheri firtinalar kopardin icimde sultan tahtina oturdun gönlümün yok ettin icimdeki yarenlerimi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Topatan']::text[], 8.5, '{"poet":"Mustafa Topatan","poet_slug":"mustafa-topatan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilk-bahar-meltemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllardır Bekliyorum İstasyon da', 'yillardir-bekliyorum-i-stasyon-da-yusuf-onder-bahceci-2ffd0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllardır bekliyorum aynı istasyonda, aynı peronda,

Bekliyorum haber yok, haber yok onda, telefonda,

Benim bu beklemelerim, hep sevdiğimin uğrunda,

Yıllardır bekliyorum aynı istasyonda, aynı peronda.

Kaç tren geldi ve kaç tren gitti bu loş peronlardan,

Benim beklediğim trense yârimi bana geri getiren,

Tren bekliyorum bir türlü gelmiyor, işte beni bitiren,

Yıllardır bekliyorum aynı istasyonda, aynı peronda.

Yıllar sonra, beklenen tren geldi, yolcuları hep indi,

Bakışlarım inenlerde gezindi, beklenen, o değildi,

Gözlerim mahcup, mahcup yine hep yerlere eğildi,

Kaç tren geldi ve kaç tren gitti bu loş peronlardan,

Peronda sırtıma deyen bir ele, işte o geldi dedim,

Şöyle yavaşdan korkarak başımı geriye çevirdim,

Abi be kusura bakma, ateşin varmı acaba, diyen, 

Kaç tren geldi ve kaç tren gitti bu loş peronlardan...', 'Yıllardır bekliyorum aynı istasyonda, aynı peronda, Bekliyorum haber yok, haber yok onda, telefonda, Benim bu beklemelerim, hep sevdiğimin u...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yillardir-bekliyorum-istasyon-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy feryadımı', 'duy-feryadimi-selahattin-yetgin-5o7jx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'uçup savrulup üstüme kondu küllerin

günlerce yalnızlığı çizdiğim kıyılarımda

aydınlığı umarken ansızın ışıksız kaldım

sen karanlığa açılan tüm kapılarını açtın

yüzümü döndürüp karanlığına

nefesine yürüdüm el yordamıyla

ellerini düşündüm başka kollarda

dudakların kim bilir hangi dudakta

çürümüş çiğnenmiş çıplaklığımla

korkularımla yalnız başıma kalınca

yenik gövdemin üzerinden şimdi

çiğneyerek sen de geç üzerimden

sen ki gece gündüz hep aynı sevdada

bir bakışınla mevsim ötesi coşkuyla

taşın ve toprağın en özündeki sevdayla

şubat ayazında nehirlere salardın beni

zaman mor günlere döndü sonunda

çürüdü bahçemdeki emsalsiz elmalar

delişmen günlerin aklarına büründüm

şimdi yürür içimde sinsi bir korku

kulak ver gümbürtüsüne yüreğimin

duy artık sana olan son feryadımı

dinle içimde koşturan deli sevincimi

bir yıkık evde bulmadan bedenimi', 'uçup savrulup üstüme kondu küllerin günlerce yalnızlığı çizdiğim kıyılarımda aydınlığı umarken ansızın ışıksız kaldım sen karanlığa açılan t...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duy-feryadimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdiki Zaman...', 'simdiki-zaman-mine-kartal-oozx6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tükettik mi kelimeleri? 

Yoksa düşünceler mi fakirleşti? 

Konuşmadan,

Öyle sessiz sedasız bakışmalarda mı zaman? 

Yoksa sessizliğin sesi mi konuşan? 

Duygular mı kayboldu? 

Yoksa kaybetme korkusumu başlayan?', 'Tükettik mi kelimeleri?  Yoksa düşünceler mi fakirleşti?  Konuşmadan, Öyle sessiz sedasız bakışmalarda mı zaman?  Yoksa sessizliğin sesi mi ...', ARRAY['Türk Edebiyatı','Şiir','Mine Kartal']::text[], 8.5, '{"poet":"Mine Kartal","poet_slug":"mine-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/simdiki-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birisi Beni Arıyor', 'birisi-beni-ariyor-talha-sagiroglu-arc65', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şeyimi döktüm ortaya

           Yanılgılarımı sorguladım korkmadan

               Çoğu şeyi bulamadan kaybettim,

               Doğrular beni arıyor.

    

           Islanan sadece gözlerim değil

           Bütün çiçeklerde ıslanmış,

               Bak bahçelere, her şey karışmış

               Yağmur damlaları beni arıyor.

           Sokağın başını tutmuşlar

           Kafamı taşlara vurmuşlar

               Herkes kızmış, darılmış bana

               Mahalleli beni arıyor.

           Annem kesmiş muhabbeti

           Her kadın çıkmazda bana karşı,

               Uykularım ağır geliyor yinede 

               Annem beni arıyor.

           Ortada bir kız dolaşıyor

           Saçları siyah, simsiyah

               Gözlerini daha göstermedi

               Elinde bir kağıt, dolaşıyor

           Sanki kalbi çırılçıplak

           Ve sanki duygu namına bir şey yok

     

           Anlamasam da bir şeyler duyuyorum

           Göremesem de kokusunu alıyorum

               Gözlerini göremesem de ağlıyorum

               Birisi yana döne beni arıyor…', 'Her şeyimi döktüm ortaya            Yanılgılarımı sorguladım korkmadan                Çoğu şeyi bulamadan kaybettim,                Doğrular...', ARRAY['Türk Edebiyatı','Şiir','Talha Sağıroğlu']::text[], 8.5, '{"poet":"Talha Sağıroğlu","poet_slug":"talha-sagiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/birisi-beni-ariyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Şiir Neye Yazılır', 'en-guzel-siir-neye-yazilir-yusuf-onder-bahceci-h3bx6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En güzel şiirler kârlı, buzlu, ulu dağlar için mi yazılır,

En güzel şiirler, bilmem uzayan yollar için mi yazılır,

En güzel şiirler yaylalar ve çobanları için mi yazılır,

En güzel şiirlerde acaba kimlere methiyeler dizilir.

En güzel şiiri benim yazdığımı asla iddia edemem,

Seni çok seviyorum be Gülüm bırakıp ta gidemem,

Deli gönlüm abdal olmuş sana şiirler söyleyemem,

En güzel şiirlerde acaba kimlere methiyeler dizilir.

Güzel, en güzel şiirler acaba neler, neler için yazılır,

Seven sevdiğini çok sevmiş se, acaba niye kaçılır,

Seven kâlbimden, seven kâlbine ah sevgisi saçılır, 

En güzel şiirlerde acaba kimlere methiyeler dizilir.

Şiirler yazalım böyle gönüllerin dilinden ve elinden,

İnsan nasıl zarar görür ki çok sevdiğinin yüzünden,

İçimde hiç bir ümit kalmadı diyorum hep hüzünden,

En güzel şiirlerde acaba kimlere methiyeler dizilir.', 'En güzel şiirler kârlı, buzlu, ulu dağlar için mi yazılır, En güzel şiirler, bilmem uzayan yollar için mi yazılır, En güzel şiirler yaylalar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/en-guzel-siir-neye-yazilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damla Su Bile Değilim', 'bir-damla-su-bile-degilim-talha-sagiroglu-rcr88', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir resim çiz yüreğine 

				Misal; 

         Sen İstanbul`sun yüreğinde bozkır garibi

         Ama ben Ankara değilim

         Sen martılarsın denizsin

         Ben bir damla su bile değilim

         Bir avuç toprak bul yüreğime gömmek için

         Bir şeyleri			misal; 

         Sen Piyer Loti de çay keyfi

         Ben dibinde mahzun Halice refakatçi

                             Tıklım tıklım bir mezarlık.

         Sen Konur sokakta kaldırım taşları

         İnsanların her daim yüreğini çiğnediği

         Ben varoşların yoksulluk gizli sokakları

         Bulutlar elli sene sonrası

                   Saçlarının sonradan görme akları

         Hem sen İstanbulsun denizin ılıklığında

         Ama ben Ankara değilim

         Sen martılarsın denizsin

         Ben bir damla su bile değilim.', 'Bir resim çiz yüreğine  				Misal;           Sen İstanbul`sun yüreğinde bozkır garibi          Ama ben Ankara değilim          Sen martılars...', ARRAY['Türk Edebiyatı','Şiir','Talha Sağıroğlu']::text[], 8.5, '{"poet":"Talha Sağıroğlu","poet_slug":"talha-sagiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-damla-su-bile-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kararsız', 'kararsiz-volkan-i-ncel-u3xtp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep aynı kalsaydık yol almasaydık

Bir adım atsaydık da geri dönseydik

Bin kere yansaydık yine sönseydik

Sona hiç gelmeden başa dönseydik

Ellerimizi tutsaydık da bıraksaydık

Cesaret bulamasak ürkek kalsaydık

Sözler hiç çıkmasa geri yutsaydık

Sevgi masum dursa yazık etmeseydik

Göz göze bakışıp geri kaçsaydık

Buluşmaya giderken yolu şaşsaydık

Durağa geç gitsek otobüsü kaçırsaydık

Aşk bardakta dursaydı hiç taşırmasaydık', 'Hep aynı kalsaydık yol almasaydık Bir adım atsaydık da geri dönseydik Bin kere yansaydık yine sönseydik Sona hiç gelmeden başa dönseydik Ell...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kararsiz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü 2', 'turku-2-volkan-i-ncel-r0x0i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlığa bir yol oldu 

Gözlerinin ışığı

Yardan ayrı tutan yansın 

Gözü yaşlı aşığı

Anam yine pilav yapmış

Sapladım ben kaşığı

Dağlar bile durduramaz

Benim gibi aşığı

Çiçeklerle yola yazdım

Senin güzel adını

Azrail bile alamaz

Benim olan kadını

Dudağından bir kez öptüm

Unutamam tadını

Kimselere kısmet etmem

Benim olan kadını', 'Karanlığa bir yol oldu  Gözlerinin ışığı Yardan ayrı tutan yansın  Gözü yaşlı aşığı Anam yine pilav yapmış Sapladım ben kaşığı Dağlar bile d...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turku-2-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Kimlere Kalmış', 'dunya-kimlere-kalmis-yusuf-onder-bahceci-6d7nh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelin, gelin de sizlerle şöyle bir atışalım,

Siz parke taşları atın bizler de gül atalım,

Birbirimize dertlerimizi, sorup anlatalım,

Gelin, gelin de sizlerle şöyle bir atışalım.

O çok sevdiğiniz Dünya, kimlere kalmış,

Hani Sultan Süleyman hani ya ne olmuş,

Mezarını açalım da bakalım hâli nasılmış,

O çok sevdiğiniz Dünya, kimlere kalmış.

Fuhuş yaparken yakalanıyor, açım diyor,

Esrarı, eroini içiyor suçum nedir ki diyor,

Hırsızlık, yankesicilik yapıyor ne var diyor,

O çok sevdiğiniz Dünya, kimlere kalmış.

Adam suyun gözünü tutmuş içiyor, içiyor,

Sadece su mu galon, galon, içkiyi içiyor,

Hiç ayık gezmiyor da kendinden geçiyor,

O çok sevdiğiniz Dünya, kimlere kalmış....', 'Gelin, gelin de sizlerle şöyle bir atışalım, Siz parke taşları atın bizler de gül atalım, Birbirimize dertlerimizi, sorup anlatalım, Gelin, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-kimlere-kalmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkıntı', 'sikinti-volkan-i-ncel-wxfsl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün  seni düşündüm de 

Uykum kaçtı yatamadım

Hasretin bağrıma çöktü 

Bir yol bulup atamadım

Derdinden yandım kül oldum

Bir yel bulup uçamadım

Kapı kapı dolandım da 

Kimselere açamadım', 'Bugün  seni düşündüm de  Uykum kaçtı yatamadım Hasretin bağrıma çöktü  Bir yol bulup atamadım Derdinden yandım kül oldum Bir yel bulup uçama...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sikinti-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnam', 'turnam-volkan-i-ncel-chb8p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geldi benim telli turnam

Elinde bir tutam bahar

Bizi başbaşa  bırakın

Ona soracaklarım var

Sılaya yolun düştü mü 

Anamın saçları hep kar

Gidersen beni de götür

Zor geldi bana bu diyar', 'Geldi benim telli turnam Elinde bir tutam bahar Bizi başbaşa  bırakın Ona soracaklarım var Sılaya yolun düştü mü  Anamın saçları hep kar Gid...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/turnam-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur!', 'dur-rezzan-ersoy-d0hxs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aldım ben beni avuçlarıma,

uçurtmam artık kendimi başka ruhlara..

rüyalarımdan biraz eksik kal! ! 

biraz kendin kal benim içimde..

karışma dünyama..kimyama.

yoluna çıktım benimden geçen senin..ve kestim yolunu..

dur orda hatta bi kaç adım geri dur ki..yaşıyım kendimi..

yaşıyım bu yağmuru,akan zamanı yaşıyım..

yaşıyım çıkan gökkuşağını ve çekiyim içine tüm renklerini..

ve sen de aradığım benimden mahrum kalayım..', 'aldım ben beni avuçlarıma, uçurtmam artık kendimi başka ruhlara.. rüyalarımdan biraz eksik kal! !  biraz kendin kal benim içimde.. karışma d...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Ersoy']::text[], 8.5, '{"poet":"Rezzan Ersoy","poet_slug":"rezzan-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dur-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi', 'gemi-volkan-i-ncel-ehnne', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Demir aldım bu limandan

Gün ışıyınca giderim

Yüküm sevaptı bir zaman

Şimdi günahlar yükledim

Dümenimi bir zamanlar

Bu limana kırmıştım

Issız sandım bu limanı

Nasıl hevesle gelmiştim

Sevdanın en güzeliyle

Doluydu bütün ambarlar

Öyle çok yüklemiştim ki 

Tartamıyordu kantarlar

Şimdi boşaldı ambarlar

Gemimi yüklü sansınlar

Geldiğim gibi bir  zamanlar

Gün ışıyınca giderim

Demir aldım bu limandan

Gün ışıyınca giderim

Sevda yüklüydüm bir zamanlar

Şimdi acılar yükledim', 'Demir aldım bu limandan Gün ışıyınca giderim Yüküm sevaptı bir zaman Şimdi günahlar yükledim Dümenimi bir zamanlar Bu limana kırmıştım Issız...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gemi-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şizofren', 'sizofren-evren-baloglu-gh9zg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sendin beni sende bırakan 

Güzeldin 

Üstelik benim olmanda 

Yaşadığım neydi bilmemde 

Gerekmezdi 

Kayıpsa kayıp 

Üzüntüyse üzüntüydü 

Yokluğunda yanında 

Sağlıklıyken şizofren 

Olmak 

Sende mümkündü', 'Sendin beni sende bırakan  Güzeldin  Üstelik benim olmanda  Yaşadığım neydi bilmemde  Gerekmezdi  Kayıpsa kayıp  Üzüntüyse üzüntüydü  Yokluğ...', ARRAY['Türk Edebiyatı','Şiir','Evren Baloğlu']::text[], 8.5, '{"poet":"Evren Baloğlu","poet_slug":"evren-baloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sizofren-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilber', 'dilber-volkan-i-ncel-cs4u1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi tohumları ektin bağrıma

Umutları ektim bir,bir toprağa

Geleceksen eğer düşüp ardıma

Kırarım zincirim gelirim dilber

Bahçenin etrafı yüksek tel duvar

Duvarın ardında her gün ilkbahar

Kızımın adını koyarsan bahar

Kırarım zincirim gelirim dilber

Nicedir söylenir hepsi de ezber

Bu dünyada herkes garibi ezer

Kuru soğan ekmek seversen eğer

Yalanım yok bende garibim dilber', 'Sevgi tohumları ektin bağrıma Umutları ektim bir,bir toprağa Geleceksen eğer düşüp ardıma Kırarım zincirim gelirim dilber Bahçenin etrafı yü...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilber-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-volkan-i-ncel-gjeis', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yok deme bir gün tutuşacaksın

Başını yastığa dayayacaksın

Yüreğin yanacak hasretimle

Hıçkıra,hıçkıra ağlayacaksın

Elini uzatıp tutmak istesen

Koynumda sarılıp yatmak istesen

Yüreğin sızlardı beni bir görsen

Yokluğum acı gelir ağlayacaksın

Yok deme bir gün unutacağım

Mazimden seni söküp fırlatacağım

Bendeki resimleri hep yakacağım

Küllerini alınca ağlayacaksın', 'Yok deme bir gün tutuşacaksın Başını yastığa dayayacaksın Yüreğin yanacak hasretimle Hıçkıra,hıçkıra ağlayacaksın Elini uzatıp tutmak istese...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglayacaksin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum günü...', 'dogum-gunu-rezzan-ersoy-xg438', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bugün doğuşumu kutladım ben.. 

bugün kendime dokundum..

ve artık istemiyordum seni...huzur sarmış ruhumu..

pamuktan bir gölgenin içindeyim.. 

ve küçük bir çocuğum..

20 olmak umrumda mı.

hayır..! 

peki bu bitivermez senin dahi bilmediğin oyunlarımda,

saniye bile geçirmek istiyor muyum.? .

hayır! ..

şuanımda.! .

zamanın durduğu ve doğuşumu kutladığım şu dakkalarda...

kayıp gitmek istiyorum bugünün içinden.. 

ve bugünüm bitmesin istiyorum..

sarıldım deliliğime bırakmıyorum...', 'bugün doğuşumu kutladım ben..  bugün kendime dokundum.. ve artık istemiyordum seni...huzur sarmış ruhumu.. pamuktan bir gölgenin içindeyim.....', ARRAY['Türk Edebiyatı','Şiir','Rezzan Ersoy']::text[], 8.5, '{"poet":"Rezzan Ersoy","poet_slug":"rezzan-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dogum-gunu-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Şehir Duymazı', 'mavi-sehir-duymazi-hilal-sakar-c1aiw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sınırsızlıkla kuşanmış,

Nice insanlar adanmış.

Dikenlerde yaşlar boşalmış,

Mavi şehir duymazı.

Ocak başı atıldın ayaza,

Ne ev bulabildin.

Ne ısınacak bir baraka,

Nasılda mahzunsun ortada.

Bir iki kelime,

Ve enkaz eden bir titreme.

Uykusuz bomboş gece,

Yaşlarla yıkanmış boylu boyunca cadde.

Dost taziyeleri,

Dudaklardan dökülen keşkeler.

Vahlama olamayacak emsaldeler,

Bir çakımlık kibrite boyun eğdiler.

Gülüyorum duyduklarıma,

Şaşkınım! Bu nasıl bir tanıma? 

Bütünüyle yanlış anlama,

Yalan yere bunca aldatma.

Kelimeler ne kadar uzak anlamdan,

Doğru anlamayı bilmezsin.

Seni tanıdığımdan çok,

Beni tanımazsın.

Üşümek; 

Elleri pahasına devam edene,

Ne kadar ruhsuz bir kelime.

Yürümek; 

Uzun yolu üşenmeden tepene,

Çok hafif geldide.

Rüzgarlarda sürüklenmek,

Çamura aldırmadan teselli vermek.

Yağmurla dans edebilmek,

Zor gelmez asla.

Bilmezsin,bilirim.

Sana çok iyi diyorlar,

Merak ediyorum! 

Kötü taraflarını,

Sırf ben mi biliyorum? 

Sonuna kadar kapalı kapılar,

Dostluğu bilmeyenlere,

Sevgiye şüphe diyenlere,

Herşeyi maddede bilenlere.

Tüm bunlar iyilikse eğer,

Kötü olmayı kabul ediyorum.

Mavi şehrimde mutluyum,

Tüm maddeler sizin olsun.

Şehrime gidiyorum...

                    yağmurmah 2006', 'Sınırsızlıkla kuşanmış, Nice insanlar adanmış. Dikenlerde yaşlar boşalmış, Mavi şehir duymazı. Ocak başı atıldın ayaza, Ne ev bulabildin. Ne...', ARRAY['Türk Edebiyatı','Şiir','Hilal Şakar']::text[], 8.5, '{"poet":"Hilal Şakar","poet_slug":"hilal-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/mavi-sehir-duymazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri Sayfam', 'gri-sayfam-rezzan-ersoy-ivzse', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'simsiyah eldivenlerim vardı benim..

ellerimin sığınağı..

belki de ruhuma ördüğüm duvardı..

dokunmak istemiyordum sana..

dokunmak üşütüyordu beni..

sessizlik ağır bir taş oldu,sularıma düştü..

oyunlar vardı,çocuk oldum çıktım..

gri bir sayfa oldum açılamadım...', 'simsiyah eldivenlerim vardı benim.. ellerimin sığınağı.. belki de ruhuma ördüğüm duvardı.. dokunmak istemiyordum sana.. dokunmak üşütüyordu ...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Ersoy']::text[], 8.5, '{"poet":"Rezzan Ersoy","poet_slug":"rezzan-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gri-sayfam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iliklerime Isleyen Ayrilik', 'iliklerime-isleyen-ayrilik-gultekin-toga-0nn1q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nice acı tatdım yalan Dünya´da,

Hepisinden ağır bastı ayrılık..

Bir de eklenince yalnızlık buna,

Tümden iflahımı kesti ayrılık..

İliklerime dek işledi,tutdu,

Umut kaynağımı yaktı,kuruttu,

Ne bir gün gösterdi ne de uyuttu,

Sam yeli oldu da esti ayrılık..

Memleket dilimin hecelerinde,

Hayalim dağların yücelerinde,

Gurbetin gasvetli gecelerinde,

Gam doğurdu,hüzün kustu ayrılık..

Gönüle yabanci etti neşeyi,

Kaf dağı ardına attı neşeyi,

Bir dev iştahıyla yuttu neşeyi,

Sevincin sesini kıstı ayrılık..

Yüzün cizgisinde,saçın akında,

Sanki tuzdur Sentezi´nin kökünde,

Hakk nasip etse de desem yakında,

Artık benim ile küstü ayrılık..', 'Nice acı tatdım yalan Dünya´da, Hepisinden ağır bastı ayrılık.. Bir de eklenince yalnızlık buna, Tümden iflahımı kesti ayrılık.. İliklerime ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iliklerime-isleyen-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Avuç Fasülye', 'bir-avuc-fasulye-yusuf-onder-bahceci-3cydb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk okul birinci sınıftaydım, küçücük bir çocuktum,

Öğretmen, yazı yazacağız, bir avuç fasülye dedi,

Eve gelince anneme dedim, annem aradı durdu,

Öğretmenin istediği bu fasülyeyi çok zorla buldu. 

O zaman yokluk vardı, kimse de fazla mal yoktu,

Ama bunun karşılığında insanlık, dürüstlük çoktu,

Aldatma, kandırma, çarpma,çırpma, talan yoktu,

İlk okul birinci sınıftaydım, küçücük bir çocuktum.

O günleri hiç unutmam zavallı annem zorla buldu,

Küçük bir torba dikip, fasülyeleri içine doldurdu,

Bir avuç fasulye bulmak için ne kadar da yoruldu,

İlk okul birinci sınıftaydım, küçücük bir çocuktum.

Şimdi bir oğlan ve iki kız çocuğum var okuyorlar,

Onlar, fasulye değil bilgisayar, internet istiyorlar,

Biraz sabır dediğimizde de hemence küsüyorlar,

Bu bir avuç fasülye, bilgisayar ve internetler için......', 'İlk okul birinci sınıftaydım, küçücük bir çocuktum, Öğretmen, yazı yazacağız, bir avuç fasülye dedi, Eve gelince anneme dedim, annem aradı d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-avuc-fasulye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamaz Oldum', 'bulamaz-oldum-suleyman-zaman-iwcm7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şeker iletiyle sarsıldı beden

Yorulur elbette her hızlı giden

Aranır nesnede niçin ve neden

Ben kendi özümü bilemez oldum

İlerledi yaşım, araz var tende

Dostlar belli olur, her kara günde

Aynı şey aslında, gelen, gidende

Bu kadar gerçeği göremez oldum

Tabipler sorgular, bulur gerçeği

Döner devran her an, yoktur ölçeği

Var eder kültürler, onca süreği

Bilinç evrenine, giremez oldum

Nice dertler yüklü bu ten içinde

Anımsanır dertler, farklı biçimde

Arama mutluluk, sonsuz evrende

Bu sanal alemi, çözemez oldum

Girdim elli yaşa,  baktım geriye

Bir an geçmiş sanki, baktım maziye

Yaşamın amacı, nedir ki diye? 

Sorguladım amma, bilemez oldum

Zamanım dert ile, dolmuş taşıyor

Bir hedefe doğru, herkes koşuyor

Kimi bulmuş mevzi, kendin aşıyor

Nedense bir kamil, bulamaz oldum

				22.02.2006', 'Şeker iletiyle sarsıldı beden Yorulur elbette her hızlı giden Aranır nesnede niçin ve neden Ben kendi özümü bilemez oldum İlerledi yaşım, ar...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bulamaz-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Özgürlük *', 'ozgurluk-serkan-turna-7ix8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Demir penceresinde

Kuşlara özenir garip...

Mesele o ki 

Vicdan muhasebesinde gece,

Ruhun özgür olmalı ranzada…

Özgürde olsa kuşlar; 

Nihayetinde yerde ölür…', 'Demir penceresinde Kuşlara özenir garip... Mesele o ki  Vicdan muhasebesinde gece, Ruhun özgür olmalı ranzada… Özgürde olsa kuşlar;  Nihayet...', ARRAY['Türk Edebiyatı','Şiir','Serkan Turna']::text[], 8.5, '{"poet":"Serkan Turna","poet_slug":"serkan-turna","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ozgurluk-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yalnız Bırakmayan', 'huzun-yalniz-birakmayan-yakup-icik-ngck8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne varsa yasadigim hayatimda

Her sey senden var olan güzelliklerdi.

Simdi bir kendim ve yoklugunla anilarin kucagindayim

Hüzün bir beni yalniz birakmayan.

Bir anlam yüklemeye calissamda hayatima

Dolmuyorsun sen yeniden icime.

Kederden öte bir seyler sarili her zerremde

Figanim sensiz ve sessiz issizlarda.

Beni duyan hislerim anlamsiz duygularimda.

{Buer/Almanya}', 'Ne varsa yasadigim hayatimda Her sey senden var olan güzelliklerdi. Simdi bir kendim ve yoklugunla anilarin kucagindayim Hüzün bir beni yaln...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzun-yalniz-birakmayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şubat Şiiri', 'subat-siiri-i-lhami-turker-4ef19', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ŞUBAT ŞİİRİ

sen mayıslarda 

mor menekşeyi gördün mü

boynu bükük

bilir misin eylül çiçeklerinin 

hüznünü

sen şubat nedir bilir misin

bilir misin karın altında çarpar yürek

o gücük aydır öyle mi

tam da zemheri

ve uzun yıllardan 

sinmiş her köşesine dimağımın

damla damla erirmisin

sen şubat nedir bilir misin 

bilir misin

kaç yılda kaç ceker bu şubat

bu ayaz bu ayaz

çatlatır toprağı

gönüller mahzun

yüzler maznun

kefen rengini kaç günde atar

sen

bilir misin kaç çeker şubat

bu kara yazı 

bu ayazlamak ve ayaz

dayan be mehmet biraz 

önü gelen bahardır', 'ŞUBAT ŞİİRİ sen mayıslarda  mor menekşeyi gördün mü boynu bükük bilir misin eylül çiçeklerinin  hüznünü sen şubat nedir bilir misin bilir mi...', ARRAY['Türk Edebiyatı','Şiir','İlhami Türker']::text[], 8.5, '{"poet":"İlhami Türker","poet_slug":"i-lhami-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/subat-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah-u Vah', 'ah-u-vah-i-lhami-turker-e6o3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hattat elin kırılmasın

Öyle bir vav çek ki

Duyulsun ahı leylanın

ve mecnunun ah-u vahı', 'Hattat elin kırılmasın Öyle bir vav çek ki Duyulsun ahı leylanın ve mecnunun ah-u vahı...', ARRAY['Türk Edebiyatı','Şiir','İlhami Türker']::text[], 8.5, '{"poet":"İlhami Türker","poet_slug":"i-lhami-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ah-u-vah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konser ve', 'konser-ve-mehmet-coban-jro1g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Konser,

Müzikle insanın

Duygu ile maddenin

Birleşerek bütünleştiği

Aynı duygu ve düşüncelerin

Yerden göğe, gökten yere 

Merkezden çevreye 

Yakından uzak yere

Genişleyip bütünleştiği

Coşup taşan olgu, sel gibi

Konserve,

Hapsedilmiş doğa

Hakları elinden alınmış

Yitirilmiş özgürlükler

Yaşamlar, hayaller

Düşünceler, idealler

Kapağın açılmasını bekler

Hapsedilmiş doğa,

Konser olmak ister! ...

22.02.2006-İzmir', 'Konser, Müzikle insanın Duygu ile maddenin Birleşerek bütünleştiği Aynı duygu ve düşüncelerin Yerden göğe, gökten yere  Merkezden çevreye  Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/konser-ve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mim', 'mim-i-lhami-turker-6bpie', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mimsiz olsam da hayatta

Bahtım yürüyüp

Talihim yar olmasa da

Bir nokta var adımda', 'Mimsiz olsam da hayatta Bahtım yürüyüp Talihim yar olmasa da Bir nokta var adımda...', ARRAY['Türk Edebiyatı','Şiir','İlhami Türker']::text[], 8.5, '{"poet":"İlhami Türker","poet_slug":"i-lhami-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yA bİR yAPrak Ya bİR nEFEs', 'ya-bi-r-yaprak-ya-bi-r-nefes-gul-yazganarikan-sjbfj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ağaç olsam mı acaba evinizin önünde...

Dallarım yatak odanızın penceresinde...

Açtığınızda perdeyi ilk ışıkla 

Gözleriniz yapraklarıma değse...

Uzayınca kollarım budasanız beni

Böylelikle dokunurdunuz tenime 

Rüzgar okşadıkça varlığımı 

Bir şarkı olup fısıldardım  sizi size...

Yazın sıcağında gölgem de düşer çıplak teninize

Baharda koklardınız çiçeklerimi,

Kışın bir avuç kara karışırdım da 

eridikçe kar avuçlarınızda 

kıymık olup batardım parmaklarınıza

Mevsim bu durur mu durduğu yer de...

Sonbahar da gelir elbette

İşte o zaman açınca pencerenizi

Rüzgar yatağınıza kadar getirirdi beni...

hiç olmazsa yaprak olup girerdim koynunuza...

Biliyor musunuz 

o ağaç bile daha şanslı galiba,

Siz böyle kaçın benden, 

ya bir yaprak 

ya bir nefes ya da bir GÜL’e karışıp

gireceğim bir gün gönül pencerenizden...

sonra keseceğim yatak odanıza uzanan tüm dalları,

olur ya biri daha

 yaprak olur da 

girer aramıza 

sonbaharda...', 'Bir ağaç olsam mı acaba evinizin önünde... Dallarım yatak odanızın penceresinde... Açtığınızda perdeyi ilk ışıkla  Gözleriniz yapraklarıma d...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ya-bir-yaprak-ya-bir-nefes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-006 Aklandım..', 'ub-006-aklandim-mehmet-coban-fvoac', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ak

Düşüncelerim

Hayallerim vardı

İdeallerle süslenmiş

Çocukluk anılarım

Okuduğum hikâyeler

Okuduğum kitaplar vardı

Güzellikleri, insanlığı anlatan

Öğrendiğim din vardı

İnsana insanlığa öğütler veren

İnsanları özgürlüğe ileten

Zulmü, zalimi yok eden

Tartışılan ideolojiler vardı

Hepsi insanın mutluluğu 

İnsanlığın kurtuluşu için 

Emek, kavga veren! ....

Aklan

Tanrı ilinde

Tanrı sözünde

Başarmak için

Bilgilen, bilinçlen

Tanrı sözleriyle

Adını koy dünyaya

İnançlı eyleminle

Dediler……

Söyleyenler, 

Okuduklarım

Aklım bilincim! ..

Aklanmaya çalışıyorum

Sürekli düşüncede eylemde

Tartışıyorum kendimi sürekli

Geçmişimde, anımda geleceğimde

Aklandım

İse gerçekten

Tanrı ilinde

Tanrının sözleriyle…

Dünya ve ahirette eğer

Yaşam yaşanmaya değer..

Aklanamazsam, 

Ne burada, ne orada

Yaşamım yaşanmışlığım 

Değersiz geçmişten 

Başka ne eder? ! ........

21.02.2006-İzmir', 'Ak Düşüncelerim Hayallerim vardı İdeallerle süslenmiş Çocukluk anılarım Okuduğum hikâyeler Okuduğum kitaplar vardı Güzellikleri, insanlığı a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ub-006-aklandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş…', 'arkadas-mehmet-coban-lc3ns', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ar

Onurumdur kimliğim

Onu arsızlarla paylaşamam

Arsızlıkla karalayamam

Ark

Yoldur benim için

Yoluma engel tanımam

Yolumu haktan ayıramam

Zulümle asla karıştıramam

Arka

Geçmişimdir 

Ders alırım ondan

Özeleştirimle, bilincimle

Hatalarına, eksiklerine,

Sahip çıkamam……

Arkadaş

Sanki ikinci bendir

Duygularımı hayallerimi

Hayalimi rüyalarımı

Bilen, paylaşan, duyan

Gönülden sırdaşım…

Beni sever ben gibi

Beni düşünür ben gibi

Beni hisseder ben gibi

Beni korur ben gibi

Beni dinler ben gibi

Beni söyler ben gibi

Arkadaştır ben gibi

Ar’ım, Ar’ıdır

Ark’ım, Ark’ıdır

Tıpkı ben gibi

Arkadaştır ben gibi

22.02.2006-İzmir', 'Ar Onurumdur kimliğim Onu arsızlarla paylaşamam Arsızlıkla karalayamam Ark Yoldur benim için Yoluma engel tanımam Yolumu haktan ayıramam Zul...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/arkadas-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tırnağımı Kesseler Onu Dahi Acıtırlar', 'tirnagimi-kesseler-onu-dahi-acitirlar-zeynal-yaman-zmqq1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adaletin olmadığı yerde mahkemeler zulüm dağıtırlar

Parmak yerine kesseler tırnağımı onu dahi acıtırlar

1997', 'Adaletin olmadığı yerde mahkemeler zulüm dağıtırlar Parmak yerine kesseler tırnağımı onu dahi acıtırlar 1997...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tirnagimi-kesseler-onu-dahi-acitirlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Olur', 'nasil-olur-yusuf-onder-bahceci-5ouna', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kafama bir eşşek kafası taksalar acaba nasıl, nasıl olur,

Bu kafayla sadece çayırlarda otlanır da üzerine mi binilir,

Nasıl olur da bu kafa ile Ay''a, Uzay''a ve Merkür''e gidilir,

Kafama bir eşşek kafası taksalar acaba nasıl, nasıl olur.

Kafama eşşek kafası taksalar, gözlerimi mi beğenirim,

Bilmem bu konulardan acaba hangi konulara değinirim,

Acaba çayırlarda, meralarda hep başıboş mu gezinirim,

Kafama bir eşşek kafası taksalar acaba nasıl, nasıl olur.

Kafamda ki eşşek kafasıyla sesim çıksa ne düşünürüm,

İçimden güzel ce bir semer vursalar diye mi düşünürüm,

Sahibim sırtıma deyneği vurur ha bire vurursa ne olurum,

Kafama bir eşşek kafası taksalar acaba nasıl, nasıl olur.

Aman bu eşşek kafası da bana ne de güzelce yakışmış,

Eşşeğin sahibinin sağı, solu olmaz, yükü çok yüklermiş,

Eşşek yavaş gidiyor be diye ha bire ha bire nodullarmış,

Kafama bir eşşek kafası taksalar acaba nasıl, nasıl olur...', 'Kafama bir eşşek kafası taksalar acaba nasıl, nasıl olur, Bu kafayla sadece çayırlarda otlanır da üzerine mi binilir, Nasıl olur da bu kafa ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Tutsun', 'uzak-tutsun-mehmet-sait-akkus-1nxhd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sevgiler bu sevmeler

Hepside yalanmış meğer

Bir daha seversem eğer

Beni kurşuna dizsinler

Çekinir oldum sevmekten

Sırtımdan bıçak yemekten

Bıktım hep acı çekmekten

Sevmem daha öldürseler

Hep acıdır,hep hüsrandır

Yaralı gönlüm virandır

Yüreğimde hep figandır

Sevmem daha öldürseler

Ağardı saçım sevdadan

Bir çekilirsem aradan

Dileğim var yaradandan

Yar sevmeyi uzak tutsun', 'Bu sevgiler bu sevmeler Hepside yalanmış meğer Bir daha seversem eğer Beni kurşuna dizsinler Çekinir oldum sevmekten Sırtımdan bıçak yemekte...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzak-tutsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutluyum yarınlardan', 'umutluyum-yarinlardan-mikdat-bal-l2wz2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutluyum yarınlardan

An bellidir zaman belli

Kaçmam küçük sorunlardan

Dün bellidir devran belli

Ananemiz töremiz var

Dert olmayan neremiz var

Her şeye bir çaremiz var

Kan bellidir, derman belli

Bayrak geçsin elimize 

Görün akan selimize

Biz bakarız yolumuza

Yön bellidir mekan belli

Zulmün kökü kazılacak

Yılan çıyan ezilecek

Tarih yine yazılacak

Şan bellidir ferman belli

Biri bize kastı mı var! 

Bunun altı üstü mü var! 

Türkün başka dostu mu var! 

Can bellidir, canan belli

Türkün çoktur beşareti

Hürdür sevmez esareti

Bir gün verir işareti

Han bellidir sultan belli

Mikdatî der geliyoruz

İşi ele alıyoruz

Biz herkesi biliyoruz

Lan bellidir ulan belli', 'Umutluyum yarınlardan An bellidir zaman belli Kaçmam küçük sorunlardan Dün bellidir devran belli Ananemiz töremiz var Dert olmayan neremiz v...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/umutluyum-yarinlardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk....', 'mutluluk-pinar-koc-l07sl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluktur gözlerimden akanlar belki,

Utanmadan indiririm yanaklarımdan,.,

Tasasız,dertsiz bir aşkın izleridir sanki,

Leylak rengi bir şarkı dökülür dudaklarımdan….

Umutsuzca yaşamış bir yüreğindir bu sevgi,

Leyla ile mecnunun  yarınlarından…

Unutmam artık yaşadığım bu günleri bil ki,

Kalbim atıyor artık senli mutluluğumdan....

                                                                              22.02.06        01:00', 'Mutluluktur gözlerimden akanlar belki, Utanmadan indiririm yanaklarımdan,., Tasasız,dertsiz bir aşkın izleridir sanki, Leylak rengi bir şark...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mutluluk-134-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkının Derdindeyim(arzuma)', 'askinin-derdindeyim-arzuma-mahir-celik-caxg3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öğrenemiyorum sensiz ayakta durmayı 

İki gizemli perdeyi sarmışlar yüreğime 

İçimdeki acıyı kanatıyor üzerindeki iğneler 

Aklıma geldiğince acıyorum 

Gerisi boş bir nefes alış 

Tohumları ağaçların ve dahi çiçeklerin 

Yeni bir yaşama hazırlanıyorlar; mevsimin adı bu 

Ben ölüşlerin içindeki duygularımı kurtarma çabasındayım 

Ellerimi hançerlesede kader, sıyırma telaşındayım aşkını 

Çare yok değil mi gidiyorsun! 

Ben dünün düşüncelerini sildim sevgili 

Ne yeni biri, ne dost ne de kardeş derdim 

Sensiz kalışlarımı cezalandır ve dön artık 

Ne gözüm yaşa tahammül eder ne sensiz geceye günüm 

Dön benim biricik bebeğim 

Aşkının derdindeyim...', 'Öğrenemiyorum sensiz ayakta durmayı  İki gizemli perdeyi sarmışlar yüreğime  İçimdeki acıyı kanatıyor üzerindeki iğneler  Aklıma geldiğince ...', ARRAY['Türk Edebiyatı','Şiir','Mahir Celik']::text[], 8.5, '{"poet":"Mahir Celik","poet_slug":"mahir-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askinin-derdindeyim-arzuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu sevdayı terk ediyorum…', 'bu-sevdayi-terk-ediyorum-pinar-koc-kedfx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Evet işte 

Bu gün,

Bu saat,

Ve bu dakika

Bu sevdayı terk ediyorum…

Derin uçurumlardan umarsızca atlamanın,

Bile bile ölüme gözü açık katlanmanın,

Ve geri dönmeyecek birini kucaklamanın

Acısını hiç mi hiç yaşamıyorum…

Ve bu saniyede

Bu sevdayı terk ediyorum…

Bu sefer katlanmak zor gelmedi 

Pervasızca sarf ettiğin sözlere,

İçimi acıtmadı açtığın yaralar,

Ve biliyorum ki kapanması an meselesi,

Ve biliyorum ki

Bir sızımlık bıçak darbesi,…

Evet işte

Bugün,

Bu saat,

Ve bu dakikada

Bu sevdayı terk ediyorum…

                                                                               21.02.06   18:45', 'Evet işte  Bu gün, Bu saat, Ve bu dakika Bu sevdayı terk ediyorum… Derin uçurumlardan umarsızca atlamanın, Bile bile ölüme gözü açık katlanm...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bu-sevdayi-terk-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk...', 'cocukluk-baris-pinar-tumer-1ysbf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep böyle olurdu...

Herkes sofradayken 

Sıcak bir yaz gecesi

Cırcır böceklerinin neşeli sesleri

Yemeklere dolardı.

Hep böyle olurdu...

Pencereler sonuna kadar açılırdı

Herkes sofradayken 

Ninemin sesi ve kokular

Çocukları çağırırdı.

Rüyalar gerçek olsa

yine böyle olurdu

Çocukluğum geri gelir

Cırcır böcekleri

Odama dolardı...', 'Hep böyle olurdu... Herkes sofradayken  Sıcak bir yaz gecesi Cırcır böceklerinin neşeli sesleri Yemeklere dolardı. Hep böyle olurdu... Pence...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocukluk-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve biliyorum....', 've-biliyorum-pinar-koc-jqpqo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görmedim,

Duymadım,

Ve konuşmadım değil....

Görmedim,

Ama duydum,

Ve biliyorum....

Ve seni çok seviyorum..............

                                                                      22.02.06  01:00', 'Görmedim, Duymadım, Ve konuşmadım değil.... Görmedim, Ama duydum, Ve biliyorum.... Ve seni çok seviyorum..............                      ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ve-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semah(arzuma)', 'semah-arzuma-mahir-celik-3avfh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinden gelen ışığa semah dönecek yüreğim 

Ellerin ne kadar eski bildik ama bu tat yeni 

Bir dokunuşun semazeni olmak varmış kaderde 

Ellerim ellerine hasret kalırcasına deli 

Masum duruşunda saklı selenin yeri 

Sessizliğinde tutuyorsun yüreğimi 

Kalbinle kalbime kan doluyor 

Nefesine aşina ciğerlerim, rüzgarına deli 

Esir edişinde gizli yüreğimdeki kıpırtı 

Gitme deyişlerinde gözlerinin 

Sevdanın adı senin adın olmalı 

Layığına kavuşan gönül mutlu, aşkına deli', 'Gözlerinden gelen ışığa semah dönecek yüreğim  Ellerin ne kadar eski bildik ama bu tat yeni  Bir dokunuşun semazeni olmak varmış kaderde  El...', ARRAY['Türk Edebiyatı','Şiir','Mahir Celik']::text[], 8.5, '{"poet":"Mahir Celik","poet_slug":"mahir-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/semah-arzuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-taner-erinc-dn1mr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baba demeyi özledim ben.

Sırtımdaki yükü sensiz atamadım,çok ağırdı baba,halen yere bırakamadım ben

       Hep istedim ellerinden tutmayı,ellerinle yüzümü okşamayı

     

Annem ağlıyordu sen gidince, hep ağladı zaten süzüldü gözlerinden yığınca damla sen ölünce,

O hep başlarını okşadığın öğrencilerin vardı arkanda,

ürkek sessiz ama gönüllerince

O çok sevdiğin arkadaşların vardı hüzünlü, suskun, ama başları dik yürüdüler 

seni sevince

       Kemanının sesini, kapının zilini çalışını, hadi ordan hınzır diğişini

       Vallahi baba demeyi özledim ben.

Büyüdüm, okudum, adam oldum

Evlendim torunların oldu, büyüdün içlerinde sen

İnanki baba demeyi özledim ben

       Mezarının taşını, gözün gibi baktığın bisikletinle alacakaranlıkta mahallede salınışını,

       İnanki baba demeyi

                                                             ÖZLEDİM    BEN', 'Baba demeyi özledim ben. Sırtımdaki yükü sensiz atamadım,çok ağırdı baba,halen yere bırakamadım ben        Hep istedim ellerinden tutmayı,el...', ARRAY['Türk Edebiyatı','Şiir','Taner Erinç']::text[], 8.5, '{"poet":"Taner Erinç","poet_slug":"taner-erinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozledim-164-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 72', 'guncel-beyitler-72-huseyin-avdic-fhpe1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Istersen Hayatin Tadini

