INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-rifki-kaymaz-5q798', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen o mesut ülkede,

Ben ise buradayım.

Gündüz gelip geçse de

Ben hâlâ uykudayım.

Beni yanına sesle

Geleyim bin hevesle

Ruhuma o nefesle

Üfle ki uyanayım.

Bir ses ki mesut eden

Kurtarır bu geceden

Çözülmez bilmeceden

Manaya uzanayım.', 'Sen o mesut ülkede, Ben ise buradayım. Gündüz gelip geçse de Ben hâlâ uykudayım. Beni yanına sesle Geleyim bin hevesle Ruhuma o nefesle Üfle...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-335-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizimin T/Adı', 'denizimin-t-adi-aylin-ayla-selcukoglu-h35qg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha sesinin yankısı vurmadan yüzüme

Efkârı basıyor yokluğunun

Nalan oluyorum, akan, durulmaz gözyaşlarımla

İzbe köşesini kanatıyorum ruhumun

Zamanı kovalıyorum, pencerene konayım diye, sensiz sabahlara uyanışımla

20.02.2006   00.41', 'Daha sesinin yankısı vurmadan yüzüme Efkârı basıyor yokluğunun Nalan oluyorum, akan, durulmaz gözyaşlarımla İzbe köşesini kanatıyorum ruhumu...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/denizimin-t-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren...', 'tren-ercan-akbay-qhl62', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tren,

   Ne zaman düdüğünü çalsa,

   Ne zaman kara dumanlar tütse,

   Ayrılık,gurbet,özlem,gözyaşı gelir akla.

   Oysa,her peron mutlaka sarsılmıştır,

   Sevgilerle dopdolu bir kucaklaşmayla...

                                        14.9.1992', 'Tren,    Ne zaman düdüğünü çalsa,    Ne zaman kara dumanlar tütse,    Ayrılık,gurbet,özlem,gözyaşı gelir akla.    Oysa,her peron mutlaka sar...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tren-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Var olmuş,Bi Yok olmuş', 'bi-var-olmus-bi-yok-olmus-aylin-ayla-selcukoglu-ge231', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölü bir korkunun çığlıkları

Saçlarımın gölgesine vurmuş

Kuytusuna sığınmış yalnızlığımın

Ve özlemlerimin kıyısına demir almış

Soyunmuş kahırları, mazileri

Yüreğine okyanusları salmış

Yürümüş dal uçlarına  neşenin

Sağrısına ben saplanmış belayı rehin bırakmış

Dirseklerini tırnaklamış gecelerin

Sahipsizliğinde üşüyen güne kavuşmuş

Budamış dallarını, tazecik gelinciklerin

Mateminde gülmüş kıs kıs, gamzelerinde yok olmuş

Bi var olmuş seslenişlere,her zemheri

Bi yok olmuş kayıtsızlığında âfâkın

Bi var olmuş düşüne uyanan seferî

Bi yok olmuş tüm dünden kalma kuruntu ve hüzünleri

23.02.2006 Perşembe  11.18-11.24', 'Ölü bir korkunun çığlıkları Saçlarımın gölgesine vurmuş Kuytusuna sığınmış yalnızlığımın Ve özlemlerimin kıyısına demir almış Soyunmuş kahır...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bi-var-olmus-bi-yok-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-85 (M.S.) 22/02/2006', 'mektuplar-85-m-s-22-02-2006-mahzun-doga-h8gtw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne uçsuz bir zaman oldu

bu kente kalbin düştüğünden beri

bir önceki nefesimiz kadar uzak 

sonraki kadar gurbet dolu

sakin ve onurlu

Ne kadar u-mutluyum

mutluluğun oldum olalı

bu kente ellerin düştüğünden beri

bağırmadan duyuluyor hüznüm

yüzüne tırmanabiliyor yüzüm

sana dokunabiliyorum

anlayabiliyorum

beni canlayabiliyorsun

ve öldürebiliyorsun 

bu kent sana esir düştüğünden beri

ne kadar yakınsın 

ölüm 

ne kadar uzaksın 

yaşam

aşk

ne kadar ço(cu)  ksun

Bu kente geldin geleli

ne çok büyümüşüz

ne çok küçülmüş yokluğun

ve ne çok anladım

ne çok büyüyorsun

bu kentten gittin gideli', 'Ne uçsuz bir zaman oldu bu kente kalbin düştüğünden beri bir önceki nefesimiz kadar uzak  sonraki kadar gurbet dolu sakin ve onurlu Ne kadar...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mektuplar-85-m-s-22-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çayımın Şekeri', 'cayimin-sekeri-aylin-ayla-selcukoglu-sfdt9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önceden

Bi ince belliye attığım

Altı küpten sanırdım

Anladım ki

Bi tutam sen, bi tutam benmiş

Çayımın şekeri

Sen yoktun

Ben çayımı sensiz içemedim

Soğudu çayım

“Sensizliktendi” diyemedim

22.02.2006   23.59', 'Önceden Bi ince belliye attığım Altı küpten sanırdım Anladım ki Bi tutam sen, bi tutam benmiş Çayımın şekeri Sen yoktun Ben çayımı sensiz iç...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cayimin-sekeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzüne Çizdiğimin Elleriyle', 'gokyuzune-cizdigimin-elleriyle-aylin-ayla-selcukoglu-w8kji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Âfâkın gözbebekleri öperken avuç içlerimi

Damlalar çöreklenir ıssız yarınlarıma

Ardıma savrulan öfkem kaybolmakta dilsizlikten

Pişmanlık kokusu yıkanmakta sellerimde

Önüne düşmekteyim akıl almaz gölge oyunlarının

Küsmekteyim, dün barıştıklarımla ve 

Barışmaktayım, gökyüzüme çizdiğimin uzattığı elleriyle

Kavururken yeni doğan gençliğimi

23.02.2006  11.01', 'Âfâkın gözbebekleri öperken avuç içlerimi Damlalar çöreklenir ıssız yarınlarıma Ardıma savrulan öfkem kaybolmakta dilsizlikten Pişmanlık kok...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gokyuzune-cizdigimin-elleriyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-86 (M.S.) 23/02/2006', 'mektuplar-86-m-s-23-02-2006-mahzun-doga-23asa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarın geldin

Dün gittin

“vay be”

ne kadar geç geldin

ne kadar erken gittin

Sana ne diyeyim ki ben

ne diyeceksin ki bana

beni kim bıraktı

seni kim götürdü

ne diyeceğimizi kime diyeceğiz

sustuğumuz yerde susuyoruz şimdilik

başka çare yok

ne kadar azarlasak da bu yerleri 

arı yok belli

susmak mı-en iyisi

Unutma ama

yarin gittin 

dün gel', 'Yarın geldin Dün gittin “vay be” ne kadar geç geldin ne kadar erken gittin Sana ne diyeyim ki ben ne diyeceksin ki bana beni kim bıraktı sen...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mektuplar-86-m-s-23-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadan ve Denizden', 'karadan-ve-denizden-aylin-ayla-selcukoglu-mfz54', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabaha uzanan sızıma

Ellerin ilaç oldu saydım

Sesin kaderime barışırken

Çok gözyaşı uğurladım

Karadan ve denizden

En son bi yağmurun

Tozunu dumanına kattım sulak yüreğimde

Ve…

23.02.2006   06.42', 'Sabaha uzanan sızıma Ellerin ilaç oldu saydım Sesin kaderime barışırken Çok gözyaşı uğurladım Karadan ve denizden En son bi yağmurun Tozunu ...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karadan-ve-denizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öp Gözlerimden', 'op-gozlerimden-aylin-ayla-selcukoglu-feuon', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay, bi karanlık dolum yüreklere

Bileklere ekmek ve su

Bu sabah

Pencerenden içeri süzülen ışık

“Ben”im

Hadi aç gözlerini

Ve, öp gözlerimden

22.02.2006 09.29', 'Ay, bi karanlık dolum yüreklere Bileklere ekmek ve su Bu sabah Pencerenden içeri süzülen ışık “Ben”im Hadi aç gözlerini Ve, öp gözlerimden 2...', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/op-gozlerimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanoğluna Güven Olmaz (Geçmiş Zaman Olur ki) ...', 'i-nsanogluna-guven-olmaz-gecmis-zaman-olur-ki-ali-orhan-gunaydin-ukeap', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '…Eski Konak’tan Yeni Bina’ya Nasihat…

Hey gidi dünya hey…

Yıllar da ne çabuk geçiyor, 

hissettirmeden su misali…

Sanki dünmüş gibi…

Sahibim buraların hatırı sayılır eşrafındandı, 

huzur içinde yatsın…

Eh! ...yaşlandık artık,

Böyle giderse, benim de yıkılma vaktim,çok yakındır…

Zaten belim bükülmüş büküleceği kadar…

Dün basamaklarımdan biri daha kırıldı…

Günden güne daha da yıpranıyor, engel de olamıyorum çöküyorum…

Şuna bak şuna nasılda şımarıyor,

Hani derler ya “küçükler saygısız olur,büyüğünü geçer” diye…

Buda öyle işte…

Evlat...

Şöyle bir yaklaş da  beni bir dinle…

Bir şeyler öğren hiç değilse…

Senin o kurulduğun yerde çok daha güzel ve heybetli bir konak vardı…

Nelere şahit olmamıştı ki o konağın kerpiçten olan duvarları…

Konaktan mı? yoksa içinde yaşayanlarından mı? 

Daha bir çocuksu olurdu evin küçüklerinin şen kahkaları…

Görüyorum ki boylu poslusun…

Dilerim ki bu dünya, sana daim olsun…

Yalnız unutma…

İnsanoğluna güven olmaz…

Tarih nedir bilmez…

Eskiye hürmet nedir bilmez…

Kendini şimdiden hazırla,

Gün gelir devran döner senin bu kurulduğun yere 

başka binalar türer…

Senin burada olup olmadığını 

Tarih bile inkar eder…

31/06/1997

Kastamonu

Not: Fotoğraftaki eski ev bir Zile evidir...', '…Eski Konak’tan Yeni Bina’ya Nasihat… Hey gidi dünya hey… Yıllar da ne çabuk geçiyor,  hissettirmeden su misali… Sanki dünmüş gibi… Sahibim ...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/insanogluna-guven-olmaz-gecmis-zaman-olur-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Özlüyorum', 'ben-seni-ozluyorum-riza-baldede-kgz9o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabahları uyandığımda sen yoksun

Öğlen bir şekilde vakit geçiyor

Akşamları sensizliğe alışmaya çalışıyorum

Geceler,bende sonlanmamış seni tercüme ediyor

Ben seni özlüyorum

Rüyalar içinde rüyalar görüyorum

Hep sen varsın,rüyalarımın içinde

Senli rüyaları hayra yormayı bıraktım

Sensizliği tercüme ediyor yokluğun

Ben seni özlüyorum

Yağmurlar artık seni getirmiyor

Albümdeki resimlerimiz eskiyor

Telefonlarda senin sesin gelmiyor

Aşkı tercümeyle meşgul kalbim

Ben seni özlüyorum

Sevgim gelişirken,herşey değişiyor

Yollar,evler,bir sen aynı kalıyorsun bende

Gecen gün yeni kazak aldım kendime

Her neyse...

Ben seni özlüyorum', 'Sabahları uyandığımda sen yoksun Öğlen bir şekilde vakit geçiyor Akşamları sensizliğe alışmaya çalışıyorum Geceler,bende sonlanmamış seni te...', ARRAY['Türk Edebiyatı','Şiir','Rıza Baldede']::text[], 8.5, '{"poet":"Rıza Baldede","poet_slug":"riza-baldede","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-seni-ozluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-87 (M.S.) 24/02/2006', 'mektuplar-87-m-s-24-02-2006-mahzun-doga-6ccc1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakışların

körlüğümüzü yıkayan 

bakışların

göz ağartan

içli ve narin

derin ve dingin bir gölet

Mavi saçlarındaki ışıltı

Ak alnın altında

bakışların

hüznümün cümlesi 

aklımın hazinesi

durgunluğum

bakışların

Yaşam anlatan

güz kaçıran

bakışların

aşk çağıran

saç ağartan

bakışların

“ama gittin

daha yazamadım”', 'Bakışların körlüğümüzü yıkayan  bakışların göz ağartan içli ve narin derin ve dingin bir gölet Mavi saçlarındaki ışıltı Ak alnın altında bak...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mektuplar-87-m-s-24-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilememki', 'bilememki-seyfet-bozcali-hijpu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözlerimle gönüllere bir girsem,

Girdiğim gönülden sevgi toplasam,

Çaresiz mahluka faydalı olsam,

Mutluluk sinemden taşar mı bilmem...

Parlayan güneşe elçilik yapsam,

Mazlumun evine bir uğra desem,

Geçmişe yürekten mendil sallasam,

Mutluluk göz yaşım siler mi bilmem...

             24.02.2006', 'Sözlerimle gönüllere bir girsem, Girdiğim gönülden sevgi toplasam, Çaresiz mahluka faydalı olsam, Mutluluk sinemden taşar mı bilmem... Parla...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bilememki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin', 'ne-dersin-ferah-yilmaz-0csay', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzak diyarlardayım

Yetişir mi sesim? 

Adını anımsasam

Çınlar mı kulağın? 

Seviyorum dersem seni

Söyle bana 

Ne dersin? ? 

Dağarcık / Ardahan - 1981', 'Uzak diyarlardayım Yetişir mi sesim?  Adını anımsasam Çınlar mı kulağın?  Seviyorum dersem seni Söyle bana  Ne dersin? ?  Dağarcık / Ardahan...', ARRAY['Türk Edebiyatı','Şiir','Ferah Yılmaz']::text[], 8.5, '{"poet":"Ferah Yılmaz","poet_slug":"ferah-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-dersin-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Kişi Ateşin Başında', 'dort-kisi-atesin-basinda-melih-coskun-2jrl7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece sırnaşık bir kedi gibi 

Dolanıyor ayaklarıma 

Dört kişi ateşin başında 

Adlarını ve adreslerini bilmediğim 

Dört kişi yalnızlıklarını yakıp ısınmakta

İlki, iri yarı görünüşünün ardında 

Bir çocuğun kalbini taşıyan saf bir adam 

Hiçbir düşüncesi olmamış bu güne kadar

Dünyaya ve insanoğlunun kurtuluşuna dair. 

Aklında daha görmediği üç aylık oğlu

Dilinde çok eski bir türkü

Bir taş plağın buğulu tınısından armağan kalan

“gözlerimde kanlı yaşlar” 

“Dört kişi ateşin başında 

Dört kişi bu gece 

Büyük hasretlerini yakıp ısınmakta” 

İkincisi,

Sarı benizli, zayıf bir adam 

Dudaklarının ucunda 

Sırrını dumanının ardına sakladığı

Tek nefesi kalmış sigarası, 

Topallayan bacağında 

Kendiyle bir başına kaldığı gecenin acı hatırası

“Dört kişi ateşin başında 

Dört kişi bu gece 

Kimsesizliklerini yakıp ısınmakta”

Üçüncüsü,

Yarım asırlık ömrüne 

Binlerce yılın öyküsünü sığdırmış

Bilge bir adam. 

Görüp gezmediği hiçbir şehri kalmamış memleketin 

Ve şahit olmadığı hiçbir acı

Aşık olmuş bir kez ölesiye 

Sevilmemiş ama. 

Beyninde hiçbir zaman çözemediği bir soru:

Hayat neden en çok güzel çocuklarını kanatır? 

“Dört kişi ateşin başında 

Dört kişi bu gece 

Yaşanmamışlıklarını yakıp ısınmakta.

Sonuncusu

Her duyguyu iki kere yaşayan

Genç ve heyecanlı bir adam

Ne kör karanlık zindanlarda yatmış kısa ömründe

Ne de beklemiş iğrenç ıslığını 

Ense köküne inecek olan bir sopanın 

Ama hissetmiş acısını yüreğinde 

Dünyanın öbür ucunda denize düşen bir gül yaprağının...

Bakın diyor gözlerime 

Bakın gözlerim ne diyor; 

“bir gün 

ama bir gün mutlaka”

Ay ışığı sızıyor 

Parmaklarımın arasından 

Dört kişi kayan yıldızlar gibi 

Akıp geçiyor otobüsün penceresinden

“Dört kişi ateşin başında

Dört kişi bu gece büyük sırlarını yakıp ısınmakta...”

2005

www.melihcoskun.com', 'Gece sırnaşık bir kedi gibi  Dolanıyor ayaklarıma  Dört kişi ateşin başında  Adlarını ve adreslerini bilmediğim  Dört kişi yalnızlıklarını y...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/dort-kisi-atesin-basinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömürden Günlerim Geçiyor', 'omurden-gunlerim-geciyor-seyfet-bozcali-7w5v0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dertlerim abanıyor üstüme,

Korkarak uykularım kaçıyor.

Izdırap doluyor testime,

Ömürden günlerim geçiyor...

Kaderin pençesine düşmüşüm,

Bir çok zorlu engel aşmışım,

Dertle yoğrulmuşum,aşkla pişmişim,

Ayrılmak ömrümden geçiyor...

Sevenler kalbimde tek ses,

Günlerim ızdırap, saatler sitres,

Yadımdan çıkmıyor prenses,

Ömrümden çalarak kaçıyor...

Kahrından eridi heceler,

Uykusus tükendi geceler,

Şafakla doğarken güneşler,

Günler,günleri seçiyor...

     23.02.2006', 'Dertlerim abanıyor üstüme, Korkarak uykularım kaçıyor. Izdırap doluyor testime, Ömürden günlerim geçiyor... Kaderin pençesine düşmüşüm, Bir ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omurden-gunlerim-geciyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sukrettim', 'sukrettim-fatma-ay-3hwuw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gun rasladim bir tanidiga.

Durdum,dedimki:

-Merhaba.

Bakti ve; dediki:

-Merhaba,taniyamadim ama.

Ben Fatma.Hani 4 yil once,

Ayni amacla beraberdik her toplantida.

-Simdi hatirladim.

Basladi anlatmaya.

Icimden gelen bir ses..

Sana yaptigi haksizligi vur suratina.

Tam diyordum konusmasina verse ara; 

Icimden gelen yine o ses.

Ne yapiyorsun? Fatma.

Ihanet edersin inancina.

Kulun sucunu yuzune vurma.

Vurursan gelme karsima diyor:

Allhutaala.

Sonra nasil cikarsin? 

Allahin karsisina.

Durdum,irkildim.

Dinledim,dinledim ve dinledim.

Ayrildik sonra.

Hic arkama bakmadan yurudum gururla.

Yurudum salina salina.

Ve sukurler olsun Allhim sana.

Kisiligimden,benligimden,onurumdan.

Kaybettirmedin bana.

Sukurler olsun Allahim sana.', 'Bu gun rasladim bir tanidiga. Durdum,dedimki: -Merhaba. Bakti ve; dediki: -Merhaba,taniyamadim ama. Ben Fatma.Hani 4 yil once, Ayni amacla b...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ay']::text[], 8.5, '{"poet":"Fatma Ay","poet_slug":"fatma-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sukrettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Avuç Mutluluk', 'bir-avuc-mutluluk-ferah-yilmaz-7o8um', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi bir kelimesin dudaklarımda 

Belli belirsiz, 

Bir tebessümsün yüz hatlarımda, 

Belkide birkaç damla gözyaşısın 

Yanaklarımdan aşağı süzülen... 

Şimdi; 

Bir ışıksın karanlık gecelerimi aydınlatan, 

Yağmurun ardından açan Gökkuşağım.. 

Renk cümbüşüm, 

Ellerimle şekil verdiğim eserim, 

Nakış nakış, 

Dize dize işlediğim 

Mısralarım, cümlelerim, şiirlerim.. 

Şimdi, 

Bir tek sigarasın parmaklarımın arasında 

Ağırdan tüten. 

Ciğerlerime çektiğim nefes, nefes 

Bir kadeh meysin masamda duran 

Yudum Yudum içtiğim 

Ve.. 

Bir avuç mutluluğumsun sen 

Dirhem dirhem tattığım 

İnan bana! 

Kimselere anlatamadığım.. 

Dağarcık / Kocaeli  - 18.10.2002

10 HAZİRAN 2007 tarihinde www.edebiyatdefteri.com sitesinde ÖZEL SEÇKİ almıştır.', 'Şimdi bir kelimesin dudaklarımda  Belli belirsiz,  Bir tebessümsün yüz hatlarımda,  Belkide birkaç damla gözyaşısın  Yanaklarımdan aşağı süz...', ARRAY['Türk Edebiyatı','Şiir','Ferah Yılmaz']::text[], 8.5, '{"poet":"Ferah Yılmaz","poet_slug":"ferah-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-avuc-mutluluk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen mezar da degil, kalbimdesin! Ay-Nur', 'sen-mezar-da-degil-kalbimdesin-ay-nur-ali-ekber-wb5ad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden geriye,sadece bir resminmi kalacakti bana? 

Ayaklari sallanan mermer masam da,

Bir de maziye karismis,bulanik hayalin aklim da,

Nasil da terk edip gittin,ardindan bedbaht ettin,

Allah kahr etsin,mezar da degil,kalbim de tek tesellimsin! 

Bakma sitemkar bugulu gözlerinle,öyle gözlerime,

inan,sen yoksun diye hic isyan etmedim''ki,

Sen yoksun diye,göz yaslarimi kalbime akitmadim''ki,

Hic karamsarliga düsmedim''ki,sen yoksun diye,

Kahr olsun,mezar da degilsin''ki,kabrin kalbim de biliyorsun! 

Resimi her elime alisim da canlanir anilarim,

Siyah ömlük,beyaz yaka ve gri yamali pantolona bürünürüm,

Onun yanin da,onun icin de,kalbin de,el-ele yürürüm,

Göz-göze,omuz-omuza,kalplerimiz bile tek atar,tek vücut olurum...

Allah kahr etsin,sen mezar da degil,kalbim de gömülüsün! 

Resim bazen gözlerime öyle bakar''ki büyülenirim,

Günese bakar gibi olurum,atesler de yanarim,

Bir hos olurum,bir baska olurum,bambaska... deliririm,

Sen mezar da degil,kalbim de''ki yasayan,yakan günesimsin! 

Bazen dayanamam bakislarina,semalara kanat acarim,

Okyanuslari avuclarim,canlilarini ugruna yok ederim,

Ayaklarina, daglari serer,kir ciceklerini üzerine ekerim,

Dünyayi cerceve yaparim ama Resimini sigdiramam.

Sen ölü degilsin, kalbim de yasayan en canli resimsin! 

Seni hic unutmayacagim,anilarim''in ölümsüz kahramani,

Biliyorum, sen melekler diyarindasin,

Ve benim kalbim de,verdigin resimin de yasayacaksin...

Allah kahr etsin,sen mezar da degil,hayat nefesimdesin!', 'Senden geriye,sadece bir resminmi kalacakti bana?  Ayaklari sallanan mermer masam da, Bir de maziye karismis,bulanik hayalin aklim da, Nasil...', ARRAY['Türk Edebiyatı','Şiir','Ali Ekber']::text[], 8.5, '{"poet":"Ali Ekber","poet_slug":"ali-ekber","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-mezar-da-degil-kalbimdesin-ay-nur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Boğazında', 'i-stanbul-bogazinda-nur-demirciler-jd1bq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul Boğazında,

Kaderim avucumda.

Kıyısında oturdum bir gece,

Boğaza attım sevdamı öylece...

Dalgalar aldı götürdü onu benden.

Sevemem, sevemem,

                     seni ben.

Bıçak sırtında yaşamaktan,

Yoruldum, usandım gizli sevdadan

Tutsağın olamam, söz veremem,

Sevemem, sevemem,

                     seni ben.

Şimdi sen belki açık denizlerde,

Bense hep aynı yerlerde

Yüreğim buruk sanki ateşte,

Yinede sevemem sevemem 

                                seni ben

Kıyısında kaybettim sevdamı,

İstanbul Boğazı yüreğimin sancısı.

Şubat/1999

İstanbul', 'İstanbul Boğazında, Kaderim avucumda. Kıyısında oturdum bir gece, Boğaza attım sevdamı öylece... Dalgalar aldı götürdü onu benden. Sevemem, ...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/istanbul-bogazinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşk', 'i-lk-ask-ferah-yilmaz-8sbx1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anneni sevmekle başlarsın ilk önce,

Ardından babanı,

İlk sevgiyi onlarla tadarsın

Daha sonra,

Sokaktaki arkadaşlarını sevmeyi öğrenirsin

Sevmeyi öğrendikçe,

Her birinin sevgisi,

Bir sonrakine savar sırasını,

Okul yılları gelir peşi sıra

Tek sevgilin

Öğretmenin olmuştur sonunda

Sadece o vardır aklında

Zaman geçtikçe

Sevgiler köşe kapmaca 

Başlar sıralardaki heyecan

Ki yaşamın sonunda dahi

Sadece odur hatırlanan..

Oysaki her aşk

Bir öncekinin tekrarıdır

Farkına varılmadan yaşanan

Sonunda hafızanda kalan

İlk aşkındır her zaman….

Zaman tünelidir sevmek…

Dağarcık / İzmit - 23.12.2005 – 23:15', 'Anneni sevmekle başlarsın ilk önce, Ardından babanı, İlk sevgiyi onlarla tadarsın Daha sonra, Sokaktaki arkadaşlarını sevmeyi öğrenirsin Sev...', ARRAY['Türk Edebiyatı','Şiir','Ferah Yılmaz']::text[], 8.5, '{"poet":"Ferah Yılmaz","poet_slug":"ferah-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ilk-ask-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Tanrım', 'yuce-tanrim-necati-keceli-2z64z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gariban, fakire şöyle bir bak

      Eksiği olanı gör yüce Tanrım

      Benim gönlüme de bir ışık yak

      İçimde huzuru kur Yüce Tanrım

      Yolunu kaybetmiş yolsuzlara yol

      Alil, acizlere kanat yâda kol

      Muhtaç olanlara bolca para pul

      Yoksullara iş, aş ser Yüce Tanrım

      Yatakta ümitsiz baygın yatana

      İlaç için, evden eşya satana

      Hastanın altından alıp atana

      Onada kol kanat ger Yüce Tanrım

      Bütün insanlara iman, itikat

      İnanan herkese gerçek, hakikat

      Zayıf, sakatlara güç ile takat

      Yarasına merhem sür Yüce Tanrım

      Âlim’i, zalime etme maskara

      Karda kışda nöbet tutan askere

      Zamanı gelince bir de teskere

      Nasip eyleyerek ver Yüce Tanrım

      Kurtlara, kuşlara nasip kısmeti

      Tüm Müslümanlara göster cenneti

      Çoluk çocuğuma sağlık, sıhhati

      Merhamet içinde sar Yüce Tanrım

      Necati KEÇELİ

      ADANA', 'Gariban, fakire şöyle bir bak       Eksiği olanı gör yüce Tanrım       Benim gönlüme de bir ışık yak       İçimde huzuru kur Yüce Tanrım    ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuce-tanrim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Emek İster', 'sevgi-emek-i-ster-birsen-ates-b821w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ellerimde kaldı yüreğin

bakışların düşlerde

kimsesiz bir sevgiydi 

öylesine garip bir çocuk gibi

aldım büyüttüm

emzirdim sevdanın göğüslerinde

sevgi emek ister diye

şimdi

istiyorum düşmeyi

hüznün uçurumlarından

yalnızlıkların koynuna

25.02.06', 'ellerimde kaldı yüreğin bakışların düşlerde kimsesiz bir sevgiydi  öylesine garip bir çocuk gibi aldım büyüttüm emzirdim sevdanın göğüslerin...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-emek-ister-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yagmur', 'yagmur-fatma-ay-fevs4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bak sevgilim yine yagiyor yagmur,cisil cisil.

Hani o ilk sevistigimiz gun gibi.

Nasilda yagiyordu yagmur? Usuul usuuul.

Hani akiyordu yagmur sulari ayagimizin altindan.

Iste oyle yagiyor, yine cisiil cisiil.

Ikimizde severdik yagmur adli sarkiyi.

Dinledikce ilk tanistigimiz gunu animsardik.

Ne guzeldi degilmi? O gunlerimiz.

Herkes imrenirdi,birbirimize kenetlenmis kalplerimize.

Simdi yine yagiyor yagmur ama...

Ikimizde ayri yerlerden bakiyoruz ona.

Su anda benim animsadigim gibi.

Sende animsadin, beni ve sevgimizi.

Biliyorum bunu, tipki icimdeki sevgin gibi.

Her yagan yagmurun ardindan gunes doguyor.

Bizimki ise batti.

Hem bizi hemde o kutsal sevgimizi batirdi.

Dua ediyorum Allha.

Bu yagan yagmurun ardindan...

Gunes dogsa,ellerimiz birlesse.

Her zamanki gibi, herkes sevgimize imrense.Tarih-23-10-1980', 'Bak sevgilim yine yagiyor yagmur,cisil cisil. Hani o ilk sevistigimiz gun gibi. Nasilda yagiyordu yagmur? Usuul usuuul. Hani akiyordu yagmur...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ay']::text[], 8.5, '{"poet":"Fatma Ay","poet_slug":"fatma-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yagmur-270-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkemin Çivisi Çıktı Dostlarım', 'ulkemin-civisi-cikti-dostlarim-seyfet-bozcali-wnmy7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mazlumlar ağlarken,zalim gülüyor,

Haklı haksız,haksız rağbet görüyor,

Hırsız çalıp, birde haklıyım diyor,

Ülkemin çivisi çıktı dostlarım...

Araba çalmalar oldu arpalık,

Geri vermek için sürer pazarlık,

Emeksiz yaşamak onca haklılık,

İnsanlar bunlardan bıktı dostlarım...

Adamlar hem suçlu hem tehtit eder,

Vermezsen parayı,yakarım derler,

Alırlar parayı,tekrar satıp giderler,

Daha sonra tekrar çalar dostlarım...

İnsan hakları der,haklar gasp olur,

Haklı fiilinde,hep haksız olur,

Adelet kör,topal adelet kalır,

Ülkemize yazık olur dostlarım...

Mafya,kapkaç dizileri revaçta,

Kısa yoldan köşe dönmek kapkaçta,

Caydırıcı suçlar yok ki en başta,

İnsanlar sokakta ölür dostlarım...

Seyfet derki mazlum heder oluyor,

Hırsızlar sokakta çirit atıyor,

İnsanlar tedirgin yaşam sürüyor,

Ülkemin çivisi çıktı dostlarım...

           24.02.2006', 'Mazlumlar ağlarken,zalim gülüyor, Haklı haksız,haksız rağbet görüyor, Hırsız çalıp, birde haklıyım diyor, Ülkemin çivisi çıktı dostlarım... ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ulkemin-civisi-cikti-dostlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Insan Sevince', 'insan-sevince-kemal-oguz-8476n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah günes dogacak, kizil ufuktan.

Senin hayallerinle, dolu bir gece.

Yalnizlik arkadasim, yildizlar dostum

Yasamak cok güzeldir, insan sevince.

Uzaklarda olmasan, yanimda olsan.

Bu karanlik gecede, sesini duysam.

Yildizlardan birtanem, selam yollasam.

Biterdi yalnizligim, bana gelince.

(Filderstadt, Aralik 1998)', 'Sabah günes dogacak, kizil ufuktan. Senin hayallerinle, dolu bir gece. Yalnizlik arkadasim, yildizlar dostum Yasamak cok güzeldir, insan sev...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/insan-sevince-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın sonu yoktu', 'zamanin-sonu-yoktu-guzin-osmancik-y4uro', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretin yaktığı kalplerde

Yaşandı SONsuz sevgiler

Akşamın çöktüğü her yerde

Aşk yanı başımdaydı

O zaman çalındı canı yakan şarkılar

Orada sevgi beni vurdu

Zaman:

Zamansızlık kadar uzundu

Zamanın SONu yoktu

SONun vakti gelecek diye

Kavuşma hayali ile geçti seneler

Yazlar, kışlar, baharlar, mevsimler

Seneler sona akıp gitti

Vuslat zahirde hiç gerçekleşmedi

Hayallerin kurulduğu en güzel düşler

Gecelerdi

Gecelerde son buldu ayrılık

Vuslat; hayallerde gerçekleşti

                               Zamansız', 'Hasretin yaktığı kalplerde Yaşandı SONsuz sevgiler Akşamın çöktüğü her yerde Aşk yanı başımdaydı O zaman çalındı canı yakan şarkılar Orada s...', ARRAY['Türk Edebiyatı','Şiir','Güzin Osmancık']::text[], 8.5, '{"poet":"Güzin Osmancık","poet_slug":"guzin-osmancik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zamanin-sonu-yoktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Osman Yok Artık', 'osman-yok-artik-nur-demirciler-roa3w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte bugünkü kötü haber.

Osman yok artık.

Kim olduğu ne farkeder sanki,

Adı, işi, ya da yaşı,

Evli mi? bekar mı? 

İyi mi? kötü mü? 

Ne önemi var,

Artık yaşamıyor ki.

Ama merak edenlere,

İşte Osmanın hikayesi,

Evliydi, 

sağlık nedeniyle erken yaşta,

bankanın birinden emekli,

eşi Ayşe...

birde geç gelen mutluluk 2 yaşındaki kızları,

ikizlerden diğeri oğlan, doğumdan hemen sonra öldü.

Ne olduysa ondan sonra oldu.

Osman buna dayanamadı.

Hastalandı,

Ve işte sonuç,

Ayşe önce ikizin birini, şimdi de,

sevgili eşini verdi kara toprağa,

Üstelik yan yana.

Nasıl dayanır Ayşe''nin yüreği buna,

Allah sabır versin Ayşe''ye,

Rahmet eylesin Osmanı''na,

İbret olsun bizlere,

Yalan dünya kime kalmış,

Vakti gelen fani olmuş,

Hey gidi canına yandığımın dünyası hey,

Dibine kibrit suyu parasının pulunun,

Sevdiklerin yanında mı? 

Sağlığınız yerinde mi? 

Her anın tadını çıkar,

Hayat senden çalmadan birşeyleri,

Sen kopar ondan gücünün yettiğini,

Aman ha sakın unutmayın SEVİYORUM demeyi...

Şubat/2006

İstanbul', 'İşte bugünkü kötü haber. Osman yok artık. Kim olduğu ne farkeder sanki, Adı, işi, ya da yaşı, Evli mi? bekar mı?  İyi mi? kötü mü?  Ne önemi...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/osman-yok-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damla Ateş', 'bir-damla-ates-sair-swain-spweh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateşin özünden yanağıma süzülen damla; 

Yak beni, dokun sevgiliye,

Yak damarlarında aşkı,

Yaz alnına kırışığımı; 

Alevim düşsün ellerine', 'Ateşin özünden yanağıma süzülen damla;  Yak beni, dokun sevgiliye, Yak damarlarında aşkı, Yaz alnına kırışığımı;  Alevim düşsün ellerine...', ARRAY['Türk Edebiyatı','Şiir','Şair Swain']::text[], 8.5, '{"poet":"Şair Swain","poet_slug":"sair-swain","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-damla-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyor Musun', 'anliyor-musun-ethem-turan-na4mu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canım sıkkın ve durgunum 

Olmamalı mıyım 

Nasıl olmam ki sensizim 

Yaşarım yokluğunu 

İstemeyişlerine kırılır içime atarım 

Amansız hastalık gibisin 

Yaşayamıyorum 

Anlamıyorsun beni değil mi 

Sensiz olamıyorum 

Seni kaybetmeyi göze alabilsem 

Alamıyorum

Yaşamın tadını kaybedeli çok oldu 

Günlere kısa demesinler sakın 

Bana  günler ay oldu 

Sevmemem gerek belki 

Ama anlamıyor bu gönül 

Laf dinlemiyor 

Anlıyor musun 

Gitmelerine  gücenir bu gönül 

Özler, bir resmini görmek  ister

Hatırasını canlandırmak

Bulamaz yine kırılır içine atar 

Bir gün

Bu deniz taşarda 

Sularında bu gönül adasını istila ederse

Bu ada boğulmaya razı

Sularında kaybolup gitmeye istekli 

Tusunami’sini  beklemekte

Anlıyorsun değil mi', 'Canım sıkkın ve durgunum  Olmamalı mıyım  Nasıl olmam ki sensizim  Yaşarım yokluğunu  İstemeyişlerine kırılır içime atarım  Amansız hastalık...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/anliyor-musun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangisi Gerçek', 'hangisi-gercek-isik-german-ersoy-ct06a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gerçek sanatçıyla

Sahtesini ayırmak için

Aradaki kopya kağıdını

Çıkarmamız gerekir', 'Gerçek sanatçıyla Sahtesini ayırmak için Aradaki kopya kağıdını Çıkarmamız gerekir...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hangisi-gercek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Varsın Bir Yoksun', 'bir-varsin-bir-yoksun-sukret-baldede-n7st6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varsın olsun demekle olmuyor

Olduğunda ben yokum, sen varsın

On yıl öncesinin düşünü kuruyor...

Canım sıkılıyor, sen yoksun ben varım.



Bugün o dün değil, dünün bugünü sen değilsin

Bu gününde, dünün de tek var olanı benim.

Sen bir varsın bir yoksun, masal gibi

Canım sıkılıyor, ne sen varsın, ne ben yokum...', 'Varsın olsun demekle olmuyor Olduğunda ben yokum, sen varsın On yıl öncesinin düşünü kuruyor... Canım sıkılıyor, sen yoksun ben varım. Bugün...', ARRAY['Türk Edebiyatı','Şiir','Sükret Baldede']::text[], 8.5, '{"poet":"Sükret Baldede","poet_slug":"sukret-baldede","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-varsin-bir-yoksun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Bu Kadar', 'benden-bu-kadar-isik-german-ersoy-79g0b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni

Şiirlere yazmalı önce

Sonra bestelemeli 

Ve de kaset yapıp

Piyasaya sürmeli

Benden bu kadar

Gerisini sen düşün

Artık', 'Seni Şiirlere yazmalı önce Sonra bestelemeli  Ve de kaset yapıp Piyasaya sürmeli Benden bu kadar Gerisini sen düşün Artık...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benden-bu-kadar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim', 'seni-ozledim-ethem-turan-gwk9q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yar 

Kokunu özledim 

Saçının telini

Dudaklarındaki gülüşünü

Kirpiklerinin dizilişini

Kaşını 

Gamzeni 

Gözlerini 

Seni özledim 

 Hani itmelerini 

İstemeyişlerini

Bana ne deyişlerini

Neyseeeeee

Seni özledim 

Gözündeki yaşını 

Saçını savuruşunu 

Koşmanı 

Umursamayışını 

Tenime dokunuşlarını

Anla işte seni özledim 

Gözlerini kaçırışlarını 

Israrla bakmayı 

Seni belleğime çiviyle kazımayı 

Elini tutmayı 

Yapamasam da bir kez sarılmayı 

Anlıyorsun değil mi

Seni yaşamayı özledim', 'Yar  Kokunu özledim  Saçının telini Dudaklarındaki gülüşünü Kirpiklerinin dizilişini Kaşını  Gamzeni  Gözlerini  Seni özledim   Hani itmeler...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seni-ozledim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyalar', 'papatyalar-isik-german-ersoy-dirwr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık

Size de

İnancım kalmadı

Papatyalar

Hani o seviyordu

Beni', 'Artık Size de İnancım kalmadı Papatyalar Hani o seviyordu Beni...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/papatyalar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pitalistler…', 'pitalistler-yusuf-ziya-leblebici-riyko', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Delik deşik olmuş beynim

Pitalistler tepemizde

Dikta rejim ne kardeşim

Kambur olmuş belimizde

O kimdi ki bize rap rap

Dama soktu zorlayarak

O içerken beyaz şarap

Bize döndü coplayarak

Baş kaldırdık baş kesildi

Tabureye tekme indi

Hain miydik biz kardeşim

Hani ülke bizlerindi

Yani biz de çağ atladık

Çağ yerine taş yaladık

Hortumcular kol gezerken

Olanlara baka kaldık

O kültürüm nerde benim

Baldır bacak önümüzde

Manken topu ne kardeşim

Pop mu vardı türkümüzde

O kim ola transparan

Sanatçı diye sunulan

Popülerlik sevdasına

Bizim önümüze konan', 'Delik deşik olmuş beynim Pitalistler tepemizde Dikta rejim ne kardeşim Kambur olmuş belimizde O kimdi ki bize rap rap Dama soktu zorlayarak ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/pitalistler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyerem…', 'diyerem-yusuf-ziya-leblebici-9dap0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ak beyazdan ayrılsa da 

Renklerini ben sevirem

Öteleyen olsa bile

İnadına şah diyerem

Başım üstü dost dediğin

Yoluna ser post dediğin

Kalpten geçer yol bildiğin

Doğruluğa çık diyerem

Allah’ı kalpte bilirem

O’nu beynimde görürem

Doğru isen hah diyerem

Sapar isen vah diyerem

Aynaya bak ne görürsen

Ne okursan sen gözünden

Çizgileri görmez isen

İyicene bak diyerem

Ben yoluma hak demişem

İnsanları çok sevmişem

Önüme barış sürmüşem 

Ateşini yak diyerem

Toy balada dem olur mu

Soğuk sudan yem olur mu

Üreğimin sönse mumu

Çakmağını çak diyerem

Ne edersem ben edirem

Ölsem de ben gömülerem

Körolmasın gözün emi

Yusuf Ziya bak diyerem', 'Ak beyazdan ayrılsa da  Renklerini ben sevirem Öteleyen olsa bile İnadına şah diyerem Başım üstü dost dediğin Yoluna ser post dediğin Kalpte...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/diyerem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör olayım', 'kor-olayim-yusuf-ziya-leblebici-6pvca', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vur şu zincirleri bana

Kırmaz isem kör olayım

Ver şu gurbetleri bana

Yıkmaz isem kör olayım

Ey sevgili can yoldaşım

Gözüm üstündeki kaşım

Olsan da şu bulutlarda

Çıkmaz isem kör olayım

Seni saran bir dikenim

Yaprağında birikenim

Susar isen yağmurlara 

Yağmaz isem kör olayım

Hasatımda sevincimsin

Toprağımda ekinimsin

Yabancı bir ot da çıksa

Yolmaz isem kör olayım

Yusuf Ziya ben değilim

Ben diyecek sen bilirim

Şu gönlünü kapasan da

Açmaz isem kör olayım', 'Vur şu zincirleri bana Kırmaz isem kör olayım Ver şu gurbetleri bana Yıkmaz isem kör olayım Ey sevgili can yoldaşım Gözüm üstündeki kaşım Ol...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kor-olayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoca', 'hoca-isik-german-ersoy-knwp6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yeni ölene

Dua edip

Gömerken hoca

Düşünürdü kendini

O meftanın yerinde

Onu kim gömecekti

Acaba

Hangi hoca', 'Her yeni ölene Dua edip Gömerken hoca Düşünürdü kendini O meftanın yerinde Onu kim gömecekti Acaba Hangi hoca...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hoca-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye', 'niye-ethem-turan-5x562', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beyaz üzerine lekedir siyah 

Doğru üzerinde  yanlışta öyle

Peki yaşı olguna ermişe 

Aşk niye

Yılların üzerine  serilen toprağa

Tüm anlayışlara rağmen 

Gül fidanı ekmek  niye

Zincire vurulan aslanın 

Salıverilmesi gibi

Özgürlüğe koşuş

Niye

Önü setle tutulan suyun 

Hayat kaynağı iken 

Setini aşıp,yıkıp yok etmesi 

Niye

Şansı parada arayanlar

Hiç uğruna inadına  yok olanlar 

En büyük güç gönül gücü 

Hani nerede 

Zamanı kaçırmışların 

Bulduğunun değerini bilse de

Geç kalışının 

Hüznü niye', 'Beyaz üzerine lekedir siyah  Doğru üzerinde  yanlışta öyle Peki yaşı olguna ermişe  Aşk niye Yılların üzerine  serilen toprağa Tüm anlayışla...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/niye-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-ersin-yildirim-t2uoi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Önce iki damla yaş süzüldü gözlerimden

Sonra sensizliğin hasreti yaktı kalbimi

Düşünmekten yoruldum sensiz geçen günleri

Şimdi her yerde sen varsın

İşte sevmek bu   değilmi 

Güneşim ay gözlerin aynam oldu

Gözlerine bakınca  içinde cenneti gördüm

Gözlerimle  haykırdım sevgimi

Dilin sustuğu gözlerin konuştuğu anda sevdim ben seni 

İşte sevmek bu   değilmi 

Her şeyi göze aldım senin için

Uğruna canımı siper ettim

Akan her damla göz yaşıma sevgimi ekledim

Bir kere yüzüme gülmen için

İşte sevmek bu değilmi

Karşılık beklemeden sevdim

Belki bir gün seversin dedim

Düşlerimde hep seni bekledim

Sen seni sen olduğun için sevdim

İşte sevmek bu değilmi

Neden diye sormadan

Gözlerine bakmadan

Ellerini tutmadan

Uzaktan sevdim

İşte sevmek bu değilmi

Toprağa ekdim sevgimi

Belki büyür diye

İçine hasret kattım özlem biter diye

Ayrılığı kokladım çabuk dön diye

İşte sevmek bu değlmi

Sabretmeyi öğrendim

Gözyaşımı silmeyi 

Gözlerle konuşmayı öğrendim

Dilin çaresizliğini

İşte sevmek bu  değilmi

İçimde bir sen keşfettim

Bir tek ona söyledim sevgimi

Kendimi avuttum bir çocuk gibi

Korktum elimden alırlar diye seni

İşte sevmek bu demek değilmi

Sonbaharı bekledim daha çok severim diye

Kışın kar ile örttüm sevgimi saf kalsın diye

İlk baharı bekledim çiçek açar diye

Yazın ay gibi doğar diye

İşte sevmek bu  değilmi

Sıcaklığı özledim

Ellerin uzanır diye bekledim

Hep omzunda uyumak istedim

Belki gözlerime bakarsın diye

İşte sevmek bu  değilmi

Hasretin alev oldu

Ağladım söner diye

Özlemin keder oldu

Bekledim geçer diye

İşte sevmek bu  değilmi

Kimseye söylemedim belki güler diye

Kalbime sakladım ateşi söner diye

Gece ile kapattım kimse görmesin diye

Hep ölümü bekledim bu özlem  bitsin diye

İşte sevmek bu  değilmi', 'Önce iki damla yaş süzüldü gözlerimden Sonra sensizliğin hasreti yaktı kalbimi Düşünmekten yoruldum sensiz geçen günleri Şimdi her yerde sen...', ARRAY['Türk Edebiyatı','Şiir','Ersin Yıldırım']::text[], 8.5, '{"poet":"Ersin Yıldırım","poet_slug":"ersin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/sevmek-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebeb', 'sebeb-ersin-yildirim-hqqrz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sebebi me sebebi mi sordular

Sebebi ben değilim dedi

Gönlüme zincir vurdu 

Kilidi ben değilim dedi

Damlayan gözyaşım dedim

Ağlatan ben değilim dedi

Sevdiğim sensin dedim

Seven ben değilim dedi', 'Sebebi me sebebi mi sordular Sebebi ben değilim dedi Gönlüme zincir vurdu  Kilidi ben değilim dedi Damlayan gözyaşım dedim Ağlatan ben değil...', ARRAY['Türk Edebiyatı','Şiir','Ersin Yıldırım']::text[], 8.5, '{"poet":"Ersin Yıldırım","poet_slug":"ersin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sebeb-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-ersin-yildirim-0crfl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine hayallere dalmış gidiyorum 

Uçsuz bucaksız hayallere

Ve ben yine yalnız

Yine kederliyim

Ellerini tutmak istiyor ellerim

Gözlerine bakmak istiyor gözlerim

Sana bir can kadar yakın

Bir o kadar da uzağım

Seni görünce tutulur dilim

Ama hep konuşur gözlerim

İşte seviyorum diye haykırıyorlar

Ne olur duy artık sevdiğim.

Sevilmek güzelmiş

Sevmekten ziyade

Şimdi anladım seni sevince

Yinede seveceğim sen sevmesende', 'Yine hayallere dalmış gidiyorum  Uçsuz bucaksız hayallere Ve ben yine yalnız Yine kederliyim Ellerini tutmak istiyor ellerim Gözlerine bakma...', ARRAY['Türk Edebiyatı','Şiir','Ersin Yıldırım']::text[], 8.5, '{"poet":"Ersin Yıldırım","poet_slug":"ersin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdigim-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-ersin-yildirim-1y7l4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceleri gündüze çevirdim

Beklemekten usandım

Yalnızlığın türküsünü söyledim 

Zamanı durdu sandım sen olmayınca

Müebbet hükmünü yedim

Cezam ise özlemek

Tek şahidim sendin şu yalan dünyada

Ne olur dön artık gittiğin o meçhullerden

Bilirim ki bu ayrılık bitecektir

Tek korkum unutulmaktır benim

Ağlamaya alışsa da gözlerim

Sigara dumanı gibi uçup gitmekten korkar bu gönlüm', 'Geceleri gündüze çevirdim Beklemekten usandım Yalnızlığın türküsünü söyledim  Zamanı durdu sandım sen olmayınca Müebbet hükmünü yedim Cezam ...', ARRAY['Türk Edebiyatı','Şiir','Ersin Yıldırım']::text[], 8.5, '{"poet":"Ersin Yıldırım","poet_slug":"ersin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-336-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceza', 'ceza-ersin-yildirim-l66v1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mecnun ettin beni çöllerde gezer oldum

Kerem ettin dağları deler oldum

Ferhat gibi şirini özler oldum

Kahrettin beni derdimden verem oldum

Irmak idim çöl eyledin

Şu zengin gönlümü fakir eyledin

Fidan idim zay eyledin

Kahrettin beni derdimden verem oldum

Şu dağlara duman olaydım

Bir kurşuna hedef olaydım

Viran yurda baykuş olaydım

Kahrettin beni derdimden verem oldum

Selvi boyuna köle olaydım

Al yazmana  oya olaydım

O elleri tutan olaydım

Kahrettin beni derdimden verem oldum', 'Mecnun ettin beni çöllerde gezer oldum Kerem ettin dağları deler oldum Ferhat gibi şirini özler oldum Kahrettin beni derdimden verem oldum I...', ARRAY['Türk Edebiyatı','Şiir','Ersin Yıldırım']::text[], 8.5, '{"poet":"Ersin Yıldırım","poet_slug":"ersin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ceza-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm-se...', 'gulum-se-selma-sengoren-r50l0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülün yaprağı değince gönlüne

Hayallerden düşen kırmızı misali

Geçmişte silinecek hatıralar

Yaşanan demleri bulamazsın

Yağmur damlası gözlerinde

Savrulur fırtınada kelimeler

Konuşmalar çaresiz nefesinde

Sen

yağmuru sevemezsin

Çiçeklerde mahsun duruşlar

Bundandır suskun bulutlar

Bundandır çöllerin ağlaması

Sen 

mevsimleri sevemezsin

Coşkun hançer sinene saplanır

Anlarsın vurgunların acısını

Yaşarken hasrete doymuş yüreğin

Sen 

özlemeyi bilemezsin

Ruhlarda kaybolan gülüşler

Bundandır bakışlarda hüzünler

Bundandır son serzenişler

Sen 

kimseyi sevemezsin…

---------

Kaybetmeden yaşanacak ömrün

Filizlenen hayaliyle,

Kimbilir hangi şafakta muştun 

Sevmeyi bil yeter ki, 

Üzülme…', 'Gülün yaprağı değince gönlüne Hayallerden düşen kırmızı misali Geçmişte silinecek hatıralar Yaşanan demleri bulamazsın Yağmur damlası gözler...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gulum-se-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başımızda çıngıraklı yılan var.', 'basimizda-cingirakli-yilan-var-i-lhami-arslantas-rkj0b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey...! ahali biz duymadık demeyin,

Ankara’da türlü türlü plan var.

Oradadır hortumcusu, çalanı,

Patlaması gereken bir balon var.

Çıban başı ta baştadır bilinmez,

Ne hikmetse bu forsları delinmez,

Niye bilmem tarihten hiç silinmez,

Tepemizde sabıkası olan var.

Umursamaz seçip saldığın vekil,

Diyemezsin artık oradan çekil,

Böyle gitmez gitmemeli bu şekil,

Hakkımızı yasal deyip çalan var. 

Fukara aç onlar gazı dolarlar,

Elden önce ortalığa salarlar,

Yasa yapar kendileri delerler,

Suçluları yasa yapıp salan var.

Bilirim ki her tür dümen orada,

Kim bilir kim zanlı olur sırada,

Sen mi ben mi çıkacağız kurada,

Suçsuzları içeriye alan var.

Der İlhami sabra zaman kalmadı,

Keyfe keder kimse ozan olmadı,

Aç avunma deme çilem dolmadı,

Başımızda çıngıraklı yılan var.', 'Ey...! ahali biz duymadık demeyin, Ankara’da türlü türlü plan var. Oradadır hortumcusu, çalanı, Patlaması gereken bir balon var. Çıban başı ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/basimizda-cingirakli-yilan-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savruk Gülüşler', 'savruk-gulusler-umut-beylik-ttbq2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ben yenilmişim	

Gecenin kollarina savruk gülüslerimle.		

Kimler var şimdi,		

Ezik düslerimde? 		

Yoklugunun kor ateslerindeyim		

Seni özledim.		

Geceye bir tebessüm düşsün istedim.

Sen düştün aklıma,

Gecenin en namert pususundayım.

Hangi söz dermanim olur? 

	

Seni özlemenin adini öfke koymusken,

Deli hasretlerin bahçesinde,

Acina yosun tutmusum…

Hangi geçitlerin yüreğisin? 

Munzur ol,

Zilan ol,	

Düslerimin en yalnız bereketisin.

Ellerimi al koynuna…

Umudum ol...

   

''''Başlık seçiminde bana yardimci olan,Gula ve Fethi ASLAN dostlara tesekkürlerimi sunarim.''''', 'Bir ben yenilmişim	 Gecenin kollarina savruk gülüslerimle.		 Kimler var şimdi,		 Ezik düslerimde? 		 Yoklugunun kor ateslerindeyim		 Seni öz...', ARRAY['Türk Edebiyatı','Şiir','Umut Beylik']::text[], 8.5, '{"poet":"Umut Beylik","poet_slug":"umut-beylik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/savruk-gulusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar vicdan heyeti', 'cocuklar-vicdan-heyeti-i-lhami-arslantas-9z67h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ne demek ben ne demek

 İnsanın madeni aynı

Laz nedir Çerkez ne demek 

hepsinin de geni aynı

Alevi,Sünni diyorlar 

Soyu aynı bilmiyorlar

Farklı yoldan gidiyorlar

Birleşen zemini  aynı

Zenci  beyaz birdir kanı

Acır hepsinin de canı

Vermez  renk dini imanı

Bedendeki canı aynı

Bak ne icat etmiş gavur

İstersen bir yalan savur

Yaptığıyla duyun gurur

Ateşin dumanı aynı

Televizyon, bilgisayar

Bir dünya sesini duyar

Verin kendinize ayar

Amacın imanı aynı

Silin atın art niyeti

Köhneleşmiş zihniyeti

Çocuklar vicdan heyeti

Doğduğunda dini aynı', 'Sen ne demek ben ne demek  İnsanın madeni aynı Laz nedir Çerkez ne demek  hepsinin de geni aynı Alevi,Sünni diyorlar  Soyu aynı bilmiyorlar ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cocuklar-vicdan-heyeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nesin', 'nesin-ethem-turan-qq4cz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapıyı kapamak gibi 

Geceyi kapamak

Yaşananlara set vurma 

Mola verme  hayata

Dışarıda kalan ışık gibi 

Anahtar deliğinden de olsa 

Sızıp girersin kapalı kapının ardına 

Odamda uyurken de olsa 

Loş ışık olur geceme 

Renk katarsın karanlık odamda 

Uyusam da gezersin 

Kim bilir 

Yanağımı okşar seversin 

Uykuma kıyamaz 

Sabah ışımasıyla çekip gidersin

Gecemi gündüze teslim eder

Karanlığa bırakamazsın beni 

Seversin sende 

Bilemem 

Elle tutamam ki seni

Gözle görürüm ancak 

Hayalet sevgili gibisin

Haftada birde olsa

Sanal dünyama gelip girersin

Olsun 

Sen benim için çoooook değerlisin

Karanlık dünyamda 

Ateş böceğimsin', 'Kapıyı kapamak gibi  Geceyi kapamak Yaşananlara set vurma  Mola verme  hayata Dışarıda kalan ışık gibi  Anahtar deliğinden de olsa  Sızıp gi...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nesin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buyuk kucuk firtinalar', 'buyuk-kucuk-firtinalar-ulya-erkman-9d4rj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Firtinalari kim bilmez? 

Siddetlerini

Kontrol edilemeyen 

Kuvvetlerini 

Butun bir bolgeyi nasil

Tahrip ettiklerini

Insafsizca esislerini

Kucuk firtinalar da gozukur 

Zaman zaman

Bir aile reisi gibi, farkedilmezler 

Bazan

Onlar da olur bir ailenin firtinasi

Her an

Kontrol edilemeyen hirslari savurur 

Herseyi durmadan

Buyuk firtinanin kirdigi 

Kollar gibi

Bu kucuk firtina da kirar 

Bir kol belki

Buyuk firtinanin bir hamlede 

Devirdigi agac misali

Kucuk firtina da bir yumrukta 

devirir esini

Buyuk firtinanin tahrip ettigi gibi

Bir bolgeyi

Kucuk firtina da tahrip eder ailenin

Butun benligini

Buyuk firtinanin tahrip ettigi evin

nasil yapilamazsa ayni esi

Kucuk firtinanin tahrip ettigi ruhlar da

Olamaz artik eskisi gibi

Buyuk firtina esip gidince 

Uzaklara

Bolgeyi kurmak icin baslanir tekrar

Calismalara

Kucuk firtina da cekip gitmeli

Bir tarafa

Belki kavusur bu kucuk aile

Nihayet refaha

Buyuk firtinalar allahin isi

Kucukleri durdurmak bizlere kalmis degil mi?', 'Firtinalari kim bilmez?  Siddetlerini Kontrol edilemeyen  Kuvvetlerini  Butun bir bolgeyi nasil Tahrip ettiklerini Insafsizca esislerini Kuc...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/buyuk-kucuk-firtinalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz''in Rengi', 'deniz-in-rengi-naciye-bildim-84jzi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir savaşcının yorgun düşlerinde tanıştım

sevdayla,

Bir elimde kalbim,yüreğimde silahım.

Gözlerim alev alev yanarken,

Kah söylendi boş,kah söylendi hoş dudaklarım.

Ben gökyüzünü gözüm kapalı iken tanıdım,

Gök mavi derlerdi oysa ben inanmazdım.

Hani deniz mavi renkliydi,

ben denizi güneş batışında kan renklerinde tanıdım.

              02.07.2000', 'Bir savaşcının yorgun düşlerinde tanıştım sevdayla, Bir elimde kalbim,yüreğimde silahım. Gözlerim alev alev yanarken, Kah söylendi boş,kah s...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deniz-in-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Kızım Ceren''e', 'canim-kizim-ceren-e-naciye-bildim-g6e8b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana hep kırmızılar giydirip

Saçına rengarenk çiçekli tokalar takacağım.

Gözlerin alabildiğince parlak

Ve yıldızları oraya yağdıracağım.

Saçların hep kıvrım kıvrım,lüle lüle

Papatyalardan taçlar yapacağım,

Ve sadece ben okşayıp,ben tarayacağım.

yanakların hep böyle al

Dudaklarında dolu dolu sevgiler,

Bir beni birde babanı

Vsevgiyle buseler ver  Babana,bana, birde kardeşine', 'sana hep kırmızılar giydirip Saçına rengarenk çiçekli tokalar takacağım. Gözlerin alabildiğince parlak Ve yıldızları oraya yağdıracağım. Saç...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/canim-kizim-ceren-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Kızım Ceren', 'canim-kizim-ceren-naciye-bildim-dk86a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani varya saçların

Dalga dalga yüzer gözlerimde.

Alaycı bakışların  simsiyah gözlerin

Her an her saniye benimle.

sana her canım diyip sarıldığımda,

Binbir yerimden volkanlar patlar.

Kelimeler yetmez duygularıma

Milyonlarca dünya olsa

değmez hiç biri senin yokluğuna.

Ve diyebilmem güzel

Canım biricikkızım,yavruma.

04.06.2001', 'Hani varya saçların Dalga dalga yüzer gözlerimde. Alaycı bakışların  simsiyah gözlerin Her an her saniye benimle. sana her canım diyip sarıl...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canim-kizim-ceren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-naciye-bildim-wbs34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözleri doluydu bakarken,

Yüzyıllardır özlemiş gibiydi yüreği.

Elinde sigara çektikçe içine

Volkanlar patlıyordu heryerinde.

Alev alev tüterken dumanlar

Bir yara bizim için açılıyordu ciğerinde.

Titrektiya elleri,

Büğüm büğümdü dudakları.

Arasına sıkışmış kalmışken bir çift kelime

Ve

Ve gözleri doluydu bakarken.

ama bir damla yaş akmadı gözlerinden

baba yüreği 

dayanamadı işte.

         20.08.2001', 'Gözleri doluydu bakarken, Yüzyıllardır özlemiş gibiydi yüreği. Elinde sigara çektikçe içine Volkanlar patlıyordu heryerinde. Alev alev tüter...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/babama-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruyor', 'vuruyor-yasar-gurlek-fg6x6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben kime  yazayim  zalim  derdim

Alip  beni  yerden  yere  vuruyor

Seline  irmagina  kurdum bendimi

Sanki  yetmez gibi durup  vuruyor

Hasret koydun doyamadim o can anaya

Doya doya sarilmadim candan babaya

Uzak ettin beni hep hisim akrabaya

Sanki  yetmez  gibi  donup  vuruyor

Beni  yardan ayri  koyup  gurbete  attin

Her olur olmaza  pul diye  sattin

Benden alip gittin zenginde tuttun

Sanki  yetmez  gibi  gelip  vuruyor

Silemem goz yasim akar  sel  gibi

Simdi  babam  dostlarim bana  el gibi

Her  yerde  yetistin  esen yel  gibi

Sanki  yetmez  gibi  ucup  vuruyor

Yasar  gurlek

24-02-2006 rotterdam

HOLLANDA', 'Ben kime  yazayim  zalim  derdim Alip  beni  yerden  yere  vuruyor Seline  irmagina  kurdum bendimi Sanki  yetmez gibi durup  vuruyor Hasret...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/vuruyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askini', 'askini-yasar-gurlek-c0b6a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugun  aska  gelip  optun  askini

Dindirdin yuregimde seli taskini

Nasil oderim ben  senin  hakkini

Allahtan   dilerim  cenneti   sana

Her  derdime  ortak olup  bitirdin

Acilarimi    alip    nese    getirdin

Bunca derdim alip nere goturdun

Rabbimden dilerim kevseri  sana

Gece gunduz yollarimi  beklersin

Dertlerin    ucuna   cile   eklersin

Her turlu  aciyi benden saklarsin

Rahmandan dilerim sabir,i  sana

Sevmedin  bosa  bu   koca cinari

Senin icin aglarim ben zari  zari

Cicekten  yapiyor  bak  bali  ari

Hudadan  diledim cenneti  sana

Yasar  gurlek

24-02-2006 rotterdam

HOLLANDA', 'Bugun  aska  gelip  optun  askini Dindirdin yuregimde seli taskini Nasil oderim ben  senin  hakkini Allahtan   dilerim  cenneti   sana Her  ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/askini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevindir RABBIM', 'sevindir-rabbim-yasar-gurlek-prx0v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Guleyim  izin ver  bende  guleyim

Vatanima  yurduma  donup  gideyim

Bir dilegim var huzurunda eda edeyim

Her seyin caresi  dermani  sende

Makamim mescidde  ard  sira  olsun

Dertlerim tukenip  neseler dolsun

Bu yasar,i huzurunda sevgide bulsun

Her seyin caresi  dermani  sende

Bu yasar  kulunu sevindir rabbim

Senin ismu azaminla carpar bu kalbim

Sen buyuksun ulusun ey buyuk rabbim

Her seyin caresi  dermani  sende

Yasar  gurlek

10-02-1992 Leiden

HOLLANDA', 'Guleyim  izin ver  bende  guleyim Vatanima  yurduma  donup  gideyim Bir dilegim var huzurunda eda edeyim Her seyin caresi  dermani  sende Ma...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevindir-rabbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gurbet', 'bu-gurbet-mikdat-bal-scp8t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kellemiz koltukta savaşıyoruz

Ne şehit ne gazi, ne cihattır bu

Cinnet sınırına yanaşıyoruz

Ne sabır,ne sebat ne inattır bu

Bu nasıl tahammül şaşırıyoruz

Vatanı anınca yaşarıyoruz

En ağır işleri başarıyoruz

Ne takat, ne kuvvet ne sıhhattir bu

Yokluğu çekeriz servet içinde

Zehiri tadarız şerbet içinde

Yaşarız gurbeti, gurbet içinde

Ne geçtik, ne seçtik ne biattır bu

Ters gitti olmadı istediğimiz

Şimdi anlaşılmaz ne dediğimiz

İstikbal adına ödediğimiz

Ne değer, ne bedel ne fiyattır bu

Mikdatî der hergün kalbim kırılır

Gurbetçiye türlü akıl verilir

İşte cehenneme burdan girilir

Ne köprü ne geçit, ne sırattır bu', 'Kellemiz koltukta savaşıyoruz Ne şehit ne gazi, ne cihattır bu Cinnet sınırına yanaşıyoruz Ne sabır,ne sebat ne inattır bu Bu nasıl tahammül...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Şekeri', 'elma-sekeri-muammer-erturan-kcihq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değişe değiştire

.......değişe değiştire

................sardık yokuşa...

Vurula kırıla

.......vurula kırıla

................ palazlandı kavga...

Adam baktı,

.................pabuç pahalı...

Döne

..........döne

...............döne

................döne

...............döne

.......döne

döne,

yüzseksen derece 

...........ters bir yönde

.......................buldu kendini...

Bir elma şekeri

........tutuşturmuşlardı eline

yalansın

...ve oyalansın

........ve oyalasın diye

havadan sudan şeylerle

............    potansiyel muhalefeti...

Pek tatlı geldi

....elma şekeri nitekim,

..........bizim eski cengâvere ki,

yalana yalana

.....yalana yalana

.............alıştı yalana...

Ve dahi

.....başyalakalığa kadar

.............vardırdı işi taaa ki...

(4 Nisan ''97)', 'Değişe değiştire .......değişe değiştire ................sardık yokuşa... Vurula kırıla .......vurula kırıla ................ palazlandı kav...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/elma-sekeri-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum...', 'sustum-halil-manap-3mpux', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sustum... 

Zehrinizi kustum

Ey ikinci yüzünü takanlar! ...

Kırık bir hançer gibi yırtarak karanlığı 

Yepyeni bir dünya kurdum. 

Kirsiz... İsyan eden şarkılarımla...

Kavramları yeniden irdeleyen bakışımı alın! 

Evreni sarsacak depremler sallıyor yüreğimi

Kuyuya çıkrıkla kovaları salın... Su iç/in! 

Ah! Siz! Bilemezsiniz! ...

Peki siz kimsiniz? ..Nesiniz? 

Dar dünyasından çıkamayan dinozor kırıkları...

İkiyüzlü ihanetle kirletiniz suları! ...

Paçamın yırtıkları...

......

......', 'Sustum...  Zehrinizi kustum Ey ikinci yüzünü takanlar! ... Kırık bir hançer gibi yırtarak karanlığı  Yepyeni bir dünya kurdum.  Kirsiz... İs...', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sustum-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aptal Hasan', 'aptal-hasan-muammer-erturan-h8csk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu coşkuya bak! ..

Kıçını yırtacak kadar bağırındığı

altı üstü bir gol...

Globalleşme denen karambol

leşleşen dünya 

yükselen enflasyon

düşen yaşam kalitesi

düşünce suçluları

kirli savaşlar 

gözaltında kayıplar 

yargısız infazlar

coplanan analar

açlıkla pençeleşen çocuklar... 

Uzar da uzarmış bu liste 

öte yanda

umurunda değil adamın... 

Umurunda olmasın diye gerçi 

kahvehanesine 

meyhanesine 

evine kadar 

getirildi ya stadyumlar... 

Maçlar biter 

''kritikler'' başlar 

ve dolar zaman... 

Zaman dolar

adam boşalır iyice

ve haberi olmaksızın 

nasıl bir çarkın dişlilerince 

öğütüldüğünden habire

karışır sürüye... 

O gollerle oyalandıkça

çok gol yersin daha yaşamdan

aptal Hasan! ..

(16 Eylül ''98)', 'Şu coşkuya bak! .. Kıçını yırtacak kadar bağırındığı altı üstü bir gol... Globalleşme denen karambol leşleşen dünya  yükselen enflasyon düşe...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/aptal-hasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Sevgilim Özgürlük', 'tek-sevgilim-ozgurluk-muammer-erturan-cyhtx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neydi o içime sığmayan 

içimin sığmadığı ya da 

ya sabahları bulan sarhoşluklar 

ve onca yol katedip de 

diyemediğim gene? ..

Paylaşım günlerinin 

yoldaş çisentisini 

ahmak ıslatana çeviren 

o aymaz umut, 

nice umarsız kıvranışlara gebeymiş 

nice sellere

kendine bir paye 

çıkarmasın diye düşman 

göz pınarlarımda hapsettiğim... 

Ufkunda güneşin 

doğası yokmuş meğer...

Meğer ki 

mis gibi kokuyormuş toprak

parçalamak varmış kafesi 

ve kanatlanmak 

uçsuz bucaksız maviliklerde

ve diyebilmek: 

Tek sevgilim özgürlük! ..

(Temmuz ''79, Pangaltı)', 'Neydi o içime sığmayan  içimin sığmadığı ya da  ya sabahları bulan sarhoşluklar  ve onca yol katedip de  diyemediğim gene? .. Paylaşım günle...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tek-sevgilim-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Sular Olur ki', 'gecmis-sular-olur-ki-huseyin-salim-saracer-4nu9j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın kanununu yazsam yeniden

Gözlerin çinilenmiş kalbimin duvarına en mavi yerinden

Aşkın asude bir aşkın baharat ülkesi 

Yolunda kalsam da yalın kalem, yalın kalp

Çöller arşınlamaktayım, zeybek oynamaktayım

Ölülerimin ardından, ömürlerimin ardından

Çal zurnacı, kan sun solgun rengine gülün

Uçan halılar muttasıl açık pencere arar yekpare taşlanmış bir ufukta

Camdan cama vurur yaralı bir kumru, yaralı bir sohbet

Dolgun kahkahalar çınlar, patlar sığ sular, memleketim, memleketim

Tennurem her gün ölür, her gün olur, evin arar

Bayramgâha gider, segâhla

Bir şair çocuk, bir tebessüm, bir heyecan, bir hayret

Esirgemeyen, bağışlamasız büyükadımların ardından

Ve hep iyi insan, hâlâ kendini başkalarına açış

Dünyanın en kimsesiz şairi, en kimsesiz aşığı

En sarsıntıya açığı, sarsılmadan kayıp gidiyor 

Dalgaların üstünde, köpüklerle sevişerek

Dünyayla bir, sularla bir, rüzgarla bir

...

Batan gün kana benziyor, aşkla kapanıyor

Üzerine denizin çinçinesinin

Kabak kemanesiyle hıdır ve salyangoz boruzanıyla iliyas

İki yavru yonis düşmüşler peşine 

Kanlı perdesini yırtayorlar yenihayatın ki

Masmavi ufuk fışkırsın en çürük satıhlardan:

Sevişelim a dostlar akşamlarla, sularla 

Şahitsiz, sahipsiz

Ve bütün zamanlarda

N’ayrı dunyasız ve dünyada

Alabora, alaborda

....

Aşk bir emanet, annem sana terlik pabuç

Alacak, aşk narin, aşk bir terbiye

Aşk bir açıklık, aşk kendi oluşunu

Sarsıntıya açış, tesadüfe açış, bir çekiliş

Kayboluş, olgunlaşma, unutulma, dışarda kalış

‘Beni bu kadar sevdiğini bir bilebilseydim’leri duyamayış:

Bende bir dem ben bile kalmadı aşkdan başka

Aşk yoldan da başka aşkdan da başka bir aşka... veyl

Hasselby

9 agustos 2003', 'Aşkın kanununu yazsam yeniden Gözlerin çinilenmiş kalbimin duvarına en mavi yerinden Aşkın asude bir aşkın baharat ülkesi  Yolunda kalsam da...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Salim Saraçer']::text[], 8.5, '{"poet":"Hüseyin Salim Saraçer","poet_slug":"huseyin-salim-saracer","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/gecmis-sular-olur-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben de Seni Özledim Bebeğim...', 'ben-de-seni-ozledim-bebegim-cafer-tayyar-ozkan-izahz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tenimde derin boşluklar oluştu sensizlikte... 

yalnızca sen titretiyorsun aşkınla bu canı... 

ben azına razıyım... 

azına razıyım çünkü aza razı olmayan çoğunu bulamazmış... 

bırak artık tenine hasret ekmeyi... 

hayat aşkla yaşamaya değer... 

sevgisiz aşksız geçen her gün zarar... 

zararlarını çoğaltma! ! ! iflas edersin... 

hayat bu yaşta iflas ettirilecek kadar ucuz değil... 

bu nedenle, her fırsatta, her yerde, her an aşkımızı yaşayalım... 

çünkü yarının kefesi yok, bitmez... 

bu cihan nicelerini yutmuş asırlardır... 

aşka dair ne varsa yaşanmalı... 

yoksa ihtiyarlıkta ahu vah etmek akıl karı değil... 

hayatını keşkelerle değil

iyi ki yaşamışım, iyi ki yapmışım diyeceğin sözlerle anlarla doldurmaya bak... 

giden gelmiyor geri... 

heybenin gözünü keşkelerle doldurursan,

yarın keşkelerine cevap bulmakta zorlanır gönlün... 

en iyisimi yol yakınken

hele ki seni delicesine seven sevgilin varken

sevip sevilirken aşkı yaşamak en güzeli...

teninden sevgisiz ödün verme...

yoksa hep senden eksilir

gönül fermanını bulduğun da dinlememeli

diyebilirsin ki sevgimiz risk taşıyor

hayatın her zerresi risk

ya aldığın nefesi veremezsen geri...

ya sevdiğin kişi kaprislerinden bıkıp çekip giderse...

eşin dostun terkederse...

düşünce bir tekme daha atarlar insana...

gel gerçek sevgi taşıyorsan kalbinde

sevgilinin nefesine tenine gel...

en vefalı dost, seni gerçekten karşılıksız, 

çıkarsızca sevendir...

yarın çok geç olabilir aşka... 

23 Şubat 2006 Ankara', 'tenimde derin boşluklar oluştu sensizlikte...  yalnızca sen titretiyorsun aşkınla bu canı...  ben azına razıyım...  azına razıyım çünkü aza ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ben-de-seni-ozledim-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A - Ey zalim gurbet?', 'a-ey-zalim-gurbet-mikdat-bal-hl35r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bitmiyor kederin, tükenmez gamın

Öldürecek misin, ey zalim gurbet? 

Ufaktan ufaktan esiyor samın

Solduracak mısın ey zalim gurbet? 

Öyle bir seraba bağlattın beni

Hasret ateşiyle dağlattın beni

Otuz dort senedir ağlattın beni

Güldürecek misin ey zalim gurbet? 

Umutlarım vardı yok ettin benim

Sana ilenmemi hak ettin benim

Simsiyah saçımı ak ettin benim

Yolduracak mısın ey zalim gurbet? 

İstikbal adına kazdın kuyumu

Sinir küpü ettin bozdun huyumu

İnsafa gelip de artık suyumu

Kaldıracak mısın ey zalim gurbet? 

Mikdatî der ettin gönlümü viran

İyileşmez artık derindir yaran

İnsafın mı yoktur her dakka her an

Saldıracak mısın ey zalim gurbet?', 'Bitmiyor kederin, tükenmez gamın Öldürecek misin, ey zalim gurbet?  Ufaktan ufaktan esiyor samın Solduracak mısın ey zalim gurbet?  Öyle bir...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-zalim-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki damla gözyaşı 4.Bölüm', 'i-ki-damla-gozyasi-4-bolum-ayhan-isin-5kgfs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '………...............Kasabada kış çok zorlu geçmişti bu yıl. İlk defa kar yağmıştı ama bir parmak bile tutmamıştı. İç bölgelerde iki metreyi bulmuş, ana yollar kapanmış soğuktan göller ve nehirler donmuştu. Nisan ayı gelmesine rağmen hala kar ve soğuk geçmemiş Anadolu’ya bahar gelmemişti.  Ankara’da ve İstanbul’da da kar ve soğuk bu dev şehirleri köye çevirmişti.

…………………Arzu ve Kemal’in bu yıl son seneleriydi ve son dönemleriydi. Çok çalışmışlar, zorlu sınavlar, sıkıntılı yılar geçmiş, artık her şey sona erecek ve birbirlerine kovuşacaklardı. Her dönem sonunda kasabada görüşüyorlar. Yaz aylarında ıssız kumsalda ve mabetlerinde buluşuyor, aşklarını tazeliyorlardı. Çok sabretmişlerdi yıl içinde de mektuplaşıyorlardı. Babaları onlara birer cep telefonu da almıştı. Teknoloji ne harikaydı akşamları da netten görüşüyorlar. Konuşmasalar da birbirlerine çağrı atıyorlar. Aralarında anlaştılar iki defa çaldırdıklarında seni seviyorum. Üç defa seni çok özledim. Bu şekilde zamanda geçiyordu.

 …………………Kemal Kızılay da okula girdiğinden beri akşamları bir kasetçide çalışıyordu. Burasını tesadüfen bulmuştu. Sahibi üniversiteden mezun olduktan sonra iş bulamamış, babasının yardımı ile bu dükkânı açmış Kemal’den beş altı yaş büyük alımlı sarışın bir bayan olan Nurten;  Kemal’li işe almıştı. Nurten de üniversiteyi İzmir de bitirmiş. Okuduğu yıllarda bir kasetçide çalışarak okul harçlığını çıkarmış, Kemal’li de bu yüzden işe almıştı. Bir vefa borcu diye biliriz. Ama şimdi Kemal çok tecrübe kazanmış, bütün gün kazancından daha fazla akşam üç saatlik zamanda kazanmaya başlamıştı. Nurten de Kemal konusunda çok memnundu. İçten içe de Kemal’e ilgi duyuyordu. Tabi ki Arzu’dan haberi vardı. Ama zaten bu temiz Anadolu çocuğunun temiz duyguları onu cezp ediyordu. Nurten de çok güzel bir kadındı sarışın, yeşil gözlü, dolgun göğüslü balıketinde şen şakrak hayatla barışık hatta biraz deli bir kadındı. Arkadaşları vardı ama onların aklı fikri Nurten’in güzel vücudundaydı. İlişkileri de çok kısa sürüyordu. Ama Kemal öylemi Arzu’yla aşkları yılar sürmüş ve hala devam ediyordu. Aslında Nurten Arzu’yu kıskanıyordu. Hiçte tanışmamışlardı ama. 

…………………Bir Cuma günü Kemal satış tecrübelerini konuşturuyor ve muazzam satışlar yapıyordu. Nurten’de uzaktan Kemal’li seyrediyor, düşünüyordu. Bu akşam Kemal’i kesinlikle yatağa atmalıydı. Arkadaşından yeni ayrılmıştı. Aslında terk edilmişti. Bunun acısını azaltmalıydı. Akşam saat dokuz olmuş hala müşteriler gitmemişti. Nurten arka tarafa geçmiş. Önce üzerini değiştirdi. Abiye yeni aldığı iç çamaşırlarını,  sonra göğüs dekolteli kırmızı bir elbise, topuklu bir ayakkabı giydi. Sarı saçlarını açtı dağıttı ve masaya oturdu. Kendini zorladı ve ağlamaya başladı. Kollarını kavuşturdu yüzünü kollarının üzerine bıraktı ve ağlamayı sürdürdü. Müşterilerde artık dükkândan çıkmışlar, Kemal’de hesabı çıkarmış kasayı kapatmıştı. Nurten’e seslendi bu gün ‘harika satış yaptık’ ama ses gelmedi. Bir daha seslendi ama yine ses yok. Sonra bir ağlama sesi Kemal koşarak arkaya geldi. Nurten ağlıyordu. Çok şaşırdı onu hiç ağlarken görmemişti. Bu neşeli kadına ne olmuştu. Yavaşça başını kaldırdı. Kolları ağlamaktan ıslanmış, yüzü kızarmış gözyaşları boynundan süzülmüş, dolgun göğüslerine doğru akıyordu. Görünümü çok acıklıydı bir o kadar da seksi. Bu kırmızı elbisesini önceden de giydiği zaman, Kemal onu çok seksi bulur içinde bir şeylerin kıpırdandığını hissederdi. Çok zaman Kemal’in önüne gelir tezgâha eğilir ve bütün göğüslerini sergilerdi ama bunu bilerek yapmazdı ya da Kemal böyle düşünürdü. Çünkü Nurten rahat bir kadındı etek giydiği zamanlar bile otururken dikkat etmez her şeyleri gözükürdü. İşte böyle zamanlarda Arzu aklına gelmezdi. Kemal’in okuldan da kız arkadaşları vardı ama Nurten den etkilendiği kadar kimseden etkilenmiyordu. Gözyaşlarını eliyle sildi. Ne oldu diye sordu. Kemal yine beni terk ettiler. Beni seven bir kişi bile çıkmayacak mı? Ben onlara her şeyimi veriyorum. Onlar beni kullanıp atıyorlar. Ben de insanım duygularım var. Ben çok safım değil mi? Kemal bak sen öyle değilsin! Arzu’yu seviyorsun! Beni de sevecek bir insan evladı yok mu bu dünyada! Tabiî ki var sende bir gün sende mutlu olacaksın umudunu tüketme haydi sil gözlerinin yaşını. Dükkânı kapatalım biraz yürürüz siz de açılırsınız. Dükkânı kapadılar ota parka doğru yürümeye başladılar. Nurten, Kemal’e yaslanmıştı. Yerler buzlu kar hala kalkamamıştı. Kemal’in sıcaklığını hissediyordu. Bu akşam ben içmek istiyorum, hâsılatta nasılsa bu gün iyi senin sayende. Bu gün yemekler içkiler benden ne olur beni yalnız bırakma Kemal diyordu Nurten. Bu güne kadar hiç böyle bir teklif almamıştı patronundan. Önce kabul etmedi ama Nurten yine ağlamaklı oldu. Gönlü razı gelmedi Kemal’in kabul etti.  Ata kuleye gidelim yiyelim içelim ben her şeyi unutmak istiyorum dedi. Orası çok pahalı değil mi? Ya sana ne! Ben den hesaplar. Olmaz bize yakışmaz! Kadına para ödetti dedirtmem. Ya sen ne safsın ya! Ben sana veririm sen verirsin ne olur yanı paranın lafı mı olur. Boş ver taktığın şeye bak. Arabaya bindiler ve doğru Ata kuleye çıktılar. Kemal daha önce buraya gelmişti ama yukarıdan Ankara’yı seyretmek için restorana girmek zaten onun için mümkün değildi. Geniş bir masaya oturdular, Ankara ayaklarının altındaydı. Kemal’in cep telefonu iki kez çaldı. Arayan Arzu’ydu bunun anlamı Seni Seviyorum demekti. Ama bu aralar son bir aydır, Arzu’ dan da ne mektup nede netten mesaj gelmiyordu. Telefonu da çaldırmıyordu. İçine mi doğmuştu bu günü mü bulmuştu. O da iki kez çaldırdı. Nurten ne oldu annen mi arıyor dedi. Yok, Arzu değince Nurten’in yüzü değişti. Sanki şimdi sırası mı?  Yemeklerini ısmarladılar, birde büyük Tekirdağ! Kemal az içmeye çalışıyor Nurten ısrar ediyordu. Zaten burası dönüyordu. Kemal’lin başı mı dönüyor yoksa burası mı? Neyse şakalaştılar, gülüştüler. Bir ara Nurten garsona nerelisin hemşerim dedi. Adam esmer bıyıklı ama tipine göre çok nazikti, Urfalıyım dedi. Bende Elazığlıyım dedi Nurten. Hemşeri sayılırız doğuluyuz ya! Kemal anlayamamıştı önce ama adam Nurten’ e öyle bakıyordu ki göğüslerinden içeri düşecek gibiydi. Kemal sinirlendi sana ne adamın memleketinden ya şurada neşemizi bulmuşken yaptığın şeye bak dedi. Ne yapmışım ki? Bak ne güzel bize hizmet ediyor biraz muhabbetten ne çıkar. Bizim kitabımızda yazmaz yanında ben varken, elin herifiyle ne muhabbet ediyorsun. Nurten amacına ulaşmıştı. Kemal kıskanıyordu. Peki, peki tamam bak önüme döndüm. Sana bakıyorum işte adamada bir şey demeyeceğim. O zaman da sen bana bak olur mu? Tamam, ben yurda geç kaldım almayacaklar hadi kalkalım. Nurten, Kemal’in eline bir hayli yüksek bir para sıkıştırdı sen verirsin dedi. Kemal hesabı ödedi. Beraber çıktılar. Nurten bayağı sarhoş görünüyor boyuna Kemal’lin üzerine düşüyor. Kemal onu tutmaya çalışıyor ama Kemal’de bayağı içmiş kafası şimdi daha çok dönüyordu. Aslında Nurten alışıktı bir büyük daha içse ona bir şey olmazdı. Ama böyle yapmak zorundaydı. Arabaya bindiler zaten Nurten’in evi iki üç sokak aşağıda idi. Güç bela evin önüne arabayı park ettiler. Kemal ben gidiyorum şuradan bir taksi çeviririm dedi. Bu arada Nurten sendeledi ve yere düştü. Kemal kaldırdı. Nurten, Kemal beni böyle bırakıp gidecek misin?  Bari eve çıkar beni sen ne biçim erkeksin! Kolundan tuttu sendeleye, sendeleye eve çıktılar. Kapıyı açtılar sonra salondaki koltuğun üzerine beraberce yıkıldılar. Kemal, Nurten’in üzerinde bütün bedenini hissediyordu. Nurten birden bire Kemal’in dudaklarına yapıştı. Kemal ne olduğunu anlayamadan kendini Nurten’le sevişir buldu. Nurten’in yatak odasına geçtiler. Nurten soyunmuş seksi iç çamaşırlarıyla kalmıştı birden bu halı Arzu ile seviştikleri tarihi mabetlerindeki resimdeki kadın aklına geldi. İşte o geniş kalçalı iri göğüslü kadın karşısındaydı. Nurten çok tecrübeliydi amacına ulaşmıştı hep arzu ettiği adam karşısındaydı ve bütün hünerlerini göstermeliydi. Kemal savunmasız kalmıştı. Aklına ne Arzu Aşkları hiç bir şey onu kurtaramazdı. Çok sarhoştu elini kaldıracak hali yoktu teslim oldu Nurten’e! Sabah beraber uyandılar. Hala çıplaktılar. Beraber duşa girdiler. Kahvaltı ettiler. Beraber evden çıktılar. Nurten, Kemal’i okula bıraktı. Oda dükkânı açmaya gitti. 

…………………Kemal çok düşündü ama bunu nasıl anlatacaktı Arzu’ya zaten oda eskisi gibi aramıyor mektup yazmıyordu ilk zamanlar sınavlardan vakit bulamıyor diye düşünüyordu. Ama iki aydır ilk defa yemek sırasında aramıştı. Sonra boş verdi Nurten’le ilişkileri devam etti. Önce yurttan ayrıldı. Nurten’in evine yerleşti. Artık her işi beraber yapar oldular. Ama eksik bir şeyler vardı bu ilişkide Arzu ile beraber oldukları zaman var olan bir şey, ona haz veren o şey ama ne?  Nurten’le beraber oldukları zaman hissetmediği o şey yoktu ama bir türlüde çözememişti. Ama Arzu’nun verdiği nazar boncuğu eşyalarını yurttan aldığı gün mendilin içine baktığında dört parçaya bölünmüştü. Artık Veteriner hekimdi memleketine dönecek ve ideali olan kasabasında hizmet verecekti. Ama Nurten gitmesini istemiyor sende beni bırakıyor mu sun? Diyerek ağlıyordu. Bir karar vermeliydi. Arzu’yu da düşünüyordu bir sözü vardı. Zaten okul çoktan bitmiş sırf Nurten yüzünden burada kalmış. Üç aydır memleketine dönmemişti. Yaz gelmişti o kara kıştan sonra çok sıcak havalar gelmiş. Ankara yazın bile serin olmasına karşın kavruluyordu. Babası her görüşmelerinde sıcaktan yakınıyordu! Aslında Arzu’da İstanbul’daydı. Ama olanları anlatmalı artık herkes yoluna gitmeliydi. Kendini topladı cep telefonundan aradı ama bir erkek sesi orada olmadığını söyledi bir an sevindi belki de oda bir erkek arkadaş bulmuştu bu her şeyi çözerdi. Sonra bir mesaj yazdı. Bir hafta sonra buluştukları ıssız sahilde buluşalım memlekete beraber dönelim diye, Arzu’da sadece Tamam Akşam üç gibi orada ol. Diye mesaj yazdı.

25-02-2006', '………...............Kasabada kış çok zorlu geçmişti bu yıl. İlk defa kar yağmıştı ama bir parmak bile tutmamıştı. İç bölgelerde iki metreyi bu...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iki-damla-gozyasi-4-bolum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maşallah', 'masallah-munevver-erilmez-ay116', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha dün girmiştin kırk''ına

Ne çabuk  kırkbir  oldun

41 kere maşallah sana

Sevgili Minnoş Ana

Kalbin sevgi, iyilik dolu

Sarsın sabahları Elif''inin kolu

Anaların anası,güzel ana

Sen en büyük nimetsin bana

Daha nice yıllara

Sevgili Minnoş Ana', 'Daha dün girmiştin kırk''ına Ne çabuk  kırkbir  oldun 41 kere maşallah sana Sevgili Minnoş Ana Kalbin sevgi, iyilik dolu Sarsın sabahları Eli...', ARRAY['Türk Edebiyatı','Şiir','Münevver Erilmez']::text[], 8.5, '{"poet":"Münevver Erilmez","poet_slug":"munevver-erilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/masallah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barışa Kurşunlar İşler Mi Sandın', 'barisa-kursunlar-i-sler-mi-sandin-cengiz-ozkan-q4rmb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Barışa kurşunlar işler mi sandın 

Kurşun sıkan yanar közümde benim 

Panzer çicekleri ezer mi sandın 

Filizleri açar özümde benim 

Yaşamaya geldik  fani dünyaya

Şükür etmeliyiz ekmek ve suya 

İnsanlık yolunda kalmışız yaya 

Hainler kör olur tozumda benim 

Özkanım bakınız aya güneşe 

Yakışır insana güler yüz neşe 

Gönül bir saraydır güzellik döşe 

Kardeşlik tütüyor gözümde benim', 'Barışa kurşunlar işler mi sandın  Kurşun sıkan yanar közümde benim  Panzer çicekleri ezer mi sandın  Filizleri açar özümde benim  Yaşamaya g...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Özkan']::text[], 8.5, '{"poet":"Cengiz Özkan","poet_slug":"cengiz-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/barisa-kursunlar-isler-mi-sandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Canunu Alsun', 'allah-canunu-alsun-ali-kilic-kakiz-1fnd3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adamın biri, namaz kılmayı bilmeyen bir şahsa,

namazın ne şekil kılınacağını öğretmiş anlatmış.

Hayli bir süre geçtikten sonra,

arkadaşıyla camiye, Cuma namazı için gitmişler.

Maksat, camide de bir şeyler görür öğrenir diye..

İmamın sağ omzunun arkasında ki safta yerlerini almışlar.

Namaza durmuşlar, durmasına ama:

O adam nerden bilsin namazda konuşup konuşulmayacağını.

Aklına bir şey gelmiş ve ya ilişmiş,

illâ ki söyleyecek.

İnsanlara hayatın tüm şubelerin de musallat olan şeytan,

Allahın huzurunda duranların bile yakasını bırakmıyor.

Adam Demiş ki:

Haso habu kıldıhumuz namaz farz mudur, sunnet mudur? 

Hafif sesle söylemeye çalışıyormuş ki saftakiler duymasınlar diye.

Arkadaşında bir ses seda çıkmamış bir daha tekrarlar,

bir daha tekrarlar, ayağıyla da ayağına dürtermiş ki söyletebilsin..

Gel gör ki arkadaşını konuşturamamış, fena da kızmış …

Demiş ki ona:

Ûlan haset adamun Allah canunu alsun.

İstanbul / 1998', 'Adamın biri, namaz kılmayı bilmeyen bir şahsa, namazın ne şekil kılınacağını öğretmiş anlatmış. Hayli bir süre geçtikten sonra, arkadaşıyla ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/allah-canunu-alsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün', 'dugun-arif-buk-zndee', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elimde gül parmak izleri

Yüzüme gamze dost gülüşü

Küt küt atar da yüreğim

Tenimde düğün kurulur. 

Yağar yağmur 

İki el şemsiyenin altında 

Rahmete eren

Ve bir çocuk; annesi masallar ören 

Tutunca ellerinden 

Birleşir düğün kurulur. 

Gençliğim ihtiyarlığıma miras kalınca

Canımda çalkantılar durur 

Dua molası verilmiş bir seherde 

Seccadem sıcaksa alnımdan 

Gönlümde düğün kurulur. 

Göğe kaldırır gözümü kuşlar 

Artar ruhumda kumanyam 

Soframda düğün kurulur. 



*Bu şiir, Meb.Bilim ve Aklın Aydınlığında Eğitim  Dergisinde yayımlanmıştır.', 'Elimde gül parmak izleri Yüzüme gamze dost gülüşü Küt küt atar da yüreğim Tenimde düğün kurulur.  Yağar yağmur  İki el şemsiyenin altında  R...', ARRAY['Türk Edebiyatı','Şiir','Arif Bük']::text[], 8.5, '{"poet":"Arif Bük","poet_slug":"arif-buk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dugun-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşgal sömürü cinayet', 'i-sgal-somuru-cinayet-elazigli-mustafa-kaya-v8glo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mermi sıktılar

daha çocuktular 

bomba yağdırdılar

daha uykudaydılar

hayasızca saldırdılar

katlin

işkencenin

bin bir yalanın

propagandanın

endüstrisini kurdular

abd – israil - rus 

batı

kutsal ittifakı

işgal

sömürü

cinayet

gözleri önünde  herkesin

yapmadıklarını bırakmadılar

sözde medeni

barbarlar

tek dişi kalmış canavarlar

bugün ırak

dün Afganistan

yıllarca Filistin

işgal altında çeçenistan..

özgürlük ve

demokrasi getirmek  (!) 

yeni dünya düzeninin

entrikası

işgal-sömürü-vahşet

insanlığın yüzkarası

dialog

medeniyetler uzlaşması

insan hakları (!)  adına

rezalet…

Mustafa kaya

24.02.2006 / Üsküdar', 'mermi sıktılar daha çocuktular  bomba yağdırdılar daha uykudaydılar hayasızca saldırdılar katlin işkencenin bin bir yalanın propagandanın en...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/isgal-somuru-cinayet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç kimse yok', 'hic-kimse-yok-elazigli-mustafa-kaya-refg2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hiç kimse yok

içimde.

kimse tanımadı 

şehirde.

görmedi gözlerim 

kimseyi de.

bilmiyorum,

hangi kalpte

bekleniyorum …

Mustafa kaya

25.02.2006 /   İstanbul', 'hiç kimse yok içimde. kimse tanımadı  şehirde. görmedi gözlerim  kimseyi de. bilmiyorum, hangi kalpte bekleniyorum … Mustafa kaya 25.02.2006...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hic-kimse-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En çıkmaz sokaklar', 'en-cikmaz-sokaklar-elazigli-mustafa-kaya-v4xyv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu son tövbem

üzdüysem gamzelerini

eğer 

yarım kaldı

sözlerim 

çıkmaz sokalar 

başındayım 

korkuttu hıçkırıklarım

sessiz bir akşamda 

güvercinleri… 

Mustafa kaya

25.02.2006 / istanbul', 'bu son tövbem üzdüysem gamzelerini eğer  yarım kaldı sözlerim  çıkmaz sokalar  başındayım  korkuttu hıçkırıklarım sessiz bir akşamda  güverc...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-cikmaz-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Yaprak', 'suskun-yaprak-selman-can-d4ipq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'suskun yaprak

yağmur yağarken inceden inceye,

ıslanmış günah tohumu çınarım.

bulutlar gizlemiş güneşi diye,

kimsesiz mi kalmış sahipsiz kaldırım

sarhoş yağmurun asırlık eseri

tanımada yine gamlı hazanı.

paslı toprak şikayetçi serseri,

buda şımarığın ödlek yalanı.

mehtabı dolmuş gecenin ardında,

şarkı söylesin sabahın meltemi.

sahte kaldırım, avare avında,

bir daha çalmasın hüzün bestemi.

kopardım artık, dostum dikenleri,

sende kucaklama paslı toprak.

yazın beklediğim kardelenleri,

kimse bilmesin sakın suskun yaprak.', 'suskun yaprak yağmur yağarken inceden inceye, ıslanmış günah tohumu çınarım. bulutlar gizlemiş güneşi diye, kimsesiz mi kalmış sahipsiz kald...', ARRAY['Türk Edebiyatı','Şiir','Selman Can']::text[], 8.5, '{"poet":"Selman Can","poet_slug":"selman-can","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/suskun-yaprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yer Küre', 'yer-kure-hasan-ekrem-8z18x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağınık, puslu ve bir o kadar kirli,

Belki de hep öyleydi.

İlk gördüğümüzde neden ağlamıştık,

İlk gülüşümüz niçin ve nedendi,

Hayatımızın en büyük çelişkisine, 

Değilse, eğer…

—bilmem hatırlayanınız var mı? —

Pırıl pırıl bir güneş ve yemyeşil kırlardı,

İlk çizdiklerimiz..

Umut bir akar yıldızdır aslında,

Hep var olan sonsuzda ve yakalanamayan.

Ki biz o kırlarda yuvarlanır,

Kim bilir belki hayalden öteyi yakalamak uğruna,

Yılgınlıkla karışık yorgunluğumuzu,

Dindirirken bir bilge ceviz ağacının gölgesinde,

Kenarındaki dereden kana kana su da içerdik.

Bulamadık hiç, sahi neredeydiler,

Çağırsak gelirler miydi? 

Kapı aralığından bile olsa,

Çelik ya da tahta ne fark ederdi,

Hiç gülümsemediler..

Sonra ozon deliklerine tuval bir gökyüzü

Nötron patlamalarıyla kanser resitalleri..

Soğumakta olan güneş,

Ve inat nebula’nın doğasına,

Isınmakta, 

—belki kızmakta, terk edilmişliğin acısıyla—

Dağınık, puslu ve bir o kadar kirli,

Umutlarımız gibi,

Maviyi terke hazır, 

Doyamadığımız yer küre..', 'Dağınık, puslu ve bir o kadar kirli, Belki de hep öyleydi. İlk gördüğümüzde neden ağlamıştık, İlk gülüşümüz niçin ve nedendi, Hayatımızın en...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yer-kure-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müzmin Münzevi', 'muzmin-munzevi-muhammed-mehmet-gul-anm2y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana dar sokaklarda 

Ustura ağzı gibi ağıtlar söyleten

Beni yudum yudum içen,içine çeken

Bu kenti

Bir akşamüstü ateşe verdiğimi duyunca

Aklın almaz bilirim.

Sen ey müzmin münzevi

Sen ey martıların dilindeki çığlık

Terkedilmiş istasyonlardaki tehirli sevdam

Beni can evimden vuran şiirlerin müsebbibi

Sarhoş atların ağır toynaklarıyla ezdiği

Yürek ülkemin ıssız bozkırlarında açan

Sen ey intihar gülüm.

Ateş dolu yüreğime hudutlar çizen

Gözlerimi dört duvara mahkum eden

Bu kenti

Bir akşamüstü yaktığımı duyunca 

Aklın almaz bilirim

Sen ey müzmin münzevi.', 'Bana dar sokaklarda  Ustura ağzı gibi ağıtlar söyleten Beni yudum yudum içen,içine çeken Bu kenti Bir akşamüstü ateşe verdiğimi duyunca Aklı...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/muzmin-munzevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mabetlerin Kalbi', 'mabetlerin-kalbi-muhammed-mehmet-gul-odnz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizim öykümüz karanlıklarda geçiyor

Gökyüzünün kasvetli kızıllığı ve

Tüm ışıkları söndürülmüş gecelerindir hüküm

Şimdi,mehtabı arayan gönlüm,uçurumlara

Şelalelere meylediyor

Hep boşluğu seyrediyor gözlerim

Ayan beyan ortadayken

Unutulmuşluğumuz,avutulmuşluğumuz

Ansızın kesildi ardımız sıra yükselen nidalar

Ey mabetlerin kalbi

Ey zarif şehir

Şimdi eskisinden daha karanlık odalar

Ruh iklimlerimizin değiştiği günlerdeyiz

Artık her çocuk gözlerini

Mevsimsiz bir sabaha açıyorken 

Acıyor,içimiz acıyor

İki dudağımız arasına sıkışıp kalan sözlerimiz…

Boşluğa asılı gözlerimizden

Bir atom bombası gibi düşerken

Mermer eşiklere

Biz hala uçurumun karanlık kıyısındayız

Oysa bir zamanlar 

Aynalardan ruhumuzun derinliklerine bakmıştık

Köprüleri atmış

Bütün gemileri öylece yakmıştık

Şimdi sen kara bağrımda ağrım

Ey mabetlerin kalbi

Ey zarif şehir

Şimdi sen eğrim doğrumsun

Ey bütün başlangıçların son bulduğu şehir

Sakın ha dokunmasın duvarların ellerime

Ahım,eyvahım sana da bulaşır

El vurma tarihsiz günahıma

Bilirim ki hep günahsızlar dolaşırdı sokaklarında

Benimse şakaklarımda

Her günahın sonrası 

Bir tel

Bir tel daha ağarıyor

Tan ağarıyor öpülesi gökyüzünde

Ve ben ağır ağır zamanın kollarında eleniyorum

Ey mabetlerin kalbi

Ey zarif şehir

Şimdi yüzüme kapanan kapılardan maverayı dileniyorum', 'Bizim öykümüz karanlıklarda geçiyor Gökyüzünün kasvetli kızıllığı ve Tüm ışıkları söndürülmüş gecelerindir hüküm Şimdi,mehtabı arayan gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/mabetlerin-kalbi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm Sakın', 'olurum-sakin-huseyin-sigirtmac-top96', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılıktan yana döndürme çarkın.

Sen olmasan nasıl dururum sakın.

Yüreğime bir sen bir de Hak yakın.

Sensiz çöl olurum kururum sakın.

Duyguma varlığın düştü bir kere.

Senden bir iz taşır bende her zerre.

İstersen sevgimi götür mahşere.

Orda da vazgeçmez bulurum sakın.

Bağlarım sensizse saracak kolu.

Kapatırım aşka giden her yolu.

Ben beni taşımam doluyum dolu.

Patlayan bir volkan olurum sakın.

Ayrılık hasretlik gelmesin senden.

Hak’tan emir ise giderim önden.

Gidersen arayıp sormam yeniden.

Kalbime pranga vururum sakın.

Kolay mı bulunur can içinde can.

Ne bana azap ver ne de sen gel yan.

Ben köle olurum gel sen ol Sultan.

Sığırtmaç’ım sensiz ölürüm sakın.', 'Ayrılıktan yana döndürme çarkın. Sen olmasan nasıl dururum sakın. Yüreğime bir sen bir de Hak yakın. Sensiz çöl olurum kururum sakın. Duygum...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olurum-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümle Saklambaç..', 'olumle-saklambac-pinar-koc-5kvxb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vay be ölüm,

Sende mi buldun beni

Saklandığım en kuytu köşelerde………..

Kendimden bile kaçtığım zamanlarda

Ve uçsuz bucaksız sonsuzluklarda,

Unutulmanın acısını yüklenmişken bedenim,

Ve kamburum çıkıp,göğüs kafesim ezilmişken,

Bir tas acı su serpilmişken toprağıma,

Sende mi buldun beni,

Saklandığım en kuytu köşelerde……….

Vay be ölüm,

Gelişini merak ederdim hep

Ve ne zaman gideceğimizi………..

Seven bir sevgili edasıyla tutup,

Çektin ellerimden kıyılarına önce……..

Yüzmeyi beceremediğim sulara ayaklarımı değdirdim.

Sonra boyuma kadar girdim.

Ve boyumu aşan uzaklıklara………

Tıpkı boyumu aşan işlerde boğulduğum gibi.

Sonra,

Son bir nefes bile aldırmadan götürdün.

Sürükledin peşinden alev çemberlerine…..

Vay be ölüm,

Sende mi buldun beni,

Saklandığım en kuytu köşelerde…….

Oysa suskundum………

                                                                     25.02.06    02:00', 'Vay be ölüm, Sende mi buldun beni Saklandığım en kuytu köşelerde……….. Kendimden bile kaçtığım zamanlarda Ve uçsuz bucaksız sonsuzluklarda, U...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/olumle-saklambac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum', 'agliyorum-zeynep-demirci-f4j6h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geldi mi, üst üste gelirmiş

Felaketler, acılar…

Önce fay hatları patladı fütursuzca

Şimdi de sen…

Neden? 

Yürekleri bir

Sözleri, gözleri aydın,

Patlayan bombalarda; 

Beyinleriyle savaşan

Bir ordu bıraktın ardında

Kalemleri omuzlarında

Süngü misali…

Adam gibi mertçe direniyorken

Doğrularınla yaşama hakkının,

Kahpece elinden alındığı

Büyük bir çınardın devrilen…

Bu sabah; 

Doğmayacaktın güneş

Isınamıyorum, ağlıyorum…

Onaramayacağımız Marmara’ya

Bulamayacağımız meçhuller eklendi

Vah size (bize)

                                              

Ahmet Taner KIŞLALI için 23.10.1999', 'Geldi mi, üst üste gelirmiş Felaketler, acılar… Önce fay hatları patladı fütursuzca Şimdi de sen… Neden?  Yürekleri bir Sözleri, gözleri ayd...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Demirci']::text[], 8.5, '{"poet":"Zeynep Demirci","poet_slug":"zeynep-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agliyorum-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-kamil-boyraz-jg8gp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bahar günüydü çıktın karşıma

Neler getirdin şu garip başıma

Zehir kattın ekmeğime aşıma

Gözlerin maviydi gök,deni mavi

İçimde titreyen umudum söndü

Gönlümde gizlenen yarınım öldü

Gündüzüm yeniden geceye döndü

Gözlerin maviydi hayallerim mavi.

Şikayetim kader sanadı sana

Yıllardır yalnızlık düşüyor bana

Kardeş payı yapman derdi insana

Gözlerim maviydi dertlerin mavi.

Sitemime kulak asma ne olur.! 

Seven insanların kaderi budur.

Şiirde şarkıda teselli bulur.

Gözlerin maviydi dünya mas mavi', 'Bir bahar günüydü çıktın karşıma Neler getirdin şu garip başıma Zehir kattın ekmeğime aşıma Gözlerin maviydi gök,deni mavi İçimde titreyen u...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mavi-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişat', 'gidisat-yilmaz-aybar-c51u6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyaset esnafıyla verip kafa kafaya

      Bezirgânlar ortaklık fotoğrafı çektirdi

      Arsızlıkla dal- budak saldılar her tarafa

      Günden güne gidişat o kadar tersleşti ki 



      Seks,şiddet ve maddiyat şeytan üçgeni gibi

      Dünya yuvarlağını çekti kendi içine

      Gölgeledi hayatın bütün değerlerini

      Küresellik lâfı da tüy dikti üzerine

      Kaba güç rüzgârları yeniden eser oldu

      Kuvvete yenildi hak''insan hakları''derken

      Safsatalar gerçeğin önünü keser oldu

      Barbarlığa sapıldı uygarlığa giderken

      Hakça düzen ülküsü hedefe varamadan

      Bezirgânlar bugünün sultanları oldular

      Dünün sultanlarına rahmet okutaraktan

      Tüm dengeleri altüst etmeye koyuldular

      Ve varsıllar daha çok gömülürken varlığa

      Yoksullar ellerinde olanı da yitirdi

      Yazık ki bahtı kara dünyamız ola ola

      Dev bir Arap ülkesi olma yoluna girdi.', 'Siyaset esnafıyla verip kafa kafaya       Bezirgânlar ortaklık fotoğrafı çektirdi       Arsızlıkla dal- budak saldılar her tarafa       Günd...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidisat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalar', 'dalgalar-yilmaz-aybar-odzgg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalgalar çoğu kez aynı nakarat

      Yeknesaklık deryasında çalkantı

      Kararsız işleyen sarkaçlı saat

      Ne olduran ne öldüren sallantı

      Dalgalar kimi gün ninni şırıltı

      Sütliman sularda huzura varış

      Uykuda sayıklar gibi mırıltı

      Rüya hiç bitmesin diye yakarış

      Ardından dalgalar dehşetin sesi

      Bir barbar akını önlenemeyen

      Yıkımlar getiren vahşetin sesi

      Canavar sürüsü aman vermeyen

      Ufuklardan doludizgin koşarak

      Dalgalar peşpeşe gelen dalgalar

      Kabararak köpürerek taşarak

      Kapkara tablolar çizen dalgalar

      Ve sonra hiçbir şey olmamış gibi

      Kendini engine salan dalgalar

      Yanar-döner bir manzara misali

      Hayatın aynası olan dalgalar', 'Dalgalar çoğu kez aynı nakarat       Yeknesaklık deryasında çalkantı       Kararsız işleyen sarkaçlı saat       Ne olduran ne öldüren sallan...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dalgalar-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı', 'marti-tulay-sustam-k1wr4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sağ omzumdan uçar

y a l n ı z l ı k l a r a

sol tarafımda çığlığı diner

koparır dizlerimin bağını

g e l e m e m  s a n a

gözbebeğinde donar acısı

kanatları kırılır mavinin

t u t u ş m a z  e t e k l e r i  a y '' ı n 

koparır geceden göbek bağını

sırtını döner kimsesiz akşamlara

bir damla yağmur da yudumlar uzakları

.

maviye sırtımı döndüğüm günden beri 

.

seni göğüs kafesime alamam

.

24 şubat

kabataş', 'sağ omzumdan uçar y a l n ı z l ı k l a r a sol tarafımda çığlığı diner koparır dizlerimin bağını g e l e m e m  s a n a gözbebeğinde donar ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/marti-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Yaşamak', 'i-yi-yasamak-yilmaz-aybar-soq1q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sırf yiyip içmek

      Sevişmek

      Ve de gezip tozmak mıdır iyi yaşamak

      Ama hayvanlar da öyle yapıyor

      Hem de özgürlük-mozgürlük demeden

      Sınırlarını aşmadan

      Havaları kirletmeden

      Suları çirkef etmeden

      Doğayı tüketmeden

     Bindikleri dalı kesmeden yapıyorlar

      Yani iyi yaşama bahsinde

      Eksikleri yok insandan

      Fazlaları var

      Uzun lafın kısası

      Kötü yaşayan yaratık yok şu dünyada

      İnsan kadar', 'Sırf yiyip içmek       Sevişmek       Ve de gezip tozmak mıdır iyi yaşamak       Ama hayvanlar da öyle yapıyor       Hem de özgürlük-mozgürl...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iyi-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzularımda ceylandın!', 'arzularimda-ceylandin-enes-ates-5jkad', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölmek ve dirilmek ceylan gözlerinde,

Diriltmek ölmüşleri..

 Maviye boyayıp tüm düşleri,

Hislerini boğmak nefeslerinde; ; ; 

    Sevmek! ! ,

SEVDİRMEDİLER...

          Yalan ve gerçek sözleri ayıklamak

           Anlamak sıcaklığını cümlelerin

            Hissetmek sevgiyi içli ve derin

              Umutlara koca bir şarjör sıkmak

                 Ölmek! ! ,

ÖLDÜRMEDİLER...

                 Görmek acı yanlarını hayatın

                   Yaşamak ensende o ihtişamı

                     Süzülmek uçurumlarında bir dağın..

                             Vurdular uçurtmamı,,,

............................                    İndirmediler...', 'Ölmek ve dirilmek ceylan gözlerinde, Diriltmek ölmüşleri..  Maviye boyayıp tüm düşleri, Hislerini boğmak nefeslerinde; ; ;      Sevmek! ! , ...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/arzularimda-ceylandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek!', 'gercek-enes-ates-8cnn1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ceylan gözlü vardı şiirlerimde

Bir de yeşil gözlü, cümlelerimde

        

           Hissedip ceylanın titreyişini

           Ağladım yeşilin gülüşlerinde...', 'Bir ceylan gözlü vardı şiirlerimde Bir de yeşil gözlü, cümlelerimde                     Hissedip ceylanın titreyişini            Ağladım yeş...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gercek-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dibi ince bardak', 'dibi-ince-bardak-zati-erbas-fxl9b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'küçük 

adımlarla gelirsin hep

tıpkı 

bir 

kedi yavrusunun mindere gidişi 

gibi

koynuma.

ben

sıcaklığı

senden

öğrendim.

kenarı

kırık 

dibi ince

rakı dolu 

bir 

bardak 

gibi

kanatıyorsun dudaklarımı 

ve 

ben

arta kalanı

boşluk

olarak

ekliyorum içimdeki okyanusa', 'küçük  adımlarla gelirsin hep tıpkı  bir  kedi yavrusunun mindere gidişi  gibi koynuma. ben sıcaklığı senden öğrendim. kenarı kırık  dibi in...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dibi-ince-bardak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalık Yalnızlara Elveda', 'kalabalik-yalnizlara-elveda-arzu-gulucudur-bbz6r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat ondokuz onbeş...

Kalabalık yalnızlardayım cami avlusunda

Çıngırak sesleri kulağımda

Hayalin, meyal aklımda

Son çağırış yolculuğa 

Bir nara...bir nara daha...

Elvedalara el sallayış

Düne, bugüne elveda

Soluk almak zor bu diyarda

Bir cigara içimlik arada 

İs kokan bu sokakta

Kalabalık yalnızlardayım

Ölüme dem vuran bu akşamda

Namlunun ucunda mermi, şakağımda

Beni çağıran azrail kucağında 

Yarına, bugüne elveda

Dört kollu sandalda

Kürek çekenler yanımda

Ağıtlar, yakarışlar boşuna

Kalabalık yanlızlardayım, sen olmadıktan sonra

Karanlığa....sana....ve yalnızlara elveda...', 'Saat ondokuz onbeş... Kalabalık yalnızlardayım cami avlusunda Çıngırak sesleri kulağımda Hayalin, meyal aklımda Son çağırış yolculuğa  Bir n...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kalabalik-yalnizlara-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyaya bir daha gelecek olsam..', 'dunyaya-bir-daha-gelecek-olsam-enes-ates-35c3i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyaya bir daha gelecek olsam,

Yine düşünür müydüm

Tekrar gelebilme ihtimalimi acaba..? 

   Yoksa gelmemek için mi ölürdüm

    Son defa,

Bu suali sorar mıydım

Dünyaya bir daha gelecek olsam? ? ?', 'Dünyaya bir daha gelecek olsam, Yine düşünür müydüm Tekrar gelebilme ihtimalimi acaba..?     Yoksa gelmemek için mi ölürdüm     Son defa, Bu...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dunyaya-bir-daha-gelecek-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mürşid-i Kamil', 'mursid-i-kamil-taner-nisanci-r66t5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'MÜRŞİD-İ KAMİL

Nakış nakış olan sözünde

Hicran ateşi var közünde

Nur-u ziya olan özünde

Mürşid-i Kamilsin bilirim

Ayrı değil Hakkel yakınsın

Nazar-ı ibretle bakansın

Aşk ateşi korlu yakansın

Mürşid-i Kamilsin bilirim

Nefs kibir benliğin atanlar

Aşk pazarında can satanlar

Huzur bulur elin tutanlar

Mürşid-i Kamilsin bilirim

Katlanıp bin türlü mihnete

Talipsin durmadan hizmete

Her halin uygundur sünnete

Mürşid-i Kamilsin bilirim

Yolun gözler seni sevenler

Hep sarhoş kemalin görenler

Uğrunda var canın verenler

Mürşid-i Kamilsin bilirim

Kulluk abasını giydiren

İnsanı günahtan caydıran

Emiri yasağı saydıran 

Mürşid-i Kamilsin bilirim

Geceyi gündüze eklerim

Garibim  himmetin beklerim

Sözümü sözünle aklarım

Mürşid-i Kamilsin bilirim

                                        12/02/2006', 'MÜRŞİD-İ KAMİL Nakış nakış olan sözünde Hicran ateşi var közünde Nur-u ziya olan özünde Mürşid-i Kamilsin bilirim Ayrı değil Hakkel yakınsın...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mursid-i-kamil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devlet Baba', 'devlet-baba-durmus-karakus-qzs1y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep ağaya bey''e değil,

Biz''e de ver devlet baba,

A ya B ye C ye değil,

Biz''e de ver devlet baba.

Allah versin derim ömür,

Hortumcu yu bir bir sömür,

Biraz odun biraz kömür,

Biz''e de ver devlet baba.

Deniz in den kara sın dan,

Şişli taksim arasın dan,

Uzan ların parasından,

Biz''e de ver devlet baba.', 'Hep ağaya bey''e değil, Biz''e de ver devlet baba, A ya B ye C ye değil, Biz''e de ver devlet baba. Allah versin derim ömür, Hortumcu yu bir bi...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/devlet-baba-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama kardeşim!', 'aglama-kardesim-enes-ates-qlb52', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlama kardeşim, n''olur ağlama..

Kalbinden vurulmuş umutlarını,

İstanbul''da, Buhara''da, Bağdat''ta 

Onaracaklar var,

Ağlama...

Kuşları gösterirdim sana ya,

Hepsi bir sesin ardından gitti.

Sanki gökyüzünü kan buladı da

Martılar, serçeler ve de kargalar,

O muhteşem sesin ardından gitti.

Boşver sen kuşları,

Ağlama! ! 

Kardeşini gösterirdim sana ya,

Az evvel oynarken patlak topuyla

Kocaman bir araç ezdi de geçti.

Görmedi galiba kardeşinin,

Patlak topun ardından gittiğini.

Herşeyin bir anda yittiğini,

Bilmedi galiba! ! 

Evini gösterirdim sana şurada,

Sivri ucuyla roketin çarptığını duvarlara,

evin viran olduğunu söylerdim ya,

Boşver,

Ağlama! ! 

Babanı gösterirdim sana kardeşim,

Fakat geçen üç-beş amca geldiler,

Alıp götürdüler babanı sarmaş dolaş.

Askerlik arkadaşlarıydı herhalde,

Silahları vardı ellerinde,

Bize de gösterdiler.

Baban gitmek istemedi kardeşim,

Yanlışlıkla olacak herhalde,

Tam alnının ortasından vurdular babanı,

Olsun,

Ağlama! ! ! 

Ülkeni gösterirdim sana ya,

Şişko bir dedeye miras kalmışmış.

Sokakta geçen gün sorduğumuzda

Asker amcalar söylemişti bize.

Huzurmuş, ferahmış, rahatmış istedikleri..

Ama ablanı niye götürdüler anlamadım! 

Anneni, halanı, teyzeni niye götürdüler...

Kuşları, kardeşini, evini,

babanı, ülkeni gösteremedim 

Belki kardeşim ama,

Her birinin yüreği en az senin kadar yaralı

Kardeşler göstereceğim sana,

Ağlama! ! ! 

Ağlama! ! !', 'Ağlama kardeşim, n''olur ağlama.. Kalbinden vurulmuş umutlarını, İstanbul''da, Buhara''da, Bağdat''ta  Onaracaklar var, Ağlama... Kuşları göster...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/aglama-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarılırsak Umutlara', 'sarilirsak-umutlara-ferah-yilmaz-eya5w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve güneş doğarsa,

Yakar bir gün bu tepeleri

Gülo yakar

Cana can katar

Umutlar okşar sevdaları....

Gülo umutlar,

Senin, benim

Bizim umutlarımız gülo

Ve kavganın ışıltıları

Işıklara karışır.

Ne sızlayan kan damarları,

Ne yürek sızısı

Ne mağlupluğun verdiği acı,

Durgunluğu değil, 

Yaşamı bilesin....

Dağarcık/Ardahan 1979', 'Ve güneş doğarsa, Yakar bir gün bu tepeleri Gülo yakar Cana can katar Umutlar okşar sevdaları.... Gülo umutlar, Senin, benim Bizim umutlarım...', ARRAY['Türk Edebiyatı','Şiir','Ferah Yılmaz']::text[], 8.5, '{"poet":"Ferah Yılmaz","poet_slug":"ferah-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarilirsak-umutlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup&e...', 'mektup-e-ali-baksi-jcl1a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalıplaşmış sevgiler,

Buralarda sensiz! ! 

Sessiz ve derin,yapraklar''la,

Hasret alıp götürüyor uzaklara, 

Dayanmıyor yüregim bu ayrılıga, 

Durma ya git,yada ğel artık,

Bu ayrılıklar son olsun buralar’da

Seni seviyorum emel inan artık bana...', 'Kalıplaşmış sevgiler, Buralarda sensiz! !  Sessiz ve derin,yapraklar''la, Hasret alıp götürüyor uzaklara,  Dayanmıyor yüregim bu ayrılıga,  D...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mektup-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çapkından Elveda', 'capkindan-elveda-umit-tuna-yw0zz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu dünyadan elimi eteğimi çekiyorum,

Artık çapkınlığı da bırakıyorum,

Hiçbir kız arkadaşım yanımda olsun istemiyorum,

Ben artık öbür tarafı düşünüyorum.

Ve korkuyorum…

Nasıl hesap vereceğim öbür tarafta bilmiyorum,

Şu dakikadan itibaren tövbe ediyorum,

Çapkınlık huyuma elveda diyorum.

Artık kimsenin ağını almak istemiyorum,

Yaşadıklarımdan utanıyorum,

Allah’ım senin affına sığınıyorum,

Senden merhamet diliyorum,

Senin her şeye güçün yeter biliyorum.

Artık bu dünya yalan buna inanıyorum,

Nefsime yenik düşmemek istiyorum,

Eski Ümit’e elveda diyorum,

Beni neler bekliyor bilmiyorum.

Ama şu an da çok mutluyum,

İşte bunu hissediyorum,

Affedin kızlar ben artık çapkınlığı bırakıyorum,

Bambaşka bir Ümit olarak tekrar doğuyorum! ...', 'Bu dünyadan elimi eteğimi çekiyorum, Artık çapkınlığı da bırakıyorum, Hiçbir kız arkadaşım yanımda olsun istemiyorum, Ben artık öbür tarafı ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/capkindan-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reddediyorum...', 'reddediyorum-vahan-i-saoglu-15n4r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tuhaf bir gecenin yıldızlı, maviş gökyüzünde saklı yüzün, 

Ve sarı ışıkların süslediği kaldırımların son nefesi sessizlik, 

Su birikintisinin arasına tünemiş sahipsiz bir avuç gözyaşı, 

Bir minik kuş yuvasında uyuyor masum masum, 

Ama yerini söylemem uyanmasın diye, 

Sonsuz çabası utandırsada yuvasına çekirdek kabuğunu sürükleyen karıncanın, 

Yinede bir of çekmek geliyor da, ya gururda takılıyor ya gümrükte alıkonuluyor... 

Şimdi soğuğa rehin bıraktım donuk bakışlarımı, 

Üç gözyaşı damlası aldım karşılığında, 

Birini o su birikintisine bıraktım yalnız kalmasın diye, 

Diğerini o kuşun yuvasına koydum uyandığında susuz kalmasın diye, 

Sonuncusunu avuçlarımın arasına koydum, sana yolluyorum, 

İhbar ediyorum özlemini ve sonsuz hapsine sunuyorum. 

Onu incitmeyeceğini umuyor ve şartlı tahliyesini reddediyorum...', 'Tuhaf bir gecenin yıldızlı, maviş gökyüzünde saklı yüzün,  Ve sarı ışıkların süslediği kaldırımların son nefesi sessizlik,  Su birikintisini...', ARRAY['Türk Edebiyatı','Şiir','Vahan İsaoğlu']::text[], 8.5, '{"poet":"Vahan İsaoğlu","poet_slug":"vahan-i-saoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/reddediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can ile Canan Ayrı Kalır', 'can-ile-canan-ayri-kalir-multe-ci-han-kldb5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nereye gideyim ki sensiz

Gecelerim uykusuz, odam sessiz

Sen olmayınca eksiğim her zaman

Dağınık kalbim, kanatlarım kırık

Bir tek sensin beni duymayan

Diyetimi ödüyorum

Kalbim o kadar çok sevinmişti ki seninle

Şimdi üzülüyor biçare ümitlerde

Diyetini ödüyor; 

kelimeleri virane

Yarım kalan hayatların baş kahramanıyım

Zaman akmaz, günler geçmez burada

Saatlarin minesi kırılmıştır

Pes edersin duygularının doruğunda...

Can ile canan ayrı kalır

Sıradağlar vardır arasında

Kendi kendine söz verir ve uygularsın

Can çıkmayınca bedenden

Canan ayrılmaz kalbinden', 'Nereye gideyim ki sensiz Gecelerim uykusuz, odam sessiz Sen olmayınca eksiğim her zaman Dağınık kalbim, kanatlarım kırık Bir tek sensin beni...', ARRAY['Türk Edebiyatı','Şiir','Mülte Ci Han']::text[], 8.5, '{"poet":"Mülte Ci Han","poet_slug":"multe-ci-han","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/can-ile-canan-ayri-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın Yollarımız Ayrılsın', 'varsin-yollarimiz-ayrilsin-ferah-yilmaz-jzs85', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Böyle günden güne eriyeceksek

Yüreğimizi acılar kapatacaksa

Bırak tutunduğumuz dallar kırılsın

Bütün yollar, dertler acı verecekse,

Bırak yeşermesin umutlarımız

Yerin dibine batsın! ! ! 

Tüketecekse bu sevda yüreğimizi

Varsın yollarımız ayrılsın

Ne sen söyle sevgimizi, ne de ben

İçimizi, bağrımızı dağlasın

Bırak horlaşsın sevgimiz

Gözlerimiz ağlayabildiği kadar ağlasın! ! ! 

Dağarcık/Ardahan - 1982', 'Böyle günden güne eriyeceksek Yüreğimizi acılar kapatacaksa Bırak tutunduğumuz dallar kırılsın Bütün yollar, dertler acı verecekse, Bırak ye...', ARRAY['Türk Edebiyatı','Şiir','Ferah Yılmaz']::text[], 8.5, '{"poet":"Ferah Yılmaz","poet_slug":"ferah-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/varsin-yollarimiz-ayrilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Ağlamaz', 'sair-aglamaz-ferah-yilmaz-bt72z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bıçak gibi saplanmış benliğime yalnızlık,

Ağlayacak sanma bu öksüz gecelerime, 

Şair ağlamaz unutma! 

Mürekkep döker kağıtlara yaş yerine.

Biliyorum ellerim yetim gebe karanlıkta,

Doğum sancıları fışkırıyor yüreğimden.

Yemyeşil gözlerin yok biliyorum,

Darda kalan hayalin o eşsiz gecelerde,

Şimdi bir göçmen kuşu, uçuşuyor saçlarım.

İsmini andığım o sessiz eski gecelerde.

Yanaklarım çökmüş kalbim parça parça,

Can çekişiyor o eski kaldırımlarda......

Sanma ki çaresizim, yinede eziğim,

Dert ortağı tabiatım var benim..

Aşk kokulu çiçeklerim, yemyeşil yapraklarım var..

Yalnızlığıma ben değil, bil ki mısralar ağlar! ! ! ! 

Dağarcık / Ardahan - 20 Mart 1978

1979 yılında Günaydın Gazetesi eki Kelebek Gazetesinde ayrıca 2007 yılında Trabzon TAKA GAZATESİ''nin - ŞİİR TAKASI bölümünde yayınlanmıştır.', 'Bir bıçak gibi saplanmış benliğime yalnızlık, Ağlayacak sanma bu öksüz gecelerime,  Şair ağlamaz unutma!  Mürekkep döker kağıtlara yaş yerin...', ARRAY['Türk Edebiyatı','Şiir','Ferah Yılmaz']::text[], 8.5, '{"poet":"Ferah Yılmaz","poet_slug":"ferah-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sair-aglamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böylemi Olmalıydık', 'boylemi-olmaliydik-seyfet-bozcali-rckpl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Istırapla inleyen bu bağrımın,

Bu beynimi iğneleyen sırrımın,

Sevda yüklü yaşamımın,gönlümün,

Der ki Yarap böylemi olmalıydık? 

Her kes baksa gökyüzüne,yıldıza,

Çok çalışsa da erişse o haza,

Sevgi,saygı verse oğula,kıza,

Huzurla,sükünla hep kalmalıydık...

Sokaklar kan,reva sokakta vahşet,

Küçücük çocuklar saçıyor dehşet,

Gazeteler boy boy atıyor manşet,

Dostlar bizler böylemi olmalıydık? 

Kanundan sakınmaz,kimseden korkmaz,

Piskopatça yaşar kimseyi saymaz,

Çalar,çırpar gider hiç gözü doymaz,

Bu nesili  böylemi görmeliydik? 

Balici,tinerci köşe başında,

Kaybetmiş kendini,hayel peşinde,

Gözü halkın ekmeğinde,aşiında,

Sonumuzu böylemi görmeliydik? 

Her kes gaflet uykusundan kalkmalı,

Bu yeni nesile sahip çıkmalı,

Sokaklarda aç insan bırakmamalı,

Biz bunları önceden görmeliydik...

Ta küçükken bilmeliydi hakkını,

Büyüğünce yemezdi kul hakkını,

Yıkmaz idi mazlumların barkını,

Seyfet derki bunları görmeliğdik...

            25.02.2006', 'Istırapla inleyen bu bağrımın, Bu beynimi iğneleyen sırrımın, Sevda yüklü yaşamımın,gönlümün, Der ki Yarap böylemi olmalıydık?  Her kes baks...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/boylemi-olmaliydik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmayacağım Asla', 'seni-unutmayacagim-asla-i-lyas-genc-96whu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün senden ayrılışımın kırkıncı gününü kutluyorum 

Yine yalnız bir başıma acılarla ağlıyorum 

Tam kırk gün geçti aradan..kırk yıl gibi.. 

İçtiğimiz son kahvemiz geliyor aklıma 

Şu an üçüncü katın sokak direğini gören camındayım 

Çocuklar sek sek oynamaya çağırsa da beni 

Artık eskisi gibi olamadığımı hissediyorum 

Ne çocuklarla sek sek oynuyorum, nede 

Tavla turnuvalarında boy gösteriyorum.. 

Senden öncekiler gibi seninde zamansız gidişin 

Benim alışkanlıklarımı altüst etti şimdi fark ediyorum 

Bir elimde kahvem bir elimde bomboş kalan ümitlerim 

İdam cezası almış bir mahkum gibi asılmayı bekliyorum

Dayanacak gücüm kalmadı acılara,tükeniyorum..kayboluyorum..

Keşke diyorum keşkeler arasında gidip geliyorum

Olsaydın yanımda,beraber çocukları seyretseydik

Sen çocuklarla körebe oynardın bir süre sonra 

Ben sigaramı içerdim eskisi gibi yani..

bana kızardın söndür derdin Ben avucumun içine saklardım,

elim yanardı anlardın Yanıma gelip öpüp koklardın,

ben sana doyamazdım Sen bana kıyamazdın..

benzin dökülüp Dirhem dirhem yakılsaydım 

şu an yandığım gibi yanmazdım 

Hiç işlemediğim bir günahla yaşamak zorundayım 

Az kaldı sende biliyorsun ki artık yolun sonundayım 

Keşke şu kırk günlük  düzeni bozsaydık..hiç ayrılmasak 

Hep mutlu olabilseydik..ama olmadı.. 

Tutkular bize yasaklanmış,sevdalar yasaklanmış 

Keşkeklerle,amalarla geçeçek ömrümüz 

Böyle yazılmış alın yazımız 

Yazımızda bahtımız gibi karaydı 

Şimdi hayallarımı arıyorum sokaklarda 

Göz yaşlarım nisan yağmurlarına karışıyor 

Ve sana değen damlaları arıyor okyanuslarda.. 

Sensiz kalmak  beni  kötü yollara  sürüklese de

bekliyorum,.seni özledikçe artan sevgim.. içimde 

derin uçurumlar oluştursa da aldırış etmiyorum

biliyorum ki..bu dünyada olmasa 

Cennet bahçelerinde kavuşacağız..elbet bir gün buluşacağız

Ve ben sensizliğimin şu kırkıncı gününde 

Sana olan duygularımı yazıyorum görünmeyen duvarlara 

Adına şiir mi derler makalemi,bilmecemi bilmem  ama 

Unutmamak için acılarımı haykırıyorum dağlara taşlara

Seninle paylaştığım hatıralara,ve kitabın üzerine yemin ediyorum ki! 

Seni unutmayacağım..seni unutmayacağım asla…', 'Bugün senden ayrılışımın kırkıncı gününü kutluyorum  Yine yalnız bir başıma acılarla ağlıyorum  Tam kırk gün geçti aradan..kırk yıl gibi..  ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/seni-unutmayacagim-asla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-sahabettin-mert-5o42h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana,

Seni seviyorum…

Diyebilmenin farklılığını.

İçimde hissederken…

İçinde adının geçtiği,

Toplamak istedim tüm şiirleri…

Evimin her bir duvarına,

İşlemek istedim gülüm seni…

Yapmak istedim resmini.

Hayal ettim, 

Kapatarak gözlerimi…

Dudaklarını ve gülüşünü tasvir edemedim.

Bakışlarını ve gözlerini de.

Ay yüzün ise çizilemedi tuvale…

Saçlarının tonu dahi yoktu paletimde…

Militan ruhumun,

Eylem adımlarımla dolaşmasında.

Sevdan yüreğimi,

Özlem bedenimi her dağladığında.

Duvarlara yazmak istedim…

Adının baş harfiyle,

Benim adımın baş harfini.

Yan yana...

Sana,

Seni seviyorum…

Diyebilmenin farklılığını.

Yaşamaksa; 

En büyük dileğimdi…

İnan gülüm hayatta…

Şimdi ise çok mutluyum.

Çünkü, sana; 

Seni seviyorum…

Diyebiliyorum.', 'Sana, Seni seviyorum… Diyebilmenin farklılığını. İçimde hissederken… İçinde adının geçtiği, Toplamak istedim tüm şiirleri… Evimin her bir du...', ARRAY['Türk Edebiyatı','Şiir','Şahabettin Mert']::text[], 8.5, '{"poet":"Şahabettin Mert","poet_slug":"sahabettin-mert","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seni-seviyorum-339-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaş!', 'gardas-afiq-agdamli-hs3gn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Felek tuzak kurmuş,avını bekler,

Kimse bu tuzaktan kaçamaz,gardaş! 

Hep kendi yükünü bizlere yükler,

İyiyi,yamanı seçemez,gardaş! 

Tükenmiş sabrımız,artmış kinimiz,

Hep dünü aratır bizim günümüz.

''Adil ol! ''dese de yüce dinimiz,

Kimse menfaat`ten geçemez,gardaş! 

Eğri yorulmadan''hakkın''arıyor,

Doğrunu bitmeyen dertler sarıyor.

Eğri azrailden can koparıyor,

Doğru ektiğini biçemez,gardaş! 

Ağdami,doğru az iyidir çoktan,

En zor gününde de ayrılma haktan.

Allahdır vareden dünyanı yoktan,

İsterse kuş bile uçamaz,gardaş!', 'Felek tuzak kurmuş,avını bekler, Kimse bu tuzaktan kaçamaz,gardaş!  Hep kendi yükünü bizlere yükler, İyiyi,yamanı seçemez,gardaş!  Tükenmiş ...', ARRAY['Türk Edebiyatı','Şiir','Afiq Agdamlı']::text[], 8.5, '{"poet":"Afiq Agdamlı","poet_slug":"afiq-agdamli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gardas-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatay 23 Temmuz', 'hatay-23-temmuz-hayreddin-abravci-6qqpb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HATAY–23 TEMMUZ

Harbiye’de Defne ağacındaki yaprağım ben…

Belki de Asi nehrinde bir damla su...

Künefedeki tuzsuz peynirim..

Belki de çevlik’te bir kum tanesi…

Bat ayaz da bir esinti, bir rüzgârım ben…

Belki de Altınözü’nde bir zeytin ağacı..

Yayladağı’nda bir tabakada tütün..

Belki de bir genç kızın kulağında küpe..

Bedii amcanın bahçesinde bir demet çiçeğim ben…

Belki de Aysel teyzenin tandırında sıcak bir ekmek..

Habib Neccar camiinde bir öğle ezanı

Belki de kilisede bir çan..

Mozaik müzesinde bir lahitim ben…

Belki de Vali konağında bir havuz..

Sen Piyer de bir zeytin ağacı..

Belki de şu havai fişekteki ebruli bir renk…

Antakya’nın sokaklarında bir kaldırım taşıyım ben…

Belki de kebaptaki ince bir ekmek…

Gelinlik kızın elindeki kına…

Belki de zeytin dağındaki bir tutam zahter…

Belediye parkında bir salıncağım ben…

Belki de Samandağ’da güzel bir kız..

Bardaktaki soğuk bir meyan şerbeti..

Belki de hasret ile akan gözyaşı…

Tatlıda köpük helvası, sarmada yaprağım ben…

Belki de kısırda bir parça biber salçası..

Gelinlik kızın belinde altın bir kemer..

Belki de Mehmetçiğin yanık mektubu..

Kırk yıllık Türk Yurduyum ben…

Belki de Ata’mın üniformasında Ay ile yıldızım ben

Belki  Kılıcının kabzasında pırlantayım ben…

Belki  Albay Şükrü Kanatlı’nın beyaz atıyım ben…

Belki de Misak-ı Millinin gümüş tacıyım ben…

      

                                                                                   Hayreddin ABRAVCI

                                                                    

                                                                               ÇERKEZKÖY/TEKİRDAĞ', 'HATAY–23 TEMMUZ Harbiye’de Defne ağacındaki yaprağım ben… Belki de Asi nehrinde bir damla su... Künefedeki tuzsuz peynirim.. Belki de çevlik...', ARRAY['Türk Edebiyatı','Şiir','Hayreddin Abravcı']::text[], 8.5, '{"poet":"Hayreddin Abravcı","poet_slug":"hayreddin-abravci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hatay-23-temmuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memur', 'memur-volkan-i-ncel-r5kd8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Simit satiyorum köşede

İşten çıktıktan sonra beşte

Çocukların kahvaltısını yaptırdıktan

Yumurtayı haşlayıp,ekmeği kızarttıktan sonra

Selinayın üzerini örtüp

Sevim''e masal  anlattıktan sonra

Biraz yazı yazıp,gazeteleri okuduktan 

Kapıcı Ayhan''dan  gelen postaları aldıktan sonra

Otobüsten inip ıslanmadan eve koştuktan 

Anahtarımı aramayıp kapıcı dairesinin ziline bastıktan sonra

Arkadaşlara iyi akşamlar dileyip işyerinden çıktıktan 

Gelen evrakları onaylayıp,gidenleri kaydettikten sonra

Çayla simidimi yeyip  öğünü atlattıktan sonra

Koşa koşa büroya girip işe geç kalmadıktan sonra

Her sabah memur oluyorum

İnsanlığımı evde bıraktıktan sonra', 'Simit satiyorum köşede İşten çıktıktan sonra beşte Çocukların kahvaltısını yaptırdıktan Yumurtayı haşlayıp,ekmeği kızarttıktan sonra Selinay...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/memur-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyayı zulümden kurtaralım,gidelim adaletli güzel olan çağlara', 'dunyayi-zulumden-kurtaralim-gidelim-adaletli-guzel-olan-caglara-halil-colak-o5tg3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Irakta Müslümanlar bir birine düşmüş vuruyor

Dinimin düşmanları petrol vurgununu vuruyor

Ey gafil Müslümanlar peygamberim ne  ediyor

Birlikte kuvvet var,ayrılıkta düşman sizi yer diyor

İnandığınız bizi yaratan da Allah aynı Allah  değil mi

İman ettiğiniz Hz.Muhammed aynı peygamber değil mi

Okuduğunuz kuran Müslüman’ım aynı kuran değil mi

Namazda durduğunuz  kıbleniz de aynı kıble değil mi 

Bak İsrail Yahudi’ si sizleri de düşürdü de birbirinize

 Müslümanlar ölüyor Allah’tan korkun gelin kendinize

Uyanın  artık bu olaylar neden olacak sizin felaketinize

Haçlılar bu gidişle tüm sahip olacak kutsal  toprağınıza

Ey Müslüman kardeşim uyma fitneye dökme kardeş kanını

Tüm Müslümanlar birbirine düşer alırsın bunların vebalini

Kendinize gelin sunisi,Şii si ahir rette veremezsiniz hesabını

Bırakın ayrılığı düşmana karşı koyun koruyun dininizi imanızı

Bir zamanlar da Yahudi Abdullah İbni sebe aynı işi yapmıştı

İslam’da ilk fitneyi çıkarıp Müslümanları birbirine de katmıştı

Müslümanlar bu fitne yüzünden çok açılar,izdi rap da çekmişti 

Çok belalar Müslümanlar görmüş dirlik düzenliğini bozmuştu

Bırakın mezhep ayrımını Allah rızası için bir kenara koyunda

Haçlıya karşı birlik olalım ders verelim o  zalim münafıklara

Kudüs u kurtaralım Müslümanları götürelim eski mutlu günlere

Dünyayı zulümden kurtaralım,gidelim adaletli güzel olan çağlara

Halil Çolak 25.2.2006 Ankara', 'Irakta Müslümanlar bir birine düşmüş vuruyor Dinimin düşmanları petrol vurgununu vuruyor Ey gafil Müslümanlar peygamberim ne  ediyor Birlikt...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dunyayi-zulumden-kurtaralim-gidelim-adaletli-guzel-olan-caglara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Git', 'hadi-git-murat-celebi-sfhek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HADİ GİT

Düşünme beni hiç hadi git

Gecelerimle baş başa bırak ve git

Umutlarımız bende kalsın

Hayallerimiz yerin dibine batsın

Anılar bir bir yansın

Üzülme hiç bırak ve git

Acı verme bana arkana bakmadan git 

Bir günahla yanıp bunaldım

Hatamı geçte olsa anladım

Bir hayaldi belkide düşünmeden yaşadım

Bırak beni kendi halimle git 

Bir söz bile söyleme

Teselli verme sözlerin yetmez

Sanki gerimi döneceksin farketmez

Dağlar,Uçurumlar var aramızda aşılmaz

Her şeyi bana bırak ve git

Murat ÇELEBİ', 'HADİ GİT Düşünme beni hiç hadi git Gecelerimle baş başa bırak ve git Umutlarımız bende kalsın Hayallerimiz yerin dibine batsın Anılar bir bi...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hadi-git-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haksızlığa Kızarım', 'haksizliga-kizarim-yusuf-onder-bahceci-7caie', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben her çeşit şiir yazarım, haksızlığa kızarım,

Nerde oynanan bir oyun görsem de bozarım,

Çok sevdiğim aklıma gelince inan ki ağlarım,

Ben her çeşit şiir yazarım, haksızlığa kızarım.

Derdim derindir, derin kendi kendimi yerim,

Nerde sevdiğim hâni, kimlere sitem ederim,

Fazla kafa yorma, en uzak nereyse giderim,

Ben her çeşit şiir yazarım, haksızlığa kızarım.

Vallahi senin beni düşündüğünü, bilirim ben,

Çok ustasın sevdiğini de belli etmezsin hem,

Senden ayrıyım, demler gidiyor benden dem,

Ben her çeşit şiir yazarım, haksızlığa kızarım.

Şiirleri okuyan dostlar tekrar, tekrar okusun,

Kelimeler yanlış anlaşılmasın, dostluk olsun,

Ben yârdan ayrıyım kâlbim nasıl rahat olsun,

Ben her çeşit şiir yazarım, haksızlığa kızarım.', 'Ben her çeşit şiir yazarım, haksızlığa kızarım, Nerde oynanan bir oyun görsem de bozarım, Çok sevdiğim aklıma gelince inan ki ağlarım, Ben h...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haksizliga-kizarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin Rengi', 'yuregin-rengi-samiha-i-kbal-l1u6m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biraz ben diyorum 

Biraz kendim

Yüreğimin rengi

               AŞK...', 'Biraz ben diyorum  Biraz kendim Yüreğimin rengi                AŞK......', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yuregin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanağım', 'dayanagim-fuat-dogan-pml6s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DAYANAĞIM

bir bahar yelidir 

beni alıp bilinmezliklere sürükleyen

ne rotam bellidir

ne de düşlerimin son durağı

tek dayanağım

kıyısına tutunduğum aşk

ve zulamda eksilmeyen umut.

                           Fuat DOĞAN

                                2005', 'DAYANAĞIM bir bahar yelidir  beni alıp bilinmezliklere sürükleyen ne rotam bellidir ne de düşlerimin son durağı tek dayanağım kıyısına tutun...', ARRAY['Türk Edebiyatı','Şiir','Fuat Doğan']::text[], 8.5, '{"poet":"Fuat Doğan","poet_slug":"fuat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dayanagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Yanıyor', 'i-cim-yaniyor-seyfet-bozcali-aa6tl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerde boynu bükük bir öksüz görsem,

Yüreğim burkulur,içim yanıyor.

Haksızlık içinde bir mazlum görsem,

Gözlerim ağlıyor,içim kanıyor...

Nefret ettim iki yüzlü olandan,

Fitneciden bunca yalan,dolandan,

Şöhret için kötü yola dalandan,

Düşünürüm ama aklım almıyor...

Hak yolunda zorluklarla yarıştım,

Nefse küstüm düşmanımla barıştım,

Aşk yolunda Yunus''lara karıştım,

Sakladım bunları nefsim bilmiyor...

Dostluk kurdum insanların mertiyle,

Hep dertlendim,mazlumların derdiğle,

Karşılaştım zalimlerin sertiğle,

Seyfet derki bunu kimse bilmiyor...

25.02.2006', 'Nerde boynu bükük bir öksüz görsem, Yüreğim burkulur,içim yanıyor. Haksızlık içinde bir mazlum görsem, Gözlerim ağlıyor,içim kanıyor... Nefr...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/icim-yaniyor-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim', 'gidecegim-murat-celebi-m2949', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GİDECEĞİM

Sana elveda demeden 

Gideceğim buralardan 

Bilmeyeceksin gittiğimi 

Aramayacaksın bile beni

Hiç bilmeyeceksin seni sevdiğimi

Buralardan senin için gittiğimi

Yanında olmak acı veriyor bana 

SENİ SEVİYORUM diyemedim ben sana

MURAT ÇELEBİ', 'GİDECEĞİM Sana elveda demeden  Gideceğim buralardan  Bilmeyeceksin gittiğimi  Aramayacaksın bile beni Hiç bilmeyeceksin seni sevdiğimi Bural...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidecegim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-murat-celebi-7fdqz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'AĞLAYACAKSIN

Birgün canım bir gün 

Sende benim gibi 

Aşık olacaksın benim ne çektiğimi 

O zaman anlayacaksın

Kaybettiklerine ağlayacaksın

Hatanı anlayıp telefona sarılacaksın

Ama beni bulamayacaksın

Kaybettiklerine ağlayacaksın

MURAT ÇELEBİ', 'AĞLAYACAKSIN Birgün canım bir gün  Sende benim gibi  Aşık olacaksın benim ne çektiğimi  O zaman anlayacaksın Kaybettiklerine ağlayacaksın Ha...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglayacaksin-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Zaman Geçti', 'kac-zaman-gecti-murat-celebi-8g2tn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KAÇ ZAMAN GEÇTİ

Kaç zaman geçti bilmiyorum

Ben seni özlüyorum

Geçiyor bak günler ardı sıra

Hasretim ben o yıllara

Sen bilmedin değerimi

Sana verdiğim sevgimi

Gideceğim bu şehirden 

Sana elveda bile demeden

Arayacaksın beni yanında

Nafile güzelim bende aşkın bitti

Seni seven o sevgili

Bu şehri çoktan terk etti

Murat ÇELEBİ', 'KAÇ ZAMAN GEÇTİ Kaç zaman geçti bilmiyorum Ben seni özlüyorum Geçiyor bak günler ardı sıra Hasretim ben o yıllara Sen bilmedin değerimi Sana...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kac-zaman-gecti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki haylaz', 'i-cimdeki-haylaz-fuat-dogan-agkmh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İÇİMDEKİ HAYLAZ

yanıbaşımda öksüz kalmış dugularım

uzak çağın düşlerindeyim şimdi

içimdeki haylaz çocuk da olmasa

hepten eksik kalırım yaşamda

                           Fuat DOĞAN

                               2005', 'İÇİMDEKİ HAYLAZ yanıbaşımda öksüz kalmış dugularım uzak çağın düşlerindeyim şimdi içimdeki haylaz çocuk da olmasa hepten eksik kalırım yaşam...', ARRAY['Türk Edebiyatı','Şiir','Fuat Doğan']::text[], 8.5, '{"poet":"Fuat Doğan","poet_slug":"fuat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/icimdeki-haylaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviye', 'seviye-ersin-alptekin-d4xkx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Altta kalanın üste çıkma gayreti

Zirvelere oynamanın rehaveti

Her insanın yer gök arası seviyesi

Sizin insanlıktaki yeriniz neresi? 

Hırsızı,fedakarı,iyimseri

Akıllısı,kurnazı,cimrisi

Her insanın yer gök arası seviyesi

Sizin insanlıktaki yeriniz neresi? 

Zalimi,mazlumu,merhametlisi

Suskunu,gevezesi,düşüneni

Her insanın yer gök arası seviyesi

Sizin insanlıktaki yeriniz neresi? 

Şaşkını,hovardası,saf olanı

Şerefsizi,kötümseri,iyi niyetlisi

Her insanın yer gök arası seviyesi

Sizin insanlıktaki yeriniz neresi? 

Aynı tohumda binlerce karakteri

Bu handa ölüm var vücutlar fani

Anlamalı insanoğlu,anlatmalı bunu herkez bilmeli

En üst seviyedir son peygamberin yeri...

nicova', 'Altta kalanın üste çıkma gayreti Zirvelere oynamanın rehaveti Her insanın yer gök arası seviyesi Sizin insanlıktaki yeriniz neresi?  Hırsızı...', ARRAY['Türk Edebiyatı','Şiir','Ersin Alptekin']::text[], 8.5, '{"poet":"Ersin Alptekin","poet_slug":"ersin-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seviye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamazsın Beni', 'bulamazsin-beni-murat-celebi-489vl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BULAMAZSIN BENİ

Bulamazsın o eski beni

Kalbi sevgi seli

O masum gülüşleri

Bulamazsın o eski beni

Üstünden yıllar geçti 

Sana verdiğim değeri

Bulamazsın o eski beni

Seni seveni

Yıllar önce bırakıp gittiğin gibi

Bulamazsın o eski beni

MURAT ÇELEBİ', 'BULAMAZSIN BENİ Bulamazsın o eski beni Kalbi sevgi seli O masum gülüşleri Bulamazsın o eski beni Üstünden yıllar geçti  Sana verdiğim değeri...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulamazsin-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-murat-celebi-kh9m1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YILDIZLAR

Sen gideli ıssız ve sessiz buralar

Artık karanlık tüm sokaklar

Mezar taşlarım kaldırımlar

Kefenim oldu YILDIZLAR

Murat ÇELEBİ', 'YILDIZLAR Sen gideli ıssız ve sessiz buralar Artık karanlık tüm sokaklar Mezar taşlarım kaldırımlar Kefenim oldu YILDIZLAR Murat ÇELEBİ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yildizlar-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-murat-celebi-k3jjm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖLÜM

İnsan bir kez ölür

Ben hergün ölüyorum

Artık ölüm bile oyun bana 

Ölümüm kurtuluşum olur belkide

Hergün ölmektense

Birkez ölürüm ve...,

Biter bu işkence...! 

Murat ÇELEBİ', 'ÖLÜM İnsan bir kez ölür Ben hergün ölüyorum Artık ölüm bile oyun bana  Ölümüm kurtuluşum olur belkide Hergün ölmektense Birkez ölürüm ve...,...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olum-270-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Suçum Sevmek', 'tek-sucum-sevmek-yusuf-onder-bahceci-oy6u1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim tek suçum var, kâlbimle sevdim dilimle diyemedim,

Seni çok severdim, seni düşünür, düşünür, hâyal ederdim,

Bazan dalar, dalar bulutlara, semalara, arşa bile giderdim,

Benim tek suçum var, kâlbimle sevdim dilimle diyemedim.

Vefasız sevdiğim bunu biliyordun, bazan bana gülüyordun,

Sen benden beterdin, utanıyor sende bir türlü demiyordun,

Biliyordum, biliyordum sende benim gibi hayal kuruyordun,

Benim tek suçum var, kâlbimle sevdim dilimle diyemedim.

Şimdi senden geriye kalan, bir kaç tane resim var elim de,

Ellerim se bellerim de, gözlerim yollara bakar beklerim de,

Neden, neden diyerek içimi çekerim, deliyim, derbederim,

Benim tek suçum var, kâlbimle sevdim dilimle diyemedim.

Mektuplarını çoktan yaktım, yakarken, ümitlerimi de yaktım,

Ellerimi semaya açıp, gözlerimi yere diktim böyle ağladım,

Senden ayrı kaç bahar geçti saymadım, dedim ya ağladım,

Benim tek suçum var, kâlbimle sevdim dilimle diyemedim,', 'Benim tek suçum var, kâlbimle sevdim dilimle diyemedim, Seni çok severdim, seni düşünür, düşünür, hâyal ederdim, Bazan dalar, dalar bulutlar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-sucum-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Gelme', 'git-gelme-murat-celebi-w53o5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GİT GELME

Geri gelme 

Dayanamam inan

Geri gelme 

Katlanamam ''''yalan''''...! 

Geri gelme 

İstemiyorum seni

Ölsemde yalnızlıktan...! 

Murat ÇELEBİ', 'GİT GELME Geri gelme  Dayanamam inan Geri gelme  Katlanamam ''''yalan''''...!  Geri gelme  İstemiyorum seni Ölsemde yalnızlıktan...!  Murat ÇELE...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/git-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-murat-celebi-u0fdl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''''YALAN ''''! ! 

Unuttum aşkı sevdayı

Yıllar aldı benden 

Tüm duygularımı 

Sevgim uğruna

Harcadığım zamanı

Yalanmış hepsi

Bana olan sevgisi

O masum gülüşü

Seni seviyorum CANIM deyişi

MURAT ÇELEBİ', '''''YALAN ''''! !  Unuttum aşkı sevdayı Yıllar aldı benden  Tüm duygularımı  Sevgim uğruna Harcadığım zamanı Yalanmış hepsi Bana olan sevgisi O ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalan-206-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutamam', 'seni-unutamam-murat-celebi-1t7ld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '? ? ? *Seni Unutamam*? ? ? 

Sabahlarımda doğan güneş

Gecelerimde yolumu aydınlatan ay

Baktığım her yerde

Senin yüzün var 

Seni unutamam 

Bende bir sevdan var

Bu kalp senin için atar 

Bu hasretleri kaldır artık aradan

Bu şehirde seni bekleyen 

Bir aşık var...! 

MURAT ÇELEBİ', '? ? ? *Seni Unutamam*? ? ?  Sabahlarımda doğan güneş Gecelerimde yolumu aydınlatan ay Baktığım her yerde Senin yüzün var  Seni unutamam  Ben...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-unutamam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim Sevgilim', 'vazgectim-sevgilim-murat-celebi-dopvd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vazgeçtim Sevgilim

Gecelerce Dusunmek Yeter, Seni 

Seveceksen Sev Beni 

Vereceksen Bana... 

... Herseyini 

Adayacaksan Sevgini 

Tutacaksan Ellerimi 

Yatacaksan Dizlerime 

Bakacaksan Gozlerime 

Don Be Zalim Don Geri 

Gecelerce Dusunmek Yeter Seni 

Aglatma Artik Seni Seveni 

Kiymet Bilmezsin, Bilirim Seni 

Vazgectim Sevgilim Donme Geri 

Unut Seni Sevdigimi 

Ve Çık Ruyalarimdan Donme Bana Geri 

Gecelerce Dusunmek Yeter Seni... 

MURAT ÇELEBİ', 'Vazgeçtim Sevgilim Gecelerce Dusunmek Yeter, Seni  Seveceksen Sev Beni  Vereceksen Bana...  ... Herseyini  Adayacaksan Sevgini  Tutacaksan E...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vazgectim-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-songul-sandikci-94sdu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim kenetlendi bu gece,

Ne olduğunu anlamadım ben yine,

Ağlayan gözlerim olsa bile,

Gözyaşları damlıyordu yüreğime.

Soruyorum kendime nedir bu diye,

Geçmişten gelen bir sızı olduğunu bile bile,

Dilim söylemek istemesede,

İçimden bir ses haykırıyor ''Neden? '' diye.', 'Gözlerim kenetlendi bu gece, Ne olduğunu anlamadım ben yine, Ağlayan gözlerim olsa bile, Gözyaşları damlıyordu yüreğime. Soruyorum kendime n...', ARRAY['Türk Edebiyatı','Şiir','Songül Sandıkçı']::text[], 8.5, '{"poet":"Songül Sandıkçı","poet_slug":"songul-sandikci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neden-225-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyorum Bu Gece Sabah Olmasın', 'i-stemiyorum-bu-gece-sabah-olmasin-ahmet-nural-ozturk-9y8yj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'istemiyorum bu gece sabah olmasın

lakin olacak

yenik düşecek  siyah beyaza

senden ayrı anlar zor gelecek elbet bana

derken gün batacak

siyah gittikçe koyulaşırken gözlerimde sen

ellerinde umudum çoğalacak

bir siyah bir beyaz 

bir ben bir sen bir de güneş

alt alta üst üste geçerken ömür

mehtap ve göğün diğer güzellikleri hep yanımda

ve ben her gece fısıldayacağım kulağına

istemiyorum bu gece sabah olmasın

lakin olacak

ve bir sabah omuzlarda ayrılacağım senden

aşkımız beyazlar içinde karanlığa koşacak', 'istemiyorum bu gece sabah olmasın lakin olacak yenik düşecek  siyah beyaza senden ayrı anlar zor gelecek elbet bana derken gün batacak siyah...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istemiyorum-bu-gece-sabah-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-sadettin-deren-hh9i3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben öldüğümde,

Kurtlar kuşlar bayram edecekler.

Ben onlara ne yaptım ki,

Üşüşüp beni yiyecekler.

Ben öldüğümde,

Uzun serviler yükselecek üzerimde.

Uzayacaklar Tanrı’ya yemyeşil,

Rüzgârlar esecek her yerimde.

Ben öldüğümde,

Şiirlerim üzülüp büzülecekler,

Onları kimler okur kim bilir? 

Üşüyüp titreyecekler.', 'Ben öldüğümde, Kurtlar kuşlar bayram edecekler. Ben onlara ne yaptım ki, Üşüşüp beni yiyecekler. Ben öldüğümde, Uzun serviler yükselecek üze...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazarın nefes alışları 3', 'yazarin-nefes-alislari-3-baykal-kaanalp-29n7r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'işe sakıncalı bulduğu bazı bölümleri çıkararak başladı.

kendi fikirlerini yansıtmıyordu sanki.yazdıkları.

yazılmaya çalışılan,alelacele çiziktirilmiş izlenimini

veriyordu.gözlüklerini çıkardı.büyük bir özen ve 

itinayla camlarını şu sıralarda tedavülden kalkmış

yumuşak bir bezle sildi.hohladı tekrar sildi.

yeniden başlamayı canı istemedi.yapabileceğinden de

şüpheliydi artık.bu kadar saçma sapan destanımsı 

kelimeler zincirini insanlar nasıl sayıp döküyorlardı.

hayretler içinde kalıyordu.okumaya çalışırken.

oysa kendisi alabildiğine sade,her bir harfi boşa 

harcamamak için ne kadar çaba sarfediyordu.

hiç kıymet bilmiyorlardı.onu okuduğunu sananlar

gerçekten okunuyormuydu.öylesine miydi? 

biraz dumana ihtiyacım var diye düşündü.

arandı her tarafını bulunduğu mekanın

yoktu ki,şöyle doyasıya içine çekebileceği

bi duman türü.bütün dumanlar işte öyle.

kaskatı kesilmiş bir dilim kaşar peynirini

eline aldı iştahla bir iki ısırık aldı.tadı hoştu.

yanında çay olmalıydı heralde iyi bir kahvaltı

çaysız olmazdı.çaydanlığı yavaş ve hüzünlü

hareketlerle ocağa koydu.şimdi bir de kibrit

lazımdı.her yere baktı.iç ceplerine bile ceketinin.

vazcaydı bulut kümeleriyle oynaşmaktan

kaynamış suyun dumanına kaptırdı kendini

uzun bir yürüyüşe çıktı gözlerini kapatan 

cam parçaları dünyayı iki cam parçasından

görüntülemek herhangi bir kameraman kadar

sıradan düzensiz öylesine isteksiz zevksiz

okumakda vardı işin içinde bütün görünmezleri 

çayın demi kadar keyifli duman altı olunca

sözcükler tarafından sarsılmak omuzbaşlarından

silkelenmek kalpsizliğine aldırmadan bir aşkın

dilimlenmiş bir tutam peynir çürütülmüş rafta

unutulmuş zeytin tarafından aldırmadan', 'işe sakıncalı bulduğu bazı bölümleri çıkararak başladı. kendi fikirlerini yansıtmıyordu sanki.yazdıkları. yazılmaya çalışılan,alelacele çizi...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yazarin-nefes-alislari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Evvel Ölürsem', 'senden-evvel-olursem-yusuf-onder-bahceci-pvu92', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni nasıl, nasıl da sevdiğimi, artık biliyorsun,

Yıllarım heba oldu da gitti be gitti mi diyorsun,

Allah için söyle, benim için ne düşünüyorsun,

Seni nasıl, nasıl da sevdiğimi, artık biliyorsun.

Önce ben ölürsem, Arasat''ta bekleyeceğim,

Mizan terazisi önünde sevmiştim diyeceğim,

Başın öne eğilecek, cevabını bekleyeceğim,

Önce ben ölürsem, Arasat''ta bekleyeceğim.

Benden evvelce ölürsen kabrine geleceğim,

Gözyaşım sel olacak, toprak yaşla dolacak,

Mezarının başından, beni kimler koparacak,

Benden evvelce ölürsen kabrine geleceğim,

O zaman bilecek, eyvah, eyvah, diyecekler,

Mezarının başındayken kollarıma girecekler,

Önder, Allah''ın adına sabır, sabır diyecekler,

O zaman bilecek, eyvah, eyvah, diyecekler...', 'Seni nasıl, nasıl da sevdiğimi, artık biliyorsun, Yıllarım heba oldu da gitti be gitti mi diyorsun, Allah için söyle, benim için ne düşünüyo...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-evvel-olursem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-murat-celebi-h9ckl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİLİRMİSİN

Bilirmisin sen yolcu uğurlamayı

Canından can yollamayı 

Gözünden yaş yerine kan akıtmayı 

Bugün yolladım 

Canım dan can

Bedenimden bir parçam

Onun yokluğuyla 

Bir yanım hep eksik kalan

MURAT ÇELEBİ', 'BİLİRMİSİN Bilirmisin sen yolcu uğurlamayı Canından can yollamayı  Gözünden yaş yerine kan akıtmayı  Bugün yolladım  Canım dan can Bedenimde...', ARRAY['Türk Edebiyatı','Şiir','Murat Çelebi']::text[], 8.5, '{"poet":"Murat Çelebi","poet_slug":"murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bilirmisin-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-songul-sandikci-aa9sq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün dönüpte baktığında arkana,

Yalnız kalacaksın şu koskoca dünyada,

Sana yalvardığım günleri hatırlayıp beni arayacaksın,

Fakat çoktan iş işten geçmiş olacak,

O zaman kendi kendine kahrolup ağlayacaksın.

Ben ise hatıralarımı düşüneceğim,

Senin durumun bil ki beni sevindirmeyecek,

Aksine kederlendirecek,kahredecek ve üzüleceğim,

Senin tüm yaptıklarına rağmen,

Emin ol seni ömür boyu içimde hissedeceğim.

                                                          

                                                                               1991', 'Bir gün dönüpte baktığında arkana, Yalnız kalacaksın şu koskoca dünyada, Sana yalvardığım günleri hatırlayıp beni arayacaksın, Fakat çoktan ...', ARRAY['Türk Edebiyatı','Şiir','Songül Sandıkçı']::text[], 8.5, '{"poet":"Songül Sandıkçı","poet_slug":"songul-sandikci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-gun-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Ta Kendisi', 'umudun-ta-kendisi-dogan-ekdi-cehsc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanıtla 

Tümünü Yanıtla 

İçinde İlet 

Ek Olarak İlet 

