INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlar eriyor çıkıyor da o güzelim kardelen', 'karlar-eriyor-cikiyor-da-o-guzelim-kardelen-halil-colak-u0zvh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karlar eriyor çıkıyor da o güzelim kardelen

O vefasız yar ki rüyalarıma da gizlice giren 

Bin bir çiçekten toz alıp ta petekte bal yapan

Felek beni acımasız  bir gülü zara da yar etti 

Gönül gece gündüz aşık hane de gezerken

Yarın bahçesinden  gonca güller dererken 

Güzel gül kokusunu da etrafına saçarken

Felek beni de bir nadide çiçeğe de kul etti

Halil Çolak 252.2006 Ankara', 'Karlar eriyor çıkıyor da o güzelim kardelen O vefasız yar ki rüyalarıma da gizlice giren  Bin bir çiçekten toz alıp ta petekte bal yapan Fel...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karlar-eriyor-cikiyor-da-o-guzelim-kardelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül''e Düşer', 'gul-e-duser-gulseren-onay-9f8lu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay yok olur, yıldız kayar, 

Siyah peçe güle düşer 

Aşk kaybolur, umut solar, 

Bir bilmece güle düşer 

Alem coşar, mutlu olur

Düğün dernek toy kurulur

Saz çalar,davul vurulur

sesi gonca güle düşer

Gün kavuşur eve döner

Dört duvara hasret siner

Işık söner, kilit döner

Öksüz gece güle düşer 

Ömür dolu haz ve keder

Bülbül güle isyan eder

Aşk yangını içten tüter

Kor usulca güle düşer.

Bu ne tasa, bu ne zulüm,

Dayanamaz buna Gül’üm

Bekle gelsin diye ölüm,

Gam sessizce güle düşer..

25.02.2006/ ANTALYA', 'Ay yok olur, yıldız kayar,  Siyah peçe güle düşer  Aşk kaybolur, umut solar,  Bir bilmece güle düşer  Alem coşar, mutlu olur Düğün dernek to...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gul-e-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüğüm Her Güzelde', 'gordugum-her-guzelde-yusuf-onder-bahceci-7qr1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gördüğüm her güzel de gözlerim seni arıyor,

Bil ki ayrılığın hüznüyle, böyle sararıp soluyor,

Senin güzel gözlerin bir türlü beni bırakmıyor,

Gördüğüm her güzel de gözlerim seni arıyor.

Gelsinler şimdi bana aynı hareketi yapsınlar,

Gözlerinden bilirim başka sokağa sapsınlar,

Sakın ha bana, aynı kelimeleri anlatmasınlar,

Gördüğüm her güzel de gözlerim seni arıyor.

Dünya''da tek sevdiğim, gönlümün güzelisin,

Seni nasıl sevmiştim, neden diyememiştim,

O da beni çok seviyor, gitmez mi demiştim,

Gördüğüm her güzel de gözlerim seni arıyor.

Artık bundan sonra ölmüşüm, hep şiir yazılır,

Şiirler yazılır, her şiir sevenin kâlbine kazınır,

Her gece yorganın altında, sessizce ağlanır,

Gördüğüm her güzel de gözlerim seni arıyor...

4', 'Gördüğüm her güzel de gözlerim seni arıyor, Bil ki ayrılığın hüznüyle, böyle sararıp soluyor, Senin güzel gözlerin bir türlü beni bırakmıyor...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gordugum-her-guzelde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ellerime Yabancı Yüzüm/Birde Aynalara', 'bir-ellerime-yabanci-yuzum-birde-aynalara-murat-isik-ht8zj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ellerime yabancı yüzüm,

Birde aynalara.

Yoksa herşey aynı senden sonra.

Usulca süzülüyorum yataktan

Her sabah seni uyandırmadan.

Kılıfını değiştirmedim yastığının

Köşesinde kalmış diye saç telin.

Terliklerim hizada bekliyor beni,

Alışkanlık senden kalan.

Bir ellerime yabancı yüzüm,

Birde aynalara.

Uzun kalamıyorum artık banyoda

Hala ıslakmış gibi diş fırçan.

Hergün aynı saatte çıkıyorum,

Bir dakika bile şaşmadan.

Usulca çekiyorum dış kapıyı

Sürgülenecekmiş gibi arkamdan.

Artık çok dağınıkmışım diye

O alçak kovmuş beni işimden.

Kurtuldum o siyah çantamda 

Bir ton evrak taşımaktan.

Yüküm şimdi bir olta

Ve bir parça bayat ekmek 

Akşam yemeğimden kalan.

Bir ellerime yabancı yüzüm,

Birde aynalara.

Kafada saç kalmamış,

Duyduğuma göre dostlardan.

Sakalım çok uzamış,

Gidip kestireceğim ama...! 

Ah korkmasam aynalardan.', 'Bir ellerime yabancı yüzüm, Birde aynalara. Yoksa herşey aynı senden sonra. Usulca süzülüyorum yataktan Her sabah seni uyandırmadan. Kılıfın...', ARRAY['Türk Edebiyatı','Şiir','Murat Işık']::text[], 8.5, '{"poet":"Murat Işık","poet_slug":"murat-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-ellerime-yabanci-yuzum-birde-aynalara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmadan Rahminde Ölüyor Güzellikler', 'dogmadan-rahminde-oluyor-guzellikler-zeynal-yaman-x7b4c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben mi karamsarım yoksa mevsim mi hazan

Yeter diyorum bu kadar vaveyla bazan

İsyan ediyor dertler kaldırıyor kazan

Doğmadan rahminde ölüyor güzellikler

Koca millet yaşıyorken Fetret Devri''ni

Eski düşmanları pazarlıyor Sevr''ini

Yaşarken halkla birlikte halkın cevrini

İçimde mum gibi eriyor güzellikler

Oysa söylenecek ne de çok şeyimiz var

Güller soluyor dalında itibarda hâr

İşte vatan her yanı ateş her yanı zâr

Nefretin odunda yanıyor güzellikler

Zeynel''im aşktan bir demet sunmak isterdim

Her güzel şeyi bir bir anmak isterdim

Milletim yanmasın tek ben yanmak isterdim

Bir bilserniz niçin ağlıyor güzellikler....? 

1997', 'Ben mi karamsarım yoksa mevsim mi hazan Yeter diyorum bu kadar vaveyla bazan İsyan ediyor dertler kaldırıyor kazan Doğmadan rahminde ölüyor ...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dogmadan-rahminde-oluyor-guzellikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtlar', 'kurtlar-oktay-baykurt-hipqi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'adı konmamış bir dağın 

iki kurdu olsak senle ben

birbirinden ayrı

sürüsüz

aynı geyiğin peşinden koşsak

uzak inlerin ferdi

bir tepenin güneşinde buluşsak

puslu gecelerin ulumalarında  sevişsek

kılanlarını kursak birleşmesiz kızanlığın

hep birbirimize ait olsak

ve zaman bizi harcamaya karar verdiğinde çağırsan beni

aynı ayın ışığında aydınlansa önümüzdeki uçurum

kaysak yıldızlar gibi

ve can bedenden çıkarken öpsem seni,sensizliği...', 'adı konmamış bir dağın  iki kurdu olsak senle ben birbirinden ayrı sürüsüz aynı geyiğin peşinden koşsak uzak inlerin ferdi bir tepenin güneş...', ARRAY['Türk Edebiyatı','Şiir','Oktay Baykurt']::text[], 8.5, '{"poet":"Oktay Baykurt","poet_slug":"oktay-baykurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kurtlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yazmak Yorar mı', 'siir-yazmak-yorar-mi-yusuf-onder-bahceci-6j0cv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir yazmak, yazmak, yorar mı, yorar, yorar,

Hele bir de, yârdan ayrıysan, nasıl da yorar,

Seni bilen dostlar, gıcığına sorar da, sorar,

Şiir yazmak, yazmak, yorar mı, yorar, yorar.

Sevdiğini fazla sevmiş, onu alamamışsan,

Sevdiğin halde, haber dahi salamamışsan,

Hayata kahredip gizli, gizli de ağlamışsan,

Şiir yazmak, yazmak, yorar mı, yorar, yorar.

Sen şimdi, sevdiğine hesap sorabilirmisin,

Bana lütfen cevap ver ver be diyebilirmisin,

Seni sevmese bile defterden silebilirmisin,

Şiir yazmak, yazmak, yorar mı, yorar, yorar.

Önder böyle şiirleri yazıp, yazıp ağlayacak,

Ağlarken de, Kainatı Yaratan''a yalvaracak,

Bilmiyorum bu hasretin sonu neye varacak,

Şiir yazmak, yazmak, yorar mı, yorar, yorar.', 'Şiir yazmak, yazmak, yorar mı, yorar, yorar, Hele bir de, yârdan ayrıysan, nasıl da yorar, Seni bilen dostlar, gıcığına sorar da, sorar, Şii...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siir-yazmak-yorar-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinimize Hakaret', 'dinimize-hakaret-mustafa-aslan-2-edd7h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hollandada yasiyorum,

Hergün degisik insanlar,

Degisik dinler,

Degisik kültürler görüyorum,

Biz onlarin dinlerine saygi duyuyoruz,

Onlar neden böyle yapiyorlar.

Elhamdülillah müslümaniz diyoruz,

Din için elimizden geleni yapmiyoruz,

Allahimiza,

Resulullaha laf atarlar,

Biz sesimizi çikarmiyoruz,

Düsüncelerimiz ne oluyor,

Bir müslüman evladi çikar bunuda halleder diyoruz,

Dogru degil biliyoruz,

Kendimize güvenemiyoruz.

Adamin biri çikar,

Karikatür çizer,

Digeri çikar, Allah yok der,

Bizde aval aval bakar,

Dogrularmis gibi susariz.

Müslümanin biri gelmis bana resullullahi savunur,

O müslüman dedigim,

Köpegine Allahin isimlerinden birini takar,

Cinsel organlarina müslüman ismi verir,

Buna müslümanlik denilmez.

Türkiye yerinden oynadi,

Karikatür olayinda,

Hollanda ses bile çikarmadi,

Allahimiza yapilan hakaretlerde.

Biz nereye gidecez böyle diyen olmadi.

Müslümanlik, kolay degildir,

Müslümanlik, ben müslümanim demek degildir,

Müslümanlik, kanimda müslümanlik var demek degildir,

Müslümanlik, yasamaktir,

Müslümanlik, Allah için savasmaktir,

Müslümanlik, Allahin yoludur.

Bizim gençlerimiz gurbet ellerde,

Baska ülkelerde,

Baska dinler arasinda,

Baska kültür ile yasiyor.

Müslümanligi unutuyor,

Müslümanligi unutturuyor,

Biz bumuyduk dostlarim,

Biz böylemi gördük,

Biz böylemi dukduk,

Resulullahtan.

Hayir,

Biz bu degiliz,

Biz yenilmisiz,

Biz nefsimiz olmusuz,

Cesaretimiz kalmamis,

Dinimize yapilan hakaretlere kulak bükmüsüz,

Duymazdan gelip,

Normal hayata devam etmisiz.

Duyun sesimi ey müslüman evlatlari duyun,

Duyunda bir ses verin,

Duyunda karsi çikin karikatür olaylarina,

Duyunda bosuna göz yasi dökmeyin.

Tarih Ve Saati: 25-02-2006	12:48', 'Hollandada yasiyorum, Hergün degisik insanlar, Degisik dinler, Degisik kültürler görüyorum, Biz onlarin dinlerine saygi duyuyoruz, Onlar ned...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/dinimize-hakaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kervancı', 'kervanci-zeynal-yaman-hkzh3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acı çekiyorum acı

Beynimi kemirir sancı

Dur hele gitme kervancı

Ötelerden bir haber ver

Bir hasret yakar içimi

Közdeki kebap biçimi

Âb-ı hayattır içimi

Ötelerden bir haber ver

Dünyada garip bir kuşum 

Ötelere vurulmuşum

Dağlar aştım yorulmuşum

Ötelerden bir haber ver

Dertten derde dalan oldum

Gidemedim kalan oldum

Kovan idim talan oldum

Ötelerden bir haber ver

1988', 'Acı çekiyorum acı Beynimi kemirir sancı Dur hele gitme kervancı Ötelerden bir haber ver Bir hasret yakar içimi Közdeki kebap biçimi Âb-ı hay...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kervanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezrail Türküsü', 'ezrail-turkusu-engin-akbaba-diuxj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir şiir gibi uyur bebekler

anneler başında bekler

kıskanır melekler

kıskanmadı o

konuşmadı... bakmadı

karanlığı çağırdı / heceler gibi

eteğine yapışan umutları toplayarak

kalbinin üstünde topallayarak  / çıktı

bu kentte camlar bu vakit

pusla sevişir

devşirme rüyalar girer yataklarımıza

sular buza karışır

sahtekar yıldızlar tutar hesabı

ay susar

susar yalanları  çatal dillerin

titrer yalnızlık

kalp gülüşler üretmek

kalpazan yüreklerin hüneri

sattığın çocuğu hırsızlamak,

k a l l e ş ç e

maziyi mora boyayıp

gök kuşağına renk katmak niye

ölü ağaçların hüzünbaz dallarıyle

tütsüle yalnızlığını

.................niye lodosuna yatıyorsun anıların

...........................karbon monoksitse arzun

ilk seviştiğin o esmer kızı düşle

şu sokakları yaksak paris niyetine

çöl türküleri fısıldasak kulağına bu kentin

su katılmış yazgımızın al kanı

dolaşsa boydan boya

niye ne farkımız var mağriplilerden

.......çatal dilleriyle çığlıklar atan kehribar kırbaç

--kardeşşşşşşşşş! ! ! 

biz de yangın yeri taşıyoruz,

bir sevdadan diğerine

(kesik kesik soluklar duyulur önce

sonra yok olur..

kara bir örtünün altından

bu türküyü söyleyenler çekilir)', 'bir şiir gibi uyur bebekler anneler başında bekler kıskanır melekler kıskanmadı o konuşmadı... bakmadı karanlığı çağırdı / heceler gibi eteğ...', ARRAY['Türk Edebiyatı','Şiir','Engin Akbaba']::text[], 8.5, '{"poet":"Engin Akbaba","poet_slug":"engin-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ezrail-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resulullah', 'resulullah-mustafa-aslan-2-job6h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Affet bizi YA RESULULLAH,

Dinimizi koruyamadik.

Affet bizi YA RESULULLAH,

Dinimize yeterince saygi duyamadik.

Affet bizi YA RESULULLAH,

Dinimize senin sahip çiktigin gibi çikamadik.

Affet bizi YA RESULULLAH,

Dinimize bizler dogru uymadik.

Affet bizi YA RESULULLAH,

Sana laik olamadik.

Affet bizi YA RESULULLAH,

Adina laf getirttik.

Affet bizi YA RESULULLAH,

Senin sünnetlerine uymadik.

Affet bizi YA RESULULLAH,

Okuma yazman olmadigi halde,

Bizler için gönderilen kuran-i kerim-i sen yazdin,

Biz kuran-i kerimimize sahip olamadik,

Okumadik,

Okutmadik.

Affet bizi YA RESULULLAH,

Cennette senin yanina laik degiliz.

Affet bizi YA RESULULLAH,

Biz müslümanligi kötüledik.

Affet bizi YA RESULULLAH,

Affet bizleri YA RESULULLAH.

Tarih Ve Saati: 25-02-2006	13:03', 'Affet bizi YA RESULULLAH, Dinimizi koruyamadik. Affet bizi YA RESULULLAH, Dinimize yeterince saygi duyamadik. Affet bizi YA RESULULLAH, Dini...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/resulullah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleme AGAM!', 'soyleme-agam-veysel-alkan-prz5i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel artık dertleri konuşmayalım.

Kalpleri virane eyleme AGAM! 

Acıyla yarışıp, boğuşmayalım.

Hüzünlü türküler söyleme AGAM! 

Umudun dökülsün tatlı dilinden. 

Bahsetme hasretten ya da ölümden.

Neşeyi ayırıp,çıkart maziden.

Hüzünlü türküler söyleme AGAM! 

Sevdiğin sevmemiş,sevmiş diğeri.

Sevmeyeni boşver,olmaz değeri.

Sızlatıp içimi,yakma ciğeri.

Hüzünlü türküler söyleme AGAM! 

Dayanmaz yüreğim,daralıverir.

Sen gibi dertlere sarılıverir.

Durur mu gözlerim,sel alıverir.

Hüzünlü türküler söyleme AGAM! 

Ne yalan söyleyim,senden beterim.

Kafayı takarım,isyan ederim.

Ya aklı sıyırır,ya da giderim.

Hüzünlü türküler söyleme AGAM! 

Sevmeyip yürekten böyle bir daha.

Unutup silelim, can gidecek ha..

Dönelim yeniden yüce ALLAH''a.

Hüzünlü türküler söyleme AGAM!', 'Gel artık dertleri konuşmayalım. Kalpleri virane eyleme AGAM!  Acıyla yarışıp, boğuşmayalım. Hüzünlü türküler söyleme AGAM!  Umudun dökülsün...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soyleme-agam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azık', 'azik-zeynal-yaman-9tx10', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşktan daha âla azık bulunmaz seyyaha

