INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevdadır Yaşamak', 'bir-sevdadir-yasamak-serap-tepedelen-8wtlz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sevdadır yaşamak,

Bir güzel gülümseyiş

Bir güzel bakış

Bir dolu yürektir yaşamak.

Saniye saniye,dakika dakika yudumlamaktır geçen anı

Her anın ortasında yeşeren bir filiz,

Bir büyüyen başak,

Bir sürülen tarla,

Berekettir toprak,

Berekettir yaşamak.

Kısır döngülerden uzak

Dingin bir deniz,

Bir balıkçı oltası,

Çığlık çığlığa bir martı,

Yakamozlar,güneşin denizle oynaşması

Bir sevdadır yaşamak

Her yaşanan günün ardından

Merhabayla karşılamak doğan günü

(Haziran2005-Bursa)', 'Bir sevdadır yaşamak, Bir güzel gülümseyiş Bir güzel bakış Bir dolu yürektir yaşamak. Saniye saniye,dakika dakika yudumlamaktır geçen anı He...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-sevdadir-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmak', 'sanmak-gulden-isik-lf6mt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sanmak,geçmişin  içinden körce

geleceğe karanlık  bakmak.

sanmak,acıttığını yok sayarak

taş atan ellere ekmek atmak.

sanmak,avuntuyu  geçer akçe  yapıp

ömür sayfasından bir bir koparılmak.

sanmak,hayaller denizinde  susuz kalıp

sönmüş volkanda kor ateş gibi yanmak.

sanmak,çıkmaz sokakta kör ebe oyunuyla

şeytan  ininde sevgiyi  aramak

sanmak,kanmak.........

Sonradan düzenlediğim hali..', 'sanmak,geçmişin  içinden körce geleceğe karanlık  bakmak. sanmak,acıttığını yok sayarak taş atan ellere ekmek atmak. sanmak,avuntuyu  geçer ...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızı', 'askimizi-aynur-avci-6brg1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beş çizginin üstüne

Notalarda sana

Aşkımı yazdım

Anlattım ne kadar sevdiğimi

Sözler beste oldu

Dillerde doladı durdu

Mavi gözlerinde noktalandı

Cesaretin varsa

Kaldır başını,bak gözlerime

Ne kadar sevdiğimi oku

Cesaretin varsa aşka

Sende yaz yüreğİne

Sende bestele

Aşkımızı   aşkımızı....

Aynur AVCI

www.radyomorfm.com', 'Beş çizginin üstüne Notalarda sana Aşkımı yazdım Anlattım ne kadar sevdiğimi Sözler beste oldu Dillerde doladı durdu Mavi gözlerinde noktala...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askimizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ray-Ban', 'ray-ban-reyhan-tataroglu-cpmzb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'güneşe bakamayan

                               bir çift gözdük

                               velhasıl... 

                               güneşe takıldı gözlük', 'güneşe bakamayan                                bir çift gözdük                                velhasıl...                                 g...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ray-ban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serap (2)', 'serap-2-yasar-akbas-dzarw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Serap olan sevdaya,gözyaşı döküyorsan

Ara, sıra hislenip, hislenip yanıyorsan

Sende beni düşünüp, düşünüp yanıyorsan

Serap doğsa da sevda,bırak öylece kalsın

Biz sevgiye aşığız, o aşk öyle yaşasın

Kalbin saf,huyun güzel,mutluluğa layıksın

Sade neşeye deyil,herşeylere layıksın

Dilerim ömür boyu,tat alarak yaşarsın

Kaderimiş o sevda, ateşlere atsada

Bahtımızmış ayrılık,ah ettikce yaksa da

Serap olan sevdamız,,sıkıntı veriyor sa? 

Huzurunu kaçırıp,hüzüne sokuyor sa

Geceleri uykusuz,uykusuz koyuyor sa

İster unut,hatırla,istersen çöplüğe at

O ölümsüz sevdayı vicdanında bir kez tart

Sana bir şey diyemem, şikayetim bahtıma

Benim üzüntüm sade,''serap'' olan aşkıma

En ufak bir derdim yok,ne senle ne şahşınla

Yalnız gönül tahtıma,başkasını çıkarma

İçimizde yaşasın,yaşasın solan sevda', 'Serap olan sevdaya,gözyaşı döküyorsan Ara, sıra hislenip, hislenip yanıyorsan Sende beni düşünüp, düşünüp yanıyorsan Serap doğsa da sevda,bı...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akbaş']::text[], 8.5, '{"poet":"Yaşar Akbaş","poet_slug":"yasar-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/serap-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum/N/iyet', 'masum-n-iyet-reyhan-tataroglu-d9gpe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '......................

                               gözüm düşmez

                               o kadar yükseklere

                               hasret kaldım

                               oynadığımız  sekseklere...', '......................                                gözüm düşmez                                o kadar yükseklere                        ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/masum-n-iyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla', 'damla-mehmet-kesen-ckdsx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her şey geçer 

                      cümlesiz kalırım demişsin ya...

boynum büküldü

eğildim

bir damla yaş süzüldü

sade ve sadece seyrettim

imlasız kaldım buralarda

söze su değdi

yalın bir iz bıraktı sükut

durduramadım 

sade seyrettim

neydi soluklarımı sıklaştıran

zaman sırtındaki bu talan

neydi çığlığımdaki duman

geceden gelen bir ses desem

olmayacak

sesi izlesem

bıraksam saçlarıma rüzgarı

durmayacak

ah teselli aradığım

bağlandığım

neydi bu yarattığım

sesin sesime karışmayalı 

            uzun mu oldu dersin

oysa dün öpüştüm geceyle

sessizliğinle

izinin içindeki cümleyle

zehir içtim sen uğruna

saydım yirmi dört tane

boğazım yandı

yaşım kadarını anımsattı

bitti tütün

bitti yaş

kurudum yavaş yavaş

kan düştü yüreğime

yirmi dörtten dedim

evet dertten dedim

yani saatten dedim

sabır diye

seni besledim

sarıldım aşka

uyku tutmadı yüreğim

dinmedi içimin sızıntısı

düşmedi bitesi gece

ah o bitesi gece

düşüremedim narı gözlerimden

dondum

savruldu anılarım

sığındım küllerin gölgesine

sade ve sadece

belki düşersin diye…

(yare yazılanlar/24)     2005', 'her şey geçer                        cümlesiz kalırım demişsin ya... boynum büküldü eğildim bir damla yaş süzüldü sade ve sadece seyrettim i...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kesen']::text[], 8.5, '{"poet":"Mehmet Kesen","poet_slug":"mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/damla-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O zaman gel', 'o-zaman-gel-baki-sulopasa-r3bke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşimi örtme bulut kardeş,

Şunun şurasında...

Üç kuruşluk zevkimiz var! 

Onu da sen kaçırtma.

Ekvatora atlarsam...

Hoop diye; 

O zaman gel,

Bana gölge et.

Başımın üstünde yerin var.', 'Güneşimi örtme bulut kardeş, Şunun şurasında... Üç kuruşluk zevkimiz var!  Onu da sen kaçırtma. Ekvatora atlarsam... Hoop diye;  O zaman gel...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/o-zaman-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım', 'aglarim-fatih-demir-gveo9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin sevdanla yanar ağlarım

Söyle! bu acıya nasıl dayanırım

Sensiz hayatta ben ne yaparım

Ayrıldığıma değil; kaderime Ağlarım

Anladım ki sevmek hep hataymış

Sevenler bağlanmakla yalnış yapmış 

Sevda güneşim doğmadan batmış

Ayrıldığıma değil; karanlık dünyama Ağlarım

Aklım diyor ki unut onu gitsin 

Bu yalan sevda burada bitsin

Bırak! yaralı kalbim başkasını sevsin

Ayrıldığıma değil; unutulduğuma Ağlarım...', 'Senin sevdanla yanar ağlarım Söyle! bu acıya nasıl dayanırım Sensiz hayatta ben ne yaparım Ayrıldığıma değil; kaderime Ağlarım Anladım ki se...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglarim-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradığım Günler', 'aradigim-gunler-fatih-mehmet-karaca-a3r9a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çırpınıyorum denize düşen yılana sarılır misali

      Bir dost arıyorum derdimi dinleyecek sabırla

      Nerede o eski arkadaşlarım bulamıyorum bir türlü

      Hani nerede nerede o eski günler arıyorum durmadan

    

    

      Bakmakla doyamadığım masmavi gökyüzü yok

      Dinlemeye doyamadığım o eski namelerden eser yok

      Koşardım doya doya şu köşe senin bu köşe benim artık yok

      Bir ben varım cismimle duruyorum köşemde yalnız yapayalnız

    

    

    

      Düşünüyorum bu yaşıma kadar geçen zamanı

      Kimler gelmiş kimler geçmiş neler neler yaşanmış

      Karageyik yaşın otuzyedi yıl onbeş gün olmuş

      Aradığın günler çocukluğundaki günlermiş

                                              25.02.2006 Aktepe Kasabası/Hassa/Hatay', 'Çırpınıyorum denize düşen yılana sarılır misali       Bir dost arıyorum derdimi dinleyecek sabırla       Nerede o eski arkadaşlarım bulamıyo...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aradigim-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bekliyor Yalnız Ve Çok Ölmek', 'beni-bekliyor-yalniz-ve-cok-olmek-babur-pinar-gpiup', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kanayan benim

Göğsünde sonbahar yaprakları hışırdayarak 

kuru bir şehvetin armağanı önünde

diz çöküp başeğen sokak

Ağlayan senin seçimin 

çünki yarım kalmış aşk

kara ırmağın düştüğü derinde

saklıyor kanlı bitişini

Sen hiçbir leke görmedin 

Duvara asılı resim gibi

sustun hep önüne bakarak

Sokaktaki  eşkıya ayazın 

iğdiş edilmiş boğa gibi böğürerek 

sırtında erkek yorgunluğu 

akşamın koynuna sokarken tutkunluğu

evlerin sekiz şiddetinde çatırdamasını

görmediğini bir kenara bırak

Kahpe avazın 

gül bahçelerini gündüz vakti

tarumar etmesini de görmedin

O kadar gömülmüştün ki ağır batağa

başkasının acısı masaldı senin için

görmezden geldin

körpe kentlerin puşt bir yalnızlığa

geceleri bedelsiz terk edilişini

Mevsim kış vakit ikindi

son kalan Ferhat dağlarda mahzun şimdi

Kanayan benim evet

Yüreğinin gölgesine sığınarak

teslim olup arsız gülüşlere ilelebet

bağırsaklarındaki ağrıyı boşaltan sokak

Öğüren senin seçimin

Oynak bir kalçanın tüm becerisini göstererek bulut

sürükleniyor dokunsan ağlayacak gibi rüzgarın önünde

Sen affedilmeyi unut

Gün ortası sensiz sevişiyor sokak

Suçların en büyüğü

kentin ırzına leke süren

bir sokak eşkıyasının peşinde 

oyunsuz kalmış çocuk gibi ağlamak

Bütün kentleri sorgudan geçirip

Ateşin söndüğü gün yatağına

şair bozması şövalyelerin girip

sabahı öylesine masum bir fotoğrafla

nasıl karşıladığını öğrenmeliğim

Yoksa ihanet seni de yoklayacak

Ve sen yalnızlığın suretini unuttuğun an

ben tanık olacağım yeni bir serüvenin

ansızın kanadımı kırdığına

Eksik zamanlı hücrelere

sorgu sonrası bıraktığım direncin resmi

vahşetin dişlerine astı gömleğimi

Çılgınlar partisini yeni savmış bir gece

kendi içinde eriyen çığlık

kül hayatı sarsarken 

ağaçların dayanıklı olması kimin umurunda

Kaç harfe yükler bedelini ölmek

kimliğin anlamı ne

Bu kent kum çakıl çimento çelik yer

soluğu karbondioksit

kucağında büyük yalnızlığı besler 

bir avuç gökyüzü ile avutur insanları sürgit

Kanayan benim 

Çoğalan düşlerin dağıtıldığı dem

suyunu toprağa vermekten sakınarak

acıyı büyüten sokak

Ardında hiçbir şey bırakmadan giden 

senin seçimin

Her insan kendi fecrinde sorgulanmalı

ve dokunulmaz bir şey bırakılmamalı mahşere

Olasıdır belki yeniden dönerim kente

yanıma alarak eski yaralarımın uğultusunu

dostların kapısını çalarım yine 

Kitap arasında verdiğin gülkurusu

incitiyor yüreğimi hala

durup dururken söner mi kasırga

Ve bir kıyıda kaldıysa

her derde devadır kusursuz sevişebilmek

Evimin önünde ve her an pusuda

yazgısı sahibine bağlı bir hayvan gibi

bekliyor beni yalnız ve çok ölmek

Kanayan benim çünki', 'Kanayan benim Göğsünde sonbahar yaprakları hışırdayarak  kuru bir şehvetin armağanı önünde diz çöküp başeğen sokak Ağlayan senin seçimin  çü...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/beni-bekliyor-yalniz-ve-cok-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BEKLeMEK', 'beklemek-levent-i-skenderoglu-o3xk7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklemek çare değil

Kırık bacaklı kargalar

Geri dönmüyor

Ne intihar sebebi 

Ne kokuşan nefesler

Ne ballı kaymak 

Ne de sen 

Hiçbiri 

Menekşeler kadar

Özlenmiyor', 'Beklemek çare değil Kırık bacaklı kargalar Geri dönmüyor Ne intihar sebebi  Ne kokuşan nefesler Ne ballı kaymak  Ne de sen  Hiçbiri  Menekşe...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beklemek-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-yasar-akbas-1saur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasretin bitmek üzre,''vuslat'' vakti yaklaştı

Gecenin kör alevi,tan vaktine yaklaştı

Vakit  tiren gibi, kalkmak üzre heran

Ne varsa eşyasını,bir bir topluyor zaman

Tan vaktini bülbül de beklermiş gülü için

Fakat umut bitince,ağlarmış için,için

O gülün açılması  servetmiş bülbül için

Gülsende bir tek çiçek aranır neden, niçin

Yürekte ki sevdalar yar için,yaren için

Çok''un sevgisi olmaz, sevdalar ''bir'' ler için

Kapalı duran kucak,sevği için açılır

Hele ''vuslat''  varı sa o aşk orda taçlanır

Gözden inci dökülür,mırıldanır dudaklar

Dua ile niyazla,artık söker şafaklar

Gayrı açılsın yollar,mani olmasın dağlar

Saçılsınlar yollara,laleler ve zambaklar

Akbaş veda vuslattır,anlıyana,bilene

Rabbim ömür verirse,gönderdigi kimseye

                                         19.05.2002', 'Hasretin bitmek üzre,''vuslat'' vakti yaklaştı Gecenin kör alevi,tan vaktine yaklaştı Vakit  tiren gibi, kalkmak üzre heran Ne varsa eşyasını,...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akbaş']::text[], 8.5, '{"poet":"Yaşar Akbaş","poet_slug":"yasar-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/vuslat-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi İsyanın Rengi', 'mavi-i-syanin-rengi-sair-mahir-xal1g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Asidir yüreğim

Rengim Mavi

Bilirsin

Mavi isyanın rengi

O yüzden köpürür deniz

Döver kıyıları

O yüzden gökyüzü asidir,

Mavidir

Değişir huyları

Ve ondandır

Nehirlerin alıp başını gitmesi

Asidir yüreğin

Gözlerin Mavi

Bilirim

Mavi isyanın rengi...', 'Asidir yüreğim Rengim Mavi Bilirsin Mavi isyanın rengi O yüzden köpürür deniz Döver kıyıları O yüzden gökyüzü asidir, Mavidir Değişir huylar...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahir']::text[], 8.5, '{"poet":"Şair Mahir","poet_slug":"sair-mahir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mavi-isyanin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa söz 16', 'kisa-soz-16-hacer-ongor-bgxkj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duyguları söze dökmek zor,

O iki kelimeyi söylemek daha da zor,

Zorda olsa işte ilan ediyorum

Seni Seviyorum.

1998', 'Duyguları söze dökmek zor, O iki kelimeyi söylemek daha da zor, Zorda olsa işte ilan ediyorum Seni Seviyorum. 1998...', ARRAY['Türk Edebiyatı','Şiir','Hacer Öngör']::text[], 8.5, '{"poet":"Hacer Öngör","poet_slug":"hacer-ongor","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kisa-soz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Pırıltı', 'o-pirilti-muammer-erturan-ws9ao', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karamsarlığa kapıldığım

olmuyor değil,

şu sefil gidişata

bakıp bakıp da...

Takılana dek gözlerim

gözlerinde bir çocuğun 

o pırıltıya ta ki...

O pırıltı ki,

ne umutlar saklı

adı konmadık,

yakası açılmadık 

ne mutlar

derinliklerinde...

Bu sırra erdikçe işte

gözlerinde gözlerim,

aydınlanıyor içim gene...

O pırıltı iyi ki var...

İyi ki de derinlerinde saklı

o mutlar ve umutlar...

Şimdiye kadar yoksa

ne ad kalmıştı konmadık(!) 

ne açılmadık yaka; 

okunmuştu çarkına alayının

çoktaaan...

O pırıltı iyi ki var...

Yaşasın çocuklar! ..

(''0 Eylül ''99)', 'Karamsarlığa kapıldığım olmuyor değil, şu sefil gidişata bakıp bakıp da... Takılana dek gözlerim gözlerinde bir çocuğun  o pırıltıya ta ki.....', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/o-pirilti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa söz 17', 'kisa-soz-17-hacer-ongor-bvl1e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değişmem bir şeye o yumak saçlarını,

Herşeyimi alsalar da elimden.

Değişmem bir şeye o bulut bakışlarını,

Gözlerimi oysalar da yerinden.

27/03/99', 'Değişmem bir şeye o yumak saçlarını, Herşeyimi alsalar da elimden. Değişmem bir şeye o bulut bakışlarını, Gözlerimi oysalar da yerinden. 27/...', ARRAY['Türk Edebiyatı','Şiir','Hacer Öngör']::text[], 8.5, '{"poet":"Hacer Öngör","poet_slug":"hacer-ongor","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kisa-soz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuğla Harmanı kaçkınları', 'tugla-harmani-kackinlari-baki-sulopasa-ymlx9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mısraların afacan çocukları,

Ağzı süt kokan bebekler.

Sizlerle oynaşırken,

Kaçar göçer sözcükler.

Tuğla harmanı kaçkınları...

Size; usta bir usta gerek! 

Duvarınız örmeye.

Güçlü bir çimento,

Bir de paslanmaz çelikten mala,

Şakülü olsa da...

Aşılmaz, puslu zirvelerden; 

Leylak,  karanfil, fulya; 

Ama ille de güller esmeli,

Duvarında çiçek açmaya...

Gonca gonca,

Demet demet,

Başında tutmaya taçlar gibi.', 'Mısraların afacan çocukları, Ağzı süt kokan bebekler. Sizlerle oynaşırken, Kaçar göçer sözcükler. Tuğla harmanı kaçkınları... Size; usta bir...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tugla-harmani-kackinlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprakla dalın ayrılışı', 'yaprakla-dalin-ayrilisi-hacer-ongor-odcc1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgar savurur sonbahar yaprağını

Yaprak yarinden zorla ayırılır.

Gövdesi der ki kırın dalımı,

Yarim olmadıkça bu dal kime bağlanır.

Dokunaklı sözleriyle zavallıcığın,

Öfkeli rüzgar lodos olur birden.

Önemli bir parçası kopmuş hayatından ağacın,

Yaşasa ne, yaşamasa ne olur bu beden.

Bağırdıkça lodosa yüreği parçalanır,

Kara lodostan ses yok bu aşka.

Son çare açar avuçlarını göklere yalvarır,

Sığınacak kimsesi yok çünkü Allahtan başka.

Verin der yarimi, geri getirin.

Sarartmayın, soldurmayın yeşil gözlerini.

Ben o olmazsa kimden güç alırım

Bir damla göz yaşı akarsa affetmem sizleri.

Bahardan bahara kavuşturmayın,

Her sonbahar olduğu gibi ayırmayın bizleri.

Ben onsuz ne yaparım, nasıl yaşarım

Ne olur, ya onu getirin bana, ya da alın ruhumla beraber bu bedenimi.

28/03/1999', 'Rüzgar savurur sonbahar yaprağını Yaprak yarinden zorla ayırılır. Gövdesi der ki kırın dalımı, Yarim olmadıkça bu dal kime bağlanır. Dokunak...', ARRAY['Türk Edebiyatı','Şiir','Hacer Öngör']::text[], 8.5, '{"poet":"Hacer Öngör","poet_slug":"hacer-ongor","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yaprakla-dalin-ayrilisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başınalığım', 'bir-basinaligim-sair-mahir-41flf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir başınalığımda soğur yüreğim

Gözlerim donuk bakar pencerelerden

Efkarlanırım, duman altı olur odam

Parmaklarım tütün kokar

Dinlediğim şarkı çarpar

İçtiğim rakının üstüne

Ağlamaya neden çok

Yaslanacak omuz bulamam

Duvarlara ağlarım

Bir başınalığımda acılanırım

Yorulur beden

Uykudan medet arar

Düşlere sığınırım...', 'Bir başınalığımda soğur yüreğim Gözlerim donuk bakar pencerelerden Efkarlanırım, duman altı olur odam Parmaklarım tütün kokar Dinlediğim şar...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahir']::text[], 8.5, '{"poet":"Şair Mahir","poet_slug":"sair-mahir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-basinaligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayan Her Şey Gibi..!', 'olmayan-her-sey-gibi-hulya-topcuoglu-r2b0n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olmayan hayatlarımız vardı, özlediğimiz

Ama asla bizim olmayan 

Ümit halatlarına tutunup

Olacağını düşünerek yaşadığımız 

İğreti hayatlardı bizi kandıran

Olmayan dostlar edindik, dost sanarak

Hüsran oldu sonu, bel bağladığımız dostluklarımızın

Varmış gibi yaptık, onlara dayandık

Birde baktık ki, uçurumların kenarında yapayalnız kaldık

Olmayan aşklarımız oldu, bize ait olmayan

Gözyaşı döktük, gecelerce kıvrandık 

Bizim sandık

Yaşıyoruz sandık 

Olmayan aşklar acıttı yüreğimizi, aldandık 

,

Olmayan bir dünyamız vardı 

Her acının dineceğine inandığımız 

Yılmadan günlerce, gecelerce bekledik 

Dinmedi acılar,

Bitmedi yalnızlıklar 

Yine olmayan herşeyde olduğu gibi, kendi dünyamızda da yanıldık..', 'Olmayan hayatlarımız vardı, özlediğimiz Ama asla bizim olmayan  Ümit halatlarına tutunup Olacağını düşünerek yaşadığımız  İğreti hayatlardı ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olmayan-her-sey-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardındaki Karanlık', 'ardindaki-karanlik-sair-mahir-z08y6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tan sabahında

Üzerime doğrulmuş namluydun

Tetiği çektin vurdun

Titremedi hiç ellerin

Merhametten yoksundun

Beni bırakıp ardında

Sislerin içinde kayboldun

Öyle bir karanlık bıraktın ki ardında

Yüzlerce mum yaktım aydınlanamadım

Görmesende

Gözlerim bulutlardan daha dolu

Kayboldu gökyüzümden ay ışıklarım

Gökyüzümü mü çaldın? 

Peki ya yıldızlarım? 

Sen hangi cehennemdesin? 

Nerdesin? 

Başa çıkamıyorum bu karanlıkla

Acı ama hala umudum sensin...', 'Bir tan sabahında Üzerime doğrulmuş namluydun Tetiği çektin vurdun Titremedi hiç ellerin Merhametten yoksundun Beni bırakıp ardında Sislerin...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahir']::text[], 8.5, '{"poet":"Şair Mahir","poet_slug":"sair-mahir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ardindaki-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Gelir Elden', 'ne-gelir-elden-nuri-celik-smekk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Farkım yoktu benim,sensiz ölüden

Vurulmuştum sana yıllar önceden

Yaş akmamışsa da,o gün gözümden

Kader böyle yazmış,ne gelir elden

İstermiydi gönlüm ayrı kalmayı

İstermiydi böyle acı duymayı

Yalnız hayallerle mutlu olmayı

Kader böyle yazmış ne gelir elden

Geçsede aradan şu kadar sene

İmkanım olsada dönsem o güne

Severdim ben seni inan ki yine

Kader böyle yazmış ne gelir elden

                 3şubat1991/pazar', 'Farkım yoktu benim,sensiz ölüden Vurulmuştum sana yıllar önceden Yaş akmamışsa da,o gün gözümden Kader böyle yazmış,ne gelir elden İstermiyd...', ARRAY['Türk Edebiyatı','Şiir','Nuri Çelik']::text[], 8.5, '{"poet":"Nuri Çelik","poet_slug":"nuri-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-gelir-elden-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askim', 'askim-ulya-erkman-z18eq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ismi sanki muhurlenmis 

Dusuncelerime

Sade o ve ben variz gibi

Bu alemde

Yalniz gidemiyorum

Bir yerlere

Sevgilim hep benimle beraber

Hayallerimde

Bir gun gormesem nefes

Alamiyor gibiyim

Ruyalarim onsuz olamiyor hep

Yanimda sevgilim

Aski yasatir beni susadigim su gibi

Kana kana icerim

Sevgim tasar akar ona dogru cosunca

Bir volkan gibi hislerim

Bir derenin yolculugu gibi uzun mudur

Askimin yolu? 

Yoksa atlamalimiyim bir mania 

Gelmesin diye bu askin sonu? 

Urperirim dusununce ya 

Kaybedersem diye onu

Sonerim ben de sonerse eger 

Bu askin sonsuzlugu', 'Ismi sanki muhurlenmis  Dusuncelerime Sade o ve ben variz gibi Bu alemde Yalniz gidemiyorum Bir yerlere Sevgilim hep benimle beraber Hayalle...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askim-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım Baba', 'yalnizim-baba-nuri-celik-2a87t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O anı yazamam elim tutmuyor

Gözlerimden hala yaşlar akıyor

Eller bana öksüz diye bakıyor

Birde yetim kaldım,yalnızım baba...

                  

                          26şubat2006', 'O anı yazamam elim tutmuyor Gözlerimden hala yaşlar akıyor Eller bana öksüz diye bakıyor Birde yetim kaldım,yalnızım baba...                ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Çelik']::text[], 8.5, '{"poet":"Nuri Çelik","poet_slug":"nuri-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalnizim-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay Güzeli', 'cay-guzeli-soner-oruc-qucce', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimde adresim var bir türlü gidemediğim,

Telefonda sesin var yüzün göremediğim.

Beni sevip sevmediğini bilemediğim,

Biri var ki biri adı Çay Güzeli.

İsmi gibi kendi bir dünya güzeli,

Ezelden gelmiştir gider ebedi.

Nice sevenleri yakıp kül eyledi,

Yanmaya değer Karadeniz Güzeli...', 'Elimde adresim var bir türlü gidemediğim, Telefonda sesin var yüzün göremediğim. Beni sevip sevmediğini bilemediğim, Biri var ki biri adı Ça...', ARRAY['Türk Edebiyatı','Şiir','Soner Oruç']::text[], 8.5, '{"poet":"Soner Oruç","poet_slug":"soner-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cay-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durak', 'durak-aylin-onder-kj7xz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duraklarıdan biriydi 

Sevdanın adının kazılı olduğu

Çoğu kahramanının isimlerini bile

Okunamaz hale getirmişti zaman

Yazların hatırası belli viran halinden

Ne aşıklar geçmiş gölgesinden 

Ne kavgalara,vedalara sahne olmuş

Binlerce kavuşmalara perde açmış

Kapalı gişe oynamış zamanında

Unutulmuş

Aşıkları ayrılınca

Belki de devre yenik düşmüş kahraman...

Duraklarıdan biriydi 

Sevdanın adının kazılı olduğu

Çoğu kahramanının isimlerini bile

Okunamaz hale getirmişti zaman...

Demirin gövdesi ne kadar sıcak olabilecekse

O kadar sıcağı görmüş 

Donma noktasının sonrasında da 

Dimdik ayaktaydı.

Ne olmuştu o aşıklara 

Zaman bu kadar acımasız nasıl olmuştu ki

Ortada ne sevda,ne durak kalmıştı....', 'Duraklarıdan biriydi  Sevdanın adının kazılı olduğu Çoğu kahramanının isimlerini bile Okunamaz hale getirmişti zaman Yazların hatırası belli...', ARRAY['Türk Edebiyatı','Şiir','Aylin Önder']::text[], 8.5, '{"poet":"Aylin Önder","poet_slug":"aylin-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/durak-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haklısın Che', 'haklisin-che-muammer-erturan-2qw57', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu denli iğrenç olmazdı,

olamazdı dünya,

Che yaşıyor olsa...

Laf işte...

Che ölmüş de sanki...

O denli yaşamaktaki hem...

O denli içindeki yaşamın...

O denli içimizde ki...

Nerde bir zulüm,

bir sömürü,

bir yobaz sultası varsa

karşısında,

O...

Nerde bir ezilen insan.

bir haklı isyan,

bir yürüyüş varsa ileri

yanında,

O...

Bu denli iğrenç olmazdı,

olamazdı dünya,

Che yaşıyor olsa...

Laf işte...

Che ölmüş de sanki...

O denli dipdiri ki hem...

O denli güçlü ki...

O denli gür ki sesi

her an,

her yere ulaşmakta... 

Ve işte kulağımda,

ve beynimde

ve yüreğimde

yankılanmakta şu an:

Hadi ordan çocuk! 

Hadi ordan...

İğrenç olan emperyalizm 

ve uşakları...

Sömürüyü ve savaşı 

ortadan kaldır,

bak bakalım ne hâl alır dünya! ..

Haklısın Che! ..

Haklısın gene...

Hele ki yaşatmamak seni

kimin haddine...

(20 Mart ''01)', 'Bu denli iğrenç olmazdı, olamazdı dünya, Che yaşıyor olsa... Laf işte... Che ölmüş de sanki... O denli yaşamaktaki hem... O denli içindeki y...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/haklisin-che-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sensizde Mutluyum', 'ben-sensizde-mutluyum-i-rfan-bilir-5cx6b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana verdiğim değeri hiç bilemedin

kaç kez arşınladım ben yollarını

yalan dünya için bir pula sattın

hem beni,kendini hem sevgimizi

demiştinki sen bensiz yaşayamazsın

bak sensizde atıyor hala yürek

Karanlık bir çukurdan kurtardım seni

sevgim ekmek oldu yüreğim katık

bozdun düzenimizi yıktın kaleyi

kendini bedbaht ettin benide rezil

sandınki sensiz gülemez yüzüm

bak sen olmasanda mutluyum artık

demekki dostluk değil çıkar aradın

yıllarca yüzüme yalancı güldün

sevgimi kullandın paçavra gibi

nereye kadar bu gidiş sanıyorsun sen

sensiz boynum bükük kalır sanmıştın

hayal bile edemezsin mutluluğumu

bugün ben yarın o nereye kadar

birgün pes edeceksin yaptıklarına

dostların sevenlerin hiç kalmayacak

ölmeden kıyametin kopacak inan

giderken bana ölür demiştin

sen öldün benim için,ben yaşıyorum..

irfan bilir

26.şubat.2006

saat:20.50', 'Sana verdiğim değeri hiç bilemedin kaç kez arşınladım ben yollarını yalan dünya için bir pula sattın hem beni,kendini hem sevgimizi demiştin...', ARRAY['Türk Edebiyatı','Şiir','İrfan Bilir']::text[], 8.5, '{"poet":"İrfan Bilir","poet_slug":"i-rfan-bilir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ben-sensizde-mutluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerkük', 'kerkuk-husam-hasret-h8vj7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özgürlüğü bir güne

Bağlayıp beklemişim

Her Türkmen sözcüğüne

Bir Kerkük eklemişim

Kaldırınca yükünü

Güçlendirdim kökünü

Türkmen''inin Kerkük''ünü

Sırtıma yüklemişim

Kalınca da dışında

Katılaştım işinde

Hür yaşamak peşinde

Neler dileklemişim', 'Özgürlüğü bir güne Bağlayıp beklemişim Her Türkmen sözcüğüne Bir Kerkük eklemişim Kaldırınca yükünü Güçlendirdim kökünü Türkmen''inin Kerkük''...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kerkuk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orada öcü var', 'orada-ocu-var-baki-sulopasa-o82mx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim boynu bükük güzellerim.

Sakın sokak mokak demeyin,

Orada öcü var! 

Bakarsınız kaçırıp, dilenci yaparlar.

En iyisi; 

Dizimin dibine oturun.

Okşayıp severken,

Bir de bakmışsınız, sizi boyuyorum.

Hatta saçlarınıza kına yakarken; 

Göz yaşlarımdan ıslanırsınız.

Zamanı gelince...

Kaçırmaları iyi olur isterseniz.

Üstelik, bir teselli de uydururum:

Benden daha çok sevdikleri için; 

Öyle olmalıydı.Diyerek.

Oysa; Bütün nehirler,

Denizlere kavuşmaz mı sonunda?', 'Benim boynu bükük güzellerim. Sakın sokak mokak demeyin, Orada öcü var!  Bakarsınız kaçırıp, dilenci yaparlar. En iyisi;  Dizimin dibine otu...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/orada-ocu-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Ve Nur Yüzlü Bir Cennet ‘MEVA’ (MEVA-1)', 'gul-ve-nur-yuzlu-bir-cennet-meva-meva-1-i-brahim-nazim-ulker-60tcb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gece ansızın; 

Yine sekarat-ı mevtte gözlerimi açtım …

Sorular alışıla gelmiş değildi,

Ve hiçbir şeyde aynı değildi.

Bir sorgu meleği yoktu örneğin.

Sade bir melek vardı,

Bir cennet bahçesi de onda saklı.

Koşuyorum soluksuz,

Her çıkışında O karşıma,

Ben koştukça uzaklaşıyordu bana.

Ve İblis dikiliyordu aramıza; 

Sualleri de İblis soruyordu,

Binlerce vaatler, cennet bahçeleri, 

Fridevs’i karşılıksız veriyordu…

Ben halen koşuyordum aralıksız; 

İbrahim misali taşlarken İblis’i,

Kavuşmak için tek bir cennet bahçesine,

O kaçtıkça ben düşerken ateşine …

Ey İblis! çekil yolumdan,

Yıkıl git karşımdan,

Verdiklerin olsa da cennet-ülhan dan,

Ne fark eder Ey İblis! .

Ben yüce aşık,

Sense şeytan! 

Fridevs’ler, nehirler senin olsun,

Arkanda duran ‘MEVA’ yı verebiliyor musun? 

Bana bir ‘MEVA’,

Bir de içinde ki gül gerek…

Uzat ellerini ''MEVA'' artık yeter,

Sana yaklaşıyorum derken,

Anızın gidişlerin yeter,

Sende bir Cennet’sin sığınılacak yer.

Gül cemalini mahrum eyleme

Adın gibi, yüzün gibidir içinde,

Kabul eyle beni ‘MEVA’! 

Ateşinden, İblisinden,

Kurtar beni, şu rezillikten.

Kaçma artık uzat ellerini ‘Meva’! 

Beni böyle bırakma, bırakma! ...', 'Bir gece ansızın;  Yine sekarat-ı mevtte gözlerimi açtım … Sorular alışıla gelmiş değildi, Ve hiçbir şeyde aynı değildi. Bir sorgu meleği yo...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gul-ve-nur-yuzlu-bir-cennet-meva-meva-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Böyleyim', 'ben-boyleyim-husam-hasret-ks0sf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bire iki diyen üçü tanımam

Günahı işlemem, suçu tanımam

Güçsüz düşmanıma öcü tanımam

Ben böyleyim, böyle bilsin el beni

Tuz, ekmek bilirim emek yitirmem

Dostluk vapurunu suya batırmam

Lekesiz adıma leke getirmem

Ben böyleyim, böyle bilsin el beni

Kötülük huyuyla düşünüp dalmam

Terse oyunlarda davulu çalmam

Lokmayı yoksulun ağzından almam

Ben böyleyim, böyle bilsin el beni

Şerden iğrenipte hayırdan doymam

Lanet eşiğine başımı koymam

Her nasıl olursa kötüye uymam

Ben böyleyim, böyle bilsin el beni

Umut dolusuyum hiçte kocamam

Dışta yaşlansam da içte kocamam

Yararlı vaktimi boşa harcamam

Ben böyleyim, böyle bilsin el beni', 'Bire iki diyen üçü tanımam Günahı işlemem, suçu tanımam Güçsüz düşmanıma öcü tanımam Ben böyleyim, böyle bilsin el beni Tuz, ekmek bilirim e...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-boyleyim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-emrah-karakoc-thumt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırılan bir gurur yıkılan hayal

Senin eserindir senin vefasız

Hiç durma göbek at, hatta davul çal

Bu gün bayramındır senin vefasız

Gurbete düşürdün yolumu benim

Nasıl oldu inan bende bilmedim

Senin aşkın oldu benim afetim

Keşke sevmeseydim seni vefasız

Dostlar şimdi ''hani, nerde'' diyorlar

O düşürdü seni derde diyorlar

Bırakıp da gittiğini biliyorlar

Lal ettin dilimi benim vefasız

Yad oldun ellerle güldün halime 

Benzedin gönlümde gaddar, zalime

Tevazu gösterip garip gönlüme

Özür dilemedin hain vefasız

Sen bende bir hiçsin, bitirdim artık

Gönlümden çıkardım, kurtuldum artık

Yazık, seni seven yüreğe yazık

Sildim yüreğimden seni, vefasız', 'Kırılan bir gurur yıkılan hayal Senin eserindir senin vefasız Hiç durma göbek at, hatta davul çal Bu gün bayramındır senin vefasız Gurbete d...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vefasiz-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinir', 'bilinir-nuri-celik-xobct', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya imarını bırak bir yana

Konulacak her şey,o gün mizana

İyi şeyler ekki çıksın karşına

Misafiriz anla,alçak dünyada

Yükselmeyi ah,kolaymı sandın

Eşine,yavruna nasıl davrandın

Sahte olanlardan medet umardın

Kurtarırmı seni,Hakkın yanında

Düşünsene biraz yaptığın nedir

Senin aklın yoksa perdelimidir

Bin nasihattansa serencem yeğdir

Perdeler yırtılır bilinir her şey.

                   (Bir dosta atfen!)', 'Dünya imarını bırak bir yana Konulacak her şey,o gün mizana İyi şeyler ekki çıksın karşına Misafiriz anla,alçak dünyada Yükselmeyi ah,kolaym...', ARRAY['Türk Edebiyatı','Şiir','Nuri Çelik']::text[], 8.5, '{"poet":"Nuri Çelik","poet_slug":"nuri-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilinir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman', 'pisman-emrah-karakoc-ai6x3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni tanıdığım güne bin lanet

Okuyor durmadan dilim çok pişman

Senle toka yapmak büyük ihanet

Kabul etti şimdi elim çok pişman

Başka gidecek yer yokmuydu diye

Niçin geldin ora sen? söyle niye

Madem soruyorsun söyleyim kirve

Uğradığı için yolum bin pişman

Kaçıyorsun benden yad eller gibi

Aramıza girdi bir kara kedi

İkiside bana büyük söz verdi

Ağladığı için gözüm bin pişman

Düşürdün yolumu kış''a boran''a

Bana yaptıkların sana dolana

Şimdi bana diyorlar ki; ''budala''

Sana koştuğu''çin dizim bin pişman

Artık bakmayacak gözüm, gözüne

İnşallah karışmaz sözüm, sözüne

Sevgi duymaz oldu özüm, özüne

Sana güldüğüne yüzüm bin pişman

Karakoç''a oldun en büyük düşman', 'Seni tanıdığım güne bin lanet Okuyor durmadan dilim çok pişman Senle toka yapmak büyük ihanet Kabul etti şimdi elim çok pişman Başka gidecek...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/pisman-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dediler', 'dediler-husam-hasret-nqslh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dediler hoşlukla dost olma, sana yar olmaz

Olmasın, gam çilesiz yaşamın anlamı yok

Zamana güvenme hiç, o hiç yüzüne gülmez

Gülmesin, her damla göz yaşım kör gözüne ok

Dediler kötü kader kara bahtın ak etmez

Etmesin, başımdaki aklarla mutluyum ben

Hayata bel bağlama acı vermekten bitmez

Bitmesin, yeter ki bir güne umutluyum ben', 'Dediler hoşlukla dost olma, sana yar olmaz Olmasın, gam çilesiz yaşamın anlamı yok Zamana güvenme hiç, o hiç yüzüne gülmez Gülmesin, her dam...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dediler-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşlik Türküsü', 'kardeslik-turkusu-husam-hasret-x5z3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey güzel olsun çirkin dünyada

Paklaşıp kalmasın bir kin dünyada

Bütün insan kardeş gibi yaşasın

Kavuşupta bulsun tekin dünyada

Yalandan, öfkeden, kinden geçilsin

Sevgiye, dostluğa kucak açılsın

Beraberce dostlar helal yaşamın

Ekmeği yenilsin, suyu içilsin

Bağımız rengarenk güllerle dolsun

Gül koksu esince dikenler solsun

Ey dostlarım barış adlı yaşamda

Türkümüz kardeşlik türküsü olsun', 'Her şey güzel olsun çirkin dünyada Paklaşıp kalmasın bir kin dünyada Bütün insan kardeş gibi yaşasın Kavuşupta bulsun tekin dünyada Yalandan...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kardeslik-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden Bileceksin', 'nerden-bileceksin-sana-ozel-i21lq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sadece ona özel', 'sadece ona özel...', ARRAY['Türk Edebiyatı','Şiir','Sana Özel']::text[], 8.5, '{"poet":"Sana Özel","poet_slug":"sana-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/nerden-bileceksin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Gelir Bana', 'zor-gelir-bana-nuri-celik-stzxl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana ne deyipte çekip gidemem

İçim kan ağlarken,zaten gülemem

Hiç birşeyim yok ki,sana veremem

Yokluğu paylaşmak,zor gelir bana

Triplere girip ilgi çekemem

Yalanla,dümenle bir söz diyemem

Nefsimin uğruna başım eğemem

O''dost gibi olmak,ters gelir bana

Anlıyorsan yeter,düzelt halini

Hak edene ver, yüce sevgini

Bir pas pas misali,serme kendini

Şerefsize yanman zor gelir bana

Dünya fanidir bunu bilirim

Kulların zulmüne güler geçerim

Bir ''kulum'' dese HAK,bayram ederim

Kula kulluk etmek,ters gelir bana.

       

                3temmuz2003', 'Bana ne deyipte çekip gidemem İçim kan ağlarken,zaten gülemem Hiç birşeyim yok ki,sana veremem Yokluğu paylaşmak,zor gelir bana Triplere gir...', ARRAY['Türk Edebiyatı','Şiir','Nuri Çelik']::text[], 8.5, '{"poet":"Nuri Çelik","poet_slug":"nuri-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zor-gelir-bana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hanci', 'hanci-ayse-alioglu-5sqt0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gariban bir kulum düstüm yollara

Köyümden topragimdan 

cok uzaklarda

Bi care kalmisim ben bu yollarda

Sevgiden nasibimi alamadim daha

Gariptir adim yoktur mekanim

Ne bir yudum asim

Nede sicak yatagim

Nerde gecem ise orada sabahlarim

Acilarin cenberini cok iyi bilirim

Yanan atesin üzerinde yürürüm

Nasir tutmus ellerim 

Yorgun bedenim.

Ben bir garip yolcuyum 

Sen ise Hanci

Acilarima katacak

isen daha cok aci

Kapat kapilarini kapat

Yüzüme karsi 

Yoluma cikma ne olur 

Cikma be Hanci

Sevgiden yana bahtim acilir mi? 

Bu kollar sevgiyle kucaklasir mi? 

Göz yasi kuruyup güller acar mi? 

Ne olur söyle söyle be hanci

Eger sen hanci isen 

Ben garip yolcu

Acilarima kalacak 

Isen daha cok aci

Kapat kapilarini kapat

Yüzüme karsi

Yoluma cikma ne olur cikma

Be Hanci

Acilar cenberine atma 

Be Hanci.................... Ayse Alioglu 26.02.06', 'Gariban bir kulum düstüm yollara Köyümden topragimdan  cok uzaklarda Bi care kalmisim ben bu yollarda Sevgiden nasibimi alamadim daha Gaript...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Alioğlu']::text[], 8.5, '{"poet":"Ayşe Alioğlu","poet_slug":"ayse-alioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hanci-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa Bir Kala', 'ayriliga-bir-kala-said-ertugrul-isik-b6o14', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece hüzün gibi çöktü içime

Karanlık fısıldadı ayrılığı sen kokan yüreğime

Ayrılmaya bir kala kömür gözlümden

Gecenin karanlığında yüreğimi gömdüm yıldızlara.

Denizin rengi mavi değil artık; kara 

Tekneler küsmüş denize uğramıyor limanıma

Vazgeçmeye bir kala kömür gözlümden

Yüreğimi gömdüm güneş battığında ıssız limana.

Hani hüzünlü bir şarkımız vardı ya

Yıldızlara bakarak ağlamaklı gözlerle söylediğimiz

Şimdi hep o şarkıyı söylüyorum kendi kendime

Ve sensizliğe bir kala ruhumu gömüyorum kömür gözlerine.', 'Gece hüzün gibi çöktü içime Karanlık fısıldadı ayrılığı sen kokan yüreğime Ayrılmaya bir kala kömür gözlümden Gecenin karanlığında yüreğimi ...', ARRAY['Türk Edebiyatı','Şiir','Said Ertuğrul Işık']::text[], 8.5, '{"poet":"Said Ertuğrul Işık","poet_slug":"said-ertugrul-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayriliga-bir-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılıksız Aşklar', 'karsiliksiz-asklar-huseyin-ozcan-dtrx0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'başlamadan biten sevdalar vardır hani,				

bitirilen…katledilen…boğulan sevdalar…				

hoyratça,acımasızca,vicdansızca harcanılan….				

tabiri caizse doğmadan öldürülen,

ana rahmindeki bebek gibi,		

kürtaja tabi tutulan sevdalar….				

yaşama hakkı olmasına rağmen 				

hayatına  kastedilen aşklar…..

					

senin ektiğin, senin sulayıp senin büyüttüğün,				

filizlenen ama bir türlü çiçek açmayan sevdalar…			

büyüyen,büyüdükçe			

sarmaşık gibi kaplayıp heryanını,				

sonra seni de mahveden aşklar….				

tıpkı bir bumerang gibi,				

ne tarafa atsan tekrar sana dönen				

karşılıksız duygular…..', 'başlamadan biten sevdalar vardır hani,				 bitirilen…katledilen…boğulan sevdalar…				 hoyratça,acımasızca,vicdansızca harcanılan….				 tabir...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karsiliksiz-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabri', 'sabri-omer-ziya-soyyigit-rn6cu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulmuş seni gönül kendine yek dost

Tek isabet olmuş ömründe Sabri

Derim şu cihanda bulunmaz eşin

Hem kalp ile tasdik ederim Sabri

Tanıyıp gördüğüm çok arkadaş var

Söyleyip güldüğüm hayli yoldaş var

Sırrını bildiğim nice sırdaş var

Benzemez bunların tekine Sabri

Vardır her halinde bir samimiyet

Okunur yüzünde anın hamiyyet

Söylediği sözde çoktur meziyyet

Zirveyi ahlaka ulaşmış Sabri

İnciltmez arkadaş kalbini asla

Tevazu gösterip konuşur nasla

Tereddüt etmeden sırtını yasla

Korkma hulf eylemez bir ferde Sabri

Şu aciz kalemim yazamaz methin

Ben bir söyledimse siz anlayın bin

İfadeyi meram edemem lakin

Tek bildiğim varsa eşsizdir Sabri

Merhamet-i kesir vardır özünde

Bulunur sadakat herbir sözünde

Görünür tebessüm anın yüzünde

Ömer sana hayran olmuştur Sabri

5 Aralık 1958

Caminin mektebinin altı Goga', 'Bulmuş seni gönül kendine yek dost Tek isabet olmuş ömründe Sabri Derim şu cihanda bulunmaz eşin Hem kalp ile tasdik ederim Sabri Tanıyıp gö...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sabri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-huseyin-ozcan-6o8en', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu mevsimde yaprağı düşürür rüzgarlar,			

kara bulutlar bu mevsimde boy gösterir.			

gece bu mevsimde erken gönderir günü,			

yıldızlar bu mevsimde terk eder semayı,			

ve bu mevsimde hep ruhum melankolik olur…			

			

ayrılıklar da bu mevsimi seçer nedense,			

adı üstünde hazan  mevsimi.			

deniz bu mevsimde çığırından çıkar,			

rüzgar bu mevsimde meydan okur buluta,			

sonbahar hüzün mevsimidir….			

			

yok olur yeşili baharın,			

toprak bu mevsimde örtüsüz kalır.			

fırtınalar isyan edercesine eser,			

gök kubbe bu mevsimde akıtır,			

dinmek bilmez sağanak yağmurlarını.			

ve hüzün..ve keder..ve isyan….ve hasret..			

ah sonbaharın yaptıkları……..', 'bu mevsimde yaprağı düşürür rüzgarlar,			 kara bulutlar bu mevsimde boy gösterir.			 gece bu mevsimde erken gönderir günü,			 yıldızlar bu m...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonbahar-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bİr/tUtAm', 'bi-r-tutam-kerime-kaya-1mro2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'zamansızlık 

  benim derdim

  yetişemediğim geleceğe…

  yetişemeyeceğim gerçeğe,

  bir tutam asilik kazıdığım…

  çalan zile, 

  yetişemediğim telefona,

  büyütemeyeceğim papatyaya,

  göremeyeceğim sonbahara…

  zaman dilimlerinde

  gördüğüm ağarmış saçlara,

  kırışmış yüzlere,

  gülmeyi bekleyen umutlara,

  elleri tutan gönüllere,

  bir tutam asilik kazıdığım…

  içtiğim sigaranın külü,

  içimi yakan şarabın rengi,

  düşlerimdeki O…

  O’na bir tutam asilik kazıdım.

  Sevgi anlamını yitirmemeli o küçük yürekte. 

  Karışmamalı duyguların duruluğu yaşanılanlarla.', 'zamansızlık    benim derdim   yetişemediğim geleceğe…   yetişemeyeceğim gerçeğe,   bir tutam asilik kazıdığım…   çalan zile,    yetişemediği...', ARRAY['Türk Edebiyatı','Şiir','Kerime Kaya']::text[], 8.5, '{"poet":"Kerime Kaya","poet_slug":"kerime-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-tutam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlenen', 'ozlenen-atilla-guler-sadgr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlenen

lodos patlamasıydı ağzımdan ıslak sokaklara savrulan

hırsıma çektiğim setlerden taştı kandırılmış düşlerim

şimşeklerini gönderiyor öfkem yağmursuz günlerde

sığın bir yerlere lanetli güneşim sana çok yakın

ortaya koyduğum hayatımın ne değeri vardı gözünde

hiç anlamadığın sevdam yazık çok uzak şimdi senden

en bilmediğim dillerde sövüyorum hiçliğe...dinle

iliğime kadar nefrete dalmış alazlarım uzanıyor yüreğine

karanlık ormanların ıssız kuytusuna yattığım her gün

ihtirasla kabarıyor çığlıklarım...haykırıyor sızılarım

sana inat... sensizliğe inat... yalnızlığa inat…yarınsız

her gün bir şiir yazıyorum kanlı bir aşkla...her güne bir şiir

hani ikimiz…

hani bizim de…

hani… 

sus…masallar anlatıyorum bir çocuğa …ninnisiz', 'Özlenen lodos patlamasıydı ağzımdan ıslak sokaklara savrulan hırsıma çektiğim setlerden taştı kandırılmış düşlerim şimşeklerini gönderiyor ö...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozlenen-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havamsin benim havam', 'havamsin-benim-havam-husamettin-guven-5p3gz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaklugunla oluyorum 

seni ben cok seviyorum

nefes,nefes soluyorum

havamsin benim havam

cok nazli ve guzelsin

hasretinle uzersin

benim icin ozelsin

havamsin benim havam

bu can sensiz olmuyorki

bir gun yuzum gulmuyorki

kalbim sizlar durmuyorki

havamsin benim havam', 'yaklugunla oluyorum  seni ben cok seviyorum nefes,nefes soluyorum havamsin benim havam cok nazli ve guzelsin hasretinle uzersin benim icin o...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/havamsin-benim-havam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapraklar', 'yapraklar-omer-ziya-soyyigit-rexpg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerde o zümrüt sürüsü

Ve kalplerin süruru

Güzel yapraklar

Bir bakışta mest edip

Bihuş eden yapraklar

İçmeden her bakanı 

Sarhoş eden yapraklar

Bübüllerin yuvası

Dertlilerin devası

Aşıkların safası

O güzelim yapraklar

Nerde o fısıldaşan

O yemyeşil alaim

Bad-ı saba mı esti? 

Görünmüyor yapraklar

Döküldü gitti bir bir

Tıpkı ölenler gibi

Çürümeye mahkümdur

O sümbüli yapraklar

Beklemek zorundayız

Beş ay daha bir zaman

Sağ isen eğer Ömer

Yine açar yapraklar.

6 Aralık 1958 Goga', 'Nerde o zümrüt sürüsü Ve kalplerin süruru Güzel yapraklar Bir bakışta mest edip Bihuş eden yapraklar İçmeden her bakanı  Sarhoş eden yaprakl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yapraklar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim Ellerinde Olsun', 'ellerim-ellerinde-olsun-nurten-tarim-6twyf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerim ellerinde olsun

Gözlerim gözlerinde

Göndereyim aşkımı

Görmediğim sevdiğime

Düşlerim yarım

Sevgim yarım kaldı

Gelemedim yanına

Kader arkadaşım

Yıkılası dünyada

Kendimi sana verdim

Sevgi tohumları yeşersin diye

Sardım sarmaladım

Güneşin üstüme doğsun diye

Çiçekli yatağında uzanırken

Düşledin mi sevdiğini

Görmek isteyipte göremediğin

Sevmek isteyipte sevemediğin

Adına kader dediğin

Meçhule giden bu yolda

Bedensiz ruhun sarıldımı beklediğine

Ertelenirken düşlerin hep

Belki yarın diye

Adını sen koy

Çile de istersen

Kendinden bir parça bulduysan

Hayal dünyasında gezerken', 'Ellerim ellerinde olsun Gözlerim gözlerinde Göndereyim aşkımı Görmediğim sevdiğime Düşlerim yarım Sevgim yarım kaldı Gelemedim yanına Kader ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ellerim-ellerinde-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençliğim', 'gencligim-omer-ziya-soyyigit-hpohm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzüldüm ızdırap çektim

Şu üç beş günlük alemde

Yıkıldım tarumar oldum

Hayır kalmadı halimde

Hazan esti dağıttı cümle

Varlığımı birden hem

Sürurum mahvolup gitti

Hemen sermayem oldu gam

Uçtu edvar-ı şebabım

Kalmadı bir zerresi

İhtiyar oldum bu gün ben

Var mıdır bir çaresi

Görmez oldu gözlerim hem

Simsiyah oldu cihan

Çıktı kamburum büküldü

Kametim pes nagehan

Sureta gencim velakin

Manada pir olmuşum

Yirmi dört yılda hayatın

Son demini sürmüşüm

İlk çağında ben hayatın

Olmuşum zir-u zeber

Fayda yoktur bir beşerden

İster öl ister geber

Görmedim bir gün safayı

Gençliğim oldu heder

Sabredip durdum cihanda

Bitmedi derdü keder

Gitti elden ihtiyarım

Hem tahammül kalmadı

Çarptı re''sim hacre zira

Bu gönül uslanmadı

Azrail geldi göründü

Erdi takdir-i Huda

Ey Ömer sen tevbeye gel

Olma kim Hak''tan cüda

11 Haziran 1958 

Mezirelik Goga', 'Üzüldüm ızdırap çektim Şu üç beş günlük alemde Yıkıldım tarumar oldum Hayır kalmadı halimde Hazan esti dağıttı cümle Varlığımı birden hem Sü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gencligim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim', 'sana-geldim-gulseren-onay-n6ckk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dediler ki; ’yarin hasta’

Ayak yalın koştum geldim

Kalbi kırık gönlü yasta

Hüzünlerle piştim geldim

Allar basmış ak tenini

Alev sarmış bedenini

Sevda kesmiş kefenini

Aşk seline düştüm geldim 

Yaşam için umut varmış

Karşı dağı kurtlar sarmış

Hava yağmur, boran, karmış

Ben dağları aştım geldim

26/02/2006/ANTALYA', 'Dediler ki; ’yarin hasta’ Ayak yalın koştum geldim Kalbi kırık gönlü yasta Hüzünlerle piştim geldim Allar basmış ak tenini Alev sarmış beden...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-geldim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam anam canim anam', 'anam-anam-canim-anam-husamettin-guven-9iopm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'garip guzel kiz anam

bagri yanik koz anam

sendin bana tek yanan

anam anam canim anam

beni hergun eziyorlar

garip gorup kiziyorlar

mezarimi kaziyorlar

anam anam canim anam

seni ben cok ariyorum

mazilere daliyorum

gunden gune eriyorum

anam anam canim anam', 'garip guzel kiz anam bagri yanik koz anam sendin bana tek yanan anam anam canim anam beni hergun eziyorlar garip gorup kiziyorlar mezarimi k...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anam-anam-canim-anam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım - 5', 'kizim-5-elazigli-mustafa-kaya-ty6un', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugün yoksun.

odana baktım.

odanın kapısı yine gıcırtılı,

dağınık bakıyor

dolabın.

boynu bükük..suskun 

sensiz eşyaların.

derdi ne..? 

tıka basa dolu çekmecesi masanın.

kıvrılıp yattığın divan

bu kez dağınık değil

toplu bırakmışsın….

fotoğraflar dizili

yenilemişsin

sıra sıra okul yılların

aile fotoğrafları

annen ve babanı  bir karede

annen,

elleriyle  pasta tutar halde

baban çok mutlu

birlikte ve sıcak

güzel bir aşk

etrafı fotoğraflarla çevrili

en sevdiğin bu belli..

duvarda yazılar…yazılar

kendine öğütler

ayet ve hadisler

buruşuk bir kağıt

atmamış asmışsın duvara

babiş ‘ inin yazısı

en kıymetlisi olmuş odanın

saklamış

sevmiş

sevinmişsin babiş’in notuyla

daha neleri tutuyorsun..? 

sessiz duvarlarda

nelerle,

gizli gizli avunuyorsun..? 

hangi hıçkırıklarını ,

ve,

neleri çok özlemektesin 

duyamadık.

gözyaşlarını kurulamayı

başaramadık..

yoksun yine,

özlem dolu 

yine hasretle dönmek 

için,

yine  “..evimi çok özledim..”

demek üzere gitmişsin 

okuduğun kitaplar

yarım kalmış,

üst üste yığılı bırakmışsın.

bozuk paraları hiç sevmedin

“..babiş bu demirlerden kurtar  beni..” derdin

aldım hepsini

raflar

çekmeceler taşıyor

ellerinin izi duruyor

benim canım kızım

biriciğim

doyasıya sevemediğim

alıp karşıma vakit ayıramadığım

çillerini özlediğim

sinirlenmelerini

geç kalışlarını

hiç sevemediğim

çiçeğim,

yoksun bugün

yoksun işte

kol geziyor hüzün

sensiz ev  yürümüyor

sessizce gezindim odanda

sessiz kaldım resminle

yüzümün  sevinci …gözlerimin ışığı

olacaksın 

geldiğin günle.

bu odada sen geziyorsun

hayalin hiç çıkmıyor

sen bilmezsin

ardındaki sevgimi

seni ne kadar beklediğimi

korkularını 

nereye saklıyordun,

gözyaşların nereye düşüyordu

söyle..! ! 

bugün yoksun

ve  tadı yok 

bu hafta sonunun ….

Mustafa kaya

27.02.2006 /  üsküdar', 'bugün yoksun. odana baktım. odanın kapısı yine gıcırtılı, dağınık bakıyor dolabın. boynu bükük..suskun  sensiz eşyaların. derdi ne..?  tıka ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/kizim-5-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya ve İnsan', 'dunya-ve-i-nsan-mehmet-ali-kalkan-knono', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herşey ayan beyan görebilirsen,

Ateş yakmak,rüzgar esmek içindir.

''''İki kulak için bir dil ne? '''' dersen,

Az konuşup çokça susmak içindir.

Hasretini söyler nefes nefes ney,

Taca boyun eğen kendisine bey,

Suyla çeliklenen bıçak denen şey,

Eline alınca kesmek içindir.

İzler önündeyse geçmiş nicesi,

Leyla Mecnunların zor bilmecesi,

Yorgun akşamların uzun gecesi,

Sevdayı zamana asmak içindir.

Ses versem dağlara bana öykünür,

Gün gelir dağı da karalar bürür,

Herkesin yanında bir ölüm yürür,

Dünya üzerine basmak içindir...

                             Mehmet Ali Kalkan', 'Herşey ayan beyan görebilirsen, Ateş yakmak,rüzgar esmek içindir. ''''İki kulak için bir dil ne? '''' dersen, Az konuşup çokça susmak içindir. H...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dunya-ve-insan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istırap', 'istirap-elazigli-mustafa-kaya-m5904', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Istırap

  

beyaz ve sarı lambalar

şehrin tüm ışıkları açık 

sırdaş bana kaldırımlar

yürüyüp giden gece

yalnızlığımı alır

nar çiçeği gülüşlerin

birazdan ağaracak gün 

cama vuran sabah

gülümseyecek

kuş cıvıltıları 

mutluluk kalkışı

bu şehre alıştım 

ıstıraplarım geçti

kambur gölgeleri

bıraktım...

Mustafa kaya 

27.02.2006 / fatih', 'Istırap    beyaz ve sarı lambalar şehrin tüm ışıkları açık  sırdaş bana kaldırımlar yürüyüp giden gece yalnızlığımı alır nar çiçeği gülüşler...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istirap-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kokulum Naat', 'gul-kokulum-naat-sevim-yakici-ivqx4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilsen nasıl yüksüzdür seni yazmayan kalem

Hasrettir nur deryana kelamlar gül kokulum

Hem yetim hem öksüzdür seni anmayan alem

Boynu bükük dökülür selamlar gül kokulum

Kevser ırmaklarında toprağın arınmıştı

Peygamber olacaklar nurunla sarınmıştı

Ezel ve ahir alem mührünle korunmuştu

Biliminle donandı alimler gül kokulum

Öz nurundan yaratmış, karanlığa çağ etmiş

Ezeli iradeyle hakikate bağ etmiş

Sana inananlara kıbleyi otağ etmiş

Sırrınla yaratıldı alemler gül kokulum

Cahiliyet kirinin zerresi bulaşmadı

Seçilenden seçildin, nesebin dolaşmadı

Varlığın tacı oldun, şirk sana ilişmedi 

Mevcudunla son buldu elemler gül kokulum

Üç sabah yıldızıyla müjdelendin cihana

Ak kanatlı bulutla tanıtıldın her cana

Şehitler yarış etti kavuşmak için sana

Vuslat diye içildi ölümler gül kokulum

Mutlak mana içinde ezel sen ahir sende

Can buldu nur deryası ipek dokulu tende

Goncalar güle döndü senin sırlı busende

Gelişinle mahv oldu zalimler gül kokulum

SUNU:

Özledim, özledim, çok özledim seni YAR! 

Sevdana talip olmuşum, Kevser havuzunun yanında buluşmaya kaç var…

