INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün..', 'surgun-zulfikar-yapar-kaleli-iigmi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'embed src= http://www.neyzen.com/images/taksim/yavuz_akalin/yavuz%20sivenuma.wma

font face=''Comic Sans MS'' color=''black'' size=''0,5''

Ben ki uslanmaz el ben kızarmaz yüz

Ben ki girginlerin en girginiyim! 

Ben ki geçmez akçe, ben dinlenmez söz

Ben ki dargınların en dargınıyım.

Ben ki ölümlere eğilmeyen baş

Ben ki ağustosta kurumayan yaş

Ben ki haksızlığa çatılmayan kaş 

Ben ki gerginlerin en gerginiyim.

Ben ki kof kavağın gevrek dalıyım

Ben ki saf sanılan şeker balıyım

Ben ki garipliğin garip halıyım

Ben ki durgunların en durgunuyum.

Ben ki her yarışta bitmeyen etap

Ben ki minberlerde dinlenmez hitap

Ben ki tozlu rafta okunmaz kitap

Ben ki kırgınların en kırgınıyım.

Ben ki gözlerimde tüter Tur dağı

Ben ki kör şeytanın kader ortağı

Ben ki atıkların atık artığı

Ben ki yorgunların en yorgunuyum.

Ben ki bir tek gönle sinmez muhabbet

Ben ki gerçeğin ta kendisi elbet

Ben ki şer başında tutarım nöbet

Ben ki vurgunların en vurgunuyum

Ben ki yarı masal, yarı gerçeğim

Ben ki haram lokma ve içeceğim

Ben ki zemheride açan çiçeğim

Ben ki argınların en argınıyım

Ben ki kalem ile yazılmaz yazı

Ben ki yazılınca bozulmaz yazı

Ben ki gönüllere kazılmaz yazı

Ben ki sürgünlerin en sürgünüyüm.', 'embed src= http://www.neyzen.com/images/taksim/yavuz_akalin/yavuz%20sivenuma.wma font face=''Comic Sans MS'' color=''black'' size=''0,5'' Ben ki u...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/surgun-171-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul (İkinci Şiir)', 'i-stanbul-i-kinci-siir-i-rfan-kaban-qb3ic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her ayrı duyguda canlanan toplam mimiklerim 

Sevincim,

İçime sindiremeyip dışa vurduğum taşkınlığımın kaynağı

kızgınlığım

Öfkemi dünyanın dönmesi gereken eksen sandığım şey yani

Ve yatışmışlığım benim 

Uzanıp yattığım,

Uyanıp kalktığım,

Unuttuğum,

Unutulduğum,

Farkına varıp, farkına varıldığım

Dert

hemdert

İstanbul

Yaşadığım kent

İstanbul

Bu nasıl şehir

Ayaklarımın altından çekilir

Adam devirir

rakı

ekmek

kavun

peynir

İstanbul içilir

İstanbul yenir

mutluluklara

mutsuzluklara İstanbul denir

arsız

dansöz kıvraklığında, kemiksiz

fark etmez ha başka biri, ha sizsiniz

madem ki kaptırıp kendinizi  karşısında oyununa  girdiniz

siz ne halt yediniz bilemezsiniz

nice namlı belalısı var

İstanbul’la dans edemezsiniz

Vurdunuz,vurdunuz

Ama ıska geçtiniz,akıbette diğerleri gibisiniz

Daha nerden çıktı diyemeden bu güruh

Bakmışsınız linç edilmişsiniz

mengeneye alınmışsın

sıkışmışsın 

dönüşü düşünemezsin

diyelim ki düşündün

ne halt yiyeceksin

keşke

keşke

keşke diyeceksin

geri dönemeyeceksin

sıkışacaksın

patlarım sanacaksın

sıkışacaksın

sıkışacaksın

patlamayacaksın

ama İstanbul’da azatsız kalacaksın

bu İstanbul ki

bu

şu umarsız şehirdir

mezhebi geniş şehirdir

gözleri kapamak

İstanbul’u dinlemek delilik etmektir

Ve bu yüzdendir

En kuytu duvarlarında yazar

Burada rahatlayan eşektir.

gün devrilip karanlık çöktüğünde

içinde tanımsız ürperdi

kalabalık yalnızlık

yalnızlık kalabalık

akar gider caddeler

İstanbul’da binlerce ipi boşalmış deli

Bakmışsın ele geçirmişler geceyi

İstanbul’u dinlemek demek

Hesapsız sevişmek

Bundandır İstanbul şehveti

Ömrün gitti gelmez geceleri

Ağlamak İstanbul’da derde deva değil ama

Ağlamak İstanbul’da 

zeytinin tadı gibi kuru ekmeğin yanında

Buruktur,acıdır 

Lakin eninde sonunda lezzettir, tadımlıktır, katıktır

Ağlamak İstanbul’da 

 bulunamayanı değil,yiteni anlatır

umut edersin,umut edersin

öyle gelir

İstanbul’da umutlarını bozdurup yesen geçinirsin

Milyonda bir İstanbul adam sivriltir

Bilemezsin nasıl olur da durduk yerde sivrilenle mutlu olursun

Şaşarsın başkalarının sevincine yok yere ortak olmuşluğuna

Tam can çekişiyorum derken düğün alayına karışmışlığına

bu gün şanslı olan başkası değil gelecekteki sensin

Dikiş tutturmak madem ki piyango şansı arar burada 

İstanbul kime niyet,kime kısmet

Araya hileyi katmayı ararsın

İstanbul u dinlemek demek

O güzelin güzeli saf duygularına ihanet

apansız saçılmış

arsız bir zaman ki

oldum bittim zamansız

bahar kokusu alır

heyecanlara dolanır

tanıdık bildik

kayısı

erik

aldanır çiçek açar

pembe

beyaz

çiçeklenir ağaçlar

adı ilk yaz

İstanbul’da gaza gelmek olmaz

Nasıl denir

İstanbul’u dinlemek demek

Fazlasından kazık yemek

İstanbul değirmen

Umut ister

Un ufak edecek

İstanbul fırın

Getirin

Adam pişirecek

Sor 

İstanbul hangisi

İstanbul günah keçisi

İstanbul’u dinlemek demek

Neyini seçersen seç

Boş çile

Meğer

Gözün hep diğerindeyse...

Bu şehrin meydanları

On beş

On altı haziranlar

Önemli değil,kimi anlamaz,kimi anlar

Bu şehrin meydanları bir mayıslar

Bu şehrin meydanları

Sokağa çıkma yasağı

Ipıssız uzanıp giderken meydanlara caddeler

Caddeleri panzer bekler

 korku sinmiş bu şehrin meydanlarına

Bin dokuz yüz yetmiş yedi bir mayısında

O zamanki ismi ile bir mayıs alanında

Kim kurşunu sıkmışsa yurdun her bir yanından gelmiş emekçilere

Vatanını kurtaran  ulu kahraman gibi gelip onlar dönüştü çetelere

Bu şehrin meydanları  ruhumun aydınlık yanı

Bu şehrin meydanları gençlik günlerimin gitti gelmez heyecanı

Yürüyüş sıralarında dışa vurup öfkesini

Sokağa taşırıp da sabrı

Bir ağızdan bağırdı

Ve özgürlük,özgürlük sesleri

Polis coplarıyla,panzerlerle dağıldı

Yürüdü canım

Gençliğin rüzgarla savrulmuş ömrü

O da İstanbul caddelerinde yürüdü

Sevdalandı

Çiçek açtı

Neden hep o ilk yaz

Gaza geldi

İstanbul’da gaza gelmek olmaz...

İstanbul güzel şehir

İstanbul gelişigüzel şehir

İstanbul yaşadığım şehir

Bu şehir albenisi çeşit şehir

Ayrı lezzettedir

Bu şehirde her seyir çekilir

Kazançlara 

Kayıplara İstanbul denir

İstanbul’u dinlemek demek

Güzelim koynunda yorgun düşmüş beden

Uzanmak yatağa

Aklımda bir daha

Aklında bir daha

Gözleri kapamak

İstanbul’u dinlemek demek

Umutla ömrü evermek güzelim

Ömrü umutla evermek...

İstanbul’u dinlemek demek

Açılmak kendine

Kim bilir rahatlamak belki

Yada ne bileyim

İstanbul’u dinlemek demek

Denemek bitirmek

Bitirmek denemek

Büyüklenmek

Tövbe etmek

İcadına girişmek yeni tövbenin

Bahane yaratıp yeni tövbeye

Sonra yeni bir tövbe daha yine

Hani deki

İstanbul’u dinlemek demek

Boğaziçi’nden geçen gemilerin kaptanının  telaşında

Geçene kadar rota üstüne rota çizmek

Kaçırınca ipin ucunu kıyılara bindirmek

İstanbul’u dinlemek demek 

çokça da  iki yakayı bir araya getirememek

bir de ne? 

İstanbul’u dinlemek demek

değildir böyle düşünmek…

1994', 'Her ayrı duyguda canlanan toplam mimiklerim  Sevincim, İçime sindiremeyip dışa vurduğum taşkınlığımın kaynağı kızgınlığım Öfkemi dünyanın dö...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kaban']::text[], 8.5, '{"poet":"İrfan Kaban","poet_slug":"i-rfan-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":193,"source_url":"https://www.antoloji.com/istanbul-ikinci-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden bilecektim?', 'nereden-bilecektim-veysel-alkan-2ch6w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.

Deli gibi sevdiğini.

Söyle! nerden bilecektim? 

Müneccim mi sandın beni? 

Söyle! nerden bilecektim? 

Gördüğüne,sorduğunu.

Bana,yürek koyduğunu.

Sevip,aşık olduğunu.

Söyle! nerden bilecektim? 

Bir görünce,uçtuğunu.

Hep peşimden koştuğunu.

Aşkın ile coştuğunu.

Söyle! nerden bilecektim? 

Gözgöze mi geldin sanki? 

İşaret mi verdin sanki? 

Aklımı mı çeldin sanki? 

Söyle! nerden bilecektim? 

Demedin ki bir kez olsun.

Daha yeni söylüyorsun.

Yıllar yılı susuyorsun.

Söyle! nerden bilecektim?', '. Deli gibi sevdiğini. Söyle! nerden bilecektim?  Müneccim mi sandın beni?  Söyle! nerden bilecektim?  Gördüğüne,sorduğunu. Bana,yürek koydu...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nereden-bilecektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
