INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Resim', 'bir-resim-isik-german-ersoy-z1rvs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Sevgili babam Vet.Dr.Albay Enver Ersoyun anısına-

Bir resim yapmıştım

Bir zamanlar

Unuttuğum

Belkide üç

Yaşındaydım...

Onu bana

Göndermişlerdi

Yakınlarım

Babamın öldüğü gün...

Yastığının altında

Bulmuşlar

Ölümüne yetişememiştim

Ya...', '-Sevgili babam Vet.Dr.Albay Enver Ersoyun anısına- Bir resim yapmıştım Bir zamanlar Unuttuğum Belkide üç Yaşındaydım... Onu bana Göndermişle...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-resim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadar Kaçarsan Kaç', 'ne-kadar-kacarsan-kac-melih-coskun-1jku4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kadar kaçarsan kaç 

Gelir bulur seni kayıp zamanların rüzgarı

Sen kavga mevsiminin çocuğusun 

En gerçek türküyü yazmaktır senin işin 

Nereye saklanırsan saklan 

Gelir bulur seni bu deli fırtına 

Korkak da olsan 

Kahraman da 

İçine çekilirsin sebepsiz kavgaların 

Sebepsiz ölümler boy gösterir kapında 

Koskoca bir hiçliğin ortasında 

Masum bir çocuk gibi dolanıp durursun 

Silahlar tutuştururlar eline 

Oysa her insan en çok kendi kavgasının kahramanıdır 

En çok korkutan da 

Hiç kere hiçliğin ortasında düşüp kalmaktır.

Nerede olursan ol 

Kapılır seninde yüreğin 

O deli gibi akan ırmağın sularına 

Aşk çağını feda edersin belki yurduna…

2004

www.melihcoskun.com', 'Ne kadar kaçarsan kaç  Gelir bulur seni kayıp zamanların rüzgarı Sen kavga mevsiminin çocuğusun  En gerçek türküyü yazmaktır senin işin  Ner...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ne-kadar-kacarsan-kac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamla Ölüm', 'yasamla-olum-isik-german-ersoy-8iime', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '* Felsefe - Doktrin Dünyada ve Antoloji.Com da ilk kez *

Yaşamla 

Ölüm arasındaki

Tek benzerlik

İkisininde

Aynı çizgide

Gidip gelmesidir', '* Felsefe - Doktrin Dünyada ve Antoloji.Com da ilk kez * Yaşamla  Ölüm arasındaki Tek benzerlik İkisininde Aynı çizgide Gidip gelmesidir...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasamla-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döneriz Başa Can Yerine', 'doneriz-basa-can-yerine-yasemin-sezer-tulgar-yvr5x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Od topladım cebinden

Hüzün yaktım 

Parmak dilinde garip

Sus pus kaldı dilim

Gece mi soğuk

Yüklendiğim kült buz küpleri mi

Bilemedim

Başım üstünde es diye dolanan rüzgar

Üflese de evime geri

Gidemedim

Bilirim

Ben bu gece garibim

Tepinmeler dengi vücutta son

Bulacak mıyım elden bir gök taşı

Düşürme alnımdan kitabeyi

Okudukça dökecek yaşı

Dokunduğu yerde ne bıraktı bilmem

Hoş

Hoş

Hoş

Hoş geliyor buz başıma düşünce an

Hoş kılınan gecem

Nahoş bıkkınlığında

Sokulunca cebine

Korktum

Söz dile düşsün diye

Döndüm can yerime

Dillensin derdim; 

Dostsa, can korku bilmez ise

Döneriz başa, can yerine

26.02.2006', 'Od topladım cebinden Hüzün yaktım  Parmak dilinde garip Sus pus kaldı dilim Gece mi soğuk Yüklendiğim kült buz küpleri mi Bilemedim Başım üs...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/doneriz-basa-can-yerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Görüntüsü', 'olumun-goruntusu-isik-german-ersoy-ad01c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümün görüntüsü

Asla

Yaşamla bağdaşamaz

Ama

Yaşamın görüntüsü

Her an

Ölümle içiçedir', 'Ölümün görüntüsü Asla Yaşamla bağdaşamaz Ama Yaşamın görüntüsü Her an Ölümle içiçedir...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olumun-goruntusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küldeki Gülümseme (Sesimdeki Kuğu)', 'kuldeki-gulumseme-sesimdeki-kugu-ayten-colakoglu-aiq9z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

gökyüzünde köşe kapmaca oynardı güneş ve ay

gönlümüze düşerdi küpe çiçekleri

lirik bir uykuya dalardı sıcak gövdelerimiz

iki kişilik rüyalarımız birbirine karışırdı

aşktan konuşmazdık hiç, çünkü biz aşktık

uzun uzun severdik uzaklığımızı, dudaklarımız incirdendi

uykusuz bir şehirdi gözlerimiz

ve içimizdeki sandal hiç kara görmemişti

yaralı güvercinlere kanat takardık

güz çocuklarıydık, durmadan üşürdü ellerimiz

aşkımızdan fidye istedi hayat

her şey yalandan bir kahkaha, sanki her şey masaldı

ateş suyu içtik, saflığımızı giyindik, kırılgandı düşlerimiz

lir çalarak uyuttuk içimizdeki yaban geyiklerini

ılık koynumdan bir anka daha kanatlandı gitti

aşk bitti, şimdi küldeki gülümsemedir yanışım...

.

Sesimdeki Kuğu / Hayal Yayınları 2004

.', '. gökyüzünde köşe kapmaca oynardı güneş ve ay gönlümüze düşerdi küpe çiçekleri lirik bir uykuya dalardı sıcak gövdelerimiz iki kişilik rüyal...', ARRAY['Türk Edebiyatı','Şiir','Ayten Çolakoğlu']::text[], 8.5, '{"poet":"Ayten Çolakoğlu","poet_slug":"ayten-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kuldeki-gulumseme-sesimdeki-kugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Sevmek', 'yeniden-sevmek-isik-german-ersoy-2aiim', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeniden sevmeye çalıştım

Sana inat

Ama onun gözlerinde

Yine seni gördüm

Dudaklarında

Hep seni tattım

Ve bedeninde 

Seni okşadım

Sana inat

Yani

Yeniden sevmeye

Çalıştım

Beni affet', 'Yeniden sevmeye çalıştım Sana inat Ama onun gözlerinde Yine seni gördüm Dudaklarında Hep seni tattım Ve bedeninde  Seni okşadım Sana inat Ya...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yeniden-sevmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun Dedim Olmasınca', 'olsun-dedim-olmasinca-ahmet-ozturk-menjv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir girdap bir girdaba biner

ve gider beni hapsettiğiyle

oysa bıyık bırakacak kadar eriyordum

şakağıma kadar dayanmadan önce 

Bültenleri okusam görecektim sonumu

küvet deliğinde bir sabun eriyordum

Çok bekledim oysa bir masada 

defterin üstünde bileklerimde mürekkep

Olsun dedim olmasınca

Olsun...

Bilmedim, fısıltı da duyamadım

sessizce prangalandım tebessümleriyle

Acı bu kadar mı su vurulmuş demir olur

sabırsa bu kadar kancık pusu

Hayali yasaktır baharın sarması

her bir dalını devasa öksüz bir ormanın

(05 Kasım 2005)', 'Bir girdap bir girdaba biner ve gider beni hapsettiğiyle oysa bıyık bırakacak kadar eriyordum şakağıma kadar dayanmadan önce  Bültenleri oku...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olsun-dedim-olmasinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutların Ardında', 'bulutlarin-ardinda-muammer-erturan-nz10j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakınmalardan,

......sakıncalardan

............ve sataşmalardan ırak; 

sıradanların,

......sürüdenlerin

...........ve sürüngenlerin

asla erişemeyeceği

.........................bir yer...

Kuşatmaları,

.......dayatmaları

..............ve anaforları

bırakıp geride,

açılmak var

.......alabildiğine

................enginlerinde...

Öyle bir yer var...

Biliyorum

......var öyle bir dünya

...............bulutların ardında...

Hazırsan

......kanatlanmaya şayet,

....................bir göz et yeter...

(12 Ekim ''96)', 'Sakınmalardan, ......sakıncalardan ............ve sataşmalardan ırak;  sıradanların, ......sürüdenlerin ...........ve sürüngenlerin asla eri...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bulutlarin-ardinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviye Çalan Hüzün', 'maviye-calan-huzun-ahmet-ozturk-svw0f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte içimdeki maviye çalan hüzün

ne kadardır aradığım yitik gerçek

Goncagül dedikleri gibi birşey

Daha tam açmamış maviye

(03:30) 

(14 Kasım 2005)', 'İşte içimdeki maviye çalan hüzün ne kadardır aradığım yitik gerçek Goncagül dedikleri gibi birşey Daha tam açmamış maviye (03:30)  (14 Kasım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/maviye-calan-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk sınır tanımaz derler bilirsiniz!', 'ask-sinir-tanimaz-derler-bilirsiniz-omer-koroglu-2gggz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün üniversiteli bir delikanlı,hergün bindiği metroda o kızı görür, saçları altın sarısı,gözleri okyanus mavisi ve hiç açıldığını görmediği dudakları kiraz kırmızısı.Her sabah o trenin hangi vagonuna ve hangi saatte biniceğini hesaplayarak çıkar evinden delikanlı.Aradan aylar geçmiştir ama kız bir kez olsun farketmemiştir delikanlıyı! Üniversiteli aşık her sabah gözlerinin ayarını hiç bozmadan bir yolunu bulup onunla göz göze gelmeye adar hayatını.Ve işte öyle günlerden birinde, delikanlı biraz geç kalır metro nun kalkış saatine, tam merdivenlerden inerken birinin daha aynı kapıya onunla beraber koştuğunu farkeder başını çevirdiğinde. O kızdır onunla aynı anda geç kalan,ama güzel sarışın bakışlarıyla olduğu yerde durup,ona bakakalan genç adamı geride bırakarak tam kapıların kapanmasına yakın, atar kendini vagona....Genç üniversiteli vagondan içeri süzülen kalp sancısını izler istasyondan.Ve işte aylardır başarmaya çalıştığı şeyi o an başarır genç adam,kız kendisini çaresiz bir şekilde izleyen o şaşkın ve bir o kadar üzgün bakışları farketmiştir arttık.O da kilitlenir ister istemez genç adama içinde tanımlayamdığı duygulara ev sahipliği yaparak.Genç adamsa oturup bir sonraki treni bekler ertesi sabah tekrar karşılaşmak umuduyla.Kısa bir beklemeden sonra karşıdan gelen treni görüp kalkar yerinden... aşinalık işte, o güzel kız olmasada,ayakları o vagona yönelir yeniden, inen yolculardan sonra kapıdan içeri ilk adımı atar ve başı önde hemen oturur bi koltuğa...Tren hareket ettikten kısa bir süre sonra sırtının dayalı olduğu koltukta oturan yüzünü göremediği birinin eli ona bi kağıt parçası uzatır, bir anlık tepki olucak, kağıtta yazanlar ilk ilgi alanı  olur, verenden ziyade; diyordur ki  kağıtta muhteşem bi el yazısıyla ; ''''Her sabah karşımda durup beni izleyen adam, sana birşey sormak istiyorum; konuşmadanda yaşanırmı aşk? ''''Adam herkesi herşeyi unutur birden, dalar gider bir kaç dakikalığına, hemen elindeki kalemle cevabını yazar ve ne yapacağı o an gelir aklına; yani onu kağıdı veren kalp sızısının bir arka koltukta oturduğu gerçeği..Süratle kalkar yerinden döner arkasını, ama boştur koltuk ve biran arka sayfasını gördüğü kağıtta bi not görür:yarın sabah cevabını aynı kağıtta ilet olurmu? 

Dünyalar genç adamın olmuştur artık... sabahı zor eder, gece sabaha kadar onu düşünür.Aklına gelen ve o an yazdığı cevap karşısında.Sabah geç kalmamak için koşar adım gider metro istasyonuna ve biner aynı vagona.İşte hayal sandığı dün, bugün nihayetine ericektir az bir zaman sonra; kızın yanı boştur, oturur ve bu sana diye uzatır cavabını ''''Kalbin dili, her dilden,her sesten üstündür'''' yazan..Kız gülerek onaylar bu cavabı ve o an delikanlıyı şaşkınlıktan lal eden bir not uzatır tekrar eline..Adım ayşen, 2 yıl önce bir trafik kazsında yaşadığım şok, işitme duyularımı kaybetmeme sebep oldu.Gözlerin ve kalbin, gözlerim ve kalbimle konuşabilrmi? ''''Genç üniversiteli şok geçirir o an evet mi dese hayırmı..İniceği istasyona geldiğini anlayınca, bir not yazar ve uzatır o tatlı sarışına; yarın yine görüşürüz''''..Ve iner trenin o sessiz vagonundan.Aslında eve varmadan kararı vermiştir içinden:EVET.			                                            

Ertesi sabah elinde bi gül ile gider istasyona ve karşıdan geldiğini görür 2 günlük rüyasının.İşte o gün başlangıcıdır bu sessiz aşkın.Delikanlı artık mektuplaşmaya, duygularını okuyarak ve yazarak yaşamaya başlar, yan koltuğunda oturduğunu bildiği o rüyasıyla.Hayat yolunda hep yan koltukta oturmasını ister o dünyalar tatlısı kızın ve aradan geçen mutlu ve umutlu 1 yılın sonunda genç adam mezun olma töreninden hemen sonra; o nu hayatının kadını yapmayı ne kadar istediğin yazar karşı sandalyede oturan rüyasına son mektubunda.Bu kez susar,cevap yazmaz kız,ama bunun yerine eğilir adamın kulağına,derin bir nefes aldıktan sonra, o şiir gibi nefesiyle, kiraz dudaklarının arasından şu sözler dökülür; ''''Hemde zerre pişmanlık duymadan, binlerce kez evet.''''

Ömer Köroğlu', 'Bir gün üniversiteli bir delikanlı,hergün bindiği metroda o kızı görür, saçları altın sarısı,gözleri okyanus mavisi ve hiç açıldığını görmed...', ARRAY['Türk Edebiyatı','Şiir','Ömer Köroğlu']::text[], 8.5, '{"poet":"Ömer Köroğlu","poet_slug":"omer-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-sinir-tanimaz-derler-bilirsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan 1', 'seytan-1-isik-german-ersoy-od406', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adamın biri

Öylesine aceleciydiki

Sonunda 

Dayanamayan şeytan

Bu duruma el koymak

Zorunda kaldı', 'Adamın biri Öylesine aceleciydiki Sonunda  Dayanamayan şeytan Bu duruma el koymak Zorunda kaldı...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seytan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasım da Aşk Başkadır', 'kasim-da-ask-baskadir-omer-koroglu-snppz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kasım da aşk başkadır; Aslında bu yazı şubatta yazıldı ama, izlediğim o film çok etkiledi bu gece beni...  İzlemeden önce sadece 1 ay, kasım ayında yaşanıp biten bir aşkı senaryolaştırmışlar sanmıştım..Ama izlerken anlıyorsunuz ki ,  KASIM bir sembol, hayattaki son 30 gününüzün sembolü.Evet hasta bir kadın ve yardıma ihtiyacı olan bir iş koliğin hayatı vardı ekranda..Hayatı ilaçlara bağlı olan bir kadın son  günlerini o asil serseri ile geçirmek istedi..Onu değiştirip mutluluğun iş temposunda değil; insanda, doğada, hayvanlarda ve en önemlisi sevgide olduğunu göstermek  istedi kadın, bunun son oyunu olduğunu bile bile...

		Kasım da aşk başkadır; Çünkü bütün takvimler  30 kasım a ayarlıydı.. O gün olunca herşey biticek ve adamın gidiceğini sandı kadın..Ama sevgi bu, aşk bu, başlamaya, kendine bir çıkış yolu bulmaya görsün, gücünü, ışığını insanların gözünü kör etmek için çıkarıyor ortaya işte....Ve o an kimsenin kendi hayatı önemli olmuyor, karşısındakininki kadar, onu üzmek istemiyor! 

		Kasım da aşk başkadır; Çünkü Filmi izlerken o büyülü anlara sizde kapılıyorsunuz; etrafınıza bakıp ben ne yapıyorum böyle diyorsunuz kendi kendinizi sorgulayıp..Hayatın, iş te, kariyerde,teknolojide değil; aşk ta, adanmışlıkta,gözlerden gözlere akan o tılsımda olduğuna hayret ve pişmanlıkla karışık bir ifadeyle bakıyorsunuz....Ve seçim yapma zamanı; ya onun yanında kalıp kör bir aşık olarak hayatının sonuna kadar, ona eşlik etmek, yada çekip gitmek düşüyor size..Ne tuhaf değil mi; işte yine bir seçim daha sunuldu önünüze! ! Seç ve yaşa; İşte az önce söylediğim gibi; kimsenin hayatı önemli olmuyor karşısındakininki kadar..Ve size en uygun olanı seçmeyi istiyorsunuz..Eğer yaşananların sizi mutlu ettiğine inanıyorsanız yanında kalıyor, veya zamana yenik düşüp şimdiki zamanın,; teknolojinin, iş hayatının, yüksek binalı metropollerin esiri kalıp uzak düşüyorsunuz kalbinizden...Daha ne kadar sürücek, bir bedenin kalpsiz yaşayamıyacağını anlamanız? 

		Kasımda aşk başkadır; Çünkü İnanın bana Kasım değildir yaşanan, son aydır o...Yaşa ve mutluluğu gör diye sana sunulan son ay..Hala anlamadınızmı; Kasım bir sembol; SON ayın sembolü..., siz ona başka adlar taksanızda olur...Mart tan başlamaya ne dersiniz? Yani hayattaki mutluluğun; insanda, doğada,hayvanlarda ve en önemlisi sevgide olduğuna, adanmışlıkta olduğuna inanmaya ve onu yakalamaya çalışmaya, sizce mart uygunmu? Başarabilirmisiniz? Hem bir beden kalbi olmadan daha ne kadar yaşar hiç düşündünüzmü? 

		Hey sen; OCAK, ŞUBAT, MART, NİSAN, MAYIS, HAZİRAN, TEMMUUZ, AĞUSTOS, EYLÜL, EKİM,KASIM, ARALIK Bunlar yetermi anlamana , hayat bu, kukla değilsin; mutlu yaşa...Hem şunuda sakın unutma; O SON AYDA AŞK BAMBAŞKA..O ayı seç ve bedenine yapışık kalbinle, onunla yaşa...Hayatının son dakikaları bile olsa...

		Çünkü; kasımda (seçtiğin ayda)  aşk başkadır...', 'Kasım da aşk başkadır; Aslında bu yazı şubatta yazıldı ama, izlediğim o film çok etkiledi bu gece beni...  İzlemeden önce sadece 1 ay, kasım...', ARRAY['Türk Edebiyatı','Şiir','Ömer Köroğlu']::text[], 8.5, '{"poet":"Ömer Köroğlu","poet_slug":"omer-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kasim-da-ask-baskadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazar Yazmayı Bırakır', 'yazar-yazmayi-birakir-omer-koroglu-71o9v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YAZAR, AŞK I ANLATAN YAZILAR YAZMAYI BIRAKIR...

Eğer yazan vazgeçerse bir gün yazmaktan; o gün başka bir şey den  daha vazgeçmiş demektir... Ve o diğer vazgeçiş, yazmaktan vazgeçmeye sürüklemiştir onu.

Kalem bile doğru durmaz elinde. Yazacak bir şey kalmamıştır artık... Bundan sonra ne gelse yüreğinden dilinin ucuna, reddedip gönderir geriye, içi tamamen ne zaman dolar taşar bilmeden.

   Yazar aşk ı anlatan yazılar yazmayı bırakır...

Eğer vazgeçmişse bir aşk ı anlatan yazılar yazmaktan, emin olun ki o aşk tan vazgeçmiştir yazar... Bir vazgeçiş bir diğerine sürüklemiştir onu. Kalemiyle oynayıp durur,  yazamaz eskisi (aşık ken ki)  gibi.

İşte buda bir gerçeği koyar ortaya; vazgeçen yazar değil, aşk tır. Aşk vazgeçmiştir ondan.

   Kelimeleri eskisi gibi dokunaklı, yüz pembeleştirici değildir artık, bütün sihri gitmiştir kaleminin.

Ve bunu anladığında; yürek temsilciliği görevini bırakır yazar...

Sıra sizde der, çeker kırar kalemini.

    Yazar aşk ını anlatan yazılar yazmayı bırakır.

Not: 2001 yılında yazdığım bir yazıydı, ve ben hala aşk a, hayat a, kader e dair yazabiliyorum. Buda zamanla olgunlaşan insan için bir cevap; Ne aşk tan geçersiniz, nede o sizden.. Yazmaya ve yaşamaya ne ömür yeter, nede acılardır engel.', 'YAZAR, AŞK I ANLATAN YAZILAR YAZMAYI BIRAKIR... Eğer yazan vazgeçerse bir gün yazmaktan; o gün başka bir şey den  daha vazgeçmiş demektir......', ARRAY['Türk Edebiyatı','Şiir','Ömer Köroğlu']::text[], 8.5, '{"poet":"Ömer Köroğlu","poet_slug":"omer-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yazar-yazmayi-birakir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban Sularda', 'yaban-sularda-muammer-erturan-19lo8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Taşar çerçevesinden

bilmez haddini

okyanus mavisi 

bir bahar

bir sihir

bir esrime

ipe sapa gelmez... 

Arkanı döner dönmez 

hançeri yedin

sen misin yelken açan 

yaban sularda... 

(14 Kasım ''99)', 'Taşar çerçevesinden bilmez haddini okyanus mavisi  bir bahar bir sihir bir esrime ipe sapa gelmez...  Arkanı döner dönmez  hançeri yedin sen...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaban-sularda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Ona Onu Anlatın', 'hadi-ona-onu-anlatin-omer-koroglu-2we61', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni tanışan iki insan bence birbini nasıl anlamaya ve tanımaya çalışmalı biliyormusunuz? 

	İster telefonla, ister karşınızda, ister messenger da  onunla konuşurken, sanki karşınızda bir başkası varmış gibi ona onu anlatın... Hissettiklerinizi, onunlayken neler düşündüğünüzü, o yokken neler çektiğinizi, hani içinize kapanık biriyseniz karşınızda o yokmuş gibi rahat rahat dökün içinizi, göreceksiniz ki sohbet bitip de gerçek kişiliklerinize döndüğünüzde sizin hakkınızda ne düşünüyor ve siz ne düşünüyorsanız ona dair, attığınız adımlar daha bi dikkatli olucak, daha bir yavaş, yada neyi gerektiriyorsa öyle. Bunu daha yeni keşfettim bende. Yani bunu bir dostunuzlada yapabilirsiniz, aşık olduğunuz kişi ilede. Yapmanız gereken, onu ona şikayet etmek, onu ona anlatmak, hani bazı insan vardır içine kapanık tam anlatamaz  hislerini, ima eder ipucu verir ama asla ortaya sermez herşeyi. Belki büyünün bozulmasından korkar, belkide çabucak kaybetmekten...

	İşte bence bunu ona karşınızda başka biri varmış gibi, bir dostunuzla konuşuyormuşsunuz gibi anlatın. O zaman samimiyetiniz ve samimiyeti hemen ortaya çıkacaktır... Hem bize birine olan hislerini anlatan bir dostu özlemedik mi bu zamanda? Dinlemeyi, yol göstermeyi yada ışık tutmayı. Yani bazen sevdiğinizin dostu olun yada sırdaşı... Siz ona sizi anlatın onu başkasının yerine koyarak, oda size sizi. Ve bu sohbet bittiğinde tekrar dönmeyi unutmayın kendi kişiliklerinize. Sohbetin sonunda eminim kiminiz; ''''beni gerçekten bu kadar önemsiyor ve düşünüyormuydu? '''' diyecek, kiminiz ''''onu seviyorum bu düşündüklerinde ötürü'''', kiminizde ''''yanlışın neresinden dönersem kardır''''. Sonucu bir tek siz bilebilirsiniz, o nedenle size bir tavsiye yazdım bu hafta deneyin diye... Zaman geçmeden, ona onu anlatın, oda size sizi başkasına anlatır gibi.

Kalın sağlıcakla', 'Yeni tanışan iki insan bence birbini nasıl anlamaya ve tanımaya çalışmalı biliyormusunuz?  	İster telefonla, ister karşınızda, ister messeng...', ARRAY['Türk Edebiyatı','Şiir','Ömer Köroğlu']::text[], 8.5, '{"poet":"Ömer Köroğlu","poet_slug":"omer-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hadi-ona-onu-anlatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Üzerine...', 'yalnizlik-uzerine-omer-koroglu-oi4b5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşanmıyor işte; insan hapşırdığında dahi yanında ''''çok yaşa'''' diyen biri olmadımı yaşanmıyor...', 'Yaşanmıyor işte; insan hapşırdığında dahi yanında ''''çok yaşa'''' diyen biri olmadımı yaşanmıyor......', ARRAY['Türk Edebiyatı','Şiir','Ömer Köroğlu']::text[], 8.5, '{"poet":"Ömer Köroğlu","poet_slug":"omer-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/yalnizlik-uzerine-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüzlüyüz Hepimiz', 'i-ki-yuzluyuz-hepimiz-omer-koroglu-pl3b7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'iki yüzü vardır insanın; biri dünya, diğeri kendi için...Bir bakın etrafınıza bunu muhakkak sizde farkedeceksiniz..Size en itici gelen erkeğin/kadının onun için ölen bir erkeği/kadını mutlaka vardır. Çünkü, siz onun dünyaya sunduğu yüzünü, o kendisine sunduğu yüzünü görür.Bu nedenle korkar insan insana yaklaşmaya,güvenmeye...Bir kadının/erkeğin kendine sakladığı yüzüne tanık olanlardır onları güzel gören. Aslında bu kadar basitmi acaba çekiciliğin tarifi? Bizim izin verdiklerimiz, kendimize olan yüzümüzü gösterdiklerimiz olmazmı çevremizde? En sevimsiz olarak gördüğümüz biri ailesinde en sevilendir bazen.İşte bu nedenle diyorum; insanın bir kendisine ayırdığı, sakladığı birde dünyaya sunduğu yüzü vardır diye..Birde hakaret sözü olarak kullanırız ''''iki yüzlü'''' diye..Aslında herkes öyle, iki yüzlüyüz hepimiz.. Patron işyerinde elemanına gaddardır, evinde melek, aşık sevdiğine en masum en sevgili  halini sunar, etrafına en mesafeli yanını,vs vs örnekleri siz daha çoğaltabilrisiniz...Dünyanın bile iki yüzü yokmudur? ; yazı kışı,gecesi gündüzü,soğuğu sıcağı....velhasıl hepimiz iki yüzlüyüz bu iki yüzlü dünyada..Birgün kendimize ve seçtiklerimize sunduğumuz yüzümüzü dünyaya sunarız belki umudunu taşıyorum içimde, o zaman daha güzel görünmezmi hayat,daha tatlı gelmezmi yazı kışı, soğuğu sıcağı,gecesi gündüzü.. Daha çok baharı yaşamazmı insan kış ortasında bile...Bence iki yüzlülük kelimesi hakaretler lugatından silinmeli; çünkü hepimiz iki yüzlüyüz,dünyanın kendisi bile...

Kalın sağlıcakla...', 'iki yüzü vardır insanın; biri dünya, diğeri kendi için...Bir bakın etrafınıza bunu muhakkak sizde farkedeceksiniz..Size en itici gelen erkeğ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Köroğlu']::text[], 8.5, '{"poet":"Ömer Köroğlu","poet_slug":"omer-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/iki-yuzluyuz-hepimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayağa Kalkmayı Öğrenmekti Her Düşüşte Yaptığımız', 'ayaga-kalkmayi-ogrenmekti-her-dususte-yaptigimiz-omer-koroglu-0k542', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden düşeriz; tekrar ayağa kalkmayı öğrenmek için değilmi? 

Hayat yolunda her düşüş bizi kimi zaman yıktı, kimi zaman isyan ettirdi, kimi zaman dünyadaki en şanssız adam olduğumuzu düşünmemizi sağladı. Oysa asıl mutluluk ve aheng o her düşüşten sonra kendi başarımızı görüp ayağa kalkmayı deneyecek azmi içimizde hissetmekti. Bunu ya başardık yada bekledik birinin bize elini uzatmasını... Öncelikle şunu kabul etmedik; hayat adil değil, hiç birimiz, hiç bir canlı eşit yaratılmadı. Baışımıza gelenlerde eşit değil elbette. Önce hayatın adil olmadığını kabul etmeliyiz, işine akıl erdirebilldiğiniz bir Tanrı, Tanrı değildir.

Jack Nicholson unun ''''Guguk Kuşu'''' filmini izleyenler varsa hatırlar; Jac Nicholson akıl hastanesindeki çok ağır bir mermer havuzu kaldırabileceğine dair diğer hastalarla iddiaya girer.Yüklenir ve havuzu kaldırmaya çalışır, ama başaramaz. Diğerleri onunla alay ederken, o derki; '''' Ben en azından denedim''''. Şİmdi sormak lazım kendimize biz acaba denedikmi? 

Nasıl istersek, neye karar verirsek hayat orada var.Güneş her sabah günü ve bizi aydınlatmaya devam ediyor, ve umut veriyor her gün bize. Yeterki biz gözümüzü açtığımızda, düşmüş olsakta yere, en büyük derteler bizi sıkıştırmışken bile köşeye; ''''bugün beni günüm'''' diyebilelim.

Her düşüşten sonra, kalkmayı öğrenmekle başlar herşey ve hayatı anladığınızda çoktan gitmiş olursunuz bu yer küreden.

Ömer Köroğlu', 'Neden düşeriz; tekrar ayağa kalkmayı öğrenmek için değilmi?  Hayat yolunda her düşüş bizi kimi zaman yıktı, kimi zaman isyan ettirdi, kimi z...', ARRAY['Türk Edebiyatı','Şiir','Ömer Köroğlu']::text[], 8.5, '{"poet":"Ömer Köroğlu","poet_slug":"omer-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayaga-kalkmayi-ogrenmekti-her-dususte-yaptigimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postacı Amca', 'postaci-amca-omer-koroglu-md7yg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'PTT nin 165. yılını kutladı  postacı amcalarımız geçtiğimiz hafta..Yıllar öncesinden hatırladıklarım var; sokağın başında göründüklerinde koşup '''' bizim eve mektup varmı? '''' diye sorduğumuz yıllar...Her postacı ezbere bilirdi kimin nerede oturduğunu ve bütün aileyi..Bazen o çağırırdı '''' al bu size '''' diye uzatmak için o zarfı.Geçen zaman teknolojiyi geliştirdi,önce cep telefonuna alıştık,sonra internetten elektronik posta göndermeye.Ellerinde kocaman, bir yığın mektupla insanları sevindiren postacı amca 21.yüzyılda sevdiklerimizin ''''satırlarıma başlamadan önce herkese selam eder....''''diye başlayan mektupları yerine, kredi kartı ekstreleri ve bilumum farklı resmi evraklar iletir oldular bize.Oysaki ne güzeldi o yıllar, sokak başında güzel haberler beklediğimiz postacı amcanın varlığına inanmak, '''' gurbetten mektup gelecek evden ayrılma '''' diye ana babalarımızın bizi sıkı sıkı tembihlemesi..Velhasıl unuttuk mektuplaşmayı,zaman kalmadı yazmaya..Oysa ne güzeldir beyaz sayfadaki kara kalemle yazılan sevdiğiniz birinin sadece size anlatması içini ve açıp açıp tekrar okumak.Siz hiç mail box ınıza gelen bi elektronik postayı kokladınızmı,onun kokusu var diye? Mektuplar buram buram o kokardı, onun elleri değimişti en son o sayfaya..Ya asker ocağında herkesin ismi söylendiğinde, o hafta mektup alamayan bir askerin, adının okunmadığında neler hissettiğini bilirimisiniz? Peki sizin için yazılmış bir mektubu okurken ne hissediyorsunuz? İçiniz titremiyormu o satırları okurken? Ünlü bir düşünüre dünyanın en değerli şeyi nedir diye sormuşlar; kısa ve net vermiş cevabı; ZAMAN dır diye..Sizin için dünyadaki en değerli şey olan zamanını harcayan birinin satırları sizi mutlu etmiyormu? ediyor değilmi...E peki neden sizde birilerini mutlu etmiyorsunuz! Bakın geçmişte o kadar yaygınmışki mektuplaşmak; Portekiz''deki Aveiro ve ABD''deki Notre Dame üniversitelerinden araştırmacıların yürüttüğü çalışma, İngilizlerin Nature dergisinin son sayısında yayımlamış. Çalışmaya göre, 1809 ile 1882 yılları arasında yaşayan Darwin, hayatı boyunca 7 bin 591 mektup yazmış, 6 bin 530 mektup almış. 1879 ile 1955 yılları arasında yaşayan Einstein ise 14 bin 500''den fazla mektup yazıp, 16 bin 200 mektup almış. 

Araştırmaya göre, her iki bilimadamı, gelen mektuplara 10 gün içinde cevap yazıyormuş. 

Şimdi bu yazıyı okuduktan sonra eliniz kalem ve beyaz bir sayfa arıyorsa tutmayın kendinizi, bir yerlerde sizden gelecek tekbir satır söz,koku ve ten-izinizi bekleyen birileri mutlaka vardır değilmi..Hem postacı amca da özledi o günleri...', 'PTT nin 165. yılını kutladı  postacı amcalarımız geçtiğimiz hafta..Yıllar öncesinden hatırladıklarım var; sokağın başında göründüklerinde ko...', ARRAY['Türk Edebiyatı','Şiir','Ömer Köroğlu']::text[], 8.5, '{"poet":"Ömer Köroğlu","poet_slug":"omer-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/postaci-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar gelmiş.', 'yar-gelmis-i-shak-ozlu-wd1zo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vuruldum annem canım yanıyor,

Kara toprağa kanım akıyor.

Kanayan yaram değil yüreğim,

Yare hasret yoluna bakıyor.

Sarıldım annem sonum geliyor,

Cankuşum bedeni terk ediyor.

Yalnız değilim üzülme annem,

Yar gelmiş yanıma el veriyor.', 'Vuruldum annem canım yanıyor, Kara toprağa kanım akıyor. Kanayan yaram değil yüreğim, Yare hasret yoluna bakıyor. Sarıldım annem sonum geliy...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yar-gelmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun Ustune', 'onun-ustune-yasar-gurlek-t24fo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onun  Ustune		

Bir guzele  gonul verdim      		

Bir optum  birde sevdim         		

Seni seviyorum dedim             		

Askim hep  onun  ustune          		

		

Zulufleri    tel  tel olmus		

Gul rengi sararip  solmus  		

Ahu  gozleride  dolmus		

Derdim hep  onun ustune		

		

Al yanaklar  bogum  bogum          		

El degmemis  meyva  bagim       		

Mor sumbullu guzel  dagim         		

Acim hep onun ustune              		

		

Kara  kaslim surme  gozlum		

Bal dudaklim tatli sozlum		

Sen uzulme  ahu  gozlum		

Derdim hep  onun ustune		

		

Ak gerdani  ak  ak  olur		

Ak  gerdan da benler durur         		

Gozlerimde  yaslar  kurur               		

Askim hep onun ustune                		

		

Boyu   selvi  fidan  gibi		

Yurumesi  ceylan gibi		

Yaktin beni seni gidi		

Acim hep onun ustune		

		

Sazim alip  daga  ciktim           		

Cikipta  yuksekten baktim           		

Gayri  bu canimdan  biktim           		

Derdim hep onun  ustune                		

		

Bulbul  kondu  sag  yanima		

Nidasi  girdi  canima		

Leke  surdurmem  sanima		

Derdim hep onun  ustune        		

		

Sazim ince  kalin telli                   		

Yarim antep urfa  elli                       		

Bal dudakli  seker  dilli                 		

Derdim hep onun ustune              		

		

Cevizdendir  dertli  sazim		

Cekilmezki  senin  nazin		

Kiz  yerim dilin  agzin		

Derdim  hep  onun  ustune		

		

Tezenem kiraz  dalindan		

Yenmezki seker  balindan 		

Meyveni topladim bagindan 		

Derdim hep onun ustune		

		

YASAR  GURLEK		

1-3-1992		

LEIDEN/HOLLANDA', 'Onun  Ustune		 Bir guzele  gonul verdim      		 Bir optum  birde sevdim         		 Seni seviyorum dedim             		 Askim hep  onun  ustu...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/onun-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O benim işte', 'o-benim-iste-yusuf-pekol-d07sh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deniz vurur ya

Deniz kabuklarını kıyıya

Deniz kabuklarında yiten

         O sesim işte

Hani balıkçı atar ağını

Çekince tekneye

Son nefesini veren

         O balığım işte

Denize tutkun balıkçıyım

Denize vurgun balığım

Denizim, balığım, balıkçıyım

         O benim işte', 'Deniz vurur ya Deniz kabuklarını kıyıya Deniz kabuklarında yiten          O sesim işte Hani balıkçı atar ağını Çekince tekneye Son nefesini ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-benim-iste-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Yamalak', 'yarim-yamalak-muammer-erturan-w5olp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarım kalan birşeyler... 

Dile gelmeyen 

ele gelmeyen 

elden gelmeyen ya da 

dilinin ucuna 

gelip gelip de... 

Yarım kalan birşeyler... 

Bilmezden gelinen 

bilinmeze giden

bam telinden nağmeler... 

Ne inkâr eden var 

ne bir ikrar... 

Yarım kalan birşeyler... 

Yarısı sende saklı

yarısı bende 

iki yakası bir araya

gelirse ancak 

ok yaydan çıkacak... 

Yarım yamalak bi’ şey... 

(''98)', 'Yarım kalan birşeyler...  Dile gelmeyen  ele gelmeyen  elden gelmeyen ya da  dilinin ucuna  gelip gelip de...  Yarım kalan birşeyler...  Bil...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarim-yamalak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski resimdeki', 'eski-resimdeki-yusuf-pekol-e2yfl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerime takılan

Puslu, silik, eski bir resimde

Sen vardın.

Boyaların, değişmişti renkleri.

Seçilmiyordu saçlarının karası.

Gözlerinin yeşili soluktu.

Güleç yüzün üzgündü.

Yoktu güzel günlerin umut ışıltıları.

Ellerin çatlamıştı, sanki kırışmıştı.

Saçların kıvır kıvır değildi.

Sanki, sanki

O resimdeki sen değildin.

Belki de

O resme bakan 

Ben değildim.', 'Gözlerime takılan Puslu, silik, eski bir resimde Sen vardın. Boyaların, değişmişti renkleri. Seçilmiyordu saçlarının karası. Gözlerinin yeşi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eski-resimdeki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tasiyamam Bu aski 1991', 'tasiyamam-bu-aski-1991-yasar-gurlek-0unti', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benden    aski   degil,   omrumu  iste

Benden    aski   degil,   canimi     iste

Benden    aski   degil,   ruhumu   iste

Tasiyamam bu aski, kalmadi derman

Omrum   hep   cileyle,   gecipte  gitti

Felek    dostlarini   bak,   nasil   secti

Kahrolasi   kader,    boynumu    bicti

Cekemez bu beden, kalmadi  derman

Soldu    bahcemin,     gonca     gulleri

Otmez       oldu,       sen      bulbulleri

Sense        mesut        ettin,        elleri

Yuklemez bu  beden, kalmadi derman

Yaklasma    bana,     derle    doluyum

ALLAH,in   bi    care,  aciz  kuluyum

Pala   biyik,    mehmedin     ogluyum

Yuk  almaz bu beden, kalmadi derman

Kimler       halime,      hep    gulmediki

Yasari   bu   hallerde,  kim   gormediki

Kahrolasi   bu   beden,   bir    olmediki

Yasiyamaz  bu  beden, kalmadi  derman

YASAR  GURLEK

30-12-1991

LEIDEN

HOLLANDA', 'Benden    aski   degil,   omrumu  iste Benden    aski   degil,   canimi     iste Benden    aski   degil,   ruhumu   iste Tasiyamam bu aski, ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tasiyamam-bu-aski-1991-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Özgürlük Olan', 'adi-ozgurluk-olan-yusuf-pekol-rpy29', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ö-püp kokladığım ekmek kadar kutsal

Z-erresine kadar değerli, önemli, güzel

G-ençliğin tadı, tuzu, kanı, herşeyi

Ü-zengisiz ata binmek gibi çılgınca

R-üzgar kadar hızlı bir duygu

L-ale, gül gibi kan kırmızı belki de

Ü-zerine yağan al yağmurun arasında

K-endin bul, kendin al, adı ÖZGÜRLÜK olan...', 'Ö-püp kokladığım ekmek kadar kutsal Z-erresine kadar değerli, önemli, güzel G-ençliğin tadı, tuzu, kanı, herşeyi Ü-zengisiz ata binmek gibi ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adi-ozgurluk-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Ağlıyordum', 'ama-agliyordum-yusuf-pekol-cvsq2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Görmüyordu gözlerim o an olanları

Diz çökmüştüm, başım iki kolum arasında

Sessizce ağlıyordum

Yanıyordu umutlar, yanıyordu yarınlar

Ölüyordu mutluluklar

        Ama ben ağlıyordum...

Sessizliği deliyordu 

İpince bedenleri deliyordu 

Gökte kuşlar bile uçmuyordu

        Ama ben ağlıyordum...', 'Görmüyordu gözlerim o an olanları Diz çökmüştüm, başım iki kolum arasında Sessizce ağlıyordum Yanıyordu umutlar, yanıyordu yarınlar Ölüyordu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ama-agliyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '20ytl Hayal', '20ytl-hayal-yusuf-pekol-etmum', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cebimde 20ytl param var

20 dakika sonra gidip

20 duble içki içeceğim

her dublede 20 hayal kuracağım

Yaşadığım her 20 yıla söveceğim

Elini tuttuğum 20 kızı anımsayacağım

Belki de 20 duble yetmeyecek

Birkaç duble daha isteyeceğim

Ama param yetmeyecek

Belki de dayak yiyeceğim

Biraz da kan kusacağım

Bir köşede sessizce ağlayacağım

Ama vazgeçmeyeceğim

Umut etmekten

Duble duble, şişe şişe...', 'Cebimde 20ytl param var 20 dakika sonra gidip 20 duble içki içeceğim her dublede 20 hayal kuracağım Yaşadığım her 20 yıla söveceğim Elini tu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/20ytl-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Buldum', 'oyle-buldum-yusuf-pekol-qqgar', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceler karanlıktı, ay yoktu, yıldızlar sönmüştü

Güneşleri çalınmış, gökyüzü karartılmış

   Umutları sökülüp atılmış, yüreklerinden

   Taptaze fidanlar sökülmüş toprağından

Çakmak çakmak gözler yaşla dolmuş

Sokaklar sıcak, kırmızı kana bulanmış

Analar kundaksız, bebeler kucaksız

Güzelim yurdumda neler olmuş

   Ama ben yapmadım       hiçbirini

   Öyle buldum     herbirini...', 'Geceler karanlıktı, ay yoktu, yıldızlar sönmüştü Güneşleri çalınmış, gökyüzü karartılmış    Umutları sökülüp atılmış, yüreklerinden    Tapta...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oyle-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liceliyim', 'liceliyim-yusuf-pekol-az1qd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O karanlık uzayın derinliğiyim

O yitik hayatların parçasıyım

O boz coğrafyanın insanıyım

O esir tarihin sayfasıyım

            Ama yine de

O karanlığa ışığım

O hayata umudum

O coğrafyaya yeşilim

O tarihe asaletim

            Çünkü ben

     Liceliyim....', 'O karanlık uzayın derinliğiyim O yitik hayatların parçasıyım O boz coğrafyanın insanıyım O esir tarihin sayfasıyım             Ama yine de O...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/liceliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Kalbim', 'buz-kalbim-yusuf-pekol-stloq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Avucumun ortasına düşen bir ateşti ölüm

Önce parmaklarımı yaktı yavaş yavaş

Kollarımdan bedenime yayıldı

Gözlerim görmez oldu, kulaklarım duymaz

Hissizleşti duyularım birer birer

Ama birden bire söndü ateş

Tam da kalbimdeydi sıra

Ama kalbimdeki buzları eritmek

Ateşe bile fazla gelmişti.

Çünkü ayrılığınla buz tutmuştu

Erimedi

Tüm bedenim yandı

Bir tek kalbim kaldı...

O da 

          Donmuştu zaten çoktan...', 'Avucumun ortasına düşen bir ateşti ölüm Önce parmaklarımı yaktı yavaş yavaş Kollarımdan bedenime yayıldı Gözlerim görmez oldu, kulaklarım du...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pekol']::text[], 8.5, '{"poet":"Yusuf Pekol","poet_slug":"yusuf-pekol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/buz-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında....', 'aslinda-rifat-gursoy-c310n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün oldu

Mutluluklar istedik kendimize haketmediğimiz

Güller kokladık dalından hoyratça koparıp

Nice urbalar giydik içinde höl döndüğümüz

Yakıştırdık yüzümüze bardabaş gülümsemeleri

Gün geldi

Gülüyoruz sandık yürekten

Ve yüzleşmelerden kaçındık yıllarca

Anladık ki mutluluk değil yüzüne güldüğümüz

Aslında 

Belimiz sadece büktüğümüz

Kök söküp,kök söktürdüğümüz

Bir ömre karşılık geldi,heder edip gittiğimiz', 'Gün oldu Mutluluklar istedik kendimize haketmediğimiz Güller kokladık dalından hoyratça koparıp Nice urbalar giydik içinde höl döndüğümüz Ya...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Gürsoy']::text[], 8.5, '{"poet":"Rıfat Gürsoy","poet_slug":"rifat-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aslinda-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emek', 'emek-gokhan-oflazoglu-bs4rx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Emek vermeden aşk mı olur,

seni sürükleyen sana yar mı.

Önemsemen, önemsenmen,

dar gününde el veren, tutkuyla

sökenden daha can olur.

Ürettiğin, paylaştığın, anladığın

anlaşıldığın, itkilerin aşkından

değerli olur.

Görebilseydin eğer, emek

verdiğinde aşkın taç olur.

Kuru heyecanla akan su kurur.

27/02/2006', 'Emek vermeden aşk mı olur, seni sürükleyen sana yar mı. Önemsemen, önemsenmen, dar gününde el veren, tutkuyla sökenden daha can olur. Üretti...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/emek-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Robin Sonat´ı', 'robin-sonat-i-sevinc-kavuk-ngh44', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Robin sonatının ütopi evveliyatı 

Ütopi sahilinin yakınında yatan

Yenik vapur harabesi.

Ama Robinson 

Karada yeteneğini öğrenmeye de 

kendini kurtarıyor.

Batan bilginin kargosuydu

Ancak onun yeteneği rejenere olabilirli

Gustav  Württemberg

Kış 1999 (Çevirilerimden)', 'Robin sonatının ütopi evveliyatı  Ütopi sahilinin yakınında yatan Yenik vapur harabesi. Ama Robinson  Karada yeteneğini öğrenmeye de  kendin...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/robin-sonat-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Dünyalar (*)', 'baska-dunyalar-sevinc-kavuk-6tzrj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuk savaştan sonraki harita ve paradigmalarda

Bu dünya politikasının resmi; 

kültürel faktörlerden belirgin

iç aksiyonlarıyla ülkeler ve gruplar 

değişik kültürlerden içerli

oldukça basite indirgeli

çok şey barındırılı

kimini genlemiş 

çoğunu karartmış...

buna rağmen ihtiyaç var

dünyayı gerçek düşünürsek

içinde etkili eylemlemek istiyor isek

bir tür basitleştirili bir haritasını gerçeğin

bir teori, bir konsept, bir model, bir paradigma…

Başka dünyalar….

Mart  1999 

Irak savaşı korkusuyla titrerken', 'Soğuk savaştan sonraki harita ve paradigmalarda Bu dünya politikasının resmi;  kültürel faktörlerden belirgin iç aksiyonlarıyla ülkeler ve g...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baska-dunyalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Kolay Gelmiş Ayrılık', 'kime-kolay-gelmis-ayrilik-yavuz-bayram-caliskan-09e71', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsimsizliğinde sevgilerimiz,

Gözlerimizde, karanlıklarda yosunlandı.

Rüzgârlardan kaçıp, duldalara gizlendi.

Güneş hasrete doğdu, dolunay kadere,

Uyuyamadık, geceyi dipledik.

Vuslatı yıldızlara bıraktık,

Ne dolunaya bakabildik,

Ne de bedenlere.

Gökkuşağı hayallerle süslü,

Gözlerimizi yıldızlara gönderdik

İmkânsız sevdalarla.

 Diyebilen var mı? 

Kime kolay gelmiş ayrılık.

Tutsaklığından mı bilinmez,

Yürünmez yollardayız,

Ayrı yollarlara gidilirse

Söyleyin aynalar? 

Kime kolay gelmiş ayrılık.

Arkamda saklanır hayat,

Bir yürüsem, ah bir yürüsem,

Gönül vermek yakmıyor da,

Ayrı yollara gitmek yakıyor.

Bakmayın yüzüme,

Kime kolay gelmiş ayrılık.

Bu nefes verildiğinde alınmayacak,

Dünya denen mekanda kalınmayacak,

Bu aşk yıllarla bilinmeyecek,

Yarası benden hiç silinmeyecek,

Söyleyin dostlar,

Kime kolay gelmiş ayrılık.

Ay buruk, gül yalnız,

Rüzgar deliliğini savurmakta,

Kelebek yalnızlığına kanatlanır,

Nehir akmakta zehirlerle,

Gök yıldırımlarına sarılır,

Bir sevgili kaybolur,

Gün zehrine akşam olur,

Diyebilen var mı? 

Kime kolay gelmiş ayrılık.

http://www.geocities.com/siirhan68/', 'Mevsimsizliğinde sevgilerimiz, Gözlerimizde, karanlıklarda yosunlandı. Rüzgârlardan kaçıp, duldalara gizlendi. Güneş hasrete doğdu, dolunay ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kime-kolay-gelmis-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Gölgesi', 'hayatin-golgesi-mehmet-sait-akkus-7dhk2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalın ayak yürürü iken

Ayağıma battı diken

Soğuktan titrer iken

Yalnızlığa sarılırım

Anam babam size ömür

Abi kardeş başka yoktur

Ecel gel benide götür

Ben yalnız kaldım Allahım

Anne baba hasretini

Onlardaki özlemimi

Onların eksikliğini

Allah kimseye vermesin

Dertler bende katar katar

Dert girdabı beni yutar

Beni sokaklara atar

Yalnızlığa ağlıyorum

Sular gibi akar oldu

Hayat beni hep yoğurdu

Dağ bile fare doğurdu

Yalnızlığa ağlıyorum

Anne baba arar oldum

Onları arayıp durdum

En sonundada umudum

Mekanları cennet olsun

Bunca yükü omuzuma

Taşıyorum bir başıma

Bakma benim yaşıma

Neler çektim bilki neler

Hayat öyle çekilmezki

Bir defada çizilmezki

Tek başına gidilmezki

Acılara gididyorum

Benim aldığım nefesi

Tüketti hayat gölgesi

Buradan gayri ötesi

Ne olursa olsun artık

Dertlerimi paylaşacak

Karşılıklı konuşacak

Dertlerimi boşaltacak

Bir arkadaş arıyorum', 'Yalın ayak yürürü iken Ayağıma battı diken Soğuktan titrer iken Yalnızlığa sarılırım Anam babam size ömür Abi kardeş başka yoktur Ecel gel b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hayatin-golgesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Sevdalar...!', 'sahte-sevdalar-hasan-basri-kale-idwhv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gün; 

coşar sevdanın seli

çok farklı olduğunuz söylenir..

gün gelir 

eser sevdanın yeli

melek olduğunuz söylenir..

er geç 

yüzlere yayılır sahte gülümsemeler

o gün

kopar sevdanın sihirli eli

gözlerinizin içine bakılıp

utanmadan 

hala yalan söylenir...', 'bir gün;  coşar sevdanın seli çok farklı olduğunuz söylenir.. gün gelir  eser sevdanın yeli melek olduğunuz söylenir.. er geç  yüzlere yayıl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sahte-sevdalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortadoğu Çocukları', 'ortadogu-cocuklari-umut-beylik-w628m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırpılmıs düşleriyle,

Hayallere daldılar.

Kimsesizdi Ortadoğu cocukları.

Dünyanın her metrekaresinde,

Dudaklarında,

Kanlarını tattılar.

Hep aynı kaderlere yazılmıstı siperleri.

Mardin''de terörist dediler,

Babasıyla geceye vurgun ettiler canını.

Filistin''liydi dünyanın celladı cocuk.

Çok kan akıtmıstı 

belki,

İsrail''e,Amerika''yada kafa tutan oydu 

Hamasın kurucusuydu belki de

Mermi sesleri acımadı 

Mahsun korkusuna,

Babasinin ardina gizlenmişken vurdular düşlerini,

Bir baba çığlığında! ! ! ! ! ! ! 

Birer-birer cephe kaybetti bu çocuklar.

Her seyi bir oyun sanmısken 

Tüm savaşlara

Kan kusmuşken

Susarak vuruldular.', 'Kırpılmıs düşleriyle, Hayallere daldılar. Kimsesizdi Ortadoğu cocukları. Dünyanın her metrekaresinde, Dudaklarında, Kanlarını tattılar. Hep ...', ARRAY['Türk Edebiyatı','Şiir','Umut Beylik']::text[], 8.5, '{"poet":"Umut Beylik","poet_slug":"umut-beylik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ortadogu-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilesin Gönlüm', 'bilesin-gonlum-hasan-ulusoy-zz1ix', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eyvah gönül bu yol seni çekiyor

Gam dağına yolun düşer bilesin.

Dert ehliyim diye derdi yüklenme,

Dert vurunca tebdil şaşar bilesin

Güneşi akşama satan bu devran

Varlığı yoklukta yutan bu devran

Yokluğu yoklukta tutan bu devran

Ol diyen ol derse yaşar bilesin.

Gam ilinde nice yanık yürek var

Gam bilmeze gönüle ne gerek var

Dünya tatlı yenilen bal börek var

Damak tutmaz diş de düşer bilesin

Acısı gönüle düşer bilmezsin

Yol kırılır yolcu düşer bilmezsin

Her yaratık fani beşer bilmezsin

Yer kudurur volkan taşar bilesin

Kıyameti vaad eyler yaratan

Kuranda vaadini söyler yaratan

Zalim değil zulmü neyler yaratan

Herkes çukurunu eşer bilesin...', 'Eyvah gönül bu yol seni çekiyor Gam dağına yolun düşer bilesin. Dert ehliyim diye derdi yüklenme, Dert vurunca tebdil şaşar bilesin Güneşi a...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ulusoy']::text[], 8.5, '{"poet":"Hasan Ulusoy","poet_slug":"hasan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilesin-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşerde Bile Bekleyeceğim Seni', 'mahserde-bile-bekleyecegim-seni-huseyin-erdogan-el9na', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yıllar sonra sende buldum

aşkı sevgiyi

sensin benim sevincim

inan ki bir tek sensin

yüreğimi ısıtan sabah güneşim

demek ki ben bu güne değin

boşuna yaşamışım senden önceyi

şiirim bir kez daha anladım ki

meğer senmişsin

benim bu dünyadaki tek eşim

bence gonca bir gülsün sen

ah! ömrümce bir tek benim için

her sabah rengarenk açıversen

şırıl şırıl sevgi akan yüreğimden

ebediyen kana kana içiversen

senin hasretin günden güne

yakıp kavursa öldürse de beni

sevdiğim sevgili şiirim bil ki

mahşerde bile bekleyeceğim seni

                               27.02.2006

                           Hüseyin Erdoğan', 'yıllar sonra sende buldum aşkı sevgiyi sensin benim sevincim inan ki bir tek sensin yüreğimi ısıtan sabah güneşim demek ki ben bu güne değin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mahserde-bile-bekleyecegim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-serdar-ahmet-guzel-b0y6e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur damlaları vuruyor

Pencereme

Geçmişe dair bir şarkı söylüyor

Gidenleri, geçmişi

Dinliyorum mırıltılarını

Yavaş yavaş beni bitiren sessizliğini

Düşünüyorum 

Varlar mıydı? 

Yoksa ben hayal mi görmüştüm 

Kalbim neden böyle çarpıyor

Beynim neden kâbuslar görüyor

Varlar mıydı? 

Yoklar mıydı? 

Belli değildi…

26.02.2006 saat:02.10', 'Yağmur damlaları vuruyor Pencereme Geçmişe dair bir şarkı söylüyor Gidenleri, geçmişi Dinliyorum mırıltılarını Yavaş yavaş beni bitiren sess...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yagmur-271-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşi Bulan Hazret', 'atesi-bulan-hazret-muammer-erturan-micvt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ateşe uzak kalmak 

netameli işti

hele ki gecelerinde kışın, 

yakın olmaksa 

yakın olmak demekti 

hayata ve aşka... 

Ne kıyametler koptu 

ne kavgalar çıktı 

ne canlar yandı yıllar yılı 

yer kapma uğruna... 

Ve kan dökmektense habire 

resmiyete döküldü iş 

en nihayetinde... 

Ancak 

sığdırmak ne mümkün 

resmi kılıfa aşkı... 

Çıkmaması kınından 

aşmaması duvarları inadına 

ve doğmaması ihanetin 

resmiyetin yanı sıra 

eşyanın doğasına aykırı... 

Sanık ayağa kalk! 

Lehinde tanıklık eden 

çıkmadı bak! .. 

Eldeki deliller desen 

aleyhinde hep... 

İhanetler tarihinin de 

ateşleyicisi olmaktan sebep 

suçlu bulundun... 

Hafifletici sebepler 

göz önünde bulundurulmak 

ve temyiz hakkın saklı kalmak 

kaydıyla elbet... 

Sana söylüyorum heeey! 

Ateşi bulan hazret! .. 

(''97)', 'Ateşe uzak kalmak  netameli işti hele ki gecelerinde kışın,  yakın olmaksa  yakın olmak demekti  hayata ve aşka...  Ne kıyametler koptu  ne ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/atesi-bulan-hazret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çift Varlıklı Olmak', 'cift-varlikli-olmak-sevinc-kavuk-jcn9l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazmak çalışmaktır

Anlatabildiklerinde anlaşılmak

İlk şart: hissedilmeli okurlarca

içinden geçenler anlaşılabilmeli

ikinci şart: gerçekten yazmalı,

“yazıyor olmalı”lık ama bir yetersizlik

üçüncü şart: çok çalışmalı

her gün yeniden şekil vermeye

her gün bir cümle yazabilmeli

ve buna belirli ölçekte yetenekte olmalı

ancak o zaman bu en güzel ve en zor sanata

alıştırma yapabilmeli öylesine 

yalnız, yapayalnız, hiç kimsesiz, ıssız, sessiz, çorak,

ki kelimenin özgürlük anlamını vurgulayacak kadar….

Hür bir şeyden hür bir şeye! 

Her yetenek geliştikçe daha da yoğunlukla! 

Bir gün alıştırma yapmasam ben hissediyorum

İki gün çalışmazsam, arkadaşlarım hissediyor

Üç gün olursa bu tembelliği dinleyiciler hissediyor… 

diyor piyanist Franz Liszt

Sıkı ve gergince lisanla ilgilenmeyi bilmeli…

aklım bana güç ver 

ne çok meslek alanlarıyla ilgilendim

böylesine çatır çatır çatlamadım…

zihnim imdattı bana ilgim ve sabrım

bu bir hastalık boyutu bile değil

üstelik çifte varlık olmaklık! 

Yazmak mantığa ders vermek değil

Veya anlamları cicileştirmek

Daha çok kelime sanatıyla

Ruhu öyle rahatlatmalı

Güven çemberine almalı ki

Bir intelektüel ve olgun fantaziyi

Bir gerçekte (veya bir yalanda)     bulabilmeli

ki o, çıplak anlatımın geçmişinde yatıyor…

her kelime ve her cümle onun hışırtı ve tınısı, 

gelgit''i denizin, eğlenirken dinlenmesi, kahkahası, 

şarkı gibiliği her ritmi lisanın, bunlar araçlarıdır

hayranlığı uyandıran ve hayran eden

yazan hep şimdi burda 

yine ama orda şaşarlığı değil

okumuş bir gezgin olmalı görevi

giderken az konuşanı anlamlatan

tahmininden de az ve yine de fazla hayal edebileceğinden…

Thomas Mann şunu anlıyor

“Doktor Faustus”da bir çocuğun ölümü

“tıbbi olarak ölü” evet çok acı

Yine de bu çocuğun ölümünü 

acı üstü algıladı -o onun torunuydu…

Çift varlıklı olmak

Bunu anlayabilmeye mi gerekli diye de sorulmalı….

27 Şubat 2006', 'Yazmak çalışmaktır Anlatabildiklerinde anlaşılmak İlk şart: hissedilmeli okurlarca içinden geçenler anlaşılabilmeli ikinci şart: gerçekten y...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/cift-varlikli-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avrupa Tarihini', 'avrupa-tarihini-sevinc-kavuk-28sgx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Avrupa tarihini öykü olarak öyle tanımlamalı ki 

Bağlantıları anlaşılıyor olmalı…

Aynı zamanda edebiyat, sanat, müzik, felsefe ve bilimle de uğraşılı ki, onun konstrüktünün serinkanlılığı, anlaşı bulabilmeyi başarmalı ve algılamaya başlayabilindi, ki bu dünyaya bakış açımızı tamamen değiştirebilir ve bizi yeni bir insan yapabilir de…

böylesine canlı bir bilgi ögrenimi orantısı kazanmaya bir şey gerekiyor:

tüm şakşaklı övgülükler, empoze efektleri 

ve sisli anlamları yok etmeli

tüm yazarlarına saygısızlık kırılmalı

formül panzerinden çıkartılmalı

hem yeni bir lisansal masaja bırakılmalı

herkesin anlayabileceği bir amaçla elbette

ve istediği kadar da anlayabileceğine…

eski öğrenim biçimleri ne yabacıl ve formüllerde donuklaşmış, kendimizi de geliştirdiğimizden kültürel bilgimizi yeni bu ortamında yine dile getirebilmeliyiz ki, bunu bugüne kadar öğrenim sistemiyle bocalamış olanlar da istiyor…

öğrenciler ve o insanlar ki, müzeleşmiş bilgi çöplüğüne imtina edenler, çünkü, onların algılama organları kendi toy yaşamlarından oluşulu denilenler…kültürümüze, bilgilerini artırmayı konuşmak için de olsun diyen bir nesil olmak isteyenler... keşke bırakabilsek onlara bu hürriyeti…

onlar için düşünülü bu tür yeni tarih kitapları

kendi yarınlarına kutlu olsun! diyen dilim ısırıyor...

Irak savaşı korkusuyla titrerken hop eden aklımı

Mart  1999', 'Avrupa tarihini öykü olarak öyle tanımlamalı ki  Bağlantıları anlaşılıyor olmalı… Aynı zamanda edebiyat, sanat, müzik, felsefe ve bilimle de...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/avrupa-tarihini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hoş Olur', 'ne-hos-olur-sevinc-kavuk-eao8w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnanması ne hoş olur

Öğrenmeden öğretilmeden 

her yazının bir eser olması

çünkü doğallığı gibi tarladan ve ormandan

ve çimenlerden yeşerdiğini sananlar

şikayette etmesinler ki

ülkemiz daha fazla tarla, orman, çimenli

ve bilgiyi yazarları daha çok ortaya çıkıyor

başka ülkeler gibi…

(her ülke, tuhaf, böyle söylüyor! Ben de işte)   

Ki o ülkelerde olağanüstü oditoryumlarda

Üniversitelerin ve ne çok başka enstitülerin olağanüstü ciddi

Pratikten de öğretildiği ve öğrenildiği…

Şair süperliği yaratmak, şekil bilmek her çiftleyişinden

Anlatanın anlatılan sanatından

Tiyatronun, filmin, radyo- ve televizyonun

Yazmanın bölüm ve senaryosunu birlikte okumak 

ve ya bir elitler birliği varlığı ne hoş olur bu zamana...

27 Şubat 2006', 'İnanması ne hoş olur Öğrenmeden öğretilmeden  her yazının bir eser olması çünkü doğallığı gibi tarladan ve ormandan ve çimenlerden yeşerdiği...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ne-hos-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kareler', 'kareler-muammer-erturan-dshic', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hızla solan renkler

hızla suskunlaşan sesler 

hızla kokuşan dünya

hızla kopuşan insan

hızla kaçan tadı yaşamın... 

Yaşamak dedimse

bir film izlercesine 

izlemek sadece yani 

uzakça bir locadan... 

Olan olmuş 

biten bitmiş 

giden gitmiş çoktan 

silinmeye yüz tutmuş izler… 

Beklentisiz bir bekleyiş 

hüküm sürmekte... 

Ve hızla eskimekte kareler...

(''99)', 'Hızla solan renkler hızla suskunlaşan sesler  hızla kokuşan dünya hızla kopuşan insan hızla kaçan tadı yaşamın...  Yaşamak dedimse bir film ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kareler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asılıyorum Küreklere', 'asiliyorum-kureklere-hatice-bediroglu-a4s4v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Islak maviler yolluyorum 

Kanatlarında poyrazın 

Arıyorum sıcaklığını 

Bir yudum çayda 

Soğuk geçiriyor dişlerini 

Sıska yanaklarıma 

Kesiyor acı...

Dilim dilim bedenimi 

Bir bir çıkarıyor gözlerimden 

Dalına tutunamamış yaprak gibi 

Savruluyorum bağrına Akdeniz’in

Mavisine yansıyor gözlerin 

Gözlerinden yüreğine 

Ha babam... 

Asılıyorum küreklere

Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 -

www.haticebediroglu.net', 'Islak maviler yolluyorum  Kanatlarında poyrazın  Arıyorum sıcaklığını  Bir yudum çayda  Soğuk geçiriyor dişlerini  Sıska yanaklarıma  Kesiyo...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asiliyorum-kureklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siromansi''ye Subat Fisiltisi', 'siromansi-ye-subat-fisiltisi-cigdem-yorgancioglu-9dd0m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tutmuşsa elin elimin parmaklarını 

Kırmışsa kalbin beynimin kararını 

Açık denizlerdeki o fay hatlarını 

Dagitirsam kim toplar fayın  parçalarini 

Denizcinin denizkızı  yaralarını 

Kuşların o mucizevi göç yollarını 

Kararla kırılan kalemin uçlarını 

Dagitirsam kim toplar ucun  parçalarini 

İçimdeki çocuğun,bembeyaz karını 

kilere kilitlenmiş  oyuncaklarını 

Ve bugüne hiç varamamış bir yarını 

Dagitirsam kim toplar çocuk parçalarini 

Sen orkideye gizlerken masallarını 

Nasıl da sakladım o siyah saçlarını 

Nasıl yasakladım bize biz kararını 

Dagitirsam kim toplar bizin  parçalarini 

Tanıklığım var bildim göz çapaklarını 

Uyurken  gördünmü sen gözkapaklarını 

Unutmam o çeşm-i siyah bakışlarını 

Dagitirsam kim toplar senin parçalarini 

Ölesiye aşkların varsa bir yarını 

Yaşayan aşk üstüne eğip dudağını 

Atamaz hiç kimse toprak yığınlarını 

Dagitirsam kim toplar toprak parçalarini 

Olurda unutup bugünden o yarını 

Kaybetsin diye kararlılık yollarını 

Açarsam o orkidenin yapraklarını 

Dagitirsam kim toplar yaprak parçalarini 

Çırpınmaktan yorulan o kanatlarını 

Düşürsem ve çizsem siyah hatlarını 

Hat çeken hattan havalanan sanatlarını 

Dagitirsam kim toplar kılıç parçalarini

Çekip arkandaki  istinat duvarını

İçip içip denizin tuzlu sularını 

Karaya otursun gemin,ez dağlarını

Dagitirsam kim toplar gemi  parçalarini

Kulağına küpe  diye anıtlarını 

Bizi biz sanıp duymayan kulaklarını

Gelecekten   tıkalı iltihaplarını 

Dagitirsam kim toplar işit  parçalarini

Yanlıştan şüphe etmeyen doğrularını

İyi satranç oynayan o şahdamarını 

Damarım tutarsa mat  edip o yarını 

Dagitirsam kim toplar piyon parçalarini

Hatırlamazmıyım koyu  kıvrımlarını 

Pervane ile gecen genclik yıllarını 

Cigdeme konan  kanatlı bilge  arını 

Dagitirsam kim toplar doğa  parçalarini

Çarşaf üstünde  iskambil kağıtlarını 

Scrabble diyerek  kelime avlarını 

Ve bilinmezin nice bulmacalarını 

Dagitirsam kim toplar gizli  parçalarini 

Topuklarıma kadar saran noktalarını 

Yorgan altında o siyah ayaklarını 

Ve masum beyazı kardan  topuklarını 

Dagitirsam kim toplar sonsuz parçalarini 

Dinledin mi sinende  kalp atışlarını 

Hissetinmi göğsümde kaburgalarını 

Çek çenemdeki o sakal mızraklarını 

Dagitirsam kim toplar mermi  parçalarini 

Gördünmü bana değen o bakışlarını 

Ya da duman gözünde kaş çatışlarını 

Avucumda  ittim ateş avuçlarını 

Dagitirsam kim toplar günah  parçalarini 

Pist pist pist diyorum git,çek kaplanlarını 

İndirme  pistime savaş uçaklarını 

Kaplanın gözüne sokma o taşlarını 

Dagitirsam kim toplar tankın  parçalarini 

Kaybedip kayıp aşkın sol anahtarını 

Sessizliğince  dağıtıp notalarını 

Ben çaldıysam sana ayrılık çanlarını

Dagitirsam kim toplar nota  parçalarini 

Geriye çektik mesafe adımlarını 

Çözdük bagımsızlığın prangalarını 

hicranla taçlandırdı aşk, tutsaklarını 

Dagitirsam,kim toplar bizin  parçalarini 

Hat üzerinde sıçratıp  dalgalarını 

Denizde analog hat sırça sarayını 

Biri sıfıra ver,dök  bilgisayarını

Dagitirsam kim toplar yonga  parçalarini 

Çeliğe su veren deli ırmaklarını

Sırtımda iz bırakan o  tırnaklarını 

Mürekkebe batırdım,o itibarını

Dagitirsam kim toplar senin parçalarini 

Gör içinde saklandigin kabuklarini 

Kipirdatma sakin o leb  dudaklarini 

Sever de seni hatirlarsam   aromani 

Dagitirsam kim toplar senin parçalarini 

alev alirsa söndüremezsin yangini 

Alev alirsa görürsün yagmur ormani 

Iki  gönül  bir   ise samani seyrani 

Dagitirsam kim toplar ateş parçalarini 

Karardayız biz kocaman aç kollarını

Üfleme  ıssızlığın  fısıltılarını 

Kararlılığın da var elbet bir yarını 

Dagitirsam kim toplar kudret parçalarini 

Tuvale saçar denizkızı  sırlarını

Bitirmez es, paletteki  renk tonlarını 

Kadın bilir  denizcinin zaaflarını 

Dagitirsam kim toplar gücün  parçalarini 

Anlatma bana kanatlı  rüyalarını 

sisir siyahi montu,çirp kanatlarini 

Konmayı bilmezse nasıl uçsun yarını

Dagitirsam kim toplar kanat  parçalarini 

Kesip durma yıldızların kuyruklarını 

Şimidiyi yaşarken beklemeden yarını

Sana geri veriyorum  kalan  yarını 

Dagitirsam kim toplar senin parçalarini 

Görünce uçurumun keskin kenarını 

Askımla dondururüm  görmezsin devranı 

Sonrada olurda yazarsam bu romani 

Atarsam  kim toplar senin parçalarini 

H.Cigdem Yorgancıoglu

14.02.2006 Istanbul 

www.cigdemyorgancioglu.net', 'Tutmuşsa elin elimin parmaklarını  Kırmışsa kalbin beynimin kararını  Açık denizlerdeki o fay hatlarını  Dagitirsam kim toplar fayın  parçal...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Yorgancıoğlu']::text[], 8.5, '{"poet":"Çiğdem Yorgancıoğlu","poet_slug":"cigdem-yorgancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":115,"source_url":"https://www.antoloji.com/siromansi-ye-subat-fisiltisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazacağız Elbet', 'yazacagiz-elbet-yusuf-onder-bahceci-sjfz6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazacağız gönlün derinliklerinden gelen bu sevdayı,

Yazacağız sevdiğinin gözlerine gülen gülü, goncayı,

Yazacağız Allah''ı için, Dini için uğraşan, düşünceyi,

Yazacağız, yazacağız elbet, yoksa hesabı sorulur.

Yazacağız yoksulları, kimsesizleri, sefilleri, garipleri,

Yazacağız komşusu açken tıka basa yiyip semireni,

Yazacağız alışverişte fişleri vermeyen, müesseseyi,

Yazacağız, yazacağız elbet, yoksa hesabı sorulur.

Yazacağız alıcı kuşların ömrünün çok az, olduğunu,

Yazacağız Avrupa''yı, Amerika''yı, Asya''yı, Somali''yi,

Yazacağız gemiyi, kaptanı, dümeni, rotayı ve kotayı,

Yazacağız, yazacağız elbet, yoksa hesabı sorulur.

Yazacağız doğurduğu çocuğunu, sokaklara atanları,

Yazacağız, sokak çocuklarını, çöp toplayanı, satanı,

Yazacağız uhu, tiner, bali çekip vatandaşa çullananı,

Yazacağız, yazacağız elbet, yoksa hesabı sorulur...', 'Yazacağız gönlün derinliklerinden gelen bu sevdayı, Yazacağız sevdiğinin gözlerine gülen gülü, goncayı, Yazacağız Allah''ı için, Dini için uğ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yazacagiz-elbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genlerin Mahkumu', 'genlerin-mahkumu-salim-erben-hb6zq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah bir sökebilseydim yüreğimi 

Parça, parça eder 

Bulurdum seven genlerimi 

Çıkarıp yakardım kor ateşte 

Sevda yüklü aşk dolu gönülleri 

Sevdaya zorlayan bu beyni 

Dur durak bilmeyen ateşli geni 

Çıkarıp atardım beynimden 

Siler süpürür temizlerdim izini 

Kör ederdim şeytani gözünü 

Hatırlamazdım ettiğin yemini 

Unuturdum verdiğin sözünü 

Sevmezdim bir daha sevmezdim seni 

Kırar dağıtır parçalardım 

Ezerdim yosunlu taşlarla 

Boğardım karanlık sularda 

Hırçın dalgaların çarptığı 

kayalara atardım 

Sürüklerdi derinlere götürürdü 

Kilometrelerce ileriye 

Elim ayağım gözüm kulağım diye 

Sarılmazdın ümitsiz gecelere 

Saymazdım yıldızları bir gecede 

Hatırlamazdım anıları 

Dizginlerdim kendimi 

Beklemezdim güneşin doğmasını 

Saymazdım kaç gece sabahladığımı 

Ey karanlık sırların anası 

Bırak sarma kanasın o gende ki

O zalımlar zalımı

O Salimin yarası Salimin yarası 

Salim ERBEN (Zalım)', 'Ah bir sökebilseydim yüreğimi  Parça, parça eder  Bulurdum seven genlerimi  Çıkarıp yakardım kor ateşte  Sevda yüklü aşk dolu gönülleri  Sev...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/genlerin-mahkumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arsuz''da Kanatlandı', 'arsuz-da-kanatlandi-cigdem-yorgancioglu-mkagy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün ruhum Arsuz’da kanatlandı

Dokularımın hepsi,yeniden canlandı

Belki çözüldüm,belki  dilim bağlandı

Yazacaklarım, tarihte çoktan imzalandı

Rüzgar esti bir kentin eteği havalandı

Bir kent bir kadına,kadın kente yandı

Cleopatra Antakya''da Marcus Antonius''la

buluşmaya giderken Arsuz''da  konuk oldu

Belli ki o da Arsuz’un güzelliğine yakalandı.

Yağmur yağdı biraz saçlarım ıslandı

Hz.İsa''nın Havarileri Arsuz''da soluklandı

Yağmur giderek daha da hızlandı

Cleopatra’nın künefeden saçları tatlandı

Rüzgar esti, saçları bir daha katlandı

Bunca söz bilmezsiniz nereden peydahlandı

Cleopatra’sızlık Arsuz da, ben gibi yaşlandı

Giderayak, gelir gelmez gözlerim yaşlandı

H.Cigdem Yorgancioglu

 ANTIOCHIA 1 adlı kitabindan 

www.cigdemyorgancioglu.net', 'Bugün ruhum Arsuz’da kanatlandı Dokularımın hepsi,yeniden canlandı Belki çözüldüm,belki  dilim bağlandı Yazacaklarım, tarihte çoktan imzalan...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Yorgancıoğlu']::text[], 8.5, '{"poet":"Çiğdem Yorgancıoğlu","poet_slug":"cigdem-yorgancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arsuz-da-kanatlandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Güzelim Gitme', 'gitme-guzelim-gitme-salim-erben-dqs7d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerim koynumda boynu bükük 

Cepler delik gömlek sökük 

Per perişan etraf dökük 

Öksüz çocuklar gibi koyup gitme 

Gönlüm kırık yüreğim yaralı 

Alın yazım hep böyle karalı 

Alışmışım sana burada kalalı 

Akan gözyaşımı silmeden gitme 

Yanarım için için külsüz dumansız 

Dokunsalar ağlarım gönül fermansız 

Ruh bedende ceset cansız 

Koymadan mezara çekip de gitme 

Gitme beni böyle bırakıp 

Yılan gibi yüreğime akıp 

Şu gönlümü yakıp yıkıp 

Alevler içinden almadan gitme 

Gidersen eğer aklım sende kalır 

Gönlüm küser kalbim kırılır 

Ömür geldi geçti günler sayılır 

Ağlatıp zalımı bırakıp gitme 

Gitme güzelim ne olur gitme

Salim ERBEN (Zalım)', 'Ellerim koynumda boynu bükük  Cepler delik gömlek sökük  Per perişan etraf dökük  Öksüz çocuklar gibi koyup gitme  Gönlüm kırık yüreğim yara...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gitme-guzelim-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cây-ı teemmül', 'c-y-i-teemmul-cigdem-yorgancioglu-e6wvj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'CÂY-I TEEMMÜL

Geçmişi kazdıkça burada

Önümüze açılacak

celesat-ı âti 

Yani gelecekteki celseler

devam ederrsek eğer

Önümüze serilecek belki cemi ezmân 

yani bütün zamanlar ve önceler

Besin değeri nedir bu hikâyenin

Derseniz eğer

Ruhum doydu ise,tadılmaya  değer

Antakya   cây-i teemmül 

ve etraflıca düşünülmeye değer

Çiğdem’in Antioch 1  kitabından 

Cây-i teemmül serisi 

H.Çiğdem Yorgancıoğlu

www.cigdemyorgancioglu.net

Antioch 1', 'CÂY-I TEEMMÜL Geçmişi kazdıkça burada Önümüze açılacak celesat-ı âti  Yani gelecekteki celseler devam ederrsek eğer Önümüze serilecek belki ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Yorgancıoğlu']::text[], 8.5, '{"poet":"Çiğdem Yorgancıoğlu","poet_slug":"cigdem-yorgancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cay-i-teemmul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsizce sevsen ne çıkar', 'sebepsizce-sevsen-ne-cikar-selcen-boyar-ykpe7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sebepsizce sevsen ne çıkar ki

sevmek için  sebebin geregi varmı? 

söylediğin her kelime

kurduğun her cümle

zaten aşkı intihara salmazmı? 

gözlerin görmüyor

ruhun duymuyor

bu aşkın bir anlamı var mı? 

umutlarım birer birer soluyor

böyle bir aşkta mevsim,

hazan olmazmı?', 'sebepsizce sevsen ne çıkar ki sevmek için  sebebin geregi varmı?  söylediğin her kelime kurduğun her cümle zaten aşkı intihara salmazmı?  gö...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sebepsizce-sevsen-ne-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindan Mektupları 1', 'zindan-mektuplari-1-harun-kuscu-xwxdq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen zaman ömürden değil

Soğuk duvarlarda zehir içtiğim

Kader bu meleğim önünde eğil

Demirler ardında bitti gençliğim

Girerken arkamda ömür bıraktım

Gözlerinde güneş kaşında hilal

Uğrunda yaşanmış bir ömrü yaktım

Hasret geceleri gel de beni al

Anne seslenişim kalbim sendedir

Her daim duana muhtacımdır bil

Ruhumu yaşatan senin sevgindir

Kader belki güler gözyaşını sil

27/02/2006

Harun kuşcu

Silifke/mersin', 'Sensiz geçen zaman ömürden değil Soğuk duvarlarda zehir içtiğim Kader bu meleğim önünde eğil Demirler ardında bitti gençliğim Girerken arkam...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zindan-mektuplari-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya/Saklı Yaşamak mı Yaşam!', 'ya-sakli-yasamak-mi-yasam-nesrin-gocmen-8r62q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüksek duvarlar, 

Anahtarı yitik kapılar ardında 

Yalnızlık öpülen

Kopya bir yaşam sunulan. 

. 

Doğarken başlar yasaklar... 

. 

Üç ezan geçmeden 

Ana memesi yasak! 

Kuytu köşeye sinmiş 

Yılanı uyandırmak, 

Dert deşmek,

Sevdalanmak, sevmek yasak! 

.

Sobelemek, istop demek, 

Atlı karınca, çikolata yasak! 

. 

Büyüdün yasak, 

Evlisin, annesin, 

Yaşın geçti yasak! 

. 

Dilediğinde 

Dileğince ölmek de 

Yasak! 

. 

27/02/2006', 'Yüksek duvarlar,  Anahtarı yitik kapılar ardında  Yalnızlık öpülen Kopya bir yaşam sunulan.  .  Doğarken başlar yasaklar...  .  Üç ezan geçm...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ya-sakli-yasamak-mi-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkek çe Yaşamalı', 'erkek-ce-yasamali-yusuf-onder-bahceci-kptmv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erkekçe seni sevmiyorum demeli insan,

Erkekçe gönülü vermedim demeli insan,

Erkekçe gel de vazgeç be demeli insan,

Erkekçe olmalı, erkekçe yaşamalı insan.

Yüze gülüp, arkadan eğlenen yiğit mi dir,

Sosyetenin gece kıyafeti bana dertmidir,

Benim böylesi şiirlerim sertmi, sertmidir,

Erkekçe olmalı, erkekçe yaşamalı insan.

Bir insan seni çok överse sakın inanma,

Sevdiğin seni sevmiyor, diyene inanma,

Gel sen şöyle gözlerime bir bak da anla,

Erkekçe olmalı, erkekçe yaşamalı insan.

Söylenen laf çoksa, yalanda pek çoktur,

Yalancılar da itibarla güven zaten yoktur,

Yalanın olduğu yerlerde, talan da çoktur, 

Erkekçe olmalı, erkekçe yaşamalı insan.', 'Erkekçe seni sevmiyorum demeli insan, Erkekçe gönülü vermedim demeli insan, Erkekçe gel de vazgeç be demeli insan, Erkekçe olmalı, erkekçe y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erkek-ce-yasamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkıldı Dünyam', 'yikildi-dunyam-umit-tuna-n9ds8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sevmiyorum dediği anda,

Yıkıldı dünya başıma,

Alt üst oldu hayatım,

Ben ne kara bahtlıyım.

Sevdiğini zannediyordum,

Yanılmışım meğer,

Sevmiyormuş beni,

Seviyorsa zaten geri döner.

Olmuyor sensiz,

Çekilmiyor hayat Ümit’siz der,

Bensiz geçen günlerine isyan eder,

Seven insan sevdiğini belli eder! ...', 'Seni sevmiyorum dediği anda, Yıkıldı dünya başıma, Alt üst oldu hayatım, Ben ne kara bahtlıyım. Sevdiğini zannediyordum, Yanılmışım meğer, S...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yikildi-dunyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bezirgan Diktası', 'bezirgan-diktasi-yilmaz-aybar-mlalj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çarşıda pazarda evde sokakta

      Her tarafta aynı şey yaşanmakta

      Moral değerlere rağbet eden yok

      Göstermelik olmuş hukuk da hak da

      Maddiyat başını almış gidiyor

      Herkes para ile yatıp kalkmakta

      Bol reklamla makyajlanmış suratlar

      Ay parçası diye pazarlanmakta

      Herkes sanıyor ki özgürlük gelmiş

      Diktatörlük falan kalmış uzakta

      Oysaki birtakım karanlık güçler

      Yepyeni bir dikta uygulamakta

      Ülkesel diktalar hoş görülmezken

      Küresel bir dikta dayatılmakta

     ''Dikta olacaksa böyle olmalı''

      Der gibi bir tavır takınılmakta

      Mumla aranıyor eski diktalar

      Bezirgan diktası en kötü dikta', 'Çarşıda pazarda evde sokakta       Her tarafta aynı şey yaşanmakta       Moral değerlere rağbet eden yok       Göstermelik olmuş hukuk da ha...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bezirgan-diktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılda Bir Kere', 'yilda-bir-kere-umit-tuna-oshe3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'El ele göz gözeydik,

Her an beraberdik,

Belki yılda bir kez beraberdik,

Ama olsun biz beraberdik.

Onun ellerini tuttuğumda,

Dünyalar benim oldu,

O gözlerine baktığımda,

Hayaller gerçek oldu.

O masum yüzüne her baktığımda,

Seviyorum, dedim

Aşkım, dedim

Biliyorum sende beni seviyorsun,

Ama söyleyemiyorsun,

Olsun be güzelim,

Sen hissettiriyorsun! ...', 'El ele göz gözeydik, Her an beraberdik, Belki yılda bir kez beraberdik, Ama olsun biz beraberdik. Onun ellerini tuttuğumda, Dünyalar benim o...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yilda-bir-kere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksaydın', 'yoksaydin-umit-tuna-hqg2x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen düşünüyorum da,

Unutmak için bir çok neden var seni,

Bazen düşünüyorum da,

Sevmek içinde bir çok neden var seni.

Çok karışık bu aşk işi çok,

Herkes beceremiyor belli,

Herkes unutup gidemiyor,

Herkes yalan söyleyemiyor.

Seni unuttuğumu söylesem de,

Sakın inanma bana,

O tatlı gülüşün hep aklımda,

Nasıl unuturum ben seni,

Yaşanan onca şeyi.

Bana unut deme sakın,

Sen unutmayı kolay mı sandın? 

Ben seni sevdim,

Sen beni yoksaydın! ...', 'Bazen düşünüyorum da, Unutmak için bir çok neden var seni, Bazen düşünüyorum da, Sevmek içinde bir çok neden var seni. Çok karışık bu aşk iş...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yoksaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüm Tutsak', 'yuzum-tutsak-saadet-un-6onrw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'odam pencerem ve ben

dışarıda gece karanlıkları

uluyan rüzgar

soluyan sessizlik

ve tütün kokusunda bir yalnızlık ki

buna inat

sırıtıyor karanlığın koynunda

şehrin ışıkları

yüzüm tutsak cama dayalı

gözlerim

bir yeryüzünde bir gökyüzünde

bir ışıklara bir yıldızlara bakıyorum

hani gelsinler istiyorum

onların yeri ayrı

dolsunlar mekanıma

misafirim olsunlar

ama çağıramıyorum

ocağım yok! 

bir fincan kahve bile

yapamam ki onlara

şimdi saat

anıların gözlerimde yürüme saatidir

ve yalnızlığın yüreğimde üşüme saati

dışarıda gece karanlıkları

şehrin ışıkları 

ve ben

yüzüm tutsak cama dayalı

beklediğim yok

zor severim

sevdimmide tam severim

çıkmasın karşıma ben aşkım diyen

bir seslik bir nefeslik insanoğulları

ki bilinsin

düşüyor gözlerimden şimdi

küstah aşkların ukalâ insanları

odam pencerem ve ben

dışarıda gece karanlıkları

içime süzülüyor sinsice

düşsel intiharlarıyla şehrin ışıkları

ve anılarımda oturuyor halen

umudumun son çırpınışları

umudum mu? 

sizlere ömür

oysa daha dün

duruyordu elimin altında

onurlu bir aşka ve sevdaya

sarılmak istedi diye

öldürüldü

döküldü yıldızlar

söndü şehrin tüm ışıkları

içimde söylenip duruyor şimdi

ayrılık şarkıları

umarsız

yüzüm tutsak cama dayalı', 'odam pencerem ve ben dışarıda gece karanlıkları uluyan rüzgar soluyan sessizlik ve tütün kokusunda bir yalnızlık ki buna inat sırıtıyor kara...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ün']::text[], 8.5, '{"poet":"Saadet Ün","poet_slug":"saadet-un","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/yuzum-tutsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Ümit', 'son-umit-husam-hasret-dzf0z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son bir ümidin yeşil ışığını gözlerken

Kırmızı ışığında dura kaldım bir ara

Hızlı adımla koştum bana gelince sıra

Sansımı açı verdim, talihimi gizlerken

Deryaları düşündüm sözümü denizlerken

Son bir ümidin yeşil ışığını gözlerken

İçimi çalkalayıp öylesine coştum ki

Bir yanardağ örneği alev alev püskürdüm

Yaktım umutsuzluğu, küllerini savurdum

Zirveyi tartı sandım, doğayı ise çeki

Acundan konuştum bir, evrenden ise iki

İçimi çalkalayıp öylesine coştum ki

Aynı ilke, ülküyle varlığımı saptadım

Her düğümlü soruna aradım ki bir çözüm

Bir noktada birleşti fikrim, işim ve sözüm

Başarımı sağladı attığım düzgün adım

Tarih sayfalarında ebedileşti adım

Aynı ilke, ülküyle varlığımı saptadım', 'Son bir ümidin yeşil ışığını gözlerken Kırmızı ışığında dura kaldım bir ara Hızlı adımla koştum bana gelince sıra Sansımı açı verdim, talihi...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-umit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uşağum (Yerel 6)', 'usagum-yerel-6-mikdat-bal-e9cqe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soyledum soyledum kulak vermedun 

Bir kere lafuma baksan uşağum 

Tövbe edup doğri yola girmedun 

Düştüğün bataktan çıksan uşağum 

Silkinsen gafletten gerçeği bulup 

Kendune dönseydun tövbekar olup 

Ananun babanun gönlini alup 

Sahte dostlaruni sıksan uşağum 

Yüksekten bakarsun bir inebilsen 

Şeytani nefsuni ah yenebilsen 

Uyanup kendune bir dönebilsen 

Gaflet otelini yıksan uşağum 

Haram çok fenadur benzer irine 

Dön olduğun yerden dalma derine 

Şöyle bir düşünüp esrar yerine 

Gönlünde bir ışık yaksan uşağum 

Gönlünde ki nuru yakman gerekir 

İman gözlüğiyle bakman gerekir 

Mezbeleye düştün çıkman gerekir 

O kirli çevrenden bıksan uşağum 

Sana deduklerum rehberun ola 

Her şey geçicidur fanidur kula 

Güvenma güçüne güvenma mala 

Dünya senun olsa noksan uşağum 

Mikdatî der pişman olursun birgün 

Giderum peşumden gelursun bir gün 

Dünya baki değil ölürsün bir gün 

En fazla yaşasan doksan uşağum', 'Soyledum soyledum kulak vermedun  Bir kere lafuma baksan uşağum  Tövbe edup doğri yola girmedun  Düştüğün bataktan çıksan uşağum  Silkinsen ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/usagum-yerel-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Öyle Nazlı Bakışlarınla', 'bakma-oyle-nazli-bakislarinla-yavuz-bayram-caliskan-gi6fm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakma öyle  nazlı bakışlarınla,

Umutları toplayıp gelsem de,

İçine oturup yüreğini delsem de,

Gözlerine dolunay olup gülsem de,

Tedirginsin, yorgunsun, vurgunsun.

Kaçma öyle  yakan gözlerinle,

Acıları ağlarla çeksem de,

Her gün bir oku kalbime soksam da,

Yıldızları taç yapıp taksam da,

Ölgünsün, solgunsun, bitkinsin.

Vurulmaksa vuruldum sana,

Çalıyorum bak aşk sirenlerimiz, anlasana,

Geçiyor sevda trenlerimiz, dinlesene,

Atıyor ruhumuz, frenlerimiz, bilsene,

Titreksin, çekingensin, özlenensin.', 'Bakma öyle  nazlı bakışlarınla, Umutları toplayıp gelsem de, İçine oturup yüreğini delsem de, Gözlerine dolunay olup gülsem de, Tedirginsin,...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bakma-oyle-nazli-bakislarinla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-munevver-erilmez-ghnb8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeter artık a güzel! 

Bırak kalemi elinden

Birazdan sabah olacak

Gündüzleri çuvala mı koydun? 

Hep geceleri yazar durursun.

Rahatsız mı oldun yoksa; 

Telefon sesinden,kapı zilinden

Gelenden,gidenden

Sokaktaki satıcıdan

Aygaz arabasının 

 Nağmelerinden,                                                                                             Fiyakalı kornalardan.

Sen de haklısın güzelim

Böyle şamatada da,

Yazılmaz ki gündüzleri

Bırakalım,GECELER senin olsun

               l4.11.1990

                Saat:00.50', 'Yeter artık a güzel!  Bırak kalemi elinden Birazdan sabah olacak Gündüzleri çuvala mı koydun?  Hep geceleri yazar durursun. Rahatsız mı oldu...', ARRAY['Türk Edebiyatı','Şiir','Münevver Erilmez']::text[], 8.5, '{"poet":"Münevver Erilmez","poet_slug":"munevver-erilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeter-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunlar Ne Alçaktır', 'bunlar-ne-alcaktir-yusuf-onder-bahceci-pihuq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirmisin nâzlı yârim bunlar, bunlar ne alçaktılar,

Beni bana bırakmadılar, seni sana bırakmadılar,

Atın ayağından nal çıkarıp da, büyü yapacaktılar,

Bilirmisin nâzlı yârim bunlar, bunlar ne alçaktılar.

Ölüm ve ayrılık büyüsü yaptırır, insanı çarptırırlar,

Emellerine ulaşırlar, sevenleri ayırırlar, bayılırlar,

Ara sıra görürüm şeytan çarpmış gibi dolanırlar,

Bilirmisin nâzlı yârim bunlar, bunlar ne alçaktılar.

Bunlar bol para verip, büyüyü sağlam yaptırırlar,

Aman da kendilerini bu işlere öyle bir kaptırırlar,

Azıcık bir imanları yoktur, Milleti böyle saptırırlar,

Bilirmisin nâzlı yârim bunlar, bunlar ne alçaktılar.

Böyle sevenleri ayıran, büyücülere neler gerekir,

Yaptıkları büyüleri bulup ta bertraf etmek gerekir,

Yaptıkları büyüleri bulup onlara yedirmek gerekir,

Bilirmisin nâzlı yârim bunlar, bunlar ne alçaktılar.', 'Bilirmisin nâzlı yârim bunlar, bunlar ne alçaktılar, Beni bana bırakmadılar, seni sana bırakmadılar, Atın ayağından nal çıkarıp da, büyü yap...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bunlar-ne-alcaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Baharı', 'askin-bahari-yavuz-bayram-caliskan-hvhny', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın baharı

Yeşermekte,

Sevdanın çimenleri

Hatıraların tutsaklığı

 Avuçlarımda sıcaklığın.

Gün ağarırken 

Dayanılamayan aydınlıklarda

Coşuyordu gelen mutluluk

Esir edilmiş  telaşlarla.

Bahar aşk tutkunu,

Yılların ardında bekleyen

Bir ömür saklı,

Umutlar içinde katlı,

Aşk bahara maksatlı?', 'Aşkın baharı Yeşermekte, Sevdanın çimenleri Hatıraların tutsaklığı  Avuçlarımda sıcaklığın. Gün ağarırken  Dayanılamayan aydınlıklarda Coşuy...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askin-bahari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gafil Avlama Beni', 'gafil-avlama-beni-lokman-hamitoglu-6604o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GAFİL AVLAMA BENİ

Beni rüyalarımda gafil avlıyorsun

Git diyorum sana

Ben hasretini seviyorum senden ziyade

Çirkinliğin bana yeter

Güzelliğin sende kalsın

Bırak ahlaksızlığımla (!)  yaşayayım

Sen ahlak (!)  denizinde yüz

Gölgeme kurşunlar sık! 

Gölgemi kanat

Yalnız rüyalarıma karışma

Bana teselli verme

Teselliler için istemezük arz ettim

Baharlar gibi git

Zemheri gibi gel

Dondur yüreğimi

Kalbim buz tutsun

Kar yağsın başıma

Korkma itiraz etmem

Yeter ki beni rüyalarımda gafil avlama... 

             Lokman HAMİTOĞLU', 'GAFİL AVLAMA BENİ Beni rüyalarımda gafil avlıyorsun Git diyorum sana Ben hasretini seviyorum senden ziyade Çirkinliğin bana yeter Güzelliğin...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gafil-avlama-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cepli Kefen Çağı', 'cepli-kefen-cagi-yilmaz-aybar-sbybt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Damlada deryayı gören kalmadı

      Bir lokma bir hırka yetmiyor artık

      Doyduğundan haber veren kalmadı

      Açgözlülük fren tutmuyor artık

      Damlada deryayı gören yok peki

      Deryada deryayı farkeden hani

      Tamaha kaptırmış herkes kendini

      Kimse başka dava gütmüyor artık

      Bir lokma bir hırka az geliyorsa

      On lokma on hırka yeter desek ya

      İstiyoruz daha daha hep daha

      Ocaklar şükürle tütmüyor artık

      Yüz lokma yüz hırka da azdır elbet

      Bürümüş gözleri zira maddiyat

      Ne bet var ortada ne de bereket

      Hırslar tükenmiyor bitmiyor artık

      Bin lokma bin hırka olsa ne yazar

      Kefen sargısının şimdi cebi var

      Neler ve de neler alacak kadar

      Bezirgan düz kefen satmıyor artık', 'Damlada deryayı gören kalmadı       Bir lokma bir hırka yetmiyor artık       Doyduğundan haber veren kalmadı       Açgözlülük fren tutmuyor ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cepli-kefen-cagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-yilmaz-aybar-ba70o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu kargalar yok mu

      Şu serçeler

      Ve daha niceleri

      Çıkmaz çöplükten gagaları

      Kuş demeye bin şahit ister

      Şu tavuskuşuna bakın

      Adı kuş

      Kanadı süs

      Ötüşü evlere şenlik

      Bir de kendini beğenmiş

      Uç ey kartal göklere

      Engin maviliklere yüksel

      Şakı ey bülbül şakıyabildiğince

      Sizinle anlamlı bu dünya

      Sizinle güzel', 'Şu kargalar yok mu       Şu serçeler       Ve daha niceleri       Çıkmaz çöplükten gagaları       Kuş demeye bin şahit ister       Şu tavusk...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kuslar-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuturum', 'unuturum-osman-yagar-poyho', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dertten derde saldın beni

Aldın aklım ettin deli

Hayal oldu saçın teli

Bende seni unuturum 

Görmez olur mavi gözün

Kırış kırış olur yüzün

Tutmaz olur iki dizin

Bende seni unuturum

Osman YAĞAR ağlar gider

Gören acır feryat eder

Elbet birgün sevdam biter

Bende seni unuturum', 'Dertten derde saldın beni Aldın aklım ettin deli Hayal oldu saçın teli Bende seni unuturum  Görmez olur mavi gözün Kırış kırış olur yüzün Tu...', ARRAY['Türk Edebiyatı','Şiir','Osman Yağar']::text[], 8.5, '{"poet":"Osman Yağar","poet_slug":"osman-yagar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unuturum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Söylemiş', 'kim-soylemis-yusuf-onder-bahceci-knpw0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim söylemiş böyle saçma sözleri,

Bunlar atasözü değil bilirim sözleri,

Benim kâlbimi yakan ateşi, közleri,

Kim söylemiş böyle saçma sözleri.

Azıcık aşım, kaygısız başım, başım,

Nedir bu Dünya telaşım, it dalaşım,

Devletin malını yemeyenler, domuz,

Kim söylemiş böyle saçma sözleri.

Bunlar atasözü olamaz be olamaz,

Vatanını seven, böyle laf söylemez,

Atasözü, deyimlerle gönül eylemez,

Kim söylemiş böyle saçma sözleri.



İşte gerçek atasözü sözlerinse özü,

Devletin malını, haksız yiyen domuz,

Yılanların başını küçükken ezmeliyiz, 

Kim söylemiş diğer saçma sözleri...', 'Kim söylemiş böyle saçma sözleri, Bunlar atasözü değil bilirim sözleri, Benim kâlbimi yakan ateşi, közleri, Kim söylemiş böyle saçma sözleri...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kim-soylemis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K a v g a', 'k-a-v-g-a-yunus-guzel-u5qz9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu bizim kavgamız

bu kavgada,

kin yok, 

nefret yok

belden aşağı vurmak hiç yok

bu kavga,

yağmurun bulutunu  ıslatması

yıldızın gökyüzünü yakması

ay ışığının ışıltılarını alıp gitmesi

ve bir balığın denizine küsmesi kadar masum

bu kavga,

al koynuna öldür beni

kır tuttuğun ellerimi diyen

ve “seni seviyorum çocuk”der gibi küfreden

sevgilinin isyanı kadar haklı

bu kavga,

gülen gözlerin,

çatık kaşıyla kavgası

bu kavga,

yen ile,

içinde kırılan kolun kavgası

ahh!  ‘bu kavga’sız hayat

tuzsuz çorbadan da berbat…', 'bu bizim kavgamız bu kavgada, kin yok,  nefret yok belden aşağı vurmak hiç yok bu kavga, yağmurun bulutunu  ıslatması yıldızın gökyüzünü yak...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/k-a-v-g-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Olamazsın', 'vefasiz-olamazsin-mustafa-bilgili-7tapo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırakıp gittin ya beni,

Yağmurlu bir güz mevsiminde,

Bir mevsim daha geçti bak,

Kara kış artık kapıma dayandı.

Zaman çok uzadı farkındamısın? 

Hiç bu kadar sensiz kalmamıştım,

Aramadın sormadın bir kere olsun,

Sen bu kadar vefasız olamazsın.

Ben sana Kardelen demiştim,

Dışarıda lapa lapa kar yağıyor,

Sen yoksun ya üşüyorum Kardelen,

Bir meçhule doğru koşarken,

Karanlık bir kör kuyuya düştüm.

Tut ellerimden çıkar beni,

Aşk senin bilmediğin bir şey değil ki,

Cömertçe harcıyorsun da,

Neden şu halimi görmüyorsun? 

Veya belki de öyle görünüyorsun.

Birazcık mutluluğu çok görme bana,

Bak aşk dilencisi oldum sayende,

Sevmesini bilmeyen bencil insanlardan,

Aşk dileniyorum,gözlerim yaşlı,

Sen bu kadar acımasız olamazsın.

Geri dön demiyorum sana,

Farkındayım dönemezsin,

Ama bir ara,bir sor beni,

Sen bu kadar vefasız olamazsın.

                                               04.02.1997', 'Bırakıp gittin ya beni, Yağmurlu bir güz mevsiminde, Bir mevsim daha geçti bak, Kara kış artık kapıma dayandı. Zaman çok uzadı farkındamısın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vefasiz-olamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-huseyin-sigirtmac-1sfzd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçip gidiyorsun madem acele.

Beni de yanına almadan gitme. 

Can teslim ederim sensiz ecele.

Bu aşkın miadı dolmadan gitme.

Dünya geniş yaşa etmeden telaş.

Sevince anlarsın sevmeye çalış. 

Sensizlik çekilmez deme ki alış.

Bu aşkın sazını çalmadan gitme.

Geçip gider isen düşerim hale.

Yüreğin katlanmaz böyle vebale.

Çağlatıp gönlümü ettin şelale.

Derdime bir derman bulmadan gitme.

Gönül gözün bensiz görmez bilirim.

Dağlar engel elin ermez bilirim.

Azrail can alır vermez bilirim.

Sığırtmaç yanında olmadan gitme.', 'Geçip gidiyorsun madem acele. Beni de yanına almadan gitme.  Can teslim ederim sensiz ecele. Bu aşkın miadı dolmadan gitme. Dünya geniş yaşa...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitme-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*bir Kadın Dolaşırdı*', 'bir-kadin-dolasirdi-hulya-koroglu-dcmkm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kadın dolaşırdı bu kaldırımlarda,

Gün çoktan tüketmişken ışıklarını...

Denizin isyankâr dalgaları arasında,

Usulca kaybolurdu çığlıkları...

Sen; 

Uykunun en tatlı yerinde,

Onun dilinde hüsran ağıtları...

En alıştığı şeydi yalnızlık,

En vazgeçilmezi...

Bir kadın dolaşırdı bu kaldırımlarda.

Senin koynunda yeni sevdalar,

Onun boynuna ilmek olmuş anılar...

Sen yeni aşklara gebe,

Onda doğmadan ölmüş yeni başlangıçlar...

Bir kadın dolaşırdı bu kaldırımlarda,

Gecenin kül kokusu sinmiş saçlarına.

Perperişan duygularla saldı kendini,

Denizin aç sularına...', 'Bir kadın dolaşırdı bu kaldırımlarda, Gün çoktan tüketmişken ışıklarını... Denizin isyankâr dalgaları arasında, Usulca kaybolurdu çığlıkları...', ARRAY['Türk Edebiyatı','Şiir','Hülya Köroğlu']::text[], 8.5, '{"poet":"Hülya Köroğlu","poet_slug":"hulya-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-kadin-dolasirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocuğu', 'sokak-cocugu-murat-onat-taqk1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sokakta bir çocuk, gözleri ıslak

Yırtık pantolonu, ayağı çıplak

Sarmış bedenini bir kirli kazak

Beden denilmez, iskelet yavrucak

Bir tas sıcak çorba ona bir servet

Servetini katlardı, bir parça et

Ekmek de iş görür, bulsa ekmeği

Sarıldı geceye, geçti hendeği

Filanca beyin köşküne yaklaştı

Zavallı yavrucak inan çok açtı

Köpekler ona havlamadı bile

Muhatap olmadılar bir sefile

Hemen girdi mutfağa pencereden

Aşırdı bir parça et tencereden

Yedikçe arttı korkusu, doymuştu

Hırsızlığa artık nokta koymuştu

Yaptığı bu işten çok pişman oldu

Yarını düşündü, gözü yaş doldu

Açlığa gösterilmiyor tahammül

Bir daha yapmam de, istersen üzül

Ertesi gün bir akşam vakti

Bir çocuk bahçe duvarını geçti

Kim bilir kaç çocuk farklı yerlerde

Açlık vardı sadece fikirlerde

1989', 'Sokakta bir çocuk, gözleri ıslak Yırtık pantolonu, ayağı çıplak Sarmış bedenini bir kirli kazak Beden denilmez, iskelet yavrucak Bir tas sıc...', ARRAY['Türk Edebiyatı','Şiir','Murat Onat']::text[], 8.5, '{"poet":"Murat Onat","poet_slug":"murat-onat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sokak-cocugu-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştım Yalnızlığa I', 'alistim-yalnizliga-i-oyku-sava-j2gct', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koyuldum yine koyu bir gecede Ankara yollarına,

Sonsuz, ıssız,soğuk ve karanlık...

Yolun sonuysa yalnızlık! ! 

Yine sonsuz,soğuk ve karanlık...

Aynı sahneye bıraktım arkamda 

Daha önce yaşadım defalarca

Hissetsem de aynı duyguları her defada

Ama yine de alıştım ben yalnızlığa..

Arkadaşlarım olsa da orda,

Hep bir eksik var aramızda 

Olmak isterim hepsiyle dost ama...

Ama yine de alıştım ben yalnızlığa....

Oysaki tek isteğim bu yalnızlığa bir ortak,

Allah’ım sadece sıcak,içten bir kucak

Neyseki umudum var elbet bir gün olacak

Ama yine de alıştım ben yalnızlığa...', 'Koyuldum yine koyu bir gecede Ankara yollarına, Sonsuz, ıssız,soğuk ve karanlık... Yolun sonuysa yalnızlık! !  Yine sonsuz,soğuk ve karanlık...', ARRAY['Türk Edebiyatı','Şiir','Öykü Sava']::text[], 8.5, '{"poet":"Öykü Sava","poet_slug":"oyku-sava","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alistim-yalnizliga-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştım Yalnızlığa II', 'alistim-yalnizliga-ii-oyku-sava-2souu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve işte Ankaradayım

Buluştum yalnızlıkla

Her zamanki yerindeydi buldu beni kolayca,

Sardı yine etrafımı,kurtulamam! 

Demiştim ya alıştım ben yalnızlığa...

Mutluyum aslında o tek kişilik hayatımda.

Ama varsa etrafında insan, yine de yalnızsan; 

İşte o zaman başlıyor içindeki isyan.

Durduramam ayak seslerini,dinlemezki beni.

Çünkü bilir aslında var birileri.

Onlar görür,duyar,anlarlar beni; 

Yine de uzatmaz elini hiçbiri.

Hepsinde aynı maske; anlamsız ve umarsız

Yitirmişler duyguları,bir ottan farksız! 

Bense yeni yeni varıyorum farkına bunların,

Her geçen gün artıyor nefretim,yalnızlığım; 

Çabalarım bir gün, öbür günse bıkarım

Çünkü boşa gitti hep tek taraflı uğraşım.

Bazen buldum sanırım,ama çok safım; 

İnanır,hayaller kurar,rüyalara dalarım

Ama çok sürmez, çabuk yara alırım...', 'Ve işte Ankaradayım Buluştum yalnızlıkla Her zamanki yerindeydi buldu beni kolayca, Sardı yine etrafımı,kurtulamam!  Demiştim ya alıştım ben...', ARRAY['Türk Edebiyatı','Şiir','Öykü Sava']::text[], 8.5, '{"poet":"Öykü Sava","poet_slug":"oyku-sava","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/alistim-yalnizliga-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim Seveli (143)', 'seni-sevdim-seveli-143-i-brahim-arslan-kc2ia', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevdim seveli,

Kader bana yaptı yapacağını..

Kini değil sevmeyi seçeli,

Bilmiyordum kendimi ateşe atacağımı...

Şimdi yoksunum senden,

Arıyorum her yanımda

Gelir diyorum,gün bitmeden

Lakin gelmiyorsun...

Bilmiyordum hasretinle yanacağımı...

Sesin geliyor kulağıma,

Hayalin benimle her an

Sen yoksun diye kahretmiyorum

Camları dökmüyorum,

Duvara yumruk atmıyorum

Biliyorum alışmalıyım yalnızlığa...

Nice geceler bitti sensiz,

Sen yoksun diye güneş,

doğmamazlık yapmıyor...

Böyle giderse sileceğim seni gönlümden,

Billahi sileceğim...

Hem hayatımdan...

Alışamam ben vefasızlığa..

Seni sevdim seveli

Alıştım sensiz yaşamaya...

              25.5.2004', 'Seni sevdim seveli, Kader bana yaptı yapacağını.. Kini değil sevmeyi seçeli, Bilmiyordum kendimi ateşe atacağımı... Şimdi yoksunum senden, A...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-sevdim-seveli-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felsefe', 'felsefe-nevzat-ozkan-xe1zr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gecenin yarısında

bilgisayar başında

yaptığım yolculukta

Nietzsche ve Kant adında

gezginlerle tanıştım.

Kantı tanıyor gibiydim,ama

Nietzsche yabancı geldi bana.

dilleri çok değişikti

bir türlü anlamadım.

tam  alışıyordum ki

birden Adorno geldi,

kampta yazılan şiir

şiir değildir dedi.

konjünktür ne olacak

aklım hepten karıştı.', 'gecenin yarısında bilgisayar başında yaptığım yolculukta Nietzsche ve Kant adında gezginlerle tanıştım. Kantı tanıyor gibiydim,ama Nietzsche...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/felsefe-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annesizlik', 'annesizlik-ali-arslan-44ebl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kadının,

bir bebeğin göz bebeklerini 

bedeninde;

tohumsuz bırakan her rüzgâra 

çığlığıdır, 

yankılanır durur şimdi,

Ne kadar açsa da 

çimlendiremediği bağrını,

zaman geçmiştir. 

Rüzgâr başka iklimlerde dolaşır,

aşk,

hep körpe baharlara koşar.

Verimsiz kalan her bir döl yatağında

sitem,

zamanın acı bir oyunudur;

yüreğinden kan damlatan,

........ve acısıyla, 

kadını;

bir bebeğin göz bebekleri için 

ağlatan!', 'Kadının, bir bebeğin göz bebeklerini  bedeninde; tohumsuz bırakan her rüzgâra  çığlığıdır,  yankılanır durur şimdi, Ne kadar açsa da  çimlen...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/annesizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzsun', 'sonsuzsun-elif-kerenciler-ifqev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sonsuz sevgim

yakında haykırılamayacak........

yeniden sever misin deseler seni

yeni bir hayatta bile sonuna kadar evetsin

hep sevildin, hep sevileceksin

27.02.2006 11:12

İSTANBUL', 'sonsuz sevgim yakında haykırılamayacak........ yeniden sever misin deseler seni yeni bir hayatta bile sonuna kadar evetsin hep sevildin, hep...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sonsuzsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim (144)', 'sana-geldim-144-i-brahim-arslan-qmyrk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sana geldim,

Haydi sar beni,

Bakmasan öyle

Yabancınmıyım...

Ben sana geldim,

Çok uzaklardan,

Ve seviyorum,

Yalancımıyım...

İstersen öldür

İstersen güldür,

Yeter ki gel de,

Yasaklınmıyım...

Yakmasan beni

Zaten gönlüm bir,

Cehennem yeri,

Yanmalımıyım..

Kaybettim seni,

İnanmalıyım.

Sevdiğim için 

Utanmalıyım...

Gel zalim olma,

Kalbime gir de,

Mutlu olayım

Ve olmalıyım...', 'Ben sana geldim, Haydi sar beni, Bakmasan öyle Yabancınmıyım... Ben sana geldim, Çok uzaklardan, Ve seviyorum, Yalancımıyım... İstersen öldü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sana-geldim-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapayım Ayrıyım', 'ne-yapayim-ayriyim-yusuf-onder-bahceci-m8i88', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ekmek parası, ne yapayım çocuklar hep kucakta,

Cânım Vatanımdan, binlerce kilometre uzaklarda,

Memleketi düşünürüm, burada ben sanki tuzakta,

Ekmek parası, ne yapayım çocuklar hep kucakta.

Ben buralardayım ama aklım, fikrim hep oralarda,

Bana haber verin Hasan Emmim''den, hâli ne ola,

Allah bilir ki tarlasını hâla öküzle sürüyordur daha,

Ben buralardayım ama aklım, fikrim hep oralarda.

Sabah kalktığımda, içimde ki özlem sabah ezanı,

Öğlen oluyor hâla Güneş yok kara bulutları, pilanı,

Kurtulamıyorum beni buralara böyle salanı, salanı,

Ben buralardayım ama aklım, fikrim hep oralarda.

Hanım''ıma bakıyorum, o da bana bakıyor, yakıyor,

Biliyorum o güzel gözlerinden böyle hasret akıyor, 

Biliyorsun geçen sene de gidemedik beyim diyor, 

Ben buralardayım ama aklım, fikrim hep oralarda.', 'Ekmek parası, ne yapayım çocuklar hep kucakta, Cânım Vatanımdan, binlerce kilometre uzaklarda, Memleketi düşünürüm, burada ben sanki tuzakta...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-yapayim-ayriyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani O Kadın Varya', 'hani-o-kadin-varya-kiymet-sonmez-ds28k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgili Peygamberimiz anlatmış seni

Hani o kadın var ya

Kocası öldükten sonra evlenmemiş,

Kendini evlatlarına adamış,

İşte o kadın cennette,

İki parmağın birbirine yakın olduğu kadar,

Benim yanımda olacak.

İşte sen,

Çok genç yaşta kaybettin eşini,

İkisi çok küçük, nerdeyse bebecik,

Beş çocukla birlikte.

Ama oturtmam evlatlarımı üvey baba sofrasına,

Benim eşim derine gitti, çıkmaz bir daha ordan dedin,

Gerekirse bir elimle tuz, bir elimle ekmek dilenirim.

Ama bırakmam onları ellerin eline dedin

Ne bayram bildin, ne bahar

Erkek işi demedin, kadın işi demedin,

Çok yoruldum yeter artık hiç demedin.

Pek çok babalı çocuktan daha iyi büyüttün evlatlarını

Dedikoduyu hiç sevmedin,

Ne yaptırdın, nede yaptın.

İş küçümsemedin

Hep çalıştın, çalıştın

Ama zor durumda kalırsam dilenirim bile dedinya

Onu hiç ama hiç yapmadın.

Arsızlık nedir hiç bilmedi çocukların,

Zaman zaman bunca çabana rağmen kırdılar seni,

Çocuklarına hiç cevap vermedin,

Yetimlere kıyamadığın için hep çekindin

Kimi bir çaydanlık su için kırdı seni,

Kimi bir sepet odun için, 

Ama kaybedince birgün seni.

Senin kendi hayatını feda ettiğini anladılar.

Ölümünde güzeli olurmuş,

Bilirsin ben ölümden çok korkardım

Ama seni görünce hiç korkmadım.

Çünkü öyle güzel olmuştunki,

Yüce Rabbim son nefeste kimine güzellik verir,

Kiminide çirkinleştirir.

Adeta gideceği yerin sedasını yüzüne yansıtır.

Sen öyle güzel oldunki,

Sanki gideceğin yeri bize gösterdi Yüce Rabbim

Bugün gideli yirmibir yıl oldu.

Dilerim,

Sevgili Peygamberimizin dediği gibi,

İki parmak kadar yakınsındır ona,

Kabrin nur,

Mekanın cennet,

En yakın komşun,

Peygamberimiz olsun.', 'Sevgili Peygamberimiz anlatmış seni Hani o kadın var ya Kocası öldükten sonra evlenmemiş, Kendini evlatlarına adamış, İşte o kadın cennette,...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/hani-o-kadin-varya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bir Bakışla (145)', 'son-bir-bakisla-145-i-brahim-arslan-7rx0p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bakışla deli gibi sevmem ben,

Aşk oyunlarına asla gelmem ben...

Sen yinede beni bana bırakma,

Bakarsın bir güzelin ardındanda,

Düşünmeden,koşarak giderim ben...

Aşık olacağımı hiç sanmam ben,

Aşk çeşmesine düşersem kanmam ben,

Ben beni bırakıp giderim belki,

Belki sıkılırım sevgisizlikten

O zaman direnmem,aşktan kaçmam ben...

Mutlu olacağıma inanmam ben

Arar bulurum seni,usanmam ben...

Belki düşerim eline kuş gibi,

Son nefesimi avucunda veririm,

O zaman yaşamaktan utanmam ben...

Sadece sensizliği istemem ben,

Bir tek sensizliğe ederim sitem

Gelip sana gecenin ikisinde

Kapına dikilip sev beni,diye

Seviyorum diye elaleme derim

İstiyorsan da çeker giderim ben...

İstiyorsan da çeker giderim,son

Bir bakışla; hayattan,hayatımdan...

                        02.09.2004', 'Bir bakışla deli gibi sevmem ben, Aşk oyunlarına asla gelmem ben... Sen yinede beni bana bırakma, Bakarsın bir güzelin ardındanda, Düşünmede...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-bir-bakisla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Takunya', 'kirmizi-takunya-sema-figen-akdogan-t8i0s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sözlerim durgun titrek dudaklarda

Öfkem dinmez bilirim bu şehrin sokaklarında

Maviyi denizlerde tanıdım 

Beni başka renklerle kandırma

Şimdi herşeyim yarım

Yüreğim acıyor

Ve mazi ağır ötesi bir hüzün gözlerimde

Hayallerim yandı hep eşkıya yollarda

Bir yıldız kadar erişilmez

Bir kuş kadar özgür olmak istiyorum

Sonsuza kadar uçmak haykırmak

Varolduğumu duyurmak istiyorum

Mutlu olmak belki

Beni tanımaya çalışma

Ben bu dünyaya bir yabancıyım

İntihar etti tüm umutlarım

Alışmalıyım.', 'Sözlerim durgun titrek dudaklarda Öfkem dinmez bilirim bu şehrin sokaklarında Maviyi denizlerde tanıdım  Beni başka renklerle kandırma Şimdi...', ARRAY['Türk Edebiyatı','Şiir','Sema Figen Akdoğan']::text[], 8.5, '{"poet":"Sema Figen Akdoğan","poet_slug":"sema-figen-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kirmizi-takunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Demeti', 'duygu-demeti-asude-gediz-t0ddt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğime sevginle

hasret biriktirdim

uykusuz gecemde

sevdamı  demledim

kördüğüm olmuş derdime çare ararken 

duygu demetinden özlemi beğendim

Bıkkın bekledim

asude dinledim

topraktım susuz

yağmuru bekledim

bir nefes vuslatı çekmek isterken

duygu demetinden hüznü beğendim

Demlendi düşlerim

güneşe verdim

gelsin kalem kağıt

çıldırsın elim

sevda pınarına bir söz ararken 

duygu demetinden coşkuyu beğendim

Varsın yürek sevdanla  hüzün biriktirsin efendim.

Duygu demetinden sevgiyi….beğendim…', 'Yüreğime sevginle hasret biriktirdim uykusuz gecemde sevdamı  demledim kördüğüm olmuş derdime çare ararken  duygu demetinden özlemi beğendim...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duygu-demeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bakışın Yetti (146)', 'bir-bakisin-yetti-146-i-brahim-arslan-gzp78', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bakışın yetti,beni benden almaya...

sana gelmek istedim,gelemedim

uçmayı bilmeyen bir kuştum ben

tek dileğim vardı bu dünyadan,

ellerinin içinde bir yaşam,

bugün ellerinden sonsuzluğa uçtum ben

kanadım olmadan...

sen yabana attın sevgimi,

küçük sevdalar sana göre değildi

gittik bir meçhule,küçük sevdamla ben...

sana olan küçük sevdamda bitti...

bir bakışın yetti beni benden almaya

bir bakışın yetti canımı almaya,

sen benim varlık sebebimdin,

ve Azrail''imdin sen benim

ben seni buldum,sen beni bulmadan

bugün sana canımı sundum...

bu can zaten hep senindi...

sen ya bana zulmettin bugün,

ya sevgimi küçümsedin

küçük sevdalar sana göre değildi

ben küçük olduğumu çoktan kabul ettim

ve sana olan küçük sevdamda bitti...

bir kışın yetti senden uzaklara

göç etmeme,

bir bakışın yetti,

yüreğimi sen de bırakmaya

beni benden almaya...

                      02.09.2004', 'Bir bakışın yetti,beni benden almaya... sana gelmek istedim,gelemedim uçmayı bilmeyen bir kuştum ben tek dileğim vardı bu dünyadan, ellerini...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-bakisin-yetti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gene aynı karanlık', 'gene-ayni-karanlik-sair-demet-c8akr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gene aynı karanlık,

Yüzünü bana dönen bir sessizlik havada

Tüylerim ürperiyor,şaşkın bir düşünce yumağı

Konuşuyorsun benimle istemesemde

İşliyorsun düşüncelerini bir saplantı içinde

Bırak artık,

Çek düşüncelerini beynimden

Karar veremezsin benim adıma,

Evet

Suçlu benim

Serin kanlılıkla öldürdüm onu

Aniden istedim

Onu tanımıyordum bile

Yavasça yaklaştım yanına

Engelledim kaçmasını

Bağladım

Ellerini ve ayaklarını

Gözlerindeki parıltı

Giderek artıyordu

Etkilenmeye başlıyordum sanki

Ama ikimizinde bildiği tek şey

Artık çok geç olduğuydu

Gerçekler ayaklarındaki gücü istiyordu

Hiçbir şeye aldırmadan saldırıyordu

Kazanmıştı

Yerde yatıyordu 

Sadece çığlıklar atarak

Başım bilinmezliğe yol almaya başlamıştı sanki

Dayanamıyordum artık o sese

Ve indirdim beyninin ortasına

Mahsende unutulmuş küflü baltayı

Ellerim kan içindeydı

Her yeri kana bulamak istiyordum,umursamadan

Dostum Duvarları ve sessiz eşyaları

Yapamadım

Çünkü

Her yer karanlıktı 

Hiçbirşey göremiyordum

Şaşırmıstım ve korkuyordum 

Sorular karsısında diz çökmek zorunda kalmıstım

Gercekten yerde yatıyormuydu acaba

Onu öldürmüşmüydüm

Ellerim kan içinde değilmiydi yoksa

Bilemıyordum

Tek bildiğim 

Bana karanlık gelene daha çabuk inandığımdı...', 'Gene aynı karanlık, Yüzünü bana dönen bir sessizlik havada Tüylerim ürperiyor,şaşkın bir düşünce yumağı Konuşuyorsun benimle istemesemde İşl...', ARRAY['Türk Edebiyatı','Şiir','Şair Demet']::text[], 8.5, '{"poet":"Şair Demet","poet_slug":"sair-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gene-ayni-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can''Im A', 'can-im-a-turan-tuncer-2z2by', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Can''Im   A

Mutluluk,

Kendi rengini içinde taşır

Umudun kardelen,

Gülüşler yeşil,

Bakışlar papatya,

Kelimeler gök kuşağı..

Sevmek! 

Yaşamın paleti; 

Renkler

Hayatın tualinde

Aşk''ın dokunuşları ile

                           yaşam bulur

Ağacın, kuşun, dağın, denizin

Ya da

Baharın resmini

Defalarca yaptılar

Sen bana, mutluluğun resmini çiz

Gözlerindeki 

Çocuk gülüşlerinde

26 Şubat 2006 /İst (Can''Im  a) 

Alkadraz_Kuşcusu', 'Can''Im   A Mutluluk, Kendi rengini içinde taşır Umudun kardelen, Gülüşler yeşil, Bakışlar papatya, Kelimeler gök kuşağı.. Sevmek!  Yaşamın p...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/can-im-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabusa Zimmetli Uykular', 'kabusa-zimmetli-uykular-i-lknur-cekici-giaeb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kabusa zimmetli uykular

Karaya büründü zamanlar

Köhnelendi asi yarınlar

Yorgun düştü deli sevdalar

Hiçlik kapladı dünyayı

Kana buladı aşkları

Dalga dalga yakamozlar

Kıyıya vurdu acılar', 'Kabusa zimmetli uykular Karaya büründü zamanlar Köhnelendi asi yarınlar Yorgun düştü deli sevdalar Hiçlik kapladı dünyayı Kana buladı aşklar...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kabusa-zimmetli-uykular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pespembe rüya', 'pespembe-ruya-riza-aslan-u0zs9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gerçekler 

adı söylenmekten korkulan

o gerçekler

böyle bir dağ gibi

böyle doruklarına sis bürümüş

bir dağ gibi

karşında 

mağrur 

ve dimdik dururken 

gerçekler yok sayılmaya

çalıştıkça büyürken

ne fayda sağlar artık

pespembe rüyalar

ne fayda sağlar 

beyni uyuşturmak için oynanan

tüm bu oyunlar

15 Şubat 2006

Mersin', 'gerçekler  adı söylenmekten korkulan o gerçekler böyle bir dağ gibi böyle doruklarına sis bürümüş bir dağ gibi karşında  mağrur  ve dimdik d...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/pespembe-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Türküsü', 'yalnizlik-turkusu-tulay-sustam-3l59p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dizleri yaralı 

bir satırım var

başı beyaz bulut

sonu gece yolculuğu

yüreği yaralı

bir anam var

başı beyaz eşarp

ayakları can kırığı', 'dizleri yaralı  bir satırım var başı beyaz bulut sonu gece yolculuğu yüreği yaralı bir anam var başı beyaz eşarp ayakları can kırığı...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-turkusu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız pişmanlıklar', 'zamansiz-pismanliklar-riza-aslan-cvv7k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tanık olunan geçmiş zamanların ardından

avuçlarından kayıp gidenlerin

o dayanılmaz yasları içinde 

pişmanlıklar sarmalar insanı

geçmişin gelecekle

geleceğin bugünle karıştığı

pişmanlıklar

18 Şubat 2006 

Mersin', 'tanık olunan geçmiş zamanların ardından avuçlarından kayıp gidenlerin o dayanılmaz yasları içinde  pişmanlıklar sarmalar insanı geçmişin gel...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zamansiz-pismanliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavan dünya', 'yavan-dunya-riza-aslan-btalo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dona kalır insan

ağlamak ister, beceremez

yavanlaşan dünyada

anlamı yitirilen tüm bu zamanlarda

bir umut arar insan

kendini hayata bağlayacak

18 Şubat 2006 

Mersin', 'dona kalır insan ağlamak ister, beceremez yavanlaşan dünyada anlamı yitirilen tüm bu zamanlarda bir umut arar insan kendini hayata bağlayaca...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yavan-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen tren', 'beklenen-tren-riza-aslan-nbn39', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'umutla beklenen o tren

gelmesi istenen yere

ulaşmaz hiçbir zaman

18 Şubat 2006 

Mersin', 'umutla beklenen o tren gelmesi istenen yere ulaşmaz hiçbir zaman 18 Şubat 2006  Mersin...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/beklenen-tren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesi Yok ki', 'sesi-yok-ki-aynur-avci-m682g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölümün

Sesi yok ki duyulsun

Anlamazsın bile

Bir gün ansızın

Haber vermeden,

Görünmeden sessizce

Girer içeri şaşırırsın

Daha çok erken desende

Tek elin sesi duyulmaz

Artık savunacak gücün yoktur

Hiç düşünmeden

İçine  sığdırdığın

Ne aşk,ne sevda da kurtaramaz

Son nefesini 

Yüreğinden koparıp alır

Bazen acı duyar çırpınırsın

Bazen de haberin olmaz

Allah''ın kanunu bu

Kimse bozamaz..', 'Ölümün Sesi yok ki duyulsun Anlamazsın bile Bir gün ansızın Haber vermeden, Görünmeden sessizce Girer içeri şaşırırsın Daha çok erken desend...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sesi-yok-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçsel hesaplaşma', 'i-csel-hesaplasma-riza-aslan-t4x58', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kendi iç hesaplaşmalarında boğulan

bir yaşamdı bizimkisi

ara ara benliğe takılan 

o güzellikler

o aşık olmanın verdiği 

dayanılmaz haz

öyle hiçbir şey olmamış gibi

üzerinden yıllar

üzerinden insanlar geçmemiş gibi

belirirse gözlerinin önünde

yum gözlerini sıkı sıkı 

o anın güzellikleri kaybolmasın diye

22 Şubat 2006 

Mersin', 'kendi iç hesaplaşmalarında boğulan bir yaşamdı bizimkisi ara ara benliğe takılan  o güzellikler o aşık olmanın verdiği  dayanılmaz haz öyle ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/icsel-hesaplasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
