INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Sesini Duy', 'kalbimin-sesini-duy-selahattin-sahip-3k0i3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KALBİMİN SESİNİ DUY

		Kalbimin senini duy,ruhun da beni hisset

		Aşkımızı haykırıp,nağmelerin de dinlet,

		Senin sevgin den başka,etmem kimseye minnet,

		Ben bir sevda kuşuyum,beni gönlüne hapset.', 'KALBİMİN SESİNİ DUY 		Kalbimin senini duy,ruhun da beni hisset 		Aşkımızı haykırıp,nağmelerin de dinlet, 		Senin sevgin den başka,etmem kims...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Sahip']::text[], 8.5, '{"poet":"Selahattin Sahip","poet_slug":"selahattin-sahip","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kalbimin-sesini-duy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taze Bir Fidanım Ben', 'taze-bir-fidanim-ben-selahattin-sahip-s5lk2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TAZE BİR FİDANIM BEN

