INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kürek Kemiğim', 'kurek-kemigim-reyhan-tataroglu-ecbe1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hürmet ettim

                                      bir kadına

                                      bakmadım 

                                      ne adına 

                                      ne soyadına

                                      yoktu ondan

                                      hiç bir çıkarım

                                      belki de 

                                      hürmetsizlikten 

                                      çıkarım

