INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğaza Karşı', 'bogaza-karsi-ahmet-agdere-xgslh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzü mavidir, mavidir gökyüzü,

Mavi hayallerle tükettik ömrümüzü.

Sevgilinin gözlerinde üzüm salkımları,

Boğaza karşı şerbetledi günümüzü.', 'Gökyüzü mavidir, mavidir gökyüzü, Mavi hayallerle tükettik ömrümüzü. Sevgilinin gözlerinde üzüm salkımları, Boğaza karşı şerbetledi günümüzü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bogaza-karsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Ne Oldu?', 'bana-ne-oldu-mehmet-can-3qfu2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hızlı akan dere oldum

Çağlayan oldum..

Bir gün açtım, bir gün soldum,

Kardelen oldum.

Çok üzüldüm çok ağladım

Gözlerim doldu..

Bana ne oldu? 

Bana ne oldu?', 'Hızlı akan dere oldum Çağlayan oldum.. Bir gün açtım, bir gün soldum, Kardelen oldum. Çok üzüldüm çok ağladım Gözlerim doldu.. Bana ne oldu?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bana-ne-oldu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet', 'lanet-mehmet-can-w6pfx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin soğuk ve karanlık yüzünde

Parlayan uzakta sokak lambası..

Bomboş caddeler

Tek tük sarhoş naraları..

 aşk kokan evlerin kıskançlığında

gözlerim bir yazıya takıldı kocaman..

duvara kireçlerle yazılmış

ilk okul çocuğu yazısı gibi, düzensiz..

kocaman beyaz yazı

‘’lanet olsun’’

kim..

neden

hangi öfkeyle? 

Kimbilir?', 'Gecenin soğuk ve karanlık yüzünde Parlayan uzakta sokak lambası.. Bomboş caddeler Tek tük sarhoş naraları..  aşk kokan evlerin kıskançlığınd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/lanet-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime ne! ....', 'kime-ne-fatma-guven-mk7ch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susar dinlerim içimi

 Ne desem bilmem ki

Yalnızlığın,burukluğun gördüğüm resmi mi? 

Vuslat derken zamana inat

Ben bende kalırım kendin kendinde.

Hani aniden buzlu bir göle dalarsın da

İliklerine kadar hissedersin ya soğuğu

Çoğunlukla kendimi infaz ederim kendimde

Kime ne! .........

Acı bir tat bırakarak geçer sancılar.

Zaman denen sandala binerim,

Uzaklara gider,bırakırım kendimi.

Kor yalazları sarar bedenim,

Yanar küllerini savurur sonsuzluğa,

Ben beni bulurum.kalırsın sen kendinde.

Ben bende yanarım,

Kime ne! .......', 'Susar dinlerim içimi  Ne desem bilmem ki Yalnızlığın,burukluğun gördüğüm resmi mi?  Vuslat derken zamana inat Ben bende kalırım kendin kendi...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kime-ne-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşmadım', 'kosmadim-sevinc-kavuk-0cks1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İhtiyaç duyumuna

İtimatname koşmadım

Özensizlik itirafına gereç

Söyleyebildiklerim demektir

Bir gün hatırlarım demeye

Söylemek istediklerim de olacak

Aynı cins elektrikli

İki cisim iter birbirini

Arap atı olan iştahlı biner

Ekmek, marul, limon, portakal

Ne bulursan al işte! 

Tayın çizelgelerini düzenliyorum

Bir itişme, bir kakışma

Bir yanındakine çelme vurup

Öne geçme yarışıdır gidiyor

Oyuncuların itirazına rağmen mi? 

Trenlerimizi de odunla işletmiyoruz

Tek cümlelik reçeteler hem çok sunuldu

Utangaç ve arzulu 

Tedirgin ve işveli bir istekle

Yorganı hızla açarak bir hamlede

Savruksu kaymam altına nahoşça

Kaybolmuş şeyleri bulurum ama

Geçirdiğim zamanın saatini bulamam

Tavırları şiir gibi ahenktar olsa da

Güler yüzü abus, yaşamı savruk

Adı Leyla da olsa Mecnun da

Kasım kasım zambak rayihası bu hava

Meltemleri ürpertir bana ulaşırsa diye

Zaman benim, ben zaman kucağında…. ısınacağız

01.03.2006', 'İhtiyaç duyumuna İtimatname koşmadım Özensizlik itirafına gereç Söyleyebildiklerim demektir Bir gün hatırlarım demeye Söylemek istediklerim ...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kosmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilitlensin', 'kilitlensin-sevinc-kavuk-4fwmo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldızlara bakındım

Göz kırpıştılar

Yüreklere dokundum

Hep ağlaştılar

Kükreyen hikmetin

Namertliğin, hinliğin

Sel halinde gibi bir bereketine

Hizmetlerdi sebebi..

Bitir! Derdin ne

Kocaman mı miden? 

Ölçünü aşan hırların boğazında

Düğümlü kilitlensin

01.03.2006', 'Yıldızlara bakındım Göz kırpıştılar Yüreklere dokundum Hep ağlaştılar Kükreyen hikmetin Namertliğin, hinliğin Sel halinde gibi bir bereketin...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kilitlensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az Önce Bir Şiir Ağladı', 'az-once-bir-siir-agladi-birsen-ates-37gfr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sensiz 

mevsimsiz açan çiçeklerin

vahşi güzelliğindeyim

umarsız bir sevinin gözlerinde

kısacık bir andı yaşadığım

yalan düşlerim

hesapsız üzerime

yağan her kar tanesinde

biraz daha sana üşüdüm

hüzünler yıkıldı üstüme

kaldım altında 

inadına yine ölmedim

yorgunum artık

neresinden tutayım ki yaşamın

demir attım sensizlik kıyısına

bu sevda bitmese de içimde

söyleyemediklerimi alıp yanıma

yürüyorum sessizce şiirlerime

az önce bir şiir ağladı

çığlık çığlığa

y o k l u ğ u n d a

01.03.06', 'sensiz  mevsimsiz açan çiçeklerin vahşi güzelliğindeyim umarsız bir sevinin gözlerinde kısacık bir andı yaşadığım yalan düşlerim hesapsız üz...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/az-once-bir-siir-agladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaz Bulutları Savrulduğunda', 'gaz-bulutlari-savruldugunda-muammer-erturan-pyesl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gaz bulutları 

savrulduğunda güneşten 

bu sevda 

çoktan yazılmıştı zaten... 

Boşuna değil 

aynı gezegene düşüşümüz

aynı ülkeye 

aynı kente 

aynı meyhaneye hatta 

aynı zamanlarda... 

Kaynaşıvermemiz hemencecik 

ilk karşılaşmamızda daha 

tanışıyormuşcasına ezelden, 

boşuna değil... 

Gaz bulutları 

savrulduğunda güneşten 

bu sevda 

belirmişti ufukta... 

Denizden karaya 

maymundan insana... 

Derken çıkageldi 

ateşli günlerin müjdecisi 

bir şimşek

ve tekerlek bulundu

aramızdaki yolu kısaltmak için

ve kaydetsin diye tarih maceramızı

yazının icadına geldi sıra... 

Gaz bulutları 

savrulduğunda güneşten 

bu sevda 

çoktan yazılmıştı oysa... 

(29 Ağustos ''95)', 'Gaz bulutları  savrulduğunda güneşten  bu sevda  çoktan yazılmıştı zaten...  Boşuna değil  aynı gezegene düşüşümüz aynı ülkeye  aynı kente  ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gaz-bulutlari-savruldugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elvedalar Dolusu', 'elvedalar-dolusu-muammer-erturan-u92pm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün doğum günündü sahi...

Düşüverdi aklıma birden,

hiç hesapta yokken...

Şu işe bak! 

Doğum günün olacak

ve hesapta olmayacak hiç...

Doğum günün olacak

ve koşmayacağım sana

ışık hızıyla...

Doğum günün olacak

ve donatmayacağım galaksiyi

sengârenk...

Doğum günün olacak

ve yaprak kımıldamayacak

gönül ormanımda...

Bugün doğum günün ha! ..

Hiç farkı yok

öteki günlerden oysa...

Bugün doğum günün...

Kutluyorum! ..

Ve kucaklıyorum yokluğunu

elvedalar dolusu...

(11 Eylül ''98)

...', 'Bugün doğum günündü sahi... Düşüverdi aklıma birden, hiç hesapta yokken... Şu işe bak!  Doğum günün olacak ve hesapta olmayacak hiç... Doğum...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/elvedalar-dolusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilgın', 'ilgin-i-shak-ozlu-xkgg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeşil Konyamın kaplıca şehri,

Kudretten ılınmış şifa nehri.

Tarihlerde bilinen ILGIN adı,

Söylenir yüzyıllardan beri.

ILGIN ağacından adını almış,

Akşehir-Kadınhanı arası kalmış.

Onbeş derdin dermanı suları,

ILGIN ismini dünyaya yaymış.

Batıdan gelen Çavuşçu gölünü gör,

Molada Hitit Yalburt Su anıtını sor.

Beden huzuruna ruh huzuru ararsan,

Handevi-Gandevi türbesinde dur.

Kaplıca suyunu içenler şifa bulurlar,

Doğuya  şeker fabrikası uğurlar.

Güzel Konyama yüzünü dönenler,

Mevlanamızın gel sesini duyarlar.', 'Yeşil Konyamın kaplıca şehri, Kudretten ılınmış şifa nehri. Tarihlerde bilinen ILGIN adı, Söylenir yüzyıllardan beri. ILGIN ağacından adını ...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanlarını Bile', 'yalanlarini-bile-muammer-erturan-ev3bm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Al sana eylül! .. 

Al sana İstanbul! .. 

Ara da bul şimdi 

o rengi

o tadı 

o kokuyu... 

Üç yıl geçti üstünden 

dile kolay 

ve bir alay ölüm... 

Ne eylül o eylül 

ne İstanbul o İstanbul…

Ara da bul şimdi 

o şevki

o coşkuyu

o ruhu... 

Günler gün değil 

aylar ay

mevsimler mevsim... 

Yalanım yok

özlemişim fena hâlde

yalanlarını bile... 

(''98)', 'Al sana eylül! ..  Al sana İstanbul! ..  Ara da bul şimdi  o rengi o tadı  o kokuyu...  Üç yıl geçti üstünden  dile kolay  ve bir alay ölüm....', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalanlarini-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Törpüsü', 'omur-torpusu-muammer-erturan-f4fil', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aynı dünyadayken

ayrı ayrı yerlerdeyiz...

Aynı yerdeyken

ayrı ayrı dünyalarda...

Hem aynı yerde,

hem aynı dünyada

olamadık bir türlü...

Aşk değil mübarek,

ömür törpüsü...

(''95)', 'Aynı dünyadayken ayrı ayrı yerlerdeyiz... Aynı yerdeyken ayrı ayrı dünyalarda... Hem aynı yerde, hem aynı dünyada olamadık bir türlü... Aşk ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/omur-torpusu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dublaj Türkçesinde', 'dublaj-turkcesinde-muammer-erturan-cux4q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Harf harf onüç... 

Hece hece altı... 

Altı üstü üç kelime… 

Yıkıp alacasını başıma 

o güz akşamının 

gittin gideli

çözemedim gitti... 

Kendine iyi bak! 

Demiştin ya giderayak hani... 

Elveda 

anlamına mı geliyordu

dublaj Türkçesinde bu? .. 

.

(17 Haziran ''97)', 'Harf harf onüç...  Hece hece altı...  Altı üstü üç kelime…  Yıkıp alacasını başıma  o güz akşamının  gittin gideli çözemedim gitti...  Kendi...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dublaj-turkcesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uşağum (Yerel 7) Sabır', 'usagum-yerel-7-sabir-mikdat-bal-mteoe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acıya, zorluğa, her haksuzluğa

Sabredersen, bil ki zordur uşağum

Zulüm işkenceye insafsuzluğa

Sabredersen bil ki hordur uşağum

Sabır güzel bir şey soni selamet

Ancak sabır olmaz varsa melanet

Melanete susmak şerre alamet

Şerre sabır etmek şerdur uşağum

Sabrı telkin eder bazı alimler

Halkı inleterek ezer zalimler

Gözlerine çarpsun bunca ilimler

Dalkavuk alimler kördur uşağum

Hayırda sabretmek mü’minun işi

Haramlardan kaçar inanan kişi

Zulme razı olan şeytanun eşi

Onun da menzili nârdur uşağum

Sözde atasözü, bir bak ne dermiş

Muradına ermiş, sabreden derviş

Böyle bir misali acep kim vermiş

Onlarun kafasi dardur uşağum

Ya dervişi bilmez ya sabrı bilmez

Zulme sabredenler ebedi gülmez

Sabrı telkin eder camiye gelmez

Onun bir hesabi vardur uşağum

Her türlü çirkefi teptikten sonra

Elinden geleni yaptukten sonra

Bir olan Allaha taptukten sonra

Sabret bu da sana kârdur uşağum

Mikdatî der bizi pasif ettiler

Çünkü dalkavuklar böyle öttüler

Kanaldan kanala kalkup gittiler

Onlarun eksuği ardur uşağum', 'Acıya, zorluğa, her haksuzluğa Sabredersen, bil ki zordur uşağum Zulüm işkenceye insafsuzluğa Sabredersen bil ki hordur uşağum Sabır güzel b...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/usagum-yerel-7-sabir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopuşlar II', 'kopuslar-ii-erol-dal-5gl1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haykırışlarımı sakladım 

Gecenin karanlığına.

Uzaklarda bir yere fırlattım

Bana lazım olan ne varsa.

Çıkmaz sokakların dibinde.

Biliyorum,

Aklımda kalan ne varsa...

.......

Geceyi ve kışı seviyorum

Geçmek bilmeyen günler benim.

Karanlığın çaldığı ıslık,

Ve,

Benim eklediğim terennüm...

...

Geceyi seviyorum. Çünkü aşklar gece ihanete uğrar genelde.

Geceyi seviyorum. Çünkü sevgiler gece doğar gerçekte.

Gece masum

Gece bizden biri; 

Öyleyse...

                          92/Mekan', 'Haykırışlarımı sakladım  Gecenin karanlığına. Uzaklarda bir yere fırlattım Bana lazım olan ne varsa. Çıkmaz sokakların dibinde. Biliyorum, A...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kopuslar-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerime Basmayın', 'ellerime-basmayin-oguzkan-bolukbasi-jomb7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Masum kaldın hep, en acımasız cinayetleri işlediğinde bile

Sana kapımı açtım

Sorgusuz sualsiz yatırdım baş köşeme

Dikkatli ol

Zamanımı aldın, iyi kullan 

Nakit olarak hem de taksitsiz kartsız

Korkularını bana yendirdin

Hayallerime korkuların bulaştı o yüzden

Düşlerimi sana verdim

Rahat uyumalısın

Işığını söndürüp çıktım odandan

Kimse kalmadı bakacak arkamdan

Sokaklar adımlarımı tutuyor

Aşk bana yüklem olmuyor

Öznesi yoklara karıştı

Kimse hakkını yemesin

Bu yürek çok çalıştı

Başkalarının ne dediği umurumda olmadan şiirler yazdım 

Dikkatli ol kelimelerimi aldın

Onları iyi anla

Bana masallar anlatmaya gelin

Gölgesiz ve cadısız masallar

Kötüsüz masallar

Sokağa çıkmaya korkanların olmadığı masallar

Yorulmaktan yoruldum

Senin aklınla yürünmüyor

Aklımı aldın, dikkatli ol

Bir boşlukta asılı kaldın, düşme

Açılması yasak olan kapıları açtım

Saklanıyorum

Ellerime basmayın…', 'Masum kaldın hep, en acımasız cinayetleri işlediğinde bile Sana kapımı açtım Sorgusuz sualsiz yatırdım baş köşeme Dikkatli ol Zamanımı aldın...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ellerime-basmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yalnız olamazsın', 'sen-yalniz-olamazsin-nazan-i-zmirli-1cdwg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''olmazzzz  ben  yalnızlığımı   seviyorum

 demek  olmaz  sevgilim  olmaz.''

 ispat  et  bana  yalnız  olduğunu

 ıssız  bir  adada  denizin  ortasında

 nasıl  yalnız  kaldığını

 parçalanmış  teknenden  arda  kalan

 çıplak   bedenin  ve  sen

 yorgun  kollarınla kumsalı kucaklayan

 takati  kalmamış   dizlerinin  yüzmekten

 bağı çözülmüşcesine tuzlu suların içinde

 yeni  ay  dalga  geçer  gibi 

 fener  olmuş  karanlık  gecene

 yakamozlar yorgan sıcaklığında  üzerinde

 uykuya geçerken  ıssız, sessiz,  yalnız

 dinlersin........ 

 bethowen dan,çaykoski den,mozart tan

 en  güzel  senfonileri

 kumsalla  deniz  sevişirken 

 sen yalnız olamazsın  segilim yalnız.........

 kuzeyden  güneye  göç  eden

 yorgun  martıların  türküsü

 çekilen  ayın ardından

 boz  kanatları, beyaz  mintanları

 pembe  bacakları  umut  yolculuğunda

 kırmızı  benekli  gagasında

 sunar  günün  ilk  avını  sana

 sabah  güneşi  ipeksi bir dokunuşla

 okşarken  tenini....

 hissedersin   parmak  uçlarında

 suların   sessizliğini

 foklar  gelir  ıssızlığında güneşlenmeye

 yunuslar  danseder  sabahlara kavuşmanın sevincine

 izlerken   onları  tebessümlerinle  boğarsın

 güneş  tam sıcaklığı  ile  sardığında  seni

 palmiyelerin  gövdesinde   rahatlarsın  

 kabaran  gel git dalgalarda 

 seviştirirsin bedenini

 ve  güneş  ufuk  çizgisinde

 bir kadeh  kırmızı şarap olur  elinde

 içersin  içersin  sarhoş  olamazsın

 korkarsın.! ! ! 

 karanlık  gecenin 

 yıldız  alacasında 

 seni; 

 yalnız,ıssız, kimsesiz  bırakamazsın

 ben sendeki gizemli yalnızlığı sevdim

 sen  yalnız olamazsın

 güzel şeyleri yaşayan insansın.........

19.06.2005- antalya', '''olmazzzz  ben  yalnızlığımı   seviyorum  demek  olmaz  sevgilim  olmaz.''  ispat  et  bana  yalnız  olduğunu  ıssız  bir  adada  denizin  or...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sen-yalniz-olamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharla', 'baharla-nazan-i-zmirli-og95x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zirveler   gülümsüyor

torosların   karlı   yüzlerinde

palmiyeler  meltemle  titrer  yüreğimde

akdeniz  ışıl  ışıl  göz  kamaştırıyor

sayısız  kuşlar  şakıyor  gönül  penceremde

baharla   gel..................sen de.....................

01.03.2006-antalya', 'zirveler   gülümsüyor torosların   karlı   yüzlerinde palmiyeler  meltemle  titrer  yüreğimde akdeniz  ışıl  ışıl  göz  kamaştırıyor sayısız...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/baharla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın gammı var', 'askin-gammi-var-nazan-i-zmirli-bqw3c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'günü  gören  ayın  suskunluğu

yorgun  dalgaların  durgunluğu

gözlerimde  ufku arayışın dalgınlığı

yüreğimde  aşkın  gammı  var

mehtapta  sunduğun  aşk  şarabının

sarhoşluğu  bu

kavuşulamayan  sabahlara

oysa  doğan  gün  GÜLÜMSÜYOR

ben  yine  kavuşacağım  sana

at  hüznü  kederi  bir   yana

gecen  başka  günün  başka

bu aşkı  yaşa  doya  doya........

01.03.2006- antalya', 'günü  gören  ayın  suskunluğu yorgun  dalgaların  durgunluğu gözlerimde  ufku arayışın dalgınlığı yüreğimde  aşkın  gammı  var mehtapta  sun...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-gammi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil yeşil baktığında....', 'yesil-yesil-baktiginda-nazan-i-zmirli-e4sw9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sana  giden  yollar........................................

dudaklarındaki  gül  pembesi  tebessümün

al  al  elmacık   kemiklerini   sardığında

ela  ela  gözlerin,  yeşil  yeşil  baktığında

başladı...........................................................

sabah   güneşinin   meltemliği  ile 

sardın  uçuşan  saçlarımın  üzerine

susuz  kalmış  hanım   ellerime

verdin  gönül  şarabını  ince ince

damla  damla  birikti

yüreğime  ulaşan  sızıntılar

damarlarımda  dolaştı  kıpır kıpır

derelere, vadilere, deryalara  ulaşmak  istedi

yeşermeye   başladı   hanımellerim 

bıraktım  onları  kendi  hallerine

gönül  şarabıyla  serpilsin

özgürce  sevsin  sevilsin  diye..........

01.03.2006-antalya', 'sana  giden  yollar........................................ dudaklarındaki  gül  pembesi  tebessümün al  al  elmacık   kemiklerini   sardığı...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yesil-yesil-baktiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünde Gelmezsen', 'bugunde-gelmezsen-sahin-erturk-lt4kd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılık acısı,yetti canıma

Sensizlik hancer,girdi tam şuramda

Durmuyor kanamam,doktor arama

Bugünde gelmezsen,çıkmam sabaha

(01.03.2006)', 'Ayrılık acısı,yetti canıma Sensizlik hancer,girdi tam şuramda Durmuyor kanamam,doktor arama Bugünde gelmezsen,çıkmam sabaha (01.03.2006)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bugunde-gelmezsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Öyküsü 12 (Elveda)', 'ask-oykusu-12-elveda-serdar-ahmet-guzel-j2kyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çıktığım yollarda, hasret rüzgârların esiyor şimdi…

Oysa ne güzel bir hikâyeydi bizimkisi

Karşıdan çıktığımda bindiğim kirli İETT otobüsünün

Viran koltuğunda, sana kavuşma ümidiyle 

Dalıyordum yalnız senin olduğun rüyalarıma

Dünya önemsizdi bu anlarda,

Geçmiş, gelecek ne varsa aklımda 

Hepsi toplanıyor koca bir yumak oluyordu etrafında

Yaşam adına ne varsa, sevda adına ne duydumsa 

Sende toplanmış, ortaya Muhsin Ertuğrul ile Afife Jalenin

Ortaya koyduğu eski, muhteşem bir eser çıkmıştı

Sahne gerisindeki rejisör ve koltuklarına oturup bizi seyreden

Seyirciler çılgına dönmüş, avuçlarını patlatarak alkışlıyorlardı.

Dedim ya bir tek sen bir tek ben vardım rüyalarımda…

Sırt üstü düştüğüm ranzamdan, uyandığımda 

Sen benim sana özlemle yanan kahrolası, Allahın cezası

Yüreğime sapladığın ateşten sıcak, buzdan soğuk ihanet 

Kamasıyla, beni öldürmüş, yaşarken mezara sokmuştun.

Soruyorum şimdi sana ne istedin serçe misali dev yüreğimden…

İsyanı basıyorum artık sana da, Leyla’ya da, arkadaşınız olacak

Aslı hanımla, Şirin hanıma 

Kurşun sıkıyorum sözlerinize, yitik rüyalarınıza 

Bu son sözüm hepinize artık elveda elveda…

28.02.2006 saat:21.50', 'Çıktığım yollarda, hasret rüzgârların esiyor şimdi… Oysa ne güzel bir hikâyeydi bizimkisi Karşıdan çıktığımda bindiğim kirli İETT otobüsünün...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-oykusu-12-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanesin Türkiye''m', 'bir-tanesin-turkiye-m-caglar-asik-ephn9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toprağınla, taşınla,

Mis havanla, suyunla,

Gökte yıldız, ayınla,

Bir tanesin, TÜRKİYE’M.

&

Bayrağımız, göğünde,

Dalgalansın, özgürce,

Çok severiz, ölürce,

Bir tanesin, TÜRKİYE’M.

&

Huzurluyuz, üstünde,

Güvendeyiz, birlikte,

Hiç bir zaman, üzülme,

Bir tanesin, TÜRKİYE’M.

&

Dertlerini, taşırız,

Sıkıntını, aşarız,

Bizler sana, aşığız,

Bir tanesin, TÜRKİYE’M.

&

Yuvamızı, kurarız,

Rızkımızı, ararız,

Özgürce can, veririz,

Bir tanesin, TÜRKİYE’M.

&

Şehit olan, ölmedi,

Mekan nedir, bilmedi,

Hak’sızları, sevmedi,

Bir tanesin, TÜRKİYE’M.

&

Nice canlar, fedayız,

Toprağında, yaşarız,

Saldırana, susmayız,

Bir tanesin, TÜRKİYE’M.

&

Tüfek çiçek, değildir,

Eziyetler, gizlidir,

Öksüz yetim, bellidir,

Bir tanesin, TÜRKİYE’M.

&

Sabır sınır, koruna,

Ortalıklar, durula,

Ağlayanlar, pir güle,

Bir tanesin, TÜRKİYE’M.

&

İstanbul - 28.02.2006 - Hece: 7

Çağlar Aşık - Bir tanesin, TÜRKİYE’M.', 'Toprağınla, taşınla, Mis havanla, suyunla, Gökte yıldız, ayınla, Bir tanesin, TÜRKİYE’M. & Bayrağımız, göğünde, Dalgalansın, özgürce, Çok se...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-tanesin-turkiye-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman değilim', 'pisman-degilim-tulay-i-cen-jynxd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duy artık  gecenin  içinde çığlığımı..! 

Bu  hasret bu isyan bitsin,

Biliyorum her şeyin bir sonu vardır.

Sana  kavuştuğum gün,

Benim için.

Sonun başlangıcı olacak.

Sonum olsanda yüreğimi kanatsanda.

Seni  sevmekten  pişman değilim.

Gelmeyeceğini bilerek  yolunu gözlemekten,

Pişman değilim....

Zindanlarının  karanlığına  atsanda  beni..

Sevmekten  seni asla  pişman değilim.

Sürgünde olsam  belirsizliğe,

Seni düşünerek uykusuzda gecse

Gecelerim.

Ölümde  olsa sonunda.

Can  seni sevmekten asla, asla

Pişman  değilim', 'Duy artık  gecenin  içinde çığlığımı..!  Bu  hasret bu isyan bitsin, Biliyorum her şeyin bir sonu vardır. Sana  kavuştuğum gün, Benim için. ...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/pisman-degilim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gözlerinde Büyüttüm Ben Aşkı', 'o-gozlerinde-buyuttum-ben-aski-mustafa-dogan-4-p8ohi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O  GÖZLERİNDE BÜYÜTTÜM BEN  AŞKI

Sabah güneşinin ışıltısı içime neşe saçıyor bugün,

O gözlerin ile yaşıyordum inan ben bunu her gün,

Sana rastladım,mecnun oldum ben o gün bu gün,

Bir tuba büyür gönlümde, sana o aşkımla her gün. 

-

Çocuk yüreğim sevgiyi ilk güzel gözlerinde tanıdı,

Hani,seni görünce hemen utanır, yüzüm kızarırdı,

O bakışların benim kalbime sevgiyi aşkı fısıldardı,

Gözlerinden okudum kalbindekini,o aşktı sevgiydi.

-

O gözlerin de sana bağlamıştım bu aşikar belliydi,

Güzel gözlerin dünyamda değerli olan tek şeyimdi,

Gönlümde o gözlerinin hayalini, kimseler silemedi,

Belki o gözlerin sahibi, onu sevdiğimi hiç bilemedi.', 'O  GÖZLERİNDE BÜYÜTTÜM BEN  AŞKI Sabah güneşinin ışıltısı içime neşe saçıyor bugün, O gözlerin ile yaşıyordum inan ben bunu her gün, Sana ra...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan 4']::text[], 8.5, '{"poet":"Mustafa Doğan 4","poet_slug":"mustafa-dogan-4","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/o-gozlerinde-buyuttum-ben-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enli Aşk', 'enli-ask-gulseren-onay-sm3ai', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Binlerce 

Tanımı var aşkın

En hüzünlü olanını 

Seçti Kadın

Binlerin içinden 

Seni

En sevmeyi bilmeyeni …', 'Binlerce  Tanımı var aşkın En hüzünlü olanını  Seçti Kadın Binlerin içinden  Seni En sevmeyi bilmeyeni …...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/enli-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G ö z l e r', 'g-o-z-l-e-r-nuray-acar-lolr7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerindir seni u y a n ı k   t u t a n

hatta hayatı hafızana k a z ı y a n

oysa gün gelir b u l a n ı k l a ş ı r

saklanır çoğu z a m a n 

